INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (1, 6, 'Some strains of Bacillus thuringiensis produce proteins that kill certain insects such as lepidopterans (tobacco budworm, armyworm),

coleopterans (beetles) and dipterans (flies, mosquitoes). B. thuringiensis forms protein crystals during a particular phase of their growth. Transgenic animals that produce useful biological products can be created by the introduction of the portion of DNA (or genes) which codes for a particular product such as human protein (a-1-antitrypsin) used to treat emphysema. In 1997, the first transgenic cow, Rosie, produced human protein-enriched milk (2.4 grams per litre). The milk contained the human alpha-lactalbumin and was nutritionally a more balanced product for human babies than natural cow-milk. A nematode Meloidegyne incognitia infects the roots of tobacco plants and causes a great reduction in yield. A novel strategy was adopted to prevent this infestation which was based on the process of RNA interference (RNAi). This method involves silencing of a specific mRNA due to a complementary dsRNA molecule that binds to and prevents translation of the mRNA (silencing). Biopiracy is the term used to refer to the use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned without compensatory payment. ELISA is based on the principle of antigen-antibody interaction. Infection by pathogen can be detected by the presence of antigens (proteins, glycoproteins, etc.) or by detecting the antibodies synthesised against the pathogen.

Biopiracy is the term used to refer:

1. The use of bio-resources by multinational companies and other organisations with proper authorisation from the countries and people concerned with compensatory payment.

2. The use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned with compensatory payment.

3. The use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned without compensatory payment.', NULL, NULL, NULL, NULL);
