INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (11, 6, 'The DNA fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The separated DNA fragments can be visualised only after staining the DNA with a compound known as ethidium bromide followed by exposure to UV radiation. The repeated amplification of DNA is achieved by the use of a thermostable DNA polymerase (isolated from a bacterium, Thermus aquaticus). After completion of the biosynthetic stage, the product has to be subjected through a series of processes before it is ready for marketing as a finished product. The downstream processing and quality control testing vary from product to product. The convention for naming restriction enzymes is the first letter of the name comes from the genus and the second two letters come from the species of the prokaryotic cell from which they were isolated.

The downstream processing does not include -

1. Separation and purification

2. Product formulation with preservatives

3. No clinical trials in case of drugs', NULL, NULL, NULL, NULL);
