INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (16, 6, 'Insulin consists of two short polypeptide chains: chain A and chain B, that are linked together by disulphide bridges. The first clinical gene therapy was given in 1990 to a 4-year old girl with adenosine deaminase (ADA) deficiency. This enzyme is crucial for the immune system to function. Recombinant DNA technology, Polymerase Chain Reaction (PCR) and Enzyme Linked Immunosorbent Assay (ELISA) are some of the techniques that serve the purpose of early diagnosis of diseases. Transgenic animals that produce useful biological products can be created by the introduction of the portion of DNA (or genes) which codes for a particular product such as human protein ( $ \alpha $-1-antitrypsin) used to treat emphysema. Biopiracy is the term used to refer to the use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned without compensatory payment.

