INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (18, 6, 'Insulin consists of two short polypeptide chains: chain A and chain B, that are linked together by disulphide bridges. The first clinical gene therapy was given in 1990 to a 4-year old girl with adenosine deaminase (ADA) deficiency. This enzyme is crucial for the immune system to function. Recombinant DNA technology, Polymerase Chain Reaction (PCR) and Enzyme Linked Immunosorbent Assay (ELISA) are some of the techniques that serve the purpose of early diagnosis of diseases. Transgenic animals that produce useful biological products can be created by the introduction of the portion of DNA (or genes) which codes for a particular product such as human protein ( $ \alpha $-1-antitrypsin) used to treat emphysema. Biopiracy is the term used to refer to the use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned without compensatory payment.

In 1997, an American company got patent rights on Basmati rice through the US Patent and Trademark Office. This allowed the company to sell a ''new'' variety of bvasnmati, in the US and abroad. This ''new'' variety of Basmati had actually been derived from Indian farmer''s varieties.. Indian Basmati was crossed with semi-dwarf varieties and claimed as an invention or a novelty. This is a case of:

1. Competitive market

2. Bioresources

3. Biopiracy', NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (19, 5, 'Biomolecules are the organic compounds present as an essential constituents of living organisms in different cells. The molecules are generally termed as macromolecules, which are carbohydrates, enzymes, nucleic acids, amino acids and proteins etc. Carbohydrates are classified as sugars and non-sugars include sucrose, glucose, fructose, starch and cellulose. Enzymes are coordinated with various chemical reactions in nucleic acid. Nucleic acids are found in living organisms made up of proteins and natural polymers. Two types that are generally found in biological systems are DNA and RNA nucleic acid. Amino acids are bifunctional groups of carboxyl and amino groups. Proteins are a class of biologically important compounds. They are crucial to virtually all processes in living systems. Some of them are hormones, which serve as chemical messengers that coordinate certain biochemical activities.

Glucose when treated with Bromine water forms

1. Saccharic acid

2. Gluconic acid

3. Glyceric acid', NULL, NULL, NULL, NULL);
