INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (32, 5, 'Electrochemistry is the study involving two types of processes. One type involves the production of electricity from the energy released during a spontaneous chemical reaction. Galvanic cells like Daniel cells are used to produce electricity from the redox reaction. Nernst equation of a galvanic cell gives the relation between the standard cell potential and the concentration of the species involved in the redox reaction. The second type of study involves the cells in which electrical energy is used to bring about the chemical reactions in a non-spontaneous process. The conductance of electrolytic solution depends on many factors including the nature of the electrolyte and the dimensions of the electrolytic cell.', NULL, NULL, NULL, NULL);
