INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (60, 18, 'There are six members in a family, named A, B, C, D, E, and F. B is the son of C but C is not the mother of B. A and C are a married couple. E is the brother of C, D is the daughter of A. F is the brother of B.

