INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (71, 13, 'High technology, or simply high-tech, is the latest generation of manufacturing activities. It is best understood as the application of intensive research and development (R and D) efforts leading to the manufacture of products of an advanced scientific and engineering character. Professional (white collar) workers make up a large share of the total workforce. These highly skilled specialists greatly outnumber the actual production (blue collar) workers. Robotics on the assembly line, computer-aided design (CAD) and manufacturing, electronic controls of smelting and refining processes, and the constant development of new chemical and pharmaceutical products are notable examples of a high-tech industry.

Neatly spaced, low, modern, dispersed, office-plant-lab buildings rather than massive assembly structures, factories and storage areas mark the high-tech industrial landscape. Planned business parks for high-tech start-ups have become part of regional and local development schemes.

High-tech industries which are regionally concentrated, self-sustained and highly specialised are called', NULL, NULL, NULL, NULL);
