3. Harihara', NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (102, 11, 'Vijayanagara Empire

