INSERT OR REPLACE INTO passages ("id", "subject_id", "body", "body_hi", "image_url", "image_alt", "deleted_at") VALUES (124, 9, '### Manorama Retail is a rapidly expanding retail company with stores across multiple cities. As the company grows, managing the workforce becomes increasingly complex

The HR department of XYZ faces several challenges, including hiring the right talent, managing employee turnover, and creating a training and development program to upskill employees.

The company’s recruitment process involves several stages, including screening resumes, conducting interviews, and background checks. However, finding candidates who align with the company culture and have the necessary skills has been difficult.

Additionally, the company struggles with high employee turnover, especially in its sales and customer service departments. To address these challenges, XYZ Retail decides to focus on improving its staffing process. The company aims to enhance its recruitment strategies by using more advanced tools, such as data analytics, to match candidates with job roles more effectively. They also implement an employee retention program that includes career development opportunities and a more robust employee recognition system.', NULL, NULL, NULL, NULL);
