INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (66, 19, NULL, NULL, 'Choose the correct statement about Sinking Fund?', NULL, '[{"text":"It is a long term account which can be closed any time.","image_url":null,"alt":null},{"text":"It does not have any specific purpose.","image_url":null,"alt":null},{"text":"In this fund, a fixed amount at regular intervals is deposited for a fixed terms","image_url":null,"alt":null},{"text":"It can be used in any emergency.","image_url":null,"alt":null}]', NULL, 2, 'A Sinking Fund is a fund established by setting aside money periodically

