INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (97, 6, NULL, 6, '4. A piece of protein is introduced in a host bacterium', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) A piece of DNA is introduced in a host bacterium

Explanation:

Transformation is a genetic engineering step where:

- Foreign DNA is introduced into a host bacterium

- Enables recombinant DNA technology

CUET Tip: Learn steps in genetic engineering.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.966Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (98, 6, NULL, 7, '4. Fucose', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'Correct Answer: (2) Agarose

Explanation:

Agarose gel electrophoresis is used to separate DNA fragments.

- Agarose is a seaweed-derived polymer

- DNA moves based on size and negative charge (due to phosphate groups), they are loaded into an agarose gel and subjected to an electric field, causing them to migrate toward the positive electrode (anode).

-The gel acts like a sieve, so smaller fragments move faster and travel farther than larger fragments.

-After the process, the separated DNA bands are made visible by staining the gel with compounds like ethidium bromide and viewing them under UV light.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.966Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (99, 6, NULL, 8, '4. Virus', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) Fungal cells

Explanation:

DNA isolation requires specific enzymes based on the cell type:

- Chitinase is used to break down fungal cell walls (made of chitin)

- Other enzymes include:

- Lysozyme for bacterial cells

- Cellulase for plant cells

Why others are wrong:

- (1) Bacterial cells: Use lysozyme, not chitinase

- (2) Plant cells: Use cellulase

- (4) Virus: Do not require chitinase', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.967Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (100, 6, NULL, 9, '4. Origin of replication (ori)', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) Recognition sequence

Explanation:

Restriction enzymes like Hind II cut DNA at specific recognition sequences.

- Hind II recognizes a six-base pair sequence

- Ensures precise DNA fragment generation for cloning

CUET Tip: Memorise cutting site concepts for restriction enzymes.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.967Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (101, 6, NULL, 10, '4. Palindromic nucleotide sequences', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4 Answer: D","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) Palindromic nucleotide sequence

Explanation:

Restriction endonucleases recognize palindromic sequences in DNA:

- These are sequences that read the same forward and backward on complementary strands

- Example: GAATTC (EcoRI recognition site)

CUET Tip: Identify sequence types relevant to DNA tools.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.968Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (102, 6, NULL, NULL, 'What does ''r'' denotes in the given equation?

dN/dT = rN', NULL, '[{"text":"Population density","image_url":null,"alt":null},{"text":"Time","image_url":null,"alt":null},{"text":"Base of natural logarithms","image_url":null,"alt":null},{"text":"Intrinsic rate of natural increase","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) Intrinsic rate of natural increase

Explanation:

The equation:

$ (dN)/(dT) = rN $

is the exponential growth equation in population ecology.

$ (dN)/(dT) = \text{change in population size over time} $.

[N] = current population size

[r] = intrinsic rate of natural increase (birth rate - death rate), under ideal conditions.

Assumes unlimited resources, giving exponential growth.

CUET Tip: Always link ''r'' to ideal growth conditions.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.968Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
