INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (104, 6, NULL, NULL, 'Exine of pollen grains has prominent apertures where sporopollenin is absent are known as:', NULL, '[{"text":"Intine","image_url":null,"alt":null},{"text":"Germ pores","image_url":null,"alt":null},{"text":"Vegetative cell","image_url":null,"alt":null},{"text":"Generative cell","image_url":null,"alt":null}]', NULL, 1, 'Correct Answer: (2) Germ pores

