INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (105, 6, NULL, NULL, 'In amensalism:', NULL, '[{"text":"One species is benefitted and the other is neither benefitted nor harmed","image_url":null,"alt":null},{"text":"One species is benefited whereas the other is unaffected","image_url":null,"alt":null},{"text":"One species is harmed whereas the other is unaffected","image_url":null,"alt":null},{"text":"One species is harmed and other is benefitted","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) One species is harmed whereas the other is unaffected

Explanation:

This is amensalism, a type of interspecific interaction.

- Example: Penicillium inhibits bacterial growth

- One species suffers, the other remains unaffected

