INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (106, 6, NULL, NULL, 'Transmission of HIV infection occurs by:

(A) By transfusion of contaminated blood

(B) By sharing infected needles

(C) Sexual contact with HIV infected person

(D) From an infected mother to her child through the placenta', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'Solution:

Correct Answer: (3)(A), (B), (C), and (D)

Explanation:

HIV transmission occurs via:

- (A) Sexual contact

- (B) Contaminated blood

- (C) Infected needles

- (D) Vertical transmission (mother to child via placenta)

