INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (107, 6, NULL, NULL, 'In Sickle-cell anemia, the substitution of amino acid in the globin protein results due to the single base substitution at the sixth codon of the beta globin gene from:', NULL, '[{"text":"AUG to GAG","image_url":null,"alt":null},{"text":"AUG to GUG","image_url":null,"alt":null},{"text":"GAG to AUG","image_url":null,"alt":null},{"text":"GAG to GUG","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) GAG to GUG

Explanation:

Sickle cell anaemia is caused by a point mutation in the $ \beta $-globin gene.

- The codon GAG (glutamic acid) changes to GUG (valine)

- This substitution alters the haemoglobin structure, causing RBCs to become sickle-shaped

- Leads to reduced oxygen-carrying capacity and blockage in capillaries', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.969Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (108, 6, NULL, NULL, 'In case of malaria, the rupture of RBCs is associated with release of a toxic substance called, _, which is responsible for the chill and high fever recurring after every three to four days.', NULL, '[{"text":"Haeme","image_url":null,"alt":null},{"text":"Haemozoin","image_url":null,"alt":null},{"text":"Haematozoin","image_url":null,"alt":null},{"text":"Haemoglobin","image_url":null,"alt":null}]', NULL, 1, 'Correct Answer: (2) Haemozoin

Explanation:

In malaria, the parasite Plasmodium ruptures RBCs, releasing haemozoin, a toxic pigment.

- Haemozoin causes cyclical fever and chills

- It''s a byproduct of haemoglobin digestion by the parasite

CUET Tip: Link parasite life cycle to symptoms.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.969Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
