INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (116, 6, NULL, NULL, 'Contact inhibition is a property of:', NULL, '[{"text":"Normal cells","image_url":null,"alt":null},{"text":"Cancer cells","image_url":null,"alt":null},{"text":"B-cells","image_url":null,"alt":null},{"text":"T-cells","image_url":null,"alt":null}]', NULL, 0, 'Correct Answer: (1) Normal cells

