INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (117, 6, NULL, NULL, 'IUCN stands for:', NULL, '[{"text":"International Union for Conservation of Natural Resources","image_url":null,"alt":null},{"text":"International Union for Conservation of Nature","image_url":null,"alt":null},{"text":"International Union for Conservation of Nature and Natural Resources","image_url":null,"alt":null},{"text":"International Union Commission of Nature and Natural Resources","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) International Union for Conservation of Nature and Natural Resources

Explanation:

IUCN is a global organization that maintains the Red List, which categorizes species based on their risk of extinction.

- Helps in biodiversity conservation and policy-making

- Categories include: Extinct, Endangered, Vulnerable, etc.

CUET Tip: Memorize full forms of key organizations.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.972Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (118, 6, NULL, NULL, 'Match List-I with List-II:

