INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (119, 6, NULL, NULL, 'The hormone releasing IUDs function by:', NULL, '[{"text":"Decreasing phagocytosis of sperms within the uterus","image_url":null,"alt":null},{"text":"Activating sperm motility and the fertilising capacity of sperms","image_url":null,"alt":null},{"text":"Making the uterus suitable for implantation and the cervix hostile to the sperms","image_url":null,"alt":null},{"text":"Making the uterus unsuitable for implantation and the cervix hostile to the sperms","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) Making the uterus unsuitable for implantation and the cervix hostile to the sperms

Explanation:

Hormone-releasing IUDs (e.g., LNG-20, Progestasert):

- Release progesterone or progestin

- Prevent implantation by altering uterine lining

- Make cervical mucus thick, hindering sperm entry', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.973Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (120, 6, NULL, NULL, 'The genetic disorder, Down''s Syndrome is caused due to:', NULL, '[{"text":"Deletion of chromosome no. 21","image_url":null,"alt":null},{"text":"Trisomy of chromosome no. 18","image_url":null,"alt":null},{"text":"Trisomy of chromosome no. 21","image_url":null,"alt":null},{"text":"Inversion of chromosome no. 21","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) Trisomy of chromosome no. 21

Explanation:

Down Syndrome is caused by trisomy 21, where an individual has three copies of chromosome 21.

- Leads to mental retardation, short stature, and distinct facial features

- Detected via karyotyping

CUET Tip: Recognize chromosomal disorders and their genetic basis.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.973Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
