INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (123, 6, NULL, NULL, 'Arrange the given structures in correct sequence of spermatogenesis?

(A) Spermatozoa

(B) Secondary spermatocytes

(C) Spermatogonia

(D) Spermatids', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(D), (C), (B), (A)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4)(C), (B), (D), (A)

Explanation:

The stages of spermatogenesis in the correct biological order are:

• Spermatogonia (Germ cells -> undergo mitosis to increase number)

• Primary Spermatocytes (not listed, but form from Spermatogonia)

• Secondary Spermatocytes (Formed after Meiosis I)

• Spermatids (Formed after Meiosis II)

• Spermatozoa (Spermatids differentiate into mature sperm)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.974Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (124, 6, NULL, NULL, 'Identify the correct sequence of events during menstrual cycle?

