INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (125, 6, NULL, NULL, 'The rate of biomass production is called productivity. It is expressed in terms of_ to compare the productivity of different ecosystems.', NULL, '[{"text":"(kcal m $ ^{-1} $) yr $ ^{-1} $","image_url":null,"alt":null},{"text":"(kcal m $ ^{-2} $) yr $ ^{-2} $","image_url":null,"alt":null},{"text":"(kcal m $ ^{-2} $) yr $ ^{-1} $","image_url":null,"alt":null},{"text":"(kcal m^{-1}) yr^{-2}","image_url":null,"alt":null}]', NULL, 2, 'Correct Answer: (3) (kcal m^{-2} yr^{-1})

Explanation:

Primary productivity is measured as the rate of biomass production:

- Expressed in kilocalories per square meter per year or grams per square meter per year

- Indicates energy flow in ecosystems

Why others are wrong:

Other options show wrong dimensions.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.974Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (126, 6, NULL, NULL, 'The "Rivet Popper Hypothesis" was used by:', NULL, '[{"text":"Alexander von Humboldt","image_url":null,"alt":null},{"text":"Paul Ehrlich","image_url":null,"alt":null},{"text":"Hardy-Weinberg","image_url":null,"alt":null},{"text":"Edward Wilson","image_url":null,"alt":null}]', NULL, 1, 'Correct Answer: (2) Paul Ehrlich

Explanation:

Paul Ehrlich, a Stanford ecologist, proposed the rivet popper hypothesis:

- Compares ecosystem to an airplane losing rivets (species)

- Loss of key species can lead to ecosystem collapse.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.975Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (127, 6, NULL, NULL, 'Nicotine stimulates the adrenal gland to release:

(A) Thyroid stimulating hormone (TSH)

(B) Adrenaline

(C) Estrogen

(D) Nor-adrenaline', NULL, '[{"text":"(B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'Correct Answer: (1) (B) and (D) only

Explanation:

Nicotine, a stimulant found in tobacco, affects the adrenal glands, triggering the release of adrenaline.

- This leads to increased blood pressure and heart rate

- It acts on the central nervous system, causing alertness and dependency

Hence, Correct statements:

- (B) Nicotine stimulates adrenal glands

- (D) Adrenaline increases blood pressure and heart rate

Why others are wrong:

- (A) Nicotine decreases heart rate: Incorrect - it increases it', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.975Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (128, 6, NULL, NULL, 'Select the intra uterine devices from the following:

(A) Multiload 375

(B) Saheli

(C) Cervical caps

(D) Progestasert', NULL, '[{"text":"(A) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'Correct Answer: (1) (A) and (D) only

Explanation:

Intrauterine Devices (IUDs) are classified into three types:

- (A) Non-medicated IUDs (e.g., Lippes Loop)

- (B) Copper-releasing IUDs (e.g., CuT, Cu7, Multiload 375)

- (C) Hormone-releasing IUDs (e.g., LNG-20, Progestasert)

Only (A) and (D) are correct in this context.

Why others are wrong:

- (B) and (C) are pill and barrier type examples

- The question asks for IUDs, and only (A) and (D) are the IUDs.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.975Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
