INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (130, 6, NULL, NULL, 'Baculoviruses are pathogens that attack', NULL, '[{"text":"Birds and other mammals","image_url":null,"alt":null},{"text":"Bacteria and other fungi","image_url":null,"alt":null},{"text":"Plants and other algae","image_url":null,"alt":null},{"text":"Insects and other arthropods","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) Insects and other arthropods

Explanation:

Baculoviruses are used as biopesticides targeting insects and arthropods.

- They are host-specific and do not harm humans, plants, or vertebrates

Why others are wrong:

Other options include organisms which are not targeted by it.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.976Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (131, 6, NULL, NULL, 'The second trophic level in an aquatic ecosystem is:', NULL, '[{"text":"Phytoplanktons","image_url":null,"alt":null},{"text":"Fishes","image_url":null,"alt":null},{"text":"Large fishes","image_url":null,"alt":null},{"text":"Zooplanktons","image_url":null,"alt":null}]', NULL, 3, 'Correct Answer: (4) Zooplanktons

Explanation:

Zooplanktons are primary consumers in aquatic ecosystems.

- They feed on phytoplankton (producers)

- Belong to the second trophic level

Why others are wrong:

- (1) Phytoplankton: Producers (first trophic level)

- (2) Fishes: Consumers (secondary consumers)

- (3) Large fishes: Higher trophic levels.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:37.976Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (132, 6, NULL, NULL, 'Match List-I with List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">List-I (Geological periods)</th>
      <th style="padding: 8px; border: 1px solid #444;">List-II (Plants evolved)</th>
