INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (283, 7, NULL, NULL, '_ operation is used to get the common tuples from two relations.', NULL, '[{"text":"Union","image_url":null,"alt":null},{"text":"Intersect","image_url":null,"alt":null},{"text":"Set Difference","image_url":null,"alt":null},{"text":"Cartesian product","image_url":null,"alt":null}]', NULL, 1, '. Intersect

- The INTERSECT operation in relational algebra returns only the tuples that are common to both relations.

- Union returns all tuples from both relations, Set Difference returns

tuples in one relation but not in the other, and Cartesian Product pairs all

tuples from the first relation with all tuples from the second.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.057Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
