INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (317, 7, NULL, NULL, 'What will be the format of the output of the NOW function?', NULL, '[{"text":"HH:MM:SS","image_url":null,"alt":null},{"text":"YYYY-MM-DD HH:MM:SS","image_url":null,"alt":null},{"text":"HH:MM:SS YYYY-MM-DD","image_url":null,"alt":null},{"text":"YYYY-DD-MM HH:MM:SS","image_url":null,"alt":null}]', NULL, 1, '. YYYY-MM-DD HH:MM:SS

In SQL, the $ \text{NOW} $ function returns the \textit{current date} and \textit{time} in the standard \textit{datetime format}.

YYYY-MM-DD HH:MM:SS\text{YYYY-MM-DD HH:MM:SS}YYYY-MM-DD HH:MM:SS

