2025-10-14 09:30:45', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.072Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
