- Lethargic means sluggish and apathetic; lacking energy.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.096Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (350, 1, NULL, NULL, 'Rearrange the following parts to form a meaningful sentence:

(A) each country by creating new words to describe indigenous features and

(B) shared across dialects, forming what is known as World English

(C) over the last 400 years, English has spread globally, evolving uniquely in

(D) absorbing words from local languages, yet the majority of its vocabulary remains', NULL, '[{"text":"(C), (A). B). (D)","image_url":null,"alt":null},{"text":"(C), (A), (D), (B)","image_url":null,"alt":null},{"text":"(B). (A). (C). (D)","image_url":null,"alt":null},{"text":"(C). (D). (B), (A)","image_url":null,"alt":null}]', NULL, 1, 'The coherent sentence formed is ;

Over the last 400 years, English has spread globally, evolving uniquely in each country by creating new words to describe indigenous features and absorbing words from local languages, yet the majority of its vocabulary remains shared across dialects, forming what bis known as World English.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.097Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (351, 1, NULL, NULL, 'Select the word closest in meaning to the word: Postulate', NULL, '[{"text":"Highlight","image_url":null,"alt":null},{"text":"Disprove","image_url":null,"alt":null},{"text":"Refute","image_url":null,"alt":null},{"text":"Hypothesize","image_url":null,"alt":null}]', NULL, 3, 'Postulate (suggest or assume the truth of something as a basis for reasoning) and Hypothesize means to propose an explanation or assumption.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.098Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
