INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (353, 1, NULL, NULL, 'Select the word or phrase that best completes the following sentence:-

Desert flowers can be invisible for years _ appear suddenly after heavy rain.', NULL, '[{"text":"alternatively or","image_url":null,"alt":null},{"text":"consequently and","image_url":null,"alt":null},{"text":"nevertheless, so","image_url":null,"alt":null},{"text":"actually, but","image_url":null,"alt":null}]', NULL, 3, 'The first blank requires an adverb that acts as a transition or intensifier, introducing a surprising fact about their invisibility: "actually" fits this.

1. The second blank requires a coordinating conjunction to connect two contrasting actions (being invisible vs. appearing suddenly): "but" is the correct choice to express this contrast.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.099Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
