INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (365, 1, NULL, 48, '4. A humorous story requires no artistic skill, while a comic story does.', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'The passage states, "The humorous story depends for its effect upon the manner of telling; the comic and the witty story, upon the matter," which directly matches option 3.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (366, 1, NULL, 49, '4. unlike the comic and witty stories, humorous stories do not depress the reader', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'The passage explicitly says "The humorous story is a high and delicate art that requires an artist to tell," positioning it above comic/witty stories, which do not need artistic skill.

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (367, 1, NULL, 50, '4. is skillfully casual in his treatment of the punchline', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 0, 'The passage says the comic storyteller "does not slur the nub, he shouts it at you and when he prints it he emphasizes the punchline with italics and exclamation marks," which means the nub (or the punchline) is stressed openly and forcefully', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (368, 1, NULL, 51, 'How is the humour in a humorous story typically conveyed?', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'The passage states the humorous story "is told gravely, with the teller attempting to conceal the humor," contrasting it with comic storytelling that announces and emphasizes the punchline', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (369, 1, NULL, 52, '4. Light reflected through the cracks', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'The passage states the researchers hypothesize microbes were carried into the rock by water after formation and that "clay deposits in the fractures may have provided nutrients," which would support survival.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (370, 1, NULL, 53, '4. By analysing clay deposits in the fractures of the rock.', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'The passage notes that after slicing the rock core, researchers "found microbial cells in tiny fractures" and "DNA staining and imaging with advanced microscopes confirmed the microbes were indigenous, with intact cell walls," indicating they were native and active, not contaminants.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.109Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (371, 1, NULL, 54, '4. Microorganisms on Mars are likely much younger than those on Earth.', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'The passage notes similarities between the Bushveld rocks and Martian rocks and suggests "the same techniques could identify life on Mars," implying methodological transfer to search for subsurface biosignatures there', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.109Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (372, 1, NULL, 55, '4. They were found in relatively young volcanic sediments', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4 Answer: C","image_url":null,"alt":null}]', NULL, 2, 'The passage calls the microbes "primitive in evolutionary terms" and says they offer clues about Earth''s earliest life forms and their evolution, implying their simplicity and adaptations parallel ancient life', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.109Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
