Tenuous : weak/insubstantial, doesn''t convey danger.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.122Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
