Modesty : humility, opposite in meaning.

Magnanimity : generosity/nobility, unrelated.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.123Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (400, 1, NULL, NULL, 'Complete the sentences given in List-I with the appropriate Phrasal verbs from List-II:-', NULL, '[{"text":"(\\mathbf{A})-(\\mathbf{I}\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I}),(\\mathbf{C})-(\\mathbf{I}\\mathbf{V}),(\\mathbf{D})-(\\mathbf{I}\\mathbf{I})","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (IV), (C) - (I), (D) - (III)","image_url":null,"alt":null}]', NULL, 1, 'A - bear out (confirm/support claims)

B - beat down (fall heavily/strike with force)

C - beat out (surpass/defeat competitors)

D - bear on (have relevance/influence on findings)', NULL, NULL, 2025, '/local-papers/assets/english-2025-05-20-shift-2/q36-table-1.jpg', 'Table for question 36', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.123Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2025-05-20-shift-2/q36-table-1.jpg","alt":"Table for question 36","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (401, 1, NULL, NULL, 'Match the words given in List-I with their meanings given in List-II:-', NULL, '[{"text":"(A) - (I), (B) - (III), (C) - (IV), (D) - (II)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (IV), (C) - (III), (D) - (I)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 1, 'Divergent : contrasting opinions/ideas

Discrete : separate, non-overlapping

Diverse : varied types/kinds

Distinct : clearly noticeable differences', NULL, NULL, 2025, '/local-papers/assets/english-2025-05-20-shift-2/q37-table-1.jpg', 'Table for question 37', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.124Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2025-05-20-shift-2/q37-table-1.jpg","alt":"Table for question 37","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (402, 1, NULL, NULL, 'Match the proverbs in List-I with their meanings in List-II:', NULL, '[{"text":"(\\mathbf{A})-(\\mathbf{I V}),(\\mathbf{B})-(\\mathbf{I}),(\\mathbf{C})-(\\mathbf{I I I}),(\\mathbf{D})-(\\mathbf{I I})","image_url":null,"alt":null},{"text":"(\\mathbf{A})-(\\mathbf{I}\\mathbf{I I}),(\\mathbf{B})-(\\mathbf{I V}),(\\mathbf{C})-(\\mathbf{I}),(\\mathbf{D})-(\\mathbf{I I})","image_url":null,"alt":null},{"text":"\\left(\\mathbf{A}\\right)-(\\mathbf{II}),\\left(\\mathbf{B}\\right)-(\\mathbf{I}),\\left(\\mathbf{C}\\right)-(\\mathbf{III}),\\left(\\mathbf{D}\\right)-(\\mathbf{IV})","image_url":null,"alt":null},{"text":"\\ (\\mathrm{A})-(\\mathrm{I}),(\\mathrm{B})-(\\mathrm{III}),(\\mathrm{C})-(\\mathrm{IV}),(\\mathrm{D})-(\\mathrm{II})","image_url":null,"alt":null}]', NULL, 1, 'A: 3 (harms own family/friends)

B: 4 (don''t be ungrateful for a gift)

C: 1 (blames tools for failure)', NULL, NULL, 2025, '/local-papers/assets/english-2025-05-20-shift-2/q38-table-1.jpg', 'Table for question 38', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.124Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2025-05-20-shift-2/q38-table-1.jpg","alt":"Table for question 38","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (403, 1, NULL, NULL, 'Fill in the blank with the correct word from the options given below:-

The king _ the throne voluntarily.', NULL, '[{"text":"accessed","image_url":null,"alt":null},{"text":"adopted","image_url":null,"alt":null},{"text":"abdicated","image_url":null,"alt":null},{"text":"abided","image_url":null,"alt":null}]', NULL, 2, 'The correct word is ''abdicated'', meaning to voluntarily give up a throne or position. Accessed - to gain entry; incorrect.

Adopted - to take on; opposite of giving up.

Abided - to follow or tolerate; unrelated', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.124Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (404, 1, NULL, NULL, 'Rearrange the following parts into a meaningful sentence:

(A) narratives, often capturing royal, religious and nature scenes,

(B) vibrant colours, offer a unique glimpse into historical and cultural

(C) with a precision that makes each piece a work of art in itself

(D) miniature paintings, known for their intricate details and', NULL, '[{"text":"(D), (B), (A), (C)","image_url":null,"alt":null},{"text":"(D), (A), (B), (C)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 0, 'Miniature paintings, known for their intricate details and vibrant colors, offer a unique glimpse into historical and cultural narratives, often capturing royal, religious, and nature scenes, with a precision that makes each piece a work of art in itself.

D introduces the subject (Miniature paintings).

B presents the first quality (vibrant colors).

A adds the narrative content captured.

C concludes with the artistic precision.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.124Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (405, 1, NULL, NULL, 'Match the words given in List-I with the definitions from List-II:', NULL, '[{"text":"(A) - (IV), (B) - (III), (C) - (II), (D) - (I)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null}]', NULL, 0, '(A) Ophthalmologists - specialize in eye and vision care.

(B) Cardiologist - deal with disorders of the heart and blood vessels.

(C) Nephrologist - focus on kidney health and diseases.

(D) Orthodontist - dental specialists specifically for teeth straightening and jaw alignment.', NULL, NULL, 2025, '/local-papers/assets/english-2025-05-20-shift-2/q42-table-1.jpg', 'Table for question 42', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.125Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2025-05-20-shift-2/q42-table-1.jpg","alt":"Table for question 42","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (406, 1, NULL, NULL, 'Rearrange the following parts into a meaningful sentence:

(A) of minds of contemporary times

(B) this volume is a rich collection of the best

(C) cutting across boundaries and gender

(D) of insights and thoughts of the greatest', NULL, '[{"text":"(B), (A), (C), (D)","image_url":null,"alt":null},{"text":"(B), (D), (A), (C)","image_url":null,"alt":null},{"text":"(D), (B), (A), (C)","image_url":null,"alt":null},{"text":"(D), (B), (C), (A)","image_url":null,"alt":null}]', NULL, 1, 'This volume is a rich collection of the best of insights and thoughts of the greatest of minds of contemporary times, cutting across boundaries and gender.

B: Introduces the subject - "This volume is a rich collection of the best."

D: Specifies the type of content - "of insights and thoughts of the greatest."

A: Identifies whose minds - "of minds of contemporary times."

C: Adds scope - "cutting across boundaries and gender."', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.125Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
