INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (413, 1, NULL, NULL, 'Fill in the blanks in List-I with the appropriate homonyms from List-II:-', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)","image_url":null,"alt":null}]', NULL, 1, 'A: disassemble - take apart the machine for transport.

B: dissemble - hide or disguise true feelings.

