INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (441, 18, NULL, NULL, 'Select a figure from the options which would continue the given series:', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-1/q29-table-1.jpg', 'Table for question 29', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.141Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-1/q29-table-1.jpg","alt":"Table for question 29","kind":"table"},{"url":"/local-papers/assets/general-test-2025-05-20-shift-1/q29-options.jpg","alt":"Printed answer choices for question 29","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (442, 18, NULL, NULL, 'The focal length of a spherical mirror is equal to:', NULL, '[{"text":"A quarter of its radius of curvature","image_url":null,"alt":null},{"text":"Half of its radius of curvature","image_url":null,"alt":null},{"text":"Three quarters of its radius of curvature","image_url":null,"alt":null},{"text":"Equal to its radius of curvature","image_url":null,"alt":null}]', NULL, 1, 'The relationship between focal length $f$ and radius of curvature $R$ for a spherical mirror is:

$f=\frac{R}{2}$

This shows that the focal length is half of the radius of curvature.

Final Answer:

2. Half of its radius of curvature', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.142Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (443, 18, NULL, NULL, 'How many perfect squares lie between 120 and 300?', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 2, 'We need perfect squares between 120 and 300.

Step 1: Find nearest square roots

• $ \sqrt{120} \approx 10.95 \rightarrow $ next integer = 11

• $ \sqrt{300} \approx 17.32 \rightarrow $ last integer = 17

Step 2: Count integers from 11 to 17

Numbers: 11, 12, 13, 14, 15, 16, 17 → total 7 numbers

So, there are 7 perfect squares:

$ 11^{2} $, $ 12^{2} $, ..., $ 17^{2} $

Final Answer:

7 (Option 3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.142Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
