INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (447, 18, NULL, NULL, 'Which of the following are non-metallic minerals?

(A) Mica

(B) Bauxite

(C) Granite

(D) Potash', NULL, '[{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'We need to identify non-metallic minerals:

- (A) Mica → Non-metallic ✓

- (B) Bauxite → Metallic (ore of aluminium) ✗

- (C) Granite → Non-metallic (rock, used as building material)

- (D) Potash → Non-metallic (used in fertilizers) ✓

Correct combination:

(A), (C) and (D)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.143Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (448, 18, NULL, NULL, 'Two persons A and B appear in an interview for two vacancies. If the probabilities of their selections are 1/4 and 1/6 respectively, then the probability that none of them is selected shall be:

3. $ \frac{5}{12} $', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4 Answer: D","image_url":null,"alt":null}]', NULL, 3, 'Given:

• $ P(A \text{ selected}) = \frac{1}{4} \Rightarrow P(A \text{ not selected}) = \frac{3}{4} $

• $ P(B \text{ selected}) = \frac{1}{6} \Rightarrow P(B \text{ not selected}) = \frac{5}{6} $

Assuming independence, probability that none is selected:

$$ \frac{3}{4}\times\frac{5}{6}=\frac{15}{24}=\frac{5}{8} $$
Final Answer:

5/8 (Option 4)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.143Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (449, 18, NULL, NULL, 'A sales agent travels a distance of 50 km in 2 hours and 30 minutes. How much faster, in kilometers per hour, on average, must he travel to make such a trip in 5/6 hours less time?', NULL, '[{"text":"40","image_url":null,"alt":null},{"text":"30","image_url":null,"alt":null},{"text":"20","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null}]', NULL, 3, 'Distance = 50 km

Step 1: Original speed

Time = 2 hours 30 minutes = 2.5 hours

$$ Speed_{1}=\frac{50}{2.5}=20km/h $$

Step 2: New time

Reduced time = $ \frac{5}{6} $ hours

$$ New~time=2.5-\frac{5}{6}=\frac{15-5}{6}=\frac{10}{6}=\frac{5}{3}hours $$

Step 3: New speed

$$ Speed_{2}=\frac{50}{5/3}=50\times\frac{3}{5}=30km/h $$

Step 4: Increase in speed

30-20=10km/h

Final Answer:

10 km/h (Option 4)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.144Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (450, 18, NULL, NULL, 'Find the coordinates of the point which divides the line segment joining the points $ (4,-3) $ and $ (8,5) $ in the ratio 3:1 internally?', NULL, '[{"text":"(7, 3)","image_url":null,"alt":null},{"text":"(3, 7)","image_url":null,"alt":null},{"text":"(2, -2)","image_url":null,"alt":null},{"text":"(-4, 6)","image_url":null,"alt":null}]', NULL, 0, 'To find the point dividing the line segment internally in the ratio 3:1, we use the section formula:

$ \left(\frac{mx_2 + nx_1}{m+n}, \frac{my_2 + ny_1}{m+n}\right) $

Here:

- $ (x_1, y_1) = (4, -3) $

- $ (x_2, y_2) = (8, 5) $

- Ratio m : n = 3 : 1

Step 1: Apply formula

$$ \begin{aligned}x&=\frac{3\cdot8+1\cdot4}{4}=\frac{24+4}{4}=7\\y&=\frac{3\cdot5+1\cdot(-3)}{4}=\frac{15-3}{4}=3\end{aligned} $$

Final Answer:

(7, 3) (Option 1)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.147Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (451, 18, NULL, NULL, 'If area of a square is 44 cm², find the area of the circle formed by the same perimeter.', NULL, '[{"text":"50 cm²","image_url":null,"alt":null},{"text":"28 cm²","image_url":null,"alt":null},{"text":"56 cm²","image_url":null,"alt":null},{"text":"16 cm²","image_url":null,"alt":null}]', NULL, 2, 'Given:

Area of square = 44 cm^{2}

Step 1: Find side of square

$$ s^{2}=44\Rightarrow s=\sqrt{44}=2\sqrt{11} $$

Step 2: Perimeter of square

$$ P=4s=8\sqrt{11} $$

This equals the circumference of the circle.

Step 3: Use circumference formula

$$ 2\pi r=8\sqrt{11}\Rightarrow r=\frac{4\sqrt{11}}{\pi} $$

Step 4: Area of circle

$$ \pi r^{2}=\pi\left(\frac{4\sqrt{11}}{\pi}\right)^{2}=\pi\cdot\frac{16\cdot11}{\pi^{2}}=\frac{176}{\pi} $$

Using $ \pi \approx \frac{22}{7} $:

$$ \frac{176}{\pi}=\frac{176\times7}{22}=56 $$

Final Answer:

56 cm $ ^{2} $ (Option 3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.148Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (452, 18, NULL, NULL, 'If $ \sqrt{2}:(1+\sqrt{3})::\sqrt{6}:x $, then x is equal to:', NULL, '[{"text":"3+\\sqrt{3}","image_url":null,"alt":null},{"text":"1+\\sqrt{3}","image_url":null,"alt":null},{"text":"\\sqrt{3}-3","image_url":null,"alt":null},{"text":"1-\\sqrt{3}","image_url":null,"alt":null}]', NULL, 0, 'Given:

$$ \sqrt{2}:(1+\sqrt{3}):\sqrt{6}:x $$

This means:

$$ \frac{\sqrt{2}}{1+\sqrt{3}}=\frac{\sqrt{6}}{x} $$

Step 1: Cross multiply

$$ x\sqrt{2}=\sqrt{6}(1+\sqrt{3}) $$

Step 2: Solve for x

$$ \begin{aligned}x&=\frac{\sqrt{6}(1+\sqrt{3})}{\sqrt{2}}\\=\sqrt{\frac{6}{2}}(1+\sqrt{3})=\sqrt{3}(1+\sqrt{3})\end{aligned} $$

Step 3: Expand

$$ x=\sqrt{3}+3 $$

Final Answer:

✓ 3 + $ \sqrt{3} $ (Option 1)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.149Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (453, 18, NULL, NULL, 'By selling 8 pens for Rs 75, a shopkeeper loses 25%. How many pens should be sold for Rs 372 to earn a 24% profit?', NULL, '[{"text":"30","image_url":null,"alt":null},{"text":"18","image_url":null,"alt":null},{"text":"24","image_url":null,"alt":null},{"text":"20","image_url":null,"alt":null}]', NULL, 2, 'Let cost price (CP) per pen = x

Step 1: Given loss of 25%

Selling 8 pens for Rs 75 $ \Rightarrow $ SP per pen = 75/8

Loss 25% $ \Rightarrow $ SP = 75% of CP

$$ \frac{75}{8}=0.75x=\frac{3}{4}x $$

$$ x=\frac{75}{8}\times\frac{4}{3}=12.5 $$

So, CP per pen = Rs 12.5

Step 2: For 24% profit

SP per pen = 1.24 × 12.5 = 15.5

Step 3: Number of pens for Rs 372

$$ Number~of~pens=\frac{372}{15.5}=24 $$

Final Answer:

24 pens (Option 3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.150Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (454, 18, NULL, NULL, 'Study the table given carefully and choose the correct number option that shall come in place of ''?'' :', NULL, '[{"text":"130","image_url":null,"alt":null},{"text":"70","image_url":null,"alt":null},{"text":"83","image_url":null,"alt":null},{"text":"110","image_url":null,"alt":null}]', NULL, 0, 'The table is:
Top row: 5 14 12
Middle row: 48 135 ?
Bottom row: 8 9 10
Observe the pattern (column-wise):
Middle number = (Top × Bottom) + Bottom
Check:
- Column 1:
$ 5 \times 8 + 8 = 40 + 8 = 48 $ ✓
- Column 2:
$ 14 \times 9 + 9 = 126 + 9 = 135 $ ✓

Apply to Column 3:
$ 12 \times 10 + 10 = 120 + 10 = 130 $

Final Answer:
✓ 130 (Option 1)', NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-1/q42-table-1.jpg', 'Table for question 42', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.150Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-1/q42-table-1.jpg","alt":"Table for question 42","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (455, 18, NULL, NULL, 'Identify the mirror image of the given figure:', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-1/q43-figure-1.jpg', 'Figure for question 43', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.151Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-1/q43-figure-1.jpg","alt":"Figure for question 43","kind":"figure"},{"url":"/local-papers/assets/general-test-2025-05-20-shift-1/q43-options.jpg","alt":"Printed answer choices for question 43","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (456, 18, NULL, NULL, 'Which one of the following statement(s) is/are correct?

(A) Every whole number is a natural number.

(B) Every natural number is a whole number.

(C) Every integer is a whole number.

(D) Every rational number is a whole number', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(B) only","image_url":null,"alt":null},{"text":"(B) and (A) only","image_url":null,"alt":null},{"text":"(D) only","image_url":null,"alt":null}]', NULL, 1, 'Let''s evaluate each statement:

(A) Every whole number is a natural number ✗

Whole numbers include 0, but natural numbers usually start from 1 → so false.

(B) Every natural number is a whole number ✓

Natural numbers (1, 2, 3, ...) are included in whole numbers (0, 1, 2, ...).

• (C) Every integer is a whole number X

Integers include negatives $ (-1, -2, \ldots) $, which are not whole numbers.

• (D) Every rational number is a whole number X

Rational numbers include fractions (like $ 1/2 $), not all are whole.

Final Answer: (B) only (Option 2)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.151Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (457, 18, NULL, NULL, 'Arrange the following in the increasing order:

(A) Micrometre

(B) Centimetre

(C) Mile

(D) Kilometre', NULL, '[{"text":"(A), (B), (D), (C)","image_url":null,"alt":null},{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (A), (B), (D)","image_url":null,"alt":null}]', NULL, 0, 'We need to arrange from smallest to largest:
- Micrometre (μm) = 10⁻⁶ m (very small)
- Centimetre (cm) = 10⁻² m
- Kilometre (km) = 10³ m
- Mile ≈ 1.6 km (larger than kilometre)

Increasing order:
Micrometre < Centimetre < Kilometre < Mile
Final Answer:
(A), (B), (D), (C) (Option 1)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.152Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (458, 18, NULL, NULL, 'If $6x - 10y = 10$ and $\frac{x}{x+y} = \frac{5}{7}$, then $(x-y)$ is equal to:', NULL, '[{"text":"12","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null}]', NULL, 3, 'We are given:

$$ 6x-10y=10\quad and\quad\frac{x}{x+y}=\frac{5}{7} $$

Step 1: Use the ratio

$$ \frac{x}{x+y}=\frac{5}{7}\Rightarrow7x=5(x+y) $$

$$ 7x=5x+5y\Rightarrow2x=5y\Rightarrow x=\frac{5}{2}y $$

Step 2: Substitute into first equation

$$ 6\left(\frac{5}{2}y\right)-10y=10 $$

$$ 15y-10y=10\Rightarrow5y=10\Rightarrow y=2 $$

Step 3: Find x

$$ x=\frac{5}{2}\times2=5 $$

Step 4: Find x - y

$$ x-y=5-2=3 $$

Final Answer:

| 3 (Option 4)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.153Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (459, 18, NULL, NULL, 'Which among the following are Fundamental Rights as included in Part III of the Constitution of India?

(A) Equality of opportunity in public employment

(B) Equal pay for equal work for men and women

(C) Right of minorities to establish educational institutions

(D) Right to education', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'Evaluate each statement under Part III (Fundamental Rights):

- (A) Equality of opportunity in public employment ✓

Comes under Article 16 (Fundamental Right).

- (B) Equal pay for equal work for men and women ✗

This is a Directive Principle of State Policy (Article 39), not a Fundamental Right.

- (C) Right of minorities to establish educational institutions ▩

Protected under Article 30 (Fundamental Right).

- (D) Right to education ✓

Included as a Fundamental Right under Article 21A.

Final Answer: (A), (C) and (D) only (Option 3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.154Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (460, 18, NULL, NULL, 'Match List-I with List-II', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{II}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{I}) $","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null},{"text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)","image_url":null,"alt":null}]', NULL, 2, '(A)

$$ \frac{12!}{10!(2!)} $$

