Problem figure:', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q16-figure-1.jpg', 'Figure for question 16', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.170Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q16-figure-1.jpg","alt":"Figure for question 16","kind":"figure"},{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q16-options.jpg","alt":"Printed answer choices for question 16","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (475, 18, NULL, NULL, 'What will be the measurement of the angle made by the hands of a clock when the time is 8:40?', NULL, '[{"text":"20^{0}","image_url":null,"alt":null},{"text":"350","image_url":null,"alt":null},{"text":"485^{0}","image_url":null,"alt":null},{"text":"50^{0}","image_url":null,"alt":null}]', NULL, 0, 'Use the clock angle formula:

$$ \mathrm{A n g l e}=|30H-5.5M| $$

For 8:40:

$$ =|30\times8-5.5\times40|=|240-220|=20^{\circ} $$

Correct Answer: 1. $ 20^{\circ} $', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.170Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (476, 18, NULL, NULL, 'Which of the following will show "Tyndall Effect"?

(A) Mixture of water and milk

(B) Sunlight passing through a canopy of dense forest

(C) Solution of copper sulphate

(D) Light entering a smoke-filled room through a small hole', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, 'Tyndall Effect:

It is the scattering of light by colloidal particles.

Check options:

• (A) Water + milk → colloid → shows Tyndall effect

• (B) Sunlight in dense forest $ \rightarrow $ dust particles scatter light

• (C) Copper sulphate solution → true solution → no scattering ✗

• (D) Smoke-filled room → colloidal particles → scattering

Correct Answer: 2. (A), (B) and (D) only', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
