INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (479, 18, NULL, NULL, 'Who is the author of the book ''The Mughals of India''?', NULL, '[{"text":"William Dalrymple","image_url":null,"alt":null},{"text":"Romila Thapar","image_url":null,"alt":null},{"text":"Harbans Mukhia","image_url":null,"alt":null},{"text":"John F. Richards","image_url":null,"alt":null}]', NULL, 2, 'But for the exact title The Mughals of India, the author is actually Harbans Mukhia. So there is likely an error in the question/options.

