INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (480, 18, NULL, NULL, 'Select the one which is different from the other three alternatives:', NULL, '[{"text":"7,56","image_url":null,"alt":null},{"text":"13,78","image_url":null,"alt":null},{"text":"9,64","image_url":null,"alt":null},{"text":"11,132","image_url":null,"alt":null}]', NULL, 2, 'Check pattern:

