INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (481, 18, NULL, NULL, 'The age distribution of 40 children is as follows

Consider the following statements in respect of the above frequency distribution.

(A) The median of the age distribution is 7 yr.

(B) 70% of the children are in the age group 6-9 yr.

(C) The modal class of the children is 8-9 yr.

Which of the above statements are true?', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null}]', NULL, 3, 'Given data:

Frequencies: 4, 7, 9, 12, 6, 2 (Total = 40)

(A) Median

Cumulative frequencies:

4, 11, 20, 32, 38, 40

$$ \frac{N}{2}=20 $$

Median class = 7-8

Median $ \approx $ 7 (approx) $ \rightarrow $ True ✓

(B) % in 6-9 age group

$$ 6-7+7-8+8-9=7+9+12=28 $$

$$ \frac{28}{40}\times100=70\% $$

→ True ✓

(C) Modal class

Highest frequency = 12 → class 8-9

→ True ✓

Correct Answer: 4. (A), (B) and (C) only', NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q23-table-1.jpg', 'Table for question 23', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.173Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q23-table-1.jpg","alt":"Table for question 23","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
