Problem figure:', NULL, '[{"text":"$$ \\mid $$","image_url":null,"alt":null},{"text":"$$ \\boxed{一} $$","image_url":null,"alt":null},{"text":"$$ \\mid $$","image_url":null,"alt":null},{"text":"$$ \\boxed{\\quad} $$","image_url":null,"alt":null}]', NULL, 0, 'Ⅰ', NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q24-table-1.jpg', 'Table for question 24', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.173Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q24-table-1.jpg","alt":"Table for question 24","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (483, 18, NULL, NULL, 'The remainder when $ (15^{23} + 23^{23}) $ is divided by 19, is:', NULL, '[{"text":"18","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.174Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (484, 18, NULL, NULL, 'The monthly salary of A, B and C are in the ratio 2:3:5. If C''s monthly salary is Rs.1200 more than that of A, then B''s annual salary is:', NULL, '[{"text":"Rs. 24000","image_url":null,"alt":null},{"text":"Rs. 14400","image_url":null,"alt":null},{"text":"Rs. 12000","image_url":null,"alt":null},{"text":"Rs. 96000","image_url":null,"alt":null}]', NULL, 1, 'Let monthly salaries be:

A: B: C = 2x: 3x: 5x

Given:

C - A = 1200

5x-2x=3x=1200\Rightarrow x=400

B''s monthly salary:

3x = 3 × 400 = 1200

B''s annual salary:

1200×12=14400

Correct Answer: 2. Rs. 14400', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.174Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (485, 18, NULL, NULL, 'Which of the following Amendments to the Constitution of India provided that the total number of Ministers, including the Prime Minister, in the Council of Ministers shall not exceed 15% of the total members of the Lok Sabha?', NULL, '[{"text":"91st Amendment","image_url":null,"alt":null},{"text":"93rd Amendment","image_url":null,"alt":null},{"text":"95th Amendment","image_url":null,"alt":null},{"text":"99th Amendment","image_url":null,"alt":null}]', NULL, 0, '1. 91st Amendment

The 91st Constitutional Amendment Act, 2003 fixed that the total number of ministers, including the Prime Minister, cannot exceed 15% of the total strength of the Lok Sabha.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.175Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (486, 18, NULL, NULL, 'What number should replace the question mark ?', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"26","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"48","image_url":null,"alt":null}]', NULL, 0, 'Pattern:

Center number = (Top-left + Bottom-left) - (Top-right + Bottom-right)

Check:

1st box:

$$ (13+12)-(4+5)=25-9=16\neq2 $$

Try another pattern:

New pattern:

Center = (Top-left × Bottom-right) - (Top-right × Bottom-left)

1st box:

$$ (13\times5)-(4\times12)=65-48=17\neq2 $$

Try simpler:

Correct pattern:

Center = (Top-left - Top-right) × (Bottom-left - Bottom-right)

1st box:

(13 - 4)(12 - 5) = 9 \times 7 = 63 \neq 2

Final correct pattern:

Center = (Sum of all numbers) ÷ 17

Check 2nd box:

$$ 23+9+22+32=86,86\div?=24 $$

Not consistent $ \rightarrow $ try difference pattern:

Correct observation:

Center = (Top-left + Bottom-right) - (Top-right + Bottom-left)

1st box:

(13+5)-(4+12)=18-16=2√

2nd box:

(23+32)-(9+22)=55-31=24 ✓

Apply to 3rd box:

(2+24)-(9+12)=26-21=5

Correct Answer: 1.5', NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q28-figure-1.jpg', 'Figure for question 28', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.175Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q28-figure-1.jpg","alt":"Figure for question 28","kind":"figure"},{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q28-figure-2.jpg","alt":"Figure for question 28","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (487, 18, NULL, NULL, 'Choose the option that shall come in place of the ? in the following series :

25WV52, 23TS32, 21QP12,?,17KJ71', NULL, '[{"text":"19MN91","image_url":null,"alt":null},{"text":"19ON92","image_url":null,"alt":null},{"text":"19NM91","image_url":null,"alt":null},{"text":"19LK92","image_url":null,"alt":null}]', NULL, 2, 'Series: 25WV52, 23TS32, 21QP12,?, 17KJ71

• First number: 25, 23, 21, 19, 17 (-2 each)

• Letters:

○ W → T → Q → N → K (-3 each)

○ V → S → P → M → J (-3 each)

• Last number:

○ 52 → 32 → 12 → ? → 71

Pattern: -20 each → 52, 32, 12, (-20 → -8 → 92), 71

Missing term:

19NM92

Correct Answer: 3.19NM92', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.176Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (488, 18, NULL, NULL, 'Which of the following are "unicellular" organisms?

(A) Plasmodium

(B) Protoza

(C) Spirogyra

(D) Leishmania', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, 'Let''s check each option:

• (A) Plasmodium $ \rightarrow $ unicellular (a protozoan parasite)

• (B) Protozoa $ \rightarrow $ unicellular organisms by definition ✓

• (C) Spirogyra $ \rightarrow $ multicellular (filamentous green algae)

• (D) Leishmania $ \rightarrow $ unicellular (a protozoan parasite)
Correct combination:

(A), (B), and (D) only

Final Answer: Option 2', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.177Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (489, 18, NULL, NULL, 'The Tlawng river is located at which of the following cities in India?', NULL, '[{"text":"Imphal","image_url":null,"alt":null},{"text":"Aizawl","image_url":null,"alt":null},{"text":"Agartala","image_url":null,"alt":null},{"text":"Itanagar","image_url":null,"alt":null}]', NULL, 1, 'The Tlawng River is associated with Aizawl in Mizoram.

Correct answer: 2. Aizawl', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.180Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (490, 18, NULL, NULL, 'How many two-digit numbers are divisible by 3?', NULL, '[{"text":"30","image_url":null,"alt":null},{"text":"20","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 0, 'Answer: A

Two-digit numbers range from 10 to 99.

First multiple $ \geq 10 \rightarrow 12 $

Last multiple ≤ 99 → 99

Now count them:

This is an arithmetic sequence: 12, 15, 18, ..., 99

Common difference = 3

Number of terms: _

$$ n=\frac{99-12}{3}+1=\frac{87}{3}+1=29+1=30 $$

✓ Final Answer:

1. 30', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.181Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (491, 18, NULL, NULL, 'Match List-I with List-II', NULL, '[{"text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (IV), (C) - (I), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null}]', NULL, 1, '(A) Least number subtracted from 2025 to be divisible by 17

To find this, we divide 2025 by 17 and find the remainder:

· 2025 = $ 17 \times 119 + 2 $

• The remainder is 2.

- Subtracting the remainder makes the number perfectly divisible.

• Result: (A) matches with (II).
(B) Least number added to $ 1057^{5} $ to be divisible by 23

First, find the remainder when 1057 is divided by 23:

- $ 1057 \div 23 = 45 $ with a remainder of 22 (which is the same as saying -1 in modular arithmetic because $ 1057 + 1 = 1058 $, and $ 1058 \leq 23 \times 46 $).

• So, 1057 ≡ -1 (mod 23).

• Then, $1057^{5} \equiv (-1)^{5} \pmod{23} \equiv -1 \pmod{23}$.

- A remainder of -1 means the number is 1 short of being divisible. Therefore, we need to add 1.

• Result: (B) matches with (IV).

(C) Unit digit of $ 6^{15} - 7^{4} $

- Unit digit of $ 6^{15} $: Any power of 6 always ends in 6.

• Unit digit of 74:

$ 0.7^{1}=7 $

$ 7^{2} = 49 \rightarrow 9 $

$ 7^{3} = 343 \to 3 $

$ 7^{4} = 2401 \rightarrow 1 $

- The difference of the unit digits is 6 - 1 = 5.

• Result: (C) matches with (I).

(D) Product of any number and the 1st whole number

• The set of whole numbers starts from 0: {0, 1, 2, 3, ...}.

• The 1st whole number is 0.

- The product of any number and 0 is always 0.

• Result: (D) matches with (III).

Conclusion

Matching the results:

(A) $ \rightarrow $ (II)

(B) $ \rightarrow $ (IV)

(C) $ \rightarrow(1) $

(D) $ \rightarrow $ (III)

This corresponds to Option 2.', NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q33-table-1.jpg', 'Table for question 33', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.181Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q33-table-1.jpg","alt":"Table for question 33","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (492, 18, NULL, NULL, 'At the foot of a mountain, the elevation of the summit is $ 45^{\circ} $. After ascending 2 kilometers towards the mountain, at an incline of $ 30^{\circ} $, the elevation changes to $ 60^{\circ} $. Determine the height of the mountain?', NULL, '[{"text":"( $ \\sqrt{3} - 1 $) kilometre","image_url":null,"alt":null},{"text":"( $ \\sqrt{3} + 1 $) kilometre","image_url":null,"alt":null},{"text":"( $ \\sqrt{3} - 2 $) kilometres","image_url":null,"alt":null},{"text":"( $ \\sqrt{3} + 2 $) kilometres","image_url":null,"alt":null}]', NULL, 1, 'Step 1: From the foot of the mountain

Angle of elevation = $ 45^{\circ} $

$$ \tan45^{\circ}=\frac{h}{x}=1\Rightarrow h=x $$

So, horizontal distance = x = h
Step 2: After moving 2 km at $ 30^{\circ} $ incline

Horizontal distance covered:

$$ 2\cos30^{\circ}=2\cdot\frac{\sqrt{3}}{2}=\sqrt{3} $$

Vertical height gained:

$$ 2\sin30^{\circ}=2\cdot\frac{1}{2}=1 $$

New position:

• Horizontal distance from mountain base = $ h - \sqrt{3} $

Height above ground = 1

Step 3: New angle of elevation = $ 60^{\circ} $

$$ \tan60^{\circ}=\frac{h-1}{h-\sqrt{3}}=\sqrt{3} $$

Step 4: Solve

$$ \frac{h-1}{h-\sqrt{3}}=\sqrt{3} $$

$$ h-1=\sqrt{3}(h-\sqrt{3}) $$

$$ h-1=\sqrt{3}h-3 $$

$$ 2=(\sqrt{3}-1)h $$

$$ h=\frac{2}{\sqrt{3}-1} $$

Rationalize:

$$ h=\frac{2(\sqrt{3}+1)}{2}=\sqrt{3}+1 $$
✓ Final Answer:

2. $ (\sqrt{3} + 1) $ kilometre', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.182Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (493, 18, NULL, NULL, 'Match List-I with List-II', NULL, '[{"text":"(A) - (III), (B) - (II), (C) - (IV), (D) - (I)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (II), (C) - (I), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (I), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null}]', NULL, 1, '(A) Gukesh D

