Question figure:', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/general-test-2025-05-20-shift-2/q36-figure-1.jpg', 'Figure for question 36', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.183Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q36-figure-1.jpg","alt":"Figure for question 36","kind":"figure"},{"url":"/local-papers/assets/general-test-2025-05-20-shift-2/q36-options.jpg","alt":"Printed answer choices for question 36","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (495, 18, NULL, NULL, 'Arrange the following historical events in chronological order, beginning with the earliest to the most recent.

(A) Universities established in Bombay, Madras and Calcutta

(B) Transfer of Capital from Calcutta to Delhi

(C) Supreme Court set up in Calcutta by the East India Company

(D) Asiatic Society founded by Sir William Jones', NULL, '[{"text":"(C), (D), (A), (B)","image_url":null,"alt":null},{"text":"(C), (D), (B), (A)","image_url":null,"alt":null},{"text":"(D), (C), (B), (A)","image_url":null,"alt":null},{"text":"(D), (C), (A), (B)","image_url":null,"alt":null}]', NULL, 0, 'Dates:

- (C) Supreme Court set up in Calcutta - 1774

- (D) Asiatic Society founded - 1784

- (A) Universities in Bombay, Madras and Calcutta - 1857

- (B) Transfer of capital from Calcutta to Delhi - 1911

So the correct chronological order is:

(C), (D), (A), (B)

Final Answer: Option 1', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.184Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (496, 18, NULL, NULL, 'Ram, Shyam and Hari can complete a work in 20, 25 and 30 days, respectively.

Consider the following statements:

(A) Ram and Shyam together will complete the work in $ 11\frac{1}{9} $ days.

(B) Shyam and Hari together will complete the work in 14 days.', NULL, '[{"text":"(A) only","image_url":null,"alt":null},{"text":"(B) only","image_url":null,"alt":null},{"text":"(A) and (B)","image_url":null,"alt":null},{"text":"Neither (A) nor (B)","image_url":null,"alt":null}]', NULL, 0, 'Ram, Shyam, Hari rates:

• Ram = $ \frac{1}{20} $

$ \bullet $ Shyam = $ \frac{1}{25} $

Hari = $ \frac{1}{30} $

(A) Ram + Shyam

$$ \frac{1}{20}+\frac{1}{25}=\frac{5+4}{100}=\frac{9}{100} $$

Time taken:

$$ \frac{1}{9/100}=\frac{100}{9}=11\frac{1}{9}days $$

Statement (A) is correct

(B) Shyam + Hari

$$ \frac{1}{25}+\frac{1}{30}=\frac{6+5}{150}=\frac{11}{150} $$

Time taken:

$$ \frac{150}{11}\approx13.64days $$

❌ Not 14 days → Statement (B) is incorrect
Final Answer:

1. (A) only', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.185Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (497, 18, NULL, NULL, 'The area of a sector of a circle of radius 36 cm is $ 72\pi\ \text{cm}^2 $. Find the length of the corresponding arc of the sector.', NULL, '[{"text":"$ 4\\pi $ cm","image_url":null,"alt":null},{"text":"$ 3\\pi $ cm","image_url":null,"alt":null},{"text":"$ 2\\pi $ cm","image_url":null,"alt":null},{"text":"$ \\pi $ cm","image_url":null,"alt":null}]', NULL, 0, 'We use the sector formulas:

Area of sector:

$$ A=\frac{1}{2}r^{2}\theta $$

Arc length:

$$ L=r\theta $$

Step 1: Find $ \theta $

Given:

$$ 72\pi=\frac{1}{2}\cdot36^{2}\cdot\theta $$

$$ 72\pi=\frac{1}{2}\cdot1296\cdot\theta=648\theta $$

$$ \theta=\frac{72\pi}{648}=\frac{\pi}{9} $$

Step 2: Find arc length

$$ L=r\theta=36\cdot\frac{\pi}{9}=4\pi $$
✓ Final Answer:

1. $ 4\pi cm $', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.185Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (498, 18, NULL, NULL, 'Kalibangan, an archaeological site, is located in which state in India?', NULL, '[{"text":"Uttar Pradesh","image_url":null,"alt":null},{"text":"Assam","image_url":null,"alt":null},{"text":"Haryana","image_url":null,"alt":null},{"text":"Rajasthan","image_url":null,"alt":null}]', NULL, 3, 'Kalibangan archaeological site is in Rajasthan.

Correct answer: 4. Rajasthan', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.186Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (499, 18, NULL, NULL, 'A bus passes two persons moving in the direction of the moving bus at a speed of 3 km/hr and 5 km/hr, respectively. The bus passes the first person in 10 s and the second person in 11 s. Find the speed of the bus.', NULL, '[{"text":"28 km/hr","image_url":null,"alt":null},{"text":"27 km/hr","image_url":null,"alt":null},{"text":"25 km/hr","image_url":null,"alt":null},{"text":"24 km/hr","image_url":null,"alt":null}]', NULL, 2, 'Convert speeds to m/s:

• Bus = $ v \times \frac{5}{18} $

- Person 1 = 3 × $ \frac{5}{18} $

• Person 2 = 5 × $ \frac{5}{18} $

Case 1 (Person at 3 km/hr, time = 10 s)

Relative speed:

$$ (v-3)\frac{5}{18} $$

$$ L=\left(v-3\right)\frac{5}{18}\times10 $$

Case 2 (Person at 5 km/hr, time = 11 s)

$$ L=\left(v-5\right)\frac{5}{18}\times11 $$

Equate both:

$$ (v-3)\frac{5}{18}\times10=(v-5)\frac{5}{18}\times11 $$

Cancel $\frac{5}{18}$:

$$ 10(v-3)=11(v-5) $$

10v-30=11v-55

v = 25

✓ Final Answer:

3.25 km/hr', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.186Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (500, 18, NULL, NULL, 'Which of the following collections of letters will look the same in the mirror?

(A) OXA8voHM

(B) TWOVIMYOU

(C) HV8SIMOT

(D) AIXW08VA', NULL, '[{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, '1. Analysis of Individual Characters

Let''s check which characters remain unchanged when reflected horizontally:

• Symmetrical: A, H, I, M, O, T, U, V, W, X, Y, 0, 8, v, o.

- Non-Symmetrical: B, C, D, E, F, G, J, K, L, N, P, Q, R, S, Z, 1, 2, 3, 4, 5, 6, 7, 9.
2. Evaluating the Options

We will examine each collection to see if all characters in it are symmetrical.

(A) OXA8voHM: Every character (O, X, A, 8, v, o, H, M) is vertically symmetrical.

(B) TWOVIM YOU: Every character (T, W, O, V, I, M, Y, O, U) is vertically symmetrical.

Result: Valid

(C) HV8SIMOT: The letter ''S'' is not vertically symmetrical. In a mirror, it appears reversed (2). Result: Invalid

• (D) AIXW08VA: Every character (A, I, X, W, 0, 8, V, A) is vertically symmetrical.
3. Conclusion

Based on the analysis, collections (A), (B), and (D) consist entirely of letters and numbers that look the same in a mirror.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.187Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (501, 18, NULL, NULL, 'The Goods and Services Tax Act, expected to create "One Nation, One Tax and One Market", came into effect in which year?', NULL, '[{"text":"2013","image_url":null,"alt":null},{"text":"2015","image_url":null,"alt":null},{"text":"2017","image_url":null,"alt":null},{"text":"2019","image_url":null,"alt":null}]', NULL, 2, 'The Goods and Services Tax (GST) came into effect in 2017.

Correct answer: 3.2017', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.188Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (502, 18, NULL, NULL, 'Consider the compound interest in the following cases:

(A) The compound interest on Rs 16000 at 20% per annum for 9 months, compounded quarterly is Rs. 2500

(B) The compound interest on Rs 2800 at 10% per annum for 18 months is Rs. 434.

Choose the correct statement(s):', NULL, '[{"text":"Only (A)","image_url":null,"alt":null},{"text":"Only (B)","image_url":null,"alt":null},{"text":"(A) and (B)","image_url":null,"alt":null},{"text":"Neither (A) nor (B)","image_url":null,"alt":null}]', NULL, 1, 'Analysis of Statement (A)

• Principal (P): Rs. 16,000

• Annual Rate (R): 20%

• Time (n): 9 months (which is 3 quarters)

• Quarterly Rate (r): Since interest is compounded quarterly, the rate is 20%/4 = 5% per quarter.

Using the Compound Interest formula: $ A = P(1 + \frac{r}{100})^n $

$$ A=16000\times\left(1+\frac{5}{100}\right)^{3} $$

$$ A=16000\times(1.05)^{3} $$

$$ A=16000\times1.157625=18522 $$

Compound Interest (CI): A - P = 18522 - 16000 = Rs. 2,522

The statement says the interest is Rs. 2,500, so Statement (A) is Incorrect.

Analysis of Statement (B)

• Principal (P): Rs. 2,800

• Annual Rate (R): 10%

• Time: 18 months (1.5 years)

For fractional years, we calculate the amount for the full year and then simple interest on that amount for the remaining months:

1. Amount after 1 year: 2800 + (10% of 2800) = 2800 + 280 = Rs. 3080

2. Interest for next 6 months: 10% of 3080 for half a year = $ 308 \times 0.5 = Rs.\ 154 $

Total Compound Interest: 280 + 154 = Rs. 434

The statement says the interest is Rs. 434, so Statement (B) is Correct.
Conclusion

Since only statement (B) is accurate, the correct option is:

2. Only (B)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.188Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (503, 18, NULL, NULL, 'Baking powder is a mixture of baking soda (sodium hydrogen carbonate) and _?', NULL, '[{"text":"Acetic Acid","image_url":null,"alt":null},{"text":"Citric Acid","image_url":null,"alt":null},{"text":"Tartaric Acid","image_url":null,"alt":null},{"text":"Oxalic Acid","image_url":null,"alt":null}]', NULL, 2, 'Baking powder is a mixture of baking soda and tartaric acid.

Correct answer: 3. Tartaric Acid', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.189Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (504, 18, NULL, NULL, 'Which among the following is India''s first pico-satellite, weighing less than 1kg, developed by a consortium of seven engineering colleges of India?', NULL, '[{"text":"ANUSAT","image_url":null,"alt":null},{"text":"PRATHAM","image_url":null,"alt":null},{"text":"STUDSAT","image_url":null,"alt":null},{"text":"SWAYAM","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is STUDSAT.
Explanation:

• STUDSAT was India''s first pico-satellite (less than 1 kg)

• It was developed by a consortium of seven engineering colleges in Karnataka

Correct answer: 3. STUDSAT', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.189Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (505, 18, NULL, NULL, 'Profit earned by selling an article for Rs.1060 is 20% more than the loss incurred by selling the article for Rs.950. At what price should the article be sold to earn a 20% profit?', NULL, '[{"text":"Rs 1100","image_url":null,"alt":null},{"text":"Rs. 1150","image_url":null,"alt":null},{"text":"Rs. 1200","image_url":null,"alt":null},{"text":"Rs. 1250","image_url":null,"alt":null}]', NULL, 2, 'Loss when sold at 950:

Loss = x - 950

Profit when sold at 1060:

Profit = 1060 - x

Given:

1060 - x = 1.2 (x - 950)

Solve:

1060 - x = 1.2x - 1140

1060 + 1140 = 1.2x + x

2200=2.2x

x=1000

Now find selling price for 20% profit:

SP = 1000 + 20% = 1000 + 200 = 1200

Final Answer:

3. Rs. 1200', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.190Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (506, 18, NULL, NULL, 'Iceland is an example of _.', NULL, '[{"text":"Seamount","image_url":null,"alt":null},{"text":"Mid-oceanic Ridge","image_url":null,"alt":null},{"text":"Atoll","image_url":null,"alt":null},{"text":"Guyot","image_url":null,"alt":null}]', NULL, 1, 'Iceland lies on the Mid-Atlantic Ridge, which is a mid-oceanic ridge where tectonic plates diverge.

Correct answer: 2. Mid-oceanic Ridge', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.191Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (507, 13, NULL, 61, 'make the defaulter encroaching on the CPR a member of their user group and sharing the benefits of greening the common lands/pastures.

Jhabua district is located in which agro-climatic zone of Madhya Pradesh?', NULL, '[{"text":"Northernmost","image_url":null,"alt":null},{"text":"Southernmost","image_url":null,"alt":null},{"text":"Easternmost","image_url":null,"alt":null},{"text":"Westernmost","image_url":null,"alt":null}]', NULL, 3, 'Jhabua district lies in the extreme western part of Madhya Pradesh, bordering Gujarat. Geographically, this region, along with nearby Alirajpur and Dhar, falls under the Jhabua Hill (or Western) agro-climatic zone, which is characterized by semi-arid conditions and is one of the more marginal agricultural areas of the state.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.194Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (508, 13, NULL, 62, '4. Social-fencing', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'revitalisation of Common Property Resources (CPRs) like village pastures, ponds, and degraded forest areas requires controlled management. Practices used by communities such as the Bhils of Jhabua (

include: Plantation of fodder grass, Plantation of trees (afforestation), and Social-fencing (a system of voluntary restrictions on resource use like grazing). Open grazing is an unregulated practice that leads to over-exploitation and degradation, which is the opposite of revitalisation.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.196Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (509, 13, NULL, 63, '4. Easternmost', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Petlawad is one of the administrative blocks in the Jhabua district of Madhya Pradesh. Geographically, it is situated in the northern section of the district, bordering the Ratlam district. The Jhabua district is an area often discussed in the context of water management and tribal development in Indian Geography textbooks.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.197Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (510, 13, NULL, 64, '4. Ministry of Tribal Affairs', NULL, '[{"text":"Ministry of Tourism","image_url":null,"alt":null},{"text":"Ministries of Rural Development and Agriculture","image_url":null,"alt":null},{"text":"Ministry of Road Transport and Highway","image_url":null,"alt":null},{"text":"Ministry of Tribal Affairs","image_url":null,"alt":null}]', NULL, 1, 'Government-sponsored watershed development projects in India, such as the one in Jhabua (known for its successful implementation, sometimes involving the Haryali project), are centrally financed through key nodal agencies. The two primary central ministries responsible for funding and implementing these types of rural water conservation and land development schemes are the Ministry of Rural Development (through schemes like Neeranchal and the previous watershed components of PMKSY) and the Ministry of Agriculture', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.199Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (511, 13, NULL, 65, '3. Santhal', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 0, 'The Bhils are one of the largest tribal groups in India and have a high concentration in the western districts of Madhya Pradesh, particularly in the Jhabua region, which is often cited in the context of watershed management programs and social forestry efforts.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.200Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (512, 13, NULL, 66, 'Revert to Original

_ is related to the service sector.', NULL, '[{"text":"Dairy farming","image_url":null,"alt":null},{"text":"Weaving","image_url":null,"alt":null},{"text":"Teaching","image_url":null,"alt":null},{"text":"Iron smelting","image_url":null,"alt":null}]', NULL, 2, 'The service sector encompasses all Tertiary, Quaternary, and Quinary activities. Teaching is a specialized service that falls under Tertiary activities (provision of services) or Quaternary activities (knowledge-based services). Dairy farming is Primary, Weaving and Iron Smelting are Secondary activities.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.201Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (513, 13, NULL, 67, '4. Trade', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Exchange refers to the transfer of goods and services between people or places and is the main component of Tertiary activities. It directly involves Trade (buying and selling), Transport (moving goods), and Communication (transmitting information for transactions). Production is a Primary or Secondary activity (like farming or manufacturing) that occurs before exchange.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.202Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (514, 13, NULL, 68, '4. They involve production of tangible goods.', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'Tertiary activities are related to the service sector. They involve the provision of services (intangible) that are consumed, not the production of tangible goods (which is characteristic of the Primary and Secondary sectors). Services depend on specialized skills and knowledge.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.203Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (515, 13, NULL, 69, '4. tertiary', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'Developed countries have mature economies where the majority of economic output and employment shifts away from resource extraction and manufacturing towards services.

• Tertiary Activities are services, which include activities like transportation, communication, commerce, administration, finance, healthcare, and education.

- In developed countries, this sector dominates employment because technological advancements and high income levels create a massive demand for services and allow for the automation or outsourcing of many primary and secondary tasks.

- The high share of workers in the Tertiary (and increasingly, Quaternary/Quinary) sector is a defining characteristic of a developed economy. Conversely, in a developing country, the majority of the workforce is typically still engaged in primary activities (like agriculture).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.203Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (516, 13, NULL, 70, '4. tertiary', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'In the initial stages of a country''s economic development, the majority of the population is engaged in Primary activities, which involve extracting or harvesting natural resources like agriculture, forestry, fishing, and mining. As development progresses, the workforce shifts to the Secondary (manufacturing) and then the Tertiary (service) sectors.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.204Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (517, 13, NULL, NULL, '''Match List-I with List-II', NULL, '[{"text":"(A) (Ⅳ), (B) (Ⅱ), (C) (Ⅲ), (D) - (1)","image_url":null,"alt":null},{"text":"(A) (II), (B) - (III), (C) - (I), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) (I), (B) (II), (C) (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) (II), (B) (III), (C) (IV), (D) - (1)","image_url":null,"alt":null}]', NULL, 3, '1. Sikhs are primarily concentrated in Punjab.

2. Christians in India have significant presence in areas such as Goa (and also Kerala etc.).

3. Buddhists have a notable concentration in northeastern regions such as Sikkim (and also in Maharashtra among others).

4. Jains are found in urban areas and particular states such as Rajasthan.', NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q01-table-1.jpg', 'Table for question 1', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.205Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q01-table-1.jpg","alt":"Table for question 1","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (518, 13, NULL, NULL, 'The ports used for refueling, watering and taking food items are called', NULL, '[{"text":"Naval Ports","image_url":null,"alt":null},{"text":"Entrepot Ports","image_url":null,"alt":null},{"text":"Packet Station","image_url":null,"alt":null},{"text":"Ports of Call","image_url":null,"alt":null}]', NULL, 3, 'Ports of Call are ports where ships stop temporarily for refueling, watering, repairing, and taking in food items while on their journey to other destinations.

They are not final destinations for cargo or passengers - rather, intermediate halts essential for long-distance maritime travel.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.206Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (519, 13, NULL, NULL, 'Identify correct statements about level of urbanisation in India.

(A) The level of urbanisation in India is quite low in comparison to developed countries.

(B) Total urban population has increased three-fold during the twentieth century.

(C) Chandigarh was developed as administrative headquarter after independence.

(D) On the basis of population the Census of India classifies urban centres into six classes.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, '(D)

The Census of India classifies towns into six classes based on population size, but this classification is part of the "urban settlements classification system" and not directly about the level of urbanisation. However, since the question focuses on "level of urbanisation in India", this point is less relevant compared to (A), (B), and (C).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.207Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (520, 13, NULL, NULL, 'WTO headquarter is located at _, Switzerland.', NULL, '[{"text":"Minsk","image_url":null,"alt":null},{"text":"Brussels","image_url":null,"alt":null},{"text":"Vienna","image_url":null,"alt":null},{"text":"Geneva","image_url":null,"alt":null}]', NULL, 3, '• The World Trade Organization (WTO) was established on 1 January 1995, replacing the General Agreement on Tariffs and Trade (GATT).

• Its headquarters is located in Geneva, Switzerland.

- The WTO is responsible for setting and enforcing global trade rules, resolving trade disputes, and promoting free and fair international trade among member countries.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.207Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (521, 13, NULL, NULL, 'Name the country that officially proclaims the Gross National Happiness (GNH) as the measure of the country''s progress.', NULL, '[{"text":"Singapore","image_url":null,"alt":null},{"text":"Nepal","image_url":null,"alt":null},{"text":"Japan","image_url":null,"alt":null},{"text":"Bhutan","image_url":null,"alt":null}]', NULL, 3, '• Bhutan is the only country in the world that officially proclaims Gross National Happiness (GNH) as the measure of the country''s progress.

• Instead of focusing only on Gross Domestic Product (GDP), Bhutan''s development philosophy emphasizes spiritual, cultural, environmental, and economic well-being.

• The four pillars of GNH are:

1. Sustainable and equitable socio-economic development

2. Conservation of environment

3. Preservation and promotion of culture

4. Good governance', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.208Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (522, 13, NULL, NULL, 'In the Northern States of India, which of the following crop is grown in the Rabi Season?', NULL, '[{"text":"Rice","image_url":null,"alt":null},{"text":"Cotton","image_url":null,"alt":null},{"text":"Wheat","image_url":null,"alt":null},{"text":"Bajra","image_url":null,"alt":null}]', NULL, 2, 'In northern states of India (like Punjab, Haryana, Uttar Pradesh, Bihar, etc.), wheat is the main Rabi crop.

• Rabi crops are sown in winter (October-December) and harvested in spring (March-April).

• They require cool climate for growth and bright sunshine for ripening', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.209Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (523, 13, NULL, NULL, 'Major characteristics of hunting and gathering are:

(A) It often involves primitive societies, who depend on plants and animals to satisfy their needs for food, shelter and clothing.

(B) This type of activity requires a small amount of capital investment.

(C) No surplus is produced.

(D) This is a specialized activity in which only one type of animal is reared.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, 'D.

This describes Commercial Livestock Rearing. Hunting and gathering involves killing wild animals and does not include animal rearing (domestication).

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.210Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (524, 13, NULL, NULL, 'Match LIST-I with LIST-II', NULL, '[{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{IV}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{III}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q08-table-1.jpg', 'Table for question 8', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.212Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q08-table-1.jpg","alt":"Table for question 8","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (525, 13, NULL, NULL, 'Arrange the following seaports located on the west coast of India from north to south.

(A) Mumbai

(B) New Mangalore

(C) Marmagao

(D) Kochchi', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 1, '• Mumbai Port - Maharashtra

• Mormugao Port - Goa

• New Mangalore Port - Karnataka

• Kochi Port - Kerala', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.213Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (526, 13, NULL, NULL, 'Which of the following ports are natural harbours?

(A) Kochchi Port

(B) Chennai Port

(C) Marmagao Port

(D) Mumbai Port', NULL, '[{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, '• Mumbai Port - A natural deep-water harbour located on the Konkan Coast (Maharashtra).

• Mormugao Port - Situated in Goa, it is a natural harbour that has been developed with modern facilities.

• Kochi (Cochin) Port - Located in Kerala, it is a natural harbour formed by the sea and backwaters.

Chennai Port - It is an artificial harbour, built by constructing breakwaters to protect ships from sea waves.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.214Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (527, 13, NULL, NULL, 'In the following identify the statement which is NOT correct about Indian crops.', NULL, '[{"text":"Rice is a crop of tropical humid areas.","image_url":null,"alt":null},{"text":"Wheat is primarily a crop of temperate zone.","image_url":null,"alt":null},{"text":"Maize is a food as well as fodder crop.","image_url":null,"alt":null},{"text":"Rapeseed and mustard comprise several pulses.","image_url":null,"alt":null}]', NULL, 3, 'Rapeseed and mustard are oilseeds (used for oil and condiments), not pulses. Pulses are leguminous crops like gram (chana), moong, or arhar.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.215Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (528, 13, NULL, NULL, 'Some coffee Fazendas (large plantations) in Brazil are still managed by:', NULL, '[{"text":"Europeans","image_url":null,"alt":null},{"text":"South Africans","image_url":null,"alt":null},{"text":"Japanese","image_url":null,"alt":null},{"text":"Red Indians","image_url":null,"alt":null}]', NULL, 0, 'The question relates to the historical context of Plantation Agriculture.

• Fazendas are the large coffee estates/plantations in Brazil.

• Plantation agriculture was introduced in colonies and tropical regions by Europeans.

- The British, French, Dutch, Spanish, and Americans all established plantations across the world (tea in India, rubber in Malaysia, cocoa in West Africa, etc.).

Specifically, historical accounts and NCERT-level information note that some coffee Fazendas in Brazil are still managed by Europeans (referring to European descendants or long-established European firms).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.216Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (529, 13, NULL, NULL, 'Choose the correct answer from the options given below:', NULL, '[{"text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})","image_url":null,"alt":null},{"text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I}\\mathbf{I I}),(\\mathbf{C})-(\\mathbf{I}\\mathbf{I}),(\\mathbf{D})-(\\mathbf{I}\\mathbf{V})","image_url":null,"alt":null},{"text":"(\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{III}),(\\mathbf{C})-(\\mathbf{IV}),(\\mathbf{D})-(\\mathbf{I})","image_url":null,"alt":null},{"text":"\\ (\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{IV}),(\\mathbf{C})-(\\mathbf{I}),(\\mathbf{D})-(\\mathbf{III})","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q13-table-1.jpg', 'Table for question 13', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.217Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q13-table-1.jpg","alt":"Table for question 13","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (530, 13, NULL, NULL, 'The characteristics of the National Highways Authority of India are:

(A) It is an autonomous body under the Ministry of Surface Transport.

(B) It has the responsibility of development, maintenance and operation of National Highways.

(C) It constructs and maintains the border roads in the country.

(D) It was operationalised in 1995.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, '(A) It is an autonomous body under the Ministry of Surface Transport (now Ministry of Road Transport and Highways). (Correct)

• (B) It has the responsibility of development, maintenance and operation of National Highways. (Correct)

(C) It constructs and maintains the border roads in the country. (Incorrect - This is the primary function of the Border Roads Organisation (BRO).)

• (D) It was operationalised in 1995. (Correct)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.217Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (531, 13, NULL, NULL, 'Identify the characteristics of minerals.

(A) These are unevenly distributed over space.

(B) There is an inverse relationship in the quality and quantity of minerals.

(C) All minerals are exhaustible over time.

(D) Non-metallic minerals are always organic in nature.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, '• (A) These are unevenly distributed over space. (Correct)

(B) There is an inverse relationship in the quality and quantity of minerals (high-quality minerals are low in quantity, and vice versa). (Correct)

• (C) All minerals are exhaustible over time. (Correct - They are non-renewable resources.)

(D) Non-metallic minerals are always organic in nature. (Incorrect - Non-metallic minerals like mica, limestone, and gypsum are inorganic; only fossil fuels like coal and petroleum are organic non-metallic minerals.)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.217Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (532, 13, NULL, NULL, 'Match LIST-I with LIST-II', NULL, '[{"text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})","image_url":null,"alt":null},{"text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I}\\mathbf{I I}),(\\mathbf{C})-(\\mathbf{I}\\mathbf{I}),(\\mathbf{D})-(\\mathbf{I}\\mathbf{V})","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null}]', NULL, 2, 'This matches the nuclear power plants with their correct states: Tarapur in Maharashtra, Kalpakkam in Tamil Nadu, Kaiga in Karnataka, and Kakrapara in Gujarat.', NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q16-table-1.jpg', 'Table for question 16', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.218Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q16-table-1.jpg","alt":"Table for question 16","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (533, 13, NULL, NULL, 'The Limits to Growth was published in _', NULL, '[{"text":"1972","image_url":null,"alt":null},{"text":"1968","image_url":null,"alt":null},{"text":"1987","image_url":null,"alt":null},{"text":"1970","image_url":null,"alt":null}]', NULL, 0, 'The Limits to Growth is a seminal book published in 1972 by the Club of Rome. It used computer modeling to study the long-term consequences of rapidly growing world population, limited resource supply, and industrial growth, advocating for a sustainable approach.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (534, 13, NULL, NULL, 'Match LIST-I with LIST-II', NULL, '[{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) - (\\mathrm{II}) $, $ (\\mathrm{C}) - (\\mathrm{III}) $, $ (\\mathrm{D}) - (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) - (\\mathrm{II}) $, $ (\\mathrm{C}) - (\\mathrm{IV}) $, $ (\\mathrm{D}) - (\\mathrm{III}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 3, 'This matches the Railway Zones with their correct Headquarters: North Eastern ( $ \rightarrow $ Gorakhpur), South Central ( $ \rightarrow $ Secunderabad), East Central ( $ \rightarrow $ Hajipur), and North Western ( $ \rightarrow $ Jaipur).', NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q18-table-1.jpg', 'Table for question 18', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.218Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q18-table-1.jpg","alt":"Table for question 18","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (535, 13, NULL, NULL, 'Geographers of which country describe the ''state/country'' as a ''living organism''?', NULL, '[{"text":"France","image_url":null,"alt":null},{"text":"Germany","image_url":null,"alt":null},{"text":"Great Britain","image_url":null,"alt":null},{"text":"India","image_url":null,"alt":null}]', NULL, 1, 'The concept of the ''state/country'' as a living organism (organic state theory) is attributed to German geographers, most notably Friedrich Ratzel. This idea, which views the state as an organism that must grow and expand to survive, is a foundational concept in the field of Political Geography and is related to the idea of Lebensraum.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (536, 13, NULL, NULL, 'Many areas of Meghalaya, Uttarakhand, Himachal Pradesh and Kerala have _ type of settlements.', NULL, '[{"text":"agglomerated","image_url":null,"alt":null},{"text":"hamleted","image_url":null,"alt":null},{"text":"dispersed or isolated","image_url":null,"alt":null},{"text":"fragmented","image_url":null,"alt":null}]', NULL, 2, 'Dispersed or isolated settlements are commonly found in areas of hilly tracts, plateaus, and thick forests, where the land is fragmented, and topography restricts close clustering. This pattern is typical of the mountainous and geographically diverse regions mentioned: Meghalaya (hills/plateau), Uttarakhand (Himalayan region), Himachal Pradesh (Himalayan region), and the hilly parts of Kerala (Western Ghats).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.219Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (537, 13, NULL, NULL, 'Which of the followings are main basis of international trade?

(A) Differences in national resources.

(B) Direction of trade.

(C) Differences in stages of economic development.

(D) Extent of foreign investment.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only.","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'The main bases of international trade are factors that create differences in production costs and market conditions across countries. (A) Differences in national resources, (C) Differences in stages of economic development, and (D) Extent of foreign investment are all fundamental bases for trade. (B) Direction of trade is a result of international trade, not a basis for it', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.219Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (538, 13, NULL, NULL, 'Arrange the following means of communication from ancient to modern in order of their development:

(A) Landline phone

(B) Communication through internet

(C) Letter

(D) Television', NULL, '[{"text":"(B), (C), (A), (D)","image_url":null,"alt":null},{"text":"(C), (A), (D), (B)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 1, 'The means of communication developed in this historical order: 1. Letter (C): Represents the oldest, physical, and manual form of communication. 2. Landline phone (A): Represents the invention of electronic voice communication (late 19th century). 3. Television (D): Represents mass electronic communication, primarily broadcasting (mid-20th century). 4. Communication through internet (B): Represents the most modern, digitized, and global form of communication (late 20th century/21st century).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (539, 13, NULL, NULL, 'Which of the following is NOT the characteristic of foot loose industries?', NULL, '[{"text":"They are not dependent on any specific raw material.","image_url":null,"alt":null},{"text":"They produce in small quantities and also employ a small labour force.","image_url":null,"alt":null},{"text":"Finished products may be for consumption in the same household.","image_url":null,"alt":null},{"text":"These are generally not polluting industries.","image_url":null,"alt":null}]', NULL, 2, 'Footloose industries are modern, usually light manufacturing industries that can be located almost anywhere, as their production costs are largely independent of their location. Characteristics of footloose industries: They are not dependent on any specific raw material (1), They produce in small quantities and also employ a small labour force (2), and They are generally not polluting industries (4). The statement (3) describes Household Industries or Cottage Industries, not footloose industries.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (540, 13, NULL, NULL, 'Which of the following is the Indian communication satellite?', NULL, '[{"text":"Cartosat","image_url":null,"alt":null},{"text":"Landsat","image_url":null,"alt":null},{"text":"SPOT","image_url":null,"alt":null},{"text":"INSAT","image_url":null,"alt":null}]', NULL, 3, 'INSAT (Indian National Satellite System) is a series of multi-purpose geostationary satellites launched by ISRO to fulfill the country''s needs for telecommunications, broadcasting, meteorology, and search and rescue operations. Cartosat is an Indian remote sensing satellite, while Landsat and SPOT are remote sensing satellites of the USA and France, respectively.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (541, 13, NULL, NULL, '_ has been constructed to relieve the pressure at Chennai port.', NULL, '[{"text":"Paradwip Port","image_url":null,"alt":null},{"text":"Jawaharlal Nehru Port","image_url":null,"alt":null},{"text":"Ennore Port","image_url":null,"alt":null},{"text":"Kandla Port","image_url":null,"alt":null}]', NULL, 2, 'Ennore Port (now officially Kamarajar Port) was constructed north of Chennai to function as a satellite port. Its primary purpose was to handle bulk cargo like thermal coal and iron ore, thereby relieving congestion and pressure at the older, major Chennai Port.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (542, 13, NULL, NULL, 'Arrange the following states of India in descending order as per their population density in 2011.

(A) Bihar

(B) Uttar Pradesh

(C) West Bengal

(D) Kerala', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (D), (B)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 1, 'Based on the 2011 Census data, the population densities of the listed states are (approximately): (A) Bihar (1106 persons/sq km), (C) West Bengal (1028 persons/sq km), (D) Kerala (860 persons/sq km), and (B) Uttar Pradesh (829 persons/sq km). The descending order is (A), (C), (D), (B).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (543, 13, NULL, NULL, 'Which of the following statements is NOT correct about Atal Tunnel?', NULL, '[{"text":"It is built in the Shivalik Ranges of the Himalayas.","image_url":null,"alt":null},{"text":"It was built by the Border Road Organisation.","image_url":null,"alt":null},{"text":"It connects Manali to Lahaul-Spiti Valley.","image_url":null,"alt":null},{"text":"It is the World''s Longest Highway Tunnel.","image_url":null,"alt":null}]', NULL, 0, 'Atal Tunnel is actually built under the Pir Panjal Range of the Himalayas, not the Shivalik Ranges. The other statements are correct: It was built by the Border Road Organisation (BRO) (2); it connects Manali to the Lahau-Spiti Valley (3); and as of its opening, it was considered the World''s Longest Highway Tunnel (above 10,000 feet) (4)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (544, 13, NULL, NULL, 'Which of the following is NOT the main cause of noise pollution?', NULL, '[{"text":"Mechanised construction work","image_url":null,"alt":null},{"text":"Automobiles","image_url":null,"alt":null},{"text":"Loudspeakers used in various festivals","image_url":null,"alt":null},{"text":"Combustion of fossil fuels","image_url":null,"alt":null}]', NULL, 3, 'The combustion of fossil fuels is primarily associated with air pollution (releasing gases like CO2, SO2, etc.). The other options-Mechanised construction work (1), Automobiles (2), and Loudspeakers (3)-are all direct and major sources of noise pollution.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (545, 13, NULL, NULL, 'Which of the following statements is NOT correct about Haryali?', NULL, '[{"text":"It is a Watershed Development Project.","image_url":null,"alt":null},{"text":"Project is executed by Gram Panchayats with People''s Participation.","image_url":null,"alt":null},{"text":"It aims to enable rural population to conserve water.","image_url":null,"alt":null},{"text":"The project focuses only on the well-being of females.","image_url":null,"alt":null}]', NULL, 3, 'The Haryali project is a Watershed Development Project (1). It is implemented by the Gram Panchayats with people''s participation (2) and aims to enable the rural population to conserve water (3) for drinking,

irrigation, etc. However, while the project does involve and benefit women''s self-help groups for resource management, it does not focus only on the well-being of females.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (546, 13, NULL, NULL, 'Arrange the following iron-ore mines from north to south

(A) Bailadila

(B) Mayurbhanj

(C) Kudremukh

(D) Ratnagiri', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, 'The geographical locations of the mines are: (B) Mayurbhanj (Odisha) is the northernmost; (A) Bailadila (Chhattisgarh) is next, located further south/west; (D) Ratnagiri (Maharashtra) is on the western coast, south of Bailadila; and (C) Kudremukh (Karnataka) is the southernmost, located in the Western Ghats. The', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (547, 13, NULL, NULL, '_ includes 168 km of west coast canal along with Champakara canal.', NULL, '[{"text":"NW1","image_url":null,"alt":null},{"text":"NW 2","image_url":null,"alt":null},{"text":"NW 4","image_url":null,"alt":null},{"text":"NW3","image_url":null,"alt":null}]', NULL, 3, 'NW 3 (National Waterway 3), also known as the West Coast Canal, runs between Kottapuram and Kollam in Kerala. It includes the West Coast Canal (168 km), the Champakara Canal, and the Udyogamandal Canal, totaling about 205 km.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (548, 13, NULL, NULL, 'Arrange the following according to stages of demographic transition.

(A) High fluctuating

(B) Early expanding

(C) Late expanding

(D) Low fluctuating', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 0, 'demographic transition theory describes population change in four stages: (A) High Fluctuating (Stage I: High birth rate and high death rate); (B) Early Expanding (Stage II: High birth rate and rapidly falling death rate); (C) Late Expanding (Stage III: Falling birth rate and low death rate); and (D) Low Fluctuating (Stage IV: Low birth rate and low death rate). The given list is already in the correct chronological order of the stages.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (549, 13, NULL, NULL, 'The movement from the plains to the mountains in summer and back in winter in search of pastures is the characteristics of', NULL, '[{"text":"Commercial Livestock Rearing","image_url":null,"alt":null},{"text":"Nomadic Herding","image_url":null,"alt":null},{"text":"Ranching","image_url":null,"alt":null},{"text":"Shifting Cultivation","image_url":null,"alt":null}]', NULL, 1, 'Nomadic Herding involves herders moving with their animals from place to place in search of pastures and water. The particular pattern of seasonal movement between high mountain pastures in summer and lower valleys/plains in winter is called transhumance, and is a key feature of nomadic herding practiced by groups like the Gujjars, Bakarwals, Bhotiyas, and Gaddis in the Himalayas.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (550, 13, NULL, NULL, 'Identify the Industry which is based on forest raw material.', NULL, '[{"text":"Paper industry","image_url":null,"alt":null},{"text":"Leather industry","image_url":null,"alt":null},{"text":"Woollen textile industry","image_url":null,"alt":null},{"text":"Jute industry","image_url":null,"alt":null}]', NULL, 0, 'The Paper industry uses wood pulp derived from forest raw material (wood). The other industries use different raw materials: Leather industry uses hides and skin of animals; Woollen textile industry uses wool from sheep; and Jute industry uses plant fibers from the jute crop.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.224Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (551, 13, NULL, NULL, 'Which one of the following is a correct statement?', NULL, '[{"text":"Natural growth of population depends on births, deaths and migration.","image_url":null,"alt":null},{"text":"Crude death rates can not be more than crude birth rates.","image_url":null,"alt":null},{"text":"Growth rate of population is the change of population expressed in percentage.","image_url":null,"alt":null},{"text":"Migration is not a component of population change.","image_url":null,"alt":null}]', NULL, 2, 'Solution:

Statement 3 is correct. The growth rate is used to express the change in population (growth) over a period of time, and is calculated as a percentage. Statement 1 is incorrect because Natural Growth only considers births and deaths, and excludes migration. Statement 2 is incorrect as crude death rates can certainly be higher than crude birth rates (e.g., during epidemics or in aging populations). Statement 4 is incorrect because Migration (immigration and emigration) is a major component of population change, along with birth and death rates.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (552, 13, NULL, NULL, 'The collection, production and dissemination of information are the characteristics of activities.', NULL, '[{"text":"Tertiary","image_url":null,"alt":null},{"text":"Quaternary","image_url":null,"alt":null},{"text":"Secondary","image_url":null,"alt":null},{"text":"Primary","image_url":null,"alt":null}]', NULL, 1, 'Quaternary activities refer to the sector of the economy that involves highly intellectual and knowledge-based tasks. These tasks include the collection, production, and dissemination of information, as well as research and development. This sector is distinct from the tertiary sector, which mainly deals with services.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.227Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (553, 13, NULL, NULL, '''Aus'', ''Aman'' and ''Boro'' are related to which of the following?', NULL, '[{"text":"Varieties of Coffee","image_url":null,"alt":null},{"text":"Zaid crops","image_url":null,"alt":null},{"text":"Variety of rice grown in Kerala","image_url":null,"alt":null},{"text":"Three crops of rice grown in West Bengal","image_url":null,"alt":null}]', NULL, 3, 'Aus, Aman, and Boro are three different rice crops grown in a year in the states of West Bengal and Assam. This is possible due to the favorable climate and heavy rainfall in the region. Aman is the autumn crop (harvested in November), Aus is the pre-kharif/summer crop (harvested in September/October), and Boro is the winter/spring crop (harvested in March/April).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.228Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (554, 13, NULL, NULL, 'Suez Canal act as a linkage between _ sea and _ sea.', NULL, '[{"text":"Mediterranean, Atlantic","image_url":null,"alt":null},{"text":"Red, Arabian","image_url":null,"alt":null},{"text":"Mediterranean, Red","image_url":null,"alt":null},{"text":"Dead, Black","image_url":null,"alt":null}]', NULL, 2, 'The Suez Canal, constructed in 1869, is an artificial sea-level waterway in Egypt connecting the Mediterranean Sea at Port Said to the Red Sea at Port Suez. This canal provides the shortest and most direct maritime route between Europe and the lands bordering the Indian and western Pacific Oceans.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.229Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (555, 13, NULL, NULL, 'Arrange the following countries of the world in descending order on the basis of their population size.

(A) Brazil

(B) Indonesia

(C) Japan

(D) U.S.A.', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(D), (B), (A), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, 'The U.S.A. has the largest population among the listed countries, followed by Indonesia. Brazil has a larger population than Japan. Therefore, the descending order is U.S.A. (D), Indonesia (B), Brazil (A), Japan (C).

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.232Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (556, 13, NULL, NULL, 'Match LIST-I with LIST-II', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null}]', NULL, 3, '• Varanasi is a well-known cultural town, famous for its religious and cultural heritage.

• New Delhi is the administrative capital of India, hence an administrative town.

• Saharanpur is known for its trade and commercial activities.

• Bokaro is an industrial town, known for its steel industry.', NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-16-shift-1/q40-table-1.jpg', 'Table for question 40', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.233Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-16-shift-1/q40-table-1.jpg","alt":"Table for question 40","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (557, 13, NULL, 71, 'technopolies. The Silicon Valley near San Francisco and Silicon Forest near Seattle are examples of technologies.

