INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (568, 13, NULL, NULL, 'These activities involve the collection, production and dissemination of information or even the production of information. Identify the activities:', NULL, '[{"text":"Quinary activities","image_url":null,"alt":null},{"text":"Secondary Activities","image_url":null,"alt":null},{"text":"Quaternary activities","image_url":null,"alt":null},{"text":"Tertiary activities","image_url":null,"alt":null}]', NULL, 2, '• Quaternary activities involve the collection, production, and dissemination of information.

• They are centered around research and development (R&D).

- These can be seen as an advanced form of services.

• They require specialised knowledge and technical skills.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.246Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (569, 13, NULL, NULL, 'Identify the challenges in society with regard to adolescent populations

(A) Illiteracy - particularly female illiteracy

(B) Low intake of nutrients

(C) Low maternal mortality rates

(D) Drug abuse and alcoholism', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, '1. Includes various issues like:

1. Lower age at marriage.

2. Illiteracy, with a particular emphasis on female illiteracy.

3. High rates of school dropouts.

2. High rate of maternal mortality among adolescent mothers.

1. Drug abuse and alcoholism.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.246Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
