INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (580, 13, NULL, NULL, '_ is a watershed development project sponsored by the Central Government which aims at enabling the rural population to conserve water for drinking, irrigation, fisheries and afforestation.', NULL, '[{"text":"Neeru-Meeru","image_url":null,"alt":null},{"text":"Haryali","image_url":null,"alt":null},{"text":"Arvary Pani Sansad","image_url":null,"alt":null},{"text":"Atal Bhujal Yojana","image_url":null,"alt":null}]', NULL, 1, 'Haryali is a watershed development project sponsored by the Central Government which aims at enabling the rural population to conserve water for drinking, irrigation, fisheries and afforestation.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (581, 13, NULL, NULL, 'In a country 350,000 people reside over an area of thousand square kilometer. The density of population of the country is _.', NULL, '[{"text":"3500 person/sq km","image_url":null,"alt":null},{"text":"35 person/sq km","image_url":null,"alt":null},{"text":"350 person/sq km","image_url":null,"alt":null},{"text":"1500 person/sq mile","image_url":null,"alt":null}]', NULL, 2, 'Population Density of Population = Population/Area', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (582, 13, NULL, NULL, 'The characteristic features of Commercial Livestock Rearing are:

(A) Movement in search of pastures is undertaken.

(B) It is practiced on permanent ranches.

(C) Only one type of animal is reared.

(D) Rearing of animals is organised on a scientific basis.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'Commercial livestock ranching is essentially associated with western cultures and is practised on permanent ranches. This is a specialised activity in which only one type of animal is reared. Important animals include sheep, cattle, goats and horses. Rearing of animals in ranching is organised on a scientific basis.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (583, 13, NULL, NULL, 'Arrange the following countries in ascending order according to their population.

(A) India

(B) Pakistan

(C) USA

(D) Mexico', NULL, '[{"text":"(D), (B), (C), (A)","image_url":null,"alt":null},{"text":"(D), (C), (B), (A)","image_url":null,"alt":null},{"text":"(C), (D), (A), (B)","image_url":null,"alt":null},{"text":"(B), (A), (C), (D)","image_url":null,"alt":null}]', NULL, 0, 'Given in Figure 2.1

So the ascending order is: (D), (B), (C), (A)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (584, 13, NULL, NULL, 'The over-use of groundwater resources in some states of India has led to which of the following:

(A) the integrated development of rain-fed areas

(B) decline in groundwater table

(C) increased fluoride concentration

(D) an increase in the concentration of arsenic.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, '(A) is incorrect because because integrated development of rain-fed areas is a solution, not a consequence.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (585, 13, NULL, NULL, 'Match List-I with List-II', NULL, '[{"text":"(A) - (III), (B) - (II), (C) - (IV), (D) - (I)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null}]', NULL, 0, 'Given in Table 3.1

• Income Approach → Oldest approach (III)

• Welfare Approach → People as passive recipients (II)

• Basic Needs Approach → Proposed by ILO (IV)

• Capability Approach → Builds human abilities (I)', NULL, NULL, 2025, '/local-papers/assets/geography-2025-05-20-shift-1/q21-table-1.jpg', 'Table for question 21', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.255Z', NULL, NULL, '[{"url":"/local-papers/assets/geography-2025-05-20-shift-1/q21-table-1.jpg","alt":"Table for question 21","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (586, 13, NULL, NULL, 'Calculate the actual change in the population of a place reporting 700 births, 200 deaths and 300 people immigration and 100 people emigration in a particular year.', NULL, '[{"text":"700","image_url":null,"alt":null},{"text":"400","image_url":null,"alt":null},{"text":"1000","image_url":null,"alt":null},{"text":"200","image_url":null,"alt":null}]', NULL, 0, 'Actual Growth = (Births - Deaths) + (In Migration - Out Migration)

Change in population: 700-200+300-100=700 ( immigration is people coming in and emigration is people moving out )', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.255Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (587, 13, NULL, NULL, 'Which of the following is NOT the characteristic of market gardening and horticulture?', NULL, '[{"text":"It specializes in the cultivation of high-value crops.","image_url":null,"alt":null},{"text":"It is both labour and capital intensive","image_url":null,"alt":null},{"text":"The farmers pool in all their resources like land, livestock and labour.","image_url":null,"alt":null},{"text":"High value products are solely for the urban markets.","image_url":null,"alt":null}]', NULL, 2, '(3) is wrong as the given characteristic is of Cooperative Farming not market gardening and horticulture', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.255Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
