INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (589, 13, NULL, NULL, 'Identify the geographer who defined Human Geography as "The study of the changing relationship between the unresting man and the unstable earth."', NULL, '[{"text":"Ratzel","image_url":null,"alt":null},{"text":"Semple","image_url":null,"alt":null},{"text":"Blache","image_url":null,"alt":null},{"text":"Karl Ritter","image_url":null,"alt":null}]', NULL, 1, 'It was defined by Ellen C. Semple and Dynamism in the relationship is the keyword in Semple''s definition.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.256Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (590, 13, NULL, NULL, 'Which of the following regions has the least network of air routes?', NULL, '[{"text":"South East Asia","image_url":null,"alt":null},{"text":"Western Europe","image_url":null,"alt":null},{"text":"Eastern U.S.A.","image_url":null,"alt":null},{"text":"10-35 degree latitudes in the southern hemisphere","image_url":null,"alt":null}]', NULL, 3, 'There are limited air services between 10-35 latitudes in the Southern hemisphere due to sparser population, limited landmass and economic development.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.257Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (591, 13, NULL, NULL, 'Which of the following is NOT a characteristic of air transport?', NULL, '[{"text":"It is the fastest means of transportation","image_url":null,"alt":null},{"text":"It is preferred by passengers for long-distance travel.","image_url":null,"alt":null},{"text":"It is used extensively to transport liquids and gases.","image_url":null,"alt":null},{"text":"It is often the only means to reach inaccessible areas.","image_url":null,"alt":null}]', NULL, 2, '(3) is the characteristic of Pipelines and not air transport.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.257Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
