INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (593, 13, NULL, NULL, 'The first population Census in India was conducted in the year _.', NULL, '[{"text":"1872","image_url":null,"alt":null},{"text":"1891","image_url":null,"alt":null},{"text":"1875","image_url":null,"alt":null},{"text":"1873","image_url":null,"alt":null}]', NULL, 0, 'The first population Census in India was conducted in 1872 but its first complete Census was conducted only in 1881', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.258Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
