(C) स्वनिदंश

(D) संबोधन
नीचे दिए गए विकल्पों में से सही उत्तर चुने:', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.289Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (649, 2, NULL, NULL, 'निम्नलिखित में से कार्यालयी पत्र व्यवहार का उदाहरण नहीं है -', NULL, '[{"text":"परिपूर्ण","image_url":null,"alt":null},{"text":"प्रेस विशिष्टि","image_url":null,"alt":null},{"text":"अधिसूचना","image_url":null,"alt":null},{"text":"परिचय पत्र Solution Q.1. Answer: (3) शिधा","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.290Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (650, 11, NULL, 84, '4. Bengal Hind University', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'Gandhiji referred to the opening of Banaras Hindu University (BHU) as "a most gorgeous show" when he attended the ceremony in 1916.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.291Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (651, 11, NULL, 85, '4. Gandhiji was against the spirit of self-governance.', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'Gandhiji critiques the Indian elite, including doctors, lawyers, and landlords, for their disregard of the working class and peasants. He argues that Indian nationalism, driven by the elite, excluded the majority of the population. Gandhi emphasises that true self-governance and national salvation can only be achieved through the involvement of the common people, particularly the peasants, highlighting a shift from elite-', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.292Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (652, 11, NULL, 86, '4. Right to be a good farmer', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'Gandhiji emphasizes that the salvation for India will come through the farmer, and that the peasants'' labor and the results of their work are being taken away by the privileged classes. This aligns with the idea that what was being taken away from the farmers were the economic benefit of their labor.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.292Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (653, 11, NULL, 87, '4. Servants of the East India Company', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Gandhiji highlights the absence of the peasants and workers at the opening of the Banaras Hindu University (BHU), while the rich and elite groups were present.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.293Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (654, 11, NULL, 88, '4. December 1916', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'Gandhiji''s speech in Benaras was delivered in February 1916. He criticised the Indian elite for their lack of concern for the poor, highlighting the absence of peasants at the Banaras Hindu University (BHU) opening. He stressed that India''s salvation would come from empowering farmers, not the rich landlords or professionals like lawyers and doctors.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.294Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (655, 11, NULL, 89, '4. Masses were in minority', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'The speaker explains that the oppression and depression faced by the tribal people are due to economic hardship, which leads to their exploitation and forms of economic slavery. The lack of legal protection and exploitation by merchants and moneylenders are also key factors in their suffering.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.296Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (656, 11, NULL, 90, '4. It is for the religious minorities only', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 2, 'It is evident that the speaker, N.G. Ranga, feels that the resolution is insufficient because it does not provide adequate protection against exploitation by non-state actors like moneylenders and landlords in rural areas. Instead, it seems to focus more on religious minorities or specific groups in urban settings, which doesn''t address the broader issue faced by marginalised tribal populations.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.298Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (657, 11, NULL, 91, '4. Constitutional protection of the welfare-state', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'Constitutional protection of the welfare state would provide a legal framework for safeguarding the rights of tribal people, ensuring they receive protection from exploitation, displacement, and other forms of injustice.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.299Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (658, 11, NULL, 92, '4. The tribals of free India', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'N.G. Ranga focused on the issues of marginalised and tribal communities in India, highlighting how their rights and interests often went overlooked in the larger socio-political context. The tribals, especially in post-

independence India, were among the most disadvantaged groups in terms of socio-economic development and political representation.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.300Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (659, 11, NULL, NULL, 'Arrange the following events of 1857 in a chronological order

(A) Shah Mal killed in battle

(B) Sepoy mutiny in Aligarh

(C) Nawab Wajid Ali Shah deposed

(D) The British suffered defeat in the battle of Chinhat', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (B), (D), (C)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 3, 'The correct chronological order of the 1857 events is:

1. Nawab Wajid Ali Shah deposed (C) - 11 February 1856, an event that contributed to the rising unrest.

2. Sepoy mutiny in Aligarh (B) - May 1857, part of the early phase of the revolt.

3. British defeat at the Battle of Chinhat (D) - June 30, 1857.

4. Shah Mal killed in battle (A) - 1st July 1857.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.300Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (660, 11, NULL, NULL, 'Choose the correct statements about the Prayaga Prashasti or the Allahabad Pillar Inscription:

(A) It is composed in Sanskrit.

(B) It was composed by Harishna, the court poet of Samudragupta

(C) It describes the King as Purusha.

(D) It describes Chandragupta as the greatest King.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, '(A) It is composed in Sanskrit - The Prayaga Prashasti (Allahabad Pillar Inscription) was written in classical Sanskrit.

(B) It was composed by Harishena, the court poet of Samudragupta - Harishena, a minister and court poet. authored this inscription.

(C) It describes the King as Purusha - The inscription glorifies Samudragupta using terms like Purusha (a supreme person or man).

• (D) It describes Chandragupta as the greatest King - It refers to Samudragupta as arguably the most powerful of the Gupta rulers(c. fourth century CE), not Chandragupta.

So, statements A, B, and C are correct.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.301Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (661, 11, NULL, NULL, 'Which of the following was not the reason for the rise of Magadha as the most powerful Mahajanapada?', NULL, '[{"text":"A region with productive agriculture.","image_url":null,"alt":null},{"text":"Accessibility to iron mines provided resources for tools and weapons.","image_url":null,"alt":null},{"text":"Elephants for army were found in the forests of the region.","image_url":null,"alt":null},{"text":"Policies of Hoysala rulers.","image_url":null,"alt":null}]', NULL, 3, 'The Hoysala dynasty ruled in South India (Karnataka) centuries later (10th-14th century CE), making their policies irrelevant to the rise of Magadha (6th-4th century BCE). The other three options (productive agriculture, access to iron, and availability of elephants) were key geographical and resource advantages that fueled Magadha''s success.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.301Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (662, 11, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, '/local-papers/assets/history-2025-05-16-shift-1/q04-table-1.jpg', 'Table for question 4', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.301Z', NULL, NULL, '[{"url":"/local-papers/assets/history-2025-05-16-shift-1/q04-table-1.jpg","alt":"Table for question 4","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (663, 11, NULL, NULL, 'In the Mughal period, who were identified as pahi-kashta peasants?', NULL, '[{"text":"Peasants who were residents of the village in which they held their lands.","image_url":null,"alt":null},{"text":"Peasants having large amount of land and rural magnates.","image_url":null,"alt":null},{"text":"Peasants who tilt their own land out of choice.","image_url":null,"alt":null},{"text":"Non-resident cultivators who belonged to some other village, but cultivated lands elsewhere on a contractual basis.","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.302Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (664, 11, NULL, NULL, 'When was Mahatma Gandhi approached by a peasant from Champaran in Bihar who told him about the harsh treatment of peasants by British indigo planters?', NULL, '[{"text":"January 1915","image_url":null,"alt":null},{"text":"February 1916","image_url":null,"alt":null},{"text":"December 1916","image_url":null,"alt":null},{"text":"March 1917","image_url":null,"alt":null}]', NULL, 2, 'During the Lucknow Session of the Indian National Congress in December 1916, Mahatma Gandhi was approached by a peasant from Champaran, Rajkumar Shukla, who informed him about the severe hardships faced by indigo farmers under oppressive plantation systems. Responding to his plea, Gandhi visited Champaran in March 1917, launching the Champaran Satyagraha, which became the first major Satyagraha movement in India and a landmark in the country''s freedom struggle.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.302Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (665, 11, NULL, NULL, 'Arrange the following events in a chronological order:

(A) Accession of Chandragupta Maurya

(B) Urbanization in the Ganga valley

(C) Satavahanas in the Deccan

(D) Rise of the Chalukyas in Karnataka', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (C), (D)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.303Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (666, 11, NULL, NULL, 'Arrange the travellers in a chronological order as per their visit to India:

(A) Afanasii Nikitich Nikitin

(B) Ibn Battuta

(C) François Bernier

(D) Duarte Barbosa', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B),(A),(D),(C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.303Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (667, 11, NULL, NULL, 'The evidence of a ploughed field associated with Early Harappan levels is found at:', NULL, '[{"text":"Mohenjodaro","image_url":null,"alt":null},{"text":"Sutkagendor","image_url":null,"alt":null},{"text":"Kalibangan","image_url":null,"alt":null},{"text":"Nageshwar","image_url":null,"alt":null}]', NULL, 2, 'The evidence of a ploughed field associated with Early Harappan levels is found at Kalibangan. This evidence at Kalibangan, Rajasthan, consists of a set of furrows at right angles to each other, suggesting that two different crops were grown together.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.303Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (668, 11, NULL, NULL, 'Which traveller has described the practice of ''child-sati'' in detail?', NULL, '[{"text":"Duarte Barbosa","image_url":null,"alt":null},{"text":"Francois Bernier","image_url":null,"alt":null},{"text":"Peter Mundy","image_url":null,"alt":null},{"text":"Jean-Baptiste Tavernier","image_url":null,"alt":null}]', NULL, 1, 'The traveller who described the practice of child-sati in detail was Francois Bernier. A French physician and traveller who visited India during the Mughal period, Bernier wrote extensively about Indian society and customs. In his accounts, he discussed instances of sati, noting the tragic practice and the difficulty in distinguishing whether the victim was a young child or a very young woman.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.304Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (669, 11, NULL, NULL, 'According to the Dharmasutras and Dharmashastras, the "ideal" occupation of the Kshatriyas were:', NULL, '[{"text":"To study and teach the Vedas, perform sacrifices, give and receive gifts.","image_url":null,"alt":null},{"text":"To engage in agriculture, pastoralism and trade.","image_url":null,"alt":null},{"text":"To serve the three higher varnas.","image_url":null,"alt":null},{"text":"To engage in warfare, protect people and administer justice.","image_url":null,"alt":null}]', NULL, 3, 'According to the dharmashastras and dharmasutras, the "ideal" occupation of the Kshatriyavarna was to engage in warfare, protect people, and administer justice.

Other Varnas:

• Brahmins: Study/teach Vedas, perform sacrifices, give/receive gifts

o Vaishyas: Agriculture, trade, pastoralism

o Shudras: Serve higher varnas', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.304Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (670, 11, NULL, NULL, 'What was included in the process of the ''integration of cults'' in Bhakti-tradition? Identify correct statements:

(A) The process of disseminating Brahmanical ideas.

(B) The composition, compilation and preservation of Puranic texts in simple Sanskrit verse meant for women and Shudras.

(C) A continuous dialogue between "great" Sanskritic Puranic traditions and "little" traditions throughout the land.

(D) Instances of integrations are not evident among goddess cults.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, 'The Bhakti movement facilitated the integration of local and Sanskritic religious traditions across India. This process included:

1. Dissemination of Brahmanical ideas: Bhakti poets and saints spread concepts such as dharma, karma, and the Puranic pantheon among common people, reaching sections like women and Shudras who had limited access to Sanskrit learning.

2. Simplification of sacred texts: Puranic stories were composed, compiled, and preserved in simple Sanskrit or vernacular verse, making complex religious ideas comprehensible and relatable to a

wider audience.

3. Dialogue between "great" and "little" traditions: Local or folk cults ("little" traditions) continuously interacted with Sanskritic Puranic traditions ("great" traditions). This led to the incorporation of regional deities and practices into the mainstream pantheon.

4. Integration of goddess cults: Local goddesses were often identified with Puranic forms such as Shakti, Parvati, or Durga, exemplifying how regional cults were absorbed into the larger Bhakti framework.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.305Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (671, 11, NULL, NULL, 'Which of the following statement is not true about mahajanapadas of the sixth-century BCE:', NULL, '[{"text":"Mahajanapadas were mostly ruled by kings.","image_url":null,"alt":null},{"text":"Each mahajanapada had a capital city, which was often fortified.","image_url":null,"alt":null},{"text":"Early Buddhist and Jaina texts mention twenty states known as mahajanapadas.","image_url":null,"alt":null},{"text":"Mahajanapadas maintained armies and bureaucracies.","image_url":null,"alt":null}]', NULL, 2, 'Buddhist and Jaina texts like the Anguttara Nikaya and Bhagavati Sutra mention 16 major states, not 20.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.305Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (672, 11, NULL, NULL, 'As per Francis Buchanan''s survey of the Dinajpur district in North Bengal, which among the following statement does not match with the description of Jotedars:', NULL, '[{"text":"Jotedars had acquired vast areas of land - sometimes as much as several thousand acres.","image_url":null,"alt":null},{"text":"Jotedars helped the zamindar with land revenue collection.","image_url":null,"alt":null},{"text":"Jotedars controlled local trade as well as money-lending, exercising immense power over the poorer cultivators of the region.","image_url":null,"alt":null},{"text":"A large part of Jotedar''s land was cultivated by sharecroppers (adhiyars or bargadars).","image_url":null,"alt":null}]', NULL, 1, 'The statement is incorrect because the relationship between the Jotedars and the Zamindars was one of antagonism and competition for power, not cooperation in revenue collection.

Role and Power of Jotedars:

1. Vast Landholding: Jotedars held large tracts of land, sometimes several thousand acres, establishing them as dominant rural elites.

2. Cultivation Method: Most of their land was cultivated by sharecroppers, known as adhiyars or bargadars, who brought their own ploughs and received half the harvest.

3. Economic Control: They controlled local markets, trade, and most importantly, money-lending. This allowed them to exercise immense power over the poorer cultivators, who often became indebted to them.

4. Resistance to Zamindars: Jotedars deliberately delayed payments of revenue to the zamindar. Their primary goal was to see the Zamindari fail, which would allow them to purchase the lands being auctioned and thus further strengthen their own local position.

Therefore, they were an obstacle to the Zamindar''s revenue collection efforts, not an aid.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.306Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (673, 11, NULL, NULL, 'Identify the correct statements about the ''Virashaiva'' tradition:

(A) It was led by a Brahmana named Basavanna.

(B) Worship Shiva in his manifestation as a linga.

(C) Lingayats supported the idea of caste and the "pollution" attributed to certain groups by Brahmanas.

(D) Virashaiva do not practise funerary rites and instead, ceremonially bury their dead.', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, '• (A) Correct: The Virashaiva (Lingayat) movement began in the 12th century in Karnataka, led by Basavanna, a Brahmana who served in the Kalachuri court.

(B) Correct: The followers worship Shiva in the form of a linga and are called Lingayats ("wearers of the linga").

(C) Incorrect: The Lingayats opposed caste divisions and Brahmanical ideas of purity and pollution; they promoted equality.

(D) Correct: They bury their dead instead of cremating them, as they believe the devotee''s soul unites with Shiva after death.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.306Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (674, 11, NULL, NULL, 'Identify the structure at ''Hampi'' based on the following description:

"Located on one of the highest points in the city, it is a massive platform rising from a base of about 11,000 sq. ft to a height of 40 ft. There is evidence that it supported a wooden structure. The base of the platform is covered with relief carvings."', NULL, '[{"text":"Lotus Mahal","image_url":null,"alt":null},{"text":"Hazara Rama temple","image_url":null,"alt":null},{"text":"Mahanavami Dibba","image_url":null,"alt":null},{"text":"Vitthala temple","image_url":null,"alt":null}]', NULL, 2, 'The Mahanavami Dibba at Hampi is a huge stone platform about 40 ft high, with its base covered in carvings showing festivals, battles, and royal scenes. A wooden pavilion once stood on top for the king''s ceremonies during the Mahanavami (Dasara) festival.

Lotus Mahal: A beautiful two-storey building with Indo-Islamic design, not a large open platform.

1. Hazara Rama Temple: A small temple in the Royal Centre with Ramayana carvings, not a big platform.

2. Vitthala Temple: A large temple complex with musical pillars and the stone chariot, located outside the Royal Centre, not an open platform.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.307Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (675, 11, NULL, NULL, 'In 1919, the project to prepare a critical edition of the Mahabharata was headed by:', NULL, '[{"text":"V.S. Sukthankar","image_url":null,"alt":null},{"text":"Alexander Cunningham","image_url":null,"alt":null},{"text":"John Marshall and Alfred Foucher","image_url":null,"alt":null},{"text":"Rajendra Lala Mitra","image_url":null,"alt":null}]', NULL, 0, 'The critical edition of the Mahabharata was started in 1919 under the leadership of V.S. Sukthankar at the Bhandarkar Oriental Research Institute (BORI), Pune. This monumental project aimed to prepare an authentic version of the epic by comparing hundreds of manuscripts and took 47 years to complete.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.307Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (676, 11, NULL, NULL, 'Arrange the following events in a chronological order:

(A) English East India Company acquires ''Diwani'' of Bengal

(B) Permanent Settlement of Bengal

(C) Regulating Act passed by the British Parliament

(D) Ryots in Deccan villages rebel', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B),(A),(D),(C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.308Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (677, 11, NULL, NULL, 'Rules for Buddhist Bhikkhus and Bhikkhunis are listed in which

among the following text?', NULL, '[{"text":"Sutta Pitaka","image_url":null,"alt":null},{"text":"Abhidhamma Pitaka","image_url":null,"alt":null},{"text":"Vinaya Pitaka","image_url":null,"alt":null},{"text":"Divyavadan","image_url":null,"alt":null}]', NULL, 2, 'The Vinaya Pitaka, part of the Tripitaka, contains the rules of discipline for Buddhist monks (Bhikkhus) and nuns (Bhikkhunis). It covers daily conduct, communal living, ordination, and procedures for penance, ensuring moral integrity and harmony within the monastic community.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.308Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (678, 11, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/history-2025-05-16-shift-1/q21-table-1.jpg', 'Table for question 21', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.308Z', NULL, NULL, '[{"url":"/local-papers/assets/history-2025-05-16-shift-1/q21-table-1.jpg","alt":"Table for question 21","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (679, 11, NULL, NULL, 'Who described the kingdom of Awadh as "a cherry that will drop into our mouth one day"?', NULL, '[{"text":"Lord Dalhousie","image_url":null,"alt":null},{"text":"Lord William Bentinck","image_url":null,"alt":null},{"text":"Lord Hardinge","image_url":null,"alt":null},{"text":"Lord Canning","image_url":null,"alt":null}]', NULL, 0, 'Lord Dalhousie, the Governor-General of India, famously described Awadh in 1851 as "a cherry that will drop into our mouth one day," expressing his belief that its annexation was inevitable due to alleged misgovernance and strategic importance. Eventually, after a period of 5 years, Awadh was annexed in 1856 by the British on the pretext of misrule.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.309Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (680, 11, NULL, NULL, 'Choose the correct statements about the Virupaksha temple at Hampi:

(A) The hall in front of the main shrine was built by Harihara and Bukka Raya to mark their accession.

(B) It was decorated with delicately carved pillars.

(C) The halls in the temple were used for programmes of music, dance, drama.

(D) The temple was built over centuries.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'The Virupaksha Temple has richly carved mandapas used for music, dance, and festivals, and it has remained as a living temple, being built and expanded over many centuries. The main hall of the temple was built by Krishnadeva Raya, not by Harihara and Bukka Raya.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.309Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (681, 11, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, '/local-papers/assets/history-2025-05-16-shift-1/q24-table-1.jpg', 'Table for question 24', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.309Z', NULL, NULL, '[{"url":"/local-papers/assets/history-2025-05-16-shift-1/q24-table-1.jpg","alt":"Table for question 24","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (682, 11, NULL, NULL, 'The term ''matrilocal'' residence means:', NULL, '[{"text":"The practice where men after marriage remain in their natal home and their wives may come to stay with them.","image_url":null,"alt":null},{"text":"The practice where men-women after marriage does not stay with their families and move to a new home.","image_url":null,"alt":null},{"text":"The practice where women after marriage remain in their natal home with their children and the husbands may come to stay with them.","image_url":null,"alt":null},{"text":"The practice where women after marriage move to the natal home of their husbands and their children stays with their parents.","image_url":null,"alt":null}]', NULL, 2, 'The term ''matrilocal'' comes from mater (mother) and locus (place), meaning the couple lives in or near the bride''s parental home. This system emphasizes maternal lineage and the woman''s central role in the family.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.310Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (683, 11, NULL, NULL, 'By c. 1800 BCE most of the Mature Harappan sites had been abandoned in regions such as _.', NULL, '[{"text":"Kashmir","image_url":null,"alt":null},{"text":"Cholistan","image_url":null,"alt":null},{"text":"Western Uttar Pradesh","image_url":null,"alt":null},{"text":"Haryana","image_url":null,"alt":null}]', NULL, 1, 'By around 1800 BCE, most Mature Harappan sites in the Cholistan desert (Pakistan) were abandoned, marking the start of the Late Harappan phase. This region, once full of settlements along the Ghaggar-Hakra River, saw a sharp decline, while areas like Haryana and Western Uttar Pradesh grew in population during the same period.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.310Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (684, 11, NULL, NULL, 'Images of Buddha and Bodhisattas that were evidently based on Greek models were found in which city?', NULL, '[{"text":"Kanauj","image_url":null,"alt":null},{"text":"Taxila","image_url":null,"alt":null},{"text":"Nalanda","image_url":null,"alt":null},{"text":"Mahabalipuram","image_url":null,"alt":null}]', NULL, 1, 'Taxila, in north-western India (modern Pakistan), was a major center of the Gandhara School of Buddhist art, showing Greek (Hellenistic) influence in realistic human forms, draped clothing, and wavy hair. This style was developed under the Indo-Greek rulers who established kingdoms in Taxila and Peshawar around 2nd century BCE.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.312Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (685, 11, NULL, NULL, 'Which texts contain the ''regional histories'' of Buddhism?', NULL, '[{"text":"Tipitakas","image_url":null,"alt":null},{"text":"Sutta Pitaka and Vinaya Pitaka","image_url":null,"alt":null},{"text":"Abhidhamma Pitaka","image_url":null,"alt":null},{"text":"Dipavamsa and Mahavamsa","image_url":null,"alt":null}]', NULL, 3, 'These two texts, particularly the Mahavamsa (Great Chronicle) and its predecessor the Dipavamsa (Island Chronicle), are important historical chronicles from Sri Lanka that detail the history of Buddhism on the island and its connection to India. They are considered key sources for the history of Buddhism in that region.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.312Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (686, 11, NULL, NULL, 'Choose the correct statements for distinctive features of the Harappan planned ''drainage system'':

(A) Roads and streets were laid out along an approximate "grid" pattern.

(B) It seems that streets with drains were laid out first and then houses built along them.

(C) Domestic waste water did not flow into the street drains.

(D) Every house needs to have at least one wall along a street.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'A) Correct - Harappan cities like Mohenjo-daro and Harappa had streets laid out in a north-south and east-west grid pattern, indicating a high level of urban planning and organisation.

(B) Correct - Archaeological evidence shows that streets and drainage systems were planned and constructed first, and houses were then built alongside them. This reflects a strong focus on civic infrastructure.

(C) Incorrect - In reality, domestic wastewater was directed into street drains via private household drains. These were often covered and maintained, highlighting the efficiency of Harappan sanitation.

(D) Correct - Most houses were designed with at least one wall adjoining a street, ensuring easy access and connection to the drainage and road network.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.313Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (687, 11, NULL, NULL, 'The original story of Mahabharata was probably composed by:', NULL, '[{"text":"Charioteer-bards known as Sutas","image_url":null,"alt":null},{"text":"Rishi Agastaya","image_url":null,"alt":null},{"text":"Maharishi Valmiki","image_url":null,"alt":null},{"text":"Manu","image_url":null,"alt":null}]', NULL, 0, 'The original story of the Mahabharata was probably composed by charioteer-bards known as Sutas. They were storytellers who accompanied kings and warriors, reciting their deeds and heroic tales. These bards preserved and passed down the epic orally over generations before it was eventually written down.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.314Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (688, 11, NULL, NULL, 'The Rajasuya and Ashvamedha sacrifices were performed by _.', NULL, '[{"text":"The chiefs and kings","image_url":null,"alt":null},{"text":"The heads of households","image_url":null,"alt":null},{"text":"The individual members of the Kula alone","image_url":null,"alt":null},{"text":"Members of the household collectively","image_url":null,"alt":null}]', NULL, 0, 'The Rājasūya and Aśvamedha sacrifices were grand Vedic rituals performed by chiefs and kings to assert their authority and sovereignty. The Rājasūya marked the king''s consecration and formal establishment of power, while the Aśvamedha (Horse Sacrifice) proclaimed his supreme control over surrounding territories.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.315Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (689, 11, NULL, NULL, 'Francois Bernier dedicated his major writings to which king of France?', NULL, '[{"text":"Francis II","image_url":null,"alt":null},{"text":"Louis XI","image_url":null,"alt":null},{"text":"Louis XIV","image_url":null,"alt":null},{"text":"Charles II","image_url":null,"alt":null}]', NULL, 2, 'François Bernier dedicated his major work, Travels in the Mughal Empire (a detailed account of his time in India and observations of the reigns of Dara Shikoh and Aurangzeb) to Louis XIV, the King of France, who was known as the "Sun King."

Bernier''s descriptions often compared the situation in the Mughal Empire unfavorably with contemporary Europe, explicitly using his observations as a cautionary tale for the French monarch and his ministers about the dangers of absolute state ownership of land.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.316Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (690, 11, NULL, NULL, 'Which details among the following were recorded by Ain-i Akbari? Identify the correct statements:

(A) Account of the daily lives of ordinary peasants.

(B) The arrangements made by the state to ensure cultivation.

(C) The arrangements made to enable the collection of revenue by the agencies of the state.

(D) The arrangements made to regulate the relationship between the state and the zamindars.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'The Ain-i Akbari is the third part of the Akbarnama, written by Abul Fazl, one of Emperor Akbar''s close courtiers. It is a detailed administrative document that records information about the institutions and functioning of the Mughal Empire. It does not describe the daily lives of ordinary peasants. Instead, it focuses on state policies and institutions as well as records the arrangements made to ensure cultivation, such as land measurement and crop classification, the systems for revenue collection by state agencies, and the regulations governing the relationship between the state and the zamindars.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.316Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (691, 11, NULL, NULL, 'Which of the following is not the subject-matter of ''The Fifth Report'', submitted to the British Parliament in 1813?', NULL, '[{"text":"The administration and activities of the East India Company in India.","image_url":null,"alt":null},{"text":"Military reforms required in the army.","image_url":null,"alt":null},{"text":"Petitions of zamindars and ryots, reports of collectors from different districts.","image_url":null,"alt":null},{"text":"Statistical tables on revenue returns, notes on the revenue and judicial administration of Bengal and Madras written by officials.","image_url":null,"alt":null}]', NULL, 1, '"The Fifth Report" submitted to the British Parliament in 1813 primarily dealt with the administration and activities of the East India Company, the petitions from zamindars and ryots, and statistical tables on revenue and judicial administration in Bengal and Madras. It did not focus on military reforms in the army.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.317Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (692, 11, NULL, NULL, 'The Ain-i Akbari does not mention this crop in the lists of crops in northern India. Identify the crop?', NULL, '[{"text":"Tobacco","image_url":null,"alt":null},{"text":"Cotton","image_url":null,"alt":null},{"text":"Mustard","image_url":null,"alt":null},{"text":"Rice","image_url":null,"alt":null}]', NULL, 0, 'The Ain-i-Akbari does not mention tobacco among the crops listed for northern India. Crops like rice, cotton, and mustard were included, but tobacco was not prominently mentioned in these records.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.317Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (693, 11, NULL, NULL, 'Identify the correct statements associated with Al-Biruni:

(A) He was born in Khwarizm, in present day Uzbekistan.

(B) He read the works of Plato and other Greek philosophers in Arabic translations.

(C) Traveled to the Chinese port town of Zaytun and extensively in China, going as far as Beijing.

(D) Wrote Kitab-ul-Hind, in Arabic, divided into 80 chapters on religion and philosophy, festivals, etc.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'Al-Biruni, born in Khwarizm (modern-day Uzbekistan), was a renowned scholar who made significant contributions to various fields. He read the works of Plato and other Greek philosophers through Arabic translations, which deeply influenced his intellectual development. Al-Biruni is best known for his work Kitab-ul-Hind, written in Arabic, which is divided into 80 chapters and covers topics such as religion, philosophy, festivals, and more, offering a detailed account of India''s culture and traditions. However, contrary to some accounts, there is no evidence that Al-Biruni traveled to China or reached the Chinese port town of Zaytun, as he focused his travels primarily within the regions surrounding the Islamic world.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.318Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (694, 11, NULL, NULL, 'The ruins at ''Hampi'' were brought to light in 1800 by _.', NULL, '[{"text":"Colin Mackenzie","image_url":null,"alt":null},{"text":"Alexander Greenlaw","image_url":null,"alt":null},{"text":"John Marshall","image_url":null,"alt":null},{"text":"J.F. Fleet","image_url":null,"alt":null}]', NULL, 0, 'Colonel Colin Mackenzie, the first Surveyor General of India, is credited with bringing the ruins of Hampi to light in 1800. During his survey of the region, he discovered the ancient remnants of the Vijayanagara Empire and documented them, helping to reveal the site''s historical significance.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.318Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (695, 11, NULL, 93, '4. Kharosthi', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'The correct option is 4. Kharosthi.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.320Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
