INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (697, 11, NULL, 95, '4. Fourth-Third Centuries BCE', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 0, 'The correct option is 1. Second-First Centuries BCE.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.321Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (698, 11, NULL, 96, '4. Roman', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 0, 'The correct option is 1. Brahmi.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.322Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (699, 11, NULL, 97, '4. Shah Jahan', NULL, '[{"text":"Muhammad bin Tughlaq","image_url":null,"alt":null},{"text":"Ghiyasuddin Khalji","image_url":null,"alt":null},{"text":"Akbar","image_url":null,"alt":null},{"text":"Shah Jahan","image_url":null,"alt":null}]', NULL, 2, 'Akbar visited the dargah fourteen times until 1580, offering gifts like a large cauldron and building a mosque there.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.322Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (700, 11, NULL, 98, '4. Ibrahim Lodhi', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'The correct option is 2. Ghiyasuddin Khalji of Malwa.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.323Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (701, 11, NULL, 99, 'fact, it was the spirited singing of pilgrims bound for Ajmer that inspired Akbar to visit the tomb.

In Sufism, the *shaikh* was revered as *wali*. What does the term *''wali''* mean?', NULL, '[{"text":"Friend of People","image_url":null,"alt":null},{"text":"Friend of Holy Spirits","image_url":null,"alt":null},{"text":"Friend of God","image_url":null,"alt":null},{"text":"Friend of Disciples","image_url":null,"alt":null}]', NULL, 2, 'After the shaikh''s death, his tomb became a pilgrimage site, symbolizing his union with God. This led to the shaikh being revered as a wali, or "friend of God."

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.323Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (702, 11, NULL, NULL, 'Arrange the following political and economic developments in a chronological order:

(A) Shaka (peoples from Central Asia) rulers in the northwest

(B) Indo-Greek rule in the northwest

(C) Vakatakas in the Deccan

(D) Invasion of Alexander of Macedon', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(D), (B), (A), (C)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.324Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (703, 11, NULL, NULL, 'Verses ascribed to Kabir have been compiled in three distinct but overlapping traditions. Which among the following is not one of them?', NULL, '[{"text":"Kabir Bijak","image_url":null,"alt":null},{"text":"Kabir Granthavali","image_url":null,"alt":null},{"text":"Adi Granth Sahib","image_url":null,"alt":null},{"text":"Guru Granth Sahib","image_url":null,"alt":null}]', NULL, 3, 'The Guru Granth Sahib was compiled in its final form in the late seventeenth century when the tenth Sikh Guru, Guru Gobind Singh, incorporated the hymns of the ninth Guru Tegh Bahadur. Thereafter, this scripture came to be known as the Guru Granth Sahib.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.324Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (704, 11, NULL, NULL, '"I free her from here, but not from there. I have bound her firmly there, so that through the grace of Indra she will have fine sons and be fortunate in her husband''s love." From where is this excerpt of a mantra for producing ''fine sons'' taken:', NULL, '[{"text":"Brihadaranyaka Upanishad","image_url":null,"alt":null},{"text":"Mahabharata","image_url":null,"alt":null},{"text":"Manusmriti","image_url":null,"alt":null},{"text":"Rigveda","image_url":null,"alt":null}]', NULL, 3, 'Rigveda because :

1. Patriliny was a common concern, reflected in many Rigvedic mantras.

2. Indra, a key deity, symbolized valour, warfare, and rain.

3. "Here" refers to the father''s house, and "there" to the husband''s house.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.325Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (705, 11, NULL, NULL, 'The Khilafat Movement of 1919-1920 demanded that the jazīrat-ul-Arab must remain under Muslim sovereignty. Which region was not a part of jazīrat-ul-Arab?', NULL, '[{"text":"Arabia","image_url":null,"alt":null},{"text":"Syria","image_url":null,"alt":null},{"text":"Afghanistan","image_url":null,"alt":null},{"text":"Palestine","image_url":null,"alt":null}]', NULL, 2, 'The Jazirat-Ul-Arab consisted of Arabia, Syria, Iraq, Palestine hence the region which was not a part is Afghanistan.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.325Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (706, 11, NULL, NULL, 'In urban centres, who represented the merchant communities during the medieval period?', NULL, '[{"text":"Gramsheth","image_url":null,"alt":null},{"text":"Kokasheth","image_url":null,"alt":null},{"text":"Nagarsheth","image_url":null,"alt":null},{"text":"Durgsheth","image_url":null,"alt":null}]', NULL, 2, 'In western India, merchant groups called mahajans were led by a sheth, and in urban centres like Ahmedabad, their chief representative was the nagarsheth.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.326Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (707, 11, NULL, NULL, 'Where was the Safavid Empire located?', NULL, '[{"text":"China","image_url":null,"alt":null},{"text":"Iran","image_url":null,"alt":null},{"text":"Turkey","image_url":null,"alt":null},{"text":"Afghanistan","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.327Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (708, 11, NULL, NULL, 'The archaeological findings of which grain are relatively rare at Harappan sites?', NULL, '[{"text":"Rice","image_url":null,"alt":null},{"text":"Wheat","image_url":null,"alt":null},{"text":"Barley","image_url":null,"alt":null},{"text":"Lentil","image_url":null,"alt":null}]', NULL, 0, 'While wheat, barley, lentils, chickpeas, sesame, and millets were commonly found at Harappan sites, rice remains are relatively rare.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.328Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (709, 11, NULL, NULL, 'Why did the zamindars regularly fail to pay the revenue demand in the early decades after the ''Permanent Settlement''. Choose the correct statements from below:

(A) The initial demands were very high.

(B) This high demand was imposed in the 1790s, a time when the prices of agricultural produce were depressed, making it difficult for the ryots to pay their dues to the zamindar.

(C) The revenue was invariable, regardless of the harvest, and had to be paid punctually.

(D) The ''Permanent Settlement'' initially limited the power of the zamindar to collect rent from the ryot and manage his zamindari.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'The correct statements are 3. (A),(B),(C) and (D).', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.329Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (710, 11, NULL, NULL, 'During the elections of 1937 in British India, the Congress came to power in _ provinces.', NULL, '[{"text":"Eight","image_url":null,"alt":null},{"text":"Nine","image_url":null,"alt":null},{"text":"Ten","image_url":null,"alt":null},{"text":"Eleven","image_url":null,"alt":null}]', NULL, 0, 'After the 1937 elections under the Government of India Act (1935), Congress formed ministries in eight of the eleven provinces, working under British Governors.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.330Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (711, 11, NULL, NULL, 'Who built Secundrah Bagh as a ''pleasure garden''?', NULL, '[{"text":"Shah Mal","image_url":null,"alt":null},{"text":"Birjis Qadr","image_url":null,"alt":null},{"text":"Wajid Ali Shah","image_url":null,"alt":null},{"text":"Bahadur Shah","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.331Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (712, 11, NULL, NULL, 'Which of the following ''mature'' Harappan sites are located in present-day India?

(A) Ganweriwala

(B) Kalibangan

(C) Banawali

(D) Rakhigarhi', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'Kalibangan is located in present-day Rajasthan, Banawali and Rakhigarhi are in Haryana, while Ganweriwala is situated in modern-day Pakistan.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.332Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (713, 11, NULL, NULL, 'After M.K. Gandhi''s release from prison in January 1931, where did the Congress leaders meet to plan the future course of action?', NULL, '[{"text":"Lucknow","image_url":null,"alt":null},{"text":"Lahore","image_url":null,"alt":null},{"text":"Calcutta","image_url":null,"alt":null},{"text":"Allahabad","image_url":null,"alt":null}]', NULL, 3, 'Gandhiji met Jawaharlal Nehru, Jamnalal Bajaj, Subhas Chandra Bose, Mahadev Desai, and Sardar Vallabh Bhai Patel in Allahabad.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.332Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (714, 11, NULL, NULL, 'Which of the following statements is true about the amara-nayakas:

(A) The amara-nayakas were civil servants who were given territories to govern by the raya.

(B) The amara-nayakas collected taxes and other dues from peasants, craftspersons and traders in the area.

(C) The amara-nayakas sent tribute to the king annually and personally appeared in the royal court with gifts to express their loyalty.

(D) Kings occasionally asserted their control over the amara-nayakas by transferring them from one place to another.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'Statements (B), (C), and (D) are correct, while (A) is incorrect because the amara-nayakas were military commanders, not civil servants, appointed by the raya to govern territories.

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.332Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (715, 11, NULL, NULL, 'The Ain-i Akbari was completed in which regnal year of the emperor Akbar?', NULL, '[{"text":"Forty-first regnal year","image_url":null,"alt":null},{"text":"Forty-second regnal year","image_url":null,"alt":null},{"text":"Forty-third regnal year","image_url":null,"alt":null},{"text":"Fifty-fourth regnal year","image_url":null,"alt":null}]', NULL, 1, 'The Ain-i Akbari, completed in 1598 during Emperor Akbar''s forty-second regnal year, was the result of an extensive administrative project led by Abu''l Fazl, undergoing five revisions before its final compilation.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.333Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (716, 11, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (Ⅳ), (B) - (Ⅲ), (C) - (Ⅱ), (D) - (Ⅰ)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 1, 'The correct answers are 2. (A)-(IV),(B)-(III),(C)-(II),(D)-(I).', NULL, NULL, 2025, '/local-papers/assets/history-2025-05-20-shift-1/q16-table-1.jpg', 'Table for question 16', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.333Z', NULL, NULL, '[{"url":"/local-papers/assets/history-2025-05-20-shift-1/q16-table-1.jpg","alt":"Table for question 16","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (717, 11, NULL, NULL, 'In which year was the last Mughal ruler, Bahadur Shah II, deposed by the British and exiled to Rangoon?', NULL, '[{"text":"1791","image_url":null,"alt":null},{"text":"1855","image_url":null,"alt":null},{"text":"1870","image_url":null,"alt":null},{"text":"1857","image_url":null,"alt":null}]', NULL, 3, 'The correct option is 4.1857', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.334Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (718, 11, NULL, NULL, 'The making of elaborate stone structures known as "megaliths" emerged in which part of the Indian subcontinent from the first millennium BCE?

(A) North India

(B) Central India

(C) South India

(D) East India', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(D) and (A) only","image_url":null,"alt":null}]', NULL, 1, 'New burial practices, including the construction of elaborate stone megaliths, appeared in central and south India from the first millennium BCE, often accompanied by iron tools and weapons.

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.334Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (719, 11, NULL, NULL, 'At the end of 1858, when the rebellion collapsed, who escaped to Nepal?', NULL, '[{"text":"Nana Sahib","image_url":null,"alt":null},{"text":"Kunwar Singh","image_url":null,"alt":null},{"text":"Rani Lakshmi Bai","image_url":null,"alt":null},{"text":"Birjis Qadr","image_url":null,"alt":null}]', NULL, 0, 'At the end of 1858, following the collapse of the rebellion, Nana Sahib escaped to Nepal, adding to his legacy of courage and valor.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.334Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (720, 11, NULL, NULL, 'Sarojini Naidu, a woman member of the Constituent Assembly, was elected from which constituency?', NULL, '[{"text":"United Provinces","image_url":null,"alt":null},{"text":"Madras","image_url":null,"alt":null},{"text":"Bihar","image_url":null,"alt":null},{"text":"Central Provinces","image_url":null,"alt":null}]', NULL, 2, 'Sarojini Naidu was nominated to the Constituent Assembly on 9 December 1946, representing Bihar.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.335Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (721, 11, NULL, NULL, 'In the Mahabharata text, "You yourself did not receive the throne, although it fell to you, because of your defect. If the Pandava receives the patrimony ..., his son will surely inherit it in turn, and so will his son, and his." Who is referred to as ''you'' in the excerpt?', NULL, '[{"text":"Dhritarashtra","image_url":null,"alt":null},{"text":"Pandu","image_url":null,"alt":null},{"text":"Duryodhana","image_url":null,"alt":null},{"text":"Yudhisthira","image_url":null,"alt":null}]', NULL, 0, '"You" refers to Dhritarashtra, spoken by his son Duryodhana out of jealousy as people favored the Pandavas for their courage.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.335Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (722, 11, NULL, NULL, 'Arrange the following teachers of the Chisti Silsila according to their year of death chronologically:

(A) Shaikh Fariduddin Ganj-i Shakar

(B) Shaikh Nasiruddin Chiragh-i Dehli

(C) Khwaja Qutbuddin Bakhtiyar Kaki

(D) Shaikh Nizamuddin Auliya', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (A), (D), (B)","image_url":null,"alt":null}]', NULL, 3, 'The correct option is 4. (C), (A), (D), (B) because :

(C) Khwaja Qutbuddin Bakhtiyar Kaki - 1235

(A) Shaikh Fariduddin Ganj-i Shakar - 1265

(D) Shaikh Nizamuddin Auliya - 1325

(B) Shaikh Nasiruddin Chiragh-i Dehli - 1356', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.336Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (723, 11, NULL, NULL, 'Who did Baba Guru Nanak appoint as one of his disciples to succeed him as the preceptor (guru)?', NULL, '[{"text":"Guru Arjan","image_url":null,"alt":null},{"text":"Guru Angad","image_url":null,"alt":null},{"text":"Guru Gobind Singh","image_url":null,"alt":null},{"text":"Guru Tegh Bahadur","image_url":null,"alt":null}]', NULL, 1, 'Baba Guru Nanak formed a community with collective worship and appointed Guru Angad as his successor. This tradition continued for nearly 200 years.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.336Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (724, 11, NULL, NULL, 'What does the term ''Piyadassi'' means in the earliest inscriptions?', NULL, '[{"text":"Beloved of the gods","image_url":null,"alt":null},{"text":"Beloved of the people","image_url":null,"alt":null},{"text":"Pleasant to behold","image_url":null,"alt":null},{"text":"Beloved of the universe","image_url":null,"alt":null}]', NULL, 2, 'James Prinsep deciphered the Brahmi and Kharosthi scripts, revealing that many inscriptions referred to a king called Piyadassi, meaning "pleasant to behold."', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.337Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
