INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (726, 11, NULL, NULL, 'Who accompanied Augustus Cleveland, the Collector of Bhagalpur, to the Jangal Mahals in 1782, and painted a set of aquatints?', NULL, '[{"text":"Joseph Noel Paton","image_url":null,"alt":null},{"text":"Thomas Jones Barker","image_url":null,"alt":null},{"text":"William Hodges","image_url":null,"alt":null},{"text":"Captain Cook","image_url":null,"alt":null}]', NULL, 2, 'William Hodges, who sailed with Captain Cook, came to India and befriended Augustus Cleveland. In 1782, he accompanied Cleveland to the Jangal Mahals and painted a series of aquatints.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.337Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (727, 11, NULL, NULL, 'According to Ibn Battuta''s description of the postal system in India, what is the ''uluq''?', NULL, '[{"text":"Horse-post","image_url":null,"alt":null},{"text":"Elephant-post","image_url":null,"alt":null},{"text":"Bullock-post","image_url":null,"alt":null},{"text":"Oxen-post","image_url":null,"alt":null}]', NULL, 0, 'In India, the postal system had two types: the horsepost, or uluq, using royal horses stationed every four miles, and the foot post, known as dawa.

_', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.338Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
