INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (729, 11, NULL, NULL, 'Which foreign traveller to the Vijayanagara Empire called the audience hall and the mahanavami dibba together as the "House of Victory"?', NULL, '[{"text":"Nicolo de Conti","image_url":null,"alt":null},{"text":"Abdur Razzaq","image_url":null,"alt":null},{"text":"Afanasii Nikitin","image_url":null,"alt":null},{"text":"Domingo Paes","image_url":null,"alt":null}]', NULL, 3, 'Domingo Paes described the "House of Victory" as two sculpted platforms, with the upper one containing the king''s chamber and an idol''s shrine. A dais with the throne, crown, and royal anklet stood at its center.', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:38.338Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
