Correct Option: (2)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:45.886Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (895, 3, NULL, NULL, '|f| $ \begin{matrix}2x\\8\end{matrix} $ $ \begin{matrix}5\\x\end{matrix} $|= $ \begin{matrix}3\\4\end{matrix} $ $ \begin{matrix}0\\-8\end{matrix} $|，then value(s) of x is/are', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"2 $ \\sqrt{2} $","image_url":null,"alt":null},{"text":"$ \\pm2\\sqrt{2} $","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 2, '$$ \det\begin{bmatrix}{{{2x}}}&{{{5}}} \\{{{8}}}&{{{x}}}\end{bmatrix}=2x^{2}-40,\quad\det\begin{bmatrix}{{{3}}}&{{{0}}} \\{{{4}}}&{{{-8}}}\end{bmatrix}=-24 $$

On equating the two sides we get:

$ 2x^{2}-40=-24 $

$ 2x^{2}=16 $

$ x^{2}=8 $

$ x=\pm2\sqrt{2} $

Correct option: (3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:45.886Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (896, 3, NULL, NULL, 'The probabilities of occurrence of two events E and F are 0.25 and 0.50 respectively. The probability of their simultaneous occurrence is 0.14. The probability that neither E nor F occurs is', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"0.39","image_url":null,"alt":null},{"text":"0.61","image_url":null,"alt":null}]', NULL, 2, '$$ P(E)=0.25,P(F)=0.50,P(E\cap F)=0.14 $$

P(neither E nor F) = 1 - P(E ∪ F) = 1 - (P(E) + P(F) - P(E ∩ F)) = 1 - 0.61 = 0.39

Correct option: (3)', NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:45.887Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
