INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1345, 1, NULL, NULL, 'Match the words in List-I with their definitions in List-II:', NULL, '[{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null},{"text":"$ (\\mathbf{A}) - (\\mathrm{IV}), (\\mathrm{B}) - (\\mathrm{III}), (\\mathrm{C}) - (\\mathrm{II}), (\\mathrm{D}) - (\\mathrm{I}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{II}) $, (D) - $ (\\mathrm{I}) $","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2024, '/local-papers/assets/english-2024-05-15-shift-2/q03-table-1.jpg', 'Table for question 3', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.199Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2024-05-15-shift-2/q03-table-1.jpg","alt":"Table for question 3","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
