INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1377, 1, NULL, 111, 'The passage reminds us to ''stay hydrated'' which means that', NULL, '[{"text":"we should have plenty of water","image_url":null,"alt":null},{"text":"we should stay indoors.","image_url":null,"alt":null},{"text":"we should have fermented foods like yogurt","image_url":null,"alt":null},{"text":"we should have zinc-rich foods with vitamin C","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is ''we should have plenty of water''.
Key Points

• Staying hydrated refers to maintaining adequate water levels in the body.

• Drinking plenty of fluids, such as water, is essential for staying hydrated.

- Proper hydration supports the body''s overall health and immune functions.

• Adequate water intake helps alleviate symptoms of colds and coughs.

• Water helps to keep the throat moist, reducing irritation caused by coughing.

- Proper hydration can help maintain the body''s balance of fluids and electrolytes.

Therefore, the correct answer is ''Option 1''.
Additional Information

• Staying indoors does not directly relate to maintaining hydration.

• Fermented foods like yogurt do not directly help in staying hydrated.

• Having zinc-rich foods with vitamin C is beneficial for immune support but does not specifically address hydration.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1378, 1, NULL, 111, 'The passage encourages us to consume zinc in the form of', NULL, '[{"text":"zinc solution","image_url":null,"alt":null},{"text":"unprocessed food grains","image_url":null,"alt":null},{"text":"a variety of plant and animal foods","image_url":null,"alt":null},{"text":"non-vegetarian sources only Answer: C","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is ''a variety of plant and animal foods''.
Key Points

• The passage emphasizes the inclusion of zinc-rich foods from both plant and animal sources.

• It mentions specific zinc-rich foods such as lean meats, poultry, seafood, dairy, nuts, and seeds.

- Consuming a diverse range of foods ensures that different sources of zinc are included in the diet.

- The passage highlights the importance of combining zinc-rich foods with vitamin C for enhanced immune support.

• It suggests moderation and diversity in the diet to maximize the benefits of zinc.

• The passage also advises vegetarians on methods to improve zinc absorption from plant sources.

Therefore, the correct answer is ''Option 3''.
Additional Information

- Zinc solution is not mentioned as a primary source of zinc in the passage.

- Unprocessed food grains contain phytates that hinder zinc absorption, so they are not recommended as the main source.

- Non-vegetarian sources are included but are not the only recommended sources of zinc.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1379, 1, NULL, 111, 'Choose the word that means the opposite of ''pivotal''.', NULL, '[{"text":"Central","image_url":null,"alt":null},{"text":"Important","image_url":null,"alt":null},{"text":"Life-changing","image_url":null,"alt":null},{"text":"Unimportant","image_url":null,"alt":null}]', NULL, 3, 'The correct answer is ''Unimportant''.
Key Points

• The word ''pivotal'' refers to something that is crucial, central, or of utmost importance.

• The opposite of ''pivotal'' would be something that lacks importance or is not central to a situation.

• ''Unimportant'' directly indicates a lack of significance or relevance.

• In the context of the passage, ''pivotal'' describes zinc''s significant role in supporting body functions.

• Therefore, the opposite term would downplay its importance, fitting the meaning of ''unimportant''.

• Recognizing antonyms helps understand the relative importance or lack thereof of a concept.

Therefore, the correct answer is ''Option 4''.
Additional Information

• ''Central'' is synonymous with ''pivotal'', not an antonym.

• ''Important'' is synonymous with ''pivotal'', not an antonym.

• ''Life-changing'' also indicates something significant, so it is not an antonym.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.226Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1380, 1, NULL, 111, 'In the passage, which of the following is not a benefit connected to consuming zinc?', NULL, '[{"text":"Strengthens immune system","image_url":null,"alt":null},{"text":"Anti-viral properties","image_url":null,"alt":null},{"text":"Anti-inflammatory agent","image_url":null,"alt":null},{"text":"Supports hair growth Answer: D","image_url":null,"alt":null}]', NULL, 3, 'The correct answer is ''Supports hair growth''.
Key Points

- The passage highlights zinc''s role in reducing the severity and duration of respiratory tract infections.

• It mentions that zinc soothes sore throats due to its anti-inflammatory properties.

• Zinc is stated to play a pivotal role in supporting the immune system and overall health.

- The passage states that zinc prevents viruses from growing in the body, indicating its anti-viral properties.

• The immune-boosting properties of zinc are specifically noted in the passage.

- However, the passage does not mention any benefits of zinc related to supporting or enhancing hair growth.

Therefore, the correct answer is ''Option 4''.
Additional Information

• Strengthening the immune system is explicitly mentioned as a benefit of zinc.

- Anti-viral properties are clearly indicated in the passage.

• The anti-inflammatory effect of zinc is described in detail.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.226Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1381, 1, NULL, 111, 'What does the word ''solution'' signify in ''a secret solution''?', NULL, '[{"text":"Remedy","image_url":null,"alt":null},{"text":"Drink","image_url":null,"alt":null},{"text":"Function","image_url":null,"alt":null},{"text":"Food","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is ''Remedy''.
Key Points

- The passage refers to zinc as a secret solution for reducing the severity and duration of respiratory tract infections and soothing sore throats.

- Zinc''s role in supporting various body functions, suggesting it helps in overall health, implies a corrective aspect.

- I he context in which ''solution'' is used in the passage aligns with the concept of something that solves or alleviates a problem, particularly health-related issues.

- The passage contrasts zinc with vitamin C, which is commonly known for its remedial benefits for colds, suggesting zinc serves a similar purpose.

• ''Solution'' in the context of health and wellness generally signifies a remedy or treatment for an ailment.

- Thus, the term ''solution'' here does not refer to a drink, function, or food, but to something that offers relief or cure.

Therefore, the correct answer is ''Option 1''.
Additional Information

• ''Drink'' would imply a liquid consumed for health, but the passage does not use ''solution'' in this manner.

- ''Function'' pertains to the roles zinc plays in the body but does not fit the context of ''secret solution''

• ''Food'' refers to items containing zinc, not the alleviating role zinc plays.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.227Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1382, 1, NULL, 111, 'According to the passage, combining zinc-rich foods with vitamin C will result in', NULL, '[{"text":"reduced immunity.","image_url":null,"alt":null},{"text":"increased immunity","image_url":null,"alt":null},{"text":"food allergy","image_url":null,"alt":null},{"text":"a sore throat.","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is Option 2.
Key Points

• Combining zinc-rich foods with vitamin C enhances immune support.

• Vitamin C and zinc are both known to boost the immune system.

• The passage specifically mentions the benefit of combining them for enhanced immune support.

Therefore, the correct answer is Option 2.

Explanation: Combining zinc-rich foods with vitamin C is beneficial for immunity, as both nutrients play key roles in supporting and boosting the immune system.
Additional Information

