INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1387, 1, NULL, 112, 'Choose a word from the options given below to replace the underlined word.
Deforestation reduces $ \underline{\text{nesting}} $ sites', NULL, '[{"text":"building","image_url":null,"alt":null},{"text":"sheltering","image_url":null,"alt":null},{"text":"reproducing","image_url":null,"alt":null},{"text":"protecting","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is ''sheltering''.

