INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1389, 1, NULL, 114, 'According to the passage, ego means', NULL, '[{"text":"our view of the cognitive world","image_url":null,"alt":null},{"text":"an inflated view of ourselves","image_url":null,"alt":null},{"text":"our view of others","image_url":null,"alt":null},{"text":"a balanced view of oneself","image_url":null,"alt":null}]', NULL, 0, 'our view of the cognitive world', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.235Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1390, 1, NULL, 114, '''Knowing oneself'' is important because', NULL, '[{"text":"it leads to stress","image_url":null,"alt":null},{"text":"it is a liability","image_url":null,"alt":null},{"text":"it is an asset","image_url":null,"alt":null},{"text":"it leads one to the black hole area Answer: C","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is ''it is an asset''.
Key Points

