• Option 4: The "black hole area" refers to the negative consequences of an inflated ego, not the importance of self-awareness.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.235Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1391, 1, NULL, 114, '''To start ballooning'' means', NULL, '[{"text":"to deflate","image_url":null,"alt":null},{"text":"to inflate","image_url":null,"alt":null},{"text":"to lose importance","image_url":null,"alt":null},{"text":"to create havoc Answer: B","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is ''to inflate''.
Key Points

