• Option 4: "To create havoc" is a consequence of an inflated ego but not the direct meaning of "ballooning."', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.236Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1392, 1, NULL, 114, 'People with ''inflated'' ego are', NULL, '[{"text":"popular","image_url":null,"alt":null},{"text":"disliked","image_url":null,"alt":null},{"text":"servile","image_url":null,"alt":null},{"text":"naive","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is ''disliked''.
