INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1393, 1, NULL, 114, 'The passage does not refer to :', NULL, '[{"text":"All human beings have an ego","image_url":null,"alt":null},{"text":"Inftated ego can prove detrimental","image_url":null,"alt":null},{"text":"Inflated ego can be counter productive","image_url":null,"alt":null},{"text":"Inflated ego has a win-win outcome.","image_url":null,"alt":null}]', NULL, 3, 'The correct answer is ''Inflated ego has a win-win outcome''.
