INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1394, 1, NULL, 114, 'Seeking frequent feedback leads to', NULL, '[{"text":"success as a leader","image_url":null,"alt":null},{"text":"havoc at the work front","image_url":null,"alt":null},{"text":"derailment","image_url":null,"alt":null},{"text":"reduced leader''s clout Answer: A","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is ''success as a leader''.
