INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1395, 1, NULL, 115, 'Why did the Green Blazer draw Raju''s attention?', NULL, '[{"text":"It was his favourite colour.","image_url":null,"alt":null},{"text":"It screamed to be followed","image_url":null,"alt":null},{"text":"It merged well with the crowd","image_url":null,"alt":null},{"text":"It was too conspicuous in that crowd","image_url":null,"alt":null}]', NULL, 3, 'The correct answer is ''It was too conspicuous in that crowd''.
