INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1397, 1, NULL, 115, 'What do you think is Raju''s profession?', NULL, '[{"text":"an idler","image_url":null,"alt":null},{"text":"a pickpocketer","image_url":null,"alt":null},{"text":"a gambler","image_url":null,"alt":null},{"text":"an artist","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is ''a pickpocketer''.
