INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1398, 1, NULL, NULL, 'Rearrange the parts in the correct sequence to form a meaningful sentence:

(A) to obesity have a lower risk of heart disease

(B) people with a high BMI and a genetic predisposition

(C) related to environmental and lifestyle factors alone

(D) compared to people whose extra weight is', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (B), (D)","image_url":null,"alt":null},{"text":"(B), (A), (D), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is Option 3.
Key Points

• The rearranged sentence should make logical and grammatical sense.

• Sentence A follows as it explains the consequence for these people:

○ "to obesity have a lower risk of heart disease"

• Sentence D is the third sentence because it introduces a comparison:

o "compared to people whose extra weight is"

• Sentence C is the fourth as it completes the comparison:

o "related to environmental and lifestyle factors alone"

• The correct sequence is BADC.

Coherent sentence after rearrangement:

"People with a high BMI and a genetic predisposition to obesity have a lower risk of heart disease compared to people whose extra weight is related to environmental and lifestyle factors alone."', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.239Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1399, 1, NULL, NULL, 'Rearrange the parts in the correct sequence to form a meaningful sentence:

(A) frozen, canned, and dried fruits can be

(B) despite the enduring belief that

(C) just as nutritious as their fresh counterparts

(D) ''fresh is best'', research has found that', NULL, '[{"text":"(A), (B), (C), (D)","image_url":null,"alt":null},{"text":"(A), (C), (D), (B)","image_url":null,"alt":null},{"text":"(B), (D), (A), (C)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is Option 3.
Key Points

The statement is about comparing the nutritional value of frozen, canned, and dried fruits to fresh fruits.

• Sentence B is the first sentence as it introduces the common belief:

○ "Despite the enduring belief that"

• Sentence D follows as it presents the research findings that challenge the belief:

o "''fresh is best'', research has found that"

• Sentence A is the third sentence because it specifies the types of fruits being discussed:

o "frozen, canned, and dried fruits can be"

• Sentence C is the fourth as it concludes the statement with the comparison:

☐ "just as nutritious as their fresh counterparts"

• The correct sequence is BDAC.

Coherent sentence after rearrangement:

"Despite the enduring belief that ''fresh is best'', research has found that frozen, canned, and dried fruits can be just as nutritious as their fresh counterparts."', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.239Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
