INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1402, 1, NULL, NULL, 'Choose the correct synonym of the word ''effrontery'':', NULL, '[{"text":"audacity","image_url":null,"alt":null},{"text":"civility","image_url":null,"alt":null},{"text":"impetuosity","image_url":null,"alt":null},{"text":"affluence","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is: audacity.
Key Points

• The word "effrontery" means shameless or impudent boldness; lack of respect in a way that is shocking or rude. (धृष्टता, बेश्मा)

○ Example: He had the effrontery to challenge the teacher''s authority in front of the entire class.

• "Audacity" refers to the willingness to take bold risks; rude or disrespectful behavior. (साहस, धृष्टा)

Example: She had the audacity to argue with the manager about the new policy.

• Hence, we can infer that the synonym of ''effrontery'' is ''audacity''.

Therefore, the correct answer is: audacity.
Additional Information

Here are the other options explained along with their Hindi meanings and example sentences:

• Civility (शिष्टता): Polite and courteous behavior.

○ Example: He treated everyone with the utmost civility.

• Impetuosity (उत्वलोपन): Acting or done quickly and without thought or care.

• Example: His impetuosity often got him into trouble.

• Affluence (สมาคม): The state of having a great deal of money; wealth.

○ Example: The affluence of the neighborhood was evident in the large houses and expensive cars.

Question: Choose the correct synonym of the word ''effrontery'':

The correct answer is: audacity.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.240Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1403, 1, NULL, NULL, 'Choose the correct antonym of the underlined word: She is an $ \underline{\text{astute}} $ observer of human behaviour.', NULL, '[{"text":"sharp","image_url":null,"alt":null},{"text":"brilliant","image_url":null,"alt":null},{"text":"ingenuous","image_url":null,"alt":null},{"text":"prudent","image_url":null,"alt":null}]', NULL, 2, 'The correct answer is: ingenuous.
Key Points

• The word "astute" means having or showing an ability to accurately assess situations or people and turn this to one''s advantage. (चतुर)

Example: She is an astute investor who always makes profitable decisions.

• "Ingenuous" refers to being innocent and unsuspecting, lacking in craftiness or deceit. (भोली)

• Example: His ingenuous smile made everyone trust him immediately.

• Hence, we can infer that the opposite of ''astute'' is ''ingenuous''.

Therefore, the correct answer is: ingenuous.
Additional Information

