• Prudent (দ্বিকো): Acting with or showing care and thought for the future.

Example: It is prudent to save some money for emergencies.

Question: Choose the correct antonym of the underlined word: She is an astute observer of human behaviour.

Therefore, the correct answer is: ingenuous.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1404, 1, NULL, NULL, 'Rearrange the following parts of a sentence to form a meaningful sentence:

