INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1408, 1, NULL, NULL, 'Fill in the blanks in List I with the Phrasal verbs in List II :', NULL, '[{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{II}) $, (D) - $ (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{I}) $, (B) - $ (\\mathrm{II}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{III}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $ Answer: A","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is (A) - (II), (B) - (IV), (C) - (I), (D) - (III).
Key Points

• From the given options, only option 1 creates correct sentences.

Let''s look at the sentences:

○ (A) She is financially very smart and has got a few thousand rupees put away for her retirement.

''Put away'' means to save or store something for future use.

○ (B) He is clever, but his gruff exterior makes most people get put off by it.

Put off means to discourage or repel someone.

(C) I wonder how she puts up with his erratic behaviour.

''Puts up'' means to tolerate or endure something.

◦ (D) Every day she puts in ten to twelve hours of study; she will certainly crack the CAT exam.

''Puts in'' means to spend a certain amount of time doing something.

Hence, the correct answer is option 1.', NULL, NULL, 2024, '/local-papers/assets/english-2024-05-29-shift-1/q29-table-1.jpg', 'Table for question 29', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.246Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2024-05-29-shift-1/q29-table-1.jpg","alt":"Table for question 29","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
