INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1411, 1, NULL, NULL, 'Match the blanks in List-I with appropriate Homonyms in List-II', NULL, '[{"text":"(A) - $ IV $, (B) - $ III $, (C) - $ I $, (D) - $ II $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{II}) $, (D) - $ (\\mathrm{I}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{II}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{IV}) $","image_url":null,"alt":null},{"text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is ''$(A) - (III)$, $(B) - (IV)$, $(C) - (II)$, $(D) - (I)$.
