INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1453, 18, NULL, NULL, 'If $ 26^{th} $ January, 2020 was a Sunday, then what day of the week was it on $ 16^{th} $ March of that year?', NULL, '[{"text":"Sunday","image_url":null,"alt":null},{"text":"Monday","image_url":null,"alt":null},{"text":"Tuesday","image_url":null,"alt":null},{"text":"Wednesday Answer: B","image_url":null,"alt":null}]', NULL, 1, 'Given:26th January, 2020 was a Sunday

