INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1460, 18, NULL, NULL, 'What will be the next number of the series

3, 6, 10.5, 17, 26, ?', NULL, '[{"text":"31","image_url":null,"alt":null},{"text":"38","image_url":null,"alt":null},{"text":"40","image_url":null,"alt":null},{"text":"41","image_url":null,"alt":null}]', NULL, 1, 'The logic followed here is:

Hence, "Option 2" is the correct answer.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.293Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1461, 18, NULL, NULL, 'In a class of 40 students, Anjali''s rank is thrice that of Anita. There are 4 students who have ranks worse than that of Anjali. Anita''s rank in the class is :', NULL, '[{"text":"$ 9^{th} $","image_url":null,"alt":null},{"text":"$ 10^{th} $","image_url":null,"alt":null},{"text":"$ 18^{th} $","image_url":null,"alt":null},{"text":"$ 12^{th} $","image_url":null,"alt":null}]', NULL, 3, 'Given: Class of 40 students

1) There are 4 students who have ranks worse than that of Anjali.

2) Anjali''s rank is thrice that of Anita.

Anjali''s rank = $ 3 \times $ Anita''s rank

36 = 3 × Anita''s rank

Anita''s rank = 12 (from top)

Thus, Anita''s rank is 12th in the class.

Hence, "Option 4" is the correct answer.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.294Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1462, 18, NULL, NULL, 'Six people E, H, K, M, S and U are seated in a circle facing the centre. U and H are immediate neighbours of M. E is the only person sitting between K and S. H is to the immediate right of S. Who is to the immediate right of U?', NULL, '[{"text":"M","image_url":null,"alt":null},{"text":"E","image_url":null,"alt":null},{"text":"K","image_url":null,"alt":null},{"text":"S","image_url":null,"alt":null}]', NULL, 0, 'Given:Six peopleE, H, K, M, S and U are seated in a circle facing the centre.

1)E is the only person sitting between K and S.

2) H is to the immediate right of S.

E

3) U and H are immediate neighbours of M.

Thus, according to the final arrangement, M is to the immediate right of U. Hence, "Option 1" is the correct answer.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.295Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1463, 18, NULL, NULL, 'Simplify: $ 24 \div 4 \times 2 + 8 - 4 = ? $', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null},{"text":"56","image_url":null,"alt":null}]', NULL, 2, 'Calculation:

$ 24 \div 4 \times 2 + 8 - 4 = ? $

$ \Rightarrow 6 \times 2 + 4 = ? $

$ \Rightarrow 12 + 4 = ? $

$ \Rightarrow 16 $

The correct answer is', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.296Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1464, 18, NULL, NULL, 'The difference of the greatest and the smallest of the fractions $ \frac{1}{2} $, $ \frac{8}{11} $, $ \frac{7}{8} $, $ \frac{7}{9} $, $ \frac{5}{6} $ is:', NULL, '[{"text":"$ \\frac{3}{8} $","image_url":null,"alt":null},{"text":"$ \\frac{6}{7} $","image_url":null,"alt":null},{"text":"$ \\frac{7}{9} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{3} $","image_url":null,"alt":null}]', NULL, 0, 'Given:

Fractions: 1/2, 8/11, 7/8, 7/9, 5/6

Convert all to decimal for easy comparison:

1/2 = 0.50

8/11 ≈ 0.727

7/8 = 0.875

7/9 ≈ 0.778

5/6 ≈ 0.833

Greatest = 7/8 = 0.875

Smallest = 1/2 = 0.50

Difference = 0.875 - 0.50 = 0.375

Convert back to fraction: 0.375 = 3/8

∴ The difference is $ \underline{3/8} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.297Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1465, 18, NULL, NULL, 'The sum of LCM and HCF of two numbers is 854. If the LCM is 60 times the HCF and one of the numbers is 70, then the other number is', NULL, '[{"text":"160","image_url":null,"alt":null},{"text":"164","image_url":null,"alt":null},{"text":"168","image_url":null,"alt":null},{"text":"172","image_url":null,"alt":null}]', NULL, 2, 'Given:
LCM + HCF = 854
LCM = 60 \times HCF
One number = 70
Calculation:
Let HCF = x \Rightarrow LCM = 60x
So, x + 60x = 854
$ \Rightarrow $ 61x = 854
$ \Rightarrow $ x = 854 \div 61 = 14
So, HCF = 14, LCM = 60 \times 14 = 840
Use formula: Product of two numbers = HCF \times LCM
$ \Rightarrow $ 70 \times other number = 14 \times 840
$ \Rightarrow $ other number = (14 \times 840) \div 70
$ \Rightarrow $ other number = 11760 \div 70 = 168
∴ The other number is $ \underline{168} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.298Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1466, 18, NULL, NULL, 'The present age of Harish is 8 times the sum of the ages of his two sons at present. After 8 years, his age will be 2 times the sum of the ages of his two sons. The present age of Harish (in years) is :', NULL, '[{"text":"31","image_url":null,"alt":null},{"text":"32","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null},{"text":"34","image_url":null,"alt":null}]', NULL, 1, 'Given:

Let the present age of Harish be = H

Let the present age of Harish''s son''s (two sons) be = S

1) The present age of Harish is 8 times the sum of the ages of his two sons at present.

H = 8S _ (I)

2) After 8 years, his age will be 2 times the sum of the ages of his two sons.

H + 8 = 2 (S + 16), Here, ''16'' is added instead of 8, because there are two sons $ 8 \times 2 = 16 $

H + 8 = 2S + 32

H-2S=24 (II)

Putting, the value of H in equation (II):

H-2S=24

8S-2S=24

6S = 24

S=4

So, Putting, the value of S in equation (I):

H=8\times4

H = 32 years

Hence, "Option 2" is the correct answer.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.299Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1467, 18, NULL, NULL, 'In a class of 40 students, ratio of boys and girls is 3:2 and the average marks scored by boys is 42 and that by girls is 46. Then the average marks scored by the whole class is:', NULL, '[{"text":"43.4","image_url":null,"alt":null},{"text":"43.6","image_url":null,"alt":null},{"text":"43.8","image_url":null,"alt":null},{"text":"44","image_url":null,"alt":null}]', NULL, 1, 'Given:
Total number of students = 40
Ratio of boys to girls = 3 : 2
Average marks scored by boys = 42
Average marks scored by girls = 46
Formula Used:
Average marks of the whole class = $ (Total marks scored by boys + Total marks scored by girls) / Total number of students $
Calculation:
Number of boys = $ (3/5) \times 40 = 24 $
Number of girls = $ (2/5) \times 40 = 16 $
Total marks scored by boys = $ 24 \times 42 = 1008 $
Total marks scored by girls = $ 16 \times 46 = 736 $
Total marks scored by the whole class = 1008 + 736 = 1744
Average marks of the whole class = 1744 / 40
Average marks of the whole class = 43.6
The average marks scored by the whole class is 43.6.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.299Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1468, 18, NULL, NULL, 'The sum of three numbers is 136. If the ratio between the first number and the second number is 2:3 and that between the second and the third number is 5:3, then the first number is:', NULL, '[{"text":"42","image_url":null,"alt":null},{"text":"40","image_url":null,"alt":null},{"text":"36","image_url":null,"alt":null},{"text":"32","image_url":null,"alt":null}]', NULL, 0, 'Given:

Sum of three numbers = 136

First : Second = 2 : 3

Second : Third = 5 : 3

Calculation:

Combine ratios using the common term (second number):

First : Second = 2 : 3 = 10 : 15 (×5)

Second : Third = 5 : 3 = 15 : 9 (×3)

⇒ Combined ratio: First : Second : Third = 10 : 15 : 9

Total parts = 10 + 15 + 9 = 34

Value of 1 part = 136 ÷ 34 = 4

First number = 10 × 4 = 40

∴ The first number is $ \underline{40} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.299Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1469, 18, NULL, NULL, 'An item is sold for ₹504 after allowing 20% discount and still a profit of 5% has been earned. The marked price is how much more than the cost price?', NULL, '[{"text":"₹120","image_url":null,"alt":null},{"text":"₹135","image_url":null,"alt":null},{"text":"₹150","image_url":null,"alt":null},{"text":"₹160","image_url":null,"alt":null}]', NULL, 2, 'Given:

Selling Price (SP) = ₹504

Discount = 20%

Profit = 5%

Formula used:

SP = MP × (1 - Discount%)

SP = CP × (1 + Profit%)

We need to find MP - CP

Calculation:

Let Cost Price (CP) = x

SP = x × (1 + 5/100) = 1.05x

⇒ 1.05x = 504 ⇒ x = 504 ÷ 1.05 = 480

Now, SP = MP × 80% ⇒ 504 = 0.8 × MP

⇒ MP = 504 ÷ 0.8 = 630

Required difference = MP - CP = 630 - 480 = 150

∴ The marked price is ₹150 more than the cost price', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.300Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1470, 18, NULL, NULL, 'A certain sum becomes ₹2,356 in 3 years and ₹2,660 in 5 years on simple interest. The value of sum is :', NULL, '[{"text":"₹1,800","image_url":null,"alt":null},{"text":"₹1,880","image_url":null,"alt":null},{"text":"₹1,900","image_url":null,"alt":null},{"text":"₹1,980","image_url":null,"alt":null}]', NULL, 0, 'Given:

Amount after 3 years = ₹2,356

Amount after 5 years = ₹2,660

Formula used:

Simple Interest (SI) = Amount - Principal

Calculation:

Difference in SI over 2 years = ₹2,660 - ₹2,356 = ₹304

SI per year = 304 ÷ 2 = ₹152

Total SI for 3 years = 152 × 3 = ₹456

Principal = Amount - SI = 2356 - 456 = ₹1,900

∴ The value of the sum is ₹1,900', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.300Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1471, 18, NULL, NULL, 'In a square, lengths of the diagonals are $ (4k+6) $ cm and $ (7k-3) $ cm. The area of the square $ (in\ cm^{2}) $ is :', NULL, '[{"text":"144","image_url":null,"alt":null},{"text":"162","image_url":null,"alt":null},{"text":"169","image_url":null,"alt":null},{"text":"172","image_url":null,"alt":null}]', NULL, 1, 'Given:

Diagonals of a square: $ (4k + 6) $ cm and $ (7k - 3) $ cm

Property used:

In a square, both diagonals are equal.

Formula used:

Area of square = (Diagonal $ ^{2} $) \div 2

Calculation:

Equating diagonals:

$ 4k + 6 = 7k - 3 $

$ \Rightarrow 6 + 3 = 7k - 4k $

$ \Rightarrow 9 = 3k \Rightarrow k = 3 $

Now, diagonal = $ 4k + 6 = 4 \times 3 + 6 = 18 \, cm $

Area = $ (18 \times 18) \div 2 = 324 \div 2 = 162 \, cm^{2} $

∴ Area of the square is $ \underline{162} $ cm $ ^{2} $.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.301Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1472, 18, NULL, NULL, 'The volume of a cylinder having base radius 3 cm is $ 396 \, \text{cm}^3 $. Find its curved surface area (in $ \text{cm}^2 $).

(Use $ \pi = \frac{22}{7} $)', NULL, '[{"text":"280","image_url":null,"alt":null},{"text":"301.5","image_url":null,"alt":null},{"text":"264","image_url":null,"alt":null},{"text":"320.6","image_url":null,"alt":null}]', NULL, 2, 'Given:

Volume of cylinder = 396 cm³

Radius (r) = 3 cm

$ \pi = 22/7 $

Formula used:

Volume of cylinder = $ \pi \times r^{2} \times h $

Curved Surface Area (CSA) = $ 2 \times \pi \times r \times h $

Calculation:

396 = $ (22/7) \times 3^{2} \times h $

$ \Rightarrow 396 = (22/7) \times 9 \times h $

$ \Rightarrow 396 = (198/7) \times h $

$ \Rightarrow h = (396 \times 7) \div 198 = 2772 \div 198 = 14 \, cm $

CSA = $ 2 \times (22/7) \times 3 \times 14 $

$ \Rightarrow $ CSA = $ 2 \times (22/7) \times 42 = (44 \times 42) \div 7 = 1848 \div 7 = 264 \, cm^{2} $

$ \therefore $ Curved Surface Area = $ \underline{\text{264 cm²}} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.301Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1473, 18, NULL, NULL, 'A tap can fill a tank in 6 hours. After half the tank is filled, three more similar taps are opened. What is the total time taken to fill the tank completely?', NULL, '[{"text":"4 hours","image_url":null,"alt":null},{"text":"5 hours","image_url":null,"alt":null},{"text":"3 hours 30 minutes","image_url":null,"alt":null},{"text":"3 hours 45 minutes","image_url":null,"alt":null}]', NULL, 3, 'Given:

1 tap fills the tank in 6 hours.

After half the tank is filled, 3 more similar taps are opened (total 4 taps).

Calculation:

Total capacity of tank = LCM of 6 = 6 units

$ \Rightarrow $ 1 tap fills $ 6 \div 6 = 1 $ unit per hour

Half of the tank = 3 units

Time taken by 1 tap to fill 3 units = $3 \div 1 = 3$ hours

Now 4 taps work together

4 taps fill = 4 × 1 = 4 units per hour

Remaining = 3 units

Time = 3 ÷ 4 = 3/4 hour = 45 minutes

Total time = 3 hours + 45 minutes = $ \underline{\text{3 hours 45 minutes}} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.302Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1474, 18, NULL, NULL, 'A train running at the speed of 80 km/h crosses a 350 m long tunnel in 36 seconds. The length of the train (in m) is', NULL, '[{"text":"350","image_url":null,"alt":null},{"text":"380","image_url":null,"alt":null},{"text":"420","image_url":null,"alt":null},{"text":"450","image_url":null,"alt":null}]', NULL, 3, 'Given:

Speed of train = 80 km/h

Time to cross tunnel = 36 seconds

Length of tunnel = 350 m

Formula used:

Speed = Distance ÷ Time

Total distance = Length of train + Length of tunnel

Calculation:

Convert speed to m/s

80 km/h = (80 × 1000) ÷ 3600 = 80000 ÷ 3600 = 22.22 m/s

Total distance = Speed × Time = 22.22 × 36 ≈ 800 m

Length of train = Total distance - Tunnel length = 800 - 350 = 450 m

∴ Length of the train is $ \underline{\text{450 metres}} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.302Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1475, 18, NULL, NULL, 'If the mean of 3, 4, 9, 2k, 10, 8, 6 and $ (k+6) $ is 8, and mode of 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5 and 6 (p is a natural number) is 4, then the value of $ (k-2p) $ is :', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null}]', NULL, 2, 'Given:
Mean of: 3, 4, 9, 2k, 10, 8, 6, $ (k+6)=8 $
Mode of: 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5, 6 = 4
Formula used:
Mean = (Sum of all terms) ÷ (Number of terms)
Mode = Value occurring most frequently
Calculation:
Solve for k
Sum = 3 + 4 + 9 + 2k + 10 + 8 + 6 + (k + 6) = 46 + 3k
Mean = $ (46 + 3k) \div 8 = 8 $
$ \Rightarrow 46 + 3k = 64 $
$ \Rightarrow 3k = 18 $
$ \Rightarrow k = 6 $
Solve for p
Numbers: 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5, 6
Mode is $ 4 \Rightarrow 4 $ must occur most frequently

Try p = 1 ⇒ 2p = 2, 2p+1 = 3 ⇒ list: 2, 2, 3, 2, 3, 4, 4, 5, 6

2 occurs 3 times ⇒ mode = 2

Try p = 2 ⇒ 2p = 4, 2p+1 = 5 ⇒ list: 2, 2, 3, 4, 5, 4, 4, 5, 6

4 occurs 3 times ⇒ mode = 4

⇒ p = 2

Find k - 2p:

k = 6, p = 2 ⇒ k - 2p = 6 - 4 = 2

∴ The value of (k - 2p) is 2', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.303Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1476, 18, NULL, NULL, 'In triangle ABC, points D and E are on AB and AC respectively such that DE is parallel to BC. If AD = 6 cm, DB = 4 cm, AE = 9 cm, then the length of EC (in cm) is', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"6.4","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"5.5","image_url":null,"alt":null}]', NULL, 2, 'Given:

In triangle ABC:

Points D and E lie on AB and AC respectively

DE $ \parallel $ BC

AD = 6 cm, DB = 4 cm $ \Rightarrow $ AB = AD + DB = 10 cm

AE = 9 cm
Concept used:

By Basic Proportionality Theorem (Thales'' Theorem):

If a line is drawn parallel to one side of a triangle intersecting the other two sides, then it divides those sides in the same ratio.
Formula used:

AD/DB=AE/EC

Calculation:

$$ 6\ /4=9\ /EC $$

$ \Rightarrow 3/2 = 9/EC $

$ \Rightarrow EC = (2 \times 9) \div 3 = 18 \div 3 = 6 \, \text{cm} $

$ \therefore $ The length of EC is $ \underline{6} $ cm', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.303Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1477, 18, NULL, NULL, 'The sum of the digits of a two-digit number is 10. If 18 is subtracted from it, the digits in the resulting number will be equal. The number is :', NULL, '[{"text":"75","image_url":null,"alt":null},{"text":"73","image_url":null,"alt":null},{"text":"65","image_url":null,"alt":null},{"text":"64","image_url":null,"alt":null}]', NULL, 3, 'Given:

The sum of the digits of a two-digit number is 10.

If 18 is subtracted from it, the digits in the resulting number will be equal.

Formula Used:

Let the two-digit number be $ 10a + b $, where a and b are the digits of the number.

a + b = 10

(10a + b) - 18 = 10b + a
Calculation:

From the second equation:

10a + b - 18 = 10b + a

⇒ 10a - a + b - 10b = 18
⇒ 9a - 9b = 18
⇒ a - b = 2
Now, we have two equations:
1) a + b = 10
2) a - b = 2
Adding these two equations:
a + b + a - b = 10 + 2
⇒ 2a = 12
⇒ a = 6
Substitute a = 6 in equation 1:
6 + b = 10
⇒ b = 4
The number is 10a + b = 10×6 + 4 = 64
The number is 64.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.305Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1478, 18, NULL, NULL, 'In the given question, a statement is given followed by some conclusions. Choose the conclusion(s) which logically follow(s) the given statement.

Statement: Few shops on this road have neon lights, but they all have signboards.
Conclusions :

I. Some shops have either signboards or neon lights.

II. Some shops have no signboards.

III. Some shops have no neon lights.

IV. Some shops have both signboards and neon lights.

The conclusion(s) correctly drawn is/are :', NULL, '[{"text":"IV alone","image_url":null,"alt":null},{"text":"I alone","image_url":null,"alt":null},{"text":"II and III","image_url":null,"alt":null},{"text":"III and IV","image_url":null,"alt":null}]', NULL, 3, 'Given.

Statement:

Few shops on this road have neon lights, but they all have signboards.
Conclusions:

I. Some shops have either signboards or neon lights. - False(Because the statement says that Few shops on this road have neon lights, but they all have signboards. Therefore, all shops have signboards, and some of those shops have neon lights.)

II. Some shops have no signboards. - False (Because, the statement says that all shops have signboards.)

III. Some shops have no neon lights. - True (Because, the statement says that only a few shops have neon lights, implying that some shops do not have neon lights.)

IV. Some shops have both signboards and neon lights. - True (Because, the statement says that all shops have signboards and few have neon lights. Therefore, some shops have both signboards and neon lights)

So, Conclusions I, III and IV follow.

Hence, the correct answer is "Option 4" (III and IV).', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.306Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1479, 18, NULL, NULL, 'Anubhav spent 14% of his income on electricity bills, 28% on rent and 18% on shopping. If $ \frac{1}{4} $th remaining amount is Rs. 5120, how much did he spend on electricity bills?', NULL, '[{"text":"Rs.7160","image_url":null,"alt":null},{"text":"Rs.7168","image_url":null,"alt":null},{"text":"Rs.8160","image_url":null,"alt":null},{"text":"Rs.9000","image_url":null,"alt":null}]', NULL, 1, 'Anubhav spent 14% of his income on electricity bills, 28% on rent, and 18% on shopping.

$ \frac{1}{4} $th of the remaining amount is Rs. 5120.

Formula Used:

Total Income = Total Expenses + Remaining Amount

Remaining Amount = Total Income - (Electricity Bills + Rent + Shopping)

Electricity Bills = 14% of Total Income

Calculation:

Let Anubhav''s total income be x.

Expenses on electricity bills = 14% of x = 0.14x

Expenses on rent = 28% of x = 0.28x

Expenses on shopping = 18% of x = 0.18x

Remaining Amount = x - (0.14x + 0.28x + 0.18x)

Remaining Amount = x - 0.60x = 0.40x

$ \frac{1}{4} $th of Remaining Amount = Rs. 5120

$ \frac{1}{4} $ $ \times $ 0.40x = 5120

$ 0.10x = 5120 $

$ \Rightarrow x = 5120 / 0.10 $

$ \Rightarrow x = 51200 $

Anubhav''s total income = Rs. 51200

Expenses on electricity bills = 14% of 51200

$ \Rightarrow 0.14 \times 51200 = 7168 $

Therefore, Anubhav spent Rs. 7168 on electricity bills.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.306Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1480, 18, NULL, NULL, 'If the average of p numbers is $ q^2 $ and that of q numbers is $ p^2 $, then the average of $ (p + q) $ numbers is :', NULL, '[{"text":"$ \\frac{p}{q} $","image_url":null,"alt":null},{"text":"$ p + q $","image_url":null,"alt":null},{"text":"pq","image_url":null,"alt":null},{"text":"p - q","image_url":null,"alt":null}]', NULL, 2, 'Given:

The average of p numbers = q^{2}

The average of q numbers = p^{2}

Formula Used:

Average of $ (p + q) $ numbers = (Sum of p numbers + Sum of q numbers) / (p + q)

Calculation:

Sum of p numbers = $ p \times q^{2} $

Sum of q numbers = q × p²

Total Sum = p × q² + q × p²

Total numbers = p + q

Average of (p + q) numbers = (p × q² + q × p²) / (p + q)

Average of (p + q) numbers = pq(p + q) / (p + q)

Average of (p + q) numbers = pq

The correct answer is option 3.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.307Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1481, 18, NULL, NULL, 'Ajay walks at a speed of 4 km/hr. He doubles his speed after reaching exactly half way. He walks for 12 hours in all. What is the total distance travelled by him?', NULL, '[{"text":"32 km","image_url":null,"alt":null},{"text":"30 km","image_url":null,"alt":null},{"text":"64 km","image_url":null,"alt":null},{"text":"60 km","image_url":null,"alt":null}]', NULL, 2, 'Given:

Ajay''s initial speed = 4 km/hr

Total time walked = 12 hours

He doubles his speed after reaching halfway.

Formula Used:

Total Distance = Distance at initial speed + Distance at doubled speed
Calculation:

Let the total distance be D km.
Time to cover the first half (D/2) at 4 km/hr:
Time = Distance / Speed
Time $ _{1} $ = (D/2) / 4
Time $ _{1} $ = D / 8
Time to cover the second half (D/2) at 8 km/hr:
Time $ _{2} $ = (D/2) / 8
Time $ _{2} $ = D / 16
Total time walked = Time $ _{1} $ + Time $ _{2} $
12 = D / 8 + D / 16
$ \Rightarrow $ 12 = (2D + D) / 16
$ \Rightarrow $ 12 = 3D / 16
$ \Rightarrow $ 12 $ \times $ 16 = 3D
$ \Rightarrow $ 192 = 3D
$ \Rightarrow $ D = 192 / 3
$ \Rightarrow $ D = 64 km
The total distance travelled by Aiay is 64 km.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.307Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1482, 18, NULL, NULL, 'A shopkeeper earned a profit (in ₹) by selling an item, which is three times the discount offered (in ₹). If the discount offered is 6.25%, what is his profit percentage?', NULL, '[{"text":"20%","image_url":null,"alt":null},{"text":"25%","image_url":null,"alt":null},{"text":"10%","image_url":null,"alt":null},{"text":"12%","image_url":null,"alt":null}]', NULL, 1, 'Given:
Discount % = 6.25%
Profit = $ 3 \times $ Discount
Formula used:
Profit % = $ \frac{Profit}{CostPrice} \times 100 $
Calculation:
Let MRP = ₹100
Discount = 6.25% of 100 = ₹6.25
Selling Price = 100 - 6.25 = ₹93.75
Profit = $ 3 \times 6.25 = 18.75 $
Cost Price = 93.75 - 18.75 = ₹75
Profit % = $ \frac{18.75}{75} \times 100 $
⇒ Profit % = 25%
∴ The correct answer is option (2).', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.307Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1483, 18, NULL, NULL, 'The total population of a town is 50,000. The number of males and females increases by 10% and 15% respectively and consequently the

population of the town becomes 56,000. What was the number of males in the town?', NULL, '[{"text":"20,000","image_url":null,"alt":null},{"text":"30,000","image_url":null,"alt":null},{"text":"35,000","image_url":null,"alt":null},{"text":"40,000","image_url":null,"alt":null}]', NULL, 1, 'Given:

Total population of the town = 50,000

Population after increase = 56,000

Increase in males = 10%

Increase in females = 15%

Calculation:

Let the number of males be M.

Let the number of females be F.

Total population: $ M + F = 50,000 $

After increase: $ M \times 1.10 + F \times 1.15 = 56,000 $

We have two equations:

1) $ M + F = 50,000 $

2) $ 1.10M + 1.15F = 56,000 $

From equation (1): $ F = 50,000 - M $

Substitute F in equation (2):

$ 1.10M + 1.15(50,000 - M) = 56,000 $

Simplify:

$ 1.10M + 57,500 - 1.15M = 56,000 $

$$ \Rightarrow-0.05M+57,500=56,000 $$

$$ \Rightarrow-0.05\mathrm{M}=56,000-57,500 $$

$$ \Rightarrow-0.05M=-1,500 $$

$$ \Rightarrow\mathrm{M}=-1,500\ /-0.05 $$

$$ \Rightarrow M=30,000 $$

The number of males in the town was 30,000.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.308Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1484, 18, NULL, NULL, 'A 6-digit number has digits as consecutive natural numbers. The number is always divisible by :', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null}]', NULL, 0, 'Given:

A 6-digit number is formed using consecutive natural numbers.

Formula used:

Any number with digits as consecutive natural numbers (e.g., 123456, 234567, etc.) follows a pattern and must be tested for divisibility.

Calculation:

Take example: 123456

Check divisibility:

$ 123456 \div 3 = 41152 \rightarrow \text{divisible} $

123456 ÷ 6 = 20576 → divisible

123456 ÷ 9 = 13717.33 → not divisible

Try another: 234567

234567 ÷ 3 = 78189 → divisible

234567 ÷ 6 = 39094.5 → not divisible

So only consistent divisibility for all such numbers is by 3

∴ The correct answer is option (2) 3.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.308Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1485, 18, NULL, NULL, 'The average of 101 consecutive odd numbers is 303. Find the largest number.', NULL, '[{"text":"373","image_url":null,"alt":null},{"text":"401","image_url":null,"alt":null},{"text":"403","image_url":null,"alt":null},{"text":"409","image_url":null,"alt":null}]', NULL, 2, 'Given:

Average of 101 consecutive odd numbers = 303

Formula used:

Average = Middle term (when count is odd)

Largest number = Middle term + (n - 1)/2 × 2

Calculation:

Middle term = 303

Total numbers = 101

⇒ Largest number = 303 + (101 - 1)/2 × 2
⇒ Largest number = 303 + 50 × 2
⇒ Largest number = 303 + 100
⇒ Largest number = 403
∴ The correct answer is 403.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.308Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1486, 18, NULL, NULL, 'If A : B = 5 : 6 and B : C = 6 : 7, then A + B : B + C : A + C is :', NULL, '[{"text":"10:12:11","image_url":null,"alt":null},{"text":"9:11:10","image_url":null,"alt":null},{"text":"11:13:12","image_url":null,"alt":null},{"text":"19:21:20","image_url":null,"alt":null}]', NULL, 2, 'Given:
If A : B = 5 : 6 and B : C = 6 : 7,
Formula Used:
If A : B = p : q and B : C = r : s, then A : B : C = p : q : (qs / r)
Calculation:
A : B = 5 : 6
B : C = 6 : 7
$ \Rightarrow $ A : B : C = 5 : 6 : (7)
Let A = 5k, B = 6k, C = 7k
$ \Rightarrow $ A + B = 5k + 6k = 11k

⇒ B + C = 6k + 7k = 13k

⇒ A + C = 5k + 7k = 12k

Therefore, A + B : B + C : A + C = 11k : 13k : 12k

⇒ A + B : B + C : A + C = 11 : 13 : 12

The correct answer is option 3: 11 : 13 : 12', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.309Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1487, 18, NULL, NULL, 'Aman can do 50% of the job in 16 days, and Bhanu can do 25% of the job in 24 days. In how many days can they do $ \frac{1}{4} $th of the job working together?', NULL, '[{"text":"6 days","image_url":null,"alt":null},{"text":"8 days","image_url":null,"alt":null},{"text":"10 days","image_url":null,"alt":null},{"text":"12 day","image_url":null,"alt":null}]', NULL, 0, 'Given:

Aman does 50% job in 16 days $ \Rightarrow $ 100% in 32 days

Bhanu does 25% job in 24 days $ \Rightarrow $ 100% in 96 days

Formula used:

Work together rate = $ (1/Aman''s\ time)+(1/Bhanu''s\ time) $

Time = Work / Rate

Calculation:

Aman''s 1 day work = 1/32

Bhanu''s 1 day work = 1/96
⇒ Combined 1 day work = 1/32 + 1/96
⇒ LCM of 32 and 96 = 96
⇒ $ (3 + 1)/96 = 4/96 = 1/24 $
They complete 1/24 of job per day
Time to do 1/4 of job = $ (1/4) \div (1/24) $
$ \Rightarrow 1/4 \times 24 = 6 $ days
∴ The correct answer is 6 days.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.309Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1488, 18, NULL, NULL, 'In 80 litres mixture of milk and water, the ratio of amount of milk to that of amount of water is 7 : 3. In order to make this ratio 2 : 1, how many litres of water should be added?', NULL, '[{"text":"5 litres","image_url":null,"alt":null},{"text":"6 litres","image_url":null,"alt":null},{"text":"4 litres","image_url":null,"alt":null},{"text":"10 litres","image_url":null,"alt":null}]', NULL, 2, 'Given:

Total mixture = 80 litres

Milk : Water = 7 : 3

Target ratio = 2 : 1

Formula used:

Milk quantity remains unchanged, only water is added

Calculation:

Milk = (7/10) × 80 = 56 litres
Water = (3/10) × 80 = 24 litres
Let x litres of water be added
⇒ New water = 24 + x
⇒ New ratio = 56 : (24 + x) = 2 : 1
⇒ 56 / (24 + x) = 2 / 1
⇒ 56 = 2 × (24 + x)
⇒ 56 = 48 + 2x
⇒ 2x = 8
⇒ x = 4
∴ The correct answer is 4 litres.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.310Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1489, 18, NULL, NULL, 'In a triangle PQR, if $ \angle P + \angle R = 150^\circ $ and $ \angle P + 3\angle Q = 170^\circ $, then $ \angle P $ is equal to :', NULL, '[{"text":"$70^{\\circ}$","image_url":null,"alt":null},{"text":"$80^{\\circ}$","image_url":null,"alt":null},{"text":"$75^{\\circ}$","image_url":null,"alt":null},{"text":"$65^{\\circ}$","image_url":null,"alt":null}]', NULL, 1, 'Given:

In a triangle PQR, if $ \angle P + \angle R = 150^\circ $ and $ \angle P + 3\angle Q = 170^\circ $
Formula Used:

Sum of all angles in a triangle = $ 180^{\circ} $

Calculation:

Let \angle P = P, \angle Q = Q, and \angle R = R

Given:

$ P + R = 150^{\circ} \ldots (i) $

$ P + 3Q = 170^{\circ} \ldots (ii) $

From the sum of angles in a triangle:

$ P + Q + R = 180^{\circ} \ldots (iii) $

From (i), $ R = 150^{\circ} - P $

Substitute R in (iii):

$ P + Q + (150^{\circ} - P) = 180^{\circ} $

$ Q = 30^{\circ} $

Substitute Q in (ii):

$ P + 3 \times 30^{\circ} = 170^{\circ} $

$ P + 90^{\circ} = 170^{\circ} $

$ P = 80^{\circ} $

Therefore, \angle P is equal to 80^{\circ}.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.310Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1490, 18, NULL, NULL, 'Aman invested Rs. (P + 3000) for 3 years at 8% simple interest. Anuj invested an amount of Rs. P for 2 years at 12% compound interest and received the same amount of interest as Aman received. Find the amount that is invested by Anuj.', NULL, '[{"text":"$ \\Re","image_url":null,"alt":null},{"text":"\\Re","image_url":null,"alt":null},{"text":"\\Re","image_url":null,"alt":null},{"text":"\\Re $","image_url":null,"alt":null}]', NULL, 2, 'Given:
Aman''s investment = (P + 3000)
Time = 3 years, Rate = 8% (Simple Interest)
Anuj''s investment = P
Time = 2 years, Rate = 12% (Compound Interest)
Interest earned by both is same
Formula used:
SI = (P × R × T)/100
CI = P(1 + $ \frac{r}{100} $)^t - 1
Calculation:
Aman''s SI = (P + 3000) × 8 × 3 / 100
$ \Rightarrow $ Aman''s SI = (P + 3000) × 24 / 100
$ \Rightarrow $ Aman''s SI = (24P + 72000)/100
Anuj''s CI = P × [(1 + 12/100)^2 - 1]
$ \Rightarrow $ CI = P × [(1.12)^2 - 1]
$ \Rightarrow $ CI = P × [1.2544 - 1] = P × 0.2544
Equating both:
$ \Rightarrow $ (24P + 72000)/100 = 0.2544P
$ \Rightarrow $ 24P + 72000 = 25.44P
$ \Rightarrow $ 72000 = 25.44P - 24P
$ \Rightarrow $ 72000 = 1.44P
$ \Rightarrow $ P = 72000 / 1.44
$ \Rightarrow $ P = 50000', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.313Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1491, 18, NULL, NULL, 'In the Delhi zoo, there are some ducks and rabbits. If the heads are counted there are 160, while the legs are 450. What will be number of ducks in the zoo?', NULL, '[{"text":"90","image_url":null,"alt":null},{"text":"92","image_url":null,"alt":null},{"text":"95","image_url":null,"alt":null},{"text":"99","image_url":null,"alt":null}]', NULL, 2, 'Given:
Total heads = 160
Total legs = 450
Ducks have 2 legs, Rabbits have 4 legs
Formula used:
Let number of ducks = x, then rabbits = 160 - x
Total legs = (Ducks $ \times $ 2) + (Rabbits $ \times $ 4)
Calculation:
$ \Rightarrow 2x + 4(160 - x) = 450 $
$ \Rightarrow 2x + 640 - 4x = 450 $
$ \Rightarrow -2x + 640 = 450 $
$ \Rightarrow -2x = 450 - 640 $

$ \Rightarrow -2x = -190 $

$ \Rightarrow x = 95 $

∴ The number of ducks is 95.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.313Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1492, 18, NULL, NULL, 'Ankit and Raju decided to start a business and they invested Rs. 5500 and Rs. 6500 respectively. After 11 months, the difference between their profits is Rs. 680. Find the total profit.', NULL, '[{"text":"Rs.8160","image_url":null,"alt":null},{"text":"Rs.7260","image_url":null,"alt":null},{"text":"Rs.7000","image_url":null,"alt":null},{"text":"Rs.6500","image_url":null,"alt":null}]', NULL, 0, 'Given:

Ankit''s investment = ₹5500

Raju''s investment = ₹6500

Time = 11 months for both

Difference in profit = ₹680

Formula used:

Profit share ∝ Investment × Time

Difference in profit = (Raju''s share - Ankit''s share)

Calculation:

Ankit''s share = 5500 \times 11 = 60500

Raju''s share = 6500 \times 11 = 71500

Ratio = $ \frac{60500}{71500} = 121 : 143 $

Difference in ratio = 143 - 121 = 22 parts

$ \Rightarrow $ 22 parts = ₹680

$ \Rightarrow $ 1 part = ₹680 ÷ 22 = ₹30.91

Total parts = 121 + 143 = 264

Total profit = 264 $ \times $ 30.91 = ₹8160.24

∴ The total profit is approximately ₹8160', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.314Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1493, 18, NULL, NULL, 'PQR is a triangle. The bisectors of the internal angle $\angle Q$ and external angle $\angle R$ intersect at M. If $\angle QMR = 40^{\circ}$, then $\angle P$ is :', NULL, '[{"text":"$ 75^{\\circ} $","image_url":null,"alt":null},{"text":"$ 60^{\\circ} $","image_url":null,"alt":null},{"text":"$ 65^{\\circ} $","image_url":null,"alt":null},{"text":"$ 80^{\\circ} $","image_url":null,"alt":null}]', NULL, 3, 'Given:

$ \angle QMR = 40^{\circ} $, MQ and MR are internal and external angle bisectors

Formula used:

Triangle angle sum = $ \angle P + \angle Q + \angle R = 180^\circ $

Calculation:

$$ \angle QMR=\frac{1}{2}(\angle Q+180^\circ-\angle R) $$

$$ \Rightarrow40^{\circ}=\frac{1}{2}(\angle Q+180^{\circ}-\angle R) $$

$$ \Rightarrow80^{\circ}=\angle Q+180^{\circ}-\angle R $$

$$ \Rightarrow\angle Q=\angle R-100^{\circ} $$

$$ \Rightarrow\angle P+\angle Q+\angle R=180^{\circ} $$

$$ \Rightarrow\angle P+(\angle R-100^{\circ})+\angle R=180^{\circ} $$

$$ \Rightarrow\angle P=280^{\circ}-2\angle R $$

Let $\angle R = 100^{\circ}$, then $\angle P = 280^{\circ} - 200^{\circ} = 80^{\circ}$

∴ The correct answer is $ \angle P = 80^{\circ} $', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.315Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1494, 18, NULL, NULL, 'What is the name of the alloy which is obtained after mixing mercury with another metal?', NULL, '[{"text":"Solder","image_url":null,"alt":null},{"text":"Amalgam","image_url":null,"alt":null},{"text":"Duralumin","image_url":null,"alt":null},{"text":"Pewter","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is $ \underline{\text{Amalgam}} $.
Key Points

• An amalgam is an alloy of mercury with one or more other metals.

- These alloys are formed through the process of amalgamation, where mercury reacts with other metals.

• Amalgams are commonly used in dental fillings due to their durability and ease of application.

• They are also used in the extraction of precious metals like gold and silver from their ores.

- The use of amalgams dates back to ancient times and has been pivotal in various industrial applications.
Additional Information

• $ \underline{\text{Solder}} $

Solder is a fusible metal alloy used to join metal workpieces together.

o It typically consists of a combination of tin and lead, although other metals can be used.

- Solder is widely used in electronics to create strong, conductive joints.

• Duralumin

o Duralumin is an alloy primarily composed of aluminum and copper, with small amounts of manganese, magnesium, and iron.

o It is known for its lightweight and high strength, making it ideal for aerospace applications.

• $ \underline{\text{Pewter}} $

o Pewter is a malleable metal alloy, traditionally composed of tin with copper, antimony, and sometimes bismuth.

o It has been used for tableware and decorative objects for centuries.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.315Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1495, 18, NULL, NULL, 'Which state became the 25^{th} state of India on 30th May, 1987?', NULL, '[{"text":"Telangana","image_url":null,"alt":null},{"text":"Haryana","image_url":null,"alt":null},{"text":"Gujarat","image_url":null,"alt":null},{"text":"Goa","image_url":null,"alt":null}]', NULL, 3, 'Key Points

• Goa became the 25th state of India on 30th May 1987.

• Prior to this, Goa was a Union Territory along with Daman and Diu.

• On 30th May 1987, Goa was granted statehood, while Daman and Diu remained a Union Territory.

• It is the smallest state in India by area and the fourth smallest by population.

• Goa is known for its tourism, with its beaches, Portuguese heritage, and vibrant culture.

• The capital of Goa is Panaji, and its largest city is Vasco da Gama.
Additional Information

• Telangana

Telangana was formed on 2nd June 2014, making it the 29th state of India.

o It was carved out of the northwestern part of Andhra Pradesh.

o The capital city is Hyderabad.

• $ \underline{\text{Haryana}} $

Haryana was formed on 1st November 1966.

o It was carved out from the state of Punjab.

o The capital city is Chandigarh, which is also the capital of Punjab.

• $ \underline{\text{Gujarat}} $

o Gujarat was formed on 1st May 1960.

o It was created out of the state of Bombay.

o The capital city is Gandhinagar.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.316Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1496, 18, NULL, NULL, 'Which of these temples is not located in Uttarakhand?', NULL, '[{"text":"Nanda Devi","image_url":null,"alt":null},{"text":"Surkanda Devi","image_url":null,"alt":null},{"text":"Kalighat Kali","image_url":null,"alt":null},{"text":"Tungnath","image_url":null,"alt":null}]', NULL, 2, 'The Correct answer is $ \underline{\text{Kalighat Kali}} $.
Key Points

• Kalighat Kali temple is located in Kolkata, West Bengal, and not in Uttarakhand.

• It is one of the 51 Shakti Peethas in India, dedicated to Goddess Kali.

• The temple is situated on the banks of the Adi Ganga, a small canal that connects to the Hooghly River.

- Kalighat is an important pilgrimage site and is believed to be over 200 years old.

• The temple attracts millions of devotees each year, especially during the festival of Kali Puja.
Additional Information

• Nanda Devi

o Nanda Devi temple is located in Uttarakhand, India.

o The temple is dedicated to Goddess Nanda Devi, the presiding deity of the region.

It is a significant part of the Nanda Devi Raj Jat Yatra, a grand pilgrimage that takes place every 12 years.

• Surkanda Devi

o The Surkanda Devi temple is located near Dhanaulti in Uttarakhand.

o It is dedicated to Goddess Parvati and is part of the Kedarkhand region of the Skanda Purana.

The temple offers a panoramic view of the Himalayas and is accessible after a 2 km trek from the village of Kaddukhal.

• Tungnath

Tungnath is one of the highest Shiva temples in the world and is located in the Rudraprayag district of Uttarakhand.

o It is part of the Panch Kedar pilgrimage circuit.

Legend has it that the temple was built by the Pandavas to atone for their sins after the Kurukshetra war.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.317Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1497, 18, NULL, NULL, 'Which of these states do not share a border with Chhattisgarh?', NULL, '[{"text":"Karnataka","image_url":null,"alt":null},{"text":"Madhya Pradesh","image_url":null,"alt":null},{"text":"Telangana","image_url":null,"alt":null},{"text":"Jharkhand","image_url":null,"alt":null}]', NULL, 0, 'The Correct answer is $ \underline{\text{Karnataka}} $.
Key Points

• Chhattisgarh is a state located in central India and shares its borders with several states.

- The states that share a border with Chhattisgarh are Madhya Pradesh to the northwest, Uttar Pradesh to the north, Jharkhand to the northeast, Odisha to the east, Telangana to the south, and Maharashtra to the southwest.

• Karnataka is located in the southwestern region of India and does not share a border with Chhattisgarh.

Understanding the geographical boundaries and neighboring states is crucial for various competitive exams.
Additional Information

• Madhya Pradesh

o Madhya Pradesh is a state located in the central part of India.

o It shares its borders with Chhattisgarh to the southeast.

• $ \underline{\text{Telangana}} $

o Telangana is a state in southern India.

o It shares its northern border with Chhattisgarh.

• $ \underline{\text{Jharkhand}} $

o Jharkhand is a state located in eastern India.

o It shares its western border with Chhattisgarh.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.317Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1498, 18, NULL, NULL, 'Which bowler became second Indian bowler to take 500 wickets in Test matches in February, 2024?', NULL, '[{"text":"Harbhajan Singh","image_url":null,"alt":null},{"text":"Ravichandran Ashwin","image_url":null,"alt":null},{"text":"Ishant Sharma","image_url":null,"alt":null},{"text":"Mohammed Shami","image_url":null,"alt":null}]', NULL, 1, 'The Correct answer is $ \underline{\text{Ravichandran Ashwin}} $.
Key Points

• Ravichandran Ashwin is an Indian international cricketer.

• He became the second Indian bowler to take 500 wickets in Test matches in February 2024.

- He is a right-arm off-break bowler known for his skill and variations.

He has been a crucial part of the Indian Test team and has performed consistently over the years.

- In addition to his bowling, Ashwin is also a useful lower-order batsman, making him a valuable all-rounder for the team.

His achievement places him among the elite bowlers in the history of cricket.
Additional Information

• Harbhajan Singh

o Harbhajan Singh is a former Indian cricketer and an off-spin bowler.

o He was the first Indian bowler to take 400 Test wickets.

o Harbhajan has been known for his aggressive and passionate style of play.

• Ishant Sharma

o Ishant Sharma is a right-arm fast bowler for the Indian cricket team.

o He is known for his height and ability to extract bounce from the pitch.

o Ishant has been a key bowler for India in Test cricket, especially in overseas conditions.

Mohammed Shami

Mohammed Shami is an Indian international cricketer who bowls right-arm fast.

o He is known for his pace, swing, and seam movement.

o Shami has been a vital part of the Indian pace attack in both Test and limited-overs cricket.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.318Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1499, 18, NULL, NULL, 'Which one of the following rivers is not included in ''Panchnad - The five rivers of Punjab''?', NULL, '[{"text":"The Luni","image_url":null,"alt":null},{"text":"The Jhelum","image_url":null,"alt":null},{"text":"The Chenab","image_url":null,"alt":null},{"text":"The Sutlej","image_url":null,"alt":null}]', NULL, 0, 'The correct answer is $ \underline{\text{The Luni}} $.
Key Points

• The Luni River is not included in the ''Panchnad'' - the five rivers of Punjab.

- Luni is a river in Rajasthan and is also known as the Sarasvati River in its upper course.

• The river is called Luni because of its high salinity.

- The Luni originates from the Naga hills in the Aravalli Range in Rajasthan and flows through the Thar Desert.

• It is an inland river that does not drain into any sea or ocean but ends in the Rann of Kutch.
Additional Information

• $ \underline{\text{The Jhelum}} $

o The Jhelum is one of the five rivers of Punjab.

- It originates from Verinag Spring at the foot of the Pir Panjal in the southeastern part of the Kashmir Valley.

o It flows through Kashmir and enters Pakistan.

• $ \underline{\text{The Chenab}} $

o The Chenab is another river included in the ''Panchnad''.

It is formed by the confluence of two rivers, Chandra and Bhaga, in the Lahaul and Spiti district of Himachal Pradesh.

o It flows through the Jammu region of Jammu and Kashmir.

• The Sutlej

The Sutlej is the longest of the five rivers that flow through the historic crossroad region of Punjab in northern India and Pakistan.

o It originates from Lake Rakshastal in Tibet.

o The Sutlej River merges with the Chenab River in Pakistan to form the Panjnad River.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.318Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1500, 18, NULL, NULL, 'Where was the $ 15^{th} $ BRICS Summit-2023 organised?', NULL, '[{"text":"South Africa","image_url":null,"alt":null},{"text":"Brazil","image_url":null,"alt":null},{"text":"Russia","image_url":null,"alt":null},{"text":"China","image_url":null,"alt":null}]', NULL, 0, 'The Correct answer is $ \underline{\text{South Africa}} $.

Key Points

• The 15th BRICS Summit in 2023 was organized in South Africa.

• BRICS is an acronym for an association of five major emerging economies: Brazil, Russia, India, China, and South Africa.

• South Africa hosted the summit in the city of Johannesburg.

- This summit aimed at strengthening cooperation among the BRICS countries in various fields such as economy, trade, and political coordination.

• The summit also focused on the theme of "BRICS and Africa: Partnership for Mutually Accelerated Growth, Sustainable Development, and Inclusive Multilateralism".

• South Africa''s role in BRICS is significant as it represents the African continent in the group.
Additional Information

• $ \underline{\text{Brazil}} $

Brazil is a member of BRICS and is the largest country in South America.

o It hosted the BRICS Summit previously, with the most recent one being the 11th BRICS Summit in 2019.

• Russia

o Russia is a founding member of BRICS.

o It hosted the 12th BRICS Summit in 2020.

• China

China, a key member of BRICS, hosted the 14th BRICS Summit in 2022.

China is the world''s most populous country and the second-largest economy.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.319Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1501, 18, NULL, NULL, 'Match List I with List II :', NULL, '[{"text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)","image_url":null,"alt":null},{"text":"(A) - (I), (B) - (IV), (C) - (III), (D) - (II)","image_url":null,"alt":null},{"text":"\\left(\\mathrm{A}\\right)-\\left(\\mathrm{II}\\right),\\left(\\mathrm{B}\\right)-\\left(\\mathrm{III}\\right),\\left(\\mathrm{C}\\right)-\\left(\\mathrm{IV}\\right),\\left(\\mathrm{D}\\right)-\\left(\\mathrm{I}\\right)","image_url":null,"alt":null}]', NULL, 3, 'The Correct answer is $ (\underline{\mathbf{A}})_{-(\underline{\mathbf{II}}),-(\underline{\mathbf{B}})_{-(\underline{\mathbf{III}}),-(\underline{\mathbf{C}})_{-(\underline{\mathbf{IV}}),-(\underline{\mathbf{D}})_{-(\underline{\mathbf{I}}})} $.
Key Points

• TheRs. 10 notefeatures theKonark Sun Temple, which is a 13th-century temple located in thePuri district of Odisha.

- The Rs. 100 note showcases the Rani Ki Vav, which is an intricately constructed stepwell situated in Gujarat. This stepwell is also a UNESCO World Heritage Site.

- The Rs. 500 note depicts the Red Fort, a historic fort in the city of Delhi that served as the main residence of the Mughal Emperors.

• TheRs. 20 notefeatures theEllora Caves. The Ellora Caves are a UNESCO World Heritage Site located in the Aurangabad district of Maharashtra.
Additional Information

• Ellora Caves

The Ellora Caves represent one of the largest rock-cut monastery-temple cave complexes in the world.

o They feature artworks from Buddhism, Hinduism, and Jainism.

• Rani Ki Vav

o Rani Ki Vav is an exceptional example of a distinctive form of subterranean water architecture of the Indian subcontinent.

o It was built as a memorial to an 11th-century AD king.

• Red Fort

The Red Fort is a symbol of India''s sovereignty and is the location where the Prime Minister hoists the national flag on Independence Day.

o It was designated a UNESCO World Heritage Site in 2007.

• Konark Sun Temple

The Konark Sun Temple is designed in the shape of a gigantic chariot with intricately carved stone wheels, pillars, and walls.

o It is dedicated to the Hindu Sun God Surya.', NULL, NULL, 2024, '/local-papers/assets/general-test-2024-05-29-shift-1/q28-table-1.jpg', 'Table for question 28', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.319Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2024-05-29-shift-1/q28-table-1.jpg","alt":"Table for question 28","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1502, 18, NULL, NULL, 'From the given options, name the longest river in Asia.', NULL, '[{"text":"Yangtze River","image_url":null,"alt":null},{"text":"Lena River","image_url":null,"alt":null},{"text":"Indus River","image_url":null,"alt":null},{"text":"Brahmaputra River Answer: A","image_url":null,"alt":null}]', NULL, 0, 'The Correct answer is $ \underline{\text{Yangtze River}} $.
Key Points

- Yangtze River is the longest river in Asia and the third-longest in the world, after the Nile and the Amazon.

• It has a total length of about 6,300 kilometers (3,917 miles).

- The river flows from the glaciers of the Qinghai-Tibet Plateau in China to the East China Sea at Shanghai.

- The Yangtze River basin is home to one-third of the population of China and is a major water source for agriculture, industry, and daily life.

- The river is also known for its diverse and rich ecosystem, which includes several endangered species like the Chinese alligator and the Yangtze river dolphin.

- It has significant historical and cultural importance in China, often referred to as the cradle of Chinese civilization.
Additional Information

• Lena River

o The Lena River is one of the longest rivers in the world and the longest river in Russia.

o It flows across eastern Siberia and eventually empties into the Arctic Ocean.

o The river has a length of about 4,400 kilometers (2,736 miles).

• Indus River

o The Indus River flows through China, India, and Pakistan.

o It is one of the longest rivers in the world, with a length of about 3,180 kilometers (1,976 miles).

o The river is crucial for agriculture and has been the cradle of the ancient Indus Valley Civilization.

• $ \underline{\text{Brahmaputra River}} $

o The Brahmaputra River flows through Tibet, India, and Bangladesh.

○ It has a length of about 2,900 kilometers (1,800 miles).

o The river is known for its strong currents and is also prone to flooding during the monsoon season.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.320Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1503, 18, NULL, NULL, 'Arrange the following important days according to their chronological order from January to December:', NULL, '[{"text":"Indian Airforce Day","image_url":null,"alt":null},{"text":"Kargil Victory Day","image_url":null,"alt":null},{"text":"World Soil Day","image_url":null,"alt":null},{"text":"National Youth Day E. International Women''s Day Select the correct answer from the options given below","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is $ \underline{\text{D - E - B - A - C}} $.
Key Points

• National Youth Day is observed on January 12. It marks the birth anniversary of Swami Vivekananda.

• International Women''s Day is celebrated on March 8 every year, highlighting the achievements and contributions of women globally.

• Kargil Victory Day is observed on July 26 to commemorate India''s victory over Pakistan in the Kargil War in 1999.

• Indian Airforce Day is celebrated on October 8 each year to mark the establishment of the Indian Air Force (IAF) in 1932.

- World Soil Day is observed on December 5 to raise awareness about the importance of soil health and sustainable management of soil resources.
Additional Information

• Swami Vivekananda

Swami Vivekananda was a key figure in the introduction of the Indian philosophies of Vedanta and Yoga to the Western world.

He is best known for his speech at the Parliament of the World''s Religions in Chicago in 1893, which began with "Sisters and brothers of America...".

• Indian Air Force

o The Indian Air Force (IAF) is the air arm of the Indian Armed Forces.

o Its primary mission is to secure Indian airspace and to conduct aerial warfare during armed conflict.

• $ \underline{\text{Kargil War}} $

o The Kargil War, also known as the Kargil conflict, was an armed conflict between India and Pakistan that took place between May and July 1999 in the Kargil district of Jammu and Kashmir.

During the conflict, the Indian Army, with the support of the Indian Air Force, recaptured most of the positions on the Indian side of the LOC (Line of Control) that had been occupied by Pakistani troops and militants.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.320Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1504, 18, NULL, NULL, 'Which Railway Minister from the following, resigned immediately after the 1956 Ariyalur train accident?', NULL, '[{"text":"Jagjivan Ram","image_url":null,"alt":null},{"text":"Lal Bahadur Shastri","image_url":null,"alt":null},{"text":"S.K. Patil","image_url":null,"alt":null},{"text":"Lalit Narayan Mishra","image_url":null,"alt":null}]', NULL, 1, 'The correct answer is $ \underline{\text{Lal Bahadur Shastri}} $.
Key Points

• Lal Bahadur Shastri was the Railway Minister of India during the Ariyalur train accident in 1956.

- The Ariyalur train accident occurred on November 23, 1956, in Tamil Nadu, resulting in significant casualties.

• As a mark of his moral responsibility, Lal Bahadur Shastri resigned from his position immediately after the accident.

His resignation was seen as a demonstration of ethical leadership and accountability.

- Lal Bahadur Shastri later became the Prime Minister of India from 1964 to 1966.
Additional Information

• $ \underline{\text{Jagjivan Ram}} $

○ Jagjivan Ram was a prominent Indian politician and a senior leader in the Indian National Congress.

o He served as the Deputy Prime Minister of India from 1977 to 1979.

• S.K. Patil

o S.K. Patil was an Indian politician and a senior leader of the Indian National Congress.

o He served as the Minister of Railways and the Minister of Food and Agriculture.

• Lalit Narayan Mishra

• Lalit Narayan Mishra was an Indian politician from the state of Bihar.

o He served as the Minister of Railways in the Government of India.

• Lalit Narayan Mishra was assassinated in 1975.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.320Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
