o The team is one of the most successful in the history of the tournament.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.321Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
