INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1520, 18, NULL, NULL, 'If $ 1^{st} $ January, 2001 was a Monday, what was the day on $ 26^{th} $ January, 2003 ?', NULL, '[{"text":"Saturday","image_url":null,"alt":null},{"text":"Sunday","image_url":null,"alt":null},{"text":"Monday","image_url":null,"alt":null},{"text":"Wednesday","image_url":null,"alt":null}]', NULL, 1, 'Given: 1st January 2001 was Monday.

Now,

2001 to 2003 = 2 Years (2 Ordinary Year).

And, 1 Ordinary Year has 1 odd day.

Total odd days = 2.

then, 1st January 2003 will be Monday + 2= Wednesday.

Now, the number of days between 1st January 2003 to 26th January 2003

=25days.

=25days $ \rightarrow $ 25/7 = 3 weeks and 4odd days.

So, 26th January 2003 will be Wednesday +4= Sunday.

Hence, the correct answer is "Option 2".', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.328Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
