INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1522, 18, NULL, NULL, 'Which one will replace the question mark (?) ?', NULL, '[{"text":"40","image_url":null,"alt":null},{"text":"43","image_url":null,"alt":null},{"text":"44","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null}]', NULL, 3, 'Logic followed here is,

