INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1523, 18, NULL, NULL, 'Take the given statements to be true even if they seem to be at variance with commonly known facts. Then decide which of the given conclusions logically follow the given statements.

Statements :

0% chairs are tables.

All computers are chairs.

Some books are tables.

Conclusions :

I. Not a single table is a computer.

II. Some books are not chairs.', NULL, '[{"text":"Only conclusion I follows.","image_url":null,"alt":null},{"text":"Only conclusion II follows.","image_url":null,"alt":null},{"text":"Both conclusions I and II follow.","image_url":null,"alt":null},{"text":"Neither conclusion I nor II follows.","image_url":null,"alt":null}]', NULL, 0, 'Given Statements:

0% chairs are tables.

→ "0% chairs are tables" means no chair is a table. Represent this by keeping the circles for "Chairs" and "Tables" completely separate.

All computers are chairs.

Some books are tables.

The least possible Venn diagram for the given statement is:

Explanation of the Venn Diagram:

Conclusions:

I. Not a single table is a computer. - True (Since all computers are inside chairs and no chairs are tables, no computers are tables.)

II. Some books are not chairs. - False (We only know some books are tables. We don''t have any information about the relation between books and chairs. It''s possible that some books are chairs, or no books are chairs. We can only say that some books are tables. It is not confirmed that some books are not chairs.)

So, Only conclusion I follows.

Hence, the correct answer is "Option 1".', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.331Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1524, 18, NULL, NULL, 'Find the number of triangles in the given figure.', NULL, '[{"text":"8","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null}]', NULL, 1, 'The total number of triangles is,

