INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1525, 18, NULL, NULL, 'Rakesh is $17^{\text{th}}$ from the right and Ankit is $15^{\text{th}}$ from the left in a line of students. If they interchange their places, the position of Ankit becomes $19^{\text{th}}$ from the left. How many students are there in the line?', NULL, '[{"text":"36","image_url":null,"alt":null},{"text":"35","image_url":null,"alt":null},{"text":"34","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null}]', NULL, 1, 'The logic followed here is:

Position of Rakesh from the right = 17th

Position of Ankit from the left = 15th

After interchanging, Position of Ankit from the left = 19th

So,

Total number of students = Position of Rakesh from the right + Position of Ankit from the left after interchange - 1

= 17 + 19 - 1

= 36 - 1 = 35.

Hence, the total number of students in the line are 35.', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.332Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1526, 18, NULL, NULL, 'In a family, Bhanu is the father of Kamlesh. Bhanu has only two children. Kamlesh is the brother of Ritu. Ritu is the daughter of Santosh. Aryan is the grandson of Santosh. Sunny is the father of Aryan. How is Sunny related to Bhanu?', NULL, '[{"text":"Son-in-law","image_url":null,"alt":null},{"text":"Son","image_url":null,"alt":null},{"text":"Nephew","image_url":null,"alt":null},{"text":"Brother-in-law","image_url":null,"alt":null}]', NULL, 0, 'Family Chart:

Given: Bhanu is the father of Kamlesh.

Bhanu has only two children.

Kamlesh is the brother of Ritu.

Ritu is the daughter of Santosh.

Aryan is the grandson of Santosh.

Sunny is the father of Aryan.

Therefore, Sunny is Ritu''s husband, and Ritu is Bhanu''s daughter.

So, Sunny is the Son-in-law of Bhanu.

Hence, the correct answer is "Option 1".', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:46.333Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
