INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1592, 2, NULL, NULL, 'निम्नलिखित गद्यों के आधार पर दिए गए प्रश्नों के उत्तर दीजिए :

दुनिया से अच्छा ग्रहण करने का अधिकार सभी देशों को है, भारत के शान-विशान-चितन से बहुत-सी चीज़ों दुनिया ने ली हैं। दूसरी बात यह है कि संसार में जहाँ भी शान-विशान-विचार जन्म लेते हैं उनमें अन्य देशों की भी शात-अशाथ भूमिका होती है और यह आदान-प्रदान का सिलसिला न जाने कब से चल रहा है। आज भी पश्चिम में हो रहे नवीनतम अनचेषणों में विभिन्न

देशों की मेधा, प्रतिभा, श्रम, कौशल, धन, आदि लगे हैं। उदाहरण के लिए भारत की अनेक प्रतिभाएँ अर्से से अमेरिका और अन्य देशों में उच्चस्तरिय अन्वेषण और संगणक के क्षेत्र में सॉफ्टवेयर निर्माण में लगी हैं, क्या यह प्रकारांतर से भारतीय अवदान नहीं है ? उक्त देशों की वस्तुएँ ऊँचे मूल्य पर खरीद कर अनेक छोटे देश उत्तर अनुसंधान में पराक्ष आर्थिक योगदान देते हैं। इसलिए किसी भी उपलब्धि को किसी भूगोल में सीमित नहीं किया जा सकता। यह दूसरी बात है कि हमें अपनी ''आसननिभरता'' लगातार बढ़ानी होगी और अपनी प्रतिभाओं को निरंतर ''प्रोसाहित'' करना होगा। आयातित प्रदूषण से बचने और अपने सांस्कृतिक उद्ययन के लिए यह अनिवार्य है।
गद्यांश के आधार पर सूची-1 को सूची-11 से सुमेलित कीजिए :
नीचे दिए गए विकल्पों में से सही उत्तर चुनीए :', NULL, '[{"text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (IV), (C) - (I), (D) - (III)","image_url":null,"alt":null},{"text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)","image_url":null,"alt":null},{"text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)","image_url":null,"alt":null}]', NULL, 1, 'सही उत्तर है -(A)−(II),-(B)−(IV),-(C)−(I),-(D)−(III).

