• विकास तुषारकोकिताबे देता है।', NULL, NULL, 2024, '/local-papers/assets/hindi-2024-05-16-shift-2/q23-table-1.jpg', 'Table for question 23', NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:54.285Z', NULL, NULL, '[{"url":"/local-papers/assets/hindi-2024-05-16-shift-2/q23-table-1.jpg","alt":"Table for question 23","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1600, 2, NULL, NULL, '"श्याम घर आना चाहता है" वाक्य में कौन-सी क्रिया है ?', NULL, '[{"text":"इच्छा बोधक","image_url":null,"alt":null},{"text":"आवश्यकता बोधक","image_url":null,"alt":null},{"text":"अभ्यास बोधक","image_url":null,"alt":null},{"text":"निश्रय बोधक","image_url":null,"alt":null}]', NULL, 0, '"श्याम घर आना चाहता है" वाक्य मैकिया है -इच्छा बोधक
Key Points

• "श्याम घर आना चाहता है" वाक्य में ''आना चाहता है'' क्रिया इच्छा बोधक क्रिया है, जो श्याम की घर आने की इच्छा को व्यक्त कर रही है।

• जिस संयुक्त क्रिया के करने की इच्छा प्रकट होती है, उसे इच्छाबोधक संयुक्त क्रिया कहते हैं ।

• जैसे: मै लिखना चाहता हूँ।
Important Points

• अर्थ के अनुसार संयुक्त क्रिया के मुख्य 11 भेद हैं:

○ आरंभ बौधक

- समाप्ती बौधक

- अवकाश बौधक

- अनुमति बौधक

- नियता बौधक

- आवश्यकता बौधक

- निरभय बौधक

- इच्छा बौधक

- अभ्यास बौधक

- शक्ति बौधक

- पुनरंकत बौधक
Additional Information
आवश्यकता बौधकः-

• जिससे कार्य की आवश्यकता या कर्तव्य का बोध हो, वह ''आवश्यकता बोधक संयुक्त क्रिया'' है।

• उदाहरण: मुझे रोज सूचल जाना पड़ता है।
अभ्यास बोधक:-

- इससे क्रिया के करने के अभ्यास का बोध होता है। सामान्य भूतकाल की क्रिया में ''करना'' क्रिया लगाने से अभ्यासबोधक संयुक्त क्रियाएँ बनती हैं।

- उदाहरण: वह पढ़ा करता है।
निशय बोधक:-

• जिस संयुक्त क्रिया से मुख्य क्रिया के व्यापार की निश्चितता का बोध हो, उसे निक्षयबोधक संयुक्त क्रिया कहते हैं।

• उदाहरण: रमेश एकाएक बोल उठा।', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:54.285Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1601, 2, NULL, NULL, '"हंस दूध और पानी को अलग कर देता है" वाक्य में अध्यय की पहचान करें :', NULL, '[{"text":"को","image_url":null,"alt":null},{"text":"कर","image_url":null,"alt":null},{"text":"और","image_url":null,"alt":null},{"text":"ऐ","image_url":null,"alt":null}]', NULL, 2, 'सही उत्तर है -अप्रैल
Key Points

• "हंस दूध और पानी को अलग कर देता है" इस वाक्य में "और" अभय है।

• अध्यय का शादिंक अर्थ होता है - जो व्यय न हो।

• जिन शब्दों के रूप में लिंग, वचन, कार्य आदि के कारण कोई परिवर्तन नहीं होता है, उन्हें अथ्य (अ+ व्य) या अविकारी शब्द कहते हैं।

• जैसे -जब, तब, अभी, उधर, वहाँ, इधर, कब, क्यों, वाह, आह, ठीक, अरे, और, तथा, एवं, किन्तु, परन्तु, बल्कि, इसलिए, अत:, अतएव, चूंकि, अवश्य, अर्थात इत्यादि।

० में विद्यालय तत्कानया।
Additional Information
कारक-

• संशा और सर्वनाम का क्रिया के साथ दूसरे शब्दों में संबंध बताने वाले निशानों को कार्य कहते है।

• कार्यक चिह्म जैसे ''से'', ''के लिए'', ''का/के/की'', ''में'', ''पर'' आदि।

• जैसे -गरीबों को खाना दो।
मूल धातु-

• वे क्रिया के रूप होते हैं जो स्वतंत्र होते हैं और किसी अन्य शब्द पर निर्भर नहीं होते।

• उदाहरण: "खाना", "देख" (देखना), "पी" ( पीना), "कर" (करना)
सहायक क्रिया-

• जो क्रिया मुख्य क्रिया के साथ मिलकर वाक्य में काल, भाव, या आवाज़ को व्यक्त करती है,उसे सहायक क्रिया कहते हैं।

• उदाहरण:

• "बारिश हो रही है" में, "हे" एक सहायक क्रिया है।

• "हम दौड़ रहे थे" में, "थे" एक सहायक क्रिया है।', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:54.286Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
