INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1603, 2, NULL, NULL, '"श्री गुरु चरन सरोज रज, निज मन मुकुर सुधार।

बरनौ रघुवर विमल जस, जो दायक फल चार।।"

इन पंक्तियों में किस छंद का प्रयोग किया गया है ?', NULL, '[{"text":"सोरठा","image_url":null,"alt":null},{"text":"कुडिलिया","image_url":null,"alt":null},{"text":"बरवे","image_url":null,"alt":null},{"text":"दोहா","image_url":null,"alt":null}]', NULL, 3, '"श्री गुर चरन सरोज रज, निज मन मुकुर सुधार।

बरनौ रघुवर विमल जस, जो दायक फल चार।।"

इन पंक्तियों में छेद का प्रयोग किया गया है -द्रोह
Key Points

• "श्री गुरु चरन सरोज रज, निज मन मुकुर सुधार।

• S I II IIIISIII II I III S I =13 +11 = 24

• बरनो रघुवर विमल जस, जो दायक फल चार।|"=13 +11 = 24

IISI II IISISSIIS I

- इन पंक्तियों में छिद का प्रयोग किया गया है -दोह्मा
Important Points

དེ་ཐང་：

• यहअर्थसम्ममாதிறक छेदहोता है। येसोरठा छेदके विपरीत होता है।

- इसमेंपहलेऔरतीसरेचरण में13-13तथा दूसरे औरचौथेचरण में11-11मांत्राएँ होती हैं।

- इसमें चरण के अंत मेलधु (1)होना जस्सी होता है।

• जैसे:-

• रहिमन पानी राखेए, बिन पानी सब सून।

○ I III SSSISII SSII S I

• पानी गए न ऊबरे, मोती मानुष चून।।
Additional Information

सोरहा:-

• यहअर्थसम मাত্রिक ऊँदहै । यहदोहेका उल्ता होता है।

- इसकेप्रथमऔरतृतीयचरण में11-11मांत्राएँ एवंहितीयऔरचतुथர்கरण में13-13मात्राएँ होती हैं।

• इसमें तुकप्रथमऔरतृतीयचरण के अंत में अर्थितमध्यमें होता है। इसके सम चरणों मेंजगणनहीं होता।

उदाहरण-

• जो सुमिरत सिंधि होई, गन नायक कविवर बदन।

• करहु अनुग्रह सोई, बुडि रासि शुभ गुन सदन॥

बरवेः-

• बरवे अईसम मात्रिक छन्द है।

• इसके प्रथम एवं तृतीय चरण में 12-12 मात्राएँ तथा द्वितीय एवं चतुर्थ चरण में 7-7 मात्राएँ होती हैं।

• सम चरणों के अंत में ''जगण'' (1 S 1) होता है।

• गोस्वामी तुलसीदास की प्रसिद्ध रचनाओं में से एक ''बरवे रमायाण'' बरवे छन्दों में ही रची गई है, जिसमें भगवान श्रीराम की कथा है।
उदाहरण-

• ऑख मिलेंगी सबसे, रख व्यवहार।

फूल सभी जन चाहें, एक न खार।।
कुण्डलिया:-

• कुण्डलीया छेददोहा-रोलाछंदों के योग से बनता है।

• कुडिलियाएंकिविषम मात्रिकेछंद होता है।

• यहदोह-रोलाछंदोंके योग से बनता है।

• पहलेएक दोहाओं बाद मेंदोها के चौथे चरणसे यदिएक रोलारख दिया जाए तो वहकुडलिया छेदबन जाता है।
उदाहरण-

• सावन बरसा जोर से, प्रमुदित हुआ कियांन ।

• लगा रोपने खेत में, आशाओं के धान ।।

• ओशिआं के धान, मधुर स्तर कोयल बोल ।

• लिए प्रेम-संदेश, मेघ सावन के डोले ।

• ''ठकुरेला'' कविराय, लगा सबको मनभावन ।

• मन में भरे उर्मेण, झुम्मा गाता सावन ।।', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:54.286Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
