INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1605, 2, NULL, NULL, 'नीचे दो कथन दिए गए हैं :

कथन 1 : जहाँ किसी शब्द का प्रयोग एक बार हो, किंतु अर्थ भित्र-भित्र होता हो वहाँ श्लेष अलंकार होता है।

कथन 11 : जहाँ कोई शब्द एक से अधिक बार प्रयुक्त हो, किंतु उसका अर्थ अलग-अलग हो वहाँ श्लेष अलंकार होता है।

उपयुक्त कथन के आलोक में, नीचे दिए गए विकल्पों में से सबसे उपयुक्त उत्तर का चयन कीजिए :', NULL, '[{"text":"कथन 1 और 11 दोनों सही हैं","image_url":null,"alt":null},{"text":"कथन 1 और 11 दोनों गलत हैं।","image_url":null,"alt":null},{"text":"कथन 1 सही है, लेकिन कथन 11 गलत है","image_url":null,"alt":null},{"text":"कथन 1 गलत है, लेकिन कथन 11 सही है","image_url":null,"alt":null}]', NULL, 2, 'सही उत्तर है -कथन ऑसरी है, लेकिन कथन ऑसरी गलत है
Key Points

• कथन 1 सही है। श्लेष अलंकार तब होता है जब एक ही शब्द का प्रयोग एक बार किया जाए और इसका अर्थ भिन्न-भिन्न हो।

• कथन 11 गलत है। श्लेष अलंकार में एक ही शब्द का प्रयोग बार-बार नहीं होता बल्कि एक ही शब्द का अर्थ अल्ग-अलग होता है।

○ अत: सबसे उपयुक्त उत्तर होगा: कथन 1 सही है और कथन 11 गलत है।
Additional Information
হলে:

• श्लेष का अर्थ हैचिपकाना,

• जहां शब्द तोएक बारप्रयुक्त किया जाए पर उसकेएक से अधिक अर्थिकलौ वहाँश्लेष अलंकारहोता है।
उदाहरण-

• मेरी भव बाधा हरो राधा नागरी सोय।

• जा तन की शॉर्ड्स पर देखाम हरित दुर्दित हों।।

• (काव्यांश में कवि द्वारा हरित शब्द का प्रयोग दो अर्थ प्रकट करने के लिए किया है।

• यहाँ हरित शब्द के अर्थ है- हर्षित (प्रसत्र होना) और हरे रंग का होना।)', NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T20:59:54.287Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
