INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2403, 5, NULL, NULL, 'Which of the following is an example of negatively charged sol?', NULL, '[{"text":"AL_{2}O_{3}.xH_{2}O","image_url":null,"alt":null},{"text":"As_{2}S_{3}","image_url":null,"alt":null},{"text":"TiO_{2}","image_url":null,"alt":null},{"text":"Blood","image_url":null,"alt":null}]', NULL, 3, 'Examples of negatively charged sols: Metal sols, metal sulphides, gold sols, blood, starch, acidic dyes, etc.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.162Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
