(E) CH_{3}CH_{2}Cl', NULL, '[{"text":"(C), (B), (A), (D), (E)","image_url":null,"alt":null},{"text":"(C), (A), (B), (E), (D)","image_url":null,"alt":null},{"text":"(B), (C), (E), (A), (D)","image_url":null,"alt":null},{"text":"(B), (C), (A), (E), (D)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-1.jpg', 'Figure for question 27', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.445Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-1.jpg","alt":"Figure for question 27","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-2.jpg","alt":"Figure for question 27","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-3.jpg","alt":"Figure for question 27","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-4.jpg","alt":"Figure for question 27","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q27-figure-5.jpg","alt":"Figure for question 27","kind":"figure"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2580, 5, NULL, NULL, 'Identify P,Q and R in the correct sequence of reactions shown below.

(a)

(b)

(c)

(d)', NULL, '[{"text":"(A), (B), and (C) only","image_url":null,"alt":null},{"text":"(B), (D), and (E) only","image_url":null,"alt":null},{"text":"(B), (C), and (D) only","image_url":null,"alt":null},{"text":"(A), (C), and (D) only","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-1.jpg', 'Figure for question 29', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.447Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-1.jpg","alt":"Figure for question 29","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-2.jpg","alt":"Figure for question 29","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-3.jpg","alt":"Figure for question 29","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-4.jpg","alt":"Figure for question 29","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-5.jpg","alt":"Figure for question 29","kind":"figure"},{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q29-figure-6.jpg","alt":"Figure for question 29","kind":"figure"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2581, 5, NULL, NULL, 'Which of the following alkyl halide will undergo SNI reaction most readily:', NULL, '[{"text":"$ (CH_{3})_{3}C-F $","image_url":null,"alt":null},{"text":"$ (CH_{3})_{3}C-Cl $","image_url":null,"alt":null},{"text":"$ (CH_{3})_{3}C-Br $","image_url":null,"alt":null},{"text":"$ (CH_{3})_{3}C-I $","image_url":null,"alt":null}]', NULL, 3, 'All the given compounds are tertiary alkyl halides but the bond formed between carbon and iodine (C-l) bond is the weakest bond due to large difference in the size of carbon and iodine. So, (CH3)3 C-l gives S_{N}1 reaction most readily.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.449Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2582, 5, NULL, NULL, 'Which of the properties are shown by d block elements?

(A) Complex formation

(B) Chelating agents

(C) Bleaching agents

(D) Catalytic properties

(E) Alloy formation', NULL, '[{"text":"(C), (D), (E) only","image_url":null,"alt":null},{"text":"(A), (B), (C) only","image_url":null,"alt":null},{"text":"(B), (C), (D) only","image_url":null,"alt":null},{"text":"(A), (D), (E) only","image_url":null,"alt":null}]', NULL, 3, '[A] The d-block elements being smaller in size and have high electropositive density and they consist of $ (n-1)d $ free orbitals to accept the free electrons from the ligand and it forms complexes easily.

[D] Transition elements or d-block elements exhibit catalytic behaviour primarily for the following reasons: They have unoccupied d-orbitals. They are capable of displaying a range of valencies. They have a proclivity for forming complicated chemicals.

[E] D block elements are used to make alloys with other metals', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.449Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2583, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null}]', NULL, 1, '[A] The defects introduced in the crystal lattice due to the presence of a certain impurity are called impurity defects. This type of defect arises in the crystal due to the presence of impurity or a foreign particle in a lattice. When $ Sr^{2+} $ replaces $ 2Na^{+} $ ions, it occupies only one site and leaves the other site vacant. Thus, this causes a vacancy.

[B] Metal excess defects can occur due to a missing anion from an ideal ionic solid, which leads to the creation of an F-centre, which is generally occupied by an unpaired electron. e.g., NaCl with the anionic site.

[C] FeO shows metal deficiency defect. In crystal of FeO some $ Fe^{2+} $ cations are missing and the loss of positive charge is made up by the presence of required number of $ Fe^{3+} $ ions.

[D] When an atom is not present at their lattice sites, then that lattice site is vacant and it creates a vacancy defect. Due to this, the density of a substance decreases.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-13-shift-3/q32-table-1.jpg', 'Table for question 32', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.450Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q32-table-1.jpg","alt":"Table for question 32","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2584, 5, NULL, NULL, 'Name the reagent required to convert cyclohexene into hexane -1, 6-dioic acid.

(a) $ KMnO_{4}/H_{2}SO_{4}, \Delta $

(b) Tollen''s reagent

(c) Grignard reagent

(d) KCN

(A) The coagulation of lyophobic sols can be done by electrophoresis

(B) Principal emulsifying agent for W/O emulsions are proteins, soaps, gums etc.

(C) Alum is used for cleaning muddy water

(D) Gelatin is added to ice cream to act as emulsifier', NULL, '[{"text":"(D), (C) and (A) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(C), (A) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (A) only","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.451Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2585, 5, NULL, NULL, 'Match the chemical conversion in List-I to the appropriate reagent in List-II.', NULL, '[{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-13-shift-3/q35-table-1.jpg', 'Table for question 35', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.454Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q35-table-1.jpg","alt":"Table for question 35","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2586, 5, NULL, NULL, 'Write the IUPAC name of the following compound $ C_{6}H_{5}O(CH_{2})_{6}-CH_{3} $', NULL, '[{"text":"2-Methoxy heptane","image_url":null,"alt":null},{"text":"1-Phenoxy heptane","image_url":null,"alt":null},{"text":"1-Benzoyl heptane","image_url":null,"alt":null},{"text":"Methyl benzyl ether","image_url":null,"alt":null}]', NULL, 1, 'The IUPAC name of the compound $ C_{6}H_{5}O(CH_{2})_{6}CH_{3} $ is 1-phenoxy heptane.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.454Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2587, 5, NULL, NULL, 'Tertiary amino group is found in:', NULL, '[{"text":"Novocain","image_url":null,"alt":null},{"text":"Ephedrine","image_url":null,"alt":null},{"text":"Benadryl","image_url":null,"alt":null},{"text":"Adrenaline","image_url":null,"alt":null}]', NULL, 2, 'Benadryl, a well-known antihistaminic drug also contains tertiary amino group.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.455Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2588, 5, NULL, NULL, 'Which of the following shows both, Frenkel and Schottky defect?', NULL, '[{"text":"KCl","image_url":null,"alt":null},{"text":"AgCl","image_url":null,"alt":null},{"text":"AgBr","image_url":null,"alt":null},{"text":"NaCl","image_url":null,"alt":null}]', NULL, 2, 'AgBr has both schottky and frenkel defects. In general, silver haldies show both schottky and frenkel defects. In schottky defect, equal number of cations and anions are missing from crystal lattice.

-In AgCl, as the anion is much larger than the cation, it shows Frenkel defect', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.458Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2589, 5, NULL, NULL, 'The role of a catalyst is to change:', NULL, '[{"text":"Gibbs energy of reaction","image_url":null,"alt":null},{"text":"Enthalpy of reaction","image_url":null,"alt":null},{"text":"Activation energy of reaction","image_url":null,"alt":null},{"text":"Equilibrium constant","image_url":null,"alt":null}]', NULL, 2, 'The role of a catalyst is to change the activation energy of the reaction. However, catalyst does not changes Gibbs energy of reaction, enthalpy of reaction and equilibrium constant.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.460Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2590, 5, NULL, NULL, 'Which of the following reaction occurs at anode during discharging of lead storage battery?', NULL, '[{"text":"$\\mathrm{PbO}_{2}+\\mathrm{SO}_{4}^{2-}(\\mathrm{aq})+\\mathrm{H}^{+}(\\mathrm{aq})+2\\mathrm{e}^{-}\\rightarrow\\mathrm{PbSO}_{4}(\\mathrm{s})+2\\mathrm{H}_{2}\\mathrm{O}(\\mathrm{l})$","image_url":null,"alt":null},{"text":"$\\mathrm{Pb}(\\mathrm{s})+\\mathrm{SO}_{4}^{2-}(\\mathrm{aq})\\rightarrow\\mathrm{PbSO}_{4}(\\mathrm{s})+2\\mathrm{e}^{-}$","image_url":null,"alt":null},{"text":"$\\mathrm{PbSO}_{4}+2\\mathrm{e}^{-}\\rightarrow\\mathrm{Pb}(\\mathrm{s})+\\mathrm{SO}_{4}^{2-}(\\mathrm{aq})$","image_url":null,"alt":null},{"text":"$\\mathrm{PbSO}_{4}(\\mathrm{s})+2\\mathrm{H}_{2}\\mathrm{O}(\\mathrm{l})\\rightarrow\\mathrm{Pb}(\\mathrm{s})+2\\mathrm{H}_{2}\\mathrm{SO}_{4}+\\mathrm{SO}_{4}^{2-}(\\mathrm{aq})+\\mathrm{H}^{+}(\\mathrm{aq})+2\\mathrm{e}^{-}$ Direction for the question 41 to 45: Answer the question on basis of passage given below: In zwitter ionic form, amino acids show amphoteric behaviour as they react both with acids and bases. Except glycine, all other naturally occurring $ \\alpha $-amino acids are optically active, since the $ \\alpha $-carbon atom is asymmetric. These exist both in ''D'' and ''L'' forms. Most naturally occurring amino acids have L-configuration. L-Aminoacids are represented by writing the $ -NH_{2} $ group on left hand side.","image_url":null,"alt":null}]', NULL, 1, 'Pb → Pb^{2+} + 2e⁻

Pb^{2+} + SO_{4}^{2-} \rightarrow PbSO_{4}

Overall reaction at anode during discharge:

Pb + SO_{4}^{2-} \rightarrow PbSO_{4} + 2e⁻', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.467Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2591, 5, NULL, NULL, 'Which of the following amino acid is essential?', NULL, '[{"text":"Glycine","image_url":null,"alt":null},{"text":"Glutamic acid","image_url":null,"alt":null},{"text":"Alanine","image_url":null,"alt":null},{"text":"Valine","image_url":null,"alt":null}]', NULL, 3, 'The 9 essential amino acids are: histidine, isoleucine, leucine, lysine, methionine, phenylalanine, threonine, tryptophan, and valine.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.469Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2592, 5, NULL, NULL, 'Which of the following Twitter ion form is correct?

(a)

+ R

NH_{3}-CH-COO^{-}

(b)

+ R

NH_{4}-CH-COO^{-}

(c)

NH_{2}-CH-COOH

(CH_{2})_{2}-COOH

(d)

NH_{2}-CH-COOH

Identify the amino acid which is amphoteric in nature.', NULL, '[{"text":"$ (CH_2)_3-NH-\\overset{NH_2}{C}=NH $ $ \\mathrm{NH_2-CH-COOH} $","image_url":null,"alt":null},{"text":"$ \\mathrm{H-COOH} $","image_url":null,"alt":null},{"text":"$ \\mathrm{CH_2-COOH} $ $ \\mathrm{NH_2-CH-COOH} $","image_url":null,"alt":null},{"text":"$ \\mathrm{NH_2-Cl-COOH} $","image_url":null,"alt":null}]', NULL, 0, '$ \begin{array}{c}

\text{H}_3\text{N} - \text{CH}_2 - \text{COOH} \rightleftharpoons \text{H}_3\text{N} - \text{CH}_2 - \text{COO}^- \\

\downarrow \quad \downarrow \quad \text{(Zwitterion form)}

\end{array} $

Sol. pK_a = 9.60 pK_a = 2.34', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.473Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2593, 5, NULL, NULL, 'Optically inactive amino acid from the following is:', NULL, '[{"text":"Valine","image_url":null,"alt":null},{"text":"Glycine","image_url":null,"alt":null},{"text":"Aianine","image_url":null,"alt":null},{"text":"Proline","image_url":null,"alt":null}]', NULL, 1, 'Glycine has no chiral center. So, it is optically inactive.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.474Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2594, 5, NULL, NULL, '$ \beta $-D-Deoxyribose and $ \beta $-D-ribose differs from each other in configuration at:', NULL, '[{"text":"C-5","image_url":null,"alt":null},{"text":"C-3","image_url":null,"alt":null},{"text":"C-4","image_url":null,"alt":null},{"text":"C-2 Direction for the question 46 to 50: Answer the question on basis of passage given below: P block elements are placed in groups 13 to 18 of the periodic table. Their valence shell electronic configuration is $ ns^{2} $ np $ ^{1-6} $. Group 16 of the p block elements are known as the group of chalcogens having $ ns^{2} $ np $ ^{4} $ as their general electronic configuration. They exhibit number of oxidation states but the stability of -2 oxidation state decreases down the group. They are sometimes also known as group of chalcogens as the name is derived from the Greek word for brass and points to the association of sulphur and its congeners with copper. Their ionisation enthalpy decreases down the group. Oxygen shows anomalous behaviour due to its small size and high electronegativity.","image_url":null,"alt":null}]', NULL, 3, 'The structure of Ribose and Deoxyribose is almost identical, with just one difference. Ribose sugar has a hydroxyl (OH) group at position 2, whereas deoxyribose sugar has a hydrogen (H) atom at position 2.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.475Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2595, 5, NULL, NULL, 'Which one is the correct electronic configuration of sulphur?', NULL, '[{"text":"[NeI 3s² 3p²","image_url":null,"alt":null},{"text":"[He] 2s² 2p⁴","image_url":null,"alt":null},{"text":"[Ne] 3s² 3p⁴","image_url":null,"alt":null},{"text":"[Ne] 3s² 3p⁶","image_url":null,"alt":null}]', NULL, 2, 'Electronic configuration of sulphur is $ 1s^{2}2s^{2}2p^{6}3s^{2}3p^{4} $

So, electronic configuration is $ [Ne]3s^{2}3p^{4} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.478Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2596, 5, NULL, NULL, 'Identify the epsilon salt out of the following salts:', NULL, '[{"text":"Pbs","image_url":null,"alt":null},{"text":"ZnS","image_url":null,"alt":null},{"text":"$ CuFeS_{2} $","image_url":null,"alt":null},{"text":"$ MgSO_{4}\\cdot7H_{2}O $","image_url":null,"alt":null}]', NULL, 3, 'Magnesium Sulphate is also known as Epsom salt. It is an inorganic salt and its formula is $ \mathrm{MgSO_{4}(H_{2}O)x} $.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.481Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2597, 5, NULL, NULL, 'Match the oxidation state of phosphorous in the following compounds to their counter parts in List II.', NULL, '[{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(IV), (C)-(II), (D)-(III)","image_url":null,"alt":null}]', NULL, 0, 'The Oxidation Number of P in H_{3}PO_{2} is +1

Thus oxidation states of P in H_{4}P_{2}O_{5}, H_{4}P_{2}O_{6}, H_{4}P_{2}O_{7},

are +3, +4 and +5.

The oxidation number of P in H_{3}PO_{3} is +3

The oxidation number of Phosphorus (P) in

Phosphoric acid (H_{3}PO_{4}) is equal to +5.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-13-shift-3/q48-table-1.jpg', 'Table for question 48', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.482Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-13-shift-3/q48-table-1.jpg","alt":"Table for question 48","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2598, 5, NULL, NULL, 'What will be the products formed in the following equation?

$ \text{U(S)} + 3\text{ClF}_3\text{(1)} \rightarrow $_ + _.', NULL, '[{"text":"$ \\text{UF}_4\\text{(g)} $ and 3UCI (g)","image_url":null,"alt":null},{"text":"$ \\text{UF}_6\\text{(g)} $ and 3CIF (g)","image_url":null,"alt":null},{"text":"$ \\text{UF}_4\\text{(g)} $ and 3 CIF (g)","image_url":null,"alt":null},{"text":"$ \\text{UF}_6\\text{(g)} $ and 3 UCI (g)","image_url":null,"alt":null}]', NULL, 2, '$ \mathrm{U}\left(\mathrm{s}\right) + 3\mathrm{ClF}_{3}\left(\mathrm{l}\right) \rightarrow \mathrm{UF}_{4}\left(\mathrm{l}\right) + 3\mathrm{ClF}\left(\mathrm{s}\right) $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.483Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2599, 5, NULL, NULL, 'Given below are the Hydrides formed by group 15 elements. Choose the correct decreasing order of basicity of the following hydrides

(A) AsH₃

(B) PH₃

(C) NH₃

(D) BiH₃

(E) SbH₃', NULL, '[{"text":"(C), (B), (A), (E), (D)","image_url":null,"alt":null},{"text":"(B), (A), (C), (D), (E)","image_url":null,"alt":null},{"text":"(A), (D), (E), (B), (C)","image_url":null,"alt":null},{"text":"(D), (E), (A), (C), (B)","image_url":null,"alt":null}]', NULL, 0, 'As we move down the group the size of the central atom increases thereby their orbital become more diffused, hence the nucleophilicity of the lone pair is less dense over the bigger atoms thereby decreasing the basicity. So, the increasing order of their basic character is, $ \mathrm{BiH}_{3} < \mathrm{SbH}_{3} < \mathrm{AsH}_{3} < \mathrm{PH}_{3} < \mathrm{NH}_{3} $.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.484Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2600, 5, NULL, NULL, 'Second most abundant element in alloy misch metal is:', NULL, '[{"text":"Fe","image_url":null,"alt":null},{"text":"Ce","image_url":null,"alt":null},{"text":"Al","image_url":null,"alt":null},{"text":"S","image_url":null,"alt":null}]', NULL, 0, 'Misch metal contains Lanthanide metals (94-95)% + Iron (5)% + Traces of S, C, Si, Ca and Al. The maximum amount of Mischmetal is used to make Magnesium based alloy called pyrophoric alloy.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.487Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2601, 5, NULL, NULL, 'The correct increasing order of basic strength of amine is:

(A) $ C_6H_5NH_2 < NH_3 < C_6H_5CH_2NH_2 < C_2H_5NH_2 < (C_2H_5)_2NH $

(B) $ NH_3 < C_6H_5NH_2 < C_6H_5CH_2NH_2 < C_2H_5NH_2 < (C_2H_5)_2NH $

(C) $ C_6H_5CH_2NH_2 < C_6H_5NH_2 < NH_3 < C_2H_5NH_2 < (C_2H_5)_2NH $

(D) $ C_2H_5NH_2 < (C_2H_5)_2NH < C_6H_5NH_2 < NH_3 $', NULL, '[{"text":"(A) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(D) only","image_url":null,"alt":null}]', NULL, 0, 'Considering the inductive effect of alkyl groups, NH₃, C₂H₅NH₂, and (C₂H₅)₂NH can be arranged in the increasing order of their basic strengths as: NH₃ < C₂H₅NH₂ < (C₂H₅)₂NH

Again, C₆H₅NH₂ has proton acceptability less than NH₃. Thus, we have: C₆H₅NH₂ < NH₃ < C₂H₅NH₂ < (C₂H₅)₂NH

Due to the -I effect of C₆H₅ group, the electron density on the N-atom in C₆H₅CH₂NH₂ is lower than that on the N-atom in C₂H₅NH₂, but more than that in NH₃. Therefore, the given compounds can be arranged in the order of their basic strengths as: C₆H₅NH₂ < NH₃ < C₆H₅CH₂NH₂ < C₂H₅NH₂ < (C₂H₅)₂NH', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.488Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2602, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null}]', NULL, 1, 'CrO₂ is a ferromagnetic substance, which is attracted very strongly by a magnetic field.

MnO is an antiferromagnetic substance as its domains cancel out each other''s magnetic moment.

Fe₃O₄ (magnetite) is a ferrimagnetic substance because in it the magnetic moments of the domains are aligned in parallel and anti-parallel direction in unequal number.

Na⁺ has electronic configuration [Ne]

Cl⁻ has electronic configuration [Ar]

Thus, both cation and anion have an inert gas electronic configuration in which all the electrons are paired.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q03-table-1.jpg', 'Table for question 3', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.489Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q03-table-1.jpg","alt":"Table for question 3","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2603, 5, NULL, NULL, 'A reaction takes 30 minutes to complete 50% of the reaction and takes 45 minutes to complete 75% of the reaction. The order of the reaction is:', NULL, '[{"text":"First","image_url":null,"alt":null},{"text":"Second","image_url":null,"alt":null},{"text":"Third","image_url":null,"alt":null},{"text":"Zero","image_url":null,"alt":null}]', NULL, 0, 'For first order reaction, t = 2.303/k log [A₀]/[A]

For 50% completion, t = t₁/₂, A₀ = 1, A = ½

t₁/₂ = 2.303/k log(2/1)

t₁/₂ = 2.303/k log₂. {1}

for 75% completion, t = t₃/₄ {75/100 = ³/₄}

A₀ = 1, A = 1-3/4 = ¹/₄

t₃/₂ = 2.303/k log(4)

t₃/₄ = 2(2.303/k log₂). {2}

t₃/₄ = 2t₁/₂

the above reaction holds true for 1st order reaction', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.489Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2604, 5, NULL, NULL, 'Which of the following haloalkanes reacts with aqueous KOH most easily?', NULL, '[{"text":"1-Bromobutane","image_url":null,"alt":null},{"text":"2-Bromobutane","image_url":null,"alt":null},{"text":"2-Bromo-2-methyl propane","image_url":null,"alt":null},{"text":"2-Chlorobutane","image_url":null,"alt":null}]', NULL, 2, 'The tertiary carbocation formed in the reaction is stable in 2-Bromo-2-methylpropane. So these haloalkanes react with aqueous KOH most easily.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.490Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2605, 5, NULL, NULL, '[NiCl_{2}(PPh_{3})_{2}] is named as:', NULL, '[{"text":"Dichloridobis (triphenyl phosphine) nickel (II)","image_url":null,"alt":null},{"text":"Nickel chlorido bis (triphenyl phosphine)","image_url":null,"alt":null},{"text":"Diphenyl phosphine Nickel (II) chloride","image_url":null,"alt":null},{"text":"Dichlorobis (Diphenyl phosphine) Nickel (II)","image_url":null,"alt":null}]', NULL, 0, 'The IUPAC name of [Ni (PPh_{3})_{2}Cl_{2}]^{2+} is dichlorobis(triphenylphosphine)nickel(II) ion', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.491Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2606, 5, NULL, NULL, 'Identify transition metal complexes which are not octahedral in shape.

(A) [Co(NH₃)₆]³⁺

(B) [Ni(CO)₄]

(C) [CoCl(NH₃)₅]²⁺

(D) [CoCl₂(NH₃)₄]⁺

(E) [PtCl₄]²⁻', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (E) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(D) and (E) only","image_url":null,"alt":null}]', NULL, 1, '[B] In Ni(CO) $ _{4} $, Ni is sp $ ^{3} $ hybridised and its geometry is tetrahedral

[E] [PtCl_{4}]^{2-} has square planar', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.491Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2607, 5, NULL, NULL, 'E_{cell} for the given cell

[Given $ E^{\circ}_{Br_{2}/Br^{-}=+1.09V,E^{\circ}_{Cl_{2}/Cl^{-}}}=+1.36V $ at 298 K is', NULL, '[{"text":"0.1518 V","image_url":null,"alt":null},{"text":"0.3291 V","image_url":null,"alt":null},{"text":"0.3882 V","image_url":null,"alt":null},{"text":"0.2109 V","image_url":null,"alt":null}]', NULL, 3, 'The net reaction is: $\mathrm{Cl_2 + 2Br^- \rightarrow 2Cl^- + Br_2}$

$\mathrm{E^{0}_{cell}} = E^{0}_{cathode} - E^{0}_{anode} = 1.36 - 1.09 = 0.27}$

$\mathrm{E} = \mathrm{E^0} - 0.0591/\mathrm{n\log[Product/Reactant]}$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.492Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2608, 5, NULL, NULL, 'In which of the following molecules carbon atom marked with asterix (*) is a stereocentre or Chiral centre?', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 0, 'Asymmetric carbon is a sp $ ^{3} $ hybridised carbon which is attached to four different substituents. This is also called as the chiral centre. So by this definition, (I) is chiral centres.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.497Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q10-options.jpg","alt":"Printed answer choices for question 10","kind":"options"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2609, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(III), (B)-(IV), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(IV), (C)-(II), (D)-(I II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null}]', NULL, 0, '[A] Urease (urea amidohydrolase EC 3.5. 15) catalyzes the hydrolysis of urea to ammonia and carbon dioxide

[B] The maltase and diastase enzymes are used to convert maltose into glucose.

[C] Invertase (EC 3.2.7.26) is an enzyme that catalyzes the hydrolysis reaction of sucrose to form glucose and fructose

[D] Diastase enzymes are used to convert maltose into glucose.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q11-table-1.jpg', 'Table for question 11', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.498Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q11-table-1.jpg","alt":"Table for question 11","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2610, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null}]', NULL, 3, '[A] Some of the examples of gels are curd, cheese, butter, etc.

[B] Examples of foams formed by gases in liquids include whipped cream, fire retardant foam, and soap bubbles.

[C] In hair cream, both the dispersion medium and dispersed phase are liquids, hence it is an example of emulsion.

[D] Aerosols can be natural or artificial. Examples of natural aerosols are fog, forest exudates and geyser steam. Examples of artificial aerosols are haze, dust, particulate air pollutants and smoke.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q12-table-1.jpg', 'Table for question 12', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.499Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q12-table-1.jpg","alt":"Table for question 12","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2611, 5, NULL, NULL, 'Match the ores in List-I with their chemical composition in List-II:', NULL, '[{"text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)","image_url":null,"alt":null}]', NULL, 2, '[A] The chemical formula for kaolinite as used in mineralogy is $ Al_{2}Si_{2}O_{5}(OH)_{4} $

[B] Siderite is a mineral composed of iron(II) carbonate ( $ FeCO_{3} $)

[C] Malachite is another copper carbonate hydroxide mineral with chemical formula $ [Cu_{2}CO_{3}(OH)_{2}] $ formed by the weathering of copper ore bodies in the vicinity.

[D] $ ZnCO_{3} $ is the chemical formula of calamine.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q13-table-1.jpg', 'Table for question 13', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.499Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q13-table-1.jpg","alt":"Table for question 13","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2612, 5, NULL, NULL, 'Rate of a reaction changes from $ 2.48 \times 10^{-3} $ mol $ ^{-1} $ sec $ ^{-1} $ to $ 4.96 \times 10^{-3} $ mol $ ^{-1} $ sec $ ^{-1} $ when concentration of reactant, is changed from 0.6 M to 2.4 M respectively, the order of reaction is:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"zero","image_url":null,"alt":null},{"text":"0.5","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null}]', NULL, 2, '0.5', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.500Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2613, 5, NULL, NULL, 'Ferric oxide in blast furnace''s upper half is mainly reduced by:', NULL, '[{"text":"CO","image_url":null,"alt":null},{"text":"C","image_url":null,"alt":null},{"text":"CO_{2}","image_url":null,"alt":null},{"text":"H_{2}","image_url":null,"alt":null}]', NULL, 0, 'CO is the main reducing agent in the furnace. Iron oxide is reduced to iron by CO.

In a blast furnace, a substance called coke (mainly C) reacts with oxygen, O2, to form carbon monoxide, CO. The carbon monoxide (a strong reducing agent) then reacts with iron oxide (in the form of hematite or magnetite) to form pig iron (mainly Fe) and carbon dioxide.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.501Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2614, 5, NULL, NULL, 'These structures represent which particular kind of halides:', NULL, '[{"text":"Alkyl halides","image_url":null,"alt":null},{"text":"Benzylic halides","image_url":null,"alt":null},{"text":"Vinyl halide","image_url":null,"alt":null},{"text":"Allylic halides","image_url":null,"alt":null}]', NULL, 3, 'The compounds with halogen atoms bonded to sp $ ^{3} $-hybridised carbon to carbon-carbon double bond (C=C) i.e. to an allylic carbon.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q16-figure-1.jpg', 'Figure for question 16', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.501Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q16-figure-1.jpg","alt":"Figure for question 16","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2615, 5, NULL, NULL, 'Which of the following compound will not undergo Azo coupling reaction?', NULL, '[{"text":"Aniline","image_url":null,"alt":null},{"text":"Phenol","image_url":null,"alt":null},{"text":"Anisole","image_url":null,"alt":null},{"text":"Nitrobenzene","image_url":null,"alt":null}]', NULL, 3, 'Diazonium cation is a weak electrophile and hence it reacts with electron-rich compounds containing electron-donating groups such as -OH, $ -NH_2 $ and $ OCH_3 $ groups and not with compounds containing electron-withdrawing groups such as $ -NO_2 $, etc.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.502Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2616, 5, NULL, NULL, 'Degree of dissociation, when molar conductivity of X at its concentration C is 24.14 and its limiting molar conductivity is 48.28 will be:', NULL, '[{"text":"0.3","image_url":null,"alt":null},{"text":"0.5","image_url":null,"alt":null},{"text":"0.6","image_url":null,"alt":null},{"text":"0.9","image_url":null,"alt":null}]', NULL, 1, '$ \alpha= $ molar conductivity/limiting molar conductivity $ \alpha=24.1/48.28=0.5 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.503Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2617, 5, NULL, NULL, 'Phenol is brominated in solvent CS_{2} at low temperature. The product formed are:', NULL, '[{"text":"Monobromophenols","image_url":null,"alt":null},{"text":"Dibromophenols","image_url":null,"alt":null},{"text":"Tribromophenols","image_url":null,"alt":null},{"text":"Tribromobenzene","image_url":null,"alt":null}]', NULL, 1, 'Phenol reacts with bromine in $ CS_{2} $ at low temperature to give o and p-bromophenol.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.504Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2618, 5, NULL, NULL, 'Osmotic pressure of solution formed by mixing 50 ml of 0.2 M urea and 50 ml of 0.4 m glucose aqueous solution at 298 K will be: (R = 0.083 L atm K $ ^{-1} $ mol $ ^{-1} $)', NULL, '[{"text":"14.84 atm","image_url":null,"alt":null},{"text":"7.42 atm","image_url":null,"alt":null},{"text":"11.13 atm","image_url":null,"alt":null},{"text":"3.71 atm","image_url":null,"alt":null}]', NULL, 1, 'The molar mass of glucose and urea are 60 g/mol and 180 g/mol respectively.

The number of moles of urea = 50 $ \times $ 0.2/100 $ \times $ 60 = 0.002

The number of moles of glucose = 50 $ \times $ 0.4/100 $ \times $ 180 = 0.001

Total molar concentration = 0.0016 + 0.001/50 mL + 50 mL $ \times $ 1000 mL/1L = 0.03 M

The osmotic pressure is $ \Pi= $CRT

= 0.03 $ \times $ 0.083 $ \times $ 298 = 0.742', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.505Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2619, 5, NULL, NULL, 'Decreasing order of freezing point of 0.1 M aqueous solution of following will be:

(A) K_{4}[Fe(CN)_{6}]

(B) K_{2}SO_{4}

(C) NH_{2}CONH_{2}

(D) AlCl_{3}

(E) HCl', NULL, '[{"text":"(A) > (D) > (B) > (E) > (C)","image_url":null,"alt":null},{"text":"(A) > (D) > (B) > (C) > (E)","image_url":null,"alt":null},{"text":"(C) > (E) > (B) > (D) > (A)","image_url":null,"alt":null},{"text":"(E) > (C) > (B) > (D) > (A)","image_url":null,"alt":null}]', NULL, 0, 'All are in aqueous solution.

Concentration is same for all i.e., 0.1

So their freezing point will depend on von''t hoff factor.

(A) K_{4}[Fe(CN)_{6}] (i = 5)

(B) K_{2}SO_{4} (i = 3)

(C) NH_{2}CONH_{2} (i = 1)

(D) AlCl_{3} (i = 4)

(E) HCl - i = 2', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.506Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2620, 5, NULL, NULL, 'When blood cells are placed in 1% (w/v) NaCl aquem solution:', NULL, '[{"text":"Cell will burst","image_url":null,"alt":null},{"text":"Cell will shrink","image_url":null,"alt":null},{"text":"Cell will swell","image_url":null,"alt":null},{"text":"Cell remains as such","image_url":null,"alt":null}]', NULL, 1, 'A 1% NaCl solution is a hypertonic solution that causes RBC cells to shrink.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.506Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2621, 5, NULL, NULL, 'A divalent ion of ''V'' (Atomic no. - 23) in aqueous solution is:', NULL, '[{"text":"$ \\sqrt{24} $ BM","image_url":null,"alt":null},{"text":"$ \\sqrt{15} $ BM","image_url":null,"alt":null},{"text":"$ \\sqrt{12} $ BM","image_url":null,"alt":null},{"text":"$ \\sqrt{3} $ BM","image_url":null,"alt":null}]', NULL, 1, 'The atomic number is 23. The metal is vanadium with valence shell, V: [Ar]4s $ ^{2} $3d $ ^{3} $.

The divalent ion V2+ has valence shell electronic configuration 3d3. It contains five unpaired electrons. n=3

It''s spin only magnetic moment is $ \sqrt{n(n+2)}=\sqrt{3(3+2)}=\sqrt{15} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.507Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2622, 5, NULL, NULL, 'Which of the following is incorrect?', NULL, '[{"text":"$ \\ce{CH3-CH2-OH ->[H2SO4][\\text{Con/443 K}] CH2=CH2 + H2O} $","image_url":null,"alt":null},{"text":"$ \\ce{CH2-C(=O)-CH3 ->[\\text{CH3}] \\ce{CH3}} $","image_url":null,"alt":null},{"text":"$ \\ce{CH3-CH2-CH3 ->[\\text{OH}] \\ce{CH3}} $","image_url":null,"alt":null},{"text":"$ \\ce{CH3-CH2-OH ->[\\text{Cu}] \\ce{CH3}} $ (e)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.508Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2623, 5, NULL, NULL, 'What is the packing efficiency of simple cubic lattice?', NULL, '[{"text":"69%","image_url":null,"alt":null},{"text":"74%","image_url":null,"alt":null},{"text":"52.4%","image_url":null,"alt":null},{"text":"80.2%","image_url":null,"alt":null}]', NULL, 2, 'The packing efficiencies of simple cubic and body-centered cubic lattices are 52.4% and 68% respectively.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.508Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2624, 5, NULL, NULL, 'Phenol is manufactured from hydrocarbon, Cumene.

Cumene is chemically:', NULL, '[{"text":"tert. butyl benzene","image_url":null,"alt":null},{"text":"Isopropyl benzene","image_url":null,"alt":null},{"text":"Acetone","image_url":null,"alt":null},{"text":"isopropyl alcohol","image_url":null,"alt":null}]', NULL, 1, 'Cumene is isopropyl benzene. Cumene in presence of sodium carbonate is oxidised by passing air or oxygen. The catalyst is cobalt naphthenate.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.509Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2625, 5, NULL, NULL, 'Increasing order of oxidation states of transition metal oxides will be:

(A) TiO_{2}

(B) MnO_{4}^{-}

(C) VO_{2}^{+}

(D) CrO_{4}^{2-}

(E) Ni(CO)_{4}', NULL, '[{"text":"(B) < (D) < (C) < (A) < (E)","image_url":null,"alt":null},{"text":"(E) < (C) < (A) < (D) < (B)","image_url":null,"alt":null},{"text":"(E) < (A) < (C) < (D) < (B)","image_url":null,"alt":null},{"text":"(B) < (A) < (C) < (D) < (E)","image_url":null,"alt":null}]', NULL, 2, '[A] The oxidation state of titanium in titanium dioxide is commonly assumed to be +4.

[B] $ \mathrm{MnO}_{4}^{-} = x + 4(-2) = -1 = 7 $

[C] $ \mathrm{VO}_{2}^{+} = x + 2(-2) = 1 = 5 $

[D] $ \mathrm{CrO}_{4}^{2-} = x + 4(-2) = -2 => 6 $

[E] The oxidation number of Ni in $ \mathrm{Ni(CO)}_{4} $ is +2.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.513Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2626, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(II), (B)-(IV), (C)-(III), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(IV), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)","image_url":null,"alt":null}]', NULL, 1, '[A] Monomers of BUNA-S: 1,3-butadiene and styrene

[B] We can write its structure as

$ -(CH_{2}-C(Cl)=CH-CH_{2})_{n}- $

From the structure of Neoprene, we can understand that the polymer is formed from polymerization of Chloroprene, which is a chlorine-substituted diene molecule. Neoprene is also known as poly chloroprene.

[C] PVC is produced from its monomer, vinyl chloride.

[D] The monomer unit of Teflon is Tetrafluoroethylene ( $ F_{2}C=CF_{2} $).', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q28-table-1.jpg', 'Table for question 28', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.514Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q28-table-1.jpg","alt":"Table for question 28","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2627, 5, NULL, NULL, 'Inner orbital complex among the following is:

(A) $ [Co(NH3)_6]^{3+} $

(B) $ [COF_6]^{3-} $

(D) $ [MnC1_6]^{3-} $

(E) $ [FeF_6]^{3-} $', NULL, '[{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(D) and (E) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null}]', NULL, 0, '[A] In the presence of NH₃ the 3d electrons pair up leaving two d-orbitals empty to be involved in d²sp³ hybridisation forming inner orbital complex in case of [Co(NH₃)₆]³⁺

[C] In the complex $ [\mathrm{Ni(CN)_4}]^{2-} $, the central Ni metal has +2 oxidation state with outer electronic configuration $ 3d^8 $. One 3d, one 4s and two 4p orbitals undergo $ dsp^2 $ hybridisation. Since, inner d orbital is used in the hybridisation, the complex

is inner orbital or low spin or spin paired complex.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.515Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2628, 5, NULL, NULL, 'The presence or absence of hydroxyl group on which carbon atom of sugar differentiate RNA and DNA:', NULL, '[{"text":"$ 2^{nd} $","image_url":null,"alt":null},{"text":"$ 4^{th} $","image_url":null,"alt":null},{"text":"$ 3^{rd} $","image_url":null,"alt":null},{"text":"$ 1^{st} $","image_url":null,"alt":null}]', NULL, 0, 'RNA has a hydroxy group on the second carbon which is not present in DNA.

Thus, hydroxy group on a second carbon atom of the sugar differentiate between RNA and DNA.

D-ribose (RNA)

D-2-deoxyribose (DNA)', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.516Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2629, 5, NULL, NULL, 'Coagulating power of an ion for a colloidal solution depends on:', NULL, '[{"text":"Its magnitude of charge only","image_url":null,"alt":null},{"text":"Its size only","image_url":null,"alt":null},{"text":"Its tendency to hydrate","image_url":null,"alt":null},{"text":"Its size and magnitude of charge both","image_url":null,"alt":null}]', NULL, 3, 'The coagulating power of an ion depends on both magnitude and sign of the charge on the ion. The ions of the opposite sign of the charge to those present on the surface of the particles cause the precipitation of the particles.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.517Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2630, 5, NULL, NULL, 'Which of the following statements are correct?

(A) Glucocorticoids control the carbohydrate metabolism

(B) Testosterone is major female sex hormone

(C) Insulin is released in response to increase in blood sugar

(D) Hypothyroidism is caused by low level of thyroxine

(E) Mineralocorticoid is major male sex hormone', NULL, '[{"text":"(A), (B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (C), (D) and (E) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 2, '[A] They are anti-inflammatory in all tissues, and control metabolism in muscle, fat, liver and bone. Glucocorticoids also affect vascular tone, and in the brain influence mood, behaviour and sleep-wakefulness cycles.

[C] After a meal, when exogenous blood glucose levels are high, insulin is released to trigger glucose uptake into insulin-dependent muscle and adipose tissues as well as to promote glycogenesis.

[D] Primary hypothyroidism is due to decreased secretion of $ T_{4} $ and $ T_{3} $ from the thyroid. Serum $ T_{4} $ and $ T_{3} $ levels are low, and thyroid-stimulating hormone (TSH) is increased.

Incorrect statements

[B] Oestrogen is considered to be the ''female'' hormone, whereas testosterone is considered the ''male'' hormone.

[E] Testosterone is a male sex hormone that is important for sexual and reproductive development.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.518Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2631, 5, NULL, NULL, 'Which of the following sols are correctly matched with their corresponding charges?

(A) Cr(OH) $ _{3} $ sol : negatively changed sol

(B) TiO $ _{2} $ sol : positively charged sol

(C) CdS sol : positively charged sol

(D) Gum : negatively charged sol

(E) Silver sol : positively charged sol', NULL, '[{"text":"(C) and (E) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(B) and (E) only","image_url":null,"alt":null},{"text":"(B) and (D) only","image_url":null,"alt":null}]', NULL, 3, '(a) Negatively charged colloids • Metal sulphides: As_{2}S_{3}, CdS

Metal dispersions: Ag, Au, Pt

Sulphur sol

Sols of starch, gums, gold, gelatin etc

Positively charged colloids

Metal hydroxides: Al(OH)_{3}, Fe(OH)_{3}

Metal oxide: TiO_{2}

Positively charged sols are: $ \mathrm{Fe(OH)}_{3} $, $ \mathrm{Al(OH)}_{3} $, methyleneblue, Haemoglobin, $ \mathrm{Cr(OH)}_{3} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.518Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2632, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null}]', NULL, 3, '[A] An alcohol used as antifreeze compound is ethylene glycol

[B] Phenol is used as starting material in the manufacture of nylon, plastics, aspirin, picric acid, and salicylic acid, etc.

[C] Methyl alcohol or Methanol is obtained by the process of destructive distillation of wood. It leads to the degradation of unprocessed materials by heating. Hence, Methanol is called as "Wood spirit".

[D] Soaps are sodium or potassium salt of fatty acids, made by hydrolysis of fats and oils with bases. This process yields soap as a product and glycerol as by-product.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q34-table-1.jpg', 'Table for question 34', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.519Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q34-table-1.jpg","alt":"Table for question 34","kind":"table"},{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q34-table-2.jpg","alt":"Table for question 34","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2633, 5, NULL, NULL, 't99.9% with respect to t90% for a first order reaction is:', NULL, '[{"text":"Two","image_url":null,"alt":null},{"text":"One","image_url":null,"alt":null},{"text":"Three","image_url":null,"alt":null},{"text":"Four","image_url":null,"alt":null}]', NULL, 2, 'For first order reaction:

$ \text{kt} = \ln [A_0] / [A_t] $

at t = 0 \quad A_0

at $ t = t_{0.999} $ \quad 0.001A_0

at $ t = t_{0.90} $ \quad 0.1 A_0

$ t_{0.999} / t_{0.90} = \ln 10^3 / \ln 10 = 3 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.519Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2634, 5, NULL, NULL, 'Predict the major product in the following reaction

$ \ce{ \chemfig{*6(=-=-=-)}-N+ \equiv NCl- } $ + $ \ce{ \chemfig{*6(=-(-Phen)=-=)}-OH} $ $ \xrightarrow{\ce{OH-}} $ ?', NULL, '[{"text":"p-Aminoazobeneze","image_url":null,"alt":null},{"text":"p-Hydroxyozobenzene","image_url":null,"alt":null},{"text":"Sulphanilic acid","image_url":null,"alt":null},{"text":"Phenol","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.520Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2635, 5, NULL, NULL, 'Which of the following are fat soluble vitamins:

(A) vit A

(B) vit B

(C) vit D

(D) vit E

(E) vit K', NULL, '[{"text":"(A), (B), (D) and (E) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (C), (D) and (E) only","image_url":null,"alt":null},{"text":"(B), (C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 2, 'Vitamins A, D, E, and K are called the fat-soluble vitamins, because they are soluble in organic solvents and are absorbed and transported in a manner similar to that of fats.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.520Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2636, 5, NULL, NULL, 'In a reaction:

$ \text{MnO}_4^- + 8\text{H}^+ + 5e \rightarrow \underline{\quad\text{A}\quad} + \text{H}_2\text{O} $

A stands for:', NULL, '[{"text":"$ \\text{Mn}^{3+} $","image_url":null,"alt":null},{"text":"$ \\text{Mn}^{4+} $","image_url":null,"alt":null},{"text":"$ \\text{Mn}^{2+} $","image_url":null,"alt":null},{"text":"$ \\text{Mn}^+ $","image_url":null,"alt":null}]', NULL, 2, '$ MnO_{4}^{-} + 8H^{+} 5e^{-} \rightarrow Mn^{2+} + 4H_{2}O $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.521Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2637, 5, NULL, NULL, 'If we use molten NaCl, the products of electrolysis are _.', NULL, '[{"text":"H $ _{2} $ gas and Cl $ _{2} $ gas","image_url":null,"alt":null},{"text":"NaOH and Cl_{2} gas","image_url":null,"alt":null},{"text":"H_{2}O and Cl_{2} gas","image_url":null,"alt":null},{"text":"Sodium metal and Cl_{2} gas","image_url":null,"alt":null}]', NULL, 3, 'During electrolysis of molten NaCl, sodium metal is deposited at the cathode, whereas, chlorine is liberated at the anode.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.521Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2638, 5, NULL, NULL, 'Which statement is not true for a detergent molecule?', NULL, '[{"text":"It is not biodegradable","image_url":null,"alt":null},{"text":"It is a surface active agent","image_url":null,"alt":null},{"text":"It has a non-polar organic part and a polar non-organic part","image_url":null,"alt":null},{"text":"It is sodium salt of fatty acid Direction for the question 41 to 45: Question is based on following passage: Methyl nitrile is hydrolysed to carboxylic acid in the presence of $ H^{+} $ or $ OH^{-} $ as catalyst. An intermediate compound [A] is formed during this reaction.","image_url":null,"alt":null}]', NULL, 3, 'Detergents are sodium salt of sulphonic acids.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.521Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2639, 5, NULL, NULL, 'The intermediate compound [Al is:', NULL, '[{"text":"Methyl isocyanide","image_url":null,"alt":null},{"text":"Ethyl amine","image_url":null,"alt":null},{"text":"Ethanamide","image_url":null,"alt":null},{"text":"Methanamide","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.522Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2640, 5, NULL, NULL, 'Converting [A] into [C] is called:', NULL, '[{"text":"Ammonolysis","image_url":null,"alt":null},{"text":"Hoffmann Degradation Reaction","image_url":null,"alt":null},{"text":"Carbylamine reaction","image_url":null,"alt":null},{"text":"Gabriel phthalamide reaction","image_url":null,"alt":null}]', NULL, 1, 'Ethanamide is treated with bromine and boiled with NaOH produces methyl amine.

This is Hoffmann''s bromamide reaction or Hoffmann''s degradation reaction.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.522Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2641, 5, NULL, NULL, 'The sweet smelling compound [D] is:', NULL, '[{"text":"Acid anhydride","image_url":null,"alt":null},{"text":"Acyl halide","image_url":null,"alt":null},{"text":"Aldehyde","image_url":null,"alt":null},{"text":"Ester","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.522Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2642, 5, NULL, NULL, 'What is not true regarding compound [B]?

(A) They are higher boiling liquids than aldehydes and ketones due to extensive H Bonding

(B) They are soluble in Benzene

(C) They produce alkane when heated with soda lime

(D) Produces CO₂ when treated with NaHCO₃', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(B) only","image_url":null,"alt":null},{"text":"(A) only","image_url":null,"alt":null}]', NULL, 2, 'Acetic acid is a polar molecule while benzene is a non-polar solvent. So, acetic acid cannot dissolve in benzene.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.523Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2643, 5, NULL, NULL, 'Which of the following is the correct statement for hybridization of C-atom and number of and $ \Pi $ bonds in the Carbonyl group?', NULL, '[{"text":"$ Sp^{2} $, $ 3\\sigma $, $ 1\\pi $","image_url":null,"alt":null},{"text":"Sp, $ 3\\sigma $, $ 1\\pi $","image_url":null,"alt":null},{"text":"$ Sp^{3} $, $ 3\\sigma $, $ 1\\pi $","image_url":null,"alt":null},{"text":"$ Sp^{2} $, $ 2\\sigma $, $ 2\\pi $ Direction for the question 46 to 50: Question is based on following passage: p-block elements are placed in groups 13 to 18 of the periodic table. Group 15 is nitrogen family. Nitrogen makes various compounds like NH₃, HNO₃, N₂O, NO₂ etc. Phosphorus exists in the form of white and red phosphorus. White phosphorus glows in dark. PH₃ gas is used as smoke screen. Group 16 is called oxygen family. Dry air contains 21% O₂ gas by volume. Combined sulphur exists as sulphates such as gypsum, eposome salt, baryte etc. The allotropic forms of sulphur are Rhombic and monoclinic sulphur. $ S_{2} $ is paramagnetic like $ O_{2} $ and it stable at high temperature. Group 17 is Halogen family. $ F_{2} $ is highly reactive, $ Cl_{2} $ is greenish yellow gas. Both $ SO_{2} $ and $ Cl_{2} $ are used for bleaching. Group 18 is Noble gas family but some noble gases also form compounds. Complete hydrolysis of $ XeF_{6} $ gives HF and $ XeO_{3} $ as main products.","image_url":null,"alt":null}]', NULL, 0, 'The carbonyl carbon and oxygen are sp2-hybridized with 3 sigma and 1 pi bond.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.523Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2644, 5, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null}]', NULL, 0, '[A] Ammonia is used in the detection of Cu $ ^{2+} $ ion

[A] Ammonia is used in the detection of Cu $ ^{2+} $ ion

[B] The Ostwald process is a process used for manufacturing Nitric acid.

[C] Phosphine is a colourless gas with rotten fish smell and is highly poisonous.

[D] One of the oldest known chemiluminescent reactions is that of elemental white phosphorus oxidizing in moist air, producing a green glow.', NULL, NULL, 2023, '/local-papers/assets/chemistry-2023-06-15-shift-1/q46-table-1.jpg', 'Table for question 46', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.523Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2023-06-15-shift-1/q46-table-1.jpg","alt":"Table for question 46","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2645, 5, NULL, NULL, 'Sulphate of magnesium of the following is:', NULL, '[{"text":"Gypsum","image_url":null,"alt":null},{"text":"Epsom salt","image_url":null,"alt":null},{"text":"Baryte","image_url":null,"alt":null},{"text":"Galena","image_url":null,"alt":null}]', NULL, 1, 'Epsom salt is also known as magnesium sulfate. It''s a chemical compound made up of magnesium, sulfur, and oxygen.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.524Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2646, 5, NULL, NULL, 'At elevated temperature (~1000 K) the dominant form of sulphur is:', NULL, '[{"text":"Rhombic Sulphur","image_url":null,"alt":null},{"text":"Monoclinic Sulphur","image_url":null,"alt":null},{"text":"S_{8} molecules","image_url":null,"alt":null},{"text":"S_{2}","image_url":null,"alt":null}]', NULL, 3, 'At elevated temperatures (~1000 K), S₂ is the dominant species and is paramagnetic like O₂.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.524Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2647, 5, NULL, NULL, 'The permanent bleaching effect is caused by:', NULL, '[{"text":"Chlorine gas","image_url":null,"alt":null},{"text":"$ SO_{2} $ gas","image_url":null,"alt":null},{"text":"Aqua Regia","image_url":null,"alt":null},{"text":"$ COCl_{2} $","image_url":null,"alt":null}]', NULL, 0, 'Chlorine''s bleaching activity is permanent since it includes the oxidation process. Chlorine produces nascent oxygen when it combines with water. This oxygen reacts with the pigments in the substance, rendering it colourless. It has a strong oxidising effect.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.525Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
