INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2660, 1, NULL, NULL, 'The key elements of an Entertaining Speech are:

A. It is not time bound; it can go on forever

B. It needs a good opening with anecdotes

C. It should be a third person account

D. It is effective when presented in the first-person account and in the present tense

E. It is knowledge based', NULL, '[{"text":"A and E only","image_url":null,"alt":null},{"text":"B and D only","image_url":null,"alt":null},{"text":"C and E only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.535Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
