INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2703, 1, NULL, NULL, 'What is the theme of the poem?', NULL, '[{"text":"Enjoying the present time","image_url":null,"alt":null},{"text":"Fleeting nature of youth","image_url":null,"alt":null},{"text":"Time give false vows","image_url":null,"alt":null},{"text":"Breaking of humans promises Read the following passage carefully and answer the question given below. In the late 1950s, solar cells were adopted by NASA to power satellites. The space industry''s pioneering of solar technology for use in spacecraft has contributed to the advancement, reliability, and cost effectiveness of solar technology. PV panels are most commonly seen on rooftops and walls, but nowadays, anything from clocks, watches, calculating, road signs and bus shelters to houses and commercial buildings can run on power generated by PV system. Areas of PV arrays known as solar farms produce electricity on a scale large enough to be distributed through a power grid to thousands of homes. The world''s largest solar farm, Waldpolenz Solar Park near Leipzig, Germany, covers 110 hectares $ ^{2} $ and uses state-of-the-art thin-film photovoltaic technology to produce 40,000 megawatts (MW) of electricity. Concentrating solar power (CSP) uses large minors or receiving collectors to concentrate the sun''s radiation on pipes, tubes, or cylinders filled with fluid or gas. An intense heat of $ 160^{\\circ} $ to $ 540^{\\circ} $ C ( $ 300^{\\circ} $ to $ 1.000^{\\circ} $F) creates steam or expands gas to drive a turbine or electricity generator. High-temperature collectors, such as giant parabolic dishes covered with mirrors, generate large amounts of electricity that is fed into a power grid. In the 1980s, nine thermal solar power plants with a combined capacity of 354 MW were built in the Mojave Desert. The Ivanpah Solar Power facility, which is still under construction in the southwestern United States, will have a combined capacity of 392 MW. Another form of collector technology is solar thermal energy, which heats swimming pools and household water. The first solar water heater was patented in the United States in 1891. and by 1897. nearly a third of the homes in Pasadena. California, had installed a solar water heating system. Interest in these system revived in the late 1970s but in the mid-1980s, their popularity'' declined with energy prices and the expiration of federal tax credit. Direction Q6 to Q10","image_url":null,"alt":null}]', NULL, 1, 'Fleeting nature of youth.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.565Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
