INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2801, 1, NULL, NULL, 'All of a sudden a dog became boisterous and it bit a child in the leg. The dog got angry mainly because:', NULL, '[{"text":"One boy did mischief","image_url":null,"alt":null},{"text":"Dog was feeling hungry","image_url":null,"alt":null},{"text":"Dog saw another dog","image_url":null,"alt":null},{"text":"Boy did not give food to the dog.","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.630Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
