INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2905, 1, NULL, NULL, 'The passage is about:', NULL, '[{"text":"two friends","image_url":null,"alt":null},{"text":"two friends who turned rivals","image_url":null,"alt":null},{"text":"two enemies","image_url":null,"alt":null},{"text":"two strangers Direction for Q11 to Q15. In stark contrast to where I grew up-in warm, lush green Trivandrum, Kerala, filled with rich sights, sounds and people-life at the Poles is quiet. The harshness of winter brings along with it an eerie desolation and near-total silence. Survival in this frigid, dark and windy terrain is only for the fittest. A misstep can mean anything from an icy injury to a bitter, benumbed death. But while it is tenuous, life here is also humbling-physically, mentally, and even spiritually. The experience has allowed me to witness the wonderful qualities of nature: raw, brutal and unforgiving but nurturing and awe-inspiring at the same time. As the days shorten, almost all life starts to depart seeking warmer lands. But those who stay are surrounded by glacial beauty and an otherworldly stillness that stands unmatched. In peak winter months, the sun seems to live only in memory. Its absence however, is only an illusion: shimmering displays of blue, red, yellow, green, and orange auroras shifting and snaking like billowing curtains across the pitch black sky remind me that the light shall one day return. Even the emptiness of the land is deceptive. Look closely and out waddles a flock of penguins from behind an ice shelf on the Antarctic peninsula","image_url":null,"alt":null}]', NULL, 1, 'two friends who turned rivals', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.701Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
