INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3052, 1, NULL, NULL, 'Which of the following could be a suitable title for the passage?', NULL, '[{"text":"How to conduct an Interview","image_url":null,"alt":null},{"text":"How to give an Interview","image_url":null,"alt":null},{"text":"An Introduction to Interviews","image_url":null,"alt":null},{"text":"How to get a Job Direction for Q11. to Q15. Read the following passage and answer the question that follows: Learning the Queen''s English is like scrubbing off the bright red varnish from your toe nails, the morning after a dance. It takes a long time and there is always a little bit left at the end, a stain of red along the growing edges to remind you of the good time you had. So, you can see that learning came slowly to me. On the other hand, I had plenty of time. I learned your language in an immigration detention centre, in Essex, in the southeastern part of the United Kingdom. Two years, they locked me in there. Time was all I had. But why did I go to all the trouble? It is because of what some of the older girls explained to me: to survive, you must look good or talk even better. The plain ones and the silent ones, it seems their paperwork in never in order. You say, they get repatriated. We say, sent home early. The Other Hand is the story of a young woman who flees conflict in her home village in the oil-rich region of southern Nigeria. She makes her way to the UK as an illegal immigrant and is detained for a long period of time at an immigrant detention centre near London. When she finally gets out, she seeks out the only two people she knows in England, whom she met on a Nigerian beach during a life-changing event a few years before. Will she be able to find them, and if so will they help her? And if not, will she survive in her newly adopted country as an immigrant?","image_url":null,"alt":null}]', NULL, 0, 'How to conduct an interview', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.806Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
