INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3094, 18, NULL, NULL, 'The area of a circle is numerically equal to its circumference. Find the diameter of the circle.', NULL, '[{"text":"2 unit","image_url":null,"alt":null},{"text":"4 unit","image_url":null,"alt":null},{"text":"1 unit","image_url":null,"alt":null},{"text":"5 unit","image_url":null,"alt":null}]', NULL, 1, 'Area of circle = Circumference of circle $ \pi r^{2} = 2\pi r $

$ r^{2} = 2r $

r = 2 Then d = 2r = 4 units', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.829Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3095, 18, NULL, NULL, 'Which of the following players didn''t receive Medal in Tokyo Olympics 2020?', NULL, '[{"text":"PV Sindhu","image_url":null,"alt":null},{"text":"Neeraj Chopra","image_url":null,"alt":null},{"text":"Abhinav Bindra","image_url":null,"alt":null},{"text":"Ravi Kumar Dahiya","image_url":null,"alt":null}]', NULL, 2, '(a) P. V. Sindhu received Bronze medal in Badminton

(b) Neeraj Chopra received Gold medal in men''s Javelin throw

(c) Abhinav Bindra did not receive any medal in Tokyo Olympic 2020 games.

(d) Ravi Kumar Dahiya received silver medal in wrestling.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.831Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3096, 18, NULL, NULL, 'Find the angle traced by hour hand of a correct clock between 7 pm 0 clock and 2 am 0 clock.', NULL, '[{"text":"200°","image_url":null,"alt":null},{"text":"210°","image_url":null,"alt":null},{"text":"310°","image_url":null,"alt":null},{"text":"290°","image_url":null,"alt":null}]', NULL, 1, 'Angle made by hour hand in 1 hour = $ 30^{\circ} $

7 pm to 2 am = 7 hours.

Angle traced = $ 30^{\circ} \times 7 = 210^{\circ} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.831Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3097, 18, NULL, NULL, 'Consider the Diagram:

Math

500 Candidates appeared in an Examination comprising test in English, Hindi and Maths. The Diagram gives number of students who failed in different tests. What is the % percentage of student who failed at least two subjects?', NULL, '[{"text":"6.8%","image_url":null,"alt":null},{"text":"7.8%","image_url":null,"alt":null},{"text":"1.0%","image_url":null,"alt":null},{"text":"0.078%","image_url":null,"alt":null}]', NULL, 1, 'No. of students failed in at least two subjects = 10 + 5 + 12 + 12 = 39

Percentage= $ \frac{39}{100} \times 100 = 7.8\% $', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-05-21-shift-1/q05-figure-1.jpg', 'Figure for question 5', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.832Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-05-21-shift-1/q05-figure-1.jpg","alt":"Figure for question 5","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3098, 18, NULL, NULL, 'A railway half-ticket costs half the full ticket. However, the reservation charge for all the tickets is constant. One full reserved ticket for a journey is 2525. If the cost of one full and one half reserved ticket for the same journey is 1850, then what is the reservation charge per ticket?', NULL, '[{"text":"2120","image_url":null,"alt":null},{"text":"2150","image_url":null,"alt":null},{"text":"2125","image_url":null,"alt":null},{"text":"2115","image_url":null,"alt":null}]', NULL, 2, 'Let x be the fare and y be reservation char

$ x + y = 525 \ldots (i) $

One full and one-half ticket = $ 1 + \frac{1}{2} = \frac{3}{2} $

Cost of half ticket = x/2

$ x + y + \frac{x}{2} + y = 850 $

$ \frac{3}{2}x + 2y = 850 $

$ 3x + 4y = 1700 \ldots (ii) $

Solving (i) & (ii),

x = 400 ... (iii)

Using (iii) in (i), y = 125

So, reservation charge is ₹125.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.833Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3099, 18, NULL, NULL, 'A and B can do a work in 9 days and 12 days respectively. If they work on alternate days starting with A, then in how many days will the work be completed?', NULL, '[{"text":"36 days","image_url":null,"alt":null},{"text":"10 days","image_url":null,"alt":null},{"text":"10 days","image_url":null,"alt":null},{"text":"13 days","image_url":null,"alt":null}]', NULL, 2, '$ \frac{36}{7} = 5 $ (1 rem) means 10 days and 1 unit work is remaining which is done by $ A = \frac{1}{4} $

So, total to be taken = 10 $ \frac{1}{4} $ days', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.834Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
