INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3102, 18, NULL, NULL, 'Major is related to Lieutenant in the same way as ''Squadron Leader is Related to ''?', NULL, '[{"text":"Pilot officer","image_url":null,"alt":null},{"text":"Flying Attendant","image_url":null,"alt":null},{"text":"Group captain","image_url":null,"alt":null},{"text":"Flying officer","image_url":null,"alt":null}]', NULL, 3, 'Major and Squadron Leader are equivalent ranks in Army and Air Force respectively. In the same way Lieutenant and Flying officer are equivalent ranks in Army and Air Force respectively.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.835Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
