INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3104, 18, NULL, NULL, 'Major Constituent of natural gas is _.', NULL, '[{"text":"Propane","image_url":null,"alt":null},{"text":"Butane","image_url":null,"alt":null},{"text":"Methane","image_url":null,"alt":null},{"text":"Carbon","image_url":null,"alt":null}]', NULL, 2, 'Natural gas consists of methane (85%), ethane (10%) and little amount of propane and butane. Thus, the major constituent of natural gas would be methane.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.836Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3105, 18, NULL, NULL, 'How many terms are there in the A.P. 3, 7, 11, ....., 407?', NULL, '[{"text":"100","image_url":null,"alt":null},{"text":"101","image_url":null,"alt":null},{"text":"99","image_url":null,"alt":null},{"text":"102","image_url":null,"alt":null}]', NULL, 3, 'Given 3, 7, 11, ... 407

So given sequence in A.P, with a = 3, d = 4

Now Tn = 407

$ \Rightarrow a + (n - 1)d = 407 $

$ \Rightarrow 3 + (n - 1)4 = 407 $

$ \Rightarrow n = 102 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.836Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3106, 18, NULL, NULL, 'Which of the following is a metal?', NULL, '[{"text":"Carban","image_url":null,"alt":null},{"text":"Mercury","image_url":null,"alt":null},{"text":"Sulphur","image_url":null,"alt":null},{"text":"Iodine","image_url":null,"alt":null}]', NULL, 1, 'Except mercury, all options belong to non-metal. Thus, mercury is metal.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.837Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3107, 18, NULL, NULL, 'X got 98 marks in his exam which is 56% of the total marks. What is the maximum marks of the exam?', NULL, '[{"text":"150","image_url":null,"alt":null},{"text":"175","image_url":null,"alt":null},{"text":"200","image_url":null,"alt":null},{"text":"225","image_url":null,"alt":null}]', NULL, 1, '56% → 98

1% → 98/56

100% → $ \frac{98}{56} \times 100 = 175 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.838Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
