INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3110, 18, NULL, NULL, 'Statement I: Constitution is the framework for the governance of a country which delegates power and authority to the executive, legislative and judiciary. Statement II: It serves a country in maintaining good relationships with her neighbouring countries. In the light of the above statements, chose the most appropriate war from the options below.', NULL, '[{"text":"Both Statement I and Statement II are correct","image_url":null,"alt":null},{"text":"Both Statement I and Statement II are incorrect","image_url":null,"alt":null},{"text":"Statement I is correct but Statement II is incorrect","image_url":null,"alt":null},{"text":"Statement I is incorrect but Statement II is correct","image_url":null,"alt":null}]', NULL, 0, 'Statement-I: Constitution of India provides for delegation of power and authority among three organs of state viz executive, legislative and judiciary. Thus, it is true statement Statement-II: Constitution through Article 51 provides for maintenance of international peace and good relationships with her neighbouring countries. Thus, this statement is also true.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.840Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3111, 18, NULL, NULL, 'Which of the following speeds is the least?', NULL, '[{"text":"50 meter/second","image_url":null,"alt":null},{"text":"50 meter/minute","image_url":null,"alt":null},{"text":"70 km/hour","image_url":null,"alt":null},{"text":"5 km/minute","image_url":null,"alt":null}]', NULL, 1, '50 m/s → 180 km/h

50 m/min → 3 km/h

70 km/h → 70 km/h

5 km/min → 300 km/h

So, 50 m/min is the least.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.841Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3112, 18, NULL, NULL, 'Which of the following is not a ''state''?', NULL, '[{"text":"Nagaland","image_url":null,"alt":null},{"text":"Manipur","image_url":null,"alt":null},{"text":"Ladakh","image_url":null,"alt":null},{"text":"Meghalaya","image_url":null,"alt":null}]', NULL, 2, 'Among the given options, Ladakh is correct because it has been made a Union Territory by The Jammu and Kashmir Reorganisation Act 2019.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.841Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3113, 18, NULL, NULL, 'In a row of 40 children. A is 13th from the left end and B is ninth from the right end. How many children are there between A and C if C is fourth to the left of B.', NULL, '[{"text":"13","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null}]', NULL, 1, 'C''s rank from right = 9 + 4 = 13th

So, C''s rank from left = (40 - 13) + 1 = 28th

Number of students between A and C = (28 - 13) - 1 = 14', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.842Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3114, 18, NULL, NULL, 'Find the perimeter of a rhombus whose one diagonal is 16 cm long and area is 240 cm².', NULL, '[{"text":"68 cm","image_url":null,"alt":null},{"text":"30 cm","image_url":null,"alt":null},{"text":"24 cm","image_url":null,"alt":null},{"text":"36 cm","image_url":null,"alt":null}]', NULL, 0, 'Area = 240 cm², One diagonal = 16 cm

Second diagonal = $ \frac{\text{Area} \times 2}{\text{d}_1} = \frac{240 \times 2}{16} = 30 $ cm

Perimeter =

$ 2\sqrt{(d_1)^2 + (d_2)^2} = 2\sqrt{(16)^2 + (30)^2} = 68 $ cm', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.843Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3115, 18, NULL, NULL, 'If today is Saturday, then what will be the day on 363 $ ^{rd} $ day?', NULL, '[{"text":"Sunday","image_url":null,"alt":null},{"text":"Monday","image_url":null,"alt":null},{"text":"Thursday","image_url":null,"alt":null},{"text":"Friday","image_url":null,"alt":null}]', NULL, 3, '363/7 = 6 remainder

Saturday + 6 = Friday', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.845Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3116, 18, NULL, NULL, 'Arrange the following in meaningful sequence:

A. Key B. Door

C. Lock D. Room', NULL, '[{"text":"A, C, B, D","image_url":null,"alt":null},{"text":"D, C, A, B","image_url":null,"alt":null},{"text":"B, A, D, C","image_url":null,"alt":null},{"text":"C, B, D, A","image_url":null,"alt":null}]', NULL, 0, 'At first, we have to key, then we unlock the lock, then open the door and enter into room. So, sequence is $ \rightarrow $ A, C, B, D', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.846Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
