INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3118, 18, NULL, NULL, 'Find the next term in the alpha-numeric series D4T, F9R, H20P, J43N.', NULL, '[{"text":"L 90 M","image_url":null,"alt":null},{"text":"N 90 N","image_url":null,"alt":null},{"text":"L 90 L","image_url":null,"alt":null},{"text":"J 90 L","image_url":null,"alt":null}]', NULL, 2, 'D 4 T, F 9 R, H 20 P, J 43 N, L 90 L

