INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3119, 18, NULL, NULL, 'If the median of $ \frac{x}{5}, x, \frac{x}{4}, \frac{x}{2} $ and $ \frac{x}{3} $ (where x > 0) is 8, then the value of x will be', NULL, '[{"text":"24","image_url":null,"alt":null},{"text":"32","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null}]', NULL, 0, 'Arrange in ascending order: $ \frac{x}{5}, \frac{x}{4}, \frac{x}{3}, \frac{x}{2}, x $

Middle value $ =\frac{x}{3}=8 \Rightarrow x = 24 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.850Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3120, 18, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I. B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-III, B-I. C-IV, D-II","image_url":null,"alt":null},{"text":"A-III. B-I. C-II. D-IV","image_url":null,"alt":null},{"text":"A-I. B-IV, C-II, D-III","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-05-21-shift-1/q29-table-1.jpg', 'Table for question 29', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.850Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-05-21-shift-1/q29-table-1.jpg","alt":"Table for question 29","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3121, 18, NULL, NULL, 'Which book is written by Dr. S. Radhakrishnan?', NULL, '[{"text":"The world''s largest democracy","image_url":null,"alt":null},{"text":"India divided","image_url":null,"alt":null},{"text":"Indian Philosophy","image_url":null,"alt":null},{"text":"India Priceless heritage","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.851Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3122, 18, NULL, NULL, 'A is 3 years younger than C but one year older than D.

D is one year older than B but 4 years younger than C.

Cis 15 years old. What is the age of B in years', NULL, '[{"text":"13","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null},{"text":"11","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null}]', NULL, 3, '$$ A=C-3 $$

$$ A=D+1 $$

D=B+1

D=C-4

C = 15 So, D = 11, A = 12, B = 10 So, B''s age is 10 years old.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.852Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3123, 18, NULL, NULL, 'A man walks 2 km towards East and then he turns to South and walks 6 km. Again, he turns to East and walks 4 km, after this he turns to North and walk 14 km. How far is he from his starting point?', NULL, '[{"text":"10 km","image_url":null,"alt":null},{"text":"15 km","image_url":null,"alt":null},{"text":"20 km","image_url":null,"alt":null},{"text":"25 km","image_url":null,"alt":null}]', NULL, 0, 'Using Pythagoras theorem: $ H^{2} = 64 + 36 = 10 $ Km. So, he is 10 km away from his starting point', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.852Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3124, 18, NULL, NULL, 'A bag contains 5 black. 3 white and 2 red balls. Three balls are drawn in succession. What is the probability that the first ball is red, the second ball is black and the third ball is white?', NULL, '[{"text":"$ \\frac{1}{24} $","image_url":null,"alt":null},{"text":"$ \\frac{3}{10} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{10} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{2} $","image_url":null,"alt":null}]', NULL, 0, '$$ \frac{2}{10}\times\frac{5}{9}\times\frac{3}{8}=\frac{1}{24} $$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.853Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3125, 18, NULL, NULL, 'What is the smallest square number which is divisible by 4, 6 and 32?', NULL, '[{"text":"100","image_url":null,"alt":null},{"text":"196","image_url":null,"alt":null},{"text":"96","image_url":null,"alt":null},{"text":"576","image_url":null,"alt":null}]', NULL, 3, 'L.C.M of 4, 6 and 32 = 96 = 2 $ \times $ 2 $ \times $ 2 $ \times $ 2 $ \times $ 3

2 and 3 are not in pairs, so we multiply them to 96

$ \Rightarrow 96 \times 2 \times 3 = 576 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.853Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
