INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3129, 18, NULL, NULL, 'Which of the following is not the satellite launched by India?', NULL, '[{"text":"Explorer","image_url":null,"alt":null},{"text":"APPLE","image_url":null,"alt":null},{"text":"Bhaskar","image_url":null,"alt":null},{"text":"INSAT","image_url":null,"alt":null}]', NULL, 0, 'Satellite, APPLE, Bhaskar and INSAT were launched by India or are associated with Indian Space Research Organisation (ISRO) while explorer was the first satellite launched by United States in 1958.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.856Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3130, 18, NULL, NULL, 'If the 2nd half of the letters of the word INTERMEDIATE is reversed and placed before 1st half of the letters, which letter will be 2nd to the right of 10th letter from the right?', NULL, '[{"text":"A","image_url":null,"alt":null},{"text":"D","image_url":null,"alt":null},{"text":"E","image_url":null,"alt":null},{"text":"I","image_url":null,"alt":null}]', NULL, 1, 'Word: INTERMEDIATE

Reverse 2nd half and placed before 1st half

ETAIDEINTERM

10 - 2 = 8th from right which is D.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.856Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3131, 18, NULL, NULL, 'Find the angle of elevation of the Sun when the length of the shadow of a tree is $ \frac{1}{\sqrt{3}} $ times the height of the tree.', NULL, '[{"text":"$ 30^{\\circ} $","image_url":null,"alt":null},{"text":"$ 45^{\\circ} $","image_url":null,"alt":null},{"text":"$ 60^{\\circ} $","image_url":null,"alt":null},{"text":"$ 90^{\\circ} $","image_url":null,"alt":null}]', NULL, 2, '$$ \tan\theta=\frac{h}{h/\sqrt{3}} $$

\tan\theta = \sqrt{3}

$ \theta = 60^{0} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.857Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3132, 18, NULL, NULL, 'The point (-2, 3) lies in which quadrant?', NULL, '[{"text":"I","image_url":null,"alt":null},{"text":"II","image_url":null,"alt":null},{"text":"III","image_url":null,"alt":null},{"text":"IV","image_url":null,"alt":null}]', NULL, 1, '$ (-2, 3) $ here x is negative and y is positive. So, this point lies in 2nd quadrant.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.857Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3133, 18, NULL, NULL, 'The rate of ages of 2 boys is 37. After 2 years, the ratio of their ages will become 5:9. The ratio of their ages after 10 years will be', NULL, '[{"text":"15:16","image_url":null,"alt":null},{"text":"5:17","image_url":null,"alt":null},{"text":"17:18","image_url":null,"alt":null},{"text":"13:17","image_url":null,"alt":null}]', NULL, 3, 'Let their present age be 3x and 7x.

After two years, $ \frac{3x+2}{7x+2} = \frac{5}{9} $

x = 1

Present age = 3 years and 7 years

After 10 years = 3+10 = 13 and 7 + 10 = 17 = 13 : 17', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.857Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3134, 18, NULL, NULL, 'Who won the Noble Prize for in the field of "physiology or medicine"?', NULL, '[{"text":"C.V. Raman","image_url":null,"alt":null},{"text":"Jagdish Chandra Bose","image_url":null,"alt":null},{"text":"Homi Jehangir Bhabha","image_url":null,"alt":null},{"text":"Har Gobind Khorana","image_url":null,"alt":null}]', NULL, 3, '1968 Nobel Prize in the field of physiology or medicine was received by Har Gobind Khorana along with Marshall W. Nirenberg and Robert W. Holley for research that helped to show how the genetic components of the cell nucleus control the synthesis of proteins.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.858Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3135, 18, NULL, NULL, 'What is the probability that any non-leap year will have 53 Sundays?', NULL, '[{"text":"1/53","image_url":null,"alt":null},{"text":"2/53","image_url":null,"alt":null},{"text":"1/7","image_url":null,"alt":null},{"text":"2/7","image_url":null,"alt":null}]', NULL, 2, 'Any non-leap year has 365 days = 52 weeks + 1 day extra.

In 52 weeks, 52 Sundays are confirmed and 1 extra day will be any day of 7 days of week.

So, probability of getting Sunday in this week = 1/7', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.858Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3136, 18, NULL, NULL, 'In a class boys stand in a single line. One of the boys is seventeenth in order from both the ends. How many boys are in the class?', NULL, '[{"text":"34","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null},{"text":"32","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null}]', NULL, 1, 'Rank 1 → 17

Rank 2 → 17

Total = (R1 + R2) - 1 = 34 - 1 = 33', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.859Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3137, 18, NULL, NULL, 'What sum of money will amount to Rs. 520 in 5 years and to Rs. 568 in 7 years on simple interest?', NULL, '[{"text":"Rs. 400","image_url":null,"alt":null},{"text":"Rs. 120","image_url":null,"alt":null},{"text":"Rs. 510","image_url":null,"alt":null},{"text":"Rs. 220","image_url":null,"alt":null}]', NULL, 0, 'Amount in 5 years = Rs. 520

Amount in 7 years = Rs. 568

Interest of one year = $ \frac{48}{2} $ = Rs. 24

Interest of 5 years = $ 24 \times 5 = Rs.\ 120 $

So, sum = 520 - 120 = Rs. 400', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.861Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3138, 18, NULL, NULL, 'The minimum number of colours to required paint all sides of a cube that no two adjacent faces may have the same colour is.', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null}]', NULL, 2, 'Opposite sides have same colours. So, we need three different colours.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.862Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
