INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3140, 18, NULL, NULL, 'The relationship between the values of a country''s imports and its exports is called.', NULL, '[{"text":"Balance of Trade","image_url":null,"alt":null},{"text":"Balance of Payment","image_url":null,"alt":null},{"text":"Balance of currency","image_url":null,"alt":null},{"text":"Bill of exchange","image_url":null,"alt":null}]', NULL, 0, 'Balance of Trade is the relationship between values of a country''s imports and its exports. This balance of trade is constituent of balance of payment. Thus, correct answer is balance of trade.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.865Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3141, 18, NULL, NULL, 'Statements:

I. Some cars are black

II. Some Lions are cars

Conclusions:

I. Some blacks are Lions

II. No black is Lion', NULL, '[{"text":"Only I follow","image_url":null,"alt":null},{"text":"Only II follow","image_url":null,"alt":null},{"text":"Either I or II follows","image_url":null,"alt":null},{"text":"None follows","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.866Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3142, 18, NULL, NULL, 'The average of 12 numbers is 15 and the average of the first two numbers is 14. What is the average of the remaining numbers?', NULL, '[{"text":"15","image_url":null,"alt":null},{"text":"15.2","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null},{"text":"14:2","image_url":null,"alt":null}]', NULL, 1, 'Sum of 12 numbers = $ 12 \times 15 = 180 $

Sum of first 2 numbers = $ 2 \times 14 = 28 $

Sum of first two + Sum of remaining = 180

Sum of remaining = 180 - 28 = 152

Average = $ \frac{152}{10} $ = 15.2', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.867Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3143, 18, NULL, NULL, 'Find a single equivalent increase if the number is successively increased by 20%, 25% and 30%?', NULL, '[{"text":"75%","image_url":null,"alt":null},{"text":"85%","image_url":null,"alt":null},{"text":"95%","image_url":null,"alt":null},{"text":"35%","image_url":null,"alt":null}]', NULL, 2, 'Let original number = 100

Then after 20% it will be = 120

After 25% increase it will be = 120 $ \times $ 125\% = 150

After 30\% increase it will be = 150 $ \times $ 130\% = 195

So, single increase = $ \frac{195-100}{100} $ $ \times $ 100 = 95%', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.868Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
