INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3147, 18, NULL, NULL, 'Here are some words translated from an artificial language

Holo polo means base ball

Moto prot means my India

Prot shot means India won

Which word could be mean "All India Radio"', NULL, '[{"text":"Holo polo prot","image_url":null,"alt":null},{"text":"Kud prot nid","image_url":null,"alt":null},{"text":"Prot polo nid","image_url":null,"alt":null},{"text":"Polo nid prot","image_url":null,"alt":null}]', NULL, 1, '(1) Holo polo → Base ball

(2) Moto prot → My India

(3) Prot shot → India won India → Prot

from (2) and (3) So in 2nd option prot is in middle.

So, this answer because other two words unidentified.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.871Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3148, 18, NULL, NULL, 'If selling price of 80 articles is equal to the cost price of 100 articles, then find the gain percentage.', NULL, '[{"text":"30%","image_url":null,"alt":null},{"text":"25%","image_url":null,"alt":null},{"text":"40%","image_url":null,"alt":null},{"text":"50%","image_url":null,"alt":null}]', NULL, 1, '$ 100 \times CP = 80 \times SP $

$ \frac{SP}{CP} = \frac{100}{80} = \frac{5}{4} $

Gain \% = $ \left(\frac{5}{4} - 1\right) \times 100 = 25\% $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.872Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3149, 18, NULL, NULL, 'Find the angle of elevation of the Sun, when the length of the shadow of a tree is $ \frac{1}{\sqrt{3}} $ times the height of tree.', NULL, '[{"text":"$ 30^{\\circ} $","image_url":null,"alt":null},{"text":"$ 45^{\\circ} $","image_url":null,"alt":null},{"text":"$ 60^{\\circ} $","image_url":null,"alt":null},{"text":"$ 90^{\\circ} $","image_url":null,"alt":null}]', NULL, 2, '$$ \tan\theta=\frac{\mathrm{h}}{\mathrm{h}/\sqrt{3}}=\sqrt{3} $$

$$ \theta=60^{0} $$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.872Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
