INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3151, 18, NULL, NULL, 'Who appoints the chairman of the Union Public Service Commission?', NULL, '[{"text":"Prime Minister","image_url":null,"alt":null},{"text":"President","image_url":null,"alt":null},{"text":"Speaker of the Lok Saba","image_url":null,"alt":null},{"text":"Home Minister","image_url":null,"alt":null}]', NULL, 1, 'The Chairman and other members of the Union Public Service Commission are appointed by the President of India. This is mentioned in Article 316 of the Indian Constitution.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.875Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3152, 18, NULL, NULL, 'In which year "Panchayati Raj" was passed in Lok Sabha and Rajay Sabha?', NULL, '[{"text":"1985","image_url":null,"alt":null},{"text":"1989","image_url":null,"alt":null},{"text":"1992","image_url":null,"alt":null},{"text":"1995","image_url":null,"alt":null}]', NULL, 2, '"Panchayati Raj" was passed in both Lok Sabha and Rajya Sabha during the year 1992.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.876Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3153, 18, NULL, NULL, 'World population day is celebrated on:', NULL, '[{"text":"11 July","image_url":null,"alt":null},{"text":"11 June","image_url":null,"alt":null},{"text":"10 July","image_url":null,"alt":null},{"text":"05 June","image_url":null,"alt":null}]', NULL, 0, 'World Population Day is celebrated on 11th July every year to raise awareness about global population issues. The United Nations established this day in 1989.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.879Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3154, 18, NULL, NULL, 'Who is the author of the book "Speed Post"?', NULL, '[{"text":"Anita Nayyar","image_url":null,"alt":null},{"text":"Anita Desai","image_url":null,"alt":null},{"text":"Ritu Beri","image_url":null,"alt":null},{"text":"Shoba De","image_url":null,"alt":null}]', NULL, 3, '"Speedpost" is a book written by Shobha De.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.881Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3155, 18, NULL, NULL, 'The letters L, M, N, O, P, Q, R, S, T in their order is substituted by nine integers 1 to 9 in that order. 4 is assigned to P. The difference between P and T is 5. The difference between N and T is 3. What is the integer assigned to N?', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'ATQ, P is assigned to 4.

Difference b/w P and T is 5, so T is 9

Difference b/w N and T is 3 so N = 9 - 3 = 6

The integer assigned to N is 6.

Hence, 6 is the correct answer.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.882Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
