INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3157, 18, NULL, NULL, 'In the given question find the water image of the word "FAMILY".', NULL, '[{"text":"E V W I Γ ᴀ","image_url":null,"alt":null},{"text":"E V W I Γ ᴀ","image_url":null,"alt":null},{"text":"E V W I Γ ᴀ","image_url":null,"alt":null},{"text":"F V W I Γ ᴀ","image_url":null,"alt":null}]', NULL, 0, 'Har Gobind Khorana was awarded the Nobel Prize in Medicine in 1968 for his work on the interpretation of the genetic code and its function in protein synthesis. He shared the prize with Robert W. Holley and Marshall W. Nirenberg.

