INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3158, 18, NULL, NULL, 'Which of the following belongs to ''Harappan Culture''?', NULL, '[{"text":"Bronze Age","image_url":null,"alt":null},{"text":"Copper Age","image_url":null,"alt":null},{"text":"Iron Age","image_url":null,"alt":null},{"text":"Strong Age","image_url":null,"alt":null}]', NULL, 0, 'The Harappan civilization, also known as the Indus Valley Civilization, is often associated with the Bronze Age.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.884Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3159, 18, NULL, NULL, 'Choose the correct option (figure) after folding the figure along the dotted line.', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-05-27-shift-1/q09-figure-1.jpg', 'Figure for question 9', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.885Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-05-27-shift-1/q09-figure-1.jpg","alt":"Figure for question 9","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-05-27-shift-1/q09-options.jpg","alt":"Printed answer choices for question 9","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3160, 18, NULL, NULL, 'If 3 men or 9 boys can finish a work in 21 days, then in how many days can 5 men and 6 boys finish the same work?', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null},{"text":"11","image_url":null,"alt":null},{"text":"13","image_url":null,"alt":null}]', NULL, 1, 'Since 3 men or 9 boys do the work in 21 days, 1 man is equivalent to 3 boys.

The work involved is $ 9 \times 21 $ equivalent to 189 boydays.

So, 5 men and 6 boys are the same as $ 15 + 6 = 21 $ boys. So, the time taken is 189 boy-days/21 boys = 9 days.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.886Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3161, 18, NULL, NULL, 'The area of the largest circle, that can be drawn inside a rectangle with sides 63 cm and 42 cm is

$ (\pi = \frac{22}{7}) $', NULL, '[{"text":"1386 cm $ ^{2} $","image_url":null,"alt":null},{"text":"1586 cm $ ^{2} $","image_url":null,"alt":null},{"text":"1786 cm $ ^{2} $","image_url":null,"alt":null},{"text":"1986 cm","image_url":null,"alt":null}]', NULL, 0, 'The diameter of the circle = breadth of the rectangle = 42 cm

Hence the radius of the circle = 42/2 = 21 cm

The area of the circle = $ \pi r^{2} = \frac{22}{7} \times 21 \times 21 = 1386 \, cm^{2} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.886Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3162, 18, NULL, NULL, 'You are alone in the house and there is danger of thieves around. Just then, you hear a knock at door. You would', NULL, '[{"text":"open the door to see who is there.","image_url":null,"alt":null},{"text":"first peep out from the window to confirm whether you know the person","image_url":null,"alt":null},{"text":"not open the door.","image_url":null,"alt":null},{"text":"ask the servant to see who is there","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.887Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3163, 18, NULL, NULL, 'If A: B = $ \frac{1}{2} $: $ \frac{5}{8} $, B: C = $ \frac{1}{3} $: $ \frac{4}{5} $ and C: D = $ \frac{3}{4} $: $ \frac{5}{16} $ then the ratio A: B: C: D is:', NULL, '[{"text":"4:5:3:12","image_url":null,"alt":null},{"text":"4:12:3:5","image_url":null,"alt":null},{"text":"4:5:12:5","image_url":null,"alt":null},{"text":"4:12:5:3","image_url":null,"alt":null}]', NULL, 2, 'A: $B = \frac{1}{2} : \frac{5}{8} = 8 : 2$

$B : C = \frac{1}{3} : \frac{4}{5} = 5 : 12$

$C : D = \frac{3}{4} : \frac{5}{16} = 12 : 5$

$A : B : C : D = 4 : 5 : 12 : 5$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.888Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3164, 18, NULL, NULL, 'XY $\Longrightarrow$ Delete the last letter,

YZ $\Longrightarrow$ Replace the fourth letter with next in the alphabet,

ZX $\Longrightarrow$ Reverse the whole sequence of the letters.

Then LOGICAL $\Longrightarrow$ XY $\rightarrow$ YZ $\rightarrow$ ZX $\rightarrow$ ?', NULL, '[{"text":"ACLOJG","image_url":null,"alt":null},{"text":"ACOJGL","image_url":null,"alt":null},{"text":"ACJGOL","image_url":null,"alt":null},{"text":"ACGJOL","image_url":null,"alt":null}]', NULL, 2, 'Firstly, last letter will be deleted, so word would be ''LOGICA''

In the next step, $4^{th}$ letter would be replaced by next alphabet, so word would become ''LOGJCA''

In the last step, word would be reversed. So final word would be ''ACJGOL''.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.888Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3165, 18, NULL, NULL, 'Mohit is $15^{\text{th}}$ from the right end in a row of 49 boys.

What is his position from left end?', NULL, '[{"text":"35","image_url":null,"alt":null},{"text":"26","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null},{"text":"20","image_url":null,"alt":null}]', NULL, 0, 'Mohit''s position from the left end = 49 - 15 + 1 = 35', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.889Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3166, 18, NULL, NULL, 'If A $(2a+3b, a+6b)$ and B $(3a+4b, 2a+5b)$ are two points, then distance between the points A and B is:', NULL, '[{"text":"$2(a+b)$","image_url":null,"alt":null},{"text":"$\\sqrt{2}(a^{2}-b^{2})$","image_url":null,"alt":null},{"text":"2ab","image_url":null,"alt":null},{"text":"$\\sqrt{2(a^{2}+b^{2})}$","image_url":null,"alt":null}]', NULL, 3, 'Distance formula = $ \sqrt{(x_2 - x_1)^2 + (y_2 - y_1^2)} $ =

$ \sqrt{(3a + 4b - 2a - 3b)^2 + (2a + 5b - a - 6b)^2} $

$ \quad = \sqrt{(a + b)^2 + (a - b)^2} $

$ \quad = \sqrt{2(a^2 + b^2)} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.890Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3167, 18, NULL, NULL, 'The average of four numbers is 40. If the first number is one-third of the sum of the remaining numbers, then the first number is', NULL, '[{"text":"35","image_url":null,"alt":null},{"text":"50","image_url":null,"alt":null},{"text":"30","image_url":null,"alt":null},{"text":"40","image_url":null,"alt":null}]', NULL, 3, 'Let the first number be a

Sum of all four numbers = 4 × 40 = 160

$ a = \frac{1}{4}(160 - a) $

a = 40', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.890Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3168, 18, NULL, NULL, 'Pointing to a woman, Venus said, "She is the daughter of the only child of my grandmother." How is the woman related to Venus?', NULL, '[{"text":"Wife","image_url":null,"alt":null},{"text":"Niece","image_url":null,"alt":null},{"text":"Sister","image_url":null,"alt":null},{"text":"Cousin","image_url":null,"alt":null}]', NULL, 2, 'Daughter of only child of Venus'' Grandmother - Venus'' mother''s daughter or Venus'' father''s daughter. In both cases woman will be sister of Venus.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.890Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3169, 18, NULL, NULL, 'Which of these numbers 6400, 125, 261 and 4913 is not a perfect cube?', NULL, '[{"text":"6400","image_url":null,"alt":null},{"text":"125","image_url":null,"alt":null},{"text":"9261","image_url":null,"alt":null},{"text":"4913","image_url":null,"alt":null}]', NULL, 0, '6400 is not a perfect cube.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.891Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3170, 18, NULL, NULL, 'A stone statue of priest king has been found from:', NULL, '[{"text":"Harappa","image_url":null,"alt":null},{"text":"Mohenjo Daro","image_url":null,"alt":null},{"text":"Kalibangan","image_url":null,"alt":null},{"text":"Dholavira Which one of the four answers figure would come at the place of the question mark? (a) $$ \\boxed{\\bigtriangleup\\bigtriangleup\\circ\\Box} $$ (b) $ \\begin{array}{r} \\times \\\\ \\triangle \\bigcirc \\Box \\end{array} $ $$ \\boxed{\\bigcirc\\bigcirc\\bigtriangleup}\\times $$ $$ \\bigotimes_{\\Box}\\bigcirc\\bigtriangleup\\times $$","image_url":null,"alt":null}]', NULL, 1, 'The stone statue of the Priest King was found in Mohenjo Daro.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.891Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3171, 18, NULL, NULL, 'Starting from point A Tianna moves 20m till point C in north east direction before turning to her right. She walks 20m again turning to her right stopping at point B. How far is point A from point B.', NULL, '[{"text":"$ 20\\sqrt{2}m $","image_url":null,"alt":null},{"text":"$ 10\\sqrt{2}m $","image_url":null,"alt":null},{"text":"20m","image_url":null,"alt":null},{"text":"10m","image_url":null,"alt":null}]', NULL, 0, 'Required Distance = AB = $ \sqrt{20^2} + 20^2 = 20\sqrt{2} $m', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.892Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3172, 18, NULL, NULL, 'In a \triangle ABC right angled at B. if BC = 4 cm and \angle C = 60^{\circ}, then length of AC is:', NULL, '[{"text":"$ 8\\sqrt{3}cm $","image_url":null,"alt":null},{"text":"$ \\frac{8}{\\sqrt{3}} $","image_url":null,"alt":null},{"text":"6 cm","image_url":null,"alt":null},{"text":"8 cm","image_url":null,"alt":null}]', NULL, 0, 'Ans. (a)

$ \cos 60^{\circ} = \frac{BC}{AC} $

$ \frac{\sqrt{3}}{2} = \frac{4}{x} $

$ AC = 8\sqrt{3} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.892Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3173, 18, NULL, NULL, '_ is the heaviest gas.', NULL, '[{"text":"Radon gas","image_url":null,"alt":null},{"text":"Carbon Monoxide","image_url":null,"alt":null},{"text":"Sulphur Dioxide","image_url":null,"alt":null},{"text":"Nitrogen Oxide","image_url":null,"alt":null}]', NULL, 0, 'Radon gas is the heaviest gas. Radon is a radioactive gas that is colorless, odorless, and tasteless.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.893Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3174, 18, NULL, NULL, 'If in a certain code, ALMIRAH is written as BNPMWGO, which would be written as DNRWLUA?', NULL, '[{"text":"COSGOLT","image_url":null,"alt":null},{"text":"TOGSOLC","image_url":null,"alt":null},{"text":"TOGCLOS","image_url":null,"alt":null},{"text":"CLOSGOT","image_url":null,"alt":null}]', NULL, 3, 'The first, second, third, fourth, fifth, sixth and seventh letters in the code are respectively one, two, three, four, five, six and seven steps ahead of the corresponding word.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.895Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3175, 18, NULL, NULL, 'One litre of water is added to 5 litres of alcohol-water solution having 40% alcohol strength. The strength of alcohol in the new solution will be', NULL, '[{"text":"33%","image_url":null,"alt":null},{"text":"$ 33\\frac{1}{3}\\% $","image_url":null,"alt":null},{"text":"$ 33\\frac{2}{3}\\% $","image_url":null,"alt":null},{"text":"30%","image_url":null,"alt":null}]', NULL, 1, '5 liters of alcohol-water solution containing 40% alcohol strength contains 2 liters alcohol. When 1 liter water is added, the mixture becomes 6 liters in volume. Hence, the strength of alcohol in the new solution will be $ \frac{2}{6} \times 100 = 33 \frac{1}{3}\% $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.896Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3176, 18, NULL, NULL, 'The mean of observations is 43. Later, it was found that 59 was misread as 69. What would be the correct mean? (correct to two decimal places)', NULL, '[{"text":"44.11","image_url":null,"alt":null},{"text":"41.89","image_url":null,"alt":null},{"text":"42.11","image_url":null,"alt":null},{"text":"43.89","image_url":null,"alt":null}]', NULL, 1, 'Sum of observations = $ 9 \times 43 = 387 $

Correct Sum = 387 + 59 - 69 = 377

Correct Mean = $ \frac{377}{9} = 41.89 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.897Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3177, 18, NULL, NULL, 'Which gas is used for the manufacturing of Bleaching Powder?', NULL, '[{"text":"Fluorine gas","image_url":null,"alt":null},{"text":"Chlorine gas","image_url":null,"alt":null},{"text":"Bromine gas","image_url":null,"alt":null},{"text":"Iodine gas","image_url":null,"alt":null}]', NULL, 1, 'Chlorine gas is widely used in the manufacturing of bleaching powder.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.897Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3178, 18, NULL, NULL, 'Which of the following mountain Railways are part of UNESCO''s world Heritage site?

A. Darjeeling Himalayan Railways

B. Nilgiri mountain Railways

C. Kalka-Shimla Railways

D. Mumbai to Thane Railways', NULL, '[{"text":"A only","image_url":null,"alt":null},{"text":"A, B only","image_url":null,"alt":null},{"text":"A, B, C only","image_url":null,"alt":null},{"text":"A, B, C, D","image_url":null,"alt":null}]', NULL, 2, 'The Mumbai to Thane Railways are not part of UNESCO''s World Heritage Site.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.898Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3179, 18, NULL, NULL, '44% of 80% of a number is 6864. What will be 15% of that number?', NULL, '[{"text":"2288","image_url":null,"alt":null},{"text":"2882","image_url":null,"alt":null},{"text":"2925","image_url":null,"alt":null},{"text":"2952","image_url":null,"alt":null}]', NULL, 2, 'Let number be ''x''

As per question, $ \frac{44}{100} \times \frac{80}{100} \times x = 6864 $

x = 19500

Then 15% of x = x $ \times \frac{15}{100} $ = 2925', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.898Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3180, 18, NULL, NULL, 'In the given question, arrange the given words in the sequence occur in the dictionary.

(A) Wound

(B) Writer

(C) Whiter

(D) Worst

(E) Worked', NULL, '[{"text":"A, D, C, E, B","image_url":null,"alt":null},{"text":"B, A, C, D, E","image_url":null,"alt":null},{"text":"C, E, D, A, B","image_url":null,"alt":null},{"text":"E, C, B, A, D","image_url":null,"alt":null}]', NULL, 2, 'The dictionary sequence is C → E → D → A → B which is Whiter → Worked → Worst → Wound → Writer.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.899Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3181, 18, NULL, NULL, 'A ladder leans against a vertical wall. End of the ladder is 8 m above the ground. When the lower end of the ladder is moved 2 m farther away from

the wall, the other end of the ladder rests against

the foot of the wall. The length of the ladder is:', NULL, '[{"text":"10 m","image_url":null,"alt":null},{"text":"15 m","image_url":null,"alt":null},{"text":"30 m","image_url":null,"alt":null},{"text":"17 m","image_url":null,"alt":null}]', NULL, 3, 'Length of the ladder = x + 2

Thus, $ 8^{2} + x^{2} = (x + 2)^{2} $

Solving for x, x = 15

Length of ladder = 17', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.900Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3182, 18, NULL, NULL, 'Two dice are thrown simultaneously. What is the probability that the sum of the two numbers is 4?', NULL, '[{"text":"$ \\frac{1}{11} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{12} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{13} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{14} $","image_url":null,"alt":null}]', NULL, 1, 'The set of possible outcomes when we roll a die are {1, 2, 3, 4, 5, 6}

So, when we roll two dice there are $ 6 \times 6 = 36 $ possibilities. When we roll two dice, the possibility of getting number 4 is (1, 3), (2, 2), and (3, 1). So, the number of favourable outcomes = 3

Total number of possibilities = 36

Probability = The number of favourable outcomes / Total number of possibilities = 3/36 = 1/12', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.900Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3183, 18, NULL, NULL, 'The temple not built by Krishna Deva Raya (70 AD-1529) is:', NULL, '[{"text":"Vijaya Mahal","image_url":null,"alt":null},{"text":"Hazara Rama Temple","image_url":null,"alt":null},{"text":"Sun Temple","image_url":null,"alt":null},{"text":"Vithal Swami Temple","image_url":null,"alt":null}]', NULL, 2, 'Sun Temple is not associated with Krishna Deva Raya or the Vijayanagara Empire.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.901Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3184, 18, NULL, NULL, 'How many degrees does the minute hand cover in the same time in which the seconds hand cover $ 180^{\circ} $.', NULL, '[{"text":"18","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"180","image_url":null,"alt":null}]', NULL, 2, 'As we know that the second hand covers $360^{\circ}$ in 1 minute i.e. in 60 seconds. So, the second hand covers $180^{\circ}$ in $=\frac{60}{360^{\circ}}\times180^{\circ}=30$ seconds.

Also, we know that the minute hand covers $6^{\circ}$ in 1 minute i.e. in 60 seconds. Therefore, the minute hand covers in 30 seconds $=\frac{6^{0}}{2}=3^{\circ}$.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.901Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3185, 18, NULL, NULL, 'Where is the ''Indian grape processing Board'' located?', NULL, '[{"text":"Bengaluru (Karnataka)","image_url":null,"alt":null},{"text":"Kottayam (Kerela)","image_url":null,"alt":null},{"text":"Pune (Maharashtra)","image_url":null,"alt":null},{"text":"Kochi (Kerela)","image_url":null,"alt":null}]', NULL, 2, 'The Indian Grape Processing Board (IGPB) is a statutory body established under the Ministry of Food Processing Industries, Government of India. It is headquartered in Pune, Maharashtra.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.902Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3186, 18, NULL, NULL, 'The chairman of Drafting Committee of the constitution was:

(a) Dr. Rajendra Prasad

(b) Dr. B.R. Ambedkar

(c) Dr. Zakir Hussain

(d) Pt. Jawahar Lal Nehru

Q36. In a 2-digit number unit''s digit is 5 more than the ten''s digit. If 5 times the given number is 24 more than two times the number obtained by interchanging the digits of the given number, then the given number is:', NULL, '[{"text":"16","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null},{"text":"38","image_url":null,"alt":null},{"text":"49","image_url":null,"alt":null}]', NULL, 1, 'Dr. B.R. Ambedkar, an eminent jurist, scholar, and social reformer, was the chairman of the Drafting Committee of the Constituent Assembly.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.902Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3187, 18, NULL, NULL, 'Which of the following shows the relation between Sun, Earth and Universe?', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 2, 'Sun and Earth are different, but both are part of Universe.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.903Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-05-27-shift-1/q39-options.jpg","alt":"Printed answer choices for question 39","kind":"options"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3188, 18, NULL, NULL, 'Find the area of four walls of a room having length 12.5 m, breadth 9 m and height 7 m', NULL, '[{"text":"289 m $ ^{2} $","image_url":null,"alt":null},{"text":"300 m $ ^{2} $","image_url":null,"alt":null},{"text":"307 m $ ^{2} $","image_url":null,"alt":null},{"text":"301 m $ ^{2} $","image_url":null,"alt":null}]', NULL, 3, 'The area of four walls = $ 2(lh + bh) = 2(12.5 \times 7 + 9 \times 7) = 301 \, m^2 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.903Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3189, 18, NULL, NULL, 'If principal amount is P and rate of interest is R% per annum, then what is the difference between simple interest and compound interest for 2 years?', NULL, '[{"text":"$ \\frac{PR}{100} $","image_url":null,"alt":null},{"text":"$ \\frac{2PR}{100} $","image_url":null,"alt":null},{"text":"$ \\frac{PR^{2}}{(100)^{3}} $","image_url":null,"alt":null},{"text":"$ \\frac{PR^{2}}{100} $","image_url":null,"alt":null}]', NULL, 2, 'Simple interest for 2 years = $ \frac{2PR}{100} $

Compound interest for 2 years = $ P(1 + \frac{R}{100})^2 $

Difference = $ \frac{PR^2}{(100)^3} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.903Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3190, 18, NULL, NULL, 'If the radius of a sphere is increased by 50%, then its surface area will increase by:', NULL, '[{"text":"25%","image_url":null,"alt":null},{"text":"125%","image_url":null,"alt":null},{"text":"150%","image_url":null,"alt":null},{"text":"50%","image_url":null,"alt":null}]', NULL, 1, 'Let the original radius be r

So, the surface area of the sphere = $ 4\pi r^2 $ ....(1)

Since, the radius is increased by 50% then new

radius = 1.5r

Therefore the new surface area of the sphere will be $ =4\pi(1.5)^2 = 2.25 \times 4\pi r^2 \ldots(2) $

Therefore, the required percentage $ \frac{2.25 \times 4\pi r^2 - 4\pi r^2}{4\pi r^2} \times 100 = 125\% $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.904Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3191, 18, NULL, NULL, '_ satellite was launched on 29th March 2018 from Srihari Kota with the help of PSLV-C40 launch vehicle.', NULL, '[{"text":"DMC3","image_url":null,"alt":null},{"text":"SARAL","image_url":null,"alt":null},{"text":"Cartosat-2","image_url":null,"alt":null},{"text":"Rohini RS-1","image_url":null,"alt":null}]', NULL, 2, 'The satellite launched from Sriharikota on March 29th, 2018 with the help of the PSLV-C40 launch vehicle, Cartosat-2.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.904Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3192, 18, NULL, NULL, 'In the year 1996, the republic day was celebrated on Friday. On which day the Independence Day was celebrated in the year 2000?', NULL, '[{"text":"Monday","image_url":null,"alt":null},{"text":"Tuesday","image_url":null,"alt":null},{"text":"Sunday","image_url":null,"alt":null},{"text":"Friday","image_url":null,"alt":null}]', NULL, 1, 'The year 1966 was a Leap Year. Number of days remaining in the 1996.

=366 - 26 = 340 days = 48 weeks 4 odd days.

1997, 1998 and 1999 together have 3 odd days.

2000 was a Leap year.

Days upto 15th August 2000 = 31 + 29 + 31 + 30 + 31 + 30 + 31 + 15 = 229 days. $ \frac{228}{7} = 32 $ weeks 4 odd days.

Now, total number of odd days = 4 + 3 + 4 = 11

$ \frac{11}{7} = 1 $ week 4 odd days. 15th August 2000 was 4 days beyond Friday. i.e., Tuesday.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.904Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3193, 18, NULL, NULL, 'Choose the correct mirror image of the given figure, where mirror is represented by a line MN.

M', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-05-27-shift-1/q45-figure-1.jpg', 'Figure for question 45', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.905Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-05-27-shift-1/q45-figure-1.jpg","alt":"Figure for question 45","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-05-27-shift-1/q45-options.jpg","alt":"Printed answer choices for question 45","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3194, 18, NULL, NULL, 'Find the mean proportional between 18 and 72.', NULL, '[{"text":"36","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null},{"text":"90","image_url":null,"alt":null},{"text":"72","image_url":null,"alt":null}]', NULL, 0, '18:x::x:72

