INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3195, 18, NULL, NULL, 'How many ''7''s are preceded by 9 and followed by 6 in the given series?', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null}]', NULL, 3, '''7''s are preceded by 9 and followed by 6 = 9, 7, 6

Given series, 7, 8, $ \underline{\text{9,7,6}} $ 5, 3, 4, 2, 8, 9, 7, 2, 4, 5, 9, 2, $ \underline{\text{9,7,6}} $ 4, 7

Hence, correct answer is two.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.905Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3196, 18, NULL, NULL, 'Statements:

1. Dogs do not bark on the arrival of friends of the family

2. When A entered B''s house, B''s dog started barking.

Conclusion: A is B''s enemy.

The conclusion drawn is:', NULL, '[{"text":"Follows from the given statements.","image_url":null,"alt":null},{"text":"Is probably true.","image_url":null,"alt":null},{"text":"Does not follow from the given statements.","image_url":null,"alt":null},{"text":"Is probably false.","image_url":null,"alt":null}]', NULL, 2, 'From the statement it is clear that dogs do not bark on the arrival of friends of the family, they only bark on the arrival of some first-time visitor or a stranger. So, it cannot be said that A is B''s enemy. He might be a delivery boy or a person visiting B for the first time. Hence, the answer is option C.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.906Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3197, 18, NULL, NULL, 'Five girls sitting in a row. Raashi is not adjacent to Grace or Adhya. Anu is not adjacent to Grace. Raashi is adjacent to Venus. Venus is at the middle in the row. Then Anu is adjacent to whom?', NULL, '[{"text":"Raashi","image_url":null,"alt":null},{"text":"Grace","image_url":null,"alt":null},{"text":"Aadhya","image_url":null,"alt":null},{"text":"Venus","image_url":null,"alt":null}]', NULL, 0, 'Two cases can be made from the given information, but in both the cases Anu is adjacent to Raashi.

$ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Venus}} $ $ \underline{\text{Raashi}} $ $ \underline{\text{Anu}} $

$ \underline{\text{Anu}} $ $ \underline{\text{Raashi}} $ $ \underline{\text{Venus}} $ $ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Grace/Adhya}} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.906Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
