INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3201, 18, NULL, NULL, '''Sardar Sarovar Dam'' is built on which river?', NULL, '[{"text":"Sutlej","image_url":null,"alt":null},{"text":"Kaveri","image_url":null,"alt":null},{"text":"Narmada","image_url":null,"alt":null},{"text":"Yamuna","image_url":null,"alt":null}]', NULL, 2, 'The Sardar Sarovar Dam is built on the Narmada River in the state of Gujarat, India.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.908Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3202, 18, NULL, NULL, 'If 2x, x + 4 and x + 1 are in A.P., then the value of x is:', NULL, '[{"text":"6","image_url":null,"alt":null},{"text":"$ 6\\frac{1}{2} $","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 3, 'Given, 2x, x + 4 and x + 1 are in A.P. Then,

$ (x+4)-2x=(x+1)-(x+4) $

$ x+4-2x=x+1-x-4 $

$ -x+4=-4 $

x=8', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.908Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
