INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3205, 18, NULL, NULL, 'Difference in the place values of 3 used at two places in the number 934530 is:', NULL, '[{"text":"29970","image_url":null,"alt":null},{"text":"30070","image_url":null,"alt":null},{"text":"29570","image_url":null,"alt":null},{"text":"29990","image_url":null,"alt":null}]', NULL, 0, '30000 - 30 = 29970', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.911Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3206, 18, NULL, NULL, 'The speed of a train is 88 km/h. How much time will it take to cross a 180 m long platform if length of the train is 150 m?', NULL, '[{"text":"$ 11\\frac{1}{2}s $","image_url":null,"alt":null},{"text":"$ 10\\frac{1}{2}s $","image_url":null,"alt":null},{"text":"$ 13\\frac{1}{2}s $","image_url":null,"alt":null},{"text":"$ 14\\frac{1}{2}s $","image_url":null,"alt":null}]', NULL, 2, 'Speed of train in m/sec = $ 88 \times \frac{5}{18} = 24.4 $

Distance to cover = 180 + 150 = 330 m

Time taken by train = $ \frac{330}{24.4} = 13\frac{1}{2} $ s', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.912Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3207, 18, NULL, NULL, 'The Indian giant who got maximum Grammy Award is:', NULL, '[{"text":"Pt. Ravi Shankar","image_url":null,"alt":null},{"text":"Zakir Hussain","image_url":null,"alt":null},{"text":"Zubin Mehta","image_url":null,"alt":null},{"text":"A. R. Rehman","image_url":null,"alt":null}]', NULL, 0, 'The Indian giant who got the maximum Grammy Awards is Pt. Ravi Shankar.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.914Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3208, 18, NULL, NULL, 'Who is the author of book "Unhappy India"?', NULL, '[{"text":"M. K. Gandhi","image_url":null,"alt":null},{"text":"Lala-Lajpat Rai","image_url":null,"alt":null},{"text":"Vijay Tendulkar","image_url":null,"alt":null},{"text":"Swami Shivanand","image_url":null,"alt":null}]', NULL, 1, '"Unhappy India" is a book written by Lala Lajpat Rai, a prominent freedom fighter and leader of the Indian independence movement.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.914Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3209, 18, NULL, NULL, 'A sum of is ₹ 5100 is divided amongst A, B and C, such that the ratio of shares of A and B is 1:2 that of B and C is 3:4. Find the sum of the shares of A and B.', NULL, '[{"text":"₹ 3400","image_url":null,"alt":null},{"text":"₹ 3060","image_url":null,"alt":null},{"text":"₹ 2880","image_url":null,"alt":null},{"text":"₹ 2700","image_url":null,"alt":null}]', NULL, 3, 'Total sum of money = Rs. 5100

The ratio of the share of A and B = 1 : 2

The ratio of the share of B and C = 3 : 4

Ratio of A and B = (1 : 2) × 3 = 3 : 6

Ratio of B and C = (3 : 4) × 2 = 6 : 8

Ratio of A, B and C = 3 : 6 : 8

Total Sum = 3x + 6x + 8x

5100 = 17x

x = 300

Sum of the shares of A and B = ₹ 2700', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.916Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
