INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3212, 18, NULL, NULL, 'A box (12 + x) red balls and (18 + x) green balls. A ball is drawn at random and is found to be red. If the probability of drawn ball is $ \frac{5}{12} $, then find the value of x.', NULL, '[{"text":"4","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null}]', NULL, 1, 'Given, Probability of drawn ball = $ \frac{5}{12} $

Given, A ball is drawn at random and is found to be

red then,

$ \frac{5}{12}=\frac{(12+x)}{(12+x)+(18+x)} $

x = 3', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.917Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
