INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3214, 18, NULL, NULL, 'In a given number 1234567891, we interchange the first and the second digits, the third and the fourth digit and so on. Then which digit will be sixth from the right?', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null}]', NULL, 3, 'Actual Number: 1234567891

