INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3215, 18, NULL, NULL, 'Who said "Swaraj is my birthright and I shall have it"?', NULL, '[{"text":"Jawahar Lal Nehru","image_url":null,"alt":null},{"text":"Mahatma Gandhi","image_url":null,"alt":null},{"text":"Lala Lajpat Rai","image_url":null,"alt":null},{"text":"Bal Gangadhar Tilak","image_url":null,"alt":null}]', NULL, 3, 'Bal Gangadhar Tilak was a prominent Indian nationalist leader who is credited with popularizing the slogan "Swaraj is my birthright and I will have it."', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.918Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3216, 18, NULL, NULL, 'Given that:

