INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3217, 18, NULL, NULL, 'Rome (Italy) is situated on _ river.', NULL, '[{"text":"Tiber","image_url":null,"alt":null},{"text":"Vistula","image_url":null,"alt":null},{"text":"Thames","image_url":null,"alt":null},{"text":"Seine","image_url":null,"alt":null}]', NULL, 0, 'Rome, Italy is situated on the Tiber River.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.919Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3218, 18, NULL, NULL, 'An exterior angle of a regular polygon is $ 24^{\circ} $. How many sides will the polygon have?', NULL, '[{"text":"12","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null}]', NULL, 2, 'If an exterior angle of a regular polygon measures $ 24^{\circ} $, the polygon has 15 sides.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.919Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3219, 18, NULL, NULL, 'Find the area (in $ cm^{2} $ of the figure ABCDEF when all its sides are perpendicular to their adjacent sides.', NULL, '[{"text":"28.5","image_url":null,"alt":null},{"text":"30","image_url":null,"alt":null},{"text":"30.5","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null}]', NULL, 2, 'Area of ABCDEF = $ (9 \times 4.5) - (4 \times 2.5) = 40.5 - 10 = 30.5 $ cm $ ^{2} $', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-05-shift-1/q13-figure-1.jpg', 'Figure for question 13', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.920Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-05-shift-1/q13-figure-1.jpg","alt":"Figure for question 13","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3220, 18, NULL, NULL, 'In a Geometric Progression, if the product of the first three terms is $ \frac{27}{8} $, then its second term is:', NULL, '[{"text":"$ \\frac{3}{2} $","image_url":null,"alt":null},{"text":"$ \\frac{9}{4} $","image_url":null,"alt":null},{"text":"$ \\frac{9}{2} $","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 0, 'Let the 3 terms of GP be $ \frac{a}{r} $, a, ar

Product of these terms = $ \frac{a}{r} \times a \times ar = a^{3} $

ATQ, $ a^{3} = \frac{27}{8} $

$ a = \frac{3}{2} $

Then, second term = $ \frac{3}{2} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.920Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3221, 18, NULL, NULL, 'If 30 ml solution of 20% alcohol is mixed with 20 ml solution of 25% alcohol, then what is the strength of alcohol in the mixture?', NULL, '[{"text":"23%","image_url":null,"alt":null},{"text":"21.5%","image_url":null,"alt":null},{"text":"22%","image_url":null,"alt":null},{"text":"22.5%","image_url":null,"alt":null}]', NULL, 2, 'Quantity of alcohol in 30 ml solution = 20% of 30 ml = 6 ml

Quantity of alcohol in 20 ml solution = 25% of 20 ml = 5 ml

Percentage of alcohol in the mixture = $ \frac{6+5}{(30+20)} \times 100 = 22\% $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.920Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3222, 18, NULL, NULL, 'Given below are two statements: one is labelled as Assertion (A) and the other is labelled as Reason (R). Assertion (A): DDT has nowadays lost its use as an Insecticide.

Reason (R): DDT is harmful to man.

In the light of the above statements, choose the most appropriate answer from the options given below:', NULL, '[{"text":"Both (A) and (R) are correct and (R) is the correct explanation of (A)","image_url":null,"alt":null},{"text":"Both (A) and (R) are correct but (R) is not the correct explanation of (A)","image_url":null,"alt":null},{"text":"(A) is correct but (R) is not correct","image_url":null,"alt":null},{"text":"(A) is not correct but (R) is correct","image_url":null,"alt":null}]', NULL, 1, 'Both (A) and (R) are correct but (R) is not the correct explanation of (A).', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.921Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3223, 18, NULL, NULL, 'Mahatma Buddha was born at _.', NULL, '[{"text":"Vaishali","image_url":null,"alt":null},{"text":"Kapilvastu","image_url":null,"alt":null},{"text":"Lumbini","image_url":null,"alt":null},{"text":"Patliputra","image_url":null,"alt":null}]', NULL, 2, 'Lumbini is a UNESCO World Heritage Site located in the Terai plains of southern Nepal. It is the birthplace of Siddhartha Gautama, who later became the Buddha.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.921Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3224, 18, NULL, NULL, 'Which Fundamental Right can be described as the soul and heat of the Constitution?', NULL, '[{"text":"Right to Equality","image_url":null,"alt":null},{"text":"Right against exploitation","image_url":null,"alt":null},{"text":"Right of Freedom","image_url":null,"alt":null},{"text":"Rights to Constitutional Remedies","image_url":null,"alt":null}]', NULL, 3, 'The Fundamental Right that can be described as the "heart and soul" of the Constitution of India is the "Right to Constitutional Remedies." This right, guaranteed under Article 32 of the Indian Constitution, enables citizens to seek legal remedies and enforcement of their other fundamental rights through the Supreme Court of India. It is considered crucial for the protection and enforcement of all other fundamental rights, making it the cornerstone of the Constitution.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.922Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3225, 18, NULL, NULL, 'On dividing a number by 38, we get 90 quotient and 19 as reminder. What is the number?', NULL, '[{"text":"3439","image_url":null,"alt":null},{"text":"3401","image_url":null,"alt":null},{"text":"3382","image_url":null,"alt":null},{"text":"3458","image_url":null,"alt":null}]', NULL, 0, 'Let the number be x

We know, x = Divisor $ \times $ Quotient + R

x = 38 $ \times $ 90 + 19

x = 3439', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.922Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3226, 18, NULL, NULL, 'ISRO launched a digital platform on August 12, 2022. This platform is known as:', NULL, '[{"text":"SAMARTH","image_url":null,"alt":null},{"text":"SARTHAK","image_url":null,"alt":null},{"text":"SPARK","image_url":null,"alt":null},{"text":"INSAT","image_url":null,"alt":null}]', NULL, 2, 'ISRO launched a digital platform on August 12, 2022 called SPARK, which stands for Space Exploration and Research Platform. It is a virtual space museum that showcases various ISRO missions with an interactive interface.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.922Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3227, 18, NULL, NULL, 'The average of five consecutive natural numbers is 13.

If next two natural numbers are also included, then

find the new average.', NULL, '[{"text":"13","image_url":null,"alt":null},{"text":"13.5","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null},{"text":"13.75","image_url":null,"alt":null}]', NULL, 2, 'We know, Total = Average $ \times $ Number of entities

ATQ, $ n + (n+1) + (n+2) + (n+3) + (n+4) = 5 \times 13 $

$ 5n + 10 = 65 $

$ n = \frac{65}{5} = 13 $

Sum of the seven numbers = 7n + 21 = $ 7 \times 13 + 21 = 112 $

Average of the seven numbers = $ \frac{112}{7} = 16 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.923Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3228, 18, NULL, NULL, 'If a man starts at 7 a.m. at $ \frac{5}{4} $ of his usual speed, he reaches office 30 minutes early than usual. So, with a new speed at what time he reached his office?', NULL, '[{"text":"9:30 a.m.","image_url":null,"alt":null},{"text":"10 a.m.","image_url":null,"alt":null},{"text":"9 a.m.","image_url":null,"alt":null},{"text":"8:25 a.m.","image_url":null,"alt":null}]', NULL, 2, 'Time is inversely proportion to speed.

Let usual speed of the person be 4x

Speed of the person after decreasing = 5x

Ratio of usual speed to the after decreasing = 4x : 5x

Ratio of usual time to after decreasing = 5x : 4x

5x - 4x = 30

x = 30

Then 4x = 120 min

New time when the person reaches the office = 9 am', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.923Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3229, 18, NULL, NULL, 'On compound interest, a certain sum amounts to ₹7350 in 2 years and to ₹8575 in 3 years. Find the rate of interest.', NULL, '[{"text":"$ \\frac{25}{3}\\% $","image_url":null,"alt":null},{"text":"$ \\frac{50}{3}\\% $","image_url":null,"alt":null},{"text":"25%","image_url":null,"alt":null},{"text":"33%","image_url":null,"alt":null}]', NULL, 1, 'SI on Rs. 7350 for 1 year = Rs. (8575 - 7350) = Rs. 1225

Rate = $ \frac{100 \times 1225}{7350 \times 1} $% = $ \frac{50}{3} $%', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.923Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3230, 18, NULL, NULL, 'The word ''Cell was first coined by Robert Hook in _.', NULL, '[{"text":"1665","image_url":null,"alt":null},{"text":"1838","image_url":null,"alt":null},{"text":"1839","image_url":null,"alt":null},{"text":"1668","image_url":null,"alt":null}]', NULL, 0, 'The word "cell" was first coined by Robert Hooke in the year 1665.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.924Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3231, 18, NULL, NULL, 'Quantum theory was discovered by:', NULL, '[{"text":"Marconi","image_url":null,"alt":null},{"text":"Albert Einstein","image_url":null,"alt":null},{"text":"Max Plank","image_url":null,"alt":null},{"text":"James Chadwick","image_url":null,"alt":null}]', NULL, 2, 'Max Planck is considered the father of quantum theory.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.924Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3232, 18, NULL, NULL, 'Match List - I with List - II.', NULL, '[{"text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(IV), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null}]', NULL, 1, '(A)-(II), (B)-(I), (C)-(IV), (D)-(III)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-05-shift-1/q26-table-1.jpg', 'Table for question 26', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.924Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-05-shift-1/q26-table-1.jpg","alt":"Table for question 26","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3233, 18, NULL, NULL, 'In certain system of coding the word STATEMENT is written as TNEMETATS. In the same way coding, the code for the word "POLITICAL"?', NULL, '[{"text":"LACITILOP","image_url":null,"alt":null},{"text":"LCATILOP","image_url":null,"alt":null},{"text":"OPILITACL","image_url":null,"alt":null},{"text":"OPILATACL","image_url":null,"alt":null}]', NULL, 0, 'The letters are reversed to obtain the code. So, code for ''POLITICAL'' will be ''LACITILOP''.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.925Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3234, 18, NULL, NULL, 'A can do a work in 12 days. B''s efficiency to do the work is 50% more than that of A. In how many days will B be able to do the work?', NULL, '[{"text":"8","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"11","image_url":null,"alt":null}]', NULL, 0, 'We know, Total work = Efficiency * Num of days to finish the work

Efficiency ratio of A and B (A : B) = 100 : 150 = 2 : 3

Let A''s efficiency = 2s then B''s efficiency = 3a

Now, total work done by A = 2a × 12 = 24a

Same work done by B in = 24a/3a = 8 days

B alone will take 8 days to complete the same work.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.925Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3235, 18, NULL, NULL, 'An ice cream is in the form of a cone surmounted by a hemisphere. If the base radius of the cone in 3.5 cm and height of the ice cream is 10 cm, then find the volume of the ice cream (in cm³).

$ \left(\pi=\frac{22}{7}\right) $', NULL, '[{"text":"186.92","image_url":null,"alt":null},{"text":"109.08","image_url":null,"alt":null},{"text":"173.25","image_url":null,"alt":null},{"text":"218.16","image_url":null,"alt":null}]', NULL, 2, 'Radius of cone = Radius of hemisphere

Given, r = 3.5 and Total height = 10 cm

Height of conical shape = 10 - 3.5 = 6.5 cm

Volume of ice cream in the cone = volume of conical part + volume of hemisphere

= $ \frac{1}{3}\pi r^{2}h + \frac{2}{3}\pi r^{3} $

$ \frac{1}{3}\pi r^{2}(h + 2r) $

= $ \frac{1}{3} \times \frac{22}{7} \times (3.5)^{2}(6.5 + 7) $

Volume of ice cream = 173.25 cm³', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.925Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3236, 18, NULL, NULL, 'Fractions $ \frac{3}{4}, \frac{2}{3}, \frac{5}{6}, \frac{11}{18} $, when written in descending order are:', NULL, '[{"text":"$ \\frac{11}{18}, \\frac{2}{3}, \\frac{5}{6}, \\frac{3}{4} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{6}, \\frac{2}{3}, \\frac{3}{4}, \\frac{11}{18} $","image_url":null,"alt":null},{"text":"$ \\frac{2}{3}, \\frac{5}{6}, \\frac{3}{4}, \\frac{11}{18} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{6}, \\frac{3}{4}, \\frac{2}{3}, \\frac{11}{18} $","image_url":null,"alt":null}]', NULL, 3, '$$ \frac{5}{6},\frac{3}{4},\frac{2}{3},\frac{11}{18} $$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.926Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3237, 18, NULL, NULL, 'If point $ (x, y) $ is equidistant from the points $ (7, 1) $ and $ (3, 5) $, then which one of the following options is correct?', NULL, '[{"text":"x - y = 2","image_url":null,"alt":null},{"text":"$ x + y = 2 $","image_url":null,"alt":null},{"text":"x - y = 1","image_url":null,"alt":null},{"text":"x - y = -2","image_url":null,"alt":null}]', NULL, 0, 'ol. Using distance formula

$ \sqrt{(x-7)^{2}+(y-1)^{2}}=\sqrt{(x-3)^{2}+(y-5)^{2}} $

$ -14x+49-2y+1=-6x+9-10y+25 $

$ 8x-8y=16 $

x - y = 2', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.928Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3238, 18, NULL, NULL, 'Milk always contains:', NULL, '[{"text":"Water","image_url":null,"alt":null},{"text":"Calcium","image_url":null,"alt":null},{"text":"Fats","image_url":null,"alt":null},{"text":"Sugar","image_url":null,"alt":null}]', NULL, 1, 'Milk always contains calcium.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.930Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3239, 18, NULL, NULL, 'Match List - I with List - II.', NULL, '[{"text":"(A)-(II), (B)-(IV), (C)-(III), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null}]', NULL, 1, '(A)-(II), (B)-(IV), (C)-(I), (D)-(III)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-05-shift-1/q34-table-1.jpg', 'Table for question 34', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.931Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-05-shift-1/q34-table-1.jpg","alt":"Table for question 34","kind":"table"},{"url":"/local-papers/assets/general-test-2023-06-05-shift-1/q34-table-2.jpg","alt":"Table for question 34","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3240, 18, NULL, NULL, 'Five students are standing in a circle and all are facing towards the centre of circle. Apurva is on left of Abhishek. Alok is on the left of Apurva. Abinav is b/w Alok and Ankur. Who is sitting next to Abhinav on his immediate right.', NULL, '[{"text":"Alok","image_url":null,"alt":null},{"text":"Abhishek","image_url":null,"alt":null},{"text":"Apurva","image_url":null,"alt":null},{"text":"Ankur","image_url":null,"alt":null}]', NULL, 0, 'Clearly Alok is sitting to immediate right of Abhinav.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.931Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3241, 18, NULL, NULL, 'The value of $ \frac{(4.2)^{3}}{(2.1)^{2}} $ is:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"16.8","image_url":null,"alt":null},{"text":"19.4","image_url":null,"alt":null}]', NULL, 2, '16.8', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.932Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3242, 18, NULL, NULL, 'Ministry of Social Justice and Empowerment decided to observe "Constitution Day" on _.', NULL, '[{"text":"26th November","image_url":null,"alt":null},{"text":"26th December","image_url":null,"alt":null},{"text":"16th November","image_url":null,"alt":null},{"text":"16th December","image_url":null,"alt":null}]', NULL, 0, 'The Ministry of Social Justice and Empowerment on 19th November 2015 notified the decision of Government of India to celebrate the 26th day of November every year as ''Constitution Day'' to promote Constitution values among citizens.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.933Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3243, 18, NULL, NULL, 'If Republic Day of India in 1980 falls on Saturday. Mohan was born on 3 $ ^{rd} $ March 1980 and Sohan is 4 days older to Mohan, then Sohan''s birthday falls on:', NULL, '[{"text":"Wednesday","image_url":null,"alt":null},{"text":"Thursday","image_url":null,"alt":null},{"text":"Sunday","image_url":null,"alt":null},{"text":"Saturday","image_url":null,"alt":null}]', NULL, 1, 'Republic Day i.e, 26th January of 1980 falls on Saturday.

Mohan was born on March 3, 1980.

Sohan is older to Mohan by 4 days, so Sohan was born 4 days before March 3, 1980. As 1980 is a leap year, there are 29 days in February. So, Y was born on 28th February.

No. of days between 26th January to 28th February is 33. And 33 when divided by 7, we get 5 as remainder. 5 days after Saturday is Thursday. So, 28th February, the day Sohan was born falls on Thursday.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.933Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3244, 18, NULL, NULL, 'Which scientist is known as "Birdman of India"?', NULL, '[{"text":"Salim Ali","image_url":null,"alt":null},{"text":"Gulam Ali","image_url":null,"alt":null},{"text":"Noshad Ali","image_url":null,"alt":null},{"text":"J.C. Bose","image_url":null,"alt":null}]', NULL, 0, 'The scientist known as the "Birdman of India" is Salim Ali. He was a prominent Indian ornithologist and naturalist known for his extensive work in the field of ornithology and bird conservation.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.934Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3245, 18, NULL, NULL, 'Statements:

(I) Some books are eraser.

(II) Some erasers are black.

(III) No black is green

Conclusions:

(I) Some books are green.

(II) All erasers are green.

Which of the following conclusions can be definitely drawn from the statements given in the options?', NULL, '[{"text":"Only (I) follows","image_url":null,"alt":null},{"text":"Neither (I) nor (II) follows","image_url":null,"alt":null},{"text":"Only (II) follows","image_url":null,"alt":null},{"text":"Either (I) or (II) follows","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.934Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3246, 18, NULL, NULL, 'The cost of 5 kg apples and 3 kg oranges is ₹ 535. If the cost of 8 kg apples and 6 kg oranges is ₹ 910, then what is the cost of 2 kg apples and 8 kg oranges?', NULL, '[{"text":"₹ 803","image_url":null,"alt":null},{"text":"₹ 680","image_url":null,"alt":null},{"text":"₹ 520","image_url":null,"alt":null},{"text":"₹ 650","image_url":null,"alt":null}]', NULL, 2, 'Let the cost of an orange = Rs. x

And cost of an apple = Rs. y

ATQ, 5x + 3y = 535

And 8x + 6y = 910

4x + 3y = 455

By solving both equations, we get x = 40 and y = 35

The cost of 2 kg apples and 8 kg oranges = ₹520', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.935Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3247, 18, NULL, NULL, 'Match List - I with List - II', NULL, '[{"text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null}]', NULL, 1, '(A)-(IV), (B)-(III), (C)-(I), (D)-(II)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-05-shift-1/q42-table-1.jpg', 'Table for question 42', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.935Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-05-shift-1/q42-table-1.jpg","alt":"Table for question 42","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3248, 18, NULL, NULL, 'At what time between 5 and 6 O''clock are the hands of a Clock coincides?', NULL, '[{"text":"$ 27\\frac{3}{11} $ min past 5","image_url":null,"alt":null},{"text":"$ 22\\frac{8}{11} $ min past 4","image_url":null,"alt":null},{"text":"30 min past 5","image_url":null,"alt":null},{"text":"22 min past 4","image_url":null,"alt":null}]', NULL, 0, 'The angle between the hour hand and minutes hand

$ \theta = (30H - 11M/2) $

H = 5 and angle = $ 0^{\circ} $

When minute & hour hands coincide, then $ \theta $

$ \Rightarrow 0 = 30 \times 5 - 11M/2 $

$ \Rightarrow 0 = 150 - 11M/2 $

$ \Rightarrow 150 = 11M/2 $

$ \Rightarrow 300 = 11M $

$ \Rightarrow M = \frac{300}{11} $

$ \Rightarrow M = 27\frac{3}{11} $ Minutes

The correct answer is 27\frac{3}{11} minutes past 5.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.936Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
