INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3261, 18, NULL, NULL, 'In a right triangle, length of the hypotenuse is 17 cm. If length of its one side is 15 cm, then the area of the triangle is:', NULL, '[{"text":"127.5 cm $ ^{2} $","image_url":null,"alt":null},{"text":"122.5 cm $ ^{2} $","image_url":null,"alt":null},{"text":"60 cm $ ^{2} $","image_url":null,"alt":null},{"text":"66.5 cm $ ^{2} $","image_url":null,"alt":null}]', NULL, 2, 'Height = $ \sqrt{17^{2}-8^{2}}=15 $ cm

Area of right angles triangle $ \frac{1}{2} \times b \times h = 60 \, cm^{2} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.942Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3262, 18, NULL, NULL, 'In which state prime minister Narendra Modi inaugurated ''Jal Jan Abhiyan''?', NULL, '[{"text":"Rajasthan","image_url":null,"alt":null},{"text":"Jharkhand","image_url":null,"alt":null},{"text":"Himachal Pradesh","image_url":null,"alt":null},{"text":"Bihar","image_url":null,"alt":null}]', NULL, 0, 'Prime Minister Narendra Modi inaugurated the ''Jal Jan Abhiyan'' in Rajasthan on February 16, 2023.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.943Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3263, 18, NULL, NULL, 'How many daughters does D have?

Statement (I): B and F are sister of A.

Statement (II): C is the brother of A and F.

Statement (III): C and E are sons of D.

Choose the correct option to decide whether the data provided in the statements are sufficient to answer the question:', NULL, '[{"text":"I alone is Sufficient","image_url":null,"alt":null},{"text":"I & II together are Sufficient","image_url":null,"alt":null},{"text":"II & III together are Sufficient","image_url":null,"alt":null},{"text":"All the statements together are not sufficient","image_url":null,"alt":null}]', NULL, 3, 'Statement I alone is not sufficient, as no information is given related to D.

Statement II alone is not sufficient, as no information is given related to D.

Statement III alone is not sufficient, as no information is given related to daughters of D.

If we combine all the three statements, it is not possible to determine how many daughters D have. Therefore, all the statements together are not sufficient.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.947Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3264, 18, NULL, NULL, 'Which are the correct examples of Newton''s $ 3^{rd} $ law motion?

(A) Recoil of a gun

(B) Running horse stops suddenly, the rider bends forward

(C) Motion of rocket

(D) It gives the definition of force

(E) Swimming', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (E) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 1, '(A), (C) and (E) only are correct.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.948Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3265, 18, NULL, NULL, 'P sold an item for ₹70 and earned 100% profit. What should be the selling price of the item to earn 150% profit?', NULL, '[{"text":"₹105","image_url":null,"alt":null},{"text":"₹52.50","image_url":null,"alt":null},{"text":"₹87.50","image_url":null,"alt":null},{"text":"₹150","image_url":null,"alt":null}]', NULL, 2, 'Selling price should be ₹ 87.50 to earn 150% profit.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.949Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3266, 18, NULL, NULL, 'In a 40 litre mixture of milk and water, the ratio of milk to water is 3 : 1. How much water (in litres) should be added to make this ratio 2 : 3?', NULL, '[{"text":"30","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null},{"text":"35","image_url":null,"alt":null},{"text":"40","image_url":null,"alt":null}]', NULL, 2, 'Milk in mixture = $ \frac{3}{4} \times 40 = 30 $

Water in mixture = 40 - 30 = 10

Let x its milk be added

New ratio of milk and water = 2 : 3

30 + x : 10 = 2 : 3

3(30 + x) = 20

x = 35

Quantity of milk to be added is 35 ltrs.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.952Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3267, 18, NULL, NULL, 'The average of five consecutive natural numbers is 50. What is the product of the smallest and the largest of the numbers?', NULL, '[{"text":"2496","image_url":null,"alt":null},{"text":"2560","image_url":null,"alt":null},{"text":"3200","image_url":null,"alt":null},{"text":"1800","image_url":null,"alt":null}]', NULL, 0, 'Let the first number be $x$.

Sum of 5 consecutive number is $= 50 \times 5 = 250$

ATQ, $x + x + 1 + x + 2 + x + 3 + x + 4 = 250$

$5x + 10 = 250$

$5x = 240$

$x = 48$

Product of smallest to largest $= x(x + 4) = 48 \times 52 = 2496$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.952Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3268, 18, NULL, NULL, 'The Malacca Strait located between Indonesia-Malaysia joins Andaman Sea to:', NULL, '[{"text":"Bay of Bengal","image_url":null,"alt":null},{"text":"Tasman Sea","image_url":null,"alt":null},{"text":"South China Sea","image_url":null,"alt":null},{"text":"Red Sea","image_url":null,"alt":null}]', NULL, 2, 'The Malacca Strait located between Indonesia-Malaysia joins Andaman Sea to the South China Sea.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.953Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3269, 18, NULL, NULL, 'What will be the area of a right-angled triangle whose hypotenuse is 10 cm and base is 6 cm?', NULL, '[{"text":"60 sq cm","image_url":null,"alt":null},{"text":"24 sq cm","image_url":null,"alt":null},{"text":"48 sq cm","image_url":null,"alt":null},{"text":"30 sq cm","image_url":null,"alt":null}]', NULL, 1, 'Hypotenuse = 10 cm, Base = 6 cm

Height (h) = $ \sqrt{c^2 - b^2} = \sqrt{10^2 - 6^2} = 8 $ cm

Area = $ \frac{1}{2} \times $ base × height = $ \frac{1}{2} \times 8 \times 6 = 24 $ cm $ ^2 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.954Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3270, 18, NULL, NULL, '₹2000 amounts to ₹2226.05 in 2 years on compound interest. What is the rate of interest per annum?', NULL, '[{"text":"5%","image_url":null,"alt":null},{"text":"5.25%","image_url":null,"alt":null},{"text":"5.5%","image_url":null,"alt":null},{"text":"6%","image_url":null,"alt":null}]', NULL, 2, 'We know, $A = P \left[1 + \frac{R}{100}\right]^n$

2226.05 = 2000 $\left[1 + \frac{R}{100}\right]^2$

$\frac{2226.05}{2000} = \left[1 + \frac{R}{100}\right]^2$

1.113025 = $\left[1 + \frac{R}{100}\right]^2$

1.055 = $\left[\frac{100 + R}{100}\right]$

105.5 = 100 + R', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.954Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3271, 18, NULL, NULL, 'A, B and C started a business on partnership by investing ₹29000, ₹50,000 and ₹65,000 respectively. After 8 months, A invested ₹24,000 more while C withdrew ₹15,000. If profit earned at the end of the year is ₹1,04,000, then find the share of C in the profit.', NULL, '[{"text":"₹38,000","image_url":null,"alt":null},{"text":"₹38,850","image_url":null,"alt":null},{"text":"₹39,200","image_url":null,"alt":null},{"text":"₹39,000","image_url":null,"alt":null}]', NULL, 3, 'A''s investment:

For the first 8 months = Rs. 42000

For next 4 months = Rs. 42000 + Rs. 24,000 = Rs. 66,000

B''s investment for the entire year = Rs. 50,000

C''s investment:

For the first 8 months: Rs. 65,000

For the next 4 months = Rs. 65,000 - Rs. 15,000 = Rs. 50,000

A''s Total Investment:

For the first 8 months: ₹42,000 * 8 = ₹336,000.

For the next 4 months: ₹66,000 * 4 = ₹264,000.

Total = ₹336,000 + ₹264,000.

B''s Total Investment:

For the entire year: ₹50,000 * 12 = ₹600,000. C''s Total Investment:

For the first 8 months: ₹65,000 * 8 = ₹520,000.

For the next 4 months: ₹50,000 * 4 = ₹200,000.

$$ Total=₹520,000+₹200,000. $$

Given that the total profit at the end of the year is $ \pounds 1,04,000 $, C''s share in the profit, based on their proportion of the total investment, is $ \pounds 39,000 $.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.954Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3272, 18, NULL, NULL, 'Find the next term in the alpha numeric series:

