INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3280, 18, NULL, NULL, 'Angle of elevation of the top of a building from a point P on the horizontal is $ 30^{\circ} $. If the point P is 48 m away from the foot of the building, then what is the height of the building?', NULL, '[{"text":"$ 48\\sqrt{3} $ m","image_url":null,"alt":null},{"text":"$ 32\\sqrt{3} $ m","image_url":null,"alt":null},{"text":"$ 16\\sqrt{3} $ m","image_url":null,"alt":null},{"text":"$ 28\\sqrt{3} $ m","image_url":null,"alt":null}]', NULL, 2, 'Let height of the building be x

