INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3282, 18, NULL, NULL, 'Wular lake is situated in which place?', NULL, '[{"text":"Rajasthan","image_url":null,"alt":null},{"text":"Jammu & Kashmir","image_url":null,"alt":null},{"text":"Himachal Pradesh","image_url":null,"alt":null},{"text":"Odisha","image_url":null,"alt":null}]', NULL, 1, 'Wular Lake is the largest freshwater lake in India and is situated in the Union Territory of Jammu and Kashmir.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.959Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3283, 18, NULL, NULL, 'What is the smallest five-digit number which is when divided by 7, 11 and 21 leaves a remainder 3 in each case?', NULL, '[{"text":"10019","image_url":null,"alt":null},{"text":"10001","image_url":null,"alt":null},{"text":"10111","image_url":null,"alt":null},{"text":"10167","image_url":null,"alt":null}]', NULL, 3, 'LCM of 7, 11 and 21 = 231

Smallest 5-digit number = 10000

Multiple of 231 near 10000 = 10164

So, the required number will be = 10164 + 3 = 10167', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.961Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3284, 18, NULL, NULL, 'Who gave the slogan "Satyameva Jayate"?', NULL, '[{"text":"Pt. Madan Mohan Malviya","image_url":null,"alt":null},{"text":"Bal Gangadhar Tilak","image_url":null,"alt":null},{"text":"Lala Lajpat Rai","image_url":null,"alt":null},{"text":"Mahatma Gandhi","image_url":null,"alt":null}]', NULL, 0, 'Pt. Madan Mohan Malaviya was the freedom fighter credited with popularizing the slogan Satyameva Jayate (the truth alone shall triumph).', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.962Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3285, 18, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)","image_url":null,"alt":null}]', NULL, 2, '(A)-(IV), (B)-(I), (C)-(II), (D)-(III)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-09-shift-2/q20-table-1.jpg', 'Table for question 20', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.966Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q20-table-1.jpg","alt":"Table for question 20","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3286, 18, NULL, NULL, 'I am facing West. I turn $ 100^{\circ} $ in the anticlockwise direction and then $ 145^{\circ} $ in the clockwise direction. Which direction am I facing now?', NULL, '[{"text":"North-East","image_url":null,"alt":null},{"text":"North-West","image_url":null,"alt":null},{"text":"South-East","image_url":null,"alt":null},{"text":"South-West","image_url":null,"alt":null}]', NULL, 1, 'Total Clock wise direction movement = $ 145^{\circ} - 100^{\circ} = 45^{\circ} $. So, I will be facing North-West.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.967Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
