(X)', NULL, '[{"text":"(A)","image_url":null,"alt":null},{"text":"(B) (A) (B) (C) (D)","image_url":null,"alt":null},{"text":"(C)","image_url":null,"alt":null},{"text":"(D)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-09-shift-2/q33-figure-1.jpg', 'Figure for question 33', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.975Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q33-figure-1.jpg","alt":"Figure for question 33","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q33-figure-2.jpg","alt":"Figure for question 33","kind":"figure"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3299, 18, NULL, NULL, 'A dealer of scientific instruments allows 20% discount and still makes a profit of 25%. If his gain on sale of an instrument is ₹150, then find the marked price of the instrument.', NULL, '[{"text":"₹826.25","image_url":null,"alt":null},{"text":"₹750","image_url":null,"alt":null},{"text":"₹937.50","image_url":null,"alt":null},{"text":"₹428.75","image_url":null,"alt":null}]', NULL, 2, 'Let C.P of instrument = Rs. 100

Profit = 25% of Rs. 100 = Rs. 25

If profit is Rs. 150, $ C.P = \frac{100}{25} \times 150 = 600 $

S.P of the instrument = 600 + 150 = Rs. 750

Let M.P of the instrument be Rs. 100

If S.P is Rs. 80, $ M.P = \frac{100}{80} \times 750 = 937.50 $

Thus, marked price of the investment = Rs. 937.50', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.976Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3300, 18, NULL, NULL, 'The Currency of Russia is:', NULL, '[{"text":"Euro","image_url":null,"alt":null},{"text":"Korne","image_url":null,"alt":null},{"text":"Rouble","image_url":null,"alt":null},{"text":"Leu","image_url":null,"alt":null}]', NULL, 2, 'The Currency of Russia is Rouble.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.977Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
