Sportsmen, Cricketers, Batsman', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 2, 'All Batsman are Cricketers and All Cricketers are Sportsmen.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.979Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q36-options.jpg","alt":"Printed answer choices for question 36","kind":"options"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3302, 18, NULL, NULL, 'A train travels at 82.6 km/hr. How many meters will it cover in 15 minutes?', NULL, '[{"text":"20650","image_url":null,"alt":null},{"text":"21650","image_url":null,"alt":null},{"text":"18550","image_url":null,"alt":null},{"text":"17950","image_url":null,"alt":null}]', NULL, 0, '1 hour = 82.6 km

60 minutes = 82.6 $ \times $ 1000m

15 minutes = 82.6 $ \times $ $ \frac{1000}{60} $ $ \times $ 15 = 20650 m', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.980Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3303, 18, NULL, NULL, 'Simran can complete a work in 20 days. How much work will be done by her in 12 days?', NULL, '[{"text":"$ \\frac{3}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{8} $","image_url":null,"alt":null},{"text":"$ \\frac{4}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{2}{3} $","image_url":null,"alt":null}]', NULL, 0, 'Work done by Simran in 12 days = $ \frac{3}{5} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.981Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3304, 18, NULL, NULL, 'The book ''Devdas'' is written by:', NULL, '[{"text":"Gajanan Madhav","image_url":null,"alt":null},{"text":"Sarat Chandra Chattopadhyay","image_url":null,"alt":null},{"text":"Phanishwar Nath","image_url":null,"alt":null},{"text":"Amrit Lal Nagar","image_url":null,"alt":null}]', NULL, 1, 'The book "Devdas" is a classic Bengali novel written by Sarat Chandra Chattopadhyay.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.982Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3305, 18, NULL, NULL, 'Mahesh and Sujain are ranked eighth and eleventh respectively from the top in a class of 32 students. What will be their respective ranks from the bottom in the class?', NULL, '[{"text":"$ 25^{th} $ and $ 22^{nd} $","image_url":null,"alt":null},{"text":"$ 26^{th} $ and $ 22^{nd} $","image_url":null,"alt":null},{"text":"$ 24^{th} $ and $ 22^{nd} $","image_url":null,"alt":null},{"text":"$ 22^{nd} $ and $ 20^{th} $","image_url":null,"alt":null}]', NULL, 0, 'Mahesh''s rank from bottom = 32 - 8 + 1 = 25th

Sujain''s rank from bottom = 32 - 11 + 1 = 22nd', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.983Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3306, 18, NULL, NULL, 'If the sum of the diameters of two circles is 30 cm and the difference of their radii is 5 cm, then the ratio of area of the smaller circle to that of the bigger circle is:', NULL, '[{"text":"4:5","image_url":null,"alt":null},{"text":"3:4","image_url":null,"alt":null},{"text":"2:3","image_url":null,"alt":null},{"text":"1:4","image_url":null,"alt":null}]', NULL, 3, 'Let, $r_{1}, d_{1}$ and $A_{1}$ be the radius, diameter and Area of bigger circle respectively.

Similarly, $r_{2}, d_{2}$ and $A_{2}$ be the radius, diameter and Area of smaller circle respectively.

Given, $d_{1} + d_{2} = 30$

As we know, d = 2r then above eqn become, $r_{1} + r_{2} = 15 \ldots (1)$

Also given, $r_{1} - r_{2} = 5 \ldots (2)$

On solving eqn (1) and (2) we get, $r_{1} = 10, r_{2} = 5$

Ratio $\frac{A_{1}}{A_{2}} = \frac{\pi r_{1}}{\pi r_{2}}$

Ratio of area of the smaller circle to that of the bigger circle is $1 : 4$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.984Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3307, 18, NULL, NULL, 'Which of the following statement(s) is/are correct. Here a and r have their usual meaning:

(A) a, ar, ar², ..... is a G.P.

(B) n^{th} term of a G.P. is a_{n} = ar^{n-t}

(C) n^{th} term of a G.P. is a_{n} = ar^{n+1}

(D) Sum of first n terms of a G.P. is S_{n} = a \left( \frac{r^{n}-1}{r-1} \right), r \neq 1

(E) 4.16, 256, ..... is a G.P.

Chose the correct answer from the options given below:', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B), (D) and (E) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null}]', NULL, 3, '(A), (B) and (D) only are correct.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.985Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3308, 18, NULL, NULL, 'Select the option from given alternatives which will come in place of?

EXI :: 5X9 :: NXS : _?', NULL, '[{"text":"12X17","image_url":null,"alt":null},{"text":"13X17","image_url":null,"alt":null},{"text":"14X19","image_url":null,"alt":null},{"text":"14X21","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.986Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3309, 18, NULL, NULL, 'Infant Mortality Rate (IMR) is:', NULL, '[{"text":"Number of children born in a year","image_url":null,"alt":null},{"text":"Number of deaths in a year per 1,000 live births of children","image_url":null,"alt":null},{"text":"Total of live births in a year divided by total mid-year population","image_url":null,"alt":null},{"text":"Average number of children born to a woman over her lifetime","image_url":null,"alt":null}]', NULL, 1, 'Infant Mortality Rate (IMR) is the number of deaths in a year per 1,000 live births of children.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.986Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3310, 18, NULL, NULL, '_ is called the "Earth''s twin."', NULL, '[{"text":"Saturn","image_url":null,"alt":null},{"text":"Mars","image_url":null,"alt":null},{"text":"Venus","image_url":null,"alt":null},{"text":"Jupiter","image_url":null,"alt":null}]', NULL, 2, 'Venus is called the "Earth''s twin."', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.987Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3311, 18, NULL, NULL, '"Swachh Bharat Abhiyan" was launched on _.', NULL, '[{"text":"2 October, 2012","image_url":null,"alt":null},{"text":"2 October, 2013","image_url":null,"alt":null},{"text":"2 October, 2014","image_url":null,"alt":null},{"text":"2 October, 2015","image_url":null,"alt":null}]', NULL, 2, 'The Clean India Mission, or Swachh Bharat Abhiyan, is a nationwide initiative that was started by the Indian government on October 2, 2014.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.988Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3312, 18, NULL, NULL, 'The sum of the squares of three consecutive odd numbers is 2531. Find the smallest of these numbers.', NULL, '[{"text":"27","image_url":null,"alt":null},{"text":"29","image_url":null,"alt":null},{"text":"31","image_url":null,"alt":null},{"text":"37","image_url":null,"alt":null}]', NULL, 0, 'Let the number be, (x-2) and (x+2). Then form the equation as,

$ (x-2)^{2}+x^{2}+(x+2)^{2}=2531 $

On simplifying $ x^{2}-4x+4+x^{2}+x^{2}+4x+4=2531 $

$ 3x^{2}+8=2531 $

$ 3x^{2}=2531-8=2523 $

Or, $ x^{2}=\frac{2523}{3}=841 $ or x=29

So, the three numbers are 27, 29, 31

Thus, smaller is 27.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.988Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3313, 18, NULL, NULL, 'Find the area (in square units) of a triangle whose vertices are (1, -1), (-4, 6) and (-3, -5).', NULL, '[{"text":"22","image_url":null,"alt":null},{"text":"24","image_url":null,"alt":null},{"text":"25","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null}]', NULL, 1, 'Let A $(1,-1)$, B $(-4,6)$ and C $(-3,-5)$ be the vertices of a triangle ABC

Area = $\frac{1}{2}[x_1(y_2 - y_3) + x_2(y_3 - y_1) + x_3(y_1 - y_2)]$

Area = $\frac{1}{2}[1(6+5)+(-4)(-5+1)+(-3)(-1-6)]$

Area = 24 square units', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.989Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3314, 18, NULL, NULL, 'The price of an article is first increased by 20% and subsequently decreased by 25% due to reduction in sales. Find the net percentage change in price of the article.', NULL, '[{"text":"10% decrease","image_url":null,"alt":null},{"text":"0.2% increase","image_url":null,"alt":null},{"text":"8% decrease","image_url":null,"alt":null},{"text":"5% decrease","image_url":null,"alt":null}]', NULL, 0, 'Let the original cost = Rs. 100

Increased by 20%

New cost = 100 + 20 = Rs. 120

Decreased by 25% = $ \frac{120 \times 25}{100} = Rs. 30 $

New cost = 120 - 30 = Rs. 70

Overall change = 100 - 70 = Rs. 30

Required Percentage = $ \frac{30}{100} \times 100 = 30\% $

Thus, net percentage change = 10%', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.990Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3315, 18, NULL, NULL, 'Which amongst the following was an exclusive women force that fought for Independence of India from British rule?', NULL, '[{"text":"Rani Jhansi Brigade","image_url":null,"alt":null},{"text":"Annie Besant Force","image_url":null,"alt":null},{"text":"Lalleshwari","image_url":null,"alt":null},{"text":"Anushitan Samiti","image_url":null,"alt":null}]', NULL, 0, 'An exclusive women force that was vital to the Indian independence movement against British rule was the Rani Jhansi Regiment.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.990Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
