INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3318, 18, NULL, NULL, 'Where is the headquarters of NATO?', NULL, '[{"text":"England","image_url":null,"alt":null},{"text":"America","image_url":null,"alt":null},{"text":"Russia","image_url":null,"alt":null},{"text":"Belgium","image_url":null,"alt":null}]', NULL, 3, 'The headquarters of NATO (North Atlantic Treaty Organisation) is in Brussels, Belgium.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.993Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
