160, 118, 83, 75, 34, 20', NULL, '[{"text":"75","image_url":null,"alt":null},{"text":"34","image_url":null,"alt":null},{"text":"118","image_url":null,"alt":null},{"text":"83","image_url":null,"alt":null}]', NULL, 0, 'The pattern is -42, -35, -28, -21, -14. Therefore, wrong term in the series is 75. Instead of 75, it should be 55.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.994Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3320, 18, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(III), (B)-(IV), (C)-(III), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(III), (D)-(I)","image_url":null,"alt":null}]', NULL, 1, '(A)-(IV), (B)-(II), (C)-(I), (D)-(III)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-09-shift-2/q55-table-1.jpg', 'Table for question 55', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.996Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q55-table-1.jpg","alt":"Table for question 55","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3321, 18, NULL, NULL, 'In a month of 31 days, third Friday falls on 17th. What will be the last day of the month?', NULL, '[{"text":"5th Thursday","image_url":null,"alt":null},{"text":"5th Friday","image_url":null,"alt":null},{"text":"5th Saturday","image_url":null,"alt":null},{"text":"5th Sunday","image_url":null,"alt":null}]', NULL, 1, 'Friday will fall on 3, 10, 17, 24, 31 So, it will be 5th Friday on 31st.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.997Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3322, 18, NULL, NULL, 'What is the pH range of milk?', NULL, '[{"text":"(7.2 - 7.5)","image_url":null,"alt":null},{"text":"(9.2 - 9.5)","image_url":null,"alt":null},{"text":"(6.7 - 6.9)","image_url":null,"alt":null},{"text":"(3.4 - 3.9)","image_url":null,"alt":null}]', NULL, 2, 'The pH range of milk is typically around 6.7 to 6.9, making it slightly acidic.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.997Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3323, 18, NULL, NULL, 'The volumes of two cubes are in the ratio 8:27. The ratio of their surface areas is:', NULL, '[{"text":"2;3","image_url":null,"alt":null},{"text":"1:9","image_url":null,"alt":null},{"text":"4:9","image_url":null,"alt":null},{"text":"8:27","image_url":null,"alt":null}]', NULL, 2, 'In volume of cube, we have ratio as:

$ \frac{a_{1}^{3}}{a_{2}^{3}} = \frac{8}{27} $

$ \frac{a_{1}}{a_{2}} = \frac{2}{3} $

So, in case of surface area we have ratio as,

$ \frac{a_{1}^{2}}{a_{2}^{2}} = \frac{2^{2}}{3^{2}} = \frac{4}{9} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.998Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3324, 18, NULL, NULL, 'In a function girl were allowed to wear only red, blue or black dress. If 15 girls were wearing red, 10 girls were wearing blue and 20 girls were wearing black, then the probability that a girl selected at random was not wearing black dress is:', NULL, '[{"text":"$ \\frac{4}{9} $","image_url":null,"alt":null},{"text":"$ \\frac{7}{9} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{9} $","image_url":null,"alt":null},{"text":"$ \\frac{8}{9} $","image_url":null,"alt":null}]', NULL, 2, 'Total number of girls = 45

The probability that a girl selected at random was

not wearing black dress = $ \frac{10+15}{45} = \frac{25}{45} = \frac{5}{9} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.998Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3325, 18, NULL, NULL, 'Number of employees in different departments of an organisation and department wise percentage of female employees is given in the table.

What is the ratio of the number of females in production department to the number of females in the Marketing Department?', NULL, '[{"text":"22:23","image_url":null,"alt":null},{"text":"35:33","image_url":null,"alt":null},{"text":"23:22","image_url":null,"alt":null},{"text":"33:35","image_url":null,"alt":null}]', NULL, 2, 'Ratio of the number of females in production department to the number of females in the Marketing Department = 23:22', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-09-shift-2/q60-table-1.jpg', 'Table for question 60', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:05.998Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-09-shift-2/q60-table-1.jpg","alt":"Table for question 60","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3326, 18, NULL, NULL, 'Justice DY Chandrachud has become the new _ Chief Justice of India?', NULL, '[{"text":"$ 55^{th} $","image_url":null,"alt":null},{"text":"$ 50^{th} $","image_url":null,"alt":null},{"text":"$ 45^{th} $","image_url":null,"alt":null},{"text":"$ 52^{th} $","image_url":null,"alt":null}]', NULL, 1, 'Justice DY Chandrachud has become the 50th Chief Justice of India.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.000Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3327, 18, NULL, NULL, 'Choose that set of numbers from the four alternative sets, that is similar to the given set.

Given set: (265, 392, 285)', NULL, '[{"text":"(373, 472, 366)","image_url":null,"alt":null},{"text":"(343, 482, 360)","image_url":null,"alt":null},{"text":"(363, 482, 361)","image_url":null,"alt":null},{"text":"(373, 482, 366)","image_url":null,"alt":null}]', NULL, 3, '265 = 2 + 6 + 5 = 13

392 = 3 + 9 + 2 = 14

285 = 2 + 8 + 5 = 15.

Similar set of number from the four alternatives is option (d).', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.001Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3328, 18, NULL, NULL, 'Who was the first Indian Nobel Laureate?', NULL, '[{"text":"Dr. C.V Raman","image_url":null,"alt":null},{"text":"ST Radha Krishnan","image_url":null,"alt":null},{"text":"Rabindranath Tagore","image_url":null,"alt":null},{"text":"S.N. Bose","image_url":null,"alt":null}]', NULL, 2, 'The first Indian to win a Nobel Prize was Rabindranath Tagore. In 1913, he was awarded the Nobel Prize in Literature for his collection of poems "Gitanjali."', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.001Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3329, 18, NULL, NULL, 'Which of the following statements are true for rectangles?

A. All interior angles are right angles.

B. Diagonals are perpendicular to each other.

C. Diagonals are equal.

D. Opposite angles are supplementary.', NULL, '[{"text":"A and B only","image_url":null,"alt":null},{"text":"A and C only","image_url":null,"alt":null},{"text":"A, B and C only","image_url":null,"alt":null},{"text":"A, C and D only","image_url":null,"alt":null}]', NULL, 3, 'A, C and D only are true for rectangles.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.002Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3330, 18, NULL, NULL, 'If A(2, 3), B(2, 4) C(4, 9) and D(x, 8) are the vertices of a parallelogram ABCD, then find the value of x.', NULL, '[{"text":"8","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'Midpoint of BD = Midpoint of AC

$ \frac{2+x}{2} = \frac{2+4}{2} $

x = 4', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.002Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3331, 18, NULL, NULL, 'What is the prescribed strength of judges in the constitutional bench of supreme Court?', NULL, '[{"text":"2 Judges","image_url":null,"alt":null},{"text":"At least 5 Judges","image_url":null,"alt":null},{"text":"3 judges","image_url":null,"alt":null},{"text":"4 judges","image_url":null,"alt":null}]', NULL, 1, 'A constitutional bench of the Supreme Court must have a minimum of five judges, as stated in Article 124(1) of the Indian Constitution.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.003Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3332, 18, NULL, NULL, 'Three dice are thrown. The probability of getting a sum of numbers which is a perfect cube, is:', NULL, '[{"text":"$ \\frac{1}{6} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{8} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{36} $","image_url":null,"alt":null},{"text":"$ \\frac{7}{12} $","image_url":null,"alt":null}]', NULL, 3, 'The probability of getting a sum of numbers which is perfect cube is $ \frac{7}{12} $.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.003Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3333, 18, NULL, NULL, 'Consider the following statements:

A. Antigen A and antibody ''a'', Antigen ''B'' and antibody ''b'' cannot live together.

B. Blood group ''O'' is called universal Donor.

C. Blood group ''AB'' is called Universal Receptor.

D. At the time of Blood transfusion RH-factor is also tested.

E. Main function of blood platelets is to protect the body from the disease.', NULL, '[{"text":"B, C, D and E only","image_url":null,"alt":null},{"text":"A, B, C and D only","image_url":null,"alt":null},{"text":"A and B only","image_url":null,"alt":null},{"text":"C, D and E only","image_url":null,"alt":null}]', NULL, 1, 'A, B, C and D are the correct statements.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.003Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3334, 18, NULL, NULL, 'How many times in a day hour hand and minute hand of a clock will coincide?', NULL, '[{"text":"24 times","image_url":null,"alt":null},{"text":"22 times","image_url":null,"alt":null},{"text":"44 times","image_url":null,"alt":null},{"text":"48 times","image_url":null,"alt":null}]', NULL, 1, 'The minute and hour hand coincide every 65 minutes and not 60 minutes. So, we can say that the two hands coincide exactly 11 times in a 12-hour span. We have to find the number of times in a day so we have 24 hours in a day. Therefore, the number of times the two hands coincide $ =2 \times 11 = 22 $ times.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.004Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3335, 18, NULL, NULL, 'Study the following information and answer the question given below:

A family has 5 members P, Q, R, S and T, each have a different weight.

i. P weighs twice as much as Q

ii. Q weighs four and a half times as much as R

iii. R weighs half as much as S

iv. S weighs half as much as T

v. T weighs less than P but more than R

Which of the following member of a family is the

Which of the following member of a family is the lightest in weight?', NULL, '[{"text":"P","image_url":null,"alt":null},{"text":"Q","image_url":null,"alt":null},{"text":"R","image_url":null,"alt":null},{"text":"S","image_url":null,"alt":null}]', NULL, 2, 'Let weight of R = x

So, weight of Q will be = 4.5x and weight of P will be = 9x.

Now S weighs half as much as T, so weight of S will be = 2x.

Therefore P > Q > S > R. It is given that T weighs more than R. Therefore, R is lightest member in the family,', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.004Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3336, 18, NULL, NULL, 'Match List-I with List-II:', NULL, '[{"text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)","image_url":null,"alt":null}]', NULL, 3, '(A)-(IV), (B)-(III), (C)-(II), (D)-(I)', NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-10-shift-3/q11-table-1.jpg', 'Table for question 11', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.004Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q11-table-1.jpg","alt":"Table for question 11","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3337, 18, NULL, NULL, 'Find the alternative which contains figure (A) as its part', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-10-shift-3/q12-figure-1.jpg', 'Figure for question 12', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.005Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q12-figure-1.jpg","alt":"Figure for question 12","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q12-options.jpg","alt":"Printed answer choices for question 12","kind":"options"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3338, 18, NULL, NULL, 'The value of a car depreciates every year by 10%. What will be its value after 3 years if its present value is ₹6,25,000?', NULL, '[{"text":"₹4,50,000","image_url":null,"alt":null},{"text":"₹52,250","image_url":null,"alt":null},{"text":"₹455.625","image_url":null,"alt":null},{"text":"₹4,62,500","image_url":null,"alt":null}]', NULL, 2, 'Original price is ₹25,000

Rate of increment = 10%

Price after 1 year = 625000 × (1 - $ \frac{10}{100} $) = 625000 ×

$ \frac{90}{100} $ = 5,62,500

Price after 2 years = (1 - $ \frac{10}{100} $) = 562500 × $ \frac{90}{100} $

=506250

Price after 3 years = 506250 × $ \frac{90}{100} $ = ₹455.625', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.005Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3339, 18, NULL, NULL, 'The average of a positive number, its square and 3 is

5. Find the number.', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'By putting option,

$ \frac{3+9+3}{3}=5 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.005Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3340, 18, NULL, NULL, 'If Anil''s salary is 20% less than that of Rama, then by what percent is Rama''s salary more than that of Anil?', NULL, '[{"text":"20%","image_url":null,"alt":null},{"text":"25%","image_url":null,"alt":null},{"text":"15%","image_url":null,"alt":null},{"text":"30%","image_url":null,"alt":null}]', NULL, 1, 'Let Rama''s salary be Rs. 100

Anil''s salary is 20% less than Rama''s salary

Salary of Anil = 80% of 100 = Rs. 80

Rama''s salary is Rs. 20 more than that of Anil.

Now, the required percentage = $ \frac{20}{8} $(100)% = 25%

Rama''s salary is 25% more than Anil''s salary.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.006Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3341, 18, NULL, NULL, 'Akshay is the son of Kapil. Simar, Kapil''s sister, has a son Montu and daughter Sara. Pawan is the maternal uncle of Montu. How is Akshay related to Montu?', NULL, '[{"text":"Sister-in-law","image_url":null,"alt":null},{"text":"Mother","image_url":null,"alt":null},{"text":"Sister","image_url":null,"alt":null},{"text":"Cousin","image_url":null,"alt":null}]', NULL, 3, 'Kapil is brother or sister of Montu''s mother. So, Akshay, who is son of Kapil would be cousin of Kapil.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.006Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3342, 18, NULL, NULL, 'Lalit Kala Akademi, the National Academy of Art, was set up in _', NULL, '[{"text":"1968","image_url":null,"alt":null},{"text":"1964","image_url":null,"alt":null},{"text":"1954","image_url":null,"alt":null},{"text":"1951","image_url":null,"alt":null}]', NULL, 2, 'Lalit Kala Akademi (National Academy of Art), New Delhi was inaugurated on 5th August 1954 by the then Minister for Education, Maulana Abul Kalam Azad.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.006Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3343, 18, NULL, NULL, 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R

Assertion A: Forest cutting is desirable from the point of view of soil erosion.

Reason R: Cutting of forests reduces the interception of rain water.

In the light of the above statements, choose the correct answer from the options given below.', NULL, '[{"text":"Both A and R are true and r is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true but R is NOT the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 3, 'Forest cutting is not desirable from the point of view of soil erosion. Therefore, A is false but R is true.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.007Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3344, 18, NULL, NULL, 'Which term of the AP: 3, 7, 11, ....., 147 is its middle term?', NULL, '[{"text":"$ 18^{th} $","image_url":null,"alt":null},{"text":"$ 19^{th} $","image_url":null,"alt":null},{"text":"$ 20^{th} $","image_url":null,"alt":null},{"text":"$ 21^{st} $","image_url":null,"alt":null}]', NULL, 1, 'Here, a = 3, x_{n}=147, common difference d = 4

$ x_{n}=a+(n-1)d $

$ 147=3+(n-1)4 $

n-1=36, n=37

Thus the given series consist of 37 terms.

Therefore its middle term will be $ \frac{37+1}{2}=19th\ term $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.007Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3345, 18, NULL, NULL, 'Which of the following Mughal rulers set up a new religion called Din-i-Ilahi?', NULL, '[{"text":"Aurangzeb","image_url":null,"alt":null},{"text":"Humayun","image_url":null,"alt":null},{"text":"Akbar","image_url":null,"alt":null},{"text":"Shah Jahan","image_url":null,"alt":null}]', NULL, 2, 'Akbar, the third ruler of the Mughal Empire, founded the Din-i-Ilahi in the late 16th century.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.008Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3346, 18, NULL, NULL, 'If the average of 15, 25, 19, 20, 23, 18 and $ (x - 3) $ is 20. then Find the average of $ x $, $ (x + 6) $, $ (2x - 1) $ and 23.', NULL, '[{"text":"20","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null},{"text":"$ 28\\frac{1}{2} $","image_url":null,"alt":null},{"text":"30","image_url":null,"alt":null}]', NULL, 3, 'We know, $ Mean = \frac{Sum of all observation}{Total number of observation} $

$ 20 = \frac{15 + 25 + 19 + 20 + 23 + 18 + (x - 3)}{7} $

$ 140 = 117 + x $

x = 23

Then $ x + 6 = 29, 2x - 1 = 45 $

Average = $ \frac{23 + 29 + 45 + 23}{4} = 30 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.008Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3347, 18, NULL, NULL, 'The ratio between length and breadth of a rectangle is 3:2. If area of the rectangle is $ 96 \, cm^2 $, then length of the rectangle is', NULL, '[{"text":"6 cm","image_url":null,"alt":null},{"text":"12 cm","image_url":null,"alt":null},{"text":"8 cm","image_url":null,"alt":null},{"text":"16 cm","image_url":null,"alt":null}]', NULL, 1, 'Let the length and breadth of the rectangle be 3x and 2x respectively.

Now, $ 3x \times 2x = 96 $

$ x^{2}=\frac{96}{6} $

x = 4 cm

Length = 3x = 12 cm', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.008Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
