INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3353, 18, NULL, NULL, 'If two squares X and Y have each side of 10 m and 20 m respectively, then the side of the square Z whose area is equal to the sum of the areas of square X and square Y is:', NULL, '[{"text":"$ 10\\sqrt{3} $ m","image_url":null,"alt":null},{"text":"$ 10\\sqrt{2} $ m","image_url":null,"alt":null},{"text":"$ 10\\sqrt{7} $ m","image_url":null,"alt":null},{"text":"$ 10\\sqrt{5} $ m","image_url":null,"alt":null}]', NULL, 3, 'Area of squares $ X = 10^{2} = 100m^{2} $

Area of the square Y = 20^{2} = 400m^{2}

Area of square Z = 100 + 400 = 500 m^{2}

Side of square Z = $ \sqrt{500} $ = $ 10\sqrt{5} $ m', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.014Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3354, 18, NULL, NULL, 'In how many years a sum placed on compound interest becomes 8 times of itself, if it becomes twice in 6 years?', NULL, '[{"text":"20","image_url":null,"alt":null},{"text":"18","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null}]', NULL, 1, 'A certain sum at C.I becomes n times in t years then, n times -> t years

$n^{m}$ times $\rightarrow (m \times t)$ years

A sum of money placed at C.I doubles itself in 6 years

2 times $\rightarrow$ 6 years

8 times $\rightarrow$ $2^{3}$ times = 3 × 6 years = 18 years', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.015Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
