INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3359, 18, NULL, NULL, 'The _ lies above the mesosphere.', NULL, '[{"text":"Troposphere","image_url":null,"alt":null},{"text":"Thermosphere","image_url":null,"alt":null},{"text":"Exosphere","image_url":null,"alt":null},{"text":"Stratosphere","image_url":null,"alt":null}]', NULL, 1, 'The thermosphere is the layer of the atmosphere that lies above the mesosphere.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.018Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
