B', NULL, '[{"text":"A","image_url":null,"alt":null},{"text":"B","image_url":null,"alt":null},{"text":"C","image_url":null,"alt":null},{"text":"D C D","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, '/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-1.jpg', 'Figure for question 35', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.018Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-1.jpg","alt":"Figure for question 35","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-2.jpg","alt":"Figure for question 35","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-3.jpg","alt":"Figure for question 35","kind":"figure"},{"url":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-4.jpg","alt":"Figure for question 35","kind":"figure"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3361, 18, NULL, NULL, 'At what time between 4 0'' clock and 5 0'' clock hour hand and minute hand will coincide?', NULL, '[{"text":"4:18 $ \\frac{9}{11} $","image_url":null,"alt":null},{"text":"4:22 $ \\frac{9}{11} $","image_url":null,"alt":null},{"text":"4:21 $ \\frac{9}{11} $","image_url":null,"alt":null},{"text":"4:23 $ \\frac{9}{11} $","image_url":null,"alt":null}]', NULL, 2, 'The hour hand of a clock covers 360^{\circ} in 12 hrs or 30^{\circ} in 1 hour or 0.5^{\circ} in 1 min.

At 4:00, the minute hand has covered 0^{\circ} and the hour hand has covered 120^{\circ}.

Let the time after which the hands coincide be x min.

So, the hour hand covers 120 + \frac{x}{2} up to that time and the minute hand covers 6x^{\circ} up to that time.

When they coincide, the angles should be the same. So, we can write 120 + \frac{x}{2} = 6x

$ \frac{12x-x}{2}=120 $

$ x=\frac{240}{11}=21\frac{9}{11} $

Therefore, they will coincide at 4:21.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.019Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3362, 18, NULL, NULL, 'A solid hemisphere of radius 24 cm is melted and identical cones each of base radius 8 cm and height 6 cm are formed. How many such cones are formed?', NULL, '[{"text":"144","image_url":null,"alt":null},{"text":"96","image_url":null,"alt":null},{"text":"72","image_url":null,"alt":null},{"text":"24","image_url":null,"alt":null}]', NULL, 2, 'ATQ, Volume of hemisphere = Volume of cone

$ \frac{2}{3} \times 24^3 = \frac{1}{3} \times 8^2 \times 6 $

Number of cones = $ \frac{\frac{2}{3}\pi r^3}{\frac{2}{3}\pi r^3} = \frac{\frac{2}{3} \times 24^3}{\frac{1}{3} \times 8^2 \times 6} = 72 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.019Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3363, 18, NULL, NULL, 'Sourav completes a journey in 5½ hours. If he covers half of the distance at 5 km/h and the remaining distance at 6 km/h, then find the total distance covered by him.', NULL, '[{"text":"30 km","image_url":null,"alt":null},{"text":"35 km","image_url":null,"alt":null},{"text":"33 km","image_url":null,"alt":null},{"text":"39 km","image_url":null,"alt":null}]', NULL, 0, 'Let the distance travelled by man is 2d

$ \frac{d}{5}+\frac{d}{6}=5\frac{1}{2} $

$ \frac{11d}{30}=\frac{11}{2} $

d = 15

Then distance travelled by man = 2d = 30 km', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.020Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3364, 18, NULL, NULL, 'Who is the winner of UNESCO Peace Prize 2022?', NULL, '[{"text":"Volodymyr Zelenskyy","image_url":null,"alt":null},{"text":"Tadashi Hattori","image_url":null,"alt":null},{"text":"Swati Piramal","image_url":null,"alt":null},{"text":"Angela Merkel","image_url":null,"alt":null}]', NULL, 3, 'Former German chancellor Angela Merkel has been awarded the 2022 UNESCO Peace Prize for "her efforts to welcome refugees".', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.020Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3365, 18, NULL, NULL, 'If \cos6\theta=\sin3\theta, then the value of \theta is:', NULL, '[{"text":"$ 9^{\\circ} $","image_url":null,"alt":null},{"text":"$ 12^{\\circ} $","image_url":null,"alt":null},{"text":"$ 10^{\\circ} $","image_url":null,"alt":null},{"text":"$ 6^{\\circ} $","image_url":null,"alt":null}]', NULL, 2, 'putting $\theta=10^{\circ}$

$cos60^{\circ}=sin30^{\circ}$

$\frac{1}{2}=\frac{1}{2}$

Thus $\theta=10^{\circ}$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.021Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3366, 18, NULL, NULL, 'Simon Commission came to India in _.', NULL, '[{"text":"1925","image_url":null,"alt":null},{"text":"1928","image_url":null,"alt":null},{"text":"1923","image_url":null,"alt":null},{"text":"1930","image_url":null,"alt":null}]', NULL, 1, 'Simon Commission came formed in 1927 but came to India in 1927. But in official answer key 1927 is the correct answer.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.021Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3367, 18, NULL, NULL, 'In a school, ratio of number of boys to that of girls was 6:5. In the next year, number of boys increased by 20% and number of girls increased by 10% resulting in an increase of 119 students in the school. How many students were there in the school initially?', NULL, '[{"text":"680","image_url":null,"alt":null},{"text":"750","image_url":null,"alt":null},{"text":"770","image_url":null,"alt":null},{"text":"780","image_url":null,"alt":null}]', NULL, 2, 'Let the initial number of students be x

Then, Number of boys = $ \frac{6}{6+5}x = \frac{6x}{11} $

Similarly, Number of girls = $ \frac{5x}{11} $

20% increment in number of boys = $ \frac{6x}{11} + 20\% of \frac{6x}{11} $

10% increment in number of girls = $ \frac{5x}{11} + 10\% of \frac{5x}{11} $

ATQ. $ \frac{6x}{11} + 20\% of \frac{6x}{11} + \frac{5x}{11} + 10\% of \frac{5x}{11} = x + 119 $

$ \frac{6x}{11} + \frac{6x}{55} + \frac{5x}{11} + \frac{x}{22} = x + 119 $

127x - 110x = 119 $ \times $ 110

x = 770

Thus, number of students initially in the school is 770.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.021Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3368, 18, NULL, NULL, 'Find the missing term which can be filled at "?" place

1,3,7,22,67,?1077', NULL, '[{"text":"269","image_url":null,"alt":null},{"text":"263","image_url":null,"alt":null},{"text":"362","image_url":null,"alt":null},{"text":"267","image_url":null,"alt":null}]', NULL, 0, 'The sequence is

$ 1 \times 2 + 1 = 3 $

$ 3 \times 2 + 1 = 7 $

$ 7 \times 3 + 1 = 22 $

$ 22 \times 3 + 1 = 67 $

$ 67 \times 4 + 1 = 269 $

$ 269 \times 4 + 1 = 1077 $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.022Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3369, 18, NULL, NULL, 'In a certain code, ''lee ra de'' means ''Upanishads are it'', ''mo nil'' means ''you read'', ''nil pom ra'' means ''you like it'' and ''tok lee fo'' means ''They are immortal''. How will you write ''Upanishads you like'' in that code?', NULL, '[{"text":"de nil pom","image_url":null,"alt":null},{"text":"de nil ra","image_url":null,"alt":null},{"text":"mo nil pom","image_url":null,"alt":null},{"text":"nil tok lee","image_url":null,"alt":null}]', NULL, 0, 'lee → are

de → Upanishads

nil → you

ra → it

pom → like

So ''Upanishads you like'' will be written as ''de nil pom'' in that code.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.022Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3370, 18, NULL, NULL, 'White revolution refers to _.', NULL, '[{"text":"Cotton textile Industry","image_url":null,"alt":null},{"text":"Marble Industry","image_url":null,"alt":null},{"text":"Cement Industry","image_url":null,"alt":null},{"text":"Dairying","image_url":null,"alt":null}]', NULL, 3, 'The White Revolution in India, also known as Operation Flood, was a successful program implemented to increase milk production and make the country self-sufficient in milk and dairy products.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.022Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3371, 18, NULL, NULL, 'If today is Saturday, then day after 53 days will be:', NULL, '[{"text":"Friday","image_url":null,"alt":null},{"text":"Monday","image_url":null,"alt":null},{"text":"Tuesday","image_url":null,"alt":null},{"text":"Wednesday","image_url":null,"alt":null}]', NULL, 3, 'A week has 7 days "Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday".

53 / 7 = 7 (Remainder = 4)

So we can say that after multiples of 7 days, the day will repeat itself as Saturday. Hence after 49 days Saturday will occur again.

So, we calculate after the remainder (4), the answer is Wednesday.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.023Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3372, 18, NULL, NULL, 'A shopkeeper sold $ \frac{2}{3} $ of his stock of rice at a profit of 5% and the remaining stock at a loss of 2%. If his total profit was ₹1000, then the cost price of the whole stock of rice is:', NULL, '[{"text":"₹24,800","image_url":null,"alt":null},{"text":"₹32,600","image_url":null,"alt":null},{"text":"₹37,500","image_url":null,"alt":null},{"text":"₹48,000","image_url":null,"alt":null}]', NULL, 2, 'Let the cost price of the rice is Rs. X

$ \frac{2}{3}x \times \frac{5}{100} - \frac{1}{3}x \times \frac{2}{100} = 1000 $

$ 10x - 2x = 300000 $

x=37500

Thus, the cost price of the whole stock of rice is ₹37,500.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.023Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3373, 18, NULL, NULL, 'Which is the largest salt water inland lake of India, that provides sanctuary to lakhs of migratory birds during winter?', NULL, '[{"text":"Pachpadra Lake","image_url":null,"alt":null},{"text":"Chilika Lake","image_url":null,"alt":null},{"text":"Pangong Lake","image_url":null,"alt":null},{"text":"Lomar Lake","image_url":null,"alt":null}]', NULL, 1, 'The largest saltwater inland lake in India that provides sanctuary to a large number of migratory birds during winter is Chilika Lake.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.024Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3374, 18, NULL, NULL, 'Mean, Median and Mode of a data are related by the relation', NULL, '[{"text":"3 Mode - 2 Median = Mean","image_url":null,"alt":null},{"text":"3 Mean - 2 Mode = Median","image_url":null,"alt":null},{"text":"3 Median - 2 Mode = Mean","image_url":null,"alt":null},{"text":"3 Median - 2 Mean = Mode","image_url":null,"alt":null}]', NULL, 3, '3 Median - 2 Mean = Mode', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:06.024Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
