INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3487, 4, NULL, NULL, 'A heater boils x amount of water in time $ t_{1} $ and another heater boils the same water in time $ t_{2} $ having resistances $ R_{1} $ and $ R_{2} $ respectively. The ratio $ \frac{t_{1}}{t_{2}} $ will be:', NULL, '[{"text":"$ \\left(\\frac{R_{1}}{R_{2}}\\right)^{2} $","image_url":null,"alt":null},{"text":"$ \\left(\\frac{R_{2}}{R_{1}}\\right)^{2} $","image_url":null,"alt":null},{"text":"$ \\frac{R_{2}}{R_{1}} $","image_url":null,"alt":null},{"text":"$ \\frac{R_{1}}{R_{2}} $","image_url":null,"alt":null}]', NULL, 3, 'Let $ R_{1}R_{2} $ be the resistance of two heaters and time $ t_{1} $ and another heater boils the same water in time $ t_{2} $. If V is the voltage applied to heated then

$ H = \frac{V^{2}}{R_{1}} t_{1} = \frac{V^{2}}{R_{2}} t_{2} $

$ \mathrm{or} \frac{t_{1}}{R_{1}} = \frac{t_{2}}{R_{2}} $

$ \Rightarrow \frac{R_{1}}{R_{2}} = \frac{t_{1}}{t_{2}} $', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:16.990Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3488, 4, NULL, NULL, 'Which of the following statements are correct?

A. A Equi Convex lens of $f = 20\ \mathrm{cm}$ is cut as the $f$ focal length of each part is 10 cm.

B. A Equi Convex lens of $f = 20\ \mathrm{cm}$ is cut as the focal length of each part is 20 cm.

C. If an Equi Convex lens of refractive index $\mu_{1}$ is placed in a liquid of $(\mu2)$ such that $(\mu_{1} > \mu2)$. It will not change its nature.

D. A Convex lens of $f = 20\ \mathrm{cm}$ is cut as the focal length of each part is 40 cm.', NULL, '[{"text":"A, B only","image_url":null,"alt":null},{"text":"A, B, c only","image_url":null,"alt":null},{"text":"B, C Only","image_url":null,"alt":null},{"text":"B, C, D Only","image_url":null,"alt":null}]', NULL, 3, 'The focal length of equiconvex lens is 20 cm

$$ \frac{1}{f}=(\mu-1)\left(\frac{1}{R_{1}}-\frac{1}{R_{2}}\right) $$

for equiconvex lens $ R_{1} = -R_{2} = R $ thus,

$$ \frac{1}{20}=(\mu-1)\left(\frac{1}{R}+\frac{1}{R}\right) $$

$$ \Rightarrow R=40(\mu-1) $$

when lens is cut into two equal parts perpendicular to optical axis then,

$$ R_{1}=\infty,R_{2}=R $$

thus

$$ \frac{1}{\mathrm{f}^{\prime}}=(\mu-1)\left(\frac{1}{\mathrm{R}_{1}}-\frac{1}{\mathrm{R}_{2}}\right) $$

$$ \frac{1}{\mathrm{f}^{\prime}}=(\mu-1)\left(\frac{1}{\mathrm{R}}\right) $$

by putting value of R we get,

$$ \frac{1}{\mathrm{f}^{\prime}}=(\mu-1)\left(\frac{1}{40(\mu-1)}\right) $$

$$ \Rightarrow f^{\prime}=40cm $$

new focal length of each part is 40 cm, becomes double', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:16.990Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3489, 4, NULL, NULL, 'Which of the following statements are collect about transformers?

A. Transformers cannot be used to step up DC.

B. The frequency of output across the secondary is always equal to the frequency of input across the primary.

C. The output power of a transformer may be increased to a value which is more than the input power.

D. Transformation ratio is equal to turns ratio.

E. In a step-up transformer, secondary current is less than primary current.', NULL, '[{"text":"A, B, C","image_url":null,"alt":null},{"text":"B, C, D","image_url":null,"alt":null},{"text":"C, D, A","image_url":null,"alt":null},{"text":"A, B, D, E","image_url":null,"alt":null}]', NULL, 3, 'the output power in a step-up transformer is equal to the input power.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:16.991Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3490, 4, NULL, NULL, 'A Potentiometer wire of length L and a resistance r are connected in series with a battery of emf $ E_{0} $ and a resistance $ r_{(a)} $. An unknown emf E is balanced at a length l of the potentiometer wire. The emf E will be:', NULL, '[{"text":"$ \\frac{LE_{0}r}{(r+r_{1})l} $","image_url":null,"alt":null},{"text":"$ \\frac{E_{0}r}{lr_{1}} $","image_url":null,"alt":null},{"text":"$ \\frac{E_{0}r}{(r+r_{1})}\\cdot\\frac{l}{L} $","image_url":null,"alt":null},{"text":"$ \\frac{E_{0}l}{L} $","image_url":null,"alt":null}]', NULL, 2, 'Current in ABCD

$$I = \frac{V}{R_{eq}} = \frac{V}{r + r_1}$$

potential difference across potentiometr $$ = Ir$$

$$= \frac{V r}{(r + r_1)}$$

Potential gradient $$ = \frac{V}{L} = \frac{V r}{(r + r_1)} \times \frac{1}{L} = k$$

we know that EMF = kl

$l = \text{balancing length}$

$$ \mathrm{EMF}=\left(\frac{\mathrm{Vr}}{\mathrm{r}+\mathrm{r}_{1}}\right)\frac{1}{\mathrm{L}}=\left(\frac{Er}{\mathrm{r}+\mathrm{r}_{1}}\right)\frac{1}{\mathrm{L}} $$', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:16.991Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3491, 4, NULL, NULL, 'A capacitor of $ 25\mu F $ is connected in series with d.c Voltage of 5V. The value of current in the circuit will be:', NULL, '[{"text":"$ 2 \\times 10^{5} $ A","image_url":null,"alt":null},{"text":"5A","image_url":null,"alt":null},{"text":"$ 5 \\times 10^{6} $ A","image_url":null,"alt":null},{"text":"Zero","image_url":null,"alt":null}]', NULL, 3, 'For a DC supply of 5 V, the frequency is zero, i.e., f = 0 Hz.

For a DC supply of 5 V, under steady-state, i.e., at $t \to \infty$, the capacitor will act as an open circuit because it will offer infinite resistance.

$\therefore$ The steady-state current will be 0 A.', NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:16.991Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
