INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3686, 6, NULL, NULL, 'Identify the step involved in polymerase chain reaction from the given figure below.', NULL, '[{"text":"Primer extension","image_url":null,"alt":null},{"text":"Denaturation","image_url":null,"alt":null},{"text":"Extension","image_url":null,"alt":null},{"text":"Annealing","image_url":null,"alt":null}]', NULL, 3, 'This step is annealing allows the primers to connect to a specific spot on the single-stranded template DNA.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3687, 6, NULL, NULL, '''Rivet popper'' hypothesis was proposed by', NULL, '[{"text":"Alexander Von Humboldt","image_url":null,"alt":null},{"text":"Paul Ehrlich","image_url":null,"alt":null},{"text":"Edward Wilson","image_url":null,"alt":null},{"text":"Robert May","image_url":null,"alt":null}]', NULL, 1, 'The Rivet Popper Hypothesis was proposed by Paul Ehrlich. The hypothesis suggests the importance of species richness in the maintenance of the ecosystem.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3688, 6, NULL, NULL, 'Which of the following genes control corn borer disease?', NULL, '[{"text":"amp $ ^{R} $","image_url":null,"alt":null},{"text":"cry I Ac","image_url":null,"alt":null},{"text":"cry / Ab","image_url":null,"alt":null},{"text":"cry II Ab","image_url":null,"alt":null}]', NULL, 2, 'The proteins encoded by the genes cryIAc and cryIIAb control the cotton bollworms, that of cryIAb controls corn borer.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3689, 6, NULL, NULL, 'The rate of decomposition in a particular climatic condition is quicker, if detritus is rich in _ & _', NULL, '[{"text":"Sugars, Phosphorus","image_url":null,"alt":null},{"text":"Lignin, Phosphorous","image_url":null,"alt":null},{"text":"Sugars, Nitrogen","image_url":null,"alt":null},{"text":"Lignin, Chitin","image_url":null,"alt":null}]', NULL, 2, 'The rate of decomposition is controlled by chemical composition of detritus and climatic factors. In a particular climatic condition, decomposition rate is slower if detritus is rich in lignin and chitin, and quicker, if detritus is rich in nitrogen and water-soluble substances like sugars. Temperature and soil moisture are the most important climatic factors that regulate decomposition through their effects on the activities of soil microbes. Hence, option C is correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3690, 6, NULL, NULL, 'Which of the following is a natural method of birth control?', NULL, '[{"text":"Condoms","image_url":null,"alt":null},{"text":"Lactational amenorrhea","image_url":null,"alt":null},{"text":"IUD","image_url":null,"alt":null},{"text":"Diaphragms","image_url":null,"alt":null}]', NULL, 3, 'Lactational amenorrhoea is the method of natural contraception which is based on the fact that the ovulation and therefore the menstrual cycle do not occur during the period of intense lactation following parturition. Hence, option B is correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3691, 6, NULL, NULL, 'The Graafian follicle ruptures to release the ovum from the ovary by the process called', NULL, '[{"text":"Ovulation","image_url":null,"alt":null},{"text":"Menstruation","image_url":null,"alt":null},{"text":"Implantation","image_url":null,"alt":null},{"text":"Copulation","image_url":null,"alt":null}]', NULL, 0, 'Graafian follicles rupture to release the secondary oocyte and this process is called ovulation. The secondary oocyte completes meiosis II to form ovumi and a second polar body during fertilisation.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3692, 6, NULL, NULL, 'Match List-I with List-II', NULL, '[{"text":"A-III, B-I, C-II, D-IV","image_url":null,"alt":null},{"text":"A-IV, B-III, C-I, D-II","image_url":null,"alt":null},{"text":"A-IV, B-I, C-III, D-II","image_url":null,"alt":null},{"text":"A-IV, B-II, C-III, D-I","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-20/q26-table-1.jpg', 'Table for question 26', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.109Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-20/q26-table-1.jpg","alt":"Table for question 26","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3693, 6, NULL, NULL, 'Select the statement that are correct for GM plants with genetic modifications.

A. Made crops tolerant to abiotic stresses

B. Increased the reliance on chemical pesticides

C. Helped to reduce post-harvest losses

D. Decrease efficiency of mineral usage by plants

E. Enhanced nutritional value of food', NULL, '[{"text":"C and E only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"A, C and E only","image_url":null,"alt":null},{"text":"C, D and E only","image_url":null,"alt":null}]', NULL, 2, 'Genetic modification has:

(i) Made crops more tolerant to abiotic stress (cold, drought, salt, heat.)

(ii) Reduced reliance on chemical pesticides (pest-resistant crops).

(iii) Helped to reduce on post-harvest losses.

(iv) Increased efficiency of mineral usage by plants (this prevents early exhaustion of fertility of soil).

(v) Enhanced nutritional value of food, e.g., Vitamin ''A'' enriched rice.

In addition to these uses, GM has been used to create tailor-made plants to supply alternative resources to industries, in the form of starch, fuel, and pharmaceuticals.

28. (b, c) A parent with A blood group can have two possible genotypes, "IA IA" and "IA IO"; similarly parent with B blood group can have two possible genotypes, "IB IB" and "IB IO". Thus, they have three alleles, "IA", "IB" and "IO" which can make total six genotypes: IA IA, IA IO, IB IB, IB IO, IA IB and IOIO. Since, IA and IB alleles are dominant over IO allele; the genotypes IA IO and IB IO give A and B blood group respectively. Genotypes IA IA, IB IB, IO IO show A, B and O blood groups respectively. Due to codominance of "IA" and "IB" alleles, the genotype "IAIB" produce "AB" blood group respectively.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.110Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3694, 6, NULL, NULL, 'The embryo with 8 to 16 blastomeres is called _', NULL, '[{"text":"Morula","image_url":null,"alt":null},{"text":"Blastula","image_url":null,"alt":null},{"text":"Zygote","image_url":null,"alt":null},{"text":"Foetus","image_url":null,"alt":null}]', NULL, 0, 'Blastula is the hollow sphere of blastomeres, produced due to repeated cleavage. zygote is single celled structure formed due to fusion of male and female gametes. Foetus is the unborn offspring.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.111Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3695, 6, NULL, NULL, 'The species that invades a bare area is called _', NULL, '[{"text":"Serial stage","image_url":null,"alt":null},{"text":"Allien species","image_url":null,"alt":null},{"text":"Endemic species","image_url":null,"alt":null},{"text":"Pioneer species","image_url":null,"alt":null}]', NULL, 3, 'Pioneer species are the first species to populate a barren or devastated environment. E.g. a volcanic eruption burns an island clean of life, or causes a new island consisting of bare volcanic rock to emerge.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.112Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3696, 6, NULL, NULL, 'Mr. X wants to start Bee-keeping. Important points for successful bee-keeping are _.

A. Selection of suitable location for keeping beehives

B. Beehives can be kept in fruit orchards

C. Catching and hiving of swarms

D. Management of beehives during rainy season

E. Regular visit by veterinary doctor is mandatory', NULL, '[{"text":"A, B, C and E","image_url":null,"alt":null},{"text":"A, B and C","image_url":null,"alt":null},{"text":"A, B, D and E","image_url":null,"alt":null},{"text":"A, C, D and E","image_url":null,"alt":null}]', NULL, 1, 'Successful bee-keeping requirements are as follows:

(i) Knowledge of the nature and habits of bees,

(ii) Selection of suitable location for keeping the beehives

(iii) Catching and hiving of swarms

(iv) Management of beehives during different seasons, and

(v) Handling and collection of honey and of beeswax.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.113Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3697, 6, NULL, NULL, 'Given below are two statements; one is labelled as assertion A and other is labelled as Reason R

Assertion (A): In gel-electrophoresis, DNA fragments are separated.

Reason (R): DNA is negatively charged, so it moves towards the cathode under the influence of electric field.

In the light of the above sentences, choose the correct answer from the options given below', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true and R is not the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 2, 'In this question, assertion is correct but reason is not correct. DNA is a negatively charged molecule, hence it moves towards the positive electrode (anode).

The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.114Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3698, 6, NULL, NULL, 'Identify the drug shown below in the diagram', NULL, '[{"text":"Cocaine","image_url":null,"alt":null},{"text":"Heroin","image_url":null,"alt":null},{"text":"Cannabinoid","image_url":null,"alt":null},{"text":"Morphine","image_url":null,"alt":null}]', NULL, 3, 'The given structure is of morphine.

Morphine belongs to a class of drugs known as opioid analgesics.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-20/q33-figure-1.jpg', 'Figure for question 33', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.115Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-20/q33-figure-1.jpg","alt":"Figure for question 33","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3699, 6, NULL, NULL, 'Which of the following does not show ecological diversity?', NULL, '[{"text":"Coral reef","image_url":null,"alt":null},{"text":"Alpine meadows","image_url":null,"alt":null},{"text":"Wetlands","image_url":null,"alt":null},{"text":"Rauwolfia vomitoria","image_url":null,"alt":null}]', NULL, 3, 'Coral reef, alpine meadows, deserts, wetlands, mangrove etc., are examples of ecological diversity whereas Rauwolfia vomitoria shows genetic diversity. Hence, option d is not correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.115Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3700, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-1, B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-II, B-III, C-IV, D-I","image_url":null,"alt":null},{"text":"A-II, B-IV, C-III, D-I","image_url":null,"alt":null},{"text":"A-III, B-II, C-IV, D-I","image_url":null,"alt":null}]', NULL, 1, 'The correct matching will be:

Haemophilia is sex-linked recessive disorder.

Phenylketonuria is an autosomal recessive disorder.

Down''s syndrome is trisomy of chromosome number 21.

Turner''s syndrome is monosomy of X-chromosome.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-20/q35-table-1.jpg', 'Table for question 35', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.116Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-20/q35-table-1.jpg","alt":"Table for question 35","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3701, 6, NULL, NULL, 'The first restriction endonuclease isolated was', NULL, '[{"text":"Eco RI","image_url":null,"alt":null},{"text":"pBR 322","image_url":null,"alt":null},{"text":"Hind II","image_url":null,"alt":null},{"text":"Bam HI","image_url":null,"alt":null}]', NULL, 2, 'The first restriction nuclease characterized was isolated from Haemophilus influenzae bacteria and known as Hind II.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.116Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3702, 6, NULL, NULL, 'Which of the following are true, caused due to Inbreeding depression?

A. Reduces fertility and productivity

B. Helps in accumulation of inferior genes

C. Helps to evolve a hybrid in any animal

D. Increases productivity inbreed population

E. Retention of less desirable genes.', NULL, '[{"text":"B and C only","image_url":null,"alt":null},{"text":"A and D only","image_url":null,"alt":null},{"text":"C and E only","image_url":null,"alt":null},{"text":"B and E only","image_url":null,"alt":null}]', NULL, 1, 'The mating between the relatives in a small population is common and this may lower the population''s ability to persist and reproduce which is referred to as inbreeding depression. Inbreeding depression usually reduces fertility and productivity. Inbreeding helps in accumulation of superior genes and elimination of less desirable genes. Inbreeding depression does not play any role in development of hybrid.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.116Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3703, 6, NULL, NULL, 'Select the correct statements from the following

A. The presence of Thymine at the place of Uracil gives more stability to DNA

B. Both nucleic acids, i.e., DNA and RNA mutate

C. DNA is dependent on RNA for synthesis of proteins

D. RNA mutate at slower rate than DNA

E. DNA is better genetic material', NULL, '[{"text":"A and D only","image_url":null,"alt":null},{"text":"A and B only","image_url":null,"alt":null},{"text":"A, B, C and D only","image_url":null,"alt":null},{"text":"A, B, C and E only","image_url":null,"alt":null}]', NULL, 3, 'One incorrect statement is that RNA mutate at high rate than DNA because it is highly unstable. Rest other statements are correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.117Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3704, 6, NULL, NULL, 'Mr. X had purchased a fruit juice bottle from the market and is puzzled to see that is completely clear. It is due to', NULL, '[{"text":"Lipase and Pectinase","image_url":null,"alt":null},{"text":"Amylase and Polymerase","image_url":null,"alt":null},{"text":"Pectinase and Protease","image_url":null,"alt":null},{"text":"Protease and Ligase","image_url":null,"alt":null}]', NULL, 2, 'The enzymes pectinases and proteases help in clarifying fruit juices making them clearer as compared to those made at home. Lipases are used in detergent formulations and are helpful in removing oily stains from laundry. Amylase degrades starch.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.118Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3705, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-1, B-III, C-II, D-IV","image_url":null,"alt":null},{"text":"A-I, B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-II, B-I, C-III, D-IV","image_url":null,"alt":null},{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null}]', NULL, 3, 'Pollination is the act of transferring pollen grains from the male anther of a flower to the female stigma. The goal of every living organism, including plants, is to create offspring for the next generation. Wind pollination is quite common in grasses. Marine seagrass Zostera is a water-pollinated plant.

Among the animals, insects, particularly bees are dominant biotic pollinating agents.

The tallest flower Amorphophallus is about 6 feet in height.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-20/q41-table-1.jpg', 'Table for question 41', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.118Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-20/q41-table-1.jpg","alt":"Table for question 41","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3706, 6, NULL, NULL, 'Yucca plant shows _', NULL, '[{"text":"Flower with non-sticky pollen grains","image_url":null,"alt":null},{"text":"Water pollination","image_url":null,"alt":null},{"text":"Large feather stigma","image_url":null,"alt":null},{"text":"Moth is partner to complete life cycles","image_url":null,"alt":null}]', NULL, 3, 'For more than 40 million years there has been a relationship between yucca plants and yucca moths. It''s a particularly important one because neither the yucca or the moth can survive without the other. The moth''s larvae depend on the seeds of the yucca plant for food, and the yucca plant can only be pollinated by the yucca moth.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.118Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3707, 6, NULL, NULL, '_ is aquatic plant showing insect pollination', NULL, '[{"text":"Hydrilla","image_url":null,"alt":null},{"text":"Vallisneria","image_url":null,"alt":null},{"text":"Zostera","image_url":null,"alt":null},{"text":"Water hyacinth","image_url":null,"alt":null}]', NULL, 3, 'In a majority of aquatic plants like water hyacinth and water lily, the flowers emerge above the water level and are pollinated by insects or wind as in most of the land plants.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.119Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3708, 6, NULL, NULL, 'Which of the following is NOT a feature of insect pollinated plant?', NULL, '[{"text":"Light and non-sticky pollen grains","image_url":null,"alt":null},{"text":"Flowers are large and colourful","image_url":null,"alt":null},{"text":"Presence of nectar","image_url":null,"alt":null},{"text":"Flower with fragrance","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.119Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3709, 6, NULL, NULL, 'Grasses show pollination by', NULL, '[{"text":"Water","image_url":null,"alt":null},{"text":"Insect","image_url":null,"alt":null},{"text":"Wind","image_url":null,"alt":null},{"text":"Animals PASSAGE Read the sentence and answer the questions. The process of replication requires a set of catalyst (enzymes). The main enzyme is referred to as DNA dependent DNA Polymerase. E.coli that has only $4.6 \\times 10^{6}$ bp (compare it with human whose diploid content is $6.6 \\times 10^{6}$ bp), completes the process of replication within 18 minutes, that means the average rate of polymerisation has to be approximately 2000 bp per second these polymerase also have catalase the reaction with high degree of accuracy. Deoxyribonucleoside Triphosphates serve dual purposes. In addition to DNA dependent DNA polymerases, many additional enzymes are required to complete the process of replication with high degree of accuracy. For long DNA molecules, since the two strands of DNA cannot be separated in its entire length (due to very high energy requirement), the replication occur with in a small opening of the DNA helix, referred to as replication fork. The DNA-dependent DNA polymerase catalyse polymerisation only in one direction, that $5^{\\prime}-3^{\\prime}$. This creates some additional complications at the replicating fork. Consequently, on one strand (the template with polarity $3^{\\prime}-5^{\\prime}$) the replication is continuous, which on the others (the template with polarity $5^{\\prime}-3^{\\prime}$), it is the discontinuous. The non-continuously synthesized fragments are later joined by the enzyme DNA ligase.","image_url":null,"alt":null}]', NULL, 2, 'Majority of insect pollinated flowers are large, colourful, fragrant and rich in nectar. So, option B, C and D are correct. Characteristics of wind pollinated flowers are: Well exposed stamens. Produce large number of pollens.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3710, 6, NULL, NULL, 'The DNA dependent-DNA polymerase catalyser is a DNA polymerase in one direction only that is _', NULL, '[{"text":"5''-3'' of DNA","image_url":null,"alt":null},{"text":"3''-5'' of DNA","image_url":null,"alt":null},{"text":"5''-3'' of RNA","image_url":null,"alt":null},{"text":"3''-5'' of RNA","image_url":null,"alt":null}]', NULL, 0, 'The DNA dependent DNA polymerase catalyse polymerisation only in one direction that is $5^{\prime}\rightarrow3^{\prime}$ of DNA.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3711, 6, NULL, NULL, 'In human beings DNA polymerase complete the process of replication in _', NULL, '[{"text":"25 Minutes","image_url":null,"alt":null},{"text":"16 Minutes","image_url":null,"alt":null},{"text":"12 Minutes","image_url":null,"alt":null},{"text":"18 Minutes","image_url":null,"alt":null}]', NULL, 3, 'The main enzyme of DNA replication is referred to as DNA dependent DNA polymerase which completes the process of replication within 18 minutes.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3712, 6, NULL, NULL, 'The number of nucleotides in E. coli is _', NULL, '[{"text":"$ 1.2 \\times 10^{6} $ bp","image_url":null,"alt":null},{"text":"$ 2.3 \\times 10^{6} $ bp","image_url":null,"alt":null},{"text":"$ 4.6 \\times 10^{6} $ bp","image_url":null,"alt":null},{"text":"$ 6.6 \\times 10^{6} $ bp","image_url":null,"alt":null}]', NULL, 2, 'The length of DNA is usually defined as number of nucleotides or base pairs present in it.

The number of nucleotide in $ E.coli $ is $ 4.6 \times 10^{6} $ bp.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.121Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3713, 6, NULL, NULL, 'In E. coli the main enzyme required to catalyze the polymerisation of deoxynucleotide is _', NULL, '[{"text":"DNA-Dependent DNA Polymerase","image_url":null,"alt":null},{"text":"DNA-Dependent RNA Polymerase","image_url":null,"alt":null},{"text":"RNA-Dependent DNA Polymerase","image_url":null,"alt":null},{"text":"RNA-Dependent DNA Polymerase","image_url":null,"alt":null}]', NULL, 0, 'The main enzyme for polymerisation of DNA is referred to as DNA dependent DNA polymerases, since it uses a DNA template to catalyse the polymerisation of deoxyribonucleotides.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.121Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3714, 6, NULL, NULL, 'Which of the following statements are correct?

A. DNA dependent DNA polymerase is a slow catalyst

B. Deoxyribonucleoside triphosphate provide energy for polymerisation

C. Replication fork is a small opening of the DNA helix

D. The replication is discontinuous on DNA template with polarity 3''-5''

E. The replication is continuous on DNA template with polarity 3''-5''', NULL, '[{"text":"A and B only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"A and D only","image_url":null,"alt":null},{"text":"C and E only","image_url":null,"alt":null}]', NULL, 1, 'Average rate of polymerisation of The enzyme DNA dependent DNA polymerase is approximately 2000 bp per second with high degree of accuracy. Hence it is a fast catalyst.

- Deoxyribonucleoside triphosphates provide energy for polymerisation because its two terminal phosphates are high energy phosphate same as in case of ATP.

Replication occurs with a small opening of the DNA helix, referred to as replication fork.

- The replication is continuous on the template strand with polarity 3''->5 while on the other strand replication is discontinuous with polarity 5''->3''

As per NTA option (B) is correct however as per NCERT, statements (B), (C) and (E) are correct but none of the option includes all three statements that are (B), (C) and (E).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.122Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3715, 6, NULL, NULL, 'Select the statements that are CORRECT regarding patterns of biodiversity.(A) Species diversity increases as we move away from the equator towards the poles(B) The tropical Amazon rain forest in South America has the greatest biodiversity on earth.(C) There is more solar energy available in the temperate region than tropics.(D) Tropical environments are less seasonal relatively more constant and predictable(E) A. Humboldt observed that within a region, species richness decreases with increasing explored area, up to a limit.Choose the correct answer from the options given below:', NULL, '[{"text":"(A) and (E) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(B) and (D) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.123Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
