INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3754, 6, NULL, NULL, 'Read the following passage and answer the question :\nThe primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinary.
located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT). The primary lymphoid organ is .', NULL, '[{"text":"Lymph nodes","image_url":null,"alt":null},{"text":"Bone marrow","image_url":null,"alt":null},{"text":"Tonsils","image_url":null,"alt":null},{"text":"Spleen","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.150Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
