INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3757, 6, NULL, NULL, 'Read the following passage and answer the question :\nThe primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT).\nMucous associated lymphoid tissue (MALT) is NOT found in :\n', NULL, '[{"text":"Urinogenital tract\\n","image_url":null,"alt":null},{"text":"Digestive tract\\n","image_url":null,"alt":null},{"text":"Tonsils\\n","image_url":null,"alt":null},{"text":"Respiratory tract","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.151Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3758, 6, NULL, NULL, 'Read the following passage and answer the question :The primary lymphoid organs are bone marrow and thymus. Where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT). Which of the following is incorrect statement. (A) All blood cells including lymphocytes are produced in bone marrow (B) Lymph nodes are small solid structures located at different points along lymphatic system (C) Payer''s patches of small intestine is primary lymphoid organ. (D) Antigen trapped in lymph node are responsible for activation of lymphocytes present in lymph node and causes immune response (D) (A) only (B) and (D) onlyChoose the correct answer from the options given below :', NULL, '[{"text":"(C) only","image_url":null,"alt":null},{"text":"(B) only","image_url":null,"alt":null},{"text":"(A) only","image_url":null,"alt":null},{"text":"(D) only","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.151Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3759, 6, NULL, NULL, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to
Fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel.\nThe separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors.\nAgarose is extracted from .\n', NULL, '[{"text":"Bacteria\\n","image_url":null,"alt":null},{"text":"Marine animals\\n","image_url":null,"alt":null},{"text":"Sea weeds\\n","image_url":null,"alt":null},{"text":"Fungi","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.152Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3760, 6, NULL, NULL, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel.\nThe separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors.\nWhat is elution ?\n', NULL, '[{"text":"It is movement of negatively charged DNA fragments through agarose gel.\\n","image_url":null,"alt":null},{"text":"Extraction of DNA from the host\\n","image_url":null,"alt":null},{"text":"Extraction of DNA and treatment with restriction endonuclease\\n","image_url":null,"alt":null},{"text":"Cutting of separated DNA fragments from agarose gel and extraction of DNA fragment","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.152Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3761, 6, NULL, NULL, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther from the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The DNA fragments formed by treatment with endonuclease are separated by .', NULL, '[{"text":"PCR","image_url":null,"alt":null},{"text":"Gel Electrophoresis","image_url":null,"alt":null},{"text":"Cloning","image_url":null,"alt":null},{"text":"Restriction digestion","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.153Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3762, 6, NULL, NULL, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther from the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA
can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The separated DNA fragments can be visualised after staining with _, followed by exposure to _.', NULL, '[{"text":"$ \\beta $-galactosidase, UV radiation","image_url":null,"alt":null},{"text":"$ \\beta $-galactosidase, Gamma radiation","image_url":null,"alt":null},{"text":"Ethidium bromide, UV radiation","image_url":null,"alt":null},{"text":"Ethidium bromide, Gamma radiation","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.154Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3763, 6, NULL, NULL, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The fragments of DNA separate on agarose gel, based on the .', NULL, '[{"text":"Size of fragments","image_url":null,"alt":null},{"text":"Charge of each fragment","image_url":null,"alt":null},{"text":"Colour of fragment","image_url":null,"alt":null},{"text":"Type of DNA","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.154Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3764, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I,B-IV,C-III,D-II","image_url":null,"alt":null},{"text":"A-II,B-I,C-IV,D-III","image_url":null,"alt":null},{"text":"A-III,B-IV,C-I,D-II","image_url":null,"alt":null},{"text":"A-IV,B-II,C-III,D-I","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is the correct answer because skin in our body is the main physical barrier which prevents entry of the micro-organisms. Natural killer cells are the cellular barriers of innate immunity. Tears from eyes comes under the category of physiological barriers. Virus infected cells secrete proteins called interferons which protect non-infected cells from further viral infection. It comes under cytokine barrier.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q02-table-1.jpg', 'Table for question 2', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.156Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q02-table-1.jpg","alt":"Table for question 2","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3765, 6, NULL, NULL, 'A couple is unable to produce a child as the male partner has low sperm count. Infertility caused by this condition can be treated using', NULL, '[{"text":"ZIFT","image_url":null,"alt":null},{"text":"AI","image_url":null,"alt":null},{"text":"GIFT","image_url":null,"alt":null},{"text":"IUT","image_url":null,"alt":null}]', NULL, 1, 'Option (B) is the correct answer as infertility cases either due to inability of the male partner to inseminate the female or due to very low sperm count in the ejaculate, could be corrected by artificial insemination. After IVF, the zygote or early embryo (upto 8 blastomeres) could then be transferred into the fallopian tube i.e. ZIFT and embryo with more than 8 blastomeres is transferred into the uterus (IUT). Option (C) is not the answer as GIFT stands for Gamete Intra Fallopian Transfer.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.157Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3766, 6, NULL, NULL, 'Which of these are the carriers of male gametes in some seed plants?', NULL, '[{"text":"Microspore mother cells","image_url":null,"alt":null},{"text":"Pollen Grains","image_url":null,"alt":null},{"text":"Anthers","image_url":null,"alt":null},{"text":"Megaspore mother cells","image_url":null,"alt":null}]', NULL, 1, 'Pollen grains represent male gametophyte in seed plants. It carries the male gametes which can be transferred to the female gamete via pollination.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.157Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3767, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-IV, B-III, C-I, D-II","image_url":null,"alt":null},{"text":"A-III, B-II, C-I, D-IV","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null}]', NULL, 1, 'Option (B) is the correct answer as the causative agents of malaria, pneumonia, typhoid and filariasis are Plasmodium (protozoa), Haemophilus (bacteria), Salmonella typhi (bacteria) and Wuchereria (nematode) respectively.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q05-table-1.jpg', 'Table for question 5', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.158Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q05-table-1.jpg","alt":"Table for question 5","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3768, 6, NULL, NULL, 'Arrange the following steps in order for the technique of DNA finger printing.

A. Isolation of DNA.

B. Separation of DNA fragments by gel, electrophoresis.

C. Digestion of DNA by restriction endonucleases.

D. Blotting of separated DNA fragments to nylon membrane.

E. Hybridisation using VNTR probe followed by autoradiography.', NULL, '[{"text":"A,C,B,D,E","image_url":null,"alt":null},{"text":"A,B,C,D,E","image_url":null,"alt":null},{"text":"A,B,D,C,E","image_url":null,"alt":null},{"text":"A,E,C,B,D","image_url":null,"alt":null}]', NULL, 0, 'DNA fingerprinting involves following steps:

A. Isolation of DNA.

C. Digestion of DNA by restriction endonucleases.

B. Separation of DNA fragments by gel electrophoresis.

D. Blotting of separated DNA fragments to nylon membrane.

E. Hybridisation using VNTR probe followed by autoradiography.

So the correct order is A, C, B, D, E.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.159Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3769, 6, NULL, NULL, 'Long term use of alcohol specially causes-', NULL, '[{"text":"Liver cirrhosis","image_url":null,"alt":null},{"text":"Arthritis","image_url":null,"alt":null},{"text":"Pulmonary system damage","image_url":null,"alt":null},{"text":"Premature baldness","image_url":null,"alt":null}]', NULL, 0, 'Option (A) is the correct answer because the chronic use of drugs and alcohol damages nervous system and liver (alcoholic cirrhosis).

Option (B) is not the answer as, arthritis is defined as the inflammation of joints.

Option (C) is not the answer as pulmonary system damage is associated with smoking tobacco or other forms of air pollutants.

Option (D) is not the answer as premature baldness can occur due to deficiency of biotin or growth hormone deficiency.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.159Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3770, 6, NULL, NULL, 'Select the appropriate options with reference to post fertilisation changes in angiosperms.

A. Inner integument of ovule develops into tegmen.

B. Ovary wall forms pericarp

C. Ovule forms fruit

D. Zygote forms endosperm

E. Outer integument of ovule develops into Testa


Choose the correct answer from the options given below:

(a) B, E only (b) A, B, E only

(c) C, D, B only (d) A, C, B only

The part of the human sperm that helps in the fertilisation of the ovum is a cap-like structure called', NULL, '[{"text":"Head","image_url":null,"alt":null},{"text":"Acrosome","image_url":null,"alt":null},{"text":"Middle piece","image_url":null,"alt":null},{"text":"Tail","image_url":null,"alt":null}]', NULL, 1, 'Post fertilization events in angiosperms include-

• Formation of endosperm from primary endosperm cell.

• Formation of embryo from zygote

• Formation of seed from ovule

• During seed formation, integuments develops into seed coats. Outer integument forms testa (outer seed coat) while inner integument forms tegmen (inner seed coat).

- Formation of pericarp from ovary wall.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.161Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3771, 6, NULL, NULL, 'Rearrange the events of life cycle of a retrovirus.

A. New viral RNA produced by infected cell

B. Reverse transcription

C. New virus particles inject into other cells

D. Viral RNA introduced into the cell

E. Viral DNA incorporates into host genome', NULL, '[{"text":"A, B, D, E, C","image_url":null,"alt":null},{"text":"B, E, D, A, C","image_url":null,"alt":null},{"text":"C, A, B, D, E","image_url":null,"alt":null},{"text":"D, B, E, A, C","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is correct answer because the steps for HIV in host is as follows:

D - Viral RNA is introduced into the cell.

B - Enzyme reverse transcriptase acts on viral RNA.

E - Viral DNA produced is incorporated into the host genome.

A - New viral RNA is produced by infected cell.

C - New virus particles inject into other cells.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.163Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3772, 6, NULL, NULL, 'Secondary treatment of sewage involves', NULL, '[{"text":"Physical removal of large and small particles from sewage through filtration","image_url":null,"alt":null},{"text":"Anaerobic sludge digestion","image_url":null,"alt":null},{"text":"Sedimentation to remove smaller and larger particles","image_url":null,"alt":null},{"text":"Mechanical agitation coupled with addition of aerobic microbes","image_url":null,"alt":null}]', NULL, 3, 'Sewage treatment consists of two stages

1. Primary treatment - Removes particles through filtration and sedimentation

2. Secondary treatment/ Biological treatment-Primary effluent is treated with aerobic microbes in an aerobic tank. During the process the medium is agitated continuously for proper mixing and aeration.

Once the organic content is degraded mostly, the effluent is allowed to sediment in settling tank where the sediment formed is called Activated sludge.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.164Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3773, 6, NULL, NULL, 'Given below two statements: one is labelled as assertion A and the other is labelled as Reason R

Assertion A: In F2 generation of a Mendelian cross, the traits seen in the progeny are identical to their parents.

Reason R: The progeny of the F2 generation in a Mendelian cross shows no blending of traits.

In the light of the above statements, chose the most appropriate answer from the options given below:', NULL, '[{"text":"Both A and R are correct and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are correct but R is NOT the correct explanation of A","image_url":null,"alt":null},{"text":"A is correct but R is not correct","image_url":null,"alt":null},{"text":"A is not correct but R is correct","image_url":null,"alt":null}]', NULL, 0, 'In monohybrid Mendelian cross, F1 generation shows phenotype of only one parent while F2 generation has progenies expressing phenotype of both parents.

This observation was possible because there is no blending of traits occur. This also led to the conclusion that traits are governed by discrete units.

Both A and R are correct and R is the correct explanation of A.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.166Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3774, 6, NULL, NULL, 'In flowering plants, the egg apparatus consists of:', NULL, '[{"text":"Three antipodals and one egg cell","image_url":null,"alt":null},{"text":"Two synergids and one central cell","image_url":null,"alt":null},{"text":"Two synergids and one egg cell","image_url":null,"alt":null},{"text":"Three antipodals and two synergids","image_url":null,"alt":null}]', NULL, 2, 'Embryo sac, the female gametophyte of angiosperm is 8-nucleated 7-celled. It includes-

1. Egg apparatus $ \rightarrow $ with one egg and two synergids

2. Central cell with 2 polar nuclei

3. Three antipodals', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.167Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3775, 6, NULL, NULL, 'Layers surrounding the ovum from outside to inside are

A. Zona pellucida

B. Vitelline membrane

C. Corona radiata', NULL, '[{"text":"A, C, B","image_url":null,"alt":null},{"text":"C, B, A","image_url":null,"alt":null},{"text":"C, A, B","image_url":null,"alt":null},{"text":"A, B, C","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer, because', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.167Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3776, 6, NULL, NULL, 'The term ribosome is applicable to the following molecule in bacteria', NULL, '[{"text":"mRNA","image_url":null,"alt":null},{"text":"23S rRNA","image_url":null,"alt":null},{"text":"5S rRNA","image_url":null,"alt":null},{"text":"hn RNA","image_url":null,"alt":null}]', NULL, 1, 'In prokaryotes, the larger subunit of ribosome consists of 23S and 5S rRNA. In eukaryotes, the larger subunit of ribosome has 28S, 5.8S and 5S rRNA. Hence term ribosome is applicable to 23S rRNA in bacteria. mRNA is synthesised by transcription in both prokaryotes and eukaryotes.

hnRNA is the precursor of mRNA in eukaryotes.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.168Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3777, 6, NULL, NULL, 'After an HIV infection, the body of the patient starts becoming immunodeficient mainly due to :', NULL, '[{"text":"The damage caused to secondary lymphoid organs","image_url":null,"alt":null},{"text":"Rapid multiplication of the virus outside the host cells","image_url":null,"alt":null},{"text":"Progressive decline in the number of helper T-lymphocytes","image_url":null,"alt":null},{"text":"Infection by a number of pathogens","image_url":null,"alt":null}]', NULL, 2, 'Option C is the correct answer as

T-helper cells stimulate B-cells to produce antibodies and induce killer-T-cells to destroy the non-self cells (foreign cells).

In HIV infection, due to decrease in the number of helper T-cells, the person starts suffering from opportunistic infections due to decrease in immunity.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.168Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3778, 6, NULL, NULL, 'Bioactive molecules like statins are produced by :', NULL, '[{"text":"Trichoderma polysporum","image_url":null,"alt":null},{"text":"Monascus purpureus","image_url":null,"alt":null},{"text":"Acetobacter aceti","image_url":null,"alt":null},{"text":"Streptococcus","image_url":null,"alt":null}]', NULL, 1, 'Bioactive molecules like statins are produced by the yeast Monascus purpureus.

Trichodermapolysporum produces an immunosuppressive agent cyclosporin A.

Acetobacter aceti produces acetic acid.

Streptococcus produces the clot buster enzyme streptokinase.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.169Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3779, 6, NULL, NULL, 'The haplodiploid sex-determination system where all the males of the population are haploid and females are diploid, is seen in', NULL, '[{"text":"Drosophila","image_url":null,"alt":null},{"text":"Honey bees","image_url":null,"alt":null},{"text":"Birds","image_url":null,"alt":null},{"text":"Grasshoppers","image_url":null,"alt":null}]', NULL, 1, 'The haplo-diploid sex determination system is seen in honey bees. In honeybee males have half the number of chromosomes than that of females.

In Drosophila and grasshopper, male heterogamety is seen.

In birds, female heterogamety is seen.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.169Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3780, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I, B-II, C-III, D-IV","image_url":null,"alt":null},{"text":"A-III, B-1, C-II, D-IV","image_url":null,"alt":null},{"text":"A-I, B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is the correct answer because

• Genetic drift is defined as sudden change in gene frequency by chance.

• In stabilising selection, more individuals acquire mean character value.

• Gene flow is the change in allele frequency due to immigration and emigration.

Saltation is the single step large mutation.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q20-table-1.jpg', 'Table for question 20', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.170Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q20-table-1.jpg","alt":"Table for question 20","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3781, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A - II, B - III, C - IV, D - I","image_url":null,"alt":null},{"text":"A-I, B-II, C-III, D-IV","image_url":null,"alt":null},{"text":"A-III, B-I, C-IV, D-II","image_url":null,"alt":null},{"text":"A-IV, B-II, C-III, D-I","image_url":null,"alt":null}]', NULL, 2, 'The crop bred by hybridisation and selection for particular disease resistance are as follows

Cowpea - Bacterial blight

Chilli - Tobacco mosaic virus

Brassica - White rust

Wheat - Leaf and stripe rust

Therefore, the correct answer is option C', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q21-table-1.jpg', 'Table for question 21', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.170Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q21-table-1.jpg","alt":"Table for question 21","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3782, 6, NULL, NULL, 'What happened when heat-killed S cells along with live R cells were injected into mice in Griffith''s experiment?', NULL, '[{"text":"Mice died and showed live R cells in the blood","image_url":null,"alt":null},{"text":"Mice survived and showed live S cells in the blood","image_url":null,"alt":null},{"text":"Mice died and showed live S cells in the blood","image_url":null,"alt":null},{"text":"Mice survived and showed live R cells in the blood","image_url":null,"alt":null}]', NULL, 2, 'When Griffith injected a mixture of heat-killed S cells and live R cells, the mice died. Moreover, he recovered living S-bacteria from the dead mice. He concluded that the R-strain bacteria had somehow been transformed by the heat-killed S-strain bacteria.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.170Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3783, 6, NULL, NULL, 'Autotrophic microbe for fixing atmospheric nitrogen:', NULL, '[{"text":"Rhizobium","image_url":null,"alt":null},{"text":"Aspergillus","image_url":null,"alt":null},{"text":"Oscillatoria","image_url":null,"alt":null},{"text":"Trichoderma","image_url":null,"alt":null}]', NULL, 2, 'Cyanobacteria are autotrophic microbes widely distributed in aquatic and terrestrial environment many of which can fix atmospheric nitrogen.

e.g. Anabaena, Nostoc, Oscillatoria

Trichoderma and Aspergillus are fungi

Rhizobium is heterotrophic bacteria, as symbiont, can fix atmospheric nitrogen.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3784, 6, NULL, NULL, 'In humans females at the time of birth, the stage of cell cycle of oocyte is', NULL, '[{"text":"Prophase-I","image_url":null,"alt":null},{"text":"Prophase-II","image_url":null,"alt":null},{"text":"Meiosis-II","image_url":null,"alt":null},{"text":"Mitosis","image_url":null,"alt":null}]', NULL, 0, 'Option (A) is the correct answer because oogonia start division during fetal life and enter into prophase-I of the meiotic division and get temporarily arrested at that stage called primary oocytes. So, at the time of birth, the stage of cell cycle of oocyte is prophase-I.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3785, 6, NULL, NULL, 'Calotropis, a weed growing in abandoned fields, produces one of the following biochemicals as a defense against grazers and browsers-', NULL, '[{"text":"Nicotine","image_url":null,"alt":null},{"text":"Opium","image_url":null,"alt":null},{"text":"Cardiac glycosides","image_url":null,"alt":null},{"text":"Strychnine","image_url":null,"alt":null}]', NULL, 2, 'Calotropis, a weed growing in abandoned field produces highly poisonous cardiac glycosides as a defense against grazers and browsers.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.172Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3786, 6, NULL, NULL, 'Calculate the birth rate if there were 60 sparrows in a garden last year and through reproduction 24 new sparrows are added this year', NULL, '[{"text":"0.4 offsprings per sparrow per year","image_url":null,"alt":null},{"text":"0.2 offsprings per sparrow per year","image_url":null,"alt":null},{"text":"0.6 offsprings per sparrow per year","image_url":null,"alt":null},{"text":"0.1 offsprings per sparrow per year","image_url":null,"alt":null}]', NULL, 0, 'Birth rate = $ \frac{\Delta N}{N\Delta t} = \frac{24}{60} = 0.4 $

If there were 60 sparrows in a garden last year and through reproduction 24 new sparrows are added this year, then birth rate is 0.4 offspring per sparrow per year.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.172Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3787, 6, NULL, NULL, 'Totipotency can be defined as', NULL, '[{"text":"Capacity to generate whole plant from any cell/ex-plant","image_url":null,"alt":null},{"text":"Capacity to survive in unfavourable environment condition","image_url":null,"alt":null},{"text":"Ability to conduct water in 100 meter tall tree","image_url":null,"alt":null},{"text":"The duration of dormancy of seeds and other propagules in angiosperms","image_url":null,"alt":null}]', NULL, 0, 'The capacity to generate whole plant from any cell/explant is called totipotency.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.173Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3788, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-III, B-IV, C-I, D-II","image_url":null,"alt":null},{"text":"A-I, B-III, C-II, D-IV","image_url":null,"alt":null},{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null},{"text":"A-III, B-II, C-I, D-IV","image_url":null,"alt":null}]', NULL, 0, '- Fig species can be pollinated only by its partner wasp species. So it shows mutual relationship.

• Koel and crow show brood parasitism in which parasitic bird lays its eggs in the nest of its host and let the host incubate them.

• Balanus dominates the intertidal areas and excludes the smaller barnacle Chathamalus from the zone so shows competition.

The egret and grazing cattle shows commensalism. The egrets always forage close to where the cattle are grazing.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q28-table-1.jpg', 'Table for question 28', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.173Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q28-table-1.jpg","alt":"Table for question 28","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3789, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-Ⅱ, B-Ⅰ, C-Ⅳ, D-Ⅲ","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null},{"text":"A-I, B-IV, C-II, D-III","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer because

• Sex determination is illegally done by amniocentesis so, there is ban on it in India.

- Withdrawal method of contraception is also known as coitus interrupts in which the male partner withdraws his penis from the vagina just before ejaculation.

Vault is a barrier method of contraception.

Syphilis is a venereal or sexually transmitted bacterial disease.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q29-table-1.jpg', 'Table for question 29', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.174Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q29-table-1.jpg","alt":"Table for question 29","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3790, 6, NULL, NULL, 'Restriction endonucleases are used as molecular', NULL, '[{"text":"molecular build up at nucleotides","image_url":null,"alt":null},{"text":"molecular cement to join DNA sites","image_url":null,"alt":null},{"text":"molecular knife cut DNA at specific site","image_url":null,"alt":null},{"text":"molecular degradation to break up the DNA to nucleotides","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer because restriction endonucleases are commonly known as molecular scissors. Each restriction endonuclease inspects the length of a DNA sequence, finds its specific palindromic nucleotide sequence and cut each of the two strands of the double helix at this specific points in their sugar-phosphate backbone.

DNA ligase works as molecular glue to join up the DNA', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.175Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3791, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-III, B-I, C-IV, D-II","image_url":null,"alt":null},{"text":"A-III, B-IV, C-II, D-I","image_url":null,"alt":null},{"text":"A-I, B-II, C-III, D-IV","image_url":null,"alt":null}]', NULL, 1, 'The ''i'' gene codes for the repressor protein of the lac operon.

The ''z'' gene codes for beta galactosidase which is primarily responsible for hydrolysis of disaccharide.

The ''y'' gene codes for pemease which increases permeability of the cell to b-galactosidase.

''a'' gene encodes transacetylase.

So, A-III, B-I, C-IV, D-II.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q32-table-1.jpg', 'Table for question 32', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.175Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q32-table-1.jpg","alt":"Table for question 32","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3792, 6, NULL, NULL, 'Cohen and Boyer created the first recombinant DNA using plasmid of', NULL, '[{"text":"Escherichia coli","image_url":null,"alt":null},{"text":"Thermus aquaticus","image_url":null,"alt":null},{"text":"Salmonella typhimurium","image_url":null,"alt":null},{"text":"Bacillus thuringiensis","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer because Stanley Cohen and Herbert Boyer created the first recombinant DNA using a native plasmid of Salmonella typhimurium. This recombinant DNA was then transferred into Escherichia coli.

Thermus aquaticus is a thermostable bacterium whose enzymes are used in PCR.

Bacillus thuringiensis is used to make Bt cotton (pest-resistant crop).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.179Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3793, 6, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null},{"text":"A-I, B-IV, C-III, D-II","image_url":null,"alt":null},{"text":"A-IV, B-III, C-II, D-I","image_url":null,"alt":null},{"text":"A-III, B-IV, C-II, D-I","image_url":null,"alt":null}]', NULL, 2, '- When exhaust passes through the catalytic converter, carbon monoxide and nitric oxide are changed to carbon dioxide and water.

• Electrostatic precipitator can remove over 99% particulate matter present in the exhaust from the thermal power plant.

• High noise level in an area is eliminated by using earmuffs

Solid wastes are trashed in a depression or trench considered as landfills.', NULL, NULL, 2022, '/local-papers/assets/biology-2022-08-30/q34-table-1.jpg', 'Table for question 34', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.180Z', NULL, NULL, '[{"url":"/local-papers/assets/biology-2022-08-30/q34-table-1.jpg","alt":"Table for question 34","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3794, 6, NULL, NULL, 'Identify the correct statements

A. Oogenesis is initiated at puberty

B. Second meiotic division in secondary oocyte occurs in the ovary

C. Middle piece of sperm provides energy for movement

D. Fertilization of gametes occurs in the ampulla isthmic region of oviduct

E. Myometrium helps in muscular contractions of the uterus', NULL, '[{"text":"A, D, E only","image_url":null,"alt":null},{"text":"A, B, D only","image_url":null,"alt":null},{"text":"B, C, D only","image_url":null,"alt":null},{"text":"C, D, E only","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is the correct answer because statements C, D and E are correct.

The middle piece of sperm possesses numerous mitochondria, which produce energy for the movement of tail.

Fertilisation can only occur if the ovum and sperms are transported simultaneously to the ampulla-isthmic region of oviduct.

The middle layer, myometrium exhibits strong uterine contractions during delivery of the baby.

Oogenesis is initiated during the embryonic development stage whereas spermatogenesis starts at the age of puberty.

2nd meiotic division in secondary oocyte is completed in fallopian tube after entry of sperm into the ovum.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.181Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3795, 6, NULL, NULL, 'How many gametes will be formed in the pea plant having genotype RrTT?', NULL, '[{"text":"One","image_url":null,"alt":null},{"text":"Two","image_url":null,"alt":null},{"text":"Four","image_url":null,"alt":null},{"text":"Eight","image_url":null,"alt":null}]', NULL, 1, 'In a pea plant having genotype $ RrT^{T} $, two types of gametes will be formed i.e. RT and rT.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.182Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3796, 6, NULL, NULL, 'The detritus food chain (DFC) begins with', NULL, '[{"text":"Green plants","image_url":null,"alt":null},{"text":"Carnivore","image_url":null,"alt":null},{"text":"Dead Organic matter","image_url":null,"alt":null},{"text":"Herbivore","image_url":null,"alt":null}]', NULL, 2, 'Detritus food chain begins with detritus or dead organic matter.

Grazing food chain begins with green plants.

Carnivores feed on consumers.

Herbivores feed on green plants.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.183Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3797, 6, NULL, NULL, 'How many cycles in a PCR will be required for amplifying the genetic material to about one billion times?', NULL, '[{"text":"10 cycles","image_url":null,"alt":null},{"text":"15 cycles","image_url":null,"alt":null},{"text":"30 cycles","image_url":null,"alt":null},{"text":"35 cycles","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer because if the process of replication of DNA is repeated many times, the segment of DNA can be amplified to approximately billion times, i.e., 1 billion copies are made at the end of 30 PCR cycles. It is possible to generate ''2n'' DNA molecules after ''n'' number of cycles.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.183Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3798, 6, NULL, NULL, 'Gene of which one of the following is present exclusively on the x-chromosome in human being', NULL, '[{"text":"Thalassemia","image_url":null,"alt":null},{"text":"Phenylketonuria","image_url":null,"alt":null},{"text":"Red and green colour blindness","image_url":null,"alt":null},{"text":"Sickle cell anaemia","image_url":null,"alt":null}]', NULL, 2, 'Red-green colour blindness is an X-linked recessive. Mendelian disorder. Gene for this character is present on X-chromosome in humans.

Thalassemia, phenylketonuria and sickle cell anaemia are autosomal recessive Mendelian disorders.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.184Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3799, 6, NULL, NULL, 'Biofortification refers to', NULL, '[{"text":"Sources of proteins for animal and human nutrition","image_url":null,"alt":null},{"text":"Production of somatic hybrids","image_url":null,"alt":null},{"text":"Use of mutation breeding","image_url":null,"alt":null},{"text":"Breeding crops with higher levels of vitamins and minerals, or higher protein and healthier fat CASE STUDY Some strains of Bacillus thuringiensis produce protein that kill certain insects such as lepidopterans (tobacco budworm, armyworm), coleopterans (beetles) and dipterans (flies, mosquitoes). Bacillus thuringiensis forms protein crystals during a particular phase of their growth. These crystals contain a toxic insecticidal protein. The Bt toxin proteins exists as inactive protoxins but once an insect ingests the inactive toxin, it is converted into an active form due to alkaline pH of the gut which solubilise the crystals.","image_url":null,"alt":null}]', NULL, 3, 'Breeding of crops with higher levels of vitamins and minerals or higher protein and healthier fats is called biofortification.

SCP is one of the sources of proteins for animal and human nutrition.

Somatic hybrids are produced by somatic hybridization.

Mutation breeding is one of the methods for making crops disease resistant.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.185Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3800, 6, NULL, NULL, 'The Bt toxin acts on _ of insect pest', NULL, '[{"text":"Hind gut","image_url":null,"alt":null},{"text":"Nervous system","image_url":null,"alt":null},{"text":"Reproductive system","image_url":null,"alt":null},{"text":"Midgut","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is the correct answer because the activated Bt toxins bind to the surface of midgut epithelial cells and create pores that cause cell swelling and lysis and eventually cause death of the insect.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.185Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3801, 6, NULL, NULL, 'Some strains of Bacillus thuringiensis produce proteins that kill certain insects such as', NULL, '[{"text":"Grasshoppers and mosquitoes","image_url":null,"alt":null},{"text":"Lepidopterans, coleopterans and dipterans","image_url":null,"alt":null},{"text":"Coleopterans and nematodes","image_url":null,"alt":null},{"text":"Meloidegyne incognitia","image_url":null,"alt":null}]', NULL, 1, 'Option (B) is the correct answer because some strains of Bacillus thuringiensis produce proteins that kill certain insects such as lepidopterans (tobacco budworm, armyworm), coleopterans (beetles) and dipterans (flies, mosquitoes).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.186Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3802, 6, NULL, NULL, 'Thuringiensis forms protein crystals during a particular phase of their growth. These crystals contain a toxic.', NULL, '[{"text":"Proteolytic enzymes","image_url":null,"alt":null},{"text":"Chitin","image_url":null,"alt":null},{"text":"Insecticidal protein","image_url":null,"alt":null},{"text":"Flavoprotein","image_url":null,"alt":null}]', NULL, 2, 'Option (C) is the correct answer because Bacillus thuringiensis forms a toxic insecticidal protein during a particular phase of their growth. This protein kills the insects and leads to the development of pest-resistant crops.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.187Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3803, 6, NULL, NULL, 'Bt toxin exists as inactive protoxins, it is converted into an active form of toxin due to', NULL, '[{"text":"Enzymes in insect''s gut","image_url":null,"alt":null},{"text":"Acidic pH of the insect''s gut","image_url":null,"alt":null},{"text":"Binding with collagen in insect''s gut","image_url":null,"alt":null},{"text":"Alkaline pH of the insect''s gut","image_url":null,"alt":null}]', NULL, 3, 'Option (D) is the correct answer because the Bt toxin protein exists as inactive protoxins but once an insect ingests the inactive toxin, it is converted into an active form of toxin due to the alkaline pH of the gut which solubilises the crystals.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.187Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3804, 6, NULL, NULL, 'The proteins encoded by the genes cryIAc and cryIIAb control', NULL, '[{"text":"Corn borers","image_url":null,"alt":null},{"text":"Cotton bollworms","image_url":null,"alt":null},{"text":"Mosquitoes","image_url":null,"alt":null},{"text":"Nematodes The biological wealth of our planet has been declining rapidly and the accusing finger is clearly pointing to human activities. The colonisation of tropical pacific islands by humans is said to have led to extinction of more than 2000 species of native birds. The IUCN red list documents the extinction of 784 species. Since the origin and diversification of life on earth, there were five episodes of mass extinction of species. Current species extinction rate as estimated to be 100-1000 times faster. There are four major causes called \"The Evil quartet\" Habitat loss, over exploitation, Alien species invasion and co-extinction. Conservation efforts are necessary to preserve biodiversity and protect endangered species and their habitats. PASSAGE","image_url":null,"alt":null}]', NULL, 1, 'Option (B) is the correct answer because the proteins encoded by the genes cryIAc and cryIIAb control the cotton bollworms, that of cryIAb controls corn borer.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.188Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3805, 6, NULL, NULL, 'Tissue culture and cryopreservation are the techniques used', NULL, '[{"text":"In in-situ conservation","image_url":null,"alt":null},{"text":"To control conservation of medicinal plants only","image_url":null,"alt":null},{"text":"In ex-situ conservation method","image_url":null,"alt":null},{"text":"Used in conventional breeding programmes","image_url":null,"alt":null}]', NULL, 2, 'Ex-situ conservation method includes protective maintenance of threatened species in zoological parks and botanical gardens, in-vitro fertilization, tissue culture propagation and cryopreservation of gametes.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.189Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3806, 6, NULL, NULL, 'Mr. X wants to understand the ''Evil Quartet'' to know the reasons of Biodiversity loss. It is', NULL, '[{"text":"Habitat loss and fragmentation only","image_url":null,"alt":null},{"text":"Over exploitation and Alien species invasions only","image_url":null,"alt":null},{"text":"Co-extinctions and Alien-species invasion","image_url":null,"alt":null},{"text":"Habitat loss, over exploitation, Alien species invasions and co-extinctions","image_url":null,"alt":null}]', NULL, 3, 'There are four major causes of biodiversity losses called ''The Evil Quartet''. These are habitat loss and fragmentation, over exploitation, alien species invasions and co-extinctions.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.189Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3807, 6, NULL, NULL, 'Which one of the following is NOT the reason for decline in biodiversity?', NULL, '[{"text":"Pollution","image_url":null,"alt":null},{"text":"Agriculture","image_url":null,"alt":null},{"text":"Sacred groves","image_url":null,"alt":null},{"text":"Fishing","image_url":null,"alt":null}]', NULL, 2, 'There are accelerated rates of decline in biodiversity largely due to human activities. Agriculture results in habitat loss and pollution makes the environment unfit for survival of species. One of the example of over-exploitation can be fishing that can lead to decline in biodiversity.

In sacred groves wildlife is given total protection.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.190Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3808, 6, NULL, NULL, 'Select the one which is NOT an ex-situ conservation of biodiversity', NULL, '[{"text":"Zoological parks","image_url":null,"alt":null},{"text":"Botanical gardens","image_url":null,"alt":null},{"text":"National parks","image_url":null,"alt":null},{"text":"Seed banks","image_url":null,"alt":null}]', NULL, 2, 'National parks are in-situ conservation strategies for the protection of species. Zoological parks, botanical gardens and seed banks are ex-situ conservation strategies for the protection of species.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.191Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3809, 6, NULL, NULL, 'Identify the in-situ ways to conserve biodiversity from the following

A. Zoological parks

B. Eggs fertilised in-vitro

C. Sacred groves

D. Biosphere reserves', NULL, '[{"text":"A, B only","image_url":null,"alt":null},{"text":"B, C only","image_url":null,"alt":null},{"text":"C, D only","image_url":null,"alt":null},{"text":"A, D only","image_url":null,"alt":null}]', NULL, 2, 'Sacred groves and biosphere reserve are in-situ conservation strategies for protection of biodiversity. Zoological parks are ex-situ conservation strategies for biodiversity protection.

When the fertilization of egg is done outside the body, it is called in-vitro fertilization.

