INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3810, 5, NULL, NULL, 'In a face centred cubic unit cell of close packed atoms, the radius of atom (r) is related to the edge length ''a'' of the unit cell by the expression', NULL, '[{"text":"$ \\mathrm{r} = \\frac{\\mathrm{a}}{\\sqrt{2}} $","image_url":null,"alt":null},{"text":"$ \\mathrm{r} = \\frac{\\mathrm{a}}{2} $","image_url":null,"alt":null},{"text":"$ \\mathrm{r} = \\frac{\\mathrm{a}}{2\\sqrt{2}} $","image_url":null,"alt":null},{"text":"$ \\mathrm{r} = \\frac{\\sqrt{3}\\mathrm{a}}{4} $","image_url":null,"alt":null}]', NULL, 2, 'In fcc unit cell, atoms are present at the corners and the middle of each face of the unit cell:

$$ \sqrt{2}a=4r;r=\frac{a}{2\sqrt{2}} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.195Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3811, 5, NULL, NULL, 'An alloy of Cu, Ag and Au is found to have Cu constituting the CCP lattice. If Ag atoms occupy edge centres, and Au is present at body centre, then the alloy has formula', NULL, '[{"text":"$ Cu_{4}Ag_{2}Au $","image_url":null,"alt":null},{"text":"$ Cu_{4}Ag_{4}Au $","image_url":null,"alt":null},{"text":"$ Cu_{4}Ag_{3}Au $","image_url":null,"alt":null},{"text":"CuAgAu","image_url":null,"alt":null}]', NULL, 2, 'Cu is present at fcc, so z = 4; Ag is present at edge centre, so $ z = 12 \times 1/4 = 3 $; Au is present at bcc, so z = 1 Therefore ; formula of alloy is $ \mathrm{Cu}_{4}\mathrm{Ag}_{3}\mathrm{Au} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.196Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3812, 5, NULL, NULL, 'What is $\Delta G^{\circ}$ for the given reaction?

$\mathrm{Zn(s) + Cu^{2+}(aq) \rightarrow Zn^{2+}(aq) + Cu(s)}$

(Given: $E_{Zn^{2+}/Zn}^{0} = -0.76\,\mathrm{V}$ & $E_{Cu^{2+}/Cu}^{0} = +0.34\,\mathrm{V}$)

$F = 96500\,\mathrm{C\,mol}^{-1}$', NULL, '[{"text":"$\\Delta G^{\\circ} = -212.3\\,\\mathrm{kJ/mol}$","image_url":null,"alt":null},{"text":"$\\Delta G^{\\circ} = +212.3\\,\\mathrm{kJ/mol}$","image_url":null,"alt":null},{"text":"$\\Delta G^{\\circ} = -312.5\\,\\mathrm{kJ/mol}$","image_url":null,"alt":null},{"text":"$\\Delta G^{\\circ} = 0$ (d) $ \\Delta G^{0}=0 $","image_url":null,"alt":null}]', NULL, 0, 'The given reaction is:

$ \mathrm{Zn(s)+Cu^{2+}(aq)\rightarrow Zn^{2+}(aq)+Cu(s)} $

$ \Delta G^{\circ}=-nFE^{\circ} $

For given cell reaction, n = 2

$ E_{cell}^{\circ}=E_{cathode}^{\circ}-E_{anode}^{\circ} $

=0.34-(-0.76)=1.1 V

$ \Delta G^{\circ}=-2\times96500\times1.1 $

$$ =-212.3\mathrm{kJ/mol} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.197Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3813, 5, NULL, NULL, 'How many electrons flow when a current of 5 amperes is passed through a metal for 193s?

(Given: F = 96500 c mol $ ^{-1} $, $ N_{A} = 6.022 \times 10^{23} $ mol $ ^{-1} $)', NULL, '[{"text":"$ 6.022 \\times 10^{23} $ electrons","image_url":null,"alt":null},{"text":"$ 6.022 \\times 10^{21} $ electrons","image_url":null,"alt":null},{"text":"$ 3.011 \\times 10^{21} $ electrons","image_url":null,"alt":null},{"text":"$ 3.011 \\times 10^{23} $ electrons","image_url":null,"alt":null}]', NULL, 1, 'Charge Q = it

= 5 × 193 = 965 C

= $ \frac{965}{96500} $ = 0.01 F

1 F = charge of 1 mole electrons

0.01 F = charge of 0.01 mole electrons

= charge of $ 6.02 \times 10^{23} $ × 0.01 electrons

= charge of $ 6.02 \times 10^{21} $ electrons', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.198Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3814, 5, NULL, NULL, 'Kohlrausch law of independent migration of ion is applicable to', NULL, '[{"text":"Only to weak electrolytes at a certain concentration","image_url":null,"alt":null},{"text":"Only to strong electrolytes at all concentrations","image_url":null,"alt":null},{"text":"To both - strong and weak electrolytes","image_url":null,"alt":null},{"text":"To non-electrolytes","image_url":null,"alt":null}]', NULL, 2, 'It states that at infinite dilution, the conductivity of electrolytic solution is equal to the sum of conductivities of individual ions which are present in electrolyte.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.199Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3815, 5, NULL, NULL, 'In the first order reaction the concentration of the reactant is reduced $ \frac{1}{4} $th in 60 minutes, what will be its half-life?', NULL, '[{"text":"120 minutes","image_url":null,"alt":null},{"text":"40 minutes","image_url":null,"alt":null},{"text":"30 minutes","image_url":null,"alt":null},{"text":"25 minutes","image_url":null,"alt":null}]', NULL, 2, 'For first order reaction: $ K = \frac{2.303}{t} \log \frac{[A]_{0}}{[A]_{t}} $

$ \frac{2.303}{60} \log \frac{4[A]_{0}}{[A]_{0}} \Rightarrow 0.0231 $

$ t_{1/2} = \frac{0.693}{K} = \frac{0.693}{0.0231} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.200Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3816, 5, NULL, NULL, 'Which of the following is the correct relationship between time required for completion of 99.9% of a first order reaction and its half-life?', NULL, '[{"text":"$ t_{\\frac{1}{2}} = 5 \\times t_{99.9\\%} $","image_url":null,"alt":null},{"text":"$ t_{99.9\\%} = 10 \\times t_{\\frac{1}{2}} $","image_url":null,"alt":null},{"text":"$ t_{99.9\\%} = 2t_{\\frac{1}{2}} $","image_url":null,"alt":null},{"text":"$ t_{99.9\\%} = t_{\\frac{1}{2}} $","image_url":null,"alt":null}]', NULL, 1, 'For first order reaction

$ t = \frac{2.303}{k} \log \left[ \frac{A}{A} \right]_{t} $

at $ t = 0 $; $ a_{0} = 100 \, M $

at $ t_{99.9\%} $; $ a_{0} - x $

$ = 100 - 99.9 = 0.1 $

$ t_{99.9} = \frac{2.303}{k} \log \left[ \frac{100}{0.1} \right] = \frac{3 \times 2.303}{k} = \frac{6.9}{k} $

Since $ t_{1/2} = \frac{0.693}{k} $

$ t_{99.9} = \left( \frac{0.693}{k} \right) \times 10 $

$ t_{99.9} = 10t_{1/2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.200Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3817, 5, NULL, NULL, 'A catalyst increases the rate of reaction by:', NULL, '[{"text":"Decreasing enthalpy of reactants","image_url":null,"alt":null},{"text":"Increasing internal energy of reactants","image_url":null,"alt":null},{"text":"Decreasing activation energy of reaction","image_url":null,"alt":null},{"text":"Increasing activation energy of reaction","image_url":null,"alt":null}]', NULL, 2, 'Catalyst affects activation energy of any chemical reaction.

Catalyst increases rate of reaction by decreasing the activation energy of reaction.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.201Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
