INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3819, 5, NULL, NULL, 'Consider the case when a highly diluted solution of KI is added to AgNO_{3} solution. Arrange the following in the increasing order of ease of coagulation of the resulting sol.

A. BaSO_{4}

B. NaCl

C. Na_{3}PO_{4}

D. K_{4}[Fe(CN)_{6}]', NULL, '[{"text":"A < C < B < D","image_url":null,"alt":null},{"text":"D < C < A < B","image_url":null,"alt":null},{"text":"A < B < C < D","image_url":null,"alt":null},{"text":"B < A < C < D","image_url":null,"alt":null}]', NULL, 3, 'Since highly diluted KI is added into AgNO₃ solution, the resultant colloidal solution will be positive charged due to excess of Ag+.

This positively charged sol will be coagulated by anion of electrolyte.

Electrolyte having anion with higher negative charge will have more ease of coagulation.

Hence order will be

NaCl & BaSO₄ & Na₂PO₄ & K₄[Fe(CN)₆]', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.202Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
