INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3832, 5, NULL, NULL, 'Which of the following is the electronic configuration of the central metal atom/ion of $ [Co(H_{2}O)_{6}]^{2+} $ complex ion?', NULL, '[{"text":"$ t_{2}g^{6}eg^{1} $","image_url":null,"alt":null},{"text":"$ t_{2}g^{4}eg^{3} $","image_url":null,"alt":null},{"text":"$ t_{2}g^{5}eg^{2} $","image_url":null,"alt":null},{"text":"$ t_{2}g^{6}eg^{0} $","image_url":null,"alt":null}]', NULL, 2, 'For $ [\mathrm{Co}(\mathrm{H}_{2}\mathrm{O})_{6}]^{2+} $

