INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3834, 5, NULL, NULL, 'Aryl halides can not be prepared by the reaction of aryl alcohols with $ PCl_{3} $, $ PCl_{5} $ or $ SOCl_{2} $ because:', NULL, '[{"text":"Phenols are highly stable compounds","image_url":null,"alt":null},{"text":"Carbon-oxygen bond in phenols has a partial double bond character","image_url":null,"alt":null},{"text":"Carbon-oxygen bond is highly polar","image_url":null,"alt":null},{"text":"Phenyl cation is stabilised by resonance","image_url":null,"alt":null}]', NULL, 1, 'In case of aryl alcohol C-O bond is difficult to break as it has partial double bond character due to resonance Hence it cannot be used for preparation of aryl halide by $ PCl_{3} $, $ PCl_{5} $ or $ SOCl_{2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.209Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
