INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3838, 5, NULL, NULL, 'Out of the following compounds, which is the most basic in aqueous solution?', NULL, '[{"text":"$ \\mathrm{CH}_{3}-\\mathrm{NH}_{2} $","image_url":null,"alt":null},{"text":"$ \\mathrm{(CH_{3})_{2}NH} $","image_url":null,"alt":null},{"text":"$ (\\mathrm{CH}_{3})_{3}\\mathrm{N} $","image_url":null,"alt":null},{"text":"$ \\mathrm{C}_{6}\\mathrm{H}_{5}\\mathrm{NH}_{2} $","image_url":null,"alt":null}]', NULL, 1, 'Order of basic strength of amines depends on two factors:

(1) Availability of lone pair

(2) Stability of conjugate acid formed in an aqueous solution.

Order of basic strength in aqueous solution:

$$ (CH_{3})_{2}NH>CH_{3}\longrightarrow NH_{2}>(CH_{3})_{3}N>C_{6}H_{5}NH_{2} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.213Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3839, 5, NULL, NULL, 'Arrange the following in increasing order of their boiling points:

A. $ (C_{2}H_{5})_{2}NH $ B. n-C $ _{4} $H $ _{9} $NH $ _{2} $ C. C $ _{2} $H $ _{5} $N(CH $ _{3} $) $ _{2} $ D. n-C $ _{4} $H $ _{9} $OH', NULL, '[{"text":"B < C < A < D","image_url":null,"alt":null},{"text":"C < B < A < D","image_url":null,"alt":null},{"text":"C < A < B < D","image_url":null,"alt":null},{"text":"C < D < B < A","image_url":null,"alt":null}]', NULL, 2, 'Primary Secondary amines show intermolecular H-bonding while tertiary amine not able to show due to absence of free Hydrogen.

∴ The boiling order ofamine is $ 1^{\circ} > 2^{\circ} > 3^{\circ} $

The boiling point of alcohol with some no. of carbon is higher than amines due to stronger H-bonding Hence order is;

$$ C<A<B<D $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.214Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3840, 5, NULL, NULL, 'Which of the following is an essential amino acid?', NULL, '[{"text":"Glycine","image_url":null,"alt":null},{"text":"Alanine","image_url":null,"alt":null},{"text":"Glutamine","image_url":null,"alt":null},{"text":"Valine","image_url":null,"alt":null}]', NULL, 3, 'Valine is an essential amino acid as it cannot be synthesised in body.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.214Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3841, 5, NULL, NULL, 'In nucleic acids, the Nucleotides are joined together by', NULL, '[{"text":"Glycosidic linkage","image_url":null,"alt":null},{"text":"Phosphodiester linkage","image_url":null,"alt":null},{"text":"Hydrogen bonds","image_url":null,"alt":null},{"text":"Weak intermolecular forces","image_url":null,"alt":null}]', NULL, 1, 'In Nucleic Acids, the nucleotides are joined together by phosphodiester linkage between 5'' and 3'' carbon atom of pentose sugar.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.216Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3842, 5, NULL, NULL, 'The letter ''D'' in carbohydrates signifies', NULL, '[{"text":"Dextrorotatory","image_url":null,"alt":null},{"text":"Configuration","image_url":null,"alt":null},{"text":"Diamagnetic character","image_url":null,"alt":null},{"text":"Optical activity","image_url":null,"alt":null}]', NULL, 1, 'The letter ''D'' in carbohydrates signifies the substitution orientation at a centre of chirality i.e., configuration.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.216Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3843, 5, NULL, NULL, 'Which of the following monomeric pair is used to make polymer Nylon 6, 6?', NULL, '[{"text":"Hexane-1, 6 dioic acid and Hexane-1, 6-diamine","image_url":null,"alt":null},{"text":"Ethane-1, 2-dioic acid and Benzene-1, 4-dicarboxylic Acid","image_url":null,"alt":null},{"text":"Urea and Methanal","image_url":null,"alt":null},{"text":"Phenol and Methanol","image_url":null,"alt":null}]', NULL, 0, 'Nylon 6, 6 is formed by the condensation polymerisation of hexaethylene diamine with adipic acid under high pressure and at high temperature.

$$ \begin{align*}&\mathrm{nH_{2}N}-(\mathrm{CH_{2}})_{6}-\mathrm{NH_{2}}+\mathrm{nHOOC}-(\mathrm{CH_{2}})_{4}-\mathrm{COOH}\\&\quad\quad\quad\quad553\mathrm{K}\bigg|\bigg|_{{high~pressure}}\\&\quad\quad\quad(\mathrm{NH}-(\mathrm{CH_{2}})_{6}\mathrm{NH}-\mathrm{CO}-(\mathrm{CH_{2}})_{4}-\mathrm{CO})_{\pi}+\mathrm{nH_{2}O}\\&\quad\quad\quad\quad\mathrm{Nylon-6,6}\end{align*} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.217Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3844, 5, NULL, NULL, 'Which amongst the following antibiotics is an example of narrow spectrum antibiotic?', NULL, '[{"text":"Vancomycin","image_url":null,"alt":null},{"text":"Chloramphenicol","image_url":null,"alt":null},{"text":"Amoxycillin","image_url":null,"alt":null},{"text":"Penicillin G","image_url":null,"alt":null}]', NULL, 3, 'Narrow spectrum antibiotics are effective mainly against Gram-positive or gram-negative bacteria.

eg: Penicillin G', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3845, 5, NULL, NULL, 'Which of the following polymers are obtained by chain growth polymerisation?', NULL, '[{"text":"Orlon","image_url":null,"alt":null},{"text":"Nylon","image_url":null,"alt":null},{"text":"Teflon","image_url":null,"alt":null},{"text":"Nylon 2-nylon 6 (E) Dacron","image_url":null,"alt":null}]', NULL, 1, 'Chain growth polymers or addition polymers are formed by the repeated addition of monomers molecules possessing double or triple bonds.

$$ \begin{align*}\mathrm{nCH}_{2}&=\underset{\mathrm{CN}}{\overset{\mathrm{CH}}{\vert}}\xrightarrow{\mathrm{polymerise}}\left(-\underset{\mathrm{CN}}{\overset{\mathrm{CH}}{|}}-\underset{\mathrm{CH}}{\overset{\mathrm{CH}}{\vert}}\right)_{\mathrm{n}}\end{align*} $$

$$ \begin{aligned}nCF_{2}&\xrightarrow{polymerise}-(CF_{2}-CF_{2})_{n}\\ Tetrafluoroethene&\quad Tetflon\end{aligned} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3846, 5, NULL, NULL, 'Isotonic solutions are the solutions with:', NULL, '[{"text":"Same vapour pressure","image_url":null,"alt":null},{"text":"Same temperature","image_url":null,"alt":null},{"text":"Same osmotic pressure","image_url":null,"alt":null},{"text":"Same volume","image_url":null,"alt":null}]', NULL, 2, 'Isotonic solutions have same osmotic pressure.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.219Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3847, 5, NULL, NULL, 'An unripe mango placed in a concentrated salt solution to prepare pickle shrivels because:', NULL, '[{"text":"It gains water via osmosis","image_url":null,"alt":null},{"text":"It loses water via reverse osmosis","image_url":null,"alt":null},{"text":"It gains water via reverse osmosis","image_url":null,"alt":null},{"text":"It loses water via osmosis","image_url":null,"alt":null}]', NULL, 3, 'In osmosis flow of solvent take place from dilute solution to concentrated solution.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3848, 5, NULL, NULL, 'Adding a salt to water leads to increase in the boiling point of solution with respect to water because:', NULL, '[{"text":"Vapour pressure of solution is increased","image_url":null,"alt":null},{"text":"Solubility of salt in water is increased","image_url":null,"alt":null},{"text":"Solubility of salt in water is decreased","image_url":null,"alt":null},{"text":"Vapour pressure of solution is decreased","image_url":null,"alt":null}]', NULL, 3, 'On addition of salt to water, it will decrease the tendency to form vapour. Vapour pressure decreases as a result boiling point of solution increases.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3849, 5, NULL, NULL, 'Salt is used to clear snow on the roads covered with snow to:', NULL, '[{"text":"Decrease the freezing point","image_url":null,"alt":null},{"text":"Increase the boiling point","image_url":null,"alt":null},{"text":"Increase the osmotic pressure","image_url":null,"alt":null},{"text":"Increase the solubility of salt","image_url":null,"alt":null}]', NULL, 0, 'Salt is used to lowers the freezing point of water. Hence, salt is used to clear snow on the roads covered with snow to decrease the freezing point.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3850, 5, NULL, NULL, 'Which of the following is a colligative property?', NULL, '[{"text":"Vapour pressure","image_url":null,"alt":null},{"text":"Osmotic pressure","image_url":null,"alt":null},{"text":"Freezing point","image_url":null,"alt":null},{"text":"Boiling point Passage: Ethers are class of organic compounds that contain ether group - an oxygen atom connected to two alkyl groups or aryl groups. They have the general formula $ R-O-R'' $, where R and $ R'' $ represent the alkyl or aryl groups. Ether, like water have a tetrahedral geometry i.e., oxygen is $ sp^{3} $ hybridised. The C-O-C bond angle in ethers is slightly greater than the tetrahedral angle due to repulsive interactions between the two bulky groups when they are attached to oxygen.","image_url":null,"alt":null}]', NULL, 0, 'Osmotic pressure is a colligative property as it depends on the number of particles present in the solution.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
