INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3853, 5, NULL, NULL, 'Atoms of B forms fcc lattice and those of element A occupy alternate tetrahedral voids. The formula of the compound formed by elements A and B', NULL, '[{"text":"$ AB_{2} $","image_url":null,"alt":null},{"text":"$ A_{2}B $","image_url":null,"alt":null},{"text":"AB","image_url":null,"alt":null},{"text":"$ A_{2}B_{3} $ (C) AB","image_url":null,"alt":null}]', NULL, 2, 'Number of atom ''B'' forming Fcc lattice

$ =\frac{1}{8}\times8+\frac{1}{2}\times6=4 $

Number of atom ''A'' (Occupying alternate tetrahedral voids)

$ =1\times4 $

$ \therefore A:B \Rightarrow 4:4 $

∴ Formula of compound is AB.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
