INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3858, 5, NULL, NULL, 'Molar conductivity of _ increases drastically on dilution.', NULL, '[{"text":"$ \\mathrm{NH}_{4}\\mathrm{Cl} $","image_url":null,"alt":null},{"text":"NaCl","image_url":null,"alt":null},{"text":"$ \\mathrm{CH}_{3}\\mathrm{COOH} $","image_url":null,"alt":null},{"text":"$ \\mathrm{CH}_{3}\\mathrm{COONa} $","image_url":null,"alt":null}]', NULL, 2, 'Molar conductivity of weak electrolyte increases on dilution because of increase in number of ions.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3859, 5, NULL, NULL, 'When temperature changes from 293 K to 313 K, the rate of reaction', NULL, '[{"text":"Remains same","image_url":null,"alt":null},{"text":"Gets halved","image_url":null,"alt":null},{"text":"Gets doubles","image_url":null,"alt":null},{"text":"Gets quadruples","image_url":null,"alt":null}]', NULL, 3, 'Temperature is increased from 293 K to 313 K

$ n=\frac{313-293}{10}=2 $

Rate= $ 2^{n}=2^{2}=4 $ times', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.227Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3860, 5, NULL, NULL, 'Which of the following expression is correct for the rate of reaction given below:

$ 5\mathrm{Br}^{-}(aq) + \mathrm{BrO}_{3}^{-}(aq) + 6\mathrm{H}^{+} \rightarrow 3\mathrm{Br}_{2}(aq) + 3\mathrm{H}_{2}\mathrm{O}(l) $', NULL, '[{"text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=5\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $","image_url":null,"alt":null},{"text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=\\frac{6}{5}\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $ $$ O B=\\frac{5}{1}O A $$","image_url":null,"alt":null},{"text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=\\frac{5}{6}\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $","image_url":null,"alt":null},{"text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=6\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $","image_url":null,"alt":null}]', NULL, 2, 'Rate = $ \frac{-1}{5}\frac{\Delta[\mathrm{Br}^{-}]}{\Delta t} = \frac{-\Delta[\mathrm{BrO}_{3}^{-}]}{\Delta t} = \frac{-1}{6}\frac{\Delta[\mathrm{H}^{+}]}{\Delta t} $

$ \frac{1}{3}\frac{\Delta[\mathrm{Br}_{2}]}{\Delta t} = \frac{1}{3}\frac{\Delta[\mathrm{H}_{2}\mathrm{O}]}{\Delta t} $

$ \therefore \frac{\Delta[\mathrm{Br}^{-}]}{\Delta t} = \frac{5}{6}\frac{\Delta[\mathrm{H}^{+}]}{\Delta t} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.228Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
