INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3882, 5, NULL, NULL, 'Lactose is a disaccharide formed from $ \beta $-D-galactose and $ \beta $-D-glucose. Identify anomeric carbon atoms in monosaccharide units', NULL, '[{"text":"''a'' carbon of galactose and ''d'' carbon of glucose","image_url":null,"alt":null},{"text":"''d'' carbon of galactose and ''a'' carbon of glucose","image_url":null,"alt":null},{"text":"''a'' carbon of galactose and ''a'' carbon of glucose","image_url":null,"alt":null},{"text":"''e'' carbon of galactose and ''e'' carbon of glucose","image_url":null,"alt":null}]', NULL, 2, 'Lactose is formed of C1 of galactose and C4 of glucose. So, ''a'' carbon of galactose and ''a'' carbon of glucose are anomeric carbon atoms.', NULL, NULL, 2022, '/local-papers/assets/chemistry-2022-08-18/q37-figure-1.jpg', 'Figure for question 37', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.239Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2022-08-18/q37-figure-1.jpg","alt":"Figure for question 37","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
