INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3884, 5, NULL, NULL, 'Identify the monomers which forms biodegradable polymers', NULL, '[{"text":"Ethylene glycol + phthalic acid","image_url":null,"alt":null},{"text":"Caprolactam","image_url":null,"alt":null},{"text":"Phenol + Formaldehyde","image_url":null,"alt":null},{"text":"Amino caproic acid + glycine","image_url":null,"alt":null}]', NULL, 3, 'Nylon 2-nylon 6 is a polymer of glycine and amino caproic acid and is biodegradable. Other given polymers are non-biodegradable.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.240Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3885, 5, NULL, NULL, 'In view of general awareness and concerns for accumulation of polymeric solid waste materials, certain biodegradable synthetic polymers have been developed. Which amongst the following are biodegradable synthetic polymers?', NULL, '[{"text":"Novolac","image_url":null,"alt":null},{"text":"Neoprene","image_url":null,"alt":null},{"text":"PHBV","image_url":null,"alt":null},{"text":"BUNA-S","image_url":null,"alt":null}]', NULL, 2, 'PHBV undergoes bacterial degradation in environment.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.240Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
