INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3887, 5, NULL, NULL, 'Which of the following is likely to cause ulcer in the stomach?', NULL, '[{"text":"Luminal","image_url":null,"alt":null},{"text":"Aspirin","image_url":null,"alt":null},{"text":"Phenelzine","image_url":null,"alt":null},{"text":"Iproniazid","image_url":null,"alt":null}]', NULL, 1, 'Aspirin like pain reliever causes ulcer in stomach.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3888, 5, NULL, NULL, 'Which of the following is responsible for the mood changes/depression in humans?', NULL, '[{"text":"Thyroid","image_url":null,"alt":null},{"text":"Norethindrone","image_url":null,"alt":null},{"text":"Noradrenaline","image_url":null,"alt":null},{"text":"Terfenadine","image_url":null,"alt":null}]', NULL, 2, 'Noradrenaline is one of the neurotransmitters that plays a role in mood change.

