INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3889, 5, NULL, NULL, 'Which category of drug can act, both as antipyretic as well as analgesic?', NULL, '[{"text":"Narcotic analgesics","image_url":null,"alt":null},{"text":"Non narcotic analgesics","image_url":null,"alt":null},{"text":"Tranquilizers","image_url":null,"alt":null},{"text":"Antibiotic","image_url":null,"alt":null}]', NULL, 1, 'Non-narcotic analgesic drugs have other effects such as reducing fever (antipyretic)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3890, 5, NULL, NULL, 'Tranquilizers are the substances used for the treatments of', NULL, '[{"text":"Cancer","image_url":null,"alt":null},{"text":"AIDS","image_url":null,"alt":null},{"text":"Mental diseases","image_url":null,"alt":null},{"text":"Physical disorder Passage Solubility of gases in liquids is greatly affected by pressure and temperature. Henry gave the quantitative relationship between pressure and solubility of gas in a solvent. According to Henry''s law, partial pressure of a gas above a liquid is directly proportional to its mole fraction in solution and is expressed as $P = K_{H}x$, where KH is Henry''s constant and x is mole fraction of gas. KH is a function of nature of gas. F M Raoult gave a quantitative relationship between partial pressures and mole fractions in the binary solution of volatile liquids. Raoult''s law states that for a binary solution of volatile liquids, the partial pressure of each component in the solution is directly proportional to its mole fraction. Thus for a solution of component 1 and 2, partial pressure of each component $ P_{1} = p_{1}^{0}x_{1} $, where $ p_{1}^{0} $ is the vapour pressure of pure component 1 at the same temperature. Similarly $ p_{2} = p_{2}^{0}x_{2} $","image_url":null,"alt":null}]', NULL, 2, 'Tranquilizers are used for the treatments of mental diseases.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.242Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3891, 5, NULL, NULL, 'Solubility of Carbon dioxide in soda water increases with', NULL, '[{"text":"Increase in pressure and temperature both","image_url":null,"alt":null},{"text":"Increase in pressure and decrease in temperature","image_url":null,"alt":null},{"text":"Decrease in pressure and increase in temperature","image_url":null,"alt":null},{"text":"Decrease in pressure and decrease in temperature","image_url":null,"alt":null}]', NULL, 1, 'Solubility of CO $ _{2(g)} $ in water increases with increase in pressure and decrease in temperature.

A mixture of chloroform and acetone shows negative deviation from Raoult''s law, it is due to H-bonding.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.244Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
