INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3893, 5, NULL, NULL, 'If a solution exhibits positive deviation from Raoult''s Law then sign of $ \Delta_{\text{mix}} H $ and $ \Delta_{\text{mix}} V $ will be', NULL, '[{"text":"$ \\Delta_{\\text{mix}} H = \\text{positive}; \\Delta_{\\text{mix}} V = \\text{positive} $","image_url":null,"alt":null},{"text":"$ \\Delta_{\\text{mix}} H = \\text{positive}; \\Delta_{\\text{mix}} V = \\text{negative} $","image_url":null,"alt":null},{"text":"$ \\Delta_{\\text{mix}} H = \\text{negative}; \\Delta_{\\text{mix}} V = \\text{positive} $","image_url":null,"alt":null},{"text":"$ \\Delta_{\\text{mix}} H = \\text{negative}; \\Delta_{\\text{mix}} V = \\text{negative} $","image_url":null,"alt":null}]', NULL, 0, 'For a solution exhibiting positive deviation from Raoult''s law

