INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3895, 5, NULL, NULL, 'Which of the following shows both Frenkel as well as Schottky defects?', NULL, '[{"text":"AgBr","image_url":null,"alt":null},{"text":"NaCl","image_url":null,"alt":null},{"text":"KCl","image_url":null,"alt":null},{"text":"AgCl","image_url":null,"alt":null}]', NULL, 0, 'AgBr shows both, Frenkel as well as Schottky defects.

(c) For hexagonal crystal system, $ a = b \neq c $ and $ \alpha = \beta = 90^{\circ}, \gamma = 120^{\circ} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.249Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3896, 5, NULL, NULL, 'Efficiency of packing in body centred cubic structures is found to be', NULL, '[{"text":"33%","image_url":null,"alt":null},{"text":"74%","image_url":null,"alt":null},{"text":"52.4%","image_url":null,"alt":null},{"text":"68%","image_url":null,"alt":null}]', NULL, 3, 'For body centred cubic structures, \sqrt{3}a = 4r

Packing efficiency

= $ \frac{\text{Volume occupied by two spheres in unit cell} \times 100}{\text{Volume of unit cell}} $

$ 2 \times \frac{4}{3} \pi r^{3} $

$ = \frac{a^{3}}{a^{3}} \times 100 = 68\% $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.250Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3897, 5, NULL, NULL, 'Observe the given graph and identify the correct statement for the solution.

$ x_1=1 $ Mole Fraction $ x_1=0 $

$ x_2=0 $ $ x_2 \longrightarrow x_2=1 $', NULL, '[{"text":"Component 2 is more volatile than component 1","image_url":null,"alt":null},{"text":"Component 1 is more volatile than component 2","image_url":null,"alt":null},{"text":"Boiling point of component 1 is lower than that of component 2","image_url":null,"alt":null},{"text":"Volatility of a component depends upon its mole fraction","image_url":null,"alt":null}]', NULL, 0, '$p_{1}^{0}$ and $p_{2}^{0}$ are the vapour pressures of pure component 1 and 2 respectively from the plot, $p_{2}^{0} > p_{1}^{0}$, that means component 2 is more volatile than component 1. So, boiling point of component 1 is greater than component 2.', NULL, NULL, 2022, '/local-papers/assets/chemistry-2022-08-23/q04-figure-1.jpg', 'Figure for question 4', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.250Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2022-08-23/q04-figure-1.jpg","alt":"Figure for question 4","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3898, 5, NULL, NULL, '18 g of a non-volatile solution A is dissolved in 1 kg of water, the boiling point of water is raised to 373.51 K. Given $ K_{b} $ for water is 0.52 K kg mol $ ^{-1} $, boiling point for water is 373.15 K at 1.013 bar pressure.

The molecular weight of the solid A is', NULL, '[{"text":"$ 58.0 \\, g \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 26.0 \\, g \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 55.0 \\, g \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 110.0 \\, g \\, mol^{-1} $","image_url":null,"alt":null}]', NULL, 1, '$ \Delta T_{b} = K_{b} \times m $ (where m is molality)

$ \Delta T_{b}=373.51-373.15=0.36K $

$ \therefore $ $ 0.36=0.52\times\frac{18}{M_{A}\times1}\Rightarrow M_{A}=26\ g\ mol^{-1} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.251Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3899, 5, NULL, NULL, 'Based on solute solvent interactions, arrange the following in the order of increasing solubility in n-octane.

A. Cyclohexane

B. KCl

C. $ \mathrm{CH_{3}OH} $

D. $ \mathrm{CH_{3}NH_{2}} $

E. $ \mathrm{CH_{3}CN} $', NULL, '[{"text":"A < B < C < D < E","image_url":null,"alt":null},{"text":"B < C < E < D < A","image_url":null,"alt":null},{"text":"C < B < A < E < D","image_url":null,"alt":null},{"text":"B < C < D < E < A","image_url":null,"alt":null}]', NULL, 3, 'According to like-dissolve-like theory, polar species are soluble with polar solvent and non-polar species are soluble with non-polar solvent. n-octane is non-polar in nature.

(A) Cyclohexane $ \rightarrow $ non-polar

(B) KCl $ \rightarrow $ highly polar

(C) CH_{3}OH $ \rightarrow $ polar

(D) CH_{3}NH_{2} $ \rightarrow $ polar

(E) CH_{3}CN $ \rightarrow $ less polar in nature.

So, correct order of solubility in n-octane is

B<C<D<E<A', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.251Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3900, 5, NULL, NULL, 'In a pseudo first order reaction, the rate constant', NULL, '[{"text":"Is independent of the concentration of reactants","image_url":null,"alt":null},{"text":"Depends on concentration of reactants present in small quantity","image_url":null,"alt":null},{"text":"Depends on temperature","image_url":null,"alt":null},{"text":"Depends on concentration of reactants present in excess","image_url":null,"alt":null}]', NULL, 3, 'In a pseudo first order reaction, rate constant depends on concentration of excess reagent.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.252Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3901, 5, NULL, NULL, 'When the temperature of a reaction is increased by $ 20^{\circ} $C, the rate of reaction increases by', NULL, '[{"text":"3 times","image_url":null,"alt":null},{"text":"4 times","image_url":null,"alt":null},{"text":"2 times","image_url":null,"alt":null},{"text":"1.5 times","image_url":null,"alt":null}]', NULL, 1, 'For a chemical reaction with rise in temperature by $ 10^{\circ} $C, the rate constant is nearly doubled. So, for $ 20^{\circ} $C rise in temperature, the rate constant increases by four times.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3902, 5, NULL, NULL, 'Observe the given graph. What will be the unit for the rate constant?', NULL, '[{"text":"$ \\mathrm{mol L^{-1} s^{-1}} $","image_url":null,"alt":null},{"text":"$ \\mathrm{mol^{-1} L s^{-1}} $","image_url":null,"alt":null},{"text":"$ s^{-1} $","image_url":null,"alt":null},{"text":"$ \\mathrm{mol^{-2} L^{2} s^{-1}} $","image_url":null,"alt":null}]', NULL, 2, 'For first order reaction

$$ \mathrm{k}=\frac{2.303}{\mathrm{t}}\log\frac{\left[\mathrm{R}\right]_{0}}{\left[\mathrm{R}\right]}\Longrightarrow\log\frac{\left[\mathrm{R}\right]_{0}}{\left[\mathrm{R}\right]}=\frac{\mathrm{k}}{2.303}\times\mathrm{t}. $$

\therefore \mathrm{Slope}=\frac{k}{2.303}, the given graph represents first order reaction.

Unit of rate constant = $ (\text{mol L}^{-1})^{1-1} $ s $ ^{-1} $ = s $ ^{-1} $.

(b) Let, rate = k[A]x [B]y

From data 1 in experiment,

$ 2 \times 10^{-3} = k[0.1]x [0.1]y $

...(i)

From data 2,

$ 4 \times 10^{-3} = k[0.2]x [0.2]y $

...(ii)

From data 3,

$ 2 \times 10^{-3} = k[0.1]x [0.2]y $

...(iii)

Dividing equation (i) and (iii)

$ \frac{2 \times 10^{-3}}{2 \times 10^{-3}} = \frac{k[0.1]x [0.1]y}{k[0.1]x [0.2]y} = \left(\frac{1}{2}\right)^y \Rightarrow y = 0 $

Put the value of y in equation (i) and (ii),

$ 2 \times 10^{-3} = k[0.1]x [0.1]0 $

...(iv)

$ 4 \times 10^{-3} = k[0.2]x [0.2]0 $

...(v)

Dividing equation (iv) and (v)

$ \frac{1}{2} = \left(\frac{0.1}{0.2}\right)^x \Rightarrow x = 1 $

So, overall order = x + y = 1 + 0 = 1', NULL, NULL, 2022, '/local-papers/assets/chemistry-2022-08-23/q09-figure-1.jpg', 'Figure for question 9', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.253Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2022-08-23/q09-figure-1.jpg","alt":"Figure for question 9","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3903, 5, NULL, NULL, 'The colloids that cannot be easily coagulated are', NULL, '[{"text":"Lyophobic colloids","image_url":null,"alt":null},{"text":"Lyophilic colloids","image_url":null,"alt":null},{"text":"Irreversible sols","image_url":null,"alt":null},{"text":"Associated colloids","image_url":null,"alt":null}]', NULL, 1, 'Lyophilic colloids are quite stable and cannot be easily coagulated.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3904, 5, NULL, NULL, 'Which of the following ores can be concentrated using froth floatation process?', NULL, '[{"text":"Magnetite","image_url":null,"alt":null},{"text":"Calamine","image_url":null,"alt":null},{"text":"Copper Pyrites","image_url":null,"alt":null},{"text":"Bauxite","image_url":null,"alt":null}]', NULL, 2, 'Froth floatation process is generally used for sulphide ores. So, this method is used for copper pyrites ( $ FeS_{2} $)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3905, 5, NULL, NULL, 'The correct order of boiling points for hydrogen halides is

A. HCl

B. HBr

C. HF

D. HI', NULL, '[{"text":"HF < HI < HBr < HCl","image_url":null,"alt":null},{"text":"HF < HCl < HBr < HI","image_url":null,"alt":null},{"text":"HF > HCl > HBr > HI","image_url":null,"alt":null},{"text":"HF > HI > HBr > HCl","image_url":null,"alt":null}]', NULL, 3, 'HF has exceptionally high boiling point due to intermolecular H-Bonding.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3906, 5, NULL, NULL, 'In the reaction

$ N_{2}(g) + 3H_{2}(g) \rightleftharpoons 2NH_{3}(g) $, $ \Delta_{r}H^{0} = -46.1kJ\ mol^{-1} $

The yield of ammonia is expected to be maximum at', NULL, '[{"text":"High temperature and low pressure","image_url":null,"alt":null},{"text":"High temperature and high pressure","image_url":null,"alt":null},{"text":"Low temperature and high pressure","image_url":null,"alt":null},{"text":"Low temperature and low pressure","image_url":null,"alt":null}]', NULL, 2, 'Formation of ammonia is an exothermic process so low temperature favors formation of ammonia forward direction. On increasing pressure, reaction moves in forward direction to increase the yield of ammonia.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3907, 5, NULL, NULL, 'The structure of $SF_{4}$ is', NULL, '[{"text":"Square planar","image_url":null,"alt":null},{"text":"Tetrahedral","image_url":null,"alt":null},{"text":"Trigonal bipyramidal","image_url":null,"alt":null},{"text":"Octahedral","image_url":null,"alt":null}]', NULL, 2, 'In SF_{4}, ''S'' atom is sp^{3}d hybridised So, its geometry is trigonal bipyramidal.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.255Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
