INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3930, 5, NULL, NULL, 'The strongest oxidizing agent amongst the following Ag⁺, Cu²⁺, Fe²⁺, Pb²⁺ is', NULL, '[{"text":"Ag⁺","image_url":null,"alt":null},{"text":"Cu²⁺","image_url":null,"alt":null},{"text":"Fe²⁺","image_url":null,"alt":null},{"text":"Pb²⁺","image_url":null,"alt":null}]', NULL, 0, 'Higher the value of reduction potential, higher will be the oxidizing power of the species.

$$ \mathrm{E_{red}^{\circ}}:\mathrm{Ag^{+}}>\mathrm{Cu^{2+}}>\mathrm{Pb^{2+}}>\mathrm{Fe^{2+}}>\mathrm{Mg^{2+}} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.270Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
