INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3932, 5, NULL, NULL, 'The emf of the cell Ag(s) | Ag⁺(1m) || Pb²⁺(1m) | Pb(s), is', NULL, '[{"text":"0.67V","image_url":null,"alt":null},{"text":"1.06V","image_url":null,"alt":null},{"text":"0.93V","image_url":null,"alt":null},{"text":"0.93V","image_url":null,"alt":null}]', NULL, 2, 'Anodic reaction: Ag $ \longrightarrow $ Ag $ ^{+} $ + e

Cathodic reaction: Pb $ ^{2+} $ + 2e $ \longrightarrow $ Pb.

Cell reaction: $ 2\mathrm{Ag} + \mathrm{Pb}^{2+} \longrightarrow \mathrm{Pb} + 2\mathrm{Ag}^{+} $

(s) (1m) (s) (1m)

$$ \begin{array}{rl}\therefore\quad\mathrm{E}_{\mathrm{cell}}=\mathrm{E}_{\mathrm{cell}}^{\circ}-\frac{\mathrm{RT}}{\mathrm{nF}}\ln\left[\frac{\mathrm{Ag}^{+}}{\mathrm{Pb}^{2+}}\right]^{2}\\=\mathrm{E}_{\mathrm{cell}}^{\circ}-\frac{2.303\mathrm{RT}}{2\mathrm{F}}2\log\left[\frac{\mathrm{Ag}^{+}}{\mathrm{Pb}^{2+}}\right]\\=\mathrm{E}_{\mathrm{cell}}^{\circ}-0.059\log\frac{1\mathrm{m}}{1\mathrm{m}}\\=\mathrm{E}_{\mathrm{cell}}^{\circ}\\=(-0.80-0.13)\mathrm{v}\quad=-0.93\mathrm{v}\end{array} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.270Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3933, 5, NULL, NULL, 'When Pb is added to an aqueous solution of a mixture of $ Cu^{2+} $ and $ Mg^{2+} $ ions, it is', NULL, '[{"text":"$ Cu^{2+} $ is reduced","image_url":null,"alt":null},{"text":"$ Mg^{2+} $ is reduced","image_url":null,"alt":null},{"text":"Cu is reduced","image_url":null,"alt":null},{"text":"$ Pb^{2+} $ is reduced","image_url":null,"alt":null}]', NULL, 0, '$ E_{\text{red}}^{\circ} : Cu^{2+} > Pb^{2+} > Mg^{2+} $

$ Cu^{2+} $ will be reduced and $ Pb^{2+} $ will be oxidized, since the reduction potential of $ Cu^{2+} $ is more than $ Pb^{2+} $.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.271Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3934, 5, NULL, NULL, 'The combination of electrodes which will give maximum value of $E^{\circ}$ cell at 298 K is', NULL, '[{"text":"Anode Cathode Ag Mg","image_url":null,"alt":null},{"text":"Anode Cathode Cu Fe","image_url":null,"alt":null},{"text":"Anode Cathode Mg Ag","image_url":null,"alt":null},{"text":"Anode Cathode Pb Mg $$ \\mathrm{form} \\cong \\mathrm{M} \\equiv \\frac{81}{1 \\times \\mathrm{A} \\mathrm{M}} \\times 52.0 = 85.0 $$ resonanz realog zweidst skl-svlosozib-sklf et gnibrozoA (b) zweicogz realog-non bns nvoloz zelog dfrw olduloz zs ni zelog-con ei omoo-n imvoloz zelog-non dfrw olduloz zuron (a) In筋柱上的筋柱侧向 $$ \\mathrm{t}=\\frac{k}{200\\mathrm{~S}}=\\frac{0\\left[R\\right]}{\\left[R\\right]}\\mathrm{gal}\\Leftarrow\\frac{0\\left[R\\right]}{\\left[R\\right]}\\mathrm{gal}\\frac{200\\mathrm{~S}}{1}=k $$","image_url":null,"alt":null}]', NULL, 2, '$ E_{\text{cell}} = E_{\text{Mg/Mg}^{2+}} + E_{\text{Ag}^+/\text{Ag}} = 2.36 + 0.80 = 3.16 \, \text{V} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.271Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3935, 7, NULL, NULL, 'Which of the following function(s) is/are SQL aggregate functions?

(A) Trim() (B) Max() (C) Count (D) Lower() (E) Avg()

Choose the correct answer from the options given below:

(a) (B) only (C) (B), (C) and (E) only (D) (B), (C), (D) and (E) only
2. Consider the given table and answer the question:

What will be the effect of following command?

Select Mname as "Name", Maddress as "residence" from Mother;', NULL, '[{"text":"It will change the field headings temporarily Mname to Name and Maddress to residence.","image_url":null,"alt":null},{"text":"It will give error message","image_url":null,"alt":null},{"text":"It will change all the Names, addresses to Name and residence","image_url":null,"alt":null},{"text":"It will change the field names Mname to name and Maddress to residence","image_url":null,"alt":null}]', NULL, 2, 'Average function: It is used to perform calculations on multiple rows of a single column of a table. It is also used to summerise the data.

Sql aggregate function:

Count () → returns the no. of rows

Sum () → returns the sum

Avg () → returns the average value

Max () → returns the largest value

Min () → returns the smallest value

First () → returns the first value

Last () → returns the last value

In the given question Trim (), Lower (), are not aggregate function rest are aggregate function that is (B) Max. (c) Count (), (E) Avg ().

So option (c) B. C. E is our Answer.

So, option (c) B, C, E is our Answer.', NULL, NULL, 2022, '/local-papers/assets/computer-science-2022/q01-table-1.jpg', 'Table for question 1', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.272Z', NULL, NULL, '[{"url":"/local-papers/assets/computer-science-2022/q01-table-1.jpg","alt":"Table for question 1","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3936, 7, NULL, NULL, 'To retrieve the given column from Mother table:

Name

Lata Sharma

Lovely Singh

Lavanya Mehra

The correct command is:', NULL, '[{"text":"Select Mname from Mother Where Mname is ''Lata Sharma'', ''Lovely Singh'', ''Lavanya Mehra''.","image_url":null,"alt":null},{"text":"Select Mname from Mother where Mname like ''%L'';","image_url":null,"alt":null},{"text":"Select Mname from Mother where Mname like ''L%'';","image_url":null,"alt":null},{"text":"Select Mname from Mother starting with L;","image_url":null,"alt":null}]', NULL, 2, 'Select Mname from Mother whose Mname like ''L%''; is correct because. ''Like'' is logical operator is sql.

- Like is used in SELECT, UPDATE and DELETE statements only.

- It filter the record from columns based on pattern specified in sql query. This can be done by using two wild card operator with keyword "like"

(i) % (percent sign) → matches zero, one, or more than one character.

(ii) _ (underscore) → matches only single character. Select Column i, column ii, column X from table Name where column LIKE pattern

Option (i) and (iv) are invalid queries.

Option (ii) will give Mname having word end''s with ''L''

Only (iii) is correct it will give these names only which starts with letter ''L'' only.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.273Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3937, 7, NULL, NULL, 'Which of the following query will change the name - ''Lata Sharma'' to ''Elina''?', NULL, '[{"text":"Update Mother where Mname = ''Lata Sharma'';","image_url":null,"alt":null},{"text":"Update Mother set Mname = ''Elina'' where Mname = ''Lata Sharma'';","image_url":null,"alt":null},{"text":"Alter table Mother set Mname = ''Elina'' where Mname = ''Lata Sharma'';","image_url":null,"alt":null},{"text":"Alter table Mname = ''Elina'' where Mname = ''Lata Sharma'';","image_url":null,"alt":null}]', NULL, 1, 'Update syntax

Update table-name SET column = value - 1, column = value 2..... where condition:

So, option (b) is correct.

UPDATE Mother Set Mname = ''Elina'' where Mname = ''Lata sharma'';

UPDATE → command is used to update any value in the column.

After → After is used when we want to add, drop Rename modify any attribute name/or column name.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.273Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
