INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3939, 7, NULL, NULL, 'Identify an application software which is required by a client to request any resource and to receive response of his request out of the following:', NULL, '[{"text":"Google","image_url":null,"alt":null},{"text":"Web Browser","image_url":null,"alt":null},{"text":"Website","image_url":null,"alt":null},{"text":"Web Page","image_url":null,"alt":null}]', NULL, 1, 'i. Google is search engine it is not any application software.

ii. Web Browser is client side used application software used to request and receive any resource and information in the form of text, audio, video, image format.

iii. Website is collection of webpages and related content that is identified by a common domain name and published an web server.

iv. Web page → A hyper text document on any world wide web (www). or single page in a website.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.274Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3940, 7, NULL, NULL, 'What is the output of the code given below?

List = [1, 2, 3]

List[3]', NULL, '[{"text":"NameError","image_url":null,"alt":null},{"text":"ValueError","image_url":null,"alt":null},{"text":"IndexError","image_url":null,"alt":null},{"text":"No Error, it will","image_url":null,"alt":null}]', NULL, 2, 'Index Error

List = [1, 2, 3]

List [3]

If we have a list 1, 2, 3, 4, 5 in python then the index starts from (0) and goes to (length -1).

- The first element of the list is stored at 0th index second element stored at $ 1^{th} $ index and so on.

So, List [0] gives 1

List [i] gives 2

List [2] gives 3

[List [3] gives 4] But we have only [1, 2, 3] in the list.

So, it will give error which is indexing error name [#index Error.]', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.274Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3941, 7, NULL, NULL, 'Which of the following offer secure communication?', NULL, '[{"text":"Radio waves","image_url":null,"alt":null},{"text":"Infrared","image_url":null,"alt":null},{"text":"Laser","image_url":null,"alt":null},{"text":"Microwaves","image_url":null,"alt":null}]', NULL, 0, '- One of the most common use of the radio waves is to establish a secure communication network between planes and air traffic control unit. Radiowaves are more secure than infrared, Laser, and microwaves,

- Radio wave have high wavelength and low frequency

Radio waves are used in RADAR, Satellite, air to air contact between planes etc.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.275Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3942, 7, NULL, NULL, 'Which of the following access mode is used to open binary file in read mode only?', NULL, '[{"text":"wb","image_url":null,"alt":null},{"text":"a","image_url":null,"alt":null},{"text":"rb","image_url":null,"alt":null},{"text":"r","image_url":null,"alt":null}]', NULL, 2, 'wb $ \rightarrow $ ''wb'' mode opens the file in binary formed for writing

- a $ \rightarrow $ ''a'' mode can only be written into and cannot be read from.

rb $ \rightarrow $ To open a file in binary formed, add ''b'' to the mode parameter, Hence, the ''rb'' mode opens the file in binary format for reading.

- r = read mode.

r = read.

w = write

b = binary.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.275Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3943, 7, NULL, NULL, 'Choose the correct statements about Database:

(A) Database schema is the design of database

(B) Database is the skeleton of the database that represents the structure

(C) Meta data is data about constraint

(D) We may not retrieve the data through queries', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(D) and (A) only","image_url":null,"alt":null}]', NULL, 0, '(A) → Database Schema is the logical design of database is correct.

(B) → Databox is the skeleton of the database that represents the structure.

Types of database Schema.

(i) Logical Schema

(ii) Physical Schema

(iii) View Schema

Option (c) is incorrect as metadata is data about data. Option (d) is false because we use queries to retrieve data from database.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.277Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3944, 7, NULL, NULL, 'Match List-I with List-II

(A) Bus Topology

(B) Star Topology

(C) Ring Topology

(D) Tree Topology

(E) List-II

Terms

(I) With Central Networking device like hub or switch.

(II) Each Node is connected to two other devices, one each and either side

(III) There are multiple branches and also known as hybrid topology

(IV) A single backbone shared among the nodes.

(A)(B)(C)(D)', NULL, '[{"text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null}]', NULL, 2, 'i. Bus Topology is a single backbone shared among the noces

ii. Star Topoloty is like central networking device like switch and hubs.

iii. Ring Topology: Each node is connected to two other devices, one each and either side.

iv. Tree topology: There are Multiple branches and also known as hybrid topology.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.278Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3945, 7, NULL, NULL, 'In context of network type Local Area Network (LAN), which of the following statement(s) are correct:

(A) It covers a small area, within a building or a campus

(B) Less congestion

(C) Less fault tolerance

(D) It operates on the principle of broadcasting

(E) Speed of LAN is slower than MAN and WAN', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'LAN $ \rightarrow $ Local Area network.

(A) LAN is a group of devices connected in small geographic area within building or a campus.

(B) LAN has ww congestion as compared to WAN

(C) LAN has higher fault tolerance.

(D) It operates on the principle of broadcasting.

(E) Speed of LAN is faster than MAN and WAN So, option (A, B, D) are correct but option (C and E) are wrong', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.278Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3946, 7, NULL, NULL, 'Identify the type of error which is raised when variable name is not defined?', NULL, '[{"text":"TypeError","image_url":null,"alt":null},{"text":"NameError","image_url":null,"alt":null},{"text":"ValueError","image_url":null,"alt":null},{"text":"SyntaxError","image_url":null,"alt":null}]', NULL, 1, 'i. TypeError: In Phyton TypeError is an Exception that occurs when the data type of an object in an operation is inappropriate.

ii. NameError: In Python NameError occurs when we try to access a variable or function that is not defined or before it is defined.

To solve the error, variable name should be spelled correctly and access the variable only after defining it.

iii. ValueError: It is an exception that occurs when a function receives an argument of the correct data type but an inappropriate value.

It usually occurs in mathematical operations that require certain kind of values.

iv. SyntaxError: It occurs when teh Interpreter encounters invalid syntax in code.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.279Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3947, 7, NULL, NULL, 'Which of the following is a 12 digit hexadecimal number that uniquely identifies a machine on a network?', NULL, '[{"text":"MAC address","image_url":null,"alt":null},{"text":"IP address","image_url":null,"alt":null},{"text":"Processor Number","image_url":null,"alt":null},{"text":"ISP Code","image_url":null,"alt":null}]', NULL, 0, 'i. Mac address: Media Access control (MAC) address is a 12 digit hexadecimal number assigned to each device connected to the network.

ii. IP address: IP address is a unique address that identifies a device on the internet or a local network.

iii. Processor number: It is four digit processor number, in which first digit represents the generation, Example 9800 is a $ 9^{th} $ gen processor, while one labelled 8800 is $ 8^{th} $ gen technology.

iv. ISP code: Internet Service provider (ISP) is a company that provides individuals and organizations access to the internet and other related services.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.280Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
