INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3975, 1, NULL, NULL, 'The two protagonists of the story are _ (Select the correct option)', NULL, '[{"text":"Both innocent and naive","image_url":null,"alt":null},{"text":"One is intelligent and the other a fool","image_url":null,"alt":null},{"text":"Both cunning and selfish","image_url":null,"alt":null},{"text":"One of them is demanding and greedy, the other always generous, sensitive and supportive","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.303Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3976, 1, NULL, NULL, 'How were the tree and the little boy related to each other? (Select the correct option)', NULL, '[{"text":"They were close contenders in their race to survive","image_url":null,"alt":null},{"text":"They were very close friends due to their very long association","image_url":null,"alt":null},{"text":"They were colleagues as they work together","image_url":null,"alt":null},{"text":"They were competitors in their need to fulfil their own needs.","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.303Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3977, 1, NULL, NULL, 'The story highlights a typical selfish human nature we are all familiar with. Identify it from the options given below:', NULL, '[{"text":"Compassion and benevolence","image_url":null,"alt":null},{"text":"Conservation of forests","image_url":null,"alt":null},{"text":"Mindless greed to possess more and more wealth","image_url":null,"alt":null},{"text":"Heartless and foolish exploitation of nature","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.304Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3978, 1, NULL, NULL, '"The stump of the unselfish tree burnt in the fire, softly humming a tune." means: (Select the right options from the given options)', NULL, '[{"text":"Every tree sings when it is burnt.","image_url":null,"alt":null},{"text":"The selfless tree felt no pain even in its acute suffering while dying, caring for others.","image_url":null,"alt":null},{"text":"The frail and wonderful tree fifed to forget its pain by humming","image_url":null,"alt":null},{"text":"The tree was a fool and was humming as it did not realize that it was dying.","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.304Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3979, 1, NULL, NULL, 'How would you define the relationship that the story illustrates? Select the correct answer from the following options.', NULL, '[{"text":"It was a mutual symbiotic relationship.","image_url":null,"alt":null},{"text":"It was a relationship based on deceit and treachery.","image_url":null,"alt":null},{"text":"It was an one sided relationship where the tree loved, cared for and supported the boy till its end.","image_url":null,"alt":null},{"text":"It was a disguised enmity. After reading the following passage, answer the questions which follow: I must say that beyond occasionally exposing me to laughter, my constitutional shyness has been of no great disadvantage to me. In fact, I can see that, on the contrary, it has been all to my advantage. My hesitancy in speech, which was once an annoyance, is now a pleasure. Its greatest pleasure has been that it has taught me the economy of words. I have naturally formed the habit of restraining my thoughts. And I can now give myself the certificate that a thoughtless word hardly ever escapes of my tongue or pen. I do not recollect ever having had to regret anything in my speech or writing. I have thus been spared many a mishap and waste of time. Experience has taught me that silence is part of the spiritual discipline of a votary of truth. Proneness to exaggerate, to suppress or modify the truth, wittingly or unwittingly, is a natural weakness of man and silence is necessary in order to surmount it. A man of few words will rarely be thoughtless in his speech; he will measure every word.","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.304Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3980, 1, NULL, NULL, 'The expression, "my constitutional shyness" in the given passage would mean _(Select the right answer from the options given below):', NULL, '[{"text":"Shyness mentioned in Article 1 in the Indian Constitution","image_url":null,"alt":null},{"text":"Shyness prescribed as a mark of our democracy in the preamble of our Constitution.","image_url":null,"alt":null},{"text":"The innate and natural shyness in the author","image_url":null,"alt":null},{"text":"A shyness that the author pretends to derive some evil advantages in life.","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.305Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3981, 1, NULL, NULL, 'The author as a matured individual believes that his shy nature brought him _ (Select the right answer from the options given below):', NULL, '[{"text":"Great advantage in life","image_url":null,"alt":null},{"text":"Unmatched joy and enchantment in life","image_url":null,"alt":null},{"text":"Disadvantage while performing rituals","image_url":null,"alt":null},{"text":"Media coverage","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.305Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3982, 1, NULL, NULL, 'From the options given below, select the one which will appropriately answer the following question: The author due to his shy nature _', NULL, '[{"text":"Would aggressively attack any and every crowd around him","image_url":null,"alt":null},{"text":"Worked hard to hide his stammer","image_url":null,"alt":null},{"text":"Naturally formed the habit of restraining his thoughts","image_url":null,"alt":null},{"text":"Became an ascetic.","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.305Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3983, 1, NULL, NULL, 'The author claims that _(Select the right answer from the options given below):', NULL, '[{"text":"He has rarely even spoken a ''thoughtless word due to his shy nature","image_url":null,"alt":null},{"text":"He always speaks without thinking because he is shy","image_url":null,"alt":null},{"text":"As a shy individual, he has become prone to nightmares","image_url":null,"alt":null},{"text":"His shy nature helped him become a great cricket player.","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.306Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3984, 1, NULL, NULL, 'From the options given below, select the one which answer the following question: Experience has taught the author that', NULL, '[{"text":"Silence is better than laughter to stay fit","image_url":null,"alt":null},{"text":"Silence is part of the spiritual discipline","image_url":null,"alt":null},{"text":"Silence is to be avoided at all costs","image_url":null,"alt":null},{"text":"Silence can never be attained by man","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.306Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3985, 1, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-IV, B-III, C-II, D-I","image_url":null,"alt":null},{"text":"A-II, B-I, C-IV, D-III","image_url":null,"alt":null},{"text":"A - III, B - IV, C - I, D - II","image_url":null,"alt":null},{"text":"A-I, B-II, C-III, D-IV After reading the passage, answer the questions that follow: Unhappiness and discontent spring not only from poverty. Man is a strange creature, fundamentally different from other animals. He has far horizons, invincible hopes, creative energies, spiritual powers. If they are left undeveloped and unsatisfied, he may have all the comforts which wealth can give, but will still feel that life is not worthwhile. The great humanist writers, Shaw and Wells, Arnold Bennett and Galsworthy, who are regarded as the prophets of the dawn, expose the foibles, inconsistencies and weaknesses of modern life, but they ignore the deeper currents and sometimes misrepresent them. At any rate, they give nothing in their place. In the void left by the removal of tradition, morality and religion, others are putting in vague sentiments of race and power. The modern mind is shaped by Rousseau''s Social Contract, Marx''s Capital, Darwin''s on the Origin of Species and Spengler''s The Decline of the West. The outward chaos and confusion of our life reflect the confusion of our hearts and minds. Constitutions, says Plato, \"are but the reflections in the outside world of the values which prevail in men''s minds.\" There must be a change in the ideals we cherish, in the values we adopt, before we can give social expression to them. We help to secure the future only to the extent to which we ourselves are changed. What is missing in our age is the soul: there is nothing wrong with the body. We suffer from sickness of spirit. We must discover our roots in the eternal and regain faith in the transcendent truth which will order life, discipline discordant elements, and bring unity and purpose into it. If not, when the floods come and the winds blow and beat upon our houses, it will fall.","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2022, '/local-papers/assets/english-2022-08-06-shift-1/q12-table-1.jpg', 'Table for question 12', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.307Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2022-08-06-shift-1/q12-table-1.jpg","alt":"Table for question 12","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3986, 1, NULL, NULL, 'The author implies that if the eternal values and ideals are not regained, then _(Select the right option)', NULL, '[{"text":"The world will be flooded","image_url":null,"alt":null},{"text":"The sky will fall","image_url":null,"alt":null},{"text":"The human civilization and society will be mined forever","image_url":null,"alt":null},{"text":"The earth Will get sucked into a black hole","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.307Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
