Q17. Match List I with List II', NULL, '[{"text":"A-III, B-IV, C-I, D-II","image_url":null,"alt":null},{"text":"A-I, B-II, C-III, D-IV","image_url":null,"alt":null},{"text":"A - II, B - III, C - IV, D - I","image_url":null,"alt":null},{"text":"A-IV, B-III, C-II, D-I","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, '/local-papers/assets/english-2022-08-06-shift-1/q16-table-1.jpg', 'Table for question 16', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.308Z', NULL, NULL, '[{"url":"/local-papers/assets/english-2022-08-06-shift-1/q16-table-1.jpg","alt":"Table for question 16","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
