INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4081, 1, NULL, NULL, 'From the passage It may be assumed that the narrator was a 15-year-old teenager without parents because the passage talks about. (select the correct option)', NULL, '[{"text":"Foster home for the narrator and other foster children","image_url":null,"alt":null},{"text":"Cleaning firepits","image_url":null,"alt":null},{"text":"Church and Chapels of Great Britain","image_url":null,"alt":null},{"text":"Malls of a Metropolitan city Read the following passage to answer Question. Workers and Slaves The Pharaohs may have believed that it was their links with the Gods that kept Egypt going, but really it was the hard work of the ordinary people. It was they who dug the soil, worked in the mines and quarries, sailed the boats on the river Nile, marched with the army into Syria or Nubia, cooked food and raised children. Slavery was not very important in ancient Egypt, but it did exist. Most of the slaves prisoners who had been captured during the many wars Egypt fought with their neighbors in the Near East. Slaves were usually treated well and were allowed to own property. Many Egyptian workers were serfs. This meant that their freedom was limited. They could be bought and sold along with the estates where they worked. Farmers had to be registered with the government. They have to sell crops at a fixed field lay under water; many workers were recruited into public building projects. Punishment for those who ran away was harsh.","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.365Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
