INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4143, 1, NULL, NULL, 'Re-arrange the given jumbled groups of words to make a meaningful sentence

A. The robbers when

B. They were in the lonely place

C. The police come upon

D. Dividing their booty', NULL, '[{"text":"D, B, C, A","image_url":null,"alt":null},{"text":"B, C, A, D","image_url":null,"alt":null},{"text":"C, A, B, D","image_url":null,"alt":null},{"text":"D, C, B, A","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Let''s try to arrange the sentence according to the options. Option a is wrong because the nonfinite clause "dividing their booty" cannot meaningfully modify the pronoun "they". It will be a dangling modifier. Option b is wrong because to put the fragment C after fragment B we need a conjunction or a punctuation. Option d is wrong because it would erroneously mean the police were dividing the booty. The correct option is (c).

Sequence: The police came upon the robbers when they were in the lonely place dividing their booty.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.402Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4144, 1, NULL, NULL, 'Rearrange the jumbled groups of words to make a meaningful sentence

A. On the tools you had been taught

B. The problem you face become more constructed

C. In management as you rise higher

D. And you can''t afford to fall back', NULL, '[{"text":"B, A, C, D","image_url":null,"alt":null},{"text":"C, A, D, B","image_url":null,"alt":null},{"text":"C, B, D, A","image_url":null,"alt":null},{"text":"A, B, C, D","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Let''s try to arrange the sentences according to the options. Option a is wrong because putting fragment A after fragment B doesn''t create any meaning ("constructor" means something which is obsolete). Option b is wrong because if we put fragment A after C it would mean that the sentence is talking about rising higher on tools which is again not meaningful. Option d is wrong because it would mean that the hypothetical person, "you" has been taught problems on the tools which is again not meaningful. The correct answer is option (c). Correct sequence: In management as you rise higher the problem you face become more constructed and you can''t afford to fall back on the tools you had been thought.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.402Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4145, 1, NULL, NULL, 'Rearrange the jumbled groups of words to make a meaningful sentence

A. The spirit of residents

B. Could dampen

C. Nor the subsequent fire

D. Neither the earthquake', NULL, '[{"text":"D, B, C, A","image_url":null,"alt":null},{"text":"D, C, B, A","image_url":null,"alt":null},{"text":"A, B, D, C","image_url":null,"alt":null},{"text":"A, D, A, B, E","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Let''s arrange the sentence according to the options. "Neither...nor" is a correlative conjunction which must be attached with either two similar clauses or two similar phrases or two similar words. As "could dampen" is the only verb phrases it must be common for both "earthquake" and "fire". Hence the sentence must start with "neither...nor" making the "Neither the earthquake nor the subsequent fire" subject (two subjects joined by a conjunction) of the sentence.

Correct sequence: Neither the earthquake nor the subsequent fire could dampen the spirit of residents.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.403Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
