INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4214, 18, NULL, NULL, 'Which of the following represents x, y = 64?', NULL, '[{"text":"$ 8 : x = 8 : y $","image_url":null,"alt":null},{"text":"x : 8 = y : 8","image_url":null,"alt":null},{"text":"x : 16 = y : 4","image_url":null,"alt":null},{"text":"32 : x = y : 2","image_url":null,"alt":null}]', NULL, 3, 'Solve using options:

32: x = y: 2

$ \Rightarrow \frac{32}{x} = \frac{y}{2} \Rightarrow 32 \times 2 = x \cdot y $

$ \Rightarrow x \cdot y = 64 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.457Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
