$ \Rightarrow \frac{5^{8.14}}{5^{5.14}} = \frac{5^{(8.14-5.14)}}{1} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.457Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4216, 18, NULL, NULL, 'The LCM and HCF of two numbers are 35 and 15 respectively. The product of these numbers is _.', NULL, '[{"text":"625","image_url":null,"alt":null},{"text":"525","image_url":null,"alt":null},{"text":"425","image_url":null,"alt":null},{"text":"325","image_url":null,"alt":null}]', NULL, 1, 'Product of two number = HCF × LCM

