INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4217, 18, NULL, NULL, 'The value of $3-3 \div 3$:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 0, '$ 3 - 3 \div 3 = 3 - \frac{3}{3} = 3 - 1 = 2 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.458Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4218, 18, NULL, NULL, 'The sum of the ages of 5 children born at intervals of 3 years each is 50 years. What is the age of the youngest child?', NULL, '[{"text":"4 years","image_url":null,"alt":null},{"text":"7 years","image_url":null,"alt":null},{"text":"9 years","image_url":null,"alt":null},{"text":"10 years","image_url":null,"alt":null}]', NULL, 0, 'Let ages of 5 children are x, x + 3, x + 6, x + 9 and x + 12 years.

According to question

$ x + x + 3 + 6 + x + 12 = 50 $

$ \Rightarrow 5x = 50 - 30 $

$ \Rightarrow 5x = 20 $

$ \Rightarrow x = 4 $ years (age of youngest child)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.459Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4219, 18, NULL, NULL, 'The average of 3 even consecutive integers is 12. What is their product?', NULL, '[{"text":"1640","image_url":null,"alt":null},{"text":"1690","image_url":null,"alt":null},{"text":"1650","image_url":null,"alt":null},{"text":"1680","image_url":null,"alt":null}]', NULL, 3, 'Let 3 even consecutive integers are x, x + 2, x + 4.

According to question,

$ \frac{x + x + 2 + x + 4}{3} = 12 $

$ \Rightarrow 3x + 6 = 36 $

$ \Rightarrow 3x = 36 - 6 = 30 $

$ \Rightarrow x = 10 $

Hence, their product = 10 × (10 + 2) × (10 + 4) = 1680', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.461Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4220, 18, NULL, NULL, 'Find the average of following numbers.', NULL, '[{"text":"18.25","image_url":null,"alt":null},{"text":"12.5","image_url":null,"alt":null},{"text":"19.1","image_url":null,"alt":null},{"text":"16.1","image_url":null,"alt":null}]', NULL, 2, 'Required average = $ \frac{\text{Sum of all numbers}}{Total given numbers} $

$ \frac{191}{10} = 19.1 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.462Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4221, 18, NULL, NULL, 'What percent decrease in salaries would exactly cancel the 20 percent increase?', NULL, '[{"text":"$15\\frac{1}{3}\\%$","image_url":null,"alt":null},{"text":"$14\\frac{2}{3}\\%$","image_url":null,"alt":null},{"text":"$16\\frac{2}{3}\\%$","image_url":null,"alt":null},{"text":"$33\\frac{1}{3}\\%$","image_url":null,"alt":null}]', NULL, 2, 'Let salary is 100.

$ \therefore \text{Increased salary} = \frac{100 \times 120}{100} = 120 $

120 - 100

$$ {\text{centage}}={\frac{120-100}{120}}\times100 $$

$$=\frac{20}{120}\times100$$

$$=16\frac{2}{3}\%$$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.463Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4222, 18, NULL, NULL, 'If 20% of a number is 30, then the number is:', NULL, '[{"text":"6","image_url":null,"alt":null},{"text":"150","image_url":null,"alt":null},{"text":"60","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null}]', NULL, 1, 'Let number is x.

According to question,

$ \frac{x \times 20}{100} = 30 $

$ \Rightarrow x = 30 \times 5 = 150 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.463Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4223, 18, NULL, NULL, 'An amount becomes its 3 times in 20 years. What is the rate of simple interest per annum?', NULL, '[{"text":"15%","image_url":null,"alt":null},{"text":"10%","image_url":null,"alt":null},{"text":"6.67%","image_url":null,"alt":null},{"text":"6%","image_url":null,"alt":null}]', NULL, 1, 'Let principal = a

$ \therefore $ Amount = 3a

S.I. = Amount - Principal

= 3a - a = 2a

$ \therefore $ S.I. = $ \left(\frac{P \times R \times T}{100}\right) $

2a = $ \left(\frac{a \times R \times 20}{100}\right) $

$ \Rightarrow $ Rate = $ \left(\frac{2a \times 100}{a \times 20}\right) $ % = 10% (Simple interest)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.464Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4224, 18, NULL, NULL, 'What will be the simple interest earned on an amount of

22000 in 8 months at $8\frac{1}{4}\%$ per annum?', NULL, '[{"text":"1013","image_url":null,"alt":null},{"text":"1012","image_url":null,"alt":null},{"text":"1210","image_url":null,"alt":null},{"text":"1215","image_url":null,"alt":null}]', NULL, 2, 'Principal = ₹ 22000

Rate = 8\frac{1}{4} = \frac{33}{4}\%

Time = 8 month = \frac{8}{12} = \frac{2}{3} years

Hence, S.I = \frac{P \times R \times T}{100}

= \frac{22000 \times 33 \times 2}{4 \times 3 \times 100} = ₹ 1210', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.465Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4225, 18, NULL, NULL, 'P, Q and R can complete a work in 12, 9 and 15 days respectively. Working together, they will complete the same work in:', NULL, '[{"text":"$ 3\\frac{39}{47} $ days","image_url":null,"alt":null},{"text":"$ 5\\frac{15}{42} $ days","image_url":null,"alt":null},{"text":"$ 3\\frac{38}{47} $ days","image_url":null,"alt":null},{"text":"$ 5\\frac{39}{47} $ days","image_url":null,"alt":null}]', NULL, 0, 'P''s one day work = $\frac{1}{12}$

Q''s one day work = $\frac{1}{9}$

R''s one day work = $\frac{1}{15}$

$\therefore (P+Q+R)''s$ one day work = $\frac{1}{12}+\frac{1}{9}+\frac{1}{15}$

$=\frac{15+20+12}{180}=\frac{47}{180}$

Hence, all together complete the same work in

$=\frac{180}{47}=3\frac{39}{47}$ days.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.466Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4226, 18, NULL, NULL, 'If 36 farmers can do a piece of work in 24 hours, In how many hours will 18 farmers do it?', NULL, '[{"text":"36 hours","image_url":null,"alt":null},{"text":"42 hours","image_url":null,"alt":null},{"text":"48 hours","image_url":null,"alt":null},{"text":"56 hours","image_url":null,"alt":null}]', NULL, 2, 'According to question,

$ M_{1} \times H_{1} = M_{2} \times H_{2} $

$ \Rightarrow 36 \times 24 = 18 \times H_{2} $

$ \Rightarrow H_{2} = \frac{36 \times 24}{18} = 48 \text{ hours} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.467Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4227, 18, NULL, NULL, 'A 400 m long train passes a railway platform in 20 seconds with speed 90 km/hr. What is the length of platform?', NULL, '[{"text":"105 m","image_url":null,"alt":null},{"text":"102 m","image_url":null,"alt":null},{"text":"99 m","image_url":null,"alt":null},{"text":"100 m","image_url":null,"alt":null}]', NULL, 3, 'Given, $ L_{1}=400\ m $

$ L_{2}= $ Length of platform = ?

T=20 sec

Train''s speed = 90 km/hr = $ 90 \times \frac{5}{18} = 25 $ m/s

According to question,

$ T=\frac{L_{1}+L_{2}}{S} $

$ \Rightarrow 20=\frac{400+L_{2}}{25} $

$ \Rightarrow 500=400+L_{2} $

$ \Rightarrow L_{2}=100m $ (Platform length)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.467Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4228, 18, NULL, NULL, 'Consider a watch becomes fast by 10 minutes everyday. By what percent does it become fast?', NULL, '[{"text":"$ \\frac{5}{12} $%","image_url":null,"alt":null},{"text":"$ \\frac{1}{6} $%","image_url":null,"alt":null},{"text":"$ \\frac{25}{36} $%","image_url":null,"alt":null},{"text":"2.5%","image_url":null,"alt":null}]', NULL, 2, 'Total minute in one day = 24 $ \times $ 60 = 1440 min.

Watch gain = 10 min every day

Hence, watch becomes fast = $ \frac{10}{1440} $ $ \times $ 100

$ =\frac{100}{144}=\frac{25}{36}\% $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.468Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4229, 18, NULL, NULL, 'Please read the following carefully and answer the questions:

The marks of 7 students in a unit test are given below:

9, 10, 7, 6, 9, 3, 5

The mode of the data is:', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null}]', NULL, 1, 'Arrange data in sequence = 3, 5, 6, 7, 9, 9, 10

