INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4230, 18, NULL, NULL, 'Please read the following carefully and answer the questions:

The marks of 7 students in a unit test are given below:

9, 10, 7, 6, 9, 3, 5

Median of the data is:', NULL, '[{"text":"6","image_url":null,"alt":null},{"text":"10","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null}]', NULL, 3, 'Arrange date in Ascending order

