Hence, Mean = $ \frac{\text{Sum of all numbers}}{\text{Total numbers}} = \frac{49}{7} = 7 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.470Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4232, 18, NULL, NULL, 'The value of x in the equation $2x-3=7-3x$', NULL, '[{"text":"10","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null}]', NULL, 1, '$ 2x - 3 = 7 - 3x $

$ \Rightarrow 2x + 3x = 7 + 3 $

$ \Rightarrow 5x = 10 $

$ \Rightarrow x = 2 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.471Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4233, 18, NULL, NULL, 'If lengths of two diagonals of rectangle are $(2x-3)$ cm and $(x+2)$ cm, then the value of $x$ is:', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"$\\frac{5}{2}$","image_url":null,"alt":null},{"text":"$\\frac{5}{3}$","image_url":null,"alt":null}]', NULL, 1, 'We know that length of diagonals of Rectangle are same.

$ \therefore 2x-3=x+2 $

$ \Rightarrow 2x-x=2+3 $

$ \Rightarrow x=5\ cm. $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.471Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4234, 18, NULL, NULL, 'If a square has a diagonal of length $ 6\sqrt{2} $ cm, then the area of square is:', NULL, '[{"text":"$ 48\\ cm^{2} $","image_url":null,"alt":null},{"text":"$ 72\\ cm^{2} $","image_url":null,"alt":null},{"text":"$ 16\\ cm^{2} $","image_url":null,"alt":null},{"text":"$ 36\\ cm^{2} $","image_url":null,"alt":null}]', NULL, 3, 'As we know that,

Side of square = $ \frac{\text{Diagonal}}{\sqrt{2}} $ = $ \frac{6\sqrt{2}}{\sqrt{2}} $ = 6 cm

Hence, area of square = (side) $ ^2 $= (6) $ ^2 $ = 36 cm $ ^2 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.472Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4235, 18, NULL, NULL, 'Please read the following carefully and answer the questions:

In the given figure ABCD is square and OE = 7 cm.

The perimeter of the figure is:', NULL, '[{"text":"42 cm","image_url":null,"alt":null},{"text":"44 cm","image_url":null,"alt":null},{"text":"64 cm","image_url":null,"alt":null},{"text":"86 cm","image_url":null,"alt":null}]', NULL, 2, 'Perimeter of semi-circle = $ \pi r = \frac{22}{7} \times 7 = 22 $ cm

Side of square (AD) = 7 + 7 = 14 cm.

Hence, perimeter of figure = 22 + DC + CB + BA = 22 + 14 + 14 + 14

=64 cm', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-06/q24-figure-1.jpg', 'Figure for question 24', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.472Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-06/q24-figure-1.jpg","alt":"Figure for question 24","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4236, 18, NULL, NULL, 'Please read the following carefully and answer the questions:

In the given figure ABCD is square and OE = 7 cm.

Length of diagonal of the square is :', NULL, '[{"text":"$ 14\\sqrt{2} $ cm","image_url":null,"alt":null},{"text":"$ 7\\sqrt{2} $ cm","image_url":null,"alt":null},{"text":"14 cm","image_url":null,"alt":null},{"text":"7 cm","image_url":null,"alt":null}]', NULL, 0, 'Side of square (AD) = 14 cm

Hence, length of diagonal = $ \sqrt{2} \times $ side

= $ 14\sqrt{2} $ cm', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-06/q25-figure-1.jpg', 'Figure for question 25', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.472Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-06/q25-figure-1.jpg","alt":"Figure for question 25","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4237, 18, NULL, NULL, 'Please read the following carefully and answer the questions: In the given ABCD is a square and OE = 7 cm

Area covered by the figure is:', NULL, '[{"text":"350 cm²","image_url":null,"alt":null},{"text":"273 cm²","image_url":null,"alt":null},{"text":"372 cm²","image_url":null,"alt":null},{"text":"237 cm²","image_url":null,"alt":null}]', NULL, 1, 'Side of square (AD) = 14 cm

$ \therefore $ Area of semicircle = $ \frac{1}{2}\pi r^{2} = \frac{1}{2} \times \frac{22}{7} \times 7 \times 7 = 77 \, cm^{2} $

And, area of square = (side) $ ^{2} $ = 14 $ ^{2} $ = 196 cm $ ^{2} $

Hence, area covered by figure = 77 + 196

= 273 cm $ ^{2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.473Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4238, 18, NULL, NULL, 'If two adjacent angles of a parallelogram are $(2x+30)^{\circ}$ and $(3x-15)^{\circ}$. Then the value of $x$ is:', NULL, '[{"text":"36","image_url":null,"alt":null},{"text":"39","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null},{"text":"35 General Mental Ability & Logical and Analytical Reasoning","image_url":null,"alt":null}]', NULL, 2, 'As we know that sum of two adjacent angle of parellogram is 180^{\circ}.

$ \therefore (2x+30)+(3x-15)=180^{\circ} $

$ \Rightarrow 5x+15=180^{\circ} $

$ \Rightarrow 5x=180-15=165^{\circ} $

$ \Rightarrow x=\frac{165}{5}=33^{\circ} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.473Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4239, 18, NULL, NULL, 'In the given question, select the related word from the alternatives:

