INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4242, 18, NULL, NULL, 'Among the four options given below, three have similarities. Find the odd one out.', NULL, '[{"text":"Sepals","image_url":null,"alt":null},{"text":"Petals","image_url":null,"alt":null},{"text":"Petiole","image_url":null,"alt":null},{"text":"Stamen","image_url":null,"alt":null}]', NULL, 2, 'Except Petiole, rest are part of flower.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.475Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4243, 18, NULL, NULL, 'Match List-I with List-II.

(A) OZ (B) KL (C) PK (D) DL Choose the correct answer from the options given below:', NULL, '[{"text":"(IV)","image_url":null,"alt":null},{"text":"(III)","image_url":null,"alt":null},{"text":"(IV)","image_url":null,"alt":null},{"text":"(I) (A) B C D (II) (I) (II) (III) (IV) (V) (I) (II) (III) (A) (II) (III) (IV) (V) (B) (I) (II) (III) (V) (C) (I) (II) (III) (V) (D) (I) (II) (III) (V) (A) (II) (III) (IV) (V) (B) (I) (II) (III) (V) (C) (I) (II) (III) (V) (D) (I) (II) (III) (V)","image_url":null,"alt":null}]', NULL, 2, 'The pattern is:

$ \mathrm{O}(15) + \mathrm{Z}(26) = 41 - (\mathrm{iv}) $

$ \mathrm{K}(11) + \mathrm{L}(12) = 23 - (\mathrm{i}) $

$ \mathrm{P}(16) + \mathrm{K}(11) = 27 - (\mathrm{ii}) $

$ \mathrm{D}(4) + \mathrm{L}(12) = 16 - (\mathrm{iii}) $

Hence, Kalam is maternal Uncle of Ravi.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.475Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
