INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4254, 18, NULL, NULL, 'Which number will replace the question mark?', NULL, '[{"text":"9","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 3, 'The pattern is:

$ 10 \times 3 = 5 \times 6 = 30 $

$ 9 \times 4 = 6 \times 6 = 36 $

$ 9 \times 8 = 18 \times ? = 72 $.

$ \Rightarrow ? = \frac{72}{18} = 4 $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-06/q44-figure-1.jpg', 'Figure for question 44', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.484Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-06/q44-figure-1.jpg","alt":"Figure for question 44","kind":"figure"},{"url":"/local-papers/assets/general-test-2022-08-06/q44-figure-2.jpg","alt":"Figure for question 44","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4255, 18, NULL, NULL, 'Find the missing number from the following given options:', NULL, '[{"text":"64","image_url":null,"alt":null},{"text":"63","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null},{"text":"66","image_url":null,"alt":null}]', NULL, 0, 'The pattern is:

$ (7+4)\times4=44 $

$ (6+3)\times4=36 $

$ (9+7)\times4=64 $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-06/q45-figure-1.jpg', 'Figure for question 45', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.485Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-06/q45-figure-1.jpg","alt":"Figure for question 45","kind":"figure"},{"url":"/local-papers/assets/general-test-2022-08-06/q45-figure-2.jpg","alt":"Figure for question 45","kind":"figure"},{"url":"/local-papers/assets/general-test-2022-08-06/q45-figure-3.jpg","alt":"Figure for question 45","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4256, 18, NULL, NULL, 'Five statements are given below followed by options consisting of three statements put together in a specific order. Choose the option which indicates a conclusion drawn from the preceding two statements.

(A) All models are Pretty

(B) Some models are popular

(C) Ruby is Pretty

(D) Ruby is a popular heroine

(E) Some popular girls are Pretty', NULL, '[{"text":"(A), (B), (E)","image_url":null,"alt":null},{"text":"(A), (C), (D)","image_url":null,"alt":null},{"text":"(D), (C), (A)","image_url":null,"alt":null},{"text":"(E), (D), (C)","image_url":null,"alt":null}]', NULL, 0, '(A) All model are pretty (Statement)

(B) Some models are popular (Statement)

(C) Some popular girls are pretty (Conclusion)

Hence, D represents doctors who are singers but not players.

(a) Hence, A represents the doctors who are players but not singers.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.486Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
