INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4285, 18, NULL, NULL, 'Which country successfully launched a new satellite named Shijian-21?', NULL, '[{"text":"South Korea","image_url":null,"alt":null},{"text":"Pakistan","image_url":null,"alt":null},{"text":"China","image_url":null,"alt":null},{"text":"UAE","image_url":null,"alt":null}]', NULL, 2, 'A satellite named Shijian-21, after the Chinese word "practice," was launched by China recently. China launched the debris mitigation technology satellite Shijian 21 from XSLC in Southwest China''s Sichuan province in October 2021.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.504Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4286, 18, NULL, NULL, 'The Reserve Bank of India has authorized _ to collect direct taxes on behalf of the Central Board of Direct Taxes (CBDT).', NULL, '[{"text":"Karur Vysya Bank (KVB)","image_url":null,"alt":null},{"text":"ICICI Bank","image_url":null,"alt":null},{"text":"HDFC Bank","image_url":null,"alt":null},{"text":"Axis Bank","image_url":null,"alt":null}]', NULL, 0, 'Karur Vysya Bank is a Scheduled Commercial Bank in India. The Reserve Bank of India has authorised Karur Vysya Bank (KVB) to collect direct taxes on behalf of the Central Board of Direct Taxes (CBDT). After obtaining the approval, KVB has started the integration process with the CBDT to collect direct taxes. The integration would enable the bank to allow its customers to remit the direct taxes through any branch/net banking/mobile banking services.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.504Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
