INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4288, 18, NULL, NULL, 'Which among the following are the ranks of commissioned officers in army?

(A) General

(B) Commodore

(C) Colonel

(D) Captain

(E) Group Captain', NULL, '[{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (E) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 0, 'From the above, only General, Colonel, Captain are the ranks of commissioned officers in army. While Commodore and Group Capitan are the ranks of commissioned officers in Navy and Air - Force similarly. Captain ranks above the rank of Commander and lower than a Commodore. It is equivalent to colonel in the Indian Army and Group Captain in the Indian Aix Force.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.505Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4289, 18, NULL, NULL, 'Which among the following are the part of forebrain?

(A) Cerebrum

(B) Cerebellum

(C) Medulla oblongata

(D) Hypothalamus

(E) Diencephalon', NULL, '[{"text":"(A), (D) and (E) only","image_url":null,"alt":null},{"text":"(A), (C) and (E) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'The lower part of brain stem forms the hindbrain which comprises of the medulla oblongata, pons, and cerebellum.

The cerebrum, diencephalon and hypothalamus are parts of the forebrain.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.506Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4290, 18, NULL, NULL, 'Which among the following enzymes is required to digest protein?', NULL, '[{"text":"Disaccharides","image_url":null,"alt":null},{"text":"Trypsin","image_url":null,"alt":null},{"text":"Amylase","image_url":null,"alt":null},{"text":"Lipase","image_url":null,"alt":null}]', NULL, 1, 'Protein digestive enzymes are pepsin and trypsin. They break down proteins into smaller peptides and amino acids. Pepsin is secreted by the gastric gland in the stomach whereas trypsin is secreted by Pancreas.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.506Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4291, 18, NULL, NULL, 'What is the name of the largest diamond in the world?', NULL, '[{"text":"The Cullinan","image_url":null,"alt":null},{"text":"The Kohinoor","image_url":null,"alt":null},{"text":"The Sergio","image_url":null,"alt":null},{"text":"The Woyie River","image_url":null,"alt":null}]', NULL, 0, 'The world''s biggest diamond called the "Star of Africa I," or "Cullinan," and at 530 carats, it is the

largest-cut fine-quality colorless diamond in the world. This breathtakingly beautiful stone is on display in the Tower of London as part of the Crown Jewels.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.507Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4292, 18, NULL, NULL, 'Which among the following countries have lion as their national emblem?

(A) Spain

(B) Belgium

(C) Norway

(D) France

(E) Netherlands', NULL, '[{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (E) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(C), (D) and (E) only","image_url":null,"alt":null}]', NULL, 1, 'Belgium, Norway and Netherlands have lion as their national emblem. The lion is the official national animal of Netherlands. The lion is widely regarded as a national symbol, the Netherlands. A heraldic lion can be seen on the Belgian coat of arms and can be seen as the country''s de facto national animal. A lion became the symbol of a Norwegian king at least as early as 1280. It still stands proudly on Norway''s Coat of Arms. Wild lions have likely never made their way to Norway, but European cave lions were once found as far north as Denmark.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.507Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4293, 18, NULL, NULL, 'First Field Marshal of India was:', NULL, '[{"text":"General KM Cariappa","image_url":null,"alt":null},{"text":"General SHFJ Manekshaw","image_url":null,"alt":null},{"text":"General V P Malik","image_url":null,"alt":null},{"text":"General Bipin Rawat","image_url":null,"alt":null}]', NULL, 1, 'War of 1971, and the first Indian Army officer to be promoted to the rank of field marshal.

Sol. Field Marshal equivalent to an admiral of the fleet in the Indian Navy and a, Marshal of the Indian Air Force in the Indian Air Force. General SHFJ Manekshaw was the first person who was promoted to the rank of Field Marshal. Field Marshal Sam Hormusji Framji Jamshedji Manekshaw is widely known as Sam Manekshaw and Sam Bahadur. He was the Chief of the Army Staff of the Indian Army during the Indo-Pakistani', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.508Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4294, 18, NULL, NULL, 'Which team has won the men''s cricket world cup the greatest number of times?', NULL, '[{"text":"West Indies","image_url":null,"alt":null},{"text":"India","image_url":null,"alt":null},{"text":"England","image_url":null,"alt":null},{"text":"Australia","image_url":null,"alt":null}]', NULL, 3, 'Australia is the most successful team in the ICC ODI World Cup, won the men''s cricket world cup number of times, i.e., 5 times and finished as the runner-up 2 times. The West Indies won the first two editions (1975 and 1979) and Australia won three in a row (1999, 2003 and 2007).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.509Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4295, 18, NULL, NULL, 'Find the correct option

M × N : 13 × 14 ∵ F × R : ?', NULL, '[{"text":"7 × 19","image_url":null,"alt":null},{"text":"5 × 17","image_url":null,"alt":null},{"text":"14 × 15","image_url":null,"alt":null},{"text":"6 × 18","image_url":null,"alt":null}]', NULL, 3, 'As we know that the place value in alphabet series of M and N are 13 & 14 respectively.

So, here F and R will be replaced by their place value.

Hence. $ F \times R = 6 \times 18 $.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.509Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4296, 18, NULL, NULL, '_ transforms source code into the machine-readable code by converting into line by line.', NULL, '[{"text":"Register","image_url":null,"alt":null},{"text":"Compiler","image_url":null,"alt":null},{"text":"Cache Memory","image_url":null,"alt":null},{"text":"Interpreter","image_url":null,"alt":null}]', NULL, 1, 'A compiler is a software program that translates high-level programming language code into machine-readable code or binary code. It converts the entire source code into an executable file in one go, translating the code line by line and generating an output that can be directly executed by the computer''s hardware. This process is known as compilation. The compiled code is typically faster and more efficient than interpreted code, as the translation is done before the program is run.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.511Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4297, 18, NULL, NULL, 'Match the List-I with List II.', NULL, '[{"text":"A-II, B-III, C-IV, D-I","image_url":null,"alt":null},{"text":"A-III, B-IV, C-I, D-II","image_url":null,"alt":null},{"text":"A-IV, B-II, C-I, D-III","image_url":null,"alt":null},{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-08-shift-1/q15-table-1.jpg', 'Table for question 15', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.511Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-08-shift-1/q15-table-1.jpg","alt":"Table for question 15","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4298, 18, NULL, NULL, 'The National Rail University has been established in India at:', NULL, '[{"text":"Gorakhpur","image_url":null,"alt":null},{"text":"Varanasi","image_url":null,"alt":null},{"text":"Malda","image_url":null,"alt":null},{"text":"Vadodara","image_url":null,"alt":null}]', NULL, 3, 'Institute (NRTI) is India''s first transport Institute located in Vadodara, Gujarat, India. This institute opened its doors to the batch of 103 students from 20 states in two fully-residential undergraduate courses in each year. This institute is presently located inside the lush green 55-acre campus of Ministry of Railways'' apex training institution, National Academy of Indian Railways as a makeshift arrangement.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.513Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4299, 18, NULL, NULL, 'Find the number of rectangles in the below figure:', NULL, '[{"text":"25","image_url":null,"alt":null},{"text":"125","image_url":null,"alt":null},{"text":"225","image_url":null,"alt":null},{"text":"55","image_url":null,"alt":null}]', NULL, 2, 'In the given figure, total number of rows = 5

