INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4303, 18, NULL, NULL, 'Find the angle between the hands of clock at 12:30?', NULL, '[{"text":"$ 165^{\\circ} $","image_url":null,"alt":null},{"text":"$ 170^{\\circ} $","image_url":null,"alt":null},{"text":"$ 175^{\\circ} $","image_url":null,"alt":null},{"text":"$ 155^{\\circ} $","image_url":null,"alt":null}]', NULL, 1, 'Angle between hands of clock = 180 - 30 $ \times \frac{1}{2} = 165^{\circ} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.516Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4304, 18, NULL, NULL, 'In a dice, 1, 2, 3 and 4 are written on the adjacent faces, in a clockwise order and 5 and 6 at the top and bottom. When three is at the top, what will be at the bottom?', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 0, 'The six faces are labeled as

Face I - 1

Face IV - 2

Face III - 3

Face II - 4

Face V - 5

Face VI - 6

Therefore, 1 appears opposite to 3.

Hence, when 3 is at the top, then 1 will be at the bottom.', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-08-shift-1/q23-figure-1.jpg', 'Figure for question 23', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.517Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-08-shift-1/q23-figure-1.jpg","alt":"Figure for question 23","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
