52, 58, 60, 66, 68, 74, ...', NULL, '[{"text":"74","image_url":null,"alt":null},{"text":"76","image_url":null,"alt":null},{"text":"78","image_url":null,"alt":null},{"text":"80","image_url":null,"alt":null}]', NULL, 1, 'The pattern is +6, +2, +6, +2 and so on. So missing term = 74 + 2 = 76', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.522Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4319, 18, NULL, NULL, 'Complete the series; 8192, 2048,...,?..., 128, 32, 8', NULL, '[{"text":"256","image_url":null,"alt":null},{"text":"248","image_url":null,"alt":null},{"text":"1024","image_url":null,"alt":null},{"text":"512","image_url":null,"alt":null}]', NULL, 3, 'The pattern is as follows:

8192 2048 ? 128 32 8

Here, $2^{\mathrm{nd}}$ term = $1^{\mathrm{st}}$ term / 4

$5^{\mathrm{th}}$ term = $4^{\mathrm{th}}$ term / 4

$6^{\mathrm{th}}$ term = $5^{\mathrm{th}}$ term / 4

