INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4324, 18, NULL, NULL, 'What is the value of x if 4 : x = x : 16', NULL, '[{"text":"16","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null}]', NULL, 1, 'It is given that,

