INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4325, 18, NULL, NULL, 'If $P = \text{₹}2000$, $R = 5\%$ per annual, $T = 5$ year

A. Total sum of amount = ₹2200

B. SI = ₹200

C. SI = ₹500

D. Total sum of amount = 2500', NULL, '[{"text":"C and D Only","image_url":null,"alt":null},{"text":"A and C Only","image_url":null,"alt":null},{"text":"B and C Only","image_url":null,"alt":null},{"text":"A and D Only","image_url":null,"alt":null}]', NULL, 0, 'P = 2000, R = 5%, T = 5 year

As we know that,

$ SI = \frac{(P \times R \times T)}{100} $

$ = \frac{(2000 \times 5 \times)}{100} $

= ₹500

Total amount = 2000 + 500 = 2500', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.525Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4326, 18, NULL, NULL, 'Find the LCM of $ \frac{3}{5} $, $ \frac{4}{9} $ and $ \frac{5}{8} $ is', NULL, '[{"text":"45","image_url":null,"alt":null},{"text":"55","image_url":null,"alt":null},{"text":"60","image_url":null,"alt":null},{"text":"65","image_url":null,"alt":null}]', NULL, 2, '$$ \begin{array}{r l}{\mathrm{S o l.}}&{\mathrm{L C M~o f~f r a c t i o n}=\frac{\mathrm{L C M~o f~N u m e r a t o r}}{\mathrm{H C F~o f~D e n o m i n t o r}}}\\ &{=\frac{L C F\left(3,4,5\right)}{H C F\left(5,8,9\right)}=\frac{60}{1}}\\ &{=60}\end{array} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.525Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4327, 18, NULL, NULL, 'In a swimming pool measuring 80 m × 60 m, 120 men take a dip. If the average displacement of water by a man is 6 m³, then the rise in water level is -', NULL, '[{"text":"0.25 m","image_url":null,"alt":null},{"text":"0.10 m","image_url":null,"alt":null},{"text":"0.15 m","image_url":null,"alt":null},{"text":"0.35 m","image_url":null,"alt":null}]', NULL, 2, 'It is given that,

Length of swimming pool = 80m

Breadth of swimming pool - 60m

Let the depth of swimming pool = D m

Volume of water displaced = Displacement of water

by 120 men.

$ 80 \times 60 \times D = 120 \times 6 $

$ 4800 \times D = 720 $

D = 0.15 m', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.528Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4328, 18, NULL, NULL, 'The average age of group of 5 friends is 32 years. The youngest friend amongst them is 4 years old. What was the average age of the group at the time of birth of the youngest friend?', NULL, '[{"text":"36 years","image_url":null,"alt":null},{"text":"35 years","image_url":null,"alt":null},{"text":"34 years","image_url":null,"alt":null},{"text":"33 years","image_url":null,"alt":null}]', NULL, 1, 'Given that,

The average age of 5 fiend = 32 years

So, sum of their ages = $ 32 \times 5 = 160 $ years

The youngest friend is 4 years old, that means

youngest was born 4 years ago.

Now 4 years ago,

Sum = 160 - (4 $ \times $ 5) = 160 - 20 = 140 years

So, the average age of group at the time of the birth

of youngest one = 140/4 = 32 years

Hence, option B is correct answer.

