INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4329, 18, NULL, NULL, 'A and B are two points in a river. Point X and Y divide the line AB in three equal parts. Let the flow of the river is from A to B. The ratio of the time taken to row from point A to Y and from B to Y is 3:4. Find the ratio of the speed of the boat upstream to the flow of the river.', NULL, '[{"text":"5:6","image_url":null,"alt":null},{"text":"6:5","image_url":null,"alt":null},{"text":"4:5","image_url":null,"alt":null},{"text":"5:4","image_url":null,"alt":null}]', NULL, 1, 'AX = XY = YB

Ratio of time taken by boat to go from A to Y and B

to Y = 3 : 4

As we know that,

Speed of the boat going downstream = (Speed of the boat + Speed of the current)

Speed of the boat going upstream = (Speed of the boat - Speed of the current)

Time = Distance/Speed

Let AX = XY = BY = d

Let the speed of the boat = a km/h

Let the speed of the current = b km/h

As per the question:

$$ 2d/(a+b)\div d/(a-b)=3/4 $$

$$ \Rightarrow2(a-b)/(a+b)=3/4 $$

$$ \Rightarrow11b=5a $$

$$ a/b=11/5 $$

Sol. It is given that,

Time taken by A and B = 30 days

Time taken by C and B = 10 days

Time taken by A and C = 5 days

Let total work be 30 units (LCM of 30, 10 and 5).

$ (A+B)'' $s one day work = 30/30=1 units

$ (B+C)'' $s one day work = 30/10=3 units

$ (C+A)'' $s one day work = 30/5=6 units

Adding all three equations,

$ 2A+2B+2C=10 $

$ 2(A+B+C)=10 $

$ A+B+C=5 $

So,

$ (A+B+C)'' $s one day work = 5 units

So, time taken by them together to finish the task = 30/5 = 6 days.

337. Ans. (b)

Sol. Let the distance = X km

Time taken to cover the distance by a cycle = X/10 hr.

And time taken to cover the distance by a car = X/50 hr.

So, Average speed = $ \frac{\text{Total distance}}{\text{Total time}} $

= $ \frac{\frac{2X}{X}+\frac{X}{10}+50}{1000} $ = 16.66 km/h

Sol. 70% of 100 = (70/100) of 100 = 70 marks

40% of 50 = (40/100) of 50 = 20 marks

60% of 150 (60/100) of 150 = 90 marks

So, marks secured = 70 + 20 + 90 = 180 marks

And Total marks = 100 + 50 + 150 = 300 marks

So, required percentage = (180/300) × 100 = 60%

$$(a+b)^2 = 5 + 2\sqrt{6}$$
From the given equation possible values of a and b are $\sqrt{2}$ and $\sqrt{3}$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.529Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4330, 18, NULL, NULL, 'If $ x - \frac{1}{x} = 3 $ then the value of $ x^{2} + \frac{1}{x^{2}} $ is', NULL, '[{"text":"9","image_url":null,"alt":null},{"text":"11","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null}]', NULL, 1, '$(x - 1/x)^2 = x^2 + 1/x^2 - 2 \times x \times 1/x$
So, $3^2 = x^2 + 1/x^2 - 2$
$x^2 + 1/x^2 = -9 + 2 = 11$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.530Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
