INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4334, 18, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-IV, B-II, C-III, D-I","image_url":null,"alt":null},{"text":"A-III, B-IV, C-II, D-I","image_url":null,"alt":null},{"text":"A-I, B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-II, B-III, C-IV, D-I","image_url":null,"alt":null}]', NULL, 3, 'From the given options, option D is perfect match of areas of given figures.', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-08-shift-1/q66-figure-1.jpg', 'Figure for question 66', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.532Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-08-shift-1/q66-figure-1.jpg","alt":"Figure for question 66","kind":"figure"},{"url":"/local-papers/assets/general-test-2022-08-08-shift-1/q66-table-2.jpg","alt":"Table for question 66","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4335, 18, NULL, NULL, 'The diameter of a circle whose area is numerically 110 more than its circumference is', NULL, '[{"text":"5 units","image_url":null,"alt":null},{"text":"7 units","image_url":null,"alt":null},{"text":"14 units","image_url":null,"alt":null},{"text":"10 units","image_url":null,"alt":null}]', NULL, 1, 'As we know that, area of circle = $\pi r^2$
And circumference = $2\pi r$
As per the question,
$\pi r^2 = 2\pi r + 110$
$\pi r^2 - 2\pi r = 110$
$\pi r(r - 2) = 110$
$r(r - 2) = 7 \times 5$
So, $r = 7$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.532Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4336, 18, NULL, NULL, 'If $m-n=16$ and $m^{2}+n^{2}=400$, the value of mn is =', NULL, '[{"text":"72","image_url":null,"alt":null},{"text":"25","image_url":null,"alt":null},{"text":"144","image_url":null,"alt":null},{"text":"192","image_url":null,"alt":null}]', NULL, 0, 'As we know that,
$(m - n)^2 = m^2 + n^2 - 2mn$
$16^2 = 400 - 2mn$
$2mn = 400 - 256$
$2mn = 144$
$mn = 72$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.533Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4337, 18, NULL, NULL, 'The value of ''y'' in the question 2x + 3y - 7 = 0

if x = -3/2', NULL, '[{"text":"10","image_url":null,"alt":null},{"text":"10/3","image_url":null,"alt":null},{"text":"4/3","image_url":null,"alt":null},{"text":"13/3 Direction for question 70 to 72: From the graph given below, answer the following question.","image_url":null,"alt":null}]', NULL, 1, 'Given that,
$2x + 3y - 7 = 0$ if $x = -(3/2)$
$-2(3/2) + 3y - 7 = 0$
$-3 + 3y - 7 = 0$
$3y - 10 = 0$
$3y = 10$
$y = 10/3$
Hence, option b is correct option.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.533Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4338, 18, NULL, NULL, 'The total number of people owing books more than ''40'' is', NULL, '[{"text":"60","image_url":null,"alt":null},{"text":"31","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null},{"text":"30","image_url":null,"alt":null}]', NULL, 1, 'The total number of people owing books more than $ 40 = 14 + 10 + 7 = 31 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.534Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
