INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4340, 18, NULL, NULL, 'The total number of people surveyed is', NULL, '[{"text":"16","image_url":null,"alt":null},{"text":"56","image_url":null,"alt":null},{"text":"54","image_url":null,"alt":null},{"text":"55 Direction for questions 73 to 75: From the given diagram, answer the following question.","image_url":null,"alt":null}]', NULL, 2, 'The total number of people surveyed = 16 + 14 + 10 + 8 + 7 = 55', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.534Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4341, 18, NULL, NULL, '''AC'' is 23 cm in the adjoining figure. Consider the figure and answer the questions', NULL, '[{"text":"133 cm²","image_url":null,"alt":null},{"text":"140 cm²","image_url":null,"alt":null},{"text":"70 cm²","image_url":null,"alt":null},{"text":"66.5 cm²","image_url":null,"alt":null}]', NULL, 3, 'The area of DGFE (here, GF=h=7 cm)
= 1/2(a + b) × h = 1/2 (10 + 9) × 7
= 1/2 × 19 × 7 = 66.5 cm²', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-08-shift-1/q73-figure-1.jpg', 'Figure for question 73', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.535Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-08-shift-1/q73-figure-1.jpg","alt":"Figure for question 73","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4342, 18, NULL, NULL, 'The area of $ \Delta DBC $ is DB is a straight line', NULL, '[{"text":"$ 32.5 \\, cm^{2} $","image_url":null,"alt":null},{"text":"$ 65 \\, cm^{2} $","image_url":null,"alt":null},{"text":"$ 25 \\, cm^{2} $","image_url":null,"alt":null},{"text":"$ 15 \\, m^{2} $","image_url":null,"alt":null}]', NULL, 0, 'Area of triangle
