= 1/2 × 13 × 5 = 32.5 cm²', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.535Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4343, 18, NULL, NULL, 'The total area of figure is', NULL, '[{"text":"184.5 cm²","image_url":null,"alt":null},{"text":"205 cm²","image_url":null,"alt":null},{"text":"175.5 cm²","image_url":null,"alt":null},{"text":"153 cm² SOLUTIONS","image_url":null,"alt":null}]', NULL, 2, 'Area of figure = area ΔDBC + area ΔAGB + area
ΔEFA + Area of rec. DGFE
