INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4344, 18, NULL, NULL, 'HCF of first five odd natural numbers is:', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 3, 'First five odd natural numbers are 1, 3, 5, 7, 9. HCF is the highest common factor of these numbers.

Hence, HCF is 1.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.538Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4345, 18, NULL, NULL, 'The value of $4-3\div3+5$', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 3, '$ 4 - 3 \div 3 + 5 = 4 - 1 + 5 $

$ \Rightarrow $ 9 - 1 = 8', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.538Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4346, 18, NULL, NULL, 'Common factor of $2a^{2}b$, $4ab^{2}$, $6ac^{2}$', NULL, '[{"text":"2ab","image_url":null,"alt":null},{"text":"2a","image_url":null,"alt":null},{"text":"2abc","image_url":null,"alt":null},{"text":"2b","image_url":null,"alt":null}]', NULL, 1, 'Factor of $2a^{2}b = 2 \times a \times a \times b$

Factor of $4ab^{2} = 2 \times 2 \times a \times b \times b$

Factor of $6ac^{2} = 2 \times 3 \times a \times c \times c$

Hence, common factor $=2 \times a = 2a$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.538Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4347, 18, NULL, NULL, 'The average of 3 consecutive odd numbers is 65. What is the ratio of these numbers?', NULL, '[{"text":"61:63:65","image_url":null,"alt":null},{"text":"59:61:63","image_url":null,"alt":null},{"text":"63:65:67","image_url":null,"alt":null},{"text":"65:67:69","image_url":null,"alt":null}]', NULL, 2, 'Let three consecutive odd numbers are x, x+2, x+4. According to question,

$ \frac{x+x+2+x+4}{3}=65 $

$ \Rightarrow 3x+6=195 \Rightarrow 3x=195-6=189 $

$ \Rightarrow x=\frac{189}{3}=63 $

Hence, ratio of three numbers = 63 : 65 : 67

Hence, ratio of three numbers = 63 : 65 : 67', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.539Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4348, 18, NULL, NULL, 'The sum of the ages of father and his son is 45 years. Five years ago, the product of their ages was 34. The age of father is:', NULL, '[{"text":"40 years","image_url":null,"alt":null},{"text":"45 years","image_url":null,"alt":null},{"text":"39 years","image_url":null,"alt":null},{"text":"38 years","image_url":null,"alt":null}]', NULL, 2, '''If the age of father is x years and age of son is y years.

According to question,

$ x + y = 45 $

$ \ldots (i) $

$ (x - 5)(y - 5) = 34 $

$ \Rightarrow $ xy - 5x - 5y + 25 = 34

$ \Rightarrow $ xy - 5(x + y) = 34 - 25 = 9

$ \Rightarrow $ xy = 9 + 5 $ \times $ 45 [From eqn. (i)]

$ \Rightarrow $ xy = 234

$ \ldots (ii) $

From eq $ ^{n} $ (i) and (ii)

$ \frac{234}{y} + y = 45 $

$ \Rightarrow $ y $ ^{2} $ - 45y + 234 = 0

$ \Rightarrow $ y $ ^{2} $ - 39y - 6y + 234 = 0

$ \Rightarrow $ y(y - 39) - 6(y - 39) = 0

$ \Rightarrow $ y = 39, 6 (very less age)

Hence, father''s age is 39 years.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.539Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4349, 18, NULL, NULL, 'Sum of the ages of 4 children bom at the intervals of 4 years each is 52 years. What is the age of the eldest one?', NULL, '[{"text":"7 years","image_url":null,"alt":null},{"text":"14 years","image_url":null,"alt":null},{"text":"19 years","image_url":null,"alt":null},{"text":"24 years","image_url":null,"alt":null}]', NULL, 2, 'Let age of four children are x, x+4, x+8 and x+12 years. According to question,

x+x+4+x+8+x+12=52

$ \Rightarrow 4x=52-24=28 \Rightarrow x=\frac{28}{4}=7 $

Hence age of the eldest one = 7+12=19 years', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.540Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4350, 18, NULL, NULL, 'What is the value of x. if x% of 142 + 30% of 280 = 368', NULL, '[{"text":"150","image_url":null,"alt":null},{"text":"200","image_url":null,"alt":null},{"text":"175","image_url":null,"alt":null},{"text":"225","image_url":null,"alt":null}]', NULL, 1, '$ \frac{x}{100} \times 142 + \frac{30}{100} \times 280 = 368 $

$ \Rightarrow 142x + 8400 = 368 \times 100 = 36800 $

$ \Rightarrow 142x = 36800 - 8400 = 28400 $

$ \Rightarrow x = \frac{28400}{142} = 200 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.540Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4351, 18, NULL, NULL, 'If 0.03 is X% of 0.3, then the value of X is:

(a) 30

(b) 10

(c) 3

(d) 9

Simple interest of ₹ 9000 at 5% per annum for 6 months is:', NULL, '[{"text":"₹ 235","image_url":null,"alt":null},{"text":"₹ 245","image_url":null,"alt":null},{"text":"₹ 205","image_url":null,"alt":null},{"text":"₹ 225","image_url":null,"alt":null}]', NULL, 1, '$ \frac{x}{100} \times 0.3 = 0.03 $

$ \Rightarrow x = \frac{0.03}{0.3} \times 100 = \frac{3}{100} \times \frac{10}{3} \times 100 $

$ \Rightarrow x = 10\% $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.540Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4352, 18, NULL, NULL, 'A can complete a work in 16 days. B can complete the same work in 8 days. If both of them come together, then in how many days can they complete the same work?', NULL, '[{"text":"$ 2\\frac{1}{3} $ days","image_url":null,"alt":null},{"text":"$ 5\\frac{1}{3} $ days","image_url":null,"alt":null},{"text":"$ 7\\frac{1}{3} $ days","image_url":null,"alt":null},{"text":"$ 6\\frac{1}{3} $ days","image_url":null,"alt":null}]', NULL, 1, 'A''s one day work = $ \frac{1}{16} $

B''s one day work = $ \frac{1}{8} $

$ \therefore $ (A + B)''s one day work = $ \frac{1}{16} + \frac{1}{8} = \frac{3}{16} $

Hence, A and B together complete the same work in $ \frac{16}{3} = 5\frac{1}{3} $ days', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.541Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4353, 18, NULL, NULL, 'A train 420 m long passes a pole in 20 seconds. What is the speed of the train?', NULL, '[{"text":"20 m/s","image_url":null,"alt":null},{"text":"22 m/s","image_url":null,"alt":null},{"text":"21 m/s","image_url":null,"alt":null},{"text":"24 m/s","image_url":null,"alt":null}]', NULL, 2, 'Train''s speed = $ \frac{\text{Length of train}}{\text{Time taken to pass pole}} $ = $ \frac{420}{20} $ = 21 m/s', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.541Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4354, 18, NULL, NULL, 'If 900 m long train crosses 700 in long platform in 1 minute, then speed of the train in kilometer per hour is:', NULL, '[{"text":"$ \\frac{80}{3} $ km/h","image_url":null,"alt":null},{"text":"96 km/h","image_url":null,"alt":null},{"text":"15 km/h","image_url":null,"alt":null},{"text":"$ \\frac{35}{3} $ km/h","image_url":null,"alt":null}]', NULL, 1, 'Total Length = 900 + 700 = 1600 m

Time = 1 min = 60 sec

Hence, speed of train = $ \frac{1600}{60} = \frac{160}{6} $ m/s

$ =\frac{160}{6} \times \frac{18}{5} = 32 \times 3 = 96 $ km/hr.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.542Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4355, 18, NULL, NULL, 'If $ x^{2} + 9y^{2} - 6xy = 0 $, then x: y is equal to:', NULL, '[{"text":"3:2","image_url":null,"alt":null},{"text":"1:3","image_url":null,"alt":null},{"text":"3:1","image_url":null,"alt":null},{"text":"2:3","image_url":null,"alt":null}]', NULL, 2, '$ x^{2}+9y^{2}-6xy=0 $

$ \Rightarrow $ $ x^{2}+(3y)^{2}-2\times x\times3y=0 $

$ \Rightarrow $ $ (x-3y)^{2}=0 $ $ [\because a^{2}-2ab+b^{2}=(a-b)^{2}] $

$ \Rightarrow $ x-3y=0

$ \Rightarrow $ x=3y

$ \Rightarrow $ $ \frac{x}{y}=\frac{3}{1} $

Hence, x:y=3:1', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.543Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4356, 18, NULL, NULL, 'In the formula "Work = Fs cos θ", if angle θ between force and displacement is more than 90°, the net work done will be:', NULL, '[{"text":"Double","image_url":null,"alt":null},{"text":"Positive but not double","image_url":null,"alt":null},{"text":"Negative","image_url":null,"alt":null},{"text":"Zero","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.544Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4357, 18, NULL, NULL, 'The factors of $4x^{2}-8x+3$ are', NULL, '[{"text":"$(2x-3)(2x+1)$","image_url":null,"alt":null},{"text":"$(2x+3)(2x-1)$","image_url":null,"alt":null},{"text":"$(2x+3)(2x+1)$","image_url":null,"alt":null},{"text":"$(2x-3)(2x-1)$","image_url":null,"alt":null}]', NULL, 3, '$ 4x^{2}-8x+3 $

=4x^{2}-6x-2x+3

=2x(2x-3)-1(2x-3)

=(2x-1)(2x-3)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.546Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4358, 18, NULL, NULL, 'If the edge of a cube is 17 cm. then the volume is:', NULL, '[{"text":"$ 4813 \\, cm^{3} $","image_url":null,"alt":null},{"text":"$ 4913 \\, cm^{3} $","image_url":null,"alt":null},{"text":"$ 4713 \\, cm^{3} $","image_url":null,"alt":null},{"text":"$ 5913 \\, cm^{3} $","image_url":null,"alt":null}]', NULL, 1, 'Volume of the cube = (Edge)$^{3}$

= (17)$^{3}$ = 4913 cm$^3$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.546Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4359, 18, NULL, NULL, 'If the base radius of a cone is 7 cm and height of it is 14 cm. then:

A. Slant height = $6\sqrt{5}$ cm

B. Slant height = $7\sqrt{5}$ cm

C. Volume = $718.67\mathrm{~cm}^{3}$

D. Volume = $708.66\mathrm{~cm}^{3}$

E. Ratio of height and slant height = 2:$\sqrt{5}$', NULL, '[{"text":"A, C and D only","image_url":null,"alt":null},{"text":"B, C and E only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"A, C and E only","image_url":null,"alt":null}]', NULL, 1, 'Cone''s radius (r) = 7 cm

Cone''s height (h) = 14 cm

$\therefore$ Slant height ($l$) = $\sqrt{(r)^2 + (h)^2} = \sqrt{(7)^2 + (14)^2}$

= $7\sqrt{5}$ cm.

And, volume of cone = $\frac{1}{3}\pi r^2 h = \frac{1}{3} \times \frac{22}{7} \times 7 \times 7 \times 14$

= $\frac{2156}{3} = 718.67$ cm$^3$

Ratio of height and slant height

= $\frac{h}{l} = \frac{14}{7\sqrt{5}} \Rightarrow 2 : \sqrt{5}$

Hence, only B, C and E are the correct answers.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.547Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4360, 18, NULL, NULL, 'In the given figure AOB is a straight line. the value of x is:', NULL, '[{"text":"60","image_url":null,"alt":null},{"text":"70","image_url":null,"alt":null},{"text":"50","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null}]', NULL, 2, '$ (x+55)^{\circ}+(2x-25^{\circ})=180^{\circ} $ [SupplementaryAngle]

$ \Rightarrow $ $ 3x+30^{\circ}=180^{\circ} $

$ \Rightarrow $ $ 3x=180-30=150 \Rightarrow x=\frac{150}{3}=50 $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-18/q19-figure-1.jpg', 'Figure for question 19', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.548Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-18/q19-figure-1.jpg","alt":"Figure for question 19","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4361, 18, NULL, NULL, 'Area of the triangular region FDE is:', NULL, '[{"text":"$ 1000 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 1250 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 2400 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 1600 \\, m^{2} $","image_url":null,"alt":null}]', NULL, 1, 'Area of triangular region FDE = $ \frac{1}{2} \times $ Base $ \times $ Height

