INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4362, 18, NULL, NULL, 'Area of region ACDF is:', NULL, '[{"text":"$ 3750 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 3500 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 3250 \\, m^{2} $","image_url":null,"alt":null},{"text":"$ 3000 \\, m^{2} $","image_url":null,"alt":null}]', NULL, 0, 'In $ \Delta ABC $,

$ (AC)^{2} = (AB)^{2} + (BC)^{2} $ [By Pythagoras theorem]

$ \Rightarrow (AC)^{2} = (80)^{2} + (60)^{2} = 10000 $

$ \Rightarrow AC = \sqrt{10000} = 100 \, m $

$ \because $ Region ACDF is a trapezium shape region.

Hence, area of region ACDF = $ \frac{1}{2} \times [S_{1} + S_{2}] \times H $

$ =\frac{1}{2} \times [DF + AC] \times HG $

$ =\frac{1}{2} \times [50 + 100] \times 50 $

$ =3750 \, m^{2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.549Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4363, 18, NULL, NULL, 'Area of whole figure is:', NULL, '[{"text":"7000 m $ ^{2} $","image_url":null,"alt":null},{"text":"7200 m $ ^{2} $","image_url":null,"alt":null},{"text":"7400 m $ ^{2} $","image_url":null,"alt":null},{"text":"7500 m $ ^{2} $","image_url":null,"alt":null}]', NULL, 2, 'Area of whole figure = Area of \Delta FDE + Area of region A C D F + Area of \Delta A B C

= 1250 + 3750 + $ \frac{1}{2} $ × 80 × 60

= 5000 + 2400

= 7400 m²', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.549Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
