INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4374, 18, NULL, NULL, 'If NIGHT can be coded as 29.19.15.17, 41. then ''COLD'' will be coded as:', NULL, '[{"text":"7, 25, 31, 9","image_url":null,"alt":null},{"text":"7, 31, 25, 9","image_url":null,"alt":null},{"text":"7, 9, 31, 25","image_url":null,"alt":null},{"text":"7, 27, 31, 11","image_url":null,"alt":null}]', NULL, 1, 'As, N $ \rightarrow $ 14 $ \times $ 2 + 1 = 29

I $ \rightarrow $ 9 $ \times $ 2 + 1 = 19

G $ \rightarrow $ 7 $ \times $ 2 + 1 = 15

H $ \rightarrow $ 8 $ \times $ 2 + 1 = 17

T $ \rightarrow $ 20 $ \times $ 2 + 1 = 41

$$

\begin{aligned}

C \to 3 \times 2 + 1 &= 7 \\

O \to 15 \times 2 + 1 &= 31 \\

L \to 12 \times 2 + 1 &= 25 \\

D \to 4 \times 2 + 1 &= 9

\end{aligned}

$$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.554Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
