INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4412, 18, NULL, NULL, 'What will be the greatest number which when halved will be exactly divisible by 12, 15, 18, and 30?

(a) 240 (b) 256 (c) 360 (d) 180

81×81+51×51-2×81×51?', NULL, '[{"text":"810","image_url":null,"alt":null},{"text":"510","image_url":null,"alt":null},{"text":"800","image_url":null,"alt":null},{"text":"900","image_url":null,"alt":null}]', NULL, 2, 'L.C.M. of 12, 15, 18 and 30 = 180. Now using options.

Half of option (a) = $ \frac{240}{2} = 120 $, not divisible by 180

half of option (b) = $ \frac{256}{2} = 128 $ not divisible by 180

half of option (c) = $ \frac{360}{2} = 180 $, divisible by 180

half of option (d) = $ \frac{180}{2} = 90 $, not divisible by 180', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.582Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
