INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4414, 18, NULL, NULL, 'a = 7, b = 5 Then find the value of $ ab^{2} + 3a^{2}b $:', NULL, '[{"text":"343","image_url":null,"alt":null},{"text":"593","image_url":null,"alt":null},{"text":"735","image_url":null,"alt":null},{"text":"910","image_url":null,"alt":null}]', NULL, 3, '$ ab^{2} + 3a^{2}b $

