INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4415, 18, NULL, NULL, '$ y + \sqrt{256} = 2\sqrt{169} $, then, value of y is', NULL, '[{"text":"10","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null},{"text":"13","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null}]', NULL, 0, '$ y + 16 = 2 \times 13 $

