$ y = 10 $

8. \quad (b) \quad \left(\frac{4}{100} \times 4\right) - \left(\frac{4}{1000} \times 4\right) \Rightarrow \frac{16}{100} - \frac{16}{1000} \Rightarrow \frac{160 - 16}{1000} = \frac{144}{1000} = 0.144\)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.583Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4416, 18, NULL, NULL, 'If $ 2^{x-1} + 2^{x+1} = 1280 $, then find the value of x', NULL, '[{"text":"4","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null}]', NULL, 3, '$ \frac{2^{x}}{2} + 2^{x} \cdot 2 = 1280 $

$ 2^{x}\left(\frac{1}{2} + 2\right) = 1280 $

$2^{x}=\frac{1280\times2}{5}$

$$ 2^{x}=2^{9} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.584Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4417, 18, NULL, NULL, 'If 50% of a number is equal to 1/5th of another number, what is the ratio of the number to the second number?', NULL, '[{"text":"2:5","image_url":null,"alt":null},{"text":"9:6","image_url":null,"alt":null},{"text":"10:1","image_url":null,"alt":null},{"text":"3:7","image_url":null,"alt":null}]', NULL, 0, 'Let the Ist No. = x

then IInd no = y

A.T.Q.

50% of $ x = \frac{1}{5} y $

$ \frac{1}{2}x = \frac{y}{5} $

$ \frac{x}{y} = \frac{2}{5} \rightarrow 2:5 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.584Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4418, 18, NULL, NULL, 'The average of the four consecutive odd number is 16.

What is the difference between fourth and first?', NULL, '[{"text":"4","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null}]', NULL, 3, 'Let the four consecutive odd number.

$ 2x+1,2x+3,2x+5,2x+7 $

A.T.Q.

$ \frac{(2x+1)+(2x+3)+(2x+5)+(2x+7)}{4}=16 $

$ 8x+16=64 $

$ 8(x+2)=64 $

$ x+2=8 $

$ x=6 $

Ist odd no. = 2(6) + 1 = 13

4th odd no = 2(6) + 7 = 19

Diff. between fourth and 1st odd no. = 19 - 13 = 6', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.585Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4419, 18, NULL, NULL, 'x% of x is the same as 20% of', NULL, '[{"text":"$20x$","image_url":null,"alt":null},{"text":"$x/20$","image_url":null,"alt":null},{"text":"$x^{2}/20$","image_url":null,"alt":null},{"text":"$20x^{2}$","image_url":null,"alt":null}]', NULL, 2, 'Let number = K.

$$ \frac{(X)}{100}\cdot(X)=\frac{20}{100}\cdot K $$

$$ K\Rightarrow=\frac{X^{2}}{20} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.585Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4420, 18, NULL, NULL, 'Hari sells 6 eggs at Rs. 24. He buys 10 eggs at Rs. 30. What is his profit or loss%?', NULL, '[{"text":"33.33%","image_url":null,"alt":null},{"text":"55.33%","image_url":null,"alt":null},{"text":"65.66%","image_url":null,"alt":null},{"text":"60.66%","image_url":null,"alt":null}]', NULL, 0, 'Selling cost of 6 eggs = 24

Buying cost of 10 eggs = 30

$$ Profit\%=\frac{120-90}{90}\times100=33.33\% $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.586Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4421, 18, NULL, NULL, 'A shopkeeper bought candy at 10 for a rupee. How many for a rupee must he sells to gain 25%?', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 3, 'Cost price of 10 candy = Rs. 1 gain = 25%

∴ Number of candy sell in Rs. 1

$ =10\times\frac{100}{(100+25)}=8 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.586Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4422, 18, NULL, NULL, 'A sum becomes its double in 15 years. Find the annual rate of simple interest:', NULL, '[{"text":"$ 6\\frac{1}{3}\\% \\text{ PA} $","image_url":null,"alt":null},{"text":"$ 6\\frac{2}{3}\\% \\text{ PA} $","image_url":null,"alt":null},{"text":"$ 7\\frac{2}{3}\\% \\text{ PA} $","image_url":null,"alt":null},{"text":"$ 7\\frac{1}{3}\\% \\text{ PA} $","image_url":null,"alt":null}]', NULL, 1, 'Let the principal = Rs. P

Sum doubles i.e., = 2P

Simple interest = 2P - P = P

S.I. = $ \frac{P \times R \times T}{100} $

A.T.Q.

P = $ \frac{P \times R \times 15}{100} $

R = $ \frac{100}{15} = \frac{20}{3} = 6 \frac{2}{3}\% $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.586Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4423, 18, NULL, NULL, 'Simple interest of Rs.20000 for 8 years at 6% PA is equal to the simple interest on Rs. 16000 at 3% PA for a fixed period. The time period is', NULL, '[{"text":"20 yrs","image_url":null,"alt":null},{"text":"19 yrs","image_url":null,"alt":null},{"text":"21 yrs","image_url":null,"alt":null},{"text":"22 yrs","image_url":null,"alt":null}]', NULL, 0, 'A.T.Q.

$ \frac{20000 \times 8 \times 6}{100} = \frac{16000 \times 3 \times T}{100} $

T = 20 yrs', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.587Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4424, 18, NULL, NULL, 'P can lay railway track between two given stations in 15 days and Q can do the same job in 10 days. With help of R, they did the job in 4 days only. Then, R alone can do the job in:', NULL, '[{"text":"10 days","image_url":null,"alt":null},{"text":"12 days","image_url":null,"alt":null},{"text":"8 days","image_url":null,"alt":null},{"text":"9 days","image_url":null,"alt":null}]', NULL, 1, 'P''s one day word = $\frac{1}{15}$

Q''s one day work = $\frac{1}{10}$

Let R take x days to complete work.

P + Q + R one day word = $\frac{1}{4}$

R''s one day work = $\frac{1}{x}$

A. T.Q.

$\frac{1}{15} + \frac{1}{10} + \frac{1}{x} = \frac{1}{4}$

$\frac{1}{x} = \frac{1}{4} - \left[ \frac{1}{15} + \frac{1}{10} \right]$

$\frac{1}{x} = \frac{15 - (4 + 6)}{60} = \frac{5}{60}$

R can do job = $\frac{60}{2} = 12$ days', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.587Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4425, 18, NULL, NULL, 'Mohan is on tour and he has Rs. 75 for his expenses. If he exceeds his tour by 4 days he must reduce daily expenses by Rs. 5. The number of days of Mohan''s tour programme is-', NULL, '[{"text":"3 days","image_url":null,"alt":null},{"text":"4 days","image_url":null,"alt":null},{"text":"5 days","image_url":null,"alt":null},{"text":"6 days","image_url":null,"alt":null}]', NULL, 3, 'Let Mohan has x days tour

Then, 1 day expanse = $ \frac{75}{x} $

A. T.Q.

If tour is extended i.e. $ (x+4) $

Then 1 day expanses = $ \frac{75}{x+4} $

Now,

$ \frac{75}{x}-\frac{75}{x+4}=5 $

$ 60=x^{2}+4x $

$ x^{2}+4x-60=0 $

$ x^{2}+10x-6x-60=0 $

$ x(x+10)-6(x+10)=0 $

$ (x+10)(x-6)=0 $

$ \boxed{x=6} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.587Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4426, 18, NULL, NULL, 'A can do piece of work in 20 days, which B can do in 16 days, B worked at it for 8 days. A can finish the remaining work is.....', NULL, '[{"text":"8 days","image_url":null,"alt":null},{"text":"10 days","image_url":null,"alt":null},{"text":"6 days","image_url":null,"alt":null},{"text":"12 days","image_url":null,"alt":null}]', NULL, 1, 'A $\xrightarrow{\quad}$ 20 $\xrightarrow{\quad}$ 4

B $\xrightarrow{\quad}$ 16 $\xrightarrow{\quad}$ 80

B''s 1 day work = 5

B''s 8 day work = $5 \times 8 = 40$

Reaming work finish by $A = \frac{(80 - 40)}{4} = 10$ days', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.588Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4427, 18, NULL, NULL, 'The speed of a boat upstream is 12 km/hr and speed of the stream is 2 km/hr. How much time will take to travel 48 km downstream?', NULL, '[{"text":"3.5 hours","image_url":null,"alt":null},{"text":"2.5 hours","image_url":null,"alt":null},{"text":"5.5 hours","image_url":null,"alt":null},{"text":"3 hours","image_url":null,"alt":null}]', NULL, 3, 'Speed of the boat = u km/hr.

Here upstream speed = $(u - 2) = 12$

$\therefore u = 14$ km/hr.

$\therefore$ Downstream speed = $14 + 2 = 16$ km/hr.

Hence, time taken $= \frac{48}{16} = 3$ hr.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.588Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4428, 18, NULL, NULL, 'Ramnaresh complete a journey in 10 hours. He travels first half of the journey at the rate of 20 km/hr and second half at the rate of 25 km/hr. Find the total journey in km.', NULL, '[{"text":"111.11 km","image_url":null,"alt":null},{"text":"222.22 km","image_url":null,"alt":null},{"text":"333.33 km","image_url":null,"alt":null},{"text":"444.44 km","image_url":null,"alt":null}]', NULL, 1, 'Average speed = $ \frac{2 \times S_{1} \times S_{2}}{S_{1} + S_{2}} $

$ =\frac{2 \times 20 \times 25}{(20 + 25)} $

$ =\frac{1000}{45} \text{km/hr} $.

Total travels time = 10 hrs.

$ \therefore \text{Distance} = \frac{1000}{45} \times 10 $

=222.22 km.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.588Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4429, 18, NULL, NULL, 'Excluding stopage, the speed of a train is 120 kmph and including stopages it is 100 kmph. For how many minutes does the train stop per hour?', NULL, '[{"text":"10min","image_url":null,"alt":null},{"text":"15min","image_url":null,"alt":null},{"text":"20min","image_url":null,"alt":null},{"text":"12min","image_url":null,"alt":null}]', NULL, 0, 'without stoppage with stoppage

Speed 120 100

Time 5 6

Train takes 6 hrs with stoppage, whereas actual time taken is 5 hrs.

i.e. 1 hour is stopped in 6 hours.

A.T.Q:

6 hours = 60 min

1 hour = $ \frac{60}{6} = 10 $ min', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.589Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4430, 18, NULL, NULL, 'A train passes two bridges of lengths 1 km and 500 m in 120 seconds and 80 second respectively. The length of the train is-', NULL, '[{"text":"400m","image_url":null,"alt":null},{"text":"300m","image_url":null,"alt":null},{"text":"750m","image_url":null,"alt":null},{"text":"500m","image_url":null,"alt":null}]', NULL, 3, 'Let the length of Train = $L_{T}$ and speed of Train = $S_{T}$

A. T.Q.

Train passes 1st bridge of 1000 m in 120 sec.

Then

$120 = \frac{1000 + L_{T}}{S}$

$S = \frac{1000 + L_{T}}{120}$

Train passes IInd bridge of 500 m is 80 sec.

Then,

$S = \frac{500 + L_{T}}{80}$

From (i) and (ii)

$\frac{1000 + L_{T}}{120} = \frac{500 + L_{T}}{80}$

$2000 + 2L_{T} = 1500 + 3L_{T}$

$L_{T} = 500$ m.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.589Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4431, 18, NULL, NULL, 'The time taken by train 720 m long travelling at 28 km/hr in passing a boy walking 10 km/hr in same direction will be.', NULL, '[{"text":"146 sec","image_url":null,"alt":null},{"text":"144 sec","image_url":null,"alt":null},{"text":"145 sec","image_url":null,"alt":null},{"text":"147 sec","image_url":null,"alt":null}]', NULL, 1, 'Speed of train (in m/sec) = $ 28 \times \frac{5}{18} = \frac{70}{9} $ m/sec

Speed of boy (in m/sec) = $ 10 \times \frac{5}{18} = \frac{25}{9} $ m/sec

A. T.Q.

Relative speed of train :

$ t = \frac{720}{\left(\frac{70 - 25}{9}\right)} = \frac{9 \times 720}{45} $

= 144 sec.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.589Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4432, 18, NULL, NULL, 'The minute arm of a clock is 20 cm long. The number of minutes taken by the tip of the arm to travel a length of 20 cm is nearly equal to.', NULL, '[{"text":"4.77 min","image_url":null,"alt":null},{"text":"9.54 min","image_url":null,"alt":null},{"text":"19.18 min","image_url":null,"alt":null},{"text":"14.31 min","image_url":null,"alt":null}]', NULL, 1, 'Total length convered by minute hand in 60 mint.

$ =2\pi\times20 $

∴ Time required to move 20 cm

$ =\frac{60}{2\pi\times20}\times20=9.54\ min. $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.590Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4433, 18, NULL, NULL, 'If February 01, 2013 was Friday, what will be day on February 01, 2024?', NULL, '[{"text":"Saturday","image_url":null,"alt":null},{"text":"Monday","image_url":null,"alt":null},{"text":"Tuesday","image_url":null,"alt":null},{"text":"Thursday","image_url":null,"alt":null}]', NULL, 3, 'Number of odd days between 1st Feb 2024 to 1st Feb 2013 = 1 + 1 + 1 + 2 + 1 + 1 + 1 + 2 + 1 + 1 + 1 = 13 days

