INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4436, 18, NULL, NULL, 'If the height of cylinder is halved and radius is doubled, then what will happen to the curved surface area?', NULL, '[{"text":"Increase by 1","image_url":null,"alt":null},{"text":"double","image_url":null,"alt":null},{"text":"triple","image_url":null,"alt":null},{"text":"the same","image_url":null,"alt":null}]', NULL, 3, 'Let the height of cylinder = h

