INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4437, 18, NULL, NULL, 'The perimeter of a square is 40 cm. Find the area of given square.', NULL, '[{"text":"40 cm","image_url":null,"alt":null},{"text":"40 cm $ ^{2} $","image_url":null,"alt":null},{"text":"100 cm","image_url":null,"alt":null},{"text":"100 cm $ ^{2} $","image_url":null,"alt":null}]', NULL, 3, 'Perimeter of square = 40

