INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4438, 18, NULL, NULL, 'A man standing on the top of a tower standing on the sea shore, finds that a boat coming towards him takes 10 minutes for the angle to change from $45^{\circ}$ to $60^{\circ}$. Find the time taken by the boat to reach the shore from this position.', NULL, '[{"text":"17.32 min","image_url":null,"alt":null},{"text":"8.66 min","image_url":null,"alt":null},{"text":"7.32 min","image_url":null,"alt":null},{"text":"13.66 min DIRECTIONS (Qs. 33-36): Study the given pie chart carefully to answer the following question from","image_url":null,"alt":null}]', NULL, 3, 'In $\Delta ABD$

$\tan 45^{\circ} = \frac{AB}{BD}$

$$ \frac{1}{21} $$

In $ \Delta ABC $

$$\tan 60^{\circ} = \frac{AB}{BC}$$

$$\mathrm{BC} = \frac{AB}{\sqrt{3}}$$

$$\mathrm{CD} = \mathrm{BD} - \mathrm{BC}$$

$$= AB - \frac{AB}{\sqrt{3}}$$

$$\mathrm{CD} = AB \frac{(\sqrt{3} - 1)}{\sqrt{3}}$$

Dis. covered in 10 min = \frac{AB(\sqrt{3} - 1)}{\sqrt{3}}$$

time taken to cover dis. \(\frac{AB}{\sqrt{3}}$$

$$ \frac{100\times\sqrt{3}}{AB(\sqrt{3}-1)}\times\frac{AB}{\sqrt{3}} $$

$$=\frac{10\times\left(\sqrt{3}+1\right)}{3-1}\Rightarrow5(1.73+1)$$

=13.6min.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:17.593Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
