INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4472, 18, NULL, NULL, 'In which city Major Dhyan Chand Sports University is established?', NULL, '[{"text":"New Delhi","image_url":null,"alt":null},{"text":"Amritsar","image_url":null,"alt":null},{"text":"Meerut","image_url":null,"alt":null},{"text":"Ahmedabad","image_url":null,"alt":null}]', NULL, 2, 'Prime Minister Narendra Modi Has laid the foundation stone for Major Dhyan Chand Sports University in Meerut, Uttar Pradesh. This sports university is being established at an estimated cost of ₹700 crore at the Salawa and Kaili villages of the Sardhana town in Meerut. It will have the capacity of training 1,080 sportspersons, including 540 women and 540 men.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.667Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4473, 18, NULL, NULL, 'Match List-I with List-II.', NULL, '[{"text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-23-shift-1/q02-table-1.jpg', 'Table for question 2', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.668Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-23-shift-1/q02-table-1.jpg","alt":"Table for question 2","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4474, 18, NULL, NULL, 'The rate at which banks part short-term excess liquidity with RBI, is called.', NULL, '[{"text":"Repo Rate","image_url":null,"alt":null},{"text":"Reverse Repo Rate","image_url":null,"alt":null},{"text":"Bank Rate","image_url":null,"alt":null},{"text":"Cash Reserve Ratio","image_url":null,"alt":null}]', NULL, 1, 'Reverse Repo Rate is the rate the central bank of a country apays its commercial banks to park their excess funds in the central bank. It is the rate at which banks earn inter-when they park surplus funds with the RBI. It helps to control inflation, and increases liquidity in the economy. The repo rate set by the RBI is always higher than the reverse repo.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.669Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4475, 18, NULL, NULL, 'Who has designed the National Flag of India?', NULL, '[{"text":"Sarojini Naidu","image_url":null,"alt":null},{"text":"Subhash Chandra Bose","image_url":null,"alt":null},{"text":"Pingali Venkayya","image_url":null,"alt":null},{"text":"C. Rajagopalachari","image_url":null,"alt":null}]', NULL, 2, 'Pingali Venkayya designed the National Flag of India. The design of the flag of India that was first presented in 1921 to Mahatma Gandhi, leader of the All-India Congress, was created by Pingali Venkayya. He was also as a lecturer author, geologist, Educationalist, agriculturist, and a polyglot.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.669Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4476, 18, NULL, NULL, 'Which among the following are considered as Vedangas?

(A) Kalp

(B) Ayurveda

(C) Vyakaran

(D) Manu Smriti

(E) Jyotish', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(B), (D) and (E) only","image_url":null,"alt":null},{"text":"(A), (C) and (E) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'Vedangas, are six auxiliaries'' disciplines associated with the study understanding Of the Vedas. These are Shiksha, Chhandas, Vyakarana, Nirukta, Kalpa and Jyotisha. The Vedangas are the last treatises of the Vedic Literature.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.670Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
