INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4482, 18, NULL, NULL, '_ of the total surface area of the Earth is covered with water?', NULL, '[{"text":"72.5%","image_url":null,"alt":null},{"text":"66.7%","image_url":null,"alt":null},{"text":"70.8%","image_url":null,"alt":null},{"text":"71.6%","image_url":null,"alt":null}]', NULL, 2, 'About 70.8 % of surface is. water-covered. This is in various forms such as oceans, rivers, lakes, glaciers and ice sheets. The oceans hold about 96.5 percent of all Earth''s water.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.672Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4483, 18, NULL, NULL, 'PROM stands for', NULL, '[{"text":"Programmable Read Only Memory","image_url":null,"alt":null},{"text":"Programmed Random Only Memory","image_url":null,"alt":null},{"text":"Programmable Random Objective Memory","image_url":null,"alt":null},{"text":"Programmed Random Objective Memory","image_url":null,"alt":null}]', NULL, 0, 'PROM Stands for Programmable Read Only Memory. It a of digital of digital memory where the contents can be changed once after manufacture of the device. It can be modified once by a use PROM is a way of allowing a user to tailor a microcode program using a special machine called a PROM programmer.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.672Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4484, 18, NULL, NULL, '_ is the structural and functional unit of kidneys.', NULL, '[{"text":"Nucleon","image_url":null,"alt":null},{"text":"Ribosome","image_url":null,"alt":null},{"text":"Nephron","image_url":null,"alt":null},{"text":"Urochrome","image_url":null,"alt":null}]', NULL, 2, 'Nephron is the structural and functional unit of kidneys.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.672Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4485, 18, NULL, NULL, 'The speed of light is:', NULL, '[{"text":"$ 3 \\times 10^{8} $ m/s","image_url":null,"alt":null},{"text":"$ 3 \\times 10^{3} $ m/s","image_url":null,"alt":null},{"text":"$ 8 \\times 10^{3} $ m/s","image_url":null,"alt":null},{"text":"$ 8 \\times 10^{8} $ m/s","image_url":null,"alt":null}]', NULL, 0, 'Speed of light is $ 3 \times 10^{8} $ m/s.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.673Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4486, 18, NULL, NULL, 'Who is the first man to climb to Mount Everest without Oxygen?', NULL, '[{"text":"Sherpa Tenzing Norgay","image_url":null,"alt":null},{"text":"Sir Edmund Hillary","image_url":null,"alt":null},{"text":"Sir Everest","image_url":null,"alt":null},{"text":"Messner and Habeler","image_url":null,"alt":null}]', NULL, 3, 'Sometime between 1 and 2 in the afternoon on May 8, 1978, Messner and Habeler achieved what was believed to be impossible-the first ascent of Mt. Everest without oxygen.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.673Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4487, 18, NULL, NULL, 'A father said to his child, "I was as old as you are at the time of your birth". If the father''s age is 48 years now, the child''s age six years back was:', NULL, '[{"text":"15 years","image_url":null,"alt":null},{"text":"16 years","image_url":null,"alt":null},{"text":"17 years","image_url":null,"alt":null},{"text":"18 years","image_url":null,"alt":null}]', NULL, 3, 'Let child''s age = x years

As per the question,

2x = 48

x = 24 years

So, six years back, child''s age = 24 - 6 = 18 years', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.674Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4488, 18, NULL, NULL, 'A town has population of 20,000 in 1980. In one year i.e. by 1981 it increased by 25%. Next year i.e. in 1982, it decreased by 20%. The next year in 1983 there was an increase of 30%. What is the population at end of 1983?', NULL, '[{"text":"28,000","image_url":null,"alt":null},{"text":"24,000","image_url":null,"alt":null},{"text":"26,000","image_url":null,"alt":null},{"text":"25,000","image_url":null,"alt":null}]', NULL, 2, 'Population in year 1980 = 20,000

So,

Population in year 1981 = 20,000 $ \times \frac{125}{100} = 25,000 $

Population in year 1982 = 25,000 $ \times \frac{80}{100} = 20,000 $

Population in year 1983 = 20,000 $ \times \frac{130}{100} = 26,000 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.674Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4489, 18, NULL, NULL, 'A man can row at 6 kmph in still water. If the velocity of current is 2 kmph and it takes him 3 hours to row to a place and come back, how far is the place?', NULL, '[{"text":"8 km","image_url":null,"alt":null},{"text":"5 km","image_url":null,"alt":null},{"text":"7 km","image_url":null,"alt":null},{"text":"4 km","image_url":null,"alt":null}]', NULL, 0, 'Let the distance = x km

As we know that, $ \frac{\text{Distance}}{\text{Speed}} = \text{Time} $

So, $ \frac{x}{8} + \frac{x}{4} = 3 $

x = 8 km', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.674Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4490, 18, NULL, NULL, 'A car is sold for ₹85,000 at a loss of 20%. What is the cost price (CP) of the car?', NULL, '[{"text":"₹1,07,250","image_url":null,"alt":null},{"text":"₹1,05,250","image_url":null,"alt":null},{"text":"₹1,04,250","image_url":null,"alt":null},{"text":"₹1,06,250","image_url":null,"alt":null}]', NULL, 3, 'Let the C.P. of the car = $ \bar{x}x $

Then $ x = 85,00 \times \frac{100}{80} = 1,06,250 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.675Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4491, 18, NULL, NULL, 'If I sell a cycle at ₹3,600, I make a profit of 20%. At what price I need to sell to make a profit of 10%.', NULL, '[{"text":"₹3,500","image_url":null,"alt":null},{"text":"₹3,000","image_url":null,"alt":null},{"text":"₹3,300","image_url":null,"alt":null},{"text":"₹3,600","image_url":null,"alt":null}]', NULL, 2, 'Let the C.P. of the cycle = $ \bar{x}x $

Then $ x = 3{,}600 \times \frac{100}{120} = 3{,}000 $

Now, required sale price = 3,000 $ \times \frac{110}{100} = 3,300 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.675Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4492, 18, NULL, NULL, 'A, B and C are in a cycle race of 1,500 meters. A cycle twice as fast as B, C cycles $ \frac{1}{2} $ as fast as B, C completes the race in 40 minutes. Then, where was B from the finishing line when A finished the race?', NULL, '[{"text":"550 m from the finish line","image_url":null,"alt":null},{"text":"450 m from the finish line","image_url":null,"alt":null},{"text":"650 m from the finish line","image_url":null,"alt":null},{"text":"750 m from the finish line","image_url":null,"alt":null}]', NULL, 3, 'Let the speed of C = x m/s

Then, speed of B = 2x m/s

And speed of A = 4x m/s

So, time taken by A to finish the race

= $ \frac{1}{4}\times40=10 $ min or 600 sec

Hence, speed of A = 1,500/600 = 2.5 m/s

Now speed of B = 2.5 = 1.25 m/s

So, required distance = 1.25 $ \times $ 600 = 750 m', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.677Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4493, 18, NULL, NULL, 'Mohan asked 36 men to build his house in 30 days. 50% of the work got completed in just 10 days. So, Mohan removed some workers. Now, how many persons does he need to complete the remaining work in decided time?', NULL, '[{"text":"20","image_url":null,"alt":null},{"text":"18","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null},{"text":"14","image_url":null,"alt":null}]', NULL, 1, 'Given that, 36 men can build 50% of the house in 10 days.

Let x men can complete the same in 20 days.

As we know that,

$ M_{1}D_{1} = M_{2}D_{2} $

$ 36 \times 10 = x \times 20 $

= 18 men', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.678Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4494, 18, NULL, NULL, 'P alone can do a piece of work in 5 days and Q alone in 4 days. P and Q undertook to do it for ₹3,000. With the help of R, they completed the work in 2 days. How much is to be paid to R?', NULL, '[{"text":"₹300","image_url":null,"alt":null},{"text":"₹400","image_url":null,"alt":null},{"text":"₹500","image_url":null,"alt":null},{"text":"₹600","image_url":null,"alt":null}]', NULL, 0, 'Time taken by P to finish the task = 5 days

Time taken by Q to finish the task = 4 days

Time taken by P, Q and R to finish the task = 2 days

Total work = LCM (5, 4, 2) = 20

So, Efficiency of P = 20/5 = 4

Efficiency of Q = 20/4 = 5

And combined efficiency of P, Q and R = 10

So, efficiency of R = 1

So, amount paid to R = $ \frac{1}{10} \times 3000 = 300 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.678Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4495, 18, NULL, NULL, 'A tyre has two punctures. The first puncture alone would have made the tyre flat in 6 minutes and the second alone would have done it in 9 minutes. If air leaks out at a constant rate, how long does it take both the punctures together to make it flat?', NULL, '[{"text":"$ 3\\frac{3}{5} $ minute","image_url":null,"alt":null},{"text":"$ 4\\frac{3}{5} $ minute","image_url":null,"alt":null},{"text":"$ 5\\frac{3}{5} $ minute","image_url":null,"alt":null},{"text":"$ 2\\frac{3}{5} $ minute","image_url":null,"alt":null}]', NULL, 0, 'Time taken by $ 1^{st} $ puncture = 6 min

Time taken by $ 2^{nd} $ puncture = 9 min

So, time taken by both puncture

= $ \frac{1}{\frac{1}{6}+\frac{1}{9}}=\frac{18}{5}=3\frac{3}{5} $ min', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.679Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4496, 18, NULL, NULL, 'If length of diagonal of a square is $ 7\sqrt{2} $ m. The area of the square is', NULL, '[{"text":"$ 46\\ m^{2} $","image_url":null,"alt":null},{"text":"$ 49\\ m^{2} $","image_url":null,"alt":null},{"text":"$ 39\\ m^{2} $","image_url":null,"alt":null},{"text":"$ 48\\ m^{2} $","image_url":null,"alt":null}]', NULL, 1, 'Given that,

Length of diagonal = $ 7\sqrt{2} $ m

So, length of sides = 7 m

So, area = $ 7^{2} = 49 $ $ m^{2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.680Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4497, 18, NULL, NULL, 'If A: B is 2:5. Then, the value of 2A + 3B: A + B is', NULL, '[{"text":"14:5","image_url":null,"alt":null},{"text":"19:7","image_url":null,"alt":null},{"text":"3:11","image_url":null,"alt":null},{"text":"17:15","image_url":null,"alt":null}]', NULL, 1, 'Given that,

A: B = 2 : 5

So, $ 2A + 3B:A + B = 2 \times 2 + 3 \times 5:2 + 5 $

= 19:7', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.680Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4498, 18, NULL, NULL, 'Find the greatest number that will divide 38, 88 and 163 so as to leave the same remainder in each case', NULL, '[{"text":"18","image_url":null,"alt":null},{"text":"28","image_url":null,"alt":null},{"text":"25","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null}]', NULL, 2, 'Required number = HCF of the differences of the given numbers

= HCF (88 - 38, 163 - 88, 16. -38)

= HCF (50, 75, 125)

= 25', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.680Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4499, 18, NULL, NULL, 'If principal = P, Rate, R = R% per annum, T = Time year, SI = Simple interest, then

(A) $ T = \frac{100 \times SI}{P \times R} $

(B) $ SI = \frac{P \times R \times T}{100} $

(C) $ R = \frac{P \times SI \times T}{100} $

(D) $ T = \frac{P \times SI \times T}{100} $', NULL, '[{"text":"A and C only","image_url":null,"alt":null},{"text":"B, C, and D only","image_url":null,"alt":null},{"text":"A and B only","image_url":null,"alt":null},{"text":"C and D only","image_url":null,"alt":null}]', NULL, 2, 'As we know that,

$ SI = \frac{P \times R \times T}{100} $

From given choices options A, and B are correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.681Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4500, 18, NULL, NULL, 'Two numbers are in the ratio 4:3. If 2 is added to each of the number the new ratio becomes 5:4. Then, find the numbers', NULL, '[{"text":"20, 15","image_url":null,"alt":null},{"text":"16, 12","image_url":null,"alt":null},{"text":"8, 6","image_url":null,"alt":null},{"text":"12, 9","image_url":null,"alt":null}]', NULL, 2, 'Given that the ratio between the numbers = 4:3 Let the numbers are 4x and 3x.

As per the question,

$ \frac{4x+2}{3x+2} = \frac{5}{4} $

So, $ 16x + 8 = 15x + 10 $

x = 2

Numbers = 8 and 6

Sol. Sum of 99 positive integers

$ =\frac{99(99+1)}{2}=\frac{99\times100}{2}=4,950 $

So, required average = $ \frac{4,950}{99} $ = 50', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.681Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4501, 18, NULL, NULL, '27:729::31?', NULL, '[{"text":"961","image_url":null,"alt":null},{"text":"916","image_url":null,"alt":null},{"text":"841","image_url":null,"alt":null},{"text":"814","image_url":null,"alt":null}]', NULL, 0, 'As 729 is the square of 27. So, the missing number will be the square of 31.

