INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4511, 18, NULL, NULL, 'In this question, four words have been given of which three are alike in some way and one is different. Find the odd one out.', NULL, '[{"text":"Motorcycle","image_url":null,"alt":null},{"text":"Metro","image_url":null,"alt":null},{"text":"Bus","image_url":null,"alt":null},{"text":"Car","image_url":null,"alt":null}]', NULL, 1, 'Motorcycle, Bus and Car run on road but Metro runs on rail track.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.685Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4512, 18, NULL, NULL, 'How many triangles are in the given shape?', NULL, '[{"text":"21","image_url":null,"alt":null},{"text":"23","image_url":null,"alt":null},{"text":"27","image_url":null,"alt":null},{"text":"29","image_url":null,"alt":null}]', NULL, 1, '$$ \begin{array}{r l}{\mathrm{S o l.}}&{\mathrm{T o t a l~n u m b e r~o f~t r i a n g l e s}}\\ &{=\frac{n(n+2)(2n+1)}{8}=\frac{4\times6\times9}{8}=27}\end{array} $$', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-08-23-shift-1/q44-figure-1.jpg', 'Figure for question 44', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.686Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-08-23-shift-1/q44-figure-1.jpg","alt":"Figure for question 44","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4513, 18, NULL, NULL, 'Anita, Baby and Charu are sisters. D is the brother of E and E is the daughter of Baby. How is Anita related to D?', NULL, '[{"text":"Niece","image_url":null,"alt":null},{"text":"Sister","image_url":null,"alt":null},{"text":"Cousin","image_url":null,"alt":null},{"text":"Aunt","image_url":null,"alt":null}]', NULL, 3, 'So, Anita is Aunt of D.

Hence, option D is correct option.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.686Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4514, 18, NULL, NULL, 'Find the value of $ \frac{5^{2/3} \times \sqrt[3]{5^{7}}}{\sqrt[3]{5^{6}}} $', NULL, '[{"text":"5","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"$ \\sqrt{5} $","image_url":null,"alt":null},{"text":"$ 3\\sqrt{5} $","image_url":null,"alt":null}]', NULL, 0, '$ \frac{5^{2/3}\times\sqrt[3]{5^{7}}}{\sqrt[3]{5^{6}}}=\frac{5^{2/3}\times5^{7/3}}{5^{6/3}} $

$ =\frac{5^{9/3}}{5^{2}}=\frac{5^{3}}{5^{2}}=5 $

Hence, option A is correct option.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.686Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4515, 18, NULL, NULL, 'The angle of depression of a point situated at a distance 100 m from the base of a pole is $ 30^{\circ} $. The height of the pole is:', NULL, '[{"text":"$ 100(\\sqrt{3} + 1)m $","image_url":null,"alt":null},{"text":"$ \\frac{100}{3}m $","image_url":null,"alt":null},{"text":"$ \\frac{100}{3}\\sqrt{3}m $","image_url":null,"alt":null},{"text":"$ 100\\sqrt{3}m $","image_url":null,"alt":null}]', NULL, 2, 'In $ \Delta ABC $

$ \tan 30^{\circ} = \frac{h}{100} $

$$ \frac{1}{\sqrt{3}}=\frac{h}{100} $$

$$ h=\frac{100\times\sqrt{3}}{\sqrt{3}\times\sqrt{3}} $$

$$ h=\frac{100\sqrt{3}}{3}m $$

Hence, option C is correct option.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.687Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4516, 18, NULL, NULL, 'The value of $13.7 \times 12.7 \times 0.8$ is _', NULL, '[{"text":"13.9193","image_url":null,"alt":null},{"text":"13.9192","image_url":null,"alt":null},{"text":"139.192","image_url":null,"alt":null},{"text":"139.191","image_url":null,"alt":null}]', NULL, 2, '$ 13.7 \times 12.7 \times 0.8 = 139.192 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.687Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4517, 18, NULL, NULL, 'The sum of greatest five and lowest/smallest four digits number is:', NULL, '[{"text":"91,999","image_url":null,"alt":null},{"text":"19,999","image_url":null,"alt":null},{"text":"10,999","image_url":null,"alt":null},{"text":"1,00,999","image_url":null,"alt":null}]', NULL, 3, 'Required sum = 99,999 + 1,000 = 1,000,999', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.687Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4518, 18, NULL, NULL, 'If $ \sqrt[3]{x} = 2y $. Then, the value of $ \frac{y^3}{x} $ is _', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2/5","image_url":null,"alt":null},{"text":"1/8","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 2, 'Given that, $ \sqrt[3]{x} = 2y $

$ x = 8y^{3} $

So, $ \frac{y^{3}}{x} = \frac{1}{8} $

So, option C is correct option.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.688Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4519, 18, NULL, NULL, 'When seen through a mirror, a clock shown 8:30.

What is the correct time?', NULL, '[{"text":"2:30","image_url":null,"alt":null},{"text":"3:30","image_url":null,"alt":null},{"text":"5:30","image_url":null,"alt":null},{"text":"8:30","image_url":null,"alt":null}]', NULL, 1, 'Correct time = 11:60 - 8:30 = 3:30', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.688Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4520, 18, NULL, NULL, 'The value of $ \sqrt{0.01} \times \sqrt[3]{0.027} - 0.3 $ is', NULL, '[{"text":"0.1","image_url":null,"alt":null},{"text":"0.27","image_url":null,"alt":null},{"text":"0.027","image_url":null,"alt":null},{"text":"0.1","image_url":null,"alt":null}]', NULL, 1, 'Given that,

$ \sqrt{0.01} \times \sqrt[3]{0.027} - 0.3 = 0.1 \times 0.3 - 0.3 $

$ = 0.03 - 0.3 = -0.27 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.688Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4521, 18, NULL, NULL, '2 women and 3 men can do a piece of work in 10 days while 3 women and 2 men can do the same work in 8 days. In how many days can 2 women and 1 man do the work?', NULL, '[{"text":"$ 12\\frac{1}{4} $ days","image_url":null,"alt":null},{"text":"15 days","image_url":null,"alt":null},{"text":"25 days","image_url":null,"alt":null},{"text":"$ 12\\frac{1}{2} $ days","image_url":null,"alt":null}]', NULL, 3, 'As given in the question,

As given in the question,

$ \frac{2}{W} + \frac{3}{M} = \frac{1}{10} $

$ \frac{3}{W} + \frac{2}{M} = \frac{1}{8} $

From above equations,

$ \frac{1}{W} = \frac{7}{200} $ And $ \frac{1}{M} = \frac{1}{100} $

So, now $ \frac{2}{W} + \frac{1}{M} = \frac{14}{200} + \frac{1}{100} $

$$=\frac{16}{200}$$

So, required days = $\frac{200}{16}$ = $12\frac{1}{2}$ days', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.689Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4522, 18, NULL, NULL, 'On 7^{th} March, 2005 Monday falls. What was the day of the week on 7^{th} March 2004?', NULL, '[{"text":"Monday","image_url":null,"alt":null},{"text":"Saturday","image_url":null,"alt":null},{"text":"Sunday","image_url":null,"alt":null},{"text":"Friday","image_url":null,"alt":null}]', NULL, 2, 'As there is 1 odd day. So, 1 year before the day was Sunday.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.689Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4523, 18, NULL, NULL, 'The value of $ \frac{(793-232)^{2}-(793-232)^{2}}{793\times232} $ is', NULL, '[{"text":"7930","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"2320","image_url":null,"alt":null}]', NULL, 1, 'Given that, $ \frac{(793+232)^2-(793-232)^2}{793\times232} = \frac{4\times793\times232}{793\times232} = 4 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.689Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4524, 18, NULL, NULL, 'The simple interest as a sum of money is 4/5th of the principal. Find the rate of interest if both the rate of interest and time are numerically equal.', NULL, '[{"text":"46% P.A.","image_url":null,"alt":null},{"text":"$ 4\\sqrt{2} $ & P.A.","image_url":null,"alt":null},{"text":"43% P.A.","image_url":null,"alt":null},{"text":"$ 4\\sqrt{5} $% P.A.","image_url":null,"alt":null}]', NULL, 3, 'Let the rate of interest and time = T

And Principal amount = P

As we know that,

$ SI = \frac{P \times R \times T}{100} $

So, $ \frac{4}{5}P = \frac{P \times R \times T}{100} $ (Since, R=T)

$ T = 4\sqrt{5} $

So, rate of interest = $ 4\sqrt{5}\% $ P.A.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.690Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4525, 18, NULL, NULL, 'Find the odd number in the series 63, 48, 34, 24, 15, 8, 3', NULL, '[{"text":"24","image_url":null,"alt":null},{"text":"34","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"8","image_url":null,"alt":null}]', NULL, 1, 'In given series, 34 is the odd number as it is not following the odd number difference.

Difference of 5, 7, 9, 11, 13, 15 should be there from last.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.690Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4526, 18, NULL, NULL, 'The average of the four consecutive odd numbers is

16. What is the third number in the descending order?', NULL, '[{"text":"13","image_url":null,"alt":null},{"text":"15","image_url":null,"alt":null},{"text":"17","image_url":null,"alt":null},{"text":"19","image_url":null,"alt":null}]', NULL, 1, 'Let the numbers =X, X + 2, X + 4, X + 6

So, Average = $ \frac{X + X + 2 + X + 4 + X + 6}{4} $ = 16

X = 13

So, Require number = X + 2 = 15', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.691Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4527, 18, NULL, NULL, 'A train running at a speed of 54 km/hr crosses a platform which is double of the length of the train in 18 seconds. What is the length of the platform and train?', NULL, '[{"text":"180m and 90 m","image_url":null,"alt":null},{"text":"90 m and 180m","image_url":null,"alt":null},{"text":"70 m and 140 m","image_url":null,"alt":null},{"text":"140 m and 70 m","image_url":null,"alt":null}]', NULL, 0, 'Let the length of train = L

So, the length of platform = 2 L

Speed of the train = 54 kmph = 54 × $ \frac{5}{18} $ = 15 m/s

As we know that,

Distance = Speed × Time

3 L = 15 × 18

L = 90 m

So, the length of train = 90 m

And the length of platform = 180 m', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.691Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4528, 18, NULL, NULL, 'Find the largest size of a bamboo that can be placed in a square of area 333 m²?', NULL, '[{"text":"13 m","image_url":null,"alt":null},{"text":"13√2 m","image_url":null,"alt":null},{"text":"26 m","image_url":null,"alt":null},{"text":"26√2 m","image_url":null,"alt":null}]', NULL, 2, 'Area of square = 333m²

Let the side of square = a

So, a = $ \sqrt{333} $ m

So, largest size of the bamboo = $ a\sqrt{2} $

= $ \sqrt{2}\sqrt{333} $ = $ \sqrt{666} $ ≈ 26 m', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.692Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4529, 18, NULL, NULL, 'Arrange the following in a logical order:

(A) Frog

(B) Eagle

(C) Grasshopper

(D) Snake

(E) Grass', NULL, '[{"text":"A, C, E, B, D","image_url":null,"alt":null},{"text":"C, D, B, E, A","image_url":null,"alt":null},{"text":"E, C, A, D, B","image_url":null,"alt":null},{"text":"E, C, D, B, A","image_url":null,"alt":null}]', NULL, 2, '$ e \rightarrow c \rightarrow a \rightarrow d \rightarrow b $

The logical order is Grass - Grasshopper - Frog - Snake - Eagle', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.695Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
