INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4542, 18, NULL, NULL, 'What is the ratio between total marks obtained in all subjects by RP and FA?', NULL, '[{"text":"84:89","image_url":null,"alt":null},{"text":"50:51","image_url":null,"alt":null},{"text":"1:1","image_url":null,"alt":null},{"text":"10:11","image_url":null,"alt":null}]', NULL, 2, 'Marks obtained by RP in all subjects = 70 + 68 + 72 + 40 + 80 = 330

