INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4543, 18, NULL, NULL, 'Actress and Model "Harnaaz Sandhu" was crowned as _ in Dec 2021.', NULL, '[{"text":"Miss World 2021","image_url":null,"alt":null},{"text":"Miss India 2021","image_url":null,"alt":null},{"text":"Miss Universe 2021","image_url":null,"alt":null},{"text":"Miss Earth 2021","image_url":null,"alt":null}]', NULL, 2, 'Actress and Model "Harnaaz Sandhu" was crowned as Miss Universe in Dec 2021.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.706Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4544, 18, NULL, NULL, 'If each side of a cube is reduced by 50% the surface area will be reduced by.', NULL, '[{"text":"75%","image_url":null,"alt":null},{"text":"50%","image_url":null,"alt":null},{"text":"25%","image_url":null,"alt":null},{"text":"100%","image_url":null,"alt":null}]', NULL, 2, 'Let the side of the cube $a$.

Surface area of the cube = $6a^{2}$

In second case, decrease in side = 50%

$\therefore$ Side = $\frac{100-50}{100} \times a = \frac{a}{2}$

$\therefore$ Total surface area = $6\left(\frac{a}{2}\right)^{2} = \frac{6a^{2}}{4}$

$\therefore$ Change of total surface area = $\frac{\frac{6a^{2}}{4}}{6a^{2}} \times 100 = 25\%$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.707Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4545, 18, NULL, NULL, 'If * is an operation such that a *b = 3a - 4b, find the value of 3 * 4', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"7","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 1, 'If $ a * b = 3a - 4b $

$ \Rightarrow 3 \times 4 = 3(3) - 4(4) = 9 - 16 = -7 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.707Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4546, 18, NULL, NULL, 'In a certain language TRIANGLE is written as VTKCPING. How RECTANGLE will be written in this language?', NULL, '[{"text":"TGEUCPING","image_url":null,"alt":null},{"text":"TGEVCPKNG","image_url":null,"alt":null},{"text":"TGEVCPING","image_url":null,"alt":null},{"text":"GTEVCPING","image_url":null,"alt":null}]', NULL, 2, 'Each letter in the word is moved two steps forward to obtain the corresponding letter of the code.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.708Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4547, 18, NULL, NULL, 'The next figure is', NULL, '[{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null},{"text":"","image_url":null,"alt":null}]', NULL, 0, 'In each step, ''+'' moves one step in anti-clockwise direction and one diagonal is replaced by another in every step.', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q05-figure-1.jpg', 'Figure for question 5', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.709Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q05-figure-1.jpg","alt":"Figure for question 5","kind":"figure"},{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q05-options.jpg","alt":"Printed answer choices for question 5","kind":"options"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4548, 18, NULL, NULL, 'Two numbers are in ratio of 7:10 and if the sum of the numbers is 119. Find the difference of the numbers.', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"21","image_url":null,"alt":null},{"text":"17","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null}]', NULL, 1, 'Let two numbers are x and y

Given: Two numbers are in ratio of 7:10

$ \Rightarrow x = 7k, y = 10k $

If the sum of the numbers is 119

$ \Rightarrow 7k + 10k = 119 $

= 17k = 119

= k = 7

So, two numbers are $ x = 7 \times 7 = 49 $, y = 10 $ \times $ 7 = 70

Hence, difference of the two numbers = y - x = 70 - 49 = 21', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.710Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4549, 18, NULL, NULL, 'Who is the first Chief of Defence Staff of the Indian Armed forces?', NULL, '[{"text":"Field Marshal K. M. Cariappa","image_url":null,"alt":null},{"text":"General Manoj Mukund Narayan","image_url":null,"alt":null},{"text":"General Bipin Rawat","image_url":null,"alt":null},{"text":"General Manoj Pande","image_url":null,"alt":null}]', NULL, 2, 'General Bipin Rawat was the first Chief of Defence Staff (CDS) of the Indian Armed Forces. He assumed office on January 1, 2020, and held the position until his unfortunate demise in a helicopter crash on December 8, 2021. The position of CDS was created in December 2019 to improve coordination and integration between the three branches of the Indian Armed Forces: the Army, Navy, and Air Force.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.711Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4550, 18, NULL, NULL, 'In the given figure ABCD is a rhombus, the value of x is.', NULL, '[{"text":"$ 40^{\\circ} $","image_url":null,"alt":null},{"text":"$ 50^{\\circ} $","image_url":null,"alt":null},{"text":"$ 90^{\\circ} $","image_url":null,"alt":null},{"text":"$ 60^{\\circ} $","image_url":null,"alt":null}]', NULL, 1, 'As we know that, CD ||AB, so alternate angles are equal

$\Rightarrow \angle CDB = \angle ABD = x$

Since, Diagonals of a rhombus are perpendicular to each other

In $\Delta AOB$

$\Rightarrow \angle OAB + \angle ABO + \angle BOA = 180^{\circ}$

$\Rightarrow \angle ABO = 180^{\circ} - 40^{\circ} - 90^{\circ}$

$\Rightarrow x = 180^{\circ} - 130^{\circ}$

$\Rightarrow x = 50^{\circ}$', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q08-figure-1.jpg', 'Figure for question 8', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.712Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q08-figure-1.jpg","alt":"Figure for question 8","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
