INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4555, 18, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-II, B-IV, C-III, D-I","image_url":null,"alt":null},{"text":"A-I, B-III, C-IV, D-II","image_url":null,"alt":null},{"text":"A-II, B-III, C-IV, D-I","image_url":null,"alt":null},{"text":"A-II, B-I, C-IV, D-III","image_url":null,"alt":null}]', NULL, 2, 'A. $2x-4=2-x$

$\Rightarrow 3x=6$

$\Rightarrow x=2$

So, $A \to II$

B. $7-4x=0$

$\Rightarrow x=\frac{7}{4}$

So, $B \to III$

C. $\frac{x}{2}-3=0$

$\Rightarrow x=6$

So, $C \to IV$

D. $2x+3=x+6$

$\Rightarrow x=6-3$

$\Rightarrow x=3$

So, $D \to I$', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q13-table-1.jpg', 'Table for question 13', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.715Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q13-table-1.jpg","alt":"Table for question 13","kind":"table"}]', 'ai_draft', 'unreviewed', NULL, NULL);
