INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4564, 18, NULL, NULL, 'In the given figure $l \parallel m$ || $n$, the value of $x$ is', NULL, '[{"text":"$ 80^{\\circ} $","image_url":null,"alt":null},{"text":"$ 70^{\\circ} $","image_url":null,"alt":null},{"text":"$ 60^{\\circ} $","image_url":null,"alt":null},{"text":"$ 50^{\\circ} $","image_url":null,"alt":null}]', NULL, 3, 'Since, $l||m||n$

So, alternate angles are equal

$\angle1 = 120^{\circ}$

$\Rightarrow \angle1 + \angle2 = 180^{\circ}$

$=\angle2 = 180^{\circ} - 120^{\circ} = 60^{\circ}$

As we know that, sum of angles of triangle is $180^{\circ}$

$\Rightarrow \angle2 + 60^{\circ} + 70^{\circ} = 180^{\circ}$

$=\angle2 = 180^{\circ} - 130^{\circ}$

$=\angle2 = 50^{\circ}$', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q22-figure-1.jpg', 'Figure for question 22', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.719Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q22-figure-1.jpg","alt":"Figure for question 22","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4565, 18, NULL, NULL, 'On which date World Environment Day is celebrated?', NULL, '[{"text":"21 June","image_url":null,"alt":null},{"text":"5 June","image_url":null,"alt":null},{"text":"21 July","image_url":null,"alt":null},{"text":"22 March","image_url":null,"alt":null}]', NULL, 1, 'World Environment Day - 05 - June.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.719Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4566, 18, NULL, NULL, 'If DOG = 26, FLY = 43

them what is the code for ''BIRD''', NULL, '[{"text":"60","image_url":null,"alt":null},{"text":"32","image_url":null,"alt":null},{"text":"33","image_url":null,"alt":null},{"text":"24","image_url":null,"alt":null}]', NULL, 2, 'DOG = 4 + 15 + 7 = 26, FLY = 6 + 12 + 25 = 43

