INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4567, 18, NULL, NULL, 'Which of the following seas has highest salinity in the world?', NULL, '[{"text":"Dead Sea","image_url":null,"alt":null},{"text":"Black Sea","image_url":null,"alt":null},{"text":"Red Sea","image_url":null,"alt":null},{"text":"Mediterranean Sea","image_url":null,"alt":null}]', NULL, 0, '"Dead Sea" has highest salinity in the world.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.720Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4568, 18, NULL, NULL, 'If the sugar price is increased by 25% by how much percent consumption should be reduced that expense remains same.', NULL, '[{"text":"25%","image_url":null,"alt":null},{"text":"20%","image_url":null,"alt":null},{"text":"30%","image_url":null,"alt":null},{"text":"35%","image_url":null,"alt":null}]', NULL, 1, 'Let original price of sugar = Rs. 100

∴ Price of sugar for today = Rs. 100 + Rs. 25 = Rs. 125

In order to bring down the price to original i.e., Rs. 100, its price should be decreased by = Rs. 125 - Rs. 100 = Rs.25

∴ On Rs. 125, the price should be decreased by = Rs.25

On Re.1, the price should be decreased by = Rs. $ \frac{25}{125} $

On Rs. 100, the price should be decreased by = Rs. $ \frac{25}{125} \times 100 = Rs.\frac{1}{5} \times 100 = Rs. $

∴ Price should be decreased by 20%', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.720Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4569, 18, NULL, NULL, 'Mohan''s Mother is three times as old as Mohan. After 6 years, his mother will be two times as old as he will be them, find the age of Mohan.', NULL, '[{"text":"18 years","image_url":null,"alt":null},{"text":"6 years","image_url":null,"alt":null},{"text":"3 years","image_url":null,"alt":null},{"text":"16 years","image_url":null,"alt":null}]', NULL, 1, 'Let Mohan''s age be = x years

Mohan''s mother age = 3x years

After 6 years

Mohan''s age = x + 6 years

Mohan''s mother age = 3x + 6

It is given that after 6 years

$ \Rightarrow 3x + 6 = 2(x + 6) $

= 3x + 6 = 2x + 12

= x = 6 years

$ \therefore $ Age of Mohan is 6 years', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.721Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
