INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4575, 18, NULL, NULL, 'Which one of the following bills must be passed by each house of the India parliament separately by special majority?', NULL, '[{"text":"Money Bill","image_url":null,"alt":null},{"text":"Finance Bill","image_url":null,"alt":null},{"text":"Ordinary Bill","image_url":null,"alt":null},{"text":"Constitutional Amendment Bill","image_url":null,"alt":null}]', NULL, 3, '"Constitutional Amendment Bill" must be passed by each house of the Indian Parliament separately by special Majority.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.723Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4576, 18, NULL, NULL, 'The average of first 8 multiples of 8 is.', NULL, '[{"text":"41","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null},{"text":"36","image_url":null,"alt":null},{"text":"31 (b) (c) (d)","image_url":null,"alt":null}]', NULL, 2, 'First 8 multiples of 8 are 8, 16, 24, 32, 40, 48, 56, 64

So, average of first 8 multiples of 8 =

$ \frac{Sum\ of\ numbers}{total\ number}=\frac{8+16+24+32+40+48+56+64}{8}=36 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.723Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4577, 18, NULL, NULL, 'At hill station, the boiling point of water will be _.', NULL, '[{"text":"Same as at sea level","image_url":null,"alt":null},{"text":"More than that at sea level","image_url":null,"alt":null},{"text":"Less than that at sea level","image_url":null,"alt":null},{"text":"Equal to the melting point of Ice","image_url":null,"alt":null}]', NULL, 2, 'At hill station, the boiling point of Water will be less than that at sea level.

Sol. A rectangular paper of width 8 cm is rolled along its width to form a cylinder.

Circumference of base = 22 cm

$\Rightarrow 2\pi r = 22$

$r = \frac{22}{2\pi}$

$r = \frac{22\times7}{2\times22} = \frac{7}{2}\text{cm}$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.724Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4578, 18, NULL, NULL, 'The radius of the cylinder is-', NULL, '[{"text":"$ \\frac{2}{7} $ cm","image_url":null,"alt":null},{"text":"7 cm","image_url":null,"alt":null},{"text":"$ \\frac{7}{2} $ cm","image_url":null,"alt":null},{"text":"14 cm","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.724Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4579, 18, NULL, NULL, 'If the outer surface area of cylinder is pointed at the rate of $ \bar{x}\ 0.5/cm^{2} $, then the total cost of painting is', NULL, '[{"text":"₹88","image_url":null,"alt":null},{"text":"₹176","image_url":null,"alt":null},{"text":"₹78","image_url":null,"alt":null},{"text":"₹186","image_url":null,"alt":null}]', NULL, 0, 'Outer surface area of cylinder = $2\pi rh$

Height of cylinder = 8 cm

Radius of cylinder = $\frac{7}{2}$ cm

$\Rightarrow$ Outer surface area of cylinder = $2 \times \frac{22}{7} \times \frac{7}{2} \times 8 = 176 \, cm^{2}$

$\Rightarrow$ total cost = $0.5 \times 176 = 88$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.724Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4580, 18, NULL, NULL, 'The volume of cylinder is', NULL, '[{"text":"98cm³","image_url":null,"alt":null},{"text":"49πcm³","image_url":null,"alt":null},{"text":"49cm³","image_url":null,"alt":null},{"text":"98πcm³","image_url":null,"alt":null}]', NULL, 3, 'Volume of cylinder = $ \pi r^{2} h $

$ =\frac{7}{2}\times\frac{7}{2}\times8\pi=98\pi cm^{3} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.725Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
