INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4587, 18, NULL, NULL, 'Find the value of $ (25)^{3}+(-29)^{3}+(4)^{3} $', NULL, '[{"text":"8700","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"8700","image_url":null,"alt":null},{"text":"2900","image_url":null,"alt":null}]', NULL, 0, '$ \Rightarrow(25)^{3}+(-29)^{3}+4^{3}=-8700 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.731Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4588, 18, NULL, NULL, 'If the area and sum of parallel side of a trapezium are 48 cm² and 48cm respectively. Then the distance between the parallel sides is', NULL, '[{"text":"$ \\frac{1}{2} $ cm","image_url":null,"alt":null},{"text":"1 cm","image_url":null,"alt":null},{"text":"2 cm","image_url":null,"alt":null},{"text":"3 cm","image_url":null,"alt":null}]', NULL, 2, 'The area of trapezium id given as 48\ cm^{2} with the sum of its parallel sides as 48\ cm. Let d be the distance between the parallel sides, then

$ \Rightarrow $ Area = $ \frac{1}{2} $(sum of the parallel sides) $ \times $ h

$ \Rightarrow 48 = \frac{1}{2} \times 48 \times d $

$ \Rightarrow d = 2 \, cm $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.731Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4589, 18, NULL, NULL, 'One TB (Tera Byte) approximately occupies or comprises which of the following data or space size', NULL, '[{"text":"1000 KB","image_url":null,"alt":null},{"text":"1000 GB","image_url":null,"alt":null},{"text":"1024 KB","image_url":null,"alt":null},{"text":"1024 GB","image_url":null,"alt":null}]', NULL, 3, 'One terabyte (TB) is approximately equal to 1024 gigabytes (GB). The storage capacity of digital devices is often measured in these units.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.732Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4590, 18, NULL, NULL, 'If 36 persons can finish 50% of work in 12 days. In how many days 72 person can finish the complete work?', NULL, '[{"text":"6","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"9","image_url":null,"alt":null},{"text":"12","image_url":null,"alt":null}]', NULL, 3, '36 persons can finish 50% of work in 12 days

36 persons can finish 100% of work in 24 days

We have to find 72 persons will take how many days

So, suppose $ x_{1}=36 $, $ y_{1}=24 $, $ x_{2}=72 $, $ y_{2}=? $

Applying inverse proportional formula to solve

As it is the relation between work and time. So, it will be an inverse proportion,

So, $ \frac{x_{2}}{x_{1}} = \frac{y_{1}}{y_{2}} $

$ \Rightarrow \frac{72}{36} = \frac{24}{y_{2}} $

$ = y_{2} = \frac{24 \times 36}{72} = 12 $ days', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.733Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4591, 18, NULL, NULL, 'Who is known as ''Nightingale of India''?', NULL, '[{"text":"Vijaya Laxmi Pandit","image_url":null,"alt":null},{"text":"Indira Gandhi","image_url":null,"alt":null},{"text":"Sarojini Naidu","image_url":null,"alt":null},{"text":"Lata Mangeshkar","image_url":null,"alt":null}]', NULL, 2, 'Sarojini Naidu was known as the Nightingale of India.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.733Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4592, 18, NULL, NULL, 'Which incident led Gandhi ji to with draw non-cooperation movement?', NULL, '[{"text":"Kakori episode","image_url":null,"alt":null},{"text":"Chauri-Chaura episode","image_url":null,"alt":null},{"text":"Yang-bang episode","image_url":null,"alt":null},{"text":"Jallianwala Bagh episode","image_url":null,"alt":null}]', NULL, 1, 'Chauri - Chaura Incident lead Gandhiji to withdrew non-cooperator Movement.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.733Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4593, 18, NULL, NULL, 'A shopkeeper offers discount 50% + 50% on a shirt of M.R.P ₹800, find the selling price of the shirt.', NULL, '[{"text":"₹700","image_url":null,"alt":null},{"text":"₹0","image_url":null,"alt":null},{"text":"₹400","image_url":null,"alt":null},{"text":"₹200","image_url":null,"alt":null}]', NULL, 3, 'A shopkeeper offers discount 50% + 50% on a shirt of M.R.P ₹800

⇒ 50% on a shirt of M.R.P ₹800 = ₹ 400

⇒ A shopkeeper offer discount 50 % = ₹ 200

