INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4594, 18, NULL, NULL, 'Pointing a man in a photograph, Karina Said, ''His mother is the only daughter of my mother,'' How is Karina related to the man of photograph.', NULL, '[{"text":"Mother","image_url":null,"alt":null},{"text":"Sister","image_url":null,"alt":null},{"text":"Wife","image_url":null,"alt":null},{"text":"Daughter","image_url":null,"alt":null}]', NULL, 0, 'Karina will be mother of man in the photograph.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.734Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4595, 18, NULL, NULL, 'If 180 meter long train crosses a pole in 9 seconds, find the speed of train in kilo meter/hour.', NULL, '[{"text":"72 km/h","image_url":null,"alt":null},{"text":"36 km/h","image_url":null,"alt":null},{"text":"20 km/h","image_url":null,"alt":null},{"text":"90 km/h","image_url":null,"alt":null}]', NULL, 0, 'Speed = $ \frac{Distance}{Time} = \frac{Length of train}{Time taken} = \frac{180}{9} $ m/sec = $ 20 \times \frac{18}{5} $ km/hr = 72 km/hr', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.735Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4596, 18, NULL, NULL, 'Match List I with List II', NULL, '[{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null},{"text":"A-III, B-II, C-IV, D-I","image_url":null,"alt":null},{"text":"A-IV, B-I, C-II, D-III","image_url":null,"alt":null},{"text":"A-IV, B-I, C-III, D-II","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q56-table-1.jpg', 'Table for question 56', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.736Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q56-table-1.jpg","alt":"Table for question 56","kind":"table"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4597, 18, NULL, NULL, 'If the cost of 4 pens and 6 note books is 800, then find the cost of 6 pens and 9 note books.', NULL, '[{"text":"₹ 900","image_url":null,"alt":null},{"text":"₹ 1200","image_url":null,"alt":null},{"text":"₹ 1000","image_url":null,"alt":null},{"text":"₹ 1100","image_url":null,"alt":null}]', NULL, 1, 'Let the cost of 1 pen and 1 note book be $ \bar{x} $ x and $ \bar{y} $ respectively.

$ \Rightarrow 4x + 6y = 800 $

$ = 2x + 3y = 400 $

$ \Rightarrow 6x + 9y = 1200 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.736Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4598, 18, NULL, NULL, 'The value of $ \frac{(2\cdot7)^{3}-(2\cdot2)^{3}}{(2\cdot7)^{2}+2\cdot7\times2\cdot2+(2\cdot2)^{2}} $ is', NULL, '[{"text":"4.9","image_url":null,"alt":null},{"text":"0.5","image_url":null,"alt":null},{"text":"0.05","image_url":null,"alt":null},{"text":"0.49","image_url":null,"alt":null}]', NULL, 1, '$ \Rightarrow\frac{(2\cdot7)^{3}-(2\cdot2)^{3}}{(2\cdot7)^{2}+2\cdot7\times2\cdot2+(2\cdot2)^{2}}= $

$ \frac{(2.7-2.2)\left((2.7)^{2}+2.7\times2.2+(2.2)^{2}\right)}{((2.7)^{2}+2.7\times2.2+(2.2)^{2})}=2.7-2.2=0.5 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.737Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4599, 18, NULL, NULL, 'EVM Stands for _.', NULL, '[{"text":"Electric Vending Machine","image_url":null,"alt":null},{"text":"Electronic Vending Machine","image_url":null,"alt":null},{"text":"Electronic Voting Machine","image_url":null,"alt":null},{"text":"Electric Voting Machine","image_url":null,"alt":null}]', NULL, 2, 'EVM stands for Electronic Voting Machine.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.738Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4600, 18, NULL, NULL, 'If the volume of a cube is $ 27cm^3 $, then the diagonal of cube is', NULL, '[{"text":"3 cm","image_url":null,"alt":null},{"text":"$ 3\\sqrt{3} $ cm","image_url":null,"alt":null},{"text":"$ \\sqrt{3} $ cm","image_url":null,"alt":null},{"text":"$ \\frac{1}{\\sqrt{3}} $ cm","image_url":null,"alt":null}]', NULL, 1, 'Volume of cube = (side) $ ^{3} $

Diagonal of cube = $ \sqrt{3} \times $ side

$ \Rightarrow $ (side) $ ^{3} $ = 27

$ \Rightarrow $ side = 3 cm

$ \Rightarrow $ Diagonal of cube = $ 3\sqrt{3} $ cm', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.738Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4601, 18, NULL, NULL, 'An Atoll is _.', NULL, '[{"text":"A lake in the Crates","image_url":null,"alt":null},{"text":"A Lagoon along the shores","image_url":null,"alt":null},{"text":"A lake in Glaciated mountains","image_url":null,"alt":null},{"text":"A ring-shaped island with a lagoon at the Centre","image_url":null,"alt":null}]', NULL, 3, 'An Atoll is a ring-shaped Island with a lagoon at the centre.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.739Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4602, 18, NULL, NULL, 'The area of $ \Delta $ ABF is.', NULL, '[{"text":"180 m $ ^{2} $","image_url":null,"alt":null},{"text":"90 m $ ^{2} $","image_url":null,"alt":null},{"text":"125 m $ ^{2} $","image_url":null,"alt":null},{"text":"60 m $ ^{2} $","image_url":null,"alt":null}]', NULL, 1, 'Given: AC = 25 m, AG = 12 m, BC = 7 m

$ \Rightarrow $ AG + GB + BC = AC

$ \Rightarrow $ 12 + GB + 7 = 25

$ \Rightarrow $ GB = 25 - 12 - 7

$ \Rightarrow $ GB = 25 - 19 = 6 m

$ \Rightarrow $ AB = AG + GB = 12 + 6 = 18 m

In $ \Delta $ ABF

$ \therefore $ Required area = $ \frac{1}{2} \times BF \times AB = \frac{1}{2} \times 10 \times 18 = 90 \, m^{2} $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q62-figure-1.jpg', 'Figure for question 62', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.739Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q62-figure-1.jpg","alt":"Figure for question 62","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4603, 18, NULL, NULL, 'The area of Trapezium DGCE is.', NULL, '[{"text":"100 m $ ^{2} $","image_url":null,"alt":null},{"text":"260 m $ ^{2} $","image_url":null,"alt":null},{"text":"70 m $ ^{2} $","image_url":null,"alt":null},{"text":"130 m $ ^{2} $","image_url":null,"alt":null}]', NULL, 3, 'In Trapezium DGCE

$ \Rightarrow $ Area of trapezium $ \frac{1}{2}(DG + EC) \times GC $

$ =\frac{1}{2}(5 + 15) \times (7 + 6) $

$ =\frac{1}{2} \times 20 \times 13 $

$ =130 \, m^{2} $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q63-figure-1.jpg', 'Figure for question 63', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.739Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q63-figure-1.jpg","alt":"Figure for question 63","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4604, 18, NULL, NULL, 'Area of $ \Delta $ AFC is.', NULL, '[{"text":"$ 85 \\, m^2 $","image_url":null,"alt":null},{"text":"$ 75 \\, m^2 $","image_url":null,"alt":null},{"text":"$ 125 \\, m^2 $","image_url":null,"alt":null},{"text":"$ 250 \\, m^2 $","image_url":null,"alt":null}]', NULL, 2, 'Area of $ \Delta AFC = \frac{1}{2} \times AC \times BF = \frac{1}{2} \times 25 \times 10 = 125 \, m^{2} $', NULL, NULL, 2022, '/local-papers/assets/general-test-2022-10-06-shift-1/q64-figure-1.jpg', 'Figure for question 64', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.740Z', NULL, NULL, '[{"url":"/local-papers/assets/general-test-2022-10-06-shift-1/q64-figure-1.jpg","alt":"Figure for question 64","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4605, 18, NULL, NULL, 'Which country will host the G-20 summit in 2023?', NULL, '[{"text":"Italy","image_url":null,"alt":null},{"text":"Germany","image_url":null,"alt":null},{"text":"Japan","image_url":null,"alt":null},{"text":"India","image_url":null,"alt":null}]', NULL, 3, 'The G-20 summit in 2023 was hosted by India.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.740Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4606, 18, NULL, NULL, 'If 60% of 80 = x% of 96, then x is.', NULL, '[{"text":"50","image_url":null,"alt":null},{"text":"40","image_url":null,"alt":null},{"text":"55","image_url":null,"alt":null},{"text":"45","image_url":null,"alt":null}]', NULL, 0, 'If 60% of 80 = x% of 96

$ \Rightarrow \frac{60}{100} \times 80 = \frac{x}{100} \times 96 $

$ = 48 = \frac{96x}{100} $

$ = x = \frac{48 \times 100}{96} $

$ = x = 50 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.741Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
