INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4612, 13, NULL, NULL, 'Griffith Taylor introduced which concept of human geography?', NULL, '[{"text":"Environmental determinism","image_url":null,"alt":null},{"text":"New determinism","image_url":null,"alt":null},{"text":"Possibilism","image_url":null,"alt":null},{"text":"Dualism","image_url":null,"alt":null}]', NULL, 1, 'The concept of Neo Determinism was introduced by Griffith Taylor which emphasises the middle path or madhyam marg between two ends of environmental determinism and possibilism.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.749Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4613, 13, NULL, NULL, 'Identify scholar, who voiced his concern about the growing scarcity of resources as compared to the human population?', NULL, '[{"text":"Griffith Taylor","image_url":null,"alt":null},{"text":"Robert Malthus","image_url":null,"alt":null},{"text":"Ratzel","image_url":null,"alt":null},{"text":"Karl Marx","image_url":null,"alt":null}]', NULL, 1, 'British economist Thomas Malthus coined the term overpopulation in the late 1700s. Malthus suggested that the world''s population was growing faster than the rate of food production, and as a result, mass starvation would occur.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.750Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4614, 13, NULL, NULL, 'Identify the push factors of migration from the following:

(A) Unemployment

(B) Political turmoil

(C) Peace and Stability

(D) Socio-economic backwardness

(E) Security of life and property

Choose the correct answer from the options given below.

(A)(B)(C) only (D),(E) on', NULL, '[{"text":"(A), (B), (C) only","image_url":null,"alt":null},{"text":"(C), (D), (E) only","image_url":null,"alt":null},{"text":"(A), (C), (D) only","image_url":null,"alt":null},{"text":"(A), (B), (D) only","image_url":null,"alt":null}]', NULL, 3, 'Push factors cause people to leave their residence or place of origin. These are Unemployment, Political turmoil and Socio-economic backwardness from among the given options.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.751Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4615, 13, NULL, NULL, 'Which one of the following approach was proposed by the International Labour Organisation?', NULL, '[{"text":"Capability Approach","image_url":null,"alt":null},{"text":"Welfare Approach","image_url":null,"alt":null},{"text":"Basic Needs Approach","image_url":null,"alt":null},{"text":"Income Approach","image_url":null,"alt":null}]', NULL, 2, 'Basic Needs approach is the answer.

The ILO report for the 1976 World Employment Conference defined basic needs in terms of food, clothing, housing, education, and public transportation. The ILO was founded in October 1919. It is headquartered in Geneva, Switzerland.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.751Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4616, 13, NULL, NULL, 'Continuity in the availability of opportunities is related to which concept of Human Development?', NULL, '[{"text":"Sustainability","image_url":null,"alt":null},{"text":"Equity","image_url":null,"alt":null},{"text":"Productivity","image_url":null,"alt":null},{"text":"Empowerment","image_url":null,"alt":null}]', NULL, 0, 'Sustainability means continuity in the availability of opportunities. To have sustainable human development, each generation must have the same opportunities. All environmental, financial and human resources must be used keeping in mind the future. Misuse of any of these resources will lead to fewer opportunities for future generations.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.751Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4617, 13, NULL, NULL, 'Which one of the following is not a significant aspect of human development?', NULL, '[{"text":"Decent standard of living","image_url":null,"alt":null},{"text":"Living a long and healthier life","image_url":null,"alt":null},{"text":"Guaranteed human rights and personal self respect","image_url":null,"alt":null},{"text":"Leisure and recreation with luxurious mobility","image_url":null,"alt":null}]', NULL, 3, 'A decent standard of living; living a long and healthier life; and guaranteed human rights and persona self-respect are significant aspects of human development.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.752Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4618, 13, NULL, NULL, 'Identify the main features of capability approach to Human Development.

(A) This is the oldest approach to Human Development.

(B) This approach was initially proposed by International Labour Organisation.

(C) This approach is associated with Prof Amartya Sen.

(D) Access to resources is the key to increasing human development.', NULL, '[{"text":"(C) and (A) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(A) and (R) only","image_url":null,"alt":null},{"text":"(A) and (D) only Study the passage and answer questions numbered. Benda lives in the wilds of the Abujh Maad area of central India. His village consists of three huts deep in the wilds. Not even birds or stray dogs that usually crowd villages can be soom1to too rno:tuo2 (vi) seen in these areas. Wearing a small loin cloth and armed with his axe he slowly surveys the penda (forest) where his tribe practices a primitive form of agriculture called shifting cultivation. Benda and his friends burn small patches of forest to clear them for cultivation. The ash is used for making the soil fertile. Benda is happy that the mahua trees around him are in bloom. How lucky I am to be a part of this beautiful universe, he thinks as he looks up to see the Mahua, Palash and Sal trees that have sheltered him since childhood. Crossing the penda in a gliding motion, Benda makes his way to a stream. As he bends down to scoop up a palmful of water, he remembers to thank Loi-Lugi, the spirit of the forest for allowing him to quench his thirst. Moving on with his friends, Benda chews on succulent leaves and roots. The boys have been trying to collect Gajjhara and Kuchla, from the forest. These are special plants that Benda and his people use. He hopes the spirits of the forest will be kind and lead him to these herbs. These are needed to barter in the madhai or tribal fair coming up the next full moon. He closes his eyes and tries hard to recall what the elders had taught him about these herbs and the places they are found in. He wishes he had listened more carefully. Suddenly there is a rustling of leaves. Benda and his friends know it is the outsiders who have come searching for them in the wilds. In a single fluid motion Benda and his friends disappear behind the thick canopy of trees and become one with the spirit of the forest.","image_url":null,"alt":null}]', NULL, 1, 'The capability approach (also referred to as the capabilities approach) is a normative approach to human welfare that concentrates on the actual capability of persons to achieve lives they value rather than solely having a right or freedom to do so. It was conceived in the 1980s as an alternative approach to welfare economics. In this approach, Amartya Sen and Martha Nussbaum combine a range of ideas that were previously excluded from (or inadequately formulated in) traditional approaches to welfare economics. The core focus of the capability approach is improving access to the resources people use to live a fulfilling life.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.752Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4619, 13, NULL, NULL, 'To which one of the following ''Benda'' represents as given in the passage?', NULL, '[{"text":"Tribe living in the area","image_url":null,"alt":null},{"text":"Cultivator","image_url":null,"alt":null},{"text":"Trader","image_url":null,"alt":null},{"text":"Hunter","image_url":null,"alt":null}]', NULL, 0, 'From the passage it is clear that Benda is a cultivator.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.752Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4620, 13, NULL, NULL, 'To which one of the following ''Penda'' is referred in the text?', NULL, '[{"text":"A tribe (vi)-(C)","image_url":null,"alt":null},{"text":"A hut","image_url":null,"alt":null},{"text":"Forest (vi)-(C)","image_url":null,"alt":null},{"text":"Succulent leaves","image_url":null,"alt":null}]', NULL, 2, 'Penda refers to the forest.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.753Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4621, 13, NULL, NULL, 'Benda went to the forest for $ \underline{\text{for}} $.', NULL, '[{"text":"For hunting","image_url":null,"alt":null},{"text":"For bringing wood","image_url":null,"alt":null},{"text":"For collecting herbs","image_url":null,"alt":null},{"text":"For cultivating land","image_url":null,"alt":null}]', NULL, 2, 'Benda went to the forest for collecting herbs.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.753Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4622, 13, NULL, NULL, 'Which one of the following products were collected by Benda?', NULL, '[{"text":"Loi-Lungi","image_url":null,"alt":null},{"text":"Gajjhara and Kuchla","image_url":null,"alt":null},{"text":"Mahua and Palash","image_url":null,"alt":null},{"text":"Sal and Neen","image_url":null,"alt":null}]', NULL, 1, 'Benda and his friends had been trying to collect Gajjhara and Kuchla.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.754Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4623, 13, NULL, NULL, 'At which of the following places, Benda exchanges collected herbal parts?', NULL, '[{"text":"Mathai tribal fair","image_url":null,"alt":null},{"text":"Madhai tribal fair","image_url":null,"alt":null},{"text":"Mithai tribal fair","image_url":null,"alt":null},{"text":"Midhai tribal fair","image_url":null,"alt":null}]', NULL, 1, 'Benda exchanges collected herbal plants from Madhai tribal fair.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.754Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4624, 13, NULL, NULL, 'The Silicon valley near San Francisco and Silicon Forest near Seattle are example of which type of industry?', NULL, '[{"text":"Iron and Steel","image_url":null,"alt":null},{"text":"Cotton Textile","image_url":null,"alt":null},{"text":"Information technology","image_url":null,"alt":null},{"text":"Chemical","image_url":null,"alt":null}]', NULL, 2, 'Silicon Valley near San Francisco and Silicon Forest near Seattle are examples of Information Technology industries.

The term Silicon Valley refers to a region in the South San Francisco Bay Area. The name was first adopted in the early 1970s because of the region''s association with the silicon transistor, which is used in all modern microprocessors. The area is notable for the vast number of technology companies that are headquartered there.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.754Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
