Viticulture: Mediterranean region', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.755Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4626, 13, NULL, NULL, 'Which one of the following is the most important crop is western part of Indo-Gangetic plain?', NULL, '[{"text":"Soyabean","image_url":null,"alt":null},{"text":"Sorghum","image_url":null,"alt":null},{"text":"Wheat","image_url":null,"alt":null},{"text":"Barley","image_url":null,"alt":null}]', NULL, 2, 'Wheat is grown in western part of Indo-Gangetic Plains.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.755Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4627, 13, NULL, NULL, 'Which one of the following is an appropriate reason for low productivity per labour in intensive subsistence farming?', NULL, '[{"text":"More labour is used on small piece of land","image_url":null,"alt":null},{"text":"More labour is used on large piece of land","image_url":null,"alt":null},{"text":"Less labour is used on large piece of land","image_url":null,"alt":null},{"text":"Less labour is used on small piece of land","image_url":null,"alt":null}]', NULL, 0, 'In Intensive Subsistence agriculture more labour is used on small piece of land.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.755Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4628, 13, NULL, NULL, 'Which one of the following crop grown in intensive subsistence agriculture in wet regions of monsoonal Asia?', NULL, '[{"text":"Wheat","image_url":null,"alt":null},{"text":"Sorghum","image_url":null,"alt":null},{"text":"Paddy","image_url":null,"alt":null},{"text":"Barley","image_url":null,"alt":null}]', NULL, 2, 'Paddy is not grown in Monsoonal Asia.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.756Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4629, 13, NULL, NULL, 'Intensive Subsistence Agriculture means:', NULL, '[{"text":"growing crops for export","image_url":null,"alt":null},{"text":"growing crops for own consumption","image_url":null,"alt":null},{"text":"growing crops for selling in the market","image_url":null,"alt":null},{"text":"growing crops for food industries","image_url":null,"alt":null}]', NULL, 1, 'Growing crops for own consumption is a characteristic of Intensive Subsistence agriculture.

The sentence, "Due to the difference in relief, climate soil and some of the other geographical factors, it is not practical to grow paddy in many parts of monsoon Asia" shows that intensive subsistence agriculture is not found only in high monsoon regions.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.756Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4630, 13, NULL, NULL, 'Paper industry is associated with which of the following industries?', NULL, '[{"text":"Forest-based","image_url":null,"alt":null},{"text":"Mineral-based","image_url":null,"alt":null},{"text":"Agro-based","image_url":null,"alt":null},{"text":"Chemical-based","image_url":null,"alt":null}]', NULL, 0, 'Forest-based Industry includes- the paper industry, match industry, silk industry, lac industry, sports goods industry and handicraft.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.756Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4631, 13, NULL, NULL, 'Which one of the following activity is not a tertiary activity?', NULL, '[{"text":"Trade activities","image_url":null,"alt":null},{"text":"Services in Government offices","image_url":null,"alt":null},{"text":"Dairy farming","image_url":null,"alt":null},{"text":"Transport activities","image_url":null,"alt":null}]', NULL, 2, 'Dairy farming is a Primary activity and not tertiary. The tertiary sector covers a wide range of activities from commerce to administration, transport, financial and real estate activities, business and personal services, education, health and social work.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.757Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4632, 13, NULL, NULL, 'Identify the country from the below given options, where milk is supplied through pipelines from farms to factories:', NULL, '[{"text":"Denmark","image_url":null,"alt":null},{"text":"USA","image_url":null,"alt":null},{"text":"Australia","image_url":null,"alt":null},{"text":"New Zealand","image_url":null,"alt":null}]', NULL, 3, 'New Zealand is the country where milk is supplied through pipelines.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.757Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4633, 13, NULL, NULL, 'Arrange the events in order of land transport development:

(A) Animals were used as beasts of burden.

(B) Invention of wheel, use of carts and wagons.

(C) Railway line development and transport.

(D) Human beings as carriers.

Choose the correct answer from the options given below:

(a) (D), (A), (B), (C) (b) (A), (D), (B), (C)

(c) (D), (B), (A), (C) (d) (A), (D), (C), (B)

(27. Match List-I with List-II

List-I

Terms

(A) Network links

(B) Nodes

(C) Developed Network links

(D) Link

(ii) Madeup of nodes and link

(iii) Every road that joins two nodes

(iv) Meeting point of two or more routes', NULL, '[{"text":"(A)-(ii), (B)-(i), (C)-(iv), (D)-(iii)","image_url":null,"alt":null},{"text":"(A)-(ii), (B)-(iv), (C)-(i), (D)-(iii)","image_url":null,"alt":null},{"text":"(A)-(ii), (B)-(iii), (C)-(i), (D)-(iv)","image_url":null,"alt":null},{"text":"(A)-(iii), (B)-(iv), (C)-(i), (D)-(ii)","image_url":null,"alt":null}]', NULL, 0, 'Human beings were first used as carriers, after which animals started becoming the beasts of burden. In modern times, later, the invention of wheel, use of carts and wagons took place after which railway lines and transport development began.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.757Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4634, 13, NULL, NULL, 'Which one of the following does not fall on trans-Siberian Railway Route?

(A) Irkutsk (B) Baku

(C) Moscow (D) Khabarovsk

(E) Ulan Bator', NULL, '[{"text":"(B), (D) only","image_url":null,"alt":null},{"text":"(C), (D) only","image_url":null,"alt":null},{"text":"(B), (E) only","image_url":null,"alt":null},{"text":"(D), (E) only","image_url":null,"alt":null}]', NULL, 2, 'The trans-siberian Railways major rail route of Russia runs from St. Petersburg in the west to Vladivostok on the Pacific Coast in the east passing through Moscow, Ufa, Novosibirsk, Irkutsk, Chita and Khabarovsk.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.758Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4635, 13, NULL, NULL, 'Match List-I with List-II

(A) ASEAN (i) Belgium

(B) OPEC (ii) Uruguay

(C) EU (iii) Indonesia

(D) LAIA (iv) Austria', NULL, '[{"text":"(A)-(iv), (B)-(iii), (C)-(ii), (D)-(i)","image_url":null,"alt":null},{"text":"(A)-(i), (B)-(ii), (C)-(iv), (D)-(iii)","image_url":null,"alt":null},{"text":"(A)-(iii), (B)-(ii), (C)-(i), (D)-(iv)","image_url":null,"alt":null},{"text":"(A)-(iii), (B)-(iv), (C)-(i), (D)-(ii)","image_url":null,"alt":null}]', NULL, 3, 'ASEAN officially the Association of Southeast Asian Nations, is a political and economic union of member states in Southeast Asia, which promotes intergovernmental cooperation and facilitates economic, political, security, military, educational, and sociocultural integration between its members and countries in the Asia-Pacific. It is headquartered in Indonesia.

The Organization of the Petroleum Exporting Countries is a cartel of 13 countries. Founded on 14 September 1960 in Baghdad by the first five members (Iran, Iraq, Kuwait, Saudi Arabia, and Venezuela), it has, since 1965, been headquartered in Vienna, Austria, although Austria is not an OPEC member state. As of September 2018, the 13 member countries accounted for an estimated 44 percent of global oil production and 81.5 percent of the world''s proven oil reserves.

European Union (EU), international organization comprising 27 European countries and governing common economic, social, and security policies. It is headquartered in Belgium.

Latin American Integration Association was established by the Treaty of Montevideo (August 1980) and became operational in March 1981. It seeks

economic cooperation among its members. It is headquartered in Uruguay.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.758Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4636, 13, NULL, NULL, 'Which one of the following are types of international trade?

(A) Bilateral trade (B) Unilateral trade

(C) Multi-lateral trade (D) Collateral trade', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'Bilateral trade: Bilateral trade is done by two countries with each other. They enter into agreement to trade specified commodities amongst them. For example, country A may agree to trade some raw material with agreement to purchase some other specified item to country B or vice versa. Multi-lateral trade: As the term suggests multi-lateral trade is conducted with many trading countries. The same country can trade with a number of other countries. The country may also grant the status of the "Most Favoured Nation" (MFN) on some of the trading partners.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.759Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4637, 13, NULL, NULL, 'The first complete population census in India was conducted in which one of the following years?', NULL, '[{"text":"1881","image_url":null,"alt":null},{"text":"1872","image_url":null,"alt":null},{"text":"1891","image_url":null,"alt":null},{"text":"1951","image_url":null,"alt":null}]', NULL, 0, 'The first population Census in India was conducted in 1872 and the first complete Census was conducted only in 1881.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.761Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4638, 13, NULL, NULL, 'Arrange the following states in ascending order in terms of their literacy rate according to (census 2011):

(A) Gujarat (B) Uttar Pradesh

(C) Bihar (D) Punjab', NULL, '[{"text":"(A), (D), (B), (C)","image_url":null,"alt":null},{"text":"(A), (D), (C), (B)","image_url":null,"alt":null},{"text":"(C), (B), (D), (A)","image_url":null,"alt":null},{"text":"(C), (B), (A), (D)","image_url":null,"alt":null}]', NULL, 0, 'Correct order: - Gujarat-78.03%

Punjab-75.84%

Uttar Pradesh-67.68%

Bihar-61.80%', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.762Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4639, 13, NULL, NULL, 'Identify the major cause of female migration in India:', NULL, '[{"text":"Employment","image_url":null,"alt":null},{"text":"Education","image_url":null,"alt":null},{"text":"Marriage","image_url":null,"alt":null},{"text":"Health care","image_url":null,"alt":null}]', NULL, 2, 'Marriage is the biggest reason why women migrate from one place to another. The findings from 2011 Census, which were published recently show that marriage made up for 46 percent of the total migrations in India, of which 97 percent are women.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.763Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4640, 13, NULL, NULL, 'Arrange the trend of migration from India in chronological order.

(A) Highly qualified professionals

(B) Professional artisans and traders

(C) Indentured labourers

(D) Out flow of entrepreneurs', NULL, '[{"text":"(C), (B), (D), (A)","image_url":null,"alt":null},{"text":"(C), (D), (A), (B)","image_url":null,"alt":null},{"text":"(D), (B), (C), (A)","image_url":null,"alt":null},{"text":"(C), (A), (B), (D)","image_url":null,"alt":null}]', NULL, 3, 'The correct option is (d).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.764Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4641, 13, NULL, NULL, 'In which one of the following states, people live in compact villages for security and defence purposes?', NULL, '[{"text":"Nagaland","image_url":null,"alt":null},{"text":"Uttar Pradesh","image_url":null,"alt":null},{"text":"Bihar","image_url":null,"alt":null},{"text":"Maharashtra","image_url":null,"alt":null}]', NULL, 0, 'Compact villages are built by the people in Nagaland, mainly for defence and security purpose.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.764Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4642, 13, NULL, NULL, 'Where do we find Linear Rural Settlement Pattern?', NULL, '[{"text":"Mountain Valleys","image_url":null,"alt":null},{"text":"Along Rivers","image_url":null,"alt":null},{"text":"Around Lakes","image_url":null,"alt":null},{"text":"Near big water Body","image_url":null,"alt":null}]', NULL, 2, 'Linear Rural settlement plan is found along a road, railway line, river, canal edge of a valley or along a levee.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.764Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4643, 13, NULL, NULL, 'Which one of the following option is NOT true for the transformation of previously thinly populated areas into moderate to high concentration of population areas currently?', NULL, '[{"text":"Development of irrigation in Rajasthan","image_url":null,"alt":null},{"text":"Mining of mineral and energy resources (Jharkhand)","image_url":null,"alt":null},{"text":"Increase in irrigation in Arunachal Pradesh","image_url":null,"alt":null},{"text":"Development of transport","image_url":null,"alt":null}]', NULL, 2, 'Increase of irrigation in Arunachal Pradesh is not a factor.

Development of irrigation (Rajasthan), availability of mineral and energy resources (Jharkhand) and development of transport network (Peninsular States) have resulted in moderate to high concentration of population in areas which were previously very thinly populated.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.765Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4644, 13, NULL, NULL, 'Identify the type of settlement which are fragmented and separated?', NULL, '[{"text":"Clustered settlements","image_url":null,"alt":null},{"text":"Semi-clustered settlements","image_url":null,"alt":null},{"text":"Hamleted settlements","image_url":null,"alt":null},{"text":"Dispersed settlements","image_url":null,"alt":null}]', NULL, 2, 'Sometimes settlement is fragmented into several units physically separated from each other bearing a common name. These units are locally called panna, para, palli, nagla, dhani, etc. in various parts of the country. Such settlements are called as hamleted settlements.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.765Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4645, 13, NULL, NULL, 'Green Revolution is successful in North Western part of the country, select the reasons.', NULL, '[{"text":"Ample Rainfall","image_url":null,"alt":null},{"text":"Use of high yielding varieties of seeds","image_url":null,"alt":null},{"text":"Easily available labour","image_url":null,"alt":null},{"text":"More employment pressure on agriculture (E) 85% not shown area is cultivated through irrigation","image_url":null,"alt":null}]', NULL, 0, 'Use of high yielding varieties of seeds as well as as well as majority of net sown area being under cultivation through irrigation are the reasons for successful green revolution in the country.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.766Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4646, 13, NULL, NULL, 'The highest proportion of the total water used in the country is in which one of the following sectors?', NULL, '[{"text":"Industries","image_url":null,"alt":null},{"text":"Irrigation","image_url":null,"alt":null},{"text":"Domestic use","image_url":null,"alt":null},{"text":"Electricity production","image_url":null,"alt":null}]', NULL, 1, 'Irrigation by far is the largest user of India''s water reserve with hooping usage of 78% of total water reserve, followed by domestic sector (6%) and industrial sector (5%) (PIB 2013).', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.766Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4647, 13, NULL, NULL, 'Match List-I with List-II

List-I List-II

Water Resource of India Characteristics

(A) India''s percentage of (i) 1,869 cubic km

World''s Water Resource

(B) Annual volume of available (ii) 4 percent water from precipitation

(C) Availability from surface (iii) 4,000 cubic km water and replenishable ground water

(D) Total utilisable water (iv) 1,122 cubic km', NULL, '[{"text":"(A)-(iii), (B)-(ii), (C)-(i), (D)-(iv)","image_url":null,"alt":null},{"text":"(A)-(ii), (B)-(i), (C)-(iv), (D)-(iii)","image_url":null,"alt":null},{"text":"(A)-(iv), (B)-(ii), (C)-(i), (D)-(iii)","image_url":null,"alt":null},{"text":"(A)-(ii), (B)-(iii), (C)-(i), (D)-(iv)","image_url":null,"alt":null}]', NULL, 1, 'India''s percentage of World water resource: 4% Annual Volume of available water from participation: 1869 cubic metre

Availability from surface water and replenishable ground water: 1122 cubic metre

Total Utilizable water: 4000 cubic metre', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.766Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4648, 13, NULL, NULL, 'Which one of the following is not a broad belt of mineral mines?', NULL, '[{"text":"The North Eastern Plateau Region","image_url":null,"alt":null},{"text":"The South-Western Plateau Region","image_url":null,"alt":null},{"text":"The South Eastern Plateau Region","image_url":null,"alt":null},{"text":"The North Western Plateau Region","image_url":null,"alt":null}]', NULL, 2, 'The South-Eastern plateau region does not have broad belt of minerals.

In the north-eastern plateau region, Iron and Steel industry is located.

South Western Plateau belt is rich in ferrous metals and bauxite. It also contains high grade iron ore, manganese and limestone. This belt lacks in coal deposits except Neyveli lignite.

The North-Western region has Copper, zinc, dolomite, limestone, petroleum deposits and salt.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.767Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4649, 13, NULL, NULL, 'Which of the following sector is labour-intensive and provide employment to semi-skilled workers?', NULL, '[{"text":"Handloom sector","image_url":null,"alt":null},{"text":"Power loom sector","image_url":null,"alt":null},{"text":"Mill sectors","image_url":null,"alt":null},{"text":"Joint sector","image_url":null,"alt":null}]', NULL, 0, 'Handloom industry is labour intensive and provides employment to semi-skilled labour force. The handloom sector of India is one of the biggest unorganized economic activities. The handloom industry in India has a long tradition of outstanding artisanship that represents and preserves vibrant Indian culture.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.767Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4650, 13, NULL, NULL, 'From the given options below, identify the programme NOT directed for spatial target areas development:', NULL, '[{"text":"Marginal farmers development programme","image_url":null,"alt":null},{"text":"Desert development programme","image_url":null,"alt":null},{"text":"Command area development programme","image_url":null,"alt":null},{"text":"Hill area development programme","image_url":null,"alt":null}]', NULL, 0, 'Marginal Farmers Development Programme is not directed at Spatial Target Areas Development.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.768Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4651, 13, NULL, NULL, 'Which one of the following is not a part of watershed management programme in India?', NULL, '[{"text":"Haryali","image_url":null,"alt":null},{"text":"Neeru-Meeru","image_url":null,"alt":null},{"text":"Khushhali","image_url":null,"alt":null},{"text":"Arvary Pani Sansad","image_url":null,"alt":null}]', NULL, 2, 'Khushhali is not a part of the watershed management Programme.

Haryali is a watershed development project sponsored by the Central Government which aims at enabling the rural population to conserve water for drinking, irrigation, fisheries and afforestation.

Neeru-Meeru (Water and You) programme (in Andhra Pradesh) and Arvary Pani Sansad (in Alwar, Rajasthan) have taken up constructions of various water-harvesting structures such as percolation tanks, dug out ponds (Johad), check dams, etc., through people''s participation.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.768Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4652, 13, NULL, NULL, 'Choose the correct option for the availability of specialised goods and services.', NULL, '[{"text":"Periodic Market","image_url":null,"alt":null},{"text":"Rural Market","image_url":null,"alt":null},{"text":"Urban Market","image_url":null,"alt":null},{"text":"Retail Market","image_url":null,"alt":null}]', NULL, 0, 'Periodic market is the one for the availability of specialized goods and services.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.768Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4653, 13, NULL, NULL, 'Which one of the following is not a part of Indian railway?', NULL, '[{"text":"Broad Gauge","image_url":null,"alt":null},{"text":"Narrow Gauge","image_url":null,"alt":null},{"text":"Nano Gauge","image_url":null,"alt":null},{"text":"Meter Gauge","image_url":null,"alt":null}]', NULL, 2, 'On the basis of the width of track of the Indian Railways, three categories have been made: Broad gauge: The distance between rails in broad gauge is 1.676 metre. The total length of broad gauge lines was 63950 km (2019-20).

Metre gauge: The distance between rails is one metre. Its total length was 2402 km (2019-20).

Narrow gauge: The distance between the rails in this case is 0.762 metre or 0.610 metre. The total length of narrow gauge was 1604 km (2019-20). It is generally confined to hilly areas.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.769Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4654, 13, NULL, NULL, 'Which one of the following roads constitutes highest percent of total road length in country?', NULL, '[{"text":"National Highways","image_url":null,"alt":null},{"text":"Rural Roads","image_url":null,"alt":null},{"text":"State Highways","image_url":null,"alt":null},{"text":"Major District Roads","image_url":null,"alt":null}]', NULL, 1, 'These roads are vital for providing links in the rural areas. About 80 per cent of the total road length in India are categorised as rural roads.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.769Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4655, 13, NULL, NULL, 'Which of the following continent has highest "Highways" road density?', NULL, '[{"text":"Europe","image_url":null,"alt":null},{"text":"North America","image_url":null,"alt":null},{"text":"Australia","image_url":null,"alt":null},{"text":"Asia","image_url":null,"alt":null}]', NULL, 1, 'North America has highest highway road density, about 0.65 km per sq km. Every place is within 20 km distance from a highway. Cities located on the Pacific coast (west) are well-connected with those of the Atlantic Coast (east). Likewise, the cities of Canada in the north are linked with those of Mexico in the south.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.770Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4656, 13, NULL, NULL, 'Arrange the following Radio broadcasting development in chronological order:

(A) Radio broadcasting started by the Radio club of Bombay.

(B) Changed to Akashwani

(C) Changed to All India Radio

(D) Broadcasting system adopted

Choose the correct answer from the options given below:

(a) (D)(A)(B)(C)(b) (A)(D)(C)(B)', NULL, '[{"text":"(D),(A),(B),(C)","image_url":null,"alt":null},{"text":"(A),(D),(C),(B)","image_url":null,"alt":null},{"text":"(D),(A),(C),(B)","image_url":null,"alt":null},{"text":"(A),(B),(C),(D)","image_url":null,"alt":null}]', NULL, 1, 'Radio broadcasting started in India in 1923 by the Radio Club of Bombay. Since then, it gained immense popularity and changed the sociocultural life of people. Within no time, it made a place in every household of the country. Government took this opportunity and brought this popular mode of communication under its control in 1930 under the Indian Broadcasting System. It was changed to All India Radio in 1936 and to Akashwani in 1957.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.770Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4657, 2, NULL, NULL, 'पयोरवण प्रदूषण की समस्त आपदारों किसकी बनाई हुई है?', NULL, '[{"text":"ईश्वर","image_url":null,"alt":null},{"text":"मनुष्य","image_url":null,"alt":null},{"text":"प्रकृति","image_url":null,"alt":null},{"text":"उर्लाग","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.773Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
