INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4682, 2, NULL, NULL, 'निम्नलिखित गणनाश को पदकर उसके आधार पर प्रश्नों का उत्तर दीर्घा।\nउत्साद यास्तय में कर्म और फल की मिली-जुली अनुमृति है जिसकी प्रेरणा से तत्परता आती है। यदि फल दूर ही पर विख्याई पड़े, उसकी भावना के साथ ही उसका लेशमात्र भी कर्म या प्रयत्न के साथ लगाय न मालूम हो तो हमारे हाथ-पाँव कभी न उठे और उस फल के साथ हमारा संयोग ही न हो। इससे कर्म शृष्टता की पहली कड़ी पकड़ते ही फल के आंनद की भी कुछ अनुमृति होने लगती है। यदि हम यह निश्चय हो जाए की अमुक स्थान पर जाने से हम किसी प्रिय व्यक्ति का दर्शन होगा तो उस निश्चय के प्रभाव से हमारी यात्रा भी अत्येत प्रिय हो जाएगी। हम चल पड़ेगे और हमारे अंगों की प्रत्येक गति में प्रफुल्लाता दिखारें देगी। यही प्रफुल्लाता कितन-से-कितन कर्मों के साधन में ही देखी जाती है। ये कर्म भी प्रिय हो जाते हैं और अच्छे लगने लगते हैं। जब तक फल तक पहुंचनेवाला कर्म-पथ अच्छा न लगेगा तब तक केवल फल का अच्छा लगना कुछ नहीं। फल की इच्छा मात्र हृदय में रखकर जो प्रयत्न किया जाएगा यह अभावमय और
मनुष्य को कर्म करने से पूर्व/किसी विशेष लाभ की प्राप्ति की सूचना होती है, तो उसका चित कैसा हो जाता है ?', NULL, '[{"text":"दुर्बल","image_url":null,"alt":null},{"text":"प्रफ़्रीलात्","image_url":null,"alt":null},{"text":"विरुक्त","image_url":null,"alt":null},{"text":"निष्फय","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.788Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
