INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4685, 2, NULL, NULL, 'निम्नलिखित गवाहों को पढ़कर उसके आधार पर प्रश्न का उत्तर दीर्घकाल $ \downarrow $ उत्साद वास्तव में कर्म और फल की मिली--जुली अनुमौதி है जिसकी प्रेरणा से तत्पश्चात्तिकी होती है। यदि फल दूर ही पर विस्तृत पड़े, उसकी भावना के साथ ही उसका लेशमात्र भी कर्म या प्रयत्न के साथ लगाय न मालूम हो तो हमारे हाथ--पाँच कभी न उठे और उस फल के साथ हमारा संयोग ही न हो। इससे कर्म शुश्ला की पहली कड़ी पकड़ते ही फल
कर्म-रामायण के आधार की बेहरी हो गई। किसी व्यक्ति को नीचे बहुत दूर तक गई हुई सीबीएी दिखारें दी और यह मालूम हुआ कि नीचे उतरने पर सोने का डेर मिलेगा। यदि उसमें इतनी सजीवता है कि उक्त सूचना के साथ ही वह उस स्वर्ण-राशि के साथ एक प्रकार के मान्यिक संयोग का अनुभव करने लगा तथा उसका चित प्रफुल्ल और अंग संचेष्ट हो गए, उसे एक-एक सीबी एस्नमयी दिखारें देगी, एक-एक सीबी उत्तरने में उसे आनंद मिला जाएगा, एक-एक भण उसे सुख से बीतता हुआ जान पड़ेगा और वह प्रसनता के साथ स्वर्णराशि तक पहुंचेगा। इस प्रकार उसके प्रयत-काल को भी फल-प्राप्त होता के अंतर्गत ही समझना चाहिए। इसके विरुद्ध यदि उसका हृदय दुर्बल होगा और उसमें इच्छामात्र ही उत्पन्न होकर रह जायँगेगी, तो अभाव के बोध के कारण उसके चित न में यही होगा कि कैसे ड्रट से नीचे पहुंच जाएं उसे एक-एक सीबी उत्तरना बुरा मालूम होगा और आश्रय नहीं कि वह या तो हाथकर बैठ जाए या लाइखडारक मुँह के बैला गिरे गये।
"जब तक फल तक पहुंचने याला कर्म-पथ अच्छा न लगेगा तब तक केवल फल का अच्छा लगना कुछ नहीं?" इस वाक्यां में कर्म-पथ का क्या आश्रय है?', NULL, '[{"text":"कर्म से मुवीत","image_url":null,"alt":null},{"text":"कर्म की प्रांति","image_url":null,"alt":null},{"text":"कर्म से आश्रित","image_url":null,"alt":null},{"text":"कर्म करने का सही मार्ग","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.789Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
