INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4778, 11, NULL, NULL, 'How did Gandhiji broaden the basis of Nationalism : (A) New branches of Congress were set up in various parts of India (B) A series of ''Praja Mandals'' were established to promote nationalist creed in the princely states (C) Gandhiji encouraged communication of nationalist message in the mother tongue (D) Gandhiji was not able to gather support of Indian entrepreneurs and industrialists Choose the correct answer from the options given below :', NULL, '[{"text":"(A), (D), (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) only","image_url":null,"alt":null},{"text":"(C) & (D) only","image_url":null,"alt":null},{"text":"(A) and (B) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.850Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
