INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4782, 11, NULL, NULL, 'The leader of the Muslim League who drafted the Pakistan Resolution was :\n', NULL, '[{"text":"Khan Abdul Gaffar Khan\\n","image_url":null,"alt":null},{"text":"Maulana Azad\\n","image_url":null,"alt":null},{"text":"Sikandar Hayat Khan\\n","image_url":null,"alt":null},{"text":"Muhammad Iqbal","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.852Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4783, 11, NULL, NULL, 'Admist all the turmoil of the partition one man''s valiant efforts to restore communal harmony bore fruit. Who is being discussed in there lines ? Choose the correct option.', NULL, '[{"text":"B.N. Rau","image_url":null,"alt":null},{"text":"Rajendra Prasad","image_url":null,"alt":null},{"text":"Mahatma Gandhi","image_url":null,"alt":null},{"text":"Maulana Azad","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.852Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4784, 11, NULL, NULL, 'Read the passage given below and answer. From the Fifth Report Referring to the condition of zamindars and the auction of lands, the Fifth Report stated: The revenue was not realised with punctuality, and lands to a considerable extent were periodically exposed to sale by auction. In the native year 1203, corresponding with 1796-97, the land advertised for sale comprehended a jumma or assessment of siccarupees 28,70,061, the extent of land actually sold bore a jumma or assessment of 14,18,756, and the amount of purchase money siccarupees 17,90,416. In 1204, corresponding with 1797-98, the land advertised was for siccarupees 26,66,191, the quantity sold was for siccarupees 22,74,076, and the purchase money siccarupees 21,47,580. Among the defaulters were some of the oldest families of the country. Such were the rajah of Nuddea, Rajeshaye, Bishenpore (all districts of Bengal), ... and others, the dismemberment of whose estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in their efforts to preserve undiminished the amount of public assessment. Name the British East India company official who introduced the Permanent Settlement?', NULL, '[{"text":"Lord William Bentinck","image_url":null,"alt":null},{"text":"Lord Cornwallis","image_url":null,"alt":null},{"text":"Lord Hastings","image_url":null,"alt":null},{"text":"Lord Wellesley","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.852Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4785, 11, NULL, NULL, 'Read the passage given below and answer. From the Fifth Report Referring to the condition of zamindars and the auction of lands, the Fifth Report stated: The revenue estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in their efforts to preserve undiminished the amount of public assessment. Name the British East India company official who introduced the Permanent Settlement? (1) Lord William Bentinck (2) Lord Cornwallis (3) Lord Hastings (4) Lord Wellesley
The revenue was not realised with punctuality, and lands to a considerable extent were periodically exposed to sale by auction. In the native year 1203, corresponding with 1796-97, the land advertised for sale comprehended a jumma or assessment of siccarupees 28,70,061, the extent of land actually sold bore a jumma or assessment of 14,18,756, and the amount of purchase money siccarupees 17,90,416. In 1204, corresponding with 1797-98, the land advertised was for siccarupees 26,66,191, the quantity sold was for siccarupees 22,74,076, and the purchase money siccarupees 21,47,580. Among the defaulters were some of the oldest families of the country. Such were the rajah of Nuddea, Rajeshaye, Bishenpore (all districts of Bengal), ... and others, the dismemberment of whose estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in the efforts to preserve undiminished the amount of public assessment. What were the officials trying to show through the figures? (A) Maladministration, corruption and misrule by East India Company (B) Drawbacks of the system of Permanent Settlement (C) Inefficiency in Revenue collection (D) Collapse of the traditional Zamindari power Choose the correct answer from the options given below:', NULL, '[{"text":"(A) and (D) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(B) and (D) only","image_url":null,"alt":null},{"text":"(A) and (C) only","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.853Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
