INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4788, 11, NULL, NULL, 'From the Fifth Report
Referring to the condition of zamindars and the auction of lands, the Fifth Report stated:
The revenue was not realised with punctuality, and lands to a considerable extent were periodically exposed to sale by auction. In the native year 1203, corresponding with 1796-97, the land advertised for sale comprehended a jumma or assessment of sicca rupees 28,70,061, the extent of land actually sold bore a jumma or assessment of 14,18,756, and the amount of purchase money sicca rupees 17,90,416. In 1204, corresponding with 1797-98, the land advertised was for sicca rupees 26,66,191, the quantity sold was for sicca rupees 22,74,076, and the purchase money sicca rupees 21,47,580. Among the defaulters were some of the oldest families of the country. Such were the rajahs of Nuddea, Rajeshaye, Bishenpore (all districts of Bengal), ... and others, the dismemberment of whose estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in their efforts to preserve undiminished the amount of public assessment.
The British East India Company had issued a decree that property of would not be taken over, even in the case of non-payment of revenue.', NULL, '[{"text":"Women","image_url":null,"alt":null},{"text":"Poor Peasants","image_url":null,"alt":null},{"text":"Kings","image_url":null,"alt":null},{"text":"Jotedars","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.854Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4789, 11, NULL, NULL, 'Read the passage given below to answer.
"I believe separate electorates will be suicidal to the minorities"
During the debate on 27 August 1947, Govind Ballabh Pant said: I believe separate electorates will be suicidal to the minorities and will do them tremendous
I believe separate electorates will be suicidal to the minorities and will do them tremendous harm. If they are isolated for ever, they can never convert themselves into a majority and the feeling of frustration will cripple them even from the very beginning. What is it that you desire and what is our ultimate objective? Do the minorities always want to remain as minorities or do they ever expect to form an integral part of a great nation and as such to guide and control its destinies? If they do, can they ever achieve that aspiration and that ideal if they are isolated from the rest of the community? I think it would be extremely dangerous for them if they were segregated from the rest of the community and kept aloof in an air-tight compartment where they would have to rely on others even for the air they breath. The minorities if they are returned by separate electorates can never have any effective voice.
Which minister from Madras made a powerful plea for continuing separate electorates?', NULL, '[{"text":"R.V. Dhulekar","image_url":null,"alt":null},{"text":"Pocker Bahadur","image_url":null,"alt":null},{"text":"Sardar Vallabhbhai Patel","image_url":null,"alt":null},{"text":"Govind Ballabh Pant","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.854Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4790, 11, NULL, NULL, 'Read the passage given below to answer.
"I believe separate electorates will be suicidal to the minorities"
During the debate on 27 August 1947, Govind Ballabh Pant said:
I believe separate electorates will be suicidal to the minorities and will do them tremendous harm. If they are isolated for ever, they can never convert themselves into a majority and the feeling of frustration will cripple them even from the very beginning. What is it that you desire and what is our ultimate objective? Do the minorities always want to remain as minorities or do they ever expect to form an integral part of a great nation and as such to guide and control its destinies? If they do, can they ever achieve that aspiration and that ideal if they are isolated from the rest of the community? I think it would be extremely dangerous for them if they were segregated from the rest of the community and kept aloof in an air-tight compartment where they would have to rely on others even for the air they breath. The minorities if they are returned by separate electorates can never have any effective voice.
Separate electorates was a "poison that has entered the body politic of our country" was declared by:', NULL, '[{"text":"R.V. Dhulekar","image_url":null,"alt":null},{"text":"Pocker Bahadur","image_url":null,"alt":null},{"text":"Sardar Vallabhbhai Patel","image_url":null,"alt":null},{"text":"Begam Aizaz Rosul","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.855Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
