INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4828, 3, NULL, NULL, 'Let R be the relation in the set $A=\{a, b, c, d\}$ given by $R=\{(a, a), (b, b), (c, c), (a, b), (b, a), (c, d), (d, d), (d, c)\}$', NULL, '[{"text":"R is reflexive and symmetric but not transitive","image_url":null,"alt":null},{"text":"R is reflexive and transitive but not symmetric","image_url":null,"alt":null},{"text":"R is symmetric and transitive but not reflexive","image_url":null,"alt":null},{"text":"R is an equivalence relation Passage: Three pizza outlets A, B and C sell three types of pizza namely cheese pizza, veg pizza and paneer pizza. In a day, A can sell 40 cheese pizza, 30 veg pizza and 20 paneer pizza; B can sell 20 cheese pizza, 40 veg pizza and 60 paneer pizza; C can sell 60 cheese pizza, 20 veg pizza and 30 paneer pizza. If the revenue generated in a day by A is ₹6000, by B is ₹9000 and by C is ₹7000. If x denotes selling price of cheese pizza, y is selling price of veg pizza and z be the selling price of Paneer pizza then based on this information, answer the following question","image_url":null,"alt":null}]', NULL, 3, 'Given, set $A = \{a, b, c, d\}$ and $R = \{(a, a)(b, b)(c, c), (a, b)(b, a)(c, d)(d, d)(d, c)\}$

(i) $\because (a, a) \in R \lor a \in A$

So, $R$ is reflexive.

(ii) If $(x, y) \in R \Rightarrow (y, x) \in R$

$\therefore R$ is symmetric.

(iii) If $x \not\in R, y \not\in R \Rightarrow x \not\in R$ $\lor x, y, z \in A$

$R$ is transitive also.

$\therefore R$ is an equivalence relation.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.875Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4829, 3, NULL, NULL, 'The revenue generated by three outlets A, B and C are:', NULL, '[{"text":"6000","image_url":null,"alt":null},{"text":"22000","image_url":null,"alt":null},{"text":"16000","image_url":null,"alt":null},{"text":"15000","image_url":null,"alt":null}]', NULL, 1, 'Since outlet by A

Since outlet by $A$

$40x+30y+20z=6000$

Outlet by $B$

$20x+40y+60z=9000$

and outlet by $C$

$60x+20y+30z=7000$

$\left\{\begin{array}{l}x=50\\ \therefore y=80\\ z=80\end{array}\right.$

