INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4830, 3, NULL, NULL, 'The matrix representation of the above problem is:', NULL, '[{"text":"$$ \\begin{bmatrix}4&2&6\\\\ 3&4&2\\\\ 2&6&3\\end{bmatrix}\\begin{bmatrix}x\\\\ y\\\\ z\\end{bmatrix}=\\begin{bmatrix}600\\\\ 900\\\\ 700\\end{bmatrix} $$","image_url":null,"alt":null},{"text":"$$ \\begin{bmatrix} {4}&{3}&{2} \\\\ {2}&{4}&{6} \\\\ {6}&{2}&{3} \\end{bmatrix}\\begin{bmatrix} {x} \\\\ {y} \\\\ {z} \\end{bmatrix}=\\begin{bmatrix}600 \\\\ 900 \\\\ 700 \\end{bmatrix} $$","image_url":null,"alt":null},{"text":"$$ \\begin{bmatrix} {4}&{3}&{2} \\\\ {2}&{2}&{3} \\\\ {6}&{2}&{3} \\end{bmatrix} \\begin{bmatrix} {x} \\\\ {y} \\\\ {z} \\end{bmatrix}=\\begin{bmatrix}600 \\\\ 450 \\\\ 700 \\end{bmatrix} $$","image_url":null,"alt":null},{"text":"$$ \\begin{bmatrix}4&2&6\\\\ 3&4&2\\\\ 2&6&3\\end{bmatrix}\\begin{bmatrix}x\\\\ y\\\\ z\\end{bmatrix}=\\begin{bmatrix}6000\\\\ 9000\\\\ 7000\\end{bmatrix} $$","image_url":null,"alt":null}]', NULL, 2, 'Now, the obtained equations are

$ 4x + 3y + 2z = 600 $

$ x + 2y + 3z = 450 $

$ 6x + 2y + 3z = 700 $

$$ So,\begin{bmatrix}4&3&2\\ 1&2&3\\ 6&2&3\end{bmatrix}\begin{bmatrix}x\\ y\\ z\end{bmatrix}=\begin{bmatrix}600\\ 450\\ 700\end{bmatrix} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.877Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
