INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4833, 3, NULL, NULL, 'If the cost price of a cheese pizza is ₹30, a veg pizza is ₹50 and a paneer pizza is ₹50, what is the profit of outlet A in a day?', NULL, '[{"text":"₹6300","image_url":null,"alt":null},{"text":"₹3300","image_url":null,"alt":null},{"text":"₹2300","image_url":null,"alt":null},{"text":"₹18300 A rectangle of length ''x'' and breadth ''y'' is inscribed in a semi-circle of fixed radius ''r'' as shown in the figure given below. $$ \\textcircled{2}0^{\\prime}=\\frac{q_{1}}{q_{2}}=(\\alpha+\\bar{\\alpha})\\frac{q_{1}}{q_{2}}=-\\left(\\Sigma\\right)_{\\xi}=4\\xi+2 $$ $$ \\frac{q x}{q y}=\\frac{\\frac{q y}{q x}}{q x}\\quad\\therefore\\quad\\frac{q x}{q y}=\\frac{(q+2)}{-151-41+2}. $$ $$ \\partial=x\\partial x^{\\prime},x=x(x)\\cap D\\setminus\\mathcal{C}_{m} $$ $$ s < x \\Leftarrow 0 < 4 - x \\leq $$ $$ \\textcircled{H}:\\quad\\textcircled{a}G(x,u)=|u|^{2n}\\left(\\frac{1-x}{3x}\\right) $$ $$ \\frac{(x)(y)}{xy}\\cdot\\frac{1}{(x)(y)}=\\frac{(x)(y)}{xy} $$ $$ 20^{\\circ}=\\frac{95}{11}-\\frac{5}{11}-\\frac{25}{11}\\left(\\frac{1}{x-1}\\right) $$ $$ \\frac{1}{x-1}+\\frac{1}{x-1}=\\frac{\\zeta}{(x-1)\\times\\zeta}=\\left[\\frac{x\\zeta+\\zeta(x-1)}{\\zeta(x-1)}\\right]\\frac{x-1}{x\\zeta}= $$ Based on the above information answer the following question","image_url":null,"alt":null}]', NULL, 2, 'Now, CP of 40 cheese + 30 veg + 20 paneer = 40 × 30 + 50 × 30 + 20 × 50 = 1200 + 1500 + 1000 = ₹3700

and SP of 40 cheese + 30 veg + 20 paneer = ₹6000

Now, profit of outlet A in a day = 6000 - 3700 = ₹2300', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.881Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4834, 3, NULL, NULL, 'Area A(θ), 0 < θ < $ \frac{\pi}{2} $ of the rectangle ABCD, is', NULL, '[{"text":"$ r^{2}\\sin\\theta $","image_url":null,"alt":null},{"text":"$ r^{2}\\sin2\\theta $","image_url":null,"alt":null},{"text":"$ r^{2}\\cos2\\theta $","image_url":null,"alt":null},{"text":"$ r^{2}\\cos\\theta $","image_url":null,"alt":null}]', NULL, 1, 'From given figure,

Area (ABCD) = x \times y

