INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4835, 3, NULL, NULL, 'Dimensions x, y of the rectangle ABCD, when area is maximum are:', NULL, '[{"text":"$ r\\frac{\\sqrt{3}}{2},\\frac{2r}{\\sqrt{3}} $","image_url":null,"alt":null},{"text":"$ r\\sqrt{2},\\frac{r}{\\sqrt{2}} $","image_url":null,"alt":null},{"text":"$ \\frac{r}{\\sqrt{2}},\\sqrt{2}r $","image_url":null,"alt":null},{"text":"$ r,\\frac{r}{\\sqrt{2}} $","image_url":null,"alt":null}]', NULL, 1, 'For maximum,

Area of rectangular ABCD.

$ A'' = 0 \Rightarrow \theta = \frac{\pi}{4} $

$ \therefore x = 2r \cos \theta \quad y = r \sin \theta $

$ x = \frac{2r}{\sqrt{2}} \quad y = \frac{r}{\sqrt{2}} $

$ x = \sqrt{2} r \quad y = \frac{r}{\sqrt{2}} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.883Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4836, 3, NULL, NULL, 'Maximum area of the rectangle is: (a) $ 2r^{2} $ (b) $ 3r^{2} $ (c) $ r^{2} $ (d) $ 4r^{2} $', NULL, '[{"text":"$ 2r^{2} $","image_url":null,"alt":null},{"text":"$ 3r^{2} $","image_url":null,"alt":null},{"text":"$ r^{2} $","image_url":null,"alt":null},{"text":"$ 4r^{2} $","image_url":null,"alt":null}]', NULL, 2, 'For maximum,

Area = max $ (r^{2}\sin2\theta)=r^{2} $

$ \Rightarrow $ Maximum area =r^{2}', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.884Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4837, 3, NULL, NULL, 'Perimeter of rectangle when its area is maximum is:', NULL, '[{"text":"$ \\frac{8\\sqrt{3}r}{3} $","image_url":null,"alt":null},{"text":"4r","image_url":null,"alt":null},{"text":"$ \\frac{7\\sqrt{3}r}{3} $","image_url":null,"alt":null},{"text":"$ 3\\sqrt{2}r $ $$ 0=\\mathbf{\\Pi}\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}-x\\xi\\right)\\mathbf{\\xi}(1+x)-\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}\\right)\\xi_{x\\xi}+\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}\\right)\\xi_{x\\xi}, $$ $$ \\xi=(w)\\operatorname{arccot}\\xi,t=(w)\\operatorname{sinc}\\xi $$ $$ (b-x)(x)=m^{2}+(b-x)^{2}, $$ $$ 0=\\frac{v_{x}^{2}b}{x b}:w=\\frac{v_{b}^{2}}{x b} $$ $$ \\begin{aligned}&(1)x=1\\Longrightarrow1=x+\\xi=0\\\\&T(x+1+x-1)=1-\\psi x^{2}\\psi x=0\\\\&\\frac{1}{x^{2}+1}\\left(1-x-1\\right)\\frac{\\psi x}{x^{2}+1}=\\frac{1}{x^{2}+1}\\end{aligned} $$ $$ \\mathrm{d}\\Delta\\mathrm{T}_{\\mathrm{b}}\\left[\\mathrm{T}_{\\mathrm{d}}\\right]^{\\mathrm{T}_{\\mathrm{b}}}=\\mathrm{d}\\mathrm{b}\\frac{\\mathrm{T}_{\\mathrm{b}}}{\\mathrm{M}}\\prod_{\\mathrm{c}}^{\\mathrm{T}_{\\mathrm{b}}} $$ $$ \\left[\\frac{\\Sigma}{\\nabla I}\\right]=\\frac{1}{4}\\operatorname{c o s}\\left[\\frac{\\nabla I}{2}\\right]\\operatorname{c o s}\\left[\\frac{1}{4}\\right] $$","image_url":null,"alt":null}]', NULL, 3, 'For maximum area,

$$x = \sqrt{2} r; \quad y = \frac{r}{\sqrt{2}} = \frac{1}{(R)^q} = \frac{(R)^q}{(R + 1)^q}$$

So, perimeter = 2 ($x + y$)

$$= 2 \left( r \sqrt{2} + \frac{r}{\sqrt{2}} \right) = \frac{(1 + 1)(1 + 1)}{(1 + 1)(1 + 1)} = \frac{(1 + 1)(1 + 1)}{(1 + 1)(1 + 1)} = 2 r$$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.885Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4838, 3, NULL, NULL, 'If the matrices $ \begin{bmatrix} 1-x^2 & 2y \\ x+5 & 0 \end{bmatrix}=\begin{bmatrix}-3 & y-1 \\ 7 & 0 \end{bmatrix} $ then the value of x and y is equal to:', NULL, '[{"text":"x=2, y=-1","image_url":null,"alt":null},{"text":"x=-2, y=-1","image_url":null,"alt":null},{"text":"x=2, y=-2","image_url":null,"alt":null},{"text":"x=2, y=-1","image_url":null,"alt":null}]', NULL, 1, '(A) Let, $I = \int\limits_{0}^{\pi/2}\frac{\sin^{4}x}{\sin^{4}x+\cos^{4}x}dx$

$=\int\limits_{0}^{\pi/2}\frac{\sin^{4}\left(\frac{\pi}{2}-x\right)}{\sin^{4}\left(\frac{\pi}{2}-x\right)+\cos^{4}\left(\frac{\pi}{2}-x\right)}dx$

$\Rightarrow I=\int\limits_{0}^{\pi/2}\frac{\cos^{4}x}{\sin^{4}x+\cos^{4}x}dx$

Now,

$2I=\int\limits_{0}^{\pi/2}\frac{(\cos^{4}x+\sin^{4}x)}{\cos^{4}x+\sin^{4}x}dx=\int\limits_{0}^{\pi/2}dx=\frac{\pi}{2}$

$\Rightarrow I=\frac{\pi}{4}$

(B) $\operatorname{Let} f(x)=\sin^{5}x\cos^{4}x$

$f(-x)=-\sin^{5}x\cos^{4}x=-f(x)$

So, $\int\limits_{-1}^{\pi/2}\sin^{5}x\cos^{4}x=0$

(C) $\int\limits_{1}^{\sqrt{3}}\frac{dx}{1+x^{2}}=\left[\tan^{-1}x\right]_{1}^{\sqrt{3}}=\frac{\pi}{3}-\frac{\pi}{4}=\frac{\pi}{12}$

(D) $\int\limits_{2}^{3}x^{2}dx=\left[\frac{x^{3}}{3}\right]_{-2}^{3}=\frac{27}{3}-\frac{8}{3}=\frac{19}{3}$

$D>A>C>B$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.888Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4839, 3, NULL, NULL, 'Match List-I with List-II

List-I List-II

A. If $A'' = -A$, I. Symmetric

then matrix A is

B. If $A'' = A$, then II. $(A'')^{-1}$

matrix A is

C. $(A^{-1})'' =$ III. $B''A''$

D. $(AB)'' =$ IV. Skew-symmetric', NULL, '[{"text":"A-IV, B-I, C-III, D-II","image_url":null,"alt":null},{"text":"A-IV, B-I, C-II, D-III","image_url":null,"alt":null},{"text":"A-I, B-IV, C-II, D-III","image_url":null,"alt":null},{"text":"A-I, B-IV, C-III, D-II (d) A-1, B-IV, C-III, D-II","image_url":null,"alt":null}]', NULL, 1, '(A) If $ A'' = -A \Rightarrow A $ is skew symmetric

(B) If $ A'' = A \Rightarrow A $ is symmetric

(C) $ (A^{-1})'' = (A'')^{-1} $

(D) $ (AB)'' = B''A'' $ (Reversal law)', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.889Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4840, 3, NULL, NULL, 'For what value of k the following system of linear equations is:

$ kx + 3y + 3z = 5 $; x - 2y + z = -4

3x - y - 2z = 3

has no solution?', NULL, '[{"text":"k=2","image_url":null,"alt":null},{"text":"k=6","image_url":null,"alt":null},{"text":"k=-3","image_url":null,"alt":null},{"text":"k=-6","image_url":null,"alt":null}]', NULL, 3, 'Given,

$ kx + 3y + 3z = 5 $

$ x - 2y + z = -4 $

$ 3x - y - 2z = 3 $

For no solution, $ \begin{vmatrix} k & 3 & 3 \\ 1 & -2 & 1 \\ 3 & -1 & -2 \end{vmatrix} = 0 $

$ \Rightarrow k(4+1)-3(-2-3)+3(-1+6)=0 $

$ \Rightarrow 5k+15+15=0 \Rightarrow k=-6 $

and $ D_{1}=\begin{vmatrix} 5 & 3 & 3 \\ -4 & -2 & 1 \\ 3 & -1 & -2 \end{vmatrix} $

$ =5(4+1)-3(8-3)+3(4+6) $

$ =25-15+30 $

$ D_{1}=40\neq0 $

So k=-6 for no solution', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.889Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4841, 3, NULL, NULL, 'If $ \mathrm{e}^{\mathrm{y}}(\mathrm{x}+1)=1 $ and $ \frac{\mathrm{d}^{2}\mathrm{y}}{\mathrm{d}x^{2}}=\left(\frac{\mathrm{dy}}{\mathrm{dx}}\right)^{k} $ then the least positive integer $ k'' $ is equal to', NULL, '[{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, 'Given, $ e^{y}(x+1)=1 $

$ y+\ln(x+1)=\ln(1) \Rightarrow y=-\ln(x+1) $

Now, $ \frac{dy}{dx}=\frac{-1}{x+1} $

$ \frac{d^2y}{dx^2}=\frac{1}{(x+1)^2}=\left(\frac{1}{x+1}\right)^2 $

$ \Rightarrow \frac{d^2y}{dx^2}=\left(\frac{dy}{dx}\right)^2 $. So, k=2', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.890Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4842, 3, NULL, NULL, 'The tangent to the curve $ y = e^{2x} $ at the point $ (0, 1) $ meets x-axis at:', NULL, '[{"text":"$ (0,1) $","image_url":null,"alt":null},{"text":"$ \\left(-\\frac{1}{2},0\\right) $","image_url":null,"alt":null},{"text":"$ (2,0) $","image_url":null,"alt":null},{"text":"$ (0,2) $","image_url":null,"alt":null}]', NULL, 1, 'Given the curve $y = e^{2x}$

Now, $\frac{dy}{dx} = 2e^{2x}$

At $(0, 2)$, $\frac{dy}{dx} = 2 \times 1 = 2$

Since, equation of tangent line $y - 1 = 2(x - 0) \Rightarrow y = 2x + 1$

At $x$-axis, $2x + 1 = 0 \Rightarrow x = -\frac{1}{2}$

$\Rightarrow$ Required point $(-\frac{1}{2}, 0)$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.890Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4843, 3, NULL, NULL, 'The interval on which the function $f(x)=-2x^{3}-9x^{2}-12x+1$ is increasing, is:', NULL, '[{"text":"$(-2,-1)$","image_url":null,"alt":null},{"text":"$(-1,\\infty)$","image_url":null,"alt":null},{"text":"$(-\\infty,-2)\\cup(-1,\\infty)$","image_url":null,"alt":null},{"text":"$(-\\infty,-2)$","image_url":null,"alt":null}]', NULL, 0, 'Given, $f(x) = -2x^3 - 9x^2 - 12x + 1$

$f''(x) = -6x^2 - 18x - 12$

For increasing off, $f''(x) > 0$

$\Rightarrow -6x^2 - 18x - 12 > 0$

$\Rightarrow x^2 + 3x + 2 < 0$

$\Rightarrow (x + 2)(x + 1) < 0$

$\frac{x + 1 - x + 1}{-2 -1}$

So, $ x \in (-2, -1) $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.891Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4844, 3, NULL, NULL, 'If $ \int \frac{x}{\sqrt{x-1}} \, dx = f(x) $ and solution of this integral is

$ f(x) = A(x-1)^{3/2} + B\sqrt{x-1} + C $, then which of the

followings are true?

(A) $ A = \frac{3}{2} $, $ B = \frac{1}{2} $ (B) $ A = \frac{2}{3} $, $ B = 2 $

(C) $ A = \frac{2}{3} $, B = -2 (D) Iff(2) = 0, then $ C = -\frac{8}{3} $

(E) Iff(1) = 0, then C = 1', NULL, '[{"text":"A, D only","image_url":null,"alt":null},{"text":"B, E only","image_url":null,"alt":null},{"text":"B, D only","image_url":null,"alt":null},{"text":"D, E only","image_url":null,"alt":null}]', NULL, 2, 'Since, $\int\frac{x}{\sqrt{x-1}}dx = f(x)$

Let $x-1=t^{2} \Rightarrow dx=2tdt$

$\Rightarrow \int\frac{x}{\sqrt{x-1}}dx=\int\frac{t^{2}+1}{t}2t dt$

$=2\int(t^{2}+1)dt=2\left(\frac{t^{3}}{3}+t\right)+C$

$f(x)=\frac{2}{3}(x-1)^{3/2}+2\sqrt{x-1}+C$

So, $A=\frac{2}{3}$, $B=2$

If $f(2)=0 \Rightarrow \frac{2}{3}\cdot1+2\cdot1+C=0 \Rightarrow C=-\frac{8}{3}$

If $f(1)=0 \Rightarrow 0+0+C=0 \Rightarrow C=0$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.891Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4845, 3, NULL, NULL, '$ \int_{0}^{5}|x-5|dx= $', NULL, '[{"text":"$ \\frac{25}{2} $","image_url":null,"alt":null},{"text":"25","image_url":null,"alt":null},{"text":"26","image_url":null,"alt":null},{"text":"$ \\frac{26}{2} $","image_url":null,"alt":null}]', NULL, 0, '$\int_{0}^{5}\left|x-5\right|dx=-\int_{0}^{5}(x-5)dx$

$=\left(\frac{x^{2}}{2}-5x\right)_{5}^{0}=-\left(\frac{25}{2}-25\right)=\frac{25}{2}$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.891Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4846, 3, NULL, NULL, 'The area of the region bounded by the curve $ y=|x-1| $ and line x=0 and x=2 in first quadrant is', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 3, 'Graph of the given curves

Required Area = $ \frac{1}{2} \times 1 \times 1 + \frac{1}{2} \times 1 \times 1 = \frac{1}{2} + \frac{1}{2} = 1 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.892Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4847, 3, NULL, NULL, 'Match List-I with List-II.

List-I List-II

Differential equation Degree of

differential equation

$$ \left(\frac{\mathrm{d}^{2}\mathbf{y}}{\mathrm{d}\mathbf{x}^{2}}\right)^{2}+\left(\frac{\mathrm{d}\mathbf{y}}{\mathrm{d}\mathbf{x}}\right)^{2}=\left(\frac{\mathrm{d}\mathbf{y}}{\mathrm{d}\mathbf{x}}\right) $$

B. $ \left(1+\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{3}=\left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)^{3} $

C. $ \left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)+\left(\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{2}=0 $

D. $ \left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)^{4}+2=\left(\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{2} $

IV. 3', NULL, '[{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-IV, B-III, C-I, D-II","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null},{"text":"A-III, B-I, C-II, D-IV (d) A-III, B-I, C-II, D-IV","image_url":null,"alt":null}]', NULL, 2, '(A) Degree = 2, (B) Degree = 3

(C) Degree = 1, (D) Degree = 4', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.895Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4848, 3, NULL, NULL, 'The differential equation representing family of curve $y=ae^{mx}+be^{mx}$ is', NULL, '[{"text":"$y''''-(m+n)y''+mny=0$","image_url":null,"alt":null},{"text":"$y''''+(m+n)y''+mny=0$","image_url":null,"alt":null},{"text":"$y''''-(m+n)y''-mny=0$","image_url":null,"alt":null},{"text":"$y''-(m+n)y''+y=0$ (d) $ y''''-(m+n)y+y=0 $","image_url":null,"alt":null}]', NULL, 0, 'Given, $y = ae^{mx} + be^{nx}$

Now, $y'' = ame^{mx} + bne^{nx}$

$y'''' = am^2e^{mx} + bn^2e^{nx}$

Since, $y'''' - my'' - ny''$

$= am^2e^{mx} + bn^2e^{nx} - am^2e^{mx} - bmne^{nx}$

$ = -mn(ae^{mx} + be^{nx})$

$\Rightarrow y'''' - (m + n)y'' + mny = 0$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.896Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4849, 3, NULL, NULL, 'Two dices are thrown simultaneously. If X denotes the number of sixes, then the expectation of X is', NULL, '[{"text":"$ \\frac{1}{4} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{2} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{8} $","image_url":null,"alt":null}]', NULL, 1, 'Since, $E = \{(1, 6), (2, 6), (3, 6), (4, 6), (5, 6), (6, 6), (7, 6), (8, 6), (9, 6)\}$

Let $E_{1}=6$ coming at exact ones

$E_{2}=6$ coming on both dices

So, $P(E_{1})=\frac{10}{36}$, $P(E_{2})=\frac{1}{36}$

So, expectations $=1\times\frac{10}{36}+2\times\frac{1}{36}=\frac{1}{3}$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.897Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4850, 3, NULL, NULL, 'In a binomial distribution b(n, p), if n = 10 and q = 0.7, then its mean is', NULL, '[{"text":"7","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 2, 'Given, $n=10$

Since, $p+q=1 \Rightarrow p=1-0.7=0.3$

So. mean $10 \times 0.3 = 3$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.898Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4851, 3, NULL, NULL, 'The corner points of the feasible region, determined by the system of linear inequalities are $(0,0)(5,0)(3,4)$ and $(0,5)$. Let $z=2x+qy$ where $q>0$. For what value of $q$ the maximum value of $z$ occurs at both $(3,4)$ and $(0,5)$ is', NULL, '[{"text":"$2 \\cdot","image_url":null,"alt":null},{"text":"$ 1","image_url":null,"alt":null},{"text":"$\\frac{2}{3}$","image_url":null,"alt":null},{"text":"$6$","image_url":null,"alt":null}]', NULL, 3, 'Now, $ Z_{(0,0)}=0 $, $ Z_{(5,0)}=2.5=10 $

$ Z_{(3,4)}=6+4q $, $ Z_{(0,5)}=5q $

Since, $ Z_{(3,4)}=Z_{(0,5)} $

$ \Rightarrow 6+4a=5 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.898Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4852, 3, NULL, NULL, 'Let R be the relation in the set $\{1, 2, 3, 4\}$ and given by $R = \{(1,2),(2,2),(1,1),(1,3),(4,4),(3,3),(3,2)\}$.', NULL, '[{"text":"R is reflexive and symmetric, but not transitive","image_url":null,"alt":null},{"text":"R is reflexive and transitive, but not symmetric","image_url":null,"alt":null},{"text":"R is symmetric and transitive, but not reflexive","image_url":null,"alt":null},{"text":"R is an equivalence relation","image_url":null,"alt":null}]', NULL, 1, 'Given, $ R = \{(1, 2), (2, 2), (1, 1), (1, 3), (4, 4), (3, 3), (3, 2)\} $ and $ A = \{1, 2, 3, 4\} $

$ \forall x \in A, xRx \Rightarrow R $ is Reflexive Relation.

Since, $ 1R2 \nrightarrow 2R1 \Rightarrow R $ is not symmetric.

For any a, b, $ c \in A $, $ aRb $, $ bRc \Rightarrow aRc $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.898Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4853, 3, NULL, NULL, 'Which one of the following functions is one-one?

A. f: R → R such that f(x) = x²

B. f: R → R such that f(x) = 3x + 2

C. f: N → N such that f(x) = x²

D. f: R → R such that f(x) = [x], where [x] is greatest integer ≤ x', NULL, '[{"text":"A and C only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"C and D only","image_url":null,"alt":null},{"text":"A, B and C only","image_url":null,"alt":null}]', NULL, 1, 'Given, (A) $f(x)=x^{2}$, $f:R \to R$

For one-one, $f(x_{1})=f(x_{2})$ (Let)

$\Rightarrow x_{1}^{2}=x_{2}^{2} \Rightarrow x_{1}=\pm x_{2}$

$S_{o}f(x)=x^{2}$ is not one-one.

(B) $f(x)=3x+2$, $f:R \to R$

Let $f(x_{1})=f(x_{2})\Rightarrow 3x_{1}+2=3x_{2}+2$ $\Rightarrow x_{1}=x_{2}$

$\Rightarrow f(x)$ is one-one.

(C) $f:N \to N$, $f(x)=x^{2}$

Let $f(x_{1})=f(x_{2})\Rightarrow x_{1}^{2}=x_{2}^{2}\Rightarrow x_{1}=x_{2}$

$\Rightarrow f(x)$ is one-one.

(D) $f(x)=[x], f:R \to R$

Since $f(0.5)=[0.5]=0$, $f(0)=[0]=0$

$\Rightarrow f(x)$ is not one-one.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.899Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4854, 3, NULL, NULL, 'The value of $ \tan^{-1}\left[2\cos\left(2\sin^{-1}\frac{1}{2}\right)\right] $ is', NULL, '[{"text":"$ \\pi $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{2} $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{4} $","image_url":null,"alt":null}]', NULL, 3, 'Given,

$ \tan^{-1}\left[2\cos\left(2\cos^{-1}\left(\frac{1}{2}\right)\right)\right]=\tan^{-1}\left[2\cos\left(2\times\frac{\pi}{6}\right)\right] $

$ \tan^{-1}\left[2\cos\left(\frac{\pi}{3}\right)\right]=\tan^{-1}\left(2\times\frac{1}{2}\right) $

$ \tan^{-1}(1)=\frac{\pi}{4} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.899Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4855, 3, NULL, NULL, 'The value of $ \begin{vmatrix} x & \sin\theta & \cos\theta \\ -\sin\theta & -x & 1 \\ \cos\theta & 1 & x \end{vmatrix} $ is:', NULL, '[{"text":"independent of \\theta","image_url":null,"alt":null},{"text":"dependent of \\theta","image_url":null,"alt":null},{"text":"equal to x^{3}","image_url":null,"alt":null},{"text":"depend on both \\theta and x","image_url":null,"alt":null}]', NULL, 0, 'Given, $ \begin{vmatrix} x & \sin\theta & \cos\theta \\ -\sin\theta & -x & 1 \\ \cos\theta & 1 & x \end{vmatrix} $

$ = x (-x^2 - 1) - \sin\theta (-x \sin\theta - \cos\theta) + \cos\theta (x \cos\theta - \sin\theta) $

$ = -x^3 - x + x \sin^2\theta + \sin\theta \cos\theta + x \cos^2\theta - \sin\theta \cos\theta $

$ = -x^9 - x + x \cdot 1 = -x^3 $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.900Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4856, 3, NULL, NULL, 'One branch of $\sin^{-1}x$ other than the principal value branch corresponds to:', NULL, '[{"text":"$\\left[\\pi, 2\\pi\\right]$","image_url":null,"alt":null},{"text":"$\\left[\\frac{\\pi}{2}, \\frac{3\\pi}{2}\\right]$","image_url":null,"alt":null},{"text":"$\\left[-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right] - \\{0\\}$","image_url":null,"alt":null},{"text":"$\\left[\\frac{3\\pi}{2}, \\frac{5\\pi}{2}\\right]$","image_url":null,"alt":null}]', NULL, 3, '$ \sin^{-1} x \in \left[-\frac{\pi}{2}, \frac{\pi}{2}\right] $

$ \frac{-\pi}{2} \leq \sin^{-1} x \leq \frac{\pi}{2} $

So, other branch is

$ 2\pi - \frac{\pi}{2} \leq \sin^{-1} x \leq 2\pi + \frac{\pi}{2} $

$ \frac{3\pi}{2} \leq \sin^{-1} x \leq \frac{5\pi}{2} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.900Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4857, 3, NULL, NULL, 'If $A=\begin{bmatrix}2 & 3\\ 1 & 2\end{bmatrix}$ where $I$ is the identity matrix of order $2\times2$ and $O$ is $2\times2$ zero matrix, then choose one of the following correct option given below:', NULL, '[{"text":"$A^{2}-4A+I=0$","image_url":null,"alt":null},{"text":"$A^{2}+4A+I=0$","image_url":null,"alt":null},{"text":"$A^{2}-4A-I=0$","image_url":null,"alt":null},{"text":"$A^{2}-4A+2I=0$","image_url":null,"alt":null}]', NULL, 0, '$ A = \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} $

And, $ A^{2} = \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} = \begin{bmatrix} 7 & 12 \\ 4 & 7 \end{bmatrix} $

$ 4A = 4 \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} = \begin{bmatrix} 8 & 12 \\ 4 & 8 \end{bmatrix} $

Now, $ A^{2} - 4A + I $

$ = \begin{bmatrix} 7 & 12 \\ 4 & 7 \end{bmatrix} - \begin{bmatrix} 8 & 12 \\ 4 & 8 \end{bmatrix} + \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix} = \begin{bmatrix} 0 & 0 \\ 0 & 0 \end{bmatrix} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.901Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
