INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4859, 3, NULL, NULL, 'The points of discontinuity for the given function f:

$ R \rightarrow R $ defined as

$ f(x)=\left\{\begin{aligned}&2x-5&2<x<3\\ &2,&3\leq x<5\\ &5x,&5\leq x<7\end{aligned}\right. $

(A) 2 (B) 3 (C) 5 (D) 7', NULL, '[{"text":"A and B only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"C and D only","image_url":null,"alt":null},{"text":"A and D only","image_url":null,"alt":null}]', NULL, 1, '$ f: R \to R $ define as,

$ f(x) = \begin{cases} 2x - 5, & 2 < x < 3 \\ 2, & 3 \leq x < 5 \\ 5x, & 5 \leq x < 7 \end{cases} $

At $ x = 3 $, $ f(3^{-}) = 2 \times 3 - 5 = 1 $

$ f(3^{+}) = 2 $

Function discontinuous at $ x = 3 $

At $ x = 5 $,

$ f(5^{-}) = 2 $

$ f(5^{+}) = 5x = 5 \times 5 = 25 $

Function discontinuous at $ x = 5 $

So, 3, 5 is discontinuous points.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.901Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
