INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4874, 3, NULL, NULL, 'If the gardener wishes to put manure at the rate of $\overrightarrow{50/m^{2}}$ in the circular park. Then find the approximate cost of manuring', NULL, '[{"text":"₹8338","image_url":null,"alt":null},{"text":"₹833.8","image_url":null,"alt":null},{"text":"₹4710","image_url":null,"alt":null},{"text":"₹35325 Passage Ram purchased a gift which is in the shape of a tetrahedron. Let $ A = (1, 2, 1) $, $ B = (2, 3, 1) $, $ C = (3, 1, 0) $ and $ D = (4, 3, 1) $ be the vertices of the tetrahedron. Based on the above information, answer the following questions","image_url":null,"alt":null}]', NULL, 3, 'Area of park = 225 $\pi$ sq. units

