INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4876, 3, NULL, NULL, 'The vector $\overrightarrow{\mathrm{CD}}$ is', NULL, '[{"text":"$2\\hat{i}+2\\hat{j}+3\\hat{k}$","image_url":null,"alt":null},{"text":"$\\hat{i}+2\\hat{j}+\\hat{k}$","image_url":null,"alt":null},{"text":"$\\hat{i}-\\hat{j}+\\hat{k}$","image_url":null,"alt":null},{"text":"$\\hat{i}-2\\hat{j}-\\hat{k}$","image_url":null,"alt":null}]', NULL, 1, '$ \overrightarrow{C} = (3, 1, 0) $, $ \overrightarrow{D} = (4, 3, 1) $

