INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4877, 3, NULL, NULL, 'The area of $\triangle ABC$ is equal to', NULL, '[{"text":"$\\frac{\\sqrt{13}}{2}$","image_url":null,"alt":null},{"text":"$\\frac{\\sqrt{5}}{2}$","image_url":null,"alt":null},{"text":"$\\frac{\\sqrt{7}}{2}$","image_url":null,"alt":null},{"text":"$\\frac{\\sqrt{11}}{2}$","image_url":null,"alt":null}]', NULL, 3, '$ \overrightarrow{AB} = \overrightarrow{i} + \overrightarrow{j} $, $ \overrightarrow{BC} = \overrightarrow{i} - 2\overrightarrow{j} - \overrightarrow{k} $

