INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4880, 3, NULL, NULL, 'Assume $P$, $Q$, $R$ and $S$ are matrices of order $2 \times m$, $k \times n$, $m \times 2$ and $2 \times 3$ respectively. The restrictions on $k$, $m$ and $n$, so that $PQ + RS$ is defined are', NULL, '[{"text":"$m=3, n=2$","image_url":null,"alt":null},{"text":"$m=n, k$ is arbitrary","image_url":null,"alt":null},{"text":"$m=k$ $n$ is arbitrary","image_url":null,"alt":null},{"text":"$m=k=2, n=3$","image_url":null,"alt":null}]', NULL, 3, 'Order of $P=2\times m$

Order of $Q=k\times n$

Order of $R=m\times2$

Order of $S=2\times3$

Now, for $PQ+RS$ to be defined.

$PQ$ and $RS$ is to be defined and $PQ$ and $RS$ should be of same order.

For $PQ$ to be defined $m=k$

$\Rightarrow$ Order of $PQ=2\times n$

For $RS$ to be defined $2=2$

$\Rightarrow$ Order of $RS=m\times3$

If order of $PQ$=Order of $RS$

$\Rightarrow$ $2\times n=m\times3$

$\Rightarrow$ $m=2,n=3,k=2$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.919Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4881, 3, NULL, NULL, 'The system of equations 3x + 4y = 5, 6x + 7y = -8 is written in matrix from as', NULL, '[{"text":"$ \\begin{bmatrix} 3 & 4 \\\\ 6 & 7 \\end{bmatrix}[x \\quad y] = [5 - 8] $","image_url":null,"alt":null},{"text":"$ \\begin{bmatrix}3&6\\\\ 4&7\\end{bmatrix}\\begin{bmatrix}x\\\\ y\\end{bmatrix}=\\begin{bmatrix}5\\\\ -8\\end{bmatrix} $","image_url":null,"alt":null},{"text":"$ \\begin{bmatrix} x \\\\ y \\end{bmatrix} \\begin{bmatrix} 3 & 4 \\\\ 6 & 7 \\end{bmatrix} = \\begin{bmatrix} 5 \\\\ -8 \\end{bmatrix} $","image_url":null,"alt":null},{"text":"$ [x\\ y]\\begin{bmatrix}3\\ 6\\\\ 4\\ 7\\end{bmatrix}=[5\\ -8] $","image_url":null,"alt":null}]', NULL, 3, 'Given the equations

