INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4882, 3, NULL, NULL, 'If $ 2\begin{bmatrix}a&d\\ b&c\end{bmatrix}+3\begin{bmatrix}1&-1\\ 0&2\end{bmatrix}=3\begin{bmatrix}3&5\\ 4&6\end{bmatrix} $, then the value of $ \left|a+b-c-d\right| $ is', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"24","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"16","image_url":null,"alt":null}]', NULL, 0, 'Sample space

S: {1, 2, 3}

