where $X$ denotes larger of two integers.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.921Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4883, 3, NULL, NULL, 'Consider the function $f(x)=x^{\frac{1}{x}}$. Its', NULL, '[{"text":"minimum value is $e^{\\frac{1}{e}}$","image_url":null,"alt":null},{"text":"maximum value is $e^{\\frac{1}{e}}$","image_url":null,"alt":null},{"text":"minimum value is $e^{e}$","image_url":null,"alt":null},{"text":"maximum value is $\\left(\\frac{1}{e}\\right)^{e}$","image_url":null,"alt":null}]', NULL, 1, 'Given the function

$$

\begin{aligned}

f(x) &= x^{\frac{1}{x}} \Rightarrow \log f(x) = \frac{1}{x} \log x \\

\frac{f''(x)}{f(x)} &= \frac{1}{x^2} + (\log x) \left( -\frac{1}{x^2} \right) \\

f''(x) &= \frac{\frac{1}{x^x} [1 - \log x]}{x^2}, \text{ Now } f''(x) = 0 \\

\Rightarrow 1 - \log x &= 0 \Rightarrow \log x = 1 \\

\therefore x &= e \\

\text{Since } f''(e^-) > 0 \text{ and } f''(e^+) < 0 \\

\text{So, } f(x) \text{ has max. at } e. \\

\therefore f(x)_{\max} &= e^e

\end{aligned}

$$

$\therefore f(x)_{\max}=e^{e}$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.922Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4884, 3, NULL, NULL, 'The given function $f(x)=x^{5}-5x^{4}+5x^{3}-1$; has/have

