(b) (a), (b), (c) only

(c)', NULL, '[{"text":",","image_url":null,"alt":null},{"text":",","image_url":null,"alt":null},{"text":",","image_url":null,"alt":null},{"text":"only (d) (a), (c), (e) only","image_url":null,"alt":null}]', NULL, 2, 'Given, $f(x)=x^{5}-5x^{4}+5x^{3}-1$

$f''(x)=5x^{4}-20x^{3}+15x^{2}$

$=5x^{2}(x^{2}-4x+3)=0$

$=5x^{2}(x-3)(x-1)=0$

$x=0,3,1$

Now, $f''''(x)=20x^{3}-60x^{2}+30x$

$=10x(2x^{2}-6x+3)$

$f''''(x)=0 \Rightarrow x=0$

$f''''(1) 0 \Rightarrow x=3$

$f(3)=(3)^{5}-5(3)^{4}+5(3)^{3}-1=-28$

$f(1)=1-5+5-1=0$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.923Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
