INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4891, 3, NULL, NULL, 'A line makes the angle \theta with each of the x and z axes. If the angle \beta which it makes with y-axis is such that \sin^{2}\beta = 3\sin^{2}\theta, then the value of \cos^{2}\theta is', NULL, '[{"text":"$ \\frac{2}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{3}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{2}{5} $","image_url":null,"alt":null}]', NULL, 2, 'We know that

$ \cos^{2}\theta + \cos^{2}\beta + \cos^{2}\theta = 1 $

or $ 2\cos^{2}\theta + 1 - 3\sin^{2}\theta = 1 $

or $ 2\cos^{2}\theta = 3\sin^{2}\theta $

or $ 2\cos^{2}\theta=3-3\cos^{2}\theta\Rightarrow\cos\theta=\frac{3}{5} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.932Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4892, 3, NULL, NULL, 'If $ x = 2 \sin \theta $ and $ y = 2 \cos \theta $, then the value of $ \frac{d^2 y}{dx^2} $ at $ \theta = 0 $ is', NULL, '[{"text":"$ -\\frac{1}{2} $","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null}]', NULL, 0, 'Now, $ \frac{dy}{dx} = \frac{dy}{\frac{d\theta}{dx}} \Rightarrow \frac{dy}{dx} = \frac{-2\sin\theta}{2\cos\theta} = -\tan\theta $

$ \frac{d^2y}{dx^2} = \frac{d}{d\theta}\left(\frac{dy}{dx}\right) \cdot \frac{d\theta}{dx} \Rightarrow \frac{d^2y}{dx^2} = -\sec^2\theta \cdot \frac{d\theta}{dx} $

$ =\frac{-\sec^2\theta}{2\cos\theta} = -\frac{1}{2}\sec^3\theta $

$$ At\theta=0\Rightarrow\frac{d^{2}y}{dx^{2}}=-\frac{1}{2} $$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.932Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4893, 3, NULL, NULL, 'If $ x = e^{y + e^{y + \cdots}} $, x > 0, then $ \frac{dy}{dx} $ is equal to', NULL, '[{"text":"$ \\frac{x}{1+x} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{x} $","image_url":null,"alt":null},{"text":"$ \\frac{1-x}{x} $","image_url":null,"alt":null},{"text":"$ \\frac{1+x}{x} $","image_url":null,"alt":null}]', NULL, 2, 'Since, $ x = e^{y+x} $

Differentiating w.r.t. x, we get

$ 1 = e^{x+y} \left( 1 + \frac{dy}{dx} \right) \Rightarrow \frac{1}{x} = 1 + \frac{dy}{dx} $

or $ \frac{dy}{dx} = \frac{1 - x}{x} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.933Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4894, 3, NULL, NULL, '$ \sin^{-1}(1-x)-2\sin^{-1}x=\frac{\pi}{2} $, then x is equal to', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"$ \\frac{1}{2} $","image_url":null,"alt":null},{"text":"2 Choose the most appropriate answer from the options given below: (a) (a) and (b) only (b) (a) and (c) only (c) (a) only (d) (c) only","image_url":null,"alt":null}]', NULL, 2, 'Domain for $ \sin^{-1}(1-x) $ is [0,2] and domain for $ \sin^{-1}x $ is [-1,1].

So, Domain for x is [0,1].

$$ \left.\sin^{-1}(1-x)\right|_{\max}=\frac{\pi}{2};\left.\sin^{-1}(x)\right|_{\max}=0 $$

So, only possible condition is when x=0.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.934Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4895, 3, NULL, NULL, 'The smaller of the areas enclosed by the circle $ x^{2}+y^{2}=4 $ and the line $ x+y=2 $ is', NULL, '[{"text":"$ 2(\\pi-2) $","image_url":null,"alt":null},{"text":"$ \\pi-2 $","image_url":null,"alt":null},{"text":"$ 2\\pi-1 $","image_url":null,"alt":null},{"text":"$ 2\\pi+2 $","image_url":null,"alt":null}]', NULL, 1, 'Graph of given curves

Area of smaller region

= $ \frac{1}{4}\times4\pi-\frac{1}{2}\cdot2.2=(\pi-2) $ sq. units', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.934Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4896, 3, NULL, NULL, 'If $ 0 < x < \pi $ and the matrix $ \begin{bmatrix} 4\sin x & -1 \\ -3 & \sin x \end{bmatrix} $ is

singular, then the values of x are:', NULL, '[{"text":"$ \\frac{\\pi}{3}, \\frac{2\\pi}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{6}, \\frac{5\\pi}{6} $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{6}, \\frac{\\pi}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{\\pi}{6}, \\frac{2\\pi}{3} $","image_url":null,"alt":null}]', NULL, 0, 'Since, $ \begin{vmatrix} 4\sin x & -1 \\ -3 & \sin x \end{vmatrix} = 0 $

$ \Rightarrow 4\sin^{2}x - 3 = 0 \Rightarrow \sin^{2}x = \frac{3}{4} $

$ \Rightarrow \sin x = \pm \frac{\sqrt{3}}{2} \Rightarrow x = \frac{\pi}{3} $ or $ \frac{2\pi}{3} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.935Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4897, 3, NULL, NULL, '$ \int_{\frac{1}{3}}^{1}\frac{(x-x^{3})^{\frac{1}{3}}}{x^{4}}dx= $', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null},{"text":"0","image_url":null,"alt":null}]', NULL, 2, 'Let

$$I = \int_{1/3}^{1} \frac{x\left(\frac{1}{x^2}-1\right)^{1/3}}{x^4} dx = \int_{1/3}^{1} \frac{\left(\frac{1}{x^2}-1\right)^{1/3}}{x^3} dx$$

Let $\frac{1}{x^2} - 1 = t \Rightarrow \frac{-2}{x^3} dx = dt$

If $x = \frac{1}{3} \Rightarrow t = 8$

If $x = 1 \Rightarrow t = 0$

So, $I = \int_{8}^{0} \frac{-t^{1/3}}{2} dt = \frac{1}{2} \int_{0}^{8} t^{1/3} dt = \frac{1}{2} \cdot \frac{t^{4/3}}{4} \bigg|_{0}^{8}$

$\frac{3}{8} \left( \frac{4}{8^3} - 0^{\frac{4}{3}} \right) = \frac{3}{8} \cdot 8^{4/3} = 6$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.935Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4898, 3, NULL, NULL, 'If the points $(2, -3)$, $(\lambda, -1)$ and $(0, 4)$ are collinear, then the value of $\lambda$ is', NULL, '[{"text":"$\\frac{7}{10}$","image_url":null,"alt":null},{"text":"$\\frac{3}{10}$","image_url":null,"alt":null},{"text":"$\\frac{7}{3}$","image_url":null,"alt":null},{"text":"$\\frac{10}{7}$","image_url":null,"alt":null}]', NULL, 3, 'For collinear points,

$ \begin{vmatrix} \lambda & -1 & 1 \\ 0 & 4 & 1 \\ 2 & -3 & 1 \end{vmatrix} = 0 \Rightarrow \lambda(7) + 1(-2) + 1(-8) = 0 $

$ \Rightarrow 7\lambda - 10 = 0 \Rightarrow \lambda = \frac{10}{7} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.936Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4899, 3, NULL, NULL, 'The value of $\sin\left[2\cot^{-1}\left(\frac{-5}{12}\right)\right]$ is:', NULL, '[{"text":"$\\frac{120}{169}$","image_url":null,"alt":null},{"text":"$\\frac{-120}{169}$","image_url":null,"alt":null},{"text":"$\\frac{-60}{169}$","image_url":null,"alt":null},{"text":"$\\frac{60}{169}$","image_url":null,"alt":null}]', NULL, 1, '$ \sin\left(2\pi-2\cot^{-1}\frac{5}{12}\right)=-\sin\left(2\cot^{-1}\frac{5}{15}\right) $

Since, $ \sin(2\pi-x)=-\sin x $

Let $ \cot^{-1}\frac{15}{12}=\theta \Rightarrow \cot\theta=\frac{5}{12} $

$ \Rightarrow \tan\theta=\frac{12}{5} $

$ \sin2\theta=\frac{2\tan\theta}{1+\tan^{3}\theta}=\frac{\frac{24}{5}}{1+\frac{144}{25}}=\frac{\frac{25}{5}}{\frac{169}{25}}=\frac{120}{169} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.936Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4900, 3, NULL, NULL, 'Let $y = m \sin rx + n \cos rx$. What is the value of $\frac{d^2 y}{dy^2}$?', NULL, '[{"text":"$ry$","image_url":null,"alt":null},{"text":"$-ry$","image_url":null,"alt":null},{"text":"$ry^2 y$","image_url":null,"alt":null},{"text":"$-r^2 y$","image_url":null,"alt":null}]', NULL, 3, 'Given, $ y = m \sin rx + r \cos rx $

$ \frac{dy}{dx} = m \cdot r (\cos rx) - nr (\sin rx) $

$ \Rightarrow \frac{d^2 y}{dx^2} = mr^2 [(-\sin rx) - nr^2 (\cos rx)] $

$ =-\frac{r^2 v $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.937Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4901, 3, NULL, NULL, 'The integrating factor of the differential equation \cos x\frac{dy}{dx}+y\sin x=1 is', NULL, '[{"text":"$ \\sec x $","image_url":null,"alt":null},{"text":"$ \\cos x $","image_url":null,"alt":null},{"text":"$ \\sec x + \\tan x $","image_url":null,"alt":null},{"text":"$ \\tan x $","image_url":null,"alt":null}]', NULL, 0, 'Given, the differential equation

$ \cos x \frac{dy}{dx} + y \sin x = 1 $

$ \frac{dy}{dx} + y \tan x = \sec x $

So, I.F. = $ e^{\int \tan x \, dx} = e^{\ln (\sec x)} = \sec x $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.938Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4902, 3, NULL, NULL, 'The order and degree of the differential equation $ \left[\left(\frac{d^{2}y}{dx^{2}}\right)-3\right]^{\frac{1}{3}}=2\left(\frac{dy}{dx}\right)^{\frac{1}{4}} $ are

(a) order=2, degree=2 (b) order=2, degree=4

(c) order=2, degree=8 (d) order=1, degree=1

$$ \int\sqrt{1-49x^{2}} $$', NULL, '[{"text":"$ \\frac{x}{2}\\left(\\sqrt{1-49x^{2}}\\right)+\\frac{1}{98}\\sin^{-1}7x+C $","image_url":null,"alt":null},{"text":"$ \\frac{7x}{2}\\sqrt{1+49x^{2}}+\\frac{1}{49}\\sin^{-1}x+C $","image_url":null,"alt":null},{"text":"$ \\frac{x}{2}\\sqrt{1+\\frac{1}{7x^{2}}}-\\frac{1}{49}\\sin^{-1}7x+C $","image_url":null,"alt":null},{"text":"$ \\frac{x}{2}\\sqrt{1-49x^{2}}+\\frac{1}{14}\\sin^{-1}7x+C $","image_url":null,"alt":null}]', NULL, 2, 'Since, $ \left[\left(\frac{d^{2}y}{dx^{2}}\right)^{2}-3\right]^{\frac{1}{3}}=2\left(\frac{dy}{dx}\right)^{\frac{1}{4}} $

$ \left(\left(\frac{d^{2}y}{dx^{2}}\right)^{2}-3\right)^{4}=2^{12}\left(\frac{dy}{dx}\right)^{3} $

So, Order=2, Degree=8', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.938Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4903, 3, NULL, NULL, 'The shortest distances of the point $(1,2,3)$ from $x$, $y$, $z$ axes respectively are', NULL, '[{"text":"$1,2,3$","image_url":null,"alt":null},{"text":"$\\sqrt{5},\\sqrt{13},\\sqrt{10}$","image_url":null,"alt":null},{"text":"$\\sqrt{10},\\sqrt{13},\\sqrt{5}$","image_url":null,"alt":null},{"text":"$\\sqrt{13},\\sqrt{10},\\sqrt{5}$","image_url":null,"alt":null}]', NULL, 3, 'Since, $ D_x = \sqrt{(1-1)^2 + (2-0)^2 + (3-0)^2} $

$ \Rightarrow D_x = \sqrt{2^2 + 3^2} = \sqrt{13} $

$ D_y = \sqrt{1^2 + 3^2} = \sqrt{10} $

$ D_z = \sqrt{1^2 + 2^2} = \sqrt{5} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.939Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4904, 3, NULL, NULL, 'Distance between two planes $x+2y-z=5$ and $2x+4y-2z+2=0$ is', NULL, '[{"text":"$\\sqrt{6}$ unit","image_url":null,"alt":null},{"text":"7 unit","image_url":null,"alt":null},{"text":"$\\frac{5}{\\sqrt{6}}$ unit","image_url":null,"alt":null},{"text":"$\\frac{4}{\\sqrt{6}}$ unit","image_url":null,"alt":null}]', NULL, 0, 'Given the planes

$ P_{1}:2x+4y-2z=10 $

$ P_{2}:2x+4y-2z=-2 $

$ d=\frac{12}{\sqrt{2^{2}+4^{2}+2^{2}}}=\frac{12}{\sqrt{24}}=\sqrt{6} $ units', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.939Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4905, 3, NULL, NULL, 'If $\overrightarrow{a}=a_{1}\hat{i}+a_{2}\hat{j}+a_{3}\hat{k}$ and $\overrightarrow{b}=b_{1}\hat{i}+b_{2}\hat{j}+b_{3}\hat{k}$ are two non zero vectors inclined at an angle $\theta$, then identify the correct option out of the given options

(A) $\cos\theta=\frac{\overrightarrow{a}\cdot\overrightarrow{b}}{|\overrightarrow{a}|\cdot|\overrightarrow{b}|}$

(B) $\overrightarrow{a}$ and $\overrightarrow{b}$ are perpendicular, if $a_{1}b_{1}+a_{2}b_{2}+a_{3}b_{3}=0$

(C) $\overrightarrow{a}$ and $\overrightarrow{b}$ are perpendicular, $\frac{a_{1}}{b_{1}}=\frac{a_{2}}{b_{2}}\neq\frac{c_{1}}{c_{2}}$

(D) for $\theta=\pi,\overrightarrow{a}\times\overrightarrow{b}=0$

(E) $\cos\theta=\frac{|\overrightarrow{a}\times\overrightarrow{b}|}{|\overrightarrow{a}|\cdot|\overrightarrow{b}|}$', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (E) only","image_url":null,"alt":null},{"text":"(B), (D) and (E) only","image_url":null,"alt":null},{"text":"(A) and (B) only","image_url":null,"alt":null}]', NULL, 0, 'Given the vectors

$ \overrightarrow{a} = a_1\hat{i} + a_2\hat{j} + a_3\hat{k} $; $ \overrightarrow{b} = b_1\hat{i} + b_2\hat{j} + b_3\hat{k} $

If angle between $ \overrightarrow{a} $ and $ \overrightarrow{b} $ is $ \theta $

So, $ \cos\theta = \frac{\overrightarrow{a}\cdot\overrightarrow{b}}{|\overrightarrow{a}||\overrightarrow{b}|} $

and if $ \overrightarrow{a} $ is perpendicular to $ \overrightarrow{b} $ then

$ \overrightarrow{a}\cdot\overrightarrow{b} = 0 \Rightarrow a_1b_1 + a_2b_2 + a_3b_3 = 0 $

and if $ \theta = \pi $, then

$ \overrightarrow{a}\times\overrightarrow{b} = |\overrightarrow{a}||\overrightarrow{b}|\sin\theta\hat{n} = \overrightarrow{0} $

So, option (1) is correct.', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.939Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4906, 3, NULL, NULL, 'If $ \overline{p} = \hat{i} + \hat{j} - 2\hat{k} $ and $ \vec{q} = 2\hat{i} + \hat{j} - \hat{k} $, then the area of parallelogram having diagonals $ (\overline{p} + \overline{q}) $ and $ (\overline{p} - \overline{q}) $ is', NULL, '[{"text":"$ 4\\sqrt{11} $ sq. unit","image_url":null,"alt":null},{"text":"$ \\sqrt{44} $ sq. unit","image_url":null,"alt":null},{"text":"$ \\sqrt{11} $ sq. unit","image_url":null,"alt":null},{"text":"$ 3\\sqrt{11} $ sq. unit","image_url":null,"alt":null}]', NULL, 2, 'Given the vectors

$ p = \hat{i} + \hat{j} - 2\hat{k} $ and $ q = 2\hat{i} + 2\hat{j} - k $

Let $ \overrightarrow{d}_{1} = \overrightarrow{p} + \overrightarrow{q} = 3\hat{i} + 2\hat{j} - 3\hat{k} $

$ \overrightarrow{d}_{2} = \overrightarrow{p} - \overrightarrow{q} = \hat{i} - \hat{k} $

$ \therefore $ Area of parallelogram = $ \frac{1}{2} |\overrightarrow{d}_{1} \times \overrightarrow{d}_{2}| $

Now, $ \overrightarrow{d}_{1} \times \overrightarrow{d}_{2} = \begin{vmatrix} i & \hat{j} & \hat{k} \\ 3 & 2 & -3 \\ -1 & 0 & -1 \end{vmatrix} = -2\hat{i} + 6\hat{j} + 2\hat{k} $

$ \Rightarrow |d_{1} \times d_{2}| = \sqrt{(-2)^{2} + 6^{2} + 2^{2}} $

$ \therefore $ Area = $ \frac{1}{2}\sqrt{4 + 36 + 4} = \sqrt{11} $ sq. units', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.940Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4907, 3, NULL, NULL, 'If $ \overrightarrow{a}, \overrightarrow{b} $ and $ \overrightarrow{c} $ are three unit vectors such that $ \overrightarrow{a} + \overrightarrow{b} + \overrightarrow{c} = 0 $ then the value of $ \overrightarrow{a} \cdot \overrightarrow{b} + \overrightarrow{b} \cdot \overrightarrow{c} + \overrightarrow{c} \cdot \overrightarrow{a} $ is', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"$ -\\frac{3}{2} $","image_url":null,"alt":null},{"text":"$ \\frac{3}{2} $","image_url":null,"alt":null},{"text":"$ -\\frac{1}{3} $","image_url":null,"alt":null}]', NULL, 1, 'Given, $ \vec{a} + \vec{b} + \vec{c} = 0 $

Now, $ (\vec{a} + \vec{b} + \vec{c})(\vec{a} + \vec{b} + \vec{c}) = 0 $

$ \Rightarrow |\vec{a}| + |\vec{b}| + |\vec{c}| + 2(\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = 0 $

Since, $ \vec{a} = |\vec{b}| = |\vec{c}| = 1 $

$ \Rightarrow 2(\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = -3 $

$ \therefore (\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = -\frac{3}{2} = (0, 0, 0) $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.940Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4908, 3, NULL, NULL, 'The corner points of the feasible region for an $L.P.P.$ are $(0, 10), (5, 5), (15, 15)$ and $(0, 20)$. If the objective function is $z = px + qy; p, q > 0$, then the condition on $p$ and $q$ so that the maximum of zoccurs at $(15, 15)$ and $(0, 20)$ is', NULL, '[{"text":"$p = q$","image_url":null,"alt":null},{"text":"$p = 2q$","image_url":null,"alt":null},{"text":"q = 3p","image_url":null,"alt":null},{"text":"q = 2p","image_url":null,"alt":null}]', NULL, 2, 'Given, $z$ has max at (15, 15) and $(0, 20)$.

So, $z_{(15, 15)} = z_{(10, 20)} \Rightarrow 15p + 15q = 20q \Rightarrow q = 3p$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.941Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4909, 3, NULL, NULL, '$ \int x\sqrt{x+2} $ is equal to:

$$ \frac{ 贰 }{ 贰 } $$', NULL, '[{"text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}-\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $","image_url":null,"alt":null},{"text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}+\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $","image_url":null,"alt":null},{"text":"$ \\frac{1}{5}(x+2)^{\\frac{5}{2}}+\\frac{2}{3}(x+2)^{\\frac{3}{2}}+C $","image_url":null,"alt":null},{"text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}+\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $","image_url":null,"alt":null}]', NULL, 0, '$I = \int x \sqrt{x + 2} \, dx$

Let $x + 2 = t^2 \Rightarrow dx = 2t \, dt$

$\therefore I = \int (t^2 - 2) t \, (2t) \, dt$

$= \int (2t^4 - 4t^2) dt = \frac{2}{5}t^5 - \frac{4}{3}t^3 + C$

$= \frac{2}{5}(x + 2)^{\frac{5}{2}} - \frac{4}{3}(x + 2)^{\frac{3}{2}} + C$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.943Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4910, 3, NULL, NULL, 'Three urns contain 6 red, 4 black; 4 red, 6 black and 5 red, 5 black marbles respectively. One of the urns is selected at random and a marble is drawn from it. If the marble drawn is red, then the probability that it is drawn from the first urn is', NULL, '[{"text":"$ \\frac{6}{10} $","image_url":null,"alt":null},{"text":"$ \\frac{4}{10} $","image_url":null,"alt":null},{"text":"$ \\frac{5}{10} $","image_url":null,"alt":null},{"text":"$ \\frac{2}{5} $","image_url":null,"alt":null}]', NULL, 3, 'Let

6R 4R 5R

$ \frac{4B''}{U-1}\frac{6B''}{U-2}\frac{5B}{U-3} $

E: Drawn marble is red

$ E_1 $: Drawn marble from urn I

$ E_2 $: Drawn marble from urn II

$ E_3 $: Drawn marble from urn III

So, $ P(E_1) = P(E_2) = P(E_3) = \frac{1}{3} $

So, by conditional probability

$ P\left(\frac{E_1}{E}\right) = \frac{P(E \cap E_1)}{P(E)} $

$ P(E_1)P\left(\frac{E}{E_1}\right) $

$ P(E_1)P\left(\frac{E}{E_1}\right) + P(E_2)P\left(\frac{E}{E_2}\right) + P(E_3)\left(\frac{E}{E_3}\right) $

$ = \frac{\frac{6}{10}}{\frac{6}{10} + \frac{4}{10} + \frac{5}{10}} = \frac{6}{15} = \frac{2}{5} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.945Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4911, 3, NULL, NULL, 'Three persons A, B and C were given a task, whose probabilities of completion their task on time are $ \frac{1}{3}, \frac{1}{4} $, and $ \frac{1}{5} $ respectively. They were asked to complete the task on time independently. The probability that exactly one of them complete the task on time is', NULL, '[{"text":"$ \\frac{2}{15} $","image_url":null,"alt":null},{"text":"$ \\frac{2}{5} $","image_url":null,"alt":null},{"text":"$ \\frac{3}{20} $","image_url":null,"alt":null},{"text":"$ \\frac{13}{20} $","image_url":null,"alt":null}]', NULL, 3, 'Given, $ P(A)=\frac{1}{3}; P(B)=\frac{1}{4}; P(C)=\frac{1}{5} $

So, required probability

$ P=\frac{1}{3}\times\frac{3}{4}\times\frac{4}{5}+\frac{2}{3}\times\frac{1}{4}\times\frac{4}{5}+\frac{2}{3}\times\frac{3}{4}\times\frac{1}{5} $

$ =\frac{12+8+6}{60}=\frac{26}{60}=\frac{13}{30} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.946Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4912, 3, NULL, NULL, 'Read the text carefully and answer the questions: Three persons A, B and C were given a task, whose probabilities of completion their task on time are $\frac{1}{3},\frac{1}{4}$ and $\frac{1}{5}$ respectively. They were asked to complete the task on time independently. The probability that exactly two of them complete the task on time is', NULL, '[{"text":"$\\frac{3}{20}$","image_url":null,"alt":null},{"text":"$\\frac{13}{20}$","image_url":null,"alt":null},{"text":"$\\frac{1}{5}$","image_url":null,"alt":null},{"text":"$\\frac{2}{15}$","image_url":null,"alt":null}]', NULL, 0, 'Given, $ P(A)=\frac{1}{3}; P(B)=\frac{1}{4}; P(C)=\frac{1}{5} $

Required probability

$ P=\frac{1}{3}\times\frac{1}{4}\times\frac{4}{5}+\frac{2}{3}\times\frac{1}{4}\times\frac{1}{5}+\frac{1}{3}\times\frac{3}{4}\times\frac{1}{5} $

$ =\frac{4+2+3}{60}=\frac{9}{60}=\frac{3}{20} $', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.947Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
