INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4960, 4, NULL, NULL, 'Two identical charged metallic spheres A and B repel each other with a force F. A third sphere of same size but uncharged is brought in contact with ''A'' then brought in contact with ''B''. The new force between A and B is', NULL, '[{"text":"F","image_url":null,"alt":null},{"text":"$ \\frac{3}{8}F $","image_url":null,"alt":null},{"text":"$ \\frac{3}{4}F $","image_url":null,"alt":null},{"text":"$ \\frac{1}{2}F $","image_url":null,"alt":null}]', NULL, 0, 'The sphere are equally charged.

Let the charge be $q$.

Now, applying Coulomb''s law,

$F = \frac{Kq^{2}}{r}$

where $r$ is the distance between two sphere.

When the uncharged sphere touches sphere A and sphere

B, then charged will get $q/2$ on both spheres.

So, new force will be

$F'' = \frac{K\left(\frac{q}{2}\right)\left(\frac{q}{2}\right)}{\left(\frac{r}{2}\right)^{2}} = \frac{Kq^{2}}{r^{2}} = F$', NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:28.974Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
