INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5075, 18, NULL, NULL, 'A constant retarding force of 50 N is applied to a body of mass 20 kg moving initially with a speed of 15 m s $ ^{-1} $. How long does the body take to stop?', NULL, '[{"text":"6 s","image_url":null,"alt":null},{"text":"2.5 s","image_url":null,"alt":null},{"text":"15 s","image_url":null,"alt":null},{"text":"50 s","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.047Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
