INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5078, 18, NULL, NULL, 'A body moves from point A to B under the action of a force, varying in magnitude as shown in the figure. Force is expressed in newton and displacement in meter. What is the total work done?', NULL, '[{"text":"37.5 J","image_url":null,"alt":null},{"text":"100 J","image_url":null,"alt":null},{"text":"12.5 J","image_url":null,"alt":null},{"text":"22.5 J","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2021, '/local-papers/assets/cucet-2021-general-test/q35-figure-1.jpg', 'Figure for question 35', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.049Z', NULL, NULL, '[{"url":"/local-papers/assets/cucet-2021-general-test/q35-figure-1.jpg","alt":"Figure for question 35","kind":"figure"}]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5079, 18, NULL, NULL, 'A bomb explodes in air when it has a horizontal speed of $ v $. It breaks into two identical pieces of equal mass. If one goes vertically up at a speed of $ 4v $, the velocity of other immediately after the explosion is', NULL, '[{"text":"$ -4v\\hat{j} $","image_url":null,"alt":null},{"text":"$ -v\\hat{i} $","image_url":null,"alt":null},{"text":"$ 2v\\hat{i}-4v\\hat{j} $","image_url":null,"alt":null},{"text":"$ 2v\\hat{i}+4v\\hat{j} $","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.050Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5080, 18, NULL, NULL, 'A 40 kg boy whose legs are 4 cm² in area and 50 cm long falls through a height of 2 m without breaking his leg bones. If the bones can withstand a stress of 0.9 × 10⁸ N/m². The Young''s modulus for the material of the bone is', NULL, '[{"text":"$ 0.9 \\times 10^{8} \\, N/m^{2} $","image_url":null,"alt":null},{"text":"$ 5 \\times 10^{8} \\, N/m^{2} $","image_url":null,"alt":null},{"text":"$ 2.05 \\times 10^{9} \\, N/m^{2} $","image_url":null,"alt":null},{"text":"$ 2.05 \\times 10^{8} \\, N/m^{2} $","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.050Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5081, 18, NULL, NULL, 'The length of a metal wire is $ l_{1} $ when the tension is $ T_{1} $ and $ l_{2} $ when the tension is $ T_{2} $. The unstretched length of the wire is', NULL, '[{"text":"$ \\frac{T_{2}l_{1}-T_{1}l_{2}}{T_{2}-T_{1}} $","image_url":null,"alt":null},{"text":"$ \\frac{T_{2}l_{1}+T_{1}l_{2}}{T_{2}-T_{1}} $","image_url":null,"alt":null},{"text":"$ \\frac{T_{2}l_{1}-T_{1}l_{2}}{T_{2}+T_{1}} $","image_url":null,"alt":null},{"text":"$ \\frac{T_{2}l_{1}+T_{1}l_{2}}{T_{2}+T_{1}} $","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.051Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5082, 18, NULL, NULL, 'Two cylinders A and B of the same material have same length, their radii being in the ratio 1:2 respectively. The two are joined end to end as shown in the figure. One end of cylinder A is rigidly clamped while free end of cylinder B is twisted through an angle $ \theta $. The angle of twist of cylinder A is', NULL, '[{"text":"$ \\frac{17}{16}\\theta $","image_url":null,"alt":null},{"text":"$ 16\\theta $","image_url":null,"alt":null},{"text":"$ 17\\theta $","image_url":null,"alt":null},{"text":"$ \\frac{16}{17}\\theta $","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.051Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5083, 18, NULL, NULL, 'Soapy water drips from a capillary. When the drop breaks away, the diameter of its neck is D. The mass of the drop is m. The surface tension of soapy water is', NULL, '[{"text":"$ \\frac{mgD}{\\pi} $","image_url":null,"alt":null},{"text":"$ \\frac{mg}{\\pi D} $","image_url":null,"alt":null},{"text":"$ \\frac{mg}{D} $","image_url":null,"alt":null},{"text":"$ \\frac{m}{\\pi gD} $","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.051Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5084, 18, NULL, NULL, 'If the total energy of a particle executing SHM is E, then the potential energy V and the kinetic energy K of the particle in terms of E when its displacement is half of its amplitude will be', NULL, '[{"text":"$ V = E/4 $ and $ K = 3E/4 $","image_url":null,"alt":null},{"text":"$ V = 3E/4 $ and $ K = E/4 $","image_url":null,"alt":null},{"text":"$ V = 3E/4 $ and $ K = 3E/4 $","image_url":null,"alt":null},{"text":"$ V = E/4 $ and $ K = E/4 $","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.052Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
