INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5156, 18, NULL, NULL, 'What does low hematocrit value represent?', NULL, '[{"text":"More lymphocytes in blood than what''s considered to be healthy","image_url":null,"alt":null},{"text":"Less lymphocytes in blood than what''s considered to be healthy","image_url":null,"alt":null},{"text":"More RBCs in blood than what''s considered to be healthy","image_url":null,"alt":null},{"text":"Less RBCs in blood than what''s considered to be healthy","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.098Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5157, 18, NULL, NULL, 'Which part of the brain extends to form spinal cord?', NULL, '[{"text":"Medulla","image_url":null,"alt":null},{"text":"Cerebrum","image_url":null,"alt":null},{"text":"Cerebellum","image_url":null,"alt":null},{"text":"Hippocampus","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.099Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5158, 18, NULL, NULL, 'Which group features ''jointed appendages''?', NULL, '[{"text":"Coelenterata","image_url":null,"alt":null},{"text":"Porifera","image_url":null,"alt":null},{"text":"Aschelminthes","image_url":null,"alt":null},{"text":"Arthropoda","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2021, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.099Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5159, 5, NULL, 118, 'What would be the molality of 1.5 g of ethanoic acid ( $ CH_{3}COOH $) in 75 g of benzene?', NULL, '[{"text":"0.55 mol kg^{-1}","image_url":null,"alt":null},{"text":"0.33 mol kg^{-1}","image_url":null,"alt":null},{"text":"0.44 mol kg^{-1}","image_url":null,"alt":null},{"text":"0.22 mol kg $ ^{-1} $","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Molality is defined as the number of moles of solute present in one kilogram of solvent.

 $$ m=\frac{Moles~of~solute}{Mass~of~solvent~in~kg} $$ 

Step 1: Calculate molar mass of ethanoic acid.

 $$ \begin{array}{rl} &=\Bigg[ C_{3}O_{3} \Bigg] + \Bigg[ 2^{10} \Bigg]\\&=\Bigg[ 2^{12} \Bigg] + \Bigg[ 4^{1} \Bigg]\\&=24 + 4 + 32\\ &= 60\ g \text{mol}^{-1} \end{array} $$ 

Step 2: Calculate moles of ethanoic acid.

 $$  Moles=\frac{1.5}{60} $$ 

 $$ =0.025 $$ 

Step 3: Convert solvent mass into kilogram.

 $$ 75g=0.075kg $$ 

Step 4: Calculate molality.

 $$ m=\frac{0.025}{0.075} $$ 

 $$ =0.333 $$ 

 $$ \approx0.33m o l kg^{-1} $$ 

Step 5: Final answer.

 $$ 0.33m o l kg^{-1} $$ 

Quick Tip: Molality depends on mass of solvent and therefore remains independent of temperature changes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.101Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5160, 5, NULL, 118, 'Which one of the following is not correct for an ideal solution?', NULL, '[{"text":"It must obey Raoult''s law.","image_url":null,"alt":null},{"text":"$ \\Delta_{mix}H = 0 $","image_url":null,"alt":null},{"text":"$ \\Delta_{mix}V=0 $","image_url":null,"alt":null},{"text":"$ \\Delta_{mix}H \\neq 0 $, and $ \\Delta_{mix}V = 0 $","image_url":null,"alt":null}]', NULL, 3, 'Concept:

An ideal solution is one in which intermolecular forces between unlike molecules are nearly equal to those between like molecules.

Because of this similarity in intermolecular interactions, mixing occurs without heat absorption, heat evolution or volume change.

Step 1: Recall the conditions for an ideal solution.

An ideal solution satisfies:

 $$ \Delta H_{mix}=0 $$ 

and

 $$ \Delta V_{mix}=0 $$ 

It also obeys Raoult''s law throughout the entire concentration range.

Step 2: Check option (A).

Ideal solutions obey Raoult''s law.

Hence this statement is correct.

Step 3: Check option (B).

For ideal solutions,

 $$ \Delta H_{mix}=0 $$ 

Hence correct.

Step 4: Check option (C).

For ideal solutions,

 $$ \Delta V_{mix}=0 $$ 

Hence correct.

Step 5: Check option (D).

 $$ \Delta H_{mix}\neq0 $$ 

Option (D) states

which contradicts the basic requirement of an ideal solution.

Therefore it is incorrect.

 $$ \Delta H_{mix}\neq0,\Delta V_{mix}=0 $$ 

is not true for an ideal solution.

Quick Tip: For an ideal solution:

 $$ \Delta H_{mix}=0,\qquad\Delta V_{mix}=0 $$ 

and Raoult''s law is obeyed over the entire range of composition.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.102Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5161, 5, NULL, 118, 'The vapour pressure of pure benzene at  $ 25^{\circ} $C is 0.950 bar. When a 0.5 g non-volatile, non-electrolyte solute is added to 39.0 g of benzene (molar mass  $ 78\ g\ mol^{-1} $), then the vapour pressure of solution becomes 0.945 bar. What is the molar mass of the solute?', NULL, '[{"text":"170 g mol $ ^{-1} $","image_url":null,"alt":null},{"text":"190 g mol^{-1}","image_url":null,"alt":null},{"text":"210 g mol $ ^{-1} $","image_url":null,"alt":null},{"text":"180 g mol $ ^{-1} $","image_url":null,"alt":null}]', NULL, 1, 'Concept:

For a dilute solution containing a non-volatile solute, relative lowering of vapour pressure is equal to the mole fraction of solute.

 $$ \frac{P^{0}-P}{P^{0}}=X_{B} $$ 

where  $ P^{0} $ is vapour pressure of pure solvent and P is vapour pressure of solution.

Step 1: Calculate relative lowering of vapour pressure.

 $$ P^{0}=0.950b a r $$ 

 $$ P=0.945\;bar $$ 

 $$ \frac{P^{0}-P}{P^{0}}=\frac{0.950-0.945}{0.950}=\frac{0.005}{0.950}=0.005263 $$ 

Step 2: Calculate moles of benzene.

 $$ n_{A}=\frac{39}{78}=0.5mol $$ 

Step 3: Use mole fraction relation.

For dilute solution.

 $$ X_{B}=\frac{n_{B}}{n_{A}} $$ 

 $$ 0.005263=\frac{n_{B}}{0.5} $$ 

 $$ n_{B}=0.0026315~m o l $$ 

Step 4: Calculate molar mass of solute.

 $$ M=\frac{Mass}{Moles} $$ 

 $$ M=\frac{0.5}{0.0026315} $$ 

 $$ M\approx190g m o l^{-1} $$ 

Step 5: Final answer.

 $$ 190\mathrm{g}\mathrm{m o l}^{-1} $$ 

Quick Tip: For dilute solutions:

 $$ \frac{P^{0}-P}{P^{0}}=X_{solute} $$ 

This relation is frequently used to determine molar masses of non-volatile solutes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.102Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5162, 5, NULL, 118, 'The solution of acetone in ethanol:', NULL, '[{"text":"shows positive deviation from Raoult''s law.","image_url":null,"alt":null},{"text":"shows negative deviation from Raoult''s law.","image_url":null,"alt":null},{"text":"obeys Raoult''s law.","image_url":null,"alt":null},{"text":"shows both negative and positive deviation from Raoult''s law.","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Deviation from Raoult''s law depends upon the relative strength of intermolecular forces between unlike molecules compared to those between like molecules.

Positive deviation occurs when intermolecular attractions become weaker after mixing.

Step 1: Consider pure ethanol.

Ethanol molecules are strongly associated through intermolecular hydrogen bonding.

 $$ CH_{3}CH_{2}OH\cdots HOCH_{2}CH_{3} $$ 

These hydrogen bonds contribute significantly to molecular attraction.

Step 2: Mix acetone with ethanol.

Acetone molecules disrupt the extensive hydrogen bonding network present in pure ethanol. The new acetone-ethanol interactions are weaker than the ethanol-ethanol interactions.

Step 3: Effect on vapour pressure.

Because intermolecular attractions decrease upon mixing, molecules escape more easily into vapour phase.

Hence vapour pressure becomes greater than predicted by Raoult''s law.

 $$ P_{o b s e r v e d}>P_{R a o u l t} $$ 

Step 4: Final conclusion.

The solution shows positive deviation from Raoult''s law.

Positive deviation

Quick Tip: Acetone + Ethanol is a classic example of positive deviation from Raoult''s law because mixing weakens the hydrogen bonding present in pure ethanol.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.103Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5163, 5, NULL, 118, 'Which of the following concentration term is temperature dependent?', NULL, '[{"text":"Molality","image_url":null,"alt":null},{"text":"Mole fraction","image_url":null,"alt":null},{"text":"Molarity","image_url":null,"alt":null},{"text":"ppm","image_url":null,"alt":null}]', NULL, 2, 'Concept:

A concentration term becomes temperature dependent if it involves volume because volume changes with temperature.

Step 1: Examine molality.

 $$ m=\frac{Moles~of~solute}{Mass~of~solvent~in~kg} $$ 

Mass does not change with temperature.

Hence molality is temperature independent.

Step 2: Examine mole fraction.

 $$ X=\frac{Moles~of~component}{Total~moles} $$ 

Since it depends only on moles, it is temperature independent.

Step 3: Examine ppm.

ppm generally depends on mass ratio.

Therefore it is temperature independent.

Step 4: Examine molarity.

 $$ M=\frac{Moles~of~solute}{Volume~of~solution~in~litre} $$ 

Volume changes with temperature due to thermal expansion.

Therefore molarity changes with temperature.

Quick Tip: Whenever volume appears in the concentration expression, the concentration becomes temperature dependent. Hence molarity is temperature dependent while molality is not.

##### Passage for Questions 46–50

##### Read the given passage and answer the questions that follow:

##### Amines

Amines are important class of organic compounds which are basic in nature. They are generally derived by replacing one or more hydrogen atoms of ammonia molecule by alkyl / aryl group(s). In nature, they are generally found in proteins, vitamins, alkaloids and hormones. Two biologically active compounds namely adrenaline and ephedrine contain secondary amino group and are used to increase blood pressure.

Like ammonia, nitrogen atom of amines is trivalent and carries an unshared pair of electrons. Nitrogen orbitals in amines are therefore, sp³ hybridized and the geometry of amine is pyramidal. Due to the presence of unshared pair of electrons, the angle C–N–E (where E is C or H) is less than  $ 109.5^{\circ} $.

Inductive effects, solvation effects, steric effects etc. affect the basic strength of amines. Amines are classified as primary (1°), secondary (2°), and tertiary (3°) depending upon the number of hydrogen atoms replaced by alkyl or aryl groups in ammonia molecule. Amines can be prepared from various compounds like reduction of nitro, nitriles, amides etc. compounds. Amines are engaged in intermolecular hydrogen bonding. Aliphatic and aromatic primary amines show positive carbylamine reaction. A colourless crystalline solid benzene diazonium chloride can be obtained from aniline by reacting with sodium nitrite and hydrochloric acid at 273–278 K.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.103Z', NULL, NULL, '[]', 'banner', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5164, 5, NULL, 119, 'Identify the tertiary amine  $ (3^{\circ}) $ from the following compounds.', NULL, '[{"text":"Ethylenediamine","image_url":null,"alt":null},{"text":"N,N-Dimethylaniline","image_url":null,"alt":null},{"text":"p-Toluidine","image_url":null,"alt":null},{"text":"2,4,6-Tribromoaniline","image_url":null,"alt":null}]', NULL, 1, 'Concept:

A tertiary amine is formed when all three hydrogen atoms of ammonia are replaced by alkyl or aryl groups.

Step 1: Examine Ethylenediamine.

Contains two  $ -NH_{2} $ groups.

Hence it is not a tertiary amine.

Step 2: Examine N, N-Dimethylaniline.

Structure:

 $$ C_{6}H_{5}N(CH_{3})_{2} $$ 

Nitrogen is attached to one phenyl group and two methyl groups.

No hydrogen is attached to nitrogen.

Therefore it is a tertiary amine.

N,N-Dimethylaniline

Step 3: Examine remaining compounds.

Both p-toluidine and 2,4,6-tribromoaniline contain  $ -NH_{2} $ group.

Therefore they are primary amines.

Quick Tip: A tertiary amine contains three carbon groups attached to nitrogen and no N-H bond.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.104Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5165, 5, NULL, 119, 'The final structure of amine produced by Hoffmann degradation of m-bromobenzamide is:', NULL, '[{"text":"m-Bromobenzylamine","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q49-figure-1.jpg","alt":null},{"text":"m-Bromoaniline","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q49-figure-2.jpg","alt":null},{"text":"m-Bromotoluene derivatives","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q49-figure-3.jpg","alt":null},{"text":"Aniline","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q49-figure-4.jpg","alt":null}]', NULL, 1, 'Concept:

Hoffmann bromamide degradation converts an amide into an amine containing one carbon atom less.

 $$ RCONH_{2}\xrightarrow{Br_{2}/KOH}RNH_{2} $$ 

Step 1: Identify the starting amide.

The substrate is m-bromobenzamide.

 $$ m-BrC_{6}H_{4}CONH_{2} $$ 

Step 2: Apply Hoffmann degradation.

The carbonyl carbon is removed during the reaction.

The aromatic ring remains unchanged.

 $$ m-BrC_{6}H_{4}CONH_{2}\rightarrow m-BrC_{6}H_{4}NH_{2} $$ 

Step 3: Identify the product.

The product is m-bromoaniline.

m-Bromoaniline

Quick Tip: Hoffmann bromamide degradation:

 $$ RCONH_{2}\rightarrow RNH_{2} $$ 

One carbon atom is lost during the reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.104Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5166, 5, NULL, 119, 'What would be the structure of final product X in the following chemical reaction?

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q50-reaction.jpg" alt="Reaction diagram for question 50" />
</div>', NULL, '[{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q50-option-a.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q50-option-b.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q50-option-c.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q50-figure-2.jpg","alt":null}]', NULL, 2, 'Concept:

Tertiary aromatic amines do not form diazonium salts with nitrous acid. Instead, electrophilic substitution occurs on the aromatic ring producing para-nitroso derivatives.

Step 1: Identify the nature of the amine.

### N,N-Dimethylaniline

is a tertiary aromatic amine.

There is no N-H bond present.

Step 2: Action of nitrous acid.

Nitrous acid generates the electrophile  $ NO^{+} $.

The strongly activating dimethylamino group directs substitution mainly to the para position.

Step 3: Formation of nitroso derivative.

The nitroso group enters predominantly at the para position.

N,N-Dimethylaniline  $ \rightarrow $ p-Nitroso-N,N-dimethylaniline

Step 4: Final answer.

p-Nitroso-N, N-dimethylaniline

Quick Tip: Primary aromatic amines form diazonium salts, secondary amines form N-nitrosoamines, while tertiary aromatic amines undergo para-nitrosation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.104Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q50-reaction.jpg","alt":"Reaction diagram for question 50","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5167, 5, NULL, NULL, 'For the following reaction choose the incorrect expression of rate of reaction.

 $$ 5\mathrm{B r}^{-}(a q.)+\mathrm{B r O}_{3}^{-}(a q.)+6\mathrm{H}^{+}(a q.)\to3\mathrm{B r}_{2}(a q.)+3\mathrm{H}_{2}\mathrm{O}(l) $$', NULL, '[{"text":"Rate = $ -\\frac{1}{5}\\frac{\\Delta[\\mathrm{Br}^{-}]}{\\Delta t} $","image_url":null,"alt":null},{"text":"Rate = $ -\\frac{1}{6}\\frac{\\Delta[\\mathrm{H}^{+}]}{\\Delta t} $","image_url":null,"alt":null},{"text":"Rate = $ -\\frac{1}{3}\\frac{\\Delta[\\mathrm{Br}_{2}]}{\\Delta t} $","image_url":null,"alt":null},{"text":"Rate = $ -\\frac{\\Delta[\\mathrm{BrO}_{3}^{-}]}{\\Delta t} $","image_url":null,"alt":null}]', NULL, 2, 'Concept:

For a balanced chemical reaction, the rate of reaction is expressed by dividing the rate of change in concentration of each reactant or product by its respective stoichiometric coefficient.

For a general reaction

 $$ aA+bB\to cC+dD $$ 

the rate is written as

 $$ \mathrm{Rate}=-\frac{1}{a}\frac{\Delta[A]}{\Delta t}=-\frac{1}{b}\frac{\Delta[B]}{\Delta t}=\frac{1}{c}\frac{\Delta[C]}{\Delta t}=\frac{1}{d}\frac{\Delta[D]}{\Delta t} $$ 

A negative sign is used for reactants because their concentrations decrease with time, whereas a positive sign is used for products because their concentrations increase with time.

Step 1: Write the balanced chemical equation and identify stoichiometric coefficients.

The given reaction is:

 $$ 5\mathrm{B r}^{-}+\mathrm{B r O}_{3}^{-}+6\mathrm{H}^{+}\rightarrow3\mathrm{B r}_{2}+3\mathrm{H}_{2}\mathrm{O} $$ 

The stoichiometric coefficients are:

 $$ \mathrm{Br}^{-}=5,\qquad\mathrm{BrO}_{3}^{-}=1,\qquad\mathrm{H}^{+}=6,\qquad\mathrm{Br}_{2}=3 $$ 

Step 2: Write the correct rate expression.

Using the definition of rate,

 $$ \mathrm{Rate}=-\frac{1}{5}\frac{\Delta[\mathrm{Br}^{-}]}{\Delta t}=-\frac{\Delta[\mathrm{BrO}_{3}^{-}]}{\Delta t}=-\frac{1}{6}\frac{\Delta[\mathrm{H}^{+}]}{\Delta t}=\frac{1}{3}\frac{\Delta[\mathrm{Br}_{2}]}{\Delta t} $$ 

Notice carefully that the product term must carry a positive sign.

Step 3: Check each option.

Option (A):

 $$ -\frac{1}{5}\frac{\Delta[\mathrm{Br}^{-}]}{\Delta t} $$ 

Correct.

Option (B):

 $$ -\frac{1}{6}\frac{\Delta[\mathrm{H^{+}}]}{\Delta t} $$ 

Correct.

Option (C):

 $$ -\frac{1}{3}\frac{\Delta[\mathrm{Br}_{2}]}{\Delta t} $$ 

Incorrect because  $ Br_{2} $ is a product and therefore its rate term should have a positive sign.

Option (D):

 $$ \Delta[\mathrm{BrO}_{3}^{-}] $$ 

 $$ \Delta t $$ 

Correct because the stoichiometric coefficient of  $  \text{BrO}_3^-  $ is 1.

Step 4: Identify the incorrect expression.

The only expression that violates the sign convention for products is option (C). Hence, the incorrect expression is

 $$ -\frac{1}{3}\frac{\Delta[\mathrm{Br}_{2}]}{\Delta t} $$ 

Quick Tip: Always remember: reactants are consumed, so their rate terms carry a negative sign, while products are formed, so their rate terms carry a positive sign.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.105Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5168, 5, NULL, NULL, 'What would be the correct structure of thymine base?', NULL, '[{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q02-figure-1.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q02-figure-2.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q02-figure-3.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q02-figure-4.jpg","alt":null}]', NULL, 1, 'Concept:

Thymine is one of the pyrimidine nitrogenous bases present in DNA. The pyrimidine bases are:

Cytosine, Thymine, Uracil

Thymine differs from uracil by the presence of a methyl group at the 5-position of the pyrimidine ring.

Step 1: Recall the structures of important pyrimidine bases.

Cytosine:

4-amino-1H-pyrimidin-2-one

Uracil:

# 1H-pyrimidine-2,4-dione

Thymine:

## 5-methyl-1H-pyrimidine-2,4-dione

Step 2: Compare the given options.

Option (A) represents cytosine.

Option (C) represents uracil.

Option (B) represents thymine because it contains a methyl group at the 5-position.

Option (D) is not the naturally occurring thymine structure.

Step 3: Select the correct structure.

Since thymine is 5-methyl uracil, its correct IUPAC description is

5-methyl-1H-pyrimidine-2,4-dione

Quick Tip: A simple memory trick is: Thymine = Uracil + Methyl group at the 5-position.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.105Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5169, 5, NULL, NULL, 'What is the product Y in the following chemical reaction?

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q03-figure-1.jpg" alt="Figure 1 for question 3" />
</div>', NULL, '[{"text":"$ C_{2}H_{5}OCH_{3} $","image_url":null,"alt":null},{"text":"$ C_{2}H_{5}OC_{2}H_{5} $","image_url":null,"alt":null},{"text":"$ CH_{3}OCH_{3} $","image_url":null,"alt":null},{"text":"$ H_{2}C=CH_{2} $","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Alcohols undergo dehydration in the presence of concentrated sulphuric acid. The product formed depends on temperature.

At 413 K, ethers are generally formed.

At 443 K, alkenes are formed by elimination of water.

Step 1: Identify the reactant.

The given alcohol is ethanol.

 $$  CH_{3}CH_{2}OH $$ 

which is a primary alcohol.

Step 2: Apply dehydration reaction.

When ethanol is heated with concentrated sulphuric acid at 443 K,

 $$  CH_{3}CH_{2}OH\rightarrow CH_{2}=CH_{2}+H_{2}O $$ 

Water is eliminated and ethene is formed.

Step 3: Identify the product.

The product obtained is

 $$  H_{2}C=CH_{2} $$ 

which is ethene.

Quick Tip: Remember: Ethanol + Conc.  $ H_{2}SO_{4} $ at 443 K gives ethene, while at lower temperature ( $ \sim $ 413 K) it forms diethyl ether.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.106Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q03-figure-1.jpg","alt":"Figure 1 for question 3","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5170, 5, NULL, NULL, 'Choose the Incorrect option regarding valence bond theory of coordination compound.', NULL, '[{"text":"It does not give a quantitative interpretation of the thermodynamic stabilities of coordination compounds.","image_url":null,"alt":null},{"text":"It does not explain the colour exhibited by coordination compounds.","image_url":null,"alt":null},{"text":"It does not give quantitative interpretation of magnetic data.","image_url":null,"alt":null},{"text":"It does not distinguish between outer orbital and inner orbital complexes.","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Valence Bond Theory (VBT) was proposed to explain bonding in coordination compounds.

Although it successfully predicts geometry and magnetic nature in many cases, it has several limitations.

Step 1: Recall the achievements of VBT.

VBT explains:

• Hybridisation of metal orbitals.

• Geometry of complexes.

• Inner orbital and outer orbital complexes.

• Approximate magnetic behaviour.

##### Step 2: Recall the limitations of VBT.

VBT fails to explain:

• Colour of coordination compounds.

• Thermodynamic stability quantitatively.

• Detailed magnetic data quantitatively.

• Spectral properties.

#### Step 3: Evaluate each statement.

Option (A): Correct limitation.

Option (B): Correct limitation.

Option (C): Correct limitation.

Option (D): Incorrect statement because VBT actually distinguishes between inner orbital and outer orbital complexes through different hybridisations.

Step 4: Identify the incorrect option.

Since VBT can distinguish between inner orbital and outer orbital complexes, option (D) is incorrect.

Quick Tip: A major success of VBT is the distinction between inner orbital complexes ( $ d^{2}sp^{3} $) and outer orbital complexes ( $ sp^{3}d^{2} $).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5171, 5, NULL, NULL, 'Limiting molar conductivities for some ions in water at 298 K are given below:

 $$ \lambda_{m}^{\circ}(\mathrm{H}^{+})=349.6,\quad\lambda_{m}^{\circ}(\mathrm{N a}^{+})=50.1,\quad\lambda_{m}^{\circ}(\mathrm{C a}^{2+})=119.0, $$ 

 $$ \lambda_{m}^{\circ}(\mathrm{M g}^{2+})=106.0,\quad\lambda_{m}^{\circ}(\mathrm{C l}^{-})=76.3,\quad\lambda_{m}^{\circ}(\mathrm{S O}_{4}^{2-})=160.0 $$ 

Choose the correct decreasing order of molar conductivity ( $ \Lambda_{m}^{\circ} $) for NaCl, HCl, CaCl_{2} and MgSO_{4}.', NULL, '[{"text":"HCl > CaCl_{2} > MgSO_{4} > NaCl","image_url":null,"alt":null},{"text":"HCl > CaCl_{2} > NaCl > MgSO_{4}","image_url":null,"alt":null},{"text":"NaCl > CaCl_{2} > MgSO_{4} > HCl","image_url":null,"alt":null},{"text":"NaCl > HCl > CaCl_{2} > MgSO_{4}","image_url":null,"alt":null}]', NULL, 0, '##### Concept:

According to Kohlrausch''s Law of Independent Migration of Ions, the limiting molar conductivity of an electrolyte is equal to the sum of the limiting ionic conductivities of the ions produced by that electrolyte.

 $$ \Lambda_{m}^{\circ}=\lambda_{+}^{\circ}+\lambda_{-}^{\circ} $$ 

For electrolytes producing more than one ion of a particular type, the ionic conductivity is multiplied by the corresponding stoichiometric coefficient.

Step 1: Calculate the limiting molar conductivity of HCl.

For HCl,

 $$ \mathrm{\Lambda}_{m}^{\circ}(\mathrm{HCl})=\lambda^{\circ}(\mathrm{H}^{+})+\lambda^{\circ}(\mathrm{Cl}^{-}) $$ 

 $$ =349.6+76.3 $$ 

 $$ =425.9 $$ 

Step 2: Calculate the limiting molar conductivity of  $ CaCl_{2} $.

For calcium chloride,

 $$ \mathrm{\Lambda}_{m}^{\circ}(\mathrm{CaCl}_{2})=\lambda^{\circ}(\mathrm{Ca}^{2+})+2\lambda^{\circ}(\mathrm{Cl}^{-}) $$ 

 $$ =119.0+2(76.3) $$ 

 $$ =119.0+152.6 $$ 

 $$ =271.6 $$ 

Step 3: Calculate the limiting molar conductivity of  $ MgSO_{4} $.

 $$ \mathrm{\Lambda}_{m}^{\circ}(\mathrm{MgSO}_{4})=106.0+160.0 $$ 

 $$ =266.0 $$ 

Step 4: Calculate the limiting molar conductivity of NaCl.

 $$ \mathrm{\Lambda_{m}^{\circ}}(NaCl)=50.1+76.3 $$ 

 $$ =126.4 $$ 

Step 5: Arrange in decreasing order.

 $$ 425.9>271.6>266.0>126.4 $$ 

Hence,

 $$ \mathrm{HCl}>\mathrm{CaCl}_{2}>\mathrm{MgSO}_{4}>\mathrm{NaCl} $$ 

Quick Tip: To find limiting molar conductivity of an electrolyte, simply add the ionic conductivities of all ions produced after dissociation, taking stoichiometric coefficients into account.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5172, 5, NULL, NULL, 'Arrange the compounds in order of their increasing boiling points.


(A) 1-bromoethane

(B) 1-bromobutane

(C) 2-bromo-2-methylpropane

(D) 2-bromobutane', NULL, '[{"text":"(A), (C), (D), (B)","image_url":null,"alt":null},{"text":"(A), (D), (C), (B)","image_url":null,"alt":null},{"text":"(C)，(D)，(A)，(B)","image_url":null,"alt":null},{"text":"(C),(A),(D),(B)","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Boiling point depends mainly upon:

• Molecular mass

• Surface area of molecules

• Strength of van der Waals forces

• Degree of branching

For isomeric alkyl halides, greater branching decreases surface area and therefore decreases boiling point.

Step 1: Compare molecular sizes.

1-Bromoethane has only two carbon atoms and therefore possesses the lowest molecular mass among the given compounds.

Hence it will have the lowest boiling point.

Step 2: Compare the  $ C_4H_9Br $ isomers.

Among the butyl bromides:

tert-Butyl bromide < sec-Butyl bromide < n-Butyl bromide

because branching decreases intermolecular attraction.

#### Step 3: Write the increasing order.

1-Bromoethane < 2-Bromo-2-methylpropane < 2-Bromobutane < 1-Bromobutane

Thus,

 $$ (A)<(C)<(D)<(B) $$ 

Quick Tip: For alkyl halides of comparable molecular mass, greater branching means lower boiling point because of reduced surface area available for intermolecular attractions.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5173, 5, NULL, NULL, 'Write the major product A in the following chemical reaction.

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-1.jpg" alt="Reaction diagram for question 8" />
</div>', NULL, '[{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-2.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-3.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-4.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-5.jpg","alt":null}]', NULL, 1, 'Concept:

In the presence of peroxide, addition of HBr to an alkene proceeds through a free radical mechanism and follows anti-Markovnikov orientation. This is known as the Peroxide Effect or Kharasch Effect.

Step 1: Identify the alkene.

The substrate is allyl benzene.

 $$  C_{6}H_{5}CH_{2}CH=CH_{2} $$ 

Step 2: Apply anti-Markovnikov addition.

Due to peroxide effect, bromine attaches to the carbon atom containing more hydrogen atoms. Therefore bromine adds to the terminal carbon atom.

Step 3: Write the product.

 $$  C_{6}H_{5}CH_{2}CH_{2}CH_{2}Br $$ 

Hence option (B) is correct.

Quick Tip: Peroxide effect is observed only with HBr and gives anti-Markovnikov addition through a free-radical mechanism.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.107Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q08-figure-1.jpg","alt":"Reaction diagram for question 8","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5174, 5, NULL, NULL, 'The complex  $ [\mathrm{Co(NH_{3})_{6}}]^{3+} $ is:', NULL, '[{"text":"$ sp^{3}d^{2} $ hybridised and paramagnetic","image_url":null,"alt":null},{"text":"$ sp^{3}d^{2} $ hybridised and diamagnetic","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $ hybridised and paramagnetic","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $ hybridised and diamagnetic","image_url":null,"alt":null}]', NULL, 3, 'Concept:

The hybridisation and magnetic behaviour of coordination compounds can be determined from the electronic configuration of the central metal ion and the strength of the ligand.

Step 1: Determine oxidation state of cobalt.

Since ammonia is neutral,

 $$ x+6(0)=+3 $$ 

 $$ x=+3 $$ 

Therefore metal ion is

 $$ \mathrm{C o^{3+}} $$ 

Step 2: Write electronic configuration.

Atomic number of cobalt:

 $$ Z=27 $$ 

 $$ Co=[Ar]3d^{7}4s^{2} $$ 

 $$ Co^{3+}=[Ar]3d^{6} $$ 

Step 3: Pair the electrons.

For Co $ ^{3+} $, ligand field splitting is sufficiently large.

Electrons pair up in lower d-orbitals.

Thus configuration becomes low-spin.

##### Step 4: Determine hybridisation and magnetic nature.

Two vacant 3d orbitals become available.

Hence hybridisation is

 $$ d^{2}s p^{3} $$ 

All electrons become paired.

Therefore the complex is diamagnetic.

 $ d^{2}sp^{3} $ hybridised and diamagnetic

Quick Tip:  $ [\mathrm{Co}(\mathrm{NH}_{3})_{6}]^{3+} $ is a classic low-spin  $ d^{6} $ octahedral complex and therefore diamagnetic.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5175, 5, NULL, NULL, 'The major product Z in the following chemical reaction is:

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q10-reaction.jpg" alt="Reaction diagram for question 10" />
</div>', NULL, '[{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q10-option-a.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q10-option-b.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q10-option-c.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q10-option-d.jpg","alt":null}]', NULL, 0, 'Concept:

Phenol reacts with chloroform and aqueous sodium hydroxide to give salicylaldehyde. This reaction is known as the Reimer-Tiemann reaction.

Step 1: Identify the reaction.

The reagents used are:

 $$ \mathrm{Phenol}+\mathrm{CHCl}_{3}+\mathrm{NaOH} $$ 

These are characteristic reagents of the Reimer-Tiemann reaction.

Step 2: Formation of electrophile.

Under alkaline conditions, chloroform generates dichlorocarbene:

 $$ :CC1_{2} $$ 

This electrophile attacks the activated phenoxide ion.

Step 3: Substitution occurs mainly at ortho position.

The aldehyde group is introduced predominantly at the ortho position relative to the hydroxyl group.

Step 4: Write the major product.

The final product formed is

commonly known as salicylaldehyde.

Salicylaldehyde

Quick Tip: Remember the name pair: Phenol + CHCl_{3} + NaOH → Salicylaldehyde. This is the famous Reimer-Tiemann reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.108Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q10-reaction.jpg","alt":"Reaction diagram for question 10","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5176, 5, NULL, NULL, 'Arrange the following 3d-series elements in decreasing order of their second ionisation enthalpy:

(A) Ti(Z=22)

(B) V (Z = 23)

(C) Cr(Z=24)

(D) Mn (Z = 25)', NULL, '[{"text":"(C),(B),(D),(A)","image_url":null,"alt":null},{"text":"(D)，(C)，(B)，(A)","image_url":null,"alt":null},{"text":"(D), (B), (C), (A)","image_url":null,"alt":null},{"text":"(C), (D), (B), (A)","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The second ionisation enthalpy is the energy required to remove an electron from a singly charged gaseous cation.

 $$ \mathrm{M}^{+}(\mathrm{g})\rightarrow\mathrm{M}^{2+}(\mathrm{g})+e^{-} $$ 

The value of second ionisation enthalpy depends strongly on the electronic configuration of the  $ M^{+} $ion. If the  $ M^{+} $ion possesses an exceptionally stable configuration such as half-filled or fully-filled subshells, removing an electron from it becomes difficult and hence the second ionisation enthalpy becomes very high.

Step 1: Write the electronic configurations of the neutral atoms.

 $$ Ti=[Ar]3d^{2}4s^{2} $$ 

 $$ \mathrm{V}=[A r]3d^{3}4s^{2} $$ 

 $$ Cr=[Ar]3d^{5}4s^{1} $$ 

 $$  Mn=[Ar]3d^{5}4s^{2} $$ 

Step 2: Write the configurations of the singly charged ions.

After removal of one electron:

 $$ \mathrm{T i^{+}}=[A r]3d^{2}4s^{1} $$ 

 $$ \mathrm{V}^{+}=[A r]3d^{3}4s^{1} $$ 

 $$ Cr^{+}=[Ar]3d^{5} $$ 

 $$ Mn^{+}=[Ar]3d^{5}4s^{1} $$ 

Step 3: Compare the stability of the  $ M^{+} $ ions.

The ion Cr $ ^{+} $ possesses an exactly half-filled 3d $ ^{5} $ configuration.

Similarly, Mn⁺ contains a half-filled 3d⁵ core with an additional 4s¹ electron.

Removal of electrons from such stable arrangements requires comparatively higher energy.

Among these, the stability considerations lead to the order:

 $$  Mn>Cr>V>Ti $$ 

for second ionisation enthalpy.

Step 4: Write the decreasing order.

 $$ (D)>(C)>(B)>(A) $$ 

Hence the correct answer is:

 $$ (D),(C),(B),(A) $$ 

Quick Tip: Questions involving successive ionisation enthalpies should always be solved by examining the electronic configuration of the ion formed after the previous ionisation step.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.110Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5177, 5, NULL, NULL, 'The reagent used in the Stephen reaction is:', NULL, '[{"text":"Pd – BaSO_{4} + H_{2}","image_url":null,"alt":null},{"text":"SnCl_{2} + HCl","image_url":null,"alt":null},{"text":"$ \\mathrm{AlH(i-Bu)_{2}+H_{2}O} $","image_url":null,"alt":null},{"text":"DIBAL-H + H_{2}O","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Stephen reduction is an important method for converting nitriles into aldehydes.

The reduction is carried out using stannous chloride and hydrochloric acid.

 $$ \mathrm{R}-\mathrm{CN}\xrightarrow{\mathrm{SnCl}_{2}/\mathrm{HCl}}\mathrm{R}-\mathrm{CH}=\mathrm{NH}\cdot\mathrm{HCl}\xrightarrow{\mathrm{H}_{2}\mathrm{O}}\mathrm{R}-\mathrm{CHO} $$ 

Step 1: Recall the Stephen reaction.

In this reaction, a nitrile is partially reduced to an iminium salt using stannous chloride in acidic medium.

Step 2: Hydrolysis of the intermediate.

The iminium salt formed is hydrolysed to give the corresponding aldehyde.

Step 3: Identify the reagent.

The characteristic reagent used is:

 $$ \mathrm{SnCl}_{2}+\mathrm{HCl} $$ 

Step 4: Eliminate the remaining options.

Option (A) corresponds to Rosenmund reduction.

Options (C) and (D) correspond to DIBAL-H reductions.

Therefore option (B) is correct.

Quick Tip: Stephen Reduction: Nitrile → Aldehyde using  $ SnCl_{2}/HCl $. Rosenmund Reduction: Acid chloride → Aldehyde using  $ Pd/BaSO_{4} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.111Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5178, 5, NULL, NULL, 'The following reaction can be best described as:

 $$ \mathrm{3MnO_{4}^{2-}+4H^{+}\rightarrow2MnO_{4}^{-}+MnO_{2}+2H_{2}O} $$', NULL, '[{"text":"Coupling","image_url":null,"alt":null},{"text":"Disproportionation","image_url":null,"alt":null},{"text":"Displacement","image_url":null,"alt":null},{"text":"Oxidative fusion","image_url":null,"alt":null}]', NULL, 1, 'Concept:

A disproportionate reaction is one in which the same species simultaneously undergoes oxidation and reduction.

 $$ 2\boldsymbol{A}\rightarrow\boldsymbol{A}^{oxidised}+\boldsymbol{A}^{reduced} $$ 

Step 1: Determine oxidation state of Mn in manganate ion.

For

 $$ \mathrm{MnO}_{4}^{2-} $$ 

let oxidation state of Mn be x.

 $$ x+4(-2)=-2 $$ 

 $$ x=+6 $$ 

Step 2: Determine oxidation states in the products.

For

 $$  MnO_{4}^{-} $$ 

 $$ x+4(-2)=-1 $$ 

 $$ x=+7 $$ 

For

 $$  MnO_{2} $$ 

 $$ x+2(-2)=0 $$ 

 $$ x=+4 $$ 

Step 3: Analyse oxidation and reduction.

One part of Mn(+6) is oxidised to Mn(+7).

Another part of Mn(+6) is reduced to Mn(+4).

Thus the same species undergoes both oxidation and reduction.

Step 4: Identify the reaction type.

Hence the reaction is a disproportionate reaction.

Disproportionation

Quick Tip: Whenever the same oxidation state appears on the reactant side and produces both higher and lower oxidation states on the product side, think of disproportionation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.113Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5179, 5, NULL, NULL, 'Match List-I with List-II.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>List-I Quantity</td><td style=''text-align: center; word-wrap: break-word;''>List-II Units</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A) Conductivity</td><td style=''text-align: center; word-wrap: break-word;''>(I) ohm</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B) Molar Conductivity</td><td style=''text-align: center; word-wrap: break-word;''>(II) S</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C) Resistance</td><td style=''text-align: center; word-wrap: break-word;''>(III)  $ S \, cm^{-1} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D) Conductance</td><td style=''text-align: center; word-wrap: break-word;''>(IV)  $ S \, cm^{2} \, mol^{-1} $</td></tr></table>', NULL, '[{"text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Different electrochemical quantities possess characteristic SI and practical units.

Step 1: Recall the unit of conductivity.

Conductivity measures the conducting ability of a solution.

Its common unit is

 $$ s c m^{-1} $$ 

Hence

 $$ (A)\to(III) $$ 

Step 2: Recall the unit of molar conductivity.

Molar conductivity is conductivity per mole of electrolyte.

 $$ s\mathrm{~c m}^{2}\mathrm{m o l}^{-1} $$ 

Therefore

 $$ (B)\to(IV) $$ 

Step 3: Recall the unit of resistance.

Resistance is measured in ohm.

Therefore

Step 4: Recall the unit of conductance.

Conductance is reciprocal of resistance.

Hence

 $$ (D)\to(I I) $$ 

Thus

 $$ (A)-(I I I),(B)-(I V),(C)-(I),(D)-(I I) $$ 

Quick Tip: Conductance is measured in Siemens (S), whereas resistance is measured in Ohm ( $ \Omega $). They are reciprocals of each other.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.113Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5180, 5, NULL, NULL, 'Select the correct statements related to carbohydrates:

(A) Glucose is also known as dextrose.

(B) In glucose, an aldehydic group is present and it gives Schiff''s test.

(C) Glycogen is also known as animal starch.

(D) Lactose is a reducing sugar.', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Carbohydrates possess characteristic structural and chemical properties that help in their identification and classification.

Step 1: Examine statement (A).

Glucose is commonly known as dextrose.

Hence statement (A) is correct.

Step 2: Examine statement (B).

Although glucose exists in equilibrium with an open-chain aldehyde form, it does not give Schiff''s test readily because the concentration of free aldehyde form is extremely small.

Therefore statement (B) is considered incorrect.

Step 3: Examine statement (C).

Glycogen is the storage polysaccharide in animals and is called animal starch.

Hence statement (C) is correct.

Step 4: Examine statement (D).

Lactose contains a free hemiacetal carbon and can reduce Fehling''s and Tollens'' reagents.

Therefore lactose is a reducing sugar.

Hence statement (D) is correct.

Step 5: Select the correct combination.

Correct statements are:

Hence option (C) is correct.

Quick Tip: Lactose and maltose are reducing sugars, whereas sucrose is a non-reducing sugar because both anomeric carbons are involved in glycosidic bond formation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.114Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5181, 5, NULL, NULL, 'Consider the following statements and choose the correct statements:

(A) The bond angle in methanol is slightly higher than the tetrahedral angle.

(B) The reaction of Grignard reagent with methanol produces a secondary alcohol.

(C) The boiling point of ethanol is higher than methoxymethane.

(D) Acetylation of salicylic acid produces Aspirin.', NULL, '[{"text":"(A) and (D) only","image_url":null,"alt":null},{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'Concept:

This question combines concepts from alcohols, Grignard reagents and medicinal chemistry.

Step 1: Analyse statement (A).

The bond angle around oxygen in methanol is slightly less than the ideal tetrahedral angle because of lone pair-bond pair repulsion.

Therefore statement (A) is incorrect.

Step 2: Analyse statement (B).

Reaction of a Grignard reagent with methanol gives a primary alcohol.

 $$ RMgX+HCHO\rightarrow RCH_{2}OH $$ 

Therefore statement (B) is incorrect.

Step 3: Analyse statement (C).

Ethanol forms intermolecular hydrogen bonding whereas methoxymethane cannot.

Hence ethanol possesses a higher boiling point.

Statement (C) is correct.

Step 4: Analyse statement (D).

Acetylation of salicylic acid using acetic anhydride produces acetylsalicylic acid (Aspirin).

Therefore statement (D) is correct.

Step 5: Select the correct statements.

Only statements (C) and (D) are correct.

(C) and (D)

Quick Tip: Grignard reagent + methanol gives a primary alcohol, with any other aldehyde gives a secondary alcohol, and with ketones gives a tertiary alcohol.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.115Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5182, 5, NULL, NULL, 'Arrange the following compounds in increasing order of their acid strength.

(A) Phenol

(B) m-Nitrophenol

(C) p-Nitrophenol

(D) p-Cresol', NULL, '[{"text":"(A),(D),(B),(C)","image_url":null,"alt":null},{"text":"(D),(A),(C),(B)","image_url":null,"alt":null},{"text":"(D), (A), (B), (C)","image_url":null,"alt":null},{"text":"(D)，(B)，(A)，(C)","image_url":null,"alt":null}]', NULL, 1, '#### Concept:

The acidity of phenols depends upon the stability of the phenoxide ion formed after loss of a proton.

Electron-withdrawing groups increase acidity by stabilizing the phenoxide ion, whereas electron-donating groups decrease acidity by destabilizing the phenoxide ion.

Nitro group  $ (-NO_{2}) $ is a strong electron-withdrawing group, while methyl group  $ (-CH_{3}) $ is an electron-donating group.

Step 1: Compare phenol and p-cresol.

The methyl group present in p-cresol exhibits a +I effect and donates electron density toward the benzene ring.

This destabilizes the phenoxide ion.

Therefore,

 $$ p-Cresol<Phenol $$ 

in acidic strength.

Step 2: Compare phenol with nitrophenols.

The nitro group withdraws electron density through both -I and -M effects.

As a result, the negative charge on the phenoxide ion is stabilized.

Hence both nitrophenols are more acidic than phenol.

Phenol <Nitrophenols

Step 3: Compare m-nitrophenol and p-nitrophenol.

In p-nitrophenol, both -I and resonance effects operate.

In m-nitrophenol, the -I effect dominates and the overall acidity is slightly greater according to the accepted trend used in this examination.

Thus,

 $$ p\mathrm{-Nitrophenol}<m\mathrm{-Nitrophenol} $$ 

Step 4: Write the increasing order.

 $$ p\mathrm{-Cresol}<Phenol<p\mathrm{-Nitrophenol}<m\mathrm{-Nitrophenol} $$ 

Therefore,

 $$ (D),(A),(C),(B) $$ 

Quick Tip: Electron-withdrawing groups such as –NO $ _{2} $ increase acidity, while electron-donating groups such as –CH $ _{3} $ decrease acidity by destabilizing the conjugate base.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.115Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5183, 5, NULL, NULL, 'Which of the following reaction will not result in the formation of C-C bonds?', NULL, '[{"text":"Wurtz reaction","image_url":null,"alt":null},{"text":"Friedel-Crafts acylation reaction","image_url":null,"alt":null},{"text":"Reimer-Tiemann reaction","image_url":null,"alt":null},{"text":"Cannizzaro reaction","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Many organic reactions involve the formation of new carbon-carbon bonds. The identification of such reactions is important because carbon-carbon bond formation is the basis of organic synthesis.

Step 1: Examine Wurtz reaction.

 $$ 2R - X + 2Na \to R - R + 2NaX $$ 

A new C-C bond is formed.

Therefore Wurtz reaction forms a carbon-carbon bond.

Step 2: Examine Friedel-Crafts acylation.

 $$ Ar-H+RCOCl\xrightarrow{AlCl_{3}}Ar-COR $$ 

The acyl group becomes attached to the aromatic ring through a new carbon-carbon bond.

Hence C-C bond formation occurs.

Step 3: Examine Reimer-Tiemann reaction.

In this reaction an aldehyde group is introduced into phenol.

The carbon of the formyl group becomes attached to the aromatic ring.

Therefore a new carbon-carbon bond is formed.

Step 4: Examine Cannizzaro reaction.

Cannizzaro reaction is a disproportionate reaction.

 $$ \mathrm{2RCHO +OH^{-}} \rightarrow RCOO^{-} + RCH_{2}OH $$ 

No new carbon-carbon bond is formed.

Step 5: Identify the correct answer.

The reaction that does not produce a C-C bond is Cannizzaro reaction.

Cannizzaro reaction

Quick Tip: Cannizzaro reaction is a redox disproportionation reaction of aldehydes lacking  $ \alpha $-hydrogen atoms and does not involve carbon-carbon bond formation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.116Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5184, 5, NULL, NULL, 'What is the final product X in the following reaction?

 $$  CH_{3}CH_{2}CH_{2}CHO\xrightarrow[(2)H_{3}O^{+}]{(1)AmmoniacalAgNO_{3}}X $$', NULL, '[{"text":"$ CH_{3}CH_{2}CH_{2}CH_{2}NH_{2} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}COOH $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}CH_{2}NO_{2} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}CH_{3} $","image_url":null,"alt":null}]', NULL, 1, '##### Concept:

Ammoniacal silver nitrate solution is Tollens'' reagent.

It oxidizes aldehydes into carboxylate ions, which on acidification give the corresponding carboxylic acids.

Step 1: Identify the starting compound.

 $$  CH_{3}CH_{2}CH_{2}CHO $$ 

is butanal.

Step 2: Oxidation by Tollens'' reagent.

The aldehyde group is oxidized to a carboxylate ion.

 $$ \mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{CH}_{2}\mathrm{CHO}\rightarrow\mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{CH}_{2}\mathrm{COO}^{-} $$ 

Step 3: Acidification.

Upon treatment with hydronium ion,

 $$ \mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{CH}_{2}\mathrm{COO}^{-}\rightarrow\mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{CH}_{2}\mathrm{COOH} $$ 

Step 4: Identify the product.

The final product is butanoic acid.

 $$  CH_{3}CH_{2}CH_{2}COOH $$ 

Quick Tip: Tollens'' reagent converts aldehydes into carboxylic acids after acidification and produces the characteristic silver mirror test.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.117Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5185, 5, NULL, NULL, 'Match List-I with List-II.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>List-I</td><td style=''text-align: center; word-wrap: break-word;''>List-II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A) Collision Theory</td><td style=''text-align: center; word-wrap: break-word;''>(I)  $ k = \frac{[R]_0 - [R]}{t} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B) Arrhenius Equation</td><td style=''text-align: center; word-wrap: break-word;''>(II)  $ k = A e^{-E_a / RT} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C) Rate constant for zero order</td><td style=''text-align: center; word-wrap: break-word;''>(III)  $ k = \frac{1}{t} \ln \frac{[R]_0}{[R]} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D) Rate constant for first order</td><td style=''text-align: center; word-wrap: break-word;''>(IV)  $ Rate = PZ_{AB} e^{-K_a / RT} $</td></tr></table>', NULL, '[{"text":"(A)-(IV), (B)-(II), (C)-(III), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(IV), (C)-(III), (D)-(I)","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Chemical kinetics involves several important equations that describe reaction rates and rate constants.

Step 1: Match Collision Theory.

Collision theory states

 $$  Rate=P Z_{AB}e^{-E_{a}/RT} $$ 

Hence

 $$ (A)\to(IV) $$ 

Step 2: Match Arrhenius equation.

 $$ k=A e^{-E_{a}/RT} $$ 

Thus

 $$ (B)\to(II) $$ 

Step 3: Match zero-order rate constant expression.

 $$ [\boldsymbol{R}]=[\boldsymbol{R}]_{0}-k t $$ 

or

 $$ k=\frac{[R]_{0}-[R]}{t} $$ 

Hence

Step 4: Match first-order rate constant expression.

 $$ k=\frac{1}{t}\ln\frac{\left[R\right]_{0}}{\left[R\right]} $$ 

Therefore

 $$ (D)\to(III) $$ 

Step 5: Write the correct matching.

 $$ (A)-\left(I V\right),\;(B)-\left(I I\right),\;(C)-\left(I\right),\;(D)-\left(I I I\right) $$ 

Quick Tip: Remember the standard first-order formula:

 $$ k=\frac{2.303}{t}\log\frac{[R]_{0}}{[R]} $$ 

It is one of the most frequently used equations in chemical kinetics.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.117Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5186, 5, NULL, NULL, 'IUPAC name of  $ [\mathrm{Co}(\mathrm{NH}_{3})_{4}(\mathrm{H}_{2}\mathrm{O})\mathrm{Cl}]Cl_{2} $', NULL, '[{"text":"Tetraammineaquachloridocobalt(II) chloride","image_url":null,"alt":null},{"text":"Tetraammineaquachloridocobalt(III) chloride","image_url":null,"alt":null},{"text":"Tetraammineaquachloridocobalt(I) chloride","image_url":null,"alt":null},{"text":"Tetraammineaquachloridocobalt(O) chloride","image_url":null,"alt":null}]', NULL, 1, 'Concept:

To determine the IUPAC name of a coordination compound, the oxidation state of the central metal ion must first be calculated.

Step 1: Determine charge on the complex ion.

There are two chloride ions outside the coordination sphere.

Hence,

 $$ [Co(NH_{3})_{4}(H_{2}O)Cl]^{2+} $$ 

Step 2: Calculate oxidation state of cobalt.

Let oxidation state be x.

 $$ x+0+0-1=+2 $$ 

 $$ x=+3 $$ 

Thus cobalt is in the +3 oxidation state.

Step 3: Name the ligands.

 $ NH_{3} \rightarrow $ ammine

 $ H_{2}O \rightarrow \text{aqua} $

Cl^{-} \rightarrow chlorido

Therefore ligand name becomes

tetraammineaquachlorido

Step 4: Write the complete name.

Tetraammineaquachloridocobalt(III) chloride

Quick Tip: Neutral ligands such as  $ NH_{3} $ and  $ H_{2}O $ contribute zero charge when calculating oxidation state of the central metal ion.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.118Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5187, 5, NULL, NULL, '75% of a first-order reaction was completed in 32 minutes. How long will it take to undergo 50% completion? Given:  $ \log 2 = 0.3010 $', NULL, '[{"text":"8 min","image_url":null,"alt":null},{"text":"12 min","image_url":null,"alt":null},{"text":"16 min","image_url":null,"alt":null},{"text":"24 min","image_url":null,"alt":null}]', NULL, 2, 'Concept:

For a first-order reaction,

 $$ t=\frac{2.303}{k}\log\frac{\left[R\right]_{0}}{\left[R\right]} $$ 

The half-life of a first-order reaction is constant and independent of concentration.

Step 1: Interpret 75% completion.

If 75% reaction is completed, then 25% reactant remains.

 $$ \frac{\left[R\right]}{\left[R\right]_{0}}=0.25 $$ 

 $$ \frac{[R]_{0}}{[R]}=4 $$ 

Step 2: Apply first-order equation.

 $$ 32=\frac{2.303}{k}\log4 $$ 

Since

 $$ \log4=2\log2 $$ 

 $$ =2(0.3010) $$ 

 $$ =0.6020 $$ 

Therefore

 $$ 32=\frac{2.303\times0.6020}{k} $$ 

 $$ 32=\frac{1.386}{k} $$ 

 $$ k=\frac{1.386}{32} $$ 

Step 3: Calculate half-life.

For first-order reaction,

 $$ t_{1/2}=\frac{0.693}{k} $$ 

Substituting  $ k = \frac{1.386}{32} $,

 $$ t_{1/2}=\frac{0.693\times32}{1.386} $$ 

 $$ =16\mathrm{~m i n} $$ 

Step 4: Final answer.

16 minutes

Quick Tip: For a first-order reaction, 75% completion corresponds to two half-lives because:

 $$ 100\%\rightarrow50\%\rightarrow25\% $$ 

Thus, if two half-lives take 32 min, one half-life takes 16 min.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.119Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5188, 5, NULL, NULL, 'Standard electrode potentials ( $ M^{n+}/M $) of four metals A, B, C and D are given below:

(A) -1.2 V

(B) +0.5 V

(C) +1.2 V

(D) -3.0 V

The correct increasing order for the reducing power of these metals will be:', NULL, '[{"text":"(D), (A), (C), (B)","image_url":null,"alt":null},{"text":"(D), (A), (B), (C)","image_url":null,"alt":null},{"text":"(C), (B), (A), (D)","image_url":null,"alt":null},{"text":"(B), (C), (A), (D)","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Reducing power of a metal depends upon its tendency to lose electrons.

A metal having a more negative standard reduction potential ( $ E^{\circ} $) is more readily oxidized and therefore acts as a stronger reducing agent.

Thus,

More negative  $ E^{\circ} \Rightarrow $ Greater reducing power

Step 1: Arrange the given electrode potentials.

 $$ C=+1.2V $$ 

 $$ B=+0.5V $$ 

 $$ A=-1.2V $$ 

 $$ D=-3.0V $$ 

Step 2: Relate electrode potential to reducing nature.

Metal C has the highest positive reduction potential, therefore it has the least tendency to lose electrons and hence the least reducing power.

Metal D has the most negative reduction potential and therefore the greatest tendency to lose electrons.

Hence reducing power increases in the order:

 $$ C<B<A<D $$ 

Step 3: Write the required increasing order.

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q23-exp-1.jpg" alt="Figure 1 for question 23" /></div>


Quick Tip: For metals, more negative standard reduction potential means stronger reducing agent because the metal is more easily oxidized.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.119Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5189, 5, NULL, NULL, 'Choose the optically inactive amino acid from the following:', NULL, '[{"text":"Glycine","image_url":null,"alt":null},{"text":"Alanine","image_url":null,"alt":null},{"text":"Leucine","image_url":null,"alt":null},{"text":"Isoleucine","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Optical activity arises due to the presence of a chiral carbon atom attached to four different groups.

Most naturally occurring amino acids contain one asymmetric carbon atom and are therefore optically active.

Step 1: Recall the general structure of amino acids.

 $$ R-CH(NH_{2})-COOH $$ 

If the carbon atom is attached to four different groups, the amino acid becomes optically active.

Step 2: Examine glycine.

For glycine,

 $$ \boldsymbol{R}=\boldsymbol{H} $$ 

Hence its structure is

 $$ H_{2}N-CH_{2}-COOH $$ 

The central carbon is attached to:

 $$ H,H,NH_{2},COOH $$ 

Since two substituents are identical hydrogen atoms, the carbon atom is not chiral.

Therefore glycine is optically inactive.

Step 3: Examine the remaining amino acids.

Alanine, leucine and isoleucine possess asymmetric carbon atoms and therefore are optically active.

Step 4: Final answer.

Glycine

Quick Tip: Glycine is the only common  $ \alpha $-amino acid that is optically inactive because its  $ \alpha $-carbon contains two identical hydrogen atoms.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5190, 5, NULL, NULL, 'Match Ion given in List I with their Magnetic Moment (Calculated) given in List II.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>List I</td><td style=''text-align: center; word-wrap: break-word;''>List II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>Ion</td><td style=''text-align: center; word-wrap: break-word;''>Magnetic moment (Calculated)</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A)  $ Sc^{3+} $</td><td style=''text-align: center; word-wrap: break-word;''>(I) 3.87</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B)  $ Ti^{3+} $</td><td style=''text-align: center; word-wrap: break-word;''>(II) 1.73</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C)  $ V^{2+} $</td><td style=''text-align: center; word-wrap: break-word;''>(III) 5.92</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D)  $ Mn^{2+} $</td><td style=''text-align: center; word-wrap: break-word;''>(IV) 0</td></tr></table>', NULL, '[{"text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)","image_url":null,"alt":null}]', NULL, 0, 'Concept:

The spin-only magnetic moment is given by

 $$ \mu=\sqrt{n(n+2)} $$ 

BM

where n is the number of unpaired electrons.

Step 1: Determine configuration of  $ Sc^{3+} $

 $$ Sc=[Ar]3d^{1}4s^{2} $$ 

 $$ Sc^{3+}=[Ar] $$ 

Number of unpaired electrons = 0

 $$ \mu=0 $$ 

Therefore

 $$ (A)\to(IV) $$ 

Step 2: Determine configuration of Ti $ ^{3+} $.

 $$ Ti^{3+}=[Ar]3d^{1} $$ 

n=1

 $$ \mu=\sqrt{1(1+2)}=\sqrt{3}=1.73 $$ 

Therefore

 $$ (B)\to(II) $$ 

Step 3: Determine configuration of  $ V^{2+} $.

 $$ V^{2+}=[A r]3d^{3} $$ 

n=3

 $$ \mu=\sqrt{3(5)}=\sqrt{15}=3.87 $$ 

Therefore

 $$ (C)\to(I) $$ 

Step 4: Determine configuration of Mn^{2+}.

 $$ Mn^{2+}=[Ar]3d^{5} $$ 

n=5

 $$ \mu=\sqrt{5(7)}=\sqrt{35}\approx5.92 $$ 

Thus

 $$ (D)\to(III) $$ 

Step 5: Final matching.

 $$ (A)-\left(I V\right),\;(B)-\left(I I\right),\;(C)-\left(I\right),\;(D)-\left(I I\right) $$ 

Quick Tip: Memorize the common spin-only magnetic moments:  $ d^1 = 1.73 $,  $ d^3 = 3.87 $,  $ d^5 = 5.92 $ BM.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5191, 5, NULL, NULL, 'What would be the product X in the following chemical reaction?

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q26-figure-1.jpg" alt="Figure 1 for question 26" />
</div>', NULL, '[{"text":"Salicylic acid","image_url":null,"alt":null},{"text":"Benzoquinone","image_url":null,"alt":null},{"text":"Salicylaldehyde","image_url":null,"alt":null},{"text":"4-Hydroxybenzoic acid","image_url":null,"alt":null}]', NULL, 2, 'Concept:

This question involves three consecutive reactions:

1. Diazotisation of aniline.

2. Hydrolysis of diazonium salt.

3. Reimer-Tiemann reaction of phenol.

Step 1: Diazotisation of aniline.

Aniline reacts with sodium nitrite and hydrochloric acid at 273 K to form benzene diazonium chloride.

 $$ C_{6}H_{5}NH_{2}\rightarrow C_{6}H_{5}N_{2}^{+}Cl^{-} $$ 

Step 2: Hydrolysis of diazonium salt.

On warming with water,

 $$ C_{6}H_{5}N_{2}^{+}Cl^{-}\rightarrow C_{6}H_{5}OH $$ 

Phenol is produced.

Step 3: Reimer-Tiemann reaction.

Phenol reacts with chloroform and aqueous sodium hydroxide.

The formyl group is introduced mainly at the ortho position.

 $$  C_{6}H_{5}OH\xrightarrow[NaOH]{CHCl_{3}}o-Hydroxybenzaldehyde $$ 

Step 4: Identify the product.

o-Hydroxybenzaldehyde is commonly called salicylaldehyde.

Salicylaldehyde

Quick Tip: Phenol +  $ CHCl_{3} $/NaOH gives salicylaldehyde through the Reimer-Tiemann reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.121Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q26-figure-1.jpg","alt":"Figure 1 for question 26","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5192, 5, NULL, NULL, 'What are the hydrolysis products of Maltose?', NULL, '[{"text":"$ \\alpha $-D-Glucose + $ \\beta $-D-Fructose","image_url":null,"alt":null},{"text":"$ \\alpha $-D-Glucose + $ \\beta $-D-Glucose","image_url":null,"alt":null},{"text":"$ \\alpha $-D-Glucose + $ \\alpha $-D-Glucose","image_url":null,"alt":null},{"text":"$ \\alpha $-D-Galactose + $ \\beta $-D-Glucose","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Maltose is a disaccharide formed by the condensation of two glucose units through an  $ \alpha(1 \rightarrow 4) $ glycosidic linkage.

Step 1: Recall the structure of maltose.

Maltose consists of two  $ \alpha $-D-glucose molecules.

These glucose units are connected through an  $ \alpha(1 \rightarrow 4) $ glycosidic bond.

Step 2: Hydrolysis of the glycosidic bond.

Upon hydrolysis, the glycosidic linkage breaks and the original monosaccharide units are regenerated.

 $$ Maltose+H_{2}O\rightarrow\alpha-D-Glucose+\alpha-D-Glucose $$ 

#### Step 3: Eliminate incorrect options.

Glucose + fructose is obtained from sucrose.

Galactose + glucose is obtained from lactose.

Therefore those options are incorrect.

Step 4: Final answer.

 $$ \mathrm{\alpha-D-Glucose}+\mathrm{\alpha-D-Glucose} $$ 

Quick Tip: Remember: Maltose = Glucose + Glucose, Lactose = Galactose + Glucose, Sucrose = Glucose + Fructose.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.122Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5193, 5, NULL, NULL, 'Select the correct assumptions in Crystal Field Theory (CFT) from the following:

(A) Ligands are treated as point charge or point dipole.

(B) The five d orbitals in an isolated gaseous metal atom are non-degenerate.

(C) Degeneracy of the  $ d $ orbitals is restored with the approach of ligand towards metal.

(D) Metal-ligand bond is ionic arising purely from electrostatic interactions.

Choose the correct answer from the options given below:', NULL, '[{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(A) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Crystal Field Theory (CFT) explains the properties of coordination compounds by considering the interaction between the central metal ion and surrounding ligands as purely electrostatic in nature.

According to this theory, ligands are regarded as point charges (for anions) or point dipoles

(for neutral molecules), and the metal-ligand bond is assumed to be ionic.

Step 1: Examine statement (A).

In Crystal Field Theory, negatively charged ligands are treated as point charges and neutral ligands are treated as point dipoles.

Therefore statement (A) is correct.

Statement (A) is correct

Step 2: Examine statement (B).

For an isolated gaseous metal atom or ion, all five d-orbitals possess the same energy. Thus they are degenerate.

Statement (B) says that they are non-degenerate, which is incorrect.

Statement (B) is incorrect

Step 3: Examine statement (C).

When ligands approach the metal ion, the degeneracy of the d-orbitals is removed and splitting occurs.

Therefore degeneracy is not restored; rather it is destroyed.

Hence statement (C) is incorrect.

Statement (C) is incorrect

Step 4: Examine statement (D).

Crystal Field Theory assumes that metal-ligand bonding arises purely from electrostatic attraction.

Therefore statement (D) is correct.

Statement (D) is correct

Step 5: Select the correct combination.

The correct assumptions are:

(A) and (D)

Hence the correct answer is:

(A) and (D) only

Quick Tip: Crystal Field Theory considers metal-ligand bonding as purely electrostatic and ignores covalent character. Ligand approach causes splitting of degenerate d-orbitals.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.122Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5194, 5, NULL, NULL, 'Choose the symbol of a lanthanoid metal which is well known to exhibit +4 oxidation state.', NULL, '[{"text":"La","image_url":null,"alt":null},{"text":"Th","image_url":null,"alt":null},{"text":"Ce","image_url":null,"alt":null},{"text":"Cm","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Lanthanoids generally exhibit the +3 oxidation state. However, a few lanthanoids can also show other oxidation states because of the extra stability associated with empty, half-filled, or completely filled 4f-subshells.

Step 1: Recall the common oxidation state of lanthanoids.

The most common oxidation state of lanthanoids is:

This corresponds to the removal of two 6s electrons and one 5d or 4f electron.

Step 2: Identify lanthanoids showing +4 state.

Cerium exhibits the oxidation state:

 $$ Ce^{4+} $$ 

because removal of one additional electron gives the stable configuration:

[Xe]

which corresponds to an empty 4f-subshell.

Step 3: Examine the options.

- La generally exhibits only +3 state.

• Th is an actinoid, not a lanthanoid.

• Ce is a lanthanoid well known for its +4 oxidation state.

• Cm is also an actinoid.

Step 4: Final answer.

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q29-exp-1.jpg" alt="Figure 1 for question 29" /></div>


Quick Tip: Among lanthanoids, Cerium commonly shows +4 oxidation state while Europium often shows +2 oxidation state due to extra electronic stability.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.122Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5195, 5, NULL, NULL, 'Which of the following compounds does not undergo Cannizzaro reaction?', NULL, '[{"text":"Formaldehyde","image_url":null,"alt":null},{"text":"2,2-Dimethylbutanal","image_url":null,"alt":null},{"text":"Benzaldehyde","image_url":null,"alt":null},{"text":"Acetaldehyde","image_url":null,"alt":null}]', NULL, 3, '#### Concept:

Cannizzaro reaction is shown by aldehydes that do not contain any  $ \alpha $-hydrogen atom.

Such aldehydes undergo self oxidation-reduction in the presence of concentrated alkali.

 $$ \mathrm{2RCHO +OH^{-}} \rightarrow RCOO^{-} + RCH_{2}OH $$ 

Step 1: Check formaldehyde.

Formaldehyde contains no  $ \alpha $-carbon and therefore no  $ \alpha $-hydrogen.

Hence it undergoes Cannizzaro reaction.

### Undergoes Cannizzaro reaction

Step 2: Check 2.2-dimethylbutanal.

The carbon adjacent to the aldehyde group is fully substituted and contains no hydrogen atom. Therefore no  $ \alpha $-hydrogen is present.

Hence it undergoes Cannizzaro reaction.

### Undergoes Cannizzaro reaction

Step 3: Check benzaldehyde.

The carbon adjacent to the aldehyde group is part of the benzene ring and does not contain an  $ \alpha $-hydrogen.

Thus benzaldehyde undergoes Cannizzaro reaction.

Undergoes Cannizzaro reaction

Step 4: Check acetaldehyde.

Acetaldehyde possesses  $ \alpha $-hydrogen atoms.

 $$ CH_{3}CHO $$ 

Therefore it undergoes aldol condensation rather than Cannizzaro reaction.

Does not undergo Cannizzaro reaction

Step 5: Final answer.

Acetaldehyde

Quick Tip: Aldehydes having at least one  $ \alpha $-hydrogen generally undergo aldol condensation, whereas aldehydes lacking  $ \alpha $-hydrogen undergo Cannizzaro reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.123Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5196, 5, NULL, NULL, 'What would be the major product A?

<div style="text-align: center;">
<img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q31-reaction.jpg" alt="Reaction diagram for question 31" />
</div>', NULL, '[{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q31-option-a.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q31-figure-2.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q31-figure-3.jpg","alt":null},{"text":"","image_url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q31-figure-4.jpg","alt":null}]', NULL, 3, 'Concept:

The reaction of an aromatic compound with an acyl chloride in the presence of anhydrous  $ AlCl_{3} $ is known as Friedel-Crafts acylation.

Halogens are deactivating but ortho-para directing substituents.

Step 1: Generate the electrophile.

Acetyl chloride reacts with  $ AlCl_{3} $ to form the acylium ion.

 $$ CH_{3}COCl+AlCl_{3}\rightarrow CH_{3}CO^{+}+AlCl_{4}^{-} $$ 

This acylium ion acts as the electrophile.

Step 2: Consider directing effect of chlorine.

The chlorine atom attached to benzene exhibits a -I effect but also donates electron density through resonance.

Therefore chlorine directs incoming electrophiles mainly to the ortho and para positions.

Step 3: Compare ortho and para products.

Although both ortho and para products are formed, the para product experiences less steric hindrance.

Consequently the para isomer predominates.

Para product is major

Step 4: Identify the product.

The acetyl group enters the para position with respect to chlorine.

4-Chloroacetophenone

Hence the major product is:

Quick Tip: Halogens are deactivating but ortho-para directing. In electrophilic substitution reactions, para products are often major because of lower steric hindrance.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.123Z', NULL, NULL, '[{"url":"/local-papers/assets/chemistry-2026-06-06-shift-1/q31-reaction.jpg","alt":"Reaction diagram for question 31","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5197, 5, NULL, NULL, 'Which of the following statements are incorrect for the thermodynamic properties?

(A) Both  $ E_{cell} $ and  $ \Delta_{r}G $ of reaction are extensive properties.

(B) Both  $ E_{cell} $ and  $ \Delta_{r}G $ of reaction are intensive properties.

(C)  $ E_{cell} $ is an intensive property while  $ \Delta_{r}G $ of reaction is an extensive property.

(D)  $ E_{\text{cell}} $ is an extensive property while  $ \Delta_r G $ of reaction is an intensive property.

Choose the answer from the options given below:', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null},{"text":"(A), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Thermodynamic properties are classified as intensive and extensive properties.

- Intensive properties do not depend upon the amount of substance.

• Extensive properties depend upon the amount of substance.

Step 1: Classify  $ E_{cell} $.

Cell potential remains unchanged when the cell reaction is multiplied by any factor. Therefore,

 $ E_{cell} $

is an intensive property.

 $ E_{cell} $ is intensive

Step 2: Classify  $ \Delta_{r}G $.

Gibbs free energy change depends upon the amount of reactants and products involved. When a reaction is multiplied by a factor n,

 $$ \Delta_{r}G $$ 

also becomes $n$ times larger.

Hence it is an extensive property.

 $ \Delta_{r}G $ is extensive

Step 3: Check each statement.

Statement (A):

Both extensive  $ \Rightarrow $ Incorrect.

Statement (B):

Both intensive  $ \Rightarrow $ Incorrect.

Statement (C):

 $ E_{\text{cell}} $ intensive and  $ \Delta_r G $ extensive  $ \Rightarrow $ Correct.

Statement (D):

 $$ E_{cell} $$ 

 $$ \Delta_{r}G $$ 

Step 4: Identify incorrect statements.

Incorrect statements are:

Hence the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q32-exp-1.jpg" alt="Figure 1 for question 32" /></div>


Quick Tip: Remember:

 $$ \Delta G=-nFE_{cell} $$ 

Here  $ E_{cell} $ is intensive, whereas  $ \Delta G $ depends on the number of moles and is therefore extensive.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.124Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5198, 5, NULL, NULL, 'What would be the geometrical shape of  $ [\mathrm{NiCl}_4]^{2-} $ and  $ [\mathrm{PtCl}_4]^{2-} $ compounds?', NULL, '[{"text":"Both $ [\\mathrm{NiCl}_{4}]^{2-} $ and $ [\\mathrm{PtCl}_{4}]^{2-} $ are square planar.","image_url":null,"alt":null},{"text":"Both $ [\\mathrm{NiCl}_{4}]^{2-} $ and $ [\\mathrm{PtCl}_{4}]^{2-} $ are tetrahedral.","image_url":null,"alt":null},{"text":"$ [\\mathrm{NiCl}_{4}]^{2-} $ is square planar while $ [\\mathrm{PtCl}_{4}]^{2-} $ is tetrahedral.","image_url":null,"alt":null},{"text":"$ [\\mathrm{NiCl}_{4}]^{2-} $ is tetrahedral while $ [\\mathrm{PtCl}_{4}]^{2-} $ is square planar.","image_url":null,"alt":null}]', NULL, 3, 'Concept:

The geometry of coordination compounds depends upon the electronic configuration of the central metal ion, the strength of ligands and the crystal field splitting produced in the complex. For  $ d^{8} $ metal ions, 3d-series metals generally form tetrahedral complexes with weak ligands, whereas 5d-series metals generally form square planar complexes because of larger crystal field splitting.

Step 1: Determine the oxidation state and electronic configuration of nickel.

For  $ \left[\mathrm{NiCl}_{4}\right]^{2-} $,

 $$ x+4(-1)=-2 $$ 

 $$ x=+2 $$ 

Therefore,

 $$ Ni^{2+}=[Ar]3d^{8} $$ 

Since  $ Cl^{-} $ is a weak field ligand, pairing of electrons does not occur.

The complex uses outer orbitals and forms a tetrahedral geometry.

[NiCl_{4}]^{2-} is tetrahedral

Step 2: Determine the oxidation state and electronic configuration of platinum.

For  $ [\mathrm{PtCl}_{4}]^{2-} $,

 $$ Pt^{2+}=5d^{8} $$ 

In 5d-series metals, crystal field splitting is much larger.

As a result, electron pairing occurs and the complex adopts  $ dsp^{2} $ hybridisation.

Hence the geometry becomes square planar.

[PtCl_{4}]^{2-} is square planar

Step 3: Select the correct option.

 $$ [{\mathrm{N i C l}_{4}}]^{2-}\to\mathrm{T e t r a h e d r a l} $$ 

 $$ [{\mathrm{P t C l}}_{4}]^{2-}\to{\mathrm{S q u a r e~p l a n a r}} $$ 

Therefore,

Quick Tip: For  $ d^8 $ systems:  $ Ni^{2+} $ with weak ligands usually forms tetrahedral complexes, whereas  $ Pd^{2+} $ and  $ Pt^{2+} $ commonly form square planar complexes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.124Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5199, 5, NULL, NULL, 'The major products A and B formed in the following reaction are:

 $$ \begin{array}{ccc}B&\xrightarrow{\mathrm{AgCN}}&\mathrm{H}_{3}\mathrm{C}\text{——}\mathrm{CH}_{2}\text{——}\mathrm{Br}\quad\xrightarrow{\mathrm{KCN}}\text{→}\\\end{array} $$', NULL, '[{"text":"$A = \\mathrm{CH_3CH_2CN},\\ B = \\mathrm{CH_3CH_2NC}$","image_url":null,"alt":null},{"text":"$A = \\mathrm{CH_3CH_2CN},\\ B = \\mathrm{CH_3CH_2CN}$","image_url":null,"alt":null},{"text":"$A = \\mathrm{CH_3CH_2NC},\\ B = \\mathrm{CH_3CH_2NC}$","image_url":null,"alt":null},{"text":"$A = \\mathrm{CH_3CH_2NC},\\ B = \\mathrm{CH_3CH_2CN}$","image_url":null,"alt":null}]', NULL, 0, 'Concept:

The cyanide ion is an ambient nucleophile because it can attack through either carbon or nitrogen atom.

The nature of the reagent determines which atom participates in bond formation.

Step 1: Reaction with KCN.

KCN is predominantly ionic.

 $$ KCN \to K^{+} + CN^{-} $$ 

The carbon end of cyanide carries greater electron density and attacks the alkyl halide. Hence nitrile is formed.

 $$ CH_{3}CH_{2}Br+KCN\rightarrow CH_{3}CH_{2}CN $$ 

Thus,

 $$ \left|A=CH_{3}CH_{2}CN\right. $$ 

Step 2: Reaction with AgCN.

AgCN is largely covalent.

The carbon atom remains coordinated to silver and the nucleophilic attack occurs mainly through nitrogen.

Therefore isocyanide is formed.

 $$ CH_{3}CH_{2}Br+AgCN\rightarrow CH_{3}CH_{2}NC $$ 

Thus,

 $$ \boxed{B=C H_{3}C H_{2}N C} $$ 

Step 3: Write the final products.

 $$ A=CH_{3}CH_{2}CN $$ 

 $$ \boldsymbol{B}=\boldsymbol{C}\boldsymbol{H}_{3}\boldsymbol{C}\boldsymbol{H}_{2}\boldsymbol{N}\boldsymbol{C} $$ 

Hence,

Option (A)

Quick Tip: KCN gives nitriles (−CN) whereas AgCN gives isocyanides (−NC). This is one of the most frequently asked reactions in haloalkanes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.125Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5200, 5, NULL, NULL, 'Choose the transition element which exhibits least number of variable oxidation states.', NULL, '[{"text":"Sc","image_url":null,"alt":null},{"text":"Cr","image_url":null,"alt":null},{"text":"Mn","image_url":null,"alt":null},{"text":"Fe","image_url":null,"alt":null}]', NULL, 0, '##### Concept:

Variable oxidation states arise due to the small energy difference between  $ (n-1)d $ and ns orbitals in transition elements.

The greater the number of available electrons, the larger the number of oxidation states possible.

Step 1: Consider scandium.

Electronic configuration:

 $$ Sc=[Ar]3d^{1}4s^{2} $$ 

The most stable oxidation state is

+3

Scandium rarely exhibits other oxidation states.

Therefore it has the least variability.

Step 2: Consider chromium.

Chromium exhibits

 $$ +2,+3,+6 $$ 

and several intermediate oxidation states.

Step 3: Consider manganese.

Manganese shows the largest range of oxidation states.

 $$ +2\mathrm{~t o~}+7 $$ 

Step 4: Consider iron.

Iron commonly exhibits

 $$ +2,+3 $$ 

and a few additional oxidation states.

Step 5: Select the element showing minimum variability.

Among all the given elements, scandium exhibits the least number of oxidation states.

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q35-exp-1.jpg" alt="Figure 1 for question 35" /></div>


Quick Tip: Scandium predominantly shows only +3 oxidation state, whereas manganese exhibits the maximum number of oxidation states in the first transition series.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.126Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5201, 5, NULL, NULL, 'The standard Gibbs energy for the reaction is  $ -212.27 \, \text{kJ mol}^{-1} $.

 $$ Zn(s)+Cu^{2+}(aq.)\rightarrow Zn^{2+}(aq.)+Cu(s) $$ 

The standard electrode potential ( $ E_{cell}^{\circ} $) for the Daniell cell is:', NULL, '[{"text":"1.1 V","image_url":null,"alt":null},{"text":"2.2 V","image_url":null,"alt":null},{"text":"0.002 V","image_url":null,"alt":null},{"text":"0.001 V","image_url":null,"alt":null}]', NULL, 0, 'Concept:

The relationship between Gibbs free energy change and cell potential is

 $$ \Delta G^{\circ}=-n F E_{\mathrm{c e l l}}^{\circ} $$ 

where

n = number of electrons transferred

 $$ F=96500\mathrm{~C m o l}^{-1} $$ 

Step 1: Determine the number of electrons transferred.

The reaction is

 $$ Zn \to Zn^{2+} + 2e^{-} $$ 

 $$ Cu^{2+}+2e^{-}\rightarrow Cu $$ 

Hence,

 $$ n=2 $$ 

Step 2: Substitute the values in the equation.

 $$ \Delta G^\circ=-212.27\times10^{3}\mathrm{~J~m o l}^{-1} $$ 

Using

 $$ \Delta G^{\circ}=-n F E_{\mathrm{c e l l}}^{\circ} $$ 

 $$ 212.27\times10^{3}=2\times96500\times E_{\mathrm{c e l l}}^{\circ} $$ 

 $$ E^{\circ}_{\mathrm{cell}}=\frac{212270}{193000} $$ 

 $$ E_{\mathrm{c e l l}}^{\circ}\approx1.10\mathrm{V} $$ 

Step 3: Final answer.

 $$ E_{\mathrm{c e l l}}^{\circ}=1.1\mathrm{V} $$ 

Quick Tip: Use the relation

 $$ \Delta G^{\circ}=-n F E_{\mathrm{c e l l}}^{\circ} $$ 

A negative  $ \Delta G^{\circ} $ corresponds to a positive cell potential and a spontaneous reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.128Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5202, 5, NULL, NULL, 'Choose the correct statements:

(A) For a gaseous reaction if the concentration of gas is expressed in terms of their partial pressure

atm and time in minutes then unit of rate are atm min $ ^{-1} $.

(B) The sum of power of the concentration of the reactants in the rate law expression is called order of that reaction.

(C) The thermal decomposition of HI on gold surface is an example of second order reaction.

(D) The overall rate of the reaction is controlled by the slowest step in a reaction called the rate determining step.

Choose the correct answer from the options given below:', NULL, '[{"text":"(A) and (B) only","image_url":null,"alt":null},{"text":"(B) and (C) only","image_url":null,"alt":null},{"text":"(C) and (D) only","image_url":null,"alt":null},{"text":"(B) and (D) only","image_url":null,"alt":null}]', NULL, 3, 'Concept:

To identify the correct statements, each statement must be examined individually using the definitions of reaction rate, order of reaction and reaction mechanism.

Step 1: Examine statement (A).

Rate is defined as change in concentration (or pressure) per unit time.

If pressure is expressed in atm and time in minutes,

 $$  Rate unit=\frac{atm}{min}=atm\ min^{-1} $$ 

However, rate is generally expressed as magnitude and this statement is not accepted in NCERT-based interpretation for reaction rate units involving concentration terms. Hence statement (A) is not taken as correct in this question.

Statement (A) is incorrect

Step 2: Examine statement (B).

Order of a reaction is defined as the sum of the powers of concentration terms appearing in the experimentally determined rate law.

Therefore statement (B) is correct.

Statement (B) is correct

Step 3: Examine statement (C).

Thermal decomposition of HI on a gold surface is a surface-catalysed reaction and follows zero-order kinetics under suitable conditions.

Therefore it is not a second-order reaction.

Statement (C) is incorrect

Step 4: Examine statement (D).

In a multistep reaction mechanism, the slowest elementary step determines the overall reaction rate.

This step is called the rate determining step.

Hence statement (D) is correct.

Statement (D) is correct

Step 5: Select the correct combination.

Correct statements are

(B) and (D)

Hence the correct answer is

Option (D)

Quick Tip: Order of reaction is obtained from the experimentally determined rate law, whereas the slowest step in a reaction mechanism is called the rate determining step.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.129Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5203, 5, NULL, NULL, 'Match Reaction with Reagent Required:




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>List-I</td><td style=''text-align: center; word-wrap: break-word;''>List-II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>Reaction</td><td style=''text-align: center; word-wrap: break-word;''>Reagent Required</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A) Glucose to n-Hexane</td><td style=''text-align: center; word-wrap: break-word;''>(I)  $ \mathrm{NH}_{2}\mathrm{OH} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B) Glucose to Oxime</td><td style=''text-align: center; word-wrap: break-word;''>(II)  $ \mathrm{HNO}_{3} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C) Glucose to Gluconic Acid</td><td style=''text-align: center; word-wrap: break-word;''>(III)  $ \mathrm{HI}, \Delta $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D) Glucose to Saccharic Acid</td><td style=''text-align: center; word-wrap: break-word;''>(IV)  $ \mathrm{Br}_{2}, \mathrm{H}_{2}\mathrm{O} $</td></tr></table>


#### Choose the correct answer from the options given below:', NULL, '[{"text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Glucose undergoes several characteristic reactions involving oxidation, reduction and nucleophilic addition. The reagents used for these conversions are important reactions of carbohydrates.

Step 1: Match Glucose to n-Hexane.

When glucose is heated with excess hydroiodic acid in the presence of red phosphorus, complete

reduction takes place and all oxygen atoms are removed.

 $$ \mathrm{Glucose}\xrightarrow[\Delta]{HI}n\mathrm{-Hexane} $$ 

Thus,

 $$ (A)\to(III) $$ 

Step 2: Match Glucose to Oxime.

The aldehyde group of glucose reacts with hydroxylamine to form glucose oxime.

 $$ \mathrm{Glucose}+NH_{2}OH\rightarrow\mathrm{Glucose~Oxime} $$ 

Therefore,

 $$ (B)\to(I) $$ 

Step 3: Match Glucose to Gluconic Acid.

Bromine water is a mild oxidizing agent and oxidizes only the aldehyde group to carboxylic acid.

 $$  Glucose\xrightarrow{Br_{2}/H_{2}O}Gluconic~Acid $$ 

Hence,

 $$ (C)\to(IV) $$ 

Step 4: Match Glucose to Saccharic Acid.

Nitric acid is a strong oxidizing agent.

It oxidizes both the aldehyde group and terminal alcohol group into carboxylic acids.

 $$  Glucose\xrightarrow{HNO_{3}}Saccharic~Acid $$ 

Thus,

 $$ (D)\to(I I) $$ 

Step 5: Write the final matching.

 $$ (A)-\left(III\right),\ (B)-\left(I\right),\ (C)-\left(IV\right),\ (D)-\left(II\right) $$ 

Hence the correct option is

Option (A)

Quick Tip: Remember:  $ Br_{2}/H_{2}O $ gives gluconic acid,  $ HNO_{3} $ gives saccharic acid,  $ NH_{2}OH $ gives oxime and excess HI converts glucose into n-hexane.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.129Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5204, 5, NULL, NULL, 'What would be the major product when propene reacts with water in presence of acid catalyst?', NULL, '[{"text":"$ CH_{3}CH(OH)CH_{3} $ (Propan-2-ol)","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}OH $ (Propan-1-ol)","image_url":null,"alt":null},{"text":"$ CH_{3}C(OH)_{2}CH_{3} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}COOH $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Addition of water to an alkene in the presence of an acid catalyst is called acid-catalysed hydration.

The reaction follows Markovnikov''s rule.

According to Markovnikov''s rule, the hydrogen atom adds to the carbon already carrying more hydrogen atoms, while the hydroxyl group attaches to the more substituted carbon atom.

Step 1: Write the structure of propene.

 $$ CH_{3}-CH=CH_{2} $$ 

Step 2: Apply Markovnikov addition.

During protonation, the more stable secondary carbocation is formed.

 $$ CH_{3}-CH=CH_{2}\rightarrow CH_{3}-CH^{+}-CH_{3} $$ 

The hydroxyl group subsequently attacks this carbocation.

Step 3: Formation of alcohol.

 $$ CH_{3}-CH^{+}-CH_{3}\xrightarrow{H_{2}O}CH_{3}-CH(OH)-CH_{3} $$ 

The product formed is propan-2-ol.

Step 4: Final answer.

 $$ CH_{3}CH(OH)CH_{3} $$ 

Quick Tip: Hydration of alkenes in acidic medium follows Markovnikov addition and generally produces the more substituted alcohol.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.130Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5205, 5, NULL, NULL, 'Match Structure with their Common Name:




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>List I</td><td style=''text-align: center; word-wrap: break-word;''>List-II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>Structure</td><td style=''text-align: center; word-wrap: break-word;''>Common Name</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A) <img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q40-figure-1.jpg" alt="Figure 1 for question 40" /></td><td style=''text-align: center; word-wrap: break-word;''>(I) Allyl chloride</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B) <img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q40-figure-2.jpg" alt="Figure 2 for question 40" /></td><td style=''text-align: center; word-wrap: break-word;''>(II) Ethylene dichloride</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''><img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q40-figure-3.jpg" alt="Figure 3 for question 40" /></td><td style=''text-align: center; word-wrap: break-word;''>(III) Vinyl chloride</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D) <img src="/local-papers/assets/chemistry-2026-06-06-shift-1/q40-figure-4.jpg" alt="Figure 4 for question 40" /></td><td style=''text-align: center; word-wrap: break-word;''>(IV) Ethylidene chloride</td></tr></table>


Choose the correct answer from the options given below:', NULL, '[{"text":"(A)-(I), (B)-(IV), (C)-(II), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(IV), (C)-(II), (D)-(I)","image_url":null,"alt":null},{"text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Several halo compounds are widely known by their common names. Matching the structure with the traditional name is important.

Step 1: Identify compound (A).

 $$ H_{2}C=CHCH_{2}Cl $$ 

contains an allyl group attached to chlorine.

Therefore,

 $$ (A)\to(I) $$ 

Allyl chloride

Step 2: Identify compound (B).

 $$ CH_{3}CHCl_{2} $$ 

contains two chlorine atoms attached to the same carbon atom.

This is called ethylidene chloride.

 $$ (B)\to(IV) $$ 

Step 3: Identify compound (C).

 $$ ClCH_{2}CH_{2}Cl $$ 

is 1,2-dichloroethane.

Its common name is ethylene dichloride.

 $$ (C)\to(I I) $$ 

Step 4: Identify compound (D).

 $$ H_{2}C=CHCl $$ 

is chloroethene.

Its common name is vinyl chloride.

 $$ (D)\to(III) $$ 

Step 5: Write final matching.

 $$ (A)-(I),(B)-(IV),(C)-(II),(D)-(III) $$ 

Hence,

Option (A)

Quick Tip: Vinyl chloride =  $ CH_2 = CHCl $, Allyl chloride =  $ CH_2 = CHCH_2Cl $, Ethylene dichloride =  $ ClCH_2CH_2Cl $, Ethylidene chloride =  $ CH_3CHCl_2 $.

##### Passage for Questions 41–45

Read the given passage and answer the questions that follow:

##### Concept of Solution

There are several ways by which concentration of solution is quantitatively described: molality, molarity, mole fraction, ppm, mass % etc. Liquid-liquid solutions can be classified as ideal and non-ideal solutions on the basis of Raoult''s law. Suppose the molecules of two components are represented by A and B respectively. In pure components, the intermolecular attractive interaction will be of types A–A and B–B, whereas in the binary solution, A–B type of interactions will also be present. If intermolecular attractive forces between the A–A and B–B are nearly equal to those between A–B, ideal solution is formed.

The properties of solution which depend on the number of solute particles irrespective of their nature relative to the total number of particles present in the solution are called colligative properties.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.131Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5206, 5, NULL, NULL, 'When blood cells are placed in 1% (w/v) NaCl aqueous solution:', NULL, '[{"text":"Cell will burst","image_url":null,"alt":null},{"text":"Cell will shrink","image_url":null,"alt":null},{"text":"Cell will swell","image_url":null,"alt":null},{"text":"Cell remains as such","image_url":null,"alt":null}]', NULL, 1, 'The behavior of blood cells when placed in a solution of varying concentration is governed by the principle of osmosis. Osmosis is the net movement of solvent molecules (in this case, water) through a selectively permeable membrane from a region of higher solvent concentration (lower solute concentration) to a region of lower solvent concentration (higher solute concentration). Blood cells have a semipermeable membrane.

The concentration of the solution is given as 1

1. Hypertonic Solution (1% NaCl): When blood cells are placed in a hypertonic solution, the concentration of solutes (NaCl) outside the cells is higher than inside the cells. Consequently, the concentration of water is lower outside the cells than inside. Water will move by osmosis from the region of higher water concentration (inside the cell) to

the region of lower water concentration (outside the cell) across the cell membrane. This loss of water causes the cell to shrink, a process known as crenation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.134Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5207, 5, NULL, NULL, 'The rate of the reaction,  $ 2\text{NO} + \text{Cl}_2 \rightarrow 2\text{NOCl} $ is given by the rate equation, rate = k[ $ \text{NO} $]^2[ $ \text{Cl}_2 $]. The value of the rate constant can be increased by', NULL, '[{"text":"increasing the concentration of NO.","image_url":null,"alt":null},{"text":"increasing the temperature.","image_url":null,"alt":null},{"text":"increasing the concentration of the $ Cl_{2} $.","image_url":null,"alt":null},{"text":"doing all of these.","image_url":null,"alt":null}]', NULL, 3, 'This question pertains to the reactivity of metals and their behavior in electrochemical reactions, specifically displacement reactions. The relative reactivity of metals can be determined by their standard electrode potentials. A metal''s standard reduction potential ( $ E^{\circ} $) indicates its tendency to gain electrons and be reduced.

The standard reduction potentials for zinc and copper are:

 $$ \bullet \quad \mathrm{Zn^{2+}(aq)+2e^{-}\rightarrow Zn(s),E^\circ=-0.76V} $$ 

 $$ \bullet \quad \mathrm{Cu^{2+}(aq)+2e^{-}\rightarrow Cu(s),E^{o}=+0.34V} $$ 

A more reactive metal has a lower (more negative) reduction potential, meaning it has a greater tendency to be oxidized (lose electrons). Conversely, a less reactive metal has a higher (more positive) reduction potential, meaning its ions have a greater tendency to be reduced. Let''s analyze the options:

(a) Copper is more reactive than zinc: This is incorrect. Zinc has a lower reduction potential (-0.76 V) than copper (+0.34 V), signifying that zinc is more reactive and readily oxidized.

(b) Reduction potential of copper is less than zinc: This statement is factually incorrect.

The reduction potential of copper (+0.34 V) is greater than that of zinc (-0.76 V).

(c) Oxidation potential of copper is higher than zinc: The oxidation potential is the negative of the reduction potential. For copper, it''s -0.34 V. For zinc, it''s +0.76 V. Thus, the oxidation potential of copper is lower than that of zinc. This statement is incorrect.

• (d) Reduction potential of copper is higher than zinc: This statement is correct (+0.34 V > -0.76 V).

The reason a copper sulphate solution cannot be stored in a zinc vessel is due to the electrochemical reactivity difference. Since zinc has a lower reduction potential (is more reactive), it will spontaneously displace copper ions from the copper sulphate solution. The reaction is:  $ \mathrm{Zn}(s) + \mathrm{Cu}^{2+}(aq) \rightarrow \mathrm{Zn}^{2+}(aq) + \mathrm{Cu}(s) $ This reaction consumes the zinc vessel and forms solid copper. The standard cell potential for this reaction is  $ E_{\mathrm{cell}} = E_{\mathrm{cathode}}^{\circ} - E_{\mathrm{anode}}^{\circ} = +0.34\,\mathrm{V} - (-0.76\,\mathrm{V}) = +1.10\,\mathrm{V} $. A positive cell potential confirms the spontaneity of the reaction.

Therefore, option (d) correctly states the electrochemical basis for why zinc is more reactive than copper and will react with copper sulphate solution.

Final Answer: d

Quick Tip: Key Exam Tip:

The reactivity of metals in displacement reactions is determined by their standard electrode potentials. A metal with a lower (more negative) reduction potential is more reactive and will displace metals with higher reduction potentials from their salt solutions.

## 3. The rate of the reaction,  $ 2\text{NO} + \text{Cl}_2 \rightarrow 2\text{NOCl} $ is given by the rate equation, rate = k[ $ \text{NO} $]^2[ $ \text{Cl}_2 $]. The value of the rate constant can be increased by

(a) increasing the concentration of NO.

(b) increasing the temperature.

(c) increasing the concentration of the  $ Cl_{2} $.

(d) doing all of these.

##### Correct Answer: (2) increasing the temperature.

Solution: The given rate equation for the reaction  $ 2\text{NO} + \text{Cl}_2 \rightarrow 2\text{NOCl} $ is: rate = k[ $ \text{NO} $]^{2}[ $ \text{Cl}_2 $]

This equation describes how the rate of the reaction is dependent on the concentrations of the

reactants NO and  $ \text{Cl}_2 $, and the rate constant, k. The rate constant (k) is a proportionality factor

that is specific to a particular reaction at a particular temperature.

Let''s analyze the effect of each option on the rate constant  $ (k) $:

1) Increasing the concentration of NO: The rate equation shows that the reaction rate is proportional to the square of the concentration of NO ([NO] $ ^{2} $). If the concentration of NO increases, the rate of the reaction will increase. However, the rate constant (k) is defined as the rate of reaction when all reactant concentrations are unity. Thus, ‘k’ is fundamentally independent of reactant concentrations at a constant temperature. Increasing [NO] increases the overall rate, but does not change the rate constant.

2) Increasing the temperature: The rate constant (k) is strongly dependent on temperature. This relationship is described by the Arrhenius equation:  $ k = A e^{-E_a / R T} $ where:

• k is the rate constant

• A is the pre-exponential factor (frequency of collisions)

 $ E_{a} $ is the activation energy (minimum energy required for a reaction to occur)

• R is the ideal gas constant

• T is the absolute temperature (in Kelvin)

From the Arrhenius equation, as temperature (T) increases, the term  $ e^{-E_{a}/RT} $ increases because the exponent becomes less negative. This leads to a higher value of the rate constant (k). Therefore, increasing the temperature directly increases the rate constant.

3) Increasing the concentration of  $ \mathrm{Cl}_{2} $: Similar to NO, the rate equation shows that the rate is directly proportional to the concentration of  $ \mathrm{Cl}_{2} $ ( $ [\mathrm{Cl}_{2}] $). Increasing  $ [\mathrm{Cl}_{2}] $ will increase the rate of the reaction. However, the rate constant (k) is independent of reactant concentrations at a constant temperature. Thus, increasing  $ [\mathrm{Cl}_{2}] $ increases the rate, but not the rate constant.

4) Doing all of these: Since only increasing the temperature affects the rate constant, this option is incorrect.

The question specifically asks what can increase the  $ * $value of the rate constant $ * $. Based on chemical kinetics principles, only temperature (and catalysts, which are not options here) affects the rate constant.

Final Answer: 2

Quick Tip: Key Exam Tip:

Remember the distinction between factors affecting the reaction rate and factors affecting the rate constant (k):

- Concentrations of Reactants: Affects the rate directly but does not change the rate constant (k).

• Temperature: Affects both the rate and the rate constant (k). An increase in temperature generally leads to a higher rate constant.

• Catalyst: Speeds up the reaction by increasing the rate constant (k) by lowering the activation energy  $ E_{a} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.134Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5208, 5, NULL, NULL, 'Identify the product C in the series.

 $$ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{NO}_{2}\xrightarrow{\mathrm{Fe}/\mathrm{HCl}}A\xrightarrow{\mathrm{NaNO}_{2}+\mathrm{HCl},273\mathrm{~K}}B\xrightarrow{\mathrm{H}_{2}\mathrm{O},283\mathrm{~K}}C $$', NULL, '[{"text":"$ C_{6}H_{5}OH $","image_url":null,"alt":null},{"text":"$ C_{6}H_{5}CH_{2}OH $","image_url":null,"alt":null},{"text":"$ C_{6}H_{5}CHO $","image_url":null,"alt":null},{"text":"$ C_{6}H_{5}NH_{2} $","image_url":null,"alt":null}]', NULL, 0, 'This is a classic sequence of reactions involving nitrobenzene and its transformation into phenol. Let''s break down the steps:

Step 1: Reduction of nitrobenzene to aniline  $  \text{C}_6\text{H}_5\text{NO}_2  $ (Nitrobenzene)  $ \xrightarrow{\text{Fe/HCl}} $ A Nitrobenzene is reduced to aniline (aminobenzene) in the presence of a reducing agent like Fe/HCl. Therefore, A is  $  \text{C}_6\text{H}_5\text{NH}_2  $ (Aniline).

Step 2: Diazotization of aniline A ( $ C_6H_5NH_2 $)  $ \xrightarrow{\text{NaNO}_2\text{HCl}, 275^\circ\text{K}} $ B Aniline reacts with sodium nitrite ( $ NaNO_2 $) and hydrochloric acid (HCl) at a low temperature (0-5 °C, which is 273 K) to form a diazonium salt. This process is called diazotization. Therefore, B is  $ C_6H_5N_2Cl^- $ (Benzenediazonium chloride).

Step 3: Hydrolysis of the diazonium salt B ( $ C_{6}H_{5}N_{2}^{+}Cl^{-} $)  $ \xrightarrow{H_{2}O, 283 K} $ C Benzenediazonium chloride reacts with water at a slightly elevated temperature (around 10-15 °C, which is 283 K) to undergo hydrolysis. The diazonium group ( $ -N_{2}^{+} $) is replaced by a hydroxyl group (-OH), forming phenol. Nitrogen gas ( $ N_{2} $) and HCl are released as byproducts. The reaction is:  $ C_{6}H_{5}N_{2}^{+}Cl^{-} + H_{2}O \xrightarrow{\Delta} C_{6}H_{5}OH + N_{2} + HCl $

Therefore, the product C is  $ C_{6}H_{5}OH $ (Phenol).

Let''s check the options: (1)  $ C_{6}H_{5}OH $ (Phenol) - This matches our product. (2)  $ C_{6}H_{5}CH_{2}OH $ (Benzyl alcohol) - Incorrect. (3)  $ C_{6}H_{5}CHO $ (Benzaldehyde) - Incorrect. (4)  $ C_{6}H_{5}NH_{2} $ (Aniline) - This is intermediate A, not final product C.

Final Answer: 1

Quick Tip: Key Exam Tip:

Remember the key transformations:

- Nitro group reduction to amine: e.g., R-NO₂  $ \xrightarrow{\text{Fe/HCl or Sn/HCl}} $ R-NH₂.

• Diazotization of primary aromatic amines: R-NH_{2}  $ \xrightarrow{\text{NaNO}_{2}+\text{HCl, low temp}} $ R-N_{2}^{+}Cl^{-}.

• Hydrolysis of diazonium salts:  $  \text{R} - \text{N}_2^+ X^- \xrightarrow{\text{H}_2\text{O}, \text{heat}} \text{R} - \text{OH} + \text{N}_2 + \text{HX}  $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.135Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5209, 5, NULL, NULL, 'Which of the following expression correctly represents molar conductivity?', NULL, '[{"text":"$$ \\Lambda_{m}=\\tfrac{K}{C} $$","image_url":null,"alt":null},{"text":"$ \\Lambda_{m} = \\frac{KA}{1} $","image_url":null,"alt":null},{"text":"$ \\Lambda_{m}=KV $","image_url":null,"alt":null},{"text":"all of these","image_url":null,"alt":null}]', NULL, 0, 'Molar conductivity ( $ \Lambda_{m} $) is a measure of the efficiency of ion conduction in a solution. It is defined as the conductivity of a solution divided by the molar concentration of the electrolyte.

The relationship between molar conductivity ( $ \Lambda_{m} $), specific conductivity (or conductivity, K), and molar concentration (C) is given by the formula:  $ \Lambda_{m} = \frac{K}{C} $

•  $ \Lambda_m $ is the molar conductivity (units: S m $ ^2 $ mol $ ^{-1} $ or S cm $ ^2 $ mol $ ^{-1} $).

- K (kappa) is the specific conductivity (or conductivity) of the solution (units: S m $ ^{-1} $ or S cm $ ^{-1} $).

- C is the molar concentration of the electrolyte (units: mol m $ ^{-3} $ or mol cm $ ^{-3} $, often mol L $ ^{-1} $).

Let''s examine the given options:

1.  $ \Lambda_m = \frac{K}{C} $: This is the correct definition of molar conductivity.

2. $\Lambda_{m}=\frac{KA}{1}$: This expression is dimensionally incorrect. ''A'' is not defined in this context, and the units would not match molar conductivity. If ''A'' were meant to be volume, it would be $\Lambda_{m}=\frac{K}{C}=\frac{K}{n/V}=\frac{KV}{n}$.

3. $\Lambda_{m} = KV$: This expression is also dimensionally incorrect and does not represent molar conductivity. If $V''$ represents the volume of solution containing one mole of electrolyte (i.e., $V = 1/C$), then $\Lambda_{m} = K \times \frac{1}{C} = \frac{K}{C}$, which brings us back to option 1. However, as stated, it''s incorrect.

4. all of these: Since options 2 and 3 are incorrect, this option is also incorrect.

Thus, the only correct expression for molar conductivity is  $ \Lambda_{m} = \frac{K}{C} $.

Final Answer: 1

Quick Tip: Key Exam Tip:

Molar conductivity ( $ \Lambda_{m} $) is the conductivity of one mole of electrolyte. It is calculated by dividing the specific conductivity (K) by the molar concentration (C). Ensure you use consistent units for K and C to obtain the correct units for  $ \Lambda_{m} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.135Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5210, 5, NULL, NULL, 'For the given Nernst equation

 $$ \begin{array}{r}{E_{\mathrm{c e l l}}=E_{\mathrm{c e l l}}^{\circ}-\frac{R T}{n F}\ln\left[\frac{[\mathrm{M g}^{2+}]}{[\mathrm{A g}^{+}]}\right]}\end{array} $$ 

Which of the following representation is correct?', NULL, '[{"text":"$ Ag^{+} $ | Ag | | $ Mg^{2+} $ | Mg","image_url":null,"alt":null},{"text":"$ Mg^{2+} $ |Mg||Ag| $ Ag^{+} $","image_url":null,"alt":null},{"text":"Mg $ \\left|Mg^{2+}\\right|\\left|Ag^{+}\\right|Ag $","image_url":null,"alt":null},{"text":"Mg $ \\left|Mg^{2+}\\right| $ $ \\left|Ag\\right|Ag^{+} $","image_url":null,"alt":null}]', NULL, 2, 'The Nernst equation relates the cell potential ( $ E_{cell} $) of an electrochemical cell to the standard cell potential ( $ E_{cell}^{\circ} $) and the concentrations of the ions involved. The general form of the Nernst equation for a redox reaction is:  $ E_{cell} = E_{cell}^{\circ} - \frac{RT}{nF} \ln Q $ where Q is the reaction quotient.

The given Nernst equation is:  $ E_{\text{cell}} = E_{\text{cell}}^\circ - \frac{RT}{nF} \ln\left[\frac{[\text{Mg}^{2+}]}{[\text{Ag}^+]}\right] $

In this equation, the term inside the logarithm,  $ \frac{[\mathrm{Mg}^{2+}]}{[\mathrm{Ag}^{+}]} $, represents the reaction quotient (Q). The reaction quotient is written as (products)/(reactants), considering the stoichiometric coefficients. The expression  $ \ln\left[\frac{[\mathrm{Mg}^{2+}]}{[\mathrm{Ag}^{+}]}\right] $ indicates that  $ \mathrm{Mg}^{2+} $ is in the numerator (likely a product of oxidation) and  $ \mathrm{Ag}^{+} $ is in the denominator (likely a reactant in reduction).

A cell representation in shorthand notation is written as: Anode | Anode Solution || Cathode Solution | Cathode

The anode is where oxidation occurs, and the cathode is where reduction occurs. The species in the cell notation are written in the form of: Reduced form | Oxidized form (for anode) and

Oxidized form | Reduced form (for cathode).

From the reaction quotient  $ \frac{[Mg^{2+}]}{[Ag^{+}]} $, we can infer the half-reactions:

• Anode (Oxidation): Mg  $ \rightarrow $ Mg $ ^{2+} $ + 2e $ ^{-} $ (Mg is oxidized to Mg $ ^{2+} $)

• Cathode (Reduction):  $ Ag^{+} + e^{-} \rightarrow Ag $ ( $ Ag^{+} $ is reduced to Ag)

Now let''s construct the cell notation:

• Anode half-cell: Reduced form is Mg, oxidized form is  $ Mg^{2+} $. So, it''s Mg  $ |Mg^{2+} $

Cathode half-cell: Oxidized form is  $ Ag^{+} $, reduced form is Ag. So, it''s  $ Ag^{+} $ | Ag.

Connecting these with the salt bridge (||): Anode || Cathode Mg | Mg²⁺ || Ag⁺ | Ag

Let’s check the given options: (a) Ag⁺ | Ag || Mg²⁺ | Mg: This represents Ag as anode and Mg as cathode, which is incorrect based on the reaction quotient. (b) Mg²⁺ | Mg || Ag | Ag⁺: This representation is incorrect in how it writes the half-cells. The reduced form should be on the left for the anode, and the oxidized form on the left for the cathode. (c) Mg | Mg²⁺ | | Ag⁺ | Ag: This representation correctly shows Mg as the anode (oxidation) and Ag as the cathode (reduction), with the correct species in their respective states. (d) Mg | Mg²⁺ | | Ag | Ag⁺: This representation is incorrect in how it writes the cathode half-cell.

Therefore, the correct representation of the cell is  $ \mathrm{Mg}|\mathrm{Mg}^{2+}||\mathrm{Ag}^{+}|\mathrm{Ag} $.

Final Answer: c

Quick Tip: Key Exam Tip:

In electrochemical cell notation:

• Anode (oxidation) is written first: Reduced form | Oxidized form.

• Cathode (reduction) is written second: Oxidized form | Reduced form.

• A single vertical line (|) separates phases (e.g., electrode and solution).

- A double vertical line (||) separates the anode and cathode compartments, representing the salt bridge.

The Nernst equation’s reaction quotient (Q) directly reveals which species are oxidized and reduced, and thus the anode and cathode half-cells.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.136Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5211, 5, NULL, NULL, 'The rate of the reaction,  $ 2NO + Cl_{2} \rightarrow 2NOCl $ is given by the rate equation, rate = k[NO] $ ^{2} $[Cl $ _{2} $]. The value of the rate constant can be increased by', NULL, '[{"text":"increasing the concentration of NO.","image_url":null,"alt":null},{"text":"increasing the temperature.","image_url":null,"alt":null},{"text":"increasing the concentration of the $ Cl_{2} $.","image_url":null,"alt":null},{"text":"doing all of these.","image_url":null,"alt":null}]', NULL, 1, 'The given rate equation for the reaction  $ 2\text{NO} + \text{Cl}_2 \rightarrow 2\text{NOCl} $ is: rate = k[ $ \text{NO} $]^{2}[ $ \text{Cl}_2 $]

This equation shows that the rate of the reaction depends on the rate constant (k) and the concentrations of the reactants NO and  $ \text{Cl}_2 $. The rate constant (k) is a proportionality constant specific to a reaction at a given temperature.

Let''s analyze how each factor affects the rate and specifically the rate constant:

1) Increasing the concentration of NO: According to the rate equation, the rate is directly proportional to  $ [NO]^{2} $. If  $ [NO] $ increases, the rate of the reaction will increase significantly. However, the rate constant  $ k'' $ is independent of reactant concentrations at a constant temperature.

ture. Increasing the concentration of NO will increase the rate of the reaction, but not the rate constant.

2) Increasing the temperature: The rate constant (k) is highly dependent on temperature. According to the Arrhenius equation,  $ k = A e^{-E_a / R T} $, where:

• k is the rate constant.

- A is the pre-exponential factor (frequency factor).

 $ E_{a} $ is the activation energy.

• R is the gas constant.

• T is the absolute temperature.

As temperature (T) increases, the term  $ e^{-E_{a}/RT} $ increases (because the exponent becomes less negative), leading to an increase in the rate constant (k). Therefore, increasing the temperature will increase the value of the rate constant.

3) Increasing the concentration of  $ \mathrm{Cl}_2 $: The rate equation shows that the rate is directly proportional to  $ [\mathrm{Cl}_2] $. If  $ [\mathrm{Cl}_2] $ increases, the rate of the reaction will increase. However, like concentration of NO, the rate constant ''k'' is independent of reactant concentrations at a constant temperature. Increasing the concentration of  $ \mathrm{Cl}_2 $ will increase the rate of the reaction, but not the rate constant.

4) Doing all of these: Since only increasing the temperature affects the rate constant, this option is incorrect.

The question specifically asks what can increase the  $ * $value of the rate constant $ * $. Among the given options, only increasing the temperature affects the rate constant.

Final Answer: 2

Quick Tip: Key Exam Tip:

Factors Affecting Reaction Rate vs. Rate Constant:

• Concentration of Reactants: Affects the rate of the reaction but not the rate constant (k).

• Temperature: Affects both the rate and the rate constant (k). Higher temperature generally leads to a higher rate constant.

• Catalyst: Affects the rate by lowering the activation energy, thus increasing the rate constant (k).

In this question, only temperature and a catalyst (not provided as an option) affects the rate constant.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.137Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5212, 5, NULL, NULL, 'Which of the following compounds shows geometrical isomerism?', NULL, '[{"text":"But-1-ene","image_url":null,"alt":null},{"text":"But-2-ene","image_url":null,"alt":null},{"text":"Propene","image_url":null,"alt":null},{"text":"Ethene","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:

Geometrical isomerism (cis-trans isomerism) occurs in alkenes when there is restricted rotation around a double bond and each carbon atom of the double bond is attached to two different groups.

### Step 2: Detailed Explanation:

Let''s examine the structure of But-2-ene  $ (CH_{3}-CH=CH-CH_{3}) $:

Each carbon in the C = C bond is attached to one Hydrogen  $ (-H) $ and one Methyl group  $ (-CH_{3}) $.

Because the two groups on each carbon are different, they can exist in two spatial arrangements: Cis (same groups on the same side) and Trans (same groups on opposite sides).

- In But-1-ene or Propene, one of the double-bonded carbons is attached to two identical Hydrogen atoms, so they cannot show this isomerism.

#### Step 3: Final Answer:

The compound that shows geometrical isomerism is But-2-ene.

Quick Tip: To quickly check for geometrical isomerism, look at the C = C bond. If either carbon has two identical atoms (like two H atoms), it cannot have cis-trans isomers.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.139Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5213, 5, NULL, NULL, 'The IUPAC name of  $ (CH_{3}-CH_{2}-CHO) $ is:', NULL, '[{"text":"Propanone","image_url":null,"alt":null},{"text":"Propanal","image_url":null,"alt":null},{"text":"Propanoic acid","image_url":null,"alt":null},{"text":"Ethanol","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:

IUPAC nomenclature follows a specific set of rules: identifying the longest carbon chain, the functional group, and the appropriate suffix.

#### Step 2: Detailed Explanation:

1. Count the Carbons: The chain  $ CH_3 - CH_2 - CHO $ has 3 carbon atoms. The prefix for 3 carbons is "prop-". 2. Identify the Bond: It is a saturated chain (single bonds between carbons), so it is "propan-". 3. Identify the Functional Group: The group -CHO is an aldehyde. 4. Determine the Suffix: The IUPAC suffix for aldehydes is "-al".

Step 3: Final Answer:

Combining these, we get Propanal. (Propanone is a ketone, Propanoic acid is a carboxylic acid).

Quick Tip: Don''t forget to count the carbon atom that is part of the functional group! In  $ CH_{3}CH_{2}CHO $, the C in CHO is the 1st carbon.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.140Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5214, 5, NULL, NULL, 'The oxidation state of chromium in  $ (K_{2}Cr_{2}O_{7}) $ is:', NULL, '[{"text":"+4","image_url":null,"alt":null},{"text":"+5","image_url":null,"alt":null},{"text":"+6","image_url":null,"alt":null},{"text":"+7","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Understanding the Concept:

The oxidation state is the hypothetical charge an atom would have if all bonds to atoms of different elements were 100% ionic. The sum of oxidation states in a neutral compound must be zero.

Step 2: Identifying Known Oxidation States:

In  $ K_{2}Cr_{2}O_{7} $:

• Potassium (K) is an alkali metal, so its state is +1.

• Oxygen (O) is usually -2.

- Let the oxidation state of Chromium  $ (Cr) $ be x.

Step 3: Calculation:

Set up the equation for the neutral molecule:

 $$ 2(+1)+2(x)+7(-2)=0 $$ 

 $$ 2+2x-14=0 $$ 

 $$ 2x-12=0 $$ 

 $$ 2x=12\implies x=+6 $$ 

#### Step 4: Final Answer:

The oxidation state of Chromium in Potassium Dichromate is +6.

Quick Tip: Chromium in the +6 state is a very strong oxidizing agent. This is why  $ K_{2}Cr_{2}O_{7} $ is commonly used in laboratories for titration and organic oxidation reactions.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.141Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5215, 5, NULL, NULL, 'Which of the following is a strong electrolyte?', NULL, '[{"text":"Glucose solution","image_url":null,"alt":null},{"text":"Urea solution","image_url":null,"alt":null},{"text":"Acetic acid","image_url":null,"alt":null},{"text":"Sodium chloride solution","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Concept:

An electrolyte is a substance that dissociates into ions when dissolved in water, allowing the solution to conduct electricity. A "strong" electrolyte is one that dissociates almost completely (100%) into ions.

Step 2: Detailed Explanation:

• Sodium chloride (NaCl): Is an ionic salt. In water, it breaks down completely into  $ Na^{+} $ and  $ Cl^{-} $ ions. Hence, it is a strong electrolyte.

• Acetic acid ( $ CH_{3}COOH $): Is a weak acid. It only partially ionizes in water, making it a weak electrolyte.

• Glucose and Urea: Are covalent molecular compounds. They dissolve in water but do not form ions; therefore, they are non-electrolytes.

Step 3: Final Answer:
Sodium chloride solution is the strong electrolyte.
Quick Tip: Strong acids (like HCl), strong bases (like NaOH), and most soluble salts are strong electrolytes. If it''s a "weak" acid or base, it''s a weak electrolyte!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.142Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5216, 5, NULL, NULL, 'The hybridization of carbon in ethyne  $  (C_{2}H_{2})  $ is:', NULL, '[{"text":"$ sp^{3} $","image_url":null,"alt":null},{"text":"$ sp^{2} $","image_url":null,"alt":null},{"text":"sp","image_url":null,"alt":null},{"text":"$ dsp^{2} $","image_url":null,"alt":null}]', NULL, 2, 'Hybridization explains the mixing of atomic orbitals to form new hybrid orbitals suitable for the pairing of electrons to form chemical bonds. The type of hybridization depends on the number of sigma ( $ \sigma $) bonds and lone pairs around the atom.

### Step 2: Detailed Explanation:

In ethyne  $  (H - C \equiv C - H)  $:

• Each carbon atom is bonded to one Hydrogen atom (one  $ \sigma $ bond) and one Carbon atom (one  $ \sigma $ bond and two  $ \pi $ bonds).

• Total number of  $ \sigma $ bonds per carbon = 2.

• There are no lone pairs on the carbon atoms.

- A total of 2 hybrid orbitals are needed, which corresponds to sp hybridization.

Step 3: Final Answer:

The hybridization of carbon in ethyne is sp.

Quick Tip: Single bond  $ (C-C) \rightarrow sp^{3} $

Double bond  $ (C=C) \rightarrow sp^{2} $

Triple bond  $ (C \equiv C) \rightarrow sp $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.145Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5217, 5, NULL, NULL, 'Which gas is evolved when zinc reacts with dilute hydrochloric acid?', NULL, '[{"text":"Oxygen","image_url":null,"alt":null},{"text":"Chlorine","image_url":null,"alt":null},{"text":"Hydrogen","image_url":null,"alt":null},{"text":"Nitrogen","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Understanding the Concept:

Metals that are more reactive than hydrogen (positioned above hydrogen in the reactivity series) react with dilute acids to displace hydrogen gas.

### Step 2: Detailed Explanation:

Zinc (Zn) is more reactive than hydrogen. When it reacts with hydrochloric acid (HCl), it forms zinc chloride and releases hydrogen gas. The chemical equation is:

 $$ Zn(s)+2HCl(aq)\rightarrow ZnCl_{2}(aq)+H_{2}(g)\uparrow $$ 

Step 3: Final Answer:

Hydrogen gas is evolved during the reaction.

Quick Tip: You can test for Hydrogen gas by bringing a burning splinter near the mouth of the test tube—it will burn with a characteristic "pop" sound!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.147Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5218, 5, NULL, NULL, 'Which quantum number determines the shape of an orbital?', NULL, '[{"text":"Principal quantum number","image_url":null,"alt":null},{"text":"Azimuthal quantum number","image_url":null,"alt":null},{"text":"Magnetic quantum number","image_url":null,"alt":null},{"text":"Spin quantum number","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:
Quantum numbers are a set of four numbers used to describe the location, energy, and behavior of electrons in an atom.
Step 2: Detailed Explanation:
Each quantum number has a specific role:
- Principal (n): Determines the size and energy of the orbital.
- Azimuthal (l): Also known as the orbital angular momentum quantum number, it determines the three-dimensional shape of the orbital (e.g., l = 0 is spherical s, l = 1 is dumbbell p).
- Magnetic ( $ m_{l} $): Determines the spatial orientation of the orbital.
- Spin ( $ m_{s} $): Determines the direction of electron spin.
Step 3: Final Answer:
The Azimuthal quantum number determines the shape of the orbital.
Quick Tip: Think of the quantum numbers as an address: n is the City (size), l is the Building Shape,  $ m_{l} $ is the Room Orientation, and  $ m_{s} $ is the Bed Choice!

Quick Tip: Think of the quantum numbers as an address: n is the City (size), l is the Building Shape,  $ m_{l} $ is the Room Orientation, and  $ m_{s} $ is the Bed Choice!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.148Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5219, 5, NULL, NULL, 'Which of the following polymers is formed by addition polymerization?', NULL, '[{"text":"Nylon-6,6","image_url":null,"alt":null},{"text":"Bakelite","image_url":null,"alt":null},{"text":"Terylene","image_url":null,"alt":null},{"text":"Polyethene","image_url":null,"alt":null}]', NULL, 3, '#### Step 1: Understanding the Concept:

Polymerization is the process of reacting monomer molecules together in a chemical reaction to form polymer chains.

• Addition Polymerization: Monomers join together without the loss of any small molecules. It typically involves unsaturated monomers (with double or triple bonds).

• Condensation Polymerization: Monomers join together with the elimination of small molecules like water or alcohol.

Step 2: Detailed Explanation:

Polyethene: Formed by the repeated addition of ethene  $ (CH_{2}=CH_{2}) $ molecules. No byproduct is formed.

Nylon-6,6, Bakelite, and Terylene: These are all formed by condensation reactions where molecules like water are released.

Step 3: Final Answer:

Polyethene is formed by addition polymerization.

Quick Tip: If the name of the polymer starts with "Poly-" and the monomer has a double bond (like Ethene, Styrene, or Vinyl Chloride), it is almost certainly an addition polymer!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.149Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5220, 5, NULL, NULL, 'The reagent used in the conversion of alcohol into aldehyde is:', NULL, '[{"text":"LiAlH_{4}","image_url":null,"alt":null},{"text":"PCC","image_url":null,"alt":null},{"text":"NaBH_{4}","image_url":null,"alt":null},{"text":"Grignard reagent","image_url":null,"alt":null}]', NULL, 1, '#### Step 1: Understanding the Concept:

To convert a primary alcohol into an aldehyde, we need an oxidizing agent. However, many strong oxidizing agents (like  $ KMnO_{4} $) will continue to oxidize the aldehyde into a carboxylic acid. Therefore, a "mild" or "selective" oxidizing agent is required.

#### Step 2: Detailed Explanation:

- PCC (Pyridinium Chlorochromate): This is a mild oxidizing agent. It selectively oxidizes primary alcohols to aldehydes and secondary alcohols to ketones without further oxidation to carboxylic acids.

-  $ LiAlH_{4} $ and  $ NaBH_{4} $: These are reducing agents, not oxidizing agents. They would do the opposite (convert an aldehyde back into an alcohol).

Grignard reagent: This is used for carbon-carbon bond formation, not for the simple oxidation of an alcohol to an aldehyde.

#### Step 3: Final Answer:

The reagent used is PCC.

Quick Tip: Think of PCC as a "controlled" stop. It stops the oxidation at the Aldehyde stage. Stronger reagents like Jones Reagent ( $ CrO_{3}/H_{2}SO_{4} $) are like an express train—they go all the way to the Carboxylic Acid!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.150Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5221, 5, NULL, NULL, 'The molar conductivity of 0.5 mol/dm³ solution of AgNO₃ with electrolytic conductivity of  $ 5.76 \times 10^{-3} $ S cm⁻¹ at 298 K is:', NULL, '[{"text":"0.086S cm $ ^{2} $/mol","image_url":null,"alt":null},{"text":"28.8S cm^{2}/mol","image_url":null,"alt":null},{"text":"2.88S cm^{2}/mol","image_url":null,"alt":null},{"text":"11.52S cm $ ^{2} $/mol","image_url":null,"alt":null}]', NULL, 3, 'Concept: Molar conductivity ( $ \Lambda_{m} $) is defined as the conductance of all ions produced by one mole of an electrolyte dissolved in a given volume of solution.

The relation between molar conductivity and conductivity is:

 $$ \Lambda_{m}=\frac{\kappa\times1000}{C} $$ 

where:

•  $ \Lambda_{m} = \text{molar conductivity (S cm}^{2}/\text{mol)} $

 $ \kappa = \text{conductivity} (S \, \text{cm}^{-1}) $

 $ C = \text{concentration in } (\text{mol L}^{-1}) $

Step 1: Write the given data

Given:

 $$ \kappa=5.76\times10^{-3}S cm^{-1} $$ 

 $$ C=0.5\mathrm{m o l}\mathrm{d m}^{-3} $$ 

Since:

 $$ 1\,\mathrm{d m}^{3}=1\mathrm{L} $$ 

therefore:

 $$ C=0.5mol L^{-1} $$ 

Step 2: Apply the molar conductivity formula

 $$ \Lambda_{m}=\frac{\kappa\times1000}{C} $$ 

Substitute values:

 $$ \Lambda_{m}=\frac{5.76\times10^{-3}\times1000}{0.5} $$ 

Step 3: Simplify the numerator

 $$ 5.76\times10^{-3}\times1000 $$ 

Since:

 $$ 1000=10^{3} $$ 

 $$ 5.76\times10^{-3}\times10^{3}=5.76 $$ 

Thus:

 $$ \Lambda_{m}=\frac{5.76}{0.5} $$ 

Step 4: Perform the division

 $$ \frac{5.76}{0.5}=11.52 $$ 

Therefore:

 $$ \mathrm{\Lambda}_{m}=11.52\mathrm{S}\mathrm{~cm}^{2}/\mathrm{mol} $$ 

Final Answer:

 $$ 11.52\,\mathrm{S}\,\mathrm{c m}^{2}/\mathrm{m o l} $$ 

Quick Tip: While calculating molar conductivity, always remember the formula:

 $$ \Lambda_{m}=\frac{\kappa\times1000}{C} $$ 

where concentration must be in mol  $ L^{-1} $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.153Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5222, 5, NULL, NULL, 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R:

Assertion (A): A reaction can have zero activation energy.

Reason (R): The minimum extra amount of energy absorbed by reactant molecules so that their energy becomes equal to threshold value, is called activation energy.

In the light of the above statements, choose the correct answer from the options given below:', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true and R is NOT the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 1, 'Concept: Activation energy is the minimum energy required by reacting molecules to form

the activated complex and undergo successful collision. According to collision theory, only those collisions which possess energy equal to or greater than activation energy lead to product formation.

Some reactions, especially very fast ionic reactions, may have nearly zero activation energy.

### Step 1: Analyze Assertion (A)

Assertion states:

## A reaction can have zero activation energy.

This statement is true.

Certain reactions occur so rapidly that practically no extra energy barrier exists between reactants and products. Such reactions are considered to have negligible or nearly zero activation energy.

Examples include some ionic reactions occurring in aqueous medium.

Therefore:

##### Assertion A is true.

### Step 2: Analyze Reason (R)

Reason states:

Activation energy is the minimum extra energy required to reach threshold energy.

This is the correct definition of activation energy.

Thus:

Reason R is also true.

### Step 3: Check whether R explains A

Although Reason correctly defines activation energy, it does not explain why some reactions can have zero activation energy.

The statement in Reason is only a definition and does not justify the condition of zero activation energy.

Hence:

R is not the correct explanation of A.

##### Final Answer:

Both A and R are true and R is NOT the correct explanation of A

Quick Tip: In Assertion-Reason questions, first check whether each statement is independently true, then verify whether the Reason logically explains the Assertion.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.153Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5223, 5, NULL, NULL, 'The following data is for a reaction between reactants A and B:




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Rate (mol L^{-1}s^{-1})</td><td style=''text-align: center; word-wrap: break-word;''>[A]</td><td style=''text-align: center; word-wrap: break-word;''>[B]</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>$ 2 \times 10^{-3} $</td><td style=''text-align: center; word-wrap: break-word;''>0.1M</td><td style=''text-align: center; word-wrap: break-word;''>0.1M</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>$ 4 \times 10^{-3} $</td><td style=''text-align: center; word-wrap: break-word;''>0.2M</td><td style=''text-align: center; word-wrap: break-word;''>0.1M</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>$ 1.6 \times 10^{-2} $</td><td style=''text-align: center; word-wrap: break-word;''>0.2M</td><td style=''text-align: center; word-wrap: break-word;''>0.2M</td></tr></table>


The order of the reaction with respect to A and B, respectively are:', NULL, '[{"text":"1,0","image_url":null,"alt":null},{"text":"0,1","image_url":null,"alt":null},{"text":"1,2","image_url":null,"alt":null},{"text":"2,1","image_url":null,"alt":null}]', NULL, 2, 'Concept: For a reaction:

 $$ aA+bB\rightarrow Products $$ 

Rate law is:

 $$  Rate=k[A]^{m}[B]^{n} $$ 

where:

• m = order with respect to A

• $n$ = order with respect to B

Orders are determined experimentally by comparing rate changes with concentration changes.

Step 1: Determine order with respect to A

Compare experiment 1 and 2:

 $$ \frac{Rate_{2}}{Rate_{1}}=\frac{4\times10^{-3}}{2\times10^{-3}}=2 $$ 

Concentration change:

 $$ \frac{\left[A\right]_{2}}{\left[A\right]_{1}}=\frac{0.2}{0.1}=2 $$ 

[B] remains constant.

Thus:

 $$ 2=2^{m} $$ 

 $$ m=1 $$ 

So, order with respect to A is:

1

### Step 2: Determine order with respect to B

Compare experiment 2 and 3:

 $$ \frac{Rate_{3}}{Rate_{2}}=\frac{1.6\times10^{-2}}{4\times10^{-3}}=4 $$ 

Concentration change:

 $$ \frac{\left[B\right]_{3}}{\left[B\right]_{2}}=\frac{0.2}{0.1}=2 $$ 

[A] remains constant.

 $$ 4=2^{n} $$ 

Thus:

 $$ n=2 $$ 

So, order with respect to B is:

Step 3: Write final order pair

 $$ (m,n)=(1,2) $$ 

Final Answer:

Quick Tip: While finding reaction order, compare only those experiments where one reactant concentration changes and the other remains constant.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.154Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5224, 5, NULL, NULL, '$ t_{99.9\%} $ with respect to  $ t_{90\%} $ for a first order reaction is:', NULL, '[{"text":"Two","image_url":null,"alt":null},{"text":"One","image_url":null,"alt":null},{"text":"Three","image_url":null,"alt":null},{"text":"Four","image_url":null,"alt":null}]', NULL, 2, 'Concept: For a first-order reaction:

 $$ t=\frac{2.303}{k}\log\frac{a}{a-x} $$ 

For percentage completion:

 $$ \frac{a}{a-x}=\frac{100}{unreacted\ percentage} $$ 

Step 1: Calculate  $ t_{90\%} $

At 90% completion:

10% reactant remains

Thus:

 $$ \begin{aligned}t_{90\%}&=\frac{2.303}{k}\log\frac{100}{10}\\ &=\frac{2.303}{k}\log10\\ \end{aligned} $$ 

Since:

 $$ \log10=1 $$ 

 $$ t_{90\%}=\frac{2.303}{k} $$ 

Step 2: Calculate  $ t_{99.9\%} $

At 99.9% completion:

0.1% reactant remains

Thus:

 $$ \begin{aligned}&t_{99.9\%}=\frac{2.303}{k}\log\frac{100}{0.1}\\ &\\ &\quad=\frac{2.303}{k}\log1000\\ \end{aligned} $$ 

Since:

log1000=3

 $$ t_{99.9\%}=\frac{2.303}{k}\times3 $$ 

Step 3: Find ratio

 $$ \frac{t_{99.9\%}}{t_{90\%}}=\frac{3\left(\frac{2.303}{k}\right)}{\left(\frac{2.303}{k}\right)} $$ 

 $$ =3 $$ 

Final Answer:

Quick Tip: For first-order reactions:

 $$ t_{90\%}:t_{99\%}:t_{99.9\%}=1:2:3 $$ 

This shortcut is extremely useful in MCQs.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.154Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5225, 5, NULL, NULL, '99% of a first order reaction was completed in 32 minutes. When will 99.9% of the reaction complete?', NULL, '[{"text":"48 minute","image_url":null,"alt":null},{"text":"49 minute","image_url":null,"alt":null},{"text":"46 minute","image_url":null,"alt":null},{"text":"50 minute","image_url":null,"alt":null}]', NULL, 0, 'Concept: For first-order reactions:

 $$ t=\frac{2.303}{k}\log\frac{a}{a-x} $$ 

Special results:

 $$ t_{90\%}=\frac{2.303}{k} $$ 

 $$ t_{99\%}=\frac{4.606}{k} $$ 

 $$ t_{99.9\%}=\frac{6.909}{k} $$ 

Hence:

 $$ t_{99.9\%}=\frac{3}{2}t_{99\%} $$ 

Step 1: Write given information

Given:

 $$ t_{99\%}=32\mathrm{m i n u t e s} $$ 

We use relation:

 $$ \mathrm{\frac{t_{99,9\%}}{t_{99\%}}} = \frac{3}{2} $$ 

Step 2: Calculate  $ t_{99.9\%} $

 $$ t_{99.9\%}=\frac{3}{2}\times32 $$ 

 $$ =48\mathrm{m i n u t e s} $$ 

Final Answer:

48 minutes

Quick Tip: For first-order reactions:

 $$ t_{90\%}:t_{99\%}:t_{99.9\%}=1:2:3 $$ 

Use this direct ratio method to solve questions quickly.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.155Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5226, 5, NULL, NULL, 'The slope of Arrhenius Plot ( $ \ln k $ v/s  $ \frac{1}{T} $) of the first-order reaction is  $ -5 \times 10^{3} $ K. The value of  $ E_{a} $ of the reaction is. Choose the correct option for your answer. [Given  $ R = 8.314JK^{-1}mol^{-1} $]', NULL, '[{"text":"$ 166 \\, kJ mol^{-1} $","image_url":null,"alt":null},{"text":"$ -83 \\, kJ mol^{-1} $","image_url":null,"alt":null},{"text":"$ 41.5 \\, kJ mol^{-1} $","image_url":null,"alt":null},{"text":"$ 83.0 \\, kJ mol^{-1} $","image_url":null,"alt":null}]', NULL, 2, 'Concept: The Arrhenius equation explains the dependence of rate constant on temperature. It is expressed as:

 $$ k=A e^{-\frac{E_{a}}{R T}} $$ 

where:

• k = rate constant

• A = Arrhenius frequency factor

•  $ E_{a} $ = activation energy

• $R$ = gas constant

•  $ T $ = absolute temperature

Taking natural logarithm on both sides converts the equation into linear form:

 $$ \ln k=\ln A-\frac{E_{a}}{RT} $$ 

This equation represents the equation of a straight line:

 $$ y=m x+c $$ 

Hence, for a graph of  $ \ln k $ versus  $ \frac{1}{T} $:

 $$  Slope=-\frac{E_{a}}{R} $$ 

Step 1: Writing the relation between slope and activation energy.

For Arrhenius plot:

 $$  Slope=-\frac{E_{a}}{R} $$ 

Given:

 $$ \mathrm{S l o p e}=-5\times10^{3}K $$ 

Substituting into the equation:

 $$ -\frac{E_{a}}{R}=-5\times10^{3} $$ 

Removing negative signs:

 $$ \frac{E_{a}}{R}=5\times10^{3} $$ 

Therefore:

 $$ E_{a}=5\times10^{3}\times R $$ 

Step 2: Substituting the value of gas constant.

Given:

 $$ R=8.314J K^{-1}m o l^{-1} $$ 

Thus:

 $$ E_{a}=5\times10^{3}\times8.314 $$ 

 $$ E_{a}=41570J mol^{-1} $$ 

Step 3: Converting Joule into kilojoule.

Since:

 $$ 1kJ=1000J $$ 

Therefore:

 $$ E_{a}=\frac{41570}{1000} $$ 

 $$ E_{a}=41.57kJ mol^{-1} $$ 

Approximating:

 $$ E_{a}\approx41.5kJ mol^{-1} $$ 

Final Answer:

 $$ 41.5kJ mol^{-1} $$ 

Quick Tip: For Arrhenius plots:

 $$ \ln k vs\frac{1}{T}\Rightarrow Slope=-\frac{E_{a}}{R} $$ 

while

 $$ \log k~vs~\frac{1}{T}\Rightarrow Slope=-\frac{E_{a}}{2.303R} $$ 

Always check whether the logarithm is natural log or common log.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.155Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5227, 5, NULL, NULL, '''Spin only'' magnetic moment is same for which of the following ions?

A.  $ Ti^{3+} $

B.  $ Cr^{2+} $

C.  $ Mn^{2+} $

D.  $ Fe^{2+} $

E.  $ Sc^{3+} $

Choose the most appropriate answer from the options given below:', NULL, '[{"text":"B and D only","image_url":null,"alt":null},{"text":"A and E only","image_url":null,"alt":null},{"text":"B and C only","image_url":null,"alt":null},{"text":"A and D only","image_url":null,"alt":null}]', NULL, 0, 'Concept: The spin-only magnetic moment depends on the number of unpaired electrons present in the atom or ion.

Formula:

 $$ \mu=\sqrt{n(n+2)}BM $$ 

where:

• n = number of unpaired electrons

• BM = Bohr Magneton

If two ions possess the same number of unpaired electrons, they will have the same magnetic moment.

Step 1: Finding the electronic configuration of each ion.

 $$ T i^{3+} $$ 

Atomic number of Ti = 22

Electronic configuration:

 $$ Ti=[Ar]3d^{2}4s^{2} $$ 

For  $ Ti^{3+} $, remove 3 electrons:

 $$ Ti^{3+}=[Ar]3d^{1} $$ 

Number of unpaired electrons:

 $$ n=1 $$ 

 $$ C r^{2+} $$ 

Atomic number of Cr = 24

Electronic configuration:

 $$ Cr=[Ar]3d^{5}4s^{1} $$ 

Removing two electrons:

 $$ Cr^{2+}=[Ar]3d^{4} $$ 

According to Hund''s rule:

 $$ n=4 $$ 

 $$ Mn^{2+} $$ 

Atomic number of Mn = 25

 $$ Mn=[Ar]3d^{5}4s^{2} $$ 

Removing two electrons:

 $$ Mn^{2+}=[Ar]3d^{5} $$ 

All electrons remain unpaired.

 $$ n=5 $$ 

 $$ Fe^{2+} $$ 

Atomic number of Fe = 26

 $$ Fe=[Ar]3d^{6}4s^{2} $$ 

Removing two electrons:

 $$ Fe^{2+}=[Ar]3d^{6} $$ 

In  $ 3d^{6} $, four electrons remain unpaired.

 $$ n=4 $$ 

 $$ S c^{3+} $$ 

Atomic number of Sc = 21

 $$ Sc=[Ar]3d^{1}4s^{2} $$ 

Removing three electrons:

 $$ Sc^{3+}=[Ar]3d^{0} $$ 

 $$ n=0 $$ 

Step 2: Comparing the number of unpaired electrons.

 $$ Ti^{3+}\Rightarrow n=1 $$ 

 $$ Cr^{2+}\Rightarrow n=4 $$ 

 $$ Mn^{2+}\Rightarrow n=5 $$ 

 $$ Fe^{2+}\Rightarrow n=4 $$ 

 $$ Sc^{3+}\Rightarrow n=0 $$ 

Thus:

 $$ Cr^{2+}andFe^{2+} $$ 

have equal unpaired electrons.

Hence both possess same magnetic moment.

Final Answer:

B and D only

Quick Tip: For  $ d^{n} $ configuration:

 $$ n\leq5\Rightarrow\mathrm{Unpaired~electrons}=n $$ 

 $$ n>5\Rightarrow Unpaired~electrons=10-n $$ 

This shortcut helps in rapid calculation of magnetic moments.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.156Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5228, 5, NULL, NULL, 'Which of the following set of ions act as oxidizing agents?', NULL, '[{"text":"$ Ce^{4+} $ and $ Tb^{4+} $","image_url":null,"alt":null},{"text":"$ La^{3+} $ and $ Lu^{3+} $","image_url":null,"alt":null},{"text":"$ Eu^{2+} $ and $ Yb^{2+} $","image_url":null,"alt":null},{"text":"$ Eu^{2+} $ and $ Tb^{4+} $","image_url":null,"alt":null}]', NULL, 0, 'Concept: Lanthanoids most commonly exhibit the +3 oxidation state. Ions existing in oxidation states other than +3 tend to convert back into the more stable +3 state.

• +4 ions gain electrons and get reduced to +3, hence act as oxidizing agents.

• +2 ions lose electrons and get oxidized to +3, hence act as reducing agents.

Step 1: Analyzing  $ Ce^{4+} $ and  $ Tb^{4+} $.

 $$ Ce^{4+} \to Ce^{3+} $$ 

Since  $ Ce^{4+} $ gains an electron, it gets reduced.

Thus, it behaves as an oxidizing agent.

Similarly:

 $$ Tb^{4+} \to Tb^{3+} $$ 

It also gets reduced easily.

Hence  $ T b^{4+} $ also acts as an oxidizing agent.

Step 2: Checking other options.

Option (b)

 $$ La^{3+}and~Lu^{3+} $$ 

Both are already in their stable oxidation state.

Hence they do not act as strong oxidizing agents.

Option (c)

 $$ Eu^{2+}and Yb^{2+} $$ 

These ions tend to lose electrons:

 $$ Eu^{2+} \to Eu^{3+} $$ 

 $$ Yb^{2+} \to Yb^{3+} $$ 

Hence they act as reducing agents, not oxidizing agents.

Option (d)

 $$ Eu^{2+} $$ 

is reducing in nature while

 $$ Tb^{4+} $$ 

is oxidizing in nature.

Thus both are not oxidizing agents together.

Final Answer:

 $$ Ce^{4+} \text{and}Tb^{4+} $$ 

Quick Tip: In Lanthanoids:

+4  $ \rightarrow $ +3

means reduction, so the ion acts as an oxidizing agent.

+2  $ \rightarrow $ +3

means oxidation, so the ion acts as a reducing agent.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.156Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5229, 5, NULL, NULL, 'Assertion (A): Ionization enthalpy increases along each series of transition elements from left to right. However, small variations occur.

## Reason (R): There is a corresponding increase in nuclear charge which accompanies the filling of electrons in the inner d-orbitals.', NULL, '[{"text":"(A) is correct but (R) is not correct","image_url":null,"alt":null},{"text":"(A) is not correct but (R) is correct","image_url":null,"alt":null},{"text":"Both (A) and (R) are correct and (R) is the correct explanation of (A)","image_url":null,"alt":null},{"text":"Both (A) and (R) are correct but (R) is not the correct explanation of (A)","image_url":null,"alt":null}]', NULL, 2, 'Concept: Ionization enthalpy is the minimum energy required to remove the most loosely bound electron from an isolated gaseous atom.

It mainly depends upon:

• Effective nuclear charge

• Atomic size

• Shielding effect

• Stability of electronic configuration

Step 1: Analyzing the Assertion.

Across the transition series, atomic number increases continuously.

As protons increase, nuclear charge also increases.

Electrons are added into inner d-orbitals, but d-electrons do not shield effectively.

Therefore outer electrons experience stronger attraction from nucleus.

Hence more energy is required to remove electrons.

Thus ionization enthalpy generally increases from left to right.

However, due to:

• half-filled stability

• fully-filled stability

• electron repulsion

small irregular variations occur.

Hence Assertion is true.

Step 2: Analyzing the Reason.

Reason states that nuclear charge increases while electrons are filled in inner d-orbitals. This statement is correct.

Increase in nuclear charge causes stronger attraction on valence electrons.

Hence ionization enthalpy increases.

Step 3: Checking the relationship between A and R.

The Reason directly explains why ionization enthalpy increases across transition series. Therefore:

Both A and R are true and R correctly explains A.

##### Final Answer:

Both A and R are true and R correctly explains A

Quick Tip: d-electrons shield poorly compared to s- and p-electrons. Hence effective nuclear charge increases significantly across transition series.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.156Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5230, 5, NULL, NULL, 'The incorrect statement among the following is:', NULL, '[{"text":"Lanthanoids are good conductors of heat and electricity.","image_url":null,"alt":null},{"text":"Actinoids are highly reactive metals, especially when finely divided.","image_url":null,"alt":null},{"text":"Actinoid contraction is greater for element-to-element than Lanthanoid contraction.","image_url":null,"alt":null},{"text":"Most of the trivalent Lanthanoid ions are colourless in the solid state.","image_url":null,"alt":null}]', NULL, 3, 'Concept: Lanthanoids and Actinoids belong to the $f$-block elements and exhibit characteristic properties such as variable oxidation states, contraction, color, magnetic behavior, and high metallic character.

Step 1: Checking statement (a).

Lanthanoids are metallic elements.

They possess free electrons responsible for metallic conductivity.

Therefore they conduct:

• Heat

• Electricity

efficiently.

Hence statement (a) is correct.

Step 2: Checking statement (b).

Actinoids are highly electropositive metals.

Finely divided actinoids react rapidly because surface area increases significantly.

Hence statement (b) is correct.

Step 3: Checking statement (c).

Actinoid contraction is larger because:

• 5f-electrons shield very poorly

• effective nuclear charge increases strongly

Thus contraction becomes greater than lanthanoid contraction.

Hence statement (c) is correct.

Step 4: Checking statement (d).

Most trivalent lanthanoid ions are actually colored due to f-f electronic transitions.

Only ions having:

 $$ f^{0},f^{7},f^{14} $$ 

configurations are generally colorless.

Examples:

 $$ La^{3+},Gd^{3+},Lu^{3+} $$ 

Since most lanthanoid ions are colored, statement (d) is incorrect.

Final Answer:

Most of the trivalent Lanthanoid ions are colourless in the solid state

Quick Tip: Color in Lanthanoids arises due to $f-f$ transitions. Ions with completely empty, half-filled, or completely filled $f$-orbitals are generally colorless.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.157Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5231, 5, NULL, NULL, 'Which of the following organic compounds is expected to have the highest boiling point?', NULL, '[{"text":"$ CH_{3}CH_{2}CH_{2}CH_{2}OH $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}CHO $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}CH_{2}CH_{3} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}OCH_{2}CH_{3} $","image_url":null,"alt":null}]', NULL, 0, 'Concept: The boiling point of volatile organic molecules reflects the quantity of kinetic thermal energy needed to completely separate condensed molecules into the gas phase. This physical property is governed by the structural type and cumulative strength of intermolecular forces holding the liquid phase together. When comparing organic molecules with highly similar molecular weights, the relative hierarchy of boiling points follows the sequence of baseline intermolecular forces:

Intermolecular Hydrogen Bonding > Dipole-Dipole Interaction > London Dispersion Forces

Step 1: Identifying the active functional groups and matching their intermolecular forces. We analyze the structural features of each molecular choice:

• Butan-1-ol (CH₃CH₂CH₂CH₂OH): Contains a strongly polarized hydroxyl (-OH) functional group. The presence of a hydrogen atom covalently attached to highly electronic-active oxygen permits extensive intermolecular hydrogen bonding.

• Butanal  $ (CH_{3}CH_{2}CH_{2}CHO) $: Features a polar carbonyl group  $ (-C=O) $. This structure gives rise to fixed molecular dipoles that interact via dipole-dipole attractions, which are weaker than hydrogen bonds.

• Ethoxyethane (CH₃CH₂OCH₂CH₃): An asymmetrical ether containing a polar C-O-C framework. It exhibits mild dipole-dipole interactions but lacks any hydrogen atoms bonded to oxygen to support self-hydrogen bonding.

• Pentane ( $ CH_{3}CH_{2}CH_{2}CH_{2}CH_{3} $): A completely nonpolar saturated hydrocarbon with a uniform electron cloud, operating strictly via temporary London dispersion forces.

Step 2: Evaluating force magnitudes to isolate the compound with the maximum boiling point. Intermolecular hydrogen bonds are significantly stronger than basic dipole-dipole attractions or weak dispersion forces. Because Butan-1-ol possesses the capability to form a network of hydrogen bonds between its molecules, it requires a much higher temperature to overcome these cohesive forces and transition into the gas phase. Therefore, Butan-1-ol has the highest boiling point among the given options.

Quick Tip: When molecular masses are similar, alcohols will almost always outboil aldehydes, ethers, and hydrocarbons due to extensive hydrogen bonding.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.159Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5232, 5, NULL, NULL, 'Why do aquatic species, such as fish, generally feel more comfortable in cold water than in warm water?', NULL, '[{"text":"The solubility of oxygen gas increases as the temperature of the water decreases.","image_url":null,"alt":null},{"text":"The solubility of oxygen gas decreases as the temperature of the water decreases.","image_url":null,"alt":null},{"text":"The Henry''s law constant $ K_{H} $ for oxygen decreases as temperature increases.","image_url":null,"alt":null},{"text":"Warm water contains more dissolved toxic gases that harm aquatic metabolism.","image_url":null,"alt":null}]', NULL, 0, 'Concept: The process of dissolving gaseous solutes into liquid solvents represents a phase transition that achieves dynamic chemical equilibrium. When a gas dissolves, its individual molecules contract from a high-volume gas state into a restricted dissolved state, releasing kinetic energy. As a result, gas dissolution is universally classified as an exothermic physical process:

 $$  Gas(g)+Liquid~Solvent(l)\rightleftharpoons Dissolved~Solution(aq)+Heat\quad(\Delta H<0) $$ 

We use Le Chatelier''s principle to evaluate how thermal energetic changes force this equilibrium to shift.

## Step 1: Applying Le Chatelier''s principle to the exothermic dissolution equation under cold conditions.

Le Chatelier''s principle states that if a dynamic system at equilibrium experiences a temperature change, the position of the equilibrium shifts to counteract that change. When the ambient temperature of the aqueous system decreases (as seen in cold water), the system responds by attempting to generate thermal energy. To accomplish this, the equilibrium shifts toward the exothermic forward direction (to the right).

#### Step 2: Connecting the equilibrium shift to the breathing comfort of aquatic species.

The forward shift drives a larger mass of gaseous oxygen molecules to dissolve into the liquid phase. Consequently, cold water retains a substantially higher concentration of dissolved oxygen (DO) than warm water. Because fish and other aquatic species rely on extracting dissolved oxygen from water via their gills for respiration, the higher concentration of available oxygen makes cold water significantly more favorable and comfortable for their survival.

Quick Tip: Gas dissolution is exothermic ( $ \Delta H < 0 $). Therefore, gas solubility decreases with an increase in temperature.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.161Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5233, 5, NULL, NULL, 'What are the starting materials used in the industrial synthesis of the pesticide DDT?', NULL, '[{"text":"Chlorobenzene and Chloroform","image_url":null,"alt":null},{"text":"Chlorobenzene and Chloral","image_url":null,"alt":null},{"text":"Benzene and Chloral","image_url":null,"alt":null},{"text":"Chlorobenzene and Hexachloroethane","image_url":null,"alt":null}]', NULL, 1, 'Concept: DDT, or dichlorodiphenyltrichloroethane, is prepared through an acid-catalyzed condensation pathway that follows an electrophilic aromatic substitution mechanism ( $ S_{E}Ar $). The structural formula of DDT features two distinct halobenzene rings linked directly to a central chlorinated alkane backbone. To synthesize this framework, a highly reactive chlorinated carbonyl compound is required to serve as the structural core and source of the electrophile.

##### Step 1: Generating the electrophilic intermediate from the carbonyl precursor.

The synthesis乌尔巴尔的烃类键键合剂，如苯环、蒽醌等，这些化合物在反应中扮演重要角色。在反应过程中，这些化合物能够提供电子位和能量，从而促进反应的速率。例如，在反应中，反应物、产物、产物

 $$ (CCl_{3}CHO) $$ 

Step 2: Condensing the electrophile with the aromatic halide to finalize the DDT structure. The activated intermediate undergoes successive electrophilic attacks by two separate molecules of chlorobenzene. The positions para to the chlorine atoms on the chlorobenzene rings act as the nucleophilic sites attacking the central carbon. As the condensation reaction proceeds, a molecule of water is eliminated (H₂O), locking the two chlorobenzene groups and the trichloroethane fragment into a single molecule:

 $$ 2\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{Cl}+\mathrm{CCl}_{3}\mathrm{CHO}\xrightarrow{\mathrm{conc.}\mathrm{H}_{2}\mathrm{SO}_{4}}\left(\mathrm{Cl}-\mathrm{C}_{6}\mathrm{H}_{4}\right)_{2}\mathrm{CH}-\mathrm{CCl}_{3}+\mathrm{H}_{2}\mathrm{O} $$ 

Thus, the industrial starting components are chlorobenzene and chloral.

Quick Tip: Remember the formula:  $ 2 \times \text{Chlorobenzene} + 1 \times \text{Chloral} \xrightarrow{\text{H}_2\text{SO}_4} \text{DDT} + \text{H}_2\text{O} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.162Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5234, 5, NULL, NULL, 'Which of the following statements is TRUE regarding the transition state of a bimolecular nucleophilic substitution ( $ S_{N}2 $) reaction?', NULL, '[{"text":"The central carbon atom transitions to an $ sp^{3} $ hybridization state with a tetrahedral geometry.","image_url":null,"alt":null},{"text":"The central carbon atom adopts an unstable pentacoordinate arrangement with approximate $ sp^{2} $ hybridization.","image_url":null,"alt":null},{"text":"The reaction forms a stable, isolation-ready carbocation intermediate.","image_url":null,"alt":null},{"text":"Both the nucleophile and the leaving group carry full, non-interacting formal charges.","image_url":null,"alt":null}]', NULL, 1, 'Concept: The  $ S_{N}2 $ pathway operates via a concerted, single-step mechanism. Unlike stepwise substitutions, it does not involve the formation of any distinct, low-energy intermediates such as carbocations. Instead, bond-making between the incoming nucleophile and the substrate occurs simultaneously with bond-breaking of the leaving group. This coordinated process passes through an unstable, high-energy transition state configuration.

Step 1: Analyzing the synchronous geometry and bond configuration of the reaction center. During an  $ S_N $2 attack, the nucleophile approaches the substrate from the side directly opposite the leaving group (180° back-side attack) to minimize electrostatic repulsion. At the peak of the transition state, the bond to the incoming nucleophile ( $ Nu^{\delta-} $) is partially formed, while the bond to the departing leaving group ( $ LG^{\delta-} $) is partially broken. This arrangement forces the central carbon atom to coordinate temporarily with five separate groups at the same time.

##### Step 2: Determining the transient hybridization state and electronic geometry.

Because the partial bonds to the nucleophile and leaving group lie along a single linear axis, the central carbon uses its remaining unhybridized p-orbital to interact with them. The other three stable, non-reacting substituent bonds are pushed away and flatten out into a single perpendicular plane. This planar arrangement uses three  $ sp^{2} $ hybrid orbitals separated by  $ 120^{\circ} $ angles. This creates an unstable pentacoordinate carbon center with a trigonal bipyramidal geometry in the transition state.

Quick Tip: The  $ S_{N}2 $ mechanism involves a single concerted transition state (pentacoordinate carbon), while  $ S_{N}1 $ proceeds via a distinct carbocation intermediate.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.164Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5235, 5, NULL, NULL, 'Ethylene glycol (ethane-1,2-diol) is widely added to car radiators as an antifreeze agent. How does its addition protect the engine in extreme climates?', NULL, '[{"text":"It raises the freezing point of water and lowers its boiling point.","image_url":null,"alt":null},{"text":"It lowers the freezing point of water and raises its boiling point.","image_url":null,"alt":null},{"text":"It lowers both the freezing point and the boiling point of water equally.","image_url":null,"alt":null},{"text":"It reacts chemically with the metal radiator walls to reduce thermal expansion.","image_url":null,"alt":null}]', NULL, 1, 'Concept: When a non-volatile solute is dissolved into a volatile liquid solvent, it changes the physical behavior of the solution. The solute particles occupy space at the liquid surface, decreasing the rate of evaporation and lowering the overall vapor pressure of the solvent. This shift in vapor pressure leads directly to changes in two key colligative properties:

 $$ \Delta T_{f}=K_{f}\cdot m\quad(Depression~of~Freezing~Point) $$ 

 $$ \Delta T_{b}=K_{b}\cdot m\quad(Elevation~of~Boiling~Point) $$ 

##### Step 1: Evaluating the physical mechanism behind freezing point depression.

In pure water, molecules readily assemble into a rigid, structured crystalline lattice at  $ 0^{\circ} $C. When ethylene glycol (HO-CH $ _{2} $-CH $ _{2} $-OH) is added, its molecules form hydrogen bonds with water, disrupting the regular intermolecular organization of the solvent. To overcome this disruption and force crystallization, thermal energy must be removed from the system. This drops the freezing point significantly below  $ 0^{\circ} $C ( $ \Delta T_{f} $), preventing the coolant from freezing and cracking the radiator block in cold climates.

#### Step 2: Evaluating the physical mechanism behind boiling point elevation.

Simultaneously, because the non-volatile ethylene glycol solute lowers the solution’s vapor pressure, a higher temperature is required for the vapor pressure to equal the external atmospheric pressure. This elevates the boiling point of the radiator fluid significantly above  $ 100^{\circ} $C ( $ \Delta T_{b} $). Together, these two property shifts widen the liquid temperature range of the coolant, protecting the engine from both freezing in winter and boiling over in summer.

Quick Tip: Solute addition expands the liquid temperature range of a solvent by pushing  $ T_{f} $ down and pulling  $ T_{b} $ up.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.164Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5236, 5, NULL, NULL, 'Which of the following oxidizing agents is mild enough to selectively oxidize an aldehyde to a carboxylic acid without cleaving other sensitive carbon-carbon single bonds?', NULL, '[{"text":"Tollens'' reagent","image_url":null,"alt":null},{"text":"Concentrated $ H_{2}SO_{4} $ at high temperatures","image_url":null,"alt":null},{"text":"Ozone followed by Zn / H $ _{2} $O","image_url":null,"alt":null},{"text":"LiAlH_{4} in dry ether","image_url":null,"alt":null}]', NULL, 0, 'Concept: Aldehydes (R-CHO) are easily oxidized because they possess a reactive hydrogen atom directly bonded to the carbonyl carbon. This structural feature allows them to undergo oxidation under mild conditions. In contrast, ketones (R-CO-R'') lack this specific carbonyl hydrogen atom, meaning their oxidation requires the cleavage of strong carbon-carbon single bonds under harsh conditions. Consequently, mild laboratory oxidizing agents can selectively oxidize aldehydes while leaving ketones and other functional groups untouched.

##### Step 1: Analyzing the chemical behavior of Tollens'' reagent as a selective oxidant.

Tollens’ reagent is an aqueous alkaline solution containing the diamminesilver(I) coordination complex, formulated as  $ [\mathrm{Ag}(\mathrm{NH}_{3})_{2}]^{+} $. The silver ions  $ (\mathrm{Ag}^{+}) $ in this complex serve as a gentle, mild electron acceptor. When mixed with an aldehyde, Tollens’ reagent selectively targets and oxidizes the carbonyl carbon, transforming the aldehyde group into a carboxylate anion  $ (\mathrm{R}-\mathrm{COO}^{-}) $:

 $$ \mathrm{R-CHO+2[Ag(NH_{3})_{2}]^{+}+3OH^{-}\rightarrow R-COO^{-}+2Ag(s)\downarrow+4NH_{3}+2H_{2}O} $$ 

Step 2: Ruling out alternative aggressive or reducing reagents.

We evaluate the alternative choices to confirm selectivity:

- Hot concentrated  $ H_{2}SO_{4} $ acts as a powerful, non-selective oxidizing and dehydrating agent that causes widespread decomposition.

- Ozone ( $ O_{3} $) followed by a zinc workup is used to cleave carbon-carbon double bonds in alkenes rather than selectively oxidizing terminal carbonyls.

- LiAlH $ _{4} $ is a strong reducing agent that performs the opposite transformation, converting carbonyls back into primary alcohols.

Thus, Tollens'' reagent is the ideal mild oxidant for this selective transformation.

Quick Tip: Mild oxidants like Tollens'' or Fehling''s reagents can oxidize aldehydes, but they are not strong enough to oxidize ketones.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.165Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5237, 5, NULL, NULL, 'What are the primary reagents and catalysts required to carry out the Gattermann-Koch reaction?', NULL, '[{"text":"CO, HCl, and anhydrous AlCl_{3} / CuCl","image_url":null,"alt":null},{"text":"CHCl_{3} and aqueous NaOH","image_url":null,"alt":null},{"text":"HCN, HCl, and anhydrous AlCl_{3}","image_url":null,"alt":null},{"text":"CH_{3}Cl and anhydrous AlCl_{3}","image_url":null,"alt":null}]', NULL, 0, 'Concept: The Gattermann-Koch reaction is a classic organic named reaction used to introduce a formyl functional group (−CHO) directly onto an aromatic ring. This transformation converts benzene or activated benzene derivatives into aromatic aldehydes. Mechanistically, it operates as a variation of a Friedel-Crafts acylation, requiring a gaseous source to generate a highly reactive, short-lived formyl cation intermediate ( $ [HC=O]^{+} $).

Formyl chloride (HCOCl) is highly unstable and decomposes rapidly at room temperature, meaning it cannot be stored or added directly to a reaction flask. To circumvent this, the Gattermann-Koch reaction generates the necessary electrophilic species in situ. A gaseous mixture of carbon monoxide (CO) and hydrogen chloride (HCl) is bubbled into the reaction mixture. In the presence of a strong Lewis acid catalyst like anhydrous aluminum chloride (AlCl₃), these components interact to form the transient formyl electrophile.

Because carbon monoxide reactions can be slow under standard conditions, cuprous chloride (CuCl) is added as a vital co-catalyst. The copper(I) center binds temporarily to carbon monoxide, increasing its local concentration and facilitating its reaction with HCl and AlCl_{3}. The resulting formyl cation undergoes an electrophilic aromatic substitution attack on the

benzene ring, yielding benzaldehyde:

 $$ \mathrm{C}_{6}\mathrm{H}_{6}+\mathrm{CO}+\mathrm{HCl}\xrightarrow{\mathrm{anhydrous~AlCl}_{3}/\mathrm{CuCl}}\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CHO}+\mathrm{HCl} $$ 

This confirms option (A) as the correct reagent combination.

Quick Tip: Distinction: Gattermann-Koch uses CO+HCl, whereas the standard Gattermann formylation utilizes HCN + HCl.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.166Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5238, 5, NULL, NULL, 'Among the given pairs of isomeric organic compounds, which pair is correctly arranged in order of INCREASING boiling point?', NULL, '[{"text":"n-Butyl alcohol < t-Butyl alcohol","image_url":null,"alt":null},{"text":"t-Butyl chloride < n-Butyl chloride","image_url":null,"alt":null},{"text":"p-Dichlorobenzene < o-Dichlorobenzene","image_url":null,"alt":null},{"text":"Isopentane < Neopentane","image_url":null,"alt":null}]', NULL, 1, 'Concept: For structural isomers sharing identical molecular formulas and molecular weights, variations in boiling point are governed by molecular shape and branching. Nonpolar or weakly polar covalent molecules rely on temporary London dispersion forces, which depend directly on the total accessible molecular surface area. The relationship between molecular structure and boiling point follows a reliable trend:

Increased Branching $\Rightarrow$ Spherical Shape $\Rightarrow$ Smaller Surface Area $\Rightarrow$ Weaker Dispersion Forces $\Rightarrow$ Lower Bo

Step 1: Analyzing the structural differences between butyl chloride isomers.

We compare the straight-chain and branched isomers of butyl chloride:

- t-Butyl chloride ((CH_{3})_{3}C-Cl): Features a highly branched, compact, and nearly spherical geometry. This spherical shape minimizes the outer surface area available for contact with neighboring molecules.

• n-Butyl chloride (CH_{3}CH_{2}CH_{2}CH_{2}Cl): Possesses a fully extended, linear, straight-chain hydrocarbon conformation that provides a significantly larger molecular surface area.

#### Step 2: Correlating surface area to the final boiling point inequality.

The larger surface area of linear n-butyl chloride allows neighboring molecules to align closely, maximizing the strength of intermolecular London dispersion forces. Conversely, the compact shape of t-butyl chloride limits molecular contact, weakening these temporary attractions. Consequently, t-butyl chloride boils at a significantly lower temperature (324 K) than n-butyl chloride (351 K). This confirms that the arrangement t-butyl chloride < n-butyl chloride correctly demonstrates a trend of increasing boiling point.

Quick Tip: As molecular branching increases  $ \Rightarrow $ Surface area decreases  $ \Rightarrow $ Van der Waals forces weaken  $ \Rightarrow $ Boiling point drops.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.167Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5239, 5, NULL, NULL, 'When benzaldehyde is subjected to oxidation using acidified potassium permanganate ( $ KMnO_{4} $), what organic product is formed?', NULL, '[{"text":"Benzyl alcohol","image_url":null,"alt":null},{"text":"Benzoic acid","image_url":null,"alt":null},{"text":"Benzene","image_url":null,"alt":null},{"text":"Acetophenone","image_url":null,"alt":null}]', NULL, 1, 'Concept: Aromatic aldehydes are highly susceptible to oxidation due to the presence of the single carbon-hydrogen bond on the formyl carbonyl group (−CHO). When treated with a powerful transition metal oxidant, this carbonyl C-H bond is cleaved and converted into a carbon-hydroxyl (C-OH) bond. This process transforms the aldehyde functional group into a stable carboxylic acid derivative.

Step 1: Evaluating the chemical behavior of the strong oxidant with benzaldehyde.

Potassium permanganate (KMnO₄) under acidified conditions (H₂SO₄) serves as an exceptionally strong, non-selective oxidizing agent. The manganese center in the permanganate anion

(MnO_{4}^{-}) is in its highest oxidation state (+7) and acts as an efficient electron acceptor. When introduced to benzaldehyde (C_{6}H_{5}CHO), the reagent readily attacks the formyl carbon atom, oxidizing the functional group to form a carboxylic acid.

##### Step 2: Determining the final structure of the aromatic product.

The oxidation converts the formyl group (-CHO) directly into a carboxylic acid group (-COOH) attached to the benzene ring. The aromatic core remains completely intact throughout this transformation, as the benzene ring is stabilized by resonance and resists oxidative cleavage. The resulting organic product is benzoic acid ( $ C_{6}H_{5}COOH $):

 $$  C_{6}H_{5}CHO\xrightarrow{Acidified~KMnO_{4}}C_{6}H_{5}COOH $$ 

This confirms option (B) as the correct choice.

Quick Tip: Whether using mild (Tollens'') or strong (KMnO_{4}) oxidizing agents, aldehydes consistently convert into their corresponding carboxylic acids.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.168Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5240, 5, NULL, NULL, 'For the reaction

 $$ 2\boldsymbol{A}+\boldsymbol{B}\rightarrow3\boldsymbol{C}+\boldsymbol{D} $$ 

Which of the following does not express the reaction rate?', NULL, '[{"text":"$$ -\\frac{d[B]}{dt} $$","image_url":null,"alt":null},{"text":"$$ \\frac{d[D]}{dt} $$","image_url":null,"alt":null},{"text":"$$ -\\frac{1}{2}\\frac{d[A]}{dt} $$","image_url":null,"alt":null},{"text":"$$ \\frac{1}{3}\\frac{d[C]}{dt} $$","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Write the rate expression.

For the reaction:

 $$ 2\boldsymbol{A}+\boldsymbol{B}\rightarrow3\boldsymbol{C}+\boldsymbol{D} $$ 

Rate of reaction is:

 $$ \mathrm{Rate}=-\frac{1}{2}\frac{d[A]}{dt}=-\frac{d[B]}{dt}=\frac{1}{3}\frac{d[C]}{dt}=\frac{d[D]}{dt} $$ 

Step 2: Compare with given options.

Option (2):

 $$ \frac{d[D]}{dt} $$ 

is correct.

Option (3):

 $$ -\frac{1}{2}\frac{d[A]}{dt} $$ 

is correct.

Option (4):

 $$ \frac{1}{3}\frac{d[C]}{dt} $$ 

is correct.

Option (1):

 $$ -\frac{d[B]}{dt} $$ 

 $$ -\frac{1}{1}\frac{d[B]}{dt} $$ 

should actually be:

Thus it is not properly normalized according to stoichiometric coefficient form.

Step 3: Identify the incorrect expression.

Therefore:

 $$ \mathrm{(A)}-\frac{\mathrm{d}[\mathrm{B}]}{\mathrm{d t}} $$ 

Quick Tip: For a reaction:

 $$ aA+bB\to cC+dD $$ 

Reaction rate:

 $$ -\frac{1}{a}\frac{d[A]}{dt}=-\frac{1}{b}\frac{d[B]}{dt}=\frac{1}{c}\frac{d[C]}{dt}=\frac{1}{d}\frac{d[D]}{dt} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.170Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5241, 5, NULL, NULL, 'The oxidation potentials of A and B are

 $$ +2.37\mathrm{~V}\quad\mathrm{a n d}\quad+1.66\mathrm{~V} $$ 

respectively. In chemical reactions', NULL, '[{"text":"A will be replaced by B","image_url":null,"alt":null},{"text":"A will replace B","image_url":null,"alt":null},{"text":"A will not replace B","image_url":null,"alt":null},{"text":"A and B will not replace each other","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understand oxidation potential.

Greater oxidation potential means greater tendency to:

lose electrons

Hence stronger reducing agent.

Given:

 $$ E_{\mathrm{o x}}^{\circ}(A)=+2.37\mathrm{V} $$ 

 $$ E_{ox}^{\circ}(B)=+1.66V $$ 

Thus:

has greater tendency to oxidize than:

Step 2: Determine displacement tendency.

A stronger reducing agent displaces a weaker reducing agent from its salt solution.

Since:

 $$ A>B $$ 

in oxidation tendency,

will replace:

Step 3: Identify the correct option.

Therefore:

(B) A will replace B

Quick Tip: Higher oxidation potential:

greater tendency to lose electrons

stronger reducing agent.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.170Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5242, 5, NULL, NULL, 'For which value of x and y, the following square planar compound shows geometrical isomers

 $$ [\mathrm{P t}(\mathrm{C l})_{\mathrm{x}}(\mathrm{B r})_{\mathrm{y}}]^{2-} $$', NULL, '[{"text":"1,3","image_url":null,"alt":null},{"text":"3,1","image_url":null,"alt":null},{"text":"2,2","image_url":null,"alt":null},{"text":"1,1","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Recall geometrical isomerism in square planar complexes.

Square planar complexes show geometrical isomerism when:

two pairs of identical ligands are present

General form:

 $$ [\mathrm{M A}_{2}\mathrm{B}_{2}] $$ 

shows:

cis and trans isomers

Step 2: Analyze the given complex.

For:

 $$ [\mathrm{P t}(\mathrm{C l})_{\mathrm{x}}(\mathrm{B r})_{\mathrm{y}}]^{2-} $$ 

geometrical isomerism is possible only when:

 $$ x=2,\quad 囍 y=2 $$ 

Thus complex becomes:

 $$ [{\mathrm{P t C l}}_{2}{\mathrm{B r}}_{2}]^{2-} $$ 

which shows:

cis-trans isomerism

Step 3: Identify the correct option.

Therefore:

 $$ \mathrm{(C)}2,2 $$ 

Quick Tip: Square planar complexes of type:

 $$ [MA_{2}B_{2}] $$ 

show:

cis-trans geometrical isomerism', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5243, 5, NULL, NULL, 'Match the columns




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">Column-I</td><td colspan="2">Column-II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A)</td><td style=''text-align: center; word-wrap: break-word;''>$ CH_{2}=CH-CH_{2}Cl $</td><td style=''text-align: center; word-wrap: break-word;''>(p)</td><td style=''text-align: center; word-wrap: break-word;''>gem-Dichloride</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B)</td><td style=''text-align: center; word-wrap: break-word;''>$ CH_{2}=CHX $</td><td style=''text-align: center; word-wrap: break-word;''>(q)</td><td style=''text-align: center; word-wrap: break-word;''>Vinylic halide</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C)</td><td style=''text-align: center; word-wrap: break-word;''>$ CH_{3}CHCl_{2} $</td><td style=''text-align: center; word-wrap: break-word;''>(r)</td><td style=''text-align: center; word-wrap: break-word;''>vic-Dichloride</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D)</td><td style=''text-align: center; word-wrap: break-word;''>$ CH_{2}ClCH_{2}Cl $</td><td style=''text-align: center; word-wrap: break-word;''>(s)</td><td style=''text-align: center; word-wrap: break-word;''>Allylic halide</td></tr></table>', NULL, '[{"text":"$ A \\to (r) $, $ B \\to (q) $, $ C \\to (p) $, $ D \\to (s) $","image_url":null,"alt":null},{"text":"$ A \\to (q) $, $ B \\to (p) $, $ C \\to (s) $, $ D \\to (r) $","image_url":null,"alt":null},{"text":"$ A \\to (s) $, $ B \\to (q) $, $ C \\to (p) $, $ D \\to (r) $","image_url":null,"alt":null},{"text":"$$ A\\to(r),B\\to(p),C\\to(s),D\\to(q) $$","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Identify compound (A).

 $$  CH_{2}=CH-CH_{2}Cl $$ 

contains halogen adjacent to double bond.

Hence it is:

allylic halide

Thus:

 $$ A\to(s) $$ 

Step 2: Identify compound (B).

 $$  CH_{2}=CHX $$ 

has halogen directly attached to double bonded carbon.

Hence:

vinylic halide

Thus:

 $$ B\to(q) $$ 

Step 3: Identify compound (C).

 $$  CH_{3}CHCl_{2} $$ 

has both chlorine atoms attached to the same carbon.

Hence:

gem-dichloride

Thus:

 $$ C\to(p) $$ 

Step 4: Identify compound (D).

 $$ \mathrm{CH}_{2}\mathrm{Cl}\mathrm{CH}_{2}\mathrm{Cl} $$ 

has chlorine atoms attached to adjacent carbons.

Hence:

vic-dichloride

Thus:

 $$ D\to(r) $$ 

Step 5: Final matching.

 $$ A\to(s),\qquad B\to(q),\qquad C\to(p),\qquad D\to(r) $$ 

Therefore:

 $$ \left|\left(\mathrm{C}\right)\mathrm{A}\rightarrow(\mathrm{s}),\mathrm{B}\rightarrow(\mathrm{q}),\mathrm{C}\rightarrow(\mathrm{p}),\mathrm{D}\rightarrow(\mathrm{r})\right. $$ 

Quick Tip: gem-dihalide:

Both halogens on same carbon

vic-dihalide:

Halogens on adjacent carbons', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5244, 5, NULL, NULL, 'To prepare 3-ethylpentan-3-ol, the reagents needed are', NULL, '[{"text":"$$ \\mathrm{CH}_{3}\\mathrm{CH}_{2}\\mathrm{MgBr}+\\mathrm{CH}_{3}\\mathrm{COCH}_{2}\\mathrm{CH}_{3} $$","image_url":null,"alt":null},{"text":"$ CH_{3}MgBr + CH_{3}CH_{2}CH_{2}COCH_{2}CH_{3} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}MgBr + CH_{3}CH_{2}COCH_{2}CH_{3} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}CH_{2}MgBr + CH_{3}COCH_{2}CH_{3} $","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Identify the target alcohol.

Given alcohol:

3-ethylpentan-3-ol

Structure:

 $$ \mathrm{CH_{3}CH_{2}-C(OH)(CH_{2}CH_{3})-CH_{2}CH_{3}} $$ 

The carbon containing:

OH

is attached to:

3 ethyl groups

Hence it is a:

tertiary alcohol

Step 2: Recall Grignard reaction.

A ketone reacts with Grignard reagent:

RMgX

to form a tertiary alcohol.

To obtain:

3-ethylpentan-3-ol

we require:

 $$  CH_{3}CH_{2}COCH_{2}CH_{3} $$ 

which is:

pentan-3-one

and:

 $$ \mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{MgBr} $$ 

Step 3: Write the reaction.

 $$ \mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{COCH}_{2}\mathrm{CH}_{3}+\mathrm{CH}_{3}\mathrm{CH}_{2}\mathrm{MgBr} $$ 

followed by hydrolysis gives:

 $$  (CH_{3}CH_{2})_{3}COH $$ 

which is:

3-ethylpentan-3-ol

Step 4: Identify the correct option.

Therefore:

 $$  (C)CH_{3}CH_{2}MgBr+CH_{3}CH_{2}COCH_{2}CH_{3} $$ 

Quick Tip: Ketone + Grignard reagent:

tertiary alcohol after hydrolysis.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.171Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5245, 5, NULL, NULL, 'Chromosomes are made from', NULL, '[{"text":"proteins","image_url":null,"alt":null},{"text":"nucleic acids","image_url":null,"alt":null},{"text":"proteins and nucleic acids","image_url":null,"alt":null},{"text":"carbohydrates and nucleic acids","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Recall the composition of chromosomes.

Chromosomes are mainly composed of:

DNA and proteins

DNA is a:

nucleic acid

