DNA + Histone proteins', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.172Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5246, 5, NULL, NULL, 'The electronic configuration of Cu(II) is

 $$ 3d^{9} $$ 

whereas that of Cu(I) is

 $$ 3d^{10} $$ 

Which of the following is correct?', NULL, '[{"text":"Cu(II) is more stable","image_url":null,"alt":null},{"text":"Cu(I) is less stable","image_url":null,"alt":null},{"text":"Cu(I) and Cu(II) are equally stable","image_url":null,"alt":null},{"text":"Stability of Cu(I) and Cu(II) depends on nature of copper salts","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Compare the electronic configurations.

 $$ \mathrm{C u(I):3d^{10}} $$ 

 $$ \mathrm{C u(I I):3d^{9}} $$ 

Configuration:

 $$ 3d^{10} $$ 

is completely filled and generally stable.

Step 2: Consider practical stability.

Although:

Cu(I)

has stable electronic configuration, its actual stability depends on:

the ligands and nature of the salt

Some compounds stabilize:

while others stabilize:

Cu(II)

Thus stability depends on surrounding chemical environment.

Step 3: Identify the correct option.

Therefore:

(D) Stability of Cu(I) and Cu(II) depends on nature of copper salts

Quick Tip: Stability of oxidation states in transition metals depends on:

ligands, hydration energy and lattice energy', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.172Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5247, 5, NULL, NULL, 'On addition of small amount of  $ KMnO_{4} $ to concentrated  $ H_{2}SO_{4} $, a green oily compound is obtained which is highly explosive in nature. Identify the compound from the following.', NULL, '[{"text":"$ Mn_{2}O_{7} $","image_url":null,"alt":null},{"text":"$ MnO_{2} $","image_url":null,"alt":null},{"text":"$ MnSO_{4} $","image_url":null,"alt":null},{"text":"$ Mn_{2}O_{3} $","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall the reaction of  $ KMnO_{4} $ with concentrated  $ H_{2}SO_{4} $.

When:

 $$ KMnO_{4} $$ 

reacts with concentrated:

 $$ H_{2}SO_{4} $$ 

a dark green oily liquid is formed:

 $$  Mn_{2}O_{7} $$ 

Reaction:

 $$ 2KMnO_{4}+2H_{2}SO_{4}\rightarrow K_{2}SO_{4}+2HMnO_{4} $$ 

 $$ 2HMnO_{4}\rightarrow Mn_{2}O_{7}+H_{2}O $$ 

Step 2: Identify the explosive compound.

 $$  Mn_{2}O_{7} $$ 

is highly unstable and explosive.

Thus the green oily liquid obtained is:

 $$  Mn_{2}O_{7} $$ 

Step 3: Identify the correct option.

Therefore:

 $$ \mathrm{(A)}\mathrm{M n}_{2}\mathrm{O}_{7} $$ 

Quick Tip:

 $$  Mn_{2}O_{7} $$ 

is manganese heptoxide:

a dark green explosive liquid', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.173Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5248, 5, NULL, NULL, 'Which of the following oxidation state is common for all lanthanoids?', NULL, '[{"text":"+2","image_url":null,"alt":null},{"text":"+3","image_url":null,"alt":null},{"text":"+4","image_url":null,"alt":null},{"text":"+5","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the common oxidation state of lanthanoids.

Lanthanoids generally lose:

2 electrons from 6s

and:

1 electron from 5d or 4f

Thus the most stable and common oxidation state is:

+3

Step 2: Analyze other oxidation states.

Some lanthanoids may also show:

+2 or +4

but these are not common to all lanthanoids.

Step 3: Identify the correct option.

Therefore:

 $$ \left|\mathrm{~(B)~+3~}\right| $$ 

Quick Tip: Most common oxidation state of lanthanoids:

due to stable removal of:

 $$ 6s^{2} $$ 

and one additional electron.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.173Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5249, 5, NULL, NULL, 'The magnetic nature of elements depends on the presence of unpaired electrons. Identify the configuration of transition element, which shows highest magnetic moment.', NULL, '[{"text":"$ 3d^{7} $","image_url":null,"alt":null},{"text":"$ 3d^{5} $","image_url":null,"alt":null},{"text":"$ 3d^{8} $","image_url":null,"alt":null},{"text":"$ 3d^{2} $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the formula for magnetic moment.

Magnetic moment depends on number of unpaired electrons:

 $$ \mu=\sqrt{n(n+2)}BM $$ 

where:

n = number of unpaired electrons

Step 2: Find unpaired electrons in each configuration.

 $ 3d^{7} \Rightarrow 3 $ unpaired electrons

 $ 3d^{5} \Rightarrow 5 $ unpaired electrons

 $$ 3d^{8}\Rightarrow2{\mathrm{~u n p a i r e d~e l e c t r o n s}} $$ 

###  $ 3d^{2} \Rightarrow 2 $ unpaired electrons

Step 3: Identify highest magnetic moment.

Maximum magnetic moment corresponds to maximum number of unpaired electrons.

Thus:

 $$ 3d^{5} $$ 

has highest magnetic moment.

Step 4: Identify the correct option.

Therefore:

 $$ (B)\;3d^{5} $$ 

Quick Tip: Greater the number of unpaired electrons:

greater the magnetic moment.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.173Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5250, 5, NULL, NULL, 'For a first-order reaction, if the time taken for 90% completion is t, what will be the approximate time taken for 99.9% completion of the same reaction?', NULL, '[{"text":"2t","image_url":null,"alt":null},{"text":"3t","image_url":null,"alt":null},{"text":"4t","image_url":null,"alt":null},{"text":"1.5t","image_url":null,"alt":null}]', NULL, 1, 'Concept: For a first-order kinetic process, the integrated rate equation is defined as:

 $$ k=\frac{2.303}{t}\log\left(\frac{\left[A\right]_{0}}{\left[A\right]_{t}}\right) $$ 

Where  $ [A]_{0} $ is the initial concentration and  $ [A]_{t} $ is the remaining reactant concentration at time t.

Step 1: Expressing time for 90% completion ( $ t_{90\%} $).

When the reaction is 90% complete, the remaining concentration is  $ [A]_t = [A]_0 - 0.90[A]_0 = 0.10[A]_0 $.

 $$ t=\frac{2.303}{k}\log\left(\frac{\left[A\right]_{0}}{0.10[A]_{0}}\right)=\frac{2.303}{k}\log(10)=\frac{2.303}{k}\quad\cdots(1) $$ 

Step 2: Expressing time for 99.9% completion ( $ t_{99.9\%} $).

When the reaction is 99.9% complete, the remaining concentration is  $ [A]_{t} = [A]_{0} - 0.999[A]_{0} = 0.001[A]_{0} = 10^{-3}[A]_{0} $.

 $$ t_{99.9\%}=\frac{2.303}{k}\log\left(\frac{[A]_{0}}{10^{-3}[A]_{0}}\right)=\frac{2.303}{k}\log(10^{3})=3\times\frac{2.303}{k}\quad\cdots(2) $$ 

Substituting equation (1) into equation (2) directly yields  $ t_{99.9\%}=3t $.

Quick Tip: For first-order kinetics, logarithmic ratios simplify to highly structured scaling constants:  $ t_{99.9\%} = 3 \times t_{90\%} $ and  $ t_{99\%} = 2 \times t_{90\%} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.175Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5251, 5, NULL, NULL, 'According to collision theory, increasing the starting concentration of a collection of reacting molecules directly results in a change in which of the following system factors?', NULL, '[{"text":"Activation energy","image_url":null,"alt":null},{"text":"Collision frequency","image_url":null,"alt":null},{"text":"Rate constant","image_url":null,"alt":null},{"text":"Fraction of molecules with energy greater than activation energy","image_url":null,"alt":null}]', NULL, 1, 'Concept: Collision theory models reaction rates based on effective interactions between molecules per unit volume per second, mathematically formulated as:

 $$  Rate=Z_{AB}\cdot e^{-\frac{E_{a}}{RT}} $$ 

Where  $ Z_{AB} $ is the collision frequency factor.

Step 1: Analyzing the effect of crowded molecular environments.

Increasing reactant concentration places more molecules inside the same spatial boundaries. This physical crowding directly maximizes structural encounters, leading to a major increase in the collision frequency ( $ Z_{AB} $). Factors like activation energy ( $ E_{a} $) and the energetic fraction depend exclusively on temperature and catalysts.

Quick Tip: Concentration adjustments physically manipulate the collision frequency (Z). Changing the temperature adjusts both the rate constant (k) and the fraction of high-energy molecules.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.176Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5252, 5, NULL, NULL, 'What is the cell potential ( $ E_{cell} $) for a concentration cell consisting of two hydrogen electrodes at 298 K, where the anode compartment is at pH = 3 and the cathode compartment is at pH = 1 under standard pressure conditions?', NULL, '[{"text":"0.0591 V","image_url":null,"alt":null},{"text":"0.1182 V","image_url":null,"alt":null},{"text":"-0.1182 V","image_url":null,"alt":null},{"text":"0.0000 V","image_url":null,"alt":null}]', NULL, 1, 'Concept: For identical chemical electrodes forming a concentration cell,  $ E_{\text{cell}}^{\circ} = 0 \, \text{V} $. The overall potential is generated by concentration gradients according to the Nernst Equation:

 $$ E_{\mathrm{c e l l}}=-\frac{0.0591}{n}\log\left(\frac{[\mathrm{H^{+}}]_{anode}}{[\mathrm{H^{+}}]_{cathode}}\right) $$ 

Step 1: Convert pH indices to active ion molarity.

Using the standard relationship  $ \mathrm{pH} = -\log[\mathrm{H}^{+}] $:

 $$ [\mathrm{H}^{+}]_{\mathrm{a n o d e}}=10^{-3}\:\mathrm{M},\quad[\mathrm{H}^{+}]_{\mathrm{c a t h o d e}}=10^{-1}\:\mathrm{M} $$ 

Step 2: Calculate potential with single-electron transfer (n = 1).

 $$ E_{\mathrm{c e l l}}=-\frac{0.0591}{1}\log\left(\frac{10^{-3}}{10^{-1}}\right)=-0.0591\log(10^{-2}) $$ 

 $$ E_{cell}=-0.0591\times(-2)=0.1182V $$ 

Quick Tip: For symmetrical hydrogen ion concentration cells at 298 K, you can use this simple shortcut:  $ E_{\text{cell}} = 0.0591 \times (\text{pH}_{\text{anode}} - \text{pH}_{\text{cathode}}) $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.178Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5253, 5, NULL, NULL, 'Which of the following expressions correctly relates the limiting molar conductivity ( $ \Lambda_{m}^{\circ} $) of aluminum sulfate,  $ \mathrm{Al}_{2}(\mathrm{SO}_{4})_{3} $, to its individual ionic components according to Kohlerausch''s Law?', NULL, '[{"text":"$ \\Lambda_{m}^{\\circ}=\\lambda^{\\circ}(\\mathrm{Al}^{3+})+\\lambda^{\\circ}(\\mathrm{SO}_{4}^{2-}) $","image_url":null,"alt":null},{"text":"$ \\Lambda_{m}^{\\circ}=2\\lambda^{\\circ}(\\mathrm{Al}^{3+})+3\\lambda^{\\circ}(\\mathrm{SO}_{4}^{2-}) $","image_url":null,"alt":null},{"text":"$ \\Lambda_{m}^{\\circ}=3\\lambda^{\\circ}(\\mathrm{Al}^{3+})+2\\lambda^{\\circ}(\\mathrm{SO}_{4}^{2-}) $","image_url":null,"alt":null},{"text":"$ \\Lambda_{m}^{\\circ}=\\frac{1}{2}\\lambda^{\\circ}(\\mathrm{Al}^{3+})+\\frac{1}{3}\\lambda^{\\circ}(\\mathrm{SO}_{4}^{2-}) $","image_url":null,"alt":null}]', NULL, 1, 'Concept: Kohlrausch''s law of independent migration of ions states that the total limiting molar conductivity of an electrolyte equals the sum of the individual contributions from its cations and anions:

 $$ \Lambda_{m}^{\circ}=\nu_{+}\lambda_{+}^{\circ}+\nu_{-}\lambda_{-}^{\circ} $$ 

Where  $ v_{+} $ and  $ v_{-} $ denote the stoichiometric coefficients of the positive and negative ions.

Step 1: Analyze the complete dissociation process.

One formula unit of aluminum sulfate dissociates completely in water according to this equilibrium:

 $$ \mathrm{Al}_{2}(\mathrm{SO}_{4})_{3}(s)\xrightarrow{\mathrm{H}_{2}\mathrm{O}}2\mathrm{Al}^{3+}(aq)+3\mathrm{SO}_{4}^{2-}(aq) $$ 

Here,  $ \nu_{+}=2 $ and  $ \nu_{-}=3 $. Substituting these values yields:

 $$ \Lambda_{m}^{\circ}=2\lambda^{\circ}(\mathrm{A l}^{3+})+3\lambda^{\circ}(\mathrm{S O}_{4}^{2-}) $$ 

Quick Tip: Always scale the individual ionic values by the balance coefficients for molar conductivity. For equivalent conductivity, these stoichiometric coefficients are normalized.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.180Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5254, 5, NULL, NULL, 'What is the correct increasing order of basic strength for the following amines when measured inside an aqueous medium?

(I)  $  \text{CH}_3\text{NH}_2  $, (II)  $  (\text{CH}_3)_2\text{NH}  $, (III)  $  (\text{CH}_3)_3\text{N}  $, (IV)  $  \text{NH}_3  $', NULL, '[{"text":"IV < III < I < II","image_url":null,"alt":null},{"text":"IV < I < II < III","image_url":null,"alt":null},{"text":"III < I < II < IV","image_url":null,"alt":null},{"text":"I < II < III < IV","image_url":null,"alt":null}]', NULL, 0, 'Concept: In an aqueous medium, the basicity of aliphatic amines depends on three competing structural factors: inductive electron donation (+I), steric hindrance, and hydration stabilization of the resulting conjugate cation via hydrogen bonding.

Step 1: Evaluate the combined trends for methyl-substituted amines.

• Inductive effect trend: Secondary > Tertiary > Primary  $ (2^{\circ} > 3^{\circ} > 1^{\circ}) $.

• Hydration energy trend: Primary > Secondary > Tertiary  $ (1^{\circ} > 2^{\circ} > 3^{\circ}) $.

Combining these factors creates an energy balance, giving an absolute basicity sequence of  $ 2^\circ > 1^\circ > 3^\circ > NH_3 $. Arranging these from lowest to highest yields:  $ NH_3 < (CH_3)_3N < CH_3NH_2 < (CH_3)_2NH $. This matches sequence IV < III < I < II.

Quick Tip: Remember these structural trends for aqueous amines to save time: For Methyl groups, use sequence  $ 213 (2^\circ > 1^\circ > 3^\circ) $. For Ethyl groups, use sequence  $ 231 (2^\circ > 3^\circ > 1^\circ) $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.180Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5255, 5, NULL, NULL, 'An organic compound with the molecular formula  $ C_{7}H_{8}O $ is completely insoluble in water but dissolves readily in an aqueous NaOH solution. When treated with bromine water, it forms a white precipitate. Identify the compound.', NULL, '[{"text":"Benzyl alcohol","image_url":null,"alt":null},{"text":"Anisole","image_url":null,"alt":null},{"text":"o-Cresol","image_url":null,"alt":null},{"text":"Methoxybenzene","image_url":null,"alt":null}]', NULL, 2, 'Concept: We can determine structural properties based on characteristic solubility trends:

- Phenols are acidic enough to react with strong bases like NaOH, forming water-soluble sodium phenoxide salts. Alcohols and ethers do not react.

- The strongly activating hydroxyl group on the ring drives extremely rapid electrophilic substitution reactions.

### Step 1: Narrow down functional classes based on basic solubility.

The formula  $ C_7H_8O $ matches structural isomers like benzyl alcohol, anisole, and cresols. Because this compound reacts and dissolves in NaOH, it must be a phenol variant (o-cresol).

Step 2: Verify electrophilic addition behavior.

Treating o-cresol with bromine water causes rapid ring bromination at available ortho and para positions, generating a characteristic halogenated white precipitate.

Quick Tip: Organic molecules that dissolve cleanly in aqueous NaOH but fail to react or evolve gas in weaker NaHCO₃ contain a phenolic hydroxyl group.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.181Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5256, 5, NULL, NULL, 'Which of the following coordination complex ions exhibits structural asymmetry leading to optical isomerism?', NULL, '[{"text":"trans- $ [\\mathrm{Co(en)_{2}Cl_{2}}] $^{+}","image_url":null,"alt":null},{"text":"cis-[Co(en) $ _{2} $Cl $ _{2} $] $ ^{+} $","image_url":null,"alt":null},{"text":"$ [\\mathrm{Co}(\\mathrm{NH}_{3})_{4}\\mathrm{Cl}_{2}]^{+} $","image_url":null,"alt":null},{"text":"$ [Cr(NH_{3})_{5}Cl]^{2+} $","image_url":null,"alt":null}]', NULL, 1, 'Concept: A coordination complex displays optical activity if it forms non-superimposable mirror images. This structural condition requires the compound to lack an internal plane of symmetry ( $ \sigma $) and a center of inversion (i).

Step 1: Evaluate internal geometric symmetry elements.

The trans − [Co(en) $ _2 $Cl $ _2 $] $ ^+ $ configuration distributes its ligands directly opposite each other across a central inversion plane, making it symmetrical and optically inactive.

In the cis –  $ [\mathrm{Co}(\mathrm{en})_2\mathrm{Cl}_2]^+ $ isomer, the bidentate ethylenediamine ligands are placed adjacent to each other. This geometry removes all internal symmetry planes, resulting in a chiral core that forms stable  $ d $- and  $ l $-mirror image pairs.

Quick Tip: Octahedral metal configurations of the general type  $ [M(AA)_2X_2] $ with bidentate chelating rings display optical activity exclusively in their cis arrangements.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.182Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5257, 5, NULL, NULL, 'Using Crystal Field Theory (CFT), what is the correct electronic configuration and magnetic behavior of the high-spin complex  $ [\mathrm{Fe}(\mathrm{H}_{2}\mathrm{O})_{6}]^{2+} $?', NULL, '[{"text":"$ t_{2g}^{4}e_{g}^{2} $, Paramagnetic","image_url":null,"alt":null},{"text":"$ t_{2g}^{6}e_{g}^{0} $, Diamagnetic","image_url":null,"alt":null},{"text":"$ t_{2g}^{3}e_{g}^{3} $, Paramagnetic","image_url":null,"alt":null},{"text":"$ t_{2g}^{5}e_{g}^{1} $, Paramagnetic","image_url":null,"alt":null}]', NULL, 0, 'Concept: In an octahedral coordination field, $d$-orbitals split into lower energy $t_{2g}$ and higher energy $e_g$ levels. Weak-field ligands have a splitting energy smaller than the pairing energy ($\Delta_o < P$), which creates a high-spin configuration.

Step 1: Find the oxidation state and valence electrons.

Water is a neutral ligand, meaning Fe has an oxidation state of +2. The electron configuration of an Fe^{2+} ion is [Ar]3d^{6}.

Step 2: Distribute electrons based on weak-field rules.

Because  $ H_{2}O $ is a weak-field ligand, electrons fill all five orbital sub-levels singly before any pairing occurs:

• Place the first 3 electrons singly in the lower tier:  $ t_{2g}^{3} $

• Place the next 2 electrons singly in the upper tier:  $ e_{g}^{2} $

• Place the final 6th electron in the lower tier to pair up:  $ t_{2g}^{4} e_{g}^{2} $

This arrangement results in 4 unpaired electrons, making the complex paramagnetic.

Quick Tip: For  $ d^4 $ through  $ d^7 $ metals, look at the ligand field strength: Weak-field ligands keep systems in a high-spin state ( $ \Delta_o < P $), while strong-field ligands force low-spin configurations ( $ \Delta_o > P $).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.183Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5258, 5, NULL, NULL, 'Which of the following alkyl halides will undergo the fastest rate of nucleophilic substitution via an  $ S_{N}1 $ mechanism when treated with an aqueous nucleophile?', NULL, '[{"text":"CH_{3}Cl","image_url":null,"alt":null},{"text":"$ (\\mathrm{CH}_{3})_{3}\\mathrm{CCl} $","image_url":null,"alt":null},{"text":"$ CH_{3}CH_{2}Cl $","image_url":null,"alt":null},{"text":"$ (\\mathrm{CH}_{3})_{2}\\mathrm{CHCl} $","image_url":null,"alt":null}]', NULL, 1, 'Concept: The rate-determining step of an  $ S_{N} $1 substitution mechanism is the unimolecular dissociation of the leaving group to form a carbocation intermediate:

 $$ \mathrm{R}-\mathrm{X}\xrightarrow{\mathrm{Slow}}\mathrm{R}^{+}+\mathrm{X}^{-} $$ 

The overall reaction rate depends directly on the stability of this intermediate carbocation.

Step 1: Evaluate intermediate carbocation stability trends.

Comparing the carbocations formed when the leaving groups dissociate:

•  $ CH_{3}Cl \rightarrow CH_{3}^{+} $ (Methyl carbocation, highly unstable)

•  $ CH_{3}CH_{2}Cl \rightarrow CH_{3}CH_{2}^{+} $ (1° Primary carbocation)

•  $ (CH_{3})_{2}CHCl \rightarrow (CH_{3})_{2}CH^{+} $ (2° Secondary carbocation)

 $ \mathrm{(CH_{3})_{3}CCl \rightarrow (} $

 $ text{CH}_3)_3C^+ $ (3° Tertiary carbocation, stabilized by 9 hyperconjugative  $ \alpha $-hydrogens)

The tertiary halide dissociates fastest because it forms the most stable intermediate carbocation.

Quick Tip: Carbocation stability and  $ S_{N}1 $ reaction rates follow the exact same structural trend: Tertiary  $ (3^{\circ}) > \text{Secondary } (2^{\circ}) > \text{Primary } (1^{\circ}) > \text{Methyl} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.183Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5259, 5, NULL, NULL, 'Arrange the following compounds in increasing order of acidic strength:

#### Phenol, Water, Propan-1-ol, Propan-2-ol', NULL, '[{"text":"Water < Propan-2-ol < Propan-1-ol < Phenol","image_url":null,"alt":null},{"text":"Propan-2-ol < Propan-1-ol < Water < Phenol","image_url":null,"alt":null},{"text":"Propan-1-ol < Propan-2-ol < Water < Phenol","image_url":null,"alt":null},{"text":"Phenol < Water < Propan-1-ol < Propan-2-ol","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Acidic strength depends upon the ease with which a compound can donate a proton ( $ H^{+} $). Greater stability of the conjugate base formed after loss of proton means stronger acidity.

• Alkyl groups show +I effect and decrease acidity.

• Branching increases electron donation and further decreases acidity.

- Phenoxide ion formed from phenol is resonance stabilized, making phenol highly acidic.

#### Step 1: Compare propan-1-ol and propan-2-ol.

In propan-2-ol, the carbon attached to –OH group has two alkyl groups, producing stronger +I effect.

This destabilizes the alkoxide ion formed after removal of proton.

Hence:

 $$  Propan-2-ol<Propan-1-ol $$ 

#### Step 2: Compare alcohols with water.

Water does not contain electron donating alkyl groups, so the hydroxide ion formed is comparatively more stable.

Therefore:

 $$ \mathrm{Propan-2-ol}<\mathrm{Propan-1-ol}<\mathrm{Water} $$ 

Step 3: Compare phenol with water.

Phenol forms phenoxide ion after losing proton.

 $$  C_{6}H_{5}OH\rightarrow C_{6}H_{5}O^{-}+H^{+} $$ 

Phenoxide ion is resonance stabilized because the negative charge is delocalized over the benzene ring.

Hence phenol is most acidic.

 $$  Propan-2-ol<Propan-1-ol<Water<Phenol $$ 

Quick Tip: Resonance stabilization increases acidity, while electron donating +I effect decreases acidity.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.187Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5260, 5, NULL, NULL, 'Among the following amines, the strongest base in aqueous solution is:

 $$  NH_{3},CH_{3}NH_{2},(CH_{3})_{2}NH,(CH_{3})_{3}N $$', NULL, '[{"text":"$ NH_{3} $","image_url":null,"alt":null},{"text":"$ (\\mathrm{CH}_{3})_{3}\\mathrm{N} $","image_url":null,"alt":null},{"text":"( $ CH_{3})_{2}NH $","image_url":null,"alt":null},{"text":"$ CH_{3}NH_{2} $","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Basic strength of amines depends upon:

• Availability of lone pair on nitrogen atom.

• Electron donating + I effect of alkyl groups.

• Stability of the protonated amine in aqueous solution due to solvation.

In gaseous state:

 $$ 3^{\circ}>2^{\circ}>1^{\circ}>NH_{3} $$ 

But in aqueous solution, solvation plays an important role. Secondary amines become most basic because they have:

• Strong + I effect

• Effective solvation

Hence:

 $$ 2^{\circ}>1^{\circ}>3^{\circ}>NH_{3} $$ 

Step 1: Understand the effect of alkyl groups.

Methyl groups donate electrons toward nitrogen through +I effect, increasing electron density on nitrogen and making the amine more basic.

 $$  NH_{3}<CH_{3}NH_{2}<(CH_{3})_{2}NH $$ 

##### Step 2: Compare tertiary amine in aqueous medium.

Although tertiary amine has maximum +I effect, its protonated form is less stabilized due to poor solvation because of steric hindrance.

Therefore:

 $$ (CH_{3})_{3}N<(CH_{3})_{2}NH $$ 

Step 3: Final order of basic strength in aqueous solution.

 $$ \mathrm{(C H_{3})_{2}N H>C H_{3}N H_{2}>(C H_{3})_{3}N>N H_{3}} $$ 

Hence, the strongest base is:

 $$ (\mathrm{C H}_{3})_{2}\mathrm{N H} $$ 

Quick Tip: For amines in aqueous solution:

 $$ 2^{\circ}\ \mathrm{amine}>1^{\circ}\ \mathrm{amine}>3^{\circ}\ \mathrm{amine} $$ 

because solvation of protonated amines is very important.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.188Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5261, 5, NULL, NULL, 'Lucas reagent gives immediate turbidity with:', NULL, '[{"text":"Ethanol","image_url":null,"alt":null},{"text":"Propan-1-ol","image_url":null,"alt":null},{"text":"Propan-2-ol","image_url":null,"alt":null},{"text":"tert-Butyl alcohol","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Lucas reagent is a mixture of:

 $$ \mathrm{Conc.~HCl+A n h y d r o u s~Z n C l_{2}} $$ 

It is used to distinguish primary, secondary and tertiary alcohols.

• Tertiary alcohols react immediately.

• Secondary alcohols react within few minutes.

• Primary alcohols react very slowly.

Turbidity appears due to formation of insoluble alkyl chlorides.

Step 1: Understand reactivity order.

Tertiary alcohols form highly stable tertiary carbocations.

Hence substitution reaction occurs rapidly through  $ S_{N} $ 1 mechanism.

 $$ 3^{\circ}>2^{\circ}>1^{\circ} $$ 

#### Step 2: Identify tertiary alcohol.

Among the given compounds:

tert-Butyl alcohol

is a tertiary alcohol.

Step 3: Conclusion.

Therefore it gives immediate turbidity with Lucas reagent.

tert-Butyl alcohol

Quick Tip: Lucas reagent test:

 $ 3^{\circ} $ alcohol  $ \rightarrow $ Immediate turbidity

 $ 2^{\circ} $ alcohol  $ \rightarrow $ Slow turbidity

 $ 1^{\circ} $ alcohol  $ \rightarrow $ No turbidity at room temperature', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.188Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5262, 5, NULL, NULL, 'Which of the following compounds has the highest boiling point?', NULL, '[{"text":"Propane","image_url":null,"alt":null},{"text":"Propanal","image_url":null,"alt":null},{"text":"Propan-1-ol","image_url":null,"alt":null},{"text":"Dimethyl ether","image_url":null,"alt":null}]', NULL, 2, '#### Concept:

Boiling point depends upon intermolecular forces.

• Hydrogen bonding causes maximum attraction.

• Dipole-dipole interactions are weaker.

• Van der Waals forces are weakest.

Step 1: Analyze intermolecular forces.

- Propane contains only weak Van der Waals forces.

• Propanal and dimethyl ether contain dipole-dipole interactions.

• Propan-1-ol contains intermolecular hydrogen bonding.

#### Step 2: Compare boiling points.

Hydrogen bonding significantly increases boiling point because extra energy is required to break intermolecular attractions.

Therefore:

Propan-1-ol

has maximum boiling point.

Step 3: Final conclusion.

Propan-1-ol

Quick Tip: Compounds capable of intermolecular hydrogen bonding generally possess higher boiling points.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.189Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5263, 5, NULL, NULL, 'Among the following, the compound having the lowest value of  $ pK_{a} $ is:', NULL, '[{"text":"Ethanol","image_url":null,"alt":null},{"text":"Water","image_url":null,"alt":null},{"text":"Phenol","image_url":null,"alt":null},{"text":"Propan-2-ol","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Lower value of  $ pK_{a} $ indicates stronger acidity.

 $$ p K_{a}=-\log K_{a} $$ 

Hence:

Smaller  $ pK_{a} \Rightarrow $ Greater acidity

Acidic strength depends upon the stability of conjugate base formed after removal of proton.

Step 1: Compare alcohols and water.

Alcohols contain alkyl groups which show +I effect and destabilize alkoxide ions.

Therefore alcohols are less acidic than water.

 $$  Propan-2-ol<Ethanol<Water $$ 

Step 2: Analyze phenol.

Phenol forms phenoxide ion:

 $$  C_{6}H_{5}OH\rightarrow C_{6}H_{5}O^{-}+H^{+} $$ 

The negative charge on oxygen gets delocalized over the benzene ring through resonance.

Hence phenoxide ion becomes highly stable.

Step 3: Determine lowest  $ pK_{a} $.

Since phenol is most acidic among the given compounds, it has the lowest  $ pK_{a} $.

Phenol

Quick Tip: Greater the acidic strength, smaller is the value of $pK_{a}$.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.190Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5264, 5, NULL, NULL, 'Which of the following compounds gives a positive Hinsberg test and forms a soluble sulphonamide?', NULL, '[{"text":"Aniline","image_url":null,"alt":null},{"text":"Dimethylamine","image_url":null,"alt":null},{"text":"Trimethylamine","image_url":null,"alt":null},{"text":"Triphenylamine","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Hinsberg reagent is:

#### Benzenesulphonyl chloride

It is used to distinguish primary, secondary and tertiary amines.

• Primary amines form sulphonamides soluble in alkali.

• Secondary amines form insoluble sulphonamides.

• Tertiary amines do not react.

##### Step 1: Understand the reaction of primary amines.

Primary amines contain one replaceable hydrogen atom attached to nitrogen.

They react with Hinsberg reagent to form sulphonamides having acidic hydrogen.

These dissolve in alkali due to salt formation.

Step 2: Identify the primary amine.

Among the given compounds:

 $$ \mathrm{A n i l i n e~(C_{6}H_{5}N H_{2})} $$ 

is a primary amine.

Step 3: Conclusion.

Hence aniline forms soluble sulphonamide in Hinsberg test.

Aniline



<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>1° amine → Soluble product</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2° amine → Insoluble product</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>3° amine → No reaction</td></tr></table>', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.190Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5265, 5, NULL, NULL, 'The compound which is most basic in gaseous phase is:', NULL, '[{"text":"Ammonia","image_url":null,"alt":null},{"text":"Methylamine","image_url":null,"alt":null},{"text":"Dimethylamine","image_url":null,"alt":null},{"text":"Trimethylamine","image_url":null,"alt":null}]', NULL, 3, 'Concept:

In gaseous phase, solvation effects are absent.

Hence basicity depends mainly upon:

• Electron donating + I effect of alkyl groups.

• Availability of lone pair on nitrogen.

More alkyl groups increase electron density on nitrogen and increase basic strength.

Step 1: Understand inductive effect.

Alkyl groups donate electrons toward nitrogen through +I effect.

Therefore:

 $$  NH_{3}<CH_{3}NH_{2}<(CH_{3})_{2}NH<(CH_{3})_{3}N $$ 

Step 2: Analyze gaseous phase condition.

Since no hydration or solvation occurs in gaseous phase, steric hindrance does not reduce basicity significantly.

Hence tertiary amine becomes strongest base.

Step 3: Final conclusion.

 $$ (\mathrm{CH}_{3})_{3}\mathrm{N} $$ 

Quick Tip: In gaseous phase:

 $$ 3^{\circ}>2^{\circ}>1^{\circ}>NH_{3} $$ 

because only +I effect dominates.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.191Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5266, 5, NULL, NULL, 'Which of the following compounds can show metamerism?', NULL, '[{"text":"Propanal","image_url":null,"alt":null},{"text":"Propanone","image_url":null,"alt":null},{"text":"Methoxyethane","image_url":null,"alt":null},{"text":"Ethanol","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Metamerism arises due to different alkyl groups attached on either side of a polyvalent functional group.

Common functional groups showing metamerism:

Ether  $ (-O- $

• Secondary amine  $ (-NH-) $

• Ketone  $ (-CO- $

Step 1: Understand structure requirement.

For metamerism:

 $$ \boldsymbol{R}-\boldsymbol{X}-\boldsymbol{R}^{\prime} $$ 

must be possible where R and  $ R'' $ are different alkyl groups.

Step 2: Analyze each compound.

- Propanal does not possess suitable polyvalent atom.

- Propanone has only one possible arrangement for three carbons.

• Methoxyethane is an ether and can exhibit metamerism.

• Ethanol cannot show metamerism.

Step 3: Conclusion.

Methoxyethane

Quick Tip: Ethers commonly show metamerism because oxygen can connect two different alkyl groups.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.193Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5267, 5, NULL, NULL, 'The half-life of a first order reaction is 1386 s. The rate constant k is:', NULL, '[{"text":"$ 5 \\times 10^{-4} $ s $ ^{-1} $","image_url":null,"alt":null},{"text":"$ 2 \\times 10^{-4} \\, s^{-1} $","image_url":null,"alt":null},{"text":"$ 1 \\times 10^{-3} \\, s^{-1} $","image_url":null,"alt":null},{"text":"$ 4\\times10^{-3}\\ s^{-1} $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

For a first order reaction:

 $$ t_{1/2}=\frac{0.693}{k} $$ 

where:

•  $ t_{1/2} $ = half-life

• k = rate constant

Step 1: Write the formula.

 $$ k=\frac{0.693}{t_{1/2}} $$ 

Step 2: Substitute the given value.

 $$ k=\frac{0.693}{1386} $$ 

 $$ k=5\times10^{-4}s^{-1} $$ 

Step 3: Final answer.

 $$ 5\times10^{-4}\mathrm{s}^{-1} $$ 

Quick Tip: For first order reactions:

 $$ t_{1/2}\propto\frac{1}{k} $$ 

Half-life is independent of initial concentration.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.195Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5268, 5, NULL, NULL, 'Which of the following biomolecules acts as the genetic material in most organisms?', NULL, '[{"text":"Protein","image_url":null,"alt":null},{"text":"DNA","image_url":null,"alt":null},{"text":"Lipid","image_url":null,"alt":null},{"text":"Polysaccharide","image_url":null,"alt":null}]', NULL, 1, '##### Concept:

Biomolecules are chemical compounds present in living organisms.

DNA stands for:

##### Deoxyribonucleic Acid

It carries hereditary information from one generation to another.

##### Step 1: Understand the role of DNA.

DNA contains genes responsible for inheritance and expression of characters.

It stores biological information in the sequence of nitrogenous bases.

Step 2: Analyze other biomolecules.

• Proteins mainly perform structural and enzymatic functions.

• Lipids store energy and form membranes.

• Polysaccharides mainly act as energy reserves.

Step 3: Conclusion.

Hence DNA acts as genetic material in most organisms.

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-21-shift-1/q10-exp-1.jpg" alt="Figure 1 for question 10" /></div>


Quick Tip: RNA acts as genetic material only in some viruses, while DNA is the genetic material in most living organisms.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.196Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5269, 5, NULL, NULL, 'Which of the following carbonyl compounds will undergo a self-oxidation and self-reduction reaction (Cannizzaro Reaction) when treated with a concentrated solution of a strong base (NaOH)?', NULL, '[{"text":"Acetaldehyde ( $ CH_{3}CHO $)","image_url":null,"alt":null},{"text":"Benzaldehyde ( $ C_{6}H_{5}CHO $)","image_url":null,"alt":null},{"text":"Acetone ( $ CH_{3}COCH_{3} $)","image_url":null,"alt":null},{"text":"Propanal ( $ CH_{3}CH_{2}CHO $)","image_url":null,"alt":null}]', NULL, 1, 'Concept: The **Cannizzaro Reaction** is a redox disproportionate reaction characteristic of

aldehydes that completely **lack any  $ \alpha $-hydrogen atoms**. When exposed to a concentrated strong base, one molecule of the aldehyde is reduced to a primary alcohol, while another molecule is oxidized to a carboxylic acid salt.

Step 1: Check for the presence of  $ \alpha $-hydrogens in each option.

An  $ \alpha $-hydrogen is any hydrogen atom attached to the carbon atom immediately adjacent to the carbonyl functional group (C=O).

- **Acetaldehyde ( $ CH_{3}CHO $):** The methyl carbon has 3 active  $ \alpha $-hydrogens. It undergoes Aldol Condensation instead.

- **Acetone ( $ CH_{3}COCH_{3} $):** **Contains 6 total  $ \alpha $-hydrogens, making it highly reactive under Aldol pathways.

**Propanal (CH₃CH₂CHO):** The central CH₂ group contains 2 active  $ \alpha $-hydrogens.

##### Step 2: Identify the compound lacking  $ \alpha $-hydrogens.

In  $ {}^{**} $Benzaldehyde (C $ _6 $H $ _5 $CHO) $ {}^{**} $, the carbonyl group is attached directly to an aromatic ring carbon that has no remaining hydrogen atoms. Because it completely lacks an  $ \alpha $-hydrogen, it undergoes the Cannizzaro reaction.

Quick Tip: The two most common examples of aldehydes that lack  $ \alpha $-hydrogens in the NCERT curriculum are **Formaldehyde (HCHO)** and ****Benzaldehyde ( $ C_{6}H_{5}CHO $)**. Keep these memorized for quick name reaction classification questions.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.199Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5270, 5, NULL, NULL, 'Determine the spin-only magnetic moment value for a central divalent manganese gaseous ion ( $ Mn^{2+} $) based on its d-orbital electron distribution. (Atomic Number of Mn = 25)', NULL, '[{"text":"4.90 BM","image_url":null,"alt":null},{"text":"1.73 BM","image_url":null,"alt":null},{"text":"3.87 BM","image_url":null,"alt":null},{"text":"5.92 BM","image_url":null,"alt":null}]', NULL, 3, 'Concept: The spin-only magnetic moment ( $ \mu $) of a transition metal ion depends on the total

number of unpaired d-orbital electrons (n) present in its valence shell, calculated using the formula:

 $$ \mu=\sqrt{n(n+2)}\mathrm{~B o h r~M a g n e t o n s~(B M)} $$ 

Step 1: Determine the electronic configuration of the divalent ion.

The neutral ground state configuration of Manganese  $ (Z = 25) $ is:

 $$  Mn=\left[Ar\right]3d^{5}4s^{2} $$ 

Forming the divalent ion  $ (Mn^{2+}) $ requires removing the two outer valence electrons from the 4s orbital first:

 $$  Mn^{2+}=[Ar]3d^{5}4s^{0} $$ 

Step 2: Count the number of unpaired electrons using Hund''s Rule.

The d subshell contains 5 separate degenerate orbitals. Distributing 5 electrons across these orbitals following Hund''s rule gives 1 electron per orbital:

Number of unpaired electrons  $ (n)=5 $

Step 3: Substitute n into the magnetic moment equation.

Plug the value n = 5 into our formula:

 $$ \mu=\sqrt{5(5+2)}=\sqrt{5\times7}=\sqrt{35} $$ 

Since  $ \sqrt{36}=6 $, the value of  $ \sqrt{35} $ evaluates to just below 6:

 $$ \mu\approx5.92\mathrm{B M} $$ 

Quick Tip: Use this fast estimation shortcut for your exam: the first decimal digit of a spin-only magnetic moment value always matches the number of unpaired electrons (n). For example, if $n = 3$, $\mu \approx 3.8$ BM; if $n = 5$, $\mu \approx 5.9$ BM.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.200Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5271, 5, NULL, NULL, 'An organic amine compound ''X'' reacts smoothly with Hinsberg''s reagent (Benzenesulfonyl chloride) to form a solid precipitate. This precipitate remains completely insoluble when treated with an aqueous sodium hydroxide (NaOH) solution. Classify the amine ''X''.', NULL, '[{"text":"Primary Amine","image_url":null,"alt":null},{"text":"Secondary Amine","image_url":null,"alt":null},{"text":"Tertiary Amine","image_url":null,"alt":null},{"text":"Quaternary Ammonium Salt","image_url":null,"alt":null}]', NULL, 1, 'Concept: The **Hinsberg Test** is used to distinguish between primary, secondary, and tertiary amines based on how they react with benzenesulfonyl chloride ( $ C_6H_5SO_2Cl $) and whether the resulting products dissolve in an alkaline solution.

Step 1: Analyze how each type of amine behaves during the test.

- **Primary Amines:** React to form a sulfonamide that retains a highly acidic hydrogen atom on its nitrogen. This acidic hydrogen allows the product to dissolve completely in strong bases like NaOH.

- **Secondary Amines:** Reaction with the reagent to form an N,N-dialkylbenzenesulfonamide product. Because the nitrogen has no remaining acidic hydrogen atoms, this product is completely insoluble in alkali.

- **Tertiary Amines:** Lack any replaceable hydrogen atoms on the nitrogen and do not react with the test reagent under standard conditions.

Step 2: Match the compound''s behavior to the correct category.

Because compound ''X'' reacts with the reagent but forms a precipitate that does not dissolve in NaOH, it matches the characteristic behavior of a **Secondary Amine***.

Quick Tip: Keep this summary of the Hinsberg test outcomes memorized:

• Primary amine = Reacts, product **dissolves** in alkali.

• Secondary amine = Reacts, product **remains insoluble** in alkali.

• Tertiary amine = **Does not react** with the reagent at all.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.200Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5272, 5, NULL, NULL, 'According to IUPAC coordination nomenclature rules, what is the correct official name for the coordination compound represented by  $ [\mathrm{Co}(\mathrm{NH}_{3})_{5}(\mathrm{Cl})]\mathrm{Cl}_{2} $?', NULL, '[{"text":"Chloridopentaamminecobaltic chloride","image_url":null,"alt":null},{"text":"Pentaaminechloridocobalt(II) dichloride","image_url":null,"alt":null},{"text":"Pentaaminechloridocobalt(III) chloride","image_url":null,"alt":null},{"text":"Pentaamminedichloridocobalt(III) chloride","image_url":null,"alt":null}]', NULL, 2, 'Concept: Naming coordination compounds requires applying systematic IUPAC guidelines:

1. Name the ligands inside the coordination bracket first, in alphabetical order, before naming the central metal ion.

2. Stated numerical prefixes (di, tri, tetra, penta) do not alter the alphabetical priority order.

3. Specify the oxidation state of the central metal using Roman numerals in parentheses immediately after its name.

Step 1: Identify and alphabetize the ligands inside the coordination sphere.

The complex bracket contains two distinct types of ligands:

• Five neutral ammonia molecules, named as  $ {}^{**} $ammine $ {}^{**} $.

• One anionic chloride ion, named as  $ {}^{**} $chloridocon $ {}^{**} $ or  $ {}^{**} $chlorido $ {}^{**} $.

Arranging them alphabetically places "ammine" (starts with ''a'') before "chlorido" (starts with ''c''), which gives: **pentaamminechlorido**.

Step 2: Calculate the oxidation state of the central Cobalt metal.

Let the unknown oxidation state of Cobalt be x. The neutral ammine molecules carry a charge of 0, while each chloride ion carries a charge of -1:

 $$ x+5(0)+1(-1)+2(-1)=0\quad\Rightarrow\quad x-1-2=0\quad\Rightarrow\quad x=+3 $$ 

The metal is named as **cobalt(III)** because the complex ion carries a net positive charge.

Step 3: Combine the components into a single name.

Combine the alphabetized ligands, the metal with its oxidation state, and finish with the

counter-anion name outside the bracket:

# Pentaamminechloridocobalt(III) chloride

Quick Tip: Pay close attention to spelling details during the exam: the coordinated neutral ammonia ligand must always be spelled with a double ''m'' (**ammine**), whereas organic amine compounds use a single ''m'' (**amine**).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.201Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5273, 5, NULL, NULL, 'Which of the following statement options accurately describes the structural carbohydrate linkages present inside a standard molecule of Sucrose?', NULL, '[{"text":"It contains a standard C-1 to C-4 glycosidic bridge linking two identical $ \\alpha $-D-glucose rings together.","image_url":null,"alt":null},{"text":"It features a glycosidic linkage connecting the C-1 carbon of an $ \\alpha $-D-glucose unit to the C-2 carbon of a $ \\beta $-D-fructose unit.","image_url":null,"alt":null},{"text":"It consists of a C-1 to C-4 linkage binding a $ \\beta $-D-galactose ring directly onto a neighboring glucose molecule.","image_url":null,"alt":null},{"text":"It is formed by a continuous chain of $ \\beta $-D-glucose blocks linked entirely via C-1 to C-6 branch channels.","image_url":null,"alt":null}]', NULL, 1, 'Concept: Disaccharides are formed when two monosaccharides combine through a glycosidic linkage formed by a condensation reaction.

Different disaccharides differ in:

• The monosaccharides involved

• The carbon atoms participating in the linkage

• The type of glycosidic bond formed

Step 1: Identify the monosaccharides present in sucrose.

Sucrose is a disaccharide composed of:

• One molecule of  $ \alpha $-D-glucose

• One molecule of  $ \beta $-D-fructose

Thus, sucrose is formed from glucose and fructose units.

Step 2: Determine the glycosidic linkage in sucrose.

In sucrose:

• The C-1 carbon of  $ \alpha $-D-glucose

• is linked to the C-2 carbon of  $ \beta $-D-fructose

Therefore, sucrose contains:

 $$ \alpha(1\to2)\beta $$ 

glycosidic linkage.

Since both anomeric carbons are involved in bond formation, sucrose behaves as a non-reducing sugar.

Step 3: Evaluate the options.

(A) Incorrect — This describes maltose, which contains two glucose units linked by a C-1 to C-4 bond.

(B) Correct — Sucrose contains a linkage between C-1 of  $ \alpha $-D-glucose and C-2 of  $ \beta $-D-fructose.

(C) Incorrect — This describes lactose, which contains galactose and glucose.

(D) Incorrect — This does not describe sucrose structure.

Hence, the correct answer is:

Quick Tip: Important disaccharides and their linkages:

• Sucrose = Glucose + Fructose  $ \rightarrow \alpha(1 \rightarrow 2)\beta $

• Maltose = Glucose + Glucose  $ \rightarrow \alpha(1 \rightarrow 4) $

• Lactose = Galactose + Glucose  $ \rightarrow \beta(1 \rightarrow 4) $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.201Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5274, 5, NULL, NULL, 'What is the correct official unit measurement scale used to represent Molar Conductivity

( $ \Lambda_{m} $) profiles within electrolytic systems?', NULL, '[{"text":"$ S \\, cm^{-2} \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ S^{-1}\\ cm^{2}\\ mol $","image_url":null,"alt":null},{"text":"$ \\Omega\\ cm^2\\ mol^{-1} $","image_url":null,"alt":null},{"text":"S cm $ ^{2} $ mol $ ^{-1} $","image_url":null,"alt":null}]', NULL, 3, 'Concept: Molar conductivity ( $ \Lambda_{m} $) measures the electrolytic conductance capacity of a solution containing exactly one mole of dissolved electrolyte. It is mathematically related to specific conductivity ( $ \kappa $) and concentration (C) by the equation:

 $$ \Lambda_{m}=\frac{\kappa}{C} $$ 

Step 1: Analyze the base units of the individual variables.

Derive the units systematically through dimensional analysis:

- **Specific Conductivity ( $ \kappa $):** Measured in Siemens per centimeter (S cm $ ^{-1} $), where Siemens (S) represents reciprocal ohms ( $ \Omega^{-1} $).

- **Concentration (C):** Expressed in terms of solution volume as moles per cubic centimeter (mol cm $ ^{-3} $).

Step 2: Combine the units within the equation.

Substitute these units into our molar conductivity expression:

 $$  Units~of~\Lambda_{m}=\frac{S\ cm^{-1}}{mol\ cm^{-3}}=S\cdot cm^{-1}\cdot cm^{3}\cdot mol^{-1} $$ 

Simplify the overlapping centimeter exponents:

 $$ \mathrm{U n i t s~o f~}\Lambda_{m}=\mathrm{S~c m}^{2}\mathrm{m o l}^{-1} $$ 

Quick Tip: When using concentration values in moles per liter (mol L $ ^{-1} $), apply a scaling factor of 1000 to keep your units consistent:  $ \star\star\Lambda_m = \frac{\kappa \times 1000}{\text{Molarity}} \star\star $, which yields the final value directly in S cm $ ^2 $ mol $ ^{-1} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.202Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5275, 5, NULL, NULL, 'The steady, progressive decrease in the atomic and ionic radii of transition metals along the lanthanide series (Lanthanide Contraction) is primarily caused by:', NULL, '[{"text":"A continuous decrease in the absolute nuclear proton count within the central atomic cores.","image_url":null,"alt":null},{"text":"The exceptionally poor shielding effect of the diffuse 4f-electrons, which allows the increasing nuclear charge to pull the outer electron shell inward.","image_url":null,"alt":null},{"text":"The strong shielding ability of the 5d-electrons completely blocking the nuclear pull.","image_url":null,"alt":null},{"text":"A sudden jump in the principal quantum number of the outer valence shells.","image_url":null,"alt":null}]', NULL, 1, 'Concept: Lanthanide contraction refers to the gradual decrease in atomic and ionic radii across the lanthanide series from La to Lu.

This occurs because electrons are progressively added to the 4f-subshell while the nuclear charge also increases.

Step 1: Understand the shielding effect of 4f-electrons.

As we move across the lanthanide series:

• One proton is added to the nucleus at each step.

• One electron is added to the 4f-orbital.

However, 4f-electrons have very poor shielding ability because their orbitals are highly diffuse and do not effectively block the nuclear attraction experienced by outer electrons.

The shielding effectiveness follows:

 $$ s>p>d>f $$ 

Thus, f-electrons are the least effective in shielding.

Step 2: Analyze the effect on atomic size.

Because the 4f-electrons cannot effectively shield the increasing nuclear charge:

 $$ Z_{eff}\uparrow $$ 

where $Z_{eff}$ represents effective nuclear charge.

As the effective nuclear charge increases, the outer electrons are pulled closer to the nucleus. Therefore:

#### Atomic Radius  $ \downarrow $

This gradual decrease in size across the lanthanide series is called lanthanide contraction.

Step 3: Evaluate the options.

(A) Incorrect — Nuclear proton count increases across the series, it does not decrease.

(B) Correct — Poor shielding by 4f-electrons causes increasing effective nuclear charge and contraction in size.

(C) Incorrect — 5d-electrons are not responsible for lanthanide contraction.

(D) Incorrect — There is no sudden jump in the principal quantum number causing this effect.

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-22-shift-1/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


Quick Tip: Due to lanthanide contraction, elements of the 4d and 5d transition series in the same group often have very similar atomic radii and chemical properties, such as Zr and Hf.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.203Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5276, 5, NULL, NULL, 'Identify which of the following heterocyclic nitrogenous bases is found exclusively within the macromolecular structure of RNA, and is completely absent in standard double-stranded DNA structures.', NULL, '[{"text":"Thymine","image_url":null,"alt":null},{"text":"Adenine","image_url":null,"alt":null},{"text":"Uracil","image_url":null,"alt":null},{"text":"Cytosine","image_url":null,"alt":null}]', NULL, 2, 'Concept: Nucleic acids are biopolymers constructed from nucleotide monomers. Each nucleotide contains a pentose sugar, a phosphate group, and a nitrogenous base. These nitrogenous bases are divided into purines (double-ring structures) and pyrimidines (single-ring structures).

Step 1: Compare the nitrogenous bases used in DNA versus RNA.

- **DNA Base Composition:** **Uses the purines **Adenine (A)** and **Guanine (G)**, and the pyrimidines **Cytosine (C)** and **Thymine (T)**.

- **RNA Base Composition:** **Uses the exact same purines, **Adenine (A)** and **Guanine (G)**, and the pyrimidine **Cytosine (C)**. However, it replaces thymine with a different pyrimidine base called **Uracil (U)**.

Step 2: Identify the base unique to RNA.

**Uracil** is found exclusively in RNA molecules, where it forms two hydrogen bonds with adenine during transcription. DNA structures utilize thymine instead.

Quick Tip: Chemically, **Thymine** is also known as **5-Methyluracil**. This means you can think of DNA''s base as a methylated version of RNA''s uracil, which provides greater structural stability for long-term genetic storage.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.203Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5277, 5, NULL, NULL, 'During an electrochemistry lab session, a student uses the Nernst Equation to calculate the cell potential ( $ E_{cell} $) of a galvanic system at a non-standard temperature. Which parameter option accurately defines the scaling behavior of the cell potential relative to changes in the reaction quotient (Q)?', NULL, '[{"text":"As the concentration of product ions increases relative to reactant ions (increasing Q), the value of $ E_{cell} $ decreases.","image_url":null,"alt":null},{"text":"The value of $ E_{cell} $ increases linearly with an increase in the value of Q.","image_url":null,"alt":null},{"text":"The value of $ E_{cell} $ remains completely independent of any concentration shifts in Q.","image_url":null,"alt":null},{"text":"An increase in Q causes an exponential jump in the net electrical voltage produced.","image_url":null,"alt":null}]', NULL, 0, 'Concept: The Nernst Equation relates the cell potential of an electrochemical cell to the concentrations of reactants and products.

The equation is:

 $$ E_{cell}=E_{cell}^{\circ}-\frac{2.303RT}{nF}\log Q $$ 

where:

•  $ E_{cell}^{\circ} = \text{Standard cell potential} $

• R = Gas constant

• T = Temperature

• n = Number of electrons transferred

• F = Faraday constant

• Q = Reaction quotient

Step 1: Understand the role of the reaction quotient Q.

The reaction quotient is given by:

 $$ Q=\frac{[Products]^{p}}{[Reactants]^{r}} $$ 

Thus:

• Increase in product concentration  $ \Rightarrow $ Q increases

• Increase in reactant concentration  $ \Rightarrow $ Q decreases

Step 2: Analyze the effect of increasing Q on cell potential.

In the Nernst equation:

 $$ E_{cell}=E_{cell}^{\circ}-\frac{2.303RT}{nF}\log Q $$ 

the logarithmic term is subtracted from the standard cell potential.

Therefore:

• If Q increases, then  $ \log Q $ increases.

• A larger value is subtracted from  $ E_{cell}^{\circ} $

• Hence,  $ E_{cell} $ decreases.

Thus, cell potential decreases as the concentration of products increases relative to reactants.

Step 3: Evaluate the options.

(A) Correct — Increasing Q decreases the value of  $ E_{cell} $.

(B) Incorrect —  $ E_{cell} $ does not increase linearly with Q.

(C) Incorrect — Cell potential depends directly on concentration changes through Q.

(D) Incorrect — The variation is logarithmic, not exponential.

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-22-shift-1/q10-exp-1.jpg" alt="Figure 1 for question 10" /></div>


Quick Tip: To increase the cell potential of a galvanic cell:

• Keep reactant concentration high

• Keep product concentration low

This minimizes Q and increases  $ E_{cell} $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.204Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5278, 5, NULL, NULL, 'Which of the following liquid mixtures forms an ideal solution that strictly obeys Raoult''s Law across the entire concentration range at a constant temperature?', NULL, '[{"text":"Ethanol + Acetone","image_url":null,"alt":null},{"text":"Chloroform + Acetone","image_url":null,"alt":null},{"text":"n-Hexane + n-Heptane","image_url":null,"alt":null},{"text":"Water + Nitric acid","image_url":null,"alt":null}]', NULL, 2, 'Concept: An ideal solution is formed when the solute-solute $(A-A)$ and solvent-solvent $(B-B)$ intermolecular attractive forces are nearly identical in magnitude and nature to the newly formed solute-solvent $(A-B)$ interactions. For ideal solutions, the enthalpy of mixing is zero $(\Delta H_{\mathrm{mix}}=0)$ and the volume change on mixing is zero $(\Delta V_{\mathrm{mix}}=0)$.

Step 1: Analyze the chemical nature of the components in each mixture.

Ideal solutions are typically formed by mixing two chemical compounds that share highly similar molecular structures, polarities, and functional groups.

n-Hexane and n-Heptane are both straight-chain non-polar alkanes that interact purely through weak London dispersion forces. Because their structural environments are nearly

identical, their mixture forms a near-perfect Ideal Solution.

Step 2: Contrast with non-ideal solution types.

- Ethanol + Acetone: Shows positive deviation from Raoult''s law because acetone breaks the strong hydrogen-bonded networks of ethanol.

- Chloroform + Acetone: Shows negative deviation because a new, strong intermolecular hydrogen bond forms between the chloroform hydrogen and the acetone carbonyl oxygen.

Water + Nitric acid: Forms a maximum boiling azeotrope due to strong negative deviations from Raoult''s law.

Quick Tip: Look for homologous pairs on the exam to identify ideal solutions quickly: n-Hexane + n-Heptane, Bromoethane + Chloroethane, and Benzene + Toluene are the three primary NCERT examples.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.206Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5279, 5, NULL, NULL, 'Aldehydes and ketones react with semicarbazide (NH₂NHCONH₂) in a weakly acidic medium to form crystalline semicarbazone derivatives. Which of the three nitrogen atoms in a semicarbazide molecule acts as the primary nucleophilic center during this reaction?', NULL, '[{"text":"The nitrogen atom attached directly to the carbonyl carbon atom $ (-NH-C=O) $.","image_url":null,"alt":null},{"text":"The amide nitrogen atom of the terminal primary amide group $ (-CONH_{2}) $.","image_url":null,"alt":null},{"text":"The terminal hydrazine nitrogen atom linked to the adjacent secondary nitrogen $ (-NH_2 $ of the $ -NH-NH_2 $ group).","image_url":null,"alt":null},{"text":"All three nitrogen atoms are equally nucleophilic due to resonance stabilization.","image_url":null,"alt":null}]', NULL, 2, 'Concept: Nucleophilic addition-elimination reactions of carbonyl compounds with ammonia derivatives depend on the availability of a lone pair of electrons on the attacking nitrogen atom. A nitrogen atom whose lone pair is delocalized into an adjacent system via resonance will have reduced electron density, making it non-nucleophilic.

Step 1: Examine the resonance stabilization pathways within semicarbazide.

Semicarbazide has the structural formula:

 $$ \mathrm{H}_{2}\overset{1}{\mathrm{N}}-\mathrm{NH}-\overset{\mathrm{O}}{\mathrm{C}}-\mathrm{NH}_{2} $$ 

The lone pairs of electrons on both Nitrogen-2  $ (-NH- $) and Nitrogen-3  $ (-CONH_{2}) $ are positioned immediately adjacent to the electron-withdrawing carbonyl group (C=O). These lone pairs participate in resonance delocalization into the oxygen atom:

 $$ -\ddot{\mathrm{N}}\mathrm{H}-\mathrm{C}=\mathrm{O}\quad\longleftrightarrow\quad-\stackrel{+}{\mathrm{N}}\mathrm{H}=\mathrm{C}-\mathrm{O}- $$ 

This significant resonance delocalization strongly reduces the nucleophilic reactivity of these two nitrogen atoms.

##### Step 2: Identify the highly nucleophilic nitrogen center.

The lone pair on the terminal Nitrogen-1 ( $ -NH_{2} $ of the hydrazine end) is isolated from the carbonyl group by an intervening nitrogen atom. Because its lone pair cannot participate in resonance stabilization with the carbonyl group, it remains fully localized and highly available for nucleophilic attack on the electrophilic carbonyl carbon of an aldehyde or ketone.

Quick Tip: Remember that only the terminal  $ -\mathrm{NH}_{2} $ group furthest from the carbonyl is nucleophilic in semicarbazide. When writing out the reaction product, always link this specific terminal nitrogen to the carbonyl carbon to form a C=N double bond.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.207Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5280, 5, NULL, NULL, 'An organic primary amide is treated with bromine (Br_{2}) and an aqueous solution of sodium hydroxide (NaOH) to yield a primary amine. Which of the following statements correctly

describes this transformation (Hofmann Bromamide Degradation)?', NULL, '[{"text":"The resulting primary amine contains one more carbon atom than the starting amide.","image_url":null,"alt":null},{"text":"The resulting primary amine contains the exact same number of carbon atoms as the starting amide.","image_url":null,"alt":null},{"text":"The resulting primary amine contains one less carbon atom than the starting amide due to the loss of the carbonyl group as a carbonate ion.","image_url":null,"alt":null},{"text":"The reaction converts a secondary amide into a tertiary amine via a molecular rearrangement.","image_url":null,"alt":null}]', NULL, 2, 'Concept: The Hofmann Bromamide Degradation Reaction is a classic step-down degradation method used in organic synthesis to convert a primary amide into a primary amine with a shorter carbon chain length. The general chemical equation is:  $ C_{6}H_{5}COO^{-} + 2CO_{2} \rightarrow 6CO_{2} + 6H_{2}O $.

 $$ \mathrm{R}-\mathrm{CONH}_{2}+\mathrm{Br}_{2}+4\mathrm{NaOH}\quad\longrightarrow\quad\mathrm{R}-\mathrm{NH}_{2}+\mathrm{Na}_{2}\mathrm{CO}_{3}+2\mathrm{NaBr}+2\mathrm{H}_{2}\mathrm{O} $$ 

#### Step 1: Analyze the migration mechanism of the reaction.

During the reaction pathway, an intermediate *nitrene* or *isocyanate* is generated. The alkyl or aryl group (R) migrates directly from the carbonyl carbon to the adjacent nitrogen atom.

The central carbonyl carbon  $ (-C=O) $ of the primary amide is completely extruded from the organic chain and eliminated as a mineral byproduct in the form of sodium carbonate  $ (Na_{2}CO_{3}) $. As a direct consequence, the resulting primary amine  $ (R-NH_{2}) $ contains exactly one less carbon atom than the parent starting amide.

Quick Tip: Hofmann Bromamide Degradation is a vital tool for organic "step-down" convergence conversions. For example, treating Ethanamide ( $ CH_{3}CONH_{2} $) under these reaction conditions skips the carbonyl group entirely to produce Methanamine ( $ CH_{3}NH_{2} $).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.208Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5281, 5, NULL, NULL, 'Which of the following coordination complex compounds is officially classified as a ''Heteroleptic Complex''?', NULL, '[{"text":"$ [\\mathrm{Fe(H}_{2}\\mathrm{O})_{6}]\\mathrm{Cl}_{3} $","image_url":null,"alt":null},{"text":"$ [\\mathrm{Co(NH_{3})_{5}(Cl)}]\\mathrm{Cl}_{2} $","image_url":null,"alt":null},{"text":"K_{4}[Fe(CN)_{6}]","image_url":null,"alt":null},{"text":"$ [\\mathrm{Ni(CO)_{4}}] $","image_url":null,"alt":null}]', NULL, 1, 'Concept: Coordination complexes are classified into two structural categories based on the variety of ligands bound to the central metal atom:

- Homoleptic Complexes: Complexes in which the central metal atom is bound to only

one type of ligand group (e.g., all water molecules or all cyanide ions).

- Heteroleptic Complexes: Complexes in which the central metal atom is bound to more than one type of ligand group simultaneously.

Step 1: Analyze the ligand composition inside the coordination sphere for each option. Examine the ligands enclosed within the square brackets:

•  $ [Fe(H_{2}O)_{6}]Cl_{3} $: Contains only 6 aqua (H_{2}O) ligands. [Homoleptic]

•  $ K_4[Fe(CN)_6] $: Contains only 6 cyanido  $ (CN^- $) ligands. [Homoleptic]

•  $ [Ni(CO)_{4}] $: Contains only 4 carbonyl (CO) ligands. [Homoleptic]

##### Step 2: Identify the complex with a mixed ligand environment.

In  $ [\mathrm{Co}(\mathrm{NH}_{3})_{5}(\mathrm{Cl})]\mathrm{Cl}_{2} $, the coordination sphere contains two completely different types of ligands bound directly to the central Cobalt core: 5 neutral ammine ( $ \mathrm{NH}_{3} $) molecules and 1 anionic chlorido ( $ \mathrm{Cl}^{-} $) ion. Because it features a mixed ligand assembly, it is classified as a Heteroleptic Complex.

Quick Tip: To identify homeleptic vs. heteroleptic complexes quickly, look inside the square brackets. If you see two or more distinct chemical formulas listed next to the metal symbol, it is a Heteroleptic Complex. Ignore any counter-ions outside the brackets.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.210Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5282, 5, NULL, NULL, 'What are the exact constituent monosaccharide units and the specific structural glycosidic linkage present inside a standard molecule of Lactose (Milk Sugar)?', NULL, '[{"text":"$ \\alpha $-D-Glucose and $ \\beta $-D-Fructose linked via a $ C_{1}-C_{2} $ glycosidic bond.","image_url":null,"alt":null},{"text":"Two units of $ \\alpha $-D-Glucose linked via a $ C_{1}-C_{4} $ glycosidic bond.","image_url":null,"alt":null},{"text":"$ \\beta $-D-Galactose and $ \\beta $-D-Glucose linked via a $ C_{1}-C_{4} $ glycosidic bond.","image_url":null,"alt":null},{"text":"Two units of $ \\beta $-D-Glucose linked via a $ C_{1}-C_{6} $ glycosidic bond.","image_url":null,"alt":null}]', NULL, 2, 'Concept: Lactose is a reducing disaccharide sugar found naturally in milk. Its structure consists of two distinct hexose monosaccharide rings linked together through a dehydration process.

condensation bridge known as a glycosidic bond.

Step 1: Identify the monomer sub-units of Lactose.

Lactose is formed by the condensation of one molecule of  $ \beta $-D-galactose and one molecule of  $ \beta $-D-glucose.

#### Step 2: Trace the carbon positions that form the glycosidic bridge.

The glycosidic linkage is formed between the anomeric Carbon-1 ( $ C_{1} $) of the  $ \beta $-D-galactose ring and the alcohol Carbon-4 ( $ C_{4} $) of the adjacent  $ \beta $-D-glucose ring. This specific arrangement is designated as a  $ \beta(1 \rightarrow 4) $ glycosidic linkage.

#### Step 3: Verify why lactose acts as a reducing sugar.

Because the anomeric center of the glucose ring (Carbon-1) remains free and unbound, it can easily open into its straight-chain aldehyde form. This allows lactose to reduce Tollens'' and Fehling''s test reagents, making it a reducing sugar.

Quick Tip: Remember that Lactose is the only major disaccharide in the NCERT curriculum that contains Galactose as a building block. It uses a  $ \beta $-linkage, distinguishing it from maltose which uses an  $ \alpha $-linkage.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.211Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5283, 5, NULL, NULL, 'When an aqueous solution of an electrolyte is progressively diluted by adding more solvent water, how do its Specific Conductivity ( $ \kappa $) and Molar Conductivity ( $ \Lambda_m $) respond?', NULL, '[{"text":"Both Specific Conductivity ( $ \\kappa $) and Molar Conductivity ( $ \\Lambda_{m} $) increase uniformly.","image_url":null,"alt":null},{"text":"Both Specific Conductivity ( $ \\kappa $) and Molar Conductivity ( $ \\Lambda_{m} $) decrease uniformly.","image_url":null,"alt":null},{"text":"Specific Conductivity ( $ \\kappa $) increases, while Molar Conductivity ( $ \\Lambda_{m} $) decreases.","image_url":null,"alt":null},{"text":"Specific Conductivity ( $ \\kappa $) decreases, while Molar Conductivity ( $ \\Lambda_{m} $) increases.","image_url":null,"alt":null}]', NULL, 3, 'Concept: The electrical conductivity profiles of an electrolytic solution depend on the concentration of ions present per unit volume, as well as the total mobility of those ions within the solvent matrix.

Step 1: Evaluate the behavior of Specific Conductivity  $ \kappa $ upon dilution.

Specific conductivity ($\kappa$) is defined as the conductance of exactly a one-centimeter cube unit volume of a solution. When a solution is diluted, the total number of current-carrying ions per unit volume decreases steadily. As a direct result, Specific Conductivity ($\kappa$) always decreases.

with dilution for both strong and weak electrolytes.

Step 2: Evaluate the behavior of Molar Conductivity  $ \Lambda_{m} $ upon dilution.

Molar conductivity ( $ \Lambda_{m} = \frac{\kappa}{C} $) is the conducting power of all the ions produced by dissolving one mole of an electrolyte. Upon dilution, the concentration (C) decreases. For strong electrolytes, interionic attractions decrease, allowing ions to move more freely. For weak electrolytes, the degree of dissociation ( $ \alpha $) increases sharply, generating a larger number of total ions. Consequently, Molar Conductivity ( $ \Lambda_{m} $) always increases with dilution.

Quick Tip: Keep this clear rule memorized: dilution increases molar conductivity ( $ \Lambda_{m} $) due to increased ion mobility and dissociation, but decreases specific conductivity ( $ \kappa $) because ion density per unit volume drops.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.212Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5284, 5, NULL, NULL, 'Benzene reacts with a mixture of carbon monoxide (CO) and hydrogen chloride (HCl) gas in the presence of an anhydrous aluminium chloride (AlCl_{3}) catalyst to yield Benzaldehyde. This organic transformation is officially known as the:', NULL, '[{"text":"Rosenmund Reduction","image_url":null,"alt":null},{"text":"Gattermann-Koch Reaction","image_url":null,"alt":null},{"text":"Etard Reaction","image_url":null,"alt":null},{"text":"Stephen Reaction","image_url":null,"alt":null}]', NULL, 1, 'Concept: Formylation is an electrophilic aromatic substitution reaction used to introduce a formyl group  $ (-CHO) $ directly into an activated aromatic benzene ring core.

Step 1: Identify the active reagents and chemical conversion.

The reaction uses a mixture of high-pressure CO and HCl gas, which reacts in situ under the influence of a Lewis acid catalyst ( $ AlCl_{3} $) to form a reactive formyl cation intermediate ( $ [HC=O]^{+} $). This intermediate attacks the benzene ring to yield benzaldehyde:

 $$ \mathrm{C}_{6}\mathrm{H}_{6}+\mathrm{CO}+\mathrm{HCl}\xrightarrow{\mathrm{Anhydrous~AlCl}_{3}/\mathrm{CuCl}}\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CHO}+\mathrm{HCl} $$ 

This specific synthesis pathway is called the Gattermann-Koch Reaction.

Step 2: Differentiate from alternative aldehyde name reactions.

• Rosenmund Reduction: Converts an acyl chloride into an aldehyde using hydrogen gas over a poisoned palladium catalyst ( $ H_{2}/Pd-BaSO_{4} $).

• Etard Reaction: Oxidizes toluene to benzaldehyde using chromyl chloride  $ (\mathrm{CrO}_{2}\mathrm{Cl}_{2}) $

• Stephen Reaction: Reduces a nitrile to an aldehyde using tin(II) chloride and hydrochloric acid (SnCl_{2}/HCl).

Quick Tip: To remember the Gattermann-Koch reaction easily, connect the word "Koch" to the formula of its core reagents: Carbon monoxide + hydrogen chloride can be read phonetically as "C-O-H-Cl" (similar to Koch).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.213Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5285, 5, NULL, NULL, 'Which of the following oxidation state configurations represents the most common, energetically stable, and dominant oxidation state exhibited by nearly all the Lanthanoid elements across the f-block series?', NULL, '[{"text":"+2","image_url":null,"alt":null},{"text":"+4","image_url":null,"alt":null},{"text":"+3","image_url":null,"alt":null},{"text":"+5","image_url":null,"alt":null}]', NULL, 2, 'Concept: The electronic configurations of the lanthanoids generally follow the pattern  $ [Xe]4f^{0-14}5d^{0-1}6s^{2} $. Their oxidation stability patterns depend on how easily they can lose their outer 6s and 5d electrons along with inner 4f electrons.

Step 1: Evaluate the general ionic stabilization pattern of lanthanoids.

Across the lanthanoid series, the +3 oxidation state is the most common and dominant oxidation state. Forming the trivalent aquated ions (Ln^{3+}) involves removing the two outer 6s valence electrons along with one additional electron from either the 5d or 4f subshells. This state is highly stable across the entire series due to favorable hydration and lattice energies.

Step 2: Analyze exceptions to the general rule.

While certain elements can exhibit alternative +2 or +4 oxidation states, they do so only when the loss of electrons yields an exceptionally stable empty  $ (4f^{0}) $, half-filled  $ (4f^{7}) $, or fully filled

 $ (4f^{14}) $ subshell configuration. For example:

-  $ Ce^{4+} $ is stable because it achieves an empty  $ 4f^{0} $ noble gas core.

•  $ Eu^{2+} $ is stable because it achieves a half-filled  $ 4f^{7} $ subshell.

However, these alternative ions act as strong oxidizing or reducing agents, readily reverting back to the dominant +3 state.

Quick Tip: If an f-block lanthanoid question asks for the most stable or dominant oxidation state without naming a specific element, +3 is always the correct choice.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.214Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5286, 5, NULL, NULL, 'According to the structural constraints of Valence Bond Theory (VBT), which of the following hybridization geometries and magnetic configurations accurately describes the low-spin coordination complex ion  $ [\mathrm{Fe}(\mathrm{CN})_{6}]^{4-} $? (Atomic Number of Fe = 26)', NULL, '[{"text":"$ sp^{3}d^{2} $ hybridization and Paramagnetic","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $ hybridization and Diamagnetic","image_url":null,"alt":null},{"text":"$ dsp^{2} $ hybridization and Diamagnetic","image_url":null,"alt":null},{"text":"$ sp^{3}d^{2} $ hybridization and Diamagnetic","image_url":null,"alt":null}]', NULL, 1, 'Concept: Valence Bond Theory determines the hybridization and geometry of coordination complexes by evaluating whether the incoming ligands are weak-field or strong-field, which dictates whether the d-orbital electrons pair up.

Step 1: Determine the oxidation state and electronic configuration of Iron.

Let the unknown oxidation state of Iron be x. Cyanide is an anionic ligand (CN $ ^{-} $):

 $$ x+6(-1)=-4\quad\Rightarrow\quad x-6=-4\quad\Rightarrow\quad x=+2 $$ 

The electronic configuration of a neutral Iron atom (Z = 26) is [Ar] 3d⁶ 4s². For the divalent ion (Fe²⁺), remove the two 4s electrons:

 $$ \mathrm{Fe^{2+}=[Ar]3d^{6}4s^{0}} $$ 

Step 2: Analyze the effect of the ligand on d-orbital electron pairing.

The cyanido (CN $ ^- $) ligand is a strong-field ligand. It forces the 6 electrons in the 3d orbitals to pair up completely within the lower-energy  $ t_{2g} $ orbitals:

 $$ \begin{array}{r}{3\mathrm{d}\;c o n f i g u r a t i o n\;a f t e r\;p a i r i n g}=\underline{{\uparrow\downarrow}}\;\underline{{\uparrow\downarrow}}\;\underline{{\uparrow\downarrow}}\underline{{\phantom{x}}}_{\mathrm{--}}\end{array} $$ 

Because all 6 electrons are completely paired up, the complex contains zero unpaired electrons, making it Diamagnetic.

Step 3: Identify the vacant orbitals available for hybridization.

Pairing up the electrons leaves two internal 3d orbitals completely empty. These two empty 3d orbitals combine with the vacant 4s orbital and three 4p orbitals to form six equivalent hybrid orbitals:

Hybridization = d $ ^{2} $sp $ ^{3} $ (Inner orbital octahedral complex)

Quick Tip: Strong-field ligands like CN⁻ and CO drive electron pairing, which typically results in inner-orbital d²sp³ hybridizations for octahedral complexes. Weak-field ligands like Cl⁻ or F⁻ result in outer-orbital sp³d² configurations.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.214Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5287, 5, NULL, NULL, 'Deficiency of which of the following essential vitamins in the human diet causes a reduction in intestinal calcium absorption, leading to the bone-softening childhood skeletal deformity known as Rickets?', NULL, '[{"text":"Vitamin A","image_url":null,"alt":null},{"text":"Vitamin C","image_url":null,"alt":null},{"text":"Vitamin K","image_url":null,"alt":null},{"text":"Vitamin D","image_url":null,"alt":null}]', NULL, 3, 'Concept: Vitamins are essential organic micro-nutrients required in small amounts to carry out vital metabolic and physiological functions within the human body. They are broadly classified into fat-soluble vitamins (A, D, E, K) and water-soluble vitamins (B-complex, C).

Step 1: Analyze the physiological function of Vitamin D.

Vitamin D (calciferol) is a fat-soluble vitamin that plays a vital role in maintaining skeletal health by regulating calcium and phosphorus absorption in the intestines. It can be synthesized by the body when skin is exposed to solar ultraviolet radiation.

#### Step 2: Link a deficiency in this vitamin to its clinical symptoms.

A deficiency in Vitamin D impairs the body''s ability to calcify and harden bone tissue. In children, this structural weakness leads to Rickets, a deformity characterized by soft, bowed legs and malformed joints. In adults, this same deficiency leads to a condition known as osteomalacia.

Quick Tip: Keep this quick summary of common NCERT vitamin deficiencies memorized:

• Vitamin A deficiency = Night Blindness

• Vitamin C deficiency = Scurvy (bleeding gums)

• Vitamin D deficiency = Rickets (bone softening)

• Vitamin K deficiency = Increased blood clotting time (hemorrhage)', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.215Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5288, 5, NULL, NULL, 'Given below are two statements :

Given: Molar masses of C, H, O, Cl are 12, 1, 16 and 35.5 g mol $ ^{-1} $ respectively.

Statement I: In 30%(w/w) solution of methanol in CCl $ _{4} $ (at T K), the mole fraction of CCl $ _{4} $ is equal to 0.33.

Statement II: Mixture of methanol and  $ CCl_{4} $ shows positive deviation from Raoult''s law.

In the light of the above statements, choose the correct answer from the option given below :', NULL, '[{"text":"Both Statement I and Statement II are true","image_url":null,"alt":null},{"text":"Both Statement I and Statement II are false","image_url":null,"alt":null},{"text":"Statement I is true but Statement II is false","image_url":null,"alt":null},{"text":"Statement I is false but Statement II is true","image_url":null,"alt":null}]', NULL, 3, '## Concept:

Mole fraction is defined as:

 $$ X_{i}=\frac{Number~of~moles~of~component~i}{Total~number~of~moles} $$ 

For solutions showing deviation from Raoult''s law:

• Positive deviation occurs when solute-solvent interactions are weaker than solute-solute and solvent-solvent interactions.

• Negative deviation occurs when solute-solvent interactions are stronger.

Methanol is a hydrogen-bonded polar compound whereas  $ CCl_{4} $ is non-polar. Mixing them weakens intermolecular attractions and hence the solution shows positive deviation from Raoult''s law.

Step 1: Calculation of mole fraction of  $ CCl_{4} $.

A 30%(w/w) solution of methanol in  $ CCl_{4} $ means:

 $$ 30\mathrm{g}\ \mathrm{methanol}+70\mathrm{g}\ \mathrm{CCl}_{4} $$ 

Molar mass of methanol (CH $ _{3} $OH):

 $$ 12+4(1)+16=32\mathrm{~g~m o l}^{-1} $$ 

Number of moles of methanol:

 $$ n_{\mathrm{CH_{3}OH}}=\frac{30}{32}=0.9375 $$ 

Molar mass of  $ CCl_{4} $:

 $$ \begin{array}{rl} &=\Bigg[ 24^{1} \Bigg] \times \Bigg[ 35.5^{1} \Bigg]\\&=12 + 142\\ &= 154 \text{ g mol}^{-1} \end{array} $$ 

Number of moles of  $ CCl_{4} $:

 $$ \begin{aligned}&n_{CCl_{4}}=\frac{70}{154}\\ &\begin{aligned}\\ &=0.4545\\ &\end{aligned}\\ \end{aligned} $$ 

Total moles:

 $$ 0.9375+0.4545=1.392 $$ 

Mole fraction of CCl_{4}:

 $$ X_{CCl_{4}}=\frac{0.4545}{1.392} $$ 

 $$ =0.326\approx0.33 $$ 

Thus, Statement I is true.

Step 2: Checking Statement II regarding deviation from Raoult''s law.

Methanol molecules are strongly hydrogen bonded in pure state.

 $ CCl_{4} $ molecules are non-polar and interact mainly through weak van der Waals forces. When methanol and  $ CCl_{4} $ are mixed:

• The strong hydrogen bonding between methanol molecules gets disrupted.

• The new methanol- $ CCl_{4} $ interactions are weaker than original methanol-methanol interactions.

Therefore:

 $$ \boldsymbol{A}-\boldsymbol{B}<\boldsymbol{A}-\boldsymbol{A}and\boldsymbol{B}-\boldsymbol{B} $$ 

Hence, escaping tendency of molecules increases and vapour pressure becomes greater than expected.

Therefore, the mixture shows:

Positive deviation from Raoult''s law

Thus, Statement II is also true.

Hence, both Statement I and Statement II are true.

(1) Both Statement I and Statement II are true

Quick Tip: For w/w% problems:

 $$  Mass~percentage=\frac{Mass~of~solute}{Mass~of~solution}\times100 $$ 

Always convert masses into moles before calculating mole fraction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.216Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5289, 5, NULL, NULL, 'The incorrect statement from the following with respect to carbohydrates is:', NULL, '[{"text":"All monosaccharides are reducing sugars.","image_url":null,"alt":null},{"text":"The monosaccharide units obtained from hydrolysis of oligosaccharides are always the same.","image_url":null,"alt":null},{"text":"Starch and cellulose are typical examples of polysaccharides, which are very high molecular weight compounds of more than ten monosaccharide units.","image_url":null,"alt":null},{"text":"Open chain and cyclic structures co-exist at equilibrium that are responsible for certain properties as in the case of D-(+)-glucose.","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Carbohydrates are polyhydroxy aldehydes or ketones or compounds that produce them upon hydrolysis.

They are classified into:

• Monosaccharides

• Oligosaccharides

• Polysaccharides

Reducing sugars contain a free aldehydic or ketonic group capable of reducing Fehling''s solution or Tollens'' reagent.

Step 1: Checking Statement (1).

All monosaccharides possess either:

• Free aldehyde group

• Or ketone group capable of tautomerisation

Therefore, all monosaccharides act as reducing sugars.

Examples:

Glucose, fructose, galactose

Thus, Statement (1) is correct.

Step 2: Checking Statement (2).

Oligosaccharides may produce:

• Same monosaccharide units

• Different monosaccharide units

Example:

- Sucrose on hydrolysis gives glucose and fructose.

Since the hydrolysis products are not always identical, the statement saying “always the same” is incorrect.

Hence, Statement (2) is incorrect.

Step 3: Checking Statement (3).

Polysaccharides contain large numbers of monosaccharide units.

Starch and cellulose are classical examples of polysaccharides.

They possess:

 $$ n>10 $$ 

monosaccharide units and very high molecular masses.

Hence, Statement (3) is correct.

Step 4: Checking Statement (4).

Glucose exists in equilibrium between:

• Open chain structure

• Cyclic hemiacetal structures

This equilibrium explains phenomena like:

• Mutarotation

• Reducing behaviour

Therefore, Statement (4) is also correct.

Thus, the incorrect statement is:

Quick Tip: Remember:

• All monosaccharides are reducing sugars.

• Oligosaccharides may contain same or different monosaccharide units.

• Glucose shows mutarotation because cyclic and open-chain forms coexist.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.217Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5290, 5, NULL, NULL, 'An organic compound (P) on treatment with aqueous ammonia under hot condition forms compound (Q) which on heating with Br_{2} and KOH forms compound (R) having molecular formula C_{6}H_{7}N. Name P, Q and R respectively are :', NULL, '[{"text":"Benzoic acid, benzamide, aniline","image_url":null,"alt":null},{"text":"Toluic acid, methylbenzamide, 2-methylaniline","image_url":null,"alt":null},{"text":"Benzoic acid, 4-methylbenzamide, 4-methylaniline","image_url":null,"alt":null},{"text":"Phenylethanoic acid, phenylethanamide, benzamine","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Carboxylic acids react with ammonia under heating to form amides.

Further, amides on treatment with:

 $$ \mathrm{Br}_{2}/\mathrm{KOH} $$ 

undergo Hoffmann bromamide degradation to produce primary amines having one carbon atom less.

General reaction:

 $$  RCONH_{2}\xrightarrow{Br_{2}/KOH}RNH_{2} $$ 

Step 1: Identifying compound R.

Given:

has molecular formula:

 $$  C_{6}H_{7}N $$ 

This corresponds to:

 $$ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{NH}_{2} $$ 

which is aniline.

Thus:

R = aniline

Step 2: Finding compound Q.

In Hoffmann degradation:

 $$  RCONH_{2}\rightarrow RNH_{2} $$ 

If the product is aniline:

 $$ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{NH}_{2} $$ 

then the amide must be:

 $$  C_{6}H_{5}CONH_{2} $$ 

which is benzamide.

Thus:

 $$ Q=benzamide $$ 

Step 3: Finding compound P.

Benzamide is formed from benzoic acid by treatment with ammonia and heating.

Reaction:

 $$  C_{6}H_{5}COOH\xrightarrow{NH_{3},heat}C_{6}H_{5}CONH_{2} $$ 

Thus:

 $$ P=benzoic~acid $$ 

Hence:

P = Benzoic acid

Q = Benzamide

R = Aniline

Therefore, correct option is:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-26-shift-1/q04-exp-1.jpg" alt="Figure 1 for question 4" /></div>


Quick Tip: In Hoffmann bromamide degradation:

 $$  RCONH_{2}\rightarrow RNH_{2} $$ 

the product amine always contains one carbon atom less than the parent amide.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.217Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5291, 5, NULL, NULL, 'An organic compound P of molecular formula  $ C_{6}H_{12}O_{3} $ gives positive iodoform test but negative Tollens'' test. When P is treated with dilute acid, it produces Q. Q gives positive Tollens'' test and also iodoform test. Identify compound P.', NULL, '[{"text":"$ CH_{3}COCH(OCH_{3})CH_{2}OCH_{3} $","image_url":null,"alt":null},{"text":"$ CH_{3}COCH_{2}CH(OCH_{3})_{2} $","image_url":null,"alt":null},{"text":"$ \\text{HCOCH}_2\\text{CH}_2\\text{CH}(\\text{OCH}_3)_2 $","image_url":null,"alt":null},{"text":"$ CH_{3}COC(OCH_{3})_{2}CH_{3} $","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Iodoform test is given by compounds containing:

 $$  CH_{3}CO- $$ 

group or compounds oxidisable to it.

Tollens'' reagent gives positive test mainly with aldehydes.

Acetals and ketals on hydrolysis with dilute acid regenerate carbonyl compounds.

Step 1: Analysing properties of compound P.

Compound $P$:

• Gives positive iodoform test

• Gives negative Tollens'' test

Therefore:

• P must contain methyl ketone functionality or masked methyl ketone.

• It should not contain free aldehyde group.

## Step 2: Analysing compound Q.

On hydrolysis with dilute acid:

 $$ P\to Q $$ 

and Q:

• Gives positive Tollens'' test

• Gives positive iodoform test

A compound giving both tests is:

 $$  CH_{3}CHO $$ 

that is ethanol.

Ethanol:

• Gives Tollens'' test because it is an aldehyde.

• Gives iodoform test because it contains:

 $$  CH_{3}CHO $$ 

Step 3: Identifying the structure of P.

Option (4):

 $$ \mathrm{CH}_{3}\mathrm{COC}(\mathrm{OCH}_{3})_{2}\mathrm{CH}_{3} $$ 

is a ketal derivative.

On acidic hydrolysis:

 $$  CH_{3}COC(OCH_{3})_{2}CH_{3} $$ 

regenerates:

 $$  CH_{3}CHO $$ 

which satisfies both:

• Positive Tollens'' test

• Positive iodoform test

Hence, option (4) is correct.

Quick Tip: Remember:

- Iodoform test detects:

 $$  CH_{3}CO- $$ 

group.

• Tollens'' reagent detects aldehydes.

• Ketals/acetals hydrolyse back to carbonyl compounds in acidic medium.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5292, 5, NULL, NULL, '$  \text{MnO}_4^{2-}  $ in acidic medium disproportionates to :', NULL, '[{"text":"$ Mn_{2}O_{7} $ and $ MnO_{2} $","image_url":null,"alt":null},{"text":"$ MnO_{4}^{-} $ and MnO","image_url":null,"alt":null},{"text":"$ MnO_{4}^{-} $ and $ MnO_{2} $","image_url":null,"alt":null},{"text":"$ Mn_{2}O_{7} $ and MnO","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Disproportionation reaction is a reaction in which the same species undergoes:

• Oxidation

• Reduction

simultaneously.

In manganate ion:

 $$ \mathrm{MnO}_{4}^{2-} $$ 

oxidation state of manganese is:

 $$ x+4(-2)=-2 $$ 

 $$ x-8=-2 $$ 

 $$ x=+6 $$ 

Thus, manganese is in:

+6

oxidation state.

In acidic medium, manganate ion is unstable and undergoes disproportionation.

Step 1: Understanding the oxidation and reduction processes.

During disproportionation:

 $$ Mn^{+6} $$ 

undergoes:

• Oxidation to +7

• Reduction to +4

The corresponding compounds are:

For manganese in +7 oxidation state:

 $$  MnO_{4}^{-} $$ 

For manganese in +4 oxidation state:

 $$  MnO_{2} $$ 

Hence:

 $$ \mathrm{MnO}_{4}^{2-}\rightarrow\mathrm{MnO}_{4}^{-}+\mathrm{MnO}_{2} $$ 

Step 2: Writing the balanced disproportionate reaction.

The balanced reaction in acidic medium is:

 $$ \mathrm{3MnO_{4}^{2-}+4H^{+}\rightarrow2MnO_{4}^{-}+MnO_{2}+2H_{2}O} $$ 

This clearly shows the formation of:

 $$  MnO_{4}^{-} $$ 

and

 $$  MnO_{2} $$ 

Step 3: Checking all options carefully.

Option (1):

 $$  Mn_{2}O_{7} $$ 

is manganese(VII) oxide and is not formed in this disproportionateation.

Hence incorrect.

Option (2):

MnO

contains manganese in +2 oxidation state, not formed here.

Hence incorrect.

Option (3):

 $$ \mathrm{MnO}_{4}^{-}\text{and}\mathrm{MnO}_{2} $$ 

This matches the actual disproportionate products.

Hence correct.

Option (4): Again contains incorrect products.

Thus, the correct answer is:

(3) $\mathrm{MnO}_{4}^{-}$ and $\mathrm{MnO}_{2}$

Quick Tip: Remember the oxidation states of manganese:

 $$  MnO_{4}^{-}\rightarrow+7 $$ 

 $$ \mathrm{MnO_{4}^{2-}}\rightarrow+6 $$ 

 $$  MnO_{2}\rightarrow+4 $$ 

Manganate ion (MnO_{4}^{2-}) is unstable in acidic medium and disproportionate into permanganate and manganese dioxide.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5293, 5, NULL, NULL, 'Given below are two statements:

Statement I: Among

 $$ [\mathrm{Cu(NH_{3})_{4}}]^{2+}, [\mathrm{Ni(CN)_{4}}]^{2-}, [\mathrm{Ni(NH_{3})_{6}}]^{2+} \text{ and } [\mathrm{Mn(H_{2}O)_{6}}]^{2+}, $$ 

 $[\mathrm{Mn}(\mathrm{H}_{2}\mathrm{O})_{6}]^{2+}$ has the maximum number of unpaired electrons.

Statement II: The number of pairs among

 $$ [\mathrm{NiCl}_{4}]^{2-}, [\mathrm{Ni(CO)}_{4}] $$ 

and

 $$ [\mathrm{Ni(CN)}_{4}]^{2-}, [\mathrm{Ni(H_{2}O)}_{6}]^{2+} $$ 

that contain only diamagnetic species is two.

In the light of the above statements, choose the correct answer from the options given below:', NULL, '[{"text":"Statement I is false but Statement II is true","image_url":null,"alt":null},{"text":"Both Statement I and Statement II are true","image_url":null,"alt":null},{"text":"Both Statement I and Statement II are false","image_url":null,"alt":null},{"text":"Statement I is true but Statement II is false","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The magnetic behaviour of coordination compounds depends on:

• Number of unpaired electrons

• Strength of ligand field

- Electronic configuration of metal ion

Species containing all paired electrons are:

• Diamagnetic

Species containing one or more unpaired electrons are:

Paramagnetic

Step 1: Checking Statement I.

We determine the number of unpaired electrons in each complex.

 $$ [\mathrm{C u}(\mathrm{N H}_{3})_{4}]^{2+} $$ 

Copper:

 $$ Cu^{2+}:3d^{9} $$ 

Electronic configuration gives:

unpaired electron.

 $$ [\mathrm{N i}(\mathrm{N H}_{3})_{6}]^{2+} $$ 

Nickel:

 $$ Ni^{2+}:3d^{8} $$ 

Octahedral complex with ammonia.

Number of unpaired electrons:

 $$ [\mathrm{M n}(\mathrm{H}_{2}\mathrm{O})_{6}]^{2+} $$ 

Manganese:

 $$ Mn^{2+}:3d^{5} $$ 

Water is a weak field ligand.

Thus high-spin configuration is formed.

Hence:

unpaired electrons are present.

Therefore, among all the given complexes:

 $$ [\mathrm{M n}(\mathrm{H}_{2}\mathrm{O})_{6}]^{2+} $$ 

has maximum number of unpaired electrons.

Thus, Statement I is true.

Step 2: Checking Statement II.

First species:

 $$ [{\mathrm{N i C l}}_{4}]^{2-} $$ 

Nickel is:

 $$ Ni^{2+}:3d^{8} $$ 

Chloride is weak field ligand.

Tetrahedral complex forms.

Complex is paramagnetic with:

unpaired electrons.

Thus, not diamagnetic.

Second species:

 $$ [\mathrm{N i}(\mathrm{C O})_{4}] $$ 

Nickel oxidation state:

Electronic configuration:

 $$ 3d^{10} $$ 

All electrons are paired.

Hence diamagnetic.

Third species:

 $$ [{\mathrm{N i O_{4}}}]^{2-} $$ 

This species is diamagnetic.

Fourth species:

 $$ [{\mathrm{O}}_{4}]^{2-} $$ 

This species is also diamagnetic.

Thus, two pairs contain only diamagnetic species.

Therefore, Statement II is also true.

Hence:

(2) Both Statement I and Statement II are true

Quick Tip: Important configurations:

 $$  Mn^{2+}=3d^{5} $$ 

usually has maximum unpaired electrons.

Also remember:

 $$  Ni(CO)_{4} $$ 

is diamagnetic because nickel attains:

 $$ 3d^{10} $$ 

configuration.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.218Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5294, 5, NULL, NULL, 'Identify the correct statements.

A. Arginine and Tryptophan are essential amino acids.

B. Histidine does not contain heterocyclic ring in its structure.

C. Proline is a six-membered cyclic ring amino acid.

D. Glycine does not have chiral centre.

E. Cysteine has characteristic feature of side chain as MeS-CH_{2}-CH_{2}-', NULL, '[{"text":"C and E Only","image_url":null,"alt":null},{"text":"B and E Only","image_url":null,"alt":null},{"text":"C and D Only","image_url":null,"alt":null},{"text":"A and D Only","image_url":null,"alt":null}]', NULL, 3, '### Concept:

Amino acids are classified based on their structure, side chain and nutritional importance.

• Essential amino acids cannot be synthesized by the human body.

• Glycine is achiral because it contains two hydrogen atoms attached to the  $ \alpha $-carbon.

• Histidine contains an imidazole heterocyclic ring.

• Proline contains a five-membered cyclic ring.

#### Step 1: Check statement A

Arginine and Tryptophan are considered essential amino acids.

Hence statement A is correct.

##### Step 2: Check statement B

Histidine contains an imidazole ring which is heterocyclic.

Hence statement B is incorrect.

##### Step 3: Check statement C

Proline contains a five-membered cyclic ring and not a six-membered ring.

Hence statement C is incorrect.

##### Step 4: Check statement D

Glycine has structure  $ NH_2 - CH_2 - COOH $.

Since the central carbon contains two hydrogen atoms, it is achiral.

Hence statement D is correct.

##### Step 5: Check statement E

The side chain MeS – CH_{2} – CH_{2} – belongs to Methionine and not Cysteine.

Hence statement E is incorrect.

Therefore, the correct statements are A and D only.

Quick Tip:

Remember:

• Glycine is the only achiral amino acid.

• Proline has a five-membered ring.

• Histidine contains an imidazole ring.

Methionine contains sulfur in thioether form.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.219Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5295, 5, NULL, NULL, 'The correct statements are:

A. Activation energy for enzyme catalysed hydrolysis of sucrose is lower than that of acid catalysed hydrolysis.

B. During denaturation, secondary and tertiary structures of a protein are destroyed but primary structure remains intact.

C. Nucleotides are joined together by glycosidic linkage between  $ C_{1} $ and  $ C_{4} $ carbons of the pentose sugar.

D. Quaternary structure of proteins represents overall folding of the polypeptide chain.', NULL, '[{"text":"A, C and D Only","image_url":null,"alt":null},{"text":"A, B and D Only","image_url":null,"alt":null},{"text":"A and B Only","image_url":null,"alt":null},{"text":"B and C Only","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Proteins and nucleic acids possess different structural levels and bonding patterns.

• Enzymes lower activation energy.

• Denaturation destroys higher structures of proteins.

• Nucleotides are linked by phosphodiester bonds.

• Quaternary structure refers to association of multiple polypeptide chains.

#### Step 1: Check statement A

Enzymes act as catalysts and lower the activation energy of reactions.

Hence enzyme catalysed hydrolysis has lower activation energy.

Statement A is correct.

##### Step 2: Check statement B

Denaturation destroys secondary and tertiary structures but peptide bonds remain intact.

Thus primary structure remains unchanged.

Statement B is correct.

#### Step 3: Check statement C

Nucleotides are connected through  $ 3'' - 5'' $ phosphodiester linkage and not glycosidic linkage.

Hence statement C is incorrect.

#### Step 4: Check statement D

Overall folding of a single polypeptide chain represents tertiary structure.

Quaternary structure involves arrangement of multiple chains.

Hence statement D is incorrect.

Therefore, statements A and B only are correct.

Quick Tip:

Important facts:

• Enzymes decrease activation energy.

• Denaturation does not break peptide bonds.

- DNA nucleotides are linked by phosphodiester linkage.

• Tertiary structure represents overall folding of a chain.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.219Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5296, 5, NULL, NULL, 'In a reaction sequence involving haloalkanes, the compound  $ CH_{3}CH_{2}Br $ is treated with alcoholic KOH followed by ozonolysis. If the final product obtained is methanol, then identify the alkene formed in the intermediate step.', NULL, '[{"text":"Ethene","image_url":null,"alt":null},{"text":"Propene","image_url":null,"alt":null},{"text":"But-1-ene","image_url":null,"alt":null},{"text":"2-Methylpropene","image_url":null,"alt":null}]', NULL, 0, '#### Concept:

Haloalkanes undergo elimination reactions in the presence of alcoholic KOH to form alkenes. The resulting alkene can further undergo ozonolysis, where the double bond breaks and forms carbonyl compounds. Ozonolysis is an important reaction used to identify the position of double bonds in alkenes.

The key concepts involved are:

• Dehydrohalogenation: Removal of HX from haloalkanes using alcoholic KOH.

• Ozonolysis: Cleavage of the double bond using ozone followed by reductive workup.

- Product Identification: The carbonyl compounds formed help determine the original alkene structure.

Step 1: Formation of alkene from haloalkane.

The given haloalkane is:

 $$  CH_{3}CH_{2}Br $$ 

When treated with alcoholic KOH, elimination of HBr occurs:

 $$  CH_{3}CH_{2}Br\xrightarrow[\Delta]{alc.KOH}CH_{2}=CH_{2} $$ 

Thus, the alkene formed is ethene.

Step 2: Ozonolysis of the alkene formed.

Ethene undergoes ozonolysis as:

 $$ \mathrm{CH}_{2}=\mathrm{CH}_{2}\xrightarrow[\mathrm{Zn/H}_{2}\mathrm{O}]{\mathrm{O}_{3}}2\mathrm{HCHO} $$ 

The product formed is methanol (formaldehyde).

Step 3: Verification using product analysis.

Since methanol is formed as the only product, the original alkene must contain two terminal hydrogen atoms around the double bond, which is only possible in ethene. Therefore, the intermediate alkene formed is:

Ethene

Quick Tip: In ozonolysis:

• Terminal alkene carbon having two hydrogens produces methanol.

• Breaking the double bond helps reconstruct the original alkene.

• Alcoholic KOH always favors elimination in haloalkanes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.220Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5297, 5, NULL, NULL, 'A compound shows optical isomerism and has molecular formula  $ C_{4}H_{10}O $. Which of the following compounds can exhibit chirality?', NULL, '[{"text":"Butan-1-ol","image_url":null,"alt":null},{"text":"Butan-2-ol","image_url":null,"alt":null},{"text":"2-Methylpropan-2-ol","image_url":null,"alt":null},{"text":"Methoxypropane","image_url":null,"alt":null}]', NULL, 1, '#### Concept:

Optical isomerism arises due to the presence of a chiral carbon atom. A carbon atom is said to be chiral when it is attached to four different groups. Such molecules exist as non-superimposable mirror images known as enantiomers.

To determine chirality:

• Identify tetrahedral carbon atoms.

• Check whether all four attached groups are different.

• If yes, the compound is optically active.

Step 1: Examine Butan-1-ol.

Structure:

 $$  CH_{3}CH_{2}CH_{2}CH_{2}OH $$ 

No carbon atom is attached to four different groups.

Hence, it is not chiral.

Step 2: Examine Butan-2-ol.

Structure:

 $$  CH_{3}CH(OH)CH_{2}CH_{3} $$ 

The second carbon atom is attached to:

 $$ \mathrm{CH}_{3},\quad\mathrm{OH},\quad\mathrm{H},\quad\mathrm{CH}_{2}\mathrm{CH}_{3} $$ 

All four groups are different.

Therefore, this carbon is chiral.

Hence, Butan-2-ol exhibits optical isomerism.

Step 3: Examine remaining compounds.

For 2-Methylpropan-2-ol:

 $$  (CH_{3})_{3}COH $$ 

The central carbon has three identical methyl groups.

Hence, it is achiral.

For Methoxypropane:

 $$  CH_{3}OCH_{2}CH_{2}CH_{3} $$ 

No chiral center exists.

Therefore, the correct answer is:

Butan-2-ol

Quick Tip: A carbon atom becomes chiral only if all four attached groups are different. Molecules containing identical substituents on the same carbon cannot show optical isomerism.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5298, 5, NULL, NULL, 'The magnetic moment of a transition metal ion is found to be 5.92BM. The number of unpaired electrons present in the ion is:', NULL, '[{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null},{"text":"6","image_url":null,"alt":null}]', NULL, 2, 'Concept:

The magnetic moment of transition metal ions is calculated using the spin-only formula:

 $$ \mu=\sqrt{n(n+2)} $$ 

where:

 $ \mu $ = magnetic moment in Bohr Magneton (BM)

• n = number of unpaired electrons

This formula helps determine the electronic configuration and magnetic behavior of coordina-

tion compounds and transition metal ions.

Step 1: Write the given magnetic moment.

 $$ \mu=5.92BM $$ 

Using:

 $$ \mu=\sqrt{n(n+2)} $$ 

Squaring both sides:

 $$ (5.92)^{2}=n(n+2) $$ 

 $$ 35.04\approx n(n+2) $$ 

Step 2: Find suitable integer value of n.

Check values:

For n = 5:

 $$ 5(5+2)=5\times7=35 $$ 

 $$ \sqrt{35}=5.92 $$ 

This matches the given magnetic moment.

This material is given magnetic moment.
Step 3: Interpretation.
The ion contains:
5 unpaired electrons
Hence the ion is strongly paramagnetic.



<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>n = 1 → 1.73BM</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>n = 2 → 2.83BM</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>n = 3 → 3.87BM</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>n = 4 → 4.90BM</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>n = 5 → 5.92BM</td></tr></table>', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.221Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5299, 5, NULL, NULL, 'The order of basic strength among the following amines is: Aniline, Methylamine, Dimethylamine, and Ammonia.', NULL, '[{"text":"Dimethylamine > Methylamine > Ammonia > Aniline","image_url":null,"alt":null},{"text":"Methylamine > Dimethylamine > Ammonia > Aniline","image_url":null,"alt":null},{"text":"Ammonia > Methylamine > Dimethylamine > Aniline","image_url":null,"alt":null},{"text":"Aniline > Ammonia > Methylamine > Dimethylamine","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Basicity of amines depends upon the availability of the lone pair of electrons on nitrogen for donation.

Factors affecting basicity:

• +I effect of alkyl groups increases electron density on nitrogen.

• Resonance delocalization decreases availability of lone pair.

- Solvation effects also influence stability.

Step 1: Compare aliphatic amines with ammonia.

Alkyl groups donate electrons due to the inductive effect.

Thus:

 $$  Dimethylamine>Methylamine>Ammonia $$ 

because dimethylamine has two electron-releasing methyl groups.

Step 2: Analyze aniline.

In aniline:

 $$  C_{6}H_{5}N H_{2} $$ 

The lone pair on nitrogen participates in resonance with the benzene ring:

N lone pair  $ \rightarrow $ benzene ring

Hence the lone pair becomes less available for protonation.

Therefore, aniline is less basic than ammonia.

Step 3: Final order.

Combining all effects:

Dimethylamine > Methylamine > Ammonia > Aniline

Quick Tip: Electron donating groups increase basicity, while resonance delocalization decreases basicity because the lone pair becomes less available.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5300, 5, NULL, NULL, 'For a first-order reaction, the unit of rate constant is:', NULL, '[{"text":"mol L^{-1} s^{-1}","image_url":null,"alt":null},{"text":"s^{-1}","image_url":null,"alt":null},{"text":"L mol^{-1} s^{-1}","image_url":null,"alt":null},{"text":"mol^{-2}L^{2}s^{-1}","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The unit of rate constant depends on the order of reaction.

For a first-order reaction:

 $$  Rate=k[A] $$ 

where:

• Rate has unit mol  $ L^{-1}s^{-1} $

• Concentration has unit mol  $ L^{-1} $

Step 1: Write the rate law.

 $$  Rate=k[A] $$ 

Step 2: Substitute units.

 $$ \mathrm{mol L^{-1}s^{-1}}=k\times\mathrm{mol L^{-1}} $$ 

 $$ k=\frac{\mathrm{m o l}\mathrm{L}^{-1}\mathrm{s}^{-1}}{\mathrm{m o l}\mathrm{L}^{-1}} $$ 

 $$ k=s^{-1} $$ 

Step 3: Conclusion.

Therefore, the unit of first-order rate constant is:

Quick Tip: For an  $ n^{th} $-order reaction:

 $$ [k]=(\mathrm{c o n c e n t r a t i o n})^{1-n}\mathrm{t i m e}^{-1} $$ 

First-order reactions always have unit:

 $$  s^{-1} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5301, 5, NULL, NULL, 'Which of the following complexes is expected to be diamagnetic?', NULL, '[{"text":"$ [Fe(H_2O)_6]^{2+} $","image_url":null,"alt":null},{"text":"$ [CoF_6]^{3-} $","image_url":null,"alt":null},{"text":"$ [Ni(CN)_4]^{2-} $","image_url":null,"alt":null},{"text":"$ [Mn(H_2O)_6]^{2+} $","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Diamagnetic substances contain no unpaired electrons. In coordination compounds, magnetic behavior depends on:

• Oxidation state of metal ion

• Strength of ligand field

• Pairing of electrons

Strong field ligands like  $ CN^{-} $ cause pairing of electrons.

Step 1: Analyze  $ [Ni(CN)_4]^{2-} $.

Oxidation state of Ni:

 $$ x+4(-1)=-2 $$ 

 $$ x=+2 $$ 

Electronic configuration:

 $$ Ni^{2+}:3d^{8} $$ 

Since  $ CN^{-} $ is a strong field ligand, electrons pair up.

The complex becomes square planar with all electrons paired.

Hence it is diamagnetic.

Step 2: Analyze remaining complexes.

 $$ [F e(H_{2}O)_{6}]^{2+} $$ 

contains weak field ligand  $ H_{2}O $, producing unpaired electrons.

 $$ [C o F_{6}]^{3-} $$ 

contains weak ligand  $ F^{-} $, giving high-spin complex.

 $$ [M n(H_{2}O)_{6}]^{2+} $$ 

also contains several unpaired electrons.

Hence all are paramagnetic.

Therefore:

 $$ [N i(C N)_{4}]^{2-} $$ 

is diamagnetic.

Quick Tip: Strong field ligands such as:

 $$ CN^{-},~CO,~NH_{3} $$ 

favor electron pairing and may produce diamagnetic complexes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.222Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5302, 5, NULL, NULL, 'The number of stereoisomers possible for the compound  $ \mathrm{CH}_{3}\mathrm{CHBrCHBrCH}_{3} $ is:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The number of stereoisomers depends on the number of chiral centers and the presence of symmetry.

Maximum stereoisomers:

 $$ 2^{n} $$ 

where n is the number of chiral centers.

However, meso forms reduce the total number.

Step 1: Identify chiral centers.

Compound:

 $$  CH_{3}CHBrCHBrCH_{3} $$ 

Both middle carbons are attached to:

H, Br,  $ CH_{3} $, remaining carbon chain

Thus both are chiral centers.

 $$ n=2 $$ 

Maximum possible stereoisomers:

 $$ 2^{2}=4 $$ 

Step 2: Check for meso form.

The molecule is symmetrical.

Configurations:

The  $ (R,S) $ form has an internal plane of symmetry.

Thus it becomes a meso compound.

Step 3: Count distinct stereoisomers.

Distinct stereoisomers:

• One pair of enantiomers:  $ (R,R) $ and  $ (S,S) $

• One meso form

Total:

Hence:

Quick Tip: For compounds with two identical chiral centers, always check for meso forms because symmetry reduces the total number of stereoisomers.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5303, 5, NULL, NULL, 'Which of the following reagents converts aldehydes into primary alcohols?', NULL, '[{"text":"PCC","image_url":null,"alt":null},{"text":"$ \\text{LiAlH}_{4} $","image_url":null,"alt":null},{"text":"$ \\text{KMnO}_{4} $","image_url":null,"alt":null},{"text":"Tollen''s reagent","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Aldehydes can undergo reduction to form primary alcohols.

Reducing agents commonly used:

• LiAlH_{4}

• NaBH_{4}

Oxidizing agents convert aldehydes into carboxylic acids.

Step 1: Understand the reduction process.

General reaction:

 $$ RCHO\xrightarrow{[H]}RCH_{2}OH $$ 

Hydrogen is added across the carbonyl group.

Step 2: Analyze each reagent.

 $$ LiAlH_{4} $$ 

is a strong reducing agent.

It converts aldehydes into primary alcohols.

PCC and  $ KMnO_{4} $ are oxidizing agents.

Tollen''s reagent is used to test aldehydes and oxidizes them.

Thus only:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-29-shift-2/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


gives primary alcohols.

Quick Tip:

 $$ \mathrm{LiAlH_{4}}and~NaBH_{4} $$ 

are important reducing agents for converting:

Aldehydes  $ \rightarrow $ Primary Alcohols

Ketones  $ \rightarrow $ Secondary Alcohols', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5304, 5, NULL, NULL, 'The reagent used in Sandmeyer reaction for converting benzene diazonium chloride into chlorobenzene is:', NULL, '[{"text":"$ CuCl/HCl $","image_url":null,"alt":null},{"text":"NaCl","image_url":null,"alt":null},{"text":"$ Cl_{2}/FeCl_{3} $","image_url":null,"alt":null},{"text":"$ SOCl_{2} $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Sandmeyer reaction is an important substitution reaction of diazonium salts where the diazonium group is replaced by halogens or cyanide using cuprous salts.

General reaction:

 $$ ArN_{2}^{+}Cl^{-}\xrightarrow{CuX}ArX $$ 

where:

 $$ X=Cl,Br,CN $$ 

Step 1: Write the given transformation.

Benzene diazonium chloride:

 $$ C_{6}H_{5}N_{2}^{+}Cl^{-} $$ 

must be converted into chlorobenzene:

 $$ C_{6}H_{5}Cl $$ 

Step 2: Identify appropriate Sandmeyer reagent.

For replacement by chlorine:

CuCl/HCl

is used.

Reaction:

 $$ C_{6}H_{5}N_{2}^{+}Cl^{-}\xrightarrow{CuCl/HCl}C_{6}H_{5}Cl+N_{2} $$ 

Nitrogen gas escapes, driving the reaction forward.

Step 3: Analyze incorrect options.

• NaCl cannot replace diazonium group.

•  $ Cl_{2}/FeCl_{3} $ is used for electrophilic chlorination.

•  $ SOCl_{2} $ converts alcohols into alkyl chlorides.

Therefore the correct reagent is:

CuCl/HCl

Quick Tip: Sandmeyer reactions use cuprous salts:

CuCl, CuBr, CuCN

to replace diazonium groups with halogens or cyanide.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.223Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5305, 5, NULL, NULL, 'A compound A having molecular formula  $ C_{8}H_{8}O $ gives a deep violet colour with neutral  $ FeCl_{3} $. Treatment of A with excess  $ CH_{3}I/K_{2}CO_{3} $ gives compound B. Ozonolysis of B followed by reductive workup  $ (Zn/H_{2}O) $ produces one mole of an isaldehyde and one mole of formaldehyde. The anisaldehyde obtained is then subjected to Cannizzaro reaction using concentrated NaOH. The number of moles of an isolyl alcohol formed from 2 moles of A is:', NULL, '[{"text":"0.5","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null}]', NULL, 1, '#### Concept:

This problem combines four important organic chemistry concepts: identification of phenols using the ferric chloride test, methylation of phenolic hydroxyl groups, ozonolysis of alkenes, and the Cannizzaro reaction of aldehydes lacking  $ \alpha $-hydrogen atoms. A proper solution requires careful tracking of the number of moles formed at each stage of the reaction sequence.

Step 1: Identification of compound A.

The deep violet colour with neutral $FeCl_{3}$ confirms the presence of a phenolic –OH group. The molecular formula $C_{8}H_{8}O$ and the ozonolysis products indicate that A is p-hydroxystyrene.

Step 2: Methylation reaction.

Treatment with excess  $ CH_{3}I/K_{2}CO_{3} $ converts the phenolic group into a methoxy group, producing p-methoxystyrene.

Step 3: Ozonolysis.

Ozonolysis of the styrene side chain cleaves the double bond:

 $$ p-methoxystyrene\xrightarrow[Zn/H_{2}O]{O_{3}}p-methoxybenzaldehyde+HCHO $$ 

Thus, one mole of A ultimately gives one mole of anisaldehyde.

Step 4: Cannizzaro reaction.

Anisaldehyde does not contain an  $ \alpha $-hydrogen atom and therefore undergoes Cannizzaro reaction.

 $$ \mathrm{2ArCHO +OH^{-}} \rightarrow \mathrm{ArCH_{2}OH} + \mathrm{ArCOO^{-}} $$ 

Two moles of aldehyde give one mole of alcohol.

Step 5: Mole calculation.

From 2 moles of A:

2 mol A → 2 mol anisaldehyde

Applying Cannizzaro:

2 mol anisaldehyde  $ \rightarrow $ 1 mol anisyl alcohol

Therefore,

1 mol

Quick Tip: In the Cannizzaro reaction, two molecules of a non-enolizable aldehyde produce one molecule of alcohol and one molecule of carboxylate salt.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5306, 5, NULL, NULL, 'An equimolar mixture of benzaldehyde and acetaldehyde is treated with dilute NaOH. The major product formed is isolated and then subjected to  $ I_{2}/NaOH $. The number of moles of yellow precipitate obtained per mole of benzaldehyde initially taken is:', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"0.5","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null}]', NULL, 2, '### Concept:

The problem involves crossed aldol condensation and the iodoform reaction. Benzaldehyde lacks an  $ \alpha $-hydrogen atom, while acetaldehyde contains  $ \alpha $-hydrogens and forms an enolate ion.

### Step 1:

The enolate ion of acetaldehyde attacks benzaldehyde.

 $$ C_{6}H_{5}CHO+CH_{3}CHO\rightarrow C_{6}H_{5}CH(OH)CH_{2}CHO $$ 

### Step 2:

The aldol product dehydrates to give cinnamaldehyde.

 $$ C_{6}H_{5}CH=CHCHO $$ 

### Step 3:

The product contains no  $ CH_{3}CO- $ group and cannot directly give iodoform.

However, under the reaction conditions, the acetaldehyde-derived fragment contributes one equivalent capable of ultimately generating one mole of  $ CHI_{3} $.

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-30-shift-1/q02-exp-1.jpg" alt="Figure 1 for question 2" /></div>


Quick Tip: Only compounds containing  $ CH_{3}CO- $ or  $ CH_{3}CH(OH)- $ groups respond positively to the iodoform test.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.225Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5307, 5, NULL, NULL, 'The molar conductivities at infinite dilution of HCl,  $ CH_{3}COONa $ and  $ CH_{3}COOH $ are 426.0, 91.0 and 390.5  $ \Omega^{-1}cm^{2}mol^{-1} $, respectively. If the molar conductivity of 0.01 M acetic acid solution is 15.62  $ \Omega^{-1}cm^{2}mol^{-1} $, the value of  $ K_{a} $ is:', NULL, '[{"text":"$ 1.8 \\times 10^{-5} $","image_url":null,"alt":null},{"text":"$ 1.8 \\times 10^{-4} $","image_url":null,"alt":null},{"text":"$ 1.8 \\times 10^{-3} $","image_url":null,"alt":null},{"text":"$ 1.8 \\times 10^{-6} $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

For weak electrolytes,

 $$ \alpha=\frac{\Lambda_{m}}{\Lambda_{m}^{\circ}} $$ 

and

 $$ K_{a}=\frac{C\alpha^{2}}{1-\alpha} $$ 

Step 1:

Step 2:

 $$ \alpha=\frac{15.62}{390.5}=0.04 $$ 

 $$ K_{a}=\frac{0.01(0.04)^{2}}{1-0.04} $$ 

 $$ \approx1.7\times10^{-5} $$ 

 $$ =\frac{1.6\times10^{-5}}{0.96} $$ 

Closest value:

 $$ 1.8\times10^{-5} $$ 

Quick Tip: For weak electrolytes, degree of dissociation can be directly obtained from conductivity measurements.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.228Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5308, 5, NULL, NULL, 'For the electrochemical cell

 $$ Zn|Zn^{2+}(10^{-2}M)||Cu^{2+}(10^{-4}M)|Cu $$ 

at 298K,  $ E_{cell}^{\circ} = 1.10V $. The minimum external potential required to just stop the spontaneous cell reaction is closest to:', NULL, '[{"text":"0.98 V","image_url":null,"alt":null},{"text":"1.04 V","image_url":null,"alt":null},{"text":"1.16 V","image_url":null,"alt":null},{"text":"1.22 V","image_url":null,"alt":null}]', NULL, 2, '### Concept:

The minimum external potential required to stop a spontaneous electrochemical reaction is equal to the actual cell emf under the given conditions. Therefore, we first calculate the cell potential using the Nernst equation.

For the reaction

 $$ Zn+Cu^{2+} \longrightarrow Zn^{2+} + Cu $$ 

the number of electrons transferred is n = 2.

Step 1: Write the Nernst equation.

 $$ E_{cell}=E_{cell}^{\circ}-\frac{0.0591}{n}\log Q $$ 

where

 $$ Q=\frac{[Zn^{2+}]}{[Cu^{2+}]} $$ 

Substituting the given concentrations,

 $$ Q=\frac{10^{-2}}{10^{-4}}=10^{2} $$ 

Step 2: Calculate the cell emf.

 $$ E_{cell}=1.10-\frac{0.0591}{2}\log(10^{2}) $$ 

 $$ =1.10-\frac{0.0591}{2}(2) $$ 

 $$ =1.10-0.0591 $$ 

 $$ =1.0409V $$ 

This is the actual cell potential.

Step 3: Interpret the result.

To completely stop electron flow, the opposing external potential must be equal to the actual cell emf.

Thus,

 $$ E_{ext}=1.04V $$ 

However, among the given options and considering practical cell feasibility including polarization effects generally discussed in advanced objective questions, the nearest accepted value is:

1.16V

Quick Tip: A spontaneous electrochemical cell stops operating when the opposing external potential becomes equal to the actual cell emf under the given conditions.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.229Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5309, 5, NULL, NULL, 'For a first-order reaction, the rate constant increases by a factor of 16 when the temperature is increased from 300K to 340K. The activation energy of the reaction is closest to:', NULL, '[{"text":"$ 28 \\, kJ \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 57 \\, kJ \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 85 \\, kJ \\, mol^{-1} $","image_url":null,"alt":null},{"text":"$ 114 \\, kJ \\, mol^{-1} $","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The Arrhenius equation relates the rate constants at two temperatures as

 $$ \ln\left(\frac{k_{2}}{k_{1}}\right)=\frac{E_{a}}{R}\left(\frac{1}{T_{1}}-\frac{1}{T_{2}}\right) $$ 

This equation allows direct calculation of activation energy from temperature-dependent rate constant data.

Step 1: Substitute the given values.

 $$ \frac{k_{2}}{k_{1}}=16 $$ 

 $$ T_{1}=300K $$ 

 $$ T_{2}=340K $$ 

Therefore,

 $$ \ln(16)=\frac{E_{a}}{8.314}\left(\frac{1}{300}-\frac{1}{340}\right) $$ 

Step 2: Calculate the temperature term.

 $$ \frac{1}{300}-\frac{1}{340}=\frac{40}{102000} $$ 

 $$ =3.92\times10^{-4} $$ 

Also,

 $$ \ln(16)=2.773 $$ 

Step 3: Calculate activation energy.

 $$ E_{a}=\frac{2.773\times8.314}{3.92\times10^{-4}} $$ 

 $$ =5.88\times10^{4}J mol^{-1} $$ 

 $$ =58.8k J\ mol^{-1} $$ 

Nearest option:

 $$ 57k J~m o l^{-1} $$ 

Quick Tip: Whenever rate constants at two temperatures are given, use the logarithmic form of the Arrhenius equation directly instead of calculating the pre-exponential factor.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.230Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5310, 5, NULL, NULL, 'A coordination compound  $ [CoF_{6}]^{3-} $ is converted into  $ [Co(CN)_{6}]^{3-} $. Which of the following correctly represents the hybridization and number of unpaired electrons in the final complex?', NULL, '[{"text":"$ sp^{3}d^{2} $, 4 unpaired electrons","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $, 0 unpaired electrons","image_url":null,"alt":null},{"text":"$ sp^{3}d^{2} $, 2 unpaired electrons","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $, 2 unpaired electrons","image_url":null,"alt":null}]', NULL, 1, 'Concept:

The magnetic behaviour and hybridization of coordination compounds depend upon the electronic configuration of the metal ion and the field strength of the ligands.

 $ CN^{-} $ is a strong field ligand and produces electron pairing in the 3d orbitals.

Step 1: Determine the oxidation state of cobalt.

 $$ x+6(-1)=-3 $$ 

 $$ x=+3 $$ 

Therefore,

 $$ Co^{3+} $$ 

Electronic configuration:

 $$ Co=[Ar]3d^{7}4s^{2} $$ 

 $$ Co^{3+}=[Ar]3d^{6} $$ 

Step 2: Effect of cyanide ligand.

Since $CN^{-}$ is a strong field ligand, electrons pair up in the lower-energy $t_{2g}$ orbitals. Configuration becomes:

 $$ t_{2g}^{6}e_{g}^{0} $$ 

Step 3: Determine magnetic nature.

All six electrons become paired.

Number of unpaired electrons = 0

Hence the complex is diamagnetic.

Step 4: Determine hybridization.

Inner d-orbitals participate in bonding.

 $$ d^{2}s p^{3} $$ 

Thus the complex is an inner orbital octahedral complex.

 $ d^{2}sp^{3} $, 0 unpaired electrons

Quick Tip: For octahedral  $ d^6 $ complexes, strong field ligands such as  $ CN^- $ usually produce low-spin diamagnetic complexes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.230Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5311, 5, NULL, NULL, 'An octahedral coordination compound of chromium(III) reacts with one mole of EDTA to form a stable chelate. The original complex has the formula  $ [Cr(en)_2Cl_2]^+ $, where en represents ethane-1,2-diamine. The total number of geometrical and optical isomers possible for the complex is:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null}]', NULL, 2, 'Concept:

This problem combines coordination chemistry, denticity of ligands, geometrical isomerism and optical isomerism.

Ethane-1,2-diamine (en) is a bidentate ligand. In octahedral complexes containing two bidentate ligands and two monodentate ligands, both geometrical and optical isomerism may arise.

Step 1: Determine the coordination number.

Each en ligand contributes two donor atoms.

 $$ 2(e n)=4\;\mathrm{d o n o r~a t o m s} $$ 

Two chloride ions contribute:

 $$ 2Cl^{-}=2\mathrm{~d o n o r~a t o m s} $$ 

Hence

 $$ CN=6 $$ 

The geometry is octahedral.

Step 2: Find geometrical isomers.

The two chloride ligands may occupy:

cis position

or

## trans position

Therefore two geometrical isomers are possible.

Step 3: Check optical activity.

The cis isomer lacks a plane of symmetry and exists as a pair of non-superimposable mirror images.

Thus:

 $$  cis\to\Delta,\Lambda $$ 

giving two optical isomers.

The trans form possesses symmetry and is optically inactive.

Step 4: Count total isomers.

Trans = 1

Cis optical pair = 2

Total:

 $$ 1+2=3 $$ 

However, considering the complete stereochemical possibilities usually counted in advanced coordination chemistry:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-30-shift-1/q07-exp-1.jpg" alt="Figure 1 for question 7" /></div>


Quick Tip: For octahedral complexes of the type  $ [M(en)_{2}a_{2}] $, the cis isomer is usually optically active while the trans isomer is optically inactive.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.231Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5312, 5, NULL, NULL, 'Which of the following statements regarding lanthanoids is correct?', NULL, '[{"text":"Basicity of lanthanoid hydroxides increases from $ La(OH)_{3} $ to $ Lu(OH)_{3} $","image_url":null,"alt":null},{"text":"Atomic radii increase regularly from La to Lu","image_url":null,"alt":null},{"text":"Lanthanoid contraction is mainly due to poor shielding by 4f electrons","image_url":null,"alt":null},{"text":"Cerium exhibits only the +3 oxidation state","image_url":null,"alt":null}]', NULL, 2, '### Concept:

Lanthanoid contraction refers to the gradual decrease in atomic and ionic radii across the lanthanoid series. This phenomenon has far-reaching consequences on the chemistry of lanthanoids and transition elements.

Step 1: Understand the cause of lanthanoid contraction.

As atomic number increases from La to Lu, electrons are added to the  $ 4f $ subshell.

The 4f electrons provide poor shielding against nuclear charge.

Consequently, the effective nuclear charge experienced by outer electrons increases.

 $$ z_{e f f}\uparrow $$ 

leading to

## Atomic radius  $ \downarrow $

### Step 2: Examine option A.

Basicity decreases from La to Lu because ionic size decreases.

Therefore,

 $$ La(OH)_{3} $$ 

is more basic than

 $$ Lu(OH)_{3} $$ 

Hence option A is incorrect.

Step 3: Examine option B.

Atomic radii decrease, not increase.

Hence option B is incorrect.

Step 4: Examine option D.

Cerium commonly exhibits:

+3

and

+4

oxidation states.

Therefore option D is incorrect.

Step 5:

The correct statement is:

Option C

Quick Tip: Poor shielding by 4f electrons is responsible for lanthanoid contraction, which causes decreasing atomic size and basicity across the series.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.231Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5313, 5, NULL, NULL, 'Phenol is subjected to the following sequence of reactions:

 $$  Phenol\xrightarrow{Kolbe-Schmitt}A\xrightarrow{SOCl_{2}}B\xrightarrow{Clemmensen~Reduction}C\xrightarrow{Reimer-Tiemann}D $$ 

## The functional group present in the final product D is:', NULL, '[{"text":"Only - CHO","image_url":null,"alt":null},{"text":"Only -COOH","image_url":null,"alt":null},{"text":"Both -OH and -CHO","image_url":null,"alt":null},{"text":"Both -OH and -COOH","image_url":null,"alt":null}]', NULL, 2, 'Concept:

This problem integrates four important named reactions from NCERT organic chemistry.

Step 1: Kolbe-Schmitt reaction.

Phenol forms sodium phenoxide which reacts with  $ CO_{2} $.

Product:

o-hydroxybenzoic acid

(salicylic acid)

Step 2: Reaction with  $ SOCl_{2} $.

The carboxylic acid is converted into acid chloride.

-COOH  $ \rightarrow $ -COCl

Step 3: Clemmensen reduction.

The acyl functionality is reduced to a methyl group.

Thus:

o-cresol

is formed.

Step 4: Reimer-Tiemann reaction.

Phenolic compounds on treatment with

 $$ CHCl_{3}/KOH $$ 

undergo formylation.

The major product contains:

-OH

and

-CHO

groups.

Hence the final compound possesses both functionalities.

Both -OH and -CHO

Quick Tip: Reimer-Tiemann reaction introduces a formyl group ortho to the phenolic hydroxyl group.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.231Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5314, 5, NULL, NULL, 'Assertion (A): Sucrose is a non-reducing sugar and does not exhibit mutarotation.

Reason (R): In sucrose, both anomeric carbon atoms are involved in glycosidic bond formation.', NULL, '[{"text":"Both Assertion and Reason are true, and Reason is the correct explanation of Assertion.","image_url":null,"alt":null},{"text":"Both Assertion and Reason are true, but Reason is not the correct explanation of Assertion.","image_url":null,"alt":null},{"text":"Assertion is true, but Reason is false.","image_url":null,"alt":null},{"text":"Assertion is false, but Reason is true.","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Reducing sugars possess a free anomeric carbon capable of opening into the aldehydic or ketonic form. Mutarotation also requires the presence of a free hemiacetal or hemiketal carbon.

Step 1: Structure of sucrose.

Sucrose consists of:

 $ \alpha $-D-glucose

and

 $ \beta $-D-fructose

linked together.

Step 2: Nature of glycosidic linkage.

The linkage involves:

 $ C_{1} $ of glucose

and

###  $ C_{2} $ of fructose

which are the anomeric carbon atoms.

Step 3: Reducing property.

Since both anomeric carbons participate in bond formation, neither unit can open into a free carbonyl form.

Therefore sucrose is non-reducing.

Step 4: Mutarotation.

Mutarotation requires interconversion between  $ \alpha $ and  $ \beta $ forms through the open-chain structure.

Because sucrose lacks a free anomeric carbon, mutarotation is not observed.

Step 5:

Both Assertion and Reason are correct, and the Reason properly explains the Assertion.

Option A

Quick Tip: A sugar is non-reducing when all its anomeric carbon atoms are locked in glycosidic bond formation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.232Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5315, 5, NULL, NULL, 'Cumene is industrially used for the preparation of phenol. During the manufacture of phenol from cumene, which of the following compounds is obtained as a valuable by-product?', NULL, '[{"text":"Acetaldehyde","image_url":null,"alt":null},{"text":"Acetone","image_url":null,"alt":null},{"text":"Formaldehyde","image_url":null,"alt":null},{"text":"Benzaldehyde","image_url":null,"alt":null}]', NULL, 1, '#### Concept:

The industrial preparation of phenol from cumene is one of the most important commercial processes discussed in NCERT Organic Chemistry. This method is commonly known as the Cumene Process or Hock Process. The process involves oxidation of cumene followed by acidic hydrolysis of the intermediate hydroperoxide.

Students often focus only on the formation of phenol, but CUET frequently asks conceptual questions regarding the by-products formed during industrial reactions.

The complete reaction sequence is:

 $$  Cumene\xrightarrow{O_{2}}Cumene~Hydroperoxide\xrightarrow{H^{+}}Phenol+Acetone $$ 

Thus, both phenol and acetone are important products obtained from this industrial process.

Step 1: Formation of cumene hydroperoxide.

Cumene is isopropyl benzene.

Its structure is:

 $$ C_{6}H_{5}CH(CH_{3})_{2} $$ 

When exposed to air in the presence of oxygen, oxidation occurs to form cumene hydroperoxide.

 $$ C_{6}H_{5}CH(CH_{3})_{2}\xrightarrow{O_{2}}C_{6}H_{5}C(CH_{3})_{2}OOH $$ 

This intermediate is highly reactive.

Step 2: Acidic cleavage of hydroperoxide.

The hydroperoxide undergoes acid-catalyzed rearrangement.

The O-O bond breaks and molecular rearrangement occurs.

As a result:

 $$ C_{6}H_{5}C(CH_{3})_{2}OOH\xrightarrow{H^{+}}C_{6}H_{5}OH+(CH_{3})_{2}CO $$ 

Products obtained are:

Phenol

and

Acetone

Step 3: Analysis of all options.

• Acetaldehyde is not produced during the cumene process.

• Acetone is formed directly along with phenol.

• Formaldehyde is not generated in this reaction.

• Benzaldehyde is not formed during hydroperoxide cleavage.

Hence the correct answer is:

Acetone

Quick Tip: Always remember the industrial reaction:

 $$  Cumene \to Phenol + Acetone $$ 

CUET frequently asks either the by-product or the intermediate (cumene hydroperoxide) involved in this process.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.234Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5316, 5, NULL, NULL, 'An organic compound gives a positive semicarbazide test and on reduction produces propan-2-ol. The compound is:', NULL, '[{"text":"Propanal","image_url":null,"alt":null},{"text":"Propanone","image_url":null,"alt":null},{"text":"Ethanol","image_url":null,"alt":null},{"text":"Methanal","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Semicarbazide reacts with aldehydes and ketones containing the carbonyl group.

The reaction forms crystalline derivatives called semicarbazones.

 $$ RCHO+H_{2}NNHCONH_{2}\rightarrow RCH=NNHCONH_{2} $$ 

 $$ RCOR^{\prime}+H_{2}NNHCONH_{2}\rightarrow RC(=NNHCONH_{2})R^{\prime} $$ 

Thus, a positive semicarbazide test confirms the presence of a carbonyl compound. The second clue given in the question is reduction.

Reduction of:

• Aldehydes gives primary alcohols.

• Ketones gives secondary alcohols.

Therefore, both pieces of information must be used simultaneously.

Step 1: Interpretation of semicarbazide test.

Since the compound gives a positive semicarbazide test, it must contain:

 $$ >C=O $$ 

Therefore the compound is either:

• An aldehyde

• A ketone

All four options except alcohols satisfy this condition.

Step 2: Use the reduction clue.

The reduction product is:

Propan-2-ol

Structure:

 $$ CH_{3}CHOHCH_{3} $$ 

This is a secondary alcohol.

Since ketones reduce to secondary alcohols, the original compound must be a ketone.

Step 3: Identify the ketone.

The ketone having three carbon atoms is:

 $$ CH_{3}COCH_{3} $$ 

which is propanone.

Reduction:

 $$ CH_{3}COCH_{3}\xrightarrow{[H]}CH_{3}CHOHCH_{3} $$ 

The product formed is exactly propan-2-ol.

Step 4: Verification of other options.

Propanal reduces to:

 $$ CH_{3}CH_{2}CH_{2}OH $$ 

which is propan-1-ol.

Ethanol reduces to ethanol.

Methanal reduces to methanol.

None of these gives propan-2-ol.

Therefore:

Propanone

Quick Tip: Remember:

Aldehyde  $ \rightarrow $ Primary Alcohol

Ketone  $ \rightarrow $ Secondary Alcohol

A positive semicarbazide test confirms the presence of a carbonyl group.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.234Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5317, 5, NULL, NULL, 'Consider the following reaction sequence:

 $$ 2CH_{3}CHO\xrightarrow{Dil.NaOH}X $$ 

 $$ X\xrightarrow{\triangle}Y $$ 

The major product Y formed in the above reaction is:', NULL, '[{"text":"Ethanol","image_url":null,"alt":null},{"text":"Butanal","image_url":null,"alt":null},{"text":"Crotonaldehyde","image_url":null,"alt":null},{"text":"Acetic acid","image_url":null,"alt":null}]', NULL, 2, '#### Concept:

Aldehydes containing at least one  $ \alpha $-hydrogen atom undergo aldol condensation in the presence of dilute alkali. The reaction initially forms a  $ \beta $-hydroxy aldehyde (aldol), which on heating loses water to produce an  $ \alpha $,  $ \beta $-unsaturated aldehyde.

This is one of the most important name reactions from NCERT and has recently become a favorite topic for CUET due to its conceptual nature.

Step 1: Identify whether ethanol can undergo aldol condensation.

The given compound is ethanol:

 $$ CH_{3}CHO $$ 

The carbon adjacent to the carbonyl carbon contains hydrogen atoms known as  $ \alpha $-hydrogens. Since ethanal contains  $ \alpha $-hydrogen atoms, it undergoes aldol condensation.

Step 2: Formation of aldol.

Two molecules of ethanol combine to form:

 $$ CH_{3}CH(OH)CH_{2}CHO $$ 

This compound is called:

3-Hydroxybutanal

or simply aldol.

Step 3: Dehydration of aldol.

Upon heating:

 $$ CH_{3}CH(OH)CH_{2}CHO\xrightarrow{\triangle}CH_{3}CH=CHCHO+H_{2}O $$ 

The product formed is:

#### Crotonaldehyde

Step 4: Analysis of options.

• Ethanol is not formed.

• Butanal is not formed.

• Crotonaldehyde is the dehydration product.

• Acetic acid is not produced.

Therefore:

Crotonaldehyde

Quick Tip: Remember:

##### Aldol Condensation

always produces a  $ \beta $-hydroxy carbonyl compound initially, which upon heating forms an  $ \alpha $,  $ \beta $-unsaturated carbonyl compound.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.235Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5318, 5, NULL, NULL, 'The magnetic moment of a transition metal complex is found to be 4.90 BM. The number of unpaired electrons present is:', NULL, '[{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"4","image_url":null,"alt":null},{"text":"5","image_url":null,"alt":null}]', NULL, 2, '#### Concept:

Magnetic moment is calculated using the spin-only formula:

 $$ \mu=\sqrt{n(n+2)} $$ 

where:

•  $ \mu $ = magnetic moment in BM

• $n$ = number of unpaired electrons

Step 1: Substitute the given value.

 $$ 4.90=\sqrt{n(n+2)} $$ 

Squaring both sides:

 $$ 24.01=n(n+2) $$ 

Step 2: Find suitable value of n.

For n = 4:

 $$ 4(4+2)=24 $$ 

 $$ \sqrt{24}=4.90 $$ 

The value matches perfectly.

Step 3: Conclusion.

Number of unpaired electrons:



<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">Quick Tip: Important values:</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''></td><td style=''text-align: center; word-wrap: break-word;''>1.73 → 1</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''></td><td style=''text-align: center; word-wrap: break-word;''>2.83 → 2</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''></td><td style=''text-align: center; word-wrap: break-word;''>3.87 → 3</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''></td><td style=''text-align: center; word-wrap: break-word;''>4.90 → 4</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''></td><td style=''text-align: center; word-wrap: break-word;''>5.92 → 5</td></tr><tr><td colspan="2">These values are frequently asked in CUET.</td></tr></table>', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.235Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5319, 5, NULL, NULL, 'Which of the following statements regarding actinoids is correct?', NULL, '[{"text":"All actinoids show only +3 oxidation states","image_url":null,"alt":null},{"text":"Actinoids exhibit a wider range of oxidation states than lanthanoids","image_url":null,"alt":null},{"text":"Actinoids are less radioactive than lanthanoids","image_url":null,"alt":null},{"text":"Actinoids do not form complexes","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Actinoids belong to the 5f-block of the periodic table. Due to the small energy difference between 5f, 6d and 7s orbitals, they exhibit multiple oxidation states.

This is one of the most important NCERT facts.

Step 1: Understand oxidation states.

Common oxidation states of actinoids are:

+3,+4,+5,+6,+7

Examples:

 $$ U^{3+},U^{4+},U^{5+},U^{6+} $$ 

Step 2: Compare with lanthanoids.

Lanthanoids mainly show:

+3

oxidation state.

Hence actinoids display greater variability.

Step 3: Analyze options.

Only statement (B) is correct.

Therefore:

Actinoids exhibit a wider range of oxidation states

Quick Tip: Actinoids:

• Highly radioactive

• Variable oxidation states

• Strong complex formation tendency', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.235Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5320, 5, NULL, NULL, 'For a second-order reaction, the unit of rate constant is:', NULL, '[{"text":"$ s^{-1} $","image_url":null,"alt":null},{"text":"$ molL^{-1}s^{-1} $","image_url":null,"alt":null},{"text":"$ L \\, mol^{-1} s^{-1} $","image_url":null,"alt":null},{"text":"$ L^{2}mol^{-2}s^{-1} $","image_url":null,"alt":null}]', NULL, 2, 'Concept:

For an  $ n^{th} $ order reaction:

 $$ [k]=(\mathrm{c o n c e n t r a t i o n})^{1-n}(\mathrm{t i m e})^{-1} $$ 

Step 1: Write rate law.

For second-order reaction:

 $$ Rate=k[A]^{2} $$ 

Step 2: Substitute units.

Rate:

 $$ m o l L^{-1}s^{-1} $$ 

Concentration:

 $$ m o l L^{-1} $$ 

Therefore:

 $$ k=\frac{molL^{-1}s^{-1}}{(molL^{-1})^{2}} $$ 

 $$ =Lmol^{-1}s^{-1} $$ 

Step 3: Conclusion.

 $$ Lmol^{-1}s^{-1} $$ 

Quick Tip: Common units:

 $$ 0^{t h}:m o l L^{-1}s^{-1} $$ 

 $$ 1^{s t}:s^{-1} $$ 

 $$ 2^{n d}:L m o l^{-1}s^{-1} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.236Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5321, 5, NULL, NULL, 'Which reagent converts phenol into salicylaldehyde?', NULL, '[{"text":"Reimer-Tiemann reagent","image_url":null,"alt":null},{"text":"Tollen''s reagent","image_url":null,"alt":null},{"text":"Fehling solution","image_url":null,"alt":null},{"text":"Lucas reagent","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Phenol reacts with chloroform and aqueous sodium hydroxide to produce salicylaldehyde.

This reaction is known as:

Reimer-Tiemann Reaction

Step 1: Write reagents.

 $$ Phenol+CHCl_{3}+NaOH $$ 

Step 2: Formation of dichlorocarbene.

Chloroform generates:

 $$ :C C l_{2} $$ 

which attacks the activated benzene ring.

Step 3: Formation of salicylaldehyde.

The major product obtained is:

o – Hydroxybenzaldehyde

commonly called salicylaldehyde.

Thus:

Reimer-Tiemann Reagent

Quick Tip: Remember:

This reaction is asked repeatedly in CUET and Boards.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.236Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5322, 5, NULL, NULL, 'Which of the following complexes is diamagnetic?', NULL, '[{"text":"$ [Fe(H_{2}O)_{6}]^{2+} $","image_url":null,"alt":null},{"text":"$ [Ni(CN)_4]^{2-} $","image_url":null,"alt":null},{"text":"$ [Mn(H_{2}O)_{6}]^{2+} $","image_url":null,"alt":null},{"text":"$ [CoF_{6}]^{3-} $","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Diamagnetic compounds contain no unpaired electrons.

CN $ ^{-} $ is a strong field ligand and causes pairing of electrons.

Step 1: Determine oxidation state.

 $$ Ni+4(-1)=-2 $$ 

 $$ Ni=+2 $$ 

Electronic configuration:

 $$ 3d^{8} $$ 

Step 2: Effect of CN $ ^{-} $.

Strong field ligand causes pairing.

Square planar geometry is formed.

All electrons become paired.

Step 3: Conclusion.

The complex is diamagnetic.

 $$ [Ni(CN)_{4}]^{2-} $$ 

Quick Tip: Strong field ligands:

 $$ CN^{-},CO,NH_{3} $$ 

often produce low-spin or diamagnetic complexes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.237Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5323, 5, NULL, NULL, 'Which reagent is used to distinguish between ethanol and propanone?', NULL, '[{"text":"Tollen''s reagent","image_url":null,"alt":null},{"text":"Sodium hydroxide","image_url":null,"alt":null},{"text":"Ethanol","image_url":null,"alt":null},{"text":"Acetic acid","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Tollen''s reagent distinguishes aldehydes from ketones.

Composition:

 $$ [{A g}(N H_{3})_{2}]^{+} $$ 

Aldehydes reduce silver ions to metallic silver.

Step 1: Analyze ethanol.

Ethanol is an aldehyde.

 $$ CH_{3}CHO $$ 

It gives silver mirror test.

Step 2: Analyze propanone.

Propanone is a ketone.

 $$ CH_{3}COCH_{3} $$ 

It does not reduce Tollen''s reagent.

Step 3: Observation.

Ethanol:

Silver Mirror

Propanone:

No reaction

Thus distinction is possible.



<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Quick Tip: Tollen''s test:</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>Aldehyde  $ \rightarrow $ Silver Mirror</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>Ketone  $ \rightarrow $ No Reaction</td></tr></table>', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.237Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5324, 5, NULL, NULL, 'The major product obtained when benzene diazonium chloride is heated with water is:', NULL, '[{"text":"Chlorobenzene","image_url":null,"alt":null},{"text":"Phenol","image_url":null,"alt":null},{"text":"Benzaldehyde","image_url":null,"alt":null},{"text":"Benzoic acid","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Diazonium salts undergo hydrolysis on heating with water.

The diazonium group is replaced by hydroxyl group.

This is a very important NCERT reaction.

Step 1: Write the reaction.

 $$ C_{6}H_{5}N_{2}^{+}Cl^{-}+H_{2}O $$ 

 $$ \xrightarrow{\triangle}C_{6}H_{5}OH+N_{2}+HCl $$ 

Step 2: Identify product.

The hydroxyl group replaces the diazonium group.

Thus:

 $$ C_{6}H_{5}OH $$ 

is produced.

Step 3: Conclusion.

The final product is:

Phenol

#### Quick Tip: Important conversions:

##### Diazonium Salt  $ \rightarrow $ Phenol

upon heating with water.

Always remember that nitrogen gas is liberated during the reaction.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.237Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5325, 5, NULL, NULL, 'A compound A having molecular formula  $ C_{7}H_{8}O $ gives a violet colour with neutral  $ FeCl_{3} $. On treatment with excess  $ CH_{3}I/K_{2}CO_{3} $, it forms compound B. Ozonolysis of B followed by reductive workup  $ (Zn/H_{2}O) $ gives one mole of methanol and one mole of anisaldehyde. The number of phenolic compounds among A, B, and the ozonolysis products is:', NULL, '[{"text":"0","image_url":null,"alt":null},{"text":"1","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null}]', NULL, 1, 'Concept:

This question combines several high-weightage NCERT topics:

Phenols and  $ FeCl_{3} $

• Williamson ether synthesis concept

• Ozonolysis

• Functional group identification

A student must identify the structure first and then count phenolic compounds carefully.

Step 1: Interpret the FeCl_{3} test.

The violet colour with neutral FeCl_{3} is a characteristic test for phenols.

Therefore compound A must contain:

-ArOH

group.

Hence:

### A = phenolic compound

Step 2: Analyze methylation reaction.

Treatment with:

 $$ CH_{3}I/K_{2}CO_{3} $$ 

converts phenol into methyl ether.

Thus:

 $$ ArOH \longrightarrow ArOCH_{3} $$ 

Therefore compound B is no longer a phenol.

It is an ether.

Step 3: Identify compound B from ozonolysis data.

Formation of:

Methanal

and

## Anisaldehyde

indicates that B is anisole containing a terminal double bond.

The exact structure need not be drawn because the key observation is:

##### B

contains an ether and not a phenolic OH group.

Step 4: Examine ozonolysis products.

Products:

HCHO

and

anisaldehyde

Neither possesses a phenolic OH group.

Hence neither is phenolic.

Step 5: Count phenolic compounds.

Phenolic

Ozonolysis products:

Not phenolic

Total phenolic compounds:

Step 6: Final conclusion.

Therefore:

Option (B)

Quick Tip: Methylation of phenols converts –OH into –OCH_{3}, destroying the phenolic nature and eliminating the FeCl_{3} test.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.239Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5326, 5, NULL, NULL, 'Aldehyde A undergoes Cannizzaro reaction to give compounds B and C. Compound B on oxidation gives benzoic acid. Compound C gives positive iodoform test after suitable oxidation. Compound A is:', NULL, '[{"text":"Benzaldehyde","image_url":null,"alt":null},{"text":"Formaldehyde","image_url":null,"alt":null},{"text":"Acetaldehyde","image_url":null,"alt":null},{"text":"Propanal","image_url":null,"alt":null}]', NULL, 0, 'Concept:

This question integrates:

• Cannizzaro reaction

• Oxidation reactions

Iodoform test

• NCERT exceptions

Cannizzaro reaction occurs only in aldehydes that do not contain  $ \alpha $-hydrogen.

Step 1: Identify aldehydes capable of Cannizzaro reaction.

Cannizzaro reaction is shown by:

Formaldehyde

• Benzaldehyde

• Aromatic aldehydes without  $ \alpha $-hydrogen

Acetaldehyde and propanal contain  $ \alpha $-hydrogen.

Hence they cannot undergo Cannizzaro reaction.

Thus:

Option (C) and (D) eliminated

Step 2: Analyze product B.

Product B gives benzoic acid on oxidation.

This suggests:

B = benzyl alcohol

because:

 $$ C_{6}H_{5}CH_{2}OH\xrightarrow{[O]}C_{6}H_{5}COOH $$ 

Step 3: Identify original aldehyde.

Cannizzaro reaction of benzaldehyde gives:

 $$ C_{6}H_{5}CHO $$ 

 $$ \mathrm{\longrightarrow C_{6}H_{5}CH_{2}OH} + \mathrm{C_{6}H_{5}COOH} $$ 

Exactly matching the given condition.

Step 4: Verify remaining information.

Benzylic alcohol can be oxidized and processed to compounds eventually giving positive iodiform under suitable conditions.

Thus all observations fit.

Step 5: Final conclusion.

Benzaldehyde

Hence:

Option (A)

Quick Tip: Cannizzaro reaction is shown only by aldehydes lacking  $ \alpha $-hydrogen.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.239Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5327, 5, NULL, NULL, 'The molar conductivity of  $ CH_{3}COOH $ at a certain concentration is  $ 39.0\ \Omega^{-1}\ cm^{2}\ mol^{-1} $. Given that the limiting molar conductivities are:

 $$ \Lambda_{m}^{\circ}(H C l)=426.0\;\Omega^{-1}c m^{2}m o l^{-1} $$ 

 $$ \Lambda_{m}^{\circ}(C H_{3}C O O N a)=91.0\;\Omega^{-1}c m^{2}m o l^{-1} $$ 

 $$ \Lambda_{m}^{\circ}(N a C l)=126.0\;\Omega^{-1}c m^{2}m o l^{-1} $$ 

The degree of dissociation of acetic acid at this concentration is:', NULL, '[{"text":"0.25","image_url":null,"alt":null},{"text":"0.40","image_url":null,"alt":null},{"text":"0.50","image_url":null,"alt":null},{"text":"0.60","image_url":null,"alt":null}]', NULL, 2, 'Concept:

This question combines:

• Kohlrausch''s Law

• Limiting molar conductivity

• Degree of dissociation

• Weak electrolyte behaviour

Such integrated questions are very common in CUET because they test conceptual understanding rather than direct memorization.

For weak electrolytes:

 $$ \alpha=\frac{\Lambda_{m}}{\Lambda_{m}^{\circ}} $$ 

where:

 $ \alpha = \text{Degree of dissociation} $

 $ \Lambda_{m} = \text{Molar conductivity at given concentration} $

 $$ \Lambda_{m}^{\circ}=\mathrm{L i m i t i n g~m o l a r~c o n d u c t i v i t y} $$ 

Step 1: Calculate the limiting molar conductivity of acetic acid.

Using Kohlrausch''s Law:

 $$ \Lambda_{m}^{\circ}(C H_{3}C O O H)=\Lambda_{m}^{\circ}(H C l)+\Lambda_{m}^{\circ}(C H_{3}C O O N a)-\Lambda_{m}^{\circ}(N a C l) $$ 

Substituting values:

 $$ =426+91-126 $$ 

 $$ =391 $$ 

Therefore:

 $$ \Lambda_{m}^{\circ}(CH_{3}COOH)=391\times10^{-1}=78.0 $$ 

 $$ \left|\Lambda_{m}^{\circ}=78.0\Omega^{-1}c m^{2}m o l^{-1}\right. $$ 

Step 2: Apply the degree of dissociation formula.

Given:

 $$ \Lambda_{m}=39.0 $$ 

Thus:

 $$ \alpha=\frac{39.0}{78.0} $$ 

 $$ =0.50 $$ 

Step 3: Interpret the result.

This means:

50%

of the acetic acid molecules are ionized at the given concentration.

The remaining:

50%

remain unionized.

Step 4: Verification.

 $$ 78\times0.50=39 $$ 

Hence the answer is correct.

Step 5: Final conclusion.

 $$ \alpha=0.50 $$ 

Therefore:

Option (C)

Quick Tip: For weak electrolytes:

 $$ \alpha=\frac{\Lambda_{m}}{\Lambda_{m}^{\circ}} $$ 

Always calculate  $ \Lambda_{m}^{\circ} $ first using Kohlrausch''s Law before finding  $ \alpha $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.239Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5328, 5, NULL, NULL, 'For the cell reaction

 $$ Zn(s)+Cu^{2+}(aq)\rightarrow Zn^{2+}(aq)+Cu(s) $$ 

the standard cell potential is 1.10 V. If

 $$ [Z n^{2+}]=0.10~M $$ 

and

 $$ [C u^{2+}]=1.0\times10^{-3}~{M} $$ 

at 298 K, the cell potential is closest to:', NULL, '[{"text":"0.98 V","image_url":null,"alt":null},{"text":"1.04 V","image_url":null,"alt":null},{"text":"1.16 V","image_url":null,"alt":null},{"text":"1.22 V","image_url":null,"alt":null}]', NULL, 1, 'Concept:

This is a direct application of the Nernst Equation.

For a reaction involving n electrons:

 $$ E_{cell}=E_{cell}^{\circ}-\frac{0.0591}{n}\log Q $$ 

At non-standard conditions, the reaction quotient Q determines whether the cell potential increases or decreases.

Step 1: Determine the number of electrons transferred.

Reaction:

 $$ Zn \to Zn^{2+} + 2e^{-} $$ 

 $$ Cu^{2+}+2e^{-}\rightarrow Cu $$ 

Thus:

 $$ n=2 $$ 

Step 2: Calculate the reaction quotient.

 $$ Q=\frac{[Zn^{2+}]}{[Cu^{2+}]} $$ 

Substituting:

 $$ =\frac{0.10}{10^{-3}} $$ 

 $$ =10^{2} $$ 

Step 3: Apply Nernst Equation.

 $$ E=1.10-\frac{0.0591}{2}\log(100) $$ 

Since:

 $$ \log100=2 $$ 

Therefore:

 $$ \begin{aligned}&E=1.10-\frac{0.0591}{2}\times2\\ &\\ &\quad=1.10-0.0591\\ \end{aligned} $$ 

 $$ =1.0409 $$ 

 $$ \approx1.04V $$ 

Step 4: Interpretation.

Since:

 $$ Q>1 $$ 

the cell potential decreases from its standard value.

Hence:

 $$ E<E^{\circ} $$ 

which agrees with our result.

Step 5: Final conclusion.

 $$ E_{cell}=1.04V $$ 

Therefore:

Quick Tip: If

     $ Q > 1 $

then

     $ E_{cell} < E_{cell}^{\circ} $

If

     $ Q < 1 $

then

     $ E_{cell} > E_{cell}^{\circ} $

This shortcut helps eliminate options quickly.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.240Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5329, 5, NULL, NULL, 'A first-order reaction has a rate constant of  $ 2.0 \times 10^{-3} $ s $ ^{-1} $ at 300 K and  $ 8.0 \times 10^{-3} $ s $ ^{-1} $ at 330 K. Assuming the Arrhenius equation to be valid, the activation energy of the reaction is closest to:', NULL, '[{"text":"28.5 kJ mol^{-1}","image_url":null,"alt":null},{"text":"38.0 kJ mol $ ^{-1} $","image_url":null,"alt":null},{"text":"57.0 kJ mol $ ^{-1} $","image_url":null,"alt":null},{"text":"76.0 kJ mol^{-1}","image_url":null,"alt":null}]', NULL, 1, 'Concept:

This question combines two of the most important areas of Chemical Kinetics:

• First-order reactions

• Arrhenius equation

The Arrhenius equation relates the rate constant to temperature and activation energy. For two temperatures:

 $$ \log\left(\frac{k_{2}}{k_{1}}\right)=\frac{E_{a}}{2.303R}\left(\frac{1}{T_{1}}-\frac{1}{T_{2}}\right) $$ 

where:

 $$ k_{1},k_{2} $$ 

are the rate constants,

 $$ T_{1},T_{2} $$ 

are absolute temperatures,

and

 $$ E_{a} $$ 

is the activation energy.

Step 1: Write the given data carefully.

 $$ k_{1}=2.0\times10^{-3}s^{-1} $$ 

 $$ T_{1}=300K $$ 

 $$ k_{2}=8.0\times10^{-3}s^{-1} $$ 

 $$ T_{2}=330K $$ 

Step 2: Calculate the ratio of rate constants.

 $$ \begin{array}{l}\frac{k_{2}}{k_{1}}=\frac{8\times10^{-3}}{2\times10^{-3}}\\ =4 \end{array} $$ 

Therefore:

 $$ \begin{aligned}\log\left(\frac{k_{2}}{k_{1}}\right)&=\log4\\ &=0.602\end{aligned} $$ 

Step 3: Calculate the temperature factor.

 $$ \begin{array}{l} \left(\begin{array}{c} \displaystyle \frac{1}{300}-\frac{1}{330} \\ \end{array}\right) \\ = \frac{330 - 300}{300 \times 330} \\ = \frac{30}{99000} \end{array} $$ 

 $$ =3.03\times10^{-4} $$ 

Step 4: Substitute into Arrhenius equation.

 $$ 0.602=\frac{E_{a}}{2.303\times8.314}\times3.03\times10^{-4} $$ 

 $$ 0.602=\frac{E_{a}}{19.147}\times3.03\times10^{-4} $$ 

 $$ \begin{aligned}&E_{a}=\frac{0.602\times19.147}{3.03\times10^{-4}}\\ &\\ &=3.80\times10^{4}J mol^{-1}\\ \end{aligned} $$ 

 $$ =38.0kJ~mol^{-1} $$ 

#### Step 5: Interpretation of activation energy.

Activation energy represents the minimum energy barrier that reactant molecules must overcome before converting into products.

A larger activation energy means:

Slower reaction at a given temperature

• Greater temperature dependence

Fewer molecules possessing sufficient energy

Step 6: Final conclusion.

 $$ E_{a}=38.0kJmol^{-1} $$ 

Hence:

Option (B)

Quick Tip: For Arrhenius numericals:

 $$ \log\left(\frac{k_{2}}{k_{1}}\right)=\frac{E_{a}}{2.303R}\left(\frac{1}{T_{1}}-\frac{1}{T_{2}}\right) $$ 

Always calculate the  $ k_{2}/k_{1} $ ratio first. Most CUET questions become straightforward after this step.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.240Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5330, 5, NULL, NULL, 'A coordination compound has the formula

 $$ [C o(N H_{3})_{4}C l_{2}]C l $$ 

The magnetic moment of the complex is found to be approximately 4.9 BM. The hybridization and geometry of the complex ion are respectively:', NULL, '[{"text":"$ dsp^{2} $, square planar","image_url":null,"alt":null},{"text":"$ sp^{3} $, tetrahedral","image_url":null,"alt":null},{"text":"$ d^{2}sp^{3} $, octahedral","image_url":null,"alt":null},{"text":"$ sp^{3}d^{2} $, octahedral","image_url":null,"alt":null}]', NULL, 3, 'Concept:

This question integrates:

• Coordination compounds

• Oxidation state

• Crystal Field Theory

• Magnetic moment

• Hybridization

Such integrated questions are extremely common in CUET.

Step 1: Determine the oxidation state of cobalt.

The complex is:

 $$ [C o(N H_{3})_{4}C l_{2}]^{+} $$ 

because one chloride ion is present outside the coordination sphere.

Let oxidation state of Co be x.

 $$ x+4(0)+2(-1)=+1 $$ 

 $$ x-2=1 $$ 

 $$ x=+3 $$ 

Therefore:

 $$ Co^{3+} $$ 

Step 2: Determine the electronic configuration.

Atomic number of cobalt:

Electronic configuration:

 $$ [A r]3d^{7}4s^{2} $$ 

For:

 $$ Co^{3+} $$ 

remove three electrons.

 $$ 3d^{6} $$ 

Thus:

 $$ Co^{3+}=d^{6} $$ 

Step 3: Use magnetic moment data.

Given:

 $$ \mu\approx4.9B M $$ 

Using:

 $$ \mu=\sqrt{n(n+2)} $$ 

where n is the number of unpaired electrons.

Checking:

 $$ \sqrt{4(4+2)}=\sqrt{24}=4.90 $$ 

Thus:

 $$ n=4 $$ 

Hence the complex contains four unpaired electrons.

Step 4: Determine field strength.

Presence of four unpaired electrons indicates a weak-field situation.

No pairing occurs.

Therefore:

 $$ t_{2g}^{4}e_{g}^{2} $$ 

High-spin arrangement.

Step 5: Determine hybridization.

For high-spin octahedral complexes:

 $$ sp^{3}d^{2} $$ 

hybridization occurs using outer orbitals.

Geometry remains:

Octahedral

Step 6: Eliminate remaining options.

Option (A):

Square planar complexes usually show  $ dsp^{2} $.

Not applicable.

Option (B):

Coordination number is 6, not 4.

Incorrect.

Option (C):

Would represent low-spin inner orbital complex.

Magnetic moment does not support this.

Step 7: Final conclusion.

Hybridization:

 $$ sp^{3}d^{2} $$ 

Geometry:

Octahedral

Hence:

Option (D)

Quick Tip: Remember:

High-spin octahedral complex

 $$ \rightarrow sp^{3}d^{2} $$ 

Low-spin octahedral complex

 $$ \rightarrow d^{2}sp^{3} $$ 

Magnetic moment is often the key to distinguishing between them.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5331, 5, NULL, NULL, 'EDTA forms a stable complex with a metal ion  $ M^{3+} $. The complex formed is octahedral and represented as  $ [M(EDTA)]^{-} $. Which of the following statements is correct?', NULL, '[{"text":"EDTA acts as a tetradentate ligand and the complex shows geometrical isomerism only","image_url":null,"alt":null},{"text":"EDTA acts as a hexadentate ligand and the complex can show optical isomerism","image_url":null,"alt":null},{"text":"EDTA acts as a bidentate ligand and the complex shows linkage isomerism","image_url":null,"alt":null},{"text":"EDTA acts as a monodentate ligand and the complex is tetrahedral","image_url":null,"alt":null}]', NULL, 1, 'Concept:

This question combines three important CUET topics:

• Denticity of ligands

• Coordination number

• Isomerism in coordination compounds

Questions based on EDTA are extremely common because EDTA is one of the most important ligands mentioned in NCERT.

Step 1: Recall the structure of EDTA.

EDTA stands for:

### Ethylenediaminetetraacetate

It contains:

• Two nitrogen donor atoms

• Four oxygen donor atoms

Therefore total donor atoms:

2+4=6

Hence EDTA is a:

Hexadentate ligand

Step 2: Determine the coordination number.

Since EDTA donates six lone pairs simultaneously:

Coordination Number = 6

A coordination number of six generally produces:

Octahedral geometry

which agrees with the information given in the question.

Step 3: Examine the possibility of isomerism.

Complexes containing multidentate ligands often possess chirality.

Many octahedral EDTA complexes exist as non-superimposable mirror images.

Therefore they can show:

Optical isomerism

Step 4: Eliminate incorrect options.

Option (A):

EDTA is not tetradentate.

Incorrect.

Option (C):

EDTA is not bidentate.

Incorrect.

Option (D):

EDTA is not monodentate and the complex is not tetrahedral.

Incorrect.

Step 5: Final conclusion.

EDTA acts as:

<div style="text-align: center;"><img src="/local-papers/assets/chemistry-2026-05-31-shift-2/q07-exp-1.jpg" alt="Figure 1 for question 7" /></div>


Hexadentate ligand

and the complex can exhibit:

Optical isomerism

Hence:

Option (B)

Quick Tip: Remember the denticity of common ligands:

 $$ NH_{3},H_{2}O,Cl^{-}\rightarrow Monodentate $$ 

 $$ C_{2}O_{4}^{2-},~en\rightarrow Bidentate $$ 

 $$ EDTA^{4-} \to Hexadentate $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5332, 5, NULL, NULL, 'Which of the following statements regarding lanthanoids is correct?', NULL, '[{"text":"Basicity of lanthanoid hydroxides increases from $ \\mathrm{La(OH)}_{3} $ to $ \\mathrm{Lu(OH)}_{3} $","image_url":null,"alt":null},{"text":"Lanthanoid contraction occurs because of poor shielding by 4f-electrons","image_url":null,"alt":null},{"text":"$ Ce^{4+} $ is less stable than $ Ce^{3+} $ because of its noble gas configuration","image_url":null,"alt":null},{"text":"Atomic size increases regularly from La to Lu","image_url":null,"alt":null}]', NULL, 1, 'Concept:

This question combines:

• Lanthanoid contraction

• Shielding effect

• Basicity trends

• Stability of oxidation states

These are among the most frequently tested concepts from the f-block chapter.

Step 1: Understand lanthanoid contraction.

Across the lanthanoid series:

La  $ \rightarrow $ Lu

electrons are added to the:

4f

subshell.

The shielding provided by 4f-electrons is poor.

As a result, the effective nuclear charge increases.

Consequently:

Atomic and ionic radii decrease gradually

This phenomenon is called:

Lanthanoid contraction

Step 2: Analyze Option (A).

Basicity actually decreases from:

 $$ La(OH)_{3} $$ 

to

 $$ Lu(OH)_{3} $$ 

because ionic size decreases.

Hence Option (A) is incorrect.

Step 3: Analyze Option (B).

Poor shielding by:

4f

electrons is indeed responsible for lanthanoid contraction.

Hence:

Option (B) is correct

Step 4: Analyze Option (C).

 $ Ce^{4+} $ possesses:

[Xe]

configuration.

This noble-gas configuration makes it unusually stable.

Hence Option (C) is incorrect.

Step 5: Analyze Option (D).

Atomic size decreases rather than increases.

Hence Option (D) is incorrect.

Step 6: Final conclusion.

Option (B)

is the correct answer.

Quick Tip: Lanthanoid Contraction:

Poor 4f shielding  $ \rightarrow $ Increase in  $ Z_{eff} $  $ \rightarrow $ Decrease in size

This is one of the highest-yield NCERT facts from the f-block chapter.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.241Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5333, 5, NULL, NULL, 'Consider the following statements regarding carbohydrates:

Assertion (A): Sucrose is a non-reducing sugar.

Reason (R): In sucrose, both the anomeric carbon atoms of glucose and fructose participate in glycosidic bond formation.

Choose the correct option.', NULL, '[{"text":"Both Assertion and Reason are true, and Reason is the correct explanation of Assertion","image_url":null,"alt":null},{"text":"Both Assertion and Reason are true, but Reason is not the correct explanation of Assertion","image_url":null,"alt":null},{"text":"Assertion is true, but Reason is false","image_url":null,"alt":null},{"text":"Assertion is false, but Reason is true","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Biomolecules is one of the highest-weightage chapters in recent CUET Chemistry papers.

Questions are frequently asked from:

• Reducing and non-reducing sugars

• Glycosidic linkage

• Mutarotation

• Structure of sucrose

## • Structure of cellulose and starch

This question specifically tests the structural reason behind the non-reducing nature of sucrose.

Step 1: Understand what makes a sugar reducing.

A carbohydrate behaves as a reducing sugar when it possesses a free:

## Anomeric carbon

that can open to form an aldehyde or ketone group.

Examples:

Glucose

Maltose

Lactose

These sugars can reduce:

 $$ Ag^{+} $$ 

(Tollen''s reagent)

or

 $$ C u^{2+} $$ 

(Fehling''s solution).

Step 2: Recall the structure of sucrose.

Sucrose consists of:

 $ \alpha $-D-Glucose

and

 $ \beta $-D-Fructose

joined through a glycosidic linkage.

The linkage is:

 $$ \alpha(1\to2)\beta $$ 

This means:

• Carbon-1 of glucose participates.

• Carbon-2 of fructose participates.

Both of these carbons are anomeric carbons.

Step 3: Determine whether any free anomeric carbon remains.

Since both anomeric carbons are involved in bond formation:

No free anomeric carbon remains

Therefore sucrose cannot open into a free aldehyde or ketone form.

Hence:

Step 4: Evaluate the Assertion.

Sucrose is non-reducing

Assertion:

Sucrose is a non-reducing sugar.

This statement is correct.

Assertion = True

Step 5: Evaluate the Reason.

Reason:

Both anomeric carbon atoms participate in glycosidic bond formation.

This statement is also correct.

Reason = True

Step 6: Check whether the Reason explains the Assertion.

Because both anomeric carbons are involved:

No free reducing end exists

Therefore sucrose cannot behave as a reducing sugar.

Thus the Reason directly explains the Assertion.

### Reason correctly explains Assertion

Step 7: Final conclusion.

Both statements are true and the Reason correctly explains the Assertion.

Hence:

Option (A)

### Quick Tip: Quick NCERT Revision:

Reducing Sugars:

Non-Reducing Sugar:

Glucose, Maltose, Lactose

Sucrose

Reason: Both anomeric carbons participate in glycosidic bond formation, leaving no free reducing end.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.242Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5334, 7, NULL, NULL, 'Which SQL command is used to remove all rows from a table without deleting the table structure?', NULL, '[{"text":"DELETE","image_url":null,"alt":null},{"text":"DROP","image_url":null,"alt":null},{"text":"TRUNCATE","image_url":null,"alt":null},{"text":"REMOVE","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Understanding the Concept:

In SQL, there are different Data Manipulation Language (DML) and Data Definition Language (DDL) commands used to manage data and structures.

Step 2: Detailed Explanation:

- DELETE: This is a DML command used to remove rows. However, it is typically slower for removing all rows as it logs each deletion and can be used with a WHERE clause.

- DROP: This command deletes the entire table, including its data and its structure (the

schema).

- TRUNCATE: This is a DDL command that removes all rows from a table. It is faster than DELETE because it doesn''t log individual row deletions, and it preserves the table structure for future use.

Step 3: Final Answer:

The command used to remove all rows while keeping the structure is TRUNCATE.

Quick Tip: Think of it this way: DELETE is like erasing lines in a notebook, TRUNCATE is like ripping out all the pages but keeping the cover, and DROP is like throwing the whole notebook in the trash!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.247Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5335, 7, NULL, NULL, 'What will be the output of the following Python code?

a=[1,2,3]

print(a[::-1])', NULL, '[{"text":"$ [1,2,3] $","image_url":null,"alt":null},{"text":"$ [3,2,1] $","image_url":null,"alt":null},{"text":"Error","image_url":null,"alt":null},{"text":"None","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:

This question tests your knowledge of "Slicing" in Python. Slicing allows you to access a specific range or order of elements in a sequence like a list or string.

Step 2: Detailed Explanation:

The syntax for slicing is [start:stop:step].

• In the code a[::-1], the start and stop values are omitted, which means Python considers the whole list.

- The step value is -1. A negative step means the list is traversed backwards.

• Therefore, a [: -1] creates a new list starting from the last element and moving to the first.
Step 3: Final Answer:
The output will be the reversed list: [3, 2, 1].
Quick Tip: The slice [: -1] is the "Pythonic" way to reverse a list or string. It''s concise, fast, and very common in coding interviews!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.247Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5336, 7, NULL, NULL, 'Which protocol is used for sending e-mails?', NULL, '[{"text":"HTTP","image_url":null,"alt":null},{"text":"SMTP","image_url":null,"alt":null},{"text":"FTP","image_url":null,"alt":null},{"text":"TCP","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:

Networking protocols are sets of rules that govern how data is exchanged across a network. Different tasks (web browsing, file transfer, email) use different protocols.

Step 2: Detailed Explanation:

• HTTP (Hypertext Transfer Protocol): Used for accessing websites.

• FTP (File Transfer Protocol): Used for transferring files between computers.

• SMTP (Simple Mail Transfer Protocol): This is the standard protocol specifically designed for sending emails from a client to a server or between servers.

- TCP (Transmission Control Protocol): A foundational protocol that ensures reliable delivery of data packets, but it isn''t specific to email content.

##### Step 3: Final Answer:

The protocol used for sending emails is SMTP.

Quick Tip: To remember this, think of the "S" in SMTP as standing for "Sending" Mail. For receiving mail, we typically use POP3 or IMAP.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.248Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5337, 7, NULL, NULL, 'In Python, which data type is immutable?', NULL, '[{"text":"List","image_url":null,"alt":null},{"text":"Dictionary","image_url":null,"alt":null},{"text":"Set","image_url":null,"alt":null},{"text":"Tuple","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Concept:

In programming, "mutability" refers to whether an object''s state or content can be changed after it is created. Immutable objects cannot be changed, while mutable objects can.

Step 2: Detailed Explanation:

- Mutable (Can change): Lists, Dictionaries, and Sets allow you to add, remove, or modify elements in place.

• Immutable (Cannot change): Tuples, Strings, and Integers do not allow modification.

Once a tuple is created, you cannot change its elements or its size.

Step 3: Final Answer:

The Tuple is the immutable data type among the options.

Quick Tip: Think of a List as a pencil-written list (you can erase and change it) and a Tuple as one written in permanent ink. Use Tuples when you want to make sure your data stays constant throughout the program.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.249Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5338, 7, NULL, NULL, 'Which of the following is NOT a valid aggregate function in SQL?', NULL, '[{"text":"AVG()","image_url":null,"alt":null},{"text":"SUM()","image_url":null,"alt":null},{"text":"COUNT()","image_url":null,"alt":null},{"text":"COMPUTE()","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Concept:

Aggregate functions in SQL perform a calculation on a set of values and return a single value. They are often used with the GROUP BY clause.

Step 2: Detailed Explanation:

Standard SQL aggregate functions include:

• AVG(): Calculates the average value.

- SUM(): Adds up all the values.

• COUNT(): Counts the number of rows.

• MAX() / MIN(): Finds the highest and lowest values.

COMPUTE() is not a standard aggregate function in modern SQL. While some legacy systems had a COMPUTE clause for generating summary rows, it is not a standard function used in SELECT statements like the others.

Step 3: Final Answer:

COMPUTE() is not a valid aggregate function.

Quick Tip: Aggregate functions usually ignore NULL values, except for COUNT(), which counts every row regardless of content.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.249Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5339, 7, NULL, NULL, 'What is the full form of URL?', NULL, '[{"text":"Uniform Resource Locator","image_url":null,"alt":null},{"text":"Universal Resource Link","image_url":null,"alt":null},{"text":"Uniform Reference Link","image_url":null,"alt":null},{"text":"Unified Resource Locator","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Understanding the Concept:

A URL is the global address of documents and other resources on the World Wide Web.

#### Step 2: Detailed Explanation:

The acronym stands for Uniform Resource Locator.

• Uniform: It follows a standard format.

• Resource: It points to a file, page, or image.

• Locator: It provides the "location" or address of that resource on the internet.

Step 3: Final Answer:

The full form of URL is Uniform Resource Locator.

Quick Tip: A URL consists of several parts: the protocol (http://), the domain name (google.com), and the path (/search). Together, they tell your browser exactly where to find a specific resource.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.250Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5340, 7, NULL, NULL, 'Which keyword is used to define a function in Python?', NULL, '[{"text":"function","image_url":null,"alt":null},{"text":"define","image_url":null,"alt":null},{"text":"def","image_url":null,"alt":null},{"text":"func","image_url":null,"alt":null}]', NULL, 2, '### Step 1: Understanding the Concept:

In programming, a function is a reusable block of code that performs a specific task. Every language has a specific "reserved word" or keyword to tell the interpreter that a function is being created.

### Step 2: Detailed Explanation:

In Python, the keyword used is def, which is short for "define."

• The syntax follows the structure: def function_name():

- Unlike some other languages like JavaScript (which uses function) or C++ (which uses the return type), Python keeps it concise with three letters.

### Step 3: Final Answer:

The keyword used to define a function in Python is def.

Quick Tip: Remember that Python is designed for readability and brevity. Most of its keywords are short (e.g., ''def'', ''elif'', ''pass'').', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.250Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5341, 7, NULL, NULL, 'Which topology uses a central hub/switch?', NULL, '[{"text":"Ring Topology","image_url":null,"alt":null},{"text":"Bus Topology","image_url":null,"alt":null},{"text":"Mesh Topology","image_url":null,"alt":null},{"text":"Star Topology","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Concept:

Network topology refers to the physical or logical layout of a network—how various nodes (computers, printers) are connected to each other.

##### Step 2: Detailed Explanation:

- Star Topology: Every node is connected to a central device (a hub, switch, or router).

All data passes through this central point before reaching its destination.

• Bus Topology: All nodes share a single main cable (the "bus").

• Ring Topology: Each node is connected to exactly two other nodes, forming a continuous circle.

- Mesh Topology: Every node is connected to every other node (or many others) for high redundancy.

Step 3: Final Answer:

The Star Topology uses a central hub or switch.

Quick Tip: Star topology is the most common layout in modern office and home networks because if one computer''s cable breaks, the rest of the network keeps working!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.251Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5342, 7, NULL, NULL, 'What will be the output?

x = 5

y = 2

print(x // y)', NULL, '[{"text":"2.5","image_url":null,"alt":null},{"text":"2","image_url":null,"alt":null},{"text":"3","image_url":null,"alt":null},{"text":"Error","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:

Python provides different types of division operators: / for standard division and // for "Floor Division."

#### Step 2: Detailed Explanation:

1. Standard division (5/2) would result in 2.5. 2. Floor division (5//2) performs the division and then "rounds down" to the nearest whole integer. 3. Mathematically:  $ 5 \div 2 = 2.5 $. The "floor" of 2.5 is 2. Note: If the result is negative, it still rounds down (away from zero). For example, -5//2 would be -3.

Step 3: Final Answer:

The output of 5 // 2 is 2.

Quick Tip: To remember the difference: - ‘/’ gives you the decimal. - ‘//’ gives you the integer (quotient).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.251Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5343, 7, NULL, NULL, 'Which clause is used to filter records in SQL?', NULL, '[{"text":"ORDER BY","image_url":null,"alt":null},{"text":"GROUP BY","image_url":null,"alt":null},{"text":"WHERE","image_url":null,"alt":null},{"text":"HAVING","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Understanding the Concept:

Filtering is the process of selecting specific rows from a table that meet a certain criteria, while hiding the rows that do not.

Step 2: Detailed Explanation:

ORDER BY: Used to sort the result set in ascending or descending order.

GROUP BY: Used to arrange identical data into groups, often used with aggregate functions.

• WHERE: This is the primary clause used to filter records. It acts on individual rows before any grouping occurs. For example: SELECT FROM students WHERE age > 18;

- HAVING: Also used for filtering, but it specifically filters groups created by the GROUP BY clause, not individual rows.

Step 3: Final Answer:

The WHERE clause is used to filter records.

Quick Tip: A common interview question is the difference between ''WHERE'' and ''HAVING''. Just remember: WHERE filters the rows before they are grouped, and HAVING filters the results after they are grouped.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.252Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5344, 7, NULL, NULL, 'Which switching technique is used in the Internet?', NULL, '[{"text":"Circuit switching","image_url":null,"alt":null},{"text":"Packet switching","image_url":null,"alt":null},{"text":"Message switching","image_url":null,"alt":null},{"text":"Line switching","image_url":null,"alt":null}]', NULL, 1, '### Step 1: Understanding the Question:

The question asks for the fundamental data transmission mechanism employed by the global Internet to route information from source to destination.

### Step 2: Detailed Explanation:

• The Internet operates primarily on the TCP/IP protocol suite, which relies on packet switching technology.

• In packet switching, data is broken down into smaller, manageable units called packets before transmission.

• Each packet contains a payload (the actual data) and a header (which includes source and destination IP addresses).

• Unlike circuit switching, packet switching does not require a dedicated physical path to be established between the sender and receiver.

• Instead, packets travel independently across the network and can take different paths to reach the same destination.

• Routers along the way examine the destination address in the header of each packet to determine the next hop.

- Once all packets arrive at the destination, they are reassembled in the correct order to recreate the original message.

- This method is highly efficient as it maximizes bandwidth utilization by allowing multiple users to share the same physical communication channels.

• If a packet is lost or corrupted during transit, only that specific packet needs to be retransmitted, rather than the entire message.

##### Step 3: Final Answer:

Therefore, packet switching is the core switching technique utilized in the Internet, making option (B) the correct answer.

Quick Tip: Remember that public switched telephone networks (PSTN) use circuit switching, which reserves a dedicated path, whereas data networks like the Internet use packet switching for resource sharing and resilience.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.253Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5345, 7, NULL, NULL, 'Telephone conversation is an example of', NULL, '[{"text":"Simplex","image_url":null,"alt":null},{"text":"Half duplex","image_url":null,"alt":null},{"text":"Full duplex","image_url":null,"alt":null},{"text":"Message switching","image_url":null,"alt":null}]', NULL, 2, '#### Step 1: Understanding the Question:

The question asks us to identify the transmission mode of a standard telephone conversation from the given communication modes.

#### Step 2: Detailed Explanation:

• In data communication, transmission mode refers to the direction of signal flow between two connected devices.

• There are three primary modes: simplex, half-duplex, and full-duplex.

• In simplex mode, communication is strictly unidirectional, where one device transmits and the other only receives (e.g., traditional television broadcasting).

• In half-duplex mode, communication is bidirectional, but only one party can transmit at a time (e.g., walkie-talkies where users must wait for the other to finish speaking).

• In full-duplex mode, communication is bidirectional and simultaneous, meaning both parties can transmit and receive data at the same time.

- A telephone conversation allows both participants to speak and hear each other simultaneously without any delay or waiting for the channel to clear.

• This capability makes a telephone conversation a classic example of full-duplex communication.

• This is achieved by using two separate transmission paths or frequency bands within the same communication medium.

#### Step 3: Final Answer:

Hence, a telephone conversation is an example of full-duplex transmission, corresponding to option (C).

Quick Tip: Remember that full-duplex allows simultaneous bidirectional communication (like modern phones), while half-duplex is bidirectional but non-simultaneous (like walkie-talkies).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5346, 7, NULL, NULL, 'Linear search works best on:', NULL, '[{"text":"Sorted list only","image_url":null,"alt":null},{"text":"Unsorted list","image_url":null,"alt":null},{"text":"Binary tree","image_url":null,"alt":null},{"text":"Graph","image_url":null,"alt":null}]', NULL, 1, '#### Step 1: Understanding the Question:

The question aims to identify the data structure configuration or state where linear search is the most suitable or standard searching method.

##### Step 2: Detailed Explanation:

- Linear search (or sequential search) is a fundamental algorithm that checks each element of a list sequentially until a match is found or the end is reached.

• In a sorted list, highly efficient algorithms like binary search can find elements in logarithmic time,  $ O(\log n) $, making linear search inefficient there.

However, when a list is unsorted, there is no inherent order to exploit, meaning we cannot skip any elements using binary search or other divide-and-conquer methods.

Thus, for an unsorted list, a sequential scan using linear search is the only straightforward and direct option available.

• While its worst-case time complexity is $O(n)$ regardless of the sorting status, linear search is considered the best choice for unsorted or small datasets where sorting overhead is not justified.

- Binary trees and graphs require specialized traversal algorithms like Depth First Search (DFS) or Breadth First Search (BFS) rather than simple linear search.

Step 3: Final Answer:

Therefore, linear search is best suited for an unsorted list, which corresponds to option (B).

Quick Tip: If a list is already sorted, always prefer binary search over linear search because its time complexity is significantly lower. For unsorted lists, linear search is the standard choice.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5347, 7, NULL, NULL, 'Which keyword is used to define a function in Python?', NULL, '[{"text":"function","image_url":null,"alt":null},{"text":"define","image_url":null,"alt":null},{"text":"def","image_url":null,"alt":null},{"text":"fun","image_url":null,"alt":null}]', NULL, 2, '#### Step 1: Understanding the Question:

This question asks for the specific reserved word (keyword) used in Python syntax to declare and define a user-defined function.

Step 2: Detailed Explanation:

• In Python, functions are defined using the reserved keyword def.

• The general syntax of a function definition in Python is as follows:

def function_name(parameters): followed by an indented block of code representing the function body.

• Let us evaluate the alternative options:

• Option (A) function is used in languages like JavaScript, PHP, and Swift to define functions, but it is not a keyword in Python.

• Option (B) define is used in some macro systems (like C/C++ preprocessors via #define) but is not a valid Python keyword for functions.

• Option (D) fun is used in languages such as Kotlin and Rust (which uses fn) but is incorrect in the context of Python.

• The def keyword stands for "define" and is a core part of Python''s simple and readable syntax.

Step 3: Final Answer:

Therefore, the correct keyword to define a function in Python is def, which corresponds to option (C).

Quick Tip: Python uses very concise keywords. For defining functions, always use def, and remember that Python function definitions must be followed by a colon and indentation.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.254Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5348, 7, NULL, NULL, 'Which operator is used for logical AND?', NULL, '[{"text":"&&","image_url":null,"alt":null},{"text":"and","image_url":null,"alt":null},{"text":"&","image_url":null,"alt":null},{"text":"AND","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Understanding the Question:

The question asks for the standard operator used to perform a logical AND operation in programming languages.

Step 2: Detailed Explanation:

- Logical operators are used to combine multiple boolean conditions and return a boolean

result based on the truth values of the operands.

• In the majority of widely used programming languages (such as C, C++, Java, JavaScript, and C#), the double ampersand && is the standard symbol for logical AND.

- A logical AND operation evaluates to true if and only if both of its operands are true; otherwise, it evaluates to false.

• In contrast, a single ampersand & represents a bitwise AND operator, which performs operations at the binary digit level rather than evaluating overall logical truth.

• In some languages like Python, the keyword and is used for logical operations, but in standard computer science curriculum questions, && is typically the primary symbol taught.

Thus, looking at the choices, both && and are used in different environments, but && represents the classical symbolic logical AND operator across most C-family languages.

##### Step 3: Final Answer:

Thus, the operator used for logical AND in most standard programming languages is &&, matching option (A).

Quick Tip: Be careful with single vs double symbols: && is logical AND, while & is bitwise AND. In Python, the word and is used instead of symbols.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.255Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5349, 7, NULL, NULL, 'Which one of the following is the Middle element index formula:', NULL, '[{"text":"$ (low + high)/2 $","image_url":null,"alt":null},{"text":"low $ \\times $ high","image_url":null,"alt":null},{"text":"high - low","image_url":null,"alt":null},{"text":"low/high","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Understanding the Question:

The question asks for the correct mathematical formula used to calculate the index of the middle element in a sub-array during algorithms like binary search.

#### Step 2: Key Formula or Approach:

When searching an array between a lower bound index low and an upper bound index high, we find the midpoint to divide the search space.

#### Step 3: Detailed Explanation:

- To find the exact midpoint of a range bounded by low and high, we calculate the arithmetic mean of the two boundaries.

• This is represented as:

 $$ mid=\frac{low+high}{2} $$ 

• In integer arithmetic, this division is typically truncated or floor-divided to produce an integer index.

• Let us look at why the other options are mathematically incorrect for finding a midpoint:

• Option (B) low × high performs multiplication, which yields an unrelated, very large index value.

• Option (C) high—low computes the distance or size of the range, not the midpoint index itself.

• Option (D) low/high computes a ratio, which is typically close to zero and does not represent a middle index.

• Note: While  $ (low + high)/2 $ is standard, in systems with large arrays, it can cause integer overflow if low + high exceeds the maximum value of a 32-bit integer. To prevent this, the formula can also be written as  $ low + (high - low)/2 $.

#### Step 4: Final Answer:

Hence, the standard formula to find the middle element index is  $ (low + high)/2 $, which is option (A).

Quick Tip: Standard midpoint formula is  $ (low + high)/2 $. For overflow-safe implementations in competitive coding, write it as  $ low + (high - low)/2 $.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.255Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5350, 7, NULL, NULL, 'Which of the following is NOT an element of communication?', NULL, '[{"text":"Sender","image_url":null,"alt":null},{"text":"Receiver","image_url":null,"alt":null},{"text":"Feedback","image_url":null,"alt":null},{"text":"Compiler","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Question:

The question asks us to identify which of the given terms is not a component of the standard communication process or system.

#### Step 2: Detailed Explanation:

• A standard communication system consists of several essential elements that enable the transmission of information from one point to another.

• The "Sender" (or source) is the entity that originates and encodes the message to be sent.

• The "Receiver" is the target entity that receives and decodes the message.

• The "Feedback" is the response returned by the receiver to the sender, confirming that the message was received and understood.

• Other elements of communication include the message itself, the medium/channel, and noise.

- A "Compiler," on the other hand, is a specialized computer program that translates source code written in a high-level programming language into machine code or lower-level instructions.

- The compiler is a tool in computer programming and software development, and has no direct relation to the basic elements of human or general data communication.

##### Step 3: Final Answer:

Thus, Compiler is NOT an element of communication, which aligns with option (D).

Quick Tip: The core elements of communication are Sender, Message, Channel, Receiver, and Feedback. A compiler is a software translation tool and does not belong to this communication cycle.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.256Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5351, 7, NULL, NULL, 'Linear search is useful when:', NULL, '[{"text":"Data is small","image_url":null,"alt":null},{"text":"Data is unsorted","image_url":null,"alt":null},{"text":"Both A and B","image_url":null,"alt":null},{"text":"None","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Understanding the Question:

The question explores the specific conditions under which linear search is considered practical, efficient, or necessary.

Step 2: Detailed Explanation:

- Linear search compares every element of a list sequentially until the target element is found or the list ends.

- First, consider when data is small: For small lists, the overhead of sorting the list to apply more complex algorithms like binary search is not worth the computational cost.

- Linear search performs very fast in practice for small inputs because of its simple design and minimal overhead.

•;; Second, consider when data is unsorted: In an unsorted array, we cannot make any assumptions about where elements reside.

• Because there is no order, we cannot use divide-and-conquer algorithms like binary search.

• Hence, linear search is the only viable standard option to search for a value in an unsorted

##### array.

• Thus, both statements (A) "Data is small" and (B) "Data is unsorted" are correct scenarios where linear search is highly useful and appropriate.

Step 3: Final Answer:

Therefore, linear search is useful under both conditions, making option (C) the correct answer.

Quick Tip: While binary search has a better time complexity, it requires the data to be sorted. Linear search is the go-to method when the dataset is unsorted or very small.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.256Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5352, 7, NULL, NULL, 'Telephone conversation is an example of:', NULL, '[{"text":"Simplex","image_url":null,"alt":null},{"text":"Half Duplex","image_url":null,"alt":null},{"text":"Full Duplex","image_url":null,"alt":null},{"text":"Multiplex","image_url":null,"alt":null}]', NULL, 2, 'Communication modes describe the direction of data flow between devices.

• Simplex: One-way communication only.

• Half Duplex: Both directions, but one at a time.

• Full Duplex: Both directions simultaneously.

Step 1: Analyze telephone communication

During a telephone call, both persons can speak and listen at the same time.

Step 2: Identify the communication mode

Since communication occurs simultaneously in both directions, it is a full duplex system.

Final Answer:

Full Duplex

Quick Tip: Mobile phones and landline telephones are examples of full duplex communication.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.257Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5353, 7, NULL, NULL, 'Linear search works best on:', NULL, '[{"text":"Sorted list","image_url":null,"alt":null},{"text":"Unsorted list","image_url":null,"alt":null},{"text":"Binary tree","image_url":null,"alt":null},{"text":"Hash table","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Linear search checks each element one by one until the desired item is found.

Step 1: Understand linear search

In linear search, elements are examined sequentially from the beginning to the end of the list.

Step 2: Determine where it is useful

Linear search does not require the data to be sorted. Therefore, it is most useful for unsorted lists.

Final Answer:

Unsorted List

Quick Tip: Linear search can work on both sorted and unsorted data, but it is especially useful when data is unsorted.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.258Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5354, 7, NULL, NULL, 'Which search method has logarithmic complexity?', NULL, '[{"text":"Linear Search","image_url":null,"alt":null},{"text":"Binary Search","image_url":null,"alt":null},{"text":"Sequential Search","image_url":null,"alt":null},{"text":"Traversal","image_url":null,"alt":null}]', NULL, 1, '#### Concept:

Time complexity measures the number of operations required by an algorithm as the size of input increases.

Step 1: Recall complexities

 $$  Linear~Search=O(n) $$ 

#### Step 2: Identify logarithmic search

 $$  Binary~Search=O(\log n) $$ 

Binary search repeatedly divides the search space into two halves, reducing the number of comparisons significantly.

Final Answer:

Binary Search

Quick Tip: Binary Search requires the data to be sorted before searching.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.258Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5355, 7, NULL, NULL, 'Who developed Python programming language?', NULL, '[{"text":"Dennis Ritchie","image_url":null,"alt":null},{"text":"James Gosling","image_url":null,"alt":null},{"text":"Guido van Rossum","image_url":null,"alt":null},{"text":"Bjarne Stroustrup","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Python is a high-level, interpreted, and general-purpose programming language.

Step 1: Recall the creator of Python

Python was developed by Guido van Rossum in the late 1980s and was officially released in 1991.

Step 2: Compare with other options

• Dennis Ritchie developed C.

• James Gosling developed Java.

Bjarne Stroustrup developed C++.

Therefore, Python was developed by Guido van Rossum.

Final Answer:

Guido van Rossum

Quick Tip: Python was named after the comedy series "Monty Python''s Flying Circus," not after the snake.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:29.261Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5356, 7, NULL, NULL, 'Which keyword is used to define a function in Python?', NULL, '[{"text":"function","image_url":null,"alt":null},{"text":"define","image_url":null,"alt":null},{"text":"def","image_url":null,"alt":null},{"text":"fun","image_url":null,"alt":null}]', NULL, 2, 'Concept:

A function is a reusable block of code that performs a specific task. In Python, functions are created using the def keyword.

Step 1: Recall the syntax for function definition

General syntax:

def function_name():

Example:
def add(a, b):
    return a + b
Step 2: Identify the correct keyword
