Misanthrope  $ \rightarrow $ Person who dislikes people

Sociable  $ \rightarrow $ Friendly and social', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:37.588Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
