INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5874, 13, NULL, NULL, 'Identify the ''Entrepot Port'' among the following:', NULL, '[{"text":"Singapore","image_url":null,"alt":null},{"text":"London","image_url":null,"alt":null},{"text":"Rotterdam","image_url":null,"alt":null},{"text":"All of the above","image_url":null,"alt":null}]', NULL, 3, 'Concept: An entrepot port is a port where imported goods are stored and re-exported to other countries.

Such ports function as important international trade and distribution centers.

Step 1: Analyze Singapore.

Singapore is a major international re-export trade center.

####  $ \Rightarrow $ Entrepot Port

