to other countries.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:37.804Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5875, 13, NULL, NULL, 'Which of the following factors affects the rural settlement patterns?

1. Water Supply
