INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5971, 3, NULL, NULL, 'Line through  $ (1,2,3) $ parallel to  $ \hat{i} + 2\hat{j} + 3\hat{k} $:', NULL, '[{"text":"$ \\frac{x-1}{1} = \\frac{y-2}{2} = \\frac{z-3}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{x}{1} = \\frac{y}{2} = \\frac{z}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{x+1}{1} = \\frac{y+2}{2} = \\frac{z+3}{3} $","image_url":null,"alt":null},{"text":"$ \\frac{x-1}{2} = \\frac{y-2}{3} = \\frac{z-3}{1} $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Equation of a line passing through point:

 $$ (x_{1},y_{1},z_{1}) $$ 

and parallel to vector:

 $$ a\hat{i}+b\hat{j}+c\hat{k} $$ 

is:

 $$ \frac{x-x_{1}}{a}=\frac{y-y_{1}}{b}=\frac{z-z_{1}}{c} $$ 

Step 1: Identifying point and direction ratios.

Given point:

