INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6206, 4, NULL, NULL, 'Which of the following statements is not true about electric field lines?', NULL, '[{"text":"Electric field lines start from positive charge and end at negative charge.","image_url":null,"alt":null},{"text":"Two electric field lines can never cross each other.","image_url":null,"alt":null},{"text":"Electrostatic field lines do not form any closed loops.","image_url":null,"alt":null},{"text":"Electric field lines cannot be taken as continuous curve","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Understanding the Concept:
Electric field lines are imaginary geometric pathways used to visualize the direction and
strength of an electric field in space. The tangent drawn to a field line at any point indicates
the direction of the electric force vector acting on a positive test charge at that location. These
lines possess fundamental physical properties based on conservative electrostatic laws.
Step 2: Key Formula or Approach:
We evaluate each option against the standard properties of electrostatic field lines: Lines
emerge from positive sources and terminate on negative sinks. Field vectors have a single
unique direction at any given point in space. Electrostatic fields are conservative, meaning
the loop integral
H⃗
E ·⃗dℓ= 0. Field lines must form continuous curves in a charge-free space
because electric forces do not suddenly drop or break without a terminating charge.
Step 3: Detailed Explanation:
Option (a) is TRUE: Electric field lines naturally flow from high potential (positive charge) to
low potential (negative charge). Option (b) is TRUE: If two field lines crossed, the intersection
point would have two different tangents, implying two different directions for the electric field
at a single point, which is physically impossible. Option (c) is TRUE: Because the electrostatic
field is conservative, field lines cannot loop back onto themselves. They require a positive start
and a distinct negative finish. Option (d) is FALSE: Electric field lines are entirely continuous
curves that can only break or terminate at the surface of a charge. Therefore, stating they
"cannot be taken as continuous curves" is incorrect, making this the chosen answer.
Step 4: Final Answer:
The statement that is not true is: "Electric field lines cannot be taken as continuous curve".
CUET UG 2026
Page 14 of 16
© Collegedunia.com


--- Page 15 ---
Quick Tip: Remember: "Electric field lines are continuous, but they do NOT form closed loops." This is
a key distinction that separates them from magnetic field lines, which always form closed loops!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.063Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6207, 4, NULL, NULL, 'Two infinite plane parallel sheets, separated by a distance d have equal and opposite uniform charge densities  $ \sigma $. Electric field at a point between the sheets is', NULL, '[{"text":"$ \\frac{\\sigma}{2\\varepsilon_{0}} $","image_url":null,"alt":null},{"text":"$$ \\frac{\\sigma}{\\varepsilon_{0}} $$","image_url":null,"alt":null},{"text":"zero","image_url":null,"alt":null},{"text":"depends on the location of the point","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Understanding the Concept:
