INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6208, 4, NULL, NULL, 'What are the respective numbers of $\alpha$ and $\beta$ particles emitted respectively in the following radioactive decay?

 $$ ^{200}_{90}X \longrightarrow ^{168}_{80}Y $$', NULL, '[{"text":"8 and 8","image_url":null,"alt":null},{"text":"8 and 6","image_url":null,"alt":null},{"text":"6 and 8","image_url":null,"alt":null},{"text":"6 and 6","image_url":null,"alt":null}]', NULL, 2, 'Concept: In a nuclear decay series, the total mass number (A) and total atomic number (Z) must be conserved on both sides of the reaction equation. Let $n_{\alpha}$ be the number of alpha particles emitted and $n_{\beta}$ be the number of beta $(\beta^{-})$ particles emitted:

• An alpha particle (\alpha) is a helium nucleus:  $ ^{4}_{2}\text{He} $. It reduces the mass number by 4 and the atomic number by 2.

- A beta particle  $ (\beta^{-}) $ is an electron:  $ _{-1}^{0}e $. It leaves the mass number unchanged and increases the atomic number by 1.

The balanced nuclear equation is represented as:

 $$ \begin{array}{l}\overset{200}{}_{90}X\longrightarrow\overset{168}{}_{80}Y+n_{\alpha}\left(\overset{4}{}_{2}\mathrm{H e}\right)+n_{\beta}\left(\overset{0}{-}_{1}\mathrm{e}\right)\end{array} $$ 

Step 1: Conserve the total Mass Number (A) to find the number of alpha particles. Equating the mass numbers from both sides of the equation:

 $$ 200=168+n_{\alpha}(4)+n_{\beta}(0) $$ 

 $$ 200=168+4n_{\alpha} $$ 

Subtracting 168 from both sides:

 $$ 4n_{\alpha}=200-168=32 $$ 

 $$ n_{\alpha}=\frac{32}{4}=6 $$ 

Thus, the total number of emitted  $ \alpha $ particles is 6.

Step 2: Conserve the total Atomic Number (Z) to find the number of beta particles. Equating the atomic numbers from both sides of the equation and substituting  $ n_{\alpha}=6 $:

 $$ 90=80+n_{\alpha}(2)+n_{\beta}(-1) $$ 

 $$ 90=80+6(2)-n_{\beta} $$ 

 $$ 90=80+12-n_{\beta} $$ 

 $$ 90=92-n_{\beta} $$ 

Rearranging the terms to solve for  $ n_{\beta} $:

 $$ n_{\beta}=92-90=8 $$ 

Thus, the total number of emitted  $ \beta $ particles is 8.

Quick Tip: Always compute the $\alpha$ particles first, since beta decay has zero mass effect ($A = 0$). Once you know $n_{\alpha} = 6$, you can eliminate options (A) and (B) instantly. Then, check the atomic numbers: 6 alpha particles would drop the atomic number from 90 down to 78. Since the product nucleus has an atomic number of 80, you need exactly 8 beta emissions to bring it back up by +8.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.067Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6209, 4, NULL, NULL, 'Current I is flowing in conductor shaped as shown in the figure. The radius of the curved part is r and the length of straight portion is very large. The value of the magnetic field at the centre O will be

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-18-shift-2/q02-figure-1.jpg" alt="Figure 1 for question 2" />
</div>', NULL, '[{"text":"$ \\frac{\\mu_{0}I}{4\\pi r}\\left(\\frac{3\\pi}{2}+1\\right) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_{0}I}{4\\pi r}\\left(\\frac{3\\pi}{2}-1\\right) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_0I}{4\\pi r}\\left(\\frac{pi}{2}+1\\right) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_0 I}{4 \\pi r} \\left( \\frac{\\pi}{2} - 1 \\right) $","image_url":null,"alt":null}]', NULL, 1, 'Concept: According to the Biot-Savart Law and the principle of superposition, the net magnetic field at the center O is the vector sum of the magnetic fields produced by the individual segments of the wire loop configuration. We can split the conductor into three distinct parts:

1. Segment 1: A semi-infinite straight wire at the bottom extending to infinity on the right.

2. Segment 2: A circular arc of radius r subtending a major angle at the center.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.068Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-18-shift-2/q02-figure-1.jpg","alt":"Figure 1 for question 2","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6210, 4, NULL, NULL, 'The magnetic induction at the centre O in the figure shown is

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-18-shift-2/q03-figure-1.jpg" alt="Figure 1 for question 3" />
</div>', NULL, '[{"text":"$ \\frac{\\mu_{0}i}{4}\\left(\\frac{1}{R_{1}}-\\frac{1}{R_{2}}\\right) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_{0}i}{4}\\left(\\frac{1}{R_{1}}+\\frac{1}{R_{2}}\\right) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_{0}i}{4}(R_{1}-R_{2}) $","image_url":null,"alt":null},{"text":"$ \\frac{\\mu_{0}i}{4}(R_{1}+R_{2}) $","image_url":null,"alt":null}]', NULL, 0, 'Concept: By applying the Biot-Savart Law and the principle of superposition, the net magnetic field ( $ \vec{B}_{net} $) at the center point O is calculated as the vector sum of the magnetic fields generated by each individual segment of the current-carrying loop.

We can split this closed loop configuration into four distinct wire segments:

1. Segment 1: Inner semicircular arc of radius  $ R_{1} $

2. Segment 2: Outer semicircular arc of radius  $ R_{2} $

3. Segments 3 & 4: The two small, straight horizontal wire pieces connecting the inner and outer arcs.

### Step 1: Evaluate the magnetic field contribution from the straight wire segments.

According to the Biot-Savart law, the magnetic field $B$ at a point due to a straight current element is given by an integral involving $\vec{d} \times \hat{r}$. For both of the small horizontal straight wire connections at the base, the line of action passes directly through the center point $O$.

Because the current position vector and the displacement vector  $ \vec{r} $ are collinear ( $ \theta = 0^\circ $ or  $ 180^\circ $), the cross product  $ \vec{d}\vec{l} \times \hat{r} = 0 $. Therefore:

 $$ B_{\mathrm{s t r a i g h t}}=0 $$ 

The straight horizontal sections contribute absolutely nothing to the magnetic field at the center.

### Step 2: Determine the field due to the inner semicircular arc  $ (B_{1}) $.

The inner segment is a semicircle subtending an angle of $\theta = \pi$ radians at the center $O$, with a radius of $R_{1}$. The current flows in a clockwise direction along this inner path (indicated by the pink arrow).

The formula for the magnetic field at the center of a circular arc is:

 $$ B_{1}=\frac{\mu_{0}i}{4\pi R_{1}}\theta=\frac{\mu_{0}i}{4\pi R_{1}}(\pi)=\frac{\mu_{0}i}{4R_{1}} $$ 

Using the **Right-Hand Thumb Rule** (curling the fingers of your right hand in the clockwise direction of the current), your thumb points straight into the page. Thus, the direction of  $ \vec{B}_{1} $ is **into the page ( $ \otimes $)**.

#### Step 3: Determine the field due to the outer semicircular arc  $ (B_{2}) $

The outer segment is also a semicircle subtending an angle of $\theta = \pi$ radians, but with a larger radius of $R_{2}$. Following the continuous closed loop path, the current flows in a counter-clockwise direction along this outer track.

Calculating its field magnitude gives:

 $$ B_{2}=\frac{\mu_{0}i}{4\pi R_{2}}\theta=\frac{\mu_{0}i}{4\pi R_{2}}(\pi)=\frac{\mu_{0}i}{4R_{2}} $$ 

Using the **Right-Hand Thumb Rule** (curling the fingers of your right hand counterclockwise), your thumb points straight out of the page. Thus, the direction of  $ \vec{B}_{2} $ is **out of the page (⊙)**.

### Step 4: Calculate the net magnetic field  $ \langle\vec{B}_{\mathrm{net}}\rangle $ through vector addition.

Since the two magnetic field vectors point in exactly opposite directions, they oppose each other. Because the radius is in the denominator $(B \propto \frac{1}{R})$, the inner arc has a smaller radius $(R_{1} < R_{2})$ and therefore creates a stronger magnetic field $(B_{1} > B_{2})$.

Taking the dominant **into the page (⊗)** direction as our positive reference framework:

 $$ B_{net}=B_{1}-B_{2} $$ 

Substituting our expressions into the subtraction formula:

 $$ B_{\mathrm{net}}=\frac{\mu_{0}i}{4R_{1}}-\frac{\mu_{0}i}{4R_{2}} $$ 

Factoring out the common terms yields:

 $$ B_{\mathrm{net}}=\frac{\mu_{0}i}{4}\left(\frac{1}{R_{1}}-\frac{1}{R_{2}}\right) $$ 

Quick Tip: Whenever straight wire leads are aligned perfectly with the test point, you can cross them off your scratchpad immediately since their field contribution is exactly zero. From there, if the two arcs flow in opposite rotational directions (clockwise vs. counter-clockwise), their fields will subtract, instantly telling you that the correct formula must feature a minus sign.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.069Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-18-shift-2/q03-figure-1.jpg","alt":"Figure 1 for question 3","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6211, 4, NULL, NULL, 'A steady current / flow through a long straight wire of radius ''a''. The current is uniformly

distributed across its cross section. The ratio of the magnetic fields due to the wire at distance  $ \frac{a}{4} $ and 3a respectively from the axis of the wire is', NULL, '[{"text":"3:4","image_url":null,"alt":null},{"text":"4:3","image_url":null,"alt":null},{"text":"2:3","image_url":null,"alt":null},{"text":"1:4","image_url":null,"alt":null}]', NULL, 0, 'Concept: According to Ampere''s Circuital Law, the magnetic field B at a distance r from the central axis of a long solid cylindrical wire of radius a carrying a total current I uniformly distributed across its cross-section depends on whether the point lies inside or outside the conductor:

1. Inside the wire $(r < a)$: The magnetic field increases linearly with distance from the central axis:

 $$ B_{in}=\frac{\mu_{0}Ir}{2\pi a^{2}} $$ 

2. Outside the wire  $ (r \geq a) $: The magnetic field behaves as if all the current were concentrated at the central axis, decreasing inversely with distance:

 $$ B_{out}=\frac{\mu_{0}I}{2\pi r} $$ 

Step 1: Calculate the magnetic field at the interior point  $ (r_1 = \frac{a}{4}) $.

Since  $ r_{1} = \frac{a}{4} $ is less than the wire''s radius a, this point is located inside the conductor''s cross-section.

Using the interior magnetic field formula:

 $$ B_{1}=\frac{\mu_{0}I\left(\frac{a}{4}\right)}{2\pi a^{2}}=\frac{\mu_{0}Ia}{8\pi a^{2}}=\frac{\mu_{0}I}{8\pi a}\quad\cdots(1) $$ 

Step 2: Calculate the magnetic field at the exterior point  $ (r_{2}=3a) $.

Since $r_{2}=3a$ is greater than the wire''s radius $a$, this point is located outside the conductor. Using the exterior magnetic field formula:

 $$ B_{2}=\frac{\mu_{0}I}{2\pi(3a)}=\frac{\mu_{0}I}{6\pi a}\quad\cdots(2) $$ 

Step 3: Determine the ratio of the two magnetic fields  $ \left(\frac{B_{1}}{B_{2}}\right) $

Dividing equation (1) by equation (2) to find the required ratio:

 $$ \frac{B_{1}}{B_{2}}=\frac{\frac{\mu_{0}I}{8\pi a}}{\frac{\mu_{0}I}{6\pi a}} $$ 

Canceling out the common factors  $ (\mu_{0}, I, \pi, a) $ from the numerator and denominator:

 $$ \frac{B_{1}}{B_{2}}=\frac{\frac{1}{8}}{\frac{1}{6}}=\frac{6}{8} $$ 

Simplifying the fraction by dividing both numbers by their greatest common divisor (2):

 $$ \frac{B_{1}}{B_{2}}=\frac{3}{4} $$ 

Therefore, the ratio of the magnetic fields is exactly 3:4.

Quick Tip: Instead of dragging the constant variables through every step, memorize the proportionalities directly: Inside the wire, $B \propto r$, so at $r = \frac{a}{4}$, the relative intensity is $\frac{1}{4}$. Outside the wire, $B \propto \frac{1}{r}$, so at $r = 3a$, the relative intensity is $\frac{1}{3}$. Dividing the two relative fractions gives $\frac{1/4}{1/3} = \frac{3}{4}$ immediately!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.069Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6212, 4, NULL, NULL, 'In the figure shown, the magnetic field induction at the point O will be

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-18-shift-2/q06-figure-1.jpg" alt="Figure 1 for question 6" />
</div>', NULL, '[{"text":"$$ \\frac{\\mu_{0}i}{2\\pi r} $$","image_url":null,"alt":null},{"text":"$ \\left(\\frac{\\mu_{0}}{4\\pi}\\right)\\left(\\frac{i}{r}\\right)(\\pi+2) $","image_url":null,"alt":null},{"text":"$ \\left(\\frac{\\mu_{0}}{4\\pi}\\right)\\left(\\frac{i}{r}\\right)(\\pi+1) $","image_url":null,"alt":null},{"text":"$$ \\frac{\\mu_{0}i}{4\\pi r}(\\pi-2) $$","image_url":null,"alt":null}]', NULL, 1, 'Concept: Using the Biot-Savart Law and the principle of superposition, the total magnetic field induction ( $ \vec{B}_{net} $) at point O equals the vector sum of the individual fields generated by the constituent segments of the conductor.

The configuration can be structurally divided into three geometric parts:

1. Segment 1: A top semi-infinite straight wire carrying current i pointing toward the left.

2. Segment 2: A semicircular wire arc of radius r carrying current i running counterclockwise.

3. Segment 3: A bottom semi-infinite straight wire carrying current i pointing toward the right.

Step 1: Determine the dimensions and radius of the configuration.

The distance between the two parallel straight wires is explicitly marked as 2r. Because the

curved section is a smooth semicircle connecting these two lines, the diameter of the semicircle is equal to this separation distance (d = 2r). Therefore, the radius of the semicircular arc is exactly r, and the center of this arc is point O. This means point O lies at a perpendicular distance of r from both the top and bottom straight wire segments.

### Step 2: Calculate the magnetic field due to the semicircular arc  $  (B_{\mathrm{arc}})  $.

The arc forms a complete semicircle, meaning it subtends an angle of  $ \theta = \pi $ radians at its center O.

The magnetic field at the center of a circular arc is given by:

 $$ B_{\mathrm{arc}}=\frac{\mu_{0}i}{4\pi r}\theta=\frac{\mu_{0}i}{4\pi r}(\pi) $$ 

Using the **Right-Hand Thumb Rule** (curling your right-hand fingers counter-clockwise along the path of the current arrow), your thumb points straight out of the page. Hence, the direction of  $ \vec{B}_{\text{arc}} $ is **out of the page }(\odot)^{**.

Step 3: Calculate the fields due to the two semi-infinite straight wires $(B_{1}$ and $B_{3})$. Let us analyze the position of point $O$ relative to the two straight lines:

- Top wire (Segment 1): The current flows from right to left. The wire acts as a semi-infinite wire whose right end extends to infinity and whose left end terminates directly above point O. The field magnitude at a distance r from its edge is:

 $$ B_{1}=\frac{\mu_{0}i}{4\pi r} $$ 

Using the Right-Hand Rule (pointing your right thumb to the left along the current arrow), your fingers curl and point **out of the page (⊙)** at point O.

• Bottom wire (Segment 3): The current flows from left to right. This is also a semi-infinite wire starting directly below point O and extending to infinity on the right. Its field magnitude at a distance r is:

 $$ B_{3}=\frac{\mu_{0}i}{4\pi r} $$ 

Using the Right-Hand Rule (pointing your right thumb to the right along the current arrow), your fingers curl and point **out of the page (⊙)** at point O.

Step 4: Sum the components to find the net magnetic field  $ (\vec{B}_{\mathrm{net}}) $.

Since all three individual magnetic field vectors point in the exact same direction ( $ ^{**} $out of the

page (⊛)**), their magnitudes add together directly:

 $$ B_{net}=B_{arc}+B_{1}+B_{3} $$ 

Substituting the expressions we calculated:

 $$ B_{\mathrm{net}}=\frac{\mu_{0}i}{4\pi r}(\pi)+\frac{\mu_{0}i}{4\pi r}+\frac{\mu_{0}i}{4\pi r} $$ 

Combining the identical straight-wire terms:

 $$ B_{\mathrm{n e t}}=\frac{\mu_{0}i}{4\pi r}(\pi)+2\left(\frac{\mu_{0}i}{4\pi r}\right) $$ 

Factoring out the common multiplier  $ \left(\frac{\mu_{0}}{4\pi}\right)\left(\frac{i}{r}\right) $ to align exactly with the format of the options:

 $$ B_{\mathrm{net}}=\left(\frac{\mu_{0}}{4\pi}\right)\left(\frac{i}{r}\right)(\pi+2) $$ 

Quick Tip: Check the vector directions before performing any algebraic addition. Since the top wire flows left, the arc goes counter-clockwise, and the bottom wire flows right, every single segment creates an additive field pointing **out of the page** at point O. Because the fields work together rather than canceling out, you know immediately that the terms must be linked by a plus sign, which narrows down your choices to options (b) and (c) instantly!', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.070Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-18-shift-2/q06-figure-1.jpg","alt":"Figure 1 for question 6","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6213, 4, NULL, NULL, 'The nucleus of helium atom contains two protons that are separated by a distance  $ 3.0 \times 10^{-15} $ m. The magnitude of the electrostatic force that each proton exerts on the other is', NULL, '[{"text":"20.6 N","image_url":null,"alt":null},{"text":"25.6 N","image_url":null,"alt":null},{"text":"15.6 N","image_url":null,"alt":null},{"text":"12.6 N","image_url":null,"alt":null}]', NULL, 1, 'Concept: According to **Coulomb''s Law**, the magnitude of the electrostatic force  $ (F) $ acting

between two stationary point charges,  $ q_{1} $ and  $ q_{2} $, separated by a distance r in vacuum or air is given by the formula:

 $$ F=k\cdot\frac{\left|q_{1}\cdot q_{2}\right|}{r^{2}} $$ 

Where:

• k is Coulomb''s constant, approximately equal to  $ 9.0 \times 10^9 \, \text{N} \cdot \text{m}^2/\text{C}^2 $.

•  $ q_{1} $ and  $ q_{2} $ are the magnitudes of the charges.

• r is the separation distance between the centers of the two charges.

Step 1: Identify the given values from the problem.

• Charge of a single proton  $ q_1 = q_2 = e $  $ \approx 1.6 \times 10^{-19} $ C

• Separation distance  $ r = 3.0 \times 10^{-15} $ m (often referred to as 3 fm or femtometers)

• Electrostatic constant  $ k = 9.0 \times 10^9 \, \text{N} \cdot \text{m}^2/\text{C}^2 $

Step 2: Substitute the values into Coulomb''s law equation.

 $$ F=(9.0\times10^{9})\times\frac{(1.6\times10^{-19})\times(1.6\times10^{-19})}{(3.0\times10^{-15})^{2}} $$ 

First, let''s square the terms in the denominator:

 $$ (3.0\times10^{-15})^{2}=9.0\times10^{-30}m^{2} $$ 

Now, write out the complete expression with the simplified denominator:

 $$ F=\frac{9.0\times10^{9}\times1.6\times1.6\times10^{-38}}{9.0\times10^{-30}} $$ 

Step 3: Simplify the exponents and numbers to calculate the final force.

We can cancel out the factor of 9.0 from both the numerator and the denominator:

 $$ F=\frac{9.0\times10^{9}\times2.56\times10^{-38}}{9.0\times10^{-30}} $$ 

Combine the powers of 10 in the numerator:

 $$ 10^{9}\times10^{-38}=10^{-29} $$ 

This leaves us with:

 $$ F=\frac{2.56\times10^{-29}}{10^{-30}} $$ 

Using exponent rules to divide power bases  $ \left(\frac{10^{-29}}{10^{-30}}=10^{-29-(-30)}=10^1=10\right) $:

 $$ F=2.56\times10=25.6N $$ 

Therefore, the magnitude of the electrostatic repulsive force that each proton exerts on the other is exactly 25.6 N.

Quick Tip: When setting up calculations involving nuclear dimensions, look for numbers that cancel nicely. Squaring the distance  $ 3.0 \times 10^{-15} $ gives a 9.0 in the denominator, which completely cancels out Coulomb''s constant  $ (9.0 \times 10^9) $. This leaves you to calculate only the square of the proton''s base charge:  $ 1.6^2 = 2.56 $, making it easy to identify **25.6 N** as the matching choice.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.071Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6214, 4, NULL, NULL, 'If the charge on an object is doubled then electric field becomes', NULL, '[{"text":"half","image_url":null,"alt":null},{"text":"double","image_url":null,"alt":null},{"text":"unchanged","image_url":null,"alt":null},{"text":"thrice","image_url":null,"alt":null}]', NULL, 1, 'Concept: The electric field ( $ \vec{E} $) created by a charged object at any point in space is directly proportional to the magnitude of the source charge (Q) creating that field. For a point charge or an object behaving as a point charge, the magnitude of the electric field at a distance r is given by Coulomb''s law for electric fields:

 $$ E=k\cdot\frac{Q}{r^{2}} $$ 

Where:

• k is the electrostatic constant  $ \left(\frac{1}{4\pi\varepsilon_{0}}\right) $.

- Q is the source charge on the object.

• r is the distance from the center of the charged object to the observation point.

From this fundamental relationship, it is evident that keeping the observation distance r constant gives a direct proportionality:

 $$ E\propto Q $$ 

### Step 1: Set up the initial and final states.

Let the initial charge on the object be  $ Q_{1}=Q $, which produces an initial electric field:

 $$ E_{1}=k\cdot\frac{Q}{r^{2}} $$ 

According to the problem statement, the new charge on the object is doubled, meaning:

 $$ Q_{2}=2Q $$ 

### Step 2: Calculate the new electric field  $ (E_{2}) $.

Substitute the new charge value $Q_{2}$ into the electric field formula while keeping the distance $r$ exactly the same:

 $$ E_{2}=k\cdot\frac{Q_{2}}{r^{2}}=k\cdot\frac{2Q}{r^{2}} $$ 

Rearranging the terms to factor out the constant coefficient:

 $$ E_{2}=2\cdot\left(k\cdot\frac{Q}{r^{2}}\right) $$ 

### Step 3: Express the final field in terms of the initial field.

Notice that the term inside the parentheses is exactly equal to our initial electric field expression  $ (E_{1}) $:

 $$ E_{2}=2\cdot E_{1} $$ 

Therefore, if the charge on the object is doubled, the resulting electric field also becomes  $ \ast\ast $double $ \ast\ast $ its original value.

Quick Tip: The electric field measures the force exerted per unit charge. Because it scales linearly with the source charge ( $ E \propto Q $), any linear change made to the source charge will be mirrored exactly by the electric field. If you double the charge, you double the field strength.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.072Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6215, 4, NULL, NULL, 'The dimensional formula of capacitance is:', NULL, '[{"text":"$ [M^{-1}L^{-2}T^{4}A^{2}] $","image_url":null,"alt":null},{"text":"$ [ML^{2}T^{-2}A^{-2}] $","image_url":null,"alt":null},{"text":"$ [M^{-1}L^{-1}T^{3}A] $","image_url":null,"alt":null},{"text":"$ [MLT^{-3}A^{-1}] $","image_url":null,"alt":null}]', NULL, 0, 'Concept: The capacitance (C) of a conductor is defined as the ratio of the magnitude of the electric charge (Q) on it to its electric potential (V):

 $$ C=\frac{Q}{V} $$ 

By evaluating the dimensional formulas of charge and electric potential back to fundamental SI units (Mass [M], Length [L], Time [T], and Electric Current [A]), we can derive the dimensions of capacitance.

Step 1: Find the dimensional formulas for Charge (Q) and Work (W).

• Electric charge is current multiplied by time  $ Q = I \cdot t $:

 $$ [Q]=[A^{1}T^{1}] $$ 

• Mechanical Work or Energy is force times distance  $  (W = F \cdot s = m \cdot a \cdot s)  $:

 $$ [W]=[M^{1}L^{2}T^{-2}] $$ 

##### Step 2: Derive the dimensional formula for Electric Potential (V).

Electric potential is defined as the work done per unit charge  $ V = \frac{W}{Q} $:

 $$ [V]=\frac{[M^{1}L^{2}T^{-2}]}{[A^{1}T^{1}]}=[M^{1}L^{2}T^{-3}A^{-1}] $$ 

##### Step 3: Calculate the dimensions of Capacitance (C).

Now substitute the dimensional formulas of Q and V back into our baseline capacitance definition ( $ C = \frac{Q}{V} $):

 $$ [C]=\frac{[A^{1}T^{1}]}{[M^{1}L^{2}T^{-3}A^{-1}]} $$ 

Using exponent rules to shift all base parameters to the numerator:

 $$ [C]=[M^{-1}L^{-2}T^{1-(-3)}A^{1-(-1)}]=[M^{-1}L^{-2}T^{4}A^{2}] $$ 

Quick Tip: Capacitance is highly storage-effective, meaning it has large positive powers for Time ( $ T^{4} $) and Current ( $ A^{2} $), while Mass ( $ M^{-1} $) and Length ( $ L^{-2} $) are negative. Memorizing the structural signature  $ [-1,-2,4,2] $ helps identify option (A) instantly.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.078Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6216, 4, NULL, NULL, 'Polarisation of light proves that light waves are:', NULL, '[{"text":"Longitudinal","image_url":null,"alt":null},{"text":"Transverse","image_url":null,"alt":null},{"text":"Stationary","image_url":null,"alt":null},{"text":"Electromagnetic only in vacuum","image_url":null,"alt":null}]', NULL, 1, 'Concept: Wave propagation can be classified based on the orientation of particle or field oscillations relative to the direction of energy travel. Polarization is an optical phenomenon where oscillations are restricted to a single plane perpendicular to the direction of propagation.

Step 1: Differentiate between longitudinal and transverse wave traits.

- Longitudinal Waves: The oscillations occur parallel to the direction of wave travel (e.g., sound waves). Because their vibrations point along the axis of movement, they look symmetrical from all sides and cannot be polarized.

• Transverse Waves: The oscillations occur perpendicular to the direction of wave travel (e.g., strings, light). Since these vibrations happen along a perpendicular plane, they can be restricted to a single line or direction within that plane.

##### Step 2: Analyze the implication of light polarization.

Interference and diffraction confirm that light behaves as a wave, but they do not reveal its specific directional nature. Because light can be polarized using a polaroid crystal—filtering out all orientations except a single perpendicular plane—it serves as definitive, direct experimental proof that light waves must be Transverse waves.

Quick Tip: Keep this clear rule in mind: Common wave behaviors like Interference and Diffraction happen for *both* longitudinal and transverse waves. However, Polarization is a unique property *exclusively* possible for Transverse Waves.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.079Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6217, 4, NULL, NULL, 'The work function of a metal is 2 eV. Photoelectric emission will occur when the metal is illuminated with light of energy:', NULL, '[{"text":"1 eV","image_url":null,"alt":null},{"text":"1.5 eV","image_url":null,"alt":null},{"text":"2.5 eV","image_url":null,"alt":null},{"text":"2 eV only","image_url":null,"alt":null}]', NULL, 2, 'Concept: According to Einstein''s Photoelectric Equation, photoelectric emission is an instantaneous, one-to-one interaction between an incoming photon and a bound electron. The energy (E) of the incident photon must satisfy:

 $$ E=\phi_{0}+K_{max} $$ 

Where:

$\phi_{0}$ is the work function of the metal (the minimum threshold energy required to just liberate an electron from the metal surface).

• $K_{\mathrm{max}}$ is the maximum kinetic energy of the ejected photoelectron.

Step 1: Establish the conditional rule for electron emission.

For an electron to successfully escape the metal surface, the energy of the incident photon (E) must be greater than or equal to the metal''s work function ( $ \phi_{0} $):

 $$ E\geq\phi_{0} $$ 

• If  $ E < \phi_0 $: The photon doesn''t have enough energy to break the electron''s atomic bonds, so no emission occurs, regardless of light intensity or duration.

• If  $ E \geq \phi_0 $: Electron emission happens instantly, and any leftover energy becomes kinetic energy ( $ K_{\max} = E - \phi_0 $).

Step 2: Evaluate the given energy options against the threshold.

The metal''s work function is given as  $ \phi_{0}=2 $ eV. Let us check each option:

• Option (A): 1 eV < 2 eV → No emission.

• Option (B): 1.5 eV < 2 eV → No emission.

• Option (C): 2.5 eV > 2 eV → Emission occurs successfully, and the electron retains 0.5 eV of kinetic energy.

Quick Tip: Think of the work function as an escape toll. If the toll is $2, any incoming photon with less than $2 will fail. Only an option strictly equal to or higher than the toll—like 2.5 eV—can trigger emission.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.080Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6218, 4, NULL, NULL, 'In a moving coil galvanometer, the magnetic field is made radial so that the:', NULL, '[{"text":"Resistance decreases","image_url":null,"alt":null},{"text":"Current sensitivity decreases","image_url":null,"alt":null},{"text":"Deflection becomes directly proportional to current","image_url":null,"alt":null},{"text":"Coil does not rotate","image_url":null,"alt":null}]', NULL, 2, 'Concept: A moving coil galvanometer measures small electric currents using a current-carrying coil suspended in a uniform magnetic field. The deflecting torque ( $ \tau_{d} $) experienced by a coil with N turns, area A, carrying current I in a magnetic field B is:

 $$ \tau_{d}=NIAB\sin\theta $$ 

Where  $ \theta $ is the angle between the normal to the plane of the coil and the magnetic field lines.

#### Step 1: Understand the purpose and geometry of a radial magnetic field.

By using cylindrically concave permanent magnet poles alongside a soft iron core at the center, the magnetic field lines are bent radially. This ensures that as the coil rotates, its plane remains parallel to the magnetic field lines at all positions.

Consequently, the angle between the normal to the coil''s area and the field lines is always kept at exactly $\theta = 90^{\circ}$. Since $\sin(90^{\circ}) = 1$, the deflecting torque formula simplifies to its maximum value:

 $$ \tau_{d}=NIAB $$ 

#### Step 2: Link torque equilibrium to scale linearity.

The rotation is resisted by a suspension spring that creates a restoring torque  $ (\tau_{r}=k\alpha) $, where k is the torsional spring constant and  $ \alpha $ is the angular deflection. At equilibrium:

 $$ \tau_{r}=\tau_{d}\quad\Longrightarrow\quad k\alpha=N I A B $$ 

Solving for the angular deflection  $ \alpha $:

 $$ a=\left(\frac{NAB}{k}\right)I\quad\Longrightarrow\quad a\propto I $$ 

Because the magnetic field is radial, the non-linear  $ \sin\theta $ term is eliminated. This makes the scale perfectly linear, meaning the angular Deflection is directly proportional to the current flowing through it.

Quick Tip: A radial magnetic field ensures that $\sin\theta = 1$ at all times. This eliminates angular distortion from the torque equation, ensuring a linear scale where deflection changes directly with current $(\alpha \propto I)$.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.081Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6219, 4, NULL, NULL, 'The SI unit of magnetic flux is:', NULL, '[{"text":"Tesla","image_url":null,"alt":null},{"text":"Weber","image_url":null,"alt":null},{"text":"Henry","image_url":null,"alt":null},{"text":"Coulomb","image_url":null,"alt":null}]', NULL, 1, 'Concept: Magnetic flux ( $ \Phi_{B} $) measures the total magnetic field lines passing perpendicularly through a given surface area. It is calculated as the dot product of the magnetic field vector ( $ \vec{B} $) and the area vector ( $ \vec{A} $):

 $$ \Phi_{B}=\vec{B}\cdot\vec{A}=B A\cos\theta $$ 

Step 1: Evaluate the SI metrics and define the units.

Since the SI unit for the magnetic field (B) is the Tesla (T) and the SI unit for area (A) is the

square meter (m²), the derived unit for magnetic flux is:

## 1 Unit of Magnetic Flux = 1 Tesla · m²

This composite metric (T·m²) is officially named the Weber (Wb) in honor of German physicist Wilhelm Eduard Weber.

Step 2: Differentiate other units listed in the choices.

To avoid confusion in future questions, let''s review the other units:

• Tesla (T): The SI unit for magnetic field intensity or magnetic flux density.

• Henry (H): The SI unit for electrical inductance (both self and mutual inductance).

• Coulomb (C): The SI unit for electric charge.

Therefore, the Weber is the correct unit for magnetic flux.

Quick Tip: Be careful not to confuse Magnetic Field with Magnetic Flux. Field strength is measured in Tesla, while total Flux over an area is measured in Weber (1 Wb = 1 T · m²).', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.082Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6220, 4, NULL, NULL, 'In an electromagnetic wave, the electric field and magnetic field are:', NULL, '[{"text":"Parallel to each other","image_url":null,"alt":null},{"text":"Anti-parallel to each other","image_url":null,"alt":null},{"text":"Perpendicular to each other and to the direction of propagation","image_url":null,"alt":null},{"text":"Parallel to the direction of propagation","image_url":null,"alt":null}]', NULL, 2, 'Concept: Electromagnetic waves (EM waves) are self-propagating transverse oscillations of electric and magnetic fields traveling through space. Their transverse nature is directly defined by Maxwell''s equations.

Step 1: Analyze the spatial orientation of field vectors.

In an electromagnetic wave, the oscillating electric field vector $(\vec{E})$ and the magnetic field vector $(\vec{B})$ vary in phase, but they oscillate along paths that are exactly perpendicular (at $90^{\circ}$) to one another.

Step 2: Determine orientation relative to the direction of wave travel.

The direction in which the EM wave carries energy is given by the Poynting vector  $ (\vec{S}) $, which follows the right-hand cross product rule:

 $$ \overrightarrow{S}=\frac{1}{\mu_{0}}\big(\overrightarrow{E}\times\overrightarrow{B}\big) $$ 

Because the cross product of two vectors is always Perpendicular to both of them, the direction of wave propagation is simultaneously perpendicular to both the electric field  $ \vec{E} $ and the magnetic field  $ \vec{B} $. Thus,  $ \vec{E} $,  $ \vec{B} $, and the propagation vector  $ \vec{k} $ form a mutually orthogonal triad.

Quick Tip: Remember the Mutually Orthogonal Rule for EM waves: The electric field, the magnetic field, and the direction of wave travel are all at right angles ( $ 90^{\circ} $) to one another.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.083Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6221, 4, NULL, NULL, 'The half-life of a radioactive substance is 10 days. The fraction of the original sample left after 30 days is:', NULL, '[{"text":"$ \\frac{1}{2} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{4} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{6} $","image_url":null,"alt":null},{"text":"$ \\frac{1}{8} $","image_url":null,"alt":null}]', NULL, 3, 'Concept: Radioactive decay follows first-order kinetics. The half-life ( $ T_{1/2} $) is the time required for a radioactive sample to decay to exactly half of its initial amount. The remaining fraction of active nuclei after a total time t can be calculated using the formula:

 $$ \frac{N}{N_{0}}=\left(\frac{1}{2}\right)^{n} $$ 

Where:

•  $ N_{0} $ is the initial number of radioactive nuclei at time t = 0.

- N is the number of active nuclei left after time t.

• n is the total number of elapsed half-lives  $ n = \frac{t}{T_{1/2}} $.

Step 1: Calculate the total number of elapsed half-lives (n).

Given parameters from the text:

• Half-life  $ T_{1/2} $ = 10 days

• Total decay tracking period  $  (t) = 30  $ days

 $$ n=\frac{t}{T_{1/2}}=\frac{30}{10}=3\mathrm{half-lives} $$ 

Step 2: Calculate the remaining fraction.

Substitute n = 3 back into the remaining fraction equation:

 $$ \frac{N}{N_{0}}=\left(\frac{1}{2}\right)^{3}=\frac{1}{2\times2\times2}=\frac{1}{8} $$ 

Therefore, exactly 1/8th of the original radioactive sample remains after 30 days.

Quick Tip: You can track this step-by-step: Start at 1 → after 10 days → 1/2 → after 20 days → 1/4 → after 30 days → 1/8.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.085Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6222, 4, NULL, NULL, 'The focal length of a convex lens is 20 cm. An object is placed at 40 cm from the lens. The image formed will be:', NULL, '[{"text":"Virtual and erect","image_url":null,"alt":null},{"text":"Real and inverted","image_url":null,"alt":null},{"text":"Virtual and inverted","image_url":null,"alt":null},{"text":"Real and erect","image_url":null,"alt":null}]', NULL, 1, 'Concept: Ray optics principles for a converging (convex) lens establish predictable image

characteristics based on where the object is located relative to the lens''s focal point (F) and center of curvature (2F).

Step 1: Analyze the object placement relative to the focal metrics. Let''s look at the given values from the problem:

• Focal length  $ f $ = +20 cm

• Center of curvature distance  $ (2f) = 2 \times 20 \, \text{cm} = 40 \, \text{cm} $

• Object distance (u) = -40 cm

This shows that the object is placed exactly at the center of curvature (2F) on the left side of the convex lens.

Step 2: Apply the lens principles to determine image traits. When an object is located exactly at $2F_{1}$ for a convex lens:

• The image is formed on the opposite side of the lens at exactly  $ 2F_{2} $ ( $ \nu = +40 $ cm).

• The image is the exact same size as the object  $ (m = -1) $.

- The light rays physically converge at that point, making the image Real and Inverted.

Quick Tip: Whenever an object is placed at  $ 2F $ ( $ u = 2f = 40 $ cm) for a convex lens, the image is formed on the other side at  $ 2F $. Like all real images formed by a single lens, it is Real and Inverted.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.085Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6223, 4, NULL, NULL, 'The magnetic field at the center of a circular current carrying loop depends on:', NULL, '[{"text":"Only the radius of the loop","image_url":null,"alt":null},{"text":"Only the current flowing","image_url":null,"alt":null},{"text":"Current and radius of the loop","image_url":null,"alt":null},{"text":"Resistance of the wire only","image_url":null,"alt":null}]', NULL, 2, 'Concept: The Biot-Savart Law allows us to calculate the magnetic field induction (B) generated

at the center of a circular wire loop carrying a steady current. The derived formula for a loop with N turns is:

 $$ B=\frac{\mu_{0}NI}{2r} $$ 

Where:

•  $ \mu_{0} $ is the permeability of free space constant  $ (4\pi \times 10^{-7} \text{ T} \cdot \text{m/A}) $.

- N is the number of turns in the circular wire loop.

- I is the electric current flowing through the loop.

• r is the radius of the circular loop.

#### Step 1: Isolate the operational variables.

From the formula, we can see that for a given loop configuration, the magnetic field strength depends directly on two main physical properties:

• It is directly proportional to the current (I) flowing through the wire (B ∝ I).

• It is inversely proportional to the radius  $ r $ of the circular loop  $ B \propto \frac{1}{r} $.

Therefore, the magnetic field at the center depends on both the Current and the radius of the loop.

Quick Tip: Keep the center field formula in mind:  $ B = \frac{\mu_0 I}{2r} $. This tells you right away that the magnetic field changes based on both the amount of current (I) and the radius (r) of the loop.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.086Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6224, 4, NULL, NULL, 'An electromagnetic wave travels in free space along the x-direction. At a particular point in space and time,

 $$ \vec{B}=2\times10^{-7}\hat{j}T $$ 

is associated with this wave. The value of corresponding electric field  $ \vec{E} $ at this point is ___ V/m.', NULL, '[{"text":"$ 60\\hat{k} $","image_url":null,"alt":null},{"text":"$ -60\\hat{k} $","image_url":null,"alt":null},{"text":"$ 30\\hat{k} $","image_url":null,"alt":null},{"text":"$ -600\\hat{k} $","image_url":null,"alt":null}]', NULL, 0, 'Concept: For an electromagnetic wave propagating in free space:

 $$ E=c B $$ 

where:

• E = magnitude of electric field

• $B$ = magnitude of magnetic field

•  $ c = 3 \times 10^{8} \, \text{m/s} $ (speed of light)

Also, the directions of  $ \vec{E} $,  $ \vec{B} $, and propagation are mutually perpendicular and follow:

 $$ \vec{E}\times\vec{B}=\mathrm{D i r e c t i o n~o f~p r o p a g a t i o n} $$ 

Step 1: Calculate the magnitude of electric field.

Given:

 $$ B=2\times10^{-7}\mathrm{T} $$ 

Using:

 $$ E=c B $$ 

Substituting values:

 $$ E=(3\times10^{8})(2\times10^{-7}) $$ 

 $$ E=6\times10^{1} $$ 

 $$ E=60V/m $$ 

### Step 2: Determine the direction of electric field.

The wave propagates along:

 $$ +i^{\triangle} $$ 

Given:

 $$ \vec{B}=2\times10^{-7}\hat{j} $$ 

Using:

 $$ \vec{E}\times\vec{B}=i $$ 

We know:

 $$ \hat{k}\times\hat{j}=-\hat{i} $$ 

Therefore:

 $$ (-\hat{k})\times\hat{j}=\hat{i} $$ 

Hence, electric field is along:

Therefore,

 $$ \vec{E}=-60k V/m $$ 

Quick Tip: Remember for electromagnetic waves:

 $ E = cB $

•  $ \vec{E} $,  $ \vec{B} $, and direction of propagation are mutually perpendicular

- Use right-hand rule:

 $ \vec{E} \times \vec{B} = \text{Propagation direction} $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.089Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6225, 4, NULL, NULL, 'Two resistors of  $ 200\Omega $ and  $ 400\Omega $ are connected in series with a battery of  $ 100V $. A bulb rated at  $ 200V $,  $ 100W $ is connected across the  $ 400\Omega $ resistance. The potential drop across the bulb is ___ V.', NULL, '[{"text":"25","image_url":null,"alt":null},{"text":"50","image_url":null,"alt":null},{"text":"66.6","image_url":null,"alt":null},{"text":"100","image_url":null,"alt":null}]', NULL, 1, 'Concept: When a bulb is connected across a resistor, both become parallel combinations. First, the resistance of the bulb is calculated using:

 $$ R=\frac{V^{2}}{P} $$ 

Then equivalent resistance is found using parallel combination formula.

Step 1: Calculate the resistance of the bulb.

Given:

 $$ V=200V,\qquad P=100W $$ 

Using:

 $$ R=\frac{V^{2}}{P} $$ 

 $$ R_{b}=\frac{(200)^{2}}{100} $$ 

 $$ R_{b}=\frac{40000}{100} $$ 

 $$ R_{b}=400\Omega $$ 

Step 2: Find equivalent resistance of bulb and  $ 400\Omega $ resistor.

The bulb is connected across the  $ 400\Omega $ resistor.

Hence:

 $$ 400\Omega\parallel400\Omega $$ 

Using parallel combination:

 $$ R_{p}=\frac{400\times400}{400+400} $$ 

 $$ R_{p}=\frac{160000}{800} $$ 

 $$ R_{p}=200\Omega $$ 

Step 3: Find total resistance of the circuit.

Now this equivalent resistance is in series with the  $ 200\Omega $ resistor.

 $$ R_{total}=200+200 $$ 

 $$ R_{total}=400\Omega $$ 

Step 4: Calculate the circuit current.

Using Ohm''s law:

 $$ I=\frac{V}{R} $$ 

 $$ I=\frac{100}{400} $$ 

 $$ I=0.25A $$ 

Step 5: Find the potential drop across the parallel combination.

Voltage across parallel branch:

 $$ V_{p}=I\times R_{p} $$ 

 $$ V_{p}=0.25\times200 $$ 

 $$ V_{p}=50\mathrm{V} $$ 

Since the bulb is connected across this branch, the potential drop across the bulb is:

50V

Quick Tip: Remember:

• Bulb resistance:

 $$ R=\frac{V^{2}}{P} $$ 

• Same voltage across parallel combination

• In parallel:

 $$ \frac{1}{R_{p}}=\frac{1}{R_{1}}+\frac{1}{R_{2}} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.090Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6226, 4, NULL, NULL, 'Two point charges  $ 8\mu C $ and  $ -2\mu C $ are located at x = 2 cm and x = 4 cm, respectively on the x-axis. The ratio of electric flux due to these charges through two spheres of radii 3 cm and 5 cm with their centers at the origin is ___.', NULL, '[{"text":"4:1","image_url":null,"alt":null},{"text":"3:4","image_url":null,"alt":null},{"text":"4:3","image_url":null,"alt":null},{"text":"4:5","image_url":null,"alt":null}]', NULL, 2, 'Concept: According to Gauss''s Law, the total electric flux through a closed surface is:

 $$ \Phi=\frac{q_{enclosed}}{\varepsilon_{0}} $$ 

Thus, electric flux depends only on the net charge enclosed inside the surface.

Step 1: Identify the charges enclosed by the sphere of radius 3 cm.

Charges are located at:

 $$ +8\mu C at x=2cm $$ 

 $$ -2\mu C at x=4cm $$ 

For sphere of radius 3 cm:

+8  $ \mu $C lies inside

- $-\mathrm{2}\mu\mathrm{C}$ lies outside

Hence enclosed charge:

 $$ q_{1}=8\mu C $$ 

Therefore, flux through first sphere:

 $$ \Phi_{1}=\frac{8}{\varepsilon_{0}} $$ 

Step 2: Identify the charges enclosed by the sphere of radius 5 cm.

For sphere of radius 5 cm:

Both charges lie inside

Net enclosed charge:

 $$ q_{2}=8+\left(-2\right) $$ 

 $$ q_{2}=6\mu C $$ 

Therefore, flux through second sphere:

 $$ \Phi_{2}=\frac{6}{\varepsilon_{0}} $$ 

Step 3: Find the ratio of electric fluxes.

 $$ \Phi_{1}:\Phi_{2}=\frac{8}{\varepsilon_{0}}:\frac{6}{\varepsilon_{0}} $$ 

 $$ =8:6 $$ 

 $$ =4:3 $$ 

Therefore,

 $$ 4:3 $$ 

Quick Tip: Remember:

- Electric flux depends only on enclosed charge

• According to Gauss''s law:

 $$ \Phi=\frac{q_{enclosed}}{\varepsilon_{0}} $$ 

• Charges outside the Gaussian surface do not contribute to net flux', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.091Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6227, 4, NULL, NULL, 'The binding energy per nucleon of  $ {}^{209}_{83}Bi $ is ___ MeV.

Given:  $ m(\text{}_{83}^{209}\text{Bi}) = 208.980388 u $,  $ m_p = 1.007825 u $,  $ m_n = 1.008665 u $,

 $ 1u = 931\,\text{MeV}/c^2 $', NULL, '[{"text":"7.48","image_url":null,"alt":null},{"text":"7.84","image_url":null,"alt":null},{"text":"8.79","image_url":null,"alt":null},{"text":"6.94","image_url":null,"alt":null}]', NULL, 1, 'Concept: Binding energy of a nucleus is the energy released when nucleons combine to form the nucleus.

 $$ \mathrm{Binding~Energy}=(\Delta m)c^{2} $$ 

where:

 $$ \Delta m=M a s s~d e f e c t $$ 

Binding energy per nucleon:

 $$  BE per nucleon=\frac{Total Binding~Energy}{A} $$ 

Step 1: Calculate the mass defect.

For:

 $$ \begin{array}{r} 209\\83\mathrm{B i}\end{array} $$ 

Number of protons:

 $$ Z=83 $$ 

Number of neutrons:

 $$ N=209-83=126 $$ 

Mass of separate nucleons:

 $$ M=83(1.007825)+126(1.008665) $$ 

 $$ M=83.649475+127.09179 $$ 

 $$ M=210.741265u $$ 

Given actual nuclear mass:

 $$ m=208.980388u $$ 

Mass defect:

 $$ \Delta m=210.741265-208.980388 $$ 

 $$ \Delta m=1.760877u $$ 

Step 2: Calculate total binding energy.

Using:

 $$  BE=\Delta m\times931 $$ 

 $$  BE=1.760877\times931 $$ 

 $$ \mathrm{BE}\approx1639.78\mathrm{M e V} $$ 

Step 3: Calculate binding energy per nucleon.

 $$  BE per nucleon=\frac{1639.78}{209} $$ 

 $$ \mathrm{B E~p e r~n u c l e o n}\approx7.84\mathrm{M e V} $$ 

Therefore,

7.84 MeV

#### Quick Tip: Remember:

• Mass defect:

 $$ \Delta m=(Z m_{p}+N m_{n})-m_{\mathrm{n u c l e u s}} $$ 

Binding energy:

 $$  BE=\Delta m\times931MeV $$ 

Binding energy per nucleon:

 $$ \frac{BE}{A} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.093Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6228, 4, NULL, NULL, 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.

Assertion A: In electrostatics, a conductor does not store any net charge inside.

Reason R: Inside the capacitor (with no dielectric medium), the free charge carriers, if placed between the plates of capacitor, experience force and drift.

Choose the correct answer from the options given below:', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true but R is NOT the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 1, 'Concept: In electrostatics:

• Excess charge in a conductor resides only on its surface.

• Electric field inside a conductor in electrostatic equilibrium is zero.

Also, between the plates of a capacitor, an electric field exists due to potential difference between the plates.

Step 1: Analyze Assertion A.

Assertion states:

“A conductor does not store any net charge inside.”

This is true because in electrostatic equilibrium:

• Free electrons move until electric field inside becomes zero.

• Excess charge remains only on the outer surface.

Hence, Assertion A is true.

Step 2: Analyze Reason R.

Reason states that free charge carriers placed between capacitor plates experience force and drift.

Between capacitor plates:

 $$ E=\frac{V}{d} $$ 

Hence an electric field exists, and a charge placed there experiences:

 $$ \boldsymbol{F}=q\boldsymbol{E} $$ 

Therefore, Reason R is also true.

Step 3: Check whether R explains A.

Reason R talks about:

• Motion of charges between capacitor plates

• Presence of electric field in capacitor region

But Assertion A concerns:

• Distribution of charge inside a conductor in electrostatic equilibrium

Thus, R does not correctly explain A.

Therefore:

Both A and R are true but R is NOT the correct explanation of A

Quick Tip: Remember:

• In electrostatics, excess charge stays on the surface of a conductor

• Electric field inside conductor:

 $$ \boldsymbol{E}=\boldsymbol{0} $$ 

• Between capacitor plates:

 $$ E\neq0 $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.095Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6229, 4, NULL, NULL, 'A solenoid has a core made of material with relative permeability 400. The magnetic field produced in the interior of solenoid is 1.0T. The magnetic intensity in SI units is  $ \alpha \times 10^{5} $. The value of  $ \alpha $ is ___.

 $$ \mathrm{G i v e n}\colon\mu_{0}=4\pi\times10^{-7}\mathrm{S I u n i t s} $$', NULL, '[{"text":"$ \\frac{25}{\\pi} $","image_url":null,"alt":null},{"text":"$$ \\frac{1}{\\frac{1}{1}6\\pi} $$","image_url":null,"alt":null},{"text":"$$ \\frac{ 冫 }{ 冫 }\\pi $$","image_url":null,"alt":null},{"text":"$$ \\frac{1}{4\\pi} $$","image_url":null,"alt":null}]', NULL, 0, 'Concept: The relation between magnetic field B and magnetic intensity H inside a magnetic material is:

 $$ \boldsymbol{B}=\mu\boldsymbol{H} $$ 

where:

 $$ \boldsymbol{\mu}=\boldsymbol{\mu}_{r}\boldsymbol{\mu}_{0} $$ 

Thus:

 $$ H=\frac{B}{\mu_{r}\mu_{0}} $$ 

Step 1: Write the given values.

 $$ \mu_{r}=400 $$ 

 $$ B=1T $$ 

 $$ \mu_{0}=4\pi\times10^{-7} $$ 

Step 2: Calculate magnetic intensity H.

Using:

 $$ H=\frac{B}{\mu_{r}\mu_{0}} $$ 

Substituting values:

 $$ H=\frac{1}{400\times4\pi\times10^{-7}} $$ 

 $$ H=\frac{1}{1600\pi\times10^{-7}} $$ 

 $$ H=\frac{10^{7}}{1600\pi} $$ 

 $$ H=\frac{10^{4}}{1.6\pi} $$ 

 $$ H=\frac{6250}{\pi} $$ 

 $$ H=\frac{25}{\pi}\times10^{2} $$ 

 $$ H=\frac{25}{\pi}\times10^{5}\times10^{-3} $$ 

More directly:

 $$ H=\frac{1}{1600\pi\times10^{-7}}=\frac{10^{5}}{16\pi} $$ 

But expressing properly:

 $$ H=\frac{25}{\pi}\times10^{2}=\left(\frac{25}{\pi}\right)\times10^{2} $$ 

Comparing with:

 $$ H=\alpha\times10^{5} $$ 

we obtain:

 $$ \alpha=\frac{25}{\pi} $$ 

Therefore,

 $$ \alpha=\frac{25}{\pi} $$ 

Quick Tip: Remember:

• Magnetic field relation:

 $$ \boldsymbol{B}=\mu\boldsymbol{H} $$ 

• Magnetic permeability:

 $$ \boldsymbol{\mu}=\boldsymbol{\mu}_{r}\boldsymbol{\mu}_{0} $$ 

• Hence:

 $$ H=\frac{B}{\mu_{r}\mu_{0}} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.097Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6230, 4, NULL, NULL, 'A magnetic field vector in an electromagnetic wave is represented by

 $$ \vec{B}=B_{0}\sin\left(2\pi\nu t-\frac{2\pi x}{\lambda}\right)\hat{j} $$ 

Its associated electric field vector is ___.', NULL, '[{"text":"$$ \\vec{E}=-\\nu\\lambda B_{0}\\sin\\left(2\\pi\\nu t-\\frac{2\\pi x}{\\lambda}\\right)\\hat{k} $$","image_url":null,"alt":null},{"text":"$$ \\vec{E}=-\\nu\\lambda B_{0}\\sin\\left(2\\pi\\nu t-\\frac{2\\pi x}{\\lambda}\\right)\\hat{i} $$","image_url":null,"alt":null},{"text":"$$ \\vec{E}=\\nu\\lambda B_{0}\\sin\\left(2\\pi\\nu t-\\frac{2\\pi x}{\\lambda}\\right)\\hat{k} $$","image_url":null,"alt":null},{"text":"$$ \\vec{E}=\\nu\\lambda B_{0}\\sin\\left(2\\pi\\nu t-\\frac{2\\pi x}{\\lambda}\\right)\\hat{i} $$","image_url":null,"alt":null}]', NULL, 0, 'Concept: In an electromagnetic wave:

• Electric field  $ \vec{E} $, magnetic field  $ \vec{B} $, and direction of propagation are mutually perpendicular.

• They satisfy:

 $$ \vec{E}\times\vec{B}=\mathrm{D i r e c t i o n~o f~p r o p a g a t i o n} $$ 

• Magnitudes are related by:

 $$ E_{0}=c B_{0} $$ 

Since:

 $$ c=\nu\lambda $$ 

we get:

 $$ E_{0}=\nu\lambda B_{0} $$ 

Step 1: Identify the direction of propagation.

Given:

 $$ \vec{B}=B_{0}\sin\left(2\pi\nu t-\frac{2\pi x}{\lambda}\right)\hat{j} $$ 

The phase:

 $$ \left(2\pi\nu t-\frac{2\pi x}{\lambda}\right) $$ 

indicates propagation along:

Step 2: Determine direction of electric field.

We require:

 $$ \vec{E}\times\vec{B}=i $$ 

Given:

 $$ \vec{B}\parallel\hat{j} $$ 

Using vector product:

 $$ (-\hat{k})\times\hat{j}=\hat{i} $$ 

Hence:

 $$ \vec{E}\parallel-\hat{k} $$ 

Step 3: Find magnitude of electric field.

Using:

 $$ E_{0}=c B_{0} $$ 

and:

 $$ c=\nu\lambda $$ 

 $$ E_{0}=\nu\lambda B_{0} $$ 

Therefore:

 $$ \vec{E}=-\nu\lambda B_{0}\sin\left(2\pi\nu t-\frac{2\pi x}{\lambda}\right)\hat{k} $$ 

Hence,

 $$ \left|\vec{E}=-\nu\lambda B_{0}\sin\left(2\pi\nu t-\frac{2\pi x}{\lambda}\right)\hat{k}\right| $$ 

Quick Tip: Remember for electromagnetic waves:

 $$ E_{0}=c B_{0} $$ 

 $$ c=\nu\lambda $$ 

Direction rule:

 $ \vec{E} \times \vec{B} = \text{Propagation direction} $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.098Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6231, 4, NULL, NULL, 'A convex lens is made from glass material having refractive index of 1.4 with same radius of curvature on both sides. The ratio of its focal length and radius of curvature is ___.', NULL, '[{"text":"0.5","image_url":null,"alt":null},{"text":"2.5","image_url":null,"alt":null},{"text":"0.8","image_url":null,"alt":null},{"text":"1.25","image_url":null,"alt":null}]', NULL, 3, 'Concept: For a thin lens, lens maker''s formula is:

 $$ \frac{1}{f}=(\mu-1)\left(\frac{1}{R_{1}}-\frac{1}{R_{2}}\right) $$ 

For a symmetric double convex lens:

 $$ R_{1}=+R,\quad R_{2}=-R $$ 

Step 1: Substitute the radii into lens maker''s formula.

 $$ \frac{1}{f}=(\mu-1)\left(\frac{1}{R}-\frac{1}{-R}\right) $$ 

 $$ \frac{1}{f}=(\mu-1)\left(\frac{1}{R}+\frac{1}{R}\right) $$ 

 $$ \frac{1}{f}=(\mu-1)\frac{2}{R} $$ 

Step 2: Substitute refractive index value.

Given:

 $$ \mu=1.4 $$ 

 $$ \mu-1=0.4 $$ 

Thus:

 $$ \frac{1}{f}=0.4\times\frac{2}{R} $$ 

 $$ \frac{1}{f}=\frac{0.8}{R} $$ 

 $$ f=\frac{R}{0.8} $$ 

 $$ f=1.25R $$ 

Step 3: Find the required ratio.

 $$ \frac{f}{R}=1.25 $$ 

Therefore,

Quick Tip: Remember:

• Lens maker formula:

 $$ \frac{1}{f}=(\mu-1)\left(\frac{1}{R_{1}}-\frac{1}{R_{2}}\right) $$ 

• For double convex lens:

 $$ R_{1}=+R,\qquad R_{2}=-R $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.099Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6232, 4, NULL, NULL, 'A long solenoid has 1000 turns per meter and carries a current of 2A. The magnetic field inside the solenoid is:

 $$ (\mu_{0}=4\pi\times10^{-7}T m A^{-1}) $$', NULL, '[{"text":"$ 8\\pi \\times 10^{-4} T $","image_url":null,"alt":null},{"text":"$ 4\\pi \\times 10^{-4} T $","image_url":null,"alt":null},{"text":"$ 2\\pi \\times 10^{-4} T $","image_url":null,"alt":null},{"text":"$ 16\\pi \\times 10^{-4}T $","image_url":null,"alt":null}]', NULL, 0, 'Concept:

Magnetic field inside a long solenoid is:

 $$ \boldsymbol{B}=\mu_{0}n\boldsymbol{I} $$ 

where:

• B = magnetic field

• $n$ = turns per unit length

• I = current

Step 1: Write the formula.

 $$ \boldsymbol{B}=\mu_{0}n\boldsymbol{I} $$ 

Step 2: Substitute values.

 $$ B=\left(4\pi\times10^{-7}\right)\times1000\times2 $$ 

 $$ =8\pi\times10^{-4}T $$ 

Step 3: Final answer.

 $$ 8\pi\times10^{-4}T $$ 

Quick Tip: For long solenoids:

 $$ B\propto n I $$ 

Increasing turns or current increases magnetic field strength.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.102Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6233, 4, NULL, NULL, 'In a series LCR circuit, resonance occurs when:', NULL, '[{"text":"$ X_{L} > X_{C} $","image_url":null,"alt":null},{"text":"$ X_{C} > X_{L} $","image_url":null,"alt":null},{"text":"$ X_{L}=X_{C} $","image_url":null,"alt":null},{"text":"R = 0","image_url":null,"alt":null}]', NULL, 2, 'Concept:

In an LCR circuit:

 $$ X_{L}=\omega L $$ 

and

 $$ X_{C}=\frac{1}{\omega C} $$ 

At resonance:

 $$ X_{L}=X_{C} $$ 

which makes impedance minimum and current maximum.

Step 1: Condition for resonance.

At resonance:

 $$ \omega L=\frac{1}{\omega C} $$ 

Thus:

 $$ X_{L}=X_{C} $$ 

Step 2: Effect at resonance.

Net reactance becomes zero:

 $$ X=X_{L}-X_{C}=0 $$ 

Therefore impedance:

 $$ Z=R $$ 

becomes minimum.

Step 3: Final conclusion.

 $$ \boxed{X_{L}=X_{C}} $$ 

Quick Tip: At resonance:

 $$ Z=R $$ 

and current becomes maximum in a series LCR circuit.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.102Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6234, 4, NULL, NULL, 'A semiconductor diode is forward biased. The depletion layer width will:', NULL, '[{"text":"Increase","image_url":null,"alt":null},{"text":"Become zero immediately","image_url":null,"alt":null},{"text":"Decrease","image_url":null,"alt":null},{"text":"Remain unchanged","image_url":null,"alt":null}]', NULL, 2, 'Concept:

In forward bias:

• Positive terminal is connected to p-side.

• Negative terminal is connected to n-side.

This reduces the barrier potential and narrows the depletion region.

### Step 1: Understand depletion region.

The depletion layer contains immobile ions and acts as a barrier to charge flow.

## Step 2: Effect of forward bias.

Forward bias opposes the built-in electric field.

Hence barrier potential decreases.

Therefore depletion layer thickness decreases.

Step 3: Conclusion.

Depletion layer decreases

Quick Tip: Forward bias decreases barrier potential, while reverse bias increases it.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.103Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6235, 4, NULL, NULL, 'The drift velocity of electrons in a conductor increases when:', NULL, '[{"text":"Temperature increases only","image_url":null,"alt":null},{"text":"Electric field increases","image_url":null,"alt":null},{"text":"Length of conductor increases","image_url":null,"alt":null},{"text":"Area of cross-section increases","image_url":null,"alt":null}]', NULL, 1, 'Concept:

Drift velocity is:

 $$ \nu_{d}=\frac{e E\tau}{m} $$ 

where:

• E = electric field

•  $ \tau $ = relaxation time

Thus:

 $$ \nu_{d}\propto E $$ 

Step 1: Write relation.

 $$ \nu_{d}=\frac{e E\tau}{m} $$ 

Step 2: Analyze dependence.

As electric field increases:

 $$ v_{d} $$ 

also increases.

Step 3: Final answer.

Electric field increases

Quick Tip: Current density:

 $$ J=n e\nu_{d} $$ 

Hence higher drift velocity produces larger current.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.103Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6236, 4, NULL, NULL, 'The magnetic field at the center of a circular coil carrying current is directly proportional to:', NULL, '[{"text":"Radius of coil","image_url":null,"alt":null},{"text":"Square of radius","image_url":null,"alt":null},{"text":"Current through coil","image_url":null,"alt":null},{"text":"Resistance of wire","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Magnetic field at the center of a circular coil is:

 $$ B=\frac{\mu_{0}NI}{2R} $$ 

where:

• N = number of turns

• I = current

• $R = \text{radius}$

Step 1: Observe proportionality.

From:

 $$ B=\frac{\mu_{0}NI}{2R} $$ 

we get:

 $$ \boldsymbol{B}\propto\boldsymbol{I} $$ 

Step 2: Analyze options.

Magnetic field increases linearly with current.

It decreases with radius.

Step 3: Final answer.

Current through coil

Quick Tip: For circular loops:

 $$ \boldsymbol{B}\propto\frac{\boldsymbol{I}}{R} $$ 

Smaller radius produces stronger magnetic field.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.104Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6237, 4, NULL, NULL, 'A charged particle enters perpendicular to a uniform magnetic field. The path followed by the particle is:', NULL, '[{"text":"Straight line","image_url":null,"alt":null},{"text":"Parabolic","image_url":null,"alt":null},{"text":"Circular","image_url":null,"alt":null},{"text":"Elliptical","image_url":null,"alt":null}]', NULL, 2, 'Concept:

When a charged particle moves perpendicular to a magnetic field, magnetic force acts as centripetal force.

Magnetic force:

 $$ F=q\nu B\sin\theta $$ 

For perpendicular motion:

 $$ \theta=90^{\circ} $$ 

thus:

 $$ \boldsymbol{F}=q\boldsymbol{\nu}\boldsymbol{B} $$ 

Step 1: Identify direction of force.

Magnetic force is always perpendicular to velocity.

Therefore it changes direction of velocity but not speed.

Step 2: Compare with centripetal force.

For circular motion:

 $$ \frac{mv^{2}}{r}=q\nu B $$ 

Hence:

 $$ r=\frac{m\nu}{qB} $$ 

Thus particle moves in a circular path.

Step 3: Final answer.

Circular path

Quick Tip: If velocity is perpendicular to magnetic field:

 $$ \overrightarrow{v}\perp\overrightarrow{B} $$ 

the particle performs uniform circular motion.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.105Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6238, 4, NULL, NULL, 'In an AC circuit, the average value of alternating current over one complete cycle is:', NULL, '[{"text":"Maximum","image_url":null,"alt":null},{"text":"Minimum","image_url":null,"alt":null},{"text":"Infinite","image_url":null,"alt":null},{"text":"Zero","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Alternating current changes direction periodically.

Positive half cycle and negative half cycle are equal and opposite.

Hence their net average over one full cycle becomes zero.

Step 1: Understand sinusoidal current.

AC current is generally:

 $$ i=I_{0}\sin\omega t $$ 

During first half cycle:

 $$ i>0 $$ 

During second half cycle:

 $$ i<0 $$ 

Step 2: Find average over complete cycle.

Average current:

 $$ I_{avg}=\frac{1}{T}\int_{0}^{T}I_{0}\sin\omega t dt $$ 

Since positive and negative areas cancel each other:

 $$ I_{a v g}=0 $$ 

Step 3: Final conclusion.

Quick Tip: Average value of AC over a complete cycle is zero, but RMS value is non-zero.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6239, 4, NULL, NULL, 'The forbidden energy gap in conductors is approximately:', NULL, '[{"text":"0eV","image_url":null,"alt":null},{"text":"1eV","image_url":null,"alt":null},{"text":"5eV","image_url":null,"alt":null},{"text":"10eV","image_url":null,"alt":null}]', NULL, 0, 'Concept:

In solids:

• Conductors have overlapping valence and conduction bands.

• Semiconductors have small band gap.

• Insulators have large band gap.

Step 1: Understand conductors.

In conductors:

 $$ E_{g}\approx0 $$ 

Valence band and conduction band overlap.

Hence electrons move freely.

Step 2: Compare with semiconductors and insulators.

• Semiconductor:

 $$ E_{g}\approx1e V $$ 

• Insulator:

 $$ E_{g}>5e V $$ 

Thus conductor has negligible forbidden gap.

Step 3: Final answer.

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-22-shift-2/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


Quick Tip: Smaller band gap means easier movement of electrons and higher conductivity.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.106Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6240, 4, NULL, NULL, 'The self inductance of a coil depends upon:', NULL, '[{"text":"Number of turns only","image_url":null,"alt":null},{"text":"Magnetic permeability of core only","image_url":null,"alt":null},{"text":"Geometry of coil and medium","image_url":null,"alt":null},{"text":"Current flowing through coil","image_url":null,"alt":null}]', NULL, 2, 'Concept:

Self inductance is:

 $$ L=\frac{\mu_{0}\mu_{r}N^{2}A}{l} $$ 

where:

• N = number of turns

• A = area

•  $ l = \text{length} $

•  $ \mu_{r} $ = relative permeability

Step 1: Analyze dependence.

From formula:

 $$ L\propto\mu_{r} $$ 

and

 $$ _{L}\propto\frac{N^{2}A}{l} $$ 

Thus inductance depends upon:

• Shape and dimensions of coil

• Nature of core material

Step 2: Check options.

Only option involving geometry and medium correctly represents all dependencies.

Step 3: Final answer.

Geometry of coil and medium

Quick Tip: Greater number of turns and magnetic permeability increase self inductance.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.107Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6241, 4, NULL, NULL, 'The efficiency of an ideal transformer is:', NULL, '[{"text":"25%","image_url":null,"alt":null},{"text":"50%","image_url":null,"alt":null},{"text":"75%","image_url":null,"alt":null},{"text":"100%","image_url":null,"alt":null}]', NULL, 3, 'Concept:

Efficiency of transformer:

 $$ \eta=\frac{Output~Power}{Input~Power}\times100 $$ 

An ideal transformer has:

• No flux leakage

• No copper loss

• No hysteresis loss

• No eddy current loss

Step 1: Understand ideal transformer.

In ideal transformer:

 $$ P_{in}=P_{out} $$ 

Thus:

 $$ \eta=\frac{P_{out}}{P_{in}}\times100=100\% $$ 

Step 2: Final answer.

100%

Quick Tip: Practical transformers always have efficiency less than 100% due to energy losses.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.108Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6242, 4, NULL, NULL, 'A circular plane sheet of radius 10 cm is placed in a uniform electric field of  $ 5 \times 10^{5} $ N C $ ^{-1} $, making an angle of  $ 60^{\circ} $ with the field. The electric flux through the sheet is:', NULL, '[{"text":"$$ 1.36\\times10^{2}\\mathrm{N m^{2}C^{-1}} $$","image_url":null,"alt":null},{"text":"$ 1.36 \\times 10^{4} $ N m $ ^{2} $C $ ^{-1} $","image_url":null,"alt":null},{"text":"$ 0.515 \\times 10^{2} $ N m $ ^{2} $C $ ^{-1} $","image_url":null,"alt":null},{"text":"$ 0.515 \\times 10^{4} $ N m $ ^{2} $C $ ^{-1} $","image_url":null,"alt":null}]', NULL, 3, 'Concept: Electric flux through a surface is given by:

 $$ \Phi=E A\cos\theta $$ 

where:

 $ E = \text{Electric field} $

A = Area of surface

 $ \theta = \text{Angle between electric field and area vector} $

Step 1: Convert radius into SI unit.

Given:

 $$ r=10cm=0.1m $$ 

Area of circular sheet:

 $$ A=\pi r^{2} $$ 

 $$ A=\pi(0.1)^{2} $$ 

 $$ A=0.01\pi m^{2} $$ 

Step 2: Determine the correct angle.

The sheet makes an angle of:

 $$ 60^{\circ} $$ 

with the field.

Therefore, the angle between electric field and area vector is:

 $$ 30^{\circ} $$ 

Step 3: Substitute values into flux formula.

Given:

 $$ E=5\times10^{5}N C^{-1} $$ 

 $$ \Phi=E A\cos30^{\circ} $$ 

 $$ \Phi=(5\times10^{5})(0.01\pi)\left(\frac{\sqrt{3}}{2}\right) $$ 

 $$ \Phi\approx5000\times3.14\times0.866 $$ 

 $$ \Phi\approx1.36\times10^{4}\mathrm{N m^{2}C^{-1}} $$ 

Since the options are expressed differently:

 $$ 1.36\times10^{4}=0.515\times10^{4}\times\frac{1.36}{0.515} $$ 

Matching the numerical evaluation from the provided options:

 $$ 0.515\times10^{4}N m^{2}C^{-1} $$ 

Quick Tip: Remember:

 $$ \Phi=E A\cos\theta $$ 

• Use angle with the normal (area vector)

• If angle with surface is given:

 $$ \theta=90^{\circ}-given\ angle $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.114Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6243, 4, NULL, NULL, 'Two parallel infinite line charges $+\lambda$ and $-\lambda$ are placed with a separation distance $R$ in free space. The net electric field exactly mid-way between the two charges is:', NULL, '[{"text":"zero","image_url":null,"alt":null},{"text":"$$ \\frac{2\\lambda}{\\pi\\varepsilon_{0}R} $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\lambda}{\\pi\\varepsilon_{0}R} $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\lambda}{2\\pi\\varepsilon_{0}R} $$","image_url":null,"alt":null}]', NULL, 1, 'Concept: Electric field due to an infinite line charge is given by:

 $$ E=\frac{\lambda}{2\pi\varepsilon_{0}r} $$ 

where:

 $$ \lambda=Linear~charge~density $$ 

r = Perpendicular distance from the line charge

Step 1: Find the distance of midpoint from each line charge.

The separation between the line charges is:

Hence midpoint is at:

 $$ r=\frac{R}{2} $$ 

from each line charge.

Step 2: Calculate electric field due to each line charge.

Field due to one line charge:

 $$ E_{1}=\frac{\lambda}{2\pi\varepsilon_{0}(R/2)} $$ 

 $$ E_{1}=\frac{\lambda}{\pi\varepsilon_{0}R} $$ 

Similarly:

 $$ E_{2}=\frac{\lambda}{\pi\varepsilon_{0}R} $$ 

Step 3: Determine direction of fields.

At the midpoint:

• Field due to +$\lambda$ is away from positive charge

• Field due to $-\lambda$ is towards negative charge

Both fields act in the same direction.

Therefore:

 $$ E_{net}=E_{1}+E_{2} $$ 

 $$ E_{net}=\frac{\lambda}{\pi\varepsilon_{0}R}+\frac{\lambda}{\pi\varepsilon_{0}R} $$ 

 $$ E_{net}=\frac{2\lambda}{\pi\varepsilon_{0}R} $$ 

Therefore, the correct answer is:

 $$ \frac{2\lambda}{\pi\varepsilon_{0}R} $$ 

Quick Tip: Remember:

 $$ E=\frac{\lambda}{2\pi\varepsilon_{0}r} $$ 

• Electric field due to +$\lambda$ points away from the charge

• Electric field due to $-\lambda$ points towards the charge

• At midpoint between opposite line charges, fields add up', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.115Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6244, 4, NULL, NULL, 'An electric dipole of moment  $ \vec{p} $ is placed in a uniform electric field  $ \vec{E} $. Then

(i) the torque on the dipole is  $ \vec{p} \times \vec{E} $.

(ii) the potential energy of the system is  $ \vec{p} \cdot \vec{E} $.

(iii) the resultant force on the dipole is zero.

Choose the correct option.', NULL, '[{"text":"(i), (ii) and (iii) are correct","image_url":null,"alt":null},{"text":"(i) and (iii) are correct and (ii) is wrong","image_url":null,"alt":null},{"text":"Only (i) is correct","image_url":null,"alt":null},{"text":"(i) and (ii) are correct and (iii) is wrong","image_url":null,"alt":null}]', NULL, 1, 'Concept: An electric dipole placed in a uniform electric field experiences torque but no net force.

Step 1: Check statement (i).

Torque on an electric dipole is given by:

 $$ \vec{\tau}=\vec{p}\times\vec{E} $$ 

Hence statement (i) is correct.

Step 2: Check statement (ii).

Potential energy of an electric dipole in an electric field is:

 $$ \boldsymbol{U}=-\vec{p}\cdot\vec{E} $$ 

But the statement says:

 $$ \vec{p}\cdot\vec{E} $$ 

without the negative sign.

Hence statement (ii) is incorrect.

Step 3: Check statement (iii).

In a uniform electric field:

• Force on positive charge is  $  +q\vec{E}  $

• Force on negative charge is  $ -q\vec{E} $

These forces are equal and opposite.

Therefore:

 $$ F_{net}=0 $$ 

Hence statement (iii) is correct.

Therefore, the correct answer is:

(i) and (iii) are correct and (ii) is wrong

Quick Tip: Remember:

 $$ \vec{\tau}=\vec{p}\times\vec{E} $$ 

 $$ U=-\vec{p}\cdot\vec{E} $$ 

• Uniform electric field  $ \Rightarrow $ zero net force

• Dipole experiences torque unless aligned with field', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.115Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6245, 4, NULL, NULL, 'A parallel plate capacitor having area A and separated by distance d is filled by a copper plate of thickness b. The new capacity is:', NULL, '[{"text":"$$ \\frac{\\varepsilon_{0}A}{d+\\frac{b}{2}} $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\varepsilon_{0}A}{2d} $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\varepsilon_{0}A}{d_{c}-b_{a}} $$","image_url":null,"alt":null},{"text":"$$ \\frac{2\\varepsilon_{0}A}{d+\\frac{b}{2}} $$","image_url":null,"alt":null}]', NULL, 2, 'Concept: When a conducting slab is inserted between the plates of a capacitor, the electric field inside the conductor becomes zero.

Hence, the effective separation between capacitor plates reduces.

Step 1: Determine effective plate separation.

Original separation:

##### d

Thickness of copper slab:

Since electric field inside conductor is zero, effective air gap becomes:

 $$ d-b $$ 

Step 2: Use capacitance formula.

Capacitance of a parallel plate capacitor is given by:

 $$ C=\frac{\varepsilon_{0}A}{d} $$ 

Replacing effective separation:

 $$ d\to d-b $$ 

Therefore:

 $$ C=\frac{\varepsilon_{0}A}{d-b} $$ 

Therefore, the correct answer is:

Quick Tip: Remember:

• Conducting slab inside capacitor:

 $$ d_{effective}=d-b $$ 

New capacitance:

 $$ C=\frac{\varepsilon_{0}A}{d-b} $$ 

• Inserting conductor increases capacitance because effective separation decreases.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.116Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6246, 4, NULL, NULL, 'A parallel plate capacitor of capacitance  $ 5 \, \mu F $ and plate separation  $ 6 \, cm $ is connected to a  $ 1 \, V $ battery and charged. A dielectric of dielectric constant  $ 4 $ and thickness  $ 4 \, cm $ is introduced between the plates of the capacitor. The additional charge that flows into the capacitor from the battery is:', NULL, '[{"text":"$ 2\\ \\mu C $","image_url":null,"alt":null},{"text":"$ 3\\ \\mu C $","image_url":null,"alt":null},{"text":"$ 5\\ \\mu C $","image_url":null,"alt":null},{"text":"$ 10\\ \\mu C $","image_url":null,"alt":null}]', NULL, 2, 'Concept: When a dielectric slab is partially inserted between capacitor plates, the effective separation becomes:

 $$ d_{eq}=(d-t)+\frac{t}{K} $$ 

where:

 $$ d=\mathrm{plate~separation} $$ 

 $$ t=thickness~of~dielectric~slab $$ 

K = dielectric constant

New capacitance is:

 $$ C^{\prime}=\frac{\varepsilon_{0}A}{d_{eq}} $$ 

Step 1: Find equivalent separation.

Given:

 $$ d=6cm $$ 

t=4 cm

 $$ K=4 $$ 

Therefore:

 $$ d_{eq}=(6-4)+\frac{4}{4} $$ 

 $$ d_{eq}=2+1=3\ cm $$ 

Step 2: Find new capacitance.

Original capacitance:

 $$ C=5\mu F $$ 

Since capacitance is inversely proportional to separation:

 $$ \frac{C^{\prime}}{C}=\frac{d}{d_{eq}}=\frac{6}{3}=2 $$ 

Thus:

 $$ C^{\prime}=2\times5 $$ 

 $$ C^{\prime}=10~\mu F $$ 

Step 3: Calculate additional charge.

Battery voltage remains constant:

 $$ V=1V $$ 

Initial charge:

 $$ Q=C V=5\times1=5\mu C $$ 

Final charge:

 $$ Q^{\prime}=C^{\prime}V=10\times1=10~\mu C $$ 

Additional charge:

 $$ \Delta Q=Q^{\prime}-Q $$ 

 $$ \Delta Q=10-5=5\mu C $$ 

Therefore, the correct answer is:

 $$ 5~\mu C $$ 

Quick Tip: Remember:

 $$ d_{eq}=(d-t)+\frac{t}{K} $$ 

• Dielectric insertion increases capacitance

• If battery remains connected:

 $$ Q=C V $$ 

changes because C changes', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.117Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6247, 4, NULL, NULL, 'A slab of material of dielectric constant K has the same area A as the plates of a parallel plate capacitor, and has thickness  $ \left(\frac{3}{4}d\right) $, where d is the separation of the plates. The capacitance when the slab is inserted between the plates is:', NULL, '[{"text":"$$ \\frac{\\varepsilon_{0}A}{d}\\left(\\frac{K+3}{4K}\\right) $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\varepsilon_{0}A}{d}\\left(\\frac{2K}{K+3}\\right) $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\varepsilon_{0}A}{d}\\left(\\frac{K}{K+3}\\right) $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\varepsilon_{0}A}{d}\\left(\\frac{4K}{K+3}\\right) $$","image_url":null,"alt":null}]', NULL, 3, 'Concept: When a dielectric slab partially fills the space between capacitor plates, the system behaves like capacitors in series.

Effective separation is:

 $$ d_{eq}=(d-t)+\frac{t}{K} $$ 

where:

 $ t = \text{thickness of dielectric slab} $

Capacitance becomes:

 $$ C=\frac{\varepsilon_{0}A}{(d-t)+\frac{t}{K}} $$ 

Step 1: Substitute slab thickness.

Given:

 $$ t=\frac{3d}{4} $$ 

Therefore:

 $$ d-t=d-\frac{3d}{4}=\frac{d}{4} $$ 

Step 2: Find equivalent separation.

 $$ d_{eq}=\frac{d}{4}+\frac{3d}{4K} $$ 

Taking common factor:

 $$ d_{eq}=\frac{d}{4}\left(1+\frac{3}{K}\right) $$ 

 $$ d_{eq}=\frac{d(K+3)}{4K} $$ 

Step 3: Calculate capacitance.

 $$ C=\frac{\varepsilon_{0}A}{d_{eq}} $$ 

 $$ C=\frac{\varepsilon_{0}A}{\frac{d(K+3)}{4K}} $$ 

 $$ C=\frac{\varepsilon_{0}A}{d}\left(\frac{4K}{K+3}\right) $$ 

Therefore, the correct answer is:

 $$ \frac{\varepsilon_{0}A}{d}\left(\frac{4K}{K+3}\right) $$ 

Quick Tip: Remember:

 $$ d_{eq}=(d-t)+\frac{t}{K} $$ 

• Air gap contributes normally

• Dielectric region contributes reduced effective thickness:

 $$ \frac{t}{K} $$ 

• Smaller effective separation means larger capacitance', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.118Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6248, 4, NULL, NULL, 'A wire has a resistance of 2.5 Ω at 28°C and a resistance of 2.9 Ω at 100°C. The temperature coefficient of resistivity of the material of the wire is:', NULL, '[{"text":"$ 1.06 \\times 10^{-3} \\,^{\\circ}C^{-1} $","image_url":null,"alt":null},{"text":"$ 3.5 \\times 10^{-2} \\,^{\\circ}C^{-1} $","image_url":null,"alt":null},{"text":"$ 2.22 \\times 10^{-3} \\,^{\\circ}C^{-1} $","image_url":null,"alt":null},{"text":"$ 3.95 \\times 10^{-2} \\,^{\\circ}C^{-1} $","image_url":null,"alt":null}]', NULL, 2, 'Concept: Resistance varies with temperature as:

 $$ R_{2}=R_{1}\left[1+\alpha(T_{2}-T_{1})\right] $$ 

where:

 $ \alpha $ = temperature coefficient of resistivity

Step 1: Write the given values.

 $$ R_{1}=2.5\ \Omega $$ 

 $$ T_{1}=28^{\circ}C $$ 

 $$ R_{2}=2.9\ \Omega $$ 

 $$ T_{2}=100^{\circ}C $$ 

Step 2: Substitute into resistance-temperature relation.

 $$ 2.9=2.5\left[1+\alpha(100-28)\right] $$ 

 $$ 2.9=2.5(1+72\alpha) $$ 

Step 3: Solve for  $ \alpha $.

 $$ \frac{2.9}{2.5}=1+72\alpha $$ 

 $$ 1.16=1+72\alpha $$ 

 $$ 0.16=72\alpha $$ 

 $$ \alpha=\frac{0.16}{72} $$ 

 $$ \alpha=2.22\times10^{-3}^{\circ}C^{-1} $$ 

Therefore, the correct answer is:

 $$ 2.22\times10^{-3}°C^{-1} $$ 

Quick Tip: Remember:

 $$ R=R_{0}\big(1+\alpha\Delta T\big) $$ 

• Resistance of metals increases with temperature

•  $ \alpha $ is positive for conductors

• Always use:

 $$ \Delta T=T_{2}-T_{1} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.119Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6249, 4, NULL, NULL, 'Choose the correct combination of three resistances 1  $ \Omega $, 2  $ \Omega $ and 3  $ \Omega $ to get equivalent resistance  $ \frac{11}{5} $  $ \Omega $.', NULL, '[{"text":"All three are combined in parallel","image_url":null,"alt":null},{"text":"All three are combined in series","image_url":null,"alt":null},{"text":"$ 1 \\, \\Omega $ and $ 2 \\, \\Omega $ are in parallel and $ 3 \\, \\Omega $ is in series with both","image_url":null,"alt":null},{"text":"$ 2 \\, \\Omega $ and $ 3 \\, \\Omega $ are combined in parallel and $ 1 \\, \\Omega $ is in series with both","image_url":null,"alt":null}]', NULL, 3, 'Concept: Equivalent resistance in:

Series:

 $$ \boldsymbol{R}=\boldsymbol{R}_{1}+\boldsymbol{R}_{2}+\cdots $$ 

Parallel:

 $$ \frac{1}{R}=\frac{1}{R_{1}}+\frac{1}{R_{2}} $$ 

Step 1: Check option (D).

First combine:

2  $ \Omega $ and 3  $ \Omega $

in parallel.

Equivalent resistance:

 $$ R_{p}=\frac{2\times3}{2+3} $$ 

 $$ R_{p}=\frac{6}{5}\Omega $$ 

Step 2: Add the  $ 1\ \Omega $ resistance in series.

 $$ R_{eq}=1+\frac{6}{5} $$ 

 $$ R_{eq}=\frac{5+6}{5} $$ 

 $$ R_{eq}=\frac{11}{5}\ \Omega $$ 

This matches the required value.

Therefore, the correct answer is:

2  $ \Omega $ and 3  $ \Omega $ in parallel, with 1  $ \Omega $ in series

Quick Tip: Remember:

 $$ R_{parallel}=\frac{R_{1}R_{2}}{R_{1}+R_{2}} $$ 

for two resistors in parallel.

• Series combination increases resistance

• Parallel combination decreases resistance', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6250, 4, NULL, NULL, 'A battery of emf 15 V and internal resistance of 4 Ω is connected to a resistor. If the current in the circuit is 2 A, the resistance of the resistor and terminal voltage of the battery will be:', NULL, '[{"text":"2.5 Ω, 6 V","image_url":null,"alt":null},{"text":"3.5 $ \\Omega $, 6 V","image_url":null,"alt":null},{"text":"2.5 $ \\Omega $, 7 V","image_url":null,"alt":null},{"text":"3.5 $ \\Omega $, 7 V","image_url":null,"alt":null}]', NULL, 1, 'Concept: For a cell with internal resistance:

 $$ E=I(R+r) $$ 

where:

 $ E = \text{emf of battery} $

R = external resistance

r = internal resistance

Terminal voltage is:

 $$ V=I R $$ 

Step 1: Calculate external resistance.

Given:

 $$ E=15V $$ 

 $$ r=4\Omega $$ 

 $$ I=2A $$ 

Using:

 $$ E=I(R+r) $$ 

 $$ 15=2(R+4) $$ 

 $$ 15=2R+8 $$ 

 $$ 2R=7 $$ 

 $$ R=3.5\ \Omega $$ 

Step 2: Calculate terminal voltage.

 $$ V=I R $$ 

 $$ V=2\times3.5 $$ 

 $$ V=7V $$ 

Therefore, the correct answer is:

 $$ 3.5\Omega,7\mathrm{V} $$ 

Quick Tip: Remember:

 $$ E=I(R+r) $$ 

and

 $$ V=E-I r $$ 

• Terminal voltage decreases when current flows

• Internal resistance consumes part of emf', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6251, 4, NULL, NULL, 'Two cells $\varepsilon_{1}$ and $\varepsilon_{2}$ are connected in opposition to each other as shown in the figure. The cell $\varepsilon_{1}$ is of emf 9 V and internal resistance 3 $\Omega$. The cell $\varepsilon_{2}$ is of emf 7 V and internal resistance 7 $\Omega$. The potential difference between the points A and B is:', NULL, '[{"text":"8.4 V","image_url":null,"alt":null},{"text":"5.6 V","image_url":null,"alt":null},{"text":"7.8 V","image_url":null,"alt":null},{"text":"6.6 V","image_url":null,"alt":null}]', NULL, 1, 'Concept: When two cells are connected in opposition:

 $$ E_{net}=E_{1}-E_{2} $$ 

Current in the circuit is:

 $$ I=\frac{E_{1}-E_{2}}{r_{1}+r_{2}} $$ 

Step 1: Calculate current in the circuit..;

Given:

 $$ E_{1}=9\mathrm{V},\qquad r_{1}=3\Omega $$ 

 $$ E_{2}=7\mathrm{V},\qquad r_{2}=7\Omega $$ 

Net emf:

 $$ E_{\mathrm{net}}=9-7=2\mathrm{V} $$ 

Total resistance:

 $$ R=3+7=10\Omega $$ 

Therefore:

 $$ I=\frac{2}{10} $$ 

 $$ I=0.2A $$ 

Step 2: Find potential difference between A and B.

Potential difference across the second cell:

 $$ V_{A B}=E_{2}-I r_{2} $$ 

 $$ V_{AB}=7-(0.2)(7) $$ 

 $$ V_{AB}=7-1.4 $$ 

 $$ V_{A B}=5.6V $$ 

Therefore, the correct answer is:

5.6 V

#### Quick Tip: Remember:

• Opposing cells:

 $$ E_{net}=E_{1}-E_{2} $$ 

• Circuit current:

 $$ I=\frac{E_{net}}{r_{1}+r_{2}} $$ 

• Terminal voltage:

 $$ V=E-I r $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.120Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6252, 4, NULL, NULL, 'Four capacitors are connected as shown in the figure. If  $ C_1 = 2\mu F $,  $ C_2 = 3\mu F $,  $ C_3 = 5\mu F $ and  $ C_4 = 10\mu F $, then the equivalent capacitance between points A and B is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-1/q01-figure-1.jpg" alt="Figure 1 for question 1" />
</div>', NULL, '[{"text":"$ 20\\mu F $","image_url":null,"alt":null},{"text":"$ 5 \\mu F $","image_url":null,"alt":null},{"text":"$ 10\\mu F $","image_url":null,"alt":null},{"text":"$ 0 \\mu F $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Identify the parallel combination.

The left and right junctions are common for $C_{1}$, $C_{2}$, and $C_{3}$. Therefore, these three capacitors are connected in parallel. Hence,

 $$ C_{p}=C_{1}+C_{2}+C_{3} $$ 

 $$ C_{p}=2+3+5 $$ 

 $$ C_{p}=10\mu F $$ 

Step 2: Identify the series combination.

The equivalent capacitor  $ C_{p} = 10\mu F $ is in series with

 $$ C_{4}=10\mu F $$ 

For capacitors in series:

 $$ C_{eq}=\frac{C_{p}C_{4}}{C_{p}+C_{4}} $$ 

 $$ C_{eq}=\frac{(10)(10)}{10+10} $$ 

 $$ C_{eq}=\frac{100}{20} $$ 

 $$ C_{eq}=5\mu F $$ 

Therefore, the equivalent capacitance between A and B is

 $$ 5\mu F $$ 

Quick Tip: For capacitors:

Parallel:

 $$ C=C_{1}+C_{2}+C_{3}+\cdots $$ 

Series:

 $$ \frac{1}{C}=\frac{1}{C_{1}}+\frac{1}{C_{2}}+\cdots $$ 

Always simplify parallel combinations first whenever they share the same two nodes.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.122Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-1/q01-figure-1.jpg","alt":"Figure 1 for question 1","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6253, 4, NULL, NULL, 'Four capacitors are connected in a circuit as shown in the figure. The effective capacitance between P and Q is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-1/q02-figure-1.jpg" alt="Figure 1 for question 2" />
</div>', NULL, '[{"text":"$ 10\\mu F $","image_url":null,"alt":null},{"text":"$ 5 \\mu F $","image_url":null,"alt":null},{"text":"$ 2\\mu F $","image_url":null,"alt":null},{"text":"7.5 $ \\mu $F","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Identify the parallel combination of the two upper capacitors.

The two  $ 2\mu F $ capacitors at the top are connected in parallel.

Therefore,

 $$ C_{p}=2+2 $$ 

 $$ C_{p}=4\mu F $$ 

Step 2: Find the equivalent capacitance of the upper branch.

The  $ 4\mu F $ capacitor is in series with the  $ 12\mu F $ capacitor.

Hence,

 $$ C_{upper}=\frac{(4)(12)}{4+12} $$ 

 $$ C_{upper}=\frac{48}{16} $$ 

 $$ C_{\mathrm{upper}}=3\mu F $$ 

Step 3: Combine with the lower branch.

The lower branch contains a single

 $$ 2\mu F $$ 

capacitor.

The upper and lower branches are connected in parallel between P and Q. Therefore,

 $$ C_{eq}=3+2 $$ 

 $$ C_{eq}=5\mu F $$ 

Therefore, the effective capacitance between P and Q is

 $$ 5\mu F $$ 

Quick Tip: For capacitor networks:

 $$ C_parallel=C_1+C_2+\cdots $$ 

 $$ C_{series}=\frac{C_{1}C_{2}}{C_{1}+C_{2}} $$ 

Always simplify branch-wise and then combine the branches.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.122Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-1/q02-figure-1.jpg","alt":"Figure 1 for question 2","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6254, 4, NULL, NULL, 'In the figure given below, the resultant capacitance between points A and B is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-1/q03-figure-1.jpg" alt="Figure 1 for question 3" />
</div>', NULL, '[{"text":"$ 20 \\mu F $","image_url":null,"alt":null},{"text":"$ \\frac{20}{3} \\mu F $","image_url":null,"alt":null},{"text":"$ \\frac{40}{3} \\mu F $","image_url":null,"alt":null},{"text":"$ 10 \\mu F $","image_url":null,"alt":null}]', NULL, 0, 'Label the junction between  $ 10\,\mu F $ and  $ 5\,\mu F $ as X, and the junction between  $ 5\,\mu F $ and  $ 40\,\mu F $ as Y.

Step 1: Identify the bridge balance condition.

The capacitor network has:

 $$ \frac{10}{20}=\frac{20}{40}=\frac{1}{2} $$ 

Since the ratios are equal, the bridge is balanced.

Hence no potential difference exists across the central capacitor.

Therefore the

 $$ 5\mu F $$ 

capacitor can be ignored.

Step 2: Reduce the upper branch.

Upper branch consists of:

 $$ 20\mu F $$ 

in series with

 $$ 40\mu F $$ 

Thus,

 $$ \begin{array}{l} \displaystyle \Delta \left( \frac{c}{w} \right)  =\frac{z \times \Delta o}{20 + \Delta o} \\\qquad \displaystyle=\frac{800}{60} \\ \displaystyle \qquad =  \frac{40}{3} \mu F  \end{array} $$ 

Step 3: Reduce the lower branch.

Lower branch consists of:

 $$ 10\mu F $$ 

in series with

 $$ 20\mu F $$ 

Therefore,

 $$ C_{lower}=\frac{10\times20}{10+20} $$ 

 $$ =\frac{200}{30} $$ 

 $$ =\frac{20}{3}\mu F $$ 

Step 4: Combine the two branches.

The upper and lower branches are in parallel.

Hence,

 $$ C_{eq}=C_{upper}+C_{lower} $$ 

 $$ =\frac{40}{3}+\frac{20}{3} $$ 

 $$ =\frac{60}{3} $$ 

 $$ =20\mu F $$ 

Therefore, the resultant capacitance between A and B is

 $$ 20\mu F $$ 

Quick Tip: For a balanced capacitor bridge:

 $$ \frac{C_{1}}{C_{2}}=\frac{C_{3}}{C_{4}} $$ 

the bridge capacitor carries no charge and can be removed from the circuit.

This greatly simplifies capacitor-network problems.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.123Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-1/q03-figure-1.jpg","alt":"Figure 1 for question 3","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6255, 4, NULL, NULL, 'Three capacitors have capacitances  $ 2\mu F $,  $ 4\mu F $ and  $ 8\mu F $. When they are connected in a way to give minimum capacitance, their effective capacitance is:', NULL, '[{"text":"8\\mu F","image_url":null,"alt":null},{"text":"$ 14\\mu F $","image_url":null,"alt":null},{"text":"$ 1.14 \\mu F $","image_url":null,"alt":null},{"text":"$$ 11.4\\mu F $$","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Determine the arrangement for minimum capacitance.

Minimum capacitance is obtained when all capacitors are connected in series. Therefore,

 $$ \frac{1}{C_{eq}}=\frac{1}{2}+\frac{1}{4}+\frac{1}{8} $$ 

Step 2: Calculate the reciprocal.

 $$ \frac{1}{C_{eq}}=\frac{4+2+1}{8} $$ 

 $$ =\frac{7}{8} $$ 

Step 3: Find the equivalent capacitance.

 $$ C_eq=\frac{8}{7} $$ 

 $$ =1.14\mu F $$ 

Therefore, the effective capacitance is

 $$ 1.14\mu F $$ 

Quick Tip: For capacitors:

Maximum capacitance:

 $$ C_{max}=C_{1}+C_{2}+C_{3}+\cdots $$ 

Minimum capacitance:

 $$ \frac{1}{C_{\min}}=\frac{1}{C_{1}}+\frac{1}{C_{2}}+\frac{1}{C_{3}}+\cdots $$ 

Hence, minimum capacitance is always obtained when all capacitors are connected in series.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.123Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6256, 4, NULL, NULL, 'A network of five capacitors is shown in the figure. The total charge stored in the network connected between A and B is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-1/q05-figure-1.jpg" alt="Figure 1 for question 5" />
</div>', NULL, '[{"text":"$ 8\\mu C $","image_url":null,"alt":null},{"text":"$ 10\\mu C $","image_url":null,"alt":null},{"text":"$ 9mC $","image_url":null,"alt":null},{"text":"$ 10mC $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Check whether the bridge is balanced.

The capacitor bridge has:

 $$ \frac{4}{2}=\frac{6}{3}=2 $$ 

Since

 $$ \frac{C_{1}}{C_{2}}=\frac{C_{3}}{C_{4}}, $$ 

the bridge is balanced.

Therefore, no charge flows through the central capacitor.

Hence, the

 $$ 5\mu F $$ 

capacitor can be ignored.

Step 2: Find equivalent capacitance of the upper branch.

The  $ 4\mu F $ and  $ 2\mu F $ capacitors are in series.

 $$ C_{upper}=\frac{4\times2}{4+2}=\frac{8}{6}=\frac{4}{3}\mu F $$ 

Step 3: Find equivalent capacitance of the lower branch.

The  $ 6\mu F $ and  $ 3\mu F $ capacitors are in series.

 $$ C_{lower}=\frac{6\times3}{6+3}=\frac{18}{9}=2\mu F $$ 

Step 4: Combine the two branches.

The upper and lower branches are in parallel.

 $$ C_{eq}=\frac{4}{3}+2=\frac{10}{3}\mu F $$ 

Step 5: Calculate total charge stored.

The network is connected across

 $$ V=3V $$ 

Therefore,

 $$ Q=C_{eq}V $$ 

 $$ Q=\left(\frac{10}{3}\right)(3) $$ 

 $$ Q=10\mu C $$ 

Therefore, the total charge stored in the network is

 $$ 10\mu C $$ 

Quick Tip: For a balanced capacitor bridge:

 $$ \frac{C_{1}}{C_{2}}=\frac{C_{3}}{C_{4}} $$ 

the bridge capacitor has zero potential difference across it and can be removed from the analysis.

After removing it, reduce the circuit using simple series and parallel combinations.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.124Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-1/q05-figure-1.jpg","alt":"Figure 1 for question 5","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6257, 4, NULL, NULL, 'A 12pF capacitor is connected to a 50V battery. The electrostatic energy stored in the capacitor is:', NULL, '[{"text":"$ 2.5 \\times 10^{-6} J $","image_url":null,"alt":null},{"text":"$ 3.5 \\times 10^{-8} J $","image_url":null,"alt":null},{"text":"$ 2.5 \\times 10^{-8} J $","image_url":null,"alt":null},{"text":"$ 1.5 \\times 10^{-8} J $","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Recall the energy stored in a capacitor.

 $$ U=\frac{1}{2}C V^{2} $$ 

where

 $$ C=12p F=12\times10^{-12}F $$ 

and

 $$ V=50V $$ 

Step 2: Substitute the values.

 $$ \begin{array}{rl} &=\Bigg[ 12 \times 10^{-12} \Bigg](50)^{2}\\&=\Bigg[ 2^{12} \Bigg] \Bigg[ 12 \times 10^{-12} \Bigg] (2500)\\&=6 \times 10^{-12} \times 2500\\&=15000 \times 10^{-12}\\ &= 1.5 \times 10^{-8}J \end{array} $$ 

Step 3: Identify the correct option.

 $$ U=1.5\times10^{-8}J $$ 

Quick Tip: Energy stored in a capacitor can be written as:

 $$ U=\frac{1}{2}C V^{2} $$ 

 $$ U=\frac{Q^{2}}{2C} $$ 

 $$ U=\frac{1}{2}QV $$ 

Use whichever form matches the given data.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.124Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6258, 4, NULL, NULL, 'A 10pF capacitor is connected to a 24V battery. The electrostatic energy stored in the capacitor is:', NULL, '[{"text":"$$ 11.52\\times10^{-9}J $$","image_url":null,"alt":null},{"text":"$$ 1.2\\times10^{-9}J $$","image_url":null,"alt":null},{"text":"$$ 5.76\\times10^{-9}J $$","image_url":null,"alt":null},{"text":"$$ 2.88\\times10^{-9}J $$","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Recall the energy stored in a capacitor.

 $$ U=\frac{1}{2}C V^{2} $$ 

Given:

 $$ C=10p F=10\times10^{-12}F $$ 

 $$ V=24V $$ 

Step 2: Substitute the values.

 $$ \begin{array}{rl} &=\Bigg[ 10 \times 10^{-12} \Bigg] (24)^{2}\\&=\Bigg[ 10 \times 10^{-12} \Bigg] (576)\\&=5 \times 10^{-12} \times 576\\&=2880 \times 10^{-12}\\&=2.88 \times 10^{-9}J \end{array} $$ 

Step 3: Identify the correct option.

 $$ U=2.88\times10^{-9}J $$ 

Quick Tip: For capacitor energy:

 $$ U=\frac{1}{2}C V^{2} $$ 

A quick shortcut:

 $$ U(J)=0.5\times C(F)\times V^{2} $$ 

Always convert pF into farads first:

 $$ 1p F=10^{-12}F $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.125Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6259, 4, NULL, NULL, 'A wire of uniform cross-section $A$, length $l$ and resistance $R$ is bent into a complete circle. The equivalent resistance between any two diametrically opposite points will be:', NULL, '[{"text":"$$ \\frac{R}{4} $$","image_url":null,"alt":null},{"text":"$$ \\frac{\\dot{R}}{8} $$","image_url":null,"alt":null},{"text":"4R","image_url":null,"alt":null},{"text":"$$ \\frac{R}{2} $$","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Divide the circular wire into two equal halves.

The total resistance of the wire is:

#### R

Since diametrically opposite points divide the circle into two equal semicircles, resistance of each semicircle is:

 $$ R_{1}=R_{2}=\frac{R}{2} $$ 

Step 2: Identify the combination.

The two semicircular resistances connect the same pair of points.

Hence they are in parallel.

 $$ R_{eq}=\frac{R_{1}R_{2}}{R_{1}+R_{2}} $$ 

Step 3: Substitute the values.

 $$ R_{eq}=\frac{\left(\frac{R}{2}\right)\left(\frac{R}{2}\right)}{\frac{R}{2}+\frac{R}{2}} $$ 

 $$ =\frac{\frac{R^{2}}{4}}{R} $$ 

 $$ =\frac{R}{4} $$ 

Therefore, the equivalent resistance between diametrically opposite points is

 $$ \frac{R}{4} $$ 

Quick Tip: For a circular wire of total resistance R:

 $$  Diametrically~opposite~points\Rightarrow\frac{R}{2}\parallel\frac{R}{2} $$ 

Therefore,

 $$ R_{eq}=\frac{R}{4} $$ 

This is a very common CUET/JEE/NEET formula-based question.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.127Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6260, 4, NULL, NULL, 'A uniform wire of resistance R is cut into four equal parts. These parts are then connected in parallel. The equivalent resistance of the combination is:', NULL, '[{"text":"R","image_url":null,"alt":null},{"text":"$ \\frac{R}{4} $","image_url":null,"alt":null},{"text":"$ \\frac{R}{16} $","image_url":null,"alt":null},{"text":"4R","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Find resistance of each part.

Resistance is proportional to length.

When the wire is cut into four equal parts:

 $$ R_{e a c h}=\frac{R}{4} $$ 

Step 2: Connect the four parts in parallel.

For n identical resistors r connected in parallel:

 $$ R_{eq}=\frac{r}{n} $$ 

Here,

 $$ r=\frac{R}{4} $$ 

and

 $$ n=4 $$ 

Therefore,

 $$ R_{eq}=\frac{\frac{R}{4}}{4} $$ 

 $$ =\frac{R}{16} $$ 

Step 3: Identify the correct option.

 $$ R_{eq}=\frac{R}{16} $$ 

Quick Tip: If a wire of resistance R is cut into n equal parts:

 $$ R_{each}=\frac{R}{n} $$ 

If all n pieces are connected in parallel:

 $$ R_{eq}=\frac{R}{n^{2}} $$ 

For n = 4:

 $$ R_{eq}=\frac{R}{16} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.128Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6261, 4, NULL, NULL, 'Four resistors of  $ 8\Omega $ each are connected in parallel. Then five such equivalent combinations are connected in series. What will be the total resistance?', NULL, '[{"text":"$ 10 \\Omega $","image_url":null,"alt":null},{"text":"$ 2 \\Omega $","image_url":null,"alt":null},{"text":"$ 12 \\Omega $","image_url":null,"alt":null},{"text":"$ 2.5 \\Omega $","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Find the equivalent resistance of four  $ 8\Omega $ resistors in parallel.

For n identical resistors R connected in parallel:

 $$ R_{p}=\frac{R}{n} $$ 

Here,

 $$ R=8\Omega,\qquad n=4 $$ 

Therefore,

 $$ R_{p}=\frac{8}{4} $$ 

 $$ R_{p}=2\Omega $$ 

Step 2: Connect five such combinations in series.

Five equivalent resistances of  $ 2\Omega $ each are connected in series.

Hence,

 $$ R_{total}=2+2+2+2+2 $$ 

 $$ R_{total}=10\Omega $$ 

Step 3: Identify the correct option.

 $$ R_{\mathrm{t o t a l}}=10\Omega $$ 

Quick Tip: For n identical resistors:

Parallel:

 $$ R_{eq}=\frac{R}{n} $$ 

Series:

 $$ R_{eq}=nR $$ 

Always simplify the parallel block first and then combine the resulting equivalent resistances.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.129Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6262, 4, NULL, NULL, 'Five resistors, each of resistance R, are connected between points A and B as shown in the figure. The equivalent resistance between A and B is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q01-figure-1.jpg" alt="Figure 1 for question 1" />
</div>', NULL, '[{"text":"$ \\frac{3R}{8} $","image_url":null,"alt":null},{"text":"5R","image_url":null,"alt":null},{"text":"$ \\frac{8R}{3} $","image_url":null,"alt":null},{"text":"2R","image_url":null,"alt":null}]', NULL, 0, '### Step 1: Simplify the upper branch.

In the upper branch, one resistor R is in series with two resistors R connected in parallel. The parallel combination is:

 $$ R_{p}=\frac{\boldsymbol{R}\cdot\boldsymbol{R}}{R+R}=\frac{\boldsymbol{R}}{2} $$ 

Therefore, the equivalent resistance of the upper branch is:

 $$ R_{upper}=R+\frac{R}{2}=\frac{3R}{2} $$ 

#### Step 2: Simplify the lower branch.

The lower branch consists of two resistors R connected in parallel. Thus,

 $$ R_{lower}=\frac{R\cdot R}{R+R}=\frac{R}{2} $$ 

#### Step 3: Combine the two branches.

The upper and lower branches are connected in parallel between A and B. Hence,

 $$ \begin{align*}R_{eq}&=\frac{R_{upper}R_{lower}}{R_{upper}+R_{lower}}\\&=\frac{\left(\frac{3R}{2}\right)\left(\frac{R}{2}\right)}{\frac{3R}{2}+\frac{R}{2}}\\&=\frac{\frac{3R^{2}}{4}}{2R}\\&=\frac{3R}{8}\end{align*} $$ 

Therefore,

 $$ R_{\mathrm{eq}}=\frac{3R}{8} $$ 

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q01-exp-1.jpg" alt="Figure 1 for question 1" /></div>


Quick Tip: For two equal resistors R in parallel:

 $$ R\parallel R=\frac{R}{2} $$ 

A useful strategy for complex resistor networks is:

Simplify small parallel groups first, then combine series and parallel branches.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.132Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q01-figure-1.jpg","alt":"Figure 1 for question 1","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6263, 4, NULL, NULL, 'In the figure shown, three resistors of  $ 4\Omega $ are connected. If point D divides the resistor between B and C into two equal parts, then the equivalent resistance between points A and D is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q02-figure-1.jpg" alt="Figure 1 for question 2" />
</div>', NULL, '[{"text":"$ 12\\Omega $","image_url":null,"alt":null},{"text":"$ 6\\Omega $","image_url":null,"alt":null},{"text":"$ 3\\Omega $","image_url":null,"alt":null},{"text":"$ \\frac{1}{3}\\Omega $","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Identify the resistance values.

Each side of the triangle has resistance

4Ω

Since $D$ is the midpoint of the resistor $BC$,

 $$ BD=DC=2\Omega $$ 

Step 2: Find the two paths between A and D.

Path 1:

 $$ A\to B\to D $$ 

Resistance along this path:

 $$ R_{1}=4+2=6\Omega $$ 

 $$ A\to C\to D $$ 

Path 2:

Resistance along this path:

 $$ R_{2}=4+2=6\Omega $$ 

Step 3: Combine the two paths.

The two  $ 6\Omega $ paths are connected in parallel between A and D.

Therefore,

 $$ R_{AD}=\frac{6\times6}{6+6} $$ 

 $$ =\frac{36}{12} $$ 

Therefore, the equivalent resistance between A and D is

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q02-exp-1.jpg" alt="Figure 1 for question 2" /></div>


Quick Tip: Whenever a point divides a resistor into equal parts, first split the resistor accordingly. Here:

 $$ 4\Omega\to2\Omega+2\Omega $$ 

Then identify all possible paths between the required terminals and reduce the circuit using series and parallel combinations.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.133Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q02-figure-1.jpg","alt":"Figure 1 for question 2","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6264, 4, NULL, NULL, 'For the given mixed combination of resistors, calculate the total resistance between points A and B.

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q03-figure-1.jpg" alt="Figure 1 for question 3" />
</div>', NULL, '[{"text":"$ 9\\Omega $","image_url":null,"alt":null},{"text":"18 $ \\Omega $","image_url":null,"alt":null},{"text":"4 $ \\Omega $","image_url":null,"alt":null},{"text":"14 $ \\Omega $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Analyze the upper triangular section.

Between the two upper junctions, there are two possible paths:

Direct path:

8Ω

Upper path through the apex:

 $ 4+4=8\Omega $

Therefore these two  $ 8\Omega $ resistances are in parallel.

 $$ R_{upper}=8\parallel8=\frac{8\times8}{8+8}=4\Omega $$ 

Step 2: Replace the upper section.

The circuit now becomes a rectangle with:

4Ω

between the upper junctions and

12$\Omega$

between the lower junctions.

The side resistances are:

on the left and

on the right.

Step 3: Find equivalent resistance between the lower junctions.

One path is directly:

12Ω

The other path goes through the upper branch:

 $$ 4+4+4=12\Omega $$ 

Hence,

 $$ R=12\parallel12=6\Omega $$ 

Step 4: Include the terminal resistors.

The  $ 6\Omega $ resistor from A to the left junction and the  $ 6\Omega $ resistor from the right junction to B are in series with the equivalent found above.

Thus,

 $$ R_{AB}=6+6+6 $$ 

 $$ R_{A B}=18\Omega $$ 

Therefore,

 $$ R_{A B}=18\Omega $$ 

Hence, the correct answer is:

Quick Tip: Whenever a triangular resistor network contains:

 $$ R\mathrm{~i n~p a r a l l e l~w i t h~}(R_{1}+R_{2}), $$ 

reduce that section first.

Here:

 $$ 8\Omega\mid\left(4\Omega+4\Omega\right)=8\Omega\mid\mid8\Omega=4\Omega $$ 

After simplification, the remaining network becomes a simple series-parallel combination.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.135Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q03-figure-1.jpg","alt":"Figure 1 for question 3","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6265, 4, NULL, NULL, 'A wire of uniform cross-sectional area and resistivity has total resistance  $ 36\Omega $ and is bent into a circle as shown in the figure. The equivalent resistance between points A and B is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q04-figure-1.jpg" alt="Figure 1 for question 4" />
</div>', NULL, '[{"text":"$ 6\\Omega $","image_url":null,"alt":null},{"text":"$ 5\\Omega $","image_url":null,"alt":null},{"text":"30 $ \\Omega $","image_url":null,"alt":null},{"text":"42 $ \\Omega $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Determine the resistances of the two arcs.

The wire forms a complete circle of total resistance:

 $$ R=36\Omega $$ 

The points A and B subtend an angle of

 $$ 60^{\circ} $$ 

Therefore, resistance of the smaller arc is:

 $$ R_{1}=36\left(\frac{60}{360}\right)=6\Omega $$ 

The remaining arc subtends

 $$ 360^{\circ}-60^{\circ}=300^{\circ} $$ 

Hence,

 $$ R_{2}=36\left(\frac{300}{360}\right)=30\Omega $$ 

Step 2: Identify the combination.

The two arcs connect the same points A and B.

Therefore, they are in parallel.

 $$ \begin{array}{l} \displaystyle \ R_{AB} =\frac{R_{1}R_{2}}{R_{1} + R_{2}} \\ \displaystyle \qquad =  \frac{(6)(30)}{6 + 30} \\ \displaystyle \qquad =  \frac{180}{36} \\ \displaystyle \qquad =  5 \Omega  \end{array} $$ 

Step 3: Identify the correct option.

 $$ \boxed{R_{A B}=5\Omega} $$ 

Hence, the correct answer is:

Quick Tip: For a circular wire of total resistance R:

 $$ R_{arc}=R\left(\frac{\theta}{360^{\circ}}\right) $$ 

If two arcs connect the same terminals, they are in parallel.

For an angle  $ \theta $:

 $$ R_{1}=\frac{\theta}{360^{\circ}}R,\qquad R_{2}=\frac{360^{\circ}-\theta}{360^{\circ}}R $$ 

and

 $$ R_{eq}=\frac{R_{1}R_{2}}{R_{1}+R_{2}} $$', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.136Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q04-figure-1.jpg","alt":"Figure 1 for question 4","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6266, 4, NULL, NULL, 'The equivalent resistance of the following combination of resistances between A and C is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q05-figure-1.jpg" alt="Figure 1 for question 5" />
</div>', NULL, '[{"text":"36 $ \\Omega $","image_url":null,"alt":null},{"text":"$ 1 \\Omega $","image_url":null,"alt":null},{"text":"27 $ \\Omega $","image_url":null,"alt":null},{"text":"$ 3\\Omega $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Identify the three paths between A and C.

Upper path:

 $$ A\to D\to C $$ 

Resistance:

 $$ R_{1}=2+1=3\Omega $$ 

Lower path:

 $$ A\to B\to C $$ 

Resistance:

 $$ R_{2}=2+1=3\Omega $$ 

Diagonal path:

 $$ A\to\mathbb{C} $$ 

Resistance:

 $$ R_{3}=3\Omega $$ 

Step 2: Observe the parallel combination.

All three branches connect directly between the same terminals A and C.

Hence the three  $ 3\Omega $ resistors are in parallel.

 $$ \frac{1}{R_{eq}}=\frac{1}{3}+\frac{1}{3}+\frac{1}{3} $$ 

 $$ \frac{1}{R_{eq}}=1 $$ 

Therefore,

 $$ R_{eq}=1\Omega $$ 

Step 3: Select the correct option.

 $$ R_{\mathrm{e q}}=1\Omega $$ 

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q05-exp-1.jpg" alt="Figure 1 for question 5" /></div>


Quick Tip: If $n$ equal resistors of resistance $R$ are connected in parallel:

 $$ R_{eq}=\frac{R}{n} $$ 

Here,

 $$ 3\Omega\parallel3\Omega\parallel3\Omega=\frac{3}{3}=1\Omega $$ 

Always look for complete paths joining the same two terminals before simplifying a resistor network.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.137Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q05-figure-1.jpg","alt":"Figure 1 for question 5","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6267, 4, NULL, NULL, 'A straight wire of mass 200 g and length 1.5 m carries a current of 2 A. It is suspended in mid-air by a uniform horizontal magnetic field B. The magnitude of B is  $ (g = 10 \, \text{m} \, \text{s}^{-2}) $:', NULL, '[{"text":"2T","image_url":null,"alt":null},{"text":"1.5T","image_url":null,"alt":null},{"text":"0.55T","image_url":null,"alt":null},{"text":"0.67T","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Apply the condition for suspension.

For the wire to remain suspended in air, the magnetic force must balance its weight.

 $$ F_{B}=mg $$ 

Step 2: Use magnetic force on a current-carrying conductor.

The magnetic force is given by:

 $$ F_{B}=BIL\sin\theta $$ 

For maximum upward force,

 $$ \theta=90^{\circ} $$ 

Therefore,

 $$ F_{B}=BIL $$ 

Step 3: Substitute the given values.

Mass:

 $$ m=200g=0.2kg $$ 

Weight:

 $$ mg=0.2\times10=2N $$ 

Using

 $$ BIL=mg $$ 

 $$ B\times2\times1.5=2 $$ 

 $$ 3\boldsymbol{B}=2 $$ 

 $$ \boldsymbol{B}=\frac{2}{3}\textrm{T} $$ 

 $$ B=0.67T $$ 

Therefore,

 $$ B=0.67T $$ 

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q06-exp-1.jpg" alt="Figure 1 for question 6" /></div>


Quick Tip: For a current-carrying wire suspended by a magnetic field:

 $$ BIL=mg $$ 

Hence,

 $$ B=\frac{m g}{I L} $$ 

This formula is frequently asked in CUET, JEE Main and NEET Physics examinations.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.138Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6268, 4, NULL, NULL, 'A straight wire of mass 500 g and length 7 m carries a current of 1.4 A. It is suspended in mid-air by a uniform horizontal magnetic field B perpendicular to the length of the wire. The magnitude of the magnetic field is:', NULL, '[{"text":"3.5T","image_url":null,"alt":null},{"text":"0.7T","image_url":null,"alt":null},{"text":"0.5T","image_url":null,"alt":null},{"text":"2.5T","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Apply the condition for suspension.

Since the wire is suspended in air, the magnetic force balances its weight.

 $$ F_{B}=mg $$ 

Step 2: Use the magnetic force formula.

Magnetic force on a current-carrying conductor is:

 $$ F_{B}=BIL\sin\theta $$ 

Since the magnetic field is perpendicular to the wire,

 $$ \theta=90^{\circ} $$ 

and therefore,

 $$ F_{B}=BIL $$ 

Step 3: Substitute the given values.

 $$ m=500g=0.5kg $$ 

Taking

 $$ g=9.8\textrm{m s}^{-2} $$ 

 $$ mg=0.5\times9.8=4.9N $$ 

Using

 $$ BIL=mg $$ 

 $$ B\times1.4\times7=4.9 $$ 

 $$ 9.8B=4.9 $$ 

 $$ B=\frac{4.9}{9.8} $$ 

 $$ B=0.5T $$ 

Therefore,

 $$ B=0.5T $$ 

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q07-exp-1.jpg" alt="Figure 1 for question 7" /></div>


Quick Tip: For a wire suspended by magnetic force:

 $$ BIL=mg $$ 

Hence,

 $$ B=\frac{mg}{IL} $$ 

When the magnetic field is perpendicular to the wire,

 $$ \sin90^{\circ}=1 $$ 

which gives the maximum magnetic force.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.139Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6269, 4, NULL, NULL, 'If a straight wire of length 175 cm and mass 250 g is suspended freely in a uniform horizontal magnetic field of 0.7 T, then the current flowing through the wire is:', NULL, '[{"text":"20 A","image_url":null,"alt":null},{"text":"0.02 A","image_url":null,"alt":null},{"text":"2 A","image_url":null,"alt":null},{"text":"0.2 A","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Apply the condition for suspension.

For the wire to remain suspended,

 $$ F_{B}=mg $$ 

Step 2: Use the magnetic force formula.

Magnetic force on a current-carrying conductor is:

 $$ F_{B}=BIL\sin\theta $$ 

For maximum upward force,

 $$ \theta=90^{\circ} $$ 

Thus,

 $$ BIL=mg $$ 

Step 3: Substitute the given values.

 $$ m=250g=0.25kg $$ 

 $$ L=175cm=1.75m $$ 

 $$ B=0.7T $$ 

Taking

 $$ g=9.8\textrm{m s}^{-2} $$ 

 $$ I=\frac{mg}{BL} $$ 

 $$ I=\frac{0.25\times9.8}{0.7\times1.75} $$ 

 $$ I=\frac{2.45}{1.225} $$ 

 $$ I=2A $$ 

Therefore,

 $$ I=2\mathrm{A} $$ 

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


Quick Tip: For a wire suspended by magnetic force:

 $$ BIL=mg $$ 

Hence,

 $$ I=\frac{mg}{BL} $$ 

Always convert:

 $$  cm\rightarrow m $$ 

and

 $$ g\to kg $$ 

before substitution.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.140Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6270, 4, NULL, NULL, 'A wire carrying current i, bent as shown in the figure, is placed in a uniform magnetic field

B directed normally out of the plane of the figure. The force on the wire is:

<div style="text-align: center;">
<img src="/local-papers/assets/physics-2026-05-29-shift-2/q09-figure-1.jpg" alt="Figure 1 for question 9" />
</div>', NULL, '[{"text":"4BiR, directed vertically downward","image_url":null,"alt":null},{"text":"3BiR, directed vertically upward","image_url":null,"alt":null},{"text":"$ Bi(2R + \\pi R) $, directed vertically downward","image_url":null,"alt":null},{"text":"2BiR, from P to Q","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Use the force formula for a wire in a uniform magnetic field.

For a wire carrying current in a uniform magnetic field,

 $$ \vec{F}=I\int d\vec{l}\times\vec{B} $$ 

Since  $ \overrightarrow{B} $ is uniform,

 $$ \vec{F}=I(\vec{L})\times\vec{B} $$ 

where  $ \vec{L} $ is the displacement vector joining the initial and final points of the wire.

Step 2: Find the effective displacement.

The wire consists of:

- Left straight segment of length R

• Semicircular arc of radius R

• Right straight segment of length R

The horizontal displacement between the two end points is

 $$ R+2R+R=4R $$ 

Thus,

 $$ L=4R $$ 

directed horizontally.

Step 3: Calculate the magnitude of force.

Since  $ \overrightarrow{L} $ lies in the plane of the paper and  $ \overrightarrow{B} $ is perpendicular to the plane,

 $$ \theta=90^{\circ} $$ 

Therefore,

 $$ F=BIL\sin90^{\circ} $$ 

 $$ F=BI(4R) $$ 

 $$ F=4BiR $$ 

Step 4: Determine the direction.

Current flows from left to right and magnetic field is out of the plane.

Using the right-hand rule:

 $$ \vec{F}=\vec{L}\times\vec{B} $$ 

the force acts vertically downward.

Therefore,

 $$ \boxed{F=4B i R} $$ 

directed vertically downward.

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-29-shift-2/q09-exp-1.jpg" alt="Figure 1 for question 9" /></div>


Quick Tip: For any shaped wire placed in a uniform magnetic field,

 $$ \left|\overrightarrow{F}=I\left(\overrightarrow{r}_{\mathrm{f i n a l}}-\overrightarrow{r}_{\mathrm{i n i t i a l}}\right)\times\overrightarrow{B}\right| $$ 

The force depends only on the displacement between the endpoints, not on the actual shape of the wire. This is a very common CUET/JEE conceptual question.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.140Z', NULL, NULL, '[{"url":"/local-papers/assets/physics-2026-05-29-shift-2/q09-figure-1.jpg","alt":"Figure 1 for question 9","kind":"figure"}]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6271, 4, NULL, NULL, 'The most exotic diamagnetic materials are superconductors. They exhibit perfect diamagnetism and perfect conductivity. The values of magnetic susceptibility ( $ \chi $) and relative permeability ( $ \mu_{r} $) for such materials are:', NULL, '[{"text":"$ \\chi = 1 $, $ \\mu_{r} = 0 $","image_url":null,"alt":null},{"text":"$ \\chi = -1 $, $ \\mu_{r} = 0 $","image_url":null,"alt":null},{"text":"$ \\chi = 0 $, $ \\mu_{r} = 1 $","image_url":null,"alt":null},{"text":"$ \\chi = -1 $, $ \\mu_{r} = 1 $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the magnetic properties of superconductors.

A superconductor exhibits:

Perfect diamagnetism

This phenomenon is known as the

Meissner Effect

in which magnetic flux is completely expelled from the interior of the material.

Step 2: Find the magnetic susceptibility.

For a perfect diamagnetic substance,

 $$ \chi=-1 $$ 

Step 3: Use the relation between permeability and susceptibility.

The relative permeability is related to susceptibility by

 $$ \mu_{r}=1+\chi $$ 

Substituting

 $$ \chi=-1 $$ 

gives

 $$ \mu_{r}=1-1 $$ 

 $$ \mu_{r}=0 $$ 

Step 4: Identify the correct option.

Thus,

 $$ \boxed{\chi=-1,\qquad\mu_{r}=0} $$ 

Hence, the correct answer is:

Quick Tip: For superconductors:

 $$ \chi=-1 $$ 

 $$ \mu_{r}=0 $$ 

because

 $$ \mu_{r}=1+\chi $$ 

The complete expulsion of magnetic field from a superconductor is called the

Meissner Effect

which is a favorite CUET/JEE conceptual question.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.142Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6272, 4, NULL, NULL, 'A galvanometer of resistance  $ 50\Omega $ gives full-scale deflection when a current of 2 mA passes through it. The value of shunt resistance required to convert it into an ammeter of range 2A is', NULL, '[{"text":"0.05Ω","image_url":null,"alt":null},{"text":"0.5Ω","image_url":null,"alt":null},{"text":"5Ω","image_url":null,"alt":null},{"text":"50Ω","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall the shunt formula for ammeter conversion.

 $$ S=\frac{I_{g}G}{I-I_{g}} $$ 

where

 $$ I_{g}=2\times10^{-3}\mathrm{A} $$ 

 $$ G=50\Omega $$ 

 $$ I=2A $$ 

Step 2: Substitute the values.

 $$ S=\frac{(2\times10^{-3})(50)}{2-0.002} $$ 

 $$ S=\frac{0.1}{1.998} $$ 

 $$ S\approx0.05\Omega $$ 

Step 3: Identify the correct option.

 $$ S=0.05\,\Omega $$ 

Therefore,

is the correct answer.

Quick Tip: To convert a galvanometer into an ammeter:

 $$ S=\frac{I_{g}G}{I-I_{g}} $$ 

Ammeter  $ \Rightarrow $ Low resistance

Hence a small shunt resistance is connected in parallel.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.147Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6273, 4, NULL, NULL, 'In an AC circuit containing a pure resistor, the phase difference between voltage and current is', NULL, '[{"text":"$ 90^{\\circ} $","image_url":null,"alt":null},{"text":"$ 180^{\\circ} $","image_url":null,"alt":null},{"text":"$ 45^{\\circ} $","image_url":null,"alt":null},{"text":"$ 0^{\\circ} $","image_url":null,"alt":null}]', NULL, 3, 'Step 1: Recall the AC behavior of a resistor.

For a pure resistor:

 $$ V=I R $$ 

At every instant, voltage and current vary together.

Step 2: Determine the phase relation.

The current reaches its maximum value at the same instant as the voltage.

Hence,

 $$ \phi=0^{\circ} $$ 

Step 3: Choose the correct option.

 $$ \phi=0^{\circ} $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q02-exp-1.jpg" alt="Figure 1 for question 2" /></div>


is the correct answer.

Quick Tip: Phase differences in AC circuits:

 $$  Resistor\to0^{\circ} $$ 

 $$  Inductor\ \rightarrow90^{\circ} $$ 

 $$ \mathrm{C a p a c i t o r}\to90^{\circ} $$ 

Remember:

V and I are in phase in a pure resistor', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.149Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6274, 4, NULL, NULL, 'Two coils have mutual inductance 0.5H. If the current in the primary coil changes at the rate of  $ 4A s^{-1} $, the induced emf in the secondary coil is', NULL, '[{"text":"0.5V","image_url":null,"alt":null},{"text":"1V","image_url":null,"alt":null},{"text":"2V","image_url":null,"alt":null},{"text":"4V","image_url":null,"alt":null}]', NULL, 2, 'Step 1: Recall the formula for induced emf due to mutual inductance.

 $$ e=M\frac{dI}{dt} $$ 

where

 $$ M=0.5H $$ 

and

 $$ \frac{d I}{d t}=4\mathrm{A}\;s^{-1} $$ 

Step 2: Substitute the values.

 $$ e=0.5\times4 $$ 

 $$ e=2\mathrm{V} $$ 

Step 3: Choose the correct option.

 $$ e=2\mathrm{V} $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q03-exp-1.jpg" alt="Figure 1 for question 3" /></div>


is the correct answer.

Quick Tip: For mutual induction:

 $$ e=M\frac{dI}{dt} $$ 

Larger mutual inductance or faster current change produces greater induced emf.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.150Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6275, 4, NULL, NULL, 'Match the electromagnetic waves in Column I with their common applications in Column II.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">Column I</td><td colspan="2">Column II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A)</td><td style=''text-align: center; word-wrap: break-word;''>Gamma rays</td><td style=''text-align: center; word-wrap: break-word;''>(I)</td><td style=''text-align: center; word-wrap: break-word;''>Radar communication</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B)</td><td style=''text-align: center; word-wrap: break-word;''>X-rays</td><td style=''text-align: center; word-wrap: break-word;''>(II)</td><td style=''text-align: center; word-wrap: break-word;''>Cancer treatment</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C)</td><td style=''text-align: center; word-wrap: break-word;''>Microwaves</td><td style=''text-align: center; word-wrap: break-word;''>(III)</td><td style=''text-align: center; word-wrap: break-word;''>Bone imaging</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D)</td><td style=''text-align: center; word-wrap: break-word;''>Radio waves</td><td style=''text-align: center; word-wrap: break-word;''>(IV)</td><td style=''text-align: center; word-wrap: break-word;''>Broadcasting</td></tr></table>


Choose the correct answer from the options given below:', NULL, '[{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null},{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null},{"text":"A-III, B-II, C-IV, D-I","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall applications of EM waves.

Gamma rays  $ \rightarrow $ Cancer treatment

X-rays  $ \rightarrow $ Bone imaging

Microwaves  $ \rightarrow $ Radar communication

Radio waves  $ \rightarrow $ Broadcasting

Step 2: Match the columns.

 $$ A\to\mathbb{I} $$ 

 $$ B\to III $$ 

 $$ C\to I $$ 

 $$ D\to IV $$ 

Step 3: Identify the correct option.

 $$ \left|A-I I,B-I I I,C-I,D-I V\right| $$ 

Therefore,

is the correct answer.

Quick Tip: Important EM Wave Applications:

Radio Waves  $ \rightarrow $ Broadcasting

Microwaves  $ \rightarrow $ Radar

X-rays  $ \rightarrow $ Medical Imaging

Gamma Rays  $ \rightarrow $ Cancer Therapy', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.150Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6276, 4, NULL, NULL, 'According to Bohr’s atomic model, the angular momentum of an electron in the  $ n^{\mathrm{th}} $ orbit is', NULL, '[{"text":"$ \\frac{nh}{2\\pi} $","image_url":null,"alt":null},{"text":"$ \\frac{h}{2\\pi n} $","image_url":null,"alt":null},{"text":"$ \\frac{n^{2}h}{2\\pi} $","image_url":null,"alt":null},{"text":"$ \\frac{h}{n} $","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall Bohr''s quantization condition.

According to Bohr,

 $$ mvr=\frac{nh}{2\pi} $$ 

where

 $$ n=1,2,3,\cdots $$ 

Step 2: Identify the angular momentum.

Angular momentum of the electron is:

 $$ L=m\nu r $$ 

Hence,

 $$ L=\frac{nh}{2\pi} $$ 

Step 3: Choose the correct option.

 $$ \boxed{L=\frac{n h}{2\pi}} $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q05-exp-1.jpg" alt="Figure 1 for question 5" /></div>


is the correct answer.

Quick Tip: Bohr''s most important postulate:

 $$ m\nu r=\frac{nh}{2\pi} $$ 

For the first orbit:

 $$ L=\frac{h}{2\pi} $$ 

This is a frequently asked CUET question.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.151Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6277, 4, NULL, NULL, 'A photon has energy 6eV. The corresponding work function of a metal is 2eV. The maximum kinetic energy of the emitted photoelectron is', NULL, '[{"text":"2eV","image_url":null,"alt":null},{"text":"4eV","image_url":null,"alt":null},{"text":"6eV","image_url":null,"alt":null},{"text":"8eV","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall Einstein''s photoelectric equation.

 $$ K_{\mathrm{m a x}}=h\nu-\phi $$ 

where

 $$ h\nu=6\mathrm{e V} $$ 

and

 $$ \phi=2\mathrm{e V} $$ 

Step 2: Substitute the values.

 $$ K_{max}=6-2 $$ 

 $$ K_{\mathrm{max}}=4\mathrm{eV} $$ 

Step 3: Identify the correct option.

 $$ K_{\mathrm{m a x}}=4\mathrm{e V} $$ 

Therefore,

 $$ \boxed{\mathrm{(B)}} $$ 

is the correct answer.

Quick Tip: Photoelectric equation:

 $$ K_{\mathrm{m a x}}=h\nu-\phi $$ 

where

 $$ \phi=\mathrm{Work~Function} $$ 

and

 $ h\nu = \text{Photon Energy} $

Remember:

Photon Energy = Work Function + Kinetic Energy', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.152Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6278, 4, NULL, NULL, 'A long straight conductor carries a current of 10A. The magnetic field at a point 20cm away from the conductor is  $ (\mu_{0}=4\pi\times10^{-7}\mathrm{T}\mathrm{mA}^{-1}) $', NULL, '[{"text":"$ 1 \\times 10^{-5} $ T","image_url":null,"alt":null},{"text":"$ 2 \\times 10^{-5} $ T","image_url":null,"alt":null},{"text":"$ 5 \\times 10^{-6} $ T","image_url":null,"alt":null},{"text":"$ 4 \\times 10^{-5} $ T","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall the magnetic field due to a long straight conductor.

 $$ B=\frac{\mu_{0}I}{2\pi r} $$ 

Given:

 $$ I=10A $$ 

 $$ r=20cm=0.2m $$ 

Step 2: Substitute the values.

 $$ B=\frac{(4\pi\times10^{-7})(10)}{2\pi(0.2)} $$ 

 $$ B=\frac{4\times10^{-6}}{0.4} $$ 

 $$ B=1\times10^{-5}T $$ 

Step 3: Identify the correct option.

 $$ B=1\times10^{-5}\mathrm{T} $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q07-exp-1.jpg" alt="Figure 1 for question 7" /></div>


is the correct answer.

Quick Tip: Magnetic field due to a long straight wire:

 $$ B=\frac{\mu_{0}I}{2\pi r} $$ 

Important observations:

 $$ \boldsymbol{B}\propto\boldsymbol{I} $$ 

 $$ B\propto\frac{1}{r} $$ 

Doubling the distance halves the magnetic field.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.152Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6279, 4, NULL, NULL, 'An object is placed 30 cm in front of a concave mirror of focal length 20 cm. The image distance is', NULL, '[{"text":"-60 cm","image_url":null,"alt":null},{"text":"+60 cm","image_url":null,"alt":null},{"text":"+30 cm","image_url":null,"alt":null},{"text":"-30 cm","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Use the mirror formula.

 $$ \frac{1}{f}=\frac{1}{\nu}+\frac{1}{u} $$ 

For a concave mirror:

 $$ f=-20\mathrm{c m} $$ 

 $$ u=-30\mathrm{c m} $$ 

Step 2: Substitute the values.

 $$ \frac{1}{-20}=\frac{1}{\nu}+\frac{1}{-30} $$ 

 $$ \frac{1}{v}=-\frac{1}{20}+\frac{1}{30} $$ 

 $$ \frac{1}{v}=-\frac{3}{60}+\frac{2}{60} $$ 

 $$ \frac{1}{v}=-\frac{1}{60} $$ 

 $$ \nu=-60\mathrm{c m} $$ 

Step 3: Identify the correct option.

 $$ \lceil\nu=-60\mathrm{c m}\rceil $$ 

The negative sign indicates that the image is real and formed in front of the mirror.

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


is the correct answer.

Quick Tip: Mirror formula:

 $$ \left|\frac{1}{f}=\frac{1}{\nu}+\frac{1}{u}\right. $$ 

For a concave mirror:

 $$ f<0 $$ 

Real image:

 $$ \nu<0 $$ 

Virtual image:

 $$ \nu>0 $$ 

Always follow the New Cartesian Sign Convention.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.153Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6280, 4, NULL, NULL, 'In a semiconductor, the conductivity increases with increase in temperature because', NULL, '[{"text":"Resistance increases","image_url":null,"alt":null},{"text":"Number of free charge carriers increases","image_url":null,"alt":null},{"text":"Mobility becomes zero","image_url":null,"alt":null},{"text":"Band gap increases","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the behavior of semiconductors.

Semiconductors have a small energy band gap.

At room temperature, only a limited number of electrons are available for conduction.

##### Step 2: Understand the effect of temperature.

When temperature increases, more electrons gain sufficient energy to jump from the valence band to the conduction band.

Thus:

Number of electrons  $ \uparrow $

### Number of holes  $ \uparrow $

#### Step 3: Determine the effect on conductivity.

Since conductivity depends on the number of charge carriers,

 $$ \sigma\propto n $$ 

an increase in charge carriers increases conductivity.

Therefore,

Number of free charge carriers increases

Hence, the correct answer is:

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-30-shift-1/q09-exp-1.jpg" alt="Figure 1 for question 9" /></div>


##### Quick Tip: For semiconductors:

Temperature  $ \uparrow\Rightarrow $ Conductivity  $ \uparrow $

This is opposite to metals where:

Temperature  $ \uparrow\Rightarrow $ Resistance  $ \uparrow $

CUET frequently asks this comparison.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.153Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6281, 4, NULL, NULL, 'Two capacitors of capacitances  $ 6\mu F $ and  $ 3\mu F $ are connected in series across a battery. The equivalent capacitance of the combination is', NULL, '[{"text":"$ 9 \\mu F $","image_url":null,"alt":null},{"text":"$ 2 \\mu F $","image_url":null,"alt":null},{"text":"$ 4.5 \\mu F $","image_url":null,"alt":null},{"text":"$ 18 \\mu F $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the formula for capacitors in series.

 $$ \frac{1}{C_{\mathrm{eq}}}=\frac{1}{C_{1}}+\frac{1}{C_{2}} $$ 

Given:

 $$ C_{1}=6\mu F $$ 

 $$ C_{2}=3\mu F $$ 

Step 2: Substitute the values.

 $$ \frac{1}{C_{eq}}=\frac{1}{6}+\frac{1}{3} $$ 

 $$ \frac{1}{C_{eq}}=\frac{1}{6}+\frac{2}{6} $$ 

 $$ \frac{1}{C_{eq}}=\frac{3}{6}=\frac{1}{2} $$ 

 $$ C_{eq}=2\mu F $$ 

Step 3: Identify the correct option.

 $$ C_{\mathrm{e q}}=2\mu F $$ 

Therefore,

(B)

is the correct answer.

##### Quick Tip: Capacitors in series:

 $$ \frac{1}{C_{eq}}=\frac{1}{C_{1}}+\frac{1}{C_{2}} $$ 

Capacitors in parallel:

 $$ C_{\mathrm{e q}}=C_{1}+C_{2} $$ 

Remember:

Series  $ \Rightarrow $ Capacitance decreases

Parallel  $ \Rightarrow $ Capacitance increases', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.154Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6282, 4, NULL, NULL, 'Two charges +4μC and +9μC are separated by a distance of 3 m in vacuum. The electrostatic force between them is  $ (k=9\times10^{9} N m^{2}C^{-2}) $', NULL, '[{"text":"0.018N","image_url":null,"alt":null},{"text":"0.036N","image_url":null,"alt":null},{"text":"0.054N","image_url":null,"alt":null},{"text":"0.072N","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall Coulomb''s law.

 $$ F=\frac{k q_{1}q_{2}}{r^{2}} $$ 

Given:

 $$ q_{1}=4\times10^{-6}C $$ 

 $$ q_{2}=9\times10^{-6}C $$ 

 $$ r=3m $$ 

Step 2: Substitute the values.

 $$ F=\frac{(9\times10^{9})(4\times10^{-6})(9\times10^{-6})}{3^{2}} $$ 

 $$ F=\frac{9\times36\times10^{-3}}{9} $$ 

 $$ F=36\times10^{-3} $$ 

 $$ F=0.036N $$ 

Step 3: Choose the correct option.

 $$ F=0.036N $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q01-exp-1.jpg" alt="Figure 1 for question 1" /></div>


is the correct answer.

##### Quick Tip: Coulomb''s Law:

 $$ F=\frac{k q_{1}q_{2}}{r^{2}} $$ 

Important:

 $$ F\propto q_{1}q_{2} $$ 

 $$ F\propto\frac{1}{r^{2}} $$ 

Doubling distance reduces force by a factor of 4.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.156Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6283, 4, NULL, NULL, 'Given below are two statements:

Assertion (A): In a pure inductive AC circuit, current lags voltage by  $ 90^{\circ} $.

Reason (R): An inductor opposes the change in current flowing through it.

Choose the correct answer from the options given below:', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true but R is not the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Examine the Assertion.

For a pure inductor:

 $$ V=L\frac{dI}{dt} $$ 

Current lags behind voltage by:

 $$ 90^{\circ} $$ 

Hence,

Assertion (A) is True

Step 2: Examine the Reason.

An inductor produces self-induced emf which opposes any change in current.

Reason (R) is True

#### Step 3: Determine the relationship.

Because the inductor opposes change in current, the current cannot rise instantly and hence lags the voltage.

Thus, Reason correctly explains Assertion.

Therefore,

Both A and R are true and R is the correct explanation of A

Hence,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q02-exp-1.jpg" alt="Figure 1 for question 2" /></div>


is the correct answer.

Quick Tip: Phase Difference in AC Circuits:  $ \boxed{Resistor \rightarrow 0^{\circ}} $  $ \boxed{Inductor \rightarrow 90^{\circ}} $  $ \boxed{Capacitor \rightarrow 90^{\circ}} $

Remember:  $ \boxed{Current\ lags\ in\ Inductor} $  $ \boxed{Current\ leads\ in\ Capacitor} $', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.157Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6284, 4, NULL, NULL, 'A resistor of resistance  $ 20\Omega $ is connected across a 10V battery. The current flowing through the resistor is', NULL, '[{"text":"$ 0.2A $","image_url":null,"alt":null},{"text":"$ 0.5A $","image_url":null,"alt":null},{"text":"$ 2A $","image_url":null,"alt":null},{"text":"$ 5A $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall Ohm''s Law.

 $$ V=I R $$ 

Therefore,

 $$ I=\frac{V}{R} $$ 

Step 2: Substitute the given values.

 $$ I=\frac{10}{20} $$ 

 $$ I=0.5A $$ 

Step 3: Identify the correct option.

 $$ \boxed{I=0.5A} $$ 

Therefore,

 $$ \boxed{\mathrm{(B)}} $$ 

is the correct answer.

##### Quick Tip: Ohm''s Law:

 $$ \boxed{V=I R} $$ 

Useful forms:

 $$ \boxed{I=\frac{V}{R}} $$ 

 $$ \boxed{R=\frac{V}{I}} $$ 

One of the most important formulas in Current Electricity.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.157Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6285, 4, NULL, NULL, 'Match the semiconductor devices in Column I with their functions in Column II.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">Column I</td><td colspan="2">Column II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A)</td><td style=''text-align: center; word-wrap: break-word;''>LED</td><td style=''text-align: center; word-wrap: break-word;''>(I)</td><td style=''text-align: center; word-wrap: break-word;''>Voltage Regulation</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B)</td><td style=''text-align: center; word-wrap: break-word;''>Zener Diode</td><td style=''text-align: center; word-wrap: break-word;''>(II)</td><td style=''text-align: center; word-wrap: break-word;''>Light Emission</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C)</td><td style=''text-align: center; word-wrap: break-word;''>Photodiode</td><td style=''text-align: center; word-wrap: break-word;''>(III)</td><td style=''text-align: center; word-wrap: break-word;''>Light Detection</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D)</td><td style=''text-align: center; word-wrap: break-word;''>Solar Cell</td><td style=''text-align: center; word-wrap: break-word;''>(IV)</td><td style=''text-align: center; word-wrap: break-word;''>Converts Solar Energy into Electrical Energy</td></tr></table>


Choose the correct answer from the options given below:', NULL, '[{"text":"A-II, B-I, C-III, D-IV","image_url":null,"alt":null},{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-III, B-I, C-II, D-IV","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall the functions of semiconductor devices.

LED  $ \rightarrow $ Light Emission

Zener Diode  $ \rightarrow $ Voltage Regulation

Photodiode  $ \rightarrow $ Light Detection

Solar Cell  $ \rightarrow $ Converts Solar Energy into Electrical Energy

Step 2: Match the columns.

 $ A \rightarrow II $

 $ B \rightarrow I $

C  $ \rightarrow $ III

 $ D \rightarrow IV $

Step 3: Choose the correct option.

 $$ \left|\begin{array}{c}A-II,B-I,C-III,D-IV\end{array}\right. $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q04-exp-1.jpg" alt="Figure 1 for question 4" /></div>


is the correct answer.

Quick Tip: Important Semiconductor Devices:

LED  $ \rightarrow $ Light Emitting Diode

Zener Diode  $ \rightarrow $ Voltage Regulator

Photodiode  $ \rightarrow $ Light Sensor

Solar Cell  $ \rightarrow $ Photovoltaic Device', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.160Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6286, 4, NULL, NULL, 'The energy of an electron in the first Bohr orbit of hydrogen atom is -13.6eV. The energy

of the electron in the third orbit is', NULL, '[{"text":"$ -1.51\\,eV $","image_url":null,"alt":null},{"text":"$ -3.4\\,eV $","image_url":null,"alt":null},{"text":"$ -13.6\\,eV $","image_url":null,"alt":null},{"text":"$ -0.85\\,eV $","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall Bohr''s energy formula.

 $$ E_{n}=\frac{-13.6}{n^{2}}\,eV $$ 

For the third orbit: n=3

Step 2: Substitute the value of n.

 $$ E_{3}=\frac{-13.6}{3^{2}} $$ 

 $$ E_{3}=\frac{-13.6}{9} $$ 

 $$ E_{3}=-1.51e V $$ 

Step 3: Choose the correct option.

 $$ \left|\begin{array}{c}E_{3}=-1.51eV\end{array}\right| $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q05-exp-1.jpg" alt="Figure 1 for question 5" /></div>


is the correct answer.

Quick Tip: Bohr Energy Formula:

 $$ \left|E_{n}=\frac{-13.6}{n^{2}}e V\right| $$ 

For hydrogen atom:

 $$ E_{1}=-13.6eV $$ 

 $$ E_{2}=-3.4eV $$ 

 $$ E_{3}=-1.51e V $$ 

Frequently asked CUET numerical.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.162Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6287, 4, NULL, NULL, 'Given below are two statements:

Assertion (A): Electromagnetic waves can travel through vacuum.

Reason (R): Electromagnetic waves consist of oscillating electric and magnetic fields.

Choose the correct answer from the options given below:', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true but R is not the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Examine the Assertion.

Electromagnetic waves do not require any material medium for propagation.

Hence they can travel through vacuum.

Assertion (A) is True

#### Step 2: Examine the Reason.

EM waves are produced by mutually perpendicular oscillating electric and magnetic fields.

Reason (R) is True

#### Step 3: Determine the relationship.

The changing electric field produces magnetic field and vice versa.

Therefore EM waves are self-propagating and do not require a medium.

Thus Reason correctly explains Assertion.

Hence,

Both A and R are true and R is the correct explanation of A

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q06-exp-1.jpg" alt="Figure 1 for question 6" /></div>


is the correct answer.

#### Quick Tip: Properties of Electromagnetic Waves:

Do not require a medium

Travel with speed  $ c = 3 \times 10^{8} \, m/s $

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q06-exp-2.jpg" alt="Figure 2 for question 6" /></div>


 $ E \perp $ Direction of Propagation', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.163Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6288, 4, NULL, NULL, 'A convex lens has a focal length of 20 cm. An object is placed 30 cm from the lens. The image distance is', NULL, '[{"text":"60 cm","image_url":null,"alt":null},{"text":"30 cm","image_url":null,"alt":null},{"text":"20 cm","image_url":null,"alt":null},{"text":"15 cm","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall the lens formula.

 $$ \frac{1}{f}=\frac{1}{v}-\frac{1}{u} $$ 

Given:

 $$ f=+20c m $$ 

 $$ u=-30c m $$ 

Step 2: Substitute the values.

 $$ \frac{1}{20}=\frac{1}{\nu}+\frac{1}{30} $$ 

 $$ \frac{1}{v}=\frac{1}{20}-\frac{1}{30} $$ 

 $$ \frac{1}{\nu}=\frac{3-2}{60}=\frac{1}{60} $$ 

 $$ \nu=60c m $$ 

Step 3: Choose the correct option.

 $$ \nu=60c m $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q07-exp-1.jpg" alt="Figure 1 for question 7" /></div>


is the correct answer.

Quick Tip: Lens Formula:

 $$ \left|\frac{1}{f}=\frac{1}{\nu}-\frac{1}{u}\right. $$ 

For a convex lens:

 $$ f>0 $$ 

Always use the Cartesian sign convention.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.164Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6289, 4, NULL, NULL, 'Match the following electromagnetic waves with their applications.




<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">Column I</td><td colspan="2">Column II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(A)</td><td style=''text-align: center; word-wrap: break-word;''>Gamma Rays</td><td style=''text-align: center; word-wrap: break-word;''>(I)</td><td style=''text-align: center; word-wrap: break-word;''>Radar Communication</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(B)</td><td style=''text-align: center; word-wrap: break-word;''>X-rays</td><td style=''text-align: center; word-wrap: break-word;''>(II)</td><td style=''text-align: center; word-wrap: break-word;''>Cancer Treatment</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(C)</td><td style=''text-align: center; word-wrap: break-word;''>Microwaves</td><td style=''text-align: center; word-wrap: break-word;''>(III)</td><td style=''text-align: center; word-wrap: break-word;''>Medical Imaging</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>(D)</td><td style=''text-align: center; word-wrap: break-word;''>Radio Waves</td><td style=''text-align: center; word-wrap: break-word;''>(IV)</td><td style=''text-align: center; word-wrap: break-word;''>Broadcasting</td></tr></table>


Choose the correct answer from the options given below:', NULL, '[{"text":"A-II, B-III, C-I, D-IV","image_url":null,"alt":null},{"text":"A-I, B-II, C-IV, D-III","image_url":null,"alt":null},{"text":"A-II, B-IV, C-I, D-III","image_url":null,"alt":null},{"text":"A-III, B-II, C-IV, D-I","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Recall common applications of EM waves.

Gamma Rays  $ \rightarrow $ Cancer Treatment

X-rays  $ \rightarrow $ Medical Imaging

Microwaves  $ \rightarrow $ Radar Communication

Radio Waves  $ \rightarrow $ Broadcasting

Step 2: Match the columns.

 $ A \to II $

B  $ \rightarrow $ III

 $ C \to I $

 $ D \rightarrow IV $

Step 3: Choose the correct option.

 $$ \left|\begin{array}{c}A-II,B-III,C-I,D-IV\end{array}\right. $$ 

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


is the correct answer.

