INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6290, 4, NULL, NULL, 'A photon of wavelength 500 nm is incident on a metal surface. The energy of the photon is approximately  $ h = 6.63 \times 10^{-34} \, J \, s $,  $ c = 3 \times 10^8 \, m/s $', NULL, '[{"text":"$ 1.99 \\times 10^{-19} J $","image_url":null,"alt":null},{"text":"$ 3.98 \\times 10^{-19} J $","image_url":null,"alt":null},{"text":"$ 5.97 \\times 10^{-19} J $","image_url":null,"alt":null},{"text":"$ 7.96 \\times 10^{-19} J $","image_url":null,"alt":null}]', NULL, 1, 'Step 1: Recall the photon energy relation.

 $$ E=\frac{h c}{\lambda} $$ 

Given:

 $$ h=6.63\times10^{-34}J s $$ 

 $$ c=3\times10^{8}m/s $$ 

 $$ \lambda=500\times10^{-9}m $$ 

Step 2: Substitute the values.

 $$ E=\frac{(6.63\times10^{-34})(3\times10^{8})}{500\times10^{-9}} $$ 

 $$ E=\frac{19.89\times10^{-26}}{5\times10^{-7}} $$ 

 $$ E=3.98\times10^{-19}J $$ 

Step 3: Choose the correct option.

 $$ E=3.98\times10^{-19}J $$ 

Therefore,

 $$ \left|\mathrm{(B)}\right. $$ 

is the correct answer.

Quick Tip: Photon Energy:

 $$ E=\frac{h c}{\lambda} $$ 

Useful shortcut:

 $$ E(eV)=\frac{1240}{\lambda(nm)} $$ 

For shorter wavelength:

Higher Energy', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.165Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6291, 4, NULL, NULL, 'Given below are two statements:

Assertion (A): In a nuclear reactor, control rods are used to control the rate of fission reaction.

Reason (R): Control rods absorb excess neutrons produced during fission.

Choose the correct answer from the options given below:', NULL, '[{"text":"Both A and R are true and R is the correct explanation of A","image_url":null,"alt":null},{"text":"Both A and R are true but R is not the correct explanation of A","image_url":null,"alt":null},{"text":"A is true but R is false","image_url":null,"alt":null},{"text":"A is false but R is true","image_url":null,"alt":null}]', NULL, 0, 'Step 1: Examine the Assertion.

Control rods are inserted into the reactor core to regulate the chain reaction.

Assertion (A) is True

Step 2: Examine the Reason.

Control rods made of cadmium or boron absorb excess neutrons.

Reason (R) is True

#### Step 3: Determine the relationship.

Since neutrons are responsible for sustaining the chain reaction, absorbing excess neutrons controls the rate of fission.

Thus Reason correctly explains Assertion.

Hence,

Both A and R are true and R is the correct explanation of A

Therefore,

<div style="text-align: center;"><img src="/local-papers/assets/physics-2026-05-31-shift-2/q10-exp-1.jpg" alt="Figure 1 for question 10" /></div>


is the correct answer.

##### Quick Tip: Components of a Nuclear Reactor:

Fuel  $ \rightarrow U^{235} $

Moderator  $ \rightarrow $ Slows Neutrons

Control Rods  $ \rightarrow $ Absorb Neutrons

Coolant  $ \rightarrow $ Removes Heat

A very important CUET Physics topic.', NULL, NULL, 2026, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.165Z', NULL, NULL, '[]', 'ai_draft', 'unreviewed', NULL, NULL);
