Calculate Goodwill on the basis of 3 years purchase of weighted average profits of last five years based on weights 1, 2, 3, 4 and 5 respectively.', NULL, '[{"text":"₹68,200","image_url":null,"alt":null},{"text":"₹69,600","image_url":null,"alt":null},{"text":"₹64,800","image_url":null,"alt":null},{"text":"₹66,000","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.234Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6399, 8, NULL, NULL, 'Consider the following facts about the categories of Share Capital

A. Nominal Capital is that part of Authorised Capital which is actually issued to the public

B. Issue Capital is a part of Registered Capital.

C. Subscribed Capital can be further categorised into fully paid-up and not fully paid up

D. Reserve Capital is a profit of capital nature

E. Called up Capital is that part of subscribed capital which company has asked the shareholders to pay

Choose the correct answer from the options given below:', NULL, '[{"text":"A, B and D only","image_url":null,"alt":null},{"text":"B, C and E only","image_url":null,"alt":null},{"text":"C, D and E only","image_url":null,"alt":null},{"text":"A, B and C only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.235Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6400, 8, NULL, NULL, 'This formula would result in TRUE if C4 is less than 10 and D4 is less than 100.', NULL, '[{"text":"= AND (C4 > 10, D4 > 10)","image_url":null,"alt":null},{"text":"= AND (C4 > 10, D4 > 100)","image_url":null,"alt":null},{"text":"= AND (C4 > 10, D4 = 100)","image_url":null,"alt":null},{"text":"= AND (C4 > 10, D4 < 100)","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:47.235Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
