INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6709, 8, NULL, NULL, 'Dissolution of a partnership firm may be ordered by the court on the following grounds:

(A) when a partner becomes insane.

(B) when a partner becomes permanently incapable of performing his duties as partner.

(C) when a partner acts in good faith

(D) when it is regarded just and equitable by the court.

Choose the correct answer from the options given below:

1. (A) and (D) only

2. (A), (B) and (D) only

3. (D) only

4. (A), (B), (C) and (D)', NULL, '[{"text":"(A) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(D) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.654Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
