INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6723, 8, NULL, NULL, 'Which of the following is not the feature of partnership -

1. There should be at least two persons coming together for a common goal.

2. Partnership is the result of an agreement between two or more persons to do business and share its profits only.

3. The business of a partnership concern may be carried on by all the partners or any of them acting for all.

4. The business profits and losses are shared by all the partners as per profit sharing ratio', NULL, '[{"text":"There should be at least two persons coming together for a common goal","image_url":null,"alt":null},{"text":"Partnership is the result of an agreement between two or more persons to do business and share its profits only","image_url":null,"alt":null},{"text":"The business of a partnership concern may be carried on by all the partners or any of them acting for all","image_url":null,"alt":null},{"text":"The business profits and losses are shared by all the partners as per profit sharing ratio","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.664Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6724, 8, NULL, NULL, 'At the time of admission of a new partner, in case there is no workmen''s compensation claim, the total amount of workmen''s compensation fund will be :-', NULL, '[{"text":"Credited to old partners'' capital account in their old profit sharing ratio","image_url":null,"alt":null},{"text":"Debited to old partners'' capital account in their old profit sharing ratio","image_url":null,"alt":null},{"text":"Credited to old partners'' capital account in their new profit sharing ratio","image_url":null,"alt":null},{"text":"Debited to old partners'' capital account in their new profit sharing ratio","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.665Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6725, 8, NULL, NULL, 'Calculate interest on drawing if Ram withdrew Rs. 3,000 per month at the beginning of each month for the whole year, if interest on drawing is charged @ 9% per annum.

