INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6726, 8, NULL, NULL, 'Hem and Nem are partners in a firm sharing profits in the ratio of 3:2. Their capitals were Rs. 80,000 and Rs. 50,000 respectively. They admitted Sam on Jan. 1, 2017 as a new partner for 1/5 share in the future profits. Sam brought Rs. 60,000 as his capital. Calculate the value of the goodwill of the firm if Sam brings his share of goodwill in Cash:', NULL, '[{"text":"Rs. 82,000","image_url":null,"alt":null},{"text":"Rs. 62,000","image_url":null,"alt":null},{"text":"Rs. 22,000","image_url":null,"alt":null},{"text":"Rs 32,000","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.665Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6727, 8, NULL, NULL, 'The Profit and Loss Appropriation Account is merely an extension of the Profit and Loss Account of the firm, which, among the

following, is not shown in the Profit and Loss Appropriation Account?', NULL, '[{"text":"All adjustments in respect of partner''s salary","image_url":null,"alt":null},{"text":"All adjustments in respect of payment to Vendor","image_url":null,"alt":null},{"text":"All adjustments in respect of interest on capital","image_url":null,"alt":null},{"text":"All adjustments in respect of interest on drawings","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.666Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6728, 8, NULL, NULL, 'The following are the features of the Dissolution of Partnership:

(A) Assets and liabilities are revalued, and a new balance sheet is drawn.

(B) Economic relationships between partners continue, though in a changed form.

(C) The business is not terminated.

(D) The books of account are closed.

Choose the correct answer from the options given below:', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.666Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6729, 8, NULL, NULL, 'The following are the features of Debenture:

(A) Debentures can be converted into shares if the terms of issue are so provided, and in that case these are known as convertible debentures.

(B) Debentures are generally secured and carry a fixed or floating charge over the assets of the company.

(C) The rate of interest on debentures may vary from year to year depending upon the profits of the company.

(D) The debentures are issued for a specified period and repayable on the expiry of that period.

Choose the correct answer from the options given below:', NULL, '[{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.667Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6730, 8, NULL, NULL, 'Which among the following is NOT true?

1. Valid partnership can be formulated even without a written agreement between the partners.

2. Each partner carrying on the business is the principal as well as he agent for all the other partners.

3. The agreement may carry or not on any business. Mere co-ownership of a property can amount to partnership.

4. Persons who have entered into partnership with one another are individually called ''partners'' and collectively called ''firm''.', NULL, '[{"text":"Valid partnership can be formulated even without a written agreement between the partners","image_url":null,"alt":null},{"text":"Each partner carrying on the business is the principal as well as he agent for all the other partners","image_url":null,"alt":null},{"text":"The agreement may carry or not on any business. Mere co-ownership of a property can amount to partnership","image_url":null,"alt":null},{"text":"Persons who have entered into partnership with one another are individually called ''partners'' and collectively called ''firm''","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.667Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6731, 8, NULL, NULL, 'Identify the type of Share Capital, which is clearly shown in Notes to Accounts, but not included in the total of Notes to Account under SHARE CAPITAL head', NULL, '[{"text":"Subscribed and fully paid up Share Capital","image_url":null,"alt":null},{"text":"Subscribed but not fully paid up Share Capital","image_url":null,"alt":null},{"text":"Issued Share Capital and Un-issued Share Capital","image_url":null,"alt":null},{"text":"Registered Share Capital and Issued Share Capital","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.668Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6732, 8, NULL, NULL, 'Which among the following is NOT true for New Profit Sharing Ratio:

1. How much of the share of profit for the new partner and how he will acquire it from the existing partners is decided mutually between the old partners and the new partner.

2. If nothing is specified as to how the new partner acquires his share from the old partners, it may be assumed that he gets it from them in their profit sharing ratio.

3. The new partner acquires his share from the old partners only according to their respective contribution, no any other way can be possible for profit sharing at any condition.

4. On admission of a new partner, the profit sharing ratio among the old partners will change, keeping in view their respective contribution to the profit sharing ratio of the incoming partner.', NULL, '[{"text":"How much of the share of profit for the new partner and how he will acquire it from the existing partners is decided mutually between the old partners and the new partner","image_url":null,"alt":null},{"text":"If nothing is specified as to how the new partner acquires his share from the old partners, it may be assumed that he gets it from them in their profit sharing ratio","image_url":null,"alt":null},{"text":"The new partner acquires his share from the old partners only according to their respective contribution, no any other way can be possible for profit sharing at any condition","image_url":null,"alt":null},{"text":"On admission of a new partner, the profit sharing ratio among the old partners will change, keeping in view their respective contribution to the profit sharing ratio of the incoming partner","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.668Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6733, 8, NULL, NULL, 'At the time of the Dissolution of a Partnership Firm, which statement is not false :-

