INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6741, 9, NULL, NULL, 'A manager should not fall into the temptations of misusing her/his powers for individual/family benefit at the cost of larger general interest of the workers/company.

The relevant principle of management is -', NULL, '[{"text":"Subordination of individual interest to general interest","image_url":null,"alt":null},{"text":"Discipline","image_url":null,"alt":null},{"text":"Unity of Direction","image_url":null,"alt":null},{"text":"Initiative","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, '/local-papers/assets/business-studies-2022/page-5-asset-p005-fig01.png', 'image for question 3', NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.673Z', NULL, NULL, '[{"url":"/local-papers/assets/business-studies-2022/page-5-asset-p005-fig01.png","alt":"image for question 3","kind":"image"}]', 'none', 'unreviewed', NULL, NULL);
