<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Dimension of Business Environment</td><td style=''text-align: center; word-wrap: break-word;''>Component</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>A. Economic</td><td style=''text-align: center; word-wrap: break-word;''>I. Festivals</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>B. Social</td><td style=''text-align: center; word-wrap: break-word;''>II. Court Judgements</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C. Political</td><td style=''text-align: center; word-wrap: break-word;''>III. Public Debt</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>D. Legal</td><td style=''text-align: center; word-wrap: break-word;''>IV. Ideology of ruling party</td></tr></table>', NULL, '[{"text":"A-II, B-I, C-IV, D-III","image_url":null,"alt":null},{"text":"A-III, B-I, C-IV, D-II","image_url":null,"alt":null},{"text":"A-IV, B-III, C-II, D-I","image_url":null,"alt":null},{"text":"A-III, B-II, C-IV, D-II","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.674Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
