INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6747, 9, NULL, NULL, 'If there is a plan to increase production then more labour and more machinery will be required. This step would also involve organizing for labour and purchase of machinery. Identify this step in the process of planning.', NULL, '[{"text":"Follow up action","image_url":null,"alt":null},{"text":"Implementing the plan","image_url":null,"alt":null},{"text":"Evaluating alternative courses","image_url":null,"alt":null},{"text":"Developing premises","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.677Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
