INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6749, 9, NULL, NULL, 'Amrit Lala, MD of Awasthi Ltd. retired after 33 years of service. The responsibility was given to Amit. Amit realized that there was a lot of rivalry, confusion and misunderstanding among departmental heads. He detected inefficiencies, took corrective action and developed a master plan for the organisation to follow. This served as basis for coordinating the activities of all the departments, led to clarity of thought and action and the work got a smooth start.

