INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6849, 9, NULL, NULL, 'Employees learn their jobs on the equipment they will be using, but the training is conducted away from the actual work place.

Name the training method, explained here.', NULL, '[{"text":"Case study","image_url":null,"alt":null},{"text":"Programmed instructions","image_url":null,"alt":null},{"text":"Vestibule training","image_url":null,"alt":null},{"text":"Internship training ## Direction for the question 41 to 45: Read the following passage and answer question Directing refers to the process of instructing, guiding, counselling, motivating and leading people in the organisation to achieve its objectives. Directing is a managerial process which takes place throughout the life of the organisation irrespective of people occupying managerial positions. In the organisation every individual effort contributes to the organisational performance. Thus, it ensures that the individual work for organisational goals. One of the principles of Directing emphasises that directing techniques must help every individual in the organisation to contribute to his maximum potential for achievement of organisational objectives. In the organisation different techniques are used to motivate people such as pay, bonus, promotion, recognitions, praise, responsibility etc. and also different financial incentives are used. Under one of such incentive schemes employees are offered company shares at a predetermined price which is lower than market price","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.761Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6850, 9, NULL, NULL, '"Directing takes place throughout the life of the organisation irrespective of people occupying managerial positions." Identify the feature of directing being reflected here.', NULL, '[{"text":"Directing takes place at every level of management","image_url":null,"alt":null},{"text":"Directing initiates action","image_url":null,"alt":null},{"text":"Directing flows from top to bottom","image_url":null,"alt":null},{"text":"Directing is a continuous process","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.762Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6851, 9, NULL, NULL, '''In the organisations every individual contributes to the organisational performance thus it ensures that the individual works for organisational goal." Identify the importance of directing.', NULL, '[{"text":"Directing initiate actions","image_url":null,"alt":null},{"text":"Directing integrates employees'' efforts","image_url":null,"alt":null},{"text":"Directing guides employees","image_url":null,"alt":null},{"text":"Directing facilitates introduction of changes","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.763Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
