INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6853, 9, NULL, NULL, 'Under which financial incentive schemes, employees are offered company''s shares at a predetermined price which is lower than market price?', NULL, '[{"text":"Retirement benefit","image_url":null,"alt":null},{"text":"Co-partnership","image_url":null,"alt":null},{"text":"Profit sharing","image_url":null,"alt":null},{"text":"Bonus ## Direction for the question 46 to 50: Read the following passage and answer question Mr. Avinash has joined as a vice President of a manufacturing unit manufacturing garments. As a vice president, he was given the responsibility of increasing the production and efficiency of workers. He observed that managers relied on their personal judgement while attending to the problems they confronted. So, he recommended work study which will result in saving time, effort and increasing efficiency. He also noticed that management was not honouring their commitment. He surveyed the market too. His study of the survey showed that demand can be increased through diversification. He decided to diversify into footwear and handbags. He created divisions for garments, footwear and handbags and made the divisional managers responsible for performance. Each division is self-contained with respect to various functions like production, purchases, finance, marketing etc. Now he decided to fill the various positions created with the right person. For this, he analysed the number and type of workers needed. He got his organisation registered at naukri.com","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2023, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.765Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
