INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6969, 9, NULL, NULL, 'The formal organisation can be better understood by a study of its features which are as follows :

(A) It specifies the relationships among various job positions and the nature of their inter-relationship. This clarifies who has to report to whom.

(B) It is a means to achieve the objectives specified in the plans, as it lays down rules and procedures essential for their achievement.

(C) Independent channels of communication without specified direction of flow of information are developed by group members.

(D) It is deliberately designed by the top management to facilitate the smooth functioning of the organisation.

Which of the following options are correct?', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.887Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6970, 9, NULL, NULL, 'The informal organisation offers many benefits. Important among them are given below :

(A) Prescribed lines of communication are not followed. Thus, informal organisation leads to faster spread of information as well as quick feedback.

(B) It helps to fulfil the social needs of the members and allows them to find like-minded people. This enhances their job satisfaction since it gives them a sense of belongingness in the organisation.

(C) It contributes towards fulfilment of organisational objectives by compensating for inadequacies in the formal organisation.

(D) Unity of command is maintained through an established chain of command.

Choose the correct answer from the options given below :', NULL, '[{"text":"(A), (B) and (D) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null},{"text":"(A), (B), (C) and (D)","image_url":null,"alt":null},{"text":"(B), (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:00:59.887Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
