to.....', NULL, '[{"text":"Inventory investment","image_url":null,"alt":null},{"text":"Fixed investment","image_url":null,"alt":null},{"text":"Gross investment","image_url":null,"alt":null},{"text":"Gross Domestic capital formation","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.056Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7169, 10, NULL, 131, 'Read the passage carefully and answer the questions based on the passage:

## Long Run Costs

In the long run, all inputs are variable. There are no fixed costs. The total cost and the total variable cost therefore, coincide in the long run. Long run marginal cost is the change in total cost per unit of change in output. Increasing returns to scale implies that if we increase all the inputs by a certain proportion, output increases by more than that proportion. Decreasing returns to scale implies that if we want to increase the output by a certain proportion, inputs need to be increased by more than that proportion. Constant returns to scale implies a proportional increase in inputs resulting in a proportional increase in output. So the average cost remains constant as

long as CRS operates. The RAC curve is a ''U''-shaped curve. Its downward sloping part corresponds to IRS and upward rising part corresponds to DRS. At the minimum point of the LRAC curve, CRS is observed. For the first unit of output, both LRMC and LRAC are the same. Then, as output increases, LRAC initially falls, and then, after a certain point, it rises. As long as average cost is falling, marginal cost must be less than the average cost. When the average cost is rising, marginal cost must be greater than the average cost. RMC cuts the LRAC curve from below at the minimum point of the LRAC.

In the long run when the average cost is rising, marginal cost must be.

1. Equal to average cost.

2. Less than the average cost.

3. Greater than the average cost.

4. Falling.

Options:

Answer: C', NULL, '[{"text":"Equal to average cost","image_url":null,"alt":null},{"text":"Less than the average cost","image_url":null,"alt":null},{"text":"Greater than the average cost","image_url":null,"alt":null},{"text":"Falling","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.060Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7170, 10, NULL, 131, 'Read the passage carefully and answer the questions based on the passage:

## Long Run Costs

In the long run, all inputs are variable. There are no fixed costs. The total cost and the total variable cost therefore, coincide in the long run. Long run marginal cost is the change in total cost per unit of change in output. Increasing returns to scale implies that if we increase all the inputs by a certain proportion, output increases by more than that proportion. Decreasing returns to scale implies that if we want to increase the output by a certain proportion, inputs need to be increased by more than that proportion. Constant returns to scale implies a proportional increase in inputs resulting in a proportional increase in output. So the average cost remains constant as long as CRS operates. The RAC curve is a ''U''-shaped

curve. Its downward sloping part corresponds to IRS and upward rising part corresponds to DRS. At the minimum point of the LRAC curve, CRS is observed. For the first unit of output, both LRMC and LRAC are the same. Then, as output increases, LRAC initially falls, and then, after a certain point, it rises. As long as average cost is falling, marginal cost must be less than the average cost. When the average cost is rising, marginal cost must be greater than the average cost. RMC cuts the LRAC curve from below at the minimum point of the LRAC.

The shape of the long-run average cost curve and long-run marginal cost curve.

1. Only LRAC is U shaped.

2. LRAC is U shaped and LRMC upward sloping.

3. Rectangular hyperbole.

4. U shaped.

Options:

Answer: D', NULL, '[{"text":"Only LRAC is U shaped","image_url":null,"alt":null},{"text":"LRAC is U shaped and LRMC upward sloping","image_url":null,"alt":null},{"text":"Rectangular hyperbole","image_url":null,"alt":null},{"text":"U shaped","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.061Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7171, 10, NULL, 132, 'Read the passage carefully and answer the questions based on the passage:

Determination of Income and Employment

When, at a particular price level, aggregate demand for final goods equals aggregate supply of final goods, the final

goods or product market reaches its equilibrium. Aggregate demand for final goods consists of ex ante consumption, ex ante investment, government spending etc. The rate of increase in ex ante consumption due to a unit increment in income is called marginal propensity to consume. For simplicity we assume a constant final goods price and constant rate of interest over short run to determine the level of aggregate demand for final goods in the economy. We also assume that the aggregate supply is perfectly elastic at this price. Under such circumstances, aggregate output is determined solely by the level of aggregate demand. This is known as effective demand principle. An increase in autonomous spending causes aggregate output of final goods to increase by a larger amount through the multiplier process. Full employment level of income is that level of income where all the factors of production are fully employed in the production process. The equilibrium attained at the point of equality of Y and AD by itself does not signify full employment of resources. Equilibrium only means that if left to itself the level of income in the economy will not change even when there is unemployment in the economy. The equilibrium level of output may be more or less than the full employment level of output.

If the equilibrium level of output is more than the full employment level, it is due to the fact that the demand is more than the level of

output produced at full employment level. This situation is called as.....', NULL, '[{"text":"Excess demand","image_url":null,"alt":null},{"text":"Deficient demand","image_url":null,"alt":null},{"text":"Excess output","image_url":null,"alt":null},{"text":"Deficient output","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.062Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7172, 10, NULL, 133, 'A change in autonomous spending causes aggregate output of final goods to change by a large or small amount due to?', NULL, '[{"text":"Change in Consumption","image_url":null,"alt":null},{"text":"Change in Investment","image_url":null,"alt":null},{"text":"Constant Price and Interest rate","image_url":null,"alt":null},{"text":"Multiplier Mechanism","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.063Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7173, 10, NULL, 133, 'Which parameter does not determine the income and employment in the economy.', NULL, '[{"text":"Fixed price level","image_url":null,"alt":null},{"text":"Aggregate supply","image_url":null,"alt":null},{"text":"Fixed autonomous spending","image_url":null,"alt":null},{"text":"Aggregate demand","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2025, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.064Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
