INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7226, 11, NULL, NULL, 'Which NWFP leader was known as ‘Frontier Gandhi’?', NULL, '[{"text":"Abdul Kalam Azad","image_url":null,"alt":null},{"text":"M. A. Jinnah","image_url":null,"alt":null},{"text":"Abdul Ghaffar Khan","image_url":null,"alt":null},{"text":"Abdul Latif ## DIRECTIONS: Read the passage and answer the questions that follows: For several years after the Non-cooperation Movement ended, Mahatma Gandhi focused on his social reform work. In 1928, however he began to think of re-entering politics. That year there was an all India campaign in opposition to the all-White Simon Commission, sent from England to enquire into conditions in the colony. Gandhiji did not himself participate in this movement, although he gave it his blessings, as he also did to a peasant Satyagraha in Bardoli in the same year. In the end of December 1929, the Congress held its annual session in the city of Lahore. The meeting was significant for two things; the election of Jawaharlal Nehru as President, signifying the passing of the baton of leadership to the younger generation; and the proclamation of commitment to ''Purna Swaraj'', or complete independence. Now the pace of politics picked up once more. On 26 January 1930, ''Independence Day'' was observed, with the national flag being hoisted in different venues, and patriotic songs being sung. Gandhiji himself issued precise instructions as to how the days should be observed. \"It would be good,\" he says \"if the declaration of Independence is made by whole villages, whole cities even.... It would be well if all the meetings were held at the Identical minute in all the places","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.116Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
