INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7258, 16, NULL, NULL, 'Convention Relating to Status of Refugees, 1951 provides:', NULL, '[{"text":"Legal safeguard to a refugee/person who is granted asylum/shelter in another country","image_url":null,"alt":null},{"text":"Economic support to refugees","image_url":null,"alt":null},{"text":"Protection of property right of refugees","image_url":null,"alt":null},{"text":"Interim benefits to refugees DIRECTIONS (Qs. 41-45): Read the passage and answer the question below: ## Case Study Sadhna a corporate lawyer is married to Ashish an IAS officer with the government of India. Both had a happy marriage for almost three years when Ashish started behaving poorly with Sadhna. His temper tantrums were becoming often. This was also a period when Sadhna was travelling outside the country for arbitration proceedings between her client M. Pharma (an Indian Company) and the opposite party Xylum Pharmaceuticals INC (incorporated in the United Kingdom having a subsidiary in India). The award for such an arbitration was to be enforced in India. Sadhna had wrapped up the arbitration and had come back to India, when she realised Ashish''s employment was terminated because of some bribery charges against him and also a sexual harassment complaint by one of his junior colleagues Ms. Pari Sahwney. While Ashish wanted to pursue his matter in the court of law, Sadhna wanted to file a divorce while their matter of divorce was still pending in the court of law, to fasten the matters Sadhna & Ashish filed their case at an alternative forum. Sadhna knew that the court will refund their court fee in case their dispute in resolved by this alternative forum. On the other hand, a case of bribery was also filed against Ashish by Mr. Khanna who had conducted this sting operation at Ashish''s office","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.147Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7259, 16, NULL, NULL, 'Identify the type of arbitration that Sadhna who involved in, between M. Pharma & Xylum Pharmaceuticals:', NULL, '[{"text":"Domestic Arbitration","image_url":null,"alt":null},{"text":"Foreign Arbitration","image_url":null,"alt":null},{"text":"Institutional Arbitration","image_url":null,"alt":null},{"text":"Ad-hoc Arbitration","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.147Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
