INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7261, 16, NULL, NULL, 'After having identified the ''alternative forum for Sadhna and Ashish divorce petition, identify its functions.', NULL, '[{"text":"No strict application of procedural laws","image_url":null,"alt":null},{"text":"Secrecy","image_url":null,"alt":null},{"text":"Flexible and informal technique","image_url":null,"alt":null},{"text":"Transparency (E) Efficiency Choose the correct answer from the option given below: (a) (B) and (E) only (b) (A), (D) and (E) only (c) (C) only (d) (C) and (D) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.148Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
