INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7263, 16, NULL, NULL, 'In which forum can Mr. Khanna bring the case of bribery against Ashish?', NULL, '[{"text":"Lok Adalat","image_url":null,"alt":null},{"text":"Central Administrative Tribunal","image_url":null,"alt":null},{"text":"Central Vigilance Officer","image_url":null,"alt":null},{"text":"The Lokpal ### DIRECTIONS (Qs. 46-50): Read the passage and answer the question below: Legal Practice in India as in most other countries is a male dominated profession. In 1916, Calcutta high court and in 1922 Patna high court had held that women otherwise qualified were not entitled to enrol as a Vakil or pleader. In the Patna High Court case the petitioner secured BL Degree from Calcutta University and was refused to be enrolled as pleader. She challenged this in High Court of Patna. The Court ruled that legal practitioner Act referred to males only and no women had even been admitted to the roll of pleaders. The legal Practitioners (women) act XXIII of 1923 was enacted to expressly provide that no women would be reason only of her sex disqualified from being admitted or enrolled as legal practitioner or from practicing as such The Allahabad High Court took lead enrolling the first India Lady Vakil by a decision of English committee of court. Since then number of women entering into profession has increased but gender bias still pervades","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2022, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.149Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
