INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7442, 15, NULL, NULL, 'Dhruv has been consuming alcohol for many years. Recently he has joined an alcohol rehabilitation center. During his group therapy session, Dhruv shared the amount of alcohol he could drink to feel ''high''. He started with a peg and to get the same effect now he has to take greater amount. Identify the reason for this change:', NULL, '[{"text":"Withdrawal","image_url":null,"alt":null},{"text":"Tolerance","image_url":null,"alt":null},{"text":"Poor quality of alcohol","image_url":null,"alt":null},{"text":"Fixation","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.277Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7443, 15, NULL, NULL, 'The Clinical formulation of a client''s problem has the following advantages:

(A) Identification of areas to be targeted for treatment in psychotherapy

(B) Understanding the status of the client

(C) Understanding the problems

(D) To make money

(E) Choice of techniques for treatment

Choose the correct answer from the options given below:', NULL, '[{"text":"(B), (C) & (E) only","image_url":null,"alt":null},{"text":"(C), (D) & (E) only","image_url":null,"alt":null},{"text":"(A), (B) & (C) only","image_url":null,"alt":null},{"text":"(A), (C) & (E) only","image_url":null,"alt":null}]', NULL, 3, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.278Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7444, 15, NULL, NULL, 'Discussed below are elements of triarchic theory. Choose the correct options from the statements given below.

(A) The triarchic theory of intelligence was given by Howard Gardner

(B) According to this theory intelligence is the ability to adapt, to shape and select environment to accomplish ones goals.

(C)There are three basic types of intelligence: componential, contextual and experiential

(D)Componential intelligence may also be called street smartness or business sense

(E) Experiential or creative intelligence is involved in using past experiences creatively to solve novel problems

Choose the correct answer from the options given below:', NULL, '[{"text":"(A), (C) and (D) only","image_url":null,"alt":null},{"text":"(B). (C) and (D) only","image_url":null,"alt":null},{"text":"(B), (C) and (E) only","image_url":null,"alt":null},{"text":"(A), (B) and (C) only","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.279Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7445, 15, NULL, NULL, 'When a large audience is asked to clap as loudly as possible, it was observed that the bigger the group size the more the increase in noise, but the amount of noise each participant made was reduced. This phenomenon is called:', NULL, '[{"text":"Social facilitation","image_url":null,"alt":null},{"text":"Social Loafing","image_url":null,"alt":null},{"text":"Social rejection","image_url":null,"alt":null},{"text":"Social participation","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.280Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7446, 15, NULL, NULL, 'The concept of ''Balance'' in Attitude Change is explained below. Identify the correct options:

(A) Fritz Heider described this change in the form of P-O-X triangle, which explains relationship between the aspects.

(B) P is the person whose attitude is being studied. O is another person, X is the topic towards which attitude is studied.

(C) Attitude changes if there is a state of imbalance between P-O, O-X, P-X attitude.

(D) Imbalance is found when all three sides are positive.

(E) Balance is found when all three sides of the P-O-X triangle are negative.

Choose the correct answer from the options given below:', NULL, '[{"text":"(A), (B) & (D) only","image_url":null,"alt":null},{"text":"(A), (B) & (C) only","image_url":null,"alt":null},{"text":"(A), (B) & (E) only","image_url":null,"alt":null},{"text":"(A), (D) & (E) only","image_url":null,"alt":null}]', NULL, 1, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.280Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7447, 15, NULL, NULL, 'Find out the correct statements about alternative therapies:

(A) Yoga is an ancient Indian technique detailed in the Ashtanga Yoga of Patanjali''s Yoga Sutras.

(B) Alternative therapies are treatment possibilities to the conventional drug treatment or psychotherapy.

(C) Sudarshan Karma Yoga does not benefit individuals with anxiety and depression but helps substance abuse.

(D) There are many alternative therapies like cognitive behaviour therapy and rational emotive therapy.

(E) Vipasana meditation is also known as mindfulness based meditation.

Choose the correct answer from the options given below:', NULL, '[{"text":"(A), (B) & (C) only","image_url":null,"alt":null},{"text":"(B), (C) & (D) only","image_url":null,"alt":null},{"text":"(A), (B) & (E) only","image_url":null,"alt":null},{"text":"(C), (D) & (E) only","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.280Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
