INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7449, 15, NULL, NULL, 'Beth, aged 18, has been trying to keep a secret from her family and friends. She is a binge eater. When others are not around, she gorges on cakes, ice cream and other food so fast that she hardly has time to chew. Once she begins there is no stopping until her stomach aches. After her binge, Beth feels disgusted with herself and makes herself vomit, then takes a double dose of laxative. Her life is totally dominated by her obsession with food. Beth is suffering from which disorder?', NULL, '[{"text":"Anorexia Nervosa","image_url":null,"alt":null},{"text":"Body Dysmorphic Disorder","image_url":null,"alt":null},{"text":"Bulimia Nervosa","image_url":null,"alt":null},{"text":"Conduct disorder","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.281Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7450, 15, NULL, NULL, 'According to Holmes and Rahe, arrange stressful life events in sequence from highest to lowest in terms of their severity:

