<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">List – I</td><td colspan="2">List – II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>A.</td><td style=''text-align: center; word-wrap: break-word;''>Self-esteem</td><td style=''text-align: center; word-wrap: break-word;''>I.</td><td style=''text-align: center; word-wrap: break-word;''>The extent to which individuals believe that they themselves control their life&#x27;s outcomes.</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>B.</td><td style=''text-align: center; word-wrap: break-word;''>Self-efficacy</td><td style=''text-align: center; word-wrap: break-word;''>II.</td><td style=''text-align: center; word-wrap: break-word;''>Judgements about our own value or worth.</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C.</td><td style=''text-align: center; word-wrap: break-word;''>Social-Self</td><td style=''text-align: center; word-wrap: break-word;''>III.</td><td style=''text-align: center; word-wrap: break-word;''>The way we perceive ourselves and the ideas we hold about our competencies and attributes.</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>D.</td><td style=''text-align: center; word-wrap: break-word;''>Self-concept</td><td style=''text-align: center; word-wrap: break-word;''>IV.</td><td style=''text-align: center; word-wrap: break-word;''>Familial or relational self.</td></tr></table>

## Choose the correct answer from the options given below:', NULL, '[{"text":"A - II, B - III, C - IV, D - I","image_url":null,"alt":null},{"text":"A - II, B - IV, C - I, D - III","image_url":null,"alt":null},{"text":"A - II, B - I, C - IV, D - III","image_url":null,"alt":null},{"text":"A - II, B - IV, C - III, D - I","image_url":null,"alt":null}]', NULL, 2, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.283Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
