INSERT OR REPLACE INTO questions ("id", "subject_id", "topic_id", "passage_id", "text", "text_hi", "options", "options_hi", "correct_option", "explanation", "explanation_hi", "difficulty", "year", "image_url", "image_alt", "explanation_image_url", "explanation_image_alt", "status", "supersedes_id", "created_by", "created_at", "updated_at", "deleted_at", "assets_json", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7454, 15, NULL, NULL, 'While judging a personality pageant, raters gave high scores to contestants who were already famous because of their presence in popular T.V. serials or advertisements and tended to give low scores to those who were not so popular. This phenomena is called', NULL, '[{"text":"Halo effect","image_url":null,"alt":null},{"text":"Recency effect","image_url":null,"alt":null},{"text":"Primacy effect","image_url":null,"alt":null},{"text":"Rosenthal effect","image_url":null,"alt":null}]', NULL, 0, NULL, NULL, NULL, 2024, NULL, NULL, NULL, NULL, 'published', NULL, NULL, '2026-11-05T21:01:00.284Z', NULL, NULL, '[]', 'none', 'unreviewed', NULL, NULL);
