INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (14, 'biology-2025-05-20-shift-2', 'p45ed34429892', 'Reading passage', 'The DNA fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The separated DNA fragments can be visualised only after staining the DNA with a compound known as ethidium bromide followed by exposure to UV radiation. The repeated amplification of DNA is achieved by the use of a thermostable DNA polymerase (isolated from a bacterium, Thermus aquaticus). After completion of the biosynthetic stage, the product has to be subjected through a series of processes before it is ready for marketing as a finished product. The downstream processing and quality control testing vary from product to product. The convention for naming restriction enzymes is the first letter of the name comes from the genus and the second two letters come from the species of the prokaryotic cell from which they were isolated.

The thermostable DNA polymerase is isolated from -

1. Thermus aquaticas

2. Thermus aquaticus

3. Thermus aquaticus', NULL);
