INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (16, 'biology-2025-05-20-shift-2', 'pa224766a7d90', 'Reading passage', 'Insulin consists of two short polypeptide chains: chain A and chain B, that are linked together by disulphide bridges. The first clinical gene therapy was given in 1990 to a 4-year old girl with adenosine deaminase (ADA) deficiency. This enzyme is crucial for the immune system to function. Recombinant DNA technology, Polymerase Chain Reaction (PCR) and Enzyme Linked Immunosorbent Assay (ELISA) are some of the techniques that serve the purpose of early diagnosis of diseases. Transgenic animals that produce useful biological products can be created by the introduction of the portion of DNA (or genes) which codes for a particular product such as human protein ( $ \alpha $-1-antitrypsin) used to treat emphysema. Biopiracy is the term used to refer to the use of bio-resources by multinational companies and other organisations without proper authorisation from the countries and people concerned without compensatory payment.

