INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (23, 'chemistry-2025-05-21-shift-2', 'p41b88e867801', 'Reading passage', 'The transition metals and their compounds are known for their catalytic activity. This activity is ascribed to their ability to adopt multiple oxidation states and to form complexes. Vanadium(V) oxide (in Contact Process), finely divided iron, and nickel (in Catalytic Hydrogenation) are some of the examples. Catalysts at a solid surface involve the formation of bonds between reactant molecules and atoms of the surface of the catalyst (first row transition metals utilise 3d and 4s electrons for bonding). This has the effect of increasing the concentration of the reactants at the catalyst surface and also weakening of the bonds in the reacting molecules (the activation energy is lowering). Also because the transition metal ions can change their oxidation states, they become more effective as catalysts.

In the Wacker process the oxidation of ethene to ethanol is catalysed by _

1. TiCl_{4}

2. PdCl_{2}

3. MnO_{2}', NULL);
