INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (60, 'general-test-2025-05-20-shift-2', 'p359cb7b2c350', 'Reading passage', 'There are six members in a family, named A, B, C, D, E, and F. B is the son of C but C is not the mother of B. A and C are a married couple. E is the brother of C, D is the daughter of A. F is the brother of B.

(A) There are only three male members in the family

(B) A has only three children

(C) A and D are both females

(D) D is a female but A is not a female

Choose the correct answer from the options given below

1. (A), (B), (C), and (D) are all incorrect

2. (A), (B), (C), and (D) are all correct

3. (A) and (C) are correct but (B) and (D) are incorrect', NULL);
INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (61, 'geography-2025-05-16-shift-1', 'p94fc7b10ab45', 'Reading passage', 'Jhabua district is located in the westernmost agro-climatic zone in Madhya Pradesh. It is, in fact, one of the five most backward districts of the country. It is characterised by high concentration of tribal population (mostly Bhils). The people suffer due to poverty which has been accentuated by the high rate of resource degradation, both forest and land. The watershed management programmes funded by both the ministries of "Rural Development" and "Agriculture", Government of India, have been successfully implemented in Jhabua district which has gone a long way in preventing land degradation and improving soil quality. Watershed Management Programmes acknowledge the linkage between land, water and vegetation and attempts to improve livelihoods of

people through natural resource management and community participation. In the past five years, the programmes funded by the Ministry of Rural Development alone (implemented by Rajiv Gandhi Mission for Watershed Management) has treated 20 per cent of the total area under Jhabua district. The Petlawad block of Jhabua is located in the northernmost part of the district and represents an interesting and successful case of Government-NGO partnership and community participation in managing watershed programmes. The Bhils in Petlawad block, for example, (Sat Rundi hamlet of Karravat village) through their own efforts, have revitalised large parts of common property resources. Each household planted and maintained one tree the common property. They also have planted fodder grass on the pasture land and adopted social-fencing of these lands for at least two years. Even after that, they say, there would be no open grazing on these lands, but stall feeding of cattle, and they are thus confident that the pastures they have developed would sustain their cattle in future. An interesting aspect of this experience is that before the community embarked upon the process of management of the pasture, there was encroachment on this land by a villager from an adjoining village. The villagers called the tehsildar to ascertain the rights of the common land. The ensuing conflict was tackled by the villagers by offering to', NULL);
