INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (76, 'geography-2025-05-20-shift-1', 'pf8cc85ad6632', 'Reading passage', 'Pipelines are the most convenient and efficient mode of transporting liquids and gases over long distances. Even solids can also be transported by pipelines after converting them into slurry. Oil India Limited (OIL) under the

administrative set up of the Ministry of Petroleum and Natural Gas is engaged in the exploration, production and transportation of crude oil and natural gas. It was incorporated in 1959 as a company. Asia''s first cross country pipeline covering a distance of 1,157 km was constructed by OIL from Naharkatiya oilfield in Assam to Barauni refinery in Bihar. It was further extended up to Kanpur in 1966. GAIL (India) Ltd. was set up in 1984 as a public sector undertaking to transport, process and market natural gas for its economic use. The first 1,700 km long Hazira-Vijaipur-Jagdishpur (HVJ) cross country gas pipeline, constructed by GAIL (India), linked Mumbai High and Bassein gas fields with various fertiliser, power and industrial complexes in western and northern India. This artery provided impetus to Indian gas market development. Overall, India''s gas infrastructure has expanded over ten times from 1,700 km to 18,500 km of cross-country pipelines and is expected to soon reach over 34,000 km as Gas Grid by linking all the gas sources and consuming markets across the country including North Eastern States.

Hazira is located in _.

1. North Eastern part of India

2. Northern part of India

3. Western part of India', NULL);
INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (77, 'geography-2025-05-20-shift-1', 'pf1a88dc06612', 'Reading passage', 'Pipelines are the most convenient and efficient mode of transporting liquids and gases over long distances. Even solids can also be transported by pipelines after converting them into slurry. Oil India Limited (OIL) under the administrative set up of the Ministry of Petroleum and Natural Gas is engaged in the exploration, production and transportation of crude oil and natural gas. It was incorporated in 1959 as a company. Asia''s first cross country pipeline covering a distance of 1,157 km was constructed by OIL from Naharkatiya oilfield in Assam to Barauni refinery in Bihar. It was further extended up to

Kanpur in 1966. GAIL (India) Ltd. was set up in 1984 as a public sector undertaking to transport, process and market natural gas for its economic use. The first 1,700 km long Hazira-Vijaipur-Jagdishpur (HVJ) cross country gas pipeline, constructed by GAIL (India), linked Mumbai High and Bassein gas fields with various fertiliser, power and industrial complexes in western and northern India. This artery provided impetus to Indian gas market development. Overall, India''s gas infrastructure has expanded over ten times from 1,700 km to 18,500 km of cross-country pipelines and is expected to soon reach over 34,000 km as Gas Grid by linking all the gas sources and consuming markets across the country including North Eastern States.

Identify the oil well situated in the Sea?

1. Naharkatiya

2. Hazira

3. Mumbai High', NULL);
