INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (111, 'english-2024-05-29-shift-1', 'p1c8f3566a8da', 'Reading passage', 'As the weather changes, everyone is prone to colds and coughs. While we have all heard about the benefits of vitamin C for colds, few of us are aware of a secret solution - Zinc! Zinc is helpful as it can reduce the severity and duration of respiratory tract infections. It soothes sore throats with its anti-inflammatory properties. It plays a pivotal role in supporting various functions of the body like the immune system, wound healing and maintaining overall health. It prevents viruses from growing in the body. Zinc is also known to boost the immune system and fight infections.

Notably, zinc is a vital mineral found in a variety of plant and animal foods. When consuming zinc-rich foods during a cough and cold, prioritise moderation and diversity in your diet. Include lean meats, poultry, sea food, dairy, nuts and seeds. Combine zinc-rich foods with vitamin C sources for enhanced immune support.

Phytates, a substance found in unprocessed whole grains hinder the absorption of zinc, thereby making it less available for the body to utilise. Hence, vegetarians should follow some cooking techniques such as soaking them for 5-6 hours to reduce the phytate content and increase the bioavailability of zinc. Organic acids in fermented foods aid in higher absorption, so always include foods in your diet like buttermilk and yogurt along with some zinc-rich vegetarian sources. It is important to remember that a higher dosage of zinc supplement inhibits the absorption of other minerals. Therefore, it is always good to check with the healthcare professionals while taking supplements. Stay hydrated, choose cooking methods that preserve zinc, and be aware of factors like phytates affecting absorption.', NULL);
INSERT OR REPLACE INTO practice_passages ("id", "paper_slug", "passage_key", "title", "body", "deleted_at") VALUES (112, 'english-2024-05-29-shift-1', 'p0edc22a3a127', 'Reading passage', 'Pollinators, such as bees, butterflies, birds and bats, are essential for the ecosystem, health and human food security. They facilitate plant reproduction by transferring pollen between flowers, enabling the production of seeds and fruits crucial for plant biodiversity and ecosystem stability. This mutualistic relationship supports global food production, with approximately 75% of leading food crops relying on animal pollination. Pollinators contribute to the diversity and abundance of flowering plants in natural ecosystems, providing habitat and food resources for various organisms. Despite their importance, pollinators face significant threats. Habitat loss due to urbanization, agriculture and

deforestation reduces nesting sites and floral resources. Pesticide exposure, especially insecticides and

climate change further endanger pollinator populations by poisoning them and disrupting their behaviour and reproductive patterns. To safeguard pollinators and ecosystems, concerted action is necessary. This includes protecting and restoring pollinator habitats, adopting pollinator-friendly agricultural practices, reducing pesticide use and raising public awareness about the crucial role of pollinators. By addressing these challenges, we can ensure the sustainability of ecosystems, biodiversity and food production systems, securing a healthier future for both nature and humanity.', NULL);
