INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1, 'applied-mathematics-2025-06-02-shift-1', 'q01', 1, 1, '$$ \int\frac{e^{2x}-e^{-2x}}{e^{2x}+e^{-2x}}dx $$

is equal to:', '[{"id":"A","text":"$ \\frac{1}{2}\\log|e^{2x}-e^{-2x}|+C $, where $ C $ is an arbitrary constant."},{"id":"B","text":"$ \\log|e^{2x}-e^{-2x}|+C $, where $ C $ is an arbitrary constant."},{"id":"C","text":"$ \\frac{1}{2}\\log|e^{2x}+e^{-2x}|+C $, where $ C $ is an arbitrary constant."},{"id":"D","text":"$ \\log|e^{2x} + e^{-2x}| + C $, where $ C $ is an arbitrary constant."}]', 0, 'C', '1. Choose a substitution:

Let u be the denominator:

$$ u=e^{2x}+e^{-2x} $$

2. Find the differential du:

Take the derivative of u with respect to x :

$$ \frac{du}{dx}=\frac{d}{dx}(e^{2x})+\frac{d}{dx}(e^{-2x}) $$

Using the chain rule, $ \frac{d}{dx}(e^{kx}) = ke^{kx} $:

$$ \frac{du}{dx}=(2e^{2x})+(-2e^{-2x})=2e^{2x}-2e^{-2x}=2(e^{2x}-e^{-2x}) $$

Therefore, the differential $ du $ is:

$$ du=2(e^{2x}-e^{-2x})dx $$

This means the numerator, $ (e^{2x} - e^{-2x})dx $, is equal to $ \frac{1}{2}du $:

$$ (e^{2x}-e^{-2x})dx=\frac{1}{2}du $$

$$ I=\int\frac{1}{u}(\frac{1}{2}du)=\frac{1}{2}\int\frac{1}{u}du $$

3. Substitute u and du into the integral:

4. Integrate with respect to u:

The integral of $ \frac{1}{u} $ is $ \log|u| $:

$$ I=\frac{1}{2}\log|u|+C $$

where C is the arbitrary constant of integration.

5. Substitute back for x :

Replace u with $ e^{2x} + e^{-2x} $:

$$ I=\frac{1}{2}\log|e^{2x}+e^{-2x}|+C $$

Since $ e^{2x} + e^{-2x} $ is always positive, the absolute value is technically not required, but including it is mathematically correct for the general form $ \int \frac{1}{u}du = $

$$ I=\frac{1}{2}\log(e^{2x}+e^{-2x})+C $$

[The correct optionis3.]', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.474Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2, 'applied-mathematics-2025-06-02-shift-1', 'q02', 2, 2, 'Linear inequalities corresponding to the shaded feasible region OABCO in the given figure are', '[{"id":"A","text":"$ 4x + 3y \\leq 12 $, $ 3x + 4y \\leq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"},{"id":"B","text":"$ 4x + 3y \\geq 12 $, $ 3x + 4y \\geq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"},{"id":"C","text":"$ 4x + 3y \\leq 12 $, $ 3x + 4y \\geq 12 $, $ x, \\geq 0, y \\geq 0 $"},{"id":"D","text":"$ 4x + 3y \\geq 12 $, $ 3x + 4y \\leq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"}]', 0, 'A', '1. Axes (Non-Negativity)

The region is in the first quadrant:

$$ x\geq0,\quad y\geq0 $$

2. Line 1: Through D(0, 4) and A(3, 0)

Intercepts: x-intercept a = 3, y-intercept b = 4.

Equation (Intercept Form): $ \frac{x}{3} + \frac{y}{4} = 1 \Longrightarrow 4x + 3y = 12 $

Inequality: Since the region includes the origin $ (0,0) $, the constraint is: $ 4x + 3y \leq 12 $

3. Line 2: Through C(0, 3) and E(4, 0)

Intercepts: x-intercept a = 4, y-intercept b = 3.

Equation (Intercept Form): $ \frac{x}{4} + \frac{y}{3} = 1 \Longrightarrow 3x + 4y = 12 $

Inequality: Since the region includes the origin $ (0,0) $, the constraint is: $ 3x + 4y \leq 12 $
Complete System of Constraints

$$ x\geq0,\quad y\geq0,\quad4x+3y\leq12,\quad3x+4y\leq12 $$

[The correct option is 1.]', NULL, 'null', '[]', '[{"id":"q02-figure-1","kind":"figure","path":"/local-papers/assets/applied-mathematics-2025-06-02-shift-1/q02-figure-1.jpg","page":2,"alt":"Figure for question 2"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.475Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3, 'applied-mathematics-2025-06-02-shift-1', 'q03', 3, 3, 'Match List-I with List-II', '[{"id":"A","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I V}),(\\mathbf{C})-(\\mathbf{I I}),(\\mathbf{D})-(\\mathbf{I I I})"},{"id":"B","text":"\\ (\\mathrm{A})-(\\mathrm{II}),(\\mathrm{B})-(\\mathrm{I}),(\\mathrm{C})-(\\mathrm{III}),(\\mathrm{D})-(\\mathrm{IV})"},{"id":"C","text":"(A) - $ \\mathrm{(III)} $, (B) - $ \\mathrm{(IV)} $, (C) - $ \\mathrm{(II)} $, (D) - $ \\mathrm{(I)} $"},{"id":"D","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"}]', 0, 'C', 'The order of a differential equation is the order of the highest derivative present in the equation.

The degree of a differential equation is the power of the highest-order derivative after the equation has been rationalized (i.e., cleared of any fractional powers of the derivatives).

A. The degree of differential equation $ \frac{d^{3}y}{dx^{3}} = e^{\frac{dy}{dx}} $ is not defined (due to $ e^{\frac{dy}{dx}} $ term) $ \rightarrow $ (III) not defined

B. The order of differential equation $ \left(\frac{dy}{dx}\right)^{2}+\frac{d^{3}y}{dx^{3}}=0 $ is $ 3\rightarrow(IV) $ 3

C. The sum of order and degree of differential equation $ \frac{d}{dx}\left(\frac{d^2y}{dx^2}\right) + \left(\frac{dy}{dx}\right)^3 = x $ is $ (3 + 1 = 4) \to (\mathrm{II}) $ 4

D. The number of arbitrary constants in the general solution of a differential equation of order 2 is $ 2 \to (I) $

The final match is: (A) - (III), (B) - (IV), (C) - (II), (D) - (I)

[The correct option is 3.]', NULL, 'null', '[]', '[{"id":"q03-table-1","kind":"table","path":"/local-papers/assets/applied-mathematics-2025-06-02-shift-1/q03-table-1.jpg","page":3,"alt":"Table for question 3"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.476Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4, 'applied-mathematics-2025-06-02-shift-1', 'q04', 4, 4, '$$ \mathrm{I f}\begin{bmatrix}3&1\\ 2&1\end{bmatrix}A\begin{bmatrix}2&1\\ 1&1\end{bmatrix}=\begin{bmatrix}1&1\\ 0&1\end{bmatrix}, $$

then matrix ''A'' is

$$ \begin{bmatrix}1&1\\ 0&0\end{bmatrix} $$

$$ \begin{bmatrix}{{{-1}}}&{{{1}}} \\{{{3}}}&{{{-4}}}\end{bmatrix} $$

$$ \begin{bmatrix}1&-1\\ -3&4\end{bmatrix} $$

$$ 4.\begin{bmatrix}1&0\\ 0&1\end{bmatrix} $$', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The given equation is $BAC = D$. where:

$$ \boldsymbol{B}=\begin{bmatrix}{{{3}}}&{{{1}}} \\{{{2}}}&{{{1}}}\end{bmatrix},\quad\boldsymbol{C}=\begin{bmatrix}{{{2}}}&{{{1}}} \\{{{1}}}&{{{1}}}\end{bmatrix},\quad\boldsymbol{D}=\begin{bmatrix}{{{1}}}&{{{1}}} \\{{{0}}}&{{{1}}}\end{bmatrix} $$

To solve for A, we pre-multiply by $ B^{-1} $ and post-multiply by $ C^{-1} $:

$$ \boldsymbol{A}=\boldsymbol{B}^{-1}\boldsymbol{D}\boldsymbol{C}^{-1} $$

1. Calculate Inverses

For a $ 2 \times 2 $ matrix $ M = \begin{bmatrix} a & b \\ c & d \end{bmatrix} $, $ M^{-1} = \frac{1}{|M|} \begin{bmatrix} d & -b \\ -c & a \end{bmatrix} $.

Inverse of $B$

$$ \left|B\right|=3(1)-1(2)=1. $$

$$ \boldsymbol{B}^{-1}=\frac{1}{1}\begin{bmatrix}1&-1\\ -2&3\end{bmatrix}=\begin{bmatrix}1&-1\\ -2&3\end{bmatrix} $$

Inverse of C

$$ |C|=2(1)-1(1)=1. $$

$$ C^{-1}=\frac{1}{1}\begin{bmatrix}1&-1\\ -1&2\end{bmatrix}=\begin{bmatrix}1&-1\\ -1&2\end{bmatrix} $$

$$ 2.Compute B^{-1}D $$

$$ \boldsymbol{B}^{-1}\boldsymbol{D}=\begin{bmatrix}1&-1\\ -2&3\end{bmatrix}\begin{bmatrix}1&1\\ 0&1\end{bmatrix}=\begin{bmatrix}1(1)+(-1)(0)&1(1)+(-1)(1)\\ -2(1)+3(0)&-2(1)+3(1)\end{bmatrix}=\begin{bmatrix}1&0\\ -2&1\end{bmatrix} $$

$$ 3.\operatorname{Compute}A=(B^{-1}D)C^{-1} $$

$$ \boldsymbol{A}=\begin{bmatrix}1&0\\ -2&1\end{bmatrix}\begin{bmatrix}1&-1\\ -1&2\end{bmatrix}=\begin{bmatrix}1(1)+0(-1)&1(-1)+0(2)\\ -2(1)+1(-1)&-2(-1)+1(2)\end{bmatrix} $$

$$ \boldsymbol{A}=\begin{bmatrix}1&-1\\ -3&4\end{bmatrix} $$

[The correct option is 3.]', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.476Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5, 'applied-mathematics-2025-06-02-shift-1', 'q05', 5, 5, 'For the function $ f(x) = -2x^3 + 3x^2 + 36x - 10 $, which of the following is/are true?

(A) f is increasing in $ (-\infty, -2) $

(B) f is increasing in $ (-2,3) $

(C) f is decreasing in $ (-\infty, -2) $

(D) f is decreasing in $ (3, \infty) $', '[{"id":"A","text":"(B) and (D) only"},{"id":"B","text":"(B), (C) and (D) only"},{"id":"C","text":"(A) and (D) only"},{"id":"D","text":"(B) only"}]', 0, 'B', 'Analysis of Monotonicity for $ f(x) = -2x^{3} + 3x^{2} + 36x - 10 $

$$ f(x)=-2x^{3}+3x^{2}+36x-10 $$

1. Derivative and Critical Points:

$$ f^{\prime}(x)=-6x^{2}+6x+36 $$

$$ \operatorname{Set}f^{\prime}(x)=0: $$

$$ -6x^{2}+6x+36=0 $$

$$ -6(x^{2}-x-6)=0\implies-6(x-3)(x+2)=0 $$

$$ \mathrm{C r i t i c a l~p o i n t s~a r e~x}=-2\mathrm{~a n d~}\mathbf{x}=3. $$

$$ 2.\operatorname{Check\ Intervals}\ (f^{\prime}(x)\operatorname{sign}): $$

$$ \mathrm{I n t e r v a l}\left(-\infty,-2\right)\colon f^{\prime}(-3)=-6(\left(-3\right)^{2}-(-3)-6)=-6(9+3-6)=-36 0\implies\mathrm{I n c r e a s i n g}\mathrm{~(B~i s~T R U E)} $$

$$ \mathrm{I n t e r v a l}\;(3,\infty)\colon f^{\prime}(4)=-6(4^{2}-4-6)=-6(16-10)=-36<0\implies\mathrm{D e c r e a s i n g}\;(\mathbf{D}\;\mathrm{i s}\;\mathrm{T R U E}) $$

3. Conclusion:

Statements (B), (C), and (D) are TRUE.

[The correct option is 2.]', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.476Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6, 'applied-mathematics-2025-06-02-shift-1', 'q06', 6, 6, '$$ If\;y=\frac{1}{\sqrt[3]{1-x^{3}}},\;then\;\frac{dy}{dx}is equal to: $$', '[{"id":"A","text":"x(1-x^{3})^{-\\frac{4}{3}}"},{"id":"B","text":"x^{2}(1-x^{3})^{-\\frac{4}{3}}"},{"id":"C","text":"\\left(1-x^{3}\\right)^{-\\frac{4}{3}}"},{"id":"D","text":"x^{2}(1-x^{3})^{-\\frac{4}{3}}"}]', 0, 'B', '$$ y=\frac{1}{\sqrt[3]{1-x^{3}}} $$

1. Rewrite y using exponent notation:

$$ y=(1-x^{3})^{-\frac{1}{3}} $$

2. Differentiate $ \frac{dy}{dx} $ using the Chain Rule $ \frac{d}{dx}[u^{n}] = nu^{n-1} \cdot \frac{du}{dx} $:

$$ Let u=(1-x^{3}).~Then~\frac{du}{dx}=-3x^{2}. $$

$$ \frac{dy}{dx}=-\frac{1}{3}(1-x^{3})^{-\frac{1}{3}-1}\cdot\frac{d}{dx}(1-x^{3}) $$

$$ \frac{dy}{dx}=-\frac{1}{3}(1-x^{3})^{-\frac{4}{3}}\cdot(-3x^{2}) $$

3. Simplify the expression:

$$ \frac{dy}{dx}=\left(-\frac{1}{3}\right)(-3x^{2})(1-x^{3})^{-\frac{4}{3}} $$

$$ \frac{dy}{dx}=\mathbf{x}^{2}(\mathbf{1}-\mathbf{x}^{3})^{-\frac{4}{3}} $$

[The correct option is 2.]', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.477Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7, 'applied-mathematics-2025-06-02-shift-1', 'q07', 7, 7, 'If x is real, the minimum value of $ x^{2}-8x+20 $ is:', '[{"id":"A","text":"4"},{"id":"B","text":"2"},{"id":"C","text":"0"},{"id":"D","text":"1"}]', 0, 'A', 'Function: $ f(x) = x^{2} - 8x + 20 $

1. First Derivative and Critical Point:

$ f''(x) = 2x - 8 $

$ f''(x) = 0 $

$ \Longrightarrow 2x = 8 $

$ \Longrightarrow x = 4 $ (Critical Point)

2. Second Derivative Test (Confirmation):

$$ f^{\prime\prime}(x)=\frac{d}{dx}\left(2x-8\right)=\mathbf{2} $$

Since $ f''''(4) = 2 > 0 $ (positive), the function has a Local Minimum at x = 4.
3. Minimum Value:

$ f(4)=(4)^{2}-8(4)+20=16-32+20=4 $

The minimum value is 4.

[The correct option is 1.]', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.477Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (8, 'applied-mathematics-2025-06-02-shift-1', 'q08', 8, 8, 'If A is a square matrix of order 3 and |A| = 5, then the value of | - A A^{*} | is:', '[{"id":"A","text":"25"},{"id":"B","text":"25"},{"id":"C","text":"5"},{"id":"D","text":"5"}]', 0, 'B', 'Given: $ |A|=5 $, Order $ n=3 $.

Required: $ |-AA^{T}| $

$ =(-1)^{3}|AA^{T}| $

$ =-1\cdot|A||A^{T}| $

$ =-1\cdot(5)(5) $

=-25

Answer: -25', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.477Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (9, 'applied-mathematics-2025-06-02-shift-1', 'q09', 9, 9, '$$ x+y\leq60, $$

