INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (103, 'biology-2025-05-20-shift-1', 'q12', 12, 12, 'The RNA polymerase II transcribes:', '[{"id":"A","text":"tRNA"},{"id":"B","text":"hnRNA"},{"id":"C","text":"snRNA"},{"id":"D","text":"rRNA"}]', 0, 'B', 'Correct Answer: (2) hnRNA

