INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (105, 'biology-2025-05-20-shift-1', 'q14', 14, 14, 'Statins produced by the yeast variety is_ which have been commercialised as blood-cholesterol lowering agents.', '[{"id":"A","text":"Aspergillus niger"},{"id":"B","text":"Trichoderma polysporum"},{"id":"C","text":"Monascus purpureus"},{"id":"D","text":"Bacillus thuringiensis"}]', 0, 'C', 'Correct Answer: (3) Monascus purpureus

