INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (106, 'biology-2025-05-20-shift-1', 'q15', 15, 15, 'Contact inhibition is a property of:', '[{"id":"A","text":"Normal cells"},{"id":"B","text":"Cancer cells"},{"id":"C","text":"B-cells"},{"id":"D","text":"T-cells"}]', 0, 'A', 'Correct Answer: (1) Normal cells

Explanation:

Normal cells exhibit contact inhibition, stopping growth when in contact with other cells.

- Prevents overcrowding and uncontrolled proliferation

- Cancer cells lose this property, leading to tumor formation

Why others are wrong:

- (2) Cancer cells: Lack contact inhibition

- (3) &(4) involved in immunity response.

