INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (107, 'biology-2025-05-20-shift-1', 'q16', 16, 16, 'IUCN stands for:', '[{"id":"A","text":"International Union for Conservation of Natural Resources"},{"id":"B","text":"International Union for Conservation of Nature"},{"id":"C","text":"International Union for Conservation of Nature and Natural Resources"},{"id":"D","text":"International Union Commission of Nature and Natural Resources"}]', 0, 'C', 'Correct Answer: (3) International Union for Conservation of Nature and Natural Resources

Explanation:

IUCN is a global organization that maintains the Red List, which categorizes species based on their risk of extinction.

- Helps in biodiversity conservation and policy-making

- Categories include: Extinct, Endangered, Vulnerable, etc.

CUET Tip: Memorize full forms of key organizations.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (108, 'biology-2025-05-20-shift-1', 'q17', 17, 17, 'Match List-I with List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">Characteristics</th>
      <th style="padding: 8px; border: 1px solid #444;">Examples</th>
    </tr>
  </thead>
  <tbody>
    <tr><td style="padding: 8px; border: 1px solid #444;">(A) Symbiotic association with roots of leguminous plants</td><td style="padding: 8px; border: 1px solid #444;">(I) Glomus</td></tr>
    <tr><td style="padding: 8px; border: 1px solid #444;">(B) Fixes atmospheric nitrogen while free living in the soil</td><td style="padding: 8px; border: 1px solid #444;">(II) Rhizobium</td></tr>
    <tr><td style="padding: 8px; border: 1px solid #444;">(C) Symbiotic association of fungi and plants</td><td style="padding: 8px; border: 1px solid #444;">(III) Anabaena</td></tr>
    <tr><td style="padding: 8px; border: 1px solid #444;">(D) Cyanobacteria which can fix atmospheric nitrogen</td><td style="padding: 8px; border: 1px solid #444;">(IV) Azotobacter</td></tr>
  </tbody>
</table>', '[{"id":"A","text":"(A) - (II), (B) - (IV), (C) - (I), (D) - (III)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'D', 'Symbiotic with roots (Rhizobium), Free living (Azotobacter), Fungi and plants (Glomus), Cyanobacteria (Anabaena).', NULL, 'null', '[]', '[]', '[14,15]', 'keyed', '[]', '2026-11-05T20:58:38.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (109, 'biology-2025-05-20-shift-1', 'q18', 18, 18, 'The hormone releasing IUDs function by:', '[{"id":"A","text":"Decreasing phagocytosis of sperms within the uterus"},{"id":"B","text":"Activating sperm motility and the fertilising capacity of sperms"},{"id":"C","text":"Making the uterus suitable for implantation and the cervix hostile to the sperms"},{"id":"D","text":"Making the uterus unsuitable for implantation and the cervix hostile to the sperms"}]', 0, 'D', 'Correct Answer: (4) Making the uterus unsuitable for implantation and the cervix hostile to the sperms

Explanation:

Hormone-releasing IUDs (e.g., LNG-20, Progestasert):

- Release progesterone or progestin

- Prevent implantation by altering uterine lining

- Make cervical mucus thick, hindering sperm entry', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (110, 'biology-2025-05-20-shift-1', 'q19', 19, 19, 'The genetic disorder, Down''s Syndrome is caused due to:', '[{"id":"A","text":"Deletion of chromosome no. 21"},{"id":"B","text":"Trisomy of chromosome no. 18"},{"id":"C","text":"Trisomy of chromosome no. 21"},{"id":"D","text":"Inversion of chromosome no. 21"}]', 0, 'C', 'Correct Answer: (3) Trisomy of chromosome no. 21

Explanation:

Down Syndrome is caused by trisomy 21, where an individual has three copies of chromosome 21.

- Leads to mental retardation, short stature, and distinct facial features

- Detected via karyotyping

CUET Tip: Recognize chromosomal disorders and their genetic basis.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (111, 'biology-2025-05-20-shift-1', 'q20', 20, 20, 'Arrange the given structures starting from chalazal end to micropylar end in a mature embryo sac?

(A) Central cell

(B) Antipodals

(C) Synergids

(D) Egg', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D), (C), (B), (A)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'Correct Answer: (3)(B), (A), (D), (C)

Explanation:

This sequence represents the egg apparatus at the micropylar end of the embryo sac:

- (B) Synergid

- (A) Egg cell

- (D) Central cell

- (C) Antipodal cells

CUET Tip: Visualize embryo sac structure.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (112, 'biology-2025-05-20-shift-1', 'q21', 21, 21, 'You must have seen the weed Calotropis growing in abandoned fields. The plant produces highly poisonous_ and that is why you never see any cattle or

goats browsing on this plant', '[{"id":"A","text":"Cardiac amino acids"},{"id":"B","text":"Cardiac glucose"},{"id":"C","text":"Cardiac glycerol"},{"id":"D","text":"Cardiac glycosides"}]', 0, 'D', 'Correct Answer: (4) Cardiac glycosides

Explanation:

Calotropis produces cardiac glycosides, which are toxic compounds that affect heart function.

- These chemicals deter herbivores like cattle from grazing

- A classic example of chemical defense in plants', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (113, 'biology-2025-05-20-shift-1', 'q22', 22, 22, 'Arrange the given structures in correct sequence of spermatogenesis?

(A) Spermatozoa

(B) Secondary spermatocytes

(C) Spermatogonia

(D) Spermatids', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D), (C), (B), (A)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'D', 'Correct Answer: (4)(C), (B), (D), (A)

Explanation:

The stages of spermatogenesis in the correct biological order are:

• Spermatogonia (Germ cells -> undergo mitosis to increase number)

• Primary Spermatocytes (not listed, but form from Spermatogonia)

• Secondary Spermatocytes (Formed after Meiosis I)

• Spermatids (Formed after Meiosis II)

• Spermatozoa (Spermatids differentiate into mature sperm)', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (114, 'biology-2025-05-20-shift-1', 'q23', 23, 23, 'Identify the correct sequence of events during menstrual cycle?

(A) Next cycle begins

(B) Proliferative phase

(C) Menstruation

(D) Secretary phase', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D),(C),(B),(A)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'D', 'Correct Answer: (4)(C), (B), (D), (A)

Explanation:

Explanation:

This sequence represents menstrual cycle stages:

- (C) Menstruation

- (B) Follicular (proliferation) phase

- (D) Luteal (secretory) phase

- (A) Next cycle begins

CUET Tip: Review menstrual cycle timeline.

Figure 2.9 Diagrammatic presentation of various events during a menstrual cycle', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (115, 'biology-2025-05-20-shift-1', 'q24', 24, 24, 'The rate of biomass production is called productivity. It is expressed in terms of_ to compare the productivity of different ecosystems.', '[{"id":"A","text":"(kcal m $ ^{-1} $) yr $ ^{-1} $"},{"id":"B","text":"(kcal m $ ^{-2} $) yr $ ^{-2} $"},{"id":"C","text":"(kcal m $ ^{-2} $) yr $ ^{-1} $"},{"id":"D","text":"(kcal m^{-1}) yr^{-2}"}]', 0, 'C', 'Correct Answer: (3) (kcal m^{-2} yr^{-1})

Explanation:

Primary productivity is measured as the rate of biomass production:

- Expressed in kilocalories per square meter per year or grams per square meter per year

- Indicates energy flow in ecosystems

Why others are wrong:

Other options show wrong dimensions.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (116, 'biology-2025-05-20-shift-1', 'q25', 25, 25, 'The "Rivet Popper Hypothesis" was used by:', '[{"id":"A","text":"Alexander von Humboldt"},{"id":"B","text":"Paul Ehrlich"},{"id":"C","text":"Hardy-Weinberg"},{"id":"D","text":"Edward Wilson"}]', 0, 'B', 'Correct Answer: (2) Paul Ehrlich

Explanation:

Paul Ehrlich, a Stanford ecologist, proposed the rivet popper hypothesis:

- Compares ecosystem to an airplane losing rivets (species)

- Loss of key species can lead to ecosystem collapse.', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (117, 'biology-2025-05-20-shift-1', 'q26', 26, 26, 'Nicotine stimulates the adrenal gland to release:

(A) Thyroid stimulating hormone (TSH)

(B) Adrenaline

(C) Estrogen

(D) Nor-adrenaline', '[{"id":"A","text":"(B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Correct Answer: (1) (B) and (D) only

Explanation:

Nicotine, a stimulant found in tobacco, affects the adrenal glands, triggering the release of adrenaline.

- This leads to increased blood pressure and heart rate

- It acts on the central nervous system, causing alertness and dependency

Hence, Correct statements:

- (B) Nicotine stimulates adrenal glands

- (D) Adrenaline increases blood pressure and heart rate

Why others are wrong:

- (A) Nicotine decreases heart rate: Incorrect - it increases it', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (118, 'biology-2025-05-20-shift-1', 'q27', 27, 27, 'Select the intra uterine devices from the following:

(A) Multiload 375

(B) Saheli

(C) Cervical caps

(D) Progestasert', '[{"id":"A","text":"(A) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Correct Answer: (1) (A) and (D) only

Explanation:

Intrauterine Devices (IUDs) are classified into three types:

- (A) Non-medicated IUDs (e.g., Lippes Loop)

- (B) Copper-releasing IUDs (e.g., CuT, Cu7, Multiload 375)

- (C) Hormone-releasing IUDs (e.g., LNG-20, Progestasert)

Only (A) and (D) are correct in this context.

Why others are wrong:

- (B) and (C) are pill and barrier type examples

- The question asks for IUDs, and only (A) and (D) are the IUDs.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (119, 'biology-2025-05-20-shift-1', 'q28', 28, 28, 'Match List-I with List-II:

