INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (123, 'biology-2025-05-20-shift-1', 'q32', 32, 32, 'The inner cell mass of the embryo contains some cells which can give rise to all the tissues and organs. They are known as:', '[{"id":"A","text":"Ectoderm"},{"id":"B","text":"Blastomeres"},{"id":"C","text":"Trophoblast"},{"id":"D","text":"Stem cells"}]', 0, 'D', 'Correct Answer: (4) Stem cells

Explanation:

The inner cell mass of a blastocyst contains pluripotent stem cells.

- Can differentiate into various tissues

- Used in regenerative medicine', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (124, 'biology-2025-05-20-shift-1', 'q33', 33, 33, 'Zygote or embryos upto 8 blastomeres can be transferred into the fallopian tube for further development. The procedure is known as:', '[{"id":"A","text":"Zygote intra fallopian transfer (ZIFT)"},{"id":"B","text":"Gamete intra fallopian transfer (GIFT)"},{"id":"C","text":"Intra cytoplasmic sperm injection (ICSI)"},{"id":"D","text":"Intra-uterine insemination (IUI)"}]', 0, 'A', 'Correct Answer: (1) Zygote intra fallopian transfer (ZIFT)

Explanation:

Explanation:

ZIFT involves transferring a zygote or early embryo into the fallopian tube.

- Done after in vitro fertilisation

- Suitable for women with normal tubes

Why others are wrong:

- (2) GIFT: Transfers gametes, not zygote

- (3) ICSI: Injects sperm into egg, not a transfer method

- (4) IUI: Transfers sperms into uterus

CUET Tip: Recall assisted reproductive techniques.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (125, 'biology-2025-05-20-shift-1', 'q34', 34, 34, 'Cyclosporin A, which is used as an immunosuppressive agent, is produced by:', '[{"id":"A","text":"Staphylococcus"},{"id":"B","text":"Penicillium notatum"},{"id":"C","text":"Trichoderma polysporum"},{"id":"D","text":"Monascus purpureus"}]', 0, 'C', 'Solution:

Correct Answer: (3) Trichoderma polysporum

Explanation:

Cyclosporin-A, an immunosuppressant, is produced by T. polysporum.

- Used in organ transplant to prevent rejection

Why others are wrong:

- (1) Staphylococcus: It is the bacteria on which Alexander Fleming was doing experiment.

- (2) Penicillium notatum: Produces penicillin

- (4) Monascus purpureus: Produces statins

CUET Tip: Tabulate microbes and their products', NULL, 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
