INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (128, 'biology-2025-05-20-shift-1', 'q37', 37, 37, 'Choose the scientists associated with the antibiotic "Penicillin":

(A) Alexander Fleming

(B) James Watson

(C) Ernest Chain

(D) Howard Florey', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'D', 'Correct Answer: (4) (A), (C), and (D) only

