INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (137, 'biology-2025-05-20-shift-1', 'q46', 46, 46, '4. A piece of protein is introduced in a host bacterium', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Correct Answer: (3) A piece of DNA is introduced in a host bacterium

Explanation:

Transformation is a genetic engineering step where:

- Foreign DNA is introduced into a host bacterium

- Enables recombinant DNA technology

CUET Tip: Learn steps in genetic engineering.', 'pe27bdf6b7f6d', 'null', '[]', '[]', '[47]', 'keyed', '[]', '2026-11-05T20:58:38.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (138, 'biology-2025-05-20-shift-1', 'q47', 47, 47, '4. Fucose', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Correct Answer: (2) Agarose

Explanation:

Agarose gel electrophoresis is used to separate DNA fragments.

- Agarose is a seaweed-derived polymer

- DNA moves based on size and negative charge (due to phosphate groups), they are loaded into an agarose gel and subjected to an electric field, causing them to migrate toward the positive electrode (anode).

-The gel acts like a sieve, so smaller fragments move faster and travel farther than larger fragments.

-After the process, the separated DNA bands are made visible by staining the gel with compounds like ethidium bromide and viewing them under UV light.', 'p37a67e214fe4', 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (139, 'biology-2025-05-20-shift-1', 'q48', 48, 48, '4. Virus', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Correct Answer: (3) Fungal cells

Explanation:

DNA isolation requires specific enzymes based on the cell type:

- Chitinase is used to break down fungal cell walls (made of chitin)

- Other enzymes include:

- Lysozyme for bacterial cells

- Cellulase for plant cells

Why others are wrong:

- (1) Bacterial cells: Use lysozyme, not chitinase

- (2) Plant cells: Use cellulase

- (4) Virus: Do not require chitinase', 'pc3bdc7fde676', 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (140, 'biology-2025-05-20-shift-1', 'q49', 49, 49, '4. Origin of replication (ori)', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Correct Answer: (3) Recognition sequence

Explanation:

Restriction enzymes like Hind II cut DNA at specific recognition sequences.

- Hind II recognizes a six-base pair sequence

- Ensures precise DNA fragment generation for cloning

CUET Tip: Memorise cutting site concepts for restriction enzymes.', 'p404586f8a7d1', 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:38.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (141, 'biology-2025-05-20-shift-1', 'q50', 50, 50, '4. Palindromic nucleotide sequences', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4 Answer: D"}]', 0, 'D', 'Correct Answer: (4) Palindromic nucleotide sequence

Explanation:

Restriction endonucleases recognize palindromic sequences in DNA:

- These are sequences that read the same forward and backward on complementary strands

- Example: GAATTC (EcoRI recognition site)

CUET Tip: Identify sequence types relevant to DNA tools.', 'p25ab44e6d3eb', 'null', '[]', '[]', '[53]', 'keyed', '[]', '2026-11-05T20:58:38.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (142, 'biology-2025-05-20-shift-2', 'q01', 1, 1, 'A transcription unit in DNA is primarily comprised of:

(A) A Promoter

(B) Origin of replication

(C) The Structural gene

(D) A terminator', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(B), (C) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'D', '1. Correct Option: (4) (A), (C) and (D) only

A transcription unit in DNA comprises:

• Promoter (A): Site where RNA polymerase binds and initiates transcription.

• Structural gene (C): DNA sequence that gets transcribed into RNA.

• Terminator (D): Region that stops transcription.

Note: Origin of replication (B), is involved in DNA replication, not transcription.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (143, 'biology-2025-05-20-shift-2', 'q02', 2, 2, 'Health is a state of :', '[{"id":"A","text":"Economical fitness"},{"id":"B","text":"Physical, mental and social well-being"},{"id":"C","text":"Absence of disease"},{"id":"D","text":"Longevity"}]', 0, 'B', 'According to WHO (World Health Organization), health is a state of complete physical, mental, and social well-being, not merely the absence of disease. It emphasizes overall balance in body and mind.

Why Other Options Are Wrong:

(1) Economical fitness: Economic condition isn''t a direct measure of health.

(3) Absence of disease: Too narrow - health means more than just being disease-free.

(4) Longevity: Living long doesn''t guarantee being healthy; quality of life matters more.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (144, 'biology-2025-05-20-shift-2', 'q03', 3, 3, 'Which one of the followings is not the male sex accessory duct?', '[{"id":"A","text":"Rete testis"},{"id":"B","text":"Infundibulum"},{"id":"C","text":"Epididymis"},{"id":"D","text":"Vas deferens"}]', 0, 'B', 'The male sex accessory ducts include Rete testis, Epididymis, Vas deferens.

• Whereas, Infundibulum is part of female reproductive system, connects ovary to fallopian tube.

Why Other Options Are Wrong:

(1) Rete testis: Part of the male duct system inside the testis.

(3) Epididymis: Male accessory duct for sperm storage and maturation.

(4) Vas deferens: Male accessory duct carrying sperm from epididymis to urethra.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (145, 'biology-2025-05-20-shift-2', 'q04', 4, 4, 'The correct sequence of the formation of pollen grains is -

(A) Sporogenous tissue

(B) Formation of microspore

(C) Microspore tetrad formed by meiotic divisions

(D) Pollen grains develop from microspores', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', 'The correct sequence of formation of pollen grains is:

Sporogenous tissue (Microspore mother cell) → Microspore tetrad → Microspore → Pollen grains (male gametophyte)', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (146, 'biology-2025-05-20-shift-2', 'q05', 5, 5, 'The microbe involved in the production of citric acid is -', '[{"id":"A","text":"Acetobacter aceti"},{"id":"B","text":"Lactobacillus"},{"id":"C","text":"Aspergillus niger"},{"id":"D","text":"Clostridium butylicum"}]', 0, 'C', 'Aspergillus niger (a fungus) is used industrially to produce citric acid.

Why Other Options Are Wrong:', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (147, 'biology-2025-05-20-shift-2', 'q07', 6, 6, 'The unequivocal proof that DNA is the genetic material came from the experiments of -', '[{"id":"A","text":"Colin MacLeod and Maclyn McCarty"},{"id":"B","text":"Frederick Griffith"},{"id":"C","text":"Matthew Meselson and Franklin Stahl"},{"id":"D","text":"Alfred Hershey and Martha Chase"}]', 0, 'D', 'Hershey-Chase experiment (1952) used radioactive labeling of DNA and protein in bacteriophages → showed only DNA enters bacteria and directs viral reproduction, proving DNA is the genetic material.

Why Others Are Wrong:

• Option 1: Colin MacLeod and Maclyn McCarty → showed DNA from Streptococcus could transform bacteria, important but not unequivocal proof.

• Option 2: Frederick Griffith → discovered "transforming principle", but didn''t identify DNA as material.

• Option 3: Matthew Meselson and Franklin Stahl → proved semi-conservative replication of DNA, not its genetic role.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (148, 'biology-2025-05-20-shift-2', 'q08', 7, 7, 'RNA polymerase III is responsible for the transcription of -', '[{"id":"A","text":"rRNA"},{"id":"B","text":"hnRNA"},{"id":"C","text":"snRNA"},{"id":"D","text":"Triple stranded tRNA"}]', 0, 'C', 'RNA polymerase III transcribes small RNAs, including tRNA, 5S rRNA, and snRNA (small nuclear RNA). Why Others Are Wrong:', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (149, 'biology-2025-05-20-shift-2', 'q10', 8, 8, 'Pleiotropic genes are:', '[{"id":"A","text":"Polygenes"},{"id":"B","text":"Complementary genes"},{"id":"C","text":"Genes with multiple phenotypic expression"},{"id":"D","text":"Genes with single phenotypic expression"}]', 0, 'C', '• Pleiotropy occurs when one gene influences multiple, seemingly unrelated traits (e.g., sickle cell gene affects blood shape, anemia, and resistance to malaria).

Why Others Are Wrong:

• Option 1: Polygenes $ \rightarrow $ many genes contribute to a single trait (opposite of pleiotropy).

• Option 2: Complementary genes → two genes work together to produce a trait.

• Option 4: Genes with single phenotypic expression → opposite of pleiotropic genes.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (150, 'biology-2025-05-20-shift-2', 'q11', 9, 9, 'Point out the technique, which is not useful for the detection of cancer of internal organs.', '[{"id":"A","text":"X-rays"},{"id":"B","text":"DNA fingerprinting"},{"id":"C","text":"Computed tomography"},{"id":"D","text":"Magnetic resonance imaging"}]', 0, 'B', '- DNA fingerprinting identifies individual genetic profiles; it cannot detect tumors or internal organ cancers.

Why Others Are Wrong:

• Option 1: X-rays $ \rightarrow $ can detect abnormal masses or tumors.

• Option 3: Computed tomography (CT) → provides detailed images of internal organs, useful for cancer detection.

• Option 4: Magnetic resonance imaging (MRI) → excellent for soft tissue imaging, helps detect internal cancers.', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (151, 'biology-2025-05-20-shift-2', 'q12', 10, 10, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (Ⅳ), (B) - (Ⅲ), (C) - (Ⅱ), (D) - (Ⅰ)"},{"id":"C","text":"(A) - $ (\\mathrm{II}) $, (B) - $ (\\mathrm{I}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{III}) $"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', '• Homology (A) → similarity due to common ancestry → forelimbs of mammals (IV).

• Analogy (B) → similarity due to common function/habitat, not ancestry → wings of birds & butterflies (III).

• Convergent evolution (C) → unrelated organisms evolve similar traits → wings of birds and butterflies (II).

• Divergent evolution (D) → organisms from common ancestor evolve different traits → forelimbs of mammals (I).', NULL, 'null', '[]', '[{"id":"q12-table-1","kind":"table","path":"/local-papers/assets/biology-2025-05-20-shift-2/q12-table-1.jpg","page":8,"alt":"Table for question 12"}]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (152, 'biology-2025-05-20-shift-2', 'q13', 11, 11, 'Which one of the mentioned reasons does not cause the loss of biodiversity?', '[{"id":"A","text":"Habitat loss and fragmentation"},{"id":"B","text":"Alien species invasions"},{"id":"C","text":"Aforestation"},{"id":"D","text":"Co-extinctions"}]', 0, 'C', '• Aforestation (planting trees in barren areas) increases biodiversity, does not cause its loss.

Why Others Are Wrong:

• Option 1: Habitat loss and fragmentation → destroys ecosystems → reduces biodiversity.

• Option 2: Alien species invasions → outcompete native species → loss of biodiversity.

• Option 4: Co-extinctions → extinction of one species causes dependent species to go extinct → reduces biodiversity.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (153, 'biology-2025-05-20-shift-2', 'q14', 12, 12, 'The components of the ecosystem are seen to function as a unit when you consider the following aspects -

(A) Productivity

(B) Decomposition

(C) Energy flow

(D) Nutrient cycling', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', '• All these aspects show ecosystem components function together as a unit:

o Productivity (A): energy capture by producers.

o Decomposition (B): breaks down organic matter.

o Energy flow (C): transfers energy through trophic levels.

Nutrient cycling (D): recycling of elements like C, N, P.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (154, 'biology-2025-05-20-shift-2', 'q15', 13, 13, 'Typical embryo sac at maturity is:', '[{"id":"A","text":"7 nucleate, 8 celled structure"},{"id":"B","text":"8 nucleate, 7 celled structure"},{"id":"C","text":"4 nucleate, 6 celled structure"},{"id":"D","text":"8 nucleate, 6 celled structure"}]', 0, 'B', 'Mature embryo sac (female gametophyte) of angiosperms has 8 nuclei arranged in 7 cells.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (155, 'biology-2025-05-20-shift-2', 'q17', 14, 14, 'Identify, which is not the sexually transmitted infection?

Identity, which is not the sexually transmitted infection?', '[{"id":"A","text":"Chlamydiasis"},{"id":"B","text":"Trichomoniasis"},{"id":"C","text":"Rheumatoid arthritis"},{"id":"D","text":"Syphilis"}]', 0, 'C', '• Rheumatoid arthritis is an autoimmune disease, not sexually transmitted.

Why Others Are Wrong:

• Option 1: Chlamydiasis → caused by Chlamydia trachomatis, sexually transmitted.

Option 4: Syphilis $ \rightarrow $ caused by Treponema pallidum, sexually transmitted.', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (156, 'biology-2025-05-20-shift-2', 'q18', 15, 15, 'The disease phenylketonuria is caused by mutation in the gene that codes for -', '[{"id":"A","text":"Phenylalanine dehydrogenase"},{"id":"B","text":"Phenylalanine carboxylase"},{"id":"C","text":"Phenylalanine hydroxylase"},{"id":"D","text":"Phenylalanine hydrogenase"}]', 0, 'C', '- Phenylketonuria (PKU) is caused by mutation in the PAH gene, which codes for phenylalanine hydroxylase, leading to accumulation of phenylalanine and mental retardation if untreated.

Why Others Are Wrong:

• Option 1: Phenylalanine dehydrogenase $ \rightarrow $ enzyme does not exist in this pathway.

• Option 2: Phenylalanine carboxylase → incorrect enzyme.

• Option 4: Phenylalanine hydrogenase $ \rightarrow $ wrong; not involved in phenylalanine metabolism.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (157, 'biology-2025-05-20-shift-2', 'q19', 16, 16, 'Which of the following free living soil microorganisms are used as biofertilisers?

(A) Anabaena

(B) Azospirillum

(C) Rhizobium

(D) Azotobacter', '[{"id":"A","text":"(B) and (C) only"},{"id":"B","text":"(A) and (B) only"},{"id":"C","text":"(C) and (D) only"},{"id":"D","text":"(B) and (D) only"}]', 0, 'D', '• Azospirillum (B) and Azotobacter (D) are free-living nitrogen-fixing soil bacteria, used as biofertilisers to enrich soil nitrogen.

• Rhizobium is symbiotic, not free-living.

Anabaena is mostly aquatic, not typical soil biofertiliser.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (158, 'biology-2025-05-20-shift-2', 'q20', 17, 17, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"B","text":"(A) - $ (\\mathrm{I}\\mathrm{II}) $, (B) - $ (\\mathrm{IV} $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"},{"id":"C","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{IV}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{III}) $"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{II}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{IV}) $"}]', 0, 'B', '• Pectinases and proteases (A) → used to clarify bottled juices (III)
• Streptokinase (B) → acts as a clot buster (IV)
• Lipases (C) → used for removing oily stains (I)
• Cyclosporin A (D) → immunosuppressive agent (II)', NULL, 'null', '[]', '[{"id":"q20-table-1","kind":"table","path":"/local-papers/assets/biology-2025-05-20-shift-2/q20-table-1.jpg","page":14,"alt":"Table for question 20"}]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (159, 'biology-2025-05-20-shift-2', 'q21', 18, 18, 'Arrange the given structures formed during spermatogenesis in correct sequence.

(A) Spermatozoa

(B) Secondary spermatocytes

(C) Spermatids

(D) Spermatogonia', '[{"id":"A","text":"(D), (B), (C), (A)"},{"id":"B","text":"(A), (B), (C), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(D), (C), (B), (A)"}]', 0, 'A', '• Spermatogenesis sequence:

1. Spermatogonia (D) → mitotic division

2. Secondary spermatocytes (B) → after meiosis I

3. Spermatids (C) → after meiosis II

4. Spermatozoa (A) → mature, motile sperm', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (160, 'biology-2025-05-20-shift-2', 'q22', 19, 19, 'Groups of individuals in a well-defined geographical area, sharing or competing for similar resources, having the potential to interbreed, are the characteristics of :', '[{"id":"A","text":"Biomass"},{"id":"B","text":"Communities"},{"id":"C","text":"Populations"},{"id":"D","text":"Organisms"}]', 0, 'C', '• A population is a group of individuals of the same species in a defined area, sharing resources and capable of interbreeding.

Why Others Are Wrong:

• Option 1: Biomass $ \rightarrow $ total mass of living matter, not a group of interbreeding individuals.

• Option 2: Communities → all populations of different species in an area.

• Option 4: Organisms → refers to single individuals, not a group.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (161, 'biology-2025-05-20-shift-2', 'q23', 20, 20, 'Which one of the given sacred groves is not found in Madhya Pradesh?', '[{"id":"A","text":"Sarguja"},{"id":"B","text":"Jaintia hills"},{"id":"C","text":"Chanda"},{"id":"D","text":"Bastar"}]', 0, 'B', '• Jaintia Hills are located in Meghalaya, not Madhya Pradesh.

Why Others Are Wrong:

• Option 1: Sarguja → in Chhattisgarh (close to MP), considered part of central India sacred groves.

• Option 3: Chanda → in Maharashtra/central India region.

Option 4: Bastar $ \rightarrow $ in Chhattisgarh, central India sacred groves region.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (162, 'biology-2025-05-20-shift-2', 'q24', 21, 21, 'Arrange the given stages of menstrual cycle in correct sequence.

(A) Luteal phase

(B) Follicular phase

(C) Menstruation

(D) Next cycle begins', '[{"id":"A","text":"(A),(B),(C),(D)"},{"id":"B","text":"(B),(A),(D),(C)"},{"id":"C","text":"(C),(B),(A),(D)"},{"id":"D","text":"(D),(C),(A),(B)"}]', 0, 'C', '• Menstrual cycle sequence:

1. Menstruation (C) → shedding of endometrium

2. Follicular phase (B) $ \rightarrow $ follicle maturation, estrogen secretion

3. Luteal phase (A) $ \rightarrow $ corpus luteum formation, progesterone secretion

4. Next cycle begins (D) → if no fertilization, cycle restarts', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (163, 'biology-2025-05-20-shift-2', 'q25', 22, 22, 'Which one of the following features of pea plant is not suitable for genetic studies?', '[{"id":"A","text":"Stem height"},{"id":"B","text":"Flower position"},{"id":"C","text":"Pod colour"},{"id":"D","text":"Stem tendril"}]', 0, 'D', '• Stem tendril shows continuous variation influenced by environment → not ideal for Mendelian/genetic studies, which require discrete traits.

Why Others Are Wrong:

• Option 1: Stem height → Mendel used it as a discrete trait (tall/dwarf).

• Option 2: Flower position → discrete trait (axial/terminal).

• Option 3: Pod colour → discrete trait (green/yellow).', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (164, 'biology-2025-05-20-shift-2', 'q27', 23, 23, 'Match List-I with List-II', '[{"id":"A","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) - (\\mathrm{II}) $, $ (\\mathrm{C}) - (\\mathrm{III}) $, $ (\\mathrm{D}) - (\\mathrm{IV}) $"},{"id":"B","text":"(A) - $ (\\mathrm{IV}) $, $ (\\mathrm{B}) - (\\mathrm{III}) $, $ (\\mathrm{C}) - (\\mathrm{II}) $, $ (\\mathrm{D}) - (\\mathrm{I}) $"},{"id":"C","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{II}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{I}) $"},{"id":"D","text":"(A) - $ (\\mathrm{II}) $, $ (\\mathrm{B}) - (\\mathrm{I}) $, $ (\\mathrm{C}) - (\\mathrm{IV}) $, $ (\\mathrm{D}) - (\\mathrm{III}) $"}]', 0, 'B', '• Homologous organs (A) → show divergent evolution (IV) from a common ancestor.

• Analogous organs (B) → show convergent evolution (III) due to similar functions.

• Vestigial organs (C) → result of retrogressive evolution (II), losing original function.

• Saltation (D) → mutation-caused speciation (I), i.e., sudden evolutionary change.', NULL, 'null', '[]', '[{"id":"q27-table-1","kind":"table","path":"/local-papers/assets/biology-2025-05-20-shift-2/q27-table-1.jpg","page":19,"alt":"Table for question 27"}]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (165, 'biology-2025-05-20-shift-2', 'q28', 24, 24, 'A molecule that can act as the genetic material must fulfill all the mentioned criteria except one which is incorrect.', '[{"id":"A","text":"It should be able to generate its replica (replication)."},{"id":"B","text":"It should be able to express itself in the form of Mendelian characters."},{"id":"C","text":"It should not provide the scope for slow changes (mutation) that are required for evolution."},{"id":"D","text":"It should be stable chemically and structurally."}]', 0, 'C', 'Genetic material must allow mutations for evolution. Hence, saying it should not provide scope for mutations is incorrect.

Why Others Are Correct:

Option (1): Enables replication, essential for inheritance.

Option (2): Allows expression of traits (Mendelian characters).

Option (4): Ensures chemical and structural stability of genetic material.', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (166, 'biology-2025-05-20-shift-2', 'q29', 25, 25, 'In a typical microsporangium, the function of tapetum is -', '[{"id":"A","text":"Nourishment to developing ovules"},{"id":"B","text":"Nourishment to developing stigma"},{"id":"C","text":"Nourishment to developing pollen grains"},{"id":"D","text":"Nourishment to developing thalamus"}]', 0, 'C', 'Tapetum is the innermost nutritive layer of the microsporangium. It supplies nutrients, enzymes, and materials required for the development of microspores (pollen grains).

Why Others Are Wrong:

Option (1): Ovules are nourished by nucellus and integuments, not tapetum.

Option (2): Stigma receives pollen, not nourishment from tapetum.

Option (4): Thalamus supports floral whorls, unrelated to microsporangium nourishment.', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (167, 'biology-2025-05-20-shift-2', 'q30', 26, 26, 'Which one of the following approaches does not belong to ex situ conservation strategy?', '[{"id":"A","text":"Zoological parks"},{"id":"B","text":"Wildlife sanctuaries"},{"id":"C","text":"Botanical gardens"},{"id":"D","text":"Wildlife safari parks"}]', 0, 'B', 'Ex situ conservation involves protecting threatened species outside their natural habitat, e.g., in zoos, botanical gardens, or gene banks. Wildlife sanctuaries conserve species within their natural habitats, hence they are in situ, not ex situ.

Why Others Are Correct:

Option (1): Zoological parks $ \rightarrow $ Ex situ; animals conserved outside natural habitat.

Option (3): Botanical gardens $ \rightarrow $ Ex situ; plants grown and preserved under controlled conditions.

Option (4): Wildlife safari parks $ \rightarrow $ Ex situ; animals kept in semi-natural conditions for protection and awareness', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (168, 'biology-2025-05-20-shift-2', 'q31', 27, 27, 'The density of a population in a given habitat during a given period fluctuates due to changes in:

(A) Natality

(B) Emigration

(C) Immigration

(D) Mortality', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (B), (C), (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', 'Population density changes due to all four factors:

- Natality (A): adds individuals.

- Mortality (D): removes individuals.

- Immigration (C): adds individuals from outside.

- Emigration (B): removes individuals moving out.', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (169, 'biology-2025-05-20-shift-2', 'q32', 28, 28, 'The female reproductive system consists of:

(A) Ovaries

(B) External genital

(C) Cervix and vagina

(D) Oviducts and uterus', '[{"id":"A","text":"(A), (B), (C) and (D)"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A) and (D) only"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'A', 'The female reproductive system includes:

• Ovaries (A): produce eggs and hormones.

• External genitalia (B): protect internal organs and facilitate copulation.

• Cervix and vagina (C): cervix connects uterus to vagina; vagina receives sperm and serves as birth canal.

• Oviducts and uterus (D): oviducts transport eggs; uterus supports embryo development.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (170, 'biology-2025-05-20-shift-2', 'q33', 29, 29, 'Verhulst-Pearl logistic growth equation can be represented by -', '[{"id":"A","text":"dt/dN = rN(K-N/K)"},{"id":"B","text":"dN/dt = rK(K-N/K)"},{"id":"C","text":"dN/dt = rN(K-N/K)"},{"id":"D","text":"dN/dt = rN(N-K/N)"}]', 0, 'C', 'The Verhulst-Pearl logistic growth equation models population growth considering carrying capacity (K):

$ \frac{dN}{dt}=rN(1-\frac{N}{K}) $

- r = intrinsic growth rate

- N = population size

- K = maximum sustainable population

It shows that growth slows as N approaches K.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (171, 'biology-2025-05-20-shift-2', 'q34', 30, 30, 'Identify the incorrect statement in reference to the latitudinal gradient in biodiversity.', '[{"id":"A","text":"In general, species diversity decreases as we move away from the equator towards the poles."},{"id":"B","text":"The largely tropical Amazonian rain forest in South America has the greatest biodiversity on earth."},{"id":"C","text":"A forest in a tropical region like Ecuador has up to 10000 times as many species of vascular plants as a forest of equal area in a temperate region like the Midwest of the USA."},{"id":"D","text":"With very few exceptions, tropics harbor more species than temperate or polar areas."}]', 0, 'C', 'The latitudinal gradient shows species diversity decreases gradually from equator to poles. The claim of 10,000 times more species is grossly exaggerated; tropical forests are richer by 10 times.

Why Others Are Correct:

Option (1): True, diversity generally decreases from equator to poles.

Option (2): True, Amazon rainforest is the most biodiverse terrestrial ecosystem.

Option (4): True, tropics harbor far more species than temperate or polar regions, with few exceptions.', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (172, 'biology-2025-05-20-shift-2', 'q35', 31, 31, 'Medical termination of pregnancy is considered relatively safe -', '[{"id":"A","text":"Upto 24 weeks of pregnancy"},{"id":"B","text":"Upto 18 weeks of pregnancy"},{"id":"C","text":"Upto 12 weeks of pregnancy"},{"id":"D","text":"Upto 30 weeks of pregnancy"}]', 0, 'C', 'Medical termination of pregnancy (MTP) using drugs is considered relatively safe during the first trimester (up to 12 weeks). After this period, procedures become more complex and riskier.

Why Others Are Wrong:

Option (1): Up to 24 weeks → Beyond first trimester, surgical intervention is riskier; not "relatively safe" medically.

Option (2): Up to 18 weeks → Exceeds safe limit for standard medical abortion.

Option (4): Up to 30 weeks → Late pregnancy terminations are complex, unsafe, and usually surgical only.', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.513Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (173, 'biology-2025-05-20-shift-2', 'q36', 32, 32, 'The rate of production of organic matter during photosynthesis is defined as -', '[{"id":"A","text":"Quaternary productivity"},{"id":"B","text":"Secondary productivity"},{"id":"C","text":"Net primary productivity"},{"id":"D","text":"Gross primary productivity"}]', 0, 'D', 'Gross primary productivity (GPP) is the total rate of production of organic matter by plants through photosynthesis in a given time.

Why Others Are Wrong:

Option (1): Quaternary productivity $ \rightarrow $ Refers to energy transfer in the 4th trophic level, not photosynthesis.

Option (2): Secondary productivity $ \rightarrow $ Production of organic matter by consumers, not producers.

Option (3): Net primary productivity $ \rightarrow $ GPP minus plant respiration; represents energy available to consumers, not total production.', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.514Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (174, 'biology-2025-05-20-shift-2', 'q39', 33, 33, 'Decomposers break down complex organic matter into', '[{"id":"A","text":"Inorganic substances like O₂, H₂O and CO₂"},{"id":"B","text":"Inorganic substances like CO₂, H₂O and nutrients"},{"id":"C","text":"Inorganic substances like O₂, H₂S and nutrients"},{"id":"D","text":"Inorganic substances like N₂, H₂O and CO₂"}]', 0, 'B', 'Decomposers (bacteria and fungi) break down dead organic matter into simple inorganic compounds like carbon dioxide, water, and mineral nutrients, making them available for plants.

Why Others Are Wrong:

Option (1): O₂ is not a product of decomposition; it is consumed.

Option (3): H₂S is produced only in anaerobic decomposition of sulfur-containing compounds, not general.

Option (4): N₂ is generally not released; nitrogen is mineralized to ammonium or nitrates.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.514Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (175, 'biology-2025-05-20-shift-2', 'q40', 34, 34, 'The sedative & painkiller drug useful for the patients who have undergone surgery is-', '[{"id":"A","text":"Barbiturates"},{"id":"B","text":"Morphine"},{"id":"C","text":"Amphitamines"},{"id":"D","text":"Cocaine"}]', 0, 'B', 'Morphine is a potent opioid analgesic used to relieve severe pain and has sedative properties, making it useful for post-surgical patients.

Why Others Are Wrong:

Option (1): $ Barbiturates \rightarrow $ Mainly sedatives/hypnotics, not strong painkillers.

Option (3): Amphetamine $ \rightarrow $ Stimulants; increase alertness, not for pain relief.

Option (4): Cocaine $ \rightarrow $ Local anesthetic; rarely used systemically for post-surgery pain due to toxicity.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.515Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (176, 'biology-2025-05-20-shift-2', 'q41', 35, 35, '4. Strict quality control testing', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Downstream processing involves separation, purification, formulation, and quality control of a product after production. Clinical trials are part of drug development, not downstream processing.

Why Others Are Wrong:

Option (1): Separation and purification → Core part of downstream processing.

Option (2): Product formulation with preservatives → Done during downstream processing for stability.

Option (4): Strict quality control testing → Essential to ensure product safety and efficacy.', 'p80dd4b0f47a2', 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.515Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (177, 'biology-2025-05-20-shift-2', 'q42', 36, 36, '4. Ethidium bromine', '[{"id":"A","text":"Ethidium bromate"},{"id":"B","text":"Ethidium chloride"},{"id":"C","text":"Ethidium bromide"},{"id":"D","text":"Ethidium bromine"}]', 0, 'C', 'Ethidium bromide (EtBr) intercalates between DNA bases and fluoresces under UV light, allowing DNA fragments to be visualized in agarose gel electrophoresis.', 'p4370964439cb', 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.515Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (178, 'biology-2025-05-20-shift-2', 'q43', 37, 37, 'In the nomenclature of restriction enzymes —', '[{"id":"A","text":"The first letter of the name from the species and the second two letters from the different species of the prokaryotic cell"},{"id":"B","text":"The first two letter of the name from the genus and the third letter from the species of the prokaryotic cell"},{"id":"C","text":"The first letter of the name from the species and the second two letters from the genus of the prokaryotic cell"},{"id":"D","text":"The first letter of the name from the genus and the second two letters from the species of the prokaryotic cell"}]', 0, 'D', 'Restriction enzymes are named based on their source organism:

• First letter: Genus

• Next two letters: Species

• Followed by strain designation and Roman numeral if multiple enzymes exist.', 'pf0161062fcfb', 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (179, 'biology-2025-05-20-shift-2', 'q44', 38, 38, '4. Thermas aquaticus', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Taq polymerase, a thermostable DNA polymerase used in PCR, is isolated from the bacterium Thermus aquaticus, which thrives in hot springs.', 'p45ed34429892', 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (180, 'biology-2025-05-20-shift-2', 'q45', 39, 39, '4. Buffer', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'DNA is negatively charged due to its phosphate backbone. In agarose gel electrophoresis, DNA fragments migrate towards the positively charged anode under an electric field.

Why Others Are Wrong:

Option (1): Cathode → Negatively charged; DNA moves away from cathode.

Option (3): Matrix → The agarose matrix supports migration, but DNA doesn''t move "towards" it.

Option (4): Buffer → Provides ionic environment, not a direction for DNA migration.', 'p9f56f2ed4267', 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (181, 'biology-2025-05-20-shift-2', 'q48', 40, 40, '4. Adenosine deaminase deficiency', '[{"id":"A","text":"Phenylketonuria"},{"id":"B","text":"Emphysema"},{"id":"C","text":"Cystic fibrosis"},{"id":"D","text":"Adenosine deaminase deficiency"}]', 0, 'B', 'α-1-antitrypsin protects lung tissue from enzymatic damage. Its deficiency leads to emphysema. Transgenic animals producing human α-1-antitrypsin provide a therapeutic source for patients.

Why Others Are Wrong:

Option (1): Phenylketonuria → Treated by dietary management or enzyme therapy, not α-1-antitrypsin.

Option (3): Cystic fibrosis → Caused by CFTR gene mutation; α-1-antitrypsin is unrelated.

Option (4): Adenosine deaminase deficiency → Treated by enzyme replacement or gene therapy, not α-1-antitrypsin.', 'pa224766a7d90', 'null', '[]', '[]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (182, 'biology-2025-05-20-shift-2', 'q49', 41, 41, '4. Diphosphate', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Insulin consists of two polypeptide chains (A and B) linked by two disulphide (-S-S-) bridges, with an additional intrachain disulphide bond in the A chain. These bonds are crucial for its structural stability and biological activity.

Why Others Are Wrong:

Option (1): Dimethyl $ \rightarrow $ Not involved in linking insulin chains.

Option (3): Dipropyl $ \rightarrow $ Incorrect chemical; not present in proteins.

Option (4): Diphosphate $ \rightarrow $ Phosphate groups are not responsible for linking insulin chains.', 'pf1674eee98dc', 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.517Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (183, 'biology-2025-05-20-shift-2', 'q50', 42, 42, '4. Commercialization', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Biopiracy occurs when companies or individuals patent biological resources or traditional knowledge from another country without proper authorization or benefit sharing. The Basmati rice case exemplifies this.

Why Others Are Wrong:

Option (1): Competitive market $ \rightarrow $ Relates to business competition, not misuse of genetic resources.

Option (2): Bioresources $ \rightarrow $ Refers to natural resources; does not imply exploitation.

Option (4): Commercialization $ \rightarrow $ Selling or marketing a product; biopiracy is a legal/ethical issue, not just commercialization.', 'pe66fe2cfa0e3', 'null', '[]', '[]', '[36]', 'keyed', '[]', '2026-11-05T20:58:38.517Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (184, 'chemistry-2025-05-21-shift-2', 'q01', 1, 1, 'What is the mass percentage of NaCl in the solution if 1.75g of NaCl is dissolved in 5.85g of water.', '[{"id":"A","text":"23.02"},{"id":"B","text":"29.9"},{"id":"C","text":"23.98"},{"id":"D","text":"25.00"}]', 0, 'A', 'Solution - Mass percentage of a component of a solution is defined as:

$$ Mass~percentage=\frac{Mass~of~the~component~in~the~solution}{Total~mass~of~the~solution}\times100 $$

For mass percentage of NaCl in solution, it is given

Mass of NaCl = 1.75g (Mass of component)

Mass of water = 5.85g

Total mass of the solution = 1.75 + 5.85 = 7.60 g

Therefore, Mass percentage of NaCl = $ (1.75 \div 7.60) \times 100 = 23.02\% $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (185, 'chemistry-2025-05-21-shift-2', 'q02', 2, 2, 'The aqueous solutions of the following salts were electrolyzed for 30 min with a current of 20 amp. Arrange the following in the following order of the amount of metal distributed at the entails.

following in the increasing order of the amount of metal deposited at the cathode.

(A) WCl_{6}

(B) ZnSO_{4}

(C) $ \mathrm{HfCl_{4}} $

(D) AgNO_{3}

(Atomic mass of: W = 184 u, Zn = 65 u, Hf = 178 u and Ag = 108 u)', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(B), (A), (C), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(D), (C), (B), (A)"}]', 0, 'A', 'Solution - According to Faraday''s second law of Electrolysis: The amounts of different substances liberated by the same quantity of electricity passing through the electrolytic solution are proportional to their chemical equivalent weights (Atomic Mass of Metal ÷ Number of electrons required to reduce the cation). Aqueous solutions of salts were electrolyzed for 30 mins with a current of 20 amp.

Given, atomic mass of W = 184 u, Zn = 65 u, Hf = 178 u, Ag = 108 u

The mass deposited is proportional to the ratio of the molar mass to the number of electrons per ion. Amount of metal deposited in each case is:

For $ WCl_{6}\&c $: $ \frac{184}{6} = 30.6 $ u

For $ ZnSO_{4}\&c $: $ \frac{65}{2} = 32.5 $ u

For $ HfCl_{4}\&c $: $ \frac{178}{4} = 44.5 $ u

For $ AgNO_{3}\&c $: $ \frac{108}{1} = 108 $ u

Increasing order of the amount of metal deposited at the cathode (A) < (B) < (C) < (D)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (186, 'chemistry-2025-05-21-shift-2', 'q03', 3, 3, 'How much current is needed to pass for 1 sec for depositing a metal with a mass equal to double of its electrochemical equivalent?', '[{"id":"A","text":"1 amp"},{"id":"B","text":"2 amp"},{"id":"C","text":"4 amp"},{"id":"D","text":"0.5 amp"}]', 0, 'B', 'Solution- According to Faraday''s first Law of Electrolysis:

The amount of chemical reaction which occurs at any electrode during electrolysis by a current is proportional to the quantity of electricity passed through the electrolyte (solution or melt).

where, m = mass of substance deposited

$ \mathbf{Z} = \text{electrochemical equivalent} $

I = current in ampere

t = time in secs

To deposit a metal with mass equal to double of its electrochemical equivalent,

it is given

m = 2 $ \times $ Z

t = 1 sec

substituting these values in equation

m = Zit

2 $ \times $ Z = Z $ \times $ I $ \times $ 1

Solving this we get, I (current needed) = 2 amp', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (187, 'chemistry-2025-05-21-shift-2', 'q05', 4, 4, 'Which of the following amine do not respond to Hinsberg test?', '[{"id":"A","text":"Aniline"},{"id":"B","text":"N-Methyl aniline"},{"id":"C","text":"N,N-Dimethyl aniline"},{"id":"D","text":"o-Toluidine"}]', 0, 'C', 'Benzenesulphonyl chloride (C_6H_5SO_2Cl) which is also known as Hinsberg''s reagent, reacts with primary and secondary amines to form sulphonamides. Tertiary amines do not react with benzenesulphonyl chloride. This property of amines reacting with benzenesulphonyl chloride in a different manner is used for the distinction of primary, secondary and tertiary amines and also for the separation of a mixture of amines.

N, N-dimethylaniline is an example of tertiary amine so it doesn''t respond to Hinsberg Test.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (188, 'chemistry-2025-05-21-shift-2', 'q06', 5, 5, 'Match List-I with List-II', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)"},{"id":"C","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"},{"id":"D","text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"}]', 0, 'C', 'Primary aromatic amines form arene diazonium salts which are stable for a short time in solution at low temperatures.

In coupling reaction, an aromatic diazonium salt and an activated aromatic compound (like phenol or aniline) to form an azo compound $ (-N=N-) $. Coupling reaction of aryldiazonium salts with phenols or arylamines give rise to the formation of azo dyes

Alphatic and aromatic primary amines on heating with chloroform and ethanoic potassium hydroxide form isocyanides or carbylamine which are foul smelling substances. Secondary and tertiary amines do not show this reaction.

Hoffmann developed a method for preparation of primary amines by treating an amide with bromine in an aqueous or ethanolic solution of sodium hydroxide. It is an conversion of amide to amine.

Coupling reaction - phenols and aromatic amines

Hofmann''s Degradation - Amide to amine

Isocyanide Test - Primary amines

Diazonium Salts - Aromatic amines', NULL, 'null', '[]', '[{"id":"q06-table-1","kind":"table","path":"/local-papers/assets/chemistry-2025-05-21-shift-2/q06-table-1.jpg","page":4,"alt":"Table for question 6"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (189, 'chemistry-2025-05-21-shift-2', 'q07', 6, 6, 'Toluene on chlorination in presence of UV light gives', '[{"id":"A","text":"Benzyl Chloride"},{"id":"B","text":"Benzal Chloride"},{"id":"C","text":"p-Chlorotoluene"},{"id":"D","text":"o-Chlorotoluene"}]', 0, 'B', 'Toluene on chlorination in presence of UV light gives Benzal Chloride

Side chain chlorination of toluene gives benzal chloride

Toluene

Benzal chloride', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (190, 'chemistry-2025-05-21-shift-2', 'q09', 7, 7, 'Which of the following compounds will respond to iodoform test?

(A) Acetone

(B) Ethyl methyl ketone

(C) Acetophenone

(D) Pentan-2-one', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', 'iodoform reaction with sodium hypioidite is also used for detection of $ CH_{3}CO $ group or $ CH_{3}CH(OH) $ group which produces $ CH_{3}CO $ group on oxidation. A positive result is indicated by the formation of yellow precipitate of iodoform.

Pentan-2-one, acetone, acetophenone, and ethyl methyl ketone are all positive for the iodoform test, meaning they will produce a yellow precipitate of iodoform.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (191, 'chemistry-2025-05-21-shift-2', 'q10', 8, 8, 'The compound resistant to oxidation is', '[{"id":"A","text":"Carbonic acid"},{"id":"B","text":"t-Butanol"},{"id":"C","text":"Ethyl alcohol"},{"id":"D","text":"Methyl alcohol"}]', 0, 'B', 'Oxidation of alcohols involves the formation of a carbon oxygen double bond with cleavage of an O-H and C-H bonds. Tertiary alcohols do not undergo oxidation reaction

t-butanol being a tertiary alcohol is resistant to oxidation', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (192, 'chemistry-2025-05-21-shift-2', 'q11', 9, 9, 'The final product of 1-chlorobutane and 2-chlorobutane when treated in KOH (alcohol) gives:', '[{"id":"A","text":"1-butene"},{"id":"B","text":"3-butene"},{"id":"C","text":"Both 1-butene & 2-butene"},{"id":"D","text":"2-butene"}]', 0, 'C', 'When a haloalkane with beta-hydrogen atom is heated with alcoholic solution of potassium hydroxide, there is elimination of hydrogen atom from beta-carbon and a halogen atom from the alpha-carbon atom. As a result, an alkene is formed as a product. Since beta-hydrogen atom is involved in elimination, it is often called beta-elimination.

In mixture of 1-chlorobutane and 2-chlorobutane when treated with KOH (alcohol) elimination reaction occurs and it gives both but-1-ene and but-2-ene.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (193, 'chemistry-2025-05-21-shift-2', 'q12', 10, 10, 'Vitamin B12 is a coordination compound of _

Vitamin B12 is a coordination compound of', '[{"id":"A","text":"Cu"},{"id":"B","text":"Fe"},{"id":"C","text":"Mg"},{"id":"D","text":"Co"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (194, 'chemistry-2025-05-21-shift-2', 'q13', 11, 11, 'The reduction of cyclohexanone with LiAlH_{4} will give:', '[{"id":"A","text":"Cyclohexanol"},{"id":"B","text":"Cyclohexanaldehyde"},{"id":"C","text":"Benzoic acid"},{"id":"D","text":"Phenol"}]', 0, 'A', 'Aldehydes and ketones are reduced to primary and secondary alcohols respectively by sodium borohydride (NaBH $ _{4} $) or lithium aluminum hydride (LiAlH $ _{4} $) as well as by catalytic hydrogenation. Aldehydes yield primary alcohols whereas ketones give secondary alcohols.

$$ \mathrm{R}-\mathrm{C(=O)-R^{\prime}}\xrightarrow{\mathrm{NaBH}_{4}}\mathrm{R}-\mathrm{CH(OH)-R^{\prime}} $$

When cyclohexanone is treated with lithium aluminium hydride it will give cyclohexanol. Carbonyl group is converted to secondary alcohol OH group', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (195, 'chemistry-2025-05-21-shift-2', 'q14', 12, 12, 'On the basis of following observations arrange the following compounds in increasing order of mol of AgCl

precipitated per mol of the compound with excess of AgNO_{3}', '[{"id":"A","text":"(C),(A),(B),(D)"},{"id":"B","text":"(B),(C),(A),(D)"},{"id":"C","text":"(C), (A), (D), (B)"},{"id":"D","text":"(D, (A),(C),(B)"}]', 0, 'B', 'According to Werner''s theory:

Conductivity and secondary valences tell which chlorides are inside the coordination sphere (non-reactive) and which are ionic (free, react with $ Ag^{+} $ to give AgCl).

PdCl_{2}.4NH_{3} has secondary valency of 4 and has 2 Chloride ions outside the coordination sphere so it will give 2 mol of AgCl

NicI_{4}.2K has no chloride ions outside the coordination sphere so it will give no mol of AgCl

CocI_{3}.4NH_{3} has 1 chloride ion outside the coordination sphere so it will give 1 mol of AgCl

CrCl_{3}.6H_{2}O will give 3 mol of AgCl

So, increasing order B, C, A, D', NULL, 'null', '[]', '[{"id":"q14-table-1","kind":"table","path":"/local-papers/assets/chemistry-2025-05-21-shift-2/q14-table-1.jpg","page":8,"alt":"Table for question 14"}]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (196, 'chemistry-2025-05-21-shift-2', 'q16', 13, 13, 'Which type of amine produces N2 when treated with HONO', '[{"id":"A","text":"Primary amine"},{"id":"B","text":"Secondary amine"},{"id":"C","text":"Tertiary amine"},{"id":"D","text":"Quaternary ammonium salt"}]', 0, 'A', 'Primary aliphatic amines react with nitrous acid to form aliphatic diazonium salts which being unstable, liberate nitrogen gas quantitatively and alcohols. Quantitative evolution of nitrogen is used in estimation of amino acids and proteins

$$ \mathrm{R-NH_{2}+HNO_{2}\xrightarrow{NaNO_{2}+HCl}R-N_{2}Cl+H_{2}O} $$

$$ \mathrm{R}-\mathrm{N}_{2}\mathrm{Cl}+\mathrm{H}_{2}\mathrm{O}\rightarrow\mathrm{ROH}+\mathrm{N}_{2}\uparrow+\mathrm{HCl} $$', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (197, 'chemistry-2025-05-21-shift-2', 'q17', 14, 14, 'Reaction of phenol with chloroform in the presence of sodium hydroxide gives salicylaldehyde. The reaction is known as', '[{"id":"A","text":"Reimer-Tiemann reaction"},{"id":"B","text":"Kolbe''s reaction"},{"id":"C","text":"Williamson synthesis"},{"id":"D","text":"Claisen Smith Condensation reaction"}]', 0, 'A', 'On treating phenol with chloroform in the presence of sodium hydroxide, a $ -CHO $ group is introduced at ortho position of benzene ring. This reaction is known as Reimer - Tiemann reaction. The intermediate substituted benzal chloride is hydrolysed in the presence of alkali to produce salicylaldehyde.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (198, 'chemistry-2025-05-21-shift-2', 'q18', 15, 15, 'The Grignard reagent can be prepared by using magnesium in dry ether on', '[{"id":"A","text":"C2H5OH"},{"id":"B","text":"C2H5Br"},{"id":"C","text":"C2H6"},{"id":"D","text":"C2H5NO2"}]', 0, 'B', 'Organo-metallic compounds discovered by Victor Grignard in 1900 is alkyl magnesium halide, RMgX, referred as Grignard Reagents. These reagents are obtained by the reaction of haloalkanes with magnesium metal in dry ether.

Ethyl bromide can be used with Magnesium in dry ether to prepare Grignard reagent.

$$ \mathrm{CH_{3}CH_{2}Br+Mg\xrightarrow{dry ether}CH_{3}CH_{2}MgBr}\atop{Grignard~Reagent} $$', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (199, 'chemistry-2025-05-21-shift-2', 'q19', 16, 16, 'The correct order of increasing acidic strength is

(A) Ethanol

(B) Phenol

(C) Chloroacetic acid

(D) Acetic acid', '[{"id":"A","text":"(A), (B), (D) (C)"},{"id":"B","text":"(A), (D), (B) (C)"},{"id":"C","text":"(C), (D), (B), (A)"},{"id":"D","text":"(B),(C),(A),(D)"}]', 0, 'A', 'The reaction of phenol with aqueous sodium hydroxide indicates that phenols are stronger acids than alcohols and water. In alkoxide ion, the negative charge is localized on oxygen while in phenoxide ion, the charge is delocalized. The delocalization of negative charge (structures I-V) makes phenoxide ion more stable and favors the ionization of phenol.

conjugate base through delocalisation of the negative charge by inductive and/or resonance effects. Conversely, electron donating groups decrease the acidity by destabilising the conjugate base.

(Chloroacetic acid) - strongest acid here, since the electron-withdrawing chlorine atom stabilizes the conjugate base via -I effect

Increasing order of acidity Ethanol < Phenol < Acetic acid < Chloroacetic acid', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (200, 'chemistry-2025-05-21-shift-2', 'q20', 17, 17, 'Which of the following statements are correct?

(A) A solution which obeys Raoult''s law strictly is called an ideal solution.

(B) A solution which shows deviations from Raoult''s law is called a real solution.

(C) If $ T_{b} $ is the boiling point of the solvent and T is the boiling point of the solution, then the difference

(D) The elevation of boiling point is related to the lowering of vapor pressure.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'A solution that obeys Raoult''s law at all concentrations and temperatures is called an ideal solution. A solution that deviates from Raoult''s law (either positively or negatively) is called a real solution.

Let $ T_{b}^{0} $ be the boiling point of pure solvent and $ T_{b} $ be the boiling point of solution. The increase in the boiling point $ \Delta T_{b} = T_{b} - T_{b}^{0} $ is known as elevation of boiling point.

ig. 2.7: The vapour pressure curve for solution lies below the curve for pure water. The diagram shows that $ \Delta T_{b} $ denotes the elevation of boiling point of a solvent in solution.

Boiling point elevation occurs because adding a solute lowers the vapor pressure, requiring a higher temperature to boil.

A, B, D statements are correct', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (201, 'chemistry-2025-05-21-shift-2', 'q21', 18, 18, 'Match List-I with List-II', '[{"id":"A","text":"\\ (\\mathrm{A})-(\\mathrm{I}),(\\mathrm{B})-(\\mathrm{II}),(\\mathrm{C})-(\\mathrm{III}),(\\mathrm{D})-(\\mathrm{IV})"},{"id":"B","text":"\\ (\\mathrm{A})-(\\mathrm{I}),(\\mathrm{B})-(\\mathrm{III}),(\\mathrm{C})-(\\mathrm{II}),(\\mathrm{D})-(\\mathrm{IV})"},{"id":"C","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{IV}),(\\mathbf{D})-(\\mathbf{III})"},{"id":"D","text":"\\ (\\mathrm{A})-(\\mathrm{III}),(\\mathrm{B})-(\\mathrm{IV}),(\\mathrm{C})-(\\mathrm{I}),(\\mathrm{D})-(\\mathrm{II})"}]', 0, 'D', 'Gold - 4.5 x 10^{-3}

Germanium-2.0

Glass - 1.0 x $ 10^{-16} $

Graphite - 1.2 x 10', NULL, 'null', '[]', '[{"id":"q21-table-1","kind":"table","path":"/local-papers/assets/chemistry-2025-05-21-shift-2/q21-table-1.jpg","page":13,"alt":"Table for question 21"}]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (202, 'chemistry-2025-05-21-shift-2', 'q22', 19, 19, 'Arrange the following compounds in increasing order of reactivity towards Nucleophilic Substitution Reaction

(A) Chlorobenzene

(B) 4- Nitrochlorobenzene

(C) 2,4-Dinitrochlorobenzene

(D) 2,4,6-Trinitrochloronitrobenzene', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (B), (D), (C)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'A', 'Aryl halides are extremely less reactive towards nucleophilic substitution. The presence of an electron withdrawing group (-NO_{2}) at ortho- and para-positions increases the reactivity of haloarenes.

The presence of nitro group at ortho- and para-positions withdraws the electron density from the benzene ring and thus facilitates the attack of the nucleophile on haloarene. The carbanion thus formed is stabilized through resonance.

Increasing order of reactivity is Chlorobenzene < 4-Nitrochlorobenzene < 2,4-Dinitrochlorobenzene < 2,4,6-Trinitrochlorobenzene', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (203, 'chemistry-2025-05-21-shift-2', 'q23', 20, 20, 'Decreasing order of basicity for the following compounds:

(A) Ethylamine

(B) Diethylamine

(D) Benzenamine

(C) Ammonia', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'Larger the value of Kb or smaller the value of pKb , stronger is the base. Alkylamines are stronger bases than ammonia. Aniline or other arylamines, the -NH2 group is attached directly to the benzene ring. It results in the unshared electron pair on nitrogen atom to be in conjugation with the benzene ring and thus making it less available for protonation

The decreasing order of basic strength of the above amines and ammonia follows the following order: $ (C_{2}H_{5})_{2}NH > C_{2}H_{5}NH_{2} > NH_{3} > C_{6}H_{5}NH $

Diethylamine (N-ethylethanamine pkb 3.00) > (A) Ethylamine (pkb 3.29) > (C) Ammonia > (D) Benzenamine (pkb 9.38)

Match the wavelength of light absorbed given in List-I with the color of light absorbed in List-II

Choose the correct answer from the options given below:

1. (A) - (I), (B) - (II), (C) - (III), (D) - (IV)

2. (A) - (I), (B) - (III), (C) - (II), (D) - (IV)

3. (A) - (IV), (B) - (II), (C) - (I), (D) - (III)

4. (A) - (IV), (B) - (I), (C) - (II), (D) - (III)

Options:

A.

1

B.

2

C.

3

D.

4
Solution:

The increasing order of wavelength for VIBGYOR (i.e., from shortest to longest wavelength) is:

Violet < Indigo < Blue < Green < Yellow < Orange < Red

RED-600

YELLOW-535

BLUE GREEN-498

BLUE-475', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (204, 'chemistry-2025-05-21-shift-2', 'q25', 21, 21, 'CuSO₄ is colorless but CuSO₄·5H₂O is blue in color. Which of the following statements is incorrect at CuSO₄·5H₂O?', '[{"id":"A","text":"in $ CuSO_{4}\\cdot5H_{2}O $ water act as ligand"},{"id":"B","text":"crystal field splitting takes place in $ CuSO_{4}\\cdot5H_{2}O $"},{"id":"C","text":"presence of $ SO_{4}^{2-} $ ion in coordination sphere imparts the color of $ CuSO_{4}\\cdot5H_{2}O $"},{"id":"D","text":"d-d transition takes place in $ CuSO_{4}\\cdot5H_{2}O $"}]', 0, 'C', 'In $ CuSO_4 \cdot 5H_2O $ the water molecules act as ligands around the $ Cu^{2+} $ ion, producing a crystal-field splitting of the d-orbitals and allowing d-d transitions that give the blue color. The $ SO_4^{2-} $ ion is present as a counter-ion and are not present in the coordination sphere and doesn''t impart colour to copper sulphate.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (205, 'chemistry-2025-05-21-shift-2', 'q26', 22, 22, 'Which of the following statements, for the reaction of type $ A \rightarrow B $, are correct?

A) The initial rates for a second order reaction depend on the square of the concentration of the reactant

(B) The half-life is the time for half of the reactant to be consumed

(C) The expression for rate of second order reaction is $ r = k[2A]^{2} $

(D) The half-life of a second-order reaction depends on the initial concentration', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'For the given reaction A $ \rightarrow $ B The order of a rate law is the sum of the exponents of its concentration terms.

The initial rate for a second order reaction depends on the square of the concentration of the reactant.

For a second-order reaction:

Rate = k[A] $ ^{2} $(expression for rate of second order reaction)

So, the rate depends on the square of the concentration of A.

The half-life of a reaction is the time in which the concentration of a reactant is reduced to one half of its initial concentration. It is represented as $ t_{1/2} $ which can also mean the half of the reactant is consumed. Half life of a second order reaction depends on initial concentration.

$$ t_{1/2}=\frac{1}{k[A]_{0}} $$', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (206, 'chemistry-2025-05-21-shift-2', 'q27', 23, 23, 'If the $ E_{cell}^{\circ} $ of the given hypothetical cell reaction is 0.046 V, the value of $ \log K_{c} $ for this reaction at 298 K would be:

$ A(s)+2B^{+}(aq)\rightarrow A^{2+}(aq)+2B(s) $', '[{"id":"A","text":"1.556"},{"id":"B","text":"15.56"},{"id":"C","text":"1.12"},{"id":"D","text":"3.92"}]', 0, 'A', 'The reversible work done by a galvanic cell is equal to decrease in its Gibbs energy.

If the emf of the cell is E and nF is the total charge passed, then $ \Delta G = -nFE_{cell} $.

If concentration of all species is unity, $ E_{\text{cell}} = E_{\text{cell}}^\circ $, so $ \Delta G^\circ = -nFE_{\text{cell}}^\circ $.

$$ \begin{aligned}\Delta G^{\circ}&=-RT\ln K\\-nFE_{cell}^{\circ}&=-RT\ln K\end{aligned} $$

$$ \ln K=\frac{nFE_{cell}^{\circ}}{RT} $$

$$ \log K=\frac{n F E_{cell}^{\circ}}{2.303R T} $$

$$ \mathrm{Given}:E_{\mathrm{cell}}^{\circ}=0.046\mathrm{V},T=298\mathrm{K} $$

$$ Reaction:A(s)+2B^{+}(aq)\rightarrow A^{2+}(aq)+2B(s) $$

$$ n=2 $$

Substituting values of n = 2, F = 96500 C/mol, R = 8.314 J/mol.K and T = 298 K

$$ \log K=\frac{2\times96500\times0.046}{2.303\times8.314\times298} $$

$$ \log K=1.556 $$', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (207, 'chemistry-2025-05-21-shift-2', 'q28', 24, 24, 'The following statements predict the temperature dependence on the rate of reaction:

(A) Increase in temperature increases the rate of reaction.

(B) Increase in temperature decreases the rate of reaction.

(C) Increase in temperature by $ 10\ ^{\circ}C $ doubles the reaction rate.

(D) An increase in temperature by $ 10\ ^{\circ}C $ triples the rate of reaction.', '[{"id":"A","text":"(A) and (C) only"},{"id":"B","text":"(B) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Most of the chemical reactions are accelerated by increase in temperature. For a chemical reaction with rise in temperature by $ 10^{\circ} $, the rate constant is nearly doubled. The temperature dependence of the rate of a chemical reaction can be accurately explained by Arrhenius equation', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (208, 'chemistry-2025-05-21-shift-2', 'q29', 25, 25, 'What is the oxidation number of the metal of $ [\mathrm{Co}(\mathrm{H}_{2}\mathrm{O})(\mathrm{CN})(\mathrm{ox})_{2}]^{2-} $ coordination entity?', '[{"id":"A","text":"+5"},{"id":"B","text":"+1"},{"id":"C","text":"+3"},{"id":"D","text":"+2"}]', 0, 'C', 'Let x = \mathrm{oxidation number of Co}.

Charge on ligands:

\mathrm{H}_{2}\mathrm{O} (neutral) = 0, \mathrm{CN}^{-} = -1, Oxalate \left(\mathrm{C}_{2}\mathrm{O}_{4}^{2-}\right) = -2

Since there are two oxalate ions: $ 2 \times (-2) = -4 $

Total charge on complex = $ x + 0 + (-1) + (-4) $

$ x - 5 = -2 $

$ x = +3 $', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (209, 'chemistry-2025-05-21-shift-2', 'q30', 26, 26, 'The order of kinetics of S_{N}1 reactions is:', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'SN1 reactions follow first-order kinetics, meaning the reaction rate is dependent only on the concentration of the substrate, not the nucleophile. The rate law for an SN1 reaction is expressed as Rate = k[substrate]

Where k is the rate constant and [Substrate] is the concentration of the substrate. This is because the first step, the formation of a carbocation intermediate, is the rate-determining step and only involves the substrate and not the nucleophile', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (210, 'chemistry-2025-05-21-shift-2', 'q31', 27, 27, 'The units of rate of reaction and rate constant are identical for a', '[{"id":"A","text":"Fractional order reaction"},{"id":"B","text":"Zero order reaction"},{"id":"C","text":"First order reaction"},{"id":"D","text":"Second order reaction"}]', 0, 'B', 'The rate of a reaction can be defined as the change in concentration of a reactant or product in unit time. Units of rate are concentration/time. For a general reaction

$$ \mathrm{aA}+\mathrm{bB}\rightarrow\mathrm{cC}+\mathrm{dD} $$

$$ Rate=k[A]^{x}[B]^{y} $$

Where $ x + y = n $ = order of the reaction

$$ \mathrm{k}=\frac{\mathrm{Rate}}{[\mathrm{A}]x[\mathrm{B}]y} $$

$$ =\frac{\mathrm{concentration}}{\mathrm{time}}\times\frac{1}{(\mathrm{concentration})^{n}}\quad(\mathrm{where}[\mathrm{A}]=[\mathrm{B}]) $$

For a zero-order reaction n=0 so Unit of rate constant k in zero order reaction becomes concentration/time same as unit of rate.', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (211, 'chemistry-2025-05-21-shift-2', 'q32', 28, 28, 'Which of the following is not true with reference to evaporation of liquid?', '[{"id":"A","text":"The liquids having low inter-molecular forces evaporate faster."},{"id":"B","text":"The higher the temperature, the higher is the rate of evaporation."},{"id":"C","text":"Larger the surface area, larger is the rate of evaporation."},{"id":"D","text":"The evaporation rate follows the order of Water > Alcohol > Ether."}]', 0, 'D', 'First 3 statements are true.

Weaker intermolecular forces make it easier for molecules to escape into vapor and evaporate Higher temperature gives molecules more kinetic energy to escape and evaporate faster. Larger the surface area, larger is the rate of evaporation as more molecules are exposed to air, so evaporation increases.

The correct order of evaporation rate is Ether > Alcohol > Water, because ether has the weakest intermolecular forces and water the strongest (due to hydrogen bonding).', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (212, 'chemistry-2025-05-21-shift-2', 'q33', 29, 29, 'The rate of a first order reaction at a constant temperature', '[{"id":"A","text":"Increases as the reaction proceeds"},{"id":"B","text":"Decreases as the reaction proceeds"},{"id":"C","text":"May increase or decrease as the reaction proceeds"},{"id":"D","text":"Remains constant as the reaction proceeds"}]', 0, 'B', 'The rate of the reaction for first order reaction is proportional to the first power of the concentration of the reactant R. For example, $ R \rightarrow P $

$$ \mathrm{Rate}=-\frac{\mathrm{d}[R]}{\mathrm{d}t}=k[R] $$

As concentration of reactant decreases as reaction proceeds Rate also decreases

Integrating this equation we get.

When t = 0, $ R = [R]_{0} $, where $ [R]_{0} $ is the initial concentration of the reactant.

$$ \ln\frac{|R|}{|R|b}=-kt $$

Taking anti-log of both sides

$ [R] = [R]_{0} e^{-kz} $', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (213, 'chemistry-2025-05-21-shift-2', 'q34', 30, 30, '"Wood spirit" is', '[{"id":"A","text":"Methanol"},{"id":"B","text":"Ethanol"},{"id":"C","text":"Propanol"},{"id":"D","text":"Phenol"}]', 0, 'A', 'Wood spirit is another name for methanol or methyl alcohol', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (214, 'chemistry-2025-05-21-shift-2', 'q36', 31, 31, 'The reagent used to convert propanol to 1-bromopropane is:', '[{"id":"A","text":"PBr3"},{"id":"B","text":"Br2"},{"id":"C","text":"CH3Br"},{"id":"D","text":"CBr3"}]', 0, 'A', 'Alkyl halides are best prepared from alcohols, which are easily accessible. The hydroxyl group of an alcohol is replaced by halogen on reaction with concentrated halogen acids, phosphorus halides or thionyl chloride.

$ PBr_{3} $ can be used as the reagent to convert propanol to 1-bromopropane.

$$ \mathrm{3R-OH +PBr_{3} \rightarrow 3R-Br +H_{3}PO_{3} } $$

$$ \mathrm{(General~Reaction:)}\quad3\mathrm{R-OH}+\mathrm{PX}_{3}\rightarrow3\mathrm{R-X}+\mathrm{H}_{3}\mathrm{PO}_{3}\quad(X=\mathrm{Cl},\mathrm{Br}) $$', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (215, 'chemistry-2025-05-21-shift-2', 'q37', 32, 32, 'Colligative properties are applicable to:', '[{"id":"A","text":"dilute solution"},{"id":"B","text":"solid solutions"},{"id":"C","text":"concentrated solutions"},{"id":"D","text":"only aqueous solution"}]', 0, 'A', 'Properties that depend on the number of solute particles irrespective of their nature relative to the total number of particles present in the solution. Such properties are called colligative properties. Colligative properties are applicable for ideal dilute solutions. These relationships are derived based on the ideal solution assumption (Raoult''s law holds true) and dilute condition, where solute-solute and solute-solvent interactions are negligible compared to solvent-solvent interactions.', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (216, 'chemistry-2025-05-21-shift-2', 'q38', 33, 33, 'Which one represents the correct reduction reaction for the $ \mathrm{Cu^{2+}}|\mathrm{Cu} $ half-cell?', '[{"id":"A","text":"$$ \\mathrm{Cu^{2+}(aq)+2e^{-}\\rightarrow Cu(s)} $$"},{"id":"B","text":"$$ \\mathrm{Cu^{2+}(aq)\\rightarrow Cu(s)+2e^{-}} $$"},{"id":"C","text":"\\ \\mathrm{Cu(s)}\\rightarrow\\mathrm{Cu(aq)}+2\\mathrm{e}^{-}"},{"id":"D","text":"\\ \\mathrm{Cu^{2+}(aq)+2e^{-}\\rightarrow Cu^{+}(s)+e^{-}}"}]', 0, 'A', 'Reduction is a process where a chemical species gains electrons. The reduction half reaction occurs on the copper electrode.

$$ \mathrm{(i)}\mathrm{Cu^{2+}+2e^{-}\rightarrow Cu(s)}\quad(\mathrm{R e d u c t i o n~h a l f~r e a c t i o n}) $$', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (217, 'chemistry-2025-05-21-shift-2', 'q39', 34, 34, 'The Lucas reagent will react fastest with:', '[{"id":"A","text":"$ (CH_{3})_{3}COH $"},{"id":"B","text":"$ \\mathrm{CH_{3}CH_{2}OH} $"},{"id":"C","text":"$ \\mathrm{CH_{3}(CH_{2})_{2}OH} $"},{"id":"D","text":"$ \\mathrm{CH_{3}CH(CH_{3})OH} $"}]', 0, 'A', 'Alcohols are soluble in Lucas reagent (conc. HCl and ZnCl $ _2 $) while their halides are immiscible and produce turbidity in solution. In case of tertiary alcohols, turbidity is produced immediately as they form the halides easily. Primary alcohols do not produce turbidity at room temperature.

Tertiary alcohol (CH3)3COH reacts fastest with lucas reagent', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (218, 'chemistry-2025-05-21-shift-2', 'q42', 35, 35, '4. Glycerladehyde', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Glucose gets oxidised to six carbon carboxylic acid (gluconic acid) on reaction with a mild oxidising agent like bromine water. This indicates that the carbonyl group is present as an aldehydic group.', 'p787c8257a9b8', 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (219, 'chemistry-2025-05-21-shift-2', 'q43', 36, 36, '4. Cellulose', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', NULL, 'p4011e91378ec', 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (220, 'chemistry-2025-05-21-shift-2', 'q44', 37, 37, '4. Galactose', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Lactose: It is more commonly known as milk sugar since this disaccharide is found in milk. It is composed of $ \beta $-D-galactose and $ \beta $-D-glucose.', 'pfe3c2ea74417', 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (221, 'chemistry-2025-05-21-shift-2', 'q45', 38, 38, '4. (D)', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'In amino acids there is presence of both acidic (carboxyl group) and basic (amino group) groups in the same molecule. In aqueous solution, the carboxyl group can lose a proton and amino group can accept a proton, giving rise to a dipolar ion known as zwitter ion. This is neutral but contains both positive and negative charges. In zwitter ionic form, amino acids show amphoteric behaviour as they react both with acids and bases.

$$ \underset{(NH_{2})}{\mathrm{O}}\xrightarrow{\mathrm{O}}\underset{(Zwitter ion)}{\longleftrightarrow\mathrm{R-CH-C-O^{-}}} $$', 'pb92a32db1ad5', 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (222, 'chemistry-2025-05-21-shift-2', 'q46', 39, 39, '4. KMnO_{4}', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Acetaldehyde is prepared industrially by oxidation of ethene in the presence of palladium(II) chloride and cupric chloride - this is known as the wacker process.', 'p41b88e867801', 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (223, 'chemistry-2025-05-21-shift-2', 'q47', 40, 40, '$$ 4.\mathrm{S n}^{2+} $$', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'Iron(III) catalyzes the reaction between iodide and persulphate ions.

$$ 2\mathrm{I}^{-}+\mathrm{S}_{2}\mathrm{O}_{8}^{2-}\rightarrow\mathrm{I}_{2}+2\mathrm{SO}_{4}^{2-} $$

An explanation of this catalytic action is as follows:

$$ 2\mathrm{Fe}^{3+}+2\mathrm{I}^{-}\rightarrow2\mathrm{Fe}^{2+}+\mathrm{I}_{2} $$

$$ \mathrm{2Fe^{2+} +S_{2}O_{8}^{2-} \rightarrow 2Fe^{3+} +2SO_{4}^{2-}} $$', 'p4f76dfc67b9c', 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (224, 'chemistry-2025-05-21-shift-2', 'q48', 41, 41, '4. Vanadium(II) oxide', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', '$$2SO_2(g) + O_2(g) \xrightarrow{V_2O_5} 2SO_3(g)$$

Sulphuric acid is one of the most important industrial chemicals worldwide.

It is manufactured by the Contact Process.

The key step is the catalytic oxidation of $SO_2$ with $O_2$ to produce $SO_3$.

In presence of Vanadium(V) oxide', 'p5e28e689c5fb', 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (225, 'chemistry-2025-05-21-shift-2', 'q49', 42, 42, '4. Sandmeyer reaction', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'High density polythene is formed when addition polymerization of ethene takes place in a hydrocarbon solvent in the presence of a catalyst such as triethylaluminium or trimethylaluminium and titanium tetrachloride (Ziegler-Natta catalyst) at a temperature of 333 K to 343 K and under a pressure of 6-7 atmospheres', 'paeabc3e3bb17', 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (226, 'chemistry-2025-05-21-shift-2', 'q50', 43, 43, '4. formation of bonds between reactant molecules and catalyst', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The transition metals and their compounds are known for their catalytic activity. This activity is ascribed to their ability to adopt multiple oxidation states and to form complexes. Catalysts at a solid surface involve the formation of bonds between reactant molecules and atoms of the surface of the catalyst. This has the effect of increasing the concentration of the reactants at the catalyst surface and also weakening of the bonds in the reacting molecules. It doesn''t weaken bond between reacting molecules and catalyst complex but interbonds between reacting molecules.', 'pdae30d11e1c6', 'null', '[]', '[]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (227, 'chemistry-2025-05-23-shift-2', 'q01', 1, 1, 'Wood spirit is known as', '[{"id":"A","text":"Ethanol"},{"id":"B","text":"Propanol"},{"id":"C","text":"Methanol"},{"id":"D","text":"Methoxymethane"}]', 0, 'C', 'Methanol, $ CH_{3}OH $, also known as ''wood spirit'', was produced by destructive distillation of wood. Nowadays, most of the methanol is produced by catalytic hydrogenation of carbon monoxide at high pressure and temperature and in the presence of $ ZnO - Cr_{2}O_{3} $ catalyst.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (228, 'chemistry-2025-05-23-shift-2', 'q02', 2, 2, 'What are the products of the following reaction in neutral solution?

$ \mathrm{MnO_4^- + S_2O_3^{2-} + H_2O \rightarrow ?} $', '[{"id":"A","text":"$ \\mathrm{MnO_2, SO_3^{2-}, H^+} $"},{"id":"B","text":"$ \\mathrm{MnO_2, SO_2, HO^-} $"},{"id":"C","text":"$ \\mathrm{MnO_2, SO_4^{2-}, HO^-} $"},{"id":"D","text":"$ \\mathrm{Mn^{2+}, SO_4^{2-}, H^+} $"}]', 0, 'C', 'In neutral or faintly alkaline solutions, thiosulphate (S₂O₃²⁻) is oxidised by permanganate ion (MnO₄⁻) almost quantitatively to sulphate and MnO₂: $ 8\text{MnO}_4^- + 3\text{S}_2\text{O}_3^{2-} + \text{H}_2\text{O} \rightarrow 8\text{MnO}_2 + 6\text{SO}_4^{2-} + 2\text{OH}^- $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (229, 'chemistry-2025-05-23-shift-2', 'q03', 3, 3, 'When 1 mol of CrCl₃ · 6H₂O is treated with excess AgNO₃, 3 mol of AgCl are obtained.

The conductivity of the solution will correspond to:', '[{"id":"A","text":"1:1 electrolyte"},{"id":"B","text":"1:2 electrolyte"},{"id":"C","text":"2:1 electrolyte"},{"id":"D","text":"1:3 electrolyte"}]', 0, 'D', '1 mole of CrCl3·6H2O reacts with excess AgNO3 to produce 3 moles of AgCl, implying that all three Cl- ions are acting as counter ions outside the coordination sphere: [Cr(H2O)6]Cl3 -> [Cr(H2O)6]3+ + 3Cl-. Ratio of cations to anions is 1:3 electrolyte.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (230, 'chemistry-2025-05-23-shift-2', 'q04', 4, 4, 'Predict the order of decreasing reactivity of the following compounds towards SN1 reaction.

(A) $ C_6H_5CH_2Br $

(B) $ C_6H_5CH(C_6H_5)Br $

(C) $ C_6H_5CH(CH_3)Br $

(D) $ C_6H_5C(CH_3)(C_6H_5)Br $', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D), (A), (C), (B)"},{"id":"C","text":"(D), (B), (C), (A)"},{"id":"D","text":"(A), (C), (B), (D)"}]', 0, 'C', '$$ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{C}(\mathrm{CH}_{3})(\mathrm{C}_{6}\mathrm{H}_{5})\mathrm{Br}>\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CH}(\mathrm{C}_{6}\mathrm{H}_{5})\mathrm{Br}>\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CH}(\mathrm{CH}_{3})\mathrm{Br}>\mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CH}_{2}\mathrm{Br}\text{(SN1)} $$

Of the two secondary bromides, the carbocation intermediate obtained from $ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CH}(\mathrm{C}_{6}\mathrm{H}_{5})\mathrm{Br} $ is more stable than that obtained from $ \mathrm{C}_{6}\mathrm{H}_{5}\mathrm{CH}(\mathrm{CH}_{3})\mathrm{Br} $ [Therefore, the former bromide is more reactive than the latter in SN1 reactions.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (231, 'chemistry-2025-05-23-shift-2', 'q05', 5, 5, 'Identify the correct statements for the behavior of ethane-1,2-diamine as a ligand.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'Ethylenediamine (en) and oxalate ( $ ox^{2-} $) are common examples of bidentate ligands.

Since ethylenediamine (en) binds through two nitrogen atoms, it is bidentate (B).

It is also a neutral ligand (A) since it does not bear any charge, and because bidentate ligands usually lead to ring formation, they are also chelating ligands.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (232, 'chemistry-2025-05-23-shift-2', 'q06', 6, 6, 'Which one of these tripositive ions is the most stable in aqueous solution?', '[{"id":"A","text":"$ \\mathrm{Cr}^{3+} $"},{"id":"B","text":"$ \\mathrm{Ti}^{3+} $"},{"id":"C","text":"$ V^{4+} $"},{"id":"D","text":"$ \\mathrm{Mn}^{3+} $"}]', 0, 'A', 'Electronic coniguration for each ion:
Cr (Z = 24): [Ar] $ 3d^{5} $ $ 4s^{1} $
Cr^{3+}: [Ar] 3d^{3}
Ti (Z = 22): [Ar] $ 3d^{2} $ $ 4s^{2} $
Ti^{3+}: [Ar] 3d^{1}
V (Z = 23): [Ar] $ 3d^{3} $ $ 4s^{2} $
$ V^{3+} $: [Ar] $ 3d^{2} $
Mn (Z = 25): [Ar] $ 3d^{5} $ $ 4s^{2} $
Mn^{3+}: [Ar] 3d^{4}
In an aqueous solution, water molecules surround the metal ion, forming an octahedral complex.

According to Crystal Field Theory (CFT), this splits the d-orbitals into two sets:

$ t_{2g} $ (lower energy, 3 orbitals) and $ e_{g} $ (higher energy, 2 orbitals)

Electrons fill the lower energy $ t_{2g} $ set first:

$ \mathrm{Ti}^{3+}(d^{1}):t_{2g}^{1} $

$ V^{3+}(d^{2}):t_{2g}^{2} $

$ \mathrm{Cr}^{3+}(d^{3}):t_{2g}^{3} $

$ Mn^{3+}(d^{4}):t_{2g}^{3}e_{g}^{1} $

The $ Cr^{3+} $ ion has a $ t_{2g}^{3} $ configuration, which is a perfectly half-filled $ t_{2g} $ subshell.

This gives extra stability. Hence, $ Cr^{3+} $ is the most stable ion among the given choices.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (233, 'chemistry-2025-05-23-shift-2', 'q07', 7, 7, '$ Cr_{2}O_{7}^{2-} $ dissolves in aqueous NaOH to give:', '[{"id":"A","text":"$ Cr_{2}O_{3} $"},{"id":"B","text":"$ \\mathrm{Cr(OH)}_{3} $"},{"id":"C","text":"$ \\mathrm{CrO_{4}^{2-}} $"},{"id":"D","text":"$ CrO_{3} $"}]', 0, 'C', 'The chromates and dichromates are interconvertible in aqueous solution depending upon the pH of the solution.

Dichromate ion $ (\mathrm{Cr_2O_7^{2-}}) $ produces chromate ion $ (\mathrm{CrO_4^{2-}}) $ and a water molecule in basic solutions like NaOH.

$ 2\mathrm{CrO_4^{2-}} + 2\mathrm{H^+} \longrightarrow \mathrm{Cr_2O_7^{2-}} + \mathrm{H_2O} $

$ \mathrm{Cr_2O_7^{2-}} + 2\mathrm{OH^-} \longrightarrow 2\mathrm{CrO_4^{2-}} + \mathrm{H_2O} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'banner', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (234, 'chemistry-2025-05-23-shift-2', 'q08', 8, 8, 'The correct increasing reactivity order for SN2 reaction for the following compounds

(A) Benzyl Chloride

(B) Methyl Chloride,

(C) Isopropyl Chloride

(D) Tertiary butyl Chloride', '[{"id":"A","text":"(A), (B), (D), (C)"},{"id":"B","text":"(A), (B), (C), (D)"},{"id":"C","text":"(A), (D), (C), (B)"},{"id":"D","text":"(D), (C), (B), (A)"}]', 0, 'D', '$$ \left(D\right)<\left(C\right)<\left(B\right)<\left(A\right) $$

Explanation: SN₂ reactivity is governed by steric hindrance (bulkiness). The reaction needs a clear path for a "backside attack." Less bulk = faster reaction

(A) Benzyl (1°): Also has low bulk, but it''s even faster than methyl. The adjacent benzene ring helps stabilize the transition state, lowering the reaction''s

(B) Methyl: Least bulky (only small H atoms). Very fast SN $ _{2} $.

(C) Isopropyl $ (2^{\circ}) $: Very bulky. Very slow SN $ _{2} $.

(D) Tertiary butyl (3°): Most bulky. No $ SN_{2} $ reaction. (Least Reactive)', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (235, 'chemistry-2025-05-23-shift-2', 'q09', 9, 9, 'The order of a certain reaction with respect to $ Cl^{-} $ ion is -1.

The $ Cl^{-} $ is', '[{"id":"A","text":"A catalyst"},{"id":"B","text":"A promotor"},{"id":"C","text":"An inhibitor"},{"id":"D","text":"Always a product molecule"}]', 0, 'C', 'Rate Law: The order of a reaction tells how the rate depends on the concentration of a species.

In this case, Rate $ \propto $ [Cl $ ^{-} $] $ ^{-1} $.

This can be rewritten as Rate $ \propto \frac{1}{[\mathrm{Cl}^{-}]} $.

This means that as the concentration of the $ Cl^{-} $ ion increases, the overall reaction rate decreases.

A substance that decreases the rate of a reaction is called an inhibitor. A catalyst would increase the rate, leading to a positive reaction order (like +1).', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (236, 'chemistry-2025-05-23-shift-2', 'q10', 10, 10, 'Lack of Vitamin B1 causes:', '[{"id":"A","text":"Beri beri"},{"id":"B","text":"Rickets"},{"id":"C","text":"Convulsions"},{"id":"D","text":"Scurvy"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (237, 'chemistry-2025-05-23-shift-2', 'q11', 11, 11, 'The correct sequence of attachment of sugar, base and phosphoric acid in a nucleic acid is

(A) Formation of phosphodiester linkage

(B) Attachment of base to 1'' position of sugar

(C) Selection of appropriate base and sugar

(D) Attachment of phosphoric acid', '[{"id":"A","text":"(C),(B),(D),(A)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (A), (D)"}]', 0, 'A', 'Sequence: (C) Select base and sugar -> (B) Attach base to 1'' position of sugar -> (D) Attach phosphoric acid to 5'' position of sugar -> (A) Formation of phosphodiester linkage between nucleotides.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (238, 'chemistry-2025-05-23-shift-2', 'q12', 12, 12, 'Match List-I with List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">List-I</th>
      <th style="padding: 8px; border: 1px solid #444;">List-II</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(A) Wurtz-Fittig reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(I) $\mathrm{CH_3COCl}$ and Anhyd. $\mathrm{AlCl_3}$</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(B) Chiral</td>
      <td style="padding: 8px; border: 1px solid #444;">(II) CFCs</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(C) Friedel-Crafts Acylation</td>
      <td style="padding: 8px; border: 1px solid #444;">(III) Alkylarene</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(D) Freons</td>
      <td style="padding: 8px; border: 1px solid #444;">(IV) Non-superimposable mirror images</td>
    </tr>
  </tbody>
</table>', '[{"id":"A","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (II), (D) - (I)"}]', 0, 'A', '(A) Wurtz-Fittig reaction -> Alkylarene (III); (B) Chiral -> Non-superimposable mirror images (IV); (C) Friedel-Crafts Acylation -> CH3COCl and Anhyd. AlCl3 (I); (D) Freons -> CFCs (II). Mapping: (A)-(III), (B)-(IV), (C)-(I), (D)-(II).', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (239, 'chemistry-2025-05-23-shift-2', 'q13', 13, 13, 'Which of the following statements, with reference to a solution, are correct?

(A) The osmotic pressure of the solution is proportional to the molarity of the solute.

(B) The elevation of the boiling point ( $ \Delta T_b $) is directly proportional to the molal concentration of the s

(C) The unit of $ K_b $ is K kg $ ^{-1} $ mol $ ^{-1} $.

$$ \Delta T_{b}=T_{b}^{0}-T_{b}. $$', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A) and (B) only"},{"id":"C","text":"(C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'Boiling point elevation means the solution boils at a higher temperature than the pure solvent.

Therefore, $ \Delta T_b = T_b - T_b^0 $, where $ T_b $ is the boiling point of the solution and $ T_b^0 $ is the boiling point of the pure solvent.

Hence, statement (D) is incorrect, and the rest are correct.', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (240, 'chemistry-2025-05-23-shift-2', 'q14', 14, 14, 'Reaction of Ethene with Bromine in CCl_{4} will result in', '[{"id":"A","text":"Gem-Dibromide"},{"id":"B","text":"Vicinal-Dibromide"},{"id":"C","text":"Vinylic-Dibromide"},{"id":"D","text":"Allylic-Bromide"}]', 0, 'B', 'Addition of halogens: In the laboratory, addition of bromine in

, to an alkene resulting in discharge of reddish brown colour of bromine constitutes an important method for the detection of double bond in a molecule. The ad results in the synthesis of vic-dibromides, which are colourless.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (241, 'chemistry-2025-05-23-shift-2', 'q15', 15, 15, 'Which of the following compound will form a cyclic product on reaction with ethylene glycol?', '[{"id":"A","text":"Acetone"},{"id":"B","text":"Ethylether"},{"id":"C","text":"Benzoic acid"},{"id":"D","text":"Benzyl alcohol"}]', 0, 'A', 'Ketones react with ethylene glycol in the presence of dry hydrogen chloride to form cyclic products known as ethylene glycol ketals.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (242, 'chemistry-2025-05-23-shift-2', 'q16', 16, 16, 'Which of the following reagents can be used to convert Ethanol to Ethanal?

(A) Chromium trioxide in Pyridine and HCl

(B) Heated Copper at 573 K

(C) Anhydrous Chromium trioxide

(D) Acidic KMnO_{4}', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'Converting a primary alcohol to an aldehyde requires a mild oxidizing agent or a dehydrogenation reaction that stops at the aldehyde stage.

(B) Heated Copper at 573 K: This is a classic dehydrogenation method for primary alcohols. It converts primary alcohols to aldehydes without further oxidation to carboxylic acids.

$$ CH_{3}CH_{2}OH\xrightarrow[573K]{Cu}CH_{3}CHO+H_{2} $$

(A) Chromium trioxide in Pyridine and HCl (PCC): PCC is a mild oxidizing agent that converts primary alcohols to aldehydes.

• (C) Anhydrous Chromium trioxide (CrO3): While CrO3 is an oxidizing agent, without a specific solvent (like pyridine for PCC), it often leads to over-oxidation of primary alcohols to carboxylic acids.

(D) Acidic KMnO_{4}. This is a strong oxidizing agent. It will oxidize ethanol to ethanoic acid (acetic acid), not stop at ethanol.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (243, 'chemistry-2025-05-23-shift-2', 'q17', 17, 17, 'Arrange the following ligands in decreasing order of field strength in spectrochemical series.

(A) Br-

(B) H_{2}O

(C) OH-

(D) CO', '[{"id":"A","text":"(D), (B), (C), (A)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'A', 'ligands can be arranged in a series in the order of increasing field strength as given below:

$$ \mathrm{I^{-}<Br^{-}<SCN^{-}<Cl^{-}<S^{2-}<F^{-}<OH^{-}<C_{2}O_{4}^{2-}<H_{2}O<NCS^{-}} $$

$$ \mathrm{<edta^{4-}<N H_{3}<e n<C N^{-}<C O} $$

Such a series is termed as spectrochemical series. It is an

experimentally determined series based on the absorption of light

by complexes with different ligands.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (244, 'chemistry-2025-05-23-shift-2', 'q18', 18, 18, 'For the reaction:

$$ 2\mathsf{N}_{2}\mathsf{O}_{5}\rightarrow4\mathsf{NO}_{2}+\mathsf{O}_{2} $$

At a given instant of time, the rate and rate constant are $ 1.02 \times 10^{-4} $ mol L $ ^{-1} $s $ ^{-1} $ and $ 3.4 \times 10^{-5} $ s $ ^{-1} $, respectively.

The concentration of $ N_{2}O_{5} $ at that time will be:', '[{"id":"A","text":"3.0 mol $ L^{-1} $"},{"id":"B","text":"1.713 mol L^{-1}"},{"id":"C","text":"$ 1.02 \\times 10^{-4} $ mol $ L^{-1} $"},{"id":"D","text":"$ 3.4 \\times 10^{-5} $ mol $ L^{-1} $"}]', 0, 'A', 'The unit of the rate constant (k) is $ s^{-1} $. This indicates a first-order reaction.

For a first-order reaction, the rate law is: Rate = k[A]

For the reaction $ 2\mathrm{N}_2\mathrm{O}_5 \rightarrow 4\mathrm{NO}_2 + \mathrm{O}_2 $，the rate law is: Rate = k[ $ N_2O_5 $]

Given:

$$ \mathrm{Rate}=1.02\times10^{-4}\mathrm{m o l L^{-1}s^{-1}} $$

$$ k=3.4\times10^{-5}s^{-1} $$

$$ [{\mathrm{N_{2}O_{5}}}]={\frac{\mathrm{R a t e}}{k}} $$

$$ \mathrm{N_{2}O_{5}]}=\frac{1.02\times10^{-4}\mathrm{m o l L^{-1}s^{-1}}}{3.4\times10^{-5}\mathrm{s^{-1}}} $$

$$ \mathrm{N_{2}O_{5}]}=\left(\frac{1.02}{3.4}\right)\times\left(\frac{10^{-4}}{10^{-5}}\right)\mathrm{m o l L^{-1}} $$

$$ \mathrm{N_{2}O_{5}]=0.3\times10^{1}mol\mathrm{L^{-1}} $$

$$ [\mathrm{N}_{2}\mathrm{O}_{5}]=3.0\,\mathrm{m o l}\,\mathrm{L}^{-1} $$

The IUPAC name of the given compound is _

1.3-Bromo-4,4-dimethyl-cyclohexene

2.1-Bromo-2,2-dimethyl-cyclohexene

3.1,1-dimethyl-2-bromo-cyclohexene

4.1,1-dimethyl-2-bromo-cyclohexane
Options:

Options:

A. 1

B. 2

C. 3

D. 4

Answer: A
Solution:

CORRECT IUPAC 3-Bromo-4,4-dimethylcyclohex-1-ene.

1. Cyclohexene: 6-membered ring with one double bond.

2. Numbering: Double bond carbons are C1 and C2. Numbering (counter-clockwise) gives substituents the lowest possible positions:

- C1: Double bond starts

- C2: Double bond ends

- C3: Bromine

- C4: Two Methyl groups

3. Name: Alphabetical order: Bromo, then dimethyl.', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (245, 'chemistry-2025-05-23-shift-2', 'q20', 20, 19, 'Isomerism shown by the complex pair Co(NH₃)₅(NO₃)₃SO₄ and Co(NH₃)₅(SO₄)₃NO₃ is:', '[{"id":"A","text":"Hydrate isomerism"},{"id":"B","text":"Ionization isomerism"},{"id":"C","text":"Coordination isomerism"},{"id":"D","text":"Linkage isomerism"}]', 0, 'B', 'This form of isomerism arises when the counter ion in a complex salt is itself a potential ligand and can displace a ligand which can then become the counter ion. An example is provided by the ionisation isomers.

$$ [C o(N H_{3})_{5}(N O_{3})]S O_{4}\mathrm{a n d}[C o(N H_{3})_{5}(S O_{4})]N O_{3} $$', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (246, 'chemistry-2025-05-23-shift-2', 'q21', 21, 20, 'Decide which of the following atomic numbers are the atomic numbers of the inner transition elements

(A) 59

(B) 95

(C) 102

(D) 74', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(B), (C) and (D) only"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'B', 'Inner transition elements are the f-block elements, consisting of the Lanthanides and Actinides.

• Lanthanides: Atomic numbers 57 (La) to 71 (Lu). They fill the 4f orbital.

• Actinides: Atomic numbers 89 (Ac) to 103 (Lr). They fill the 5f orbital.

The given atomic numbers:

• (A) 59: This is Praseodymium (Pr), which is in the Lanthanide series (4f block). (Inner transition)

• (B) 95: This is Americium (Am), which is in the Actinide series (5f block). (Inner transition)

• (C) 102: This is Nobelium (No), which is in the Actinide series (5f block). (Inner transition)

• (D) 74: This is Tungsten (W), which is ad-block transition element, not an inner transition element (it''s in Group 6, Period 6). (Not inner transition)

Therefore, (A), (B), and (C) are atomic numbers of inner transition elements.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (247, 'chemistry-2025-05-23-shift-2', 'q22', 22, 21, 'Match the properties given in List-I with the metals given in List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">List-I (Property)</th>
      <th style="padding: 8px; border: 1px solid #444;">List-II (Metal)</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(A) Element with highest second ionization enthalpy</td>
      <td style="padding: 8px; border: 1px solid #444;">(I) Co</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(B) Element with highest heat of atomisation</td>
      <td style="padding: 8px; border: 1px solid #444;">(II) Cu</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(C) M in $\mathrm{M(CO)_6}$</td>
      <td style="padding: 8px; border: 1px solid #444;">(III) Zn</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(D) Element with highest third ionization enthalpy</td>
      <td style="padding: 8px; border: 1px solid #444;">(IV) Cr</td>
    </tr>
  </tbody>
</table>', '[{"id":"A","text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)"},{"id":"C","text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', '(A) Highest second ionization enthalpy -> Cu (II); (B) Highest heat of atomisation -> Co (I); (C) M in M(CO)6 -> Cr (IV); (D) Highest third ionization enthalpy -> Zn (III). Mapping: (A)-(II), (B)-(I), (C)-(IV), (D)-(III).', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (248, 'chemistry-2025-05-23-shift-2', 'q23', 23, 22, 'Which of the following reactions are involved in preparation of aldehydes?

(A) Gatterman-Koch reaction

(B) Etard Reaction

(C) Stephen Reaction

(D) Rosenmund Reaction', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(B), (C) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(A), (B) and (D) only"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (249, 'chemistry-2025-05-23-shift-2', 'q24', 24, 23, 'The relative lowering of vapor pressure is equal to the', '[{"id":"A","text":"mole fraction of solute"},{"id":"B","text":"boiling point of solvent"},{"id":"C","text":"mole fraction of solvent"},{"id":"D","text":"Vapor pressure of solute"}]', 0, 'A', 'This is directly stated by Raoult''s Law for relative lowering of vapor pressure:

$$ \frac{P^{0}-P_{s}}{P^{0}}=X_{solute} $$

Where:

$ P^{0} $ = vapor pressure of pure solvent

$ P_{s} $ = vapor pressure of solution

$ X_{solute} = mole\ fraction\ of\ solute $', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (250, 'chemistry-2025-05-23-shift-2', 'q25', 25, 24, 'Glucose reacts with Tollen''s reagent (ammoniacal silver nitrate) due to the presence of', '[{"id":"A","text":"Ester"},{"id":"B","text":"Aldehyde"},{"id":"C","text":"Ketone"},{"id":"D","text":"Alcoholic AgNO_{3}"}]', 0, 'B', '- Tollen''s reagent is a test for aldehydes. It''s a mild oxidizing agent.

• Glucose, in its open-chain form, contains an aldehyde functional group (-CHO) at C1.

• This aldehyde group is oxidized by Tollen''s reagent, reducing silver ions $ (Ag^{+}) $ to metallic silver $ (Ag) $, which forms a "silver mirror."

• Though glucose exists primarily in cyclic forms, there''s always an equilibrium with the open-chain aldehyde form, which reacts with Tollen''s reagent.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (251, 'chemistry-2025-05-23-shift-2', 'q26', 26, 25, 'Which of the following compound will undergo Cannizzaro reaction?', '[{"id":"A","text":"Methanal"},{"id":"B","text":"Cyclohexanone"},{"id":"C","text":"Propanal"},{"id":"D","text":"Acetone"}]', 0, 'A', 'In Cannizzaro reaction, aldehydes which do not have an $ \alpha $ hydrogen atom, undergo self oxidation and reduction (disproportionation) reaction on treatment with concentrated alkali. This reaction is given by methanol (formaldehyde) and benzaldehyde.

Cyclohexanone, acetone and propanal possess at least one $ \alpha $ hydrogen atom and gives Aldol condensation reaction.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (252, 'chemistry-2025-05-23-shift-2', 'q27', 27, 26, '75% of a first order reaction was completed in 16 minutes. When was it half completed?

(Given: $ \log(0.75) = -0.125 $, $ \log(0.25) = -0.602 $)', '[{"id":"A","text":"8 min"},{"id":"B","text":"12 min"},{"id":"C","text":"4 min"},{"id":"D","text":"32 min"}]', 0, 'A', 'First-Order Rate Law (Integrated): $ k = \frac{2.303}{t} \log\left(\frac{[A]_{0}}{[A]}\right) $

Where: $ k = $ rate constant, $ t = $ time, $ [A]_{0} = $ initial concentration, $ [A] = $ concentration at time $ t $

Given: 75% completed in 16 minutes.

If $ [A]_{0} = 100 $, then $ [A] = 100 - 75 = 25 $

$ k = \frac{2.303}{16} \log\left(\frac{100}{25}\right) = \frac{2.303}{16} \log(4) $

Since $ \log(4) = 2 \log(2) \approx 2 \times 0.301 = 0.602 $

$ k = \frac{2.303 \times 0.602}{16} $

For Half-Life $ (t_{1/2}) $:

Half-life is the time when the reaction is 50% completed.

So, if $ [A]_{0} = 100 $, then $ [A] = 50 $

$ k = \frac{2.303}{t_{1/2}} \log\left(\frac{100}{50}\right) = \frac{2.303}{t_{1/2}} \log(2) $

$ t_{1/2} = \frac{2.303 \log(2)}{k} = \frac{0.693}{k} $ (since $ 2.303 \times \log(2) \approx 0.693 $)

Relate 75% Completion to Half-Life:

For a first-order reaction:

After one half-life, 50% remains. After two half-lives, 25% remains.

If 25% remains, then 75% is completed.

So, 16 minutes represents two half-lives: $ 2 \times t_{1/2} = 16 $

$ t_{1/2} = \frac{16}{2} = 8 $ minutes.', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (253, 'chemistry-2025-05-23-shift-2', 'q28', 28, 27, 'Match List-I with List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">List-I (Reaction)</th>
      <th style="padding: 8px; border: 1px solid #444;">List-II (Reagent / Description)</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(A) Rosenmund reduction</td>
      <td style="padding: 8px; border: 1px solid #444;">(I) Nitrile reduced with $\mathrm{SnCl_2 + HCl}$ followed by $\mathrm{H_3O^+}$</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(B) Stephen reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(II) Acyl chloride hydrogenated over $\mathrm{Pd\text{-}BaSO_4}$</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(C) Etard reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(III) Oxidation of toluene with $\mathrm{CrO_2Cl_2}$</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(D) Gattermann-Koch reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(IV) Benzene treated with $\mathrm{CO + HCl}$ in presence of anhyd. $\mathrm{AlCl_3}$</td>
    </tr>
  </tbody>
</table>', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (I), (C) - (III), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', 'Rosenmund reduction (II), Stephen reaction (I), Etard reaction (III), Gattermann-Koch reaction (IV).', NULL, 'null', '[]', '[]', '[18,19]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (254, 'chemistry-2025-05-23-shift-2', 'q29', 29, 28, 'Match List-I with List-II:

<table border="1" style="margin: auto; width: 100%; border-collapse: collapse; text-align: left;">
  <thead>
    <tr style="background-color: rgba(255, 255, 255, 0.05);">
      <th style="padding: 8px; border: 1px solid #444;">List-I (Reaction)</th>
      <th style="padding: 8px; border: 1px solid #444;">List-II (Preparation)</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(A) Kolbe''s Reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(I) Salicylaldehyde</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(B) Reimer-Tiemann Reaction</td>
      <td style="padding: 8px; border: 1px solid #444;">(II) Salicylic acid</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(C) Williamson synthesis</td>
      <td style="padding: 8px; border: 1px solid #444;">(III) Ethyl methyl ether</td>
    </tr>
    <tr>
      <td style="padding: 8px; border: 1px solid #444;">(D) Cumene Process</td>
      <td style="padding: 8px; border: 1px solid #444;">(IV) Phenol</td>
    </tr>
  </tbody>
</table>', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (I), (C) - (III), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', '(A) Kolbe''s Reaction -> Salicylic acid (II); (B) Reimer-Tiemann Reaction -> Salicylaldehyde (I); (C) Williamson synthesis -> Ethyl methyl ether (III); (D) Cumene Process -> Phenol (IV). Mapping: (A)-(II), (B)-(I), (C)-(III), (D)-(IV).', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (255, 'chemistry-2025-05-23-shift-2', 'q30', 30, 29, 'Which structure of proteins gives rise to fibrous and globular proteins?', '[{"id":"A","text":"Primary Structure"},{"id":"B","text":"Secondary Structure"},{"id":"C","text":"Tertiary Structure"},{"id":"D","text":"Quaternary Structure"}]', 0, 'C', '• Tertiary structure refers to the overall three-dimensional folding of a single polypeptide chain. This unique 3D shape, determined by various interactions (hydrogen bonding, disulfide bridges, hydrophobic interactions, ionic bonds), is what dictates whether a protein takes on afibrous (elongated, insoluble) orglobular (compact, soluble) form.

• Primary structure is just the amino acid sequence.

• Secondary structure refers to local folding patterns like alpha-helices and beta-sheets.

- Quaternary structure involves the arrangement of multiple polypeptide subunits, but the fundamental fibrous/globular nature is established at the tertiary level for each subunit.', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (256, 'chemistry-2025-05-23-shift-2', 'q32', 32, 30, 'The function of the enzymes in various chemical reactions:', '[{"id":"A","text":"Increase activation energy"},{"id":"B","text":"Biochemical enhancers"},{"id":"C","text":"Decreases the rate of reaction"},{"id":"D","text":"Act as biological catalysts"}]', 0, 'D', 'Enzymes are biological catalysts. Their primary function is to speed up (increase the rate of) biochemical reactions by lowering the activation energy required for the reaction to proceed.

They do not increase activation energy (Option 1 is incorrect).

They do not decrease the rate of reaction (Option 3 is incorrect).', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (257, 'chemistry-2025-05-23-shift-2', 'q33', 33, 31, 'The units of rate constant of four reactions are given below. Arrange them in the increasing order of re

$$ (A)\mathbf{s}^{-1} $$

$$ (B)\mathrm{m o l}\mathrm{L}^{-1}\mathrm{s}^{-1} $$

$$ (C)mol^{1/2}L^{-1/2}s^{-1} $$

$$ (D)L^{1/2}mol^{-1/2}s^{-1} $$', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D),(A),(C),(B)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(B),(C),(A),(D)"}]', 0, 'D', 'The general unit for a rate constant $ k $ for an $ n^{\text{th}} $ order reaction is:

Units of $ k = (\text{mol L}^{-1})^{1-n} \text{s}^{-1} $ or more commonly $ \text{L}^{n-1} \text{mol}^{1-n} \text{s}^{-1} $

Let''s find the order (n) for each unit:

$$ \left(\mathbf{A}\right)\mathrm{s}^{-1} $$

Compare to $ (\text{mol L}^{-1})^{1-n}\text{s}^{-1} $. For units of $ \text{mol L}^{-1} $ to disappear, 1 - n = 0.

$$ 1-n=0\Rightarrow n=1 $$

Order = 1 (First Order)

$$ (\mathbf{B})\mathrm{m o l}\mathrm{L}^{-1}\mathrm{s}^{-1} $$

Compare to $ (\mathrm{mol~L}^{-1})^{1-n}\mathrm{s}^{-1} $. For $ mol~L^{-1} $ to have a power of 1, 1-n=1.

$$ 1-n=1\Rightarrow n=0 $$

$$ \mathrm{O r d e r}=0\ (\mathrm{Z e r o O r d e r}) $$

$$ \mathrm{(C)}\mathrm{m o l}^{1/2}\mathrm{L}^{-1/2}\mathrm{s}^{-1} $$

This is equivalent to $ (\text{mol L}^{-1})^{1/2} \text{s}^{-1} $.

$$ 1-n=\frac{1}{2}\Rightarrow n=1-\frac{1}{2}=\frac{1}{2} $$

$$ Order=\frac{1}{2}\ (Half~Order) $$

$$ \mathrm{L^{1/2}m o l^{-1/2}s^{-1}} $$

This is equivalent to $ (\text{mol L}^{-1})^{-1/2}\text{s}^{-1} $.

$$ 1-n=-\frac{1}{2}\Rightarrow n=1+\frac{1}{2}=\frac{3}{2} $$

Order = $ \frac{3}{2} $ (One and a half Order)

Increasing Order of Reaction:

0<0.5<1<1.5. So, (B)<(C)<(A)<(D)', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (258, 'chemistry-2025-05-23-shift-2', 'q34', 34, 32, 'Ethanolic acid can be converted into ethanol using reagent', '[{"id":"A","text":"Sn + HCl"},{"id":"B","text":"Na and C₂H₅OH"},{"id":"C","text":"LiAlH₄ in H₂O"},{"id":"D","text":"H₂ and Pt"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.526Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (259, 'chemistry-2025-05-23-shift-2', 'q35', 35, 33, 'Calculate the molality of 25 g of ethanoic acid (CH₃COOH) in 250 g benzene', '[{"id":"A","text":"16.64 mol kg $ ^{-1} $"},{"id":"B","text":"1.664 mol kg $ ^{-1} $"},{"id":"C","text":"166.4 mol kg $ ^{-1} $"},{"id":"D","text":"6.64 mol kg $ ^{-1} $"}]', 0, 'B', 'Formula for Molality (m): $ m = \frac{\text{moles of solute}}{\text{mass of solvent (in kg)}} $

Calculate Moles of Solute (Ethanole Acid, $ CH_{3}COOH $):

Molar mass of $ CH_{3}COOH $:

C = 12.01 g/mol,

H = 1.008 g/mol,

$$ O=16.00g/mol $$

Molar mass = 2(12.01) + 4(1.008) + 2(16.00) = 24.02 + 4.032 + 32.00 = 60.052 g/mol

$$ \mathrm{M o l e s}=\frac{\mathrm{m a s s}}{\mathrm{m o l a r m a s s}} $$

$$ \mathrm{Moles~of~CH_{3}COOH}=\frac{25\mathrm{g}}{60.052\mathrm{g/mol}}\approx0.4163\mathrm{mol} $$

Convert Mass of Solvent to kg:

$$ Mass of benzene=250g=0.250kg $$

$$ Calculate~Molality:\quad m=\frac{0.4163mol}{0.250kg}=1.6652mol kg^{-1} $$', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (260, 'chemistry-2025-05-23-shift-2', 'q36', 36, 34, '_ is the rate of a reaction at a particular moment of time.', '[{"id":"A","text":"Order of reaction"},{"id":"B","text":"Average rate"},{"id":"C","text":"Instantaneous rate"},{"id":"D","text":"Rate constant"}]', 0, 'C', '• Instantaneous rate is defined as the rate of a chemical reaction at a specific moment in time. It''s determined by finding the slope of the tangent to the concentration-time curve at that particular instant.

• Average rate is the rate over a measurable period of time.

• Order of reaction describes how the reaction rate depends on reactant concentrations.

• Rate constant is a proportionality constant in the rate law.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (261, 'chemistry-2025-05-23-shift-2', 'q37', 37, 35, 'The order of increasing boiling point for the following compounds is

(A) CH₃CH₂CH₂CH₃

(B) CH₃CH₂CH₂ CH₂OH

(C) $ C_{2}H_{5}OC_{2}H_{5} $

(D) CH₃CH₂CH₂CHO', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(A), (C), (D), (B)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'Boiling point increases with stronger intermolecular forces (IMFs).

Boiling point increases with stronger intermolecular forces (IMFs).

(A) $ CH_{3}CH_{2}CH_{2}CH_{3} $ (Alkane): Only weak London Dispersion Forces (LDFs). (Lowest BP)

(C) $ C_{2}H_{5}OC_{2}H_{5} $ (Ether): LDFs and moderate dipole-dipole forces. No H-bonding.

(D) $ CH_{3}CH_{2}CH_{2}CHO $ (Aldehyde): LDFs and stronger dipole-dipole forces (due to polar C=O). No H-bonding.

(B) $ CH_{3}CH_{2}CH_{2}CH_{2}OH $ (Alcohol): Strongest forces due to hydrogen bonding, plus dipole-dipole and LDFs. (Highest BP)

Order: Alkane < Ether < Aldehyde < Alcohol', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (262, 'chemistry-2025-05-23-shift-2', 'q38', 38, 36, 'Write the IUPAC name for the coordination compound:

[Cr(NH3)3(H2O)3]Cl3', '[{"id":"A","text":"triamminetriaquachromium (III) chloride"},{"id":"B","text":"triaquatriamminechromium (III) chloride"},{"id":"C","text":"tris(amminetriaqua)chromium (III) chloride"},{"id":"D","text":"triammine-tris(aqua)chromium (III) chloride"}]', 0, 'A', '1. Ligands: "ammine" (NH $ _{3} $) and "aqua" (H $ _{2} $O). Both are neutral.

2. Count & Alphabetize: 3 ammine, 3 aqua. "ammine" comes before "aqua". ⇒triammine, triqua.

3. Metal: Chromium (Cr).

4. Oxidation State: NH $ _{3} $(0) + H $ _{2} $O (0) + Cr (x) = +3 (due to 3Cl $ ^{-} $ counterions) $ \Rightarrow $ x = +3 (Chromium(III)).

5. Counter-ion: Chloride.

Final Name: triammine-triaqua-chromium(III) chloride.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (263, 'chemistry-2025-05-23-shift-2', 'q39', 39, 37, '50 g of ethylene glycol $ (\mathrm{C}_{2}\mathrm{H}_{6}\mathrm{O}_{2}) $ is mixed with 900 g of water. The freezing point of the solution will be', '[{"id":"A","text":"271.49 K"},{"id":"B","text":"270.15 K"},{"id":"C","text":"269.52 K"},{"id":"D","text":"273.15 K"}]', 0, 'A', '1. Molar Mass of Ethylene Glycol $ (\mathrm{C}_{2}\mathrm{H}_{6}\mathrm{O}_{2}) $: 62.07 g/mol

2. Moles of Solute: 50 g/62.07 g/mol ≈ 0.8055 mol

3. Molality (m): 0.8055 mol/0.900 kg ≈ 0.895 mol/kg

4. Freezing Point Depression $ \left(\Delta T_{f}\right) $:

$$ \Delta T_{f}=i\times K_{f}\times m $$

$$ i=1\mathrm{(n o n-e l e c t r o l y t e)} $$

$$ \Delta T_{f}=1\times1.86\mathrm{~K~k g/m o l}\times0.895\mathrm{~m o l/k g}\approx1.665\mathrm{~K~} $$

5. Freezing Point of Solution $ (T_{f}) $

$$ T_{f}^{0}(\mathrm{w a t e r})=273.15\mathrm{K} $$

$$ T_{f}=T_{f}^{0}-\Delta T_{f}=273.15\mathrm{~K}-1.665\mathrm{~K}=271.485\mathrm{~K} $$

This value is approximately 271.49 K.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (264, 'chemistry-2025-05-23-shift-2', 'q40', 40, 38, 'The major product of the following reaction is', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'D', 'Anisole undergoes Friedel-Crafts reaction, i.e., the alkyl and acyl groups are introduced at ortho and para positions by reaction with alkyl halide and acyl halide in the presence of anhydrous aluminium chloride (a Lewis acid) as catalyst.', NULL, 'null', '[]', '[{"id":"q40-figure-1","kind":"figure","path":"/local-papers/assets/chemistry-2025-05-23-shift-2/q40-figure-1.jpg","page":29,"alt":"Figure for question 40"},{"id":"q40-options","kind":"options","path":"/local-papers/assets/chemistry-2025-05-23-shift-2/q40-options.jpg","page":29,"alt":"Printed answer choices for question 40"}]', '[28,29]', 'keyed', '["image-options"]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (265, 'chemistry-2025-05-23-shift-2', 'q41', 41, 39, 'Complete the reaction by giving the final product:

Chloroethane + ethanolic (NaCN) + LiAlH_{4} \rightarrow ?', '[{"id":"A","text":"CH_{3}CH_{2}NH_{2}"},{"id":"B","text":"CH_{3}CH_{2}CH_{2}NH_{2}"},{"id":"C","text":"CH_{3}CH_{2}CN"},{"id":"D","text":"CH_{3}CH_{2}CH_{2}CN"}]', 0, 'B', 'The reaction sequence involves two steps:

1. Chloroethane $ (CH_{3}CH_{2}Cl) $ + Ethanolic NaCN:

This is a nucleophilic substitution reaction (S N 2). The cyanide ion (CN - ) displaces the chloride ion (Cl - ), extending the carbon chain by one carbon and forming a nitrile: $ CH_{3}CH_{2}Cl + NaCN \rightarrow CH_{3}CH_{2}CN + NaCl $

The product here is Propanenitrile.

2. Propanenitrile $ (CH_{3}CH_{2}CN) + LiAlH_{4} $:

Lithium Aluminium Hydride (LiAlH_{4}) is a powerful reducing agent. It reduces nitriles (-CN) to primary amines (-CH_{2}NH_{2}). CH_{3}CH_{2}CN \xrightarrow{LiAlH_{4}} CH_{3}CH_{2}CH_{2}NH_{2}

The final product is Propan-1-amine.', 'p496c0e8b4b91', 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (266, 'chemistry-2025-05-23-shift-2', 'q42', 42, 40, 'The most basic species in the following is:', '[{"id":"A","text":"$ \\mathrm{NH_{2}^{-}} $"},{"id":"B","text":"$ \\mathrm{H_{2}O} $"},{"id":"C","text":"$ \\mathrm{OH^{-}} $"},{"id":"D","text":"$ \\mathrm{NH_{3}} $"}]', 0, 'A', 'Basicity is the ability to accept a proton $ (H^{+}) $. Stronger bases have very weak conjugate acids.

Comparison of Conjugate Acids:

1. NH₂⁻: Conjugate acid is NH₃ (ammonia). NH₃ is a weak base, so NH₂⁻ is extremely strong.

2. H₂O: Conjugate acid is H₃O⁺. Water is a very weak base.

3. OH⁻: Conjugate acid is H₂O. OH⁻ is a strong base, but weaker than NH₂⁻.

4. NH₃: Conjugate acid is NH₄⁺. Ammonia is a weak base.

Order of Basicity (Strongest to Weakest): NH₂⁻>OH⁻>NH₃>H₂O

The amide ion (NH₂⁻) is derived from the very weak acid NH₃ (pKₐ ≈ 38), making it an exceptionally strong base.', 'p9756735b3e4b', 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (267, 'chemistry-2025-05-23-shift-2', 'q43', 43, 41, 'Carbylamine reaction is used as a test for:', '[{"id":"A","text":"Primary aliphatic amine"},{"id":"B","text":"Primary aliphatic and aromatic amine"},{"id":"C","text":"Secondary aliphatic amine"},{"id":"D","text":"Secondary aromatic amine"}]', 0, 'B', 'R--NH_{2}+CHCl_{3}+3KOH\xrightarrow{Heat}R--NC+3KCl+3H_{2}O

Explanation:

Aliphatic and aromatic primary amines on heating with chloroform and ethanolic potassium hydroxide form isocyanides (carbylamines), which are foul-smelling substa

Secondary and tertiary amines do not show this reaction. This reaction is known as the carbylamine reaction or isocyanide test and is used as a test for primary amin', 'p4d4b62bebc01', 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (268, 'chemistry-2025-05-23-shift-2', 'q45', 45, 42, 'Which of the following compounds will not undergo azo coupling with benzene diazonium chloride?', '[{"id":"A","text":"Anisole"},{"id":"B","text":"Phenol"},{"id":"C","text":"Aniline"},{"id":"D","text":"Nitrobenzene"}]', 0, 'D', 'Azo coupling is an electrophilic aromatic substitution reaction where the weakly electrophilic diazonium ion (Ar-N_{2}^{+}) attacks an activated aromatic ring

The aromatic ring must be highly activated by a strong electron-donating group (EDG), such as:

-OH (Phenol), -NH_{2} (Aniline), -OCH_{3} (Anisole)

Phenol, Aniline, and Anisole all contain strong EDGs that make their rings sufficiently nucleophilic to react with the diazonium ion,

typically resulting in coupling at the para position.

Nitrobenzene contains a strong electron-withdrawing group (EWG), the nitro group (-NO_{2}).

This group deactivates the benzene ring, making it too poor a nucleophile to react with the weakly electrophilic diazonium salt.', 'pa5e423ad83d5', 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (269, 'chemistry-2025-05-23-shift-2', 'q46', 46, 43, 'The conductivity of ionic electrolytic solutions does not depend on:', '[{"id":"A","text":"Concentration of electrolyte"},{"id":"B","text":"Viscosity of solvent"},{"id":"C","text":"Solvation of ion"},{"id":"D","text":"Pressure"}]', 0, 'D', 'Conductivity of ionic electrolytic solutions does not depend on pressure.', 'p30af10041eab', 'null', '[]', '[]', '[36]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (270, 'chemistry-2025-05-23-shift-2', 'q47', 47, 44, 'What is the SI unit of conductivity?', '[{"id":"A","text":"$ \\mathrm{S~m^{-1}} $"},{"id":"B","text":"$ \\Omega~\\mathrm{m} $"},{"id":"C","text":"$ \\mathrm{S~m} $"},{"id":"D","text":"$ \\Omega~\\mathrm{m^{-1}} $"}]', 0, 'A', 'SI unit of conductivity is S m^{-1}.', 'p918998dcc6b9', 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (271, 'chemistry-2025-05-23-shift-2', 'q48', 48, 45, 'Faraday''s laws of electrolysis are related to:', '[{"id":"A","text":"Speed of cation"},{"id":"B","text":"Equivalent mass of electrolyte"},{"id":"C","text":"Atomic number of anion"},{"id":"D","text":"Atomic number of cation"}]', 0, 'B', 'Faraday''s Laws of Electrolysis quantify the relationship between the amount of substance produced or consumed at an electrode and the electric char through the electrolyte

Faraday''s First Law: The mass (m) of substance liberated is directly proportional to the charge (Q) passed.

$$ m\propto Q $$

Faraday''s Second Law: The masses $ m_{1}, m_{2} $ of different substances produced by the same amount of charge are proportional to their equivalent mass

$$ \frac{m_{1}}{m_{2}}=\frac{E_{1}}{E_{2}} $$

Thus, the laws are fundamentally related to the equivalent mass (or the chemical equivalent) of the substance undergoing deposition or liberation.', 'pa7b2068c9e96', 'null', '[]', '[]', '[38]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (272, 'chemistry-2025-05-23-shift-2', 'q49', 49, 46, 'When KCl is dissolved in water, the Potassium ion is:', '[{"id":"A","text":"Oxidized"},{"id":"B","text":"Reduced"},{"id":"C","text":"Hydrated"},{"id":"D","text":"Hydrolyzed"}]', 0, 'C', 'When KCl (Potassium Chloride) dissolves in water, the solid ionic lattice dissociates into ions:

$$ \mathrm{KCl(s)}\rightarrow\mathrm{K}^{+}(aq)+\mathrm{Cl}^{-}(aq) $$

oxygen atoms (the negative end) towards the ion. This process is called hydration or solvation.

It is a salt of a strong acid (HCl) and a strong base (KOH), so neither the $ K^{+} $ nor the $ Cl^{-} $ ions undergo hydrolysis (reaction with water to change pH).

K is in its most stable oxidation state (+1) and does not undergo oxidation or reduction upon dissolving.', 'p224c1c63594d', 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (273, 'chemistry-2025-05-23-shift-2', 'q50', 50, 47, 'The following equation represents the reaction taking place in a Galvanic cell:

$$ \mathrm{Mg(s)+2Ag^{+}(0.001M) \rightarrow Mg^{2+}(0.01M)+2Ag(s)} $$

Calculate its $ E_{\text{cell}} $ at 298 K if $ E_{\text{cell}}^{\circ} = 2.91 \, \text{V} $.', '[{"id":"A","text":"2.79 V"},{"id":"B","text":"2.96 V"},{"id":"C","text":"3.21 V"},{"id":"D","text":"1.52 V"}]', 0, 'A', '$$ \mathrm{Given:}\quad\mathrm{E}_{\mathrm{c e l l}}^{\circ}=2.91\mathrm{V} $$

$$ \mathrm{Mg(s)+2Ag^{+}(0.001M)\rightarrow Mg^{2+}(0.01M)+2Ag(s)} $$

Reaction Quotient: $ Q = \frac{[\mathrm{Mg}^{2+}]}{[\mathrm{Ag}^{+}]^{2}} = \frac{0.01}{(0.001)^{2}} = \frac{10^{-2}}{10^{-6}} = 10^{4} $

Nernst Equation: $ E_{cell} = E_{cell}^{\circ} - \frac{0.0592}{n}\log Q $

$$ E_{\mathrm{c e l l}}=2.91-\frac{0.0592}{2}\mathrm{l o g}(10^{4}) $$

$$ E_{\mathrm{c e l l}}=2.91-(0.0296)(4) $$

$$ E_{\mathrm{c e l l}}=2.91-0.1184=2.7916\mathrm{V}\approx2.79\mathrm{V} $$', 'p90658ed74f64', 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (274, 'computer-science-2025', 'q01', 1, 1, 'Identify the relational algebra operation denoted by:

Course X Student:

where ''Course'' and ''Student'' are two relations and X is an operation.', '[{"id":"A","text":"Union"},{"id":"B","text":"Set Difference"},{"id":"C","text":"Cartesian Product"},{"id":"D","text":"Intersection"}]', 0, 'C', '. Cartesian Product

- The Cartesian Product combines every tuple of the first relation with every tuple of the second relation.

• Example:

Course = {C1, C2}, Student = {S1, S2, S3}

• Course $ \times $ Student = $ \{(C1,S1),(C1,S2),(C1,S3),(C2,S1),(C2,S2),(C2,S3)\} $

Other operations like Union, Intersection, or Set Difference do not combine all tuples in this way.

Tip: Whenever you see $ \times $ in relational algebra, think "every combination" $ \rightarrow $ Cartesian Product.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
