INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (282, 'computer-science-2025', 'q10', 9, 9, 'Given Relation: ''STUDENT''

Find the value of:

SELECT AVG(MARKS) FROM STUDENT;', '[{"id":"A","text":"30"},{"id":"B","text":"22.5"},{"id":"C","text":"90"},{"id":"D","text":"23"}]', 0, 'A', '.30

The AVG() function ignores NULL values when calculating the average.

Given Data:

Marks = 20, 40, NULL, 30

Calculation:

Average = (20 + 40 + 30) / 3 = 90 / 3 = 30', NULL, 'null', '[]', '[{"id":"q10-table-1","kind":"table","path":"/local-papers/assets/computer-science-2025/q10-table-1.jpg","page":4,"alt":"Table for question 10"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.531Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (283, 'computer-science-2025', 'q11', 10, 10, '_ operation is used to get the common tuples from two relations.', '[{"id":"A","text":"Union"},{"id":"B","text":"Intersect"},{"id":"C","text":"Set Difference"},{"id":"D","text":"Cartesian product"}]', 0, 'B', '. Intersect

- The INTERSECT operation in relational algebra returns only the tuples that are common to both relations.

- Union returns all tuples from both relations, Set Difference returns

tuples in one relation but not in the other, and Cartesian Product pairs all

tuples from the first relation with all tuples from the second.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.531Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (284, 'computer-science-2025', 'q12', 11, 11, 'Identify the correct IP address from the options given:', '[{"id":"A","text":"FC:F8:AE:CE:7B:16"},{"id":"B","text":"192.168.256.178"},{"id":"C","text":"192.168.0.178"},{"id":"D","text":"192.168.0.-1"}]', 0, 'C', '.192.168.0.178.

Reason: A valid IPv4 address has four numbers (0-255) separated by dots.

Option 1 is a MAC address, option 2 has 256 (invalid), option 4 has -1 (invalid), so only option 3 is correct.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.532Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (285, 'computer-science-2025', 'q13', 12, 12, 'Arrange the following python code segments in order with respect to exception handling.

(A) except ZeroDivisionError:

print("Zero denominator not allowed")

(B) finally:

print("Over and Out")

(C) try:

n=50

d=int(input("enter denominator"))

d/n=q

print("division performed")

(D) else:

print("Result="，q)', '[{"id":"A","text":"(C),(A),(B),(D)"},{"id":"B","text":"(C),(A),(D),(B)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(C),(B),(D),(A)"}]', 0, 'B', '. (C), (A), (D), (B)
Explanation: In Python:

• try: block comes first to execute code that may raise an exception.

except: block handles specific exceptions if they occur.

- else: block executes if no exception occurs.

- finally: block executes always, whether an exception occurred or not.

So the sequence is: $ \text{try} \rightarrow \text{except} \rightarrow \text{else} \rightarrow \text{finally} $.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.532Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (286, 'computer-science-2025', 'q14', 13, 13, '_ is the process of transforming data or an object in memory (RAM) to a stream of bytes called byte streams.', '[{"id":"A","text":"read()"},{"id":"B","text":"write()"},{"id":"C","text":"Pickling"},{"id":"D","text":"De-serialization"}]', 0, 'C', '. Pickling.

- Pickling is the process of converting a Python object in memory into a byte stream so it can be saved to a file or sent over a network.

- De-serialization (or unpickling) is the reverse process-converting byte streams back into Python objects.

- read() and write() are file operations, not object-to-byte conversion processes.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.532Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (287, 'computer-science-2025', 'q15', 14, 14, 'Identify the correct code to read data from the file notes.dat in a binary file:', '[{"id":"A","text":"import pickle f1=open(\"notes.dat\",\"r\") data=pickle.load(f1) print(data) f1.close()"},{"id":"B","text":"import pickle f1=open(\"notes.dat\",\"rb\") data=f1.load() print(data) f1.closen"},{"id":"C","text":"import pickle f1=open(\"notes.dat\",\"rb\") data=pickle.load(f1) print(data) f1.close()"},{"id":"D","text":"import pickle f1=open(\"notes.dat\", \"rb\") data=f1.read() print(data) f1.close()"}]', 0, 'C', '.

- To read data from a binary file using pickle, the file must be opened in binary read mode ("rb").

- The pickle.load() function is used to load the object from the file.

- Other options are incorrect because:

• Option 1: Opens in text mode "r", not binary.

- Option 2: Uses f1.load() instead of pickle.load(f1) and has a typo (f1.closen).

- Option 4: Uses f1.read(), which reads raw bytes but doesn''t deSERIALIZE the object.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.533Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (288, 'computer-science-2025', 'q16', 15, 15, 'Identify the correct python statement to open a text file "data.txt" in both read and write mode.', '[{"id":"A","text":"file.open(\"data.txt\")"},{"id":"B","text":"file.open(\"data.txt\",\"r+\")"},{"id":"C","text":"file.open(\"data.txt\".rw\")"},{"id":"D","text":"file.open(\"data.txt\",\"rw+\")"}]', 0, 'B', '. file.open("data.txt","r+").

• "r+" mode opens a file for both reading and writing.

• "rw" and "rw+" are invalid modes in Python.

• file.open("data.txt") opens the file in read-only mode by default.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.533Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (289, 'computer-science-2025', 'q17', 16, 16, 'Identify the type of expression where operators are placed before the corresponding operands:', '[{"id":"A","text":"Polish expression"},{"id":"B","text":"Infix expression"},{"id":"C","text":"Postfix expression"},{"id":"D","text":"Reverse polish expression"}]', 0, 'A', '. Polish expression.

- In a Polish expression (prefix notation), the operator comes before its operands.

○ Example: +53 means 5 + 3.

- Infix expression: Operator is between operands $(5 + 3)$.

• Postfix expression: Operator is after operands (5 +).

- Reverse Polish expression is another name for postfix notation, not prefix.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.533Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (290, 'computer-science-2025', 'q18', 17, 17, 'Evaluate the postfix expression:

2457*5/+', '[{"id":"A","text":"29"},{"id":"B","text":"30"},{"id":"C","text":"31"},{"id":"D","text":"0"}]', 0, 'C', '.31

1. Postfix evaluation: Operands are pushed to a stack; operators act on the most recent operands.

Expression: 24 5 7 * 5 / +

Step 1: Push 24 → Stack: [24]

• Step 2: Push 5 → Stack: [24, 5]

Step 3: Push 7 $ \rightarrow $ Stack: [24, 5, 7]

• Step 4: * → Pop 7 and 5, multiply: $ 5 * 7 = 35 \rightarrow $ Push 35 → Stack: [24, 35]

Step 5: Push 5 $ \rightarrow $ Stack: [24, 35, 5]

Step 6: / $ \rightarrow $ Pop 5 and 35, divide: 35 / 5 = 7 $ \rightarrow $ Push 7 $ \rightarrow $ Stack: [24, 7]

• Step 7: + → Pop 7 and 24, add: 24 + 7 = 31 → Push 31 → Stack: [31]', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (291, 'computer-science-2025', 'q19', 18, 18, 'STACK follows _ principle, where insertion and deletion is from end/ends only.', '[{"id":"A","text":"LIFO, two"},{"id":"B","text":"FIFO, two"},{"id":"C","text":"HFO, top"},{"id":"D","text":"LIFO, one"}]', 0, 'D', '. LIFO, one.

• A STACK follows the LIFO (Last In, First Out) principle.

- Insertion (push) and deletion (pop) happen from one end only, called the top of the stack.

- FIFO (First In, First Out) applies to queues, not stacks.', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (292, 'computer-science-2025', 'q20', 19, 19, 'Given a scenario:

Suppose there is a web-server hosting a website to declare results. This server can handle a maximum of 100 concurrent requests to view results, So, as to serve thousands of user requests. a _ would be the most appropriate data structure to use.', '[{"id":"A","text":"Stack"},{"id":"B","text":"Queue"},{"id":"C","text":"List"},{"id":"D","text":"Dictionary"}]', 0, 'B', '. Queue.

- A queue follows the FIFO (First In, First Out) principle, which is ideal for handling requests in the order they arrive.

In the given scenario, users'' requests to view results should be served in the order they arrive, especially when the server has a limit on concurrent requests.

- Stack (LIFO) would serve the most recent request first, which is not fair.

- List and Dictionary don''t inherently manage order or concurrency like a queue does.', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (293, 'computer-science-2025', 'q21', 20, 20, 'To perform enqueue and dequeue efficiently on a queue, which of the following operations are required?

A) isEmpty

B) peek

C) isfull

D) update', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(B) (C) and (D) only"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'B', '. (A), (B) and (C) only.

- isEmpty (A): Checks if the queue is empty before performing dequeue to avoid underflow.

- isFull (C): Checks if the queue is full before performing enqueue to avoid overflow.

- peek (B): Allows viewing the front element without removing it, which is often needed in efficient queue operations.

• update (D): Not a standard operation for basic queue functionality.', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (294, 'computer-science-2025', 'q22', 21, 21, 'Distance table:

Identify the correct place where we have to use repeaters.', '[{"id":"A","text":"Between A to B"},{"id":"B","text":"Between A to C"},{"id":"C","text":"Between A to D"},{"id":"D","text":"Between A to E"}]', 0, 'C', '. Between A to D.

- In networking, repeaters are used when the signal distance exceeds the maximum allowable range for proper transmission.

• From the distance table:

○ A to B = 20 m (within limit)

○ A to C = 50 m (within limit)

o A to D = 110 m (exceeds typical Ethernet limit of 100 m) → repeater needed

o A to E = 0 m (no distance, no repeater needed)

So, a repeater is required between A and D to ensure signal integrity.', NULL, 'null', '[]', '[{"id":"q22-figure-1","kind":"figure","path":"/local-papers/assets/computer-science-2025/q22-figure-1.jpg","page":9,"alt":"Figure for question 22"},{"id":"q22-table-2","kind":"table","path":"/local-papers/assets/computer-science-2025/q22-table-2.jpg","page":9,"alt":"Table for question 22"}]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (295, 'computer-science-2025', 'q23', 22, 22, 'In MAC address, Organisational Unique Identifier (OUI) consist of _.', '[{"id":"A","text":"32 bits"},{"id":"B","text":"48 bits"},{"id":"C","text":"24 bits"},{"id":"D","text":"64 bits"}]', 0, 'C', ') 24 bits

A MAC (Media Access Control) address is a 48-bit unique identifier for a network device. It is divided into two parts: the OUI and the device-specific ID. The OUI identifies the manufacturer of the device and occupies the first 24 bits (or first 3 bytes) of the MAC address. The remaining 24 bits are used by the manufacturer to assign unique IDs to each device.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.534Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (296, 'computer-science-2025', 'q24', 23, 23, 'Given a list numList of n elements and key value K, arrange the following steps for finding the position of the key K in the numList using binary search algorithm i.e. BinarySearch(numList, key)

(A) Calculate mid = (first + last) / 2

(B) SET first = 0, last = n-1
(C) PRINT "Search unsuccessful"
IF numList[mid] = key DRIIT "Flempt found at position" mid+1
STOP
ELSE
IF numList[mid] > key, THEN last = mid-1
EL SE first = mid + 1', '[{"id":"A","text":"(A),(B),(D),(C)"},{"id":"B","text":"(D),(B),(A),(C)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(D),(A),(B),(C)"}]', 0, 'C', ')(B),(A),(D),(C)

In binary search, you first initialize the pointers with first = 0 and last = n-1 (B). Then, calculate the middle index mid = (first + last) // 2 (A). Compare numList[mid] with the key: if equal, print the position; if numList[mid] > key, update last = mid-1; otherwise, update first = mid+1 (D). If the key is not found after the search, print "Search unsuccessful" (C).', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (297, 'computer-science-2025', 'q25', 24, 24, 'In binary search after every pass of the algorithm, the search area:', '[{"id":"A","text":"gets doubled"},{"id":"B","text":"gets reduced by half"},{"id":"C","text":"remains same"},{"id":"D","text":"gets reduced by one third"}]', 0, 'B', ') gets reduced by half

Binary search works by repeatedly dividing the search area in half. You compare the key with the middle element: if the key is smaller, you discard the right half; if larger, you discard the left half. This reduces the search area by half each time, making the search very efficient.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (298, 'computer-science-2025', 'q26', 25, 25, 'For binary search, the list is in ascending order and the key is present in the list. If the middle element is less than the key, it means:', '[{"id":"A","text":"The key is in the first half."},{"id":"B","text":"The key is in the second half."},{"id":"C","text":"The key is not in the list."},{"id":"D","text":"The key is the middle element."}]', 0, 'B', ') The key is in the second half

In an ascending sorted list, all elements after the middle element are greater than the middle element. If the middle element is less than the key, the key cannot be in the first half (which contains smaller elements). Therefore, the key must be in the second half of the list.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (299, 'computer-science-2025', 'q27', 26, 26, 'Arrange the following in order related to bubble sort for a list of elements:

(A)

-94212630

(D)

-94122630', '[{"id":"A","text":"(A), (B), (D), (C)"},{"id":"B","text":"(A),(C),(B),(D)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(C),(B),(D),(A)"}]', 0, 'B', '. (A), (C), (D), (B)

Bubble sort works by repeatedly swapping adjacent elements if they are in the wrong order.

• After each pass, the largest element "bubbles up" to its correct position.

- Applying this to the given list gives the sequence:

1. (A) - during first pass (partial swaps start)

2. (C) - after first pass

3. (D) - after second pass

4. (B) - final sorted list', NULL, 'null', '[]', '[{"id":"q27-table-1","kind":"table","path":"/local-papers/assets/computer-science-2025/q27-table-1.jpg","page":11,"alt":"Table for question 27"}]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (300, 'computer-science-2025', 'q28', 27, 27, 'The amount of time an algorithm takes to process a given data can be called its:', '[{"id":"A","text":"Process time"},{"id":"B","text":"Time period"},{"id":"C","text":"Time complexity"},{"id":"D","text":"Time bound"}]', 0, 'C', '. Time complexity

- Time Complexity is a theoretical measure that tells us how much time an algorithm takes to run depending on the size of the input data.

- It helps us compare different algorithms without actually running them - by analyzing how their runtime increases as input grows.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.535Z', NULL, NULL, 'banner', 'unreviewed', NULL, NULL);
