INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (302, 'computer-science-2025', 'q32', 29, 29, 'Match List-I with List-II', '[{"id":"A","text":"\\left(\\mathrm{A}\\right)-\\left(1\\right),\\left(\\mathrm{B}\\right)-\\left(\\mathrm{II}\\right),\\left(\\mathrm{C}\\right)-\\left(\\mathrm{III}\\right),\\left(\\mathrm{D}\\right)-\\left(\\mathrm{IV}\\right)"},{"id":"B","text":"(A) - (III), (B) - (1), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (1), (B) - (II), (C) - (IV), (D) - (I1I)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (1), (D) - (11)"}]', 0, 'B', '. (A) $ \rightarrow $ (III), (B) $ \rightarrow $ (I), (C) $ \rightarrow $ (II), (D) $ \rightarrow $ (IV)', NULL, 'null', '[]', '[{"id":"q32-table-1","kind":"table","path":"/local-papers/assets/computer-science-2025/q32-table-1.jpg","page":12,"alt":"Table for question 32"}]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (303, 'computer-science-2025', 'q33', 30, 30, 'In SQL table, the set of values which a column can take in each row is called _.', '[{"id":"A","text":"Tuple"},{"id":"B","text":"Attribute"},{"id":"C","text":"Domain"},{"id":"D","text":"Relation"}]', 0, 'C', '. Domain

In SQL, each column (attribute) in a table can take values from a specific set of permissible values, known as its domain.

For example, if a column "Age" can only have integer values between 0 and 120, then that range defines the domain of the column.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (304, 'computer-science-2025', 'q34', 31, 31, 'Which of the following is synonym for Meta - data?', '[{"id":"A","text":"Data Dictionary"},{"id":"B","text":"Database Instance"},{"id":"C","text":"Database Schema"},{"id":"D","text":"Data Constraint"}]', 0, 'A', '. Data Dictionary

Meta-data means "data about data" - it describes the structure, organization, and properties of data stored in a database.

A Data Dictionary stores this kind of information - such as table names, column names, data types, constraints, etc. Hence, it acts as a catalog of metadata.

Answer: 4. Scalar

Single row functions operate on one row at a time and return one result per row.

These are also called scalar functions, because they return a single (scalar) value for each row of input.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (305, 'computer-science-2025', 'q36', 32, 32, 'Ms Ritika wants to delete the table ''sports'' permanently. Help her in selecting the correct SQL command from the following.', '[{"id":"A","text":"DELETE FROM SPORTS;"},{"id":"B","text":"DROP SPORTS;"},{"id":"C","text":"DROP TABLE SPORTS;"},{"id":"D","text":"DELETE* FROM SPORTS;"}]', 0, 'A', '. DROP TABLE SPORTS;

In SQL:

- The DELETE command removes rows (data) from a table but keeps the table structure.

- The DROP TABLE command removes the entire table permanently, including its structure and data.

Hence, to delete the table ''sports'' permanently, the correct command is: DROP TABLE SPORTS;', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (306, 'computer-science-2025', 'q37', 33, 33, 'Which of the following are text functions?

(A) MIDO

(B) INSTRO

(C) SUBSTRO

(D) LENGTH)', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A),(B),(C)and(D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', '. (A), (B), (C) and (D)

In SQL, the following are text (string) functions:

• MIDO → Extracts a substring from text (sometimes written as SUBSTRING() or MID().

• INSTR0 → Returns the position of a substring within a string.

SUBSTR() → Extracts a part of a string (similar to MID).

• LENGTH() → Returns the number of characters in a string.

So, all four - MID, INSTR, SUBSTR, LENGTH - are text functions.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
