INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (309, 'computer-science-2025', 'q41', 36, 36, 'Bandwidth of a channel is:', '[{"id":"A","text":"The range of frequencies available for transmission of data through that channel."},{"id":"B","text":"The path of message travels between source and destination."},{"id":"C","text":"The set of rules on the Internet."},{"id":"D","text":"I he data or inormation that heeds to be exchanged."}]', 0, 'A', '. The range of frequencies available for transmission of data through that channel.

Bandwidth refers to the range of frequencies that a communication channel can use for data transmission.

A higher bandwidth means more data can be transmitted per second - just like a wider road allows more vehicles to pass.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (310, 'computer-science-2025', 'q42', 37, 37, 'Data Transfer Rate 1 Gbps is equal to:

(A) 1024 Mbps

(B) 1024 Kbps

(C) $ 2^{30} $ bps

(D) 22 bps', '[{"id":"A","text":"(A) and (D) only"},{"id":"B","text":"(A) and (C) only"},{"id":"C","text":"(B) and (D) only"},{"id":"D","text":"(B) and (C) only"}]', 0, 'B', '. (A) and (C) only (because 1 Gbps = 1024 Mbps).1 Gbps stands for

