incorrect.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (311, 'computer-science-2025', 'q43', 38, 38, 'Identify the wired transmission media for the following:

"They are less expensive and commonly used in telephone lines and LANs. These cables are of two types: Unshielded and shielded."', '[{"id":"A","text":"Optical Fibre"},{"id":"B","text":"Coaxial Cable"},{"id":"C","text":"TWisted pair cabie"},{"id":"D","text":"Microwaves"}]', 0, 'C', '. Twisted Pair Cable

The description - "less expensive, commonly used in telephone lines and LANs, available in two types: Unshielded and Shielded"- clearly refers to Twisted Pair Cable.

• Unshielded Twisted Pair (UTP): Used in telephone lines and LAN connections.

• Shielded Twisted Pair (STP): Used where extra protection from interference is needed.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (312, 'computer-science-2025', 'q44', 39, 39, 'The term Cookie is defined as:', '[{"id":"A","text":"A computer cookie is a small file or data packet which is stored by a website on the server''s computer."},{"id":"B","text":"A cookie is edited only by the website that created it, the client''s computer acts as a host to store the cookie."},{"id":"C","text":"Cookies are used by the user to store data on the computer."},{"id":"D","text":"A cookie is a security system to protect your data."}]', 0, 'B', '. A cookie is edited only by the website that created it, the client''s computer acts as a host to store the cookie.

A cookie is a small file or data packet that a website stores on the user''s (client''s) computer, not on the server.

It helps websites remember user information such as login details, preferences, or items in a shopping cart.

Only the website that created the cookie can read or modify it.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (313, 'computer-science-2025', 'q45', 40, 40, 'Identify the concept behind the below-given scenario:

If an attacker limits or stops an authorized user to access a service, device or any such resource by overloading that resource with illegitimate requests.', '[{"id":"A","text":"Snooping"},{"id":"B","text":"Eavesdropping"},{"id":"C","text":"Deniar or service"},{"id":"D","text":"Plagiarism"}]', 0, 'C', '. Denial of Service

The scenario describes a situation where an attacker overloads a server or network with fake or illegitimate requests, making it unavailable to legitimate users.

This is known as a Denial of Service (DoS) attack.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (314, 'computer-science-2025', 'q46', 41, 41, 'The HTTPS based websites require:', '[{"id":"A","text":"Search Engine Optimization"},{"id":"B","text":"Digital authenticity"},{"id":"C","text":"WWW Certificate"},{"id":"D","text":"SSL Digital Certificate"}]', 0, 'D', '. SSL Digital Certificate

Websites that use HTTPS (HyperText Transfer Protocol Secure) ensure secure data transfer between the browser and the server.

To establish this secure connection, they require an SSL (Secure Sockets Layer) Digital Certificate, which encrypts the data and verifies the website''s authenticity.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (315, 'computer-science-2025', 'q47', 42, 42, 'State the output of the following query.
SELECT ENGTH(MID(''INFORMATICS PRACTICES'',5,-5));', '[{"id":"A","text":"NO OUTPUT"},{"id":"B","text":"5"},{"id":"C","text":"0"},{"id":"D","text":"ERROR"}]', 0, 'D', '. ERROR

Let''s analyze the query:

SELECT LENGTH(MID(''INFORMATICS PRACTICES'',5,-5));

- The function MID(''INFORMATICS PRACTICES'', 5, -5) tries to extract a substring starting from position 5 with a negative length (-5).

- In SQL, the MID() (or SUBSTRING()) function does not accept negative length values.

- Using a negative number for length produces an invalid argument error.

Hence, the query will not execute successfully.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
