INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (317, 'computer-science-2025', 'q49', 44, 44, 'What will be the format of the output of the NOW function?', '[{"id":"A","text":"HH:MM:SS"},{"id":"B","text":"YYYY-MM-DD HH:MM:SS"},{"id":"C","text":"HH:MM:SS YYYY-MM-DD"},{"id":"D","text":"YYYY-DD-MM HH:MM:SS"}]', 0, 'B', '. YYYY-MM-DD HH:MM:SS

