2025-10-14 09:30:45', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (318, 'computer-science-2025', 'q50', 45, 45, 'State the output of the following query:

SELECT ROUND(9873.567,-2);', '[{"id":"A","text":"9900"},{"id":"B","text":"9873"},{"id":"C","text":"9800"},{"id":"D","text":"9873.5"}]', 0, 'A', '.9900

The SQL function ROUND(number, n) rounds a number to n digits.

- If n is positive, it rounds to that many decimal places.

- If n is negative, it rounds to the nearest 10, 100, 1000, etc.

Here:

Here:
ROUND(9873.567, -2)

- The -2 means round to the nearest hundred.

• 9873.567 → the hundreds digit is 8 and the tens digit is 7 ( $ \geq $ 5), so it rounds up to 9900.', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
