INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (323, 'english-2025-05-20-shift-1', 'q05', 5, 5, '4. ICMR wanted to take over the responsibility for the health of an average Indian.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'The passage clearly states that the internet is "flooded with wisdom on nutrition," but that this information makes it "difficult to find a balanced meal that works for you." The National Institute of Nutrition (NIN) released the guidelines specifically to give people a "comprehensive" and clear handbook on healthy eating to reduce this confusion and solve the information overload problem.', 'ped97bd32340b', 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.541Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (324, 'english-2025-05-20-shift-1', 'q06', 6, 6, '4. enforcement', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'In the phrase, "under the aegis of the Indian Council of Medical Research (ICMR)," aegis means support, sponsorship, or protection. It clarifies that the National Institute of Nutrition (NIN) released the guidelines with the official backing and authority of the ICMR, which is the main medical research body in India.', 'peab8846ef2f1', 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.541Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (325, 'english-2025-05-20-shift-1', 'q07', 7, 7, '4. The claims made by manufacturers about the product can be deceptive.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'NIN recommends reading labels because the claims made by manufacturers about the product can be deceptive. This ensures consumers can look past marketing and know the actual ingredients to make healthy choices.', 'pd8d915d5813a', 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.541Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (326, 'english-2025-05-20-shift-1', 'q08', 8, 8, '4. They direct parents on how to bring up their children.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The passage emphasizes the significance of the guidelines because of "India''s growing burden of noncommunicable diseases" (NCDs). The report specifically notes that a healthy diet based on these guidelines can prevent 80% of type 2 diabetes and significantly reduce the burden of heart disease, highlighting their primary goal is disease prevention.', 'pfeac00f5743f', 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.541Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
