INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (341, 'english-2025-05-20-shift-1', 'q24', 23, 23, 'Select the most appropriate word or phrase to complete the following sentence:-

Once you $ \underline{\text{}} $into the routine, you will find the work is quite easy.', '[{"id":"A","text":"are settled"},{"id":"B","text":"had settled"},{"id":"C","text":"settled"},{"id":"D","text":"will settle"}]', 0, 'A', '- When a sentence uses a future result ("you will find…") and starts with a time conjunction like "Once" (or if, when, as soon as), the verb in the "Once" clause must be in the Simple Present tense.

- "are settled" is the grammatically correct Simple Present (in the passive voice) needed here. The other options are incorrect tenses (past perfect, simple past, simple future).', NULL, 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.543Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (342, 'english-2025-05-20-shift-1', 'q25', 24, 24, 'Rearrange the following parts to form a meaningful sentence:

(A) surviving written literature from ancient Mesopotamia because of

(B) through the ages, including the Iliad and the Odyssey

(C) the Epic of Gilgamesh is often cited as the earliest

(D) its significantly enduring impact on ancient literary works', '[{"id":"A","text":"(C), (A), (D), (B)"},{"id":"B","text":"(B), (D), (A), (C)"},{"id":"C","text":"(C), (A), (B), (D)"},{"id":"D","text":"(B), (C), (A), (D)"}]', 0, 'A', 'The coherent sentence formed by the sequence (C), (A), (D), (B) is:

The Epic of Gilgamesh is often cited as the earliest surviving written literature from ancient Mesopotamia because of its significantly enduring impact on ancient literary works through the ages, including the Iliad.', NULL, 'null', '[]', '[]', '[38]', 'keyed', '[]', '2026-11-05T20:58:38.543Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (343, 'english-2025-05-20-shift-1', 'q26', 25, 25, 'From the given options, choose the word that best expresses the meaning of the given word: Grisly', '[{"id":"A","text":"gloomy"},{"id":"B","text":"greasy"},{"id":"C","text":"disgusting"},{"id":"D","text":"boorish"}]', 0, 'C', 'The word $ \underline{grisly} $ means causing horror or disgust; gruesome.

