INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (345, 'english-2025-05-20-shift-1', 'q28', 27, 27, 'Choose the correct word from the options given below to substitute the highlighted words:-

A careful ''preservation and protection'' of the flora and fauna is the need of the hour.', '[{"id":"A","text":"Conservation"},{"id":"B","text":"Promotion"},{"id":"C","text":"Enhancement"},{"id":"D","text":"Management"}]', 0, 'A', 'The single word that means the careful preservation and protection of natural resources, including flora and fauna, is Conservation. (Note: Option 1 is spelled as ''Conservation'', but it clearly refers to ''Conservation'').', NULL, 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:38.543Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (346, 'english-2025-05-20-shift-1', 'q29', 28, 28, 'Select the most appropriate word to fill in the blank in the following sentence:-

The oppressive regime continued to _ anyone who spoke out against its injustices.', '[{"id":"A","text":"prosecute"},{"id":"B","text":"perpetuate"},{"id":"C","text":"persecute"},{"id":"D","text":"provoke"}]', 0, 'C', 'The sentence describes an oppressive regime''s actions against people who spoke out against injustices.

• Persecute means to subject someone to hostility and ill-treatment, especially because of their political or religious beliefs.

• Prosecute means to conduct legal proceedings against. Perpetuate means to make something continue indefinitely.', NULL, 'null', '[]', '[]', '[41]', 'keyed', '[]', '2026-11-05T20:58:38.543Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (347, 'english-2025-05-20-shift-1', 'q30', 29, 29, 'Select the most appropriate expression to fill in the blank in the following sentence:

Given her fearful and timid nature in unfamiliar situations, we can say that she is _', '[{"id":"A","text":"audacious"},{"id":"B","text":"timorous"},{"id":"C","text":"reckless"},{"id":"D","text":"intrepid"}]', 0, 'B', 'The sentence describes a fearful and timid nature in unfamiliar situations.

- Timorous means showing or suffering from nervousness, fear, or a lack of confidence; timid.

- Audacious and intrepid mean brave/fearless. Reckless means without thought for danger.', NULL, 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:38.543Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
