INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (353, 'english-2025-05-20-shift-1', 'q38', 35, 35, 'Select the word or phrase that best completes the following sentence:-

Desert flowers can be invisible for years _ appear suddenly after heavy rain.', '[{"id":"A","text":"alternatively or"},{"id":"B","text":"consequently and"},{"id":"C","text":"nevertheless, so"},{"id":"D","text":"actually, but"}]', 0, 'D', 'The first blank requires an adverb that acts as a transition or intensifier, introducing a surprising fact about their invisibility: "actually" fits this.

1. The second blank requires a coordinating conjunction to connect two contrasting actions (being invisible vs. appearing suddenly): "but" is the correct choice to express this contrast.', NULL, 'null', '[]', '[]', '[49]', 'keyed', '[]', '2026-11-05T20:58:38.544Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (354, 'english-2025-05-20-shift-1', 'q39', 36, 36, 'Identify the word that is closest in meaning to the word-Relegate', '[{"id":"A","text":"Elevate"},{"id":"B","text":"Demote"},{"id":"C","text":"Acknowledge"},{"id":"D","text":"Celebrate"}]', 0, 'B', 'Relegate (means to assign to a lower position) & Demote means to move to a less important position, which is the direct meaning of relegate.', NULL, 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.544Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (355, 'english-2025-05-20-shift-1', 'q41', 37, 37, 'Rearrange the following parts to form a meaningful sentence:

(A) into simpler molecules that can be absorbed into the bloodstream

(B) digestion is an intricate process that begins in the mouth

(C) where food is broken down mechanically and chemically

(D) and continues in the stomach and intestines', '[{"id":"A","text":"(B), (C). (A). (D)"},{"id":"B","text":"(B). (D). (C). (A)"},{"id":"C","text":"(B), (A). (C). (D)"},{"id":"D","text":"(C). (B). (A). (D)"}]', 0, 'B', 'Digestion is an intricate process that begins in the mouth where food is broken down mechanically and chemically and continues in the stomach and intestines into simpler molecules that can be absorbed into the bloodstream. (BCDA should be the correct sequence)', NULL, 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:38.544Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
