INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (357, 'english-2025-05-20-shift-1', 'q43', 39, 39, 'Select the word opposite in meaning to the word: Presumptuous', '[{"id":"A","text":"Pretentious"},{"id":"B","text":"Brash"},{"id":"C","text":"Bountiful"},{"id":"D","text":"Unassuming"}]', 0, 'D', 'Presumptuous (overly confident; forward) & Unassuming means modest and not pretentious, the opposite of being presumptuous.', NULL, 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:38.544Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
