INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (365, 'english-2025-05-20-shift-2', 'q01', 1, 1, '4. A humorous story requires no artistic skill, while a comic story does.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The passage states, "The humorous story depends for its effect upon the manner of telling; the comic and the witty story, upon the matter," which directly matches option 3.', 'paf256815e0cb', 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.584Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (366, 'english-2025-05-20-shift-2', 'q02', 2, 2, '4. unlike the comic and witty stories, humorous stories do not depress the reader', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The passage explicitly says "The humorous story is a high and delicate art that requires an artist to tell," positioning it above comic/witty stories, which do not need artistic skill.

_', 'p53ed91bdca01', 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.584Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (367, 'english-2025-05-20-shift-2', 'q03', 3, 3, '4. is skillfully casual in his treatment of the punchline', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The passage says the comic storyteller "does not slur the nub, he shouts it at you and when he prints it he emphasizes the punchline with italics and exclamation marks," which means the nub (or the punchline) is stressed openly and forcefully', 'p405e680a9c09', 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.585Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (368, 'english-2025-05-20-shift-2', 'q04', 4, 4, 'How is the humour in a humorous story typically conveyed?', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'The passage states the humorous story "is told gravely, with the teller attempting to conceal the humor," contrasting it with comic storytelling that announces and emphasizes the punchline', 'pf0ef628746e9', 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.591Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (369, 'english-2025-05-20-shift-2', 'q05', 5, 5, '4. Light reflected through the cracks', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'The passage states the researchers hypothesize microbes were carried into the rock by water after formation and that "clay deposits in the fractures may have provided nutrients," which would support survival.', 'pb0749298789e', 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.591Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (370, 'english-2025-05-20-shift-2', 'q06', 6, 6, '4. By analysing clay deposits in the fractures of the rock.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The passage notes that after slicing the rock core, researchers "found microbial cells in tiny fractures" and "DNA staining and imaging with advanced microscopes confirmed the microbes were indigenous, with intact cell walls," indicating they were native and active, not contaminants.', 'pbfedb08f9139', 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.592Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (371, 'english-2025-05-20-shift-2', 'q07', 7, 7, '4. Microorganisms on Mars are likely much younger than those on Earth.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The passage notes similarities between the Bushveld rocks and Martian rocks and suggests "the same techniques could identify life on Mars," implying methodological transfer to search for subsurface biosignatures there', 'p27d83f42ab65', 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.594Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (372, 'english-2025-05-20-shift-2', 'q08', 8, 8, '4. They were found in relatively young volcanic sediments', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4 Answer: C"}]', 0, 'C', 'The passage calls the microbes "primitive in evolutionary terms" and says they offer clues about Earth''s earliest life forms and their evolution, implying their simplicity and adaptations parallel ancient life', 'p1d74a4e39de1', 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.595Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (373, 'english-2025-05-20-shift-2', 'q09', 9, 9, '4. it had a green sign', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'The paragraph states "The paint was chipped at many places; you could barely see the second ''s''," which indicates that the shop was not new.', 'p9cefbc53c922', 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.596Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (374, 'english-2025-05-20-shift-2', 'q10', 10, 10, '4. it was in a run-down neighborhood', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The paragraph says "customers barely ever walked in, as it was so hidden away in a run-down neighborhood," followed by "only disturbed five times that we spent there," linking the few interruptions to the scarcity of customers.', 'p2245b8a1bdc4', 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.596Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (375, 'english-2025-05-20-shift-2', 'q11', 11, 11, '4. was his sanctuary', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'The paragraph concludes, "The shop was my sanctuary," directly explaining why the author felt "at home" there.', 'p7082be4fd73c', 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.596Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (376, 'english-2025-05-20-shift-2', 'q12', 12, 12, '4. phonetics', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'In the paragraph, "lexicons" appear in a list of books alongside journals and biographies in a bookshop, so the word most appropriately means "dictionary."

Meaning of the other options-

Semantics: study of meaning in language.

Syntax: study of sentence structure and word arrangement.

Phonetics: study of speech sounds and their production.', 'pbd7cdaab0fb7', 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.599Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (377, 'english-2025-05-20-shift-2', 'q13', 13, 13, 'Select the verb form that most appropriately completes the following sentence:-

My sister_ me once or twice since the time she moved to Athens.', '[{"id":"A","text":"was messaging"},{"id":"B","text":"has messaged"},{"id":"C","text":"has been messaging"},{"id":"D","text":"had messaged"}]', 0, 'B', 'has messaged : Present Perfect shows an action started in the past and relevant now.

Why not others:

Has been messaging : implies ongoing activity, not occasional.

Was messaging : past continuous, no present link.

Had message: past perfect, for two past actions.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.601Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (378, 'english-2025-05-20-shift-2', 'q14', 14, 14, 'Choose the correct antonym for Acquittal from the options given below:-', '[{"id":"A","text":"confession"},{"id":"B","text":"conviction"},{"id":"C","text":"consent"},{"id":"D","text":"concord"}]', 0, 'B', 'Acquittal: legal judgment declaring a person not guilty.

Correct antonym: Conviction : formal declaration of guilt, opposite of acquittal.

Why not others:

Confession : personal admission, not a verdict.

Consent/Concord : mean agreement, unrelated to law.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.601Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (379, 'english-2025-05-20-shift-2', 'q15', 15, 15, 'Fill in the blank with the correct word from the options given below:-

Film stars and models are known for their $ \underline{\text{}} $ style.', '[{"id":"A","text":"superior"},{"id":"B","text":"frugal"},{"id":"C","text":"taciturn"},{"id":"D","text":"flamboyant"}]', 0, 'D', 'Flamboyant : showy, stylish, attracts attention; fits film stars/models.

Why not others:

Superior : better in rank/quality, not style.

Frugal : economical, opposite of flashy.

Taciturn : reserved, unrelated to style.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.602Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (380, 'english-2025-05-20-shift-2', 'q16', 16, 16, 'Fill in the blank with the correct word from the given options:-

Research has proved the significance of leading a structured life with enormous evidence to prove that mental fatigue can actually _ life.', '[{"id":"A","text":"produce"},{"id":"B","text":"curtail"},{"id":"C","text":"prolong"},{"id":"D","text":"procure"}]', 0, 'B', 'Curtail : to reduce or shorten; fits context of mental fatigue affecting life.

Why not others:

Produced: to make/create, irrelevant here.

Prolong : means to extend, opposite meaning.

Procure : to obtain, unrelated.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.605Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
