INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (384, 'english-2025-05-20-shift-2', 'q20', 20, 20, 'Choose the correct antonym for ''Infalliable'' from the options given below:-', '[{"id":"A","text":"Unerring"},{"id":"B","text":"Flawed"},{"id":"C","text":"Impeccable"},{"id":"D","text":"Explicable"}]', 0, 'B', 'Flawed: having faults or mistakes; opposite of infallible (incapable of error).

