INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (389, 'english-2025-05-20-shift-2', 'q25', 25, 25, 'Rearrange the following parts into a meaningful sentence:

(A) craftsmanship and profound spiritual depth, features

(B) ancient Indian architecture, celebrated for its intricate

(C) iconic temples, stupas, and forts that showcase', '[{"id":"A","text":"(C), (A), (B), (D)"},{"id":"B","text":"(B), (A), (D), (C)"},{"id":"C","text":"(B), (C), (D), (A)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'Ancient Indian architecture, celebrated for its intricacy, showcases iconic temples, stupas, and forts, a blend of artistic brilliance and advanced engineering, features craftsmanship and profound spiritual depth.

