INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (397, 'english-2025-05-20-shift-2', 'q33', 33, 33, 'Select the most appropriate option to fill in the blank in the following sentence:-

The _ rumble of the thunder hinted at the approaching danger, filling the air with a sense of unease.', '[{"id":"A","text":"pretentious"},{"id":"B","text":"contentious"},{"id":"C","text":"tenuous"},{"id":"D","text":"portentous"}]', 0, 'D', 'Portentous: signaling or warning of something significant/threatening; fits the ominous thunder.

