INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (399, 'english-2025-05-20-shift-2', 'q35', 35, 35, 'Select the word closest in meaning to the word Narcissism-', '[{"id":"A","text":"Meanness"},{"id":"B","text":"Self-love"},{"id":"C","text":"Modesty"},{"id":"D","text":"Magnanimity"}]', 0, 'B', 'Self-love : extreme admiration or interest in oneself; synonym of narcissism.

