INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (413, 'english-2025-05-20-shift-2', 'q50', 49, 49, 'Fill in the blanks in List-I with the appropriate homonyms from List-II:-', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)"}]', 0, 'B', 'A: disassemble - take apart the machine for transport.

