INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (414, 'general-test-2025-05-20-shift-1', 'q01', 1, 1, 'Which one of the following gland is responsible for the secretion of growth hormones?', '[{"id":"A","text":"Pineal Gland"},{"id":"B","text":"Pituitary Gland"},{"id":"C","text":"Thyroid Gland"},{"id":"D","text":"Adrenal Gland"}]', 0, 'B', 'The growth hormone (GH) is secreted by the pituitary gland (specifically the anterior pituitary). Correct answer: 2. Pituitary Gland', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.624Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (415, 'general-test-2025-05-20-shift-1', 'q02', 2, 2, 'In an A.P. if $ m^{th} $ term is n and the $ n^{th} $ term is m, where $ m \neq n $, find the $ p^{th} $ term.', '[{"id":"A","text":"$ n + m + p $"},{"id":"B","text":"m - p"},{"id":"C","text":"$ n + m - 1 $"},{"id":"D","text":"$ n + m - p $"}]', 0, 'D', 'Given:

$$ T_{m}=a+(m-1)d=n\quad\ldots(1) $$

$$ T_{n}=a+(n-1)d=m\quad\ldots(2) $$

Subtract (2) from (1):

$$ (a+(m-1)d)-(a+(n-1)d)=n-m $$

$$ (m-n)d=n-m $$

$$ d=-1 $$

Substitute $d = -1$ in (1):

$$ a+(m-1)(-1)=n $$

a - m + 1 = n

$$ a=n+m-1 $$

Now find $ T_{p} $:

$$ \begin{aligned}&T_{p}=a+(p-1)d\\=(n+m-1)+(p-1)(-1)\\&=n+m-1-p+1\\&=n+m-p\end{aligned} $$

✓ Final Answer:

4. $ n + m - p $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.624Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (416, 'general-test-2025-05-20-shift-1', 'q03', 3, 3, 'The base radius of a cone is 21 cm and the height is 28 cm, then, which of the following is/ are correct?

(A) Slant height = 35 cm

(B) Slant height = 33 cm

(C) Volume = 12936 cm^{3}

(D) Curved Surface Area = 2310 cm $ ^{2} $', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(B), (C) and (D) only"},{"id":"C","text":"(C), (D) and (A) only"},{"id":"D","text":"(D), (A) and (B) only"}]', 0, 'C', 'Given:

r = 21 cm, h = 28 cm
1. Slant height:

$$ l=\sqrt{r^{2}+h^{2}}=\sqrt{21^{2}+28^{2}}=\sqrt{1225}=35 $$

(A) correct

(B) wrong

2. Volume:

$$ \begin{aligned}V=\frac{1}{3}\pi r^{2}h=\frac{1}{3}\pi\cdot441\cdot28&=4116\pi\\ &=4116\times\frac{22}{7}=12936\end{aligned} $$

(C) correct

3. Curved Surface Area:

$$ \begin{aligned}CSA&=\pi rl=\pi\cdot21\cdot35=735\pi\\&=735\times\frac{22}{7}=2310\end{aligned} $$

(D) correct
Final Answer:

Option 3 $ \rightarrow $ (C), (D) and (A) only', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.625Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (417, 'general-test-2025-05-20-shift-1', 'q04', 4, 4, 'Who among the following is best known as the Chief Architect of the Indian Atomic Energy Program?', '[{"id":"A","text":"C.V. Raman"},{"id":"B","text":"Homi Jehangir Bhabha"},{"id":"C","text":"Meghnad N. Saha"},{"id":"D","text":"Vikram Sarabhai"}]', 0, 'B', 'The title "Chief Architect of the Indian Atomic Energy Program" is associated with:

Homi Jehangir Bhabha

He is regarded as the father of India''s nuclear program.

Correct answer:

2. Homi Jehangir Bhabha', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.625Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (418, 'general-test-2025-05-20-shift-1', 'q05', 5, 5, 'Select the figure from the options, which when placed in the blank space would complete the given pattern.', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'A', NULL, NULL, 'null', '[]', '[{"id":"q05-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q05-figure-1.jpg","page":5,"alt":"Figure for question 5"},{"id":"q05-options","kind":"options","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q05-options.jpg","page":5,"alt":"Printed answer choices for question 5"}]', '[5]', 'keyed', '["image-options"]', '2026-11-05T20:58:38.625Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (419, 'general-test-2025-05-20-shift-1', 'q06', 6, 6, 'The angle of elevation of the top of an unfinished tower at a distance of 75m from its base is $ 30^{\circ} $. How much higher must the tower be raised so that the angle of elevation of its top at the same point may be $ 60^{\circ} $?', '[{"id":"A","text":"$ 20\\sqrt{3} $ m"},{"id":"B","text":"$ 50\\sqrt{3} $ m"},{"id":"C","text":"30 m"},{"id":"D","text":"60 m"}]', 0, 'B', 'Initial height:

$$ \tan30^{\circ}=\frac{h_{1}}{75}=\frac{1}{\sqrt{3}} $$

$$ h_{1}=\frac{75}{\sqrt{3}}=25\sqrt{3} $$

Final height:

$$ \tan60^{\circ}=\frac{h_{2}}{75}=\sqrt{3} $$

$$ h_{2}=75\sqrt{3} $$

Increase in height:

$$ h_{2}-h_{1}=75\sqrt{3}-25\sqrt{3}=50\sqrt{3} $$

✓ Final Answer: 2.50√3 m', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.625Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (420, 'general-test-2025-05-20-shift-1', 'q07', 7, 7, 'Consider the compound interest of the following

(A) The compound interest on Rs 16000 at 20% per annum for 9 months, compounded quarterly is: Rs 2522

(B) The compound interest on Rs 2800 at 10% per annum for 18 months, compounded annually is: Rs 434.

Choose the correct statement(s):', '[{"id":"A","text":"Only (A)"},{"id":"B","text":"Only (B)"},{"id":"C","text":"Both (A) and (B)"},{"id":"D","text":"Neither (A) nor (B)"}]', 0, 'C', '(A)

Principal = 16000

Rate = 20% p.a. → quarterly ⇒ 5% per quarter

Time = 9 months = 3 quarters

$$ A=16000(1.05)^{3}=16000\times1.157625=18522 $$

$$ CI=18522-16000=2522 $$

(A) is correct

(B)

Principal = 2800

Rate = 10% p.a.

Time = 18 months = 1 year + 6 months

Compounded annually:

Step 1 (1 year):

$$ 2800\times1.1=3080 $$

Step 2 (next 6 months → simple interest on 3080):

$$ SI=3080\times10\%\times\frac{1}{2}=154 $$

$$ Amount=3080+154=3234 $$

CI = 3234 - 2800 = 434

(B) is correct

✓ Final Answer:

3. Both (A) and (B)', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.626Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (421, 'general-test-2025-05-20-shift-1', 'q08', 8, 8, 'How many triangles are there in the following figure?', '[{"id":"A","text":"18"},{"id":"B","text":"16"},{"id":"C","text":"12"},{"id":"D","text":"20"}]', 0, 'A', 'Step 1: Small triangles

Count all smallest unit triangles:

• Top row: 4

• Bottom row: 4

Total small = 8
Step 2: Medium triangles

Formed by combining 2 small triangles:

• Top: 3

• Bottom: 3

Total = 6

Step 3: Larger triangles

• Across full width (top): 2

• Across full width (bottom): 2

Total = 4

Step 4: Total triangles:

Final Answer: 1.18', NULL, 'null', '[]', '[{"id":"q08-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q08-figure-1.jpg","page":9,"alt":"Figure for question 8"}]', '[8,9]', 'keyed', '[]', '2026-11-05T20:58:38.626Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (422, 'general-test-2025-05-20-shift-1', 'q09', 9, 9, 'Sonam ranks 18th from the top and 15th from the bottom in certain examinations. Determine how many students appeared for the examinations?', '[{"id":"A","text":"33"},{"id":"B","text":"34"},{"id":"C","text":"32"},{"id":"D","text":"31"}]', 0, 'C', 'Use the formula:

