Final Answer: 3.32', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.626Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (423, 'general-test-2025-05-20-shift-1', 'q10', 10, 10, 'Which one among the following is a major relief feature in the Ocean floor?', '[{"id":"A","text":"Mid-Oceanic Ridges"},{"id":"B","text":"Deep Sea Plain"},{"id":"C","text":"Seamount"},{"id":"D","text":"Submarine Canyons"}]', 0, 'B', 'Hence, Deep Sea Plain They are the largest and most extensive topographic features on Earth, covering more area than any other ocean floor feature and representing the true ocean basin floor correct', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.626Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (424, 'general-test-2025-05-20-shift-1', 'q11', 11, 11, 'Who among the following awardees of the Ramon Magsaysay Award 2024 is a scholar who bridges tradition and modernity by promoting education, social entrepreneurship and culture preservation?', '[{"id":"A","text":"Farhan, Farwiza"},{"id":"B","text":"Phuntsho, Karma"},{"id":"C","text":"Miyazaki Hayao"},{"id":"D","text":"Nguyen Thi Ngoc Phuong"}]', 0, 'B', 'The correct answer is:
