INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (446, 'general-test-2025-05-20-shift-1', 'q34', 34, 33, 'Match List-I with List-II', '[{"id":"A","text":"\\ (A)-(IV),(B)-(I),(C)-(II),(D)-(III)"},{"id":"B","text":"(A) - (IV), (B) - (I), (C) - (III), (D) - (II)"},{"id":"C","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"D","text":"(A) - (III), (B) - (I), (C) - (II), (D) - (IV)"}]', 0, 'A', 'Let''s match each item with its common acid:

(A) Vinegar $ \rightarrow $ (IV) Acetic Acid

