INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (447, 'general-test-2025-05-20-shift-1', 'q35', 35, 34, 'Which of the following are non-metallic minerals?

(A) Mica

(B) Bauxite

(C) Granite

(D) Potash', '[{"id":"A","text":"(A), (C) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(B), (C) and (D) only"},{"id":"D","text":"(A), (B) and (D) only"}]', 0, 'A', 'We need to identify non-metallic minerals:

- (A) Mica → Non-metallic ✓

- (B) Bauxite → Metallic (ore of aluminium) ✗

- (C) Granite → Non-metallic (rock, used as building material)

- (D) Potash → Non-metallic (used in fertilizers) ✓

Correct combination:

(A), (C) and (D)', NULL, 'null', '[]', '[]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (448, 'general-test-2025-05-20-shift-1', 'q36', 36, 35, 'Two persons A and B appear in an interview for two vacancies. If the probabilities of their selections are 1/4 and 1/6 respectively, then the probability that none of them is selected shall be:

3. $ \frac{5}{12} $', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4 Answer: D"}]', 0, 'D', 'Given:

• $ P(A \text{ selected}) = \frac{1}{4} \Rightarrow P(A \text{ not selected}) = \frac{3}{4} $

• $ P(B \text{ selected}) = \frac{1}{6} \Rightarrow P(B \text{ not selected}) = \frac{5}{6} $

Assuming independence, probability that none is selected:

$$ \frac{3}{4}\times\frac{5}{6}=\frac{15}{24}=\frac{5}{8} $$
Final Answer:

5/8 (Option 4)', NULL, 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (449, 'general-test-2025-05-20-shift-1', 'q37', 37, 36, 'A sales agent travels a distance of 50 km in 2 hours and 30 minutes. How much faster, in kilometers per hour, on average, must he travel to make such a trip in 5/6 hours less time?', '[{"id":"A","text":"40"},{"id":"B","text":"30"},{"id":"C","text":"20"},{"id":"D","text":"10"}]', 0, 'D', 'Distance = 50 km

Step 1: Original speed

Time = 2 hours 30 minutes = 2.5 hours

$$ Speed_{1}=\frac{50}{2.5}=20km/h $$

Step 2: New time

Reduced time = $ \frac{5}{6} $ hours

$$ New~time=2.5-\frac{5}{6}=\frac{15-5}{6}=\frac{10}{6}=\frac{5}{3}hours $$

Step 3: New speed

$$ Speed_{2}=\frac{50}{5/3}=50\times\frac{3}{5}=30km/h $$

Step 4: Increase in speed

30-20=10km/h

Final Answer:

10 km/h (Option 4)', NULL, 'null', '[]', '[]', '[36]', 'keyed', '[]', '2026-11-05T20:58:38.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (450, 'general-test-2025-05-20-shift-1', 'q38', 38, 37, 'Find the coordinates of the point which divides the line segment joining the points $ (4,-3) $ and $ (8,5) $ in the ratio 3:1 internally?', '[{"id":"A","text":"(7, 3)"},{"id":"B","text":"(3, 7)"},{"id":"C","text":"(2, -2)"},{"id":"D","text":"(-4, 6)"}]', 0, 'A', 'To find the point dividing the line segment internally in the ratio 3:1, we use the section formula:

$ \left(\frac{mx_2 + nx_1}{m+n}, \frac{my_2 + ny_1}{m+n}\right) $

Here:

- $ (x_1, y_1) = (4, -3) $

- $ (x_2, y_2) = (8, 5) $

- Ratio m : n = 3 : 1

Step 1: Apply formula

$$ \begin{aligned}x&=\frac{3\cdot8+1\cdot4}{4}=\frac{24+4}{4}=7\\y&=\frac{3\cdot5+1\cdot(-3)}{4}=\frac{15-3}{4}=3\end{aligned} $$

Final Answer:

(7, 3) (Option 1)', NULL, 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (451, 'general-test-2025-05-20-shift-1', 'q39', 39, 38, 'If area of a square is 44 cm², find the area of the circle formed by the same perimeter.', '[{"id":"A","text":"50 cm²"},{"id":"B","text":"28 cm²"},{"id":"C","text":"56 cm²"},{"id":"D","text":"16 cm²"}]', 0, 'C', 'Given:

Area of square = 44 cm^{2}

Step 1: Find side of square

$$ s^{2}=44\Rightarrow s=\sqrt{44}=2\sqrt{11} $$

Step 2: Perimeter of square

$$ P=4s=8\sqrt{11} $$

This equals the circumference of the circle.

Step 3: Use circumference formula

$$ 2\pi r=8\sqrt{11}\Rightarrow r=\frac{4\sqrt{11}}{\pi} $$

Step 4: Area of circle

$$ \pi r^{2}=\pi\left(\frac{4\sqrt{11}}{\pi}\right)^{2}=\pi\cdot\frac{16\cdot11}{\pi^{2}}=\frac{176}{\pi} $$

Using $ \pi \approx \frac{22}{7} $:

$$ \frac{176}{\pi}=\frac{176\times7}{22}=56 $$

Final Answer:

56 cm $ ^{2} $ (Option 3)', NULL, 'null', '[]', '[]', '[38]', 'keyed', '[]', '2026-11-05T20:58:38.633Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (452, 'general-test-2025-05-20-shift-1', 'q40', 40, 39, 'If $ \sqrt{2}:(1+\sqrt{3})::\sqrt{6}:x $, then x is equal to:', '[{"id":"A","text":"3+\\sqrt{3}"},{"id":"B","text":"1+\\sqrt{3}"},{"id":"C","text":"\\sqrt{3}-3"},{"id":"D","text":"1-\\sqrt{3}"}]', 0, 'A', 'Given:

$$ \sqrt{2}:(1+\sqrt{3}):\sqrt{6}:x $$

This means:

$$ \frac{\sqrt{2}}{1+\sqrt{3}}=\frac{\sqrt{6}}{x} $$

Step 1: Cross multiply

$$ x\sqrt{2}=\sqrt{6}(1+\sqrt{3}) $$

Step 2: Solve for x

$$ \begin{aligned}x&=\frac{\sqrt{6}(1+\sqrt{3})}{\sqrt{2}}\\=\sqrt{\frac{6}{2}}(1+\sqrt{3})=\sqrt{3}(1+\sqrt{3})\end{aligned} $$

Step 3: Expand

$$ x=\sqrt{3}+3 $$

Final Answer:

✓ 3 + $ \sqrt{3} $ (Option 1)', NULL, 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:38.633Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (453, 'general-test-2025-05-20-shift-1', 'q41', 41, 40, 'By selling 8 pens for Rs 75, a shopkeeper loses 25%. How many pens should be sold for Rs 372 to earn a 24% profit?', '[{"id":"A","text":"30"},{"id":"B","text":"18"},{"id":"C","text":"24"},{"id":"D","text":"20"}]', 0, 'C', 'Let cost price (CP) per pen = x

Step 1: Given loss of 25%

Selling 8 pens for Rs 75 $ \Rightarrow $ SP per pen = 75/8

Loss 25% $ \Rightarrow $ SP = 75% of CP

$$ \frac{75}{8}=0.75x=\frac{3}{4}x $$

$$ x=\frac{75}{8}\times\frac{4}{3}=12.5 $$

So, CP per pen = Rs 12.5

Step 2: For 24% profit

SP per pen = 1.24 × 12.5 = 15.5

Step 3: Number of pens for Rs 372

$$ Number~of~pens=\frac{372}{15.5}=24 $$

Final Answer:

24 pens (Option 3)', NULL, 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:38.634Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (454, 'general-test-2025-05-20-shift-1', 'q42', 42, 41, 'Study the table given carefully and choose the correct number option that shall come in place of ''?'' :', '[{"id":"A","text":"130"},{"id":"B","text":"70"},{"id":"C","text":"83"},{"id":"D","text":"110"}]', 0, 'A', 'The table is:
Top row: 5 14 12
Middle row: 48 135 ?
Bottom row: 8 9 10
Observe the pattern (column-wise):
Middle number = (Top × Bottom) + Bottom
Check:
- Column 1:
$ 5 \times 8 + 8 = 40 + 8 = 48 $ ✓
- Column 2:
$ 14 \times 9 + 9 = 126 + 9 = 135 $ ✓

Apply to Column 3:
$ 12 \times 10 + 10 = 120 + 10 = 130 $

Final Answer:
✓ 130 (Option 1)', NULL, 'null', '[]', '[{"id":"q42-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q42-table-1.jpg","page":41,"alt":"Table for question 42"}]', '[41]', 'keyed', '[]', '2026-11-05T20:58:38.634Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (455, 'general-test-2025-05-20-shift-1', 'q43', 43, 42, 'Identify the mirror image of the given figure:', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'D', NULL, NULL, 'null', '[]', '[{"id":"q43-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q43-figure-1.jpg","page":43,"alt":"Figure for question 43"},{"id":"q43-options","kind":"options","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q43-options.jpg","page":43,"alt":"Printed answer choices for question 43"}]', '[42,43]', 'keyed', '["image-options"]', '2026-11-05T20:58:38.634Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (456, 'general-test-2025-05-20-shift-1', 'q44', 44, 43, 'Which one of the following statement(s) is/are correct?

(A) Every whole number is a natural number.

(B) Every natural number is a whole number.

(C) Every integer is a whole number.

(D) Every rational number is a whole number', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(B) only"},{"id":"C","text":"(B) and (A) only"},{"id":"D","text":"(D) only"}]', 0, 'B', 'Let''s evaluate each statement:

(A) Every whole number is a natural number ✗

Whole numbers include 0, but natural numbers usually start from 1 → so false.

(B) Every natural number is a whole number ✓

Natural numbers (1, 2, 3, ...) are included in whole numbers (0, 1, 2, ...).

• (C) Every integer is a whole number X

Integers include negatives $ (-1, -2, \ldots) $, which are not whole numbers.

• (D) Every rational number is a whole number X

Rational numbers include fractions (like $ 1/2 $), not all are whole.

Final Answer: (B) only (Option 2)', NULL, 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:38.635Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (457, 'general-test-2025-05-20-shift-1', 'q45', 45, 44, 'Arrange the following in the increasing order:

(A) Micrometre

(B) Centimetre

(C) Mile

(D) Kilometre', '[{"id":"A","text":"(A), (B), (D), (C)"},{"id":"B","text":"(A), (B), (C), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (A), (B), (D)"}]', 0, 'A', 'We need to arrange from smallest to largest:
- Micrometre (μm) = 10⁻⁶ m (very small)
- Centimetre (cm) = 10⁻² m
- Kilometre (km) = 10³ m
- Mile ≈ 1.6 km (larger than kilometre)

Increasing order:
Micrometre < Centimetre < Kilometre < Mile
Final Answer:
(A), (B), (D), (C) (Option 1)', NULL, 'null', '[]', '[]', '[45]', 'keyed', '[]', '2026-11-05T20:58:38.635Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (458, 'general-test-2025-05-20-shift-1', 'q46', 46, 45, 'If $6x - 10y = 10$ and $\frac{x}{x+y} = \frac{5}{7}$, then $(x-y)$ is equal to:', '[{"id":"A","text":"12"},{"id":"B","text":"8"},{"id":"C","text":"6"},{"id":"D","text":"3"}]', 0, 'D', 'We are given:

$$ 6x-10y=10\quad and\quad\frac{x}{x+y}=\frac{5}{7} $$

Step 1: Use the ratio

$$ \frac{x}{x+y}=\frac{5}{7}\Rightarrow7x=5(x+y) $$

$$ 7x=5x+5y\Rightarrow2x=5y\Rightarrow x=\frac{5}{2}y $$

Step 2: Substitute into first equation

$$ 6\left(\frac{5}{2}y\right)-10y=10 $$

$$ 15y-10y=10\Rightarrow5y=10\Rightarrow y=2 $$

Step 3: Find x

$$ x=\frac{5}{2}\times2=5 $$

Step 4: Find x - y

$$ x-y=5-2=3 $$

Final Answer:

| 3 (Option 4)', NULL, 'null', '[]', '[]', '[46]', 'keyed', '[]', '2026-11-05T20:58:38.636Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (459, 'general-test-2025-05-20-shift-1', 'q47', 47, 46, 'Which among the following are Fundamental Rights as included in Part III of the Constitution of India?

(A) Equality of opportunity in public employment

(B) Equal pay for equal work for men and women

(C) Right of minorities to establish educational institutions

(D) Right to education', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', 'Evaluate each statement under Part III (Fundamental Rights):

- (A) Equality of opportunity in public employment ✓

Comes under Article 16 (Fundamental Right).

- (B) Equal pay for equal work for men and women ✗

This is a Directive Principle of State Policy (Article 39), not a Fundamental Right.

- (C) Right of minorities to establish educational institutions ▩

Protected under Article 30 (Fundamental Right).

- (D) Right to education ✓

Included as a Fundamental Right under Article 21A.

Final Answer: (A), (C) and (D) only (Option 3)', NULL, 'null', '[]', '[]', '[47]', 'keyed', '[]', '2026-11-05T20:58:38.636Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (460, 'general-test-2025-05-20-shift-1', 'q48', 48, 47, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - $ (\\mathrm{II}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{I}) $"},{"id":"C","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"},{"id":"D","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"}]', 0, 'C', '(A)

$$ \frac{12!}{10!(2!)} $$

This is:

$$ \begin{pmatrix}12\\ 2\end{pmatrix}=\frac{12\times11}{2}=66 $$

$ \rightarrow(III) $

(B) $ ^{n}C_{2}=210 $

$$ \frac{n(n-1)}{2}=210\Rightarrow n(n-1)=420 $$

$$ n=21 $$

$ \rightarrow(IV) $

(C) $ ^{6}P_{3}-^{5}C_{2} $

$$ 6P_{3}=6\times5\times4=120 $$

$$ 5C_{2}=10 $$

120-10=110

$ \rightarrow(1) $

(D) If $ ^nC_9 =^nC_8 $, find $ ^nC_{15} $

Property: $ \binom{n}{r} = \binom{n}{r+1} \Rightarrow n = 2r + 1 $

$$ n=17 $$

$$ ^{17}C_{15}={}^{17}C_{2}=136 $$

$ \rightarrow(II) $

Final Matching:

(A) - $ (\mathrm{III}) $, (B) - $ (\mathrm{IV}) $, (C) - $ (\mathrm{I}) $, (D) - $ (\mathrm{II}) $

Correct answer: Option 3', NULL, 'null', '[]', '[{"id":"q48-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-1/q48-table-1.jpg","page":48,"alt":"Table for question 48"}]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.636Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (461, 'general-test-2025-05-20-shift-1', 'q49', 49, 48, 'Identify the odd one out :', '[{"id":"A","text":"Jayanta Talukdar"},{"id":"B","text":"Aman Saini"},{"id":"C","text":"Anshu Malik"},{"id":"D","text":"Dola Banerjee"}]', 0, 'C', 'Hence, Option 3: Anshu Malik Jayanta Talukdar, Aman Saini, and Dola Banerjee are all associated with archery, while Anshu Malik is a wrestler, making her the odd one out correct', NULL, 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.636Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (462, 'general-test-2025-05-20-shift-1', 'q50', 50, 49, 'Banda, a major city in Uttar Pradesh, is located on the banks of which one of the following rivers?', '[{"id":"A","text":"Betwa"},{"id":"B","text":"Ken"},{"id":"C","text":"Son"},{"id":"D","text":"Tapti"}]', 0, 'B', 'The correct answer is 2. Ken.

Banda in Uttar Pradesh is situated on the banks of the Ken River.

Answer: Ken', NULL, 'null', '[]', '[]', '[51]', 'keyed', '[]', '2026-11-05T20:58:38.637Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (463, 'general-test-2025-05-20-shift-2', 'q01', 1, 1, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (III), (C) - (IV), (D) - (I)"},{"id":"C","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"},{"id":"D","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"}]', 0, 'C', '(A) $ \frac{1}{6!} + \frac{1}{7!} = \frac{x}{8!} $

$$ \frac{1}{6!}=\frac{1}{720},\quad\frac{1}{7!}=\frac{1}{5040} $$

$$ LCM=5040\Rightarrow\frac{7+1}{5040}=\frac{8}{5040}=\frac{1}{630} $$

Now,

$$ \frac{x}{8!}=\frac{x}{40320}=\frac{1}{630}\Rightarrow x=\frac{40320}{630}=64 $$

(A) $ \rightarrow $ (III) 64

(B) $ \frac{n!}{(n-r)!} $, n = 6, r = 2

$$ \frac{6!}{4!}=6\times5=30 $$

(B) $ \rightarrow $ (IV) 30

(C) $ \mathrm{f}f^{n}C_{9}=^{n}C_{8} $

Property:

$$ {}^{n}C_{r}={}^{n}C_{n-r} $$

So,

$$ 9=n-8\Rightarrow n=17 $$

$$ ^{17}C_{17}=1 $$

(C) $ \rightarrow(1) $ 1

(D) $ ^{6}P_{3}-^{5}P_{2} $

$$ ^{6}P_{3}=6\times5\times4=120 $$

$$ ^{5}P_{2}=5\times4=20 $$

$$ 120-20=100 $$

(D) $ \rightarrow $ (II) 100

Final Matching:

(A) $ \rightarrow $ (III)

(B) $ \rightarrow $ (IV)

(C) $ \rightarrow $ (I)

(D) $ \rightarrow $ (II)

Correct Answer: 3. (A) - (III), (B) - (IV), (C) - (I), (D) - (II)', NULL, 'null', '[]', '[{"id":"q01-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q01-table-1.jpg","page":1,"alt":"Table for question 1"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.637Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (464, 'general-test-2025-05-20-shift-2', 'q03', 2, 2, 'If HOME is coded as 815135. How can ROAD be written as?', '[{"id":"A","text":"810034"},{"id":"B","text":"181514"},{"id":"C","text":"351518"},{"id":"D","text":"510035"}]', 0, 'B', 'Given: HOME → 815135

Break it letter-wise using positions in the alphabet:

- $ H = 8 $

- $ O = 15 $

- $ M = 13 $

- $ E = 5 $

So, HOME = 8 15 13 5 → 815135

Now apply the same rule to ROAD:

- R = 18

- O = 15

- A = 1

- D = 4

So, ROAD = 18 15 14 → 181514

Correct Answer: 2.181514', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.638Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (465, 'general-test-2025-05-20-shift-2', 'q04', 3, 3, '(A) and (D) are incorrect but (B) and (C) are correct', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'Given:

• B is the son of C, but C is not the mother → C is father → C = male

• A and C are married $ \rightarrow $ A = female

• E is the brother of C $ \rightarrow $ E = male

• D is the daughter of A $ \rightarrow $ D = female

• F is the brother of B $ \rightarrow $ F = male

Children of A and C:

B(son)

• D (daughter)

• F (son)

So, A has 3 children.

Now evaluate statements:

(A) There are only three male members

Males: C, E, B, F $ \rightarrow $ 4 males ✗ (False)

(B) A has only three children

B, D, F $ \rightarrow $ 3 children ✓ (True)

(C) A and D are both females

A (wife), D (daughter) $ \rightarrow $ True ✓

(D) D is a female but A is not a female

A is female $ \rightarrow $ False ✗

Final Answer:

4. (A) and (D) are incorrect but (B) and (C)

4. (A) and (D) are incorrect but (B) and (C) are correct', 'p359cb7b2c350', 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.638Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (466, 'general-test-2025-05-20-shift-2', 'q05', 4, 4, 'If J is the sister of K. K is the sister of L. L is the sister of M. M is the brother of N. Then which of the following statements is not necessary true?

(A) K and L are sisters.

(B) M and N are brothers.

(C) L is sister of N.

(D) J, K, L are females and M is male.', '[{"id":"A","text":"(B) and (D) only"},{"id":"B","text":"(B) only"},{"id":"C","text":"(A) and (C) only"},{"id":"D","text":"(A) only"}]', 0, 'B', 'Given:

• J is sister of K → J = female

• K is sister of L → K = female → L can be male or female

• L is sister of M → L = female → M can be male or female

• M is brother of $ N \to M = \text{male} \to N $ can be male or female

Now check statements:

(A) K and L are sisters

• K = female, L = female

✓ True (necessary)

(B) M and N are brothers

- M is male, but N''s gender is not given

✗ Not necessarily true

(C) L is sister of N

- L is sister of M, and M is brother of N → they are siblings

- L is female $ \rightarrow $ sister of N

✓ True (necessary)

(D) J, K, L are females and M is male

J, K, L = females ✓

• M = male ✓

✓ True (necessary)

Final Answer:

Only (B) is not necessarily true.

Correct Answer: 2. (B) only', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.638Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (467, 'general-test-2025-05-20-shift-2', 'q07', 5, 5, 'If day before yesterday was Friday, then what will be the Tuesday?', '[{"id":"A","text":"A day after tomorrow"},{"id":"B","text":"tomorrow"},{"id":"C","text":"today"},{"id":"D","text":"$ 3^{rd} $ day after today"}]', 0, 'A', 'Let''s solve step by step:

- Day before yesterday = Friday

- So, yesterday = Saturday

• Therefore, today = Sunday

Now find Tuesday relative to today (Sunday):

• Monday → 1 day after today

Tuesday → 2 days after today

This is same as "day after tomorrow"

Correct Answer: 1. A day after tomorrow', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.638Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (468, 'general-test-2025-05-20-shift-2', 'q08', 6, 6, 'Six friends, A, B, C, D, E and F are sitting in a row facing towards East. E and F are in the center, and A and B are at the ends. C is sitting on the left of A. Then match List-I with List-II', '[{"id":"A","text":"(A) - (IV), (B) - (II), (C) - (I), (D) - (III)"},{"id":"B","text":"(A) - (III), (B) - (II), (C) - (I), (D) - (IV)"},{"id":"C","text":"(A) - (III), (B) - (I), (C) - (II), (D) - (IV)"},{"id":"D","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"}]', 0, 'B', 'Given:

• 6 people: A, B, C, D, E, F

• Facing East (so right = forward direction → your right side is actual right)

• E and F are in the center → positions 3 & 4

• A and B are at the ends → positions 1 & 6

- C is on the left of A

Step 1: Place A and B

Positions: _ Ends → A and B

If A is at position 1, then C cannot be left of A $ \times $ So, A must be at position 6, and B at position 1

Step 2: Place C

C is to the left of A (pos 6) $ \rightarrow $ so C is at pos 5

Step 3: Place E and F (center)

Positions 3 & 4 $ \rightarrow $ E and F

Step 4: Remaining position

Only position 2 left $ \rightarrow $ D

Final arrangement:

B D E/F F/E C A

Now answer:

(A) People to the right of D (pos 2)

→ positions 3,4,5,6 → 4 people → (III)

(B) Who is on the right of B (pos 1)

→ position 2 → D → (II)

(C) Immediate left of C (pos 5)

→ position 4 $ \rightarrow $ F $ \rightarrow $ (I)

(D) People to the left of E (pos 3 or 4)

• If E at 3 → left = 2 people

• If E at $4 \rightarrow$ left = 3 people

But only matching option is $2 \rightarrow$ (IV)

Final Matching:

(A) $ \rightarrow $ (III)

(B) $ \rightarrow $ (II)

(C) $ \rightarrow $(I)

(D) $ \rightarrow $ (IV)

Correct Answer: 2. (A)-(III), (B)-(II), (C)-(I), (D)-(IV)', NULL, 'null', '[]', '[{"id":"q08-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q08-table-1.jpg","page":9,"alt":"Table for question 8"}]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.638Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (469, 'general-test-2025-05-20-shift-2', 'q09', 7, 7, 'Arrange the following major advances in Indian Epigraphy in chronological order, beginning with the earliest to the most recent.

(A) Alexander Cunningham published a set of Ashokan inscriptions

(B) James Pinsep decipherers Ashokan Brahmi

(C) First issue of Epigraphia Indica

(D) First issue of Epigraphia Carnatica', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (B), (D), (C)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(B), (A), (D), (C)"}]', 0, 'C', 'Key years:

Key words:
• (B) James Prinsep deciphered Brahmi $ \rightarrow $ 1837
• (A) Cunningham published Ashokan inscriptions $ \rightarrow $ 1870s
• (C) First issue of Epigraphia Indica $ \rightarrow $ 1888
• (D) First issue of Epigraphia Carnatica $ \rightarrow $ 1894
Chronological order:
(B) $ \rightarrow $ (A) $ \rightarrow $ (C) $ \rightarrow $ (D)
Correct Answer: 3. (B), (A), (C), (D)', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (470, 'general-test-2025-05-20-shift-2', 'q10', 8, 8, 'Which one of the following is $ \underline{\text{NOT}} $ an example of "In Situ" biodiversity conservation efforts in India?', '[{"id":"A","text":"Botanical Garden"},{"id":"B","text":"National Park"},{"id":"C","text":"Wildlife Sanctuaries"},{"id":"D","text":"Biosphere Reserve"}]', 0, 'A', '1. Botanical Garden

Why:

• In situ conservation = protecting species in their natural habitat

Examples: National Park, Wildlife Sanctuary, Biosphere Reserve

• Botanical Garden is ex situ conservation, because plants are conserved outside their natural habitat.

Correct Answer: 1. Botanical Garden', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (471, 'general-test-2025-05-20-shift-2', 'q11', 9, 9, 'Point A (4, 2) divides segment BC in the ratio 2:5. Coordinates of B and C are (2,6), (9,y) respectively. Find the value of y.', '[{"id":"A","text":"6"},{"id":"B","text":"6"},{"id":"C","text":"8"},{"id":"D","text":"8"}]', 0, 'D', 'Use section formula (internal division):

$$ A=\left(\frac{2x_{2}+5x_{1}}{2+5},\frac{2y_{2}+5y_{1}}{2+5}\right) $$

Here,

$ B(2,6) = (x_1, y_1) $

$ C(9,y)=(x_2,y_2) $

Ratio = 2:5

$ A = (4, 2) $

For x-coordinate:

$$ 4=\frac{2(9)+5(2)}{7}=\frac{18+10}{7}=\frac{28}{7}=4\checkmark $$

For y-coordinate:

$$ 2=\frac{2(y)+5(6)}{7} $$

$$ 2=\frac{2y+30}{7} $$

14=2y+30

2y = -16 $ \Rightarrow $ y = -8

Correct Answer: 4. -8', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (472, 'general-test-2025-05-20-shift-2', 'q13', 10, 10, 'Megha is fifth from the left end and Priya is tenth from the right end in a row of girls. If there are nine girls between

Megha and Priya, how many girls are there in the rows?', '[{"id":"A","text":"26"},{"id":"B","text":"25"},{"id":"C","text":"24"},{"id":"D","text":"23"}]', 0, 'C', 'Let total girls = N

- Priya is 10th from right → position from left = N - 9

Given: 9 girls between them

N-14=10\Rightarrow N=24

Correct Answer: 3.24', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
