INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (475, 'general-test-2025-05-20-shift-2', 'q17', 13, 13, 'What will be the measurement of the angle made by the hands of a clock when the time is 8:40?', '[{"id":"A","text":"20^{0}"},{"id":"B","text":"350"},{"id":"C","text":"485^{0}"},{"id":"D","text":"50^{0}"}]', 0, 'A', 'Use the clock angle formula:

