INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (481, 'general-test-2025-05-20-shift-2', 'q23', 19, 19, 'The age distribution of 40 children is as follows

Consider the following statements in respect of the above frequency distribution.

(A) The median of the age distribution is 7 yr.

(B) 70% of the children are in the age group 6-9 yr.

(C) The modal class of the children is 8-9 yr.

Which of the above statements are true?', '[{"id":"A","text":"(A) and (B) only"},{"id":"B","text":"(B) and (C) only"},{"id":"C","text":"(A) and (C) only"},{"id":"D","text":"(A), (B) and (C) only"}]', 0, 'D', 'Given data:

Frequencies: 4, 7, 9, 12, 6, 2 (Total = 40)

(A) Median

Cumulative frequencies:

4, 11, 20, 32, 38, 40

$$ \frac{N}{2}=20 $$

Median class = 7-8

Median $ \approx $ 7 (approx) $ \rightarrow $ True ✓

(B) % in 6-9 age group

$$ 6-7+7-8+8-9=7+9+12=28 $$

$$ \frac{28}{40}\times100=70\% $$

→ True ✓

(C) Modal class

Highest frequency = 12 → class 8-9

→ True ✓

Correct Answer: 4. (A), (B) and (C) only', NULL, 'null', '[]', '[{"id":"q23-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q23-table-1.jpg","page":24,"alt":"Table for question 23"}]', '[23,24]', 'keyed', '[]', '2026-11-05T20:58:38.641Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
