Problem figure:', '[{"id":"A","text":"$$ \\mid $$"},{"id":"B","text":"$$ \\boxed{一} $$"},{"id":"C","text":"$$ \\mid $$"},{"id":"D","text":"$$ \\boxed{\\quad} $$"}]', 0, 'A', 'Ⅰ', NULL, 'null', '[]', '[{"id":"q24-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q24-table-1.jpg","page":26,"alt":"Table for question 24"}]', '[25,26]', 'keyed', '[]', '2026-11-05T20:58:38.641Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (483, 'general-test-2025-05-20-shift-2', 'q25', 21, 21, 'The remainder when $ (15^{23} + 23^{23}) $ is divided by 19, is:', '[{"id":"A","text":"18"},{"id":"B","text":"15"},{"id":"C","text":"4"},{"id":"D","text":"0"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.641Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (484, 'general-test-2025-05-20-shift-2', 'q26', 22, 22, 'The monthly salary of A, B and C are in the ratio 2:3:5. If C''s monthly salary is Rs.1200 more than that of A, then B''s annual salary is:', '[{"id":"A","text":"Rs. 24000"},{"id":"B","text":"Rs. 14400"},{"id":"C","text":"Rs. 12000"},{"id":"D","text":"Rs. 96000"}]', 0, 'B', 'Let monthly salaries be:

A: B: C = 2x: 3x: 5x

Given:

C - A = 1200

5x-2x=3x=1200\Rightarrow x=400

B''s monthly salary:

3x = 3 × 400 = 1200

B''s annual salary:

1200×12=14400

Correct Answer: 2. Rs. 14400', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.641Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (485, 'general-test-2025-05-20-shift-2', 'q27', 23, 23, 'Which of the following Amendments to the Constitution of India provided that the total number of Ministers, including the Prime Minister, in the Council of Ministers shall not exceed 15% of the total members of the Lok Sabha?', '[{"id":"A","text":"91st Amendment"},{"id":"B","text":"93rd Amendment"},{"id":"C","text":"95th Amendment"},{"id":"D","text":"99th Amendment"}]', 0, 'A', '1. 91st Amendment

The 91st Constitutional Amendment Act, 2003 fixed that the total number of ministers, including the Prime Minister, cannot exceed 15% of the total strength of the Lok Sabha.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.642Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (486, 'general-test-2025-05-20-shift-2', 'q28', 24, 24, 'What number should replace the question mark ?', '[{"id":"A","text":"5"},{"id":"B","text":"26"},{"id":"C","text":"0"},{"id":"D","text":"48"}]', 0, 'A', 'Pattern:

Center number = (Top-left + Bottom-left) - (Top-right + Bottom-right)

Check:

1st box:

$$ (13+12)-(4+5)=25-9=16\neq2 $$

Try another pattern:

New pattern:

Center = (Top-left × Bottom-right) - (Top-right × Bottom-left)

1st box:

$$ (13\times5)-(4\times12)=65-48=17\neq2 $$

Try simpler:

Correct pattern:

Center = (Top-left - Top-right) × (Bottom-left - Bottom-right)

1st box:

(13 - 4)(12 - 5) = 9 \times 7 = 63 \neq 2

Final correct pattern:

Center = (Sum of all numbers) ÷ 17

Check 2nd box:

$$ 23+9+22+32=86,86\div?=24 $$

Not consistent $ \rightarrow $ try difference pattern:

Correct observation:

Center = (Top-left + Bottom-right) - (Top-right + Bottom-left)

1st box:

(13+5)-(4+12)=18-16=2√

2nd box:

(23+32)-(9+22)=55-31=24 ✓

Apply to 3rd box:

(2+24)-(9+12)=26-21=5

Correct Answer: 1.5', NULL, 'null', '[]', '[{"id":"q28-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q28-figure-1.jpg","page":29,"alt":"Figure for question 28"},{"id":"q28-figure-2","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q28-figure-2.jpg","page":29,"alt":"Figure for question 28"}]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.642Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
