25WV52, 23TS32, 21QP12,?,17KJ71', '[{"id":"A","text":"19MN91"},{"id":"B","text":"19ON92"},{"id":"C","text":"19NM91"},{"id":"D","text":"19LK92"}]', 0, 'C', 'Series: 25WV52, 23TS32, 21QP12,?, 17KJ71

