INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (488, 'general-test-2025-05-20-shift-2', 'q30', 26, 26, 'Which of the following are "unicellular" organisms?

(A) Plasmodium

(B) Protoza

(C) Spirogyra

(D) Leishmania', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'Let''s check each option:

• (A) Plasmodium $ \rightarrow $ unicellular (a protozoan parasite)

• (B) Protozoa $ \rightarrow $ unicellular organisms by definition ✓

• (C) Spirogyra $ \rightarrow $ multicellular (filamentous green algae)

• (D) Leishmania $ \rightarrow $ unicellular (a protozoan parasite)
Correct combination:

(A), (B), and (D) only

Final Answer: Option 2', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.642Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (489, 'general-test-2025-05-20-shift-2', 'q31', 27, 27, 'The Tlawng river is located at which of the following cities in India?', '[{"id":"A","text":"Imphal"},{"id":"B","text":"Aizawl"},{"id":"C","text":"Agartala"},{"id":"D","text":"Itanagar"}]', 0, 'B', 'The Tlawng River is associated with Aizawl in Mizoram.

Correct answer: 2. Aizawl', NULL, 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:38.642Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (490, 'general-test-2025-05-20-shift-2', 'q32', 28, 28, 'How many two-digit numbers are divisible by 3?', '[{"id":"A","text":"30"},{"id":"B","text":"20"},{"id":"C","text":"10"},{"id":"D","text":"8"}]', 0, 'A', 'Answer: A

Two-digit numbers range from 10 to 99.

First multiple $ \geq 10 \rightarrow 12 $

Last multiple ≤ 99 → 99

Now count them:

This is an arithmetic sequence: 12, 15, 18, ..., 99

Common difference = 3

Number of terms: _

$$ n=\frac{99-12}{3}+1=\frac{87}{3}+1=29+1=30 $$

✓ Final Answer:

1. 30', NULL, 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (491, 'general-test-2025-05-20-shift-2', 'q33', 29, 29, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (IV), (C) - (I), (D) - (III)"},{"id":"C","text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', '(A) Least number subtracted from 2025 to be divisible by 17

To find this, we divide 2025 by 17 and find the remainder:

· 2025 = $ 17 \times 119 + 2 $

• The remainder is 2.

- Subtracting the remainder makes the number perfectly divisible.

• Result: (A) matches with (II).
(B) Least number added to $ 1057^{5} $ to be divisible by 23

First, find the remainder when 1057 is divided by 23:

- $ 1057 \div 23 = 45 $ with a remainder of 22 (which is the same as saying -1 in modular arithmetic because $ 1057 + 1 = 1058 $, and $ 1058 \leq 23 \times 46 $).

• So, 1057 ≡ -1 (mod 23).

• Then, $1057^{5} \equiv (-1)^{5} \pmod{23} \equiv -1 \pmod{23}$.

- A remainder of -1 means the number is 1 short of being divisible. Therefore, we need to add 1.

• Result: (B) matches with (IV).

(C) Unit digit of $ 6^{15} - 7^{4} $

- Unit digit of $ 6^{15} $: Any power of 6 always ends in 6.

• Unit digit of 74:

$ 0.7^{1}=7 $

$ 7^{2} = 49 \rightarrow 9 $

$ 7^{3} = 343 \to 3 $

$ 7^{4} = 2401 \rightarrow 1 $

- The difference of the unit digits is 6 - 1 = 5.

• Result: (C) matches with (I).

(D) Product of any number and the 1st whole number

• The set of whole numbers starts from 0: {0, 1, 2, 3, ...}.

• The 1st whole number is 0.

- The product of any number and 0 is always 0.

• Result: (D) matches with (III).

Conclusion

Matching the results:

(A) $ \rightarrow $ (II)

(B) $ \rightarrow $ (IV)

(C) $ \rightarrow(1) $

(D) $ \rightarrow $ (III)

This corresponds to Option 2.', NULL, 'null', '[]', '[{"id":"q33-table-1","kind":"table","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q33-table-1.jpg","page":35,"alt":"Table for question 33"}]', '[34,35]', 'keyed', '[]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (492, 'general-test-2025-05-20-shift-2', 'q34', 30, 30, 'At the foot of a mountain, the elevation of the summit is $ 45^{\circ} $. After ascending 2 kilometers towards the mountain, at an incline of $ 30^{\circ} $, the elevation changes to $ 60^{\circ} $. Determine the height of the mountain?', '[{"id":"A","text":"( $ \\sqrt{3} - 1 $) kilometre"},{"id":"B","text":"( $ \\sqrt{3} + 1 $) kilometre"},{"id":"C","text":"( $ \\sqrt{3} - 2 $) kilometres"},{"id":"D","text":"( $ \\sqrt{3} + 2 $) kilometres"}]', 0, 'B', 'Step 1: From the foot of the mountain

Angle of elevation = $ 45^{\circ} $

$$ \tan45^{\circ}=\frac{h}{x}=1\Rightarrow h=x $$

So, horizontal distance = x = h
Step 2: After moving 2 km at $ 30^{\circ} $ incline

Horizontal distance covered:

$$ 2\cos30^{\circ}=2\cdot\frac{\sqrt{3}}{2}=\sqrt{3} $$

Vertical height gained:

$$ 2\sin30^{\circ}=2\cdot\frac{1}{2}=1 $$

New position:

• Horizontal distance from mountain base = $ h - \sqrt{3} $

Height above ground = 1

Step 3: New angle of elevation = $ 60^{\circ} $

$$ \tan60^{\circ}=\frac{h-1}{h-\sqrt{3}}=\sqrt{3} $$

Step 4: Solve

$$ \frac{h-1}{h-\sqrt{3}}=\sqrt{3} $$

$$ h-1=\sqrt{3}(h-\sqrt{3}) $$

$$ h-1=\sqrt{3}h-3 $$

$$ 2=(\sqrt{3}-1)h $$

$$ h=\frac{2}{\sqrt{3}-1} $$

Rationalize:

$$ h=\frac{2(\sqrt{3}+1)}{2}=\sqrt{3}+1 $$
✓ Final Answer:

2. $ (\sqrt{3} + 1) $ kilometre', NULL, 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (493, 'general-test-2025-05-20-shift-2', 'q35', 31, 31, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (III), (B) - (II), (C) - (IV), (D) - (I)"},{"id":"B","text":"(A) - (III), (B) - (II), (C) - (I), (D) - (IV)"},{"id":"C","text":"(A) - (III), (B) - (I), (C) - (II), (D) - (IV)"},{"id":"D","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"}]', 0, 'B', '(A) Gukesh D

