Question figure:', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'D', NULL, NULL, 'null', '[]', '[{"id":"q36-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q36-figure-1.jpg","page":40,"alt":"Figure for question 36"},{"id":"q36-options","kind":"options","path":"/local-papers/assets/general-test-2025-05-20-shift-2/q36-options.jpg","page":40,"alt":"Printed answer choices for question 36"}]', '[40]', 'keyed', '["image-options"]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (495, 'general-test-2025-05-20-shift-2', 'q37', 33, 33, 'Arrange the following historical events in chronological order, beginning with the earliest to the most recent.

(A) Universities established in Bombay, Madras and Calcutta

(B) Transfer of Capital from Calcutta to Delhi

(C) Supreme Court set up in Calcutta by the East India Company

(D) Asiatic Society founded by Sir William Jones', '[{"id":"A","text":"(C), (D), (A), (B)"},{"id":"B","text":"(C), (D), (B), (A)"},{"id":"C","text":"(D), (C), (B), (A)"},{"id":"D","text":"(D), (C), (A), (B)"}]', 0, 'A', 'Dates:

- (C) Supreme Court set up in Calcutta - 1774

- (D) Asiatic Society founded - 1784

- (A) Universities in Bombay, Madras and Calcutta - 1857

- (B) Transfer of capital from Calcutta to Delhi - 1911

So the correct chronological order is:

(C), (D), (A), (B)

Final Answer: Option 1', NULL, 'null', '[]', '[]', '[41]', 'keyed', '[]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (496, 'general-test-2025-05-20-shift-2', 'q38', 34, 34, 'Ram, Shyam and Hari can complete a work in 20, 25 and 30 days, respectively.

Consider the following statements:

(A) Ram and Shyam together will complete the work in $ 11\frac{1}{9} $ days.

(B) Shyam and Hari together will complete the work in 14 days.', '[{"id":"A","text":"(A) only"},{"id":"B","text":"(B) only"},{"id":"C","text":"(A) and (B)"},{"id":"D","text":"Neither (A) nor (B)"}]', 0, 'A', 'Ram, Shyam, Hari rates:

• Ram = $ \frac{1}{20} $

$ \bullet $ Shyam = $ \frac{1}{25} $

Hari = $ \frac{1}{30} $

(A) Ram + Shyam

$$ \frac{1}{20}+\frac{1}{25}=\frac{5+4}{100}=\frac{9}{100} $$

Time taken:

$$ \frac{1}{9/100}=\frac{100}{9}=11\frac{1}{9}days $$

Statement (A) is correct

(B) Shyam + Hari

$$ \frac{1}{25}+\frac{1}{30}=\frac{6+5}{150}=\frac{11}{150} $$

Time taken:

$$ \frac{150}{11}\approx13.64days $$

❌ Not 14 days → Statement (B) is incorrect
Final Answer:

1. (A) only', NULL, 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:38.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (497, 'general-test-2025-05-20-shift-2', 'q39', 35, 35, 'The area of a sector of a circle of radius 36 cm is $ 72\pi\ \text{cm}^2 $. Find the length of the corresponding arc of the sector.', '[{"id":"A","text":"$ 4\\pi $ cm"},{"id":"B","text":"$ 3\\pi $ cm"},{"id":"C","text":"$ 2\\pi $ cm"},{"id":"D","text":"$ \\pi $ cm"}]', 0, 'A', 'We use the sector formulas:

Area of sector:

$$ A=\frac{1}{2}r^{2}\theta $$

Arc length:

$$ L=r\theta $$

Step 1: Find $ \theta $

Given:

$$ 72\pi=\frac{1}{2}\cdot36^{2}\cdot\theta $$

$$ 72\pi=\frac{1}{2}\cdot1296\cdot\theta=648\theta $$

$$ \theta=\frac{72\pi}{648}=\frac{\pi}{9} $$

Step 2: Find arc length

$$ L=r\theta=36\cdot\frac{\pi}{9}=4\pi $$
✓ Final Answer:

1. $ 4\pi cm $', NULL, 'null', '[]', '[]', '[43]', 'keyed', '[]', '2026-11-05T20:58:38.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (498, 'general-test-2025-05-20-shift-2', 'q40', 36, 36, 'Kalibangan, an archaeological site, is located in which state in India?', '[{"id":"A","text":"Uttar Pradesh"},{"id":"B","text":"Assam"},{"id":"C","text":"Haryana"},{"id":"D","text":"Rajasthan"}]', 0, 'D', 'Kalibangan archaeological site is in Rajasthan.

Correct answer: 4. Rajasthan', NULL, 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:38.647Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (499, 'general-test-2025-05-20-shift-2', 'q42', 37, 37, 'A bus passes two persons moving in the direction of the moving bus at a speed of 3 km/hr and 5 km/hr, respectively. The bus passes the first person in 10 s and the second person in 11 s. Find the speed of the bus.', '[{"id":"A","text":"28 km/hr"},{"id":"B","text":"27 km/hr"},{"id":"C","text":"25 km/hr"},{"id":"D","text":"24 km/hr"}]', 0, 'C', 'Convert speeds to m/s:

• Bus = $ v \times \frac{5}{18} $

- Person 1 = 3 × $ \frac{5}{18} $

• Person 2 = 5 × $ \frac{5}{18} $

Case 1 (Person at 3 km/hr, time = 10 s)

Relative speed:

$$ (v-3)\frac{5}{18} $$

$$ L=\left(v-3\right)\frac{5}{18}\times10 $$

Case 2 (Person at 5 km/hr, time = 11 s)

$$ L=\left(v-5\right)\frac{5}{18}\times11 $$

Equate both:

$$ (v-3)\frac{5}{18}\times10=(v-5)\frac{5}{18}\times11 $$

Cancel $\frac{5}{18}$:

$$ 10(v-3)=11(v-5) $$

10v-30=11v-55

v = 25

✓ Final Answer:

3.25 km/hr', NULL, 'null', '[]', '[]', '[46]', 'keyed', '[]', '2026-11-05T20:58:38.648Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (500, 'general-test-2025-05-20-shift-2', 'q44', 38, 38, 'Which of the following collections of letters will look the same in the mirror?

(A) OXA8voHM

(B) TWOVIMYOU

(C) HV8SIMOT

(D) AIXW08VA', '[{"id":"A","text":"(A) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', '1. Analysis of Individual Characters

Let''s check which characters remain unchanged when reflected horizontally:

• Symmetrical: A, H, I, M, O, T, U, V, W, X, Y, 0, 8, v, o.

- Non-Symmetrical: B, C, D, E, F, G, J, K, L, N, P, Q, R, S, Z, 1, 2, 3, 4, 5, 6, 7, 9.
2. Evaluating the Options

We will examine each collection to see if all characters in it are symmetrical.

(A) OXA8voHM: Every character (O, X, A, 8, v, o, H, M) is vertically symmetrical.

(B) TWOVIM YOU: Every character (T, W, O, V, I, M, Y, O, U) is vertically symmetrical.

Result: Valid

(C) HV8SIMOT: The letter ''S'' is not vertically symmetrical. In a mirror, it appears reversed (2). Result: Invalid

• (D) AIXW08VA: Every character (A, I, X, W, 0, 8, V, A) is vertically symmetrical.
3. Conclusion

Based on the analysis, collections (A), (B), and (D) consist entirely of letters and numbers that look the same in a mirror.', NULL, 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.648Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (501, 'general-test-2025-05-20-shift-2', 'q45', 39, 39, 'The Goods and Services Tax Act, expected to create "One Nation, One Tax and One Market", came into effect in which year?', '[{"id":"A","text":"2013"},{"id":"B","text":"2015"},{"id":"C","text":"2017"},{"id":"D","text":"2019"}]', 0, 'C', 'The Goods and Services Tax (GST) came into effect in 2017.

Correct answer: 3.2017', NULL, 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.649Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (502, 'general-test-2025-05-20-shift-2', 'q46', 40, 40, 'Consider the compound interest in the following cases:

(A) The compound interest on Rs 16000 at 20% per annum for 9 months, compounded quarterly is Rs. 2500

(B) The compound interest on Rs 2800 at 10% per annum for 18 months is Rs. 434.

Choose the correct statement(s):', '[{"id":"A","text":"Only (A)"},{"id":"B","text":"Only (B)"},{"id":"C","text":"(A) and (B)"},{"id":"D","text":"Neither (A) nor (B)"}]', 0, 'B', 'Analysis of Statement (A)

• Principal (P): Rs. 16,000

• Annual Rate (R): 20%

• Time (n): 9 months (which is 3 quarters)

• Quarterly Rate (r): Since interest is compounded quarterly, the rate is 20%/4 = 5% per quarter.

Using the Compound Interest formula: $ A = P(1 + \frac{r}{100})^n $

$$ A=16000\times\left(1+\frac{5}{100}\right)^{3} $$

$$ A=16000\times(1.05)^{3} $$

$$ A=16000\times1.157625=18522 $$

Compound Interest (CI): A - P = 18522 - 16000 = Rs. 2,522

The statement says the interest is Rs. 2,500, so Statement (A) is Incorrect.

Analysis of Statement (B)

• Principal (P): Rs. 2,800

• Annual Rate (R): 10%

• Time: 18 months (1.5 years)

For fractional years, we calculate the amount for the full year and then simple interest on that amount for the remaining months:

1. Amount after 1 year: 2800 + (10% of 2800) = 2800 + 280 = Rs. 3080

2. Interest for next 6 months: 10% of 3080 for half a year = $ 308 \times 0.5 = Rs.\ 154 $

Total Compound Interest: 280 + 154 = Rs. 434

The statement says the interest is Rs. 434, so Statement (B) is Correct.
Conclusion

Since only statement (B) is accurate, the correct option is:

2. Only (B)', NULL, 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.649Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (503, 'general-test-2025-05-20-shift-2', 'q47', 41, 41, 'Baking powder is a mixture of baking soda (sodium hydrogen carbonate) and _?', '[{"id":"A","text":"Acetic Acid"},{"id":"B","text":"Citric Acid"},{"id":"C","text":"Tartaric Acid"},{"id":"D","text":"Oxalic Acid"}]', 0, 'C', 'Baking powder is a mixture of baking soda and tartaric acid.

Correct answer: 3. Tartaric Acid', NULL, 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:38.649Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (504, 'general-test-2025-05-20-shift-2', 'q48', 42, 42, 'Which among the following is India''s first pico-satellite, weighing less than 1kg, developed by a consortium of seven engineering colleges of India?', '[{"id":"A","text":"ANUSAT"},{"id":"B","text":"PRATHAM"},{"id":"C","text":"STUDSAT"},{"id":"D","text":"SWAYAM"}]', 0, 'C', 'The correct answer is STUDSAT.
Explanation:

• STUDSAT was India''s first pico-satellite (less than 1 kg)

• It was developed by a consortium of seven engineering colleges in Karnataka

Correct answer: 3. STUDSAT', NULL, 'null', '[]', '[]', '[53]', 'keyed', '[]', '2026-11-05T20:58:38.651Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (505, 'general-test-2025-05-20-shift-2', 'q49', 43, 43, 'Profit earned by selling an article for Rs.1060 is 20% more than the loss incurred by selling the article for Rs.950. At what price should the article be sold to earn a 20% profit?', '[{"id":"A","text":"Rs 1100"},{"id":"B","text":"Rs. 1150"},{"id":"C","text":"Rs. 1200"},{"id":"D","text":"Rs. 1250"}]', 0, 'C', 'Loss when sold at 950:

Loss = x - 950

Profit when sold at 1060:

Profit = 1060 - x

Given:

1060 - x = 1.2 (x - 950)

Solve:

1060 - x = 1.2x - 1140

1060 + 1140 = 1.2x + x

2200=2.2x

x=1000

Now find selling price for 20% profit:

SP = 1000 + 20% = 1000 + 200 = 1200

Final Answer:

3. Rs. 1200', NULL, 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:38.651Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (506, 'general-test-2025-05-20-shift-2', 'q50', 44, 44, 'Iceland is an example of _.', '[{"id":"A","text":"Seamount"},{"id":"B","text":"Mid-oceanic Ridge"},{"id":"C","text":"Atoll"},{"id":"D","text":"Guyot"}]', 0, 'B', 'Iceland lies on the Mid-Atlantic Ridge, which is a mid-oceanic ridge where tectonic plates diverge.

Correct answer: 2. Mid-oceanic Ridge', NULL, 'null', '[]', '[]', '[55]', 'keyed', '[]', '2026-11-05T20:58:38.652Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (507, 'geography-2025-05-16-shift-1', 'q01', 1, 1, '''Match List-I with List-II', '[{"id":"A","text":"(A) (Ⅳ), (B) (Ⅱ), (C) (Ⅲ), (D) - (1)"},{"id":"B","text":"(A) (II), (B) - (III), (C) - (I), (D) - (IV)"},{"id":"C","text":"(A) (I), (B) (II), (C) (IV), (D) - (III)"},{"id":"D","text":"(A) (II), (B) (III), (C) (IV), (D) - (1)"}]', 0, 'D', '1. Sikhs are primarily concentrated in Punjab.

2. Christians in India have significant presence in areas such as Goa (and also Kerala etc.).

3. Buddhists have a notable concentration in northeastern regions such as Sikkim (and also in Maharashtra among others).

4. Jains are found in urban areas and particular states such as Rajasthan.', NULL, 'null', '[]', '[{"id":"q01-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q01-table-1.jpg","page":1,"alt":"Table for question 1"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.654Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (508, 'geography-2025-05-16-shift-1', 'q02', 2, 2, 'The ports used for refueling, watering and taking food items are called', '[{"id":"A","text":"Naval Ports"},{"id":"B","text":"Entrepot Ports"},{"id":"C","text":"Packet Station"},{"id":"D","text":"Ports of Call"}]', 0, 'D', 'Ports of Call are ports where ships stop temporarily for refueling, watering, repairing, and taking in food items while on their journey to other destinations.

They are not final destinations for cargo or passengers - rather, intermediate halts essential for long-distance maritime travel.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.655Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (509, 'geography-2025-05-16-shift-1', 'q03', 3, 3, 'Identify correct statements about level of urbanisation in India.

(A) The level of urbanisation in India is quite low in comparison to developed countries.

(B) Total urban population has increased three-fold during the twentieth century.

(C) Chandigarh was developed as administrative headquarter after independence.

(D) On the basis of population the Census of India classifies urban centres into six classes.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', '(D)

The Census of India classifies towns into six classes based on population size, but this classification is part of the "urban settlements classification system" and not directly about the level of urbanisation. However, since the question focuses on "level of urbanisation in India", this point is less relevant compared to (A), (B), and (C).', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.655Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (510, 'geography-2025-05-16-shift-1', 'q04', 4, 4, 'WTO headquarter is located at _, Switzerland.', '[{"id":"A","text":"Minsk"},{"id":"B","text":"Brussels"},{"id":"C","text":"Vienna"},{"id":"D","text":"Geneva"}]', 0, 'D', '• The World Trade Organization (WTO) was established on 1 January 1995, replacing the General Agreement on Tariffs and Trade (GATT).

• Its headquarters is located in Geneva, Switzerland.

- The WTO is responsible for setting and enforcing global trade rules, resolving trade disputes, and promoting free and fair international trade among member countries.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.656Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (511, 'geography-2025-05-16-shift-1', 'q05', 5, 5, 'Name the country that officially proclaims the Gross National Happiness (GNH) as the measure of the country''s progress.', '[{"id":"A","text":"Singapore"},{"id":"B","text":"Nepal"},{"id":"C","text":"Japan"},{"id":"D","text":"Bhutan"}]', 0, 'D', '• Bhutan is the only country in the world that officially proclaims Gross National Happiness (GNH) as the measure of the country''s progress.

• Instead of focusing only on Gross Domestic Product (GDP), Bhutan''s development philosophy emphasizes spiritual, cultural, environmental, and economic well-being.

• The four pillars of GNH are:

1. Sustainable and equitable socio-economic development

2. Conservation of environment

3. Preservation and promotion of culture

4. Good governance', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.656Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (512, 'geography-2025-05-16-shift-1', 'q06', 6, 6, 'In the Northern States of India, which of the following crop is grown in the Rabi Season?', '[{"id":"A","text":"Rice"},{"id":"B","text":"Cotton"},{"id":"C","text":"Wheat"},{"id":"D","text":"Bajra"}]', 0, 'C', 'In northern states of India (like Punjab, Haryana, Uttar Pradesh, Bihar, etc.), wheat is the main Rabi crop.

• Rabi crops are sown in winter (October-December) and harvested in spring (March-April).

• They require cool climate for growth and bright sunshine for ripening', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.656Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (513, 'geography-2025-05-16-shift-1', 'q07', 7, 7, 'Major characteristics of hunting and gathering are:

(A) It often involves primitive societies, who depend on plants and animals to satisfy their needs for food, shelter and clothing.

(B) This type of activity requires a small amount of capital investment.

(C) No surplus is produced.

(D) This is a specialized activity in which only one type of animal is reared.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'D.

This describes Commercial Livestock Rearing. Hunting and gathering involves killing wild animals and does not include animal rearing (domestication).

_', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (514, 'geography-2025-05-16-shift-1', 'q08', 8, 8, 'Match LIST-I with LIST-II', '[{"id":"A","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $"},{"id":"B","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $"},{"id":"C","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{IV}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{III}) $"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q08-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q08-table-1.jpg","page":7,"alt":"Table for question 8"}]', '[6,7]', 'keyed', '[]', '2026-11-05T20:58:38.657Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (515, 'geography-2025-05-16-shift-1', 'q09', 9, 9, 'Arrange the following seaports located on the west coast of India from north to south.

(A) Mumbai

(B) New Mangalore

(C) Marmagao

(D) Kochchi', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', '• Mumbai Port - Maharashtra

• Mormugao Port - Goa

• New Mangalore Port - Karnataka

• Kochi Port - Kerala', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (516, 'geography-2025-05-16-shift-1', 'q10', 10, 10, 'Which of the following ports are natural harbours?

(A) Kochchi Port

(B) Chennai Port

(C) Marmagao Port

(D) Mumbai Port', '[{"id":"A","text":"(B), (C) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B) and (D) only"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'D', '• Mumbai Port - A natural deep-water harbour located on the Konkan Coast (Maharashtra).

• Mormugao Port - Situated in Goa, it is a natural harbour that has been developed with modern facilities.

• Kochi (Cochin) Port - Located in Kerala, it is a natural harbour formed by the sea and backwaters.

Chennai Port - It is an artificial harbour, built by constructing breakwaters to protect ships from sea waves.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (517, 'geography-2025-05-16-shift-1', 'q11', 11, 11, 'In the following identify the statement which is NOT correct about Indian crops.', '[{"id":"A","text":"Rice is a crop of tropical humid areas."},{"id":"B","text":"Wheat is primarily a crop of temperate zone."},{"id":"C","text":"Maize is a food as well as fodder crop."},{"id":"D","text":"Rapeseed and mustard comprise several pulses."}]', 0, 'D', 'Rapeseed and mustard are oilseeds (used for oil and condiments), not pulses. Pulses are leguminous crops like gram (chana), moong, or arhar.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (518, 'geography-2025-05-16-shift-1', 'q12', 12, 12, 'Some coffee Fazendas (large plantations) in Brazil are still managed by:', '[{"id":"A","text":"Europeans"},{"id":"B","text":"South Africans"},{"id":"C","text":"Japanese"},{"id":"D","text":"Red Indians"}]', 0, 'A', 'The question relates to the historical context of Plantation Agriculture.

• Fazendas are the large coffee estates/plantations in Brazil.

• Plantation agriculture was introduced in colonies and tropical regions by Europeans.

- The British, French, Dutch, Spanish, and Americans all established plantations across the world (tea in India, rubber in Malaysia, cocoa in West Africa, etc.).

Specifically, historical accounts and NCERT-level information note that some coffee Fazendas in Brazil are still managed by Europeans (referring to European descendants or long-established European firms).', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.658Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (519, 'geography-2025-05-16-shift-1', 'q13', 13, 13, 'Choose the correct answer from the options given below:', '[{"id":"A","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})"},{"id":"B","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I}\\mathbf{I I}),(\\mathbf{C})-(\\mathbf{I}\\mathbf{I}),(\\mathbf{D})-(\\mathbf{I}\\mathbf{V})"},{"id":"C","text":"(\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{III}),(\\mathbf{C})-(\\mathbf{IV}),(\\mathbf{D})-(\\mathbf{I})"},{"id":"D","text":"\\ (\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{IV}),(\\mathbf{C})-(\\mathbf{I}),(\\mathbf{D})-(\\mathbf{III})"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q13-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q13-table-1.jpg","page":11,"alt":"Table for question 13"}]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.658Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (520, 'geography-2025-05-16-shift-1', 'q14', 14, 14, 'The characteristics of the National Highways Authority of India are:

(A) It is an autonomous body under the Ministry of Surface Transport.

(B) It has the responsibility of development, maintenance and operation of National Highways.

(C) It constructs and maintains the border roads in the country.

(D) It was operationalised in 1995.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', '(A) It is an autonomous body under the Ministry of Surface Transport (now Ministry of Road Transport and Highways). (Correct)

• (B) It has the responsibility of development, maintenance and operation of National Highways. (Correct)

(C) It constructs and maintains the border roads in the country. (Incorrect - This is the primary function of the Border Roads Organisation (BRO).)

• (D) It was operationalised in 1995. (Correct)', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.658Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (521, 'geography-2025-05-16-shift-1', 'q15', 15, 15, 'Identify the characteristics of minerals.

(A) These are unevenly distributed over space.

(B) There is an inverse relationship in the quality and quantity of minerals.

(C) All minerals are exhaustible over time.

(D) Non-metallic minerals are always organic in nature.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', '• (A) These are unevenly distributed over space. (Correct)

(B) There is an inverse relationship in the quality and quantity of minerals (high-quality minerals are low in quantity, and vice versa). (Correct)

• (C) All minerals are exhaustible over time. (Correct - They are non-renewable resources.)

(D) Non-metallic minerals are always organic in nature. (Incorrect - Non-metallic minerals like mica, limestone, and gypsum are inorganic; only fossil fuels like coal and petroleum are organic non-metallic minerals.)', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.658Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (522, 'geography-2025-05-16-shift-1', 'q16', 16, 16, 'Match LIST-I with LIST-II', '[{"id":"A","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})"},{"id":"B","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{I}\\mathbf{I I}),(\\mathbf{C})-(\\mathbf{I}\\mathbf{I}),(\\mathbf{D})-(\\mathbf{I}\\mathbf{V})"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'C', 'This matches the nuclear power plants with their correct states: Tarapur in Maharashtra, Kalpakkam in Tamil Nadu, Kaiga in Karnataka, and Kakrapara in Gujarat.', NULL, 'null', '[]', '[{"id":"q16-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q16-table-1.jpg","page":14,"alt":"Table for question 16"}]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.659Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (523, 'geography-2025-05-16-shift-1', 'q17', 17, 17, 'The Limits to Growth was published in _', '[{"id":"A","text":"1972"},{"id":"B","text":"1968"},{"id":"C","text":"1987"},{"id":"D","text":"1970"}]', 0, 'A', 'The Limits to Growth is a seminal book published in 1972 by the Club of Rome. It used computer modeling to study the long-term consequences of rapidly growing world population, limited resource supply, and industrial growth, advocating for a sustainable approach.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.659Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (524, 'geography-2025-05-16-shift-1', 'q18', 18, 18, 'Match LIST-I with LIST-II', '[{"id":"A","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) - (\\mathrm{II}) $, $ (\\mathrm{C}) - (\\mathrm{III}) $, $ (\\mathrm{D}) - (\\mathrm{IV}) $"},{"id":"B","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $"},{"id":"C","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) - (\\mathrm{II}) $, $ (\\mathrm{C}) - (\\mathrm{IV}) $, $ (\\mathrm{D}) - (\\mathrm{III}) $"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'D', 'This matches the Railway Zones with their correct Headquarters: North Eastern ( $ \rightarrow $ Gorakhpur), South Central ( $ \rightarrow $ Secunderabad), East Central ( $ \rightarrow $ Hajipur), and North Western ( $ \rightarrow $ Jaipur).', NULL, 'null', '[]', '[{"id":"q18-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q18-table-1.jpg","page":16,"alt":"Table for question 18"}]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.659Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (525, 'geography-2025-05-16-shift-1', 'q19', 19, 19, 'Geographers of which country describe the ''state/country'' as a ''living organism''?', '[{"id":"A","text":"France"},{"id":"B","text":"Germany"},{"id":"C","text":"Great Britain"},{"id":"D","text":"India"}]', 0, 'B', 'The concept of the ''state/country'' as a living organism (organic state theory) is attributed to German geographers, most notably Friedrich Ratzel. This idea, which views the state as an organism that must grow and expand to survive, is a foundational concept in the field of Political Geography and is related to the idea of Lebensraum.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.660Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (526, 'geography-2025-05-16-shift-1', 'q20', 20, 20, 'Many areas of Meghalaya, Uttarakhand, Himachal Pradesh and Kerala have _ type of settlements.', '[{"id":"A","text":"agglomerated"},{"id":"B","text":"hamleted"},{"id":"C","text":"dispersed or isolated"},{"id":"D","text":"fragmented"}]', 0, 'C', 'Dispersed or isolated settlements are commonly found in areas of hilly tracts, plateaus, and thick forests, where the land is fragmented, and topography restricts close clustering. This pattern is typical of the mountainous and geographically diverse regions mentioned: Meghalaya (hills/plateau), Uttarakhand (Himalayan region), Himachal Pradesh (Himalayan region), and the hilly parts of Kerala (Western Ghats).', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.660Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (527, 'geography-2025-05-16-shift-1', 'q21', 21, 21, 'Which of the followings are main basis of international trade?

(A) Differences in national resources.

(B) Direction of trade.

(C) Differences in stages of economic development.

(D) Extent of foreign investment.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only."},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', 'The main bases of international trade are factors that create differences in production costs and market conditions across countries. (A) Differences in national resources, (C) Differences in stages of economic development, and (D) Extent of foreign investment are all fundamental bases for trade. (B) Direction of trade is a result of international trade, not a basis for it', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.660Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (528, 'geography-2025-05-16-shift-1', 'q22', 22, 22, 'Arrange the following means of communication from ancient to modern in order of their development:

(A) Landline phone

(B) Communication through internet

(C) Letter

(D) Television', '[{"id":"A","text":"(B), (C), (A), (D)"},{"id":"B","text":"(C), (A), (D), (B)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', 'The means of communication developed in this historical order: 1. Letter (C): Represents the oldest, physical, and manual form of communication. 2. Landline phone (A): Represents the invention of electronic voice communication (late 19th century). 3. Television (D): Represents mass electronic communication, primarily broadcasting (mid-20th century). 4. Communication through internet (B): Represents the most modern, digitized, and global form of communication (late 20th century/21st century).', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.660Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (529, 'geography-2025-05-16-shift-1', 'q23', 23, 23, 'Which of the following is NOT the characteristic of foot loose industries?', '[{"id":"A","text":"They are not dependent on any specific raw material."},{"id":"B","text":"They produce in small quantities and also employ a small labour force."},{"id":"C","text":"Finished products may be for consumption in the same household."},{"id":"D","text":"These are generally not polluting industries."}]', 0, 'C', 'Footloose industries are modern, usually light manufacturing industries that can be located almost anywhere, as their production costs are largely independent of their location. Characteristics of footloose industries: They are not dependent on any specific raw material (1), They produce in small quantities and also employ a small labour force (2), and They are generally not polluting industries (4). The statement (3) describes Household Industries or Cottage Industries, not footloose industries.', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.660Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (530, 'geography-2025-05-16-shift-1', 'q24', 24, 24, 'Which of the following is the Indian communication satellite?', '[{"id":"A","text":"Cartosat"},{"id":"B","text":"Landsat"},{"id":"C","text":"SPOT"},{"id":"D","text":"INSAT"}]', 0, 'D', 'INSAT (Indian National Satellite System) is a series of multi-purpose geostationary satellites launched by ISRO to fulfill the country''s needs for telecommunications, broadcasting, meteorology, and search and rescue operations. Cartosat is an Indian remote sensing satellite, while Landsat and SPOT are remote sensing satellites of the USA and France, respectively.', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.661Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (531, 'geography-2025-05-16-shift-1', 'q25', 25, 25, '_ has been constructed to relieve the pressure at Chennai port.', '[{"id":"A","text":"Paradwip Port"},{"id":"B","text":"Jawaharlal Nehru Port"},{"id":"C","text":"Ennore Port"},{"id":"D","text":"Kandla Port"}]', 0, 'C', 'Ennore Port (now officially Kamarajar Port) was constructed north of Chennai to function as a satellite port. Its primary purpose was to handle bulk cargo like thermal coal and iron ore, thereby relieving congestion and pressure at the older, major Chennai Port.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.661Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (532, 'geography-2025-05-16-shift-1', 'q26', 26, 26, 'Arrange the following states of India in descending order as per their population density in 2011.

(A) Bihar

(B) Uttar Pradesh

(C) West Bengal

(D) Kerala', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (D), (B)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', 'Based on the 2011 Census data, the population densities of the listed states are (approximately): (A) Bihar (1106 persons/sq km), (C) West Bengal (1028 persons/sq km), (D) Kerala (860 persons/sq km), and (B) Uttar Pradesh (829 persons/sq km). The descending order is (A), (C), (D), (B).', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.662Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (533, 'geography-2025-05-16-shift-1', 'q27', 27, 27, 'Which of the following statements is NOT correct about Atal Tunnel?', '[{"id":"A","text":"It is built in the Shivalik Ranges of the Himalayas."},{"id":"B","text":"It was built by the Border Road Organisation."},{"id":"C","text":"It connects Manali to Lahaul-Spiti Valley."},{"id":"D","text":"It is the World''s Longest Highway Tunnel."}]', 0, 'A', 'Atal Tunnel is actually built under the Pir Panjal Range of the Himalayas, not the Shivalik Ranges. The other statements are correct: It was built by the Border Road Organisation (BRO) (2); it connects Manali to the Lahau-Spiti Valley (3); and as of its opening, it was considered the World''s Longest Highway Tunnel (above 10,000 feet) (4)', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.662Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (534, 'geography-2025-05-16-shift-1', 'q28', 28, 28, 'Which of the following is NOT the main cause of noise pollution?', '[{"id":"A","text":"Mechanised construction work"},{"id":"B","text":"Automobiles"},{"id":"C","text":"Loudspeakers used in various festivals"},{"id":"D","text":"Combustion of fossil fuels"}]', 0, 'D', 'The combustion of fossil fuels is primarily associated with air pollution (releasing gases like CO2, SO2, etc.). The other options-Mechanised construction work (1), Automobiles (2), and Loudspeakers (3)-are all direct and major sources of noise pollution.', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.662Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (535, 'geography-2025-05-16-shift-1', 'q29', 29, 29, 'Which of the following statements is NOT correct about Haryali?', '[{"id":"A","text":"It is a Watershed Development Project."},{"id":"B","text":"Project is executed by Gram Panchayats with People''s Participation."},{"id":"C","text":"It aims to enable rural population to conserve water."},{"id":"D","text":"The project focuses only on the well-being of females."}]', 0, 'D', 'The Haryali project is a Watershed Development Project (1). It is implemented by the Gram Panchayats with people''s participation (2) and aims to enable the rural population to conserve water (3) for drinking,

irrigation, etc. However, while the project does involve and benefit women''s self-help groups for resource management, it does not focus only on the well-being of females.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.662Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (536, 'geography-2025-05-16-shift-1', 'q30', 30, 30, 'Arrange the following iron-ore mines from north to south

(A) Bailadila

(B) Mayurbhanj

(C) Kudremukh

(D) Ratnagiri', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'The geographical locations of the mines are: (B) Mayurbhanj (Odisha) is the northernmost; (A) Bailadila (Chhattisgarh) is next, located further south/west; (D) Ratnagiri (Maharashtra) is on the western coast, south of Bailadila; and (C) Kudremukh (Karnataka) is the southernmost, located in the Western Ghats. The', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.664Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (537, 'geography-2025-05-16-shift-1', 'q31', 31, 31, '_ includes 168 km of west coast canal along with Champakara canal.', '[{"id":"A","text":"NW1"},{"id":"B","text":"NW 2"},{"id":"C","text":"NW 4"},{"id":"D","text":"NW3"}]', 0, 'D', 'NW 3 (National Waterway 3), also known as the West Coast Canal, runs between Kottapuram and Kollam in Kerala. It includes the West Coast Canal (168 km), the Champakara Canal, and the Udyogamandal Canal, totaling about 205 km.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.664Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (538, 'geography-2025-05-16-shift-1', 'q32', 32, 32, 'Arrange the following according to stages of demographic transition.

(A) High fluctuating

(B) Early expanding

(C) Late expanding

(D) Low fluctuating', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'A', 'demographic transition theory describes population change in four stages: (A) High Fluctuating (Stage I: High birth rate and high death rate); (B) Early Expanding (Stage II: High birth rate and rapidly falling death rate); (C) Late Expanding (Stage III: Falling birth rate and low death rate); and (D) Low Fluctuating (Stage IV: Low birth rate and low death rate). The given list is already in the correct chronological order of the stages.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.665Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (539, 'geography-2025-05-16-shift-1', 'q33', 33, 33, 'The movement from the plains to the mountains in summer and back in winter in search of pastures is the characteristics of', '[{"id":"A","text":"Commercial Livestock Rearing"},{"id":"B","text":"Nomadic Herding"},{"id":"C","text":"Ranching"},{"id":"D","text":"Shifting Cultivation"}]', 0, 'B', 'Nomadic Herding involves herders moving with their animals from place to place in search of pastures and water. The particular pattern of seasonal movement between high mountain pastures in summer and lower valleys/plains in winter is called transhumance, and is a key feature of nomadic herding practiced by groups like the Gujjars, Bakarwals, Bhotiyas, and Gaddis in the Himalayas.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.666Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (540, 'geography-2025-05-16-shift-1', 'q34', 34, 34, 'Identify the Industry which is based on forest raw material.', '[{"id":"A","text":"Paper industry"},{"id":"B","text":"Leather industry"},{"id":"C","text":"Woollen textile industry"},{"id":"D","text":"Jute industry"}]', 0, 'A', 'The Paper industry uses wood pulp derived from forest raw material (wood). The other industries use different raw materials: Leather industry uses hides and skin of animals; Woollen textile industry uses wool from sheep; and Jute industry uses plant fibers from the jute crop.', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.666Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (541, 'geography-2025-05-16-shift-1', 'q35', 35, 35, 'Which one of the following is a correct statement?', '[{"id":"A","text":"Natural growth of population depends on births, deaths and migration."},{"id":"B","text":"Crude death rates can not be more than crude birth rates."},{"id":"C","text":"Growth rate of population is the change of population expressed in percentage."},{"id":"D","text":"Migration is not a component of population change."}]', 0, 'C', 'Solution:

Statement 3 is correct. The growth rate is used to express the change in population (growth) over a period of time, and is calculated as a percentage. Statement 1 is incorrect because Natural Growth only considers births and deaths, and excludes migration. Statement 2 is incorrect as crude death rates can certainly be higher than crude birth rates (e.g., during epidemics or in aging populations). Statement 4 is incorrect because Migration (immigration and emigration) is a major component of population change, along with birth and death rates.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.667Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (542, 'geography-2025-05-16-shift-1', 'q36', 36, 36, 'The collection, production and dissemination of information are the characteristics of activities.', '[{"id":"A","text":"Tertiary"},{"id":"B","text":"Quaternary"},{"id":"C","text":"Secondary"},{"id":"D","text":"Primary"}]', 0, 'B', 'Quaternary activities refer to the sector of the economy that involves highly intellectual and knowledge-based tasks. These tasks include the collection, production, and dissemination of information, as well as research and development. This sector is distinct from the tertiary sector, which mainly deals with services.', NULL, 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.667Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (543, 'geography-2025-05-16-shift-1', 'q37', 37, 37, '''Aus'', ''Aman'' and ''Boro'' are related to which of the following?', '[{"id":"A","text":"Varieties of Coffee"},{"id":"B","text":"Zaid crops"},{"id":"C","text":"Variety of rice grown in Kerala"},{"id":"D","text":"Three crops of rice grown in West Bengal"}]', 0, 'D', 'Aus, Aman, and Boro are three different rice crops grown in a year in the states of West Bengal and Assam. This is possible due to the favorable climate and heavy rainfall in the region. Aman is the autumn crop (harvested in November), Aus is the pre-kharif/summer crop (harvested in September/October), and Boro is the winter/spring crop (harvested in March/April).', NULL, 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.667Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (544, 'geography-2025-05-16-shift-1', 'q38', 38, 38, 'Suez Canal act as a linkage between _ sea and _ sea.', '[{"id":"A","text":"Mediterranean, Atlantic"},{"id":"B","text":"Red, Arabian"},{"id":"C","text":"Mediterranean, Red"},{"id":"D","text":"Dead, Black"}]', 0, 'C', 'The Suez Canal, constructed in 1869, is an artificial sea-level waterway in Egypt connecting the Mediterranean Sea at Port Said to the Red Sea at Port Suez. This canal provides the shortest and most direct maritime route between Europe and the lands bordering the Indian and western Pacific Oceans.', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.668Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (545, 'geography-2025-05-16-shift-1', 'q39', 39, 39, 'Arrange the following countries of the world in descending order on the basis of their population size.

(A) Brazil

(B) Indonesia

(C) Japan

(D) U.S.A.', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(D), (B), (A), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'The U.S.A. has the largest population among the listed countries, followed by Indonesia. Brazil has a larger population than Japan. Therefore, the descending order is U.S.A. (D), Indonesia (B), Brazil (A), Japan (C).

_', NULL, 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:38.668Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (546, 'geography-2025-05-16-shift-1', 'q40', 40, 40, 'Match LIST-I with LIST-II', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'D', '• Varanasi is a well-known cultural town, famous for its religious and cultural heritage.

• New Delhi is the administrative capital of India, hence an administrative town.

• Saharanpur is known for its trade and commercial activities.

• Bokaro is an industrial town, known for its steel industry.', NULL, 'null', '[]', '[{"id":"q40-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-16-shift-1/q40-table-1.jpg","page":34,"alt":"Table for question 40"}]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.668Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (547, 'geography-2025-05-16-shift-1', 'q41', 41, 41, 'make the defaulter encroaching on the CPR a member of their user group and sharing the benefits of greening the common lands/pastures.

Jhabua district is located in which agro-climatic zone of Madhya Pradesh?', '[{"id":"A","text":"Northernmost"},{"id":"B","text":"Southernmost"},{"id":"C","text":"Easternmost"},{"id":"D","text":"Westernmost"}]', 0, 'D', 'Jhabua district lies in the extreme western part of Madhya Pradesh, bordering Gujarat. Geographically, this region, along with nearby Alirajpur and Dhar, falls under the Jhabua Hill (or Western) agro-climatic zone, which is characterized by semi-arid conditions and is one of the more marginal agricultural areas of the state.', 'p94fc7b10ab45', 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.668Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (548, 'geography-2025-05-16-shift-1', 'q42', 42, 42, '4. Social-fencing', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'revitalisation of Common Property Resources (CPRs) like village pastures, ponds, and degraded forest areas requires controlled management. Practices used by communities such as the Bhils of Jhabua (

include: Plantation of fodder grass, Plantation of trees (afforestation), and Social-fencing (a system of voluntary restrictions on resource use like grazing). Open grazing is an unregulated practice that leads to over-exploitation and degradation, which is the opposite of revitalisation.', 'pe8bd92f9598a', 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.668Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (549, 'geography-2025-05-16-shift-1', 'q43', 43, 43, '4. Easternmost', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Petlawad is one of the administrative blocks in the Jhabua district of Madhya Pradesh. Geographically, it is situated in the northern section of the district, bordering the Ratlam district. The Jhabua district is an area often discussed in the context of water management and tribal development in Indian Geography textbooks.', 'p25223606f601', 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:38.669Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (550, 'geography-2025-05-16-shift-1', 'q44', 44, 44, '4. Ministry of Tribal Affairs', '[{"id":"A","text":"Ministry of Tourism"},{"id":"B","text":"Ministries of Rural Development and Agriculture"},{"id":"C","text":"Ministry of Road Transport and Highway"},{"id":"D","text":"Ministry of Tribal Affairs"}]', 0, 'B', 'Government-sponsored watershed development projects in India, such as the one in Jhabua (known for its successful implementation, sometimes involving the Haryali project), are centrally financed through key nodal agencies. The two primary central ministries responsible for funding and implementing these types of rural water conservation and land development schemes are the Ministry of Rural Development (through schemes like Neeranchal and the previous watershed components of PMKSY) and the Ministry of Agriculture', 'p18fef03fc42c', 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:38.669Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (551, 'geography-2025-05-16-shift-1', 'q45', 45, 45, '3. Santhal', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The Bhils are one of the largest tribal groups in India and have a high concentration in the western districts of Madhya Pradesh, particularly in the Jhabua region, which is often cited in the context of watershed management programs and social forestry efforts.', 'pbbab7c8350dc', 'null', '[]', '[]', '[45]', 'keyed', '[]', '2026-11-05T20:58:38.669Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (552, 'geography-2025-05-16-shift-1', 'q46', 46, 46, 'Revert to Original

_ is related to the service sector.', '[{"id":"A","text":"Dairy farming"},{"id":"B","text":"Weaving"},{"id":"C","text":"Teaching"},{"id":"D","text":"Iron smelting"}]', 0, 'C', 'The service sector encompasses all Tertiary, Quaternary, and Quinary activities. Teaching is a specialized service that falls under Tertiary activities (provision of services) or Quaternary activities (knowledge-based services). Dairy farming is Primary, Weaving and Iron Smelting are Secondary activities.', 'pb275bc3d0266', 'null', '[]', '[]', '[47]', 'keyed', '[]', '2026-11-05T20:58:38.670Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (553, 'geography-2025-05-16-shift-1', 'q47', 47, 47, '4. Trade', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Exchange refers to the transfer of goods and services between people or places and is the main component of Tertiary activities. It directly involves Trade (buying and selling), Transport (moving goods), and Communication (transmitting information for transactions). Production is a Primary or Secondary activity (like farming or manufacturing) that occurs before exchange.', 'p5d37fd480fae', 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.670Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (554, 'geography-2025-05-16-shift-1', 'q48', 48, 48, '4. They involve production of tangible goods.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'Tertiary activities are related to the service sector. They involve the provision of services (intangible) that are consumed, not the production of tangible goods (which is characteristic of the Primary and Secondary sectors). Services depend on specialized skills and knowledge.', 'p86f82e1c8cda', 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:38.670Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (555, 'geography-2025-05-16-shift-1', 'q49', 49, 49, '4. tertiary', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'Developed countries have mature economies where the majority of economic output and employment shifts away from resource extraction and manufacturing towards services.

• Tertiary Activities are services, which include activities like transportation, communication, commerce, administration, finance, healthcare, and education.

- In developed countries, this sector dominates employment because technological advancements and high income levels create a massive demand for services and allow for the automation or outsourcing of many primary and secondary tasks.

- The high share of workers in the Tertiary (and increasingly, Quaternary/Quinary) sector is a defining characteristic of a developed economy. Conversely, in a developing country, the majority of the workforce is typically still engaged in primary activities (like agriculture).', 'p1b11c99423e2', 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:38.670Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (556, 'geography-2025-05-16-shift-1', 'q50', 50, 50, '4. tertiary', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'In the initial stages of a country''s economic development, the majority of the population is engaged in Primary activities, which involve extracting or harvesting natural resources like agriculture, forestry, fishing, and mining. As development progresses, the workforce shifts to the Secondary (manufacturing) and then the Tertiary (service) sectors.', 'p7c17b5343885', 'null', '[]', '[]', '[56]', 'keyed', '[]', '2026-11-05T20:58:38.671Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (557, 'geography-2025-05-20-shift-1', 'q01', 1, 1, 'The Amazon Rainforest is located in which of the following continent?', '[{"id":"A","text":"Africa"},{"id":"B","text":"South America"},{"id":"C","text":"North America"},{"id":"D","text":"Asia"}]', 0, 'B', 'The Amazon Rainforest (or the Amazon Basin is located in South America), given in figure 5.2 Areas of Subsistence Gathering.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.673Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (558, 'geography-2025-05-20-shift-1', 'q04', 2, 2, 'These activities involve the collection, production and dissemination of information or even the production of information. Identify the activities:', '[{"id":"A","text":"Quinary activities"},{"id":"B","text":"Secondary Activities"},{"id":"C","text":"Quaternary activities"},{"id":"D","text":"Tertiary activities"}]', 0, 'C', '• Quaternary activities involve the collection, production, and dissemination of information.

• They are centered around research and development (R&D).

- These can be seen as an advanced form of services.

• They require specialised knowledge and technical skills.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.673Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (559, 'geography-2025-05-20-shift-1', 'q05', 3, 3, 'Identify the challenges in society with regard to adolescent populations

(A) Illiteracy - particularly female illiteracy

(B) Low intake of nutrients

(C) Low maternal mortality rates

(D) Drug abuse and alcoholism', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', '1. Includes various issues like:

1. Lower age at marriage.

2. Illiteracy, with a particular emphasis on female illiteracy.

3. High rates of school dropouts.

2. High rate of maternal mortality among adolescent mothers.

1. Drug abuse and alcoholism.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.673Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (560, 'geography-2025-05-20-shift-1', 'q06', 4, 4, 'Arrange the following geographical approaches in chronological order?

(A) Spatial Organization

(B) Areal Differentiation

(C) Regional Analysis

(D) Exploration and Description', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D), (C), (B), (A)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', 'Table 1.1 of the aforementioned chapter mentions all these time periods and their focus elaborately.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.674Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (561, 'geography-2025-05-20-shift-1', 'q07', 5, 5, 'Cities, such as Ghaziabad, Rohtak, Gurugram, located in proximity to the Metropolitan city of Delhi are also known as :', '[{"id":"A","text":"Functional towns"},{"id":"B","text":"Administrative towns"},{"id":"C","text":"Commercial towns"},{"id":"D","text":"Satellite towns"}]', 0, 'D', 'Some old towns developed as satellite towns around metropolitan cities like Ghaziabad, Rohtak, Gurugram in proximity to Delhi.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.674Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (562, 'geography-2025-05-20-shift-1', 'q08', 6, 6, 'Arrange the following states of India in descending order according to their total population.

(A) Rajasthan

(B) Arunachal Pradesh

(C) Sikkim

(D) Uttar Pradesh', '[{"id":"A","text":"(D), (B), (C), (A)"},{"id":"B","text":"(D), (A), (B), (C)"},{"id":"C","text":"(D), (A), (C), (B)"},{"id":"D","text":"(A), (D), (B), (C)"}]', 0, 'B', 'Uttar Pradesh has the highest population, followed by Rajasthan and Arunanchal Pradesh, whereas Sikkim has the lowest. Arunanchal Pradesh has the lowest population "density" (17 persons per sq km) and the actual population is higher than that of Sikkim.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.674Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (563, 'geography-2025-05-20-shift-1', 'q09', 7, 7, 'Which of the following regions is NOT associated with mediterranean agriculture?', '[{"id":"A","text":"Southern California"},{"id":"B","text":"North Western Europe"},{"id":"C","text":"Central Chile"},{"id":"D","text":"South Western parts of Australia"}]', 0, 'B', '1. Regions Where Mediterranean Agriculture is Practised include

Countries on either side of the Mediterranean Sea in Europe and in North Africa (from Tunisia to the Atlantic coast), Southern California, Central Chile, South western parts of South Africa, South and south western parts of Australia.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.674Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (564, 'geography-2025-05-20-shift-1', 'q10', 8, 8, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (1), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (1), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'D', 'See map (figure) 5.5 : India - Conventional Energy Resources as

• (A) Singarauli → (III) Madhya Pradesh

• (B) Singareni → (IV) Andhra Pradesh (Singareni Collieries are mainly in Telangana/earlier Andhra Pradesh)

(C) Neyveli $ \rightarrow $ (I) Tamil Nadu

(D) Jharia $ \rightarrow $ (II) Jharkhand', NULL, 'null', '[]', '[{"id":"q10-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-20-shift-1/q10-table-1.jpg","page":8,"alt":"Table for question 10"}]', '[7,8]', 'keyed', '[]', '2026-11-05T20:58:38.674Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (565, 'geography-2025-05-20-shift-1', 'q11', 9, 9, 'The Census of India, 1991, defines urban settlements as all places which have the following:

(A) Have a minimum population of 5000 persons

(B) At least 75 percent of male workers are engaged in non-agricultural pursuits

(C) People derive their life support from land-based economic activities

(D) Density of population is at least 400 persons per square kilometer', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', '1. Definition of Urban Settlements (Census of India, 1991):

a. The place must have a municipality, corporation, cantonment board, or a notified town area committee.

b. A minimum population of 5,000 persons is required.

c. At least 75 per cent of the male workers must be engaged in non-agricultural pursuits.

d. There must be a density of population of at least 400 persons per square kilometer.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.675Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (566, 'geography-2025-05-20-shift-1', 'q12', 10, 10, 'Which of the following causes land degradation ?', '[{"id":"A","text":"Rotation of crops"},{"id":"B","text":"Afforestation"},{"id":"C","text":"Dumping of Industrial waste"},{"id":"D","text":"Applying organic manure"}]', 0, 'C', 'There are some other types of wastelands such as degraded shifting cultivation area, degraded land under plantation crops, degraded forests, degraded pastures, and mining and industrial wastelands, are caused by human action.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.675Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (567, 'geography-2025-05-20-shift-1', 'q13', 11, 11, 'Identify the odd one on the basis of the scale of communication?', '[{"id":"A","text":"Television"},{"id":"B","text":"Radio"},{"id":"C","text":"Letters"},{"id":"D","text":"Cinema"}]', 0, 'C', 'Letters come under Personal Communication whereas others come under Mass communication.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.675Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (568, 'geography-2025-05-20-shift-1', 'q14', 12, 12, 'Long staple (American) cotton grown in north-western parts of India is called _.', '[{"id":"A","text":"Bitty cotton"},{"id":"B","text":"Indian cotton"},{"id":"C","text":"Narma"},{"id":"D","text":"Golden Fibre"}]', 0, 'C', 'India grows both short staple (Indian) cotton as well as long staple (American) cotton called ''narma'' in north-western parts of the country.

_', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.675Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (569, 'geography-2025-05-20-shift-1', 'q15', 13, 13, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'C', 'Given under Table 1.2: Human Geography and Sister Disciplines of Social Sciences

• Social Geography → Anthropology.

• Political Geography → Psephology

• Settlement Geography → Urban/Rural Planning

• Population Geography $ \rightarrow $ Demography', NULL, 'null', '[]', '[{"id":"q15-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-20-shift-1/q15-table-1.jpg","page":12,"alt":"Table for question 15"}]', '[11,12]', 'keyed', '[]', '2026-11-05T20:58:38.675Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (570, 'geography-2025-05-20-shift-1', 'q16', 14, 14, '_ is a watershed development project sponsored by the Central Government which aims at enabling the rural population to conserve water for drinking, irrigation, fisheries and afforestation.', '[{"id":"A","text":"Neeru-Meeru"},{"id":"B","text":"Haryali"},{"id":"C","text":"Arvary Pani Sansad"},{"id":"D","text":"Atal Bhujal Yojana"}]', 0, 'B', 'Haryali is a watershed development project sponsored by the Central Government which aims at enabling the rural population to conserve water for drinking, irrigation, fisheries and afforestation.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.676Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (571, 'geography-2025-05-20-shift-1', 'q17', 15, 15, 'In a country 350,000 people reside over an area of thousand square kilometer. The density of population of the country is _.', '[{"id":"A","text":"3500 person/sq km"},{"id":"B","text":"35 person/sq km"},{"id":"C","text":"350 person/sq km"},{"id":"D","text":"1500 person/sq mile"}]', 0, 'C', 'Population Density of Population = Population/Area', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.676Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (572, 'geography-2025-05-20-shift-1', 'q18', 16, 16, 'The characteristic features of Commercial Livestock Rearing are:

(A) Movement in search of pastures is undertaken.

(B) It is practiced on permanent ranches.

(C) Only one type of animal is reared.

(D) Rearing of animals is organised on a scientific basis.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', 'Commercial livestock ranching is essentially associated with western cultures and is practised on permanent ranches. This is a specialised activity in which only one type of animal is reared. Important animals include sheep, cattle, goats and horses. Rearing of animals in ranching is organised on a scientific basis.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.676Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (573, 'geography-2025-05-20-shift-1', 'q19', 17, 17, 'Arrange the following countries in ascending order according to their population.

(A) India

(B) Pakistan

(C) USA

(D) Mexico', '[{"id":"A","text":"(D), (B), (C), (A)"},{"id":"B","text":"(D), (C), (B), (A)"},{"id":"C","text":"(C), (D), (A), (B)"},{"id":"D","text":"(B), (A), (C), (D)"}]', 0, 'A', 'Given in Figure 2.1

So the ascending order is: (D), (B), (C), (A)', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.677Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (574, 'geography-2025-05-20-shift-1', 'q20', 18, 18, 'The over-use of groundwater resources in some states of India has led to which of the following:

(A) the integrated development of rain-fed areas

(B) decline in groundwater table

(C) increased fluoride concentration

(D) an increase in the concentration of arsenic.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', '(A) is incorrect because because integrated development of rain-fed areas is a solution, not a consequence.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.677Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (575, 'geography-2025-05-20-shift-1', 'q21', 19, 19, 'Match List-I with List-II', '[{"id":"A","text":"(A) - (III), (B) - (II), (C) - (IV), (D) - (I)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'A', 'Given in Table 3.1

• Income Approach → Oldest approach (III)

• Welfare Approach → People as passive recipients (II)

• Basic Needs Approach → Proposed by ILO (IV)

• Capability Approach → Builds human abilities (I)', NULL, 'null', '[]', '[{"id":"q21-table-1","kind":"table","path":"/local-papers/assets/geography-2025-05-20-shift-1/q21-table-1.jpg","page":16,"alt":"Table for question 21"}]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.677Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
