नीचे दिए गए विकल्पों से सही उत्तर चुनीए -', '[{"id":"A","text":"(A), (C) (B), (D)"},{"id":"B","text":"(A), (B), (C), (D)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(A), (C), (D), (B)"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.708Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
