INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (649, 'hindi-2025', 'q49', 47, 47, 'निम्नलिखित में से कार्यालयी पत्र व्यवहार का उदाहरण नहीं है -', '[{"id":"A","text":"परिपूर्ण"},{"id":"B","text":"प्रेस विशिष्टि"},{"id":"C","text":"अधिसूचना"},{"id":"D","text":"परिचय पत्र Solution Q.1. Answer: (3) शिधा"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.710Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (650, 'history-2025-05-16-shift-1', 'q01', 1, 1, 'Arrange the following events of 1857 in a chronological order

(A) Shah Mal killed in battle

(B) Sepoy mutiny in Aligarh

(C) Nawab Wajid Ali Shah deposed

(D) The British suffered defeat in the battle of Chinhat', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (B), (D), (C)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'D', 'The correct chronological order of the 1857 events is:

1. Nawab Wajid Ali Shah deposed (C) - 11 February 1856, an event that contributed to the rising unrest.

2. Sepoy mutiny in Aligarh (B) - May 1857, part of the early phase of the revolt.

3. British defeat at the Battle of Chinhat (D) - June 30, 1857.

4. Shah Mal killed in battle (A) - 1st July 1857.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.715Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (651, 'history-2025-05-16-shift-1', 'q02', 2, 2, 'Choose the correct statements about the Prayaga Prashasti or the Allahabad Pillar Inscription:

(A) It is composed in Sanskrit.

(B) It was composed by Harishna, the court poet of Samudragupta

(C) It describes the King as Purusha.

(D) It describes Chandragupta as the greatest King.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', '(A) It is composed in Sanskrit - The Prayaga Prashasti (Allahabad Pillar Inscription) was written in classical Sanskrit.

(B) It was composed by Harishena, the court poet of Samudragupta - Harishena, a minister and court poet. authored this inscription.

(C) It describes the King as Purusha - The inscription glorifies Samudragupta using terms like Purusha (a supreme person or man).

• (D) It describes Chandragupta as the greatest King - It refers to Samudragupta as arguably the most powerful of the Gupta rulers(c. fourth century CE), not Chandragupta.

So, statements A, B, and C are correct.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.716Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (652, 'history-2025-05-16-shift-1', 'q03', 3, 3, 'Which of the following was not the reason for the rise of Magadha as the most powerful Mahajanapada?', '[{"id":"A","text":"A region with productive agriculture."},{"id":"B","text":"Accessibility to iron mines provided resources for tools and weapons."},{"id":"C","text":"Elephants for army were found in the forests of the region."},{"id":"D","text":"Policies of Hoysala rulers."}]', 0, 'D', 'The Hoysala dynasty ruled in South India (Karnataka) centuries later (10th-14th century CE), making their policies irrelevant to the rise of Magadha (6th-4th century BCE). The other three options (productive agriculture, access to iron, and availability of elephants) were key geographical and resource advantages that fueled Magadha''s success.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.716Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (653, 'history-2025-05-16-shift-1', 'q04', 4, 4, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q04-table-1","kind":"table","path":"/local-papers/assets/history-2025-05-16-shift-1/q04-table-1.jpg","page":4,"alt":"Table for question 4"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.716Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (654, 'history-2025-05-16-shift-1', 'q05', 5, 5, 'In the Mughal period, who were identified as pahi-kashta peasants?', '[{"id":"A","text":"Peasants who were residents of the village in which they held their lands."},{"id":"B","text":"Peasants having large amount of land and rural magnates."},{"id":"C","text":"Peasants who tilt their own land out of choice."},{"id":"D","text":"Non-resident cultivators who belonged to some other village, but cultivated lands elsewhere on a contractual basis."}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.717Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (655, 'history-2025-05-16-shift-1', 'q06', 6, 6, 'When was Mahatma Gandhi approached by a peasant from Champaran in Bihar who told him about the harsh treatment of peasants by British indigo planters?', '[{"id":"A","text":"January 1915"},{"id":"B","text":"February 1916"},{"id":"C","text":"December 1916"},{"id":"D","text":"March 1917"}]', 0, 'C', 'During the Lucknow Session of the Indian National Congress in December 1916, Mahatma Gandhi was approached by a peasant from Champaran, Rajkumar Shukla, who informed him about the severe hardships faced by indigo farmers under oppressive plantation systems. Responding to his plea, Gandhi visited Champaran in March 1917, launching the Champaran Satyagraha, which became the first major Satyagraha movement in India and a landmark in the country''s freedom struggle.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.717Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (656, 'history-2025-05-16-shift-1', 'q07', 7, 7, 'Arrange the following events in a chronological order:

(A) Accession of Chandragupta Maurya

(B) Urbanization in the Ganga valley

(C) Satavahanas in the Deccan

(D) Rise of the Chalukyas in Karnataka', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.717Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (657, 'history-2025-05-16-shift-1', 'q09', 8, 8, 'Arrange the travellers in a chronological order as per their visit to India:

(A) Afanasii Nikitich Nikitin

(B) Ibn Battuta

(C) François Bernier

(D) Duarte Barbosa', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.717Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (658, 'history-2025-05-16-shift-1', 'q10', 9, 9, 'The evidence of a ploughed field associated with Early Harappan levels is found at:', '[{"id":"A","text":"Mohenjodaro"},{"id":"B","text":"Sutkagendor"},{"id":"C","text":"Kalibangan"},{"id":"D","text":"Nageshwar"}]', 0, 'C', 'The evidence of a ploughed field associated with Early Harappan levels is found at Kalibangan. This evidence at Kalibangan, Rajasthan, consists of a set of furrows at right angles to each other, suggesting that two different crops were grown together.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.718Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (659, 'history-2025-05-16-shift-1', 'q11', 10, 10, 'Which traveller has described the practice of ''child-sati'' in detail?', '[{"id":"A","text":"Duarte Barbosa"},{"id":"B","text":"Francois Bernier"},{"id":"C","text":"Peter Mundy"},{"id":"D","text":"Jean-Baptiste Tavernier"}]', 0, 'B', 'The traveller who described the practice of child-sati in detail was Francois Bernier. A French physician and traveller who visited India during the Mughal period, Bernier wrote extensively about Indian society and customs. In his accounts, he discussed instances of sati, noting the tragic practice and the difficulty in distinguishing whether the victim was a young child or a very young woman.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.719Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (660, 'history-2025-05-16-shift-1', 'q12', 11, 11, 'According to the Dharmasutras and Dharmashastras, the "ideal" occupation of the Kshatriyas were:', '[{"id":"A","text":"To study and teach the Vedas, perform sacrifices, give and receive gifts."},{"id":"B","text":"To engage in agriculture, pastoralism and trade."},{"id":"C","text":"To serve the three higher varnas."},{"id":"D","text":"To engage in warfare, protect people and administer justice."}]', 0, 'D', 'According to the dharmashastras and dharmasutras, the "ideal" occupation of the Kshatriyavarna was to engage in warfare, protect people, and administer justice.

Other Varnas:

• Brahmins: Study/teach Vedas, perform sacrifices, give/receive gifts

o Vaishyas: Agriculture, trade, pastoralism

o Shudras: Serve higher varnas', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.720Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (661, 'history-2025-05-16-shift-1', 'q13', 12, 12, 'What was included in the process of the ''integration of cults'' in Bhakti-tradition? Identify correct statements:

(A) The process of disseminating Brahmanical ideas.

(B) The composition, compilation and preservation of Puranic texts in simple Sanskrit verse meant for women and Shudras.

(C) A continuous dialogue between "great" Sanskritic Puranic traditions and "little" traditions throughout the land.

(D) Instances of integrations are not evident among goddess cults.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'The Bhakti movement facilitated the integration of local and Sanskritic religious traditions across India. This process included:

1. Dissemination of Brahmanical ideas: Bhakti poets and saints spread concepts such as dharma, karma, and the Puranic pantheon among common people, reaching sections like women and Shudras who had limited access to Sanskrit learning.

2. Simplification of sacred texts: Puranic stories were composed, compiled, and preserved in simple Sanskrit or vernacular verse, making complex religious ideas comprehensible and relatable to a

wider audience.

3. Dialogue between "great" and "little" traditions: Local or folk cults ("little" traditions) continuously interacted with Sanskritic Puranic traditions ("great" traditions). This led to the incorporation of regional deities and practices into the mainstream pantheon.

4. Integration of goddess cults: Local goddesses were often identified with Puranic forms such as Shakti, Parvati, or Durga, exemplifying how regional cults were absorbed into the larger Bhakti framework.', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.720Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (662, 'history-2025-05-16-shift-1', 'q14', 13, 13, 'Which of the following statement is not true about mahajanapadas of the sixth-century BCE:', '[{"id":"A","text":"Mahajanapadas were mostly ruled by kings."},{"id":"B","text":"Each mahajanapada had a capital city, which was often fortified."},{"id":"C","text":"Early Buddhist and Jaina texts mention twenty states known as mahajanapadas."},{"id":"D","text":"Mahajanapadas maintained armies and bureaucracies."}]', 0, 'C', 'Buddhist and Jaina texts like the Anguttara Nikaya and Bhagavati Sutra mention 16 major states, not 20.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.720Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (663, 'history-2025-05-16-shift-1', 'q15', 14, 14, 'As per Francis Buchanan''s survey of the Dinajpur district in North Bengal, which among the following statement does not match with the description of Jotedars:', '[{"id":"A","text":"Jotedars had acquired vast areas of land - sometimes as much as several thousand acres."},{"id":"B","text":"Jotedars helped the zamindar with land revenue collection."},{"id":"C","text":"Jotedars controlled local trade as well as money-lending, exercising immense power over the poorer cultivators of the region."},{"id":"D","text":"A large part of Jotedar''s land was cultivated by sharecroppers (adhiyars or bargadars)."}]', 0, 'B', 'The statement is incorrect because the relationship between the Jotedars and the Zamindars was one of antagonism and competition for power, not cooperation in revenue collection.

Role and Power of Jotedars:

1. Vast Landholding: Jotedars held large tracts of land, sometimes several thousand acres, establishing them as dominant rural elites.

2. Cultivation Method: Most of their land was cultivated by sharecroppers, known as adhiyars or bargadars, who brought their own ploughs and received half the harvest.

3. Economic Control: They controlled local markets, trade, and most importantly, money-lending. This allowed them to exercise immense power over the poorer cultivators, who often became indebted to them.

4. Resistance to Zamindars: Jotedars deliberately delayed payments of revenue to the zamindar. Their primary goal was to see the Zamindari fail, which would allow them to purchase the lands being auctioned and thus further strengthen their own local position.

Therefore, they were an obstacle to the Zamindar''s revenue collection efforts, not an aid.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.720Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (664, 'history-2025-05-16-shift-1', 'q16', 15, 15, 'Identify the correct statements about the ''Virashaiva'' tradition:

(A) It was led by a Brahmana named Basavanna.

(B) Worship Shiva in his manifestation as a linga.

(C) Lingayats supported the idea of caste and the "pollution" attributed to certain groups by Brahmanas.

(D) Virashaiva do not practise funerary rites and instead, ceremonially bury their dead.', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', '• (A) Correct: The Virashaiva (Lingayat) movement began in the 12th century in Karnataka, led by Basavanna, a Brahmana who served in the Kalachuri court.

(B) Correct: The followers worship Shiva in the form of a linga and are called Lingayats ("wearers of the linga").

(C) Incorrect: The Lingayats opposed caste divisions and Brahmanical ideas of purity and pollution; they promoted equality.

(D) Correct: They bury their dead instead of cremating them, as they believe the devotee''s soul unites with Shiva after death.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.721Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (665, 'history-2025-05-16-shift-1', 'q17', 16, 16, 'Identify the structure at ''Hampi'' based on the following description:

"Located on one of the highest points in the city, it is a massive platform rising from a base of about 11,000 sq. ft to a height of 40 ft. There is evidence that it supported a wooden structure. The base of the platform is covered with relief carvings."', '[{"id":"A","text":"Lotus Mahal"},{"id":"B","text":"Hazara Rama temple"},{"id":"C","text":"Mahanavami Dibba"},{"id":"D","text":"Vitthala temple"}]', 0, 'C', 'The Mahanavami Dibba at Hampi is a huge stone platform about 40 ft high, with its base covered in carvings showing festivals, battles, and royal scenes. A wooden pavilion once stood on top for the king''s ceremonies during the Mahanavami (Dasara) festival.

Lotus Mahal: A beautiful two-storey building with Indo-Islamic design, not a large open platform.

1. Hazara Rama Temple: A small temple in the Royal Centre with Ramayana carvings, not a big platform.

2. Vitthala Temple: A large temple complex with musical pillars and the stone chariot, located outside the Royal Centre, not an open platform.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.721Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (666, 'history-2025-05-16-shift-1', 'q18', 17, 17, 'In 1919, the project to prepare a critical edition of the Mahabharata was headed by:', '[{"id":"A","text":"V.S. Sukthankar"},{"id":"B","text":"Alexander Cunningham"},{"id":"C","text":"John Marshall and Alfred Foucher"},{"id":"D","text":"Rajendra Lala Mitra"}]', 0, 'A', 'The critical edition of the Mahabharata was started in 1919 under the leadership of V.S. Sukthankar at the Bhandarkar Oriental Research Institute (BORI), Pune. This monumental project aimed to prepare an authentic version of the epic by comparing hundreds of manuscripts and took 47 years to complete.', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.721Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (667, 'history-2025-05-16-shift-1', 'q19', 18, 18, 'Arrange the following events in a chronological order:

(A) English East India Company acquires ''Diwani'' of Bengal

(B) Permanent Settlement of Bengal

(C) Regulating Act passed by the British Parliament

(D) Ryots in Deccan villages rebel', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B),(A),(D),(C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.721Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (668, 'history-2025-05-16-shift-1', 'q20', 19, 19, 'Rules for Buddhist Bhikkhus and Bhikkhunis are listed in which

among the following text?', '[{"id":"A","text":"Sutta Pitaka"},{"id":"B","text":"Abhidhamma Pitaka"},{"id":"C","text":"Vinaya Pitaka"},{"id":"D","text":"Divyavadan"}]', 0, 'C', 'The Vinaya Pitaka, part of the Tripitaka, contains the rules of discipline for Buddhist monks (Bhikkhus) and nuns (Bhikkhunis). It covers daily conduct, communal living, ordination, and procedures for penance, ensuring moral integrity and harmony within the monastic community.', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.721Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (669, 'history-2025-05-16-shift-1', 'q21', 20, 20, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (II), (B) - (I), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q21-table-1","kind":"table","path":"/local-papers/assets/history-2025-05-16-shift-1/q21-table-1.jpg","page":20,"alt":"Table for question 21"}]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.722Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (670, 'history-2025-05-16-shift-1', 'q22', 21, 21, 'Who described the kingdom of Awadh as "a cherry that will drop into our mouth one day"?', '[{"id":"A","text":"Lord Dalhousie"},{"id":"B","text":"Lord William Bentinck"},{"id":"C","text":"Lord Hardinge"},{"id":"D","text":"Lord Canning"}]', 0, 'A', 'Lord Dalhousie, the Governor-General of India, famously described Awadh in 1851 as "a cherry that will drop into our mouth one day," expressing his belief that its annexation was inevitable due to alleged misgovernance and strategic importance. Eventually, after a period of 5 years, Awadh was annexed in 1856 by the British on the pretext of misrule.', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.722Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (671, 'history-2025-05-16-shift-1', 'q23', 22, 22, 'Choose the correct statements about the Virupaksha temple at Hampi:

(A) The hall in front of the main shrine was built by Harihara and Bukka Raya to mark their accession.

(B) It was decorated with delicately carved pillars.

(C) The halls in the temple were used for programmes of music, dance, drama.

(D) The temple was built over centuries.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', 'The Virupaksha Temple has richly carved mandapas used for music, dance, and festivals, and it has remained as a living temple, being built and expanded over many centuries. The main hall of the temple was built by Krishnadeva Raya, not by Harihara and Bukka Raya.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.722Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (672, 'history-2025-05-16-shift-1', 'q24', 23, 23, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q24-table-1","kind":"table","path":"/local-papers/assets/history-2025-05-16-shift-1/q24-table-1.jpg","page":23,"alt":"Table for question 24"}]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.722Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (673, 'history-2025-05-16-shift-1', 'q25', 24, 24, 'The term ''matrilocal'' residence means:', '[{"id":"A","text":"The practice where men after marriage remain in their natal home and their wives may come to stay with them."},{"id":"B","text":"The practice where men-women after marriage does not stay with their families and move to a new home."},{"id":"C","text":"The practice where women after marriage remain in their natal home with their children and the husbands may come to stay with them."},{"id":"D","text":"The practice where women after marriage move to the natal home of their husbands and their children stays with their parents."}]', 0, 'C', 'The term ''matrilocal'' comes from mater (mother) and locus (place), meaning the couple lives in or near the bride''s parental home. This system emphasizes maternal lineage and the woman''s central role in the family.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.722Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (674, 'history-2025-05-16-shift-1', 'q26', 25, 25, 'By c. 1800 BCE most of the Mature Harappan sites had been abandoned in regions such as _.', '[{"id":"A","text":"Kashmir"},{"id":"B","text":"Cholistan"},{"id":"C","text":"Western Uttar Pradesh"},{"id":"D","text":"Haryana"}]', 0, 'B', 'By around 1800 BCE, most Mature Harappan sites in the Cholistan desert (Pakistan) were abandoned, marking the start of the Late Harappan phase. This region, once full of settlements along the Ghaggar-Hakra River, saw a sharp decline, while areas like Haryana and Western Uttar Pradesh grew in population during the same period.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (675, 'history-2025-05-16-shift-1', 'q27', 26, 26, 'Images of Buddha and Bodhisattas that were evidently based on Greek models were found in which city?', '[{"id":"A","text":"Kanauj"},{"id":"B","text":"Taxila"},{"id":"C","text":"Nalanda"},{"id":"D","text":"Mahabalipuram"}]', 0, 'B', 'Taxila, in north-western India (modern Pakistan), was a major center of the Gandhara School of Buddhist art, showing Greek (Hellenistic) influence in realistic human forms, draped clothing, and wavy hair. This style was developed under the Indo-Greek rulers who established kingdoms in Taxila and Peshawar around 2nd century BCE.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (676, 'history-2025-05-16-shift-1', 'q28', 27, 27, 'Which texts contain the ''regional histories'' of Buddhism?', '[{"id":"A","text":"Tipitakas"},{"id":"B","text":"Sutta Pitaka and Vinaya Pitaka"},{"id":"C","text":"Abhidhamma Pitaka"},{"id":"D","text":"Dipavamsa and Mahavamsa"}]', 0, 'D', 'These two texts, particularly the Mahavamsa (Great Chronicle) and its predecessor the Dipavamsa (Island Chronicle), are important historical chronicles from Sri Lanka that detail the history of Buddhism on the island and its connection to India. They are considered key sources for the history of Buddhism in that region.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (677, 'history-2025-05-16-shift-1', 'q29', 28, 28, 'Choose the correct statements for distinctive features of the Harappan planned ''drainage system'':

(A) Roads and streets were laid out along an approximate "grid" pattern.

(B) It seems that streets with drains were laid out first and then houses built along them.

(C) Domestic waste water did not flow into the street drains.

(D) Every house needs to have at least one wall along a street.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'A) Correct - Harappan cities like Mohenjo-daro and Harappa had streets laid out in a north-south and east-west grid pattern, indicating a high level of urban planning and organisation.

(B) Correct - Archaeological evidence shows that streets and drainage systems were planned and constructed first, and houses were then built alongside them. This reflects a strong focus on civic infrastructure.

(C) Incorrect - In reality, domestic wastewater was directed into street drains via private household drains. These were often covered and maintained, highlighting the efficiency of Harappan sanitation.

(D) Correct - Most houses were designed with at least one wall adjoining a street, ensuring easy access and connection to the drainage and road network.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (678, 'history-2025-05-16-shift-1', 'q30', 29, 29, 'The original story of Mahabharata was probably composed by:', '[{"id":"A","text":"Charioteer-bards known as Sutas"},{"id":"B","text":"Rishi Agastaya"},{"id":"C","text":"Maharishi Valmiki"},{"id":"D","text":"Manu"}]', 0, 'A', 'The original story of the Mahabharata was probably composed by charioteer-bards known as Sutas. They were storytellers who accompanied kings and warriors, reciting their deeds and heroic tales. These bards preserved and passed down the epic orally over generations before it was eventually written down.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (679, 'history-2025-05-16-shift-1', 'q32', 30, 30, 'The Rajasuya and Ashvamedha sacrifices were performed by _.', '[{"id":"A","text":"The chiefs and kings"},{"id":"B","text":"The heads of households"},{"id":"C","text":"The individual members of the Kula alone"},{"id":"D","text":"Members of the household collectively"}]', 0, 'A', 'The Rājasūya and Aśvamedha sacrifices were grand Vedic rituals performed by chiefs and kings to assert their authority and sovereignty. The Rājasūya marked the king''s consecration and formal establishment of power, while the Aśvamedha (Horse Sacrifice) proclaimed his supreme control over surrounding territories.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.723Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (680, 'history-2025-05-16-shift-1', 'q33', 31, 31, 'Francois Bernier dedicated his major writings to which king of France?', '[{"id":"A","text":"Francis II"},{"id":"B","text":"Louis XI"},{"id":"C","text":"Louis XIV"},{"id":"D","text":"Charles II"}]', 0, 'C', 'François Bernier dedicated his major work, Travels in the Mughal Empire (a detailed account of his time in India and observations of the reigns of Dara Shikoh and Aurangzeb) to Louis XIV, the King of France, who was known as the "Sun King."

Bernier''s descriptions often compared the situation in the Mughal Empire unfavorably with contemporary Europe, explicitly using his observations as a cautionary tale for the French monarch and his ministers about the dangers of absolute state ownership of land.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (681, 'history-2025-05-16-shift-1', 'q35', 32, 32, 'Which details among the following were recorded by Ain-i Akbari? Identify the correct statements:

(A) Account of the daily lives of ordinary peasants.

(B) The arrangements made by the state to ensure cultivation.

(C) The arrangements made to enable the collection of revenue by the agencies of the state.

(D) The arrangements made to regulate the relationship between the state and the zamindars.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', 'The Ain-i Akbari is the third part of the Akbarnama, written by Abul Fazl, one of Emperor Akbar''s close courtiers. It is a detailed administrative document that records information about the institutions and functioning of the Mughal Empire. It does not describe the daily lives of ordinary peasants. Instead, it focuses on state policies and institutions as well as records the arrangements made to ensure cultivation, such as land measurement and crop classification, the systems for revenue collection by state agencies, and the regulations governing the relationship between the state and the zamindars.', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (682, 'history-2025-05-16-shift-1', 'q37', 33, 33, 'Which of the following is not the subject-matter of ''The Fifth Report'', submitted to the British Parliament in 1813?', '[{"id":"A","text":"The administration and activities of the East India Company in India."},{"id":"B","text":"Military reforms required in the army."},{"id":"C","text":"Petitions of zamindars and ryots, reports of collectors from different districts."},{"id":"D","text":"Statistical tables on revenue returns, notes on the revenue and judicial administration of Bengal and Madras written by officials."}]', 0, 'B', '"The Fifth Report" submitted to the British Parliament in 1813 primarily dealt with the administration and activities of the East India Company, the petitions from zamindars and ryots, and statistical tables on revenue and judicial administration in Bengal and Madras. It did not focus on military reforms in the army.', NULL, 'null', '[]', '[]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (683, 'history-2025-05-16-shift-1', 'q38', 34, 34, 'The Ain-i Akbari does not mention this crop in the lists of crops in northern India. Identify the crop?', '[{"id":"A","text":"Tobacco"},{"id":"B","text":"Cotton"},{"id":"C","text":"Mustard"},{"id":"D","text":"Rice"}]', 0, 'A', 'The Ain-i-Akbari does not mention tobacco among the crops listed for northern India. Crops like rice, cotton, and mustard were included, but tobacco was not prominently mentioned in these records.', NULL, 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (684, 'history-2025-05-16-shift-1', 'q39', 35, 35, 'Identify the correct statements associated with Al-Biruni:

(A) He was born in Khwarizm, in present day Uzbekistan.

(B) He read the works of Plato and other Greek philosophers in Arabic translations.

(C) Traveled to the Chinese port town of Zaytun and extensively in China, going as far as Beijing.

(D) Wrote Kitab-ul-Hind, in Arabic, divided into 80 chapters on religion and philosophy, festivals, etc.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Al-Biruni, born in Khwarizm (modern-day Uzbekistan), was a renowned scholar who made significant contributions to various fields. He read the works of Plato and other Greek philosophers through Arabic translations, which deeply influenced his intellectual development. Al-Biruni is best known for his work Kitab-ul-Hind, written in Arabic, which is divided into 80 chapters and covers topics such as religion, philosophy, festivals, and more, offering a detailed account of India''s culture and traditions. However, contrary to some accounts, there is no evidence that Al-Biruni traveled to China or reached the Chinese port town of Zaytun, as he focused his travels primarily within the regions surrounding the Islamic world.', NULL, 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (685, 'history-2025-05-16-shift-1', 'q40', 36, 36, 'The ruins at ''Hampi'' were brought to light in 1800 by _.', '[{"id":"A","text":"Colin Mackenzie"},{"id":"B","text":"Alexander Greenlaw"},{"id":"C","text":"John Marshall"},{"id":"D","text":"J.F. Fleet"}]', 0, 'A', 'Colonel Colin Mackenzie, the first Surveyor General of India, is credited with bringing the ruins of Hampi to light in 1800. During his survey of the region, he discovered the ancient remnants of the Vijayanagara Empire and documented them, helping to reveal the site''s historical significance.', NULL, 'null', '[]', '[]', '[36]', 'keyed', '[]', '2026-11-05T20:58:38.724Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (686, 'history-2025-05-16-shift-1', 'q41', 37, 37, '4. Bengal Hind University', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Gandhiji referred to the opening of Banaras Hindu University (BHU) as "a most gorgeous show" when he attended the ceremony in 1916.', 'pf5deba8a58c0', 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (687, 'history-2025-05-16-shift-1', 'q42', 38, 38, '4. Gandhiji was against the spirit of self-governance.', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Gandhiji critiques the Indian elite, including doctors, lawyers, and landlords, for their disregard of the working class and peasants. He argues that Indian nationalism, driven by the elite, excluded the majority of the population. Gandhi emphasises that true self-governance and national salvation can only be achieved through the involvement of the common people, particularly the peasants, highlighting a shift from elite-', 'p8048b95b1e12', 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (688, 'history-2025-05-16-shift-1', 'q43', 39, 39, '4. Right to be a good farmer', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Gandhiji emphasizes that the salvation for India will come through the farmer, and that the peasants'' labor and the results of their work are being taken away by the privileged classes. This aligns with the idea that what was being taken away from the farmers were the economic benefit of their labor.', 'pa226700c741e', 'null', '[]', '[]', '[41]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (689, 'history-2025-05-16-shift-1', 'q44', 40, 40, '4. Servants of the East India Company', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Gandhiji highlights the absence of the peasants and workers at the opening of the Banaras Hindu University (BHU), while the rich and elite groups were present.', 'pb768645f10b2', 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (690, 'history-2025-05-16-shift-1', 'q45', 41, 41, '4. December 1916', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Gandhiji''s speech in Benaras was delivered in February 1916. He criticised the Indian elite for their lack of concern for the poor, highlighting the absence of peasants at the Banaras Hindu University (BHU) opening. He stressed that India''s salvation would come from empowering farmers, not the rich landlords or professionals like lawyers and doctors.', 'p08acbf05a4ac', 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (691, 'history-2025-05-16-shift-1', 'q47', 42, 42, '4. Masses were in minority', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The speaker explains that the oppression and depression faced by the tribal people are due to economic hardship, which leads to their exploitation and forms of economic slavery. The lack of legal protection and exploitation by merchants and moneylenders are also key factors in their suffering.', 'pae7fce529060', 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.725Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (692, 'history-2025-05-16-shift-1', 'q48', 43, 43, '4. It is for the religious minorities only', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'It is evident that the speaker, N.G. Ranga, feels that the resolution is insufficient because it does not provide adequate protection against exploitation by non-state actors like moneylenders and landlords in rural areas. Instead, it seems to focus more on religious minorities or specific groups in urban settings, which doesn''t address the broader issue faced by marginalised tribal populations.', 'pcecaeba60114', 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.726Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (693, 'history-2025-05-16-shift-1', 'q49', 44, 44, '4. Constitutional protection of the welfare-state', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'Constitutional protection of the welfare state would provide a legal framework for safeguarding the rights of tribal people, ensuring they receive protection from exploitation, displacement, and other forms of injustice.', 'p63b184efca03', 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:38.726Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (694, 'history-2025-05-16-shift-1', 'q50', 45, 45, '4. The tribals of free India', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'D', 'N.G. Ranga focused on the issues of marginalised and tribal communities in India, highlighting how their rights and interests often went overlooked in the larger socio-political context. The tribals, especially in post-

independence India, were among the most disadvantaged groups in terms of socio-economic development and political representation.', 'pb104fd5484df', 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:38.726Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (695, 'history-2025-05-20-shift-1', 'q01', 1, 1, 'Arrange the following political and economic developments in a chronological order:

(A) Shaka (peoples from Central Asia) rulers in the northwest

(B) Indo-Greek rule in the northwest

(C) Vakatakas in the Deccan

(D) Invasion of Alexander of Macedon', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(D), (B), (A), (C)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.728Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (696, 'history-2025-05-20-shift-1', 'q02', 2, 2, 'Verses ascribed to Kabir have been compiled in three distinct but overlapping traditions. Which among the following is not one of them?', '[{"id":"A","text":"Kabir Bijak"},{"id":"B","text":"Kabir Granthavali"},{"id":"C","text":"Adi Granth Sahib"},{"id":"D","text":"Guru Granth Sahib"}]', 0, 'D', 'The Guru Granth Sahib was compiled in its final form in the late seventeenth century when the tenth Sikh Guru, Guru Gobind Singh, incorporated the hymns of the ninth Guru Tegh Bahadur. Thereafter, this scripture came to be known as the Guru Granth Sahib.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.730Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (697, 'history-2025-05-20-shift-1', 'q03', 3, 3, '"I free her from here, but not from there. I have bound her firmly there, so that through the grace of Indra she will have fine sons and be fortunate in her husband''s love." From where is this excerpt of a mantra for producing ''fine sons'' taken:', '[{"id":"A","text":"Brihadaranyaka Upanishad"},{"id":"B","text":"Mahabharata"},{"id":"C","text":"Manusmriti"},{"id":"D","text":"Rigveda"}]', 0, 'D', 'Rigveda because :

1. Patriliny was a common concern, reflected in many Rigvedic mantras.

2. Indra, a key deity, symbolized valour, warfare, and rain.

3. "Here" refers to the father''s house, and "there" to the husband''s house.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.736Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (698, 'history-2025-05-20-shift-1', 'q05', 4, 4, 'The Khilafat Movement of 1919-1920 demanded that the jazīrat-ul-Arab must remain under Muslim sovereignty. Which region was not a part of jazīrat-ul-Arab?', '[{"id":"A","text":"Arabia"},{"id":"B","text":"Syria"},{"id":"C","text":"Afghanistan"},{"id":"D","text":"Palestine"}]', 0, 'C', 'The Jazirat-Ul-Arab consisted of Arabia, Syria, Iraq, Palestine hence the region which was not a part is Afghanistan.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.737Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (699, 'history-2025-05-20-shift-1', 'q06', 5, 5, 'In urban centres, who represented the merchant communities during the medieval period?', '[{"id":"A","text":"Gramsheth"},{"id":"B","text":"Kokasheth"},{"id":"C","text":"Nagarsheth"},{"id":"D","text":"Durgsheth"}]', 0, 'C', 'In western India, merchant groups called mahajans were led by a sheth, and in urban centres like Ahmedabad, their chief representative was the nagarsheth.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.738Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (700, 'history-2025-05-20-shift-1', 'q07', 6, 6, 'Where was the Safavid Empire located?', '[{"id":"A","text":"China"},{"id":"B","text":"Iran"},{"id":"C","text":"Turkey"},{"id":"D","text":"Afghanistan"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.739Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (701, 'history-2025-05-20-shift-1', 'q08', 7, 7, 'The archaeological findings of which grain are relatively rare at Harappan sites?', '[{"id":"A","text":"Rice"},{"id":"B","text":"Wheat"},{"id":"C","text":"Barley"},{"id":"D","text":"Lentil"}]', 0, 'A', 'While wheat, barley, lentils, chickpeas, sesame, and millets were commonly found at Harappan sites, rice remains are relatively rare.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.740Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (702, 'history-2025-05-20-shift-1', 'q09', 8, 8, 'Why did the zamindars regularly fail to pay the revenue demand in the early decades after the ''Permanent Settlement''. Choose the correct statements from below:

(A) The initial demands were very high.

(B) This high demand was imposed in the 1790s, a time when the prices of agricultural produce were depressed, making it difficult for the ryots to pay their dues to the zamindar.

(C) The revenue was invariable, regardless of the harvest, and had to be paid punctually.

(D) The ''Permanent Settlement'' initially limited the power of the zamindar to collect rent from the ryot and manage his zamindari.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'C', 'The correct statements are 3. (A),(B),(C) and (D).', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.740Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (703, 'history-2025-05-20-shift-1', 'q10', 9, 9, 'During the elections of 1937 in British India, the Congress came to power in _ provinces.', '[{"id":"A","text":"Eight"},{"id":"B","text":"Nine"},{"id":"C","text":"Ten"},{"id":"D","text":"Eleven"}]', 0, 'A', 'After the 1937 elections under the Government of India Act (1935), Congress formed ministries in eight of the eleven provinces, working under British Governors.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.740Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (704, 'history-2025-05-20-shift-1', 'q11', 10, 10, 'Who built Secundrah Bagh as a ''pleasure garden''?', '[{"id":"A","text":"Shah Mal"},{"id":"B","text":"Birjis Qadr"},{"id":"C","text":"Wajid Ali Shah"},{"id":"D","text":"Bahadur Shah"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.743Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (705, 'history-2025-05-20-shift-1', 'q12', 11, 11, 'Which of the following ''mature'' Harappan sites are located in present-day India?

(A) Ganweriwala

(B) Kalibangan

(C) Banawali

(D) Rakhigarhi', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', 'Kalibangan is located in present-day Rajasthan, Banawali and Rakhigarhi are in Haryana, while Ganweriwala is situated in modern-day Pakistan.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.744Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (706, 'history-2025-05-20-shift-1', 'q13', 12, 12, 'After M.K. Gandhi''s release from prison in January 1931, where did the Congress leaders meet to plan the future course of action?', '[{"id":"A","text":"Lucknow"},{"id":"B","text":"Lahore"},{"id":"C","text":"Calcutta"},{"id":"D","text":"Allahabad"}]', 0, 'D', 'Gandhiji met Jawaharlal Nehru, Jamnalal Bajaj, Subhas Chandra Bose, Mahadev Desai, and Sardar Vallabh Bhai Patel in Allahabad.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.744Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (707, 'history-2025-05-20-shift-1', 'q14', 13, 13, 'Which of the following statements is true about the amara-nayakas:

(A) The amara-nayakas were civil servants who were given territories to govern by the raya.

(B) The amara-nayakas collected taxes and other dues from peasants, craftspersons and traders in the area.

(C) The amara-nayakas sent tribute to the king annually and personally appeared in the royal court with gifts to express their loyalty.

(D) Kings occasionally asserted their control over the amara-nayakas by transferring them from one place to another.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', 'Statements (B), (C), and (D) are correct, while (A) is incorrect because the amara-nayakas were military commanders, not civil servants, appointed by the raya to govern territories.

_', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.744Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (708, 'history-2025-05-20-shift-1', 'q15', 14, 14, 'The Ain-i Akbari was completed in which regnal year of the emperor Akbar?', '[{"id":"A","text":"Forty-first regnal year"},{"id":"B","text":"Forty-second regnal year"},{"id":"C","text":"Forty-third regnal year"},{"id":"D","text":"Fifty-fourth regnal year"}]', 0, 'B', 'The Ain-i Akbari, completed in 1598 during Emperor Akbar''s forty-second regnal year, was the result of an extensive administrative project led by Abu''l Fazl, undergoing five revisions before its final compilation.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.748Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (709, 'history-2025-05-20-shift-1', 'q16', 15, 15, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (Ⅳ), (B) - (Ⅲ), (C) - (Ⅱ), (D) - (Ⅰ)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'B', 'The correct answers are 2. (A)-(IV),(B)-(III),(C)-(II),(D)-(I).', NULL, 'null', '[]', '[{"id":"q16-table-1","kind":"table","path":"/local-papers/assets/history-2025-05-20-shift-1/q16-table-1.jpg","page":12,"alt":"Table for question 16"}]', '[12]', 'keyed', '[]', '2026-11-05T20:58:38.750Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (710, 'history-2025-05-20-shift-1', 'q17', 16, 16, 'In which year was the last Mughal ruler, Bahadur Shah II, deposed by the British and exiled to Rangoon?', '[{"id":"A","text":"1791"},{"id":"B","text":"1855"},{"id":"C","text":"1870"},{"id":"D","text":"1857"}]', 0, 'D', 'The correct option is 4.1857', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.752Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (711, 'history-2025-05-20-shift-1', 'q18', 17, 17, 'The making of elaborate stone structures known as "megaliths" emerged in which part of the Indian subcontinent from the first millennium BCE?

(A) North India

(B) Central India

(C) South India

(D) East India', '[{"id":"A","text":"(A) and (B) only"},{"id":"B","text":"(B) and (C) only"},{"id":"C","text":"(C) and (D) only"},{"id":"D","text":"(D) and (A) only"}]', 0, 'B', 'New burial practices, including the construction of elaborate stone megaliths, appeared in central and south India from the first millennium BCE, often accompanied by iron tools and weapons.

