INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (712, 'history-2025-05-20-shift-1', 'q19', 18, 18, 'At the end of 1858, when the rebellion collapsed, who escaped to Nepal?', '[{"id":"A","text":"Nana Sahib"},{"id":"B","text":"Kunwar Singh"},{"id":"C","text":"Rani Lakshmi Bai"},{"id":"D","text":"Birjis Qadr"}]', 0, 'A', 'At the end of 1858, following the collapse of the rebellion, Nana Sahib escaped to Nepal, adding to his legacy of courage and valor.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.752Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (713, 'history-2025-05-20-shift-1', 'q20', 19, 19, 'Sarojini Naidu, a woman member of the Constituent Assembly, was elected from which constituency?', '[{"id":"A","text":"United Provinces"},{"id":"B","text":"Madras"},{"id":"C","text":"Bihar"},{"id":"D","text":"Central Provinces"}]', 0, 'C', 'Sarojini Naidu was nominated to the Constituent Assembly on 9 December 1946, representing Bihar.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.753Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (714, 'history-2025-05-20-shift-1', 'q21', 20, 20, 'In the Mahabharata text, "You yourself did not receive the throne, although it fell to you, because of your defect. If the Pandava receives the patrimony ..., his son will surely inherit it in turn, and so will his son, and his." Who is referred to as ''you'' in the excerpt?', '[{"id":"A","text":"Dhritarashtra"},{"id":"B","text":"Pandu"},{"id":"C","text":"Duryodhana"},{"id":"D","text":"Yudhisthira"}]', 0, 'A', '"You" refers to Dhritarashtra, spoken by his son Duryodhana out of jealousy as people favored the Pandavas for their courage.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.755Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (715, 'history-2025-05-20-shift-1', 'q22', 21, 21, 'Arrange the following teachers of the Chisti Silsila according to their year of death chronologically:

(A) Shaikh Fariduddin Ganj-i Shakar

(B) Shaikh Nasiruddin Chiragh-i Dehli

(C) Khwaja Qutbuddin Bakhtiyar Kaki

(D) Shaikh Nizamuddin Auliya', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (A), (D), (B)"}]', 0, 'D', 'The correct option is 4. (C), (A), (D), (B) because :

(C) Khwaja Qutbuddin Bakhtiyar Kaki - 1235

(A) Shaikh Fariduddin Ganj-i Shakar - 1265

(D) Shaikh Nizamuddin Auliya - 1325

(B) Shaikh Nasiruddin Chiragh-i Dehli - 1356', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.756Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (716, 'history-2025-05-20-shift-1', 'q23', 22, 22, 'Who did Baba Guru Nanak appoint as one of his disciples to succeed him as the preceptor (guru)?', '[{"id":"A","text":"Guru Arjan"},{"id":"B","text":"Guru Angad"},{"id":"C","text":"Guru Gobind Singh"},{"id":"D","text":"Guru Tegh Bahadur"}]', 0, 'B', 'Baba Guru Nanak formed a community with collective worship and appointed Guru Angad as his successor. This tradition continued for nearly 200 years.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.757Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (717, 'history-2025-05-20-shift-1', 'q24', 23, 23, 'What does the term ''Piyadassi'' means in the earliest inscriptions?', '[{"id":"A","text":"Beloved of the gods"},{"id":"B","text":"Beloved of the people"},{"id":"C","text":"Pleasant to behold"},{"id":"D","text":"Beloved of the universe"}]', 0, 'C', 'James Prinsep deciphered the Brahmi and Kharosthi scripts, revealing that many inscriptions referred to a king called Piyadassi, meaning "pleasant to behold."', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.758Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (718, 'history-2025-05-20-shift-1', 'q25', 24, 24, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{II}) $, (D) - $ (\\mathrm{I}) $"},{"id":"C","text":"(A) - (I), (B) - (III), (C) - (IV), (D) - (II)"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'B', 'The correct option is 2. (A)-(III),(B)-(IV),(C)-(II),(D)-(I)', NULL, 'null', '[]', '[{"id":"q25-table-1","kind":"table","path":"/local-papers/assets/history-2025-05-20-shift-1/q25-table-1.jpg","page":19,"alt":"Table for question 25"}]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.767Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (719, 'history-2025-05-20-shift-1', 'q26', 25, 25, 'Who accompanied Augustus Cleveland, the Collector of Bhagalpur, to the Jangal Mahals in 1782, and painted a set of aquatints?', '[{"id":"A","text":"Joseph Noel Paton"},{"id":"B","text":"Thomas Jones Barker"},{"id":"C","text":"William Hodges"},{"id":"D","text":"Captain Cook"}]', 0, 'C', 'William Hodges, who sailed with Captain Cook, came to India and befriended Augustus Cleveland. In 1782, he accompanied Cleveland to the Jangal Mahals and painted a series of aquatints.', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.767Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (720, 'history-2025-05-20-shift-1', 'q27', 26, 26, 'According to Ibn Battuta''s description of the postal system in India, what is the ''uluq''?', '[{"id":"A","text":"Horse-post"},{"id":"B","text":"Elephant-post"},{"id":"C","text":"Bullock-post"},{"id":"D","text":"Oxen-post"}]', 0, 'A', 'In India, the postal system had two types: the horsepost, or uluq, using royal horses stationed every four miles, and the foot post, known as dawa.

