INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (730, 'history-2025-05-20-shift-1', 'q37', 36, 36, 'According to Ibn Battuta''s account of Delhi, inside which darwaza of Delhi there was a grain market?', '[{"id":"A","text":"Budaun darwaza"},{"id":"B","text":"Mandwi darwaza"},{"id":"C","text":"Gul darwaza"},{"id":"D","text":"Buland darwaza"}]', 0, 'B', 'The city of Delhi had twenty-eight gates called darwazas, with Budaun Darwaza being the largest; inside Mandwi Darwaza lies a grain market, and next to Gul Darwaza is an orchard.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.771Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (731, 'history-2025-05-20-shift-1', 'q38', 37, 37, 'What were the rayas of the Vijayanagar Empire called:', '[{"id":"A","text":"Gajapati"},{"id":"B","text":"Ashvapati"},{"id":"C","text":"Narapati"},{"id":"D","text":"Singhpati"}]', 0, 'C', 'Gajapati, meaning lord of elephants, was a powerful fifteenth-century dynasty in Orissa. In Vijayanagara, Deccan Sultans were called ashvapati (lord of horses) and rayas as narapati (lord of men).', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.771Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
