INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (743, 'history-2025-06-03-shift-2', 'q04', 4, 4, 'In 1565, who led the Vijayanagara army into battle at ''Rakshasi-Tangadi''?', '[{"id":"A","text":"Rama Raya"},{"id":"B","text":"Krishnadeva Raya"},{"id":"C","text":"Deva Raya"},{"id":"D","text":"Harihara II"}]', 0, 'A', 'In 1565 Rama Raya, the chief minister of Vijayanagara, led the army into battle at Rakshasi-Tangadi (also known as Talikota), where his forces were routed by the combined armies of Bijapur, Ahmadnagar and Golconda.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.775Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (744, 'history-2025-06-03-shift-2', 'q05', 5, 5, 'When did the Deccan Riots Commission present a report to the British Parliament?', '[{"id":"A","text":"1871"},{"id":"B","text":"1889"},{"id":"C","text":"1878"},{"id":"D","text":"1874"}]', 0, 'C', 'The commission''s findings were presented to the British Parliament in 1878 as the Deccan Riots Report, a crucial document for historical inquiry. It offers scholars a comprehensive range of primary sources for analyzing the causes and dynamics of the riot.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.776Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (745, 'history-2025-06-03-shift-2', 'q07', 6, 6, 'By the 10th century, the compositions of the 12 Alvars were compiled in an anthology known as:', '[{"id":"A","text":"Nalapira Prabandham"},{"id":"B","text":"Deviyara Prabandham"},{"id":"C","text":"Alvariya Prabandham"},{"id":"D","text":"Nalayira Divyaprabandham"}]', 0, 'D', 'By the tenth century the compositions of the 12 Alvars were compiled in an anthology known as the Nalayira Divyaprabandham ("Four Thousand Sacred Compositions").

_', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.776Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
