Sind.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', '(B), (C) and (D) are the correct statements but (A) stands incorrect because Ibn Battuta''s book of travels, called Rihla, written in Arabic.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.777Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (752, 'history-2025-06-03-shift-2', 'q14', 13, 13, 'Which stone inscription records the history of a guild of silk-weavers who originally lived in Gujarat?', '[{"id":"A","text":"Mandasor Inscription"},{"id":"B","text":"Parayaga Inscription"},{"id":"C","text":"Allahabad Inscription"},{"id":"D","text":"Vibhuti Inscription"}]', 0, 'A', 'The Mandasor Inscription is a 5th-century CE stone inscription from Mandsaur, Madhya Pradesh, dating to the reign of Gupta ruler Kumaragupta I.

It documents the activities of a guild of silk weavers (tantuvayas) who migrated from Lata (Gujarat) to Dasapura (Mandsaur).', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.777Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
