INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (755, 'history-2025-06-03-shift-2', 'q18', 16, 16, 'Which British artist went on a voyage to the Pacific (1772-75) and then came to India?', '[{"id":"A","text":"Augustus Cleveland"},{"id":"B","text":"William Hodges"},{"id":"C","text":"Francis Hamilton"},{"id":"D","text":"Charles Cornwallis"}]', 0, 'B', 'William Hodges was a British artist who accompanied Captain Cook on his second voyage to the Pacific (1772-75), and then came to India.', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:38.778Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (756, 'history-2025-06-03-shift-2', 'q19', 17, 17, 'Identify the name of the Governor-General who described the kingdom of Awadh as "a cherry that will drop into our mouth one day":', '[{"id":"A","text":"Lord Malcolm"},{"id":"B","text":"Lord Dalhousie"},{"id":"C","text":"Lord Mayo"},{"id":"D","text":"Lord Canning"}]', 0, 'B', 'In 1851 Governor General Lord Dalhousie described the kingdom of Awadh as "a cherry that will drop into our mouth one day".', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.778Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (757, 'history-2025-06-03-shift-2', 'q20', 18, 18, 'Identify the correct statements regarding Al-Biruni:

(A) Al-Biruni was well versed in several languages: Persian, Hebrew, Sanskrit etc.

(B) Al-Biruni was born in Syria.

(C) Al-Biruni was familiar with the work of Plato and other Greek

philosophers.

(D) Al-Biruni read their work in Arabic translations.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'D', '(A),(C) and (D) are correct but (B) is incorrect because Al-Biruni was born in 973, in Khwarizm in present day Uzbekistan.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.778Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (758, 'history-2025-06-03-shift-2', 'q21', 19, 19, 'Identify the most famous court-historian during Akbar''s reign:', '[{"id":"A","text":"Mir Samad"},{"id":"B","text":"Mir Hasan"},{"id":"C","text":"Abu''l Fazl"},{"id":"D","text":"Abu''l Nizami"}]', 0, 'C', 'Abu''l Fazl was the most famous court historian during Akbar''s reign. He was not only a scholar but also one of Akbar''s closest advisors and a member of his Navaratnas (Nine Jewels).

He authored two major historical works:

• Ain-i-Akbari - a detailed record of Akbar''s administration, economy, culture, and society.

• Akbarnama - the official chronicle of Akbar''s reign, describing his life, policies, and achievements.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (759, 'history-2025-06-03-shift-2', 'q22', 20, 20, 'Ibn Batutta returned to his home in _, about thirty years after he had set out.', '[{"id":"A","text":"1355"},{"id":"B","text":"1334"},{"id":"C","text":"1354"},{"id":"D","text":"1356"}]', 0, 'C', 'Ibn Battuta returned home in 1354, about 30 years after he had set out.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (760, 'history-2025-06-03-shift-2', 'q23', 21, 21, 'Who remarked that South Africa was "the making of the Mahatma":', '[{"id":"A","text":"Bipin Chandra Pal"},{"id":"B","text":"Lala Lajpat Rai"},{"id":"C","text":"Louis Fischer"},{"id":"D","text":"Chandran Devanesan"}]', 0, 'D', 'Chandran Devanesan observed that South Africa was "the making of the Mahatma," as it was there that Gandhi developed satyagraha, promoted interreligious harmony, and challenged social discrimination within Indian society.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (761, 'history-2025-06-03-shift-2', 'q24', 22, 22, 'Identify the incorrect statements regarding the travellers in Medieval India:

(A) Jean-Baptiste Tavernier travelled to India at least seven times.

(B) Manucci, the french doctor, never returned to Europe and settled down in India.

(C) Francois Bernier was closely associated with the Mughal court.

(D) Danishmand Khan, was a syrian noble at the Mughal court.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Jean-Baptiste Tavernier visited India six times, not seven. Manucci did return to Europe, and Danishmand Khan was an Iranian, not Syrian noble at the Mughal court.

_', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (762, 'history-2025-06-03-shift-2', 'q25', 23, 23, 'The most important idea in _ is that the entire world is animated.', '[{"id":"A","text":"Buddhism"},{"id":"B","text":"Hinduism"},{"id":"C","text":"Jainism"},{"id":"D","text":"Shaivism"}]', 0, 'C', 'The most important idea in Jainism is that the entire world is animated: even stones, rocks and water have life.', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (763, 'history-2025-06-03-shift-2', 'q26', 24, 24, 'Identify the year of Champaran Movement:', '[{"id":"A","text":"1917"},{"id":"B","text":"1918"},{"id":"C","text":"1921"},{"id":"D","text":"1922"}]', 0, 'A', 'In 1917, Mahatma Gandhi spent much of his time in Champaran, working to secure tenancy rights and freedom of cultivation for the peasants.', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (764, 'history-2025-06-03-shift-2', 'q27', 25, 25, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - $ (\\mathrm{I}) $, $ (\\mathrm{B}) $ - $ (\\mathrm{II}) $, $ (\\mathrm{C}) $ - $ (\\mathrm{III}) $, $ (\\mathrm{D}) $ - $ (\\mathrm{IV}) $"},{"id":"B","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{II}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{IV}) $"},{"id":"C","text":"(A) - $ (\\mathrm{II}) $, $ (\\mathrm{B}) - (\\mathrm{I}) $, $ (\\mathrm{C}) - (\\mathrm{IV}) $, $ (\\mathrm{D}) - (\\mathrm{III}) $"},{"id":"D","text":"(A) - $ (\\mathrm{I}\\mathrm{II}) $, (B) - $ (\\mathrm{IV} $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $"}]', 0, 'D', 'The correct option is 4. (A)-(III),(B)-(IV),(C)-(I),(D)-(II)', NULL, 'null', '[]', '[{"id":"q27-table-1","kind":"table","path":"/local-papers/assets/history-2025-06-03-shift-2/q27-table-1.jpg","page":19,"alt":"Table for question 27"}]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.779Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (765, 'history-2025-06-03-shift-2', 'q29', 26, 26, 'Who introduced the Subsidiary Alliance in Awadh (1801)?', '[{"id":"A","text":"Lord Hardinge"},{"id":"B","text":"Lord Hastings"},{"id":"C","text":"Lord Wellesley"},{"id":"D","text":"Lord Cornwallis"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.781Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (766, 'history-2025-06-03-shift-2', 'q30', 27, 27, 'Most Ashokan inscriptions were in _ language.', '[{"id":"A","text":"Sanskrit"},{"id":"B","text":"Pali"},{"id":"C","text":"Prakrit"},{"id":"D","text":"Arabic"}]', 0, 'C', 'Most Asokan inscriptions were in the Prakrit language.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.781Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (767, 'history-2025-06-03-shift-2', 'q31', 28, 28, 'Identify the region where the Jotedars were most powerful in the 18th-century:', '[{"id":"A","text":"East-Bihar"},{"id":"B","text":"United-Provinces"},{"id":"C","text":"West-Punjab"},{"id":"D","text":"North-Bengal"}]', 0, 'D', 'In Francis Buchanan''s survey of the Dinajpur district in North Bengal we have a vivid description of this class of rich peasants known as jotedars

