INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (768, 'history-2025-06-03-shift-2', 'q32', 29, 29, 'Identify the regions where archaeologists have found the terracotta models of the ''plough'' and evidence of ploughed field?', '[{"id":"A","text":"Cholistan, Banawali and Kalibangan"},{"id":"B","text":"Ganweriwala, Mitathal and Harappa"},{"id":"C","text":"Ameri, Balakot and Siswal"},{"id":"D","text":"Manda, Sutkagendor and Amravati"}]', 0, 'A', 'Archaeologists discovered terracotta plough models at Banawali and evidence of ploughed fields at Kalibangan and Cholistan, showing the agricultural practices of the Harappan Civilization.', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.782Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (769, 'history-2025-06-03-shift-2', 'q33', 30, 30, 'Who wrote the earliest histories of the uprising (1857), noting that, "the panchayats were a nightly occurrence in the Kanpur Sepoy lines"?', '[{"id":"A","text":"James Outram"},{"id":"B","text":"Charles Mason"},{"id":"C","text":"Charles Ball"},{"id":"D","text":"Captain Hearsey"}]', 0, 'C', 'Charles Ball, who wrote one of the earliest histories of the uprising, noted that panchayats were a nightly occurrence in the Kanpur sepoy lines. What this suggests is that some of the decisions were taken collectively.', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.783Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (770, 'history-2025-06-03-shift-2', 'q34', 31, 31, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (I), (B) - (III), (C) - (II), (D) - (IV)"},{"id":"C","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', 'Option 2: (A) - (I), (B) - (III), (C) - (II), (D) - (IV)', NULL, 'null', '[]', '[{"id":"q34-table-1","kind":"table","path":"/local-papers/assets/history-2025-06-03-shift-2/q34-table-1.jpg","page":24,"alt":"Table for question 34"}]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.783Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (771, 'history-2025-06-03-shift-2', 'q35', 32, 32, 'Arrange the following events in a chronological order:

(A) Ryots in Deccan villages rebel

(B) Santhal Rebellion

(C) Permanent Settlement in Bengal

(D) First revenue settlement in the Bombay Deccan', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (D), (B), (A)"}]', 0, 'D', 'The correct order is

(C) Permanent Settlement in Bengal - 1793

(D) First revenue settlement in the Bombay Deccan - 1818

(B) Santhal rebellion - 1855-56

(A) Ryots in Deccan villages rebel - 1875', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.784Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (772, 'history-2025-06-03-shift-2', 'q36', 33, 33, 'Who founded the Mauryan Empire in c. 321 BCE?', '[{"id":"A","text":"Asoka"},{"id":"B","text":"Bimbisara"},{"id":"C","text":"Kautilya Maurya"},{"id":"D","text":"Chandragupta Maurya"}]', 0, 'D', 'The growth of Magadha culminated in the emergence of the Mauryan Empire. Chandragupta Maurya, who founded the empire (c. 321 BCE), extended control as far northwest as Afghanistan and Baluchistan.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.784Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (773, 'history-2025-06-03-shift-2', 'q37', 34, 34, 'When was the Constitution of India signed?', '[{"id":"A","text":"December 1949"},{"id":"B","text":"January 1949"},{"id":"C","text":"January 1947"},{"id":"D","text":"August 1947"}]', 0, 'A', 'The Constitution of India was adopted and signed on 26 December 1949 by the Constituent Assembly. It came into effect on 26 January 1950, marking the beginning of the Republic of India.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.785Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (774, 'history-2025-06-03-shift-2', 'q38', 35, 35, 'Which Jataka story describes the plight of the subjects of a wicked king: these included elderly women and men, cultivators, herders, village boys, and even animals?', '[{"id":"A","text":"Panchatantra Jataka"},{"id":"B","text":"Abhidhamma Jataka"},{"id":"C","text":"Gandantindu Jataka"},{"id":"D","text":"Jivika Jataka"}]', 0, 'C', 'The Gandatinu Jataka narrates the suffering of people under a wicked king, where villagers-young and old, even animals-faced constant misery, robbed at night and taxed by day. When the king, in disguise, heard their curses, he found that many had abandoned their villages to live in the forests to escape oppression.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.785Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (775, 'history-2025-06-03-shift-2', 'q39', 36, 36, 'Francis Buchanan was a physician who came to India and served in the Bengal Medical Service from:', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Francis Buchanan was a physician who came to India and served in the Bengal Medical Service from 1794 to 1815.', NULL, 'null', '[]', '[{"id":"q39-table-1","kind":"table","path":"/local-papers/assets/history-2025-06-03-shift-2/q39-table-1.jpg","page":28,"alt":"Table for question 39"}]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.785Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (776, 'history-2025-06-03-shift-2', 'q40', 37, 37, 'Who composed the Natyashastrina in Sanskrit?', '[{"id":"A","text":"Panini"},{"id":"B","text":"Ashvaghosh"},{"id":"C","text":"Charaka"},{"id":"D","text":"Bharata"}]', 0, 'D', 'The Natyashastra, written by Bharata, is an ancient Sanskrit treatise on dramaturgy and performing arts, covering theatre, dance, and music.', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.786Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (777, 'history-2025-06-03-shift-2', 'q41', 38, 38, '4. Tanks', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'Gopurams, or royal gateways, were towering structures that often surpassed the main shrine in height, making temples visible from afar. They also symbolized royal power and authority, showcasing the wealth, skill, and resources commanded by kings.', 'pcba8d0dc9ebc', 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.786Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (778, 'history-2025-06-03-shift-2', 'q42', 39, 39, '4. Hoysalas', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'According to the passage, "severe defeats were inflicted on the Sultan of Bijapur (1520)" during the reign of Krishnadeva Raya, the ruler of the Tuluva dynasty of the Vijayanagara Empire. His reign (1509-1529) was marked by military expansion and consolidation of the empire. The defeat of the Sultan of Bijapur was one of

Krishnadeva Raya''s major military successes, which demonstrated the strength and strategic prowess of Vijayanagara under his leadership.', 'p830b147cc9e1', 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.786Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (779, 'history-2025-06-03-shift-2', 'q43', 40, 40, '4. Aravidu Dynasty', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The passage mentions that the Sangama dynasty was the first to rule Vijayanagara until 1485. After them, the Saluvas, who were military commanders, took control and ruled till 1503. Hence, the Saluvas were the second dynasty of the Vijayanagara Empire.', 'p603dbe8387d5', 'null', '[]', '[]', '[34]', 'keyed', '[]', '2026-11-05T20:58:38.786Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (780, 'history-2025-06-03-shift-2', 'q49', 41, 41, '4. Reward Act', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The Rowlatt Act (1919) permitted detention without trial, leading to widespread protests as Indians saw it as an unjust continuation of wartime repression.', 'p5b94ed7ea83f', 'null', '[]', '[]', '[46]', 'keyed', '[]', '2026-11-05T20:58:38.787Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (781, 'history-2025-06-03-shift-2', 'q50', 42, 42, '4. United Provinces', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The Rowlatt Act sparked intense protests in the Punjab, where many veterans had hoped for rewards after serving in the war. Tensions peaked in April 1919 at Amritsar, when British troops fired on a nationalist gathering, killing over 400 people in the Jallianwala Bagh massacre.', 'p3eec712466a9', 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.787Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (782, 'history-2025-06-21-shift-1', 'q01', 1, 1, 'The Ain-i-Akbari does not give a detailed account of which among the following:', '[{"id":"A","text":"Mughal Art and Architecture"},{"id":"B","text":"Organisation of the Mughal Court"},{"id":"C","text":"Mughal Administration"},{"id":"D","text":"Mughal Army"}]', 0, 'A', 'The Ain-i-Akbari, written by Abul Fazl, is a part of the Akbarnama and records the administration, court organisation, revenue system, and military of Akbar''s reign in detail. However, it does not provide a detailed account of Mughal art and architecture.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.788Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (783, 'history-2025-06-21-shift-1', 'q02', 2, 2, 'Arrange the major Sufi-teachers of the Chisti-Silsila chronologically:

(A) Khwaja Qutbuddin Bakhtiyar Kaki

(B) Shaikh Nasiruddin Chirag-i-Dehli
(C) Shaikh Nizamuddin Auliya (D) Shaikh Fariduddin Ganj-i Shakar', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(A), (D), (C), (B)"},{"id":"D","text":"(B), (D), (C), (A)"}]', 0, 'C', 'The Chishti-Silsila was a prominent Sufi order in India. The correct chronological order of its major teachers is:

1. Khwaja Qutbuddin Bakhtiyar Kaki - Disciple of Moinuddin Chishtī, he spread the order in Delhi.

2. Shaikh Fariduddin Ganj-i-Shakar - Disciple of Qutbuddin Bakhtiyar Kaki, based in Ajodhan (Pakistan).

3. Shaikh Nizamuddin Auliya - Disciple of Fariduddin, a renowned saint of Delhi.

4. Shaikh Nasiruddin Chirag-i-Dehli - Disciple of Nizamuddin Auliya and his spiritual successor.

This sequence reflects the spiritual lineage within the Chishti tradition.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.788Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (784, 'history-2025-06-21-shift-1', 'q03', 3, 3, 'Identify the correct statements for the army of the Mauryan Empire:

(A) Megasthenes mentions a committee with six subcommittees for coordinating military activity.

(B) One committee looked after the navy.

(C) The second committee looked after transport and provisions.

(D) The third committee was responsible for agriculture.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'B', 'According to Megasthenes in his book Indica, the Mauryan Empire maintained a highly organised military system, managed by a war office divided into six specialised subcommittees:

• (A) is correct: Megasthenes explicitly mentions this administrative structure.

• (B) is correct: One subcommittee was responsible for overseeing the navy.

(C) is correct: Another subcommittee managed transport and provisions, ensuring logistical support for the army.

• (D) is incorrect: No subcommittee was tasked with agriculture, as it was not part of the military administration.

Thus, only statements (A), (B), and (C) accurately reflect the military organisation of the Mauryan Empire.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (785, 'history-2025-06-21-shift-1', 'q04', 4, 4, 'The symbol of the ''wheel'' in many Buddhist sculptures stands for which representation?', '[{"id":"A","text":"Mahaniravana"},{"id":"B","text":"Buddha''s Birth"},{"id":"C","text":"Enlightenment of Buddha"},{"id":"D","text":"First Sermon of Buddha"}]', 0, 'D', 'The symbol of the ''wheel'' in many Buddhist sculptures, known as the Dharmachakra (Wheel of Dharma). The Dharmachakra symbolises the Buddha''s act of "setting the Wheel of Dharma in motion" (Dharmachakrapravartana), which refers to his very First Sermon at Sarnath, where he taught The Four Noble Truths and the Eightfold Path.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (786, 'history-2025-06-21-shift-1', 'q05', 5, 5, 'Identify the principal deities of the ''Vedic'' pantheon:', '[{"id":"A","text":"Agni, Indra, Soma"},{"id":"B","text":"Rudra, Durga, Soma"},{"id":"C","text":"Shiva, Subhadra, Balarama"},{"id":"D","text":"Indra, Soma, Jagannatha"}]', 0, 'A', 'These three deities-Indra (king, war, weather), Agni (fire, messenger to gods), and Soma (sacred drink, associated god)-are the most frequently invoked and central figures in the Rigveda, making them the principal gods of the early Vedic pantheon.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (787, 'history-2025-06-21-shift-1', 'q06', 6, 6, 'When did Alexander Greenlaw take the first detailed photographs of archaeological remains at Hampi?', '[{"id":"A","text":"1857"},{"id":"B","text":"1856"},{"id":"C","text":"1877"},{"id":"D","text":"1853"}]', 0, 'B', 'Alexander Greenlaw took the first detailed photographs of archaeological remains at Hampi in 1856.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (788, 'history-2025-06-21-shift-1', 'q07', 7, 7, 'The epic Silappadikaram was written in which language?', '[{"id":"A","text":"Tamil"},{"id":"B","text":"Telugu"},{"id":"C","text":"Kannada"},{"id":"D","text":"Bengali"}]', 0, 'A', 'The epic Silappadikaram, or "The Story of the Anklet," is written in Tamil and is one of the five great epics of Tamil literature.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (789, 'history-2025-06-21-shift-1', 'q08', 8, 8, 'What was the term used for ''the owner, master or head of household, who exercised control over the women, children etc.'' in ancient texts?', '[{"id":"A","text":"Adimai"},{"id":"B","text":"Vellalar"},{"id":"C","text":"Gahapati"},{"id":"D","text":"Uzhavar"}]', 0, 'C', '• Gahapati (Prakrit/Pali; Sanskrit: Grihapati): Refers to the head of a household in Buddhist and Jain texts. Typically, a Gahapati was a respected householder, often engaged in agriculture or trade.

- Vellalar: Wealthy landowners in ancient Tamil society. They held significant social status and controlled large agricultural estates.

• Uzhavar: Ordinary ploughmen or cultivators who directly worked the land. They formed the backbone of the agrarian economy.

- Adimai: Landless laborers and slaves. They worked under landowners and had minimal or no rights over land or produce.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.789Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (790, 'history-2025-06-21-shift-1', 'q09', 9, 9, 'The distinctive Harappan pottery has not been found in which of the following states?', '[{"id":"A","text":"Rajasthan"},{"id":"B","text":"Punjab"},{"id":"C","text":"Madhya Pradesh"},{"id":"D","text":"Maharashtra"}]', 0, 'C', 'Harappan pottery has been found in various states associated with the Harappan Civilization, including Rajasthan, Punjab, and Madhya Pradesh. These regions have yielded significant archaeological evidence of Harappan settlements and their distinctive pottery. However, Maharashtra is not a region where Harappan pottery has been discovered, as the civilisation''s influence did not extend significantly into this area.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.790Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (791, 'history-2025-06-21-shift-1', 'q10', 10, 10, 'Who among the following took pride in the title "establisher of the Yavana kingdom":', '[{"id":"A","text":"Rama Raya"},{"id":"B","text":"Bukka"},{"id":"C","text":"Harihara"},{"id":"D","text":"Krishnadeva Raya"}]', 0, 'D', 'Krishnadeva Raya (of the Vijayanagara Empire) bore the title Yavana Rajya Sthapanacharya (Establisher of the Yavana Kingdom). He earned this title after successfully reinstating a Bahmani Sultan''s power after he had been deposed, demonstrating his military and political supremacy in the Deccan.', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.790Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (792, 'history-2025-06-21-shift-1', 'q11', 11, 11, 'Identify the correct statements from below:

(A) Verses ascribed to Kabir have been compiled in three distinct but overlapping traditions.

(B) The Kabir Bijak is preserved by the Kabirpanth in Varanasi.

(C) The Kabir Granthawali is associated with the Dadupanth in Maharashtra.

(D) Many of Kabir''s compositions are found in the Adi Granth Sahib.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', 'Kabir''s verses exist in three overlapping collections: Kabir Bijak, Kabir Granthavali, and Adi Granth (A is correct).

• The Kabir Bijak is preserved by the Kabirpanth in Varanasi (B is correct).

• Many of Kabir''s compositions are found in the Adi Granth Sahib (D is correct).

- The Kabir Granthavali is not associated with the Dadupanth in Maharashtra, but with the Kabirpanth in Uttar Pradesh (C is incorrect).', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.790Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (793, 'history-2025-06-21-shift-1', 'q12', 12, 12, 'Match List-I with List-II:', '[{"id":"A","text":"(\\mathbf{A})-(\\mathbf{I}),(\\mathbf{B})-(\\mathbf{II}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})"},{"id":"B","text":"\\ (A)\\ -\\ (II),\\ (B)\\ -\\ (III),\\ (C)\\ -\\ (I),\\ (D)\\ -\\ (IV)"},{"id":"C","text":"(\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{I}),(\\mathbf{C})-(\\mathbf{IV}),(\\mathbf{D})-(\\mathbf{III})"},{"id":"D","text":"\\ (\\mathrm{A})-(\\mathrm{II}),(\\mathrm{B})-(\\mathrm{IV}),(\\mathrm{C})-(\\mathrm{I}),(\\mathrm{D})-(\\mathrm{III})"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q12-table-1","kind":"table","path":"/local-papers/assets/history-2025-06-21-shift-1/q12-table-1.jpg","page":9,"alt":"Table for question 12"}]', '[9]', 'keyed', '[]', '2026-11-05T20:58:38.790Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (794, 'history-2025-06-21-shift-1', 'q13', 13, 13, 'Which text contains the verses on ''the nature of the self'' and ''the true sacrifice'' and was composed in 6th-century BCE?', '[{"id":"A","text":"Chhandogya Upanishad"},{"id":"B","text":"Rigveda"},{"id":"C","text":"Dipavamsa"},{"id":"D","text":"Tipitaka"}]', 0, 'A', 'The text containing verses on "the nature of the self" (Atman) and "the true sacrifice", composed around the 6th century BCE, is the Chhandogya Upanishad.', NULL, 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:38.790Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (795, 'history-2025-06-21-shift-1', 'q14', 14, 14, 'Name the temple having "scenes from the Ramayana sculpted on the inner walls of the shrine" in the Vijayanagara empire?', '[{"id":"A","text":"Pampadevi Temple"},{"id":"B","text":"Lotus Temple"},{"id":"C","text":"Virupaksha Temple"},{"id":"D","text":"Hazara Rama Temple"}]', 0, 'D', 'The Hazara Rama Temple in Hampi (Vijayanagara) is famous for its extensive carvings, which cover the inner and outer walls of the shrine with detailed scenes from the Ramayana.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:38.791Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (796, 'history-2025-06-21-shift-1', 'q15', 15, 15, 'Match List-I with List-II:', '[{"id":"A","text":"(A) - (III), (B) - (II), (C) - (IV), (D) - (I)"},{"id":"B","text":"(A) - (Ⅳ), (B) - (Ⅲ), (C) - (Ⅰ), (D) - (Ⅱ)"},{"id":"C","text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)"},{"id":"D","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q15-table-1","kind":"table","path":"/local-papers/assets/history-2025-06-21-shift-1/q15-table-1.jpg","page":12,"alt":"Table for question 15"}]', '[11,12]', 'keyed', '[]', '2026-11-05T20:58:38.791Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (797, 'history-2025-06-21-shift-1', 'q17', 16, 16, 'Gonoo, the tribal cultivator of Singhbhum in Chotanagpur, became a rebel leader of which tribe?', '[{"id":"A","text":"Santhal"},{"id":"B","text":"Kol"},{"id":"C","text":"Urao"},{"id":"D","text":"Koeri"}]', 0, 'B', 'Gonoo was a tribal leader from Singhbhum who led the Kol tribes in rebellion against British rule and local exploiters. He played a key role in the Kol uprising of 1831-1832 and again during the Revolt of 1857. His leadership highlights the tribal resistance against colonial and local oppression during that period.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:38.791Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (798, 'history-2025-06-21-shift-1', 'q18', 17, 17, 'Abdur Razzaq, who visited Calicut (present-day Kozhikode) in the fifteenth-century, was:', '[{"id":"A","text":"Merchant of Aleppo"},{"id":"B","text":"Traveller from Basra"},{"id":"C","text":"Wrestler from Mysore"},{"id":"D","text":"Ambassador of Persia"}]', 0, 'D', 'Abdur Razzaq, a prominent Persian scholar and chronicler, visited India in the fifteenth century as an ambassador from Herat (Persia).

He arrived in South India and visited the Vijayanagara Empire in 1442-1443 during the reign of its ruler, Deva Raya II. His account provides one of the most important descriptions of the city of Vijayanagara, notably including details about its massive and elaborate fortifications. The fortification system he described was unique as it not only encircled the city but also enclosed agricultural tracts, forests, and water sources to protect the population and ensure food supply during sieges.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.791Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (799, 'history-2025-06-21-shift-1', 'q19', 18, 18, 'Arrange the following events in chronological order:

(A) Gandhi-Irwin Pact

(B) Rowlatt Satyagraha

(C) Civil Disobedience Movement

(D) Quit India Movement', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(B), (C), (A), (D)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:38.792Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (800, 'history-2025-06-21-shift-1', 'q20', 19, 19, 'While historians use the term "Vijayanagara empire", contemporaries describe it as:', '[{"id":"A","text":"Karnataka Samrajyamு"},{"id":"B","text":"Hampi Samrajyamு"},{"id":"C","text":"Tamil Samrajyamு"},{"id":"D","text":"Virupaksha Samrajyamு"}]', 0, 'A', 'Historians refer to the state as the Vijayanagara Empire, named after its capital, though contemporaries knew it as the Karnataka samrajyamru. Founded in 1336 by Harihara and Bukka, it rose as a major political and cultural power in South India. Though its capital was destroyed in 1565, the impressive ruins at Hampi still stand as a reminder of its former grandeur. Much of what is known about the empire comes from foreign travelers'' accounts and royal inscriptions.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.792Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (801, 'history-2025-06-21-shift-1', 'q21', 20, 20, 'Who composed the Harshacharita in Sanskrit?', '[{"id":"A","text":"Harisena"},{"id":"B","text":"Magha"},{"id":"C","text":"Kalidasa"},{"id":"D","text":"Banabhatta"}]', 0, 'D', 'Banabhatta composed the Harshacharita (Deeds of Harsha) in Sanskrit. It''s a biography of his patron, King Harsha (Harshavardhana) of the Pushyabhuti dynasty, and provides important historical and cultural insights into 7th-century India.', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:38.792Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (802, 'history-2025-06-21-shift-1', 'q22', 21, 21, 'Merchants often had strong community or kin ties and were organised into their own caste-cum-occupational bodies. In western India, these groups were called as:', '[{"id":"A","text":"Karkhanadars"},{"id":"B","text":"Sheths"},{"id":"C","text":"Mahajans"},{"id":"D","text":"Mahaprathams"}]', 0, 'C', '- Mahajans: This term refers to the guilds or organized corporate bodies of merchants in western India, particularly Gujarat and Rajasthan. The term literally means "great people" and they played a significant role in regulating trade and finance.

• Sheths: This term generally denotes a wealthy merchant, banker, or head of a guild-a title of respect given to the leading figure in the trading community, not the organization itself.

• Karkhanadars: This term refers to the owners or managers of Karkhanas (workshops or factories), not the merchant community''s organization.', NULL, 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:38.793Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (803, 'history-2025-06-21-shift-1', 'q23', 22, 22, 'Which leaders are directly related to the Revolt of 1857?

(A) Maulvi Ahmadullah Shah

(B) Rani Laxmi Bai

(C) Nana Sahib

(D) Sidhu Manjhi', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(B), (C) and (D) only"},{"id":"D","text":"(A), (B), (C) and (D)"}]', 0, 'B', 'Leaders directly associated with the Revolt of 1857 include Maulvi Ahmadullah Shah of Faizabad, Rani Laxmi Bai of Jhansi, and Nana Sahib of Kanpur. Sidhu Manjhi, however, was linked to the Santhal Rebellion of 1855-56, not the 1857 uprising', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:38.793Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (804, 'history-2025-06-21-shift-1', 'q25', 23, 23, 'Which one of the following is not part of Kuru-Panchala region and its neighbouring areas?', '[{"id":"A","text":"Bodh Gaya"},{"id":"B","text":"Indraprastha"},{"id":"C","text":"Virata"},{"id":"D","text":"Hampi"}]', 0, 'D', 'Hampi, located in Karnataka, was the capital of the medieval Vijayanagara Empire and lies far from the northern Kuru-Panchala region.

Kuru-Panchala, including places like Indraprastha and Virata, was centred in the Ganga-Yamuna Doab during the Vedic and epic periods.

Thus, Hampi is not part of Kuru-Panchala or its neighbouring areas.', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:38.793Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (805, 'history-2025-06-21-shift-1', 'q26', 24, 24, 'Who made a powerful plea to continue ''separate electorates'' on 27th August 1947?', '[{"id":"A","text":"Somnath Lahiri"},{"id":"B","text":"Pocker Bahadur"},{"id":"C","text":"B.R. Ambedkar"},{"id":"D","text":"Baldev Singh"}]', 0, 'B', 'On 27th August 1947, during the discussions in the Constituent Assembly of India, B. Pocker Bahadur, a representative from Madras, made a strong plea to continue separate electorates for Muslims. He argued that separate electorates were essential to ensure adequate political representation for minorities in independent India.', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:38.794Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (806, 'history-2025-06-21-shift-1', 'q27', 25, 25, 'In the Vijayanagara empire, the amara-nayakas were _.', '[{"id":"A","text":"Tax-Collectors"},{"id":"B","text":"Cultural-Ambassadors"},{"id":"C","text":"Military-Commanders"},{"id":"D","text":"Agriculturists"}]', 0, 'C', 'The amara-nayakas were key military and administrative chiefs in the Vijayanagara Empire, granted territories (amaram) by the king. They collected taxes, retained part for themselves, maintained troops, and funded temples and irrigation. They showed loyalty through annual tribute and court visits, while the king controlled them by occasional transfers. The Delhi Sultanate''s Iqta system likely influenced the system', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.794Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (807, 'history-2025-06-21-shift-1', 'q28', 26, 26, 'Which king among the following is not a part of the Satavahana dynasty?', '[{"id":"A","text":"Svami-Sakasena"},{"id":"B","text":"Sri-Rudradaman"},{"id":"C","text":"Siri-Satakani"},{"id":"D","text":"Siri-Pulumayi"}]', 0, 'B', '• Rudradaman I belonged to the Western Kshatrapä dynasty (Saka ruler), not the Satavahanas.

• Siri-Satakani (Satavahana), Siri-Pulumayi (Satavahana), and Svami-Sakasena (Satavahana) are names associated with or related to Satavahana rulers.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:38.794Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (808, 'history-2025-06-21-shift-1', 'q29', 27, 27, 'According to some traditions, who was Mirabai''s preceptor?', '[{"id":"A","text":"Kabirdas"},{"id":"B","text":"Chaitanya Mahaprabhu"},{"id":"C","text":"Raidas"},{"id":"D","text":"Shankaradeva"}]', 0, 'C', 'Raidas was a poet-saint of the Bhakti movement, a contemporary of Mirabai, and is known for his devotional songs and emphasis on social equality and love for God. Despite the difference in their social status, traditional narratives and some of Mirabai''s own poems suggest a guru-disciple relationship.', NULL, 'null', '[]', '[]', '[23]', 'keyed', '[]', '2026-11-05T20:58:38.794Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (809, 'history-2025-06-21-shift-1', 'q30', 28, 28, 'Identify the correct statements about Baba Guru Nanak from below:

(A) Guru Nanak (1469-1539) was born into a Hindu merchant family in a village called Nankana Sahib.

(B) Guru Nanak was trained to be an accountant and studied Persian.

(C) Guru Nanak advocated a form of saguna bhakti.

(D) Guru Nanak rejected sacrifices, ritual baths, image worship, austerities and the scriptures of both Hindus and Muslims.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (C) and (D) only"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'A', '(A) Correct: Guru Nanak (1469-1539) was born into a Hindu merchant family in the village of Nankana Sahib, now in Pakistan.

(B) Correct: He was trained to be an accountant and also studied Persian, which was the language of administration at the time.

(C) Incorrect: Guru Nanak did not advocate saguna bhakti (worship of a deity with form). He emphasized a formless, nameless God - aligning more with nirguna bhakti.

(D) Correct: Guru Nanak rejected ritual practices such as sacrifices, image worship, ritual baths, and scriptural authority of both Hindu and Muslim texts', NULL, 'null', '[]', '[]', '[24]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (810, 'history-2025-06-21-shift-1', 'q31', 29, 29, 'Which source from 1857 published an illustration with the caption, "The news of the terrible massacre at Cawnpore (Kanpur) produced an outburst of fiery indignation and wild desire for revenge throughout the whole of England"?', '[{"id":"A","text":"London News"},{"id":"B","text":"Justice, Punch"},{"id":"C","text":"The Times of India"},{"id":"D","text":"London Mirror"}]', 0, 'B', 'The illustration with the caption about the Kanpur massacre was published in Punch magazine on 12 September 1857, titled "Justice". This British cartoon reflected the intense anger and desire for revenge in England after the events at Kanpur.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (811, 'history-2025-06-21-shift-1', 'q32', 30, 30, 'The term used by Kabir from Vedantic traditions to define the ''unseen'' is:', '[{"id":"A","text":"Bani"},{"id":"B","text":"Nirakar"},{"id":"C","text":"Shabada"},{"id":"D","text":"Alakh"}]', 0, 'D', 'Kabir described the Ultimate Reality using terms from different religious traditions.

Drawing on Vedantic ideas, he spoke of it as Alakh (the unseen), Nirakar (the formless), Brahman, and Atman. At the same time, he also used Islamic terms such as Allah, Khuda, Hazrat, and Pir, as well as Yogic expressions like shabda (sound) and shunya (emptiness).', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (812, 'history-2025-06-21-shift-1', 'q33', 31, 31, 'Buddha''s teachings have been reconstructed from stories, mainly found in the _.', '[{"id":"A","text":"Brahmanas"},{"id":"B","text":"Sutta Pitaka"},{"id":"C","text":"Therigathas"},{"id":"D","text":"Vinaya Pitaka"}]', 0, 'B', 'The Sutta Pitaka contains the discourses (Suttas or Sutras) delivered by the Buddha and his close disciples. It forms a key part of the Tripitaka (Three Baskets) and serves as the primary source for understanding the Buddha''s ideas on ethical conduct, meditation, and the path to liberation (nirvana).

• Brahmanas are prose texts associated with Vedic rituals and are not related to Buddhism.

- Therigathas, though included in the Sutta Pitaka, consist specifically of verses composed by early Buddhist nuns (Theris).

- Vinaya Pitaka deals with monastic rules and discipline, not with the doctrinal or narrative teachings of the Buddha.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (813, 'history-2025-06-21-shift-1', 'q34', 32, 32, 'Arrange the following events chronologically:

(A) Champaran Movement

(B) Mahatma Gandhi''s visit to Noakhali

(C) Workers'' Movement in Ahmedabad

(D) Peasant Movement in Bardoli', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (C), (B), (D)"},{"id":"C","text":"(A), (C), (D), (B)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', '(A) Champaran Movement - 1917

→ Gandhi''s first major involvement in Indian mass politics focused on indigo farmers in Bihar.

(C) Workers'' Movement in Ahmedabad - 1918

→ Gandhi led a peaceful strike of textile mill workers.

(D) Peasant Movement in Bardoli - 1928

→ Led by Vallabhbhai Patel, supported by Gandhi, against an unjust tax hike.

(B) Mahatma Gandhi''s visit to Noakhali - 1946

→ Gandhi visited Noakhali (now in Bangladesh) to promote peace after communal riots.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (814, 'history-2025-06-21-shift-1', 'q35', 33, 33, 'Which one of the following travelers did not travel to India during the 15th and 16th-century?', '[{"id":"A","text":"Nicolo de Conti"},{"id":"B","text":"Duarte Barbosa"},{"id":"C","text":"Fernao Nuniz"},{"id":"D","text":"Brandon Sanderson"}]', 0, 'D', '• Niccolò de'' Conti - An Italian traveler and merchant who visited India and Southeast Asia in the early 15th century.

• Duarte Barbosa - A Portuguese traveler and writer who lived in India during the early 16th century, working in Cochin.

• Fernão Nuniz - A Portuguese chronicler who visited the Vijayanagara Empire around the 16th century.

• Brandon Sanderson - A modern American author of fantasy and science fiction, born in 1975. He did not live or travel during the 15th or 16th century, making him the correct answer.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:38.795Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (815, 'history-2025-06-21-shift-1', 'q36', 34, 34, 'The ''diwani'' of Bengal was transferred to the East India Company in which year?', '[{"id":"A","text":"1757"},{"id":"B","text":"1739"},{"id":"C","text":"1765"},{"id":"D","text":"1764"}]', 0, 'C', 'After the Battle of Buxar (1764), Mughal Emperor Shah Alam II granted the Diwani rights (revenue collection of Bengal, Bihar, and Orissa) to the East India Company through the Treaty of Allahabad (1765).

This made the Company the chief revenue authority in eastern India, marking the beginning of British political control in the region.', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.796Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (816, 'history-2025-06-21-shift-1', 'q37', 35, 35, 'The Mauryan ruler, Asoka, is mentioned in the inscriptions as:', '[{"id":"A","text":"Rajah"},{"id":"B","text":"Maharajadhiraj"},{"id":"C","text":"Ashok Mahan"},{"id":"D","text":"Devanampiya Piyadassi"}]', 0, 'D', 'The titles by which Ashoka is generally referred to in his inscriptions are Devanampiya and Piyadasi.

• Devanampiya (or Devānampiya) means "Beloved of the Gods."

• Piyadasi (or Priyadarsin) means "He who regards others with kindness" or "Of amiable disposition."

His personal name, Ashoka, is explicitly mentioned only in a few minor rock edicts, most famously the Maski Edict (in Karnataka) and the Gujarra Edict (in Madhya Pradesh), which helped historians conclusively identify the king using the popular titles Devanampiya Piyadasi with the historical Emperor Ashoka.', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:38.796Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (817, 'history-2025-06-21-shift-1', 'q38', 36, 36, 'Which one of the following is not related to agrarian terminology during the Mughal period?', '[{"id":"A","text":"Rabi"},{"id":"B","text":"Do-Fasla"},{"id":"C","text":"Halalkhoran"},{"id":"D","text":"Jins-i-Kamil"}]', 0, 'C', '- Rabi: Refers to the spring harvest or winter-sown crops, important in Mughal revenue administration.

• Do-Fasla: Means "two crops," indicating land yielding two harvests a year, crucial for revenue assessment.

Jins-i-Kamil: Refers to superior or cash crops (like sugarcane, cotton, oilseeds) assessed at higher revenue rates.

• Halalkhoran: Denotes a social group or caste of scavengers, not related to agriculture.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:38.796Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (818, 'history-2025-06-21-shift-1', 'q39', 37, 37, 'Identify the ''minor-rock edict'' sites among the following:', '[{"id":"A","text":"Siddapur, Brahmagiri, Udegolam"},{"id":"B","text":"Rajula Mandagiri, Jatinga Rameshwar, Sopara"},{"id":"C","text":"Girnar, Sanchi, Sannati"},{"id":"D","text":"Gujarra, Rumindei, Meerut"}]', 0, 'A', '• Siddapur, Brahmagiri, Udegolam: All three are well-known Minor Rock Edict sites in southern India (Karnataka).

• Rajula Mandagiri, Jatinga Rameshwar, Sopara: Rajula Mandagiri and Jatinga Rameshwar are Minor Rock Edict sites, but Sopara is a Major Rock Edict site.

• Girnar, Sanchi, Sannati: Girnar is a Major Rock Edict site, Sanchi has Minor Pillar Edicts, and Sannati has Major Rock Edicts.

• Gujjarra, Rumindei, Meerut: Gujjarra has a pillar inscriptions, Rumindei has a Minor Pillar Edict, and Meerut has a Major Pillar Edict.', NULL, 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:38.797Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (819, 'history-2025-06-21-shift-1', 'q40', 38, 38, 'Identify the correct statements regarding the Vijayanagara Empire:

(A) According to tradition and epigraphic evidence, two brothers, Harihara and Harihara II, founded the Vijayanagara Empire in 1336.

(B) Krishnadeva Raya''s rule was characterised by expansion and consolidation.

(C) Krishnadeva Raya founded a suburban township near Vijayanagara called Nagalapuram after his mother.

(D) In 1565, Rama Raya, the chief minister of Vijayanagara, led the army into battle at Rakshasi-Tangadi.', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(A), (B), (C) and (D)"},{"id":"D","text":"(B), (C) and (D) only"}]', 0, 'D', '• (A) Incorrect: The founders were Harihara I and Bukka Raya I in 1336, not Harihara II.

• (B) Correct: Krishnadeva Raya expanded and consolidated the empire during his reign.

• (C) Correct: Krishnadeva Raya founded Nagalapuram, a suburban township named after his mother.

• (D) Correct: Rama Raya, the chief minister, led the army at the Battle of Rakshasi-Tangadi (1565), which resulted in Vijayanagara''s defeat.', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:38.797Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (820, 'history-2025-06-21-shift-1', 'q43', 39, 39, '4. Benaras', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'In Satara district, Maharashtra, an independent government called the Prati Sarkar was established during the Quit India Movement. It was one of the longest-lasting parallel administrations, carrying out local governance, tax collection, and justice while challenging British authority.', 'p805d26a40738', 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:38.798Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (821, 'history-2025-06-21-shift-1', 'q45', 40, 40, '4. Vividh Vritti', '[{"id":"A","text":"Harijan"},{"id":"B","text":"Bunch of Old Letters"},{"id":"C","text":"Kesari"},{"id":"D","text":"Vividh Vritti"}]', 0, 'A', 'Harijan was a weekly journal started by Mahatma Gandhi in 1933 to campaign against untouchability and promote social equality, aiming to raise awareness about the rights and dignity of the marginalized sections of society.', 'p49d92b7c8324', 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:38.798Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (822, 'history-2025-06-21-shift-1', 'q46', 41, 41, '4. Mulk-Shahi', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', '• Manzil-Abadi is the first book (volume) of the Ain-i-Akbari, a detailed administrative document written by Abul Fazl during the reign of Emperor Akbar.

• It specifically deals with the Imperial Household and its maintenance.

• Sipah-Abadi is the second book, which deals with the civil and military service

• Mulk-Abadi is the third book, which deals with the imperial administration and fiscal (revenue) aspects of the empire.', 'pc4bf0ee48a97', 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:38.798Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (823, 'history-2025-06-21-shift-1', 'q47', 42, 42, '4. Five', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The Ain-i-Akbari is a composition of five books (Daftars).

• It is the third volume of Abul Fazl''s larger historical work, the Akbarnama.

• The first three books-Manzil-Abadi, Sipah-Abadi, and Mulk-Abadi-focus on administration, covering the imperial household, civil and military services, and revenue and governance.

- The last two books deal with social, religious, and philosophical traditions, along with the sayings of Emperor Akbar.', 'p43e26baccda6', 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:38.798Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (824, 'history-2025-06-21-shift-1', 'q49', 43, 43, '4. Mansabdari-abadi', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'A', 'The Akbarnama, written by Abu''l Fazl, is divided into three volumes:

• Book 1: History of Akbar''s ancestors (Timurids, Babur, Humayun)

• Book 2: Detailed history of Akbar''s reign

• Book 3: Ain-i-Akbari, covering administration, household, army, and revenue systems', 'pf7058baa1752', 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:38.799Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (825, 'history-2025-06-21-shift-1', 'q50', 44, 44, '4. 1594', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The Akbarnama, of which the Ain-i-Akbari is the third volume, was commissioned by Akbar and written by Abul Fazl. The Ain-i-Akbari was completed around the 42nd regnal year of Akbar, which corresponds to the year 1598 in the Gregorian calendar.', 'pe67efe2a0d78', 'null', '[]', '[]', '[50]', 'keyed', '[]', '2026-11-05T20:58:38.799Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (826, 'mathematics-2025-06-02-shift-1', 'q01', 1, 1, '$$ \int\frac{e^{2x}-e^{-2x}}{e^{2x}+e^{-2x}}dx $$

is equal to:', '[{"id":"A","text":"$ \\frac{1}{2}\\log|e^{2x}-e^{-2x}|+C $, where $ C $ is an arbitrary constant."},{"id":"B","text":"$ \\log|e^{2x}-e^{-2x}|+C $, where C is an arbitrary constant."},{"id":"C","text":"$ \\frac{1}{2}\\log|e^{2x}+e^{-2x}|+C $, where $ C $ is an arbitrary constant."},{"id":"D","text":"$ \\log|e^{2x} + e^{-2x}| + C $, where $ C $ is an arbitrary constant."}]', 0, 'C', '1. Choose a substitution:

Let u be the denominator:

$$ u=e^{2x}+e^{-2x} $$

2. Find the differential du:

Take the derivative of u with respect to x :

$$ \frac{du}{dx}=\frac{d}{dx}(e^{2x})+\frac{d}{dx}(e^{-2x}) $$

Using the chain rule, $ \frac{d}{dx}(e^{kx}) = ke^{kx} $:

$$ \frac{du}{dx}=(2e^{2x})+(-2e^{-2x})=2e^{2x}-2e^{-2x}=2(e^{2x}-e^{-2x}) $$

Therefore, the differential $ du $ is:

$$ du=2(e^{2x}-e^{-2x})dx $$

This means the numerator, $ (e^{2x} - e^{-2x})dx $, is equal to $ \frac{1}{2}du $:

$$ (e^{2x}-e^{-2x})dx=\frac{1}{2}du $$

3. Substitute u and du into the integral:

$$ I=\int\frac{1}{u}(\frac{1}{2}du)=\frac{1}{2}\int\frac{1}{u}du $$

4. Integrate with respect to u:

The integral of $ \frac{1}{u} $ is $ \log|u| $:

$$ I=\frac{1}{2}\log|u|+C $$

where C is the arbitrary constant of integration.

5. Substitute back for x :

Replace u with $ e^{2x} + e^{-2x} $:

$$ I=\frac{1}{2}\log|e^{2x}+e^{-2x}|+C $$

Since $ e^{2x} + e^{-2x} $ is always positive, the absolute value is technically not required, but including it is mathematically correct for the general form $ \int \frac{1}{u}du = $

$$ I=\frac{1}{2}\log(e^{2x}+e^{-2x})+C $$

[The correct optionis3.]', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:38.800Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (827, 'mathematics-2025-06-02-shift-1', 'q02', 2, 2, 'Linear inequalities corresponding to the shaded feasible region OABCO in the given figure are', '[{"id":"A","text":"$ 4x + 3y \\leq 12 $, $ 3x + 4y \\leq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"},{"id":"B","text":"$ 4x + 3y \\geq 12 $, $ 3x + 4y \\geq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"},{"id":"C","text":"$ 4x + 3y \\leq 12 $, $ 3x + 4y \\geq 12 $, $ x, \\geq 0, y \\geq 0 $"},{"id":"D","text":"$ 4x + 3y \\geq 12 $, $ 3x + 4y \\leq 12 $, $ x \\geq 0 $, $ y \\geq 0 $"}]', 0, 'A', '1. Axes (Non-Negativity)

The region is in the first quadrant:

$$ x\ge0,\quad y\ge0 $$

2. Line 1: Through D(0, 4) and A(3, 0)

Intercepts: x-intercept a = 3, y-intercept b = 4.

Equation (Intercept Form): $ \frac{x}{3} + \frac{y}{4} = 1 \Longrightarrow 4x + 3y = 12 $

Inequality: Since the region includes the origin (0,0), the constraint is: $ 4x + 3y \leq 12 $

3. Line 2: Through C(0, 3) and E(4, 0)

Intercepts: x-intercept a = 4, y-intercept b = 3.

Equation (Intercept Form): $ \frac{x}{4} + \frac{y}{3} = 1 \Longrightarrow 3x + 4y = 12 $

Inequality: Since the region includes the origin (0,0), the constraint is: $ 3x + 4y \leq 12 $
Complete System of Constraints

$$ x\geq0,\quad y\geq0,\quad4x+3y\leq12,\quad3x+4y\leq12 $$

[The correct option is 1.]', NULL, 'null', '[]', '[{"id":"q02-figure-1","kind":"figure","path":"/local-papers/assets/mathematics-2025-06-02-shift-1/q02-figure-1.jpg","page":2,"alt":"Figure for question 2"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:38.800Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (828, 'mathematics-2025-06-02-shift-1', 'q03', 3, 3, 'Match List-I with List-II', '[{"id":"A","text":"\\ (\\mathrm{A})-(\\mathrm{I}),(\\mathrm{B})-(\\mathrm{IV}),(\\mathrm{C})-(\\mathrm{II}),(\\mathrm{D})-(\\mathrm{III})"},{"id":"B","text":"\\ (\\mathbf{A})-(\\mathbf{II}),(\\mathbf{B})-(\\mathbf{I}),(\\mathbf{C})-(\\mathbf{III}),(\\mathbf{D})-(\\mathbf{IV})"},{"id":"C","text":"(A) - $ \\mathrm{(III)} $, (B) - $ \\mathrm{(IV)} $, (C) - $ \\mathrm{(II)} $, (D) - $ \\mathrm{(I)} $"},{"id":"D","text":"(A) - (IV), (B) - (I), (C) - (II), (D) - (III)"}]', 0, 'C', 'The order of a differential equation is the order of the highest derivative present in the equation.

The degree of a differential equation is the power of the highest-order derivative after the equation has been rationalized (i.e., cleared of any fractional powers of the derivatives).

A. The degree of differential equation $ \frac{d^{3}y}{dx^{3}} = e^{\frac{dy}{dx}} $ is not defined (due to $ e^{\frac{dy}{dx}} $ term) $ \rightarrow $ (III) not defined

B. The order of differential equation $ \left(\frac{dy}{dx}\right)^{2}+\frac{d^{3}y}{dx^{3}}=0 $ is $ 3\rightarrow(IV) $ 3

C. The sum of order and degree of differential equation $ \frac{d}{dx}\left(\frac{d^2y}{dx^2}\right) + \left(\frac{dy}{dx}\right)^5 = x $ is $ (3 + 1 = 4) \to (\mathrm{II}) $ 4

D. The number of arbitrary constants in the general solution of a differential equation of order 2 is $ 2 \to (\mathrm{I}) $

The final match is: (A) - (III), (B) - (IV), (C) - (II), (D) - (I)

[The correct option is 3.]', NULL, 'null', '[]', '[{"id":"q03-table-1","kind":"table","path":"/local-papers/assets/mathematics-2025-06-02-shift-1/q03-table-1.jpg","page":3,"alt":"Table for question 3"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (829, 'mathematics-2025-06-02-shift-1', 'q04', 4, 4, '$$ \mathrm{If}\begin{bmatrix}3&1\\ 2&1\end{bmatrix}A\begin{bmatrix}2&1\\ 1&1\end{bmatrix}=\begin{bmatrix}1&1\\ 0&1\end{bmatrix}, $$

then matrix ''A'' is

$$ \begin{bmatrix}1&1\\ 0&0\end{bmatrix} $$

$$ \begin{bmatrix}{{{-1}}}&{{{1}}} \\{{{3}}}&{{{-4}}}\end{bmatrix} $$

$$ \begin{bmatrix}1&-1\\ -3&4\end{bmatrix} $$

$$ 4.\begin{bmatrix}1&0\\ 0&1\end{bmatrix} $$', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'C', 'The given equation is $BAC = D$. where:

$$ \boldsymbol{B}=\begin{bmatrix}3&1\\ 2&1\end{bmatrix},\quad\boldsymbol{C}=\begin{bmatrix}2&1\\ 1&1\end{bmatrix},\quad\boldsymbol{D}=\begin{bmatrix}1&1\\ 0&1\end{bmatrix} $$

To solve for A, we pre-multiply by $ B^{-1} $ and post-multiply by $ C^{-1} $:

$$ \boldsymbol{A}=\boldsymbol{B}^{-1}\boldsymbol{D}\boldsymbol{C}^{-1} $$

1. Calculate Inverses

For a $ 2 \times 2 $ matrix $ M = \begin{bmatrix} a & b \\ c & d \end{bmatrix} $, $ M^{-1} = \frac{1}{|M|} \begin{bmatrix} d & -b \\ -c & a \end{bmatrix} $.

Inverse of $B$

$$ \left|B\right|=3(1)-1(2)=1. $$

$$ \boldsymbol{B}^{-1}=\frac{1}{1}\begin{bmatrix}1&-1\\ -2&3\end{bmatrix}=\begin{bmatrix}1&-1\\ -2&3\end{bmatrix} $$

Inverse of C

$$ |C|=2(1)-1(1)=1. $$

$$ C^{-1}=\frac{1}{1}\begin{bmatrix}1&-1\\ -1&2\end{bmatrix}=\begin{bmatrix}1&-1\\ -1&2\end{bmatrix} $$

$$ 2.Compute\boldsymbol{B}^{-1}\boldsymbol{D} $$

$$ \boldsymbol{B}^{-1}\boldsymbol{D}=\begin{bmatrix}{{{1}}}&{{{-1}}} \\{{{-2}}}&{{{3}}}\end{bmatrix}\begin{bmatrix}{{{1}}}&{{{1}}} \\{{{0}}}&{{{1}}}\end{bmatrix}=\begin{bmatrix}{{{1(1)+(-1)(0)}}}&{{{1(1)+(-1)(1)}}} \\{{{-2(1)+3(0)}}}&{{{-2(1)+3(1)}}}\end{bmatrix}=\begin{bmatrix}{{{1}}}&{{{0}}} \\{{{-2}}}&{{{1}}}\end{bmatrix} $$

$$ 3.Compute A=(B^{-1}D)C^{-1} $$

$$ \boldsymbol{A}=\begin{bmatrix}1&0\\ -2&1\end{bmatrix}\begin{bmatrix}1&-1\\ -1&2\end{bmatrix}=\begin{bmatrix}1(1)+0(-1)&1(-1)+0(2)\\ -2(1)+1(-1)&-2(-1)+1(2)\end{bmatrix} $$

$$ \boldsymbol{A}=\begin{bmatrix}1&-1\\ -3&4\end{bmatrix} $$

[The correct option is 3.]', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (830, 'mathematics-2025-06-02-shift-1', 'q05', 5, 5, 'For the function $ f(x) = -2x^3 + 3x^2 + 36x - 10 $, which of the following is/are true?

(A) f is increasing in $ (-\infty, -2) $

(B) f is increasing in $ (-2,3) $

(C) f is decreasing in $ (-\infty, -2) $

(D) f is decreasing in $ (3, \infty) $', '[{"id":"A","text":"(B) and (D) only"},{"id":"B","text":"(B), (C) and (D) only"},{"id":"C","text":"(A) and (D) only"},{"id":"D","text":"(B) only"}]', 0, 'B', 'Analysis of Monotonicity for $ f(x) = -2x^{3} + 3x^{2} + 36x - 10 $

$$ f(x)=-2x^{3}+3x^{2}+36x-10 $$

1. Derivative and Critical Points:

$$ f^{\prime}(x)=-6x^{2}+6x+36 $$

$$ \operatorname{Set}f^{\prime}(x)=0: $$

$$ -6x^{2}+6x+36=0 $$

$$ -6(x^{2}-x-6)=0\implies-6(x-3)(x+2)=0 $$

$$ \mathrm{C r i t i c a l~p o i n t s~a r e~}\mathbf{x}=-\mathbf{2}\mathrm{~a n d~}\mathbf{x}=\mathbf{3}. $$

$$ 2.\operatorname{Check\ Intervals}\left(f^{\prime}(x)\operatorname{sign}\right): $$

$$ \mathrm{I n t e r v a l}\left(-\infty,-2\right)\colon f^{\prime}(-3)=-6(\left(-3\right)^{2}-(-3)-6)=-6(9+3-6)=-36 0\implies\mathrm{I n c r e a s i n g}\mathrm{\boldmath~(B~i s~T R U E)} $$

$$ \mathrm{I n t e r v a l}\;(3,\infty)\colon f^{\prime}(4)=-6(4^{2}-4-6)=-6(16-10)=-36<0\implies\mathrm{D e c r e a s i n g}\;(\mathbf{D}\;\mathrm{i s}\;\mathrm{T R U E}) $$

3. Conclusion:

Statements (B), (C), and (D) are TRUE.

[The correct option is 2.]', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (831, 'mathematics-2025-06-02-shift-1', 'q06', 6, 6, '$$ If\;y=\frac{1}{\sqrt[3]{1-x^{3}}},\;then\;\frac{dy}{dx}is equal to: $$', '[{"id":"A","text":"x(1-x^{3})^{-\\frac{4}{3}}"},{"id":"B","text":"x^{2}(1-x^{3})^{-\\frac{4}{3}}"},{"id":"C","text":"\\left(1-x^{3}\\right)^{-\\frac{4}{3}}"},{"id":"D","text":"x^{2}(1-x^{3})^{-\\frac{4}{3}}"}]', 0, 'B', '$$ y=\frac{1}{\sqrt[3]{1-x^{3}}} $$

1. Rewrite y using exponent notation:

$$ y=\left(1-x^{3}\right)^{-\frac{1}{3}} $$

2. Differentiate $ \frac{dy}{dx} $ using the Chain Rule $ \frac{d}{dx}[u^n] = nu^{n-1} \cdot \frac{du}{dx} $:

$$ Let u=(1-x^{3}).~Then\frac{du}{dx}=-3x^{2}. $$

$$ \frac{dy}{dx}=-\frac{1}{3}(1-x^{3})^{-\frac{1}{3}-1}\cdot\frac{d}{dx}(1-x^{3}) $$

$$ \frac{dy}{dx}=-\frac{1}{3}(1-x^{3})^{-\frac{4}{3}}\cdot(-3x^{2}) $$

3. Simplify the expression:

$$ \frac{dy}{dx}=\left(-\frac{1}{3}\right)(-3x^{2})(1-x^{3})^{-\frac{4}{3}} $$

$$ \frac{dy}{dx}=\mathbf{x}^{2}(\mathbf{1}-\mathbf{x}^{3})^{-\frac{4}{3}} $$

[The correct option is 2.]', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (832, 'mathematics-2025-06-02-shift-1', 'q07', 7, 7, 'If x is real, the minimum value of $ x^{2}-8x+20 $ is:', '[{"id":"A","text":"4"},{"id":"B","text":"2"},{"id":"C","text":"0"},{"id":"D","text":"1"}]', 0, 'A', 'Function: $ f(x) = x^{2} - 8x + 20 $

1. First Derivative and Critical Point:

$ f''(x) = 2x - 8 $

$ f''(x) = 0 $

$ \Longrightarrow 2x = 8 $

$ \Longrightarrow x = 4 $ (Critical Point)

2. Second Derivative Test (Confirmation):

$$ f^{\prime\prime}(x)=\frac{d}{dx}\left(2x-8\right)=\mathbf{2} $$

Since $ f''''(4) = 2 > 0 $ (positive), the function has a Local Minimum at x = 4.
3. Minimum Value:

$ f(4)=(4)^{2}-8(4)+20=16-32+20=4 $

The minimum value is 4.

[The correct option is 1.]', NULL, 'null', '[]', '[]', '[7]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (833, 'mathematics-2025-06-02-shift-1', 'q08', 8, 8, 'If A is a square matrix of order 3 and |A|=5, then the value of |-AA^{+}| is:', '[{"id":"A","text":"25"},{"id":"B","text":"25"},{"id":"C","text":"5"},{"id":"D","text":"5"}]', 0, 'B', 'Given: |A| = 5, Order n = 3.

Required: |-AA^{T}|

=(-1)^{3}|AA^{T}|

= -1 \cdot |A||A^{T}|

=-1 \cdot (5)(5)

=-25

Answer: -25', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:38.801Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
