Computer Science', NULL, 'null', '[]', '[{"id":"q15-table-1","kind":"table","path":"/local-papers/assets/computer-science-2024-07-19-shift-1/q15-table-1.jpg","page":24,"alt":"Table for question 15"}]', '[24]', 'keyed', '[]', '2026-11-05T20:58:44.376Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1314, 'computer-science-2024-07-19-shift-1', 'q16', 16, 16, 'What is pickling?', '[{"id":"A","text":"It is used to deSERIALIZE objects i.e. converting the byte stream to object hierarchy"},{"id":"B","text":"It is used to initialize objects i.e. to convert python object hierarchy to byte stream"},{"id":"C","text":"It is used to move the file pointer to specific location"},{"id":"D","text":"It is used in exception handling"}]', 0, 'A', 'The correct answer is It_is_used_to_serialize_objects_i.e._to_convert_python object_hierarchy_to_byte_stream.
Key Points

• Pickling is the process of converting a Python object hierarchy into a byte stream.

- This byte stream can be stored in a file or transmitted over a network to be reconstructed later.

• Pickling is useful for saving program state, sharing data between different Python programs, or persisting data between program runs.

- Python provides the pickle module to facilitate the pickling process.
Additional Information

• Pickled data can be unpickled using the pickle.load() function to restore the original Python object hierarchy.

• Pickling is not secure against erroneous or maliciously constructed data. Never unpickle data received from an untrusted or unauthenticated source.

• The pickle module supports both binary and text (ASCII) serialization formats.

- Other serialization formats like JSON, XML, and Protocol Buffers are also available, but pickle is specific to Python and can handle more complex Python-specific objects.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:44.376Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1315, 'computer-science-2024-07-19-shift-1', 'q17', 17, 17, 'Consider the following code and specify the correct order of the statements to be written

(A) f.write("CUET EXAMINATION")

