(C) print("Data is Written Successfully")

(D) f.close()', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(B), (A), (C), (D)"},{"id":"C","text":"(B), (D), (C), (A)"},{"id":"D","text":"(B), (D), (A), (C)"}]', 0, 'B', 'The correct answer is Option_2.

