INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1316, 'computer-science-2024-07-19-shift-1', 'q18', 18, 18, 'Which method from below will take a file pointer to nth character with respect to r position?', '[{"id":"A","text":"fp.seek(r)"},{"id":"B","text":"fp.seek(n)"},{"id":"C","text":"fp.seek(n,r)"},{"id":"D","text":"seek(n,r).fp"}]', 0, 'C', 'The correct answer is fp.seek(n,-r).
Key Points

• The fp.seek(n, r) method in Python is used to change the file pointer position.

• It takes two arguments: $n$ (the number of bytes to move) and $r$ (the reference position).

- The reference position can be one of three values:

• e: Start of the file.

• 1: Current position.

2: End of the file.

- For example, fp.seek(10, 0) moves the file pointer to the 10th byte from the start of the file.
Additional Information

• The fp.seek() method is part of the file object in Python.

- It is commonly used in file handling for reading and writing operations.
- Using fp.seek(), you can easily navigate to different positions in a file, which is useful for modifying specific parts of a file.
- Example source code:
Open a file in read mode
with open(''example.txt'', ''r'') as fp:
Move the file pointer to the 5th byte from the start
fp.seek(5, 0)
Read the content from the current file pointer position
content = fp.read()
print(content)', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1317, 'computer-science-2024-07-19-shift-1', 'q20', 19, 19, 'Stack works on the principle of _.', '[{"id":"A","text":"Mid Element First"},{"id":"B","text":"First In First Out"},{"id":"C","text":"Last In First Out"},{"id":"D","text":"Last In Last Out"}]', 0, 'C', 'The correct answer is Last In First Out
Key Points

- A stack is a data structure that works on the principle of Last In First Out (LIFO).

- In this structure, the last element added to the stack is the first one to be removed.

- This principle is analogous to a stack of plates: you add a plate to the top of the stack, and you also remove the topmost plate first.

- Stacks are used in various applications, including function call management in programming, undo mechanisms in text editors, and parsing expressions in compilers.

- Common operations associated with stacks are push (adding an element) and pop (removing an element).

- Other stack operations include peek (viewing the top element without removing it) and is Empty (checking if the stack is empty).

• Stacks are implemented using arrays or linked lists.

- They provide an efficient way to manage data, with a time complexity of $ O(1) $ for both push and pop operations.

• Some common examples of stack usage in computer science include the evaluation of arithmetic expressions, reversing strings, and depth-first search algorithms.

- The concept of stack is fundamental in computer science and is crucial for understanding other advanced data structures and algorithms.', NULL, 'null', '[]', '[]', '[31]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1318, 'computer-science-2024-07-19-shift-1', 'q21', 20, 20, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(III), (B)-(IV), (C)-(II), (D)-(I)"},{"id":"B","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"},{"id":"C","text":"$$ (A)\\mathrm{-}(I),(B)\\mathrm{-}(II),(C)\\mathrm{-}(IV),(D)\\mathrm{-}(III) $$"},{"id":"D","text":"$$ (A)\\mathrm{-(II),(B)\\;-}(I),(C)\\;-\\left(III\\right),(D)\\;-\\left(IV\\right) $$"}]', 0, 'A', 'The correct answer is Option_1.
Key Points

• (A) Prefix - (III) In this the operator is placed before the operands.

- This notation is also known as Polish Notation. For example, the expression "+ 34" is equivalent to "3 + 4".

• (B) Postfix - (IV) In this the operator is placed after the operands.

- This notation is also known as Reverse Polish Notation. For example, the expression "3 4 +" is equivalent to "3 + 4".

• (C) Queue - (II) In this the element entered first will be removed first.

- This is the First-In-First-Out (FIFO) method. Think of it like a queue of people; the person who gets in line first gets served first.

• (D) Stack - (I) In this the element entered first will be removed last.

- This is the Last-In-First-Out (LIFO) method. Think of it like a stack of plates; the plate you put on top is the first one you take off.
Additional Information

- The concepts of Prefix and Postfix notations are heavily used in stack-based algorithms and are crucial for the functioning of certain types of compilers and calculators.

- Queues are widely used in various applications like scheduling processes in operating systems, handling requests on a web server, etc.

- Stacks are used in numerous algorithms, including depth-first search in graph theory, syntax parsing in compilers, and evaluating expressions in calculators.', NULL, 'null', '[]', '[{"id":"q21-table-1","kind":"table","path":"/local-papers/assets/computer-science-2024-07-19-shift-1/q21-table-1.jpg","page":33,"alt":"Table for question 21"}]', '[33]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1319, 'computer-science-2024-07-19-shift-1', 'q22', 21, 21, 'What will be the sequence of elements removed from the stack after performing the following operations

PUSH(10)

PUSH(20)

POP()

POP()

PUSH(30)

PUSH(40)

POP()

POP()

(A) 10

(B) 20

(C) 30

(D) 40
Choose the correct sequence from the options given below:', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(B), (A), (D), (C)"},{"id":"C","text":"(A), (B), (D), (C)"},{"id":"D","text":"(B), (A), (C), (D)"}]', 0, 'C', 'The correct answer is Option_3
Key Points

- The sequence of operations on the stack is as follows:

The sequence of operations on the stack is

• PUSH(10): Stack = [10]

• PUSH(20): Stack = [10, 20]

• POP(): Removes 20, Stack = [10]

• POP(): Removes 10, Stack = []

• PUSH(30): Stack = [30]

• PUSH(40): Stack = [30, 40]

• POP(): Removes 40, Stack = [30]

POP(): Removes 30, Stack = []

- Based on the above operations, the sequence of elements removed from the stack is 20, 10, 40, 30.

• Therefore, the correct sequence as per the given options is Option 1: (A), (B), (D), (C).
Additional Information

- Stack is a Last-In-First-Out (LIFO) data structure, meaning the last element pushed onto the stack is the first one to be popped off.

- Push operation adds an element to the top of the stack.

• Pop operation removes the top element from the stack.

• Understanding stack operations is crucial for various algorithms and applications in computer science.', NULL, 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1320, 'computer-science-2024-07-19-shift-1', 'q23', 22, 22, 'In Python, _module need to be imported for implementing Double Ended Queue.', '[{"id":"A","text":"counter"},{"id":"B","text":"collections"},{"id":"C","text":"random"},{"id":"D","text":"numpy"}]', 0, 'B', 'The correct answer is collections.
Key Points

- In Python, the collections module provides a Double Ended Queue (deque) which is a generalization of stacks and queues (the name is pronounced "deck" and is short for "double-ended queue").

- The collections.deque class supports thread-safe, memory efficient appends and pops from either side of the deque with approximately the same O(1) performance in either direction.

- Deques are a generalization of stacks and queues (the name is pronounced "deck" and is short for "double-ended queue").

- It provides a more efficient way to handle a collection of items in which you can add or remove elements from both ends efficiently.
Additional Information

• The collections module was introduced in Python 2.4.

- Other useful data types provided by the collections module include namedtuple(), Counter, OrderedDict, defaultdict, and ChainMap.

• Here is an example of how to use the deque from the collections module:

Importing deque from collections module
from collections import deque
Creating a deque
d = deque()
Adding elements to the deque
d.append(1)
d.append(2)
d.appendleft(0)
Removing elements from the deque
d.pop()
d.popleft()
Printing the deque
print(d) # Output: deque([1])', NULL, 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1321, 'computer-science-2024-07-19-shift-1', 'q24', 23, 23, 'What will be the position of front and rear after execution of the following statements, the Queue already had the given elements in FIFO order

50 $ \rightarrow $ 90 $ \rightarrow $ 7 $ \rightarrow $ 21 $ \rightarrow $ 73 $ \rightarrow $ 77

↑

F

R

dequeue()





enqueue(100)

dequeue()', '[{"id":"A","text":"Front 50, Rear 77"},{"id":"B","text":"Front 100. Rear 100"},{"id":"C","text":"Front 77. Rear 100"},{"id":"D","text":"Front 73, Rear 77"}]', 0, 'A', 'The correct answer is Front 50, Rear 77.
Key Points

• We start with the initial queue: $ 50 \rightarrow 90 \rightarrow 7 \rightarrow 21 \rightarrow 73 \rightarrow 77 $, with Front at 50 and Rear at 77.

• Each dequeue() operation removes the front element from the queue.

Let''s go through each operation step by step:

• First dequeue(): Removes 50. New queue: 90 → 7 → 21 → 73 → 77

• Second dequeue(): Removes 90. New queue: 7 → 21 → 73 → 77

• Third dequeue(): Removes 7. New queue: 21 → 73 → 77

• Fourth dequeue(): Removes 21. New queue: 73 → 77

• Fifth dequeue(): Removes 73. New queue: 77

- After five dequeue() operations, the only element left is 77, which is both the Front and Rear.

• Next, we perform an enqueue(100) operation, adding 100 to the rear of the queue. New queue: 77 → 100

• Finally, we perform another dequeue() operation, removing 77. The new queue is: 100

• Now, the Front and Rear both point to 100.
Additional Information

- Queue operations follow the FIFO (First In, First Out) principle.

- Enqueue operations add elements to the rear of the queue.

- Dequeue operations remove elements from the front of the queue.

- After all the given operations, the queue only has one element, which is 100, making it both the Front and Rear of the queue.', NULL, 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1322, 'computer-science-2024-07-19-shift-1', 'q25', 24, 24, 'data type is used to implement Queue data structure in Python.', '[{"id":"A","text":"Sets"},{"id":"B","text":"Dictionary"},{"id":"C","text":"Tuple"},{"id":"D","text":"List"}]', 0, 'D', 'The correct answer is List.
Key Points

- A List is a data type in Python that is used to implement the Queue data structure.

- Lists in Python are ordered collections of items which can be changed (mutable).

- Queues follow the First-In-First-Out (FIFO) principle. The first element added to the queue will be the first one to be removed.

- Python''s list methods such as append() for adding elements to the end and pop(∅) for removing elements from the beginning make it suitable for implementing a queue.
Additional Information

- Lists are versatile and can store elements of different data types.

- Python also provides a built-in module named collections.deque which offers an optimized way to implement queues.

Example of Queue Implementation using List in Python:

Queue implementation using list
queue = []
Adding elements to the queue
queue.append(''a'')
queue.append(''b'')
queue.append(''c'')

print("Initial queue")
print(queue)
Removing elements from the queue
print("\nElements dequeued from queue")
print(queue.pop(0))
print(queue.pop(0))
print(queue.pop(0))
print("\nQueue after removing elements")
print(queue)', NULL, 'null', '[]', '[]', '[41]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1323, 'computer-science-2024-07-19-shift-1', 'q26', 25, 25, 'Choose the statements that are correct.

(A) For Binary Search, all the elements have to be sorted.

(B) For Linear Search, all the elements have to be sorted.

(C) Linear Search takes less time for searching in worst case than binary search''s worst case.

(D) Linear Search always gives the fast result whether elements are sorted or not.', '[{"id":"A","text":"(A) only"},{"id":"B","text":"(A) and (C) only"},{"id":"C","text":"(B) and (C) only"},{"id":"D","text":"(A), (B) and (D) only"}]', 0, 'A', 'The correct answer is Option_1.
Key Points

• (A) For Binary Search, all the elements have to be sorted.

- Binary Search is a searching algorithm that works on a sorted array. It divides the array into two halves and eliminates one half of the array in each step, making the search process more efficient.
Additional Information

• (B) For Linear Search, all the elements do not have to be sorted.

- Linear Search is a simple searching algorithm that checks each element in the list sequentially until the desired element is found or the list ends. The elements do not need to be sorted.

- (C) Linear Search takes more time for searching in the worst case than binary search''s worst case.

- In the worst case, Linear Search has a time complexity of $ O(n) $, whereas Binary Search has a time complexity of $ O(\log n) $, making Binary Search more efficient for larger datasets.

• (D) Linear Search does not always give fast results whether elements are sorted or not.

- Linear Search can be slow for large lists as it checks each element sequentially. Sorting does not affect the performance of Linear Search.', NULL, 'null', '[]', '[]', '[43]', 'keyed', '[]', '2026-11-05T20:58:44.377Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1324, 'computer-science-2024-07-19-shift-1', 'q27', 26, 26, 'Arrange the following in the ascending order of their time complexity.

(A) Worst Case of Linear Search

(B) Best Case of Binary Search

(C) Worst Case of Binary Search

(D) Worst Case of Bubble Sort
Choose the correct sequence from the options given below:', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(B), (D), (A), (C)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(B), (C), (A), (D)"}]', 0, 'C', 'The correct answer is Option_3
Key Points

- To arrange the given cases in ascending order of their time complexity, we need to understand their individual time complexities first:

(A) Worst Case of Linear Search: The time complexity is $ O(n) $, where n is the number of elements in the array.

• (B) Best Case of Binary Search: The time complexity is $ O(1) $, when the element is found at the mid position in the first check.

• (C) Worst Case of Binary Search: The time complexity is O( $ \log n $), which occurs when the algorithm has to divide the array until it finds the target element.

• (D) Worst Case of Bubble Sort: The time complexity is $ O(n^{2}) $, where n is the number of elements in the array.

• Based on the above time complexities, we arrange them in ascending order:

(B) Best Case of Binary Search: O(1)

(A) Worst Case of Linear Search: O(n)

• (C) Worst Case of Binary Search: O( $ \log n $)

• (D) Worst Case of Bubble Sort: O(n^2)', NULL, 'null', '[]', '[]', '[45]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1325, 'computer-science-2024-07-19-shift-1', 'q28', 27, 27, 'How many minimum number of comparison(s) can be required to search an element from ''n'' elements, in case of Linear Search?', '[{"id":"A","text":"1"},{"id":"B","text":"n - 1"},{"id":"C","text":"n"},{"id":"D","text":"n + 1"}]', 0, 'A', 'The correct answer is $ \underline{1} $.
Key Points

- Linear Search is a simple search algorithm that checks every element in the list sequentially until the desired element is found or the list ends.

- The minimum number of comparisons required to find an element in a list of ''n'' elements using Linear Search is 1 if the element to be searched is at the first position.

• In the worst case, the element is not found or is the last element, requiring ''n'' comparisons.

- Linear Search does not require the data to be sorted.

- This algorithm is best suited for small datasets or when the list is unsorted.
Additional Information

- Time complexity of Linear Search is $ O(n) $ in the worst case, where ''n'' is the number of elements in the list.

- Linear Search is easy to implement but not efficient for large datasets compared to other search algorithms like Binary Search.

- Linear Search can be used on both arrays and linked lists.

- This algorithm does not require additional memory space, making it a space-efficient search method.', NULL, 'null', '[]', '[]', '[46]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1326, 'computer-science-2024-07-19-shift-1', 'q29', 28, 28, 'Which of the statement(s) is/are True for the given question.

Data elements are: 7, 5, 17, 13, 9, 27, 31, 25, 35.

Hash Table Size: 7

Hash Function: $ H(I) = (\text{Data element}) \mod (\text{Hash Table Size}) $

(A) Element 27 will create collision.

(B) Element 25 will create collision.

(C) Element 35 will create collision.

(D) Element 31 will create collision.', '[{"id":"A","text":"(A), (B) and (C) only"},{"id":"B","text":"(A), (C) and (D) only"},{"id":"C","text":"(B), (C) and (D) only"},{"id":"D","text":"(A) and (D) only"}]', 0, 'A', 'The correct answer is Option_1.
Key Points

- To determine if an element will create a collision in the hash table, we need to calculate the hash value using the hash function $ H(I) = (\text{Data element}) \mod (\text{Hash Table Size}) $.

- The hash table size is 7, so we need to find the remainder when each data element is divided by 7.

• 7 mod 7 = 0

• 5 mod 7 = 5

• 17 mod 7 = 3

• 13 mod 7 = 6

• 9 mod 7 = 2

• 27 mod 7 = 6

• 31 mod 7 = 3

• 25 mod 7 = 4

• 35 mod 7 = 0

Based on these calculations, we can see the following:

• Element 27 will create a collision because 27 mod 7 = 6, and 13 mod 7 = 6.

- Element 25 will not create a collision because 25 mod 7 = 4 is unique.

• Element 35 will create a collision because 35 mod 7 = 0, and 7 mod 7 = 0.

• Element 31 will create a collision because 31 mod 7 = 3, and 17 mod 7 = 3.
Additional Information

- Therefore, the statements (A), (B), and (C) are true, making Option 1 the correct answer.

• Understanding hash functions and hash table collisions is crucial in data structure design to minimize the chances of collision and improve the efficiency of data retrieval.', NULL, 'null', '[]', '[]', '[47]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1327, 'computer-science-2024-07-19-shift-1', 'q30', 29, 29, 'If a list contain ''n'' number of elements and all the

elements by default sorted in ascending order then how

many comparisons will be required during 1st pass of

bubble sort to arrange the list in ascending order?', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"n - 1"},{"id":"D","text":"n"}]', 0, 'A', 'The correct answer is $ \underline{1} $0.
Key Points

- Bubble sort is a comparison-based algorithm where each pair of adjacent elements is compared, and the elements are swapped if they are not in order.

- In the 1st pass of bubble sort, if the list is already sorted in ascending order, there will be no swaps required.

• However, comparisons are still made to check if any swaps are needed.

• For a list with ''n'' elements, the number of comparisons in the first pass is (n - 1).

- Since the list is already sorted, no swaps will be performed, making the number of swaps 0.
Additional Information

- The total number of comparisons in bubble sort for a list of ''n'' elements in the worst case is $ O(n^{2}) $.

- Bubble sort is not suitable for large data sets as its average and worst-case complexity are quite high.

• It is known for its simplicity and is useful for small data sets or nearly sorted lists.

- Bubble sort can be optimized by stopping the algorithm if the inner loop didn''t cause any swap, indicating the list is already sorted.', NULL, 'null', '[]', '[]', '[49]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1328, 'computer-science-2024-07-19-shift-1', 'q32', 30, 30, '_ compares neighbouring elements only and swaps them when necessary.', '[{"id":"A","text":"Selection Sort"},{"id":"B","text":"Bubble Sort"},{"id":"C","text":"Insertion Sort"},{"id":"D","text":"Quick Sort"}]', 0, 'B', 'The correct answer is Bubble_Sort.
Key Points

• Bubble Sort is a simple sorting algorithm that repeatedly steps through the list to be sorted, compares each pair of adjacent items, and swaps them if they are in the wrong order.

- This process is repeated until the list is sorted.

- Bubble Sort is known for its simplicity but is not suitable for large datasets as its average and worst-case time complexity is quite high.

- It works by repeatedly comparing adjacent elements and swapping them if they are in the wrong order, hence the name "bubble sort" because smaller elements "bubble" to the top of the list.

• In each pass, the largest element moves to its correct position in the list.
Additional Information

- Bubble Sort has a time complexity of $ O(n^2) $ in the average and worst cases, where n is the number of items being sorted.

• It is stable, meaning it preserves the relative order of equal elements.

- Despite its inefficiency, Bubble Sort can be useful for small datasets or as an educational tool to introduce sorting algorithms.

- It is also referred to as "sinking sort" because larger elements "sink" to their correct positions.', NULL, 'null', '[]', '[]', '[53]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1329, 'computer-science-2024-07-19-shift-1', 'q33', 31, 31, '_ are the unorganized facts that can be processed to generate meaningful information.', '[{"id":"A","text":"Information"},{"id":"B","text":"Data"},{"id":"C","text":"Blog"},{"id":"D","text":"contexts"}]', 0, 'B', 'The correct answer is $ \underline{\text{Data}} $.
Key Points

• Data refers to raw, unorganized facts and figures that need to be processed.

Data can be anything like numbers, text, symbols, or even multimedia content such as images, audio, and video.

- Once processed, data is transformed into meaningful information that can be used for decision-making.

• For example, a list of numbers is data, and when analyzed, it might provide information about trends or patterns.
Additional Information

- Data can be collected from various sources such as surveys, experiments, or transactions.

- Data is often stored in databases where it can be queried and retrieved for analysis.

- The quality of information derived from data depends on the quality and integrity of the data itself.

• Data processing involves organizing, structuring, and interpreting data to make it useful.', NULL, 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1330, 'computer-science-2024-07-19-shift-1', 'q34', 32, 32, '_ is the positive square root of the average of squared difference of each value from the mean.', '[{"id":"A","text":"Mode"},{"id":"B","text":"Variance"},{"id":"C","text":"Median"},{"id":"D","text":"Standard Deviation"}]', 0, 'D', 'The correct answer is Standard Deviation.
Key Points

• Standard Deviation is the positive square root of the average of squared difference of each value from the mean.

• It is a measure of the amount of variation or dispersion in a set of values.

- To calculate it, first find the mean (average) of the data set.

- Then, subtract the mean from each data point and square the result (the squared difference).

- The average of these squared differences is the variance.

• The square root of the variance gives the standard deviation.

- Standard Deviation is widely used in statistics to understand the distribution of data points.

• It helps in identifying how spread out the values in a data set are.
Additional Information

• Standard Deviation is used in finance to measure market volatility.

• In quality control, it is used to determine the consistency of processes and products.

- A low standard deviation indicates that the data points are close to the mean, while a high standard deviation indicates that the data points are spread out over a large range of values.

Other measures of dispersion include range, interquartile range, and mean absolute deviation.', NULL, 'null', '[]', '[]', '[55]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1331, 'computer-science-2024-07-19-shift-1', 'q36', 33, 33, 'What is the primary difference between a database and a file system?', '[{"id":"A","text":"Databases are slower than file systems for retrieving data."},{"id":"B","text":"Databases offer structured data and relationships, while file systems do not."},{"id":"C","text":"File systems can support complex queries, unlike databases."},{"id":"D","text":"Both databases and file systems handle data in the same way."}]', 0, 'B', 'The correct answer is Databases_offer_structured_data_and_relationships, while file_systems do not.
Key Points

- A database is a collection of organized data that allows for efficient storage, retrieval, and management of information.

- Databases are designed to handle large amounts of data and support complex queries and transactions.

- They offer a structured format with predefined schemas and relationships between different data entities.

- Databases ensure data integrity, consistency, and support concurrent access by multiple users.

- They provide powerful tools for data manipulation, including SQL for querying and managing data.

- A file system is a method of organizing and storing files on a storage device such as a hard drive.

- File systems store data in a hierarchical structure of directories and files.

- They do not inherently provide mechanisms for enforcing data relationships or integrity constraints.

- File systems are suitable for simple storage and retrieval tasks but lack advanced querying capabilities.

- They are generally faster for basic file operations but less efficient for complex data management tasks.
Additional Information

- Databases use a Database Management System (DBMS) to facilitate data management and provide advanced features like backup, recovery, and security.

Common types of databases include relational databases (e.g., MySQL, PostgreSQL), NoSQL databases (e.g., MongoDB, Cassandra), and in-memory databases (e.g., Redis).

- File systems are managed by the operating system and include types such as NTFS, FAT32, and ext4.

- The choice between using a database or a file system depends on the specific requirements of the application, such as data complexity, performance needs, and scalability.', NULL, 'null', '[]', '[]', '[58]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1332, 'computer-science-2024-07-19-shift-1', 'q37', 34, 34, 'A domain in a relational database refers to :', '[{"id":"A","text":"The overall database structure"},{"id":"B","text":"A specific set of valid values for an attribute"},{"id":"C","text":"A table containing multiple records"},{"id":"D","text":"A relationship between two tables"}]', 0, 'B', 'The correct answer is A specific set of valid values for an attribute.
Key Points

- A domain in a relational database is a specific set of valid values for an attribute (column).

- It defines the permissible values that a column can contain, ensuring data integrity.

• For example, a domain for a "gender" attribute might include only the values "Male", "Female", and "Other".

- Domains help enforce constraints, such as data types and value ranges, on the data stored in the database.
Additional Information

- Domains improve data consistency by ensuring that all values in a column adhere to a predefined set of rules.

- They can be used to implement business rules and validation logic at the database level.

- By defining domains, database administrators can prevent incorrect or out-of-range values from being entered into the database.

- Domains can also be shared across multiple tables, providing a standardized way of defining valid values for similar attributes.', NULL, 'null', '[]', '[]', '[60]', 'keyed', '[]', '2026-11-05T20:58:44.378Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1333, 'computer-science-2024-07-19-shift-1', 'q38', 35, 35, 'A relation in a relational database is also known as:', '[{"id":"A","text":"A data type"},{"id":"B","text":"An attribute"},{"id":"C","text":"A schema"},{"id":"D","text":"A table"}]', 0, 'D', 'The correct answer is table.
Key Points

• A relation in a relational database is also known as a table.

- In relational databases, data is organized into tables. Each table represents a collection of related data entries.

- Tables consist of rows and columns, where each row represents a unique record, and each column represents a field within the record.

- This structure allows for efficient data management and retrieval through SQL queries.

- Tables can be related to each other through keys, such as primary keys and foreign keys, which help maintain data integrity and enable complex queries.

- The concept of a relation as a table is fundamental to relational database theory, as proposed by E.F. Codd.
Additional Information

- Relational databases use Structured Query Language (SQL) for defining and manipulating data in tables.

- Popular relational database management systems (RDBMS) include MySQL, PostgreSQL, Oracle Database, and Microsoft SQL Server.

• Normalization is a process in database design used to minimize redundancy and dependency by organizing fields and table of a database.

- Each table in a relational database can have constraints to enforce rules on the data, such as NOT NULL, UNIQUE, CHECK, and DEFAULT constraints.', NULL, 'null', '[]', '[]', '[61]', 'keyed', '[]', '2026-11-05T20:58:44.379Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1334, 'computer-science-2024-07-19-shift-1', 'q39', 36, 36, 'The primary key is chosen from _.', '[{"id":"A","text":"The most complex candidate key available."},{"id":"B","text":"All available candidate keys for a table."},{"id":"C","text":"The simplest candidate key available."},{"id":"D","text":"Any attribute within the table."}]', 0, 'A', 'The correct answer is The most complex candidate key available.
Key Points

• The primary key in a database is a unique identifier for a record within a table.

- It is chosen from the candidate keys available for the table.

- The primary key ensures that each record can be uniquely identified, preventing duplicate entries.

• It is crucial for maintaining the integrity and reliability of the database.

- The most complex candidate key is often chosen to ensure that the primary key is unique and less likely to have duplicates.
Additional Information

• All candidate keys in a table are considered before selecting the primary key.

• While simplicity is valued, the uniqueness of the key is paramount.

• Primary keys can be a single attribute or a combination of attributes (composite key).

- It is essential for establishing relationships between different tables in a relational database.

• Indexes are often created on primary keys to enhance search and query performance.', NULL, 'null', '[]', '[]', '[62]', 'keyed', '[]', '2026-11-05T20:58:44.379Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1335, 'computer-science-2024-07-19-shift-1', 'q40', 37, 37, 'An alternate key is _.', '[{"id":"A","text":"Another name for the primary key"},{"id":"B","text":"A unique identifier besides the primary key"},{"id":"C","text":"A relationship between two tables"},{"id":"D","text":"A synonym for a tuple"}]', 0, 'A', 'The correct answer is Another name for the primary key.
Key Points

• An alternate key is another name for the primary key in the context of a relational database.

- Alternate keys are candidate keys that are not selected as the primary key but can still uniquely identify a record within a table.

- In other words, an alternate key is a column or set of columns that can serve as a unique identifier for the rows in a table, but is not the primary key.

- For example, if a table has columns such as EmployeeID and SocialSecurityNumber, either could be chosen as the primary key, and the other could be an alternate key.

- Alternate keys provide additional ways to enforce uniqueness in the database, which can help with data integrity and querying efficiency.
Additional Information

- Primary keys and alternate keys are part of the broader category of candidate keys, which are columns that can uniquely identify a record.

- Having multiple candidate keys (including alternate keys) provides flexibility in database design and can help with performance optimization.

- It''s important to choose the primary key carefully, as it will be used for indexing and referential integrity constraints.

• Alternate keys can also be used to create additional indexes, which can speed up query performance.

- While the primary key is often chosen for its simplicity and efficiency, alternate keys are equally important for ensuring data integrity and uniqueness.', NULL, 'null', '[]', '[]', '[63]', 'keyed', '[]', '2026-11-05T20:58:44.379Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1336, 'computer-science-2024-07-19-shift-1', 'q42', 38, 38, 'Which of the following is correct syntax for inserting foreign key constraint in a relation?', '[{"id":"A","text":"ALTER TABLE table_name ADD FOREIGN KEY(attribute name) REFERENCES referenced_table_name(attribute name)"},{"id":"B","text":"ADD TABLE table_name ADD FOREIGN KEY(attribute name) REFERENCES referenced_table_name(attribute name)"},{"id":"C","text":"ALTER TABLE table_name REFERENCES referenced_table_name(attribute name) ADD FOREIGN KEY (attribute name)"},{"id":"D","text":"MODIFY TABLE table_name ADD FOREIGN KEY(attribute name) REFERENCES referenced_table_name(attribute name)"}]', 0, 'A', 'The correct answer is ALTER_TABLE_table_name ADD_FOREIGN KEY(attribute_name) REFERENCES referenced_table_name(attribute_name).
Key Points

- To add a foreign key constraint, the ALTER TABLE statement is used to modify the existing table structure.

• The syntax for adding a foreign key is:

ALTER TABLE table_name ADD FOREIGN KEY (attribute_name) REFERENCES referenced_table_name(attribute_name);

- This statement ensures referential integrity by creating a link between the foreign key in one table and the primary key in another table.

- It is important to specify the table and attribute names correctly for both the foreign key and the referenced primary key.
Additional Information

• Foreign keys help maintain data consistency and integrity across related tables.

- They prevent actions that would destroy the relationships between tables, such as deleting a record that is referenced by a foreign key in another table.

- Foreign key constraints can also enforce cascading actions such as ON DELETE CASCADE or ON UPDATE CASCADE, which automatically update or delete dependent records.

- Properly defining foreign keys is crucial in database design to ensure data is stored in a normalized and efficient manner.', NULL, 'null', '[]', '[]', '[66]', 'keyed', '[]', '2026-11-05T20:58:44.381Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1337, 'computer-science-2024-07-19-shift-1', 'q43', 39, 39, 'What is result of following arithmetic operation in SQL?
SELECT 5+NULL AS RESULT', '[{"id":"A","text":"5"},{"id":"B","text":"NULL"},{"id":"C","text":"0"},{"id":"D","text":"5NULL"}]', 0, 'B', 'Key Points

• In SQL, the result of any arithmetic operation involving a NULL value is always NULL.

NULL represents an unknown or missing value in SQL.

- When you add a number to NULL, the result remains NULL because NULL indicates the absence of a value.

- This behavior is consistent across different SQL databases such as MySQL, SQL Server, and PostgreSQL.

• In the given SQL statement: SELECT 5+NULL AS RESULT, the NULL value makes the entire expression evaluate to NULL.
Additional Information

- It is important to handle NULL values properly in SQL queries to avoid unexpected results.

• Functions like COALESCE or ISNULL can be used to replace NULL values with a default value.

- Understanding how NULL values interact with different SQL operations is crucial for accurate data manipulation and query results.

NULL is not the same as an empty string or zero; it is a distinct marker used to indicate missing or unknown data.', NULL, 'null', '[]', '[]', '[68]', 'keyed', '[]', '2026-11-05T20:58:44.381Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1338, 'computer-science-2024-07-19-shift-1', 'q44', 40, 40, 'Which of the following expression in SQL would calculate the square root of 16?', '[{"id":"A","text":"POWER(16,2)"},{"id":"B","text":"POWER(16, 0.5)"},{"id":"C","text":"POWER(16, 1)"},{"id":"D","text":"MOD(16)"}]', 0, 'B', 'The correct answer is POWER(1.6,0.5).
Key Points

• The POWER function in SQL is used to raise a number to the power of another number.

• In this case, we need to calculate the square root of 16.

• To find the square root, we raise 16 to the power of 0.5.

- The expression POWER(16, 0.5) correctly calculates the square root of 16, which is 4.
Additional Information

• Option 1: POWER(16, 2) calculates 16 raised to the power of 2, resulting in 256.

• Option 3: POWER(16, 1) calculates 16 raised to the power of 1, resulting in 16.

- Option 4: MOD(16) is not a valid expression for calculating the square root. The MOD function is used to find the remainder of a division.', NULL, 'null', '[]', '[]', '[69]', 'keyed', '[]', '2026-11-05T20:58:44.382Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1339, 'computer-science-2024-07-19-shift-1', 'q45', 41, 41, 'Which of the following statement(s) is/are TRUE in respect of Media Access Control (MAC) Address?

(A) It can be changed if a node is removed from one network and connected to another network.

(B) Each MAC address is a 12-digit hexadecimal number.

(C) It is a unique value associated with a network adapter called NIC.

(D) It is provided by the Internet Service Provider to locate computers connected to the internet.', '[{"id":"A","text":"(B) and (C) only"},{"id":"B","text":"(A), (B) and (C) only"},{"id":"C","text":"(C) and (D) only"},{"id":"D","text":"(A) and (B) only"}]', 0, 'A', 'The correct answer is Option_1.
Key Points

• Statement (B): Each MAC address is a 12-digit hexadecimal number.

- A MAC address is typically represented as a string of 12 hexadecimal digits (0-9, A-F), such as 00:1A:2B:3C:4D:5E.

- Statement (C): It is a unique value associated with a network adapter called NIC.

- The MAC address is a unique identifier assigned to the network interface card (NIC) of a device, ensuring that each device on a network can be distinctly identified.
Additional Information

Statement (A): It can be changed if a node is removed from one network and connected to another network.

- This statement is incorrect because a MAC address is hardcoded into the network interface card (NIC) and does not change when a device moves to a different network.

• Statement (D): It is provided by the Internet Service Provider to locate computers connected to the internet.

- This statement is incorrect because MAC addresses are assigned to devices by the manufacturer of the network interface card (NIC), not by the Internet Service Provider (ISP).', NULL, 'null', '[]', '[]', '[70]', 'keyed', '[]', '2026-11-05T20:58:44.382Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1340, 'computer-science-2024-07-19-shift-1', 'q47', 42, 42, 'What is the purpose of Domain Name System Server in networking?', '[{"id":"A","text":"To encrypt data during transmission."},{"id":"B","text":"To convert domain names into IP addresses"},{"id":"C","text":"To regulate network traffic flow."},{"id":"D","text":"To establish a secure connection between devices."}]', 0, 'B', 'The correct answer is To convert domain names into IP addresses.

• The Domain Name System (DNS) Server is a crucial component in networking that translates human-friendly domain names into machine-readable IP addresses.

- When a user types a domain name into their web browser, the DNS server is queried to find the corresponding IP address.

- This translation is necessary because while domain names are easy for humans to remember, computers use IP addresses to locate each other on the network.

- DNS servers help to ensure that the internet runs smoothly by keeping track of all domain names and their IP addresses.

- Without DNS servers, users would have to remember and input numerical IP addresses to access websites, which is impractical.

• DNS servers also provide additional functionalities like email routing and service discovery within networks.
Additional Information

• DNS servers are structured in a hierarchical manner, starting from root servers down to local servers.

- They can cache DNS queries to speed up the resolution process for frequently accessed domain names.

• DNS servers use different types of records such as A records (address records), CNAME records (canonical name records), and MX records (mail exchange records).

• Security extensions like DNSSEC (DNS Security Extensions) add an additional layer of security by ensuring the authenticity and integrity of DNS data.

• The DNS system was introduced by Paul Mockapetris and Jon Postel in 1983.', NULL, 'null', '[]', '[]', '[74]', 'keyed', '[]', '2026-11-05T20:58:44.382Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1341, 'computer-science-2024-07-19-shift-1', 'q48', 43, 43, '140.168.220.200 is a 32-bit binary number usually represented as 4 decimal values, each representing 8 bits, in the range 0 to 255 separated by decimal points. What is this number called?', '[{"id":"A","text":"IP Address"},{"id":"B","text":"Web Address"},{"id":"C","text":"MAC Address"},{"id":"D","text":"Port Address"}]', 0, 'A', 'The correct answer is IP_Address.
Key Points

• An IP Address (Internet Protocol Address) is a unique identifier assigned to each device connected to a network that uses the Internet Protocol for communication.

- IP addresses are used to identify and locate devices on a network, allowing them to communicate with each other.

- IPv4 addresses are 32-bit binary numbers, usually represented in decimal format as four octets separated by periods (e.g., 140.168.220.200).

- IPv6 addresses are 128-bit binary numbers, represented in hexadecimal format and separated by colons.

- IP addresses can be static (permanently assigned) or dynamic (temporarily assigned by a DHCP server).
Additional Information

- IP addresses are essential for routing data packets between devices on different networks.

- There are two main types of IP addresses: public and private. Public IP addresses are used on the internet, while private IP addresses are used within local networks.

- NAT (Network Address Translation) allows multiple devices on a local network to share a single public IP address.

- IP addresses are assigned and managed by organizations such as the Internet Assigned Numbers Authority (IANA) and regional Internet registries.', NULL, 'null', '[]', '[]', '[75]', 'keyed', '[]', '2026-11-05T20:58:44.383Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1342, 'computer-science-2024-07-19-shift-1', 'q49', 44, 44, 'In a _ topology, if there are n devices in a network, each device has n-1 ports for cables.', '[{"id":"A","text":"Mesh"},{"id":"B","text":"Bus"},{"id":"C","text":"Star"},{"id":"D","text":"Ring"}]', 0, 'A', 'The correct answer is Mesh.
Key Points

• In a mesh topology, every device is connected to every other device in the network.

• If there are n devices in a network, each device will have n-1 ports for cables.

- This type of topology provides high redundancy and reliability because there are multiple paths for data to travel between devices.

- Mesh topology is often used in networks where communication reliability is crucial, such as in military or critical business applications.
Additional Information

- Mesh topology can be either full mesh or partial mesh. In a full mesh topology, every device is connected to every other device. In a partial mesh topology, some devices are connected to all other devices, while others are connected only to those they exchange data with most frequently.

Although mesh topology offers high reliability and redundancy, it is also more expensive and complex to implement compared to other topologies due to the large number of connections required.

- Mesh networks can manage high traffic volumes better than other topologies because of the multiple paths available for data transmission.

• Examples of technologies that use mesh topology include Zigbee in home automation networks and some wireless mesh networks.', NULL, 'null', '[]', '[]', '[77]', 'keyed', '[]', '2026-11-05T20:58:44.383Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1343, 'computer-science-2024-07-19-shift-1', 'q50', 45, 45, 'Amit wants to be familiar with SQL. One of his friends Anand suggests him to execute the following sql commands.

(A) Create Table Student

(B) Use Database DB

(C) Select * from Student

(D) Insert into Student

In which order Amit needs to run above commands.', '[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (B), (D), (C)"},{"id":"C","text":"(B), (A), (D), (C)"},{"id":"D","text":"(C), (B), (D), (A)"}]', 0, 'C', 'The correct answer is Option_3.
Key Points

- To become familiar with SQL, Amit needs to execute the commands in a specific order to ensure they are performed correctly and without errors.

- The command (B) Use Database DB is executed first to select the database in which the operations will be performed.

- The command (A) Create Table Student is executed next to create the table structure within the selected database.

- The command (D) Insert into Student is executed third to populate the table with data.

- The command (C) Select * from Student is executed last to retrieve and display the data from the table.
Additional Information

- Executing the commands in the correct order ensures the database and table are properly set up before attempting to insert or retrieve data.

- Using the USE statement ensures that subsequent operations are performed on the correct database.

• Creating the table first is essential to define the structure before inserting data.

- Inserting data is necessary before any data retrieval operations can be performed.', NULL, 'null', '[]', '[]', '[78]', 'keyed', '[]', '2026-11-05T20:58:44.383Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
