INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1377, 'english-2024-05-29-shift-1', 'q01', 1, 1, 'The passage reminds us to ''stay hydrated'' which means that', '[{"id":"A","text":"we should have plenty of water"},{"id":"B","text":"we should stay indoors."},{"id":"C","text":"we should have fermented foods like yogurt"},{"id":"D","text":"we should have zinc-rich foods with vitamin C"}]', 0, 'A', 'The correct answer is ''we should have plenty of water''.
Key Points

• Staying hydrated refers to maintaining adequate water levels in the body.

• Drinking plenty of fluids, such as water, is essential for staying hydrated.

- Proper hydration supports the body''s overall health and immune functions.

• Adequate water intake helps alleviate symptoms of colds and coughs.

• Water helps to keep the throat moist, reducing irritation caused by coughing.

- Proper hydration can help maintain the body''s balance of fluids and electrolytes.

Therefore, the correct answer is ''Option 1''.
Additional Information

• Staying indoors does not directly relate to maintaining hydration.

• Fermented foods like yogurt do not directly help in staying hydrated.

• Having zinc-rich foods with vitamin C is beneficial for immune support but does not specifically address hydration.', 'p1c8f3566a8da', 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:44.388Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1378, 'english-2024-05-29-shift-1', 'q02', 2, 2, 'The passage encourages us to consume zinc in the form of', '[{"id":"A","text":"zinc solution"},{"id":"B","text":"unprocessed food grains"},{"id":"C","text":"a variety of plant and animal foods"},{"id":"D","text":"non-vegetarian sources only Answer: C"}]', 0, 'C', 'The correct answer is ''a variety of plant and animal foods''.
Key Points

• The passage emphasizes the inclusion of zinc-rich foods from both plant and animal sources.

• It mentions specific zinc-rich foods such as lean meats, poultry, seafood, dairy, nuts, and seeds.

- Consuming a diverse range of foods ensures that different sources of zinc are included in the diet.

- The passage highlights the importance of combining zinc-rich foods with vitamin C for enhanced immune support.

• It suggests moderation and diversity in the diet to maximize the benefits of zinc.

• The passage also advises vegetarians on methods to improve zinc absorption from plant sources.

Therefore, the correct answer is ''Option 3''.
Additional Information

- Zinc solution is not mentioned as a primary source of zinc in the passage.

- Unprocessed food grains contain phytates that hinder zinc absorption, so they are not recommended as the main source.

- Non-vegetarian sources are included but are not the only recommended sources of zinc.', 'p1c8f3566a8da', 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1379, 'english-2024-05-29-shift-1', 'q03', 3, 3, 'Choose the word that means the opposite of ''pivotal''.', '[{"id":"A","text":"Central"},{"id":"B","text":"Important"},{"id":"C","text":"Life-changing"},{"id":"D","text":"Unimportant"}]', 0, 'D', 'The correct answer is ''Unimportant''.
Key Points

• The word ''pivotal'' refers to something that is crucial, central, or of utmost importance.

• The opposite of ''pivotal'' would be something that lacks importance or is not central to a situation.

• ''Unimportant'' directly indicates a lack of significance or relevance.

• In the context of the passage, ''pivotal'' describes zinc''s significant role in supporting body functions.

• Therefore, the opposite term would downplay its importance, fitting the meaning of ''unimportant''.

• Recognizing antonyms helps understand the relative importance or lack thereof of a concept.

Therefore, the correct answer is ''Option 4''.
Additional Information

• ''Central'' is synonymous with ''pivotal'', not an antonym.

• ''Important'' is synonymous with ''pivotal'', not an antonym.

• ''Life-changing'' also indicates something significant, so it is not an antonym.', 'p1c8f3566a8da', 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1380, 'english-2024-05-29-shift-1', 'q04', 4, 4, 'In the passage, which of the following is not a benefit connected to consuming zinc?', '[{"id":"A","text":"Strengthens immune system"},{"id":"B","text":"Anti-viral properties"},{"id":"C","text":"Anti-inflammatory agent"},{"id":"D","text":"Supports hair growth Answer: D"}]', 0, 'D', 'The correct answer is ''Supports hair growth''.
Key Points

- The passage highlights zinc''s role in reducing the severity and duration of respiratory tract infections.

• It mentions that zinc soothes sore throats due to its anti-inflammatory properties.

• Zinc is stated to play a pivotal role in supporting the immune system and overall health.

- The passage states that zinc prevents viruses from growing in the body, indicating its anti-viral properties.

• The immune-boosting properties of zinc are specifically noted in the passage.

- However, the passage does not mention any benefits of zinc related to supporting or enhancing hair growth.

Therefore, the correct answer is ''Option 4''.
Additional Information

• Strengthening the immune system is explicitly mentioned as a benefit of zinc.

- Anti-viral properties are clearly indicated in the passage.

• The anti-inflammatory effect of zinc is described in detail.', 'p1c8f3566a8da', 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1381, 'english-2024-05-29-shift-1', 'q05', 5, 5, 'What does the word ''solution'' signify in ''a secret solution''?', '[{"id":"A","text":"Remedy"},{"id":"B","text":"Drink"},{"id":"C","text":"Function"},{"id":"D","text":"Food"}]', 0, 'A', 'The correct answer is ''Remedy''.
Key Points

- The passage refers to zinc as a secret solution for reducing the severity and duration of respiratory tract infections and soothing sore throats.

- Zinc''s role in supporting various body functions, suggesting it helps in overall health, implies a corrective aspect.

- I he context in which ''solution'' is used in the passage aligns with the concept of something that solves or alleviates a problem, particularly health-related issues.

- The passage contrasts zinc with vitamin C, which is commonly known for its remedial benefits for colds, suggesting zinc serves a similar purpose.

• ''Solution'' in the context of health and wellness generally signifies a remedy or treatment for an ailment.

- Thus, the term ''solution'' here does not refer to a drink, function, or food, but to something that offers relief or cure.

Therefore, the correct answer is ''Option 1''.
Additional Information

• ''Drink'' would imply a liquid consumed for health, but the passage does not use ''solution'' in this manner.

- ''Function'' pertains to the roles zinc plays in the body but does not fit the context of ''secret solution''

• ''Food'' refers to items containing zinc, not the alleviating role zinc plays.', 'p1c8f3566a8da', 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1382, 'english-2024-05-29-shift-1', 'q06', 6, 6, 'According to the passage, combining zinc-rich foods with vitamin C will result in', '[{"id":"A","text":"reduced immunity."},{"id":"B","text":"increased immunity"},{"id":"C","text":"food allergy"},{"id":"D","text":"a sore throat."}]', 0, 'B', 'The correct answer is Option 2.
