INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1383, 'english-2024-05-29-shift-1', 'q07', 7, 7, 'Which of the following is not required to safeguard pollinators and ecosystems?', '[{"id":"A","text":"Protecting and restoring their habitats"},{"id":"B","text":"Adopting pollinators - friendly agricultural practices"},{"id":"C","text":"Using technology to transfer pollen between flowers"},{"id":"D","text":"Reducing pesticide use Answer: C"}]', 0, 'C', 'The correct answer is ''Using technology to transfer pollen between flowers''.
Key Points

- The passage highlights the need to protect and restore pollinator habitats to ensure their survival.

• It mentions adopting pollinator-friendly agricultural practices as a necessary measure.

• Reducing pesticide use is noted as crucial to protect pollinators from poisoning and disruptions.

- The passage does not mention the use of technology to transfer pollen between flowers as a measure to safeguard pollinators and ecosystems.

- The primary focus is on natural and sustainable methods to support pollinator health and preserve ecosystems.

- Technology for pollen transfer does not align with the natural and ecological context provided in the passage.

Therefore, the correct answer is ''Option 3''.
Additional Information

• Protecting and restoring habitats is essential for safeguarding pollinators.

• Adopting pollinator-friendly practices helps create a supportive agricultural environment.

• Reducing pesticide use protects pollinators from harmful chemical exposure.', 'p0edc22a3a127', 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1384, 'english-2024-05-29-shift-1', 'q08', 8, 8, 'Climate change endangers pollinator population

by_.', '[{"id":"A","text":"enabling the production of seeds and fruits"},{"id":"B","text":"disrupting their behaviour and reproductive patterns"},{"id":"C","text":"contributing to the abundance of flowering plants"},{"id":"D","text":"posioning them Answer: B"}]', 0, 'B', 'The correct answer is ''disrupting their behaviour and reproductive patterns''.
Key Points

• The passage explicitly states that climate change endangers pollinators by disrupting their behavior and reproductive patterns.

- Disruptions in behavior and reproductive patterns can lead to reductions in pollinator populations and affect pollination efficiency.

• Altered climates can affect the availability of flowering plants at the right time, leading to mismatches in timing between pollinators and plant blooming periods.

- These disruptions can also affect migratory patterns of certain pollinators, which are crucial for their survival and reproductive success.

- Behavioral changes and reproductive issues may result from changes in temperature and weather patterns, which are direct effects of climate change.

• Ensuring the continuity of pollinators'' natural processes is critical for maintaining the ecosystem''s balance and food production systems.

Therefore, the correct answer is ''Option 2''.
Additional Information

• Option 1: Climate change does not enable the production of seeds and fruits.

• Option 3: Climate change does not contribute to the abundance of flowering plants.

• Option 4: Climate change disrupts behaviors and patterns, while pesticide exposure is responsible for poisoning them.', 'p0edc22a3a127', 'null', '[]', '[]', '[10]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1385, 'english-2024-05-29-shift-1', 'q09', 9, 9, 'Choose the most appropriate option.
Which of the following is not a reason for habitat loss faced by pollinators?', '[{"id":"A","text":"Urbanization"},{"id":"B","text":"Climate change"},{"id":"C","text":"Pollination"},{"id":"D","text":"Pesticide exposure Answer: C"}]', 0, 'C', 'The correct answer is ''Pollination''.
Key Points

• Urbanization is mentioned as a reason for habitat loss as it leads to reduced nesting sites and floral resources.

- Climate change is noted in the passage as a factor that disrupts pollinator behavior and also contributes to habitat-related issues.

Pesticide exposure is highlighted as a threat to pollinators, impacting their health and contributing to their decline.

- The passage does not mention pollination as a reason for habitat loss; instead, pollination is the process facilitated by pollinators that is essential for plant reproduction and biodiversity.

Therefore, the correct answer is ''Option 3''.
Additional Information

• Option 1: Urbanization is a reason for habitat loss.

• Option 2: Climate change is also a factor affecting pollinator habitats and populations.

• Option 4: Pesticide exposure contributes to the decline in pollinator populations.', 'p4d3693531b9e', 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1386, 'english-2024-05-29-shift-1', 'q10', 10, 10, 'The ''mutualistic relationship'' talked about in the passage is between .', '[{"id":"A","text":"humans and pollinators"},{"id":"B","text":"animals and pollinators"},{"id":"C","text":"ecosystem and pollinators"},{"id":"D","text":"pollinators and plants"}]', 0, 'D', 'The correct answer is ''pollinators and plants''.
Key Points

The passage mentions that pollinators, such as bees, butterflies, birds, and bats, facilitate plant reproduction.

- This process involves the transfer of pollen between flowers, which is essential for the production of seeds and fruits.

- This relationship benefits both parties: plants rely on pollinators for reproduction, while pollinators gain food resources, such as nectar.

- Ine passage highlights the interdependence of pollinators and plants, which contributes to biodiversity and ecosystem stability.

- This mutualistic relationship supports global food production and benefits other organisms by providing habitat and food resources.

Therefore, the correct answer is ''Option 4''.', 'p0edc22a3a127', 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:44.389Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
