INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1390, 'english-2024-05-29-shift-1', 'q14', 14, 14, '''Knowing oneself'' is important because', '[{"id":"A","text":"it leads to stress"},{"id":"B","text":"it is a liability"},{"id":"C","text":"it is an asset"},{"id":"D","text":"it leads one to the black hole area Answer: C"}]', 0, 'C', 'The correct answer is ''it is an asset''.
Key Points

• The passage mentions that the ability to know oneself is described as an advantage.

• Knowing oneself allows for a reality check, which is vital for personal contentment.

• It is also important for maintaining healthy relationships with others.

- The sense of self-awareness is highlighted as a beneficial aspect of one''s psychological structure.

• Having self-awareness helps in personal and professional growth by managing one''s ego effectively.

- The passage emphasizes that this ability to know oneself is a skill that leaders should cultivate to positively impact their teams and organizations.

Therefore, the correct answer is ''Option 3''.
Additional Information

• Option 1: The passage does not suggest that knowing oneself leads to stress; rather, it is the lack of self-awareness that can cause problems.

• Option 2: Knowing oneself is considered an advantage, not a liability.

• Option 4: The "black hole area" refers to the negative consequences of an inflated ego, not the importance of self-awareness.', 'p6580a73eb3f2', 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:44.390Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1391, 'english-2024-05-29-shift-1', 'q15', 15, 15, '''To start ballooning'' means', '[{"id":"A","text":"to deflate"},{"id":"B","text":"to inflate"},{"id":"C","text":"to lose importance"},{"id":"D","text":"to create havoc Answer: B"}]', 0, 'B', 'The correct answer is ''to inflate''.
Key Points

• The phrase "to start ballooning" is used in the context of the ego growing excessively.

- "Ballooning" metaphorically describes the ego becoming larger or more significant than it should be.

• It implies an increase or expansion in the sense of self-importance.

• The context talks about the negative consequences when the ego is allowed to grow unchecked.

• Inflating an ego means making it bigger, which aligns perfectly with the idea of "ballooning."

- The passage warns of the problems that arise from an inflated ego, reinforcing that ballooning means to inflate.

Therefore, the correct answer is ''Option 2''.
Additional Information

• Option 1: "To deflate" means to reduce in size or importance, which is the opposite of "ballooning."

• Option 3: "To lose importance" is contrary to the idea of inflating or growing.

• Option 4: "To create havoc" is a consequence of an inflated ego but not the direct meaning of "ballooning."', 'p6580a73eb3f2', 'null', '[]', '[]', '[18]', 'keyed', '[]', '2026-11-05T20:58:44.390Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1392, 'english-2024-05-29-shift-1', 'q16', 16, 16, 'People with ''inflated'' ego are', '[{"id":"A","text":"popular"},{"id":"B","text":"disliked"},{"id":"C","text":"servile"},{"id":"D","text":"naive"}]', 0, 'B', 'The correct answer is ''disliked''.
Key Points

• The passage discusses the negative impact of allowing one''s ego to inflate excessively.

• An inflated ego can lead to a person becoming an egotist, which is problematic.

- The passage mentions that egotists create havoc in the personal and professional lives of those who have to work with them.

- This creates an impression that people with inflated egos are generally not well-liked by their colleagues and associates.

- The social and professional disruptions caused by an egotist indicate that such individuals are often disliked.

Therefore, the correct answer is ''Option 2''.
Additional Information

