• Option 3: "Servile" means excessively willing to serve or please others, which is contrary to someone with an inflated ego.

• Option 4: "Naive" means lacking experience, wisdom, or judgment, which is not directly related to having an inflated ego.', 'p6580a73eb3f2', 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:44.390Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1393, 'english-2024-05-29-shift-1', 'q17', 17, 17, 'The passage does not refer to :', '[{"id":"A","text":"All human beings have an ego"},{"id":"B","text":"Inftated ego can prove detrimental"},{"id":"C","text":"Inflated ego can be counter productive"},{"id":"D","text":"Inflated ego has a win-win outcome."}]', 0, 'D', 'The correct answer is ''Inflated ego has a win-win outcome''.
Key Points

