INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1398, 'english-2024-05-29-shift-1', 'q22', 22, 22, 'Choose the most appropriate verb to fill in the blank: Abhijat''s spirits _ when he learnt that he had won the first prize in the Poetry Recitation Competition.', '[{"id":"A","text":"plunged"},{"id":"B","text":"soared"},{"id":"C","text":"zipped"},{"id":"D","text":"tore"}]', 0, 'B', 'The correct answer is ''soared''.
