INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1399, 'english-2024-05-29-shift-1', 'q23', 23, 23, 'Choose the correct synonym of the word ''effrontery'':', '[{"id":"A","text":"audacity"},{"id":"B","text":"civility"},{"id":"C","text":"impetuosity"},{"id":"D","text":"affluence"}]', 0, 'A', 'The correct answer is: audacity.
Key Points

• The word "effrontery" means shameless or impudent boldness; lack of respect in a way that is shocking or rude. (धृष्टता, बेश्मा)

○ Example: He had the effrontery to challenge the teacher''s authority in front of the entire class.

• "Audacity" refers to the willingness to take bold risks; rude or disrespectful behavior. (साहस, धृष्टा)

Example: She had the audacity to argue with the manager about the new policy.

• Hence, we can infer that the synonym of ''effrontery'' is ''audacity''.

Therefore, the correct answer is: audacity.
Additional Information

Here are the other options explained along with their Hindi meanings and example sentences:

• Civility (शिष्टता): Polite and courteous behavior.

○ Example: He treated everyone with the utmost civility.

• Impetuosity (उत्वलोपन): Acting or done quickly and without thought or care.

• Example: His impetuosity often got him into trouble.

• Affluence (สมาคม): The state of having a great deal of money; wealth.

○ Example: The affluence of the neighborhood was evident in the large houses and expensive cars.

Question: Choose the correct synonym of the word ''effrontery'':

The correct answer is: audacity.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:44.391Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1400, 'english-2024-05-29-shift-1', 'q24', 24, 24, 'Choose the correct antonym of the underlined word: She is an $ \underline{\text{astute}} $ observer of human behaviour.', '[{"id":"A","text":"sharp"},{"id":"B","text":"brilliant"},{"id":"C","text":"ingenuous"},{"id":"D","text":"prudent"}]', 0, 'C', 'The correct answer is: ingenuous.
Key Points

• The word "astute" means having or showing an ability to accurately assess situations or people and turn this to one''s advantage. (चतुर)

Example: She is an astute investor who always makes profitable decisions.

• "Ingenuous" refers to being innocent and unsuspecting, lacking in craftiness or deceit. (भोली)

• Example: His ingenuous smile made everyone trust him immediately.

• Hence, we can infer that the opposite of ''astute'' is ''ingenuous''.

Therefore, the correct answer is: ingenuous.
Additional Information

Here are the other options explained along with their Hindi meanings and example sentences:

• Sharp (tếj): Having or showing speed of perception, comprehension, or response.

Example: His sharp mind quickly grasped the complex concepts.

• Brilliant (प्रतिभाशाली): Exceptionally clever or talented.

Example: She came up with a brilliant idea to solve the problem.

• Prudent (দ্বিকো): Acting with or showing care and thought for the future.

Example: It is prudent to save some money for emergencies.

Question: Choose the correct antonym of the underlined word: She is an astute observer of human behaviour.

Therefore, the correct answer is: ingenuous.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:44.391Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1401, 'english-2024-05-29-shift-1', 'q25', 25, 25, 'Rearrange the following parts of a sentence to form a meaningful sentence:

