INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1405, 'english-2024-05-29-shift-1', 'q29', 29, 29, 'Fill in the blanks in List I with the Phrasal verbs in List II :', '[{"id":"A","text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)"},{"id":"B","text":"(A) - $ (\\mathrm{I}) $, (B) - $ (\\mathrm{III}) $, (C) - $ (\\mathrm{II}) $, (D) - $ (\\mathrm{IV}) $"},{"id":"C","text":"(A) - $ (\\mathrm{I}) $, (B) - $ (\\mathrm{II}) $, (C) - $ (\\mathrm{IV}) $, (D) - $ (\\mathrm{III}) $"},{"id":"D","text":"(A) - $ (\\mathrm{III}) $, (B) - $ (\\mathrm{IV}) $, (C) - $ (\\mathrm{I}) $, (D) - $ (\\mathrm{II}) $ Answer: A"}]', 0, 'A', 'The correct answer is (A) - (II), (B) - (IV), (C) - (I), (D) - (III).
Key Points

• From the given options, only option 1 creates correct sentences.

Let''s look at the sentences:

○ (A) She is financially very smart and has got a few thousand rupees put away for her retirement.

''Put away'' means to save or store something for future use.

○ (B) He is clever, but his gruff exterior makes most people get put off by it.

Put off means to discourage or repel someone.

(C) I wonder how she puts up with his erratic behaviour.

''Puts up'' means to tolerate or endure something.

◦ (D) Every day she puts in ten to twelve hours of study; she will certainly crack the CAT exam.

''Puts in'' means to spend a certain amount of time doing something.

Hence, the correct answer is option 1.', NULL, 'null', '[]', '[{"id":"q29-table-1","kind":"table","path":"/local-papers/assets/english-2024-05-29-shift-1/q29-table-1.jpg","page":33,"alt":"Table for question 29"}]', '[33]', 'keyed', '[]', '2026-11-05T20:58:44.391Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
