INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1451, 'general-test-2024-05-15-shift-3', 'q31', 28, 28, 'Which of the following means ''A is the son-in-law of G''?', '[{"id":"A","text":"$ A \\times U\\% S \\times G $"},{"id":"B","text":"$ A + S\\% U \\times G $"},{"id":"C","text":"$ A - S + U \\times G $"},{"id":"D","text":"$ A \\times U\\% S + G $"}]', 0, 'D', 'Decoding symbols:

So, checking each option one by one:

Option 1) A × U % S × G → A is the husband of U who is the sister of S who is the husband of G.

Here, A is G''s husband''s brother-in-law.

Option 2) A + S % U × G → A is the son of S who is the sister of U who is the husband of G.

Here, A is G''s niece.

Option 3) A−S + U × G → A is the brother of S who is the son of U who is the husband of G.

Here, A is G''s son.

Option 4) $ A \times U \% S + G \rightarrow A $ is the husband of U who is the sister of S who is the son of G.

Here, A is G''s son-in-law.

Hence, the correct answer is"Option 4".', 'p4cc9640ed594', 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:44.400Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1452, 'general-test-2024-05-15-shift-3', 'q32', 29, 29, 'If $ 26^{th} $ January, 2020 was a Sunday, then what day of the week was it on $ 16^{th} $ March of that year?', '[{"id":"A","text":"Sunday"},{"id":"B","text":"Monday"},{"id":"C","text":"Tuesday"},{"id":"D","text":"Wednesday Answer: B"}]', 0, 'B', 'Given:26th January, 2020 was a Sunday

