INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1453, 'general-test-2024-05-15-shift-3', 'q33', 30, 30, 'What will be the measurement of the angle made by the hour and minute hands of a clock when the time is ''quarter past 3''?', '[{"id":"A","text":"$ 6\\frac{1}{2}^{\\circ} $"},{"id":"B","text":"$ 10^{\\circ} $"},{"id":"C","text":"$ 7\\frac{1}{2}^{\\circ} $"},{"id":"D","text":"$ 8\\frac{1}{2}^{\\circ} $"}]', 0, 'C', 'Given time: ''quarter past 3''→3:15

Given time gap = 15 minute

In one minutes, hour hand covers angular distance =0.5°

So, in 1 hour 20 minutes, minutes hand covers = $ 0.5^\circ \times 15 \text{ min} \Rightarrow 7\frac{1}{2}^\circ $

Hence," Option 3"is the correct answer.

Movement of Hour head
12 hr = 360°
1 hr = 30°
60 min = 30°
1 min = 0.5°
Movement of Minute head
1 hr = 360°
60 min = 360°
1 min = 6°
5 min = 30°
Movement of Seconds head
1 min = 360°
60 sec = 360°
1 sec = 6°
5 sec = 30°
Gapping between hour head and minute head
55 min = 60 min
1 min = 60/55', NULL, 'null', '[]', '[]', '[38]', 'keyed', '[]', '2026-11-05T20:58:44.400Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1454, 'general-test-2024-05-15-shift-3', 'q34', 31, 31, 'If in a certain code language, ''MERCURY'' is coded as ''NGUGZXF'', then how will ''ENTANGLE'' be coded in the same code language?', '[{"id":"A","text":"FPXFSSMSM"},{"id":"B","text":"FPWESMSM"},{"id":"C","text":"FPWESNSN"},{"id":"D","text":"FPWFTNSM"}]', 0, 'B', 'The logic followed here is:

''MERCURY'' is coded as ''NGUGZXF''

\[\begin{array}{l} M \\ 13 \quad 5 \quad 18 \quad 3 \quad 21 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} E \\ 5 \quad 18 \quad 3 \quad 21 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} Y \\ 25 \quad 18 \quad 21 \quad 3 \quad 25 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} J \\ 18 \quad 25 \quad 3 \quad 21 \quad 18 \quad 25 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} J \\ 18 \quad 25 \quad 3 \quad 21 \quad 18 \quad 25 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} N \\ 18 \quad 25 \quad 3 \quad 21 \quad 18 \quad 25 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} N \\ 18 \quad 25 \quad 3 \quad 21 \quad 18 \quad 25 \quad 18 \quad 25 \end{array} \quad \begin{array}{l} N \\ 18 \quad 25 \quad 3 \quad 21 \quad 18 \quad 25

Similarly,

''ENTANGLE'' is coded as

$$ \begin{matrix}{{\cal E}}&{{N}}&{{T}}&{{A}}&{{N}}&{{G}}&{{L}}&{{E}}\\ {{5}}&{{14}}&{{20}}&{{1}}&{{14}}&{{7}}&{{12}}&{{5}}\\ {{\downarrow^{+1}}}&{{\downarrow+2}}&{{\downarrow+3}}&{{\downarrow+4}}&{{\downarrow+5}}&{{\downarrow+6}}&{{\downarrow+7}}&{{\downarrow+8}}\\ {{{\cal F}}}&{{P}}&{{W}}&{{E}}&{{S}}&{{M}}&{{S}}&{{M}}\\ {{6}}&{{16}}&{{23}}&{{5}}&{{19}}&{{13}}&{{19}}&{{13}}\\ \end{matrix} $$

Hence," Option 2" is the correct answer.', NULL, 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:44.400Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1455, 'general-test-2024-05-15-shift-3', 'q35', 32, 32, 'The problem given below consists of a question and two statements numbered I and II. You have to decide whether the data provided in the statements are sufficient to answer the question.

How many sisters does Sunny have?

I. Sunny is the only son of his parents.

II. Sunny''s parents have three children.', '[{"id":"A","text":"Only statement I alone is sufficient to answer the question."},{"id":"B","text":"Only statement II alone is sufficient to answer the question."},{"id":"C","text":"Statements I and II together are sufficient to answer the question."},{"id":"D","text":"Either statement I or II alone is sufficient to answer the question."}]', 0, 'C', 'StatementI. Sunny is the only son of his parents.

Here, no information regarding Sunny''s sister(s), therefore statement (I) is not sufficient to answer the question. Statement II. Sunny''s parents have three children.

Here, Sunny''s sibling''s can be either brother or sister, therefore statement (II) is not sufficient to answer the question.

Combined statement (I) and (II): Sunny is the only son of his parents. Sunny''s parents have three children.

Here, Sunny has two sisters.

Thus, Statements I and II together are sufficient to answer the question.

Hence, the correct answer is "Option 3"', NULL, 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:44.400Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1456, 'general-test-2024-05-15-shift-3', 'q37', 33, 33, 'Find out which of the answer figures completes the figure matrix :

