INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1460, 'general-test-2024-05-15-shift-3', 'q42', 37, 37, 'In a class of 40 students, Anjali''s rank is thrice that of Anita. There are 4 students who have ranks worse than that of Anjali. Anita''s rank in the class is :', '[{"id":"A","text":"$ 9^{th} $"},{"id":"B","text":"$ 10^{th} $"},{"id":"C","text":"$ 18^{th} $"},{"id":"D","text":"$ 12^{th} $"}]', 0, 'D', 'Given: Class of 40 students

1) There are 4 students who have ranks worse than that of Anjali.

2) Anjali''s rank is thrice that of Anita.

Anjali''s rank = $ 3 \times $ Anita''s rank

36 = 3 × Anita''s rank

Anita''s rank = 12 (from top)

Thus, Anita''s rank is 12th in the class.

Hence, "Option 4" is the correct answer.', NULL, 'null', '[]', '[]', '[49]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1461, 'general-test-2024-05-15-shift-3', 'q43', 38, 38, 'Six people E, H, K, M, S and U are seated in a circle facing the centre. U and H are immediate neighbours of M. E is the only person sitting between K and S. H is to the immediate right of S. Who is to the immediate right of U?', '[{"id":"A","text":"M"},{"id":"B","text":"E"},{"id":"C","text":"K"},{"id":"D","text":"S"}]', 0, 'A', 'Given:Six peopleE, H, K, M, S and U are seated in a circle facing the centre.

1)E is the only person sitting between K and S.

2) H is to the immediate right of S.

E

3) U and H are immediate neighbours of M.

Thus, according to the final arrangement, M is to the immediate right of U. Hence, "Option 1" is the correct answer.', NULL, 'null', '[]', '[]', '[51]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1462, 'general-test-2024-05-15-shift-3', 'q45', 39, 39, 'II. All computers can never be keyboards.', '[{"id":"A","text":"Only conclusion I follows"},{"id":"B","text":"Only conclusion II follows"},{"id":"C","text":"Neither conclusion I nor II follows"},{"id":"D","text":"Both conclusions I and II follow"}]', 0, 'A', 'The least possible Venn diagram for the given statements is as shown below:
Conclusions:

I. All mouses are laptops→Follow(Asall mouses are computers and all computers are laptops. As whole mouses comes in computers which wholecomesin laptops, therefore it is true)

II. All computers can never be keyboards→Does not follow (Asno keyboard is a mouseandall mouses are computers.As no direct relation is given between computers and keyboards, therefore it is false.)

∴ Here, Only conclusion I follows.

Hence, the correct answer is "Option 1"', 'p6c6a4e4484b1', 'null', '[]', '[]', '[53]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1463, 'general-test-2024-05-15-shift-3', 'q46', 40, 40, 'Simplify: $ 24 \div 4 \times 2 + 8 - 4 = ? $', '[{"id":"A","text":"1"},{"id":"B","text":"7"},{"id":"C","text":"16"},{"id":"D","text":"56"}]', 0, 'C', 'Calculation:

$ 24 \div 4 \times 2 + 8 - 4 = ? $

$ \Rightarrow 6 \times 2 + 4 = ? $

$ \Rightarrow 12 + 4 = ? $

$ \Rightarrow 16 $

The correct answer is', NULL, 'null', '[]', '[]', '[54]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1464, 'general-test-2024-05-15-shift-3', 'q47', 41, 41, 'The difference of the greatest and the smallest of the fractions $ \frac{1}{2} $, $ \frac{8}{11} $, $ \frac{7}{8} $, $ \frac{7}{9} $, $ \frac{5}{6} $ is:', '[{"id":"A","text":"$ \\frac{3}{8} $"},{"id":"B","text":"$ \\frac{6}{7} $"},{"id":"C","text":"$ \\frac{7}{9} $"},{"id":"D","text":"$ \\frac{1}{3} $"}]', 0, 'A', 'Given:

Fractions: 1/2, 8/11, 7/8, 7/9, 5/6

Convert all to decimal for easy comparison:

1/2 = 0.50

8/11 ≈ 0.727

7/8 = 0.875

7/9 ≈ 0.778

5/6 ≈ 0.833

Greatest = 7/8 = 0.875

Smallest = 1/2 = 0.50

Difference = 0.875 - 0.50 = 0.375

Convert back to fraction: 0.375 = 3/8

∴ The difference is $ \underline{3/8} $', NULL, 'null', '[]', '[]', '[55]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1465, 'general-test-2024-05-15-shift-3', 'q48', 42, 42, 'The sum of LCM and HCF of two numbers is 854. If the LCM is 60 times the HCF and one of the numbers is 70, then the other number is', '[{"id":"A","text":"160"},{"id":"B","text":"164"},{"id":"C","text":"168"},{"id":"D","text":"172"}]', 0, 'C', 'Given:
LCM + HCF = 854
LCM = 60 \times HCF
One number = 70
Calculation:
Let HCF = x \Rightarrow LCM = 60x
So, x + 60x = 854
$ \Rightarrow $ 61x = 854
$ \Rightarrow $ x = 854 \div 61 = 14
So, HCF = 14, LCM = 60 \times 14 = 840
Use formula: Product of two numbers = HCF \times LCM
$ \Rightarrow $ 70 \times other number = 14 \times 840
$ \Rightarrow $ other number = (14 \times 840) \div 70
$ \Rightarrow $ other number = 11760 \div 70 = 168
∴ The other number is $ \underline{168} $', NULL, 'null', '[]', '[]', '[56]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1466, 'general-test-2024-05-15-shift-3', 'q49', 43, 43, 'The present age of Harish is 8 times the sum of the ages of his two sons at present. After 8 years, his age will be 2 times the sum of the ages of his two sons. The present age of Harish (in years) is :', '[{"id":"A","text":"31"},{"id":"B","text":"32"},{"id":"C","text":"33"},{"id":"D","text":"34"}]', 0, 'B', 'Given:

Let the present age of Harish be = H

Let the present age of Harish''s son''s (two sons) be = S

1) The present age of Harish is 8 times the sum of the ages of his two sons at present.

H = 8S _ (I)

2) After 8 years, his age will be 2 times the sum of the ages of his two sons.

H + 8 = 2 (S + 16), Here, ''16'' is added instead of 8, because there are two sons $ 8 \times 2 = 16 $

H + 8 = 2S + 32

H-2S=24 (II)

Putting, the value of H in equation (II):

H-2S=24

8S-2S=24

6S = 24

S=4

So, Putting, the value of S in equation (I):

H=8\times4

H = 32 years

Hence, "Option 2" is the correct answer.', NULL, 'null', '[]', '[]', '[57]', 'keyed', '[]', '2026-11-05T20:58:44.401Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1467, 'general-test-2024-05-15-shift-3', 'q51', 44, 44, 'In a class of 40 students, ratio of boys and girls is 3:2 and the average marks scored by boys is 42 and that by girls is 46. Then the average marks scored by the whole class is:', '[{"id":"A","text":"43.4"},{"id":"B","text":"43.6"},{"id":"C","text":"43.8"},{"id":"D","text":"44"}]', 0, 'B', 'Given:
Total number of students = 40
Ratio of boys to girls = 3 : 2
Average marks scored by boys = 42
Average marks scored by girls = 46
Formula Used:
Average marks of the whole class = $ (Total marks scored by boys + Total marks scored by girls) / Total number of students $
Calculation:
Number of boys = $ (3/5) \times 40 = 24 $
Number of girls = $ (2/5) \times 40 = 16 $
Total marks scored by boys = $ 24 \times 42 = 1008 $
Total marks scored by girls = $ 16 \times 46 = 736 $
Total marks scored by the whole class = 1008 + 736 = 1744
Average marks of the whole class = 1744 / 40
Average marks of the whole class = 43.6
The average marks scored by the whole class is 43.6.', NULL, 'null', '[]', '[]', '[59]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1468, 'general-test-2024-05-15-shift-3', 'q52', 45, 45, 'The sum of three numbers is 136. If the ratio between the first number and the second number is 2:3 and that between the second and the third number is 5:3, then the first number is:', '[{"id":"A","text":"42"},{"id":"B","text":"40"},{"id":"C","text":"36"},{"id":"D","text":"32"}]', 0, 'A', 'Given:

Sum of three numbers = 136

First : Second = 2 : 3

Second : Third = 5 : 3

Calculation:

Combine ratios using the common term (second number):

First : Second = 2 : 3 = 10 : 15 (×5)

Second : Third = 5 : 3 = 15 : 9 (×3)

⇒ Combined ratio: First : Second : Third = 10 : 15 : 9

Total parts = 10 + 15 + 9 = 34

Value of 1 part = 136 ÷ 34 = 4

First number = 10 × 4 = 40

∴ The first number is $ \underline{40} $', NULL, 'null', '[]', '[]', '[60]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1469, 'general-test-2024-05-15-shift-3', 'q53', 46, 46, 'An item is sold for ₹504 after allowing 20% discount and still a profit of 5% has been earned. The marked price is how much more than the cost price?', '[{"id":"A","text":"₹120"},{"id":"B","text":"₹135"},{"id":"C","text":"₹150"},{"id":"D","text":"₹160"}]', 0, 'C', 'Given:

Selling Price (SP) = ₹504

Discount = 20%

Profit = 5%

Formula used:

SP = MP × (1 - Discount%)

SP = CP × (1 + Profit%)

We need to find MP - CP

Calculation:

Let Cost Price (CP) = x

SP = x × (1 + 5/100) = 1.05x

⇒ 1.05x = 504 ⇒ x = 504 ÷ 1.05 = 480

Now, SP = MP × 80% ⇒ 504 = 0.8 × MP

⇒ MP = 504 ÷ 0.8 = 630

Required difference = MP - CP = 630 - 480 = 150

∴ The marked price is ₹150 more than the cost price', NULL, 'null', '[]', '[]', '[61]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1470, 'general-test-2024-05-15-shift-3', 'q54', 47, 47, 'A certain sum becomes ₹2,356 in 3 years and ₹2,660 in 5 years on simple interest. The value of sum is :', '[{"id":"A","text":"₹1,800"},{"id":"B","text":"₹1,880"},{"id":"C","text":"₹1,900"},{"id":"D","text":"₹1,980"}]', 0, 'A', 'Given:

Amount after 3 years = ₹2,356

Amount after 5 years = ₹2,660

Formula used:

Simple Interest (SI) = Amount - Principal

Calculation:

Difference in SI over 2 years = ₹2,660 - ₹2,356 = ₹304

SI per year = 304 ÷ 2 = ₹152

Total SI for 3 years = 152 × 3 = ₹456

Principal = Amount - SI = 2356 - 456 = ₹1,900

∴ The value of the sum is ₹1,900', NULL, 'null', '[]', '[]', '[63]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1471, 'general-test-2024-05-15-shift-3', 'q55', 48, 48, 'In a square, lengths of the diagonals are $ (4k+6) $ cm and $ (7k-3) $ cm. The area of the square $ (in\ cm^{2}) $ is :', '[{"id":"A","text":"144"},{"id":"B","text":"162"},{"id":"C","text":"169"},{"id":"D","text":"172"}]', 0, 'B', 'Given:

Diagonals of a square: $ (4k + 6) $ cm and $ (7k - 3) $ cm

Property used:

In a square, both diagonals are equal.

Formula used:

Area of square = (Diagonal $ ^{2} $) \div 2

Calculation:

Equating diagonals:

$ 4k + 6 = 7k - 3 $

$ \Rightarrow 6 + 3 = 7k - 4k $

$ \Rightarrow 9 = 3k \Rightarrow k = 3 $

Now, diagonal = $ 4k + 6 = 4 \times 3 + 6 = 18 \, cm $

Area = $ (18 \times 18) \div 2 = 324 \div 2 = 162 \, cm^{2} $

∴ Area of the square is $ \underline{162} $ cm $ ^{2} $.', NULL, 'null', '[]', '[]', '[63]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1472, 'general-test-2024-05-15-shift-3', 'q56', 49, 49, 'The volume of a cylinder having base radius 3 cm is $ 396 \, \text{cm}^3 $. Find its curved surface area (in $ \text{cm}^2 $).

(Use $ \pi = \frac{22}{7} $)', '[{"id":"A","text":"280"},{"id":"B","text":"301.5"},{"id":"C","text":"264"},{"id":"D","text":"320.6"}]', 0, 'C', 'Given:

Volume of cylinder = 396 cm³

Radius (r) = 3 cm

$ \pi = 22/7 $

Formula used:

Volume of cylinder = $ \pi \times r^{2} \times h $

Curved Surface Area (CSA) = $ 2 \times \pi \times r \times h $

Calculation:

396 = $ (22/7) \times 3^{2} \times h $

$ \Rightarrow 396 = (22/7) \times 9 \times h $

$ \Rightarrow 396 = (198/7) \times h $

$ \Rightarrow h = (396 \times 7) \div 198 = 2772 \div 198 = 14 \, cm $

CSA = $ 2 \times (22/7) \times 3 \times 14 $

$ \Rightarrow $ CSA = $ 2 \times (22/7) \times 42 = (44 \times 42) \div 7 = 1848 \div 7 = 264 \, cm^{2} $

$ \therefore $ Curved Surface Area = $ \underline{\text{264 cm²}} $', NULL, 'null', '[]', '[]', '[64]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1473, 'general-test-2024-05-15-shift-3', 'q57', 50, 50, 'A tap can fill a tank in 6 hours. After half the tank is filled, three more similar taps are opened. What is the total time taken to fill the tank completely?', '[{"id":"A","text":"4 hours"},{"id":"B","text":"5 hours"},{"id":"C","text":"3 hours 30 minutes"},{"id":"D","text":"3 hours 45 minutes"}]', 0, 'D', 'Given:

1 tap fills the tank in 6 hours.

After half the tank is filled, 3 more similar taps are opened (total 4 taps).

Calculation:

Total capacity of tank = LCM of 6 = 6 units

$ \Rightarrow $ 1 tap fills $ 6 \div 6 = 1 $ unit per hour

Half of the tank = 3 units

Time taken by 1 tap to fill 3 units = $3 \div 1 = 3$ hours

Now 4 taps work together

4 taps fill = 4 × 1 = 4 units per hour

Remaining = 3 units

Time = 3 ÷ 4 = 3/4 hour = 45 minutes

Total time = 3 hours + 45 minutes = $ \underline{\text{3 hours 45 minutes}} $', NULL, 'null', '[]', '[]', '[66]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1474, 'general-test-2024-05-15-shift-3', 'q58', 51, 51, 'A train running at the speed of 80 km/h crosses a 350 m long tunnel in 36 seconds. The length of the train (in m) is', '[{"id":"A","text":"350"},{"id":"B","text":"380"},{"id":"C","text":"420"},{"id":"D","text":"450"}]', 0, 'D', 'Given:

Speed of train = 80 km/h

Time to cross tunnel = 36 seconds

Length of tunnel = 350 m

Formula used:

Speed = Distance ÷ Time

Total distance = Length of train + Length of tunnel

Calculation:

Convert speed to m/s

80 km/h = (80 × 1000) ÷ 3600 = 80000 ÷ 3600 = 22.22 m/s

Total distance = Speed × Time = 22.22 × 36 ≈ 800 m

Length of train = Total distance - Tunnel length = 800 - 350 = 450 m

∴ Length of the train is $ \underline{\text{450 metres}} $', NULL, 'null', '[]', '[]', '[67]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1475, 'general-test-2024-05-15-shift-3', 'q59', 52, 52, 'If the mean of 3, 4, 9, 2k, 10, 8, 6 and $ (k+6) $ is 8, and mode of 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5 and 6 (p is a natural number) is 4, then the value of $ (k-2p) $ is :', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"2"},{"id":"D","text":"3"}]', 0, 'C', 'Given:
Mean of: 3, 4, 9, 2k, 10, 8, 6, $ (k+6)=8 $
Mode of: 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5, 6 = 4
Formula used:
Mean = (Sum of all terms) ÷ (Number of terms)
Mode = Value occurring most frequently
Calculation:
Solve for k
Sum = 3 + 4 + 9 + 2k + 10 + 8 + 6 + (k + 6) = 46 + 3k
Mean = $ (46 + 3k) \div 8 = 8 $
$ \Rightarrow 46 + 3k = 64 $
$ \Rightarrow 3k = 18 $
$ \Rightarrow k = 6 $
Solve for p
Numbers: 2, 2, 3, 2p, $ (2p+1) $, 4, 4, 5, 6
Mode is $ 4 \Rightarrow 4 $ must occur most frequently

Try p = 1 ⇒ 2p = 2, 2p+1 = 3 ⇒ list: 2, 2, 3, 2, 3, 4, 4, 5, 6

2 occurs 3 times ⇒ mode = 2

Try p = 2 ⇒ 2p = 4, 2p+1 = 5 ⇒ list: 2, 2, 3, 4, 5, 4, 4, 5, 6

4 occurs 3 times ⇒ mode = 4

⇒ p = 2

Find k - 2p:

k = 6, p = 2 ⇒ k - 2p = 6 - 4 = 2

∴ The value of (k - 2p) is 2', NULL, 'null', '[]', '[]', '[67]', 'keyed', '[]', '2026-11-05T20:58:44.402Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1476, 'general-test-2024-05-15-shift-3', 'q60', 53, 53, 'In triangle ABC, points D and E are on AB and AC respectively such that DE is parallel to BC. If AD = 6 cm, DB = 4 cm, AE = 9 cm, then the length of EC (in cm) is', '[{"id":"A","text":"7"},{"id":"B","text":"6.4"},{"id":"C","text":"6"},{"id":"D","text":"5.5"}]', 0, 'C', 'Given:

In triangle ABC:

Points D and E lie on AB and AC respectively

DE $ \parallel $ BC

AD = 6 cm, DB = 4 cm $ \Rightarrow $ AB = AD + DB = 10 cm

AE = 9 cm
Concept used:

By Basic Proportionality Theorem (Thales'' Theorem):

If a line is drawn parallel to one side of a triangle intersecting the other two sides, then it divides those sides in the same ratio.
Formula used:

AD/DB=AE/EC

Calculation:

$$ 6\ /4=9\ /EC $$

$ \Rightarrow 3/2 = 9/EC $

$ \Rightarrow EC = (2 \times 9) \div 3 = 18 \div 3 = 6 \, \text{cm} $

$ \therefore $ The length of EC is $ \underline{6} $ cm', NULL, 'null', '[]', '[]', '[69]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1477, 'general-test-2024-05-29-shift-1', 'q01', 1, 1, 'The sum of the digits of a two-digit number is 10. If 18 is subtracted from it, the digits in the resulting number will be equal. The number is :', '[{"id":"A","text":"75"},{"id":"B","text":"73"},{"id":"C","text":"65"},{"id":"D","text":"64"}]', 0, 'D', 'Given:

The sum of the digits of a two-digit number is 10.

If 18 is subtracted from it, the digits in the resulting number will be equal.

Formula Used:

Let the two-digit number be $ 10a + b $, where a and b are the digits of the number.

a + b = 10

(10a + b) - 18 = 10b + a
Calculation:

From the second equation:

10a + b - 18 = 10b + a

⇒ 10a - a + b - 10b = 18
⇒ 9a - 9b = 18
⇒ a - b = 2
Now, we have two equations:
1) a + b = 10
2) a - b = 2
Adding these two equations:
a + b + a - b = 10 + 2
⇒ 2a = 12
⇒ a = 6
Substitute a = 6 in equation 1:
6 + b = 10
⇒ b = 4
The number is 10a + b = 10×6 + 4 = 64
The number is 64.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1478, 'general-test-2024-05-29-shift-1', 'q02', 2, 2, 'In the given question, a statement is given followed by some conclusions. Choose the conclusion(s) which logically follow(s) the given statement.

Statement: Few shops on this road have neon lights, but they all have signboards.
Conclusions :

I. Some shops have either signboards or neon lights.

II. Some shops have no signboards.

III. Some shops have no neon lights.

IV. Some shops have both signboards and neon lights.

The conclusion(s) correctly drawn is/are :', '[{"id":"A","text":"IV alone"},{"id":"B","text":"I alone"},{"id":"C","text":"II and III"},{"id":"D","text":"III and IV"}]', 0, 'D', 'Given.

Statement:

Few shops on this road have neon lights, but they all have signboards.
Conclusions:

I. Some shops have either signboards or neon lights. - False(Because the statement says that Few shops on this road have neon lights, but they all have signboards. Therefore, all shops have signboards, and some of those shops have neon lights.)

II. Some shops have no signboards. - False (Because, the statement says that all shops have signboards.)

III. Some shops have no neon lights. - True (Because, the statement says that only a few shops have neon lights, implying that some shops do not have neon lights.)

IV. Some shops have both signboards and neon lights. - True (Because, the statement says that all shops have signboards and few have neon lights. Therefore, some shops have both signboards and neon lights)

So, Conclusions I, III and IV follow.

Hence, the correct answer is "Option 4" (III and IV).', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1479, 'general-test-2024-05-29-shift-1', 'q03', 3, 3, 'Anubhav spent 14% of his income on electricity bills, 28% on rent and 18% on shopping. If $ \frac{1}{4} $th remaining amount is Rs. 5120, how much did he spend on electricity bills?', '[{"id":"A","text":"Rs.7160"},{"id":"B","text":"Rs.7168"},{"id":"C","text":"Rs.8160"},{"id":"D","text":"Rs.9000"}]', 0, 'B', 'Anubhav spent 14% of his income on electricity bills, 28% on rent, and 18% on shopping.

$ \frac{1}{4} $th of the remaining amount is Rs. 5120.

Formula Used:

Total Income = Total Expenses + Remaining Amount

Remaining Amount = Total Income - (Electricity Bills + Rent + Shopping)

Electricity Bills = 14% of Total Income

Calculation:

Let Anubhav''s total income be x.

Expenses on electricity bills = 14% of x = 0.14x

Expenses on rent = 28% of x = 0.28x

Expenses on shopping = 18% of x = 0.18x

Remaining Amount = x - (0.14x + 0.28x + 0.18x)

Remaining Amount = x - 0.60x = 0.40x

$ \frac{1}{4} $th of Remaining Amount = Rs. 5120

$ \frac{1}{4} $ $ \times $ 0.40x = 5120

$ 0.10x = 5120 $

$ \Rightarrow x = 5120 / 0.10 $

$ \Rightarrow x = 51200 $

Anubhav''s total income = Rs. 51200

Expenses on electricity bills = 14% of 51200

$ \Rightarrow 0.14 \times 51200 = 7168 $

Therefore, Anubhav spent Rs. 7168 on electricity bills.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1480, 'general-test-2024-05-29-shift-1', 'q04', 4, 4, 'If the average of p numbers is $ q^2 $ and that of q numbers is $ p^2 $, then the average of $ (p + q) $ numbers is :', '[{"id":"A","text":"$ \\frac{p}{q} $"},{"id":"B","text":"$ p + q $"},{"id":"C","text":"pq"},{"id":"D","text":"p - q"}]', 0, 'C', 'Given:

The average of p numbers = q^{2}

The average of q numbers = p^{2}

Formula Used:

Average of $ (p + q) $ numbers = (Sum of p numbers + Sum of q numbers) / (p + q)

Calculation:

Sum of p numbers = $ p \times q^{2} $

Sum of q numbers = q × p²

Total Sum = p × q² + q × p²

Total numbers = p + q

Average of (p + q) numbers = (p × q² + q × p²) / (p + q)

Average of (p + q) numbers = pq(p + q) / (p + q)

Average of (p + q) numbers = pq

The correct answer is option 3.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1481, 'general-test-2024-05-29-shift-1', 'q05', 5, 5, 'Ajay walks at a speed of 4 km/hr. He doubles his speed after reaching exactly half way. He walks for 12 hours in all. What is the total distance travelled by him?', '[{"id":"A","text":"32 km"},{"id":"B","text":"30 km"},{"id":"C","text":"64 km"},{"id":"D","text":"60 km"}]', 0, 'C', 'Given:

Ajay''s initial speed = 4 km/hr

Total time walked = 12 hours

He doubles his speed after reaching halfway.

Formula Used:

Total Distance = Distance at initial speed + Distance at doubled speed
Calculation:

Let the total distance be D km.
Time to cover the first half (D/2) at 4 km/hr:
Time = Distance / Speed
Time $ _{1} $ = (D/2) / 4
Time $ _{1} $ = D / 8
Time to cover the second half (D/2) at 8 km/hr:
Time $ _{2} $ = (D/2) / 8
Time $ _{2} $ = D / 16
Total time walked = Time $ _{1} $ + Time $ _{2} $
12 = D / 8 + D / 16
$ \Rightarrow $ 12 = (2D + D) / 16
$ \Rightarrow $ 12 = 3D / 16
$ \Rightarrow $ 12 $ \times $ 16 = 3D
$ \Rightarrow $ 192 = 3D
$ \Rightarrow $ D = 192 / 3
$ \Rightarrow $ D = 64 km
The total distance travelled by Aiay is 64 km.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1482, 'general-test-2024-05-29-shift-1', 'q07', 6, 6, 'A shopkeeper earned a profit (in ₹) by selling an item, which is three times the discount offered (in ₹). If the discount offered is 6.25%, what is his profit percentage?', '[{"id":"A","text":"20%"},{"id":"B","text":"25%"},{"id":"C","text":"10%"},{"id":"D","text":"12%"}]', 0, 'B', 'Given:
Discount % = 6.25%
Profit = $ 3 \times $ Discount
Formula used:
Profit % = $ \frac{Profit}{CostPrice} \times 100 $
Calculation:
Let MRP = ₹100
Discount = 6.25% of 100 = ₹6.25
Selling Price = 100 - 6.25 = ₹93.75
Profit = $ 3 \times 6.25 = 18.75 $
Cost Price = 93.75 - 18.75 = ₹75
Profit % = $ \frac{18.75}{75} \times 100 $
⇒ Profit % = 25%
∴ The correct answer is option (2).', NULL, 'null', '[]', '[]', '[8]', 'keyed', '[]', '2026-11-05T20:58:44.403Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1483, 'general-test-2024-05-29-shift-1', 'q08', 7, 7, 'The total population of a town is 50,000. The number of males and females increases by 10% and 15% respectively and consequently the

population of the town becomes 56,000. What was the number of males in the town?', '[{"id":"A","text":"20,000"},{"id":"B","text":"30,000"},{"id":"C","text":"35,000"},{"id":"D","text":"40,000"}]', 0, 'B', 'Given:

Total population of the town = 50,000

Population after increase = 56,000

Increase in males = 10%

Increase in females = 15%

Calculation:

Let the number of males be M.

Let the number of females be F.

Total population: $ M + F = 50,000 $

After increase: $ M \times 1.10 + F \times 1.15 = 56,000 $

We have two equations:

1) $ M + F = 50,000 $

2) $ 1.10M + 1.15F = 56,000 $

From equation (1): $ F = 50,000 - M $

Substitute F in equation (2):

$ 1.10M + 1.15(50,000 - M) = 56,000 $

Simplify:

$ 1.10M + 57,500 - 1.15M = 56,000 $

$$ \Rightarrow-0.05M+57,500=56,000 $$

$$ \Rightarrow-0.05\mathrm{M}=56,000-57,500 $$

$$ \Rightarrow-0.05M=-1,500 $$

$$ \Rightarrow\mathrm{M}=-1,500\ /-0.05 $$

$$ \Rightarrow M=30,000 $$

The number of males in the town was 30,000.', NULL, 'null', '[]', '[]', '[9]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1484, 'general-test-2024-05-29-shift-1', 'q09', 8, 8, 'A 6-digit number has digits as consecutive natural numbers. The number is always divisible by :', '[{"id":"A","text":"3"},{"id":"B","text":"4"},{"id":"C","text":"5"},{"id":"D","text":"2"}]', 0, 'A', 'Given:

A 6-digit number is formed using consecutive natural numbers.

Formula used:

Any number with digits as consecutive natural numbers (e.g., 123456, 234567, etc.) follows a pattern and must be tested for divisibility.

Calculation:

Take example: 123456

Check divisibility:

$ 123456 \div 3 = 41152 \rightarrow \text{divisible} $

123456 ÷ 6 = 20576 → divisible

123456 ÷ 9 = 13717.33 → not divisible

Try another: 234567

234567 ÷ 3 = 78189 → divisible

234567 ÷ 6 = 39094.5 → not divisible

So only consistent divisibility for all such numbers is by 3

∴ The correct answer is option (2) 3.', NULL, 'null', '[]', '[]', '[11]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1485, 'general-test-2024-05-29-shift-1', 'q10', 9, 9, 'The average of 101 consecutive odd numbers is 303. Find the largest number.', '[{"id":"A","text":"373"},{"id":"B","text":"401"},{"id":"C","text":"403"},{"id":"D","text":"409"}]', 0, 'C', 'Given:

Average of 101 consecutive odd numbers = 303

Formula used:

Average = Middle term (when count is odd)

Largest number = Middle term + (n - 1)/2 × 2

Calculation:

Middle term = 303

Total numbers = 101

⇒ Largest number = 303 + (101 - 1)/2 × 2
⇒ Largest number = 303 + 50 × 2
⇒ Largest number = 303 + 100
⇒ Largest number = 403
∴ The correct answer is 403.', NULL, 'null', '[]', '[]', '[12]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1486, 'general-test-2024-05-29-shift-1', 'q11', 10, 10, 'If A : B = 5 : 6 and B : C = 6 : 7, then A + B : B + C : A + C is :', '[{"id":"A","text":"10:12:11"},{"id":"B","text":"9:11:10"},{"id":"C","text":"11:13:12"},{"id":"D","text":"19:21:20"}]', 0, 'C', 'Given:
If A : B = 5 : 6 and B : C = 6 : 7,
Formula Used:
If A : B = p : q and B : C = r : s, then A : B : C = p : q : (qs / r)
Calculation:
A : B = 5 : 6
B : C = 6 : 7
$ \Rightarrow $ A : B : C = 5 : 6 : (7)
Let A = 5k, B = 6k, C = 7k
$ \Rightarrow $ A + B = 5k + 6k = 11k

⇒ B + C = 6k + 7k = 13k

⇒ A + C = 5k + 7k = 12k

Therefore, A + B : B + C : A + C = 11k : 13k : 12k

⇒ A + B : B + C : A + C = 11 : 13 : 12

The correct answer is option 3: 11 : 13 : 12', NULL, 'null', '[]', '[]', '[13]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1487, 'general-test-2024-05-29-shift-1', 'q12', 11, 11, 'Aman can do 50% of the job in 16 days, and Bhanu can do 25% of the job in 24 days. In how many days can they do $ \frac{1}{4} $th of the job working together?', '[{"id":"A","text":"6 days"},{"id":"B","text":"8 days"},{"id":"C","text":"10 days"},{"id":"D","text":"12 day"}]', 0, 'A', 'Given:

Aman does 50% job in 16 days $ \Rightarrow $ 100% in 32 days

Bhanu does 25% job in 24 days $ \Rightarrow $ 100% in 96 days

Formula used:

Work together rate = $ (1/Aman''s\ time)+(1/Bhanu''s\ time) $

Time = Work / Rate

Calculation:

Aman''s 1 day work = 1/32

Bhanu''s 1 day work = 1/96
⇒ Combined 1 day work = 1/32 + 1/96
⇒ LCM of 32 and 96 = 96
⇒ $ (3 + 1)/96 = 4/96 = 1/24 $
They complete 1/24 of job per day
Time to do 1/4 of job = $ (1/4) \div (1/24) $
$ \Rightarrow 1/4 \times 24 = 6 $ days
∴ The correct answer is 6 days.', NULL, 'null', '[]', '[]', '[14]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1488, 'general-test-2024-05-29-shift-1', 'q13', 12, 12, 'In 80 litres mixture of milk and water, the ratio of amount of milk to that of amount of water is 7 : 3. In order to make this ratio 2 : 1, how many litres of water should be added?', '[{"id":"A","text":"5 litres"},{"id":"B","text":"6 litres"},{"id":"C","text":"4 litres"},{"id":"D","text":"10 litres"}]', 0, 'C', 'Given:

Total mixture = 80 litres

Milk : Water = 7 : 3

Target ratio = 2 : 1

Formula used:

Milk quantity remains unchanged, only water is added

Calculation:

Milk = (7/10) × 80 = 56 litres
Water = (3/10) × 80 = 24 litres
Let x litres of water be added
⇒ New water = 24 + x
⇒ New ratio = 56 : (24 + x) = 2 : 1
⇒ 56 / (24 + x) = 2 / 1
⇒ 56 = 2 × (24 + x)
⇒ 56 = 48 + 2x
⇒ 2x = 8
⇒ x = 4
∴ The correct answer is 4 litres.', NULL, 'null', '[]', '[]', '[15]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1489, 'general-test-2024-05-29-shift-1', 'q14', 13, 13, 'In a triangle PQR, if $ \angle P + \angle R = 150^\circ $ and $ \angle P + 3\angle Q = 170^\circ $, then $ \angle P $ is equal to :', '[{"id":"A","text":"$70^{\\circ}$"},{"id":"B","text":"$80^{\\circ}$"},{"id":"C","text":"$75^{\\circ}$"},{"id":"D","text":"$65^{\\circ}$"}]', 0, 'B', 'Given:

In a triangle PQR, if $ \angle P + \angle R = 150^\circ $ and $ \angle P + 3\angle Q = 170^\circ $
Formula Used:

Sum of all angles in a triangle = $ 180^{\circ} $

Calculation:

Let \angle P = P, \angle Q = Q, and \angle R = R

Given:

$ P + R = 150^{\circ} \ldots (i) $

$ P + 3Q = 170^{\circ} \ldots (ii) $

From the sum of angles in a triangle:

$ P + Q + R = 180^{\circ} \ldots (iii) $

From (i), $ R = 150^{\circ} - P $

Substitute R in (iii):

$ P + Q + (150^{\circ} - P) = 180^{\circ} $

$ Q = 30^{\circ} $

Substitute Q in (ii):

$ P + 3 \times 30^{\circ} = 170^{\circ} $

$ P + 90^{\circ} = 170^{\circ} $

$ P = 80^{\circ} $

Therefore, \angle P is equal to 80^{\circ}.', NULL, 'null', '[]', '[]', '[16]', 'keyed', '[]', '2026-11-05T20:58:44.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1490, 'general-test-2024-05-29-shift-1', 'q15', 14, 14, 'Aman invested Rs. (P + 3000) for 3 years at 8% simple interest. Anuj invested an amount of Rs. P for 2 years at 12% compound interest and received the same amount of interest as Aman received. Find the amount that is invested by Anuj.', '[{"id":"A","text":"$ \\Re"},{"id":"B","text":"\\Re"},{"id":"C","text":"\\Re"},{"id":"D","text":"\\Re $"}]', 0, 'C', 'Given:
Aman''s investment = (P + 3000)
Time = 3 years, Rate = 8% (Simple Interest)
Anuj''s investment = P
Time = 2 years, Rate = 12% (Compound Interest)
Interest earned by both is same
Formula used:
SI = (P × R × T)/100
CI = P(1 + $ \frac{r}{100} $)^t - 1
Calculation:
Aman''s SI = (P + 3000) × 8 × 3 / 100
$ \Rightarrow $ Aman''s SI = (P + 3000) × 24 / 100
$ \Rightarrow $ Aman''s SI = (24P + 72000)/100
Anuj''s CI = P × [(1 + 12/100)^2 - 1]
$ \Rightarrow $ CI = P × [(1.12)^2 - 1]
$ \Rightarrow $ CI = P × [1.2544 - 1] = P × 0.2544
Equating both:
$ \Rightarrow $ (24P + 72000)/100 = 0.2544P
$ \Rightarrow $ 24P + 72000 = 25.44P
$ \Rightarrow $ 72000 = 25.44P - 24P
$ \Rightarrow $ 72000 = 1.44P
$ \Rightarrow $ P = 72000 / 1.44
$ \Rightarrow $ P = 50000', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1491, 'general-test-2024-05-29-shift-1', 'q16', 15, 15, 'In the Delhi zoo, there are some ducks and rabbits. If the heads are counted there are 160, while the legs are 450. What will be number of ducks in the zoo?', '[{"id":"A","text":"90"},{"id":"B","text":"92"},{"id":"C","text":"95"},{"id":"D","text":"99"}]', 0, 'C', 'Given:
Total heads = 160
Total legs = 450
Ducks have 2 legs, Rabbits have 4 legs
Formula used:
Let number of ducks = x, then rabbits = 160 - x
Total legs = (Ducks $ \times $ 2) + (Rabbits $ \times $ 4)
Calculation:
$ \Rightarrow 2x + 4(160 - x) = 450 $
$ \Rightarrow 2x + 640 - 4x = 450 $
$ \Rightarrow -2x + 640 = 450 $
$ \Rightarrow -2x = 450 - 640 $

$ \Rightarrow -2x = -190 $

$ \Rightarrow x = 95 $

∴ The number of ducks is 95.', NULL, 'null', '[]', '[]', '[19]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1492, 'general-test-2024-05-29-shift-1', 'q17', 16, 16, 'Ankit and Raju decided to start a business and they invested Rs. 5500 and Rs. 6500 respectively. After 11 months, the difference between their profits is Rs. 680. Find the total profit.', '[{"id":"A","text":"Rs.8160"},{"id":"B","text":"Rs.7260"},{"id":"C","text":"Rs.7000"},{"id":"D","text":"Rs.6500"}]', 0, 'A', 'Given:

Ankit''s investment = ₹5500

Raju''s investment = ₹6500

Time = 11 months for both

Difference in profit = ₹680

Formula used:

Profit share ∝ Investment × Time

Difference in profit = (Raju''s share - Ankit''s share)

Calculation:

Ankit''s share = 5500 \times 11 = 60500

Raju''s share = 6500 \times 11 = 71500

Ratio = $ \frac{60500}{71500} = 121 : 143 $

Difference in ratio = 143 - 121 = 22 parts

$ \Rightarrow $ 22 parts = ₹680

$ \Rightarrow $ 1 part = ₹680 ÷ 22 = ₹30.91

Total parts = 121 + 143 = 264

Total profit = 264 $ \times $ 30.91 = ₹8160.24

∴ The total profit is approximately ₹8160', NULL, 'null', '[]', '[]', '[20]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1493, 'general-test-2024-05-29-shift-1', 'q18', 17, 17, 'PQR is a triangle. The bisectors of the internal angle $\angle Q$ and external angle $\angle R$ intersect at M. If $\angle QMR = 40^{\circ}$, then $\angle P$ is :', '[{"id":"A","text":"$ 75^{\\circ} $"},{"id":"B","text":"$ 60^{\\circ} $"},{"id":"C","text":"$ 65^{\\circ} $"},{"id":"D","text":"$ 80^{\\circ} $"}]', 0, 'D', 'Given:

$ \angle QMR = 40^{\circ} $, MQ and MR are internal and external angle bisectors

Formula used:

Triangle angle sum = $ \angle P + \angle Q + \angle R = 180^\circ $

Calculation:

$$ \angle QMR=\frac{1}{2}(\angle Q+180^\circ-\angle R) $$

$$ \Rightarrow40^{\circ}=\frac{1}{2}(\angle Q+180^{\circ}-\angle R) $$

$$ \Rightarrow80^{\circ}=\angle Q+180^{\circ}-\angle R $$

$$ \Rightarrow\angle Q=\angle R-100^{\circ} $$

$$ \Rightarrow\angle P+\angle Q+\angle R=180^{\circ} $$

$$ \Rightarrow\angle P+(\angle R-100^{\circ})+\angle R=180^{\circ} $$

$$ \Rightarrow\angle P=280^{\circ}-2\angle R $$

Let $\angle R = 100^{\circ}$, then $\angle P = 280^{\circ} - 200^{\circ} = 80^{\circ}$

∴ The correct answer is $ \angle P = 80^{\circ} $', NULL, 'null', '[]', '[]', '[21]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1494, 'general-test-2024-05-29-shift-1', 'q19', 18, 18, 'What is the name of the alloy which is obtained after mixing mercury with another metal?', '[{"id":"A","text":"Solder"},{"id":"B","text":"Amalgam"},{"id":"C","text":"Duralumin"},{"id":"D","text":"Pewter"}]', 0, 'B', 'The correct answer is $ \underline{\text{Amalgam}} $.
Key Points

• An amalgam is an alloy of mercury with one or more other metals.

- These alloys are formed through the process of amalgamation, where mercury reacts with other metals.

• Amalgams are commonly used in dental fillings due to their durability and ease of application.

• They are also used in the extraction of precious metals like gold and silver from their ores.

- The use of amalgams dates back to ancient times and has been pivotal in various industrial applications.
Additional Information

• $ \underline{\text{Solder}} $

Solder is a fusible metal alloy used to join metal workpieces together.

o It typically consists of a combination of tin and lead, although other metals can be used.

- Solder is widely used in electronics to create strong, conductive joints.

• Duralumin

o Duralumin is an alloy primarily composed of aluminum and copper, with small amounts of manganese, magnesium, and iron.

o It is known for its lightweight and high strength, making it ideal for aerospace applications.

• $ \underline{\text{Pewter}} $

o Pewter is a malleable metal alloy, traditionally composed of tin with copper, antimony, and sometimes bismuth.

o It has been used for tableware and decorative objects for centuries.', NULL, 'null', '[]', '[]', '[22]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1495, 'general-test-2024-05-29-shift-1', 'q22', 19, 19, 'Which state became the 25^{th} state of India on 30th May, 1987?', '[{"id":"A","text":"Telangana"},{"id":"B","text":"Haryana"},{"id":"C","text":"Gujarat"},{"id":"D","text":"Goa"}]', 0, 'D', 'Key Points

• Goa became the 25th state of India on 30th May 1987.

• Prior to this, Goa was a Union Territory along with Daman and Diu.

• On 30th May 1987, Goa was granted statehood, while Daman and Diu remained a Union Territory.

• It is the smallest state in India by area and the fourth smallest by population.

• Goa is known for its tourism, with its beaches, Portuguese heritage, and vibrant culture.

• The capital of Goa is Panaji, and its largest city is Vasco da Gama.
Additional Information

• Telangana

Telangana was formed on 2nd June 2014, making it the 29th state of India.

o It was carved out of the northwestern part of Andhra Pradesh.

o The capital city is Hyderabad.

• $ \underline{\text{Haryana}} $

Haryana was formed on 1st November 1966.

o It was carved out from the state of Punjab.

o The capital city is Chandigarh, which is also the capital of Punjab.

• $ \underline{\text{Gujarat}} $

o Gujarat was formed on 1st May 1960.

o It was created out of the state of Bombay.

o The capital city is Gandhinagar.', NULL, 'null', '[]', '[]', '[25]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1496, 'general-test-2024-05-29-shift-1', 'q23', 20, 20, 'Which of these temples is not located in Uttarakhand?', '[{"id":"A","text":"Nanda Devi"},{"id":"B","text":"Surkanda Devi"},{"id":"C","text":"Kalighat Kali"},{"id":"D","text":"Tungnath"}]', 0, 'C', 'The Correct answer is $ \underline{\text{Kalighat Kali}} $.
Key Points

• Kalighat Kali temple is located in Kolkata, West Bengal, and not in Uttarakhand.

• It is one of the 51 Shakti Peethas in India, dedicated to Goddess Kali.

• The temple is situated on the banks of the Adi Ganga, a small canal that connects to the Hooghly River.

- Kalighat is an important pilgrimage site and is believed to be over 200 years old.

• The temple attracts millions of devotees each year, especially during the festival of Kali Puja.
Additional Information

• Nanda Devi

o Nanda Devi temple is located in Uttarakhand, India.

o The temple is dedicated to Goddess Nanda Devi, the presiding deity of the region.

It is a significant part of the Nanda Devi Raj Jat Yatra, a grand pilgrimage that takes place every 12 years.

• Surkanda Devi

o The Surkanda Devi temple is located near Dhanaulti in Uttarakhand.

o It is dedicated to Goddess Parvati and is part of the Kedarkhand region of the Skanda Purana.

The temple offers a panoramic view of the Himalayas and is accessible after a 2 km trek from the village of Kaddukhal.

• Tungnath

Tungnath is one of the highest Shiva temples in the world and is located in the Rudraprayag district of Uttarakhand.

o It is part of the Panch Kedar pilgrimage circuit.

Legend has it that the temple was built by the Pandavas to atone for their sins after the Kurukshetra war.', NULL, 'null', '[]', '[]', '[26]', 'keyed', '[]', '2026-11-05T20:58:44.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1497, 'general-test-2024-05-29-shift-1', 'q24', 21, 21, 'Which of these states do not share a border with Chhattisgarh?', '[{"id":"A","text":"Karnataka"},{"id":"B","text":"Madhya Pradesh"},{"id":"C","text":"Telangana"},{"id":"D","text":"Jharkhand"}]', 0, 'A', 'The Correct answer is $ \underline{\text{Karnataka}} $.
Key Points

• Chhattisgarh is a state located in central India and shares its borders with several states.

- The states that share a border with Chhattisgarh are Madhya Pradesh to the northwest, Uttar Pradesh to the north, Jharkhand to the northeast, Odisha to the east, Telangana to the south, and Maharashtra to the southwest.

• Karnataka is located in the southwestern region of India and does not share a border with Chhattisgarh.

Understanding the geographical boundaries and neighboring states is crucial for various competitive exams.
Additional Information

• Madhya Pradesh

o Madhya Pradesh is a state located in the central part of India.

o It shares its borders with Chhattisgarh to the southeast.

• $ \underline{\text{Telangana}} $

o Telangana is a state in southern India.

o It shares its northern border with Chhattisgarh.

• $ \underline{\text{Jharkhand}} $

o Jharkhand is a state located in eastern India.

o It shares its western border with Chhattisgarh.', NULL, 'null', '[]', '[]', '[27]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1498, 'general-test-2024-05-29-shift-1', 'q25', 22, 22, 'Which bowler became second Indian bowler to take 500 wickets in Test matches in February, 2024?', '[{"id":"A","text":"Harbhajan Singh"},{"id":"B","text":"Ravichandran Ashwin"},{"id":"C","text":"Ishant Sharma"},{"id":"D","text":"Mohammed Shami"}]', 0, 'B', 'The Correct answer is $ \underline{\text{Ravichandran Ashwin}} $.
Key Points

• Ravichandran Ashwin is an Indian international cricketer.

• He became the second Indian bowler to take 500 wickets in Test matches in February 2024.

- He is a right-arm off-break bowler known for his skill and variations.

He has been a crucial part of the Indian Test team and has performed consistently over the years.

- In addition to his bowling, Ashwin is also a useful lower-order batsman, making him a valuable all-rounder for the team.

His achievement places him among the elite bowlers in the history of cricket.
Additional Information

• Harbhajan Singh

o Harbhajan Singh is a former Indian cricketer and an off-spin bowler.

o He was the first Indian bowler to take 400 Test wickets.

o Harbhajan has been known for his aggressive and passionate style of play.

• Ishant Sharma

o Ishant Sharma is a right-arm fast bowler for the Indian cricket team.

o He is known for his height and ability to extract bounce from the pitch.

o Ishant has been a key bowler for India in Test cricket, especially in overseas conditions.

Mohammed Shami

Mohammed Shami is an Indian international cricketer who bowls right-arm fast.

o He is known for his pace, swing, and seam movement.

o Shami has been a vital part of the Indian pace attack in both Test and limited-overs cricket.', NULL, 'null', '[]', '[]', '[28]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1499, 'general-test-2024-05-29-shift-1', 'q26', 23, 23, 'Which one of the following rivers is not included in ''Panchnad - The five rivers of Punjab''?', '[{"id":"A","text":"The Luni"},{"id":"B","text":"The Jhelum"},{"id":"C","text":"The Chenab"},{"id":"D","text":"The Sutlej"}]', 0, 'A', 'The correct answer is $ \underline{\text{The Luni}} $.
Key Points

• The Luni River is not included in the ''Panchnad'' - the five rivers of Punjab.

- Luni is a river in Rajasthan and is also known as the Sarasvati River in its upper course.

• The river is called Luni because of its high salinity.

- The Luni originates from the Naga hills in the Aravalli Range in Rajasthan and flows through the Thar Desert.

• It is an inland river that does not drain into any sea or ocean but ends in the Rann of Kutch.
Additional Information

• $ \underline{\text{The Jhelum}} $

o The Jhelum is one of the five rivers of Punjab.

- It originates from Verinag Spring at the foot of the Pir Panjal in the southeastern part of the Kashmir Valley.

o It flows through Kashmir and enters Pakistan.

• $ \underline{\text{The Chenab}} $

o The Chenab is another river included in the ''Panchnad''.

It is formed by the confluence of two rivers, Chandra and Bhaga, in the Lahaul and Spiti district of Himachal Pradesh.

o It flows through the Jammu region of Jammu and Kashmir.

• The Sutlej

The Sutlej is the longest of the five rivers that flow through the historic crossroad region of Punjab in northern India and Pakistan.

o It originates from Lake Rakshastal in Tibet.

o The Sutlej River merges with the Chenab River in Pakistan to form the Panjnad River.', NULL, 'null', '[]', '[]', '[29]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1500, 'general-test-2024-05-29-shift-1', 'q27', 24, 24, 'Where was the $ 15^{th} $ BRICS Summit-2023 organised?', '[{"id":"A","text":"South Africa"},{"id":"B","text":"Brazil"},{"id":"C","text":"Russia"},{"id":"D","text":"China"}]', 0, 'A', 'The Correct answer is $ \underline{\text{South Africa}} $.

Key Points

• The 15th BRICS Summit in 2023 was organized in South Africa.

• BRICS is an acronym for an association of five major emerging economies: Brazil, Russia, India, China, and South Africa.

• South Africa hosted the summit in the city of Johannesburg.

- This summit aimed at strengthening cooperation among the BRICS countries in various fields such as economy, trade, and political coordination.

• The summit also focused on the theme of "BRICS and Africa: Partnership for Mutually Accelerated Growth, Sustainable Development, and Inclusive Multilateralism".

• South Africa''s role in BRICS is significant as it represents the African continent in the group.
Additional Information

• $ \underline{\text{Brazil}} $

Brazil is a member of BRICS and is the largest country in South America.

o It hosted the BRICS Summit previously, with the most recent one being the 11th BRICS Summit in 2019.

• Russia

o Russia is a founding member of BRICS.

o It hosted the 12th BRICS Summit in 2020.

• China

China, a key member of BRICS, hosted the 14th BRICS Summit in 2022.

China is the world''s most populous country and the second-largest economy.', NULL, 'null', '[]', '[]', '[30]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1501, 'general-test-2024-05-29-shift-1', 'q28', 25, 25, 'Match List I with List II :', '[{"id":"A","text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)"},{"id":"B","text":"(A) - (III), (B) - (I), (C) - (IV), (D) - (II)"},{"id":"C","text":"(A) - (I), (B) - (IV), (C) - (III), (D) - (II)"},{"id":"D","text":"\\left(\\mathrm{A}\\right)-\\left(\\mathrm{II}\\right),\\left(\\mathrm{B}\\right)-\\left(\\mathrm{III}\\right),\\left(\\mathrm{C}\\right)-\\left(\\mathrm{IV}\\right),\\left(\\mathrm{D}\\right)-\\left(\\mathrm{I}\\right)"}]', 0, 'D', 'The Correct answer is $ (\underline{\mathbf{A}})_{-(\underline{\mathbf{II}}),-(\underline{\mathbf{B}})_{-(\underline{\mathbf{III}}),-(\underline{\mathbf{C}})_{-(\underline{\mathbf{IV}}),-(\underline{\mathbf{D}})_{-(\underline{\mathbf{I}}})} $.
Key Points

• TheRs. 10 notefeatures theKonark Sun Temple, which is a 13th-century temple located in thePuri district of Odisha.

- The Rs. 100 note showcases the Rani Ki Vav, which is an intricately constructed stepwell situated in Gujarat. This stepwell is also a UNESCO World Heritage Site.

- The Rs. 500 note depicts the Red Fort, a historic fort in the city of Delhi that served as the main residence of the Mughal Emperors.

• TheRs. 20 notefeatures theEllora Caves. The Ellora Caves are a UNESCO World Heritage Site located in the Aurangabad district of Maharashtra.
Additional Information

• Ellora Caves

The Ellora Caves represent one of the largest rock-cut monastery-temple cave complexes in the world.

o They feature artworks from Buddhism, Hinduism, and Jainism.

• Rani Ki Vav

o Rani Ki Vav is an exceptional example of a distinctive form of subterranean water architecture of the Indian subcontinent.

o It was built as a memorial to an 11th-century AD king.

• Red Fort

The Red Fort is a symbol of India''s sovereignty and is the location where the Prime Minister hoists the national flag on Independence Day.

o It was designated a UNESCO World Heritage Site in 2007.

• Konark Sun Temple

The Konark Sun Temple is designed in the shape of a gigantic chariot with intricately carved stone wheels, pillars, and walls.

o It is dedicated to the Hindu Sun God Surya.', NULL, 'null', '[]', '[{"id":"q28-table-1","kind":"table","path":"/local-papers/assets/general-test-2024-05-29-shift-1/q28-table-1.jpg","page":31,"alt":"Table for question 28"}]', '[31]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1502, 'general-test-2024-05-29-shift-1', 'q29', 26, 26, 'From the given options, name the longest river in Asia.', '[{"id":"A","text":"Yangtze River"},{"id":"B","text":"Lena River"},{"id":"C","text":"Indus River"},{"id":"D","text":"Brahmaputra River Answer: A"}]', 0, 'A', 'The Correct answer is $ \underline{\text{Yangtze River}} $.
Key Points

- Yangtze River is the longest river in Asia and the third-longest in the world, after the Nile and the Amazon.

• It has a total length of about 6,300 kilometers (3,917 miles).

- The river flows from the glaciers of the Qinghai-Tibet Plateau in China to the East China Sea at Shanghai.

- The Yangtze River basin is home to one-third of the population of China and is a major water source for agriculture, industry, and daily life.

- The river is also known for its diverse and rich ecosystem, which includes several endangered species like the Chinese alligator and the Yangtze river dolphin.

- It has significant historical and cultural importance in China, often referred to as the cradle of Chinese civilization.
Additional Information

• Lena River

o The Lena River is one of the longest rivers in the world and the longest river in Russia.

o It flows across eastern Siberia and eventually empties into the Arctic Ocean.

o The river has a length of about 4,400 kilometers (2,736 miles).

• Indus River

o The Indus River flows through China, India, and Pakistan.

o It is one of the longest rivers in the world, with a length of about 3,180 kilometers (1,976 miles).

o The river is crucial for agriculture and has been the cradle of the ancient Indus Valley Civilization.

• $ \underline{\text{Brahmaputra River}} $

o The Brahmaputra River flows through Tibet, India, and Bangladesh.

○ It has a length of about 2,900 kilometers (1,800 miles).

o The river is known for its strong currents and is also prone to flooding during the monsoon season.', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1503, 'general-test-2024-05-29-shift-1', 'q30', 27, 27, 'Arrange the following important days according to their chronological order from January to December:', '[{"id":"A","text":"Indian Airforce Day"},{"id":"B","text":"Kargil Victory Day"},{"id":"C","text":"World Soil Day"},{"id":"D","text":"National Youth Day E. International Women''s Day Select the correct answer from the options given below"}]', 0, 'B', 'The correct answer is $ \underline{\text{D - E - B - A - C}} $.
Key Points

• National Youth Day is observed on January 12. It marks the birth anniversary of Swami Vivekananda.

• International Women''s Day is celebrated on March 8 every year, highlighting the achievements and contributions of women globally.

• Kargil Victory Day is observed on July 26 to commemorate India''s victory over Pakistan in the Kargil War in 1999.

• Indian Airforce Day is celebrated on October 8 each year to mark the establishment of the Indian Air Force (IAF) in 1932.

- World Soil Day is observed on December 5 to raise awareness about the importance of soil health and sustainable management of soil resources.
Additional Information

• Swami Vivekananda

Swami Vivekananda was a key figure in the introduction of the Indian philosophies of Vedanta and Yoga to the Western world.

He is best known for his speech at the Parliament of the World''s Religions in Chicago in 1893, which began with "Sisters and brothers of America...".

• Indian Air Force

o The Indian Air Force (IAF) is the air arm of the Indian Armed Forces.

o Its primary mission is to secure Indian airspace and to conduct aerial warfare during armed conflict.

• $ \underline{\text{Kargil War}} $

o The Kargil War, also known as the Kargil conflict, was an armed conflict between India and Pakistan that took place between May and July 1999 in the Kargil district of Jammu and Kashmir.

During the conflict, the Indian Army, with the support of the Indian Air Force, recaptured most of the positions on the Indian side of the LOC (Line of Control) that had been occupied by Pakistani troops and militants.', NULL, 'null', '[]', '[]', '[33]', 'keyed', '[]', '2026-11-05T20:58:44.406Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1504, 'general-test-2024-05-29-shift-1', 'q31', 28, 28, 'Which Railway Minister from the following, resigned immediately after the 1956 Ariyalur train accident?', '[{"id":"A","text":"Jagjivan Ram"},{"id":"B","text":"Lal Bahadur Shastri"},{"id":"C","text":"S.K. Patil"},{"id":"D","text":"Lalit Narayan Mishra"}]', 0, 'B', 'The correct answer is $ \underline{\text{Lal Bahadur Shastri}} $.
Key Points

• Lal Bahadur Shastri was the Railway Minister of India during the Ariyalur train accident in 1956.

- The Ariyalur train accident occurred on November 23, 1956, in Tamil Nadu, resulting in significant casualties.

• As a mark of his moral responsibility, Lal Bahadur Shastri resigned from his position immediately after the accident.

His resignation was seen as a demonstration of ethical leadership and accountability.

- Lal Bahadur Shastri later became the Prime Minister of India from 1964 to 1966.
Additional Information

• $ \underline{\text{Jagjivan Ram}} $

○ Jagjivan Ram was a prominent Indian politician and a senior leader in the Indian National Congress.

o He served as the Deputy Prime Minister of India from 1977 to 1979.

• S.K. Patil

o S.K. Patil was an Indian politician and a senior leader of the Indian National Congress.

o He served as the Minister of Railways and the Minister of Food and Agriculture.

• Lalit Narayan Mishra

• Lalit Narayan Mishra was an Indian politician from the state of Bihar.

o He served as the Minister of Railways in the Government of India.

• Lalit Narayan Mishra was assassinated in 1975.', NULL, 'null', '[]', '[]', '[35]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1505, 'general-test-2024-05-29-shift-1', 'q32', 29, 29, 'Which of the following countries won the FIH Hockey Men''s World Cup 2023?', '[{"id":"A","text":"Germany"},{"id":"B","text":"Netherlands"},{"id":"C","text":"Belgium"},{"id":"D","text":"Australia"}]', 0, 'A', 'The Correct answer is $ \underline{\text{Germany}} $.
Key Points

• Germany won the FIH Hockey Men''s World Cup 2023.

• The tournament was held in Bhubaneswar and Rourkela, India.

Germany defeated Belgium in the final match to claim the title.

This victory marked Germany''s third title in the history of the FIH Hockey Men''s World Cup.

• The final score was 5-4 in a thrilling penalty shootout.

• Germany''s previous titles were won in 2002 and 2006.
Additional Information

• $ \underline{\text{Netherlands}} $

o The Netherlands has won the FIH Hockey Men''s World Cup three times (1973, 1990, 1998).

o The team is known for its strong performance in international hockey.

• $ \underline{\text{Belgium}} $

• Belgium was the runner-up in the 2023 tournament.

o They won their first FIH Hockey Men''s World Cup title in 2018.

• Australia

• Australia has won the FIH Hockey Men''s World Cup three times (1986, 2010, 2014).

o The team is one of the most successful in the history of the tournament.', NULL, 'null', '[]', '[]', '[36]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1506, 'general-test-2024-05-29-shift-1', 'q33', 30, 30, 'Who won the title of the $ 6^{th} $ Khelo India Youth Games 2024?', '[{"id":"A","text":"Haryana"},{"id":"B","text":"Maharashtra"},{"id":"C","text":"Karnataka"},{"id":"D","text":"Tamil Nadu"}]', 0, 'B', 'The correct answer is $ \underline{\text{Maharashtra}} $.
Key Points

• The Khelo India Youth Games is an annual event conducted by the Ministry of Youth Affairs and Sports in India.

• The aim of the games is to identify and nurture young sporting talent in the country.

• Maharashtra has consistently performed well in various editions of the Khelo India Youth Games.

- In the 6th edition held in 2024, Maharashtra emerged as the overall winner, showcasing exceptional talent across various sports disciplines.

- The event includes a wide range of sports, providing a platform for young athletes to compete at a national level.

Winning the title of the 6th Khelo India Youth Games is a testament to Maharashtra''s strong sporting infrastructure and effective youth sports development programs.
Additional Information
• $ \underline{\text{Haryana}} $

o Haryana is known for producing numerous athletes in sports like wrestling, boxing, and kabaddi.

Haryana has a strong tradition in sports and has performed well in previous editions of the Khelo India Youth Games.

• Karnataka

o Karnataka has been notable for its contributions in sports such as swimming, athletics, and hockey.

The state has a good sports infrastructure and has produced several national and international level athletes.

• $ \underline{\text{Tamil Nadu}} $

Tamil Nadu excels in sports like chess, athletics, and table tennis.

o The state has a robust sports culture and encourages youth participation in various sports activities.', NULL, 'null', '[]', '[]', '[37]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1507, 'general-test-2024-05-29-shift-1', 'q34', 31, 31, 'In January 2024, which Indian state was the host of the Purple Fest, the first inclusive festival for persons with disabilities?', '[{"id":"A","text":"Goa"},{"id":"B","text":"Gujarat"},{"id":"C","text":"Kerala"},{"id":"D","text":"Maharashtra"}]', 0, 'A', 'The correct answer is $ \underline{\text{Goa}} $.
Key Points

• Goa hosted the Purple Fest in January 2024.

• The Purple Fest is the first inclusive festival for persons with disabilities in India.

• The festival aimed to promote inclusivity and accessibility for individuals with disabilities.

• Various cultural, sports, and educational activities were organized as part of the festival.

- The event provided a platform for advocacy and awareness regarding the rights and needs of persons with disabilities.

- It was a significant step towards making Goa a more accessible and inclusive destination.
Additional Information
• $ \underline{\text{Gujarat}} $

o Gujarat is known for hosting the Vibrant Gujarat Global Summit, an international business summit.

o The state is famous for its rich cultural heritage and landmarks such as the Statue of Unity.

Kerala

• Kerala

o Kerala is renowned for its backwaters and Ayurvedic treatments.

o The state celebrates several festivals, including the famous Onam festival.

• Maharashtra

o Maharashtra is home to the bustling city of Mumbai, the financial capital of India.

o The state is also known for its historical sites like the Ajanta and Ellora Caves.', NULL, 'null', '[]', '[]', '[38]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1508, 'general-test-2024-05-29-shift-1', 'q35', 32, 32, 'In December 2023, Sultan Haitham bin Tarik was on a State visit to India. He is the Sultan and Prime Minister of which country?', '[{"id":"A","text":"Iran"},{"id":"B","text":"Yemen"},{"id":"C","text":"Qatar"},{"id":"D","text":"Oman"}]', 0, 'D', 'The correct answer is $ \underline{\text{Oman}} $.
Key Points

• Sultan Haitham bin Tarik is the current Sultan and Prime Minister of Oman.

He ascended to the throne on 11 January 2020, following the death of his cousin, Sultan Qaboos bin Said.

- Oman is a country located on the southeastern coast of the Arabian Peninsula in Western Asia.

- It shares land borders with the United Arab Emirates to the northwest, Saudi Arabia to the west, and Yemen to the southwest, and has maritime borders with Iran and Pakistan.

• The capital city of Oman is Muscat.

- Oman''s economy is primarily driven by oil and gas resources, but it is also diversifying into sectors like tourism, manufacturing, and logistics.

- Oman is known for its rich cultural heritage, historical sites, and beautiful landscapes, including deserts, mountains, and coastlines.
Additional Information
• $ \underline{\text{Iran}} $

Iran is a country in Western Asia, also known as Persia.

o Its capital is Tehran.

o Iran is an Islamic Republic and has significant oil and natural gas reserves.

• $ \underline{\text{Yemen}} $

o Yemen is located on the southern end of the Arabian Peninsula.

o Its capital city is Sana''a.

o Yemen has been experiencing a prolonged civil war since 2014.

• $ \underline{\text{Qatar}} $

o Qatar is a small but wealthy country in the Middle East, known for its reserves of natural gas and oil.

o Its capital is Doha.

Qatar will host the FIFA World Cup 2022.', NULL, 'null', '[]', '[]', '[39]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1509, 'general-test-2024-05-29-shift-1', 'q36', 33, 33, 'Which of the following states launched the ''Mukhyamantri Seekho-Kamao Yojana'' (MMSKY) in 2023?', '[{"id":"A","text":"Uttar Pradesh"},{"id":"B","text":"Himachal Pradesh"},{"id":"C","text":"Madhya Pradesh"},{"id":"D","text":"Bihar"}]', 0, 'C', 'The correct answer is $ \underline{\text{Madhya Pradesh}} $.
Key Points

• The Mukhyamantri Seekho-Kamao Yojana (MMSKY) is an initiative launched by the state government of Madhya Pradesh in 2023.

- The scheme aims to provide skill development and employment opportunities to the youth of Madhya Pradesh.

• It focuses on training young individuals in various trades and sectors to enhance their employability.

- The scheme is part of the government''s efforts to reduce unemployment and boost the economy by creating a skilled workforce.

• Beneficiaries of the scheme receive vocational training, which is aligned with industry requirements to ensure better job prospects.
Additional Information

• Uttar Pradesh

• Uttar Pradesh is the most populous state in India.

The state has a diverse range of cultural heritage and is known for its significant historical landmarks.

• Himachal Pradesh

• Himachal Pradesh is known for its scenic mountain landscapes.

o The state is a popular tourist destination for those seeking adventure and natural beauty.

• $ \underline{\text{Bihar}} $

o Bihar has a rich historical and cultural heritage.

o It is known for its role in the formation of early Indian civilization and important Buddhist sites.', NULL, 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1510, 'general-test-2024-05-29-shift-1', 'q37', 34, 34, 'Rabindranath Tagore had renounced his knighthood because _.', '[{"id":"A","text":"of execution of Bhagat Singh"},{"id":"B","text":"of Chauri-Chaura incident"},{"id":"C","text":"he wanted to join the Congress"},{"id":"D","text":"of the Jallianwala Bagh tragedy"}]', 0, 'D', 'The Correct answer is $ \underline{\text{of the Jallianwala Bagh tragedy}} $.
Key Points

• Rabindranath Tagore was a renowned Indian poet, philosopher, and polymath.

He was awarded a knighthood by the British government in 1915 for his contributions to literature.

• The Jallianwala Bagh tragedy occurred on April 13, 1919, when British troops, under the command of General Dyer, fired on a peaceful gathering, killing hundreds of unarmed Indian civilians.

Tagore was deeply affected by this brutal incident and felt it was a grave injustice to the Indian people.

- In protest, he renounced his knighthood, stating that such honors from the British government were meaningless in the face of such atrocities.

His renouncement was a significant act of defiance and inspired many Indians in their struggle for independence.
Additional Information

• $ \underline{\text{Execution of Bhagat Singh}} $

○ Bhagat Singh was a prominent Indian revolutionary who played a significant role in the Indian independence movement.

He was executed by the British government on March 23, 1931, but this event occurred much later than the Jallianwala Bagh tragedy.

• Chauri-Chaura incident

The Chauri-Chaura incident took place on February 4, 1922, when a group of protesters clashed with police, leading to the death of three civilians and 22 policemen.

This incident led Mahatma Gandhi to call off the Non-Cooperation Movement, but it was not related to Tagore''s renouncement of his knighthood.', NULL, 'null', '[]', '[]', '[41]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1511, 'general-test-2024-05-29-shift-1', 'q38', 35, 35, 'In which of the following cities of Madhya Pradesh was the $ 17^{th} $ edition of Pravasi Bharatiya Divas (PBD) organized?', '[{"id":"A","text":"Bhopal"},{"id":"B","text":"Indore"},{"id":"C","text":"Jabalpur"},{"id":"D","text":"Gwalior"}]', 0, 'B', 'The Correct answer is $ \underline{\text{Indore}} $.
Key Points

• The 17th edition of Pravasi Bharatiya Divas (PBD) was organized in Indore, a prominent city in Madhya Pradesh.

- Pravasi Bharatiya Divas is celebrated to recognize the contribution of the overseas Indian community in the development of India.

- The event provides a platform to the diaspora to engage with the government and people of the land of their ancestors.

• Indore is known for its rich cultural heritage and has been a significant center for trade and commerce in central India.

- The city is also famous for its cleanliness and has been awarded the title of India''s cleanest city multiple times.
Additional Information
• $ \underline{\text{Bhopal}} $

○ Bhopal is the capital city of Madhya Pradesh.

o It is known as the City of Lakes due to its numerous natural and artificial lakes.

o The city has a significant historical background with landmarks like the Taj-ul-Masajid and the Upper Lake.
• $ \underline{\text{Jabalpur}} $

Jabalpur is known for its marble rock formations at Bhedaghat.

o The city is an important administrative, industrial, and business hub in Madhya Pradesh.

o It is also home to several military establishments and the High Court of Madhya Pradesh.
• $ \underline{\text{Gwalior}} $

o Gwalior is known for its historic fort which has existed since the 6th century.

The city has been a significant center for classical music and is known for the famous Tansen Music Festival.

o Gwalior is also a major educational center with institutions like the Scindia School and Jiwaji University.', NULL, 'null', '[]', '[]', '[42]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1512, 'general-test-2024-05-29-shift-1', 'q39', 36, 36, 'In the joint military exercise ''Desert Cyclone'', 2024, which two nations collaborated to enhance interoperability through knowledge exchange?', '[{"id":"A","text":"India and Qatar"},{"id":"B","text":"India and Vietnam"},{"id":"C","text":"India and Australia"},{"id":"D","text":"India and UAE"}]', 0, 'D', 'The Correct answer is $ \underline{\text{India and UAE}} $.
Key Points

• The joint military exercise ''Desert Cyclone'' was conducted in 2024 between India and UAE.

- This exercise aimed at enhancing interoperability between the two nations.

• It involved knowledge exchange and the sharing of best practices in military operations.

• The exercise focused on tactical maneuvers, combat strategies, and logistical coordination.

- India and UAE have been strengthening their defense cooperation over the years, and this exercise is a testament to their growing military partnership.
Additional Information

• $ \underline{\text{India and Qatar}} $

o India and Qatar have a robust bilateral relationship, especially in the sectors of energy and trade.

o They conduct joint military exercises, but ''Desert Cyclone'' was not one of them.

• $ \underline{\text{India and Vietnam}} $

o India and Vietnam have a strong defense relationship, characterized by regular naval exercises and military exchanges.

o They focus on maritime security and counter-terrorism.

• $ \underline{\text{India and Australia}} $

o India and Australia conduct joint military exercises like ''AUSINDEX'' for enhancing naval cooperation.

o They focus on maritime domain awareness and interoperability.', NULL, 'null', '[]', '[]', '[43]', 'keyed', '[]', '2026-11-05T20:58:44.407Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1513, 'general-test-2024-05-29-shift-1', 'q40', 37, 37, 'Who among the following wrote the book "Guilty Men of India''s Partition"?', '[{"id":"A","text":"Mahatma Gandhi"},{"id":"B","text":"Lala Har Dayal"},{"id":"C","text":"Lala Lajpat Rai"},{"id":"D","text":"Ram Manohar Lohia"}]', 0, 'D', 'The correct answer is $ \underline{\text{Ram Manohar Lohia}} $.
Key Points

• Ram Manohar Lohia was an influential Indian freedom fighter, socialist political leader, and thinker.

• He wrote the book "Guilty Men of India''s Partition", which critiques the role of various leaders in the partition of India.

Lohia was known for his strong opposition to the policies of the Indian National Congress and his efforts to promote socialist ideologies in India.

He played a significant role in the Quit India Movement and was a prominent advocate for the abolition of the caste system and the promotion of equitable social policies.

Lohia''s writings and speeches have been influential in shaping the socialist and anti-colonial discourse in India.
Additional Information

• Mahatma Gandhi

o Mahatma Gandhi was the preeminent leader of the Indian independence movement in British-ruled India.

He is known for his philosophy of nonviolent resistance and his leadership in the Indian National Congress.

o Gandhi''s notable works include "Hind Swaraj" and "The Story of My Experiments with Truth".

• Lala Har Dayal

Lala Har Dayal was an Indian nationalist revolutionary and scholar who was involved in the Ghadar Party.

He is known for his contributions to the Indian independence movement and his intellectual works.

• Lala Lajpat Rai

Lala Lajpat Rai was a prominent Indian freedom fighter and a leader in the Indian Nationalist Movement.

He is also known as "Lion of Punjab" and played a significant role in the Swadeshi movement.

• Rai authored several books, including "Unhappy India".', NULL, 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1514, 'general-test-2024-05-29-shift-1', 'q41', 38, 38, 'Who authored the famous novels, ''The Fountainhead'' and ''Atlas Shrugged''?', '[{"id":"A","text":"H.G. Wells"},{"id":"B","text":"Ayn Rand"},{"id":"C","text":"George Orwell"},{"id":"D","text":"J.M. Barrie"}]', 0, 'B', 'The correct answer is $ \underline{\text{Ayn Rand}} $.

Key Points

- Ayn Rand was a Russian-American writer and philosopher.

• She is best known for her novels ''The Fountainhead'' and ''Atlas Shrugged''.

• ''The Fountainhead'', published in 1943, explores the life of an individualistic young architect named Howard Roark.

• ''Atlas Shrugged'', published in 1957, is a philosophical novel that presents Rand''s philosophy of Objectivism.

- Objectivism emphasizes rational self-interest and the pursuit of one''s own happiness as the moral purpose of life.

Both novels have had a significant impact on popular culture and continue to be widely read and discussed.
Additional Information

• H.G. Wells

o H.G. Wells was a British writer known for his works in the science fiction genre.

o Some of his famous novels include ''The War of the Worlds'' and ''The Time Machine''.

• $ \underline{\text{George Orwell}} $

George Orwell was an English novelist and essayist.

o He is best known for his novels ''1984'' and ''Animal Farm''.

• J.M. Barrie

o J.M. Barrie was a Scottish author and playwright.

o He is best known for creating the character Peter Pan.', NULL, 'null', '[]', '[]', '[45]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1515, 'general-test-2024-05-29-shift-1', 'q42', 39, 39, 'The Bhoodan-Gramadan Movement started by Vinoba Bhave is also known as _.', '[{"id":"A","text":"Civil Revolution"},{"id":"B","text":"Green Revolution"},{"id":"C","text":"Bloodless Revolution"},{"id":"D","text":"White Revolution"}]', 0, 'C', 'The correct answer is $ \underline{\text{Bloodless Revolution}} $.

Key Points

• The Bhoodan-Gramdan Movement was initiated by Vinoba Bhave in 1951.

- It aimed at persuading wealthy landowners to voluntarily give a percentage of their land to landless people.

- The movement is referred to as the Bloodless Revolution because it sought to bring about social change without any violence.

Vinoba Bhave, a follower of Mahatma Gandhi, believed in non-violence and sarvodaya (welfare of all).

- This movement was a part of the larger Sarvodaya Movement, which sought to promote economic and social equality.

- The Bhoodan-Gramdan movement received international recognition and was seen as a model for peaceful social transformation.
Additional Information

• Civil Revolution

The term Civil Revolution generally refers to movements aimed at achieving political and social changes through civil disobedience and non-violent resistance.

o Examples include the Civil Rights Movement in the United States.

• Green Revolution

The Green Revolution refers to a period of agricultural transformation that began in the 1940s and spread worldwide.

It involved the adoption of new farming techniques and high-yield crop varieties, significantly increasing food production.

• White Revolution

o The White Revolution, also known as Operation Flood, was a rural development program initiated in India in 1970.

o It transformed India into one of the world''s largest producers of milk and dairy products.', NULL, 'null', '[]', '[]', '[46]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1516, 'general-test-2024-05-29-shift-1', 'q43', 40, 40, '23 January, the birth anniversary of Netaji Subhas Chandra Bose, is celebrated every year as _.', '[{"id":"A","text":"Shaheed Diwas"},{"id":"B","text":"Parakram Diwas"},{"id":"C","text":"National Youth Day"},{"id":"D","text":"Hindi Diwas"}]', 0, 'B', 'Key Points

• Parakram Diwas is celebrated on 23 January to commemorate the birth anniversary of Netaji Subhas Chandra Bose.

- This day is observed to honor and remember the immense contribution and indomitable spirit of Netaji in the fight for India''s independence.

- Netaji Subhas Chandra Bose was one of the most prominent leaders of the Indian freedom struggle who founded the Indian National Army (INA).

• The day was officially declared as Parakram Diwas by the Government of India in 2021.

• The term "Parakram" signifies courage and valor, attributes strongly associated with Netaji.
Additional Information

• Shaheed Diwas

Shaheed Diwas, also known as Martyrs'' Day, is observed on 30 January to honor the sacrifices of Mahatma Gandhi and other martyrs of the Indian freedom struggle.

o It marks the assassination of Mahatma Gandhi in 1948.

• National Youth Day

o National Youth Day is celebrated on 12 January every year to commemorate the birth anniversary of Swami Vivekananda.

This day aims to inspire the youth of India to follow the ideals and philosophy of Swami Vivekananda.

• Hindi Diwas

o Hindi Diwas is observed on 14 September every year to celebrate the adoption of Hindi as one of the official languages of India.

o The Constituent Assembly of India adopted Hindi as the official language on 14 September 1949.', NULL, 'null', '[]', '[]', '[47]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1517, 'general-test-2024-05-29-shift-1', 'q44', 41, 41, '23 December, the birthday of former Prime Minister Chaudhary Charan Singh, is celebrated every year as _.', '[{"id":"A","text":"Samvidhan Diwas"},{"id":"B","text":"National Milk Day"},{"id":"C","text":"National Farmers'' Day"},{"id":"D","text":"Good Governance Day"}]', 0, 'C', 'The Correct answer is $ \underline{\text{National Farmers'' Day}} $.
Key Points

• National Farmers'' Day is celebrated to honor the memory of Chaudhary Charan Singh, the former Prime Minister of India.

• Chaudhary Charan Singh was known for his significant contributions to the agriculture sector and his efforts to improve the conditions of farmers in India.

• He served as the Prime Minister of India from 28 July 1979 to 14 January 1980.

• The day is celebrated on his birth anniversary, 23 December, each year.

• The celebration aims to acknowledge the hardships and contributions of farmers to the nation''s economy.

• Various programs, seminars, and events are organized to educate and support farmers.
Additional Information

• Samvidhan Diwas

o Samvidhan Diwas, also known as Constitution Day, is celebrated in India on 26 November each year.

o The day commemorates the adoption of the Constitution of India in 1949.

o It was first celebrated in 2015 to mark the 125th birth anniversary of B. R. Ambedkar.

• National Milk Day

o National Milk Day is celebrated on 26 November each year.

The day marks the birth anniversary of Dr. Verghese Kurien, the father of the White Revolution in India.

○ It was first celebrated in 2014.

• Good Governance Day

Good Governance Day is observed in India on 25 December each year.

o The day marks the birth anniversary of Atal Bihari Vajpayee, the former Prime Minister of India.

o It was established in 2014 to honor his legacy.', NULL, 'null', '[]', '[]', '[48]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
