INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1520, 'general-test-2024-05-29-shift-1', 'q48', 44, 44, 'If $ 1^{st} $ January, 2001 was a Monday, what was the day on $ 26^{th} $ January, 2003 ?', '[{"id":"A","text":"Saturday"},{"id":"B","text":"Sunday"},{"id":"C","text":"Monday"},{"id":"D","text":"Wednesday"}]', 0, 'B', 'Given: 1st January 2001 was Monday.

Now,

2001 to 2003 = 2 Years (2 Ordinary Year).

And, 1 Ordinary Year has 1 odd day.

Total odd days = 2.

then, 1st January 2003 will be Monday + 2= Wednesday.

Now, the number of days between 1st January 2003 to 26th January 2003

=25days.

=25days $ \rightarrow $ 25/7 = 3 weeks and 4odd days.

So, 26th January 2003 will be Wednesday +4= Sunday.

Hence, the correct answer is "Option 2".', NULL, 'null', '[]', '[]', '[52]', 'keyed', '[]', '2026-11-05T20:58:44.408Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
