INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1523, 'general-test-2024-05-29-shift-1', 'q51', 47, 47, 'Take the given statements to be true even if they seem to be at variance with commonly known facts. Then decide which of the given conclusions logically follow the given statements.

Statements :

0% chairs are tables.

All computers are chairs.

Some books are tables.

Conclusions :

I. Not a single table is a computer.

II. Some books are not chairs.', '[{"id":"A","text":"Only conclusion I follows."},{"id":"B","text":"Only conclusion II follows."},{"id":"C","text":"Both conclusions I and II follow."},{"id":"D","text":"Neither conclusion I nor II follows."}]', 0, 'A', 'Given Statements:

0% chairs are tables.

→ "0% chairs are tables" means no chair is a table. Represent this by keeping the circles for "Chairs" and "Tables" completely separate.

All computers are chairs.

Some books are tables.

The least possible Venn diagram for the given statement is:

Explanation of the Venn Diagram:

Conclusions:

I. Not a single table is a computer. - True (Since all computers are inside chairs and no chairs are tables, no computers are tables.)

II. Some books are not chairs. - False (We only know some books are tables. We don''t have any information about the relation between books and chairs. It''s possible that some books are chairs, or no books are chairs. We can only say that some books are tables. It is not confirmed that some books are not chairs.)

So, Only conclusion I follows.

Hence, the correct answer is "Option 1".', NULL, 'null', '[]', '[]', '[56]', 'keyed', '[]', '2026-11-05T20:58:44.409Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1524, 'general-test-2024-05-29-shift-1', 'q53', 48, 48, 'Find the number of triangles in the given figure.', '[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"12"},{"id":"D","text":"14"}]', 0, 'B', 'The total number of triangles is,

