INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1525, 'general-test-2024-05-29-shift-1', 'q54', 49, 49, 'Rakesh is $17^{\text{th}}$ from the right and Ankit is $15^{\text{th}}$ from the left in a line of students. If they interchange their places, the position of Ankit becomes $19^{\text{th}}$ from the left. How many students are there in the line?', '[{"id":"A","text":"36"},{"id":"B","text":"35"},{"id":"C","text":"34"},{"id":"D","text":"33"}]', 0, 'B', 'The logic followed here is:

Position of Rakesh from the right = 17th

Position of Ankit from the left = 15th

After interchanging, Position of Ankit from the left = 19th

So,

Total number of students = Position of Rakesh from the right + Position of Ankit from the left after interchange - 1

= 17 + 19 - 1

= 36 - 1 = 35.

Hence, the total number of students in the line are 35.', NULL, 'null', '[]', '[]', '[61]', 'keyed', '[]', '2026-11-05T20:58:44.409Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1526, 'general-test-2024-05-29-shift-1', 'q55', 50, 50, 'In a family, Bhanu is the father of Kamlesh. Bhanu has only two children. Kamlesh is the brother of Ritu. Ritu is the daughter of Santosh. Aryan is the grandson of Santosh. Sunny is the father of Aryan. How is Sunny related to Bhanu?', '[{"id":"A","text":"Son-in-law"},{"id":"B","text":"Son"},{"id":"C","text":"Nephew"},{"id":"D","text":"Brother-in-law"}]', 0, 'A', 'Family Chart:

Given: Bhanu is the father of Kamlesh.

Bhanu has only two children.

Kamlesh is the brother of Ritu.

Ritu is the daughter of Santosh.

Aryan is the grandson of Santosh.

Sunny is the father of Aryan.

Therefore, Sunny is Ritu''s husband, and Ritu is Bhanu''s daughter.

So, Sunny is the Son-in-law of Bhanu.

Hence, the correct answer is "Option 1".', NULL, 'null', '[]', '[]', '[62]', 'keyed', '[]', '2026-11-05T20:58:44.409Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
