INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1589, 'hindi-2024-05-16-shift-2', 'q12', 11, 11, 'इनमें से कौन-सा कार्यालयीयी पत्र का रूप नही है ?', '[{"id":"A","text":"कार्यालय आदेश"},{"id":"B","text":"अर्दशासकीय पत्र"},{"id":"C","text":"शोक पत्र"},{"id":"D","text":"अधिसूचना"}]', 0, 'C', 'कार्यालयी पत्र का स्पन नहीं है -शोक पत्र
Key Points
कार्ालपी पत्र के प्रकार:

• कार्यालय आदेश:

° किसी निर्णय या निर्देश को औपचारिक रूप से जारी करने के लिए

• कार्यालय शাपन:

• किसी विशेष कार्य या सूचना को कार्यालय के भीतर प्रसारित करने के लिए

• अधिसूचना:

° किसी महत्वपूर्ण सूचना को सार्वजनिक रूप से जारी करने के लिए

• अध-सरकारी पत्र:

• सरकारी अधिकारियों के बीच औपचारिक संवाद के लिए

• परिपत्र:

○ किसी विशेष विषय पर जानकारी को विभिन्न कार्यालयों या व्यक्तियों को भेजने के लिए

• हिमणी:

○ किसी विषय पर अपनी राय या सुझाव व्यक्त करने के लिए

• सूचना:

○ किसी विशेष कार्य या घटना के बारे में जानकारी देने के लिए
Important Points काल्पनिया पर का प्रासपत्त

• ऊपर बॉई और: प्रेक्षक का कार्यलियण का नाम, पता, और संपर्क विवरण

• बीच में: पत्र का विषय

• दाईं ओर: पत्र का कर्मोंके और दिनोंक

• "सेवा में" के बाद: प्राप्तकर्ति का नाम, पद, और पता

• मुख्य पाठ: पत्र का मुख्य विषय, जिसमें जानकारी, अनुरोध, या निर्णय शामिल होता है

• अंत में: प्रेक्षक का नाम और पदनाम
Additional Information
शोक पत्र-

• शोक संवेदना संदेश पत्र एक ऐसा पत्र होता है जिसे किसी व्यक्ति की मृत्यु पर लिखा जाता है।

- इस पत्र में, लेखक मृतक के प्रति अपनी संवेदना व्यक्त करता है और शोकग्रस्त परिवार के प्रति अपनी सहानुभूति व्यक्त करता है।
शोक संवेदना संदेश पत्र लिखते समयबातों का ध्यान रखना चाहिए:

• पत्र की शुरुआत में, मृतक के नाम और संबंध का उल्लेख करें।

• मृतक के प्रति अपनी संवेदना व्यक्त करें।

• मृतक के परिवार के प्रति अपनी सहानुभूति व्यक्त करें।

• मृतक के साथ अपने अनुभवों का उल्लेख करें, यदि कोई हो।

• पत्र को एक सकारशांसक नोट पर समाप्त करें।', NULL, 'null', '[]', '[]', '[17]', 'keyed', '[]', '2026-11-05T20:58:44.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
