INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1598, 'hindi-2024-05-16-shift-2', 'q22', 20, 20, 'नीचे दो कथन दिए गए हैं :

कथन I : विशेषण एक ऐसा विकारी शब्द है, जो संज्ञा या सर्वानाम की विशेषता बताता है।

कथन 11 : विशेषण के प्रयोग से जिस संज्ञा का गुण अथवा धर्म प्रकट होता है, उस संज्ञा को वैयाकरण विशेष्य कहते हैं।

उपयुक्त कथन के आलोक में नीचे दिए गए विकल्पों में से सबसे उपयुक्त उत्तर का चयन कीजिए :', '[{"id":"A","text":"कथन। और ॥ दोनों सही हैं"},{"id":"B","text":"कथन। और ॥ दोनों गलत हैं"},{"id":"C","text":"कथन। सही है, लेकिन कथन। गलत है"},{"id":"D","text":"कथन। गलत है, लेकिन कथन।। सही है"}]', 0, 'A', 'सही उत्तर है -कथन ऑपर ऑ को सही है
Key Points

विशेषज्ञ-

• विशेषण एक ऐसा विकारी शब्द है जो संशा या सर्वनाम की विशेषता बताता है।

• संज्ञाअथवासवंनामशब्दोंकीविशेषता(गुण, दोष, संख्या, परिमाण आदि)बतानेवालेशब्द''विशेषण''कहलाते हैं।

• जैसे-बड़ा, काला, लम्बा, दयालु, भारी, सुंदर, कायर, एक, दो, वीर पुरुष, गोरा, अंछा, बुरा, मीठा, खृद्राओடி।

० लोमड़ी बहुतलालची जानवर है।
विशेष आवृत्ति

• विशेषण के प्रयोग से जिस संशा का गुण या धर्म प्रकट होता है, उस संशा कोवैयाकरण'' विशेष्य'' कहते हैं।

• जिससंशाऔरसवेंनामकी विशेषता बताई जाती है, उसविशेष्यकहते है।

• जैसे-सफेदघोड़ा, गोलाआदमी। यहाँ''सफेद और गोला''विशेषण है तथा''घोड़ा और आदमी''विशेष है।
Important Points

• हिन्दी व्याकरण में विकारी शब्द चार प्रकार के होते हैं:

• संशा, सर्वनाम, विशेषण, क्रिया।

• हिन्दी व्याकरण में आविकारी शब्द चार प्रकार के होते हैं:

• क्रिया विशेषण अध्यय, संबंध बोधक अध्यय, समुच्य बोधक अध्यय, विस्मयादि बोधक अध्यय।
Additional Information

• विशेषण के मुख्य रूप से चार भेद होते हैं:

1. गुणवाचक विशेषण,

2. परिमाणवाचक विशेषण,

3. संख्यावाचक विशेषण,

4. सार्वनिम्निक विशेषण', NULL, 'null', '[]', '[]', '[32]', 'keyed', '[]', '2026-11-05T20:58:44.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
