INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1603, 'hindi-2024-05-16-shift-2', 'q27', 25, 25, '"श्री गुरु चरन सरोज रज, निज मन मुकुर सुधार।

बरनौ रघुवर विमल जस, जो दायक फल चार।।"

इन पंक्तियों में किस छंद का प्रयोग किया गया है ?', '[{"id":"A","text":"सोरठा"},{"id":"B","text":"कुडिलिया"},{"id":"C","text":"बरवे"},{"id":"D","text":"दोहா"}]', 0, 'D', '"श्री गुर चरन सरोज रज, निज मन मुकुर सुधार।

बरनौ रघुवर विमल जस, जो दायक फल चार।।"

इन पंक्तियों में छेद का प्रयोग किया गया है -द्रोह
Key Points

• "श्री गुरु चरन सरोज रज, निज मन मुकुर सुधार।

• S I II IIIISIII II I III S I =13 +11 = 24

• बरनो रघुवर विमल जस, जो दायक फल चार।|"=13 +11 = 24

IISI II IISISSIIS I

- इन पंक्तियों में छिद का प्रयोग किया गया है -दोह्मा
Important Points

དེ་ཐང་：

• यहअर्थसम्ममாதிறक छेदहोता है। येसोरठा छेदके विपरीत होता है।

- इसमेंपहलेऔरतीसरेचरण में13-13तथा दूसरे औरचौथेचरण में11-11मांत्राएँ होती हैं।

- इसमें चरण के अंत मेलधु (1)होना जस्सी होता है।

• जैसे:-

• रहिमन पानी राखेए, बिन पानी सब सून।

○ I III SSSISII SSII S I

• पानी गए न ऊबरे, मोती मानुष चून।।
Additional Information

सोरहा:-

• यहअर्थसम मাত্রिक ऊँदहै । यहदोहेका उल्ता होता है।

- इसकेप्रथमऔरतृतीयचरण में11-11मांत्राएँ एवंहितीयऔरचतुथர்கरण में13-13मात्राएँ होती हैं।

• इसमें तुकप्रथमऔरतृतीयचरण के अंत में अर्थितमध्यमें होता है। इसके सम चरणों मेंजगणनहीं होता।

उदाहरण-

• जो सुमिरत सिंधि होई, गन नायक कविवर बदन।

• करहु अनुग्रह सोई, बुडि रासि शुभ गुन सदन॥

बरवेः-

• बरवे अईसम मात्रिक छन्द है।

• इसके प्रथम एवं तृतीय चरण में 12-12 मात्राएँ तथा द्वितीय एवं चतुर्थ चरण में 7-7 मात्राएँ होती हैं।

• सम चरणों के अंत में ''जगण'' (1 S 1) होता है।

• गोस्वामी तुलसीदास की प्रसिद्ध रचनाओं में से एक ''बरवे रमायाण'' बरवे छन्दों में ही रची गई है, जिसमें भगवान श्रीराम की कथा है।
उदाहरण-

• ऑख मिलेंगी सबसे, रख व्यवहार।

फूल सभी जन चाहें, एक न खार।।
कुण्डलिया:-

• कुण्डलीया छेददोहा-रोलाछंदों के योग से बनता है।

• कुडिलियाएंकिविषम मात्रिकेछंद होता है।

• यहदोह-रोलाछंदोंके योग से बनता है।

• पहलेएक दोहाओं बाद मेंदोها के चौथे चरणसे यदिएक रोलारख दिया जाए तो वहकुडलिया छेदबन जाता है।
उदाहरण-

• सावन बरसा जोर से, प्रमुदित हुआ कियांन ।

• लगा रोपने खेत में, आशाओं के धान ।।

• ओशिआं के धान, मधुर स्तर कोयल बोल ।

• लिए प्रेम-संदेश, मेघ सावन के डोले ।

• ''ठकुरेला'' कविराय, लगा सबको मनभावन ।

• मन में भरे उर्मेण, झुम्मा गाता सावन ।।', NULL, 'null', '[]', '[]', '[40]', 'keyed', '[]', '2026-11-05T20:58:44.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1604, 'hindi-2024-05-16-shift-2', 'q28', 26, 26, '"पसरी" शब्द में कौन-सा समास निहित है ?', '[{"id":"A","text":"कर्मधारय"},{"id":"B","text":"ततुर्ष"},{"id":"C","text":"द्विगु"},{"id":"D","text":"द्वैद"}]', 0, 'C', '"पसरी" शब्द में समास निहित है -्द्रिगु
Key Points

• "पसेरी" का समास विग्रह :- पाँच सैरों का समूह

• "पसेरी" शब्द में द्विगु समास का प्रयोग है।

- वह समास जिसकापहला पदसंख्यावाचक विशेषणहोता है

• तथा समस्तपद किसीसमूहया फिर किसीसमाहारका बोध करता है, तो वहदिदगु समासकहलाता है।

• उदाहरण -

○ नवरात्र = नव रात्रियों कास्मूह

• दोराह =दो राहों कास्माहार
Important Points
समासके भेद-

1. तत्पुर्षषसमास

2. कर्मधारयसमास

3. द्विगुणमास

4. दृढ़समानस

5. बहुरीहिस्मास

6. अध्ययीभावसमास
