INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1605, 'hindi-2024-05-16-shift-2', 'q29', 27, 27, 'नीचे दो कथन दिए गए हैं :

कथन 1 : जहाँ किसी शब्द का प्रयोग एक बार हो, किंतु अर्थ भित्र-भित्र होता हो वहाँ श्लेष अलंकार होता है।

कथन 11 : जहाँ कोई शब्द एक से अधिक बार प्रयुक्त हो, किंतु उसका अर्थ अलग-अलग हो वहाँ श्लेष अलंकार होता है।

उपयुक्त कथन के आलोक में, नीचे दिए गए विकल्पों में से सबसे उपयुक्त उत्तर का चयन कीजिए :', '[{"id":"A","text":"कथन 1 और 11 दोनों सही हैं"},{"id":"B","text":"कथन 1 और 11 दोनों गलत हैं।"},{"id":"C","text":"कथन 1 सही है, लेकिन कथन 11 गलत है"},{"id":"D","text":"कथन 1 गलत है, लेकिन कथन 11 सही है"}]', 0, 'C', 'सही उत्तर है -कथन ऑसरी है, लेकिन कथन ऑसरी गलत है
Key Points

• कथन 1 सही है। श्लेष अलंकार तब होता है जब एक ही शब्द का प्रयोग एक बार किया जाए और इसका अर्थ भिन्न-भिन्न हो।

• कथन 11 गलत है। श्लेष अलंकार में एक ही शब्द का प्रयोग बार-बार नहीं होता बल्कि एक ही शब्द का अर्थ अल्ग-अलग होता है।

○ अत: सबसे उपयुक्त उत्तर होगा: कथन 1 सही है और कथन 11 गलत है।
Additional Information
হলে:

• श्लेष का अर्थ हैचिपकाना,

• जहां शब्द तोएक बारप्रयुक्त किया जाए पर उसकेएक से अधिक अर्थिकलौ वहाँश्लेष अलंकारहोता है।
उदाहरण-

• मेरी भव बाधा हरो राधा नागरी सोय।

• जा तन की शॉर्ड्स पर देखाम हरित दुर्दित हों।।

• (काव्यांश में कवि द्वारा हरित शब्द का प्रयोग दो अर्थ प्रकट करने के लिए किया है।

• यहाँ हरित शब्द के अर्थ है- हर्षित (प्रसत्र होना) और हरे रंग का होना।)', NULL, 'null', '[]', '[]', '[44]', 'keyed', '[]', '2026-11-05T20:58:44.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (1606, 'hindi-2024-05-16-shift-2', 'q30', 28, 28, '"लेवत मुख में घास मृग, मोर तजत नृत जात। आँसू गिरियत जर लता, पीरे-पीरे पात।।" उक्त पंक्तियों में कौन-सा अलंकार है ?', '[{"id":"A","text":"भ्रांतिमान"},{"id":"B","text":"अतिशयोक्ति"},{"id":"C","text":"यमक"},{"id":"D","text":"श्लेष"}]', 0, 'B', '"लेवत मुख में घास मृग, मोर तजत नृत जात।

ऑसू गिरियत जर लता, पीरे-पीरे पात।।"

उक्त पंक्तियों में अल्कार है -अतिशयोवित्त
Key Points

• उक्त पंकितयों में घटनाओं को असाधारण और बढ़ा-चढ़ाकर प्रस्तुत किया गया है।

• जिसमें हिरन के मुंह में घास लेने से मोर नाचना बंद कर देता है और ऑसू गिरने से लताएं जल जाती है,

• पते पीले हो जाते हैं। यह सब वास्तविकता से परे होने के कारण, यहाँ ''अतिशयोक्ति अलंकार'' का प्रयोग किया गया है।
Important Points
अतिशयोवित्त:-

• जब किसीवस्तु, व्यक्तिआदि का वर्णन बहुतबाधा चढ़ाकर किया जाए तब वहाँअतिशयोक्ति अलंकारहोता है।

• इस अंलकार मेनामुमिकन तथ्यबोले जाते हैं।

• उदाहरण-

• हनुमान की पूछ में लगान न पाई आगे।

• लंका सगरी जल गई, गए निशाचर भाग।।

• (स्पष्टीकरण - पूछ में आग लगने से पहले लंका का जलना अतिशयोक्ति है।)
Additional Information
भ्राता-भ्राता

• जबकोई वस्तुको देखकर हम उसे

उसकेसमान गुण्याविशेषताओंवाले

किसीअन्य पदार्थ (उपमान)के रूप में

मान लेते हैं तो वहाँभ्रितमान

अलंकारमाना जाता है।
उदाहरण -

• जানি स्वाम को स्वाम-धन नाचि उठे वन मोर।

• (ऊपर दिए गए वाक्य मंमोर श्री कृष्णको सदशय के कारणशयाम मेघ (काले बादल) समझ रहे हैं

• तथाश्यामकेकाले रंगके कारण मोरो कोकाले बादलोका भ्रम हो गया है।)

यमक:-

• जबएक ही शब्द ज्यादा बारप्रयोग हो, पर

हर बारअर्थ अलग-अलगआये, वहाँ

परयमक अलंकारहोता है।
उदाहरण-

• कालिधताका घमंडधटा।

• (''घटा''शब्ददो बारआया है और दोनों बार इसका अर्थ अलग-अलग है, पहली बार ''घटा''शब्द का अर्थ''''काले बादलों''से है, दूसरी बार ''घटा''शब्द का अर्थ''''कमी होना''या''हास''से जुड़ा है।)
হলে:

- शलेष का अर्थ हैचिपकाना,

- जहाँ शब्द तोएक बारप्रयुक्त किया जाए

पर उसके एक से अधिक अर्थिक है

वहाँशलेप अलंकारहोता है।
उदाहरण-

- सुबरन को दूढ़त फिरत कवि, व्यभिचारी, चोर।

• (इस दोहे मंसुबरनशब्द केतीनअर्थ है।

कवि ''सुबरन'' अर्थात्अछ्छे

शब्द, व्यभिचारी'' सुबरन'' अर्थात्अछ्छा

