INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2182, 'biology-2023-06-05-shift-3', 'q40', 40, 40, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)"},{"id":"C","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"},{"id":"D","text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)"}]', 0, 'D', 'Some examples of recent extinctions include the dodo (Mauritius), quagga (Africa), thylacine (Australia), Steller''s Sea Cow (Russia) and three subspecies (Bali, Javan, Caspian) of tiger.', NULL, 'null', '[]', '[{"id":"q40-table-1","kind":"table","path":"/local-papers/assets/biology-2023-06-05-shift-3/q40-table-1.jpg","page":4,"alt":"Table for question 40"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
