A stands for:', '[{"id":"A","text":"$ \\text{Mn}^{3+} $"},{"id":"B","text":"$ \\text{Mn}^{4+} $"},{"id":"C","text":"$ \\text{Mn}^{2+} $"},{"id":"D","text":"$ \\text{Mn}^+ $"}]', 0, 'C', '$ MnO_{4}^{-} + 8H^{+} 5e^{-} \rightarrow Mn^{2+} + 4H_{2}O $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2637, 'chemistry-2023-06-15-shift-1', 'q39', 39, 38, 'If we use molten NaCl, the products of electrolysis are _.', '[{"id":"A","text":"H $ _{2} $ gas and Cl $ _{2} $ gas"},{"id":"B","text":"NaOH and Cl_{2} gas"},{"id":"C","text":"H_{2}O and Cl_{2} gas"},{"id":"D","text":"Sodium metal and Cl_{2} gas"}]', 0, 'D', 'During electrolysis of molten NaCl, sodium metal is deposited at the cathode, whereas, chlorine is liberated at the anode.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2638, 'chemistry-2023-06-15-shift-1', 'q40', 40, 39, 'Which statement is not true for a detergent molecule?', '[{"id":"A","text":"It is not biodegradable"},{"id":"B","text":"It is a surface active agent"},{"id":"C","text":"It has a non-polar organic part and a polar non-organic part"},{"id":"D","text":"It is sodium salt of fatty acid Direction for the question 41 to 45: Question is based on following passage: Methyl nitrile is hydrolysed to carboxylic acid in the presence of $ H^{+} $ or $ OH^{-} $ as catalyst. An intermediate compound [A] is formed during this reaction."}]', 0, 'D', 'Detergents are sodium salt of sulphonic acids.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
