INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2640, 'chemistry-2023-06-15-shift-1', 'q42', 42, 41, 'Converting [A] into [C] is called:', '[{"id":"A","text":"Ammonolysis"},{"id":"B","text":"Hoffmann Degradation Reaction"},{"id":"C","text":"Carbylamine reaction"},{"id":"D","text":"Gabriel phthalamide reaction"}]', 0, 'B', 'Ethanamide is treated with bromine and boiled with NaOH produces methyl amine.

This is Hoffmann''s bromamide reaction or Hoffmann''s degradation reaction.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2641, 'chemistry-2023-06-15-shift-1', 'q43', 43, 42, 'The sweet smelling compound [D] is:', '[{"id":"A","text":"Acid anhydride"},{"id":"B","text":"Acyl halide"},{"id":"C","text":"Aldehyde"},{"id":"D","text":"Ester"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2642, 'chemistry-2023-06-15-shift-1', 'q44', 44, 43, 'What is not true regarding compound [B]?

(A) They are higher boiling liquids than aldehydes and ketones due to extensive H Bonding

(B) They are soluble in Benzene

(C) They produce alkane when heated with soda lime

(D) Produces CO₂ when treated with NaHCO₃', '[{"id":"A","text":"(A) and (B) only"},{"id":"B","text":"(A) and (C) only"},{"id":"C","text":"(B) only"},{"id":"D","text":"(A) only"}]', 0, 'C', 'Acetic acid is a polar molecule while benzene is a non-polar solvent. So, acetic acid cannot dissolve in benzene.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2643, 'chemistry-2023-06-15-shift-1', 'q45', 45, 44, 'Which of the following is the correct statement for hybridization of C-atom and number of and $ \Pi $ bonds in the Carbonyl group?', '[{"id":"A","text":"$ Sp^{2} $, $ 3\\sigma $, $ 1\\pi $"},{"id":"B","text":"Sp, $ 3\\sigma $, $ 1\\pi $"},{"id":"C","text":"$ Sp^{3} $, $ 3\\sigma $, $ 1\\pi $"},{"id":"D","text":"$ Sp^{2} $, $ 2\\sigma $, $ 2\\pi $ Direction for the question 46 to 50: Question is based on following passage: p-block elements are placed in groups 13 to 18 of the periodic table. Group 15 is nitrogen family. Nitrogen makes various compounds like NH₃, HNO₃, N₂O, NO₂ etc. Phosphorus exists in the form of white and red phosphorus. White phosphorus glows in dark. PH₃ gas is used as smoke screen. Group 16 is called oxygen family. Dry air contains 21% O₂ gas by volume. Combined sulphur exists as sulphates such as gypsum, eposome salt, baryte etc. The allotropic forms of sulphur are Rhombic and monoclinic sulphur. $ S_{2} $ is paramagnetic like $ O_{2} $ and it stable at high temperature. Group 17 is Halogen family. $ F_{2} $ is highly reactive, $ Cl_{2} $ is greenish yellow gas. Both $ SO_{2} $ and $ Cl_{2} $ are used for bleaching. Group 18 is Noble gas family but some noble gases also form compounds. Complete hydrolysis of $ XeF_{6} $ gives HF and $ XeO_{3} $ as main products."}]', 0, 'A', 'The carbonyl carbon and oxygen are sp2-hybridized with 3 sigma and 1 pi bond.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2644, 'chemistry-2023-06-15-shift-1', 'q46', 46, 45, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)"},{"id":"B","text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)"},{"id":"C","text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)"},{"id":"D","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"}]', 0, 'A', '[A] Ammonia is used in the detection of Cu $ ^{2+} $ ion

[A] Ammonia is used in the detection of Cu $ ^{2+} $ ion

[B] The Ostwald process is a process used for manufacturing Nitric acid.

