INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2645, 'chemistry-2023-06-15-shift-1', 'q47', 47, 46, 'Sulphate of magnesium of the following is:', '[{"id":"A","text":"Gypsum"},{"id":"B","text":"Epsom salt"},{"id":"C","text":"Baryte"},{"id":"D","text":"Galena"}]', 0, 'B', 'Epsom salt is also known as magnesium sulfate. It''s a chemical compound made up of magnesium, sulfur, and oxygen.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:51.657Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2646, 'chemistry-2023-06-15-shift-1', 'q48', 48, 47, 'At elevated temperature (~1000 K) the dominant form of sulphur is:', '[{"id":"A","text":"Rhombic Sulphur"},{"id":"B","text":"Monoclinic Sulphur"},{"id":"C","text":"S_{8} molecules"},{"id":"D","text":"S_{2}"}]', 0, 'D', 'At elevated temperatures (~1000 K), S₂ is the dominant species and is paramagnetic like O₂.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:51.658Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2647, 'chemistry-2023-06-15-shift-1', 'q49', 49, 48, 'The permanent bleaching effect is caused by:', '[{"id":"A","text":"Chlorine gas"},{"id":"B","text":"$ SO_{2} $ gas"},{"id":"C","text":"Aqua Regia"},{"id":"D","text":"$ COCl_{2} $"}]', 0, 'A', 'Chlorine''s bleaching activity is permanent since it includes the oxidation process. Chlorine produces nascent oxygen when it combines with water. This oxygen reacts with the pigments in the substance, rendering it colourless. It has a strong oxidising effect.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:51.658Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
