INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2803, 'english-2023-06-06-shift-2', 'q05', 5, 5, 'Find the synonym from the passage which means ''To become less extreme in behaviour''', '[{"id":"A","text":"Stray"},{"id":"B","text":"boisterous"},{"id":"C","text":"mellowed"},{"id":"D","text":"Folly Read the following passage carefully and answer the questions given below. The needs of a nation people are bigger and much more important than any other considerations. The mission of parliament is that it has to be alive and dynamic over issues vital to the existence of our very nationhood. Our freedom did not come as a gift. The whole country struggled for decades to achieve the first vision of independence, so we have to protect it. There were excellent leaders in all walks of life-science, education and industry. To preserve this freedom from intruders and others who would compromise it is our bounden duty and not a matter of choice and convenience. No ideology is above the security and prosperity of our country. No agenda is more important than harmony among the people. Students should get ready to transform India into a developed nation. Ignore your minds and think big. A teacher once said, ''Give me a five-year-old child. After seven years, no God or Devil will be able to change the child.'' Will all teachers be such gurus? The administrators have a great opportunity to link the people and political leaders. They should always take decisions that are good for the people I believe it is only executives like empowered district collectors who can assist transformation. The state-Central integrated fund has to be deployed in mission mode programmes."}]', 0, 'C', 'Mellowed', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:51.710Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
