INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (2905, 'english-2023-06-10-shift-2', 'q10', 10, 10, 'The passage is about:', '[{"id":"A","text":"two friends"},{"id":"B","text":"two friends who turned rivals"},{"id":"C","text":"two enemies"},{"id":"D","text":"two strangers Direction for Q11 to Q15. In stark contrast to where I grew up-in warm, lush green Trivandrum, Kerala, filled with rich sights, sounds and people-life at the Poles is quiet. The harshness of winter brings along with it an eerie desolation and near-total silence. Survival in this frigid, dark and windy terrain is only for the fittest. A misstep can mean anything from an icy injury to a bitter, benumbed death. But while it is tenuous, life here is also humbling-physically, mentally, and even spiritually. The experience has allowed me to witness the wonderful qualities of nature: raw, brutal and unforgiving but nurturing and awe-inspiring at the same time. As the days shorten, almost all life starts to depart seeking warmer lands. But those who stay are surrounded by glacial beauty and an otherworldly stillness that stands unmatched. In peak winter months, the sun seems to live only in memory. Its absence however, is only an illusion: shimmering displays of blue, red, yellow, green, and orange auroras shifting and snaking like billowing curtains across the pitch black sky remind me that the light shall one day return. Even the emptiness of the land is deceptive. Look closely and out waddles a flock of penguins from behind an ice shelf on the Antarctic peninsula"}]', 0, 'B', 'two friends who turned rivals', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:51.728Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
