INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3000, 'english-2023-06-13-shift-3', 'q07', 7, 7, 'What does ''at the stroke of the mid night hour mean''? Choose the suitable option.', '[{"id":"A","text":"at the eleventh hour"},{"id":"B","text":"very late at night"},{"id":"C","text":"when midnight approaches"},{"id":"D","text":"early morning"}]', 0, 'C', 'When midnight approaches', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.404Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
