INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3002, 'english-2023-06-13-shift-3', 'q09', 9, 9, 'Who was Pandit Jawaharlal Nehru addressing in the passage?', '[{"id":"A","text":"Britishers"},{"id":"B","text":"his jailer"},{"id":"C","text":"The Prime Minister"},{"id":"D","text":"his countrymen"}]', 0, 'D', 'His countrymen', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.405Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3003, 'english-2023-06-13-shift-3', 'q10', 10, 10, 'Why is the future one of incessant striming?

(A) It is not of ease

(B) So we can fulfill the pledges we have taken

(C) It is heavy with the memory of sorrow

(D) It is sovereign

(E) It is brave

Choose the correct option.', '[{"id":"A","text":"(A) only"},{"id":"B","text":"(B) and (C)"},{"id":"C","text":"(B) only"},{"id":"D","text":"(D) and (E) Direction for Q11. to Q15. Read the following passage and answer the question that follows: A novel is a two way street, in which the labour required on either side is, equal. Reading, done properly, is every bit as tough as writing. As for those people who align reading with the essentially passive experience of watching television, they only wish to debase reading and readers. The more accurate analogy is that of the amateur musician placing her sheet music on the stand and preparing to play. She must use her own, hard-won, skills to play this piece of music. The greater the skill, the greater the gift she gives the composer, and the composer gives her. This is a conception of \"reading\" we rarely hear now. And yet, when you spend time with a book and practise reading the old moral of effort and reward is undeniable. Reading is a skill, and an art and readers should take pride in their abilities and have no shame in cultivating them if for no other reason than the fact that writers need you. To respond to the ideal writer takes an ideal reader, one who is open enough to allow into their own mind a picture of human consciousness radically different from their own. The ideal reader steps up to the plate of the writer''s style so that together writer and reader might hit the ball out of the park. What I''m saying is, a reader must have quite a lot of talent, because even the most talented reader will find much of the land of literature tricky terrain. For how many of us fell the world to be as Kafka felt it, too impossible foreshortened to ride from one village to the next? Or can imagine a world without nouns, as Barges did? How many are willing to be as emotionally generous as Dickens, or to take religious faith as seriously as did Graham Geene? Readers fail writers just as often as writers fail readers. Readers fail when they allow themselves to believe the old mantra that fiction is the thing you relate to and writers the amenable people you seek out when you want to have your own version of the world confirmed and reinforced. That is certainly one of the many things fiction can do, but it''s a conjurer''s trick within a far deeper magic. To become better readers and writers we have to ask of each other a little bit more."}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.405Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
