INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3047, 'english-2023-06-15-shift-3', 'q05', 5, 4, 'Match List -1 with List -II.

Choose the correct answer from the options given below

$$ \mathrm{(a)}\quad\mathrm{(A)}\mathrm{-(I)},\\\mathrm{(B)}\mathrm{-(III)},\\\mathrm{(C)}\mathrm{-(II)},\\\mathrm{(D)}\mathrm{-(IV)} $$

$$ \mathrm{(b)}\mathrm{\quad(A)-(II),(B)-(III),(C)-(I),(D)-(IV)} $$

(c)', '[{"id":"A","text":"(II),"},{"id":"B","text":"(I),"},{"id":"C","text":"(IV),"},{"id":"D","text":"(III) $$ \\left(\\mathrm{d}\\right)\\mathrm{\\quad}(\\mathrm{A})-(\\mathrm{I}),\\mathrm{\\quad}(\\mathrm{B})-(\\mathrm{II}),\\mathrm{\\quad}(\\mathrm{V})-(\\mathrm{IV}),\\mathrm{\\quad}(\\mathrm{D})-(\\mathrm{III}) $$ Direction for Q6. to Q10. Read the following passage and answer the question that follows: Conducting an interview should be like painting by numbers if you are properly prepared. Consider the various aspects of the interview that benefit from early preparation. Some of these may seem obvious, but if left until the candidates are at the door, they can have a negative effect on the process. A checklist will help to make sure everything is planned and some of the less obvious considerations remembered. Frequently overlooked is the choice of venue and its layout; this can affect the atmosphere of the interview and how candidates respond. The room can feel forbidding, formal, relaxed or cosy, depending on how the furniture is arranged and how the interviewers behave towards the candidates. Interviewing can be stressful for candidates and interviewers alike, so take account of this in the timing of the interviews and briefing of the interviewers. Stress levels also influence how interviewers behave towards the candidates; developing skills in how to question and supply information to candidates will smooth the flow and help interviewers improve their performance. Of course, question technique, active listening and observation skills benefit managers in other areas of their work, too. The way in which the interview is ended also has an effect on the candidates and may well effect whether the desired candidate decides whether to accept the offer of employment or reject it."}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q05-table-1","kind":"table","path":"/local-papers/assets/english-2023-06-15-shift-3/q05-table-1.jpg","page":1,"alt":"Table for question 5"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.409Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
