INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3049, 'english-2023-06-15-shift-3', 'q07', 7, 6, 'According to the passage, which of the following DOES NOT help in reducing stress during an interview?', '[{"id":"A","text":"The behaviour of the interviewer"},{"id":"B","text":"Timing of the interview"},{"id":"C","text":"The ability of the interviewer to intimidate the candidate"},{"id":"D","text":"The ability of the interviewer to convey information to the candidate"}]', 0, 'C', 'The ability of the Interviewer to intimidate the candidate.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.409Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
