INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3095, 'general-test-2023-05-21-shift-1', 'q03', 3, 3, 'Which of the following players didn''t receive Medal in Tokyo Olympics 2020?', '[{"id":"A","text":"PV Sindhu"},{"id":"B","text":"Neeraj Chopra"},{"id":"C","text":"Abhinav Bindra"},{"id":"D","text":"Ravi Kumar Dahiya"}]', 0, 'C', '(a) P. V. Sindhu received Bronze medal in Badminton

