INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3096, 'general-test-2023-05-21-shift-1', 'q04', 4, 4, 'Find the angle traced by hour hand of a correct clock between 7 pm 0 clock and 2 am 0 clock.', '[{"id":"A","text":"200°"},{"id":"B","text":"210°"},{"id":"C","text":"310°"},{"id":"D","text":"290°"}]', 0, 'B', 'Angle made by hour hand in 1 hour = $ 30^{\circ} $

7 pm to 2 am = 7 hours.

Angle traced = $ 30^{\circ} \times 7 = 210^{\circ} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.418Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3097, 'general-test-2023-05-21-shift-1', 'q05', 5, 5, 'Consider the Diagram:

Math

500 Candidates appeared in an Examination comprising test in English, Hindi and Maths. The Diagram gives number of students who failed in different tests. What is the % percentage of student who failed at least two subjects?', '[{"id":"A","text":"6.8%"},{"id":"B","text":"7.8%"},{"id":"C","text":"1.0%"},{"id":"D","text":"0.078%"}]', 0, 'B', 'No. of students failed in at least two subjects = 10 + 5 + 12 + 12 = 39

Percentage= $ \frac{39}{100} \times 100 = 7.8\% $', NULL, 'null', '[]', '[{"id":"q05-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q05-figure-1.jpg","page":1,"alt":"Figure for question 5"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.418Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3098, 'general-test-2023-05-21-shift-1', 'q06', 6, 6, 'A railway half-ticket costs half the full ticket. However, the reservation charge for all the tickets is constant. One full reserved ticket for a journey is 2525. If the cost of one full and one half reserved ticket for the same journey is 1850, then what is the reservation charge per ticket?', '[{"id":"A","text":"2120"},{"id":"B","text":"2150"},{"id":"C","text":"2125"},{"id":"D","text":"2115"}]', 0, 'C', 'Let x be the fare and y be reservation char

$ x + y = 525 \ldots (i) $

One full and one-half ticket = $ 1 + \frac{1}{2} = \frac{3}{2} $

Cost of half ticket = x/2

$ x + y + \frac{x}{2} + y = 850 $

$ \frac{3}{2}x + 2y = 850 $

$ 3x + 4y = 1700 \ldots (ii) $

Solving (i) & (ii),

x = 400 ... (iii)

Using (iii) in (i), y = 125

So, reservation charge is ₹125.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.418Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3099, 'general-test-2023-05-21-shift-1', 'q07', 7, 7, 'A and B can do a work in 9 days and 12 days respectively. If they work on alternate days starting with A, then in how many days will the work be completed?', '[{"id":"A","text":"36 days"},{"id":"B","text":"10 days"},{"id":"C","text":"10 days"},{"id":"D","text":"13 days"}]', 0, 'C', '$ \frac{36}{7} = 5 $ (1 rem) means 10 days and 1 unit work is remaining which is done by $ A = \frac{1}{4} $

So, total to be taken = 10 $ \frac{1}{4} $ days', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.418Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
