INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3102, 'general-test-2023-05-21-shift-1', 'q10', 10, 10, 'Major is related to Lieutenant in the same way as ''Squadron Leader is Related to ''?', '[{"id":"A","text":"Pilot officer"},{"id":"B","text":"Flying Attendant"},{"id":"C","text":"Group captain"},{"id":"D","text":"Flying officer"}]', 0, 'D', 'Major and Squadron Leader are equivalent ranks in Army and Air Force respectively. In the same way Lieutenant and Flying officer are equivalent ranks in Army and Air Force respectively.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3103, 'general-test-2023-05-21-shift-1', 'q11', 11, 11, 'Match List I with List II', '[{"id":"A","text":"A-IV, B-III, C-II, D-I"},{"id":"B","text":"A-III, B-IV, C-II, D-I"},{"id":"C","text":"A-I, B-III, C-II, D-IV"},{"id":"D","text":"A-III, B-I, C-II, I-IV"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q11-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q11-table-1.jpg","page":1,"alt":"Table for question 11"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3104, 'general-test-2023-05-21-shift-1', 'q12', 12, 12, 'Major Constituent of natural gas is _.', '[{"id":"A","text":"Propane"},{"id":"B","text":"Butane"},{"id":"C","text":"Methane"},{"id":"D","text":"Carbon"}]', 0, 'C', 'Natural gas consists of methane (85%), ethane (10%) and little amount of propane and butane. Thus, the major constituent of natural gas would be methane.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3105, 'general-test-2023-05-21-shift-1', 'q13', 13, 13, 'How many terms are there in the A.P. 3, 7, 11, ....., 407?', '[{"id":"A","text":"100"},{"id":"B","text":"101"},{"id":"C","text":"99"},{"id":"D","text":"102"}]', 0, 'D', 'Given 3, 7, 11, ... 407

So given sequence in A.P, with a = 3, d = 4

Now Tn = 407

$ \Rightarrow a + (n - 1)d = 407 $

$ \Rightarrow 3 + (n - 1)4 = 407 $

$ \Rightarrow n = 102 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3106, 'general-test-2023-05-21-shift-1', 'q14', 14, 14, 'Which of the following is a metal?', '[{"id":"A","text":"Carban"},{"id":"B","text":"Mercury"},{"id":"C","text":"Sulphur"},{"id":"D","text":"Iodine"}]', 0, 'B', 'Except mercury, all options belong to non-metal. Thus, mercury is metal.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3107, 'general-test-2023-05-21-shift-1', 'q15', 15, 15, 'X got 98 marks in his exam which is 56% of the total marks. What is the maximum marks of the exam?', '[{"id":"A","text":"150"},{"id":"B","text":"175"},{"id":"C","text":"200"},{"id":"D","text":"225"}]', 0, 'B', '56% → 98

1% → 98/56

100% → $ \frac{98}{56} \times 100 = 175 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3108, 'general-test-2023-05-21-shift-1', 'q16', 16, 16, 'Match List I with List II.', '[{"id":"A","text":"A-IV, B-II, C-III, D-I"},{"id":"B","text":"A-II, B-IV, C-I, D-III"},{"id":"C","text":"A-I, B-II, C-IV, D-II"},{"id":"D","text":"A-III, B-I, C-II, D-IV"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q16-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q16-table-1.jpg","page":2,"alt":"Table for question 16"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3109, 'general-test-2023-05-21-shift-1', 'q17', 17, 17, 'Match List I with List II', '[{"id":"A","text":"A-II. B-III. C-I. D-IV"},{"id":"B","text":"A-III, B-II, C-IV, D-I"},{"id":"C","text":"A-II. B-III. C-IV. D-I"},{"id":"D","text":"A-I, B-III. C-II, D-IV"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q17-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q17-table-1.jpg","page":2,"alt":"Table for question 17"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3110, 'general-test-2023-05-21-shift-1', 'q18', 18, 18, 'Statement I: Constitution is the framework for the governance of a country which delegates power and authority to the executive, legislative and judiciary. Statement II: It serves a country in maintaining good relationships with her neighbouring countries. In the light of the above statements, chose the most appropriate war from the options below.', '[{"id":"A","text":"Both Statement I and Statement II are correct"},{"id":"B","text":"Both Statement I and Statement II are incorrect"},{"id":"C","text":"Statement I is correct but Statement II is incorrect"},{"id":"D","text":"Statement I is incorrect but Statement II is correct"}]', 0, 'A', 'Statement-I: Constitution of India provides for delegation of power and authority among three organs of state viz executive, legislative and judiciary. Thus, it is true statement Statement-II: Constitution through Article 51 provides for maintenance of international peace and good relationships with her neighbouring countries. Thus, this statement is also true.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3111, 'general-test-2023-05-21-shift-1', 'q19', 19, 19, 'Which of the following speeds is the least?', '[{"id":"A","text":"50 meter/second"},{"id":"B","text":"50 meter/minute"},{"id":"C","text":"70 km/hour"},{"id":"D","text":"5 km/minute"}]', 0, 'B', '50 m/s → 180 km/h

50 m/min → 3 km/h

70 km/h → 70 km/h

5 km/min → 300 km/h

So, 50 m/min is the least.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3112, 'general-test-2023-05-21-shift-1', 'q20', 20, 20, 'Which of the following is not a ''state''?', '[{"id":"A","text":"Nagaland"},{"id":"B","text":"Manipur"},{"id":"C","text":"Ladakh"},{"id":"D","text":"Meghalaya"}]', 0, 'C', 'Among the given options, Ladakh is correct because it has been made a Union Territory by The Jammu and Kashmir Reorganisation Act 2019.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.419Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3113, 'general-test-2023-05-21-shift-1', 'q21', 21, 21, 'In a row of 40 children. A is 13th from the left end and B is ninth from the right end. How many children are there between A and C if C is fourth to the left of B.', '[{"id":"A","text":"13"},{"id":"B","text":"14"},{"id":"C","text":"15"},{"id":"D","text":"16"}]', 0, 'B', 'C''s rank from right = 9 + 4 = 13th

So, C''s rank from left = (40 - 13) + 1 = 28th

Number of students between A and C = (28 - 13) - 1 = 14', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3114, 'general-test-2023-05-21-shift-1', 'q22', 22, 22, 'Find the perimeter of a rhombus whose one diagonal is 16 cm long and area is 240 cm².', '[{"id":"A","text":"68 cm"},{"id":"B","text":"30 cm"},{"id":"C","text":"24 cm"},{"id":"D","text":"36 cm"}]', 0, 'A', 'Area = 240 cm², One diagonal = 16 cm

Second diagonal = $ \frac{\text{Area} \times 2}{\text{d}_1} = \frac{240 \times 2}{16} = 30 $ cm

Perimeter =

$ 2\sqrt{(d_1)^2 + (d_2)^2} = 2\sqrt{(16)^2 + (30)^2} = 68 $ cm', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3115, 'general-test-2023-05-21-shift-1', 'q24', 24, 23, 'If today is Saturday, then what will be the day on 363 $ ^{rd} $ day?', '[{"id":"A","text":"Sunday"},{"id":"B","text":"Monday"},{"id":"C","text":"Thursday"},{"id":"D","text":"Friday"}]', 0, 'D', '363/7 = 6 remainder

Saturday + 6 = Friday', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3116, 'general-test-2023-05-21-shift-1', 'q25', 25, 24, 'Arrange the following in meaningful sequence:

A. Key B. Door

C. Lock D. Room', '[{"id":"A","text":"A, C, B, D"},{"id":"B","text":"D, C, A, B"},{"id":"C","text":"B, A, D, C"},{"id":"D","text":"C, B, D, A"}]', 0, 'A', 'At first, we have to key, then we unlock the lock, then open the door and enter into room. So, sequence is $ \rightarrow $ A, C, B, D', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3117, 'general-test-2023-05-21-shift-1', 'q26', 26, 25, 'Find out which of the answer figures', '[{"id":"A","text":","},{"id":"B","text":","},{"id":"C","text":"and"},{"id":"D","text":"completed the figure matrix?"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3118, 'general-test-2023-05-21-shift-1', 'q27', 27, 26, 'Find the next term in the alpha-numeric series D4T, F9R, H20P, J43N.', '[{"id":"A","text":"L 90 M"},{"id":"B","text":"N 90 N"},{"id":"C","text":"L 90 L"},{"id":"D","text":"J 90 L"}]', 0, 'C', 'D 4 T, F 9 R, H 20 P, J 43 N, L 90 L

First letter = +2

Middle number = (×2+1), (×2+2), (×2+3), (×2+4)

Last letter = -2', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.420Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3119, 'general-test-2023-05-21-shift-1', 'q28', 28, 27, 'If the median of $ \frac{x}{5}, x, \frac{x}{4}, \frac{x}{2} $ and $ \frac{x}{3} $ (where x > 0) is 8, then the value of x will be', '[{"id":"A","text":"24"},{"id":"B","text":"32"},{"id":"C","text":"8"},{"id":"D","text":"16"}]', 0, 'A', 'Arrange in ascending order: $ \frac{x}{5}, \frac{x}{4}, \frac{x}{3}, \frac{x}{2}, x $

Middle value $ =\frac{x}{3}=8 \Rightarrow x = 24 $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.421Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3120, 'general-test-2023-05-21-shift-1', 'q29', 29, 28, 'Match List I with List II', '[{"id":"A","text":"A-I. B-III, C-IV, D-II"},{"id":"B","text":"A-III, B-I. C-IV, D-II"},{"id":"C","text":"A-III. B-I. C-II. D-IV"},{"id":"D","text":"A-I. B-IV, C-II, D-III"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q29-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q29-table-1.jpg","page":3,"alt":"Table for question 29"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
