INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3122, 'general-test-2023-05-21-shift-1', 'q31', 31, 30, 'A is 3 years younger than C but one year older than D.

D is one year older than B but 4 years younger than C.

Cis 15 years old. What is the age of B in years', '[{"id":"A","text":"13"},{"id":"B","text":"12"},{"id":"C","text":"11"},{"id":"D","text":"10"}]', 0, 'D', '$$ A=C-3 $$

$$ A=D+1 $$

D=B+1

D=C-4

C = 15 So, D = 11, A = 12, B = 10 So, B''s age is 10 years old.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3123, 'general-test-2023-05-21-shift-1', 'q32', 32, 31, 'A man walks 2 km towards East and then he turns to South and walks 6 km. Again, he turns to East and walks 4 km, after this he turns to North and walk 14 km. How far is he from his starting point?', '[{"id":"A","text":"10 km"},{"id":"B","text":"15 km"},{"id":"C","text":"20 km"},{"id":"D","text":"25 km"}]', 0, 'A', 'Using Pythagoras theorem: $ H^{2} = 64 + 36 = 10 $ Km. So, he is 10 km away from his starting point', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3124, 'general-test-2023-05-21-shift-1', 'q33', 33, 32, 'A bag contains 5 black. 3 white and 2 red balls. Three balls are drawn in succession. What is the probability that the first ball is red, the second ball is black and the third ball is white?', '[{"id":"A","text":"$ \\frac{1}{24} $"},{"id":"B","text":"$ \\frac{3}{10} $"},{"id":"C","text":"$ \\frac{1}{10} $"},{"id":"D","text":"$ \\frac{1}{2} $"}]', 0, 'A', '$$ \frac{2}{10}\times\frac{5}{9}\times\frac{3}{8}=\frac{1}{24} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3125, 'general-test-2023-05-21-shift-1', 'q34', 34, 33, 'What is the smallest square number which is divisible by 4, 6 and 32?', '[{"id":"A","text":"100"},{"id":"B","text":"196"},{"id":"C","text":"96"},{"id":"D","text":"576"}]', 0, 'D', 'L.C.M of 4, 6 and 32 = 96 = 2 $ \times $ 2 $ \times $ 2 $ \times $ 2 $ \times $ 3

2 and 3 are not in pairs, so we multiply them to 96

$ \Rightarrow 96 \times 2 \times 3 = 576 $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3126, 'general-test-2023-05-21-shift-1', 'q35', 35, 34, 'Match List I with List II', '[{"id":"A","text":"A-I. B-III. C-II. D-IV"},{"id":"B","text":"A-II, B-III. C-I, D-IV"},{"id":"C","text":"A-III, B-II, C-IV, D-I"},{"id":"D","text":"A-II, B-III, C-IV, D-I"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q35-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q35-table-1.jpg","page":3,"alt":"Table for question 35"},{"id":"q35-table-2","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q35-table-2.jpg","page":3,"alt":"Table for question 35"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3127, 'general-test-2023-05-21-shift-1', 'q36', 36, 35, 'The only Indian who received noble prize in literature is:', '[{"id":"A","text":"Bankim Chandra Chatterjee"},{"id":"B","text":"Toru Dutt"},{"id":"C","text":"R.K. Narayan"},{"id":"D","text":"Rabindranath Tagore"}]', 0, 'D', '1968 Nobel Prize in the field of physiology or medicine was received by Har Gobind Khorana along with Marshall W. Nirenberg and Robert W. Holley for research that helped to show how the genetic components of the cell nucleus control the synthesis of proteins.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3128, 'general-test-2023-05-21-shift-1', 'q37', 37, 36, 'Match List I with List II Cities with their nicknames', '[{"id":"A","text":"A-III, B-I, C-IV, D-II"},{"id":"B","text":"A-I, B-III, C-IV, D-II"},{"id":"C","text":"A-III, B-I, C-II, D-IV"},{"id":"D","text":"A-II, B-I, C-III, D-IV"}]', 0, 'A', NULL, NULL, 'null', '[]', '[{"id":"q37-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q37-table-1.jpg","page":3,"alt":"Table for question 37"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.422Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3129, 'general-test-2023-05-21-shift-1', 'q38', 38, 37, 'Which of the following is not the satellite launched by India?', '[{"id":"A","text":"Explorer"},{"id":"B","text":"APPLE"},{"id":"C","text":"Bhaskar"},{"id":"D","text":"INSAT"}]', 0, 'A', 'Satellite, APPLE, Bhaskar and INSAT were launched by India or are associated with Indian Space Research Organisation (ISRO) while explorer was the first satellite launched by United States in 1958.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3130, 'general-test-2023-05-21-shift-1', 'q39', 39, 38, 'If the 2nd half of the letters of the word INTERMEDIATE is reversed and placed before 1st half of the letters, which letter will be 2nd to the right of 10th letter from the right?', '[{"id":"A","text":"A"},{"id":"B","text":"D"},{"id":"C","text":"E"},{"id":"D","text":"I"}]', 0, 'B', 'Word: INTERMEDIATE

Reverse 2nd half and placed before 1st half

ETAIDEINTERM

10 - 2 = 8th from right which is D.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3131, 'general-test-2023-05-21-shift-1', 'q40', 40, 39, 'Find the angle of elevation of the Sun when the length of the shadow of a tree is $ \frac{1}{\sqrt{3}} $ times the height of the tree.', '[{"id":"A","text":"$ 30^{\\circ} $"},{"id":"B","text":"$ 45^{\\circ} $"},{"id":"C","text":"$ 60^{\\circ} $"},{"id":"D","text":"$ 90^{\\circ} $"}]', 0, 'C', '$$ \tan\theta=\frac{h}{h/\sqrt{3}} $$

\tan\theta = \sqrt{3}

$ \theta = 60^{0} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3132, 'general-test-2023-05-21-shift-1', 'q41', 41, 40, 'The point (-2, 3) lies in which quadrant?', '[{"id":"A","text":"I"},{"id":"B","text":"II"},{"id":"C","text":"III"},{"id":"D","text":"IV"}]', 0, 'B', '$ (-2, 3) $ here x is negative and y is positive. So, this point lies in 2nd quadrant.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3133, 'general-test-2023-05-21-shift-1', 'q42', 42, 41, 'The rate of ages of 2 boys is 37. After 2 years, the ratio of their ages will become 5:9. The ratio of their ages after 10 years will be', '[{"id":"A","text":"15:16"},{"id":"B","text":"5:17"},{"id":"C","text":"17:18"},{"id":"D","text":"13:17"}]', 0, 'D', 'Let their present age be 3x and 7x.

After two years, $ \frac{3x+2}{7x+2} = \frac{5}{9} $

x = 1

Present age = 3 years and 7 years

After 10 years = 3+10 = 13 and 7 + 10 = 17 = 13 : 17', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3134, 'general-test-2023-05-21-shift-1', 'q43', 43, 42, 'Who won the Noble Prize for in the field of "physiology or medicine"?', '[{"id":"A","text":"C.V. Raman"},{"id":"B","text":"Jagdish Chandra Bose"},{"id":"C","text":"Homi Jehangir Bhabha"},{"id":"D","text":"Har Gobind Khorana"}]', 0, 'D', '1968 Nobel Prize in the field of physiology or medicine was received by Har Gobind Khorana along with Marshall W. Nirenberg and Robert W. Holley for research that helped to show how the genetic components of the cell nucleus control the synthesis of proteins.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3135, 'general-test-2023-05-21-shift-1', 'q44', 44, 43, 'What is the probability that any non-leap year will have 53 Sundays?', '[{"id":"A","text":"1/53"},{"id":"B","text":"2/53"},{"id":"C","text":"1/7"},{"id":"D","text":"2/7"}]', 0, 'C', 'Any non-leap year has 365 days = 52 weeks + 1 day extra.

In 52 weeks, 52 Sundays are confirmed and 1 extra day will be any day of 7 days of week.

So, probability of getting Sunday in this week = 1/7', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3136, 'general-test-2023-05-21-shift-1', 'q45', 45, 44, 'In a class boys stand in a single line. One of the boys is seventeenth in order from both the ends. How many boys are in the class?', '[{"id":"A","text":"34"},{"id":"B","text":"33"},{"id":"C","text":"32"},{"id":"D","text":"27"}]', 0, 'B', 'Rank 1 → 17

Rank 2 → 17

Total = (R1 + R2) - 1 = 34 - 1 = 33', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3137, 'general-test-2023-05-21-shift-1', 'q46', 46, 45, 'What sum of money will amount to Rs. 520 in 5 years and to Rs. 568 in 7 years on simple interest?', '[{"id":"A","text":"Rs. 400"},{"id":"B","text":"Rs. 120"},{"id":"C","text":"Rs. 510"},{"id":"D","text":"Rs. 220"}]', 0, 'A', 'Amount in 5 years = Rs. 520

Amount in 7 years = Rs. 568

Interest of one year = $ \frac{48}{2} $ = Rs. 24

Interest of 5 years = $ 24 \times 5 = Rs.\ 120 $

So, sum = 520 - 120 = Rs. 400', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3138, 'general-test-2023-05-21-shift-1', 'q47', 47, 46, 'The minimum number of colours to required paint all sides of a cube that no two adjacent faces may have the same colour is.', '[{"id":"A","text":"5"},{"id":"B","text":"4"},{"id":"C","text":"3"},{"id":"D","text":"6"}]', 0, 'C', 'Opposite sides have same colours. So, we need three different colours.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3139, 'general-test-2023-05-21-shift-1', 'q49', 49, 47, 'In figure out which Number indicate doctors who are not married and are not professors

Q48. Bhoodan-Gram Dan Movement was initiated by:

(a) Mahatma Gandhi

(b) Vinoba Bhave

(c) Shri Ram Chandra Reddy

(d) Sardar Patel', '[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"1"},{"id":"D","text":"6"}]', 0, 'D', 'Number 1 indicates doctors who are not married and are not professors.', NULL, 'null', '[]', '[{"id":"q49-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-05-21-shift-1/q49-figure-1.jpg","page":4,"alt":"Figure for question 49"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.423Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3140, 'general-test-2023-05-21-shift-1', 'q50', 50, 48, 'The relationship between the values of a country''s imports and its exports is called.', '[{"id":"A","text":"Balance of Trade"},{"id":"B","text":"Balance of Payment"},{"id":"C","text":"Balance of currency"},{"id":"D","text":"Bill of exchange"}]', 0, 'A', 'Balance of Trade is the relationship between values of a country''s imports and its exports. This balance of trade is constituent of balance of payment. Thus, correct answer is balance of trade.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3141, 'general-test-2023-05-21-shift-1', 'q51', 51, 49, 'Statements:

I. Some cars are black

II. Some Lions are cars

Conclusions:

I. Some blacks are Lions

II. No black is Lion', '[{"id":"A","text":"Only I follow"},{"id":"B","text":"Only II follow"},{"id":"C","text":"Either I or II follows"},{"id":"D","text":"None follows"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3142, 'general-test-2023-05-21-shift-1', 'q52', 52, 50, 'The average of 12 numbers is 15 and the average of the first two numbers is 14. What is the average of the remaining numbers?', '[{"id":"A","text":"15"},{"id":"B","text":"15.2"},{"id":"C","text":"14"},{"id":"D","text":"14:2"}]', 0, 'B', 'Sum of 12 numbers = $ 12 \times 15 = 180 $

Sum of first 2 numbers = $ 2 \times 14 = 28 $

Sum of first two + Sum of remaining = 180

Sum of remaining = 180 - 28 = 152

Average = $ \frac{152}{10} $ = 15.2', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3143, 'general-test-2023-05-21-shift-1', 'q53', 53, 51, 'Find a single equivalent increase if the number is successively increased by 20%, 25% and 30%?', '[{"id":"A","text":"75%"},{"id":"B","text":"85%"},{"id":"C","text":"95%"},{"id":"D","text":"35%"}]', 0, 'C', 'Let original number = 100

Then after 20% it will be = 120

After 25% increase it will be = 120 $ \times $ 125\% = 150

After 30\% increase it will be = 150 $ \times $ 130\% = 195

So, single increase = $ \frac{195-100}{100} $ $ \times $ 100 = 95%', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
