INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3147, 'general-test-2023-05-21-shift-1', 'q57', 57, 55, 'Here are some words translated from an artificial language

Holo polo means base ball

Moto prot means my India

Prot shot means India won

Which word could be mean "All India Radio"', '[{"id":"A","text":"Holo polo prot"},{"id":"B","text":"Kud prot nid"},{"id":"C","text":"Prot polo nid"},{"id":"D","text":"Polo nid prot"}]', 0, 'B', '(1) Holo polo → Base ball

(2) Moto prot → My India

(3) Prot shot → India won India → Prot

from (2) and (3) So in 2nd option prot is in middle.

So, this answer because other two words unidentified.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3148, 'general-test-2023-05-21-shift-1', 'q58', 58, 56, 'If selling price of 80 articles is equal to the cost price of 100 articles, then find the gain percentage.', '[{"id":"A","text":"30%"},{"id":"B","text":"25%"},{"id":"C","text":"40%"},{"id":"D","text":"50%"}]', 0, 'B', '$ 100 \times CP = 80 \times SP $

$ \frac{SP}{CP} = \frac{100}{80} = \frac{5}{4} $

Gain \% = $ \left(\frac{5}{4} - 1\right) \times 100 = 25\% $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3149, 'general-test-2023-05-21-shift-1', 'q59', 59, 57, 'Find the angle of elevation of the Sun, when the length of the shadow of a tree is $ \frac{1}{\sqrt{3}} $ times the height of tree.', '[{"id":"A","text":"$ 30^{\\circ} $"},{"id":"B","text":"$ 45^{\\circ} $"},{"id":"C","text":"$ 60^{\\circ} $"},{"id":"D","text":"$ 90^{\\circ} $"}]', 0, 'C', '$$ \tan\theta=\frac{\mathrm{h}}{\mathrm{h}/\sqrt{3}}=\sqrt{3} $$

$$ \theta=60^{0} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.424Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
