INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3155, 'general-test-2023-05-27-shift-1', 'q05', 5, 5, 'The letters L, M, N, O, P, Q, R, S, T in their order is substituted by nine integers 1 to 9 in that order. 4 is assigned to P. The difference between P and T is 5. The difference between N and T is 3. What is the integer assigned to N?', '[{"id":"A","text":"7"},{"id":"B","text":"6"},{"id":"C","text":"5"},{"id":"D","text":"4"}]', 0, 'B', 'ATQ, P is assigned to 4.

Difference b/w P and T is 5, so T is 9

Difference b/w N and T is 3 so N = 9 - 3 = 6

The integer assigned to N is 6.

Hence, 6 is the correct answer.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
