INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3160, 'general-test-2023-05-27-shift-1', 'q10', 10, 10, 'If 3 men or 9 boys can finish a work in 21 days, then in how many days can 5 men and 6 boys finish the same work?', '[{"id":"A","text":"7"},{"id":"B","text":"9"},{"id":"C","text":"11"},{"id":"D","text":"13"}]', 0, 'B', 'Since 3 men or 9 boys do the work in 21 days, 1 man is equivalent to 3 boys.

The work involved is $ 9 \times 21 $ equivalent to 189 boydays.

So, 5 men and 6 boys are the same as $ 15 + 6 = 21 $ boys. So, the time taken is 189 boy-days/21 boys = 9 days.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3161, 'general-test-2023-05-27-shift-1', 'q11', 11, 11, 'The area of the largest circle, that can be drawn inside a rectangle with sides 63 cm and 42 cm is

$ (\pi = \frac{22}{7}) $', '[{"id":"A","text":"1386 cm $ ^{2} $"},{"id":"B","text":"1586 cm $ ^{2} $"},{"id":"C","text":"1786 cm $ ^{2} $"},{"id":"D","text":"1986 cm"}]', 0, 'A', 'The diameter of the circle = breadth of the rectangle = 42 cm

Hence the radius of the circle = 42/2 = 21 cm

The area of the circle = $ \pi r^{2} = \frac{22}{7} \times 21 \times 21 = 1386 \, cm^{2} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3162, 'general-test-2023-05-27-shift-1', 'q12', 12, 12, 'You are alone in the house and there is danger of thieves around. Just then, you hear a knock at door. You would', '[{"id":"A","text":"open the door to see who is there."},{"id":"B","text":"first peep out from the window to confirm whether you know the person"},{"id":"C","text":"not open the door."},{"id":"D","text":"ask the servant to see who is there"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3163, 'general-test-2023-05-27-shift-1', 'q13', 13, 13, 'If A: B = $ \frac{1}{2} $: $ \frac{5}{8} $, B: C = $ \frac{1}{3} $: $ \frac{4}{5} $ and C: D = $ \frac{3}{4} $: $ \frac{5}{16} $ then the ratio A: B: C: D is:', '[{"id":"A","text":"4:5:3:12"},{"id":"B","text":"4:12:3:5"},{"id":"C","text":"4:5:12:5"},{"id":"D","text":"4:12:5:3"}]', 0, 'C', 'A: $B = \frac{1}{2} : \frac{5}{8} = 8 : 2$

$B : C = \frac{1}{3} : \frac{4}{5} = 5 : 12$

$C : D = \frac{3}{4} : \frac{5}{16} = 12 : 5$

$A : B : C : D = 4 : 5 : 12 : 5$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3164, 'general-test-2023-05-27-shift-1', 'q14', 14, 14, 'XY $\Longrightarrow$ Delete the last letter,

YZ $\Longrightarrow$ Replace the fourth letter with next in the alphabet,

ZX $\Longrightarrow$ Reverse the whole sequence of the letters.

Then LOGICAL $\Longrightarrow$ XY $\rightarrow$ YZ $\rightarrow$ ZX $\rightarrow$ ?', '[{"id":"A","text":"ACLOJG"},{"id":"B","text":"ACOJGL"},{"id":"C","text":"ACJGOL"},{"id":"D","text":"ACGJOL"}]', 0, 'C', 'Firstly, last letter will be deleted, so word would be ''LOGICA''

In the next step, $4^{th}$ letter would be replaced by next alphabet, so word would become ''LOGJCA''

In the last step, word would be reversed. So final word would be ''ACJGOL''.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.426Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3165, 'general-test-2023-05-27-shift-1', 'q15', 15, 15, 'Mohit is $15^{\text{th}}$ from the right end in a row of 49 boys.

What is his position from left end?', '[{"id":"A","text":"35"},{"id":"B","text":"26"},{"id":"C","text":"27"},{"id":"D","text":"20"}]', 0, 'A', 'Mohit''s position from the left end = 49 - 15 + 1 = 35', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3166, 'general-test-2023-05-27-shift-1', 'q16', 16, 16, 'If A $(2a+3b, a+6b)$ and B $(3a+4b, 2a+5b)$ are two points, then distance between the points A and B is:', '[{"id":"A","text":"$2(a+b)$"},{"id":"B","text":"$\\sqrt{2}(a^{2}-b^{2})$"},{"id":"C","text":"2ab"},{"id":"D","text":"$\\sqrt{2(a^{2}+b^{2})}$"}]', 0, 'D', 'Distance formula = $ \sqrt{(x_2 - x_1)^2 + (y_2 - y_1^2)} $ =

$ \sqrt{(3a + 4b - 2a - 3b)^2 + (2a + 5b - a - 6b)^2} $

$ \quad = \sqrt{(a + b)^2 + (a - b)^2} $

$ \quad = \sqrt{2(a^2 + b^2)} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3167, 'general-test-2023-05-27-shift-1', 'q17', 17, 17, 'The average of four numbers is 40. If the first number is one-third of the sum of the remaining numbers, then the first number is', '[{"id":"A","text":"35"},{"id":"B","text":"50"},{"id":"C","text":"30"},{"id":"D","text":"40"}]', 0, 'D', 'Let the first number be a

Sum of all four numbers = 4 × 40 = 160

$ a = \frac{1}{4}(160 - a) $

a = 40', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3168, 'general-test-2023-05-27-shift-1', 'q18', 18, 18, 'Pointing to a woman, Venus said, "She is the daughter of the only child of my grandmother." How is the woman related to Venus?', '[{"id":"A","text":"Wife"},{"id":"B","text":"Niece"},{"id":"C","text":"Sister"},{"id":"D","text":"Cousin"}]', 0, 'C', 'Daughter of only child of Venus'' Grandmother - Venus'' mother''s daughter or Venus'' father''s daughter. In both cases woman will be sister of Venus.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3169, 'general-test-2023-05-27-shift-1', 'q19', 19, 19, 'Which of these numbers 6400, 125, 261 and 4913 is not a perfect cube?', '[{"id":"A","text":"6400"},{"id":"B","text":"125"},{"id":"C","text":"9261"},{"id":"D","text":"4913"}]', 0, 'A', '6400 is not a perfect cube.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3170, 'general-test-2023-05-27-shift-1', 'q20', 20, 20, 'A stone statue of priest king has been found from:', '[{"id":"A","text":"Harappa"},{"id":"B","text":"Mohenjo Daro"},{"id":"C","text":"Kalibangan"},{"id":"D","text":"Dholavira Which one of the four answers figure would come at the place of the question mark? (a) $$ \\boxed{\\bigtriangleup\\bigtriangleup\\circ\\Box} $$ (b) $ \\begin{array}{r} \\times \\\\ \\triangle \\bigcirc \\Box \\end{array} $ $$ \\boxed{\\bigcirc\\bigcirc\\bigtriangleup}\\times $$ $$ \\bigotimes_{\\Box}\\bigcirc\\bigtriangleup\\times $$"}]', 0, 'B', 'The stone statue of the Priest King was found in Mohenjo Daro.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3171, 'general-test-2023-05-27-shift-1', 'q22', 22, 21, 'Starting from point A Tianna moves 20m till point C in north east direction before turning to her right. She walks 20m again turning to her right stopping at point B. How far is point A from point B.', '[{"id":"A","text":"$ 20\\sqrt{2}m $"},{"id":"B","text":"$ 10\\sqrt{2}m $"},{"id":"C","text":"20m"},{"id":"D","text":"10m"}]', 0, 'A', 'Required Distance = AB = $ \sqrt{20^2} + 20^2 = 20\sqrt{2} $m', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3172, 'general-test-2023-05-27-shift-1', 'q23', 23, 22, 'In a \triangle ABC right angled at B. if BC = 4 cm and \angle C = 60^{\circ}, then length of AC is:', '[{"id":"A","text":"$ 8\\sqrt{3}cm $"},{"id":"B","text":"$ \\frac{8}{\\sqrt{3}} $"},{"id":"C","text":"6 cm"},{"id":"D","text":"8 cm"}]', 0, 'A', 'Ans. (a)

$ \cos 60^{\circ} = \frac{BC}{AC} $

$ \frac{\sqrt{3}}{2} = \frac{4}{x} $

$ AC = 8\sqrt{3} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3173, 'general-test-2023-05-27-shift-1', 'q24', 24, 23, '_ is the heaviest gas.', '[{"id":"A","text":"Radon gas"},{"id":"B","text":"Carbon Monoxide"},{"id":"C","text":"Sulphur Dioxide"},{"id":"D","text":"Nitrogen Oxide"}]', 0, 'A', 'Radon gas is the heaviest gas. Radon is a radioactive gas that is colorless, odorless, and tasteless.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.427Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3174, 'general-test-2023-05-27-shift-1', 'q25', 25, 24, 'If in a certain code, ALMIRAH is written as BNPMWGO, which would be written as DNRWLUA?', '[{"id":"A","text":"COSGOLT"},{"id":"B","text":"TOGSOLC"},{"id":"C","text":"TOGCLOS"},{"id":"D","text":"CLOSGOT"}]', 0, 'D', 'The first, second, third, fourth, fifth, sixth and seventh letters in the code are respectively one, two, three, four, five, six and seven steps ahead of the corresponding word.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3175, 'general-test-2023-05-27-shift-1', 'q26', 26, 25, 'One litre of water is added to 5 litres of alcohol-water solution having 40% alcohol strength. The strength of alcohol in the new solution will be', '[{"id":"A","text":"33%"},{"id":"B","text":"$ 33\\frac{1}{3}\\% $"},{"id":"C","text":"$ 33\\frac{2}{3}\\% $"},{"id":"D","text":"30%"}]', 0, 'B', '5 liters of alcohol-water solution containing 40% alcohol strength contains 2 liters alcohol. When 1 liter water is added, the mixture becomes 6 liters in volume. Hence, the strength of alcohol in the new solution will be $ \frac{2}{6} \times 100 = 33 \frac{1}{3}\% $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3176, 'general-test-2023-05-27-shift-1', 'q27', 27, 26, 'The mean of observations is 43. Later, it was found that 59 was misread as 69. What would be the correct mean? (correct to two decimal places)', '[{"id":"A","text":"44.11"},{"id":"B","text":"41.89"},{"id":"C","text":"42.11"},{"id":"D","text":"43.89"}]', 0, 'B', 'Sum of observations = $ 9 \times 43 = 387 $

Correct Sum = 387 + 59 - 69 = 377

Correct Mean = $ \frac{377}{9} = 41.89 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3177, 'general-test-2023-05-27-shift-1', 'q28', 28, 27, 'Which gas is used for the manufacturing of Bleaching Powder?', '[{"id":"A","text":"Fluorine gas"},{"id":"B","text":"Chlorine gas"},{"id":"C","text":"Bromine gas"},{"id":"D","text":"Iodine gas"}]', 0, 'B', 'Chlorine gas is widely used in the manufacturing of bleaching powder.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3178, 'general-test-2023-05-27-shift-1', 'q29', 29, 28, 'Which of the following mountain Railways are part of UNESCO''s world Heritage site?

A. Darjeeling Himalayan Railways

B. Nilgiri mountain Railways

C. Kalka-Shimla Railways

D. Mumbai to Thane Railways', '[{"id":"A","text":"A only"},{"id":"B","text":"A, B only"},{"id":"C","text":"A, B, C only"},{"id":"D","text":"A, B, C, D"}]', 0, 'C', 'The Mumbai to Thane Railways are not part of UNESCO''s World Heritage Site.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3179, 'general-test-2023-05-27-shift-1', 'q30', 30, 29, '44% of 80% of a number is 6864. What will be 15% of that number?', '[{"id":"A","text":"2288"},{"id":"B","text":"2882"},{"id":"C","text":"2925"},{"id":"D","text":"2952"}]', 0, 'C', 'Let number be ''x''

As per question, $ \frac{44}{100} \times \frac{80}{100} \times x = 6864 $

x = 19500

Then 15% of x = x $ \times \frac{15}{100} $ = 2925', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3180, 'general-test-2023-05-27-shift-1', 'q31', 31, 30, 'In the given question, arrange the given words in the sequence occur in the dictionary.

(A) Wound

(B) Writer

(C) Whiter

(D) Worst

(E) Worked', '[{"id":"A","text":"A, D, C, E, B"},{"id":"B","text":"B, A, C, D, E"},{"id":"C","text":"C, E, D, A, B"},{"id":"D","text":"E, C, B, A, D"}]', 0, 'C', 'The dictionary sequence is C → E → D → A → B which is Whiter → Worked → Worst → Wound → Writer.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.428Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3181, 'general-test-2023-05-27-shift-1', 'q32', 32, 31, 'A ladder leans against a vertical wall. End of the ladder is 8 m above the ground. When the lower end of the ladder is moved 2 m farther away from

the wall, the other end of the ladder rests against

the foot of the wall. The length of the ladder is:', '[{"id":"A","text":"10 m"},{"id":"B","text":"15 m"},{"id":"C","text":"30 m"},{"id":"D","text":"17 m"}]', 0, 'D', 'Length of the ladder = x + 2

Thus, $ 8^{2} + x^{2} = (x + 2)^{2} $

Solving for x, x = 15

Length of ladder = 17', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.429Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3182, 'general-test-2023-05-27-shift-1', 'q33', 33, 32, 'Two dice are thrown simultaneously. What is the probability that the sum of the two numbers is 4?', '[{"id":"A","text":"$ \\frac{1}{11} $"},{"id":"B","text":"$ \\frac{1}{12} $"},{"id":"C","text":"$ \\frac{1}{13} $"},{"id":"D","text":"$ \\frac{1}{14} $"}]', 0, 'B', 'The set of possible outcomes when we roll a die are {1, 2, 3, 4, 5, 6}

So, when we roll two dice there are $ 6 \times 6 = 36 $ possibilities. When we roll two dice, the possibility of getting number 4 is (1, 3), (2, 2), and (3, 1). So, the number of favourable outcomes = 3

Total number of possibilities = 36

Probability = The number of favourable outcomes / Total number of possibilities = 3/36 = 1/12', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.430Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3183, 'general-test-2023-05-27-shift-1', 'q34', 34, 33, 'The temple not built by Krishna Deva Raya (70 AD-1529) is:', '[{"id":"A","text":"Vijaya Mahal"},{"id":"B","text":"Hazara Rama Temple"},{"id":"C","text":"Sun Temple"},{"id":"D","text":"Vithal Swami Temple"}]', 0, 'C', 'Sun Temple is not associated with Krishna Deva Raya or the Vijayanagara Empire.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.430Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3184, 'general-test-2023-05-27-shift-1', 'q35', 35, 34, 'How many degrees does the minute hand cover in the same time in which the seconds hand cover $ 180^{\circ} $.', '[{"id":"A","text":"18"},{"id":"B","text":"6"},{"id":"C","text":"3"},{"id":"D","text":"180"}]', 0, 'C', 'As we know that the second hand covers $360^{\circ}$ in 1 minute i.e. in 60 seconds. So, the second hand covers $180^{\circ}$ in $=\frac{60}{360^{\circ}}\times180^{\circ}=30$ seconds.

Also, we know that the minute hand covers $6^{\circ}$ in 1 minute i.e. in 60 seconds. Therefore, the minute hand covers in 30 seconds $=\frac{6^{0}}{2}=3^{\circ}$.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.431Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3185, 'general-test-2023-05-27-shift-1', 'q37', 37, 35, 'Where is the ''Indian grape processing Board'' located?', '[{"id":"A","text":"Bengaluru (Karnataka)"},{"id":"B","text":"Kottayam (Kerela)"},{"id":"C","text":"Pune (Maharashtra)"},{"id":"D","text":"Kochi (Kerela)"}]', 0, 'C', 'The Indian Grape Processing Board (IGPB) is a statutory body established under the Ministry of Food Processing Industries, Government of India. It is headquartered in Pune, Maharashtra.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.431Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3186, 'general-test-2023-05-27-shift-1', 'q38', 38, 36, 'The chairman of Drafting Committee of the constitution was:

(a) Dr. Rajendra Prasad

(b) Dr. B.R. Ambedkar

(c) Dr. Zakir Hussain

(d) Pt. Jawahar Lal Nehru

Q36. In a 2-digit number unit''s digit is 5 more than the ten''s digit. If 5 times the given number is 24 more than two times the number obtained by interchanging the digits of the given number, then the given number is:', '[{"id":"A","text":"16"},{"id":"B","text":"27"},{"id":"C","text":"38"},{"id":"D","text":"49"}]', 0, 'B', 'Dr. B.R. Ambedkar, an eminent jurist, scholar, and social reformer, was the chairman of the Drafting Committee of the Constituent Assembly.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.432Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3187, 'general-test-2023-05-27-shift-1', 'q39', 39, 37, 'Which of the following shows the relation between Sun, Earth and Universe?', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'C', 'Sun and Earth are different, but both are part of Universe.', NULL, 'null', '[]', '[{"id":"q39-options","kind":"options","path":"/local-papers/assets/general-test-2023-05-27-shift-1/q39-options.jpg","page":3,"alt":"Printed answer choices for question 39"}]', '[3]', 'keyed', '["image-options"]', '2026-11-05T20:58:59.433Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3188, 'general-test-2023-05-27-shift-1', 'q40', 40, 38, 'Find the area of four walls of a room having length 12.5 m, breadth 9 m and height 7 m', '[{"id":"A","text":"289 m $ ^{2} $"},{"id":"B","text":"300 m $ ^{2} $"},{"id":"C","text":"307 m $ ^{2} $"},{"id":"D","text":"301 m $ ^{2} $"}]', 0, 'D', 'The area of four walls = $ 2(lh + bh) = 2(12.5 \times 7 + 9 \times 7) = 301 \, m^2 $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.433Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3189, 'general-test-2023-05-27-shift-1', 'q41', 41, 39, 'If principal amount is P and rate of interest is R% per annum, then what is the difference between simple interest and compound interest for 2 years?', '[{"id":"A","text":"$ \\frac{PR}{100} $"},{"id":"B","text":"$ \\frac{2PR}{100} $"},{"id":"C","text":"$ \\frac{PR^{2}}{(100)^{3}} $"},{"id":"D","text":"$ \\frac{PR^{2}}{100} $"}]', 0, 'C', 'Simple interest for 2 years = $ \frac{2PR}{100} $

Compound interest for 2 years = $ P(1 + \frac{R}{100})^2 $

Difference = $ \frac{PR^2}{(100)^3} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.434Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3190, 'general-test-2023-05-27-shift-1', 'q42', 42, 40, 'If the radius of a sphere is increased by 50%, then its surface area will increase by:', '[{"id":"A","text":"25%"},{"id":"B","text":"125%"},{"id":"C","text":"150%"},{"id":"D","text":"50%"}]', 0, 'B', 'Let the original radius be r

So, the surface area of the sphere = $ 4\pi r^2 $ ....(1)

Since, the radius is increased by 50% then new

radius = 1.5r

Therefore the new surface area of the sphere will be $ =4\pi(1.5)^2 = 2.25 \times 4\pi r^2 \ldots(2) $

Therefore, the required percentage $ \frac{2.25 \times 4\pi r^2 - 4\pi r^2}{4\pi r^2} \times 100 = 125\% $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.434Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3191, 'general-test-2023-05-27-shift-1', 'q43', 43, 41, '_ satellite was launched on 29th March 2018 from Srihari Kota with the help of PSLV-C40 launch vehicle.', '[{"id":"A","text":"DMC3"},{"id":"B","text":"SARAL"},{"id":"C","text":"Cartosat-2"},{"id":"D","text":"Rohini RS-1"}]', 0, 'C', 'The satellite launched from Sriharikota on March 29th, 2018 with the help of the PSLV-C40 launch vehicle, Cartosat-2.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.434Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3192, 'general-test-2023-05-27-shift-1', 'q44', 44, 42, 'In the year 1996, the republic day was celebrated on Friday. On which day the Independence Day was celebrated in the year 2000?', '[{"id":"A","text":"Monday"},{"id":"B","text":"Tuesday"},{"id":"C","text":"Sunday"},{"id":"D","text":"Friday"}]', 0, 'B', 'The year 1966 was a Leap Year. Number of days remaining in the 1996.

=366 - 26 = 340 days = 48 weeks 4 odd days.

1997, 1998 and 1999 together have 3 odd days.

2000 was a Leap year.

Days upto 15th August 2000 = 31 + 29 + 31 + 30 + 31 + 30 + 31 + 15 = 229 days. $ \frac{228}{7} = 32 $ weeks 4 odd days.

Now, total number of odd days = 4 + 3 + 4 = 11

$ \frac{11}{7} = 1 $ week 4 odd days. 15th August 2000 was 4 days beyond Friday. i.e., Tuesday.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.434Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3193, 'general-test-2023-05-27-shift-1', 'q45', 45, 43, 'Choose the correct mirror image of the given figure, where mirror is represented by a line MN.

M', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'C', NULL, NULL, 'null', '[]', '[{"id":"q45-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-05-27-shift-1/q45-figure-1.jpg","page":3,"alt":"Figure for question 45"},{"id":"q45-options","kind":"options","path":"/local-papers/assets/general-test-2023-05-27-shift-1/q45-options.jpg","page":3,"alt":"Printed answer choices for question 45"}]', '[3]', 'keyed', '["image-options"]', '2026-11-05T20:58:59.435Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3194, 'general-test-2023-05-27-shift-1', 'q46', 46, 44, 'Find the mean proportional between 18 and 72.', '[{"id":"A","text":"36"},{"id":"B","text":"45"},{"id":"C","text":"90"},{"id":"D","text":"72"}]', 0, 'A', '18:x::x:72

