INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3195, 'general-test-2023-05-27-shift-1', 'q47', 47, 45, 'How many ''7''s are preceded by 9 and followed by 6 in the given series?', '[{"id":"A","text":"5"},{"id":"B","text":"4"},{"id":"C","text":"3"},{"id":"D","text":"2"}]', 0, 'D', '''7''s are preceded by 9 and followed by 6 = 9, 7, 6

Given series, 7, 8, $ \underline{\text{9,7,6}} $ 5, 3, 4, 2, 8, 9, 7, 2, 4, 5, 9, 2, $ \underline{\text{9,7,6}} $ 4, 7

Hence, correct answer is two.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.435Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3196, 'general-test-2023-05-27-shift-1', 'q48', 48, 46, 'Statements:

1. Dogs do not bark on the arrival of friends of the family

2. When A entered B''s house, B''s dog started barking.

Conclusion: A is B''s enemy.

The conclusion drawn is:', '[{"id":"A","text":"Follows from the given statements."},{"id":"B","text":"Is probably true."},{"id":"C","text":"Does not follow from the given statements."},{"id":"D","text":"Is probably false."}]', 0, 'C', 'From the statement it is clear that dogs do not bark on the arrival of friends of the family, they only bark on the arrival of some first-time visitor or a stranger. So, it cannot be said that A is B''s enemy. He might be a delivery boy or a person visiting B for the first time. Hence, the answer is option C.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.435Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3197, 'general-test-2023-05-27-shift-1', 'q49', 49, 47, 'Five girls sitting in a row. Raashi is not adjacent to Grace or Adhya. Anu is not adjacent to Grace. Raashi is adjacent to Venus. Venus is at the middle in the row. Then Anu is adjacent to whom?', '[{"id":"A","text":"Raashi"},{"id":"B","text":"Grace"},{"id":"C","text":"Aadhya"},{"id":"D","text":"Venus"}]', 0, 'A', 'Two cases can be made from the given information, but in both the cases Anu is adjacent to Raashi.

$ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Venus}} $ $ \underline{\text{Raashi}} $ $ \underline{\text{Anu}} $

$ \underline{\text{Anu}} $ $ \underline{\text{Raashi}} $ $ \underline{\text{Venus}} $ $ \underline{\text{Grace/Adhya}} $ $ \underline{\text{Grace/Adhya}} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.435Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3198, 'general-test-2023-05-27-shift-1', 'q50', 50, 48, 'Which of the following is not in the UNESCO''s world Heritage site of India?', '[{"id":"A","text":"Sum Temple, Konark"},{"id":"B","text":"Elephanta Caves"},{"id":"C","text":"Western Ghats"},{"id":"D","text":"Golkonda Fort"}]', 0, 'D', 'Golkonda Fort is not a UNESCO World Heritage Site. The other three sites listed in the question are all UNESCO World Heritage Sites.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.435Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
