INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3202, 'general-test-2023-05-27-shift-1', 'q54', 54, 52, 'If 2x, x + 4 and x + 1 are in A.P., then the value of x is:', '[{"id":"A","text":"6"},{"id":"B","text":"$ 6\\frac{1}{2} $"},{"id":"C","text":"7"},{"id":"D","text":"8"}]', 0, 'D', 'Given, 2x, x + 4 and x + 1 are in A.P. Then,

$ (x+4)-2x=(x+1)-(x+4) $

$ x+4-2x=x+1-x-4 $

$ -x+4=-4 $

x=8', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.436Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3203, 'general-test-2023-05-27-shift-1', 'q55', 55, 53, 'Which of the following are true regarding Supreme Court of India?

