INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3204, 'general-test-2023-05-27-shift-1', 'q56', 56, 54, 'The commander of the Armed Force in India is:', '[{"id":"A","text":"Prime Minister"},{"id":"B","text":"President"},{"id":"C","text":"Defence Minister"},{"id":"D","text":"Chief Justice if the supreme court"}]', 0, 'B', 'President is the commander of the Armed Force in India.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.436Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
