INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3206, 'general-test-2023-05-27-shift-1', 'q58', 58, 56, 'The speed of a train is 88 km/h. How much time will it take to cross a 180 m long platform if length of the train is 150 m?', '[{"id":"A","text":"$ 11\\frac{1}{2}s $"},{"id":"B","text":"$ 10\\frac{1}{2}s $"},{"id":"C","text":"$ 13\\frac{1}{2}s $"},{"id":"D","text":"$ 14\\frac{1}{2}s $"}]', 0, 'C', 'Speed of train in m/sec = $ 88 \times \frac{5}{18} = 24.4 $

Distance to cover = 180 + 150 = 330 m

Time taken by train = $ \frac{330}{24.4} = 13\frac{1}{2} $ s', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.436Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3207, 'general-test-2023-05-27-shift-1', 'q59', 59, 57, 'The Indian giant who got maximum Grammy Award is:', '[{"id":"A","text":"Pt. Ravi Shankar"},{"id":"B","text":"Zakir Hussain"},{"id":"C","text":"Zubin Mehta"},{"id":"D","text":"A. R. Rehman"}]', 0, 'A', 'The Indian giant who got the maximum Grammy Awards is Pt. Ravi Shankar.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.436Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3208, 'general-test-2023-05-27-shift-1', 'q60', 60, 58, 'Who is the author of book "Unhappy India"?', '[{"id":"A","text":"M. K. Gandhi"},{"id":"B","text":"Lala-Lajpat Rai"},{"id":"C","text":"Vijay Tendulkar"},{"id":"D","text":"Swami Shivanand"}]', 0, 'B', '"Unhappy India" is a book written by Lala Lajpat Rai, a prominent freedom fighter and leader of the Indian independence movement.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.436Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3209, 'general-test-2023-06-05-shift-1', 'q01', 1, 1, 'A sum of is ₹ 5100 is divided amongst A, B and C, such that the ratio of shares of A and B is 1:2 that of B and C is 3:4. Find the sum of the shares of A and B.', '[{"id":"A","text":"₹ 3400"},{"id":"B","text":"₹ 3060"},{"id":"C","text":"₹ 2880"},{"id":"D","text":"₹ 2700"}]', 0, 'D', 'Total sum of money = Rs. 5100

The ratio of the share of A and B = 1 : 2

The ratio of the share of B and C = 3 : 4

Ratio of A and B = (1 : 2) × 3 = 3 : 6

Ratio of B and C = (3 : 4) × 2 = 6 : 8

Ratio of A, B and C = 3 : 6 : 8

Total Sum = 3x + 6x + 8x

5100 = 17x

x = 300

Sum of the shares of A and B = ₹ 2700', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3210, 'general-test-2023-06-05-shift-1', 'q02', 2, 2, 'Mirror image of D L 9 C G 4 7 2 8:', '[{"id":"A","text":"8 5 ∇ ₹ ⊃ ⊝ D"},{"id":"B","text":"D ⊄ ⊄ ⊄ ⊄ ⊄ ⊄ 8"},{"id":"C","text":"8 5 ∇ ⊄ ⊄ ⊄ ⊄ ⊄ D"},{"id":"D","text":"8 5 ∇ ⊄ ⊄ ⊄ ⊄ D"}]', 0, 'A', 'DraCC458', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
