INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3212, 'general-test-2023-06-05-shift-1', 'q06', 6, 4, 'A box (12 + x) red balls and (18 + x) green balls. A ball is drawn at random and is found to be red. If the probability of drawn ball is $ \frac{5}{12} $, then find the value of x.', '[{"id":"A","text":"4"},{"id":"B","text":"3"},{"id":"C","text":"2"},{"id":"D","text":"5"}]', 0, 'B', 'Given, Probability of drawn ball = $ \frac{5}{12} $

