INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3215, 'general-test-2023-06-05-shift-1', 'q09', 9, 7, 'Who said "Swaraj is my birthright and I shall have it"?', '[{"id":"A","text":"Jawahar Lal Nehru"},{"id":"B","text":"Mahatma Gandhi"},{"id":"C","text":"Lala Lajpat Rai"},{"id":"D","text":"Bal Gangadhar Tilak"}]', 0, 'D', 'Bal Gangadhar Tilak was a prominent Indian nationalist leader who is credited with popularizing the slogan "Swaraj is my birthright and I will have it."', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3216, 'general-test-2023-06-05-shift-1', 'q10', 10, 8, 'Given that:

