INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3217, 'general-test-2023-06-05-shift-1', 'q11', 11, 9, 'Rome (Italy) is situated on _ river.', '[{"id":"A","text":"Tiber"},{"id":"B","text":"Vistula"},{"id":"C","text":"Thames"},{"id":"D","text":"Seine"}]', 0, 'A', 'Rome, Italy is situated on the Tiber River.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3218, 'general-test-2023-06-05-shift-1', 'q12', 12, 10, 'An exterior angle of a regular polygon is $ 24^{\circ} $. How many sides will the polygon have?', '[{"id":"A","text":"12"},{"id":"B","text":"10"},{"id":"C","text":"15"},{"id":"D","text":"16"}]', 0, 'C', 'If an exterior angle of a regular polygon measures $ 24^{\circ} $, the polygon has 15 sides.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3219, 'general-test-2023-06-05-shift-1', 'q13', 13, 11, 'Find the area (in $ cm^{2} $ of the figure ABCDEF when all its sides are perpendicular to their adjacent sides.', '[{"id":"A","text":"28.5"},{"id":"B","text":"30"},{"id":"C","text":"30.5"},{"id":"D","text":"33"}]', 0, 'C', 'Area of ABCDEF = $ (9 \times 4.5) - (4 \times 2.5) = 40.5 - 10 = 30.5 $ cm $ ^{2} $', NULL, 'null', '[]', '[{"id":"q13-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-06-05-shift-1/q13-figure-1.jpg","page":1,"alt":"Figure for question 13"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.437Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3220, 'general-test-2023-06-05-shift-1', 'q14', 14, 12, 'In a Geometric Progression, if the product of the first three terms is $ \frac{27}{8} $, then its second term is:', '[{"id":"A","text":"$ \\frac{3}{2} $"},{"id":"B","text":"$ \\frac{9}{4} $"},{"id":"C","text":"$ \\frac{9}{2} $"},{"id":"D","text":"1"}]', 0, 'A', 'Let the 3 terms of GP be $ \frac{a}{r} $, a, ar

Product of these terms = $ \frac{a}{r} \times a \times ar = a^{3} $

ATQ, $ a^{3} = \frac{27}{8} $

$ a = \frac{3}{2} $

Then, second term = $ \frac{3}{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3221, 'general-test-2023-06-05-shift-1', 'q15', 15, 13, 'If 30 ml solution of 20% alcohol is mixed with 20 ml solution of 25% alcohol, then what is the strength of alcohol in the mixture?', '[{"id":"A","text":"23%"},{"id":"B","text":"21.5%"},{"id":"C","text":"22%"},{"id":"D","text":"22.5%"}]', 0, 'C', 'Quantity of alcohol in 30 ml solution = 20% of 30 ml = 6 ml

Quantity of alcohol in 20 ml solution = 25% of 20 ml = 5 ml

Percentage of alcohol in the mixture = $ \frac{6+5}{(30+20)} \times 100 = 22\% $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3222, 'general-test-2023-06-05-shift-1', 'q16', 16, 14, 'Given below are two statements: one is labelled as Assertion (A) and the other is labelled as Reason (R). Assertion (A): DDT has nowadays lost its use as an Insecticide.

Reason (R): DDT is harmful to man.

In the light of the above statements, choose the most appropriate answer from the options given below:', '[{"id":"A","text":"Both (A) and (R) are correct and (R) is the correct explanation of (A)"},{"id":"B","text":"Both (A) and (R) are correct but (R) is not the correct explanation of (A)"},{"id":"C","text":"(A) is correct but (R) is not correct"},{"id":"D","text":"(A) is not correct but (R) is correct"}]', 0, 'B', 'Both (A) and (R) are correct but (R) is not the correct explanation of (A).', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3223, 'general-test-2023-06-05-shift-1', 'q17', 17, 15, 'Mahatma Buddha was born at _.', '[{"id":"A","text":"Vaishali"},{"id":"B","text":"Kapilvastu"},{"id":"C","text":"Lumbini"},{"id":"D","text":"Patliputra"}]', 0, 'C', 'Lumbini is a UNESCO World Heritage Site located in the Terai plains of southern Nepal. It is the birthplace of Siddhartha Gautama, who later became the Buddha.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3224, 'general-test-2023-06-05-shift-1', 'q18', 18, 16, 'Which Fundamental Right can be described as the soul and heat of the Constitution?', '[{"id":"A","text":"Right to Equality"},{"id":"B","text":"Right against exploitation"},{"id":"C","text":"Right of Freedom"},{"id":"D","text":"Rights to Constitutional Remedies"}]', 0, 'D', 'The Fundamental Right that can be described as the "heart and soul" of the Constitution of India is the "Right to Constitutional Remedies." This right, guaranteed under Article 32 of the Indian Constitution, enables citizens to seek legal remedies and enforcement of their other fundamental rights through the Supreme Court of India. It is considered crucial for the protection and enforcement of all other fundamental rights, making it the cornerstone of the Constitution.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3225, 'general-test-2023-06-05-shift-1', 'q19', 19, 17, 'On dividing a number by 38, we get 90 quotient and 19 as reminder. What is the number?', '[{"id":"A","text":"3439"},{"id":"B","text":"3401"},{"id":"C","text":"3382"},{"id":"D","text":"3458"}]', 0, 'A', 'Let the number be x

We know, x = Divisor $ \times $ Quotient + R

x = 38 $ \times $ 90 + 19

x = 3439', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3226, 'general-test-2023-06-05-shift-1', 'q20', 20, 18, 'ISRO launched a digital platform on August 12, 2022. This platform is known as:', '[{"id":"A","text":"SAMARTH"},{"id":"B","text":"SARTHAK"},{"id":"C","text":"SPARK"},{"id":"D","text":"INSAT"}]', 0, 'C', 'ISRO launched a digital platform on August 12, 2022 called SPARK, which stands for Space Exploration and Research Platform. It is a virtual space museum that showcases various ISRO missions with an interactive interface.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3227, 'general-test-2023-06-05-shift-1', 'q21', 21, 19, 'The average of five consecutive natural numbers is 13.

If next two natural numbers are also included, then

find the new average.', '[{"id":"A","text":"13"},{"id":"B","text":"13.5"},{"id":"C","text":"16"},{"id":"D","text":"13.75"}]', 0, 'C', 'We know, Total = Average $ \times $ Number of entities

ATQ, $ n + (n+1) + (n+2) + (n+3) + (n+4) = 5 \times 13 $

$ 5n + 10 = 65 $

$ n = \frac{65}{5} = 13 $

Sum of the seven numbers = 7n + 21 = $ 7 \times 13 + 21 = 112 $

Average of the seven numbers = $ \frac{112}{7} = 16 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3228, 'general-test-2023-06-05-shift-1', 'q22', 22, 20, 'If a man starts at 7 a.m. at $ \frac{5}{4} $ of his usual speed, he reaches office 30 minutes early than usual. So, with a new speed at what time he reached his office?', '[{"id":"A","text":"9:30 a.m."},{"id":"B","text":"10 a.m."},{"id":"C","text":"9 a.m."},{"id":"D","text":"8:25 a.m."}]', 0, 'C', 'Time is inversely proportion to speed.

Let usual speed of the person be 4x

Speed of the person after decreasing = 5x

Ratio of usual speed to the after decreasing = 4x : 5x

Ratio of usual time to after decreasing = 5x : 4x

5x - 4x = 30

x = 30

Then 4x = 120 min

New time when the person reaches the office = 9 am', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.438Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3229, 'general-test-2023-06-05-shift-1', 'q23', 23, 21, 'On compound interest, a certain sum amounts to ₹7350 in 2 years and to ₹8575 in 3 years. Find the rate of interest.', '[{"id":"A","text":"$ \\frac{25}{3}\\% $"},{"id":"B","text":"$ \\frac{50}{3}\\% $"},{"id":"C","text":"25%"},{"id":"D","text":"33%"}]', 0, 'B', 'SI on Rs. 7350 for 1 year = Rs. (8575 - 7350) = Rs. 1225

Rate = $ \frac{100 \times 1225}{7350 \times 1} $% = $ \frac{50}{3} $%', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.439Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
