INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3233, 'general-test-2023-06-05-shift-1', 'q27', 27, 25, 'In certain system of coding the word STATEMENT is written as TNEMETATS. In the same way coding, the code for the word "POLITICAL"?', '[{"id":"A","text":"LACITILOP"},{"id":"B","text":"LCATILOP"},{"id":"C","text":"OPILITACL"},{"id":"D","text":"OPILATACL"}]', 0, 'A', 'The letters are reversed to obtain the code. So, code for ''POLITICAL'' will be ''LACITILOP''.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.439Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3234, 'general-test-2023-06-05-shift-1', 'q28', 28, 26, 'A can do a work in 12 days. B''s efficiency to do the work is 50% more than that of A. In how many days will B be able to do the work?', '[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"5"},{"id":"D","text":"11"}]', 0, 'A', 'We know, Total work = Efficiency * Num of days to finish the work

Efficiency ratio of A and B (A : B) = 100 : 150 = 2 : 3

Let A''s efficiency = 2s then B''s efficiency = 3a

Now, total work done by A = 2a × 12 = 24a

Same work done by B in = 24a/3a = 8 days

B alone will take 8 days to complete the same work.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3235, 'general-test-2023-06-05-shift-1', 'q29', 29, 27, 'An ice cream is in the form of a cone surmounted by a hemisphere. If the base radius of the cone in 3.5 cm and height of the ice cream is 10 cm, then find the volume of the ice cream (in cm³).

$ \left(\pi=\frac{22}{7}\right) $', '[{"id":"A","text":"186.92"},{"id":"B","text":"109.08"},{"id":"C","text":"173.25"},{"id":"D","text":"218.16"}]', 0, 'C', 'Radius of cone = Radius of hemisphere

Given, r = 3.5 and Total height = 10 cm

Height of conical shape = 10 - 3.5 = 6.5 cm

Volume of ice cream in the cone = volume of conical part + volume of hemisphere

= $ \frac{1}{3}\pi r^{2}h + \frac{2}{3}\pi r^{3} $

$ \frac{1}{3}\pi r^{2}(h + 2r) $

= $ \frac{1}{3} \times \frac{22}{7} \times (3.5)^{2}(6.5 + 7) $

Volume of ice cream = 173.25 cm³', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3236, 'general-test-2023-06-05-shift-1', 'q30', 30, 28, 'Fractions $ \frac{3}{4}, \frac{2}{3}, \frac{5}{6}, \frac{11}{18} $, when written in descending order are:', '[{"id":"A","text":"$ \\frac{11}{18}, \\frac{2}{3}, \\frac{5}{6}, \\frac{3}{4} $"},{"id":"B","text":"$ \\frac{5}{6}, \\frac{2}{3}, \\frac{3}{4}, \\frac{11}{18} $"},{"id":"C","text":"$ \\frac{2}{3}, \\frac{5}{6}, \\frac{3}{4}, \\frac{11}{18} $"},{"id":"D","text":"$ \\frac{5}{6}, \\frac{3}{4}, \\frac{2}{3}, \\frac{11}{18} $"}]', 0, 'D', '$$ \frac{5}{6},\frac{3}{4},\frac{2}{3},\frac{11}{18} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3237, 'general-test-2023-06-05-shift-1', 'q31', 31, 29, 'If point $ (x, y) $ is equidistant from the points $ (7, 1) $ and $ (3, 5) $, then which one of the following options is correct?', '[{"id":"A","text":"x - y = 2"},{"id":"B","text":"$ x + y = 2 $"},{"id":"C","text":"x - y = 1"},{"id":"D","text":"x - y = -2"}]', 0, 'A', 'ol. Using distance formula

$ \sqrt{(x-7)^{2}+(y-1)^{2}}=\sqrt{(x-3)^{2}+(y-5)^{2}} $

$ -14x+49-2y+1=-6x+9-10y+25 $

$ 8x-8y=16 $

x - y = 2', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3238, 'general-test-2023-06-05-shift-1', 'q33', 33, 30, 'Milk always contains:', '[{"id":"A","text":"Water"},{"id":"B","text":"Calcium"},{"id":"C","text":"Fats"},{"id":"D","text":"Sugar"}]', 0, 'B', 'Milk always contains calcium.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3239, 'general-test-2023-06-05-shift-1', 'q34', 34, 31, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(II), (B)-(IV), (C)-(III), (D)-(I)"},{"id":"B","text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)"},{"id":"C","text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"},{"id":"D","text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)"}]', 0, 'B', '(A)-(II), (B)-(IV), (C)-(I), (D)-(III)', NULL, 'null', '[]', '[{"id":"q34-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-05-shift-1/q34-table-1.jpg","page":3,"alt":"Table for question 34"},{"id":"q34-table-2","kind":"table","path":"/local-papers/assets/general-test-2023-06-05-shift-1/q34-table-2.jpg","page":3,"alt":"Table for question 34"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.440Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3240, 'general-test-2023-06-05-shift-1', 'q35', 35, 32, 'Five students are standing in a circle and all are facing towards the centre of circle. Apurva is on left of Abhishek. Alok is on the left of Apurva. Abinav is b/w Alok and Ankur. Who is sitting next to Abhinav on his immediate right.', '[{"id":"A","text":"Alok"},{"id":"B","text":"Abhishek"},{"id":"C","text":"Apurva"},{"id":"D","text":"Ankur"}]', 0, 'A', 'Clearly Alok is sitting to immediate right of Abhinav.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.441Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3241, 'general-test-2023-06-05-shift-1', 'q36', 36, 33, 'The value of $ \frac{(4.2)^{3}}{(2.1)^{2}} $ is:', '[{"id":"A","text":"2"},{"id":"B","text":"8"},{"id":"C","text":"16.8"},{"id":"D","text":"19.4"}]', 0, 'C', '16.8', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.441Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3242, 'general-test-2023-06-05-shift-1', 'q37', 37, 34, 'Ministry of Social Justice and Empowerment decided to observe "Constitution Day" on _.', '[{"id":"A","text":"26th November"},{"id":"B","text":"26th December"},{"id":"C","text":"16th November"},{"id":"D","text":"16th December"}]', 0, 'A', 'The Ministry of Social Justice and Empowerment on 19th November 2015 notified the decision of Government of India to celebrate the 26th day of November every year as ''Constitution Day'' to promote Constitution values among citizens.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.441Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3243, 'general-test-2023-06-05-shift-1', 'q38', 38, 35, 'If Republic Day of India in 1980 falls on Saturday. Mohan was born on 3 $ ^{rd} $ March 1980 and Sohan is 4 days older to Mohan, then Sohan''s birthday falls on:', '[{"id":"A","text":"Wednesday"},{"id":"B","text":"Thursday"},{"id":"C","text":"Sunday"},{"id":"D","text":"Saturday"}]', 0, 'B', 'Republic Day i.e, 26th January of 1980 falls on Saturday.

Mohan was born on March 3, 1980.

Sohan is older to Mohan by 4 days, so Sohan was born 4 days before March 3, 1980. As 1980 is a leap year, there are 29 days in February. So, Y was born on 28th February.

No. of days between 26th January to 28th February is 33. And 33 when divided by 7, we get 5 as remainder. 5 days after Saturday is Thursday. So, 28th February, the day Sohan was born falls on Thursday.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.441Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3244, 'general-test-2023-06-05-shift-1', 'q39', 39, 36, 'Which scientist is known as "Birdman of India"?', '[{"id":"A","text":"Salim Ali"},{"id":"B","text":"Gulam Ali"},{"id":"C","text":"Noshad Ali"},{"id":"D","text":"J.C. Bose"}]', 0, 'A', 'The scientist known as the "Birdman of India" is Salim Ali. He was a prominent Indian ornithologist and naturalist known for his extensive work in the field of ornithology and bird conservation.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.442Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3245, 'general-test-2023-06-05-shift-1', 'q40', 40, 37, 'Statements:

(I) Some books are eraser.

(II) Some erasers are black.

(III) No black is green

Conclusions:

(I) Some books are green.

(II) All erasers are green.

Which of the following conclusions can be definitely drawn from the statements given in the options?', '[{"id":"A","text":"Only (I) follows"},{"id":"B","text":"Neither (I) nor (II) follows"},{"id":"C","text":"Only (II) follows"},{"id":"D","text":"Either (I) or (II) follows"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.442Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3246, 'general-test-2023-06-05-shift-1', 'q41', 41, 38, 'The cost of 5 kg apples and 3 kg oranges is ₹ 535. If the cost of 8 kg apples and 6 kg oranges is ₹ 910, then what is the cost of 2 kg apples and 8 kg oranges?', '[{"id":"A","text":"₹ 803"},{"id":"B","text":"₹ 680"},{"id":"C","text":"₹ 520"},{"id":"D","text":"₹ 650"}]', 0, 'C', 'Let the cost of an orange = Rs. x

And cost of an apple = Rs. y

ATQ, 5x + 3y = 535

And 8x + 6y = 910

4x + 3y = 455

By solving both equations, we get x = 40 and y = 35

The cost of 2 kg apples and 8 kg oranges = ₹520', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.442Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3247, 'general-test-2023-06-05-shift-1', 'q42', 42, 39, 'Match List - I with List - II', '[{"id":"A","text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)"},{"id":"B","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"C","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"},{"id":"D","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"}]', 0, 'B', '(A)-(IV), (B)-(III), (C)-(I), (D)-(II)', NULL, 'null', '[]', '[{"id":"q42-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-05-shift-1/q42-table-1.jpg","page":4,"alt":"Table for question 42"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.442Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3248, 'general-test-2023-06-05-shift-1', 'q43', 43, 40, 'At what time between 5 and 6 O''clock are the hands of a Clock coincides?', '[{"id":"A","text":"$ 27\\frac{3}{11} $ min past 5"},{"id":"B","text":"$ 22\\frac{8}{11} $ min past 4"},{"id":"C","text":"30 min past 5"},{"id":"D","text":"22 min past 4"}]', 0, 'A', 'The angle between the hour hand and minutes hand

$ \theta = (30H - 11M/2) $

H = 5 and angle = $ 0^{\circ} $

When minute & hour hands coincide, then $ \theta $

$ \Rightarrow 0 = 30 \times 5 - 11M/2 $

$ \Rightarrow 0 = 150 - 11M/2 $

$ \Rightarrow 150 = 11M/2 $

$ \Rightarrow 300 = 11M $

$ \Rightarrow M = \frac{300}{11} $

$ \Rightarrow M = 27\frac{3}{11} $ Minutes

The correct answer is 27\frac{3}{11} minutes past 5.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.442Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
