INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3263, 'general-test-2023-06-05-shift-1', 'q58', 58, 55, 'How many daughters does D have?

Statement (I): B and F are sister of A.

Statement (II): C is the brother of A and F.

Statement (III): C and E are sons of D.

Choose the correct option to decide whether the data provided in the statements are sufficient to answer the question:', '[{"id":"A","text":"I alone is Sufficient"},{"id":"B","text":"I & II together are Sufficient"},{"id":"C","text":"II & III together are Sufficient"},{"id":"D","text":"All the statements together are not sufficient"}]', 0, 'D', 'Statement I alone is not sufficient, as no information is given related to D.

Statement II alone is not sufficient, as no information is given related to D.

Statement III alone is not sufficient, as no information is given related to daughters of D.

If we combine all the three statements, it is not possible to determine how many daughters D have. Therefore, all the statements together are not sufficient.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.447Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3264, 'general-test-2023-06-05-shift-1', 'q59', 59, 56, 'Which are the correct examples of Newton''s $ 3^{rd} $ law motion?

