INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3265, 'general-test-2023-06-05-shift-1', 'q60', 60, 57, 'P sold an item for ₹70 and earned 100% profit. What should be the selling price of the item to earn 150% profit?', '[{"id":"A","text":"₹105"},{"id":"B","text":"₹52.50"},{"id":"C","text":"₹87.50"},{"id":"D","text":"₹150"}]', 0, 'C', 'Selling price should be ₹ 87.50 to earn 150% profit.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.447Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3266, 'general-test-2023-06-09-shift-2', 'q01', 1, 1, 'In a 40 litre mixture of milk and water, the ratio of milk to water is 3 : 1. How much water (in litres) should be added to make this ratio 2 : 3?', '[{"id":"A","text":"30"},{"id":"B","text":"45"},{"id":"C","text":"35"},{"id":"D","text":"40"}]', 0, 'C', 'Milk in mixture = $ \frac{3}{4} \times 40 = 30 $

Water in mixture = 40 - 30 = 10

Let x its milk be added

New ratio of milk and water = 2 : 3

30 + x : 10 = 2 : 3

3(30 + x) = 20

x = 35

Quantity of milk to be added is 35 ltrs.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.450Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3267, 'general-test-2023-06-09-shift-2', 'q02', 2, 2, 'The average of five consecutive natural numbers is 50. What is the product of the smallest and the largest of the numbers?', '[{"id":"A","text":"2496"},{"id":"B","text":"2560"},{"id":"C","text":"3200"},{"id":"D","text":"1800"}]', 0, 'A', 'Let the first number be $x$.

Sum of 5 consecutive number is $= 50 \times 5 = 250$

ATQ, $x + x + 1 + x + 2 + x + 3 + x + 4 = 250$

$5x + 10 = 250$

$5x = 240$

$x = 48$

Product of smallest to largest $= x(x + 4) = 48 \times 52 = 2496$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.450Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3268, 'general-test-2023-06-09-shift-2', 'q03', 3, 3, 'The Malacca Strait located between Indonesia-Malaysia joins Andaman Sea to:', '[{"id":"A","text":"Bay of Bengal"},{"id":"B","text":"Tasman Sea"},{"id":"C","text":"South China Sea"},{"id":"D","text":"Red Sea"}]', 0, 'C', 'The Malacca Strait located between Indonesia-Malaysia joins Andaman Sea to the South China Sea.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.450Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3269, 'general-test-2023-06-09-shift-2', 'q04', 4, 4, 'What will be the area of a right-angled triangle whose hypotenuse is 10 cm and base is 6 cm?', '[{"id":"A","text":"60 sq cm"},{"id":"B","text":"24 sq cm"},{"id":"C","text":"48 sq cm"},{"id":"D","text":"30 sq cm"}]', 0, 'B', 'Hypotenuse = 10 cm, Base = 6 cm

Height (h) = $ \sqrt{c^2 - b^2} = \sqrt{10^2 - 6^2} = 8 $ cm

Area = $ \frac{1}{2} \times $ base × height = $ \frac{1}{2} \times 8 \times 6 = 24 $ cm $ ^2 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.450Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3270, 'general-test-2023-06-09-shift-2', 'q05', 5, 5, '₹2000 amounts to ₹2226.05 in 2 years on compound interest. What is the rate of interest per annum?', '[{"id":"A","text":"5%"},{"id":"B","text":"5.25%"},{"id":"C","text":"5.5%"},{"id":"D","text":"6%"}]', 0, 'C', 'We know, $A = P \left[1 + \frac{R}{100}\right]^n$

2226.05 = 2000 $\left[1 + \frac{R}{100}\right]^2$

$\frac{2226.05}{2000} = \left[1 + \frac{R}{100}\right]^2$

1.113025 = $\left[1 + \frac{R}{100}\right]^2$

1.055 = $\left[\frac{100 + R}{100}\right]$

105.5 = 100 + R', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.451Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3271, 'general-test-2023-06-09-shift-2', 'q06', 6, 6, 'A, B and C started a business on partnership by investing ₹29000, ₹50,000 and ₹65,000 respectively. After 8 months, A invested ₹24,000 more while C withdrew ₹15,000. If profit earned at the end of the year is ₹1,04,000, then find the share of C in the profit.', '[{"id":"A","text":"₹38,000"},{"id":"B","text":"₹38,850"},{"id":"C","text":"₹39,200"},{"id":"D","text":"₹39,000"}]', 0, 'D', 'A''s investment:

For the first 8 months = Rs. 42000

For next 4 months = Rs. 42000 + Rs. 24,000 = Rs. 66,000

B''s investment for the entire year = Rs. 50,000

C''s investment:

For the first 8 months: Rs. 65,000

For the next 4 months = Rs. 65,000 - Rs. 15,000 = Rs. 50,000

A''s Total Investment:

For the first 8 months: ₹42,000 * 8 = ₹336,000.

For the next 4 months: ₹66,000 * 4 = ₹264,000.

Total = ₹336,000 + ₹264,000.

B''s Total Investment:

For the entire year: ₹50,000 * 12 = ₹600,000. C''s Total Investment:

For the first 8 months: ₹65,000 * 8 = ₹520,000.

For the next 4 months: ₹50,000 * 4 = ₹200,000.

$$ Total=₹520,000+₹200,000. $$

Given that the total profit at the end of the year is $ \pounds 1,04,000 $, C''s share in the profit, based on their proportion of the total investment, is $ \pounds 39,000 $.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.451Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3272, 'general-test-2023-06-09-shift-2', 'q07', 7, 7, 'Find the next term in the alpha numeric series:

