INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3280, 'general-test-2023-06-09-shift-2', 'q15', 15, 15, 'Angle of elevation of the top of a building from a point P on the horizontal is $ 30^{\circ} $. If the point P is 48 m away from the foot of the building, then what is the height of the building?', '[{"id":"A","text":"$ 48\\sqrt{3} $ m"},{"id":"B","text":"$ 32\\sqrt{3} $ m"},{"id":"C","text":"$ 16\\sqrt{3} $ m"},{"id":"D","text":"$ 28\\sqrt{3} $ m"}]', 0, 'C', 'Let height of the building be x

