INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3299, 'general-test-2023-06-09-shift-2', 'q34', 34, 34, 'A dealer of scientific instruments allows 20% discount and still makes a profit of 25%. If his gain on sale of an instrument is ₹150, then find the marked price of the instrument.', '[{"id":"A","text":"₹826.25"},{"id":"B","text":"₹750"},{"id":"C","text":"₹937.50"},{"id":"D","text":"₹428.75"}]', 0, 'C', 'Let C.P of instrument = Rs. 100

Profit = 25% of Rs. 100 = Rs. 25

If profit is Rs. 150, $ C.P = \frac{100}{25} \times 150 = 600 $

S.P of the instrument = 600 + 150 = Rs. 750

Let M.P of the instrument be Rs. 100

If S.P is Rs. 80, $ M.P = \frac{100}{80} \times 750 = 937.50 $

Thus, marked price of the investment = Rs. 937.50', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.454Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
