INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3302, 'general-test-2023-06-09-shift-2', 'q37', 37, 37, 'A train travels at 82.6 km/hr. How many meters will it cover in 15 minutes?', '[{"id":"A","text":"20650"},{"id":"B","text":"21650"},{"id":"C","text":"18550"},{"id":"D","text":"17950"}]', 0, 'A', '1 hour = 82.6 km

