INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3303, 'general-test-2023-06-09-shift-2', 'q38', 38, 38, 'Simran can complete a work in 20 days. How much work will be done by her in 12 days?', '[{"id":"A","text":"$ \\frac{3}{5} $"},{"id":"B","text":"$ \\frac{5}{8} $"},{"id":"C","text":"$ \\frac{4}{5} $"},{"id":"D","text":"$ \\frac{2}{3} $"}]', 0, 'A', 'Work done by Simran in 12 days = $ \frac{3}{5} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.454Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
