INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3305, 'general-test-2023-06-09-shift-2', 'q40', 40, 40, 'Mahesh and Sujain are ranked eighth and eleventh respectively from the top in a class of 32 students. What will be their respective ranks from the bottom in the class?', '[{"id":"A","text":"$ 25^{th} $ and $ 22^{nd} $"},{"id":"B","text":"$ 26^{th} $ and $ 22^{nd} $"},{"id":"C","text":"$ 24^{th} $ and $ 22^{nd} $"},{"id":"D","text":"$ 22^{nd} $ and $ 20^{th} $"}]', 0, 'A', 'Mahesh''s rank from bottom = 32 - 8 + 1 = 25th

Sujain''s rank from bottom = 32 - 11 + 1 = 22nd', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.455Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3306, 'general-test-2023-06-09-shift-2', 'q41', 41, 41, 'If the sum of the diameters of two circles is 30 cm and the difference of their radii is 5 cm, then the ratio of area of the smaller circle to that of the bigger circle is:', '[{"id":"A","text":"4:5"},{"id":"B","text":"3:4"},{"id":"C","text":"2:3"},{"id":"D","text":"1:4"}]', 0, 'D', 'Let, $r_{1}, d_{1}$ and $A_{1}$ be the radius, diameter and Area of bigger circle respectively.

Similarly, $r_{2}, d_{2}$ and $A_{2}$ be the radius, diameter and Area of smaller circle respectively.

Given, $d_{1} + d_{2} = 30$

As we know, d = 2r then above eqn become, $r_{1} + r_{2} = 15 \ldots (1)$

Also given, $r_{1} - r_{2} = 5 \ldots (2)$

On solving eqn (1) and (2) we get, $r_{1} = 10, r_{2} = 5$

Ratio $\frac{A_{1}}{A_{2}} = \frac{\pi r_{1}}{\pi r_{2}}$

Ratio of area of the smaller circle to that of the bigger circle is $1 : 4$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.455Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3307, 'general-test-2023-06-09-shift-2', 'q42', 42, 42, 'Which of the following statement(s) is/are correct. Here a and r have their usual meaning:

(A) a, ar, ar², ..... is a G.P.

(B) n^{th} term of a G.P. is a_{n} = ar^{n-t}

(C) n^{th} term of a G.P. is a_{n} = ar^{n+1}

(D) Sum of first n terms of a G.P. is S_{n} = a \left( \frac{r^{n}-1}{r-1} \right), r \neq 1

(E) 4.16, 256, ..... is a G.P.

Chose the correct answer from the options given below:', '[{"id":"A","text":"(A) and (B) only"},{"id":"B","text":"(C) and (D) only"},{"id":"C","text":"(A), (B), (D) and (E) only"},{"id":"D","text":"(A), (B) and (D) only"}]', 0, 'D', '(A), (B) and (D) only are correct.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.456Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
