INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3310, 'general-test-2023-06-09-shift-2', 'q45', 45, 45, '_ is called the "Earth''s twin."', '[{"id":"A","text":"Saturn"},{"id":"B","text":"Mars"},{"id":"C","text":"Venus"},{"id":"D","text":"Jupiter"}]', 0, 'C', 'Venus is called the "Earth''s twin."', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.456Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3311, 'general-test-2023-06-09-shift-2', 'q46', 46, 46, '"Swachh Bharat Abhiyan" was launched on _.', '[{"id":"A","text":"2 October, 2012"},{"id":"B","text":"2 October, 2013"},{"id":"C","text":"2 October, 2014"},{"id":"D","text":"2 October, 2015"}]', 0, 'C', 'The Clean India Mission, or Swachh Bharat Abhiyan, is a nationwide initiative that was started by the Indian government on October 2, 2014.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.457Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3312, 'general-test-2023-06-09-shift-2', 'q47', 47, 47, 'The sum of the squares of three consecutive odd numbers is 2531. Find the smallest of these numbers.', '[{"id":"A","text":"27"},{"id":"B","text":"29"},{"id":"C","text":"31"},{"id":"D","text":"37"}]', 0, 'A', 'Let the number be, (x-2) and (x+2). Then form the equation as,

$ (x-2)^{2}+x^{2}+(x+2)^{2}=2531 $

On simplifying $ x^{2}-4x+4+x^{2}+x^{2}+4x+4=2531 $

$ 3x^{2}+8=2531 $

$ 3x^{2}=2531-8=2523 $

Or, $ x^{2}=\frac{2523}{3}=841 $ or x=29

So, the three numbers are 27, 29, 31

Thus, smaller is 27.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.457Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3313, 'general-test-2023-06-09-shift-2', 'q48', 48, 48, 'Find the area (in square units) of a triangle whose vertices are (1, -1), (-4, 6) and (-3, -5).', '[{"id":"A","text":"22"},{"id":"B","text":"24"},{"id":"C","text":"25"},{"id":"D","text":"27"}]', 0, 'B', 'Let A $(1,-1)$, B $(-4,6)$ and C $(-3,-5)$ be the vertices of a triangle ABC

Area = $\frac{1}{2}[x_1(y_2 - y_3) + x_2(y_3 - y_1) + x_3(y_1 - y_2)]$

Area = $\frac{1}{2}[1(6+5)+(-4)(-5+1)+(-3)(-1-6)]$

Area = 24 square units', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.457Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3314, 'general-test-2023-06-09-shift-2', 'q49', 49, 49, 'The price of an article is first increased by 20% and subsequently decreased by 25% due to reduction in sales. Find the net percentage change in price of the article.', '[{"id":"A","text":"10% decrease"},{"id":"B","text":"0.2% increase"},{"id":"C","text":"8% decrease"},{"id":"D","text":"5% decrease"}]', 0, 'A', 'Let the original cost = Rs. 100

Increased by 20%

New cost = 100 + 20 = Rs. 120

Decreased by 25% = $ \frac{120 \times 25}{100} = Rs. 30 $

New cost = 120 - 30 = Rs. 70

Overall change = 100 - 70 = Rs. 30

Required Percentage = $ \frac{30}{100} \times 100 = 30\% $

Thus, net percentage change = 10%', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.457Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3315, 'general-test-2023-06-09-shift-2', 'q50', 50, 50, 'Which amongst the following was an exclusive women force that fought for Independence of India from British rule?', '[{"id":"A","text":"Rani Jhansi Brigade"},{"id":"B","text":"Annie Besant Force"},{"id":"C","text":"Lalleshwari"},{"id":"D","text":"Anushitan Samiti"}]', 0, 'A', 'An exclusive women force that was vital to the Indian independence movement against British rule was the Rani Jhansi Regiment.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.457Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
