How is REMEMBER written in that code?', '[{"id":"A","text":"REEEMMBR"},{"id":"B","text":"RMMEEEBR"},{"id":"C","text":"REMMEBER"},{"id":"D","text":"RMEMEEBR"}]', 0, 'D', 'The second and third letters, fourth and fifth letters, sixth and seventh letters of the word mutually interchange positions to form the code.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.458Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3318, 'general-test-2023-06-09-shift-2', 'q53', 53, 53, 'Where is the headquarters of NATO?', '[{"id":"A","text":"England"},{"id":"B","text":"America"},{"id":"C","text":"Russia"},{"id":"D","text":"Belgium"}]', 0, 'D', 'The headquarters of NATO (North Atlantic Treaty Organisation) is in Brussels, Belgium.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.458Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3319, 'general-test-2023-06-09-shift-2', 'q54', 54, 54, 'In the following question, one of the terms in the number series is wrong. Find out the wrong term.

160, 118, 83, 75, 34, 20', '[{"id":"A","text":"75"},{"id":"B","text":"34"},{"id":"C","text":"118"},{"id":"D","text":"83"}]', 0, 'A', 'The pattern is -42, -35, -28, -21, -14. Therefore, wrong term in the series is 75. Instead of 75, it should be 55.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.458Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3320, 'general-test-2023-06-09-shift-2', 'q55', 55, 55, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(III), (B)-(IV), (C)-(III), (D)-(I)"},{"id":"B","text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)"},{"id":"C","text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)"},{"id":"D","text":"(A)-(IV), (B)-(II), (C)-(III), (D)-(I)"}]', 0, 'B', '(A)-(IV), (B)-(II), (C)-(I), (D)-(III)', NULL, 'null', '[]', '[{"id":"q55-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-09-shift-2/q55-table-1.jpg","page":5,"alt":"Table for question 55"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.458Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3321, 'general-test-2023-06-09-shift-2', 'q56', 56, 56, 'In a month of 31 days, third Friday falls on 17th. What will be the last day of the month?', '[{"id":"A","text":"5th Thursday"},{"id":"B","text":"5th Friday"},{"id":"C","text":"5th Saturday"},{"id":"D","text":"5th Sunday"}]', 0, 'B', 'Friday will fall on 3, 10, 17, 24, 31 So, it will be 5th Friday on 31st.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.458Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3322, 'general-test-2023-06-09-shift-2', 'q57', 57, 57, 'What is the pH range of milk?', '[{"id":"A","text":"(7.2 - 7.5)"},{"id":"B","text":"(9.2 - 9.5)"},{"id":"C","text":"(6.7 - 6.9)"},{"id":"D","text":"(3.4 - 3.9)"}]', 0, 'C', 'The pH range of milk is typically around 6.7 to 6.9, making it slightly acidic.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.459Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3323, 'general-test-2023-06-09-shift-2', 'q58', 58, 58, 'The volumes of two cubes are in the ratio 8:27. The ratio of their surface areas is:', '[{"id":"A","text":"2;3"},{"id":"B","text":"1:9"},{"id":"C","text":"4:9"},{"id":"D","text":"8:27"}]', 0, 'C', 'In volume of cube, we have ratio as:

$ \frac{a_{1}^{3}}{a_{2}^{3}} = \frac{8}{27} $

$ \frac{a_{1}}{a_{2}} = \frac{2}{3} $

So, in case of surface area we have ratio as,

$ \frac{a_{1}^{2}}{a_{2}^{2}} = \frac{2^{2}}{3^{2}} = \frac{4}{9} $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.459Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3324, 'general-test-2023-06-09-shift-2', 'q59', 59, 59, 'In a function girl were allowed to wear only red, blue or black dress. If 15 girls were wearing red, 10 girls were wearing blue and 20 girls were wearing black, then the probability that a girl selected at random was not wearing black dress is:', '[{"id":"A","text":"$ \\frac{4}{9} $"},{"id":"B","text":"$ \\frac{7}{9} $"},{"id":"C","text":"$ \\frac{5}{9} $"},{"id":"D","text":"$ \\frac{8}{9} $"}]', 0, 'C', 'Total number of girls = 45

The probability that a girl selected at random was

not wearing black dress = $ \frac{10+15}{45} = \frac{25}{45} = \frac{5}{9} $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.459Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3325, 'general-test-2023-06-09-shift-2', 'q60', 60, 60, 'Number of employees in different departments of an organisation and department wise percentage of female employees is given in the table.

What is the ratio of the number of females in production department to the number of females in the Marketing Department?', '[{"id":"A","text":"22:23"},{"id":"B","text":"35:33"},{"id":"C","text":"23:22"},{"id":"D","text":"33:35"}]', 0, 'C', 'Ratio of the number of females in production department to the number of females in the Marketing Department = 23:22', NULL, 'null', '[]', '[{"id":"q60-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-09-shift-2/q60-table-1.jpg","page":5,"alt":"Table for question 60"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.459Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3326, 'general-test-2023-06-10-shift-3', 'q01', 1, 1, 'Justice DY Chandrachud has become the new _ Chief Justice of India?', '[{"id":"A","text":"$ 55^{th} $"},{"id":"B","text":"$ 50^{th} $"},{"id":"C","text":"$ 45^{th} $"},{"id":"D","text":"$ 52^{th} $"}]', 0, 'B', 'Justice DY Chandrachud has become the 50th Chief Justice of India.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.460Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
