INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3328, 'general-test-2023-06-10-shift-3', 'q03', 3, 3, 'Who was the first Indian Nobel Laureate?', '[{"id":"A","text":"Dr. C.V Raman"},{"id":"B","text":"ST Radha Krishnan"},{"id":"C","text":"Rabindranath Tagore"},{"id":"D","text":"S.N. Bose"}]', 0, 'C', 'The first Indian to win a Nobel Prize was Rabindranath Tagore. In 1913, he was awarded the Nobel Prize in Literature for his collection of poems "Gitanjali."', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.460Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3329, 'general-test-2023-06-10-shift-3', 'q04', 4, 4, 'Which of the following statements are true for rectangles?

A. All interior angles are right angles.

B. Diagonals are perpendicular to each other.

C. Diagonals are equal.

