INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3330, 'general-test-2023-06-10-shift-3', 'q05', 5, 5, 'If A(2, 3), B(2, 4) C(4, 9) and D(x, 8) are the vertices of a parallelogram ABCD, then find the value of x.', '[{"id":"A","text":"8"},{"id":"B","text":"16"},{"id":"C","text":"5"},{"id":"D","text":"4"}]', 0, 'D', 'Midpoint of BD = Midpoint of AC

$ \frac{2+x}{2} = \frac{2+4}{2} $

x = 4', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.460Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3331, 'general-test-2023-06-10-shift-3', 'q06', 6, 6, 'What is the prescribed strength of judges in the constitutional bench of supreme Court?', '[{"id":"A","text":"2 Judges"},{"id":"B","text":"At least 5 Judges"},{"id":"C","text":"3 judges"},{"id":"D","text":"4 judges"}]', 0, 'B', 'A constitutional bench of the Supreme Court must have a minimum of five judges, as stated in Article 124(1) of the Indian Constitution.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.460Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3332, 'general-test-2023-06-10-shift-3', 'q07', 7, 7, 'Three dice are thrown. The probability of getting a sum of numbers which is a perfect cube, is:', '[{"id":"A","text":"$ \\frac{1}{6} $"},{"id":"B","text":"$ \\frac{1}{8} $"},{"id":"C","text":"$ \\frac{5}{36} $"},{"id":"D","text":"$ \\frac{7}{12} $"}]', 0, 'D', 'The probability of getting a sum of numbers which is perfect cube is $ \frac{7}{12} $.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3333, 'general-test-2023-06-10-shift-3', 'q08', 8, 8, 'Consider the following statements:

A. Antigen A and antibody ''a'', Antigen ''B'' and antibody ''b'' cannot live together.

B. Blood group ''O'' is called universal Donor.

C. Blood group ''AB'' is called Universal Receptor.

D. At the time of Blood transfusion RH-factor is also tested.

E. Main function of blood platelets is to protect the body from the disease.', '[{"id":"A","text":"B, C, D and E only"},{"id":"B","text":"A, B, C and D only"},{"id":"C","text":"A and B only"},{"id":"D","text":"C, D and E only"}]', 0, 'B', 'A, B, C and D are the correct statements.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3334, 'general-test-2023-06-10-shift-3', 'q09', 9, 9, 'How many times in a day hour hand and minute hand of a clock will coincide?', '[{"id":"A","text":"24 times"},{"id":"B","text":"22 times"},{"id":"C","text":"44 times"},{"id":"D","text":"48 times"}]', 0, 'B', 'The minute and hour hand coincide every 65 minutes and not 60 minutes. So, we can say that the two hands coincide exactly 11 times in a 12-hour span. We have to find the number of times in a day so we have 24 hours in a day. Therefore, the number of times the two hands coincide $ =2 \times 11 = 22 $ times.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3335, 'general-test-2023-06-10-shift-3', 'q10', 10, 10, 'Study the following information and answer the question given below:

A family has 5 members P, Q, R, S and T, each have a different weight.

i. P weighs twice as much as Q

ii. Q weighs four and a half times as much as R

iii. R weighs half as much as S

iv. S weighs half as much as T

v. T weighs less than P but more than R

Which of the following member of a family is the

Which of the following member of a family is the lightest in weight?', '[{"id":"A","text":"P"},{"id":"B","text":"Q"},{"id":"C","text":"R"},{"id":"D","text":"S"}]', 0, 'C', 'Let weight of R = x

So, weight of Q will be = 4.5x and weight of P will be = 9x.

Now S weighs half as much as T, so weight of S will be = 2x.

Therefore P > Q > S > R. It is given that T weighs more than R. Therefore, R is lightest member in the family,', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3336, 'general-test-2023-06-10-shift-3', 'q11', 11, 11, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)"},{"id":"B","text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)"},{"id":"C","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"},{"id":"D","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"}]', 0, 'D', '(A)-(IV), (B)-(III), (C)-(II), (D)-(I)', NULL, 'null', '[]', '[{"id":"q11-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q11-table-1.jpg","page":1,"alt":"Table for question 11"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3337, 'general-test-2023-06-10-shift-3', 'q12', 12, 12, 'Find the alternative which contains figure (A) as its part', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'B', NULL, NULL, 'null', '[]', '[{"id":"q12-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q12-figure-1.jpg","page":2,"alt":"Figure for question 12"},{"id":"q12-options","kind":"options","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q12-options.jpg","page":2,"alt":"Printed answer choices for question 12"}]', '[2]', 'keyed', '["image-options"]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3338, 'general-test-2023-06-10-shift-3', 'q13', 13, 13, 'The value of a car depreciates every year by 10%. What will be its value after 3 years if its present value is ₹6,25,000?', '[{"id":"A","text":"₹4,50,000"},{"id":"B","text":"₹52,250"},{"id":"C","text":"₹455.625"},{"id":"D","text":"₹4,62,500"}]', 0, 'C', 'Original price is ₹25,000

Rate of increment = 10%

Price after 1 year = 625000 × (1 - $ \frac{10}{100} $) = 625000 ×

$ \frac{90}{100} $ = 5,62,500

Price after 2 years = (1 - $ \frac{10}{100} $) = 562500 × $ \frac{90}{100} $

=506250

Price after 3 years = 506250 × $ \frac{90}{100} $ = ₹455.625', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3339, 'general-test-2023-06-10-shift-3', 'q14', 14, 14, 'The average of a positive number, its square and 3 is

5. Find the number.', '[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"1"},{"id":"D","text":"4"}]', 0, 'B', 'By putting option,

$ \frac{3+9+3}{3}=5 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3340, 'general-test-2023-06-10-shift-3', 'q15', 15, 15, 'If Anil''s salary is 20% less than that of Rama, then by what percent is Rama''s salary more than that of Anil?', '[{"id":"A","text":"20%"},{"id":"B","text":"25%"},{"id":"C","text":"15%"},{"id":"D","text":"30%"}]', 0, 'B', 'Let Rama''s salary be Rs. 100

Anil''s salary is 20% less than Rama''s salary

Salary of Anil = 80% of 100 = Rs. 80

Rama''s salary is Rs. 20 more than that of Anil.

Now, the required percentage = $ \frac{20}{8} $(100)% = 25%

Rama''s salary is 25% more than Anil''s salary.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3341, 'general-test-2023-06-10-shift-3', 'q16', 16, 16, 'Akshay is the son of Kapil. Simar, Kapil''s sister, has a son Montu and daughter Sara. Pawan is the maternal uncle of Montu. How is Akshay related to Montu?', '[{"id":"A","text":"Sister-in-law"},{"id":"B","text":"Mother"},{"id":"C","text":"Sister"},{"id":"D","text":"Cousin"}]', 0, 'D', 'Kapil is brother or sister of Montu''s mother. So, Akshay, who is son of Kapil would be cousin of Kapil.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.461Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3342, 'general-test-2023-06-10-shift-3', 'q17', 17, 17, 'Lalit Kala Akademi, the National Academy of Art, was set up in _', '[{"id":"A","text":"1968"},{"id":"B","text":"1964"},{"id":"C","text":"1954"},{"id":"D","text":"1951"}]', 0, 'C', 'Lalit Kala Akademi (National Academy of Art), New Delhi was inaugurated on 5th August 1954 by the then Minister for Education, Maulana Abul Kalam Azad.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.463Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3343, 'general-test-2023-06-10-shift-3', 'q18', 18, 18, 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R

Assertion A: Forest cutting is desirable from the point of view of soil erosion.

Reason R: Cutting of forests reduces the interception of rain water.

In the light of the above statements, choose the correct answer from the options given below.', '[{"id":"A","text":"Both A and R are true and r is the correct explanation of A"},{"id":"B","text":"Both A and R are true but R is NOT the correct explanation of A"},{"id":"C","text":"A is true but R is false"},{"id":"D","text":"A is false but R is true"}]', 0, 'D', 'Forest cutting is not desirable from the point of view of soil erosion. Therefore, A is false but R is true.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.463Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3344, 'general-test-2023-06-10-shift-3', 'q19', 19, 19, 'Which term of the AP: 3, 7, 11, ....., 147 is its middle term?', '[{"id":"A","text":"$ 18^{th} $"},{"id":"B","text":"$ 19^{th} $"},{"id":"C","text":"$ 20^{th} $"},{"id":"D","text":"$ 21^{st} $"}]', 0, 'B', 'Here, a = 3, x_{n}=147, common difference d = 4

$ x_{n}=a+(n-1)d $

$ 147=3+(n-1)4 $

n-1=36, n=37

Thus the given series consist of 37 terms.

Therefore its middle term will be $ \frac{37+1}{2}=19th\ term $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.464Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3345, 'general-test-2023-06-10-shift-3', 'q20', 20, 20, 'Which of the following Mughal rulers set up a new religion called Din-i-Ilahi?', '[{"id":"A","text":"Aurangzeb"},{"id":"B","text":"Humayun"},{"id":"C","text":"Akbar"},{"id":"D","text":"Shah Jahan"}]', 0, 'C', 'Akbar, the third ruler of the Mughal Empire, founded the Din-i-Ilahi in the late 16th century.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.464Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3346, 'general-test-2023-06-10-shift-3', 'q21', 21, 21, 'If the average of 15, 25, 19, 20, 23, 18 and $ (x - 3) $ is 20. then Find the average of $ x $, $ (x + 6) $, $ (2x - 1) $ and 23.', '[{"id":"A","text":"20"},{"id":"B","text":"27"},{"id":"C","text":"$ 28\\frac{1}{2} $"},{"id":"D","text":"30"}]', 0, 'D', 'We know, $ Mean = \frac{Sum of all observation}{Total number of observation} $

$ 20 = \frac{15 + 25 + 19 + 20 + 23 + 18 + (x - 3)}{7} $

$ 140 = 117 + x $

x = 23

Then $ x + 6 = 29, 2x - 1 = 45 $

Average = $ \frac{23 + 29 + 45 + 23}{4} = 30 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.465Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3347, 'general-test-2023-06-10-shift-3', 'q22', 22, 22, 'The ratio between length and breadth of a rectangle is 3:2. If area of the rectangle is $ 96 \, cm^2 $, then length of the rectangle is', '[{"id":"A","text":"6 cm"},{"id":"B","text":"12 cm"},{"id":"C","text":"8 cm"},{"id":"D","text":"16 cm"}]', 0, 'B', 'Let the length and breadth of the rectangle be 3x and 2x respectively.

Now, $ 3x \times 2x = 96 $

$ x^{2}=\frac{96}{6} $

x = 4 cm

Length = 3x = 12 cm', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.465Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3348, 'general-test-2023-06-10-shift-3', 'q23', 23, 23, '''Shramev Jayate'' scheme was announced on _ by GOI.', '[{"id":"A","text":"10 October, 2013"},{"id":"B","text":"16 October, 2014"},{"id":"C","text":"12 October, 2012"},{"id":"D","text":"13 October, 2015"}]', 0, 'B', '''Shramev Jayate'' scheme was announced on October 16, 2014, by the Government of India.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.466Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3349, 'general-test-2023-06-10-shift-3', 'q24', 24, 24, 'A 180 m long train crosses a man standing on the platform in 6 seconds. What is the speed of the train?', '[{"id":"A","text":"90 km/h"},{"id":"B","text":"108 km/h"},{"id":"C","text":"120 km/h"},{"id":"D","text":"88 km/h"}]', 0, 'B', 'Speed = 180/6 = 30 m/s

Convert m/sec into km/hr, $ 30 \times \frac{18}{5} = 108 km/hr $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.466Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3350, 'general-test-2023-06-10-shift-3', 'q25', 25, 25, 'Which of the given conclusions logically follows the given two statements.

Statements:

All apples are Banana

No Banana is Grape

Some Grape are Orange
Conclusions

I. Some Banana are Orange

II. No Apple is Orange

III. All Banana are Orange is a possibility', '[{"id":"A","text":"Only I follow"},{"id":"B","text":"Only II conclusion follow"},{"id":"C","text":"Only III follow"},{"id":"D","text":"All conclusion follows"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.466Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3351, 'general-test-2023-06-10-shift-3', 'q26', 26, 26, 'Match List-I with List-II:', '[{"id":"A","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"},{"id":"B","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"},{"id":"C","text":"(A)-(I), (B)-(III), (C)-(II), (D)-(IV)"},{"id":"D","text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)"}]', 0, 'B', '(A)-(III), (B)-(IV), (C)-(I), (D)-(II)', NULL, 'null', '[]', '[{"id":"q26-table-1","kind":"table","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q26-table-1.jpg","page":3,"alt":"Table for question 26"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.467Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3352, 'general-test-2023-06-10-shift-3', 'q27', 27, 27, 'Choose the assumption which is implicit in context of the given statement.

Statement-"Z-perfume is ideal as a gift for someone you love" - An Advertisement

Assumptions

I. People generally give gifts to loved one.

II. Such advertisements generally influence people.

III. Perfume can be considered as a gift item.', '[{"id":"A","text":"I and II are implicit"},{"id":"B","text":"I and III are implicit"},{"id":"C","text":"All are implicit"},{"id":"D","text":"II and III are implicit"}]', 0, 'C', 'Clearly, all the three directly follow from the given statement.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.467Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3353, 'general-test-2023-06-10-shift-3', 'q28', 28, 28, 'If two squares X and Y have each side of 10 m and 20 m respectively, then the side of the square Z whose area is equal to the sum of the areas of square X and square Y is:', '[{"id":"A","text":"$ 10\\sqrt{3} $ m"},{"id":"B","text":"$ 10\\sqrt{2} $ m"},{"id":"C","text":"$ 10\\sqrt{7} $ m"},{"id":"D","text":"$ 10\\sqrt{5} $ m"}]', 0, 'D', 'Area of squares $ X = 10^{2} = 100m^{2} $

Area of the square Y = 20^{2} = 400m^{2}

Area of square Z = 100 + 400 = 500 m^{2}

Side of square Z = $ \sqrt{500} $ = $ 10\sqrt{5} $ m', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.468Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3354, 'general-test-2023-06-10-shift-3', 'q29', 29, 29, 'In how many years a sum placed on compound interest becomes 8 times of itself, if it becomes twice in 6 years?', '[{"id":"A","text":"20"},{"id":"B","text":"18"},{"id":"C","text":"15"},{"id":"D","text":"12"}]', 0, 'B', 'A certain sum at C.I becomes n times in t years then, n times -> t years

$n^{m}$ times $\rightarrow (m \times t)$ years

A sum of money placed at C.I doubles itself in 6 years

2 times $\rightarrow$ 6 years

8 times $\rightarrow$ $2^{3}$ times = 3 × 6 years = 18 years', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.468Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3355, 'general-test-2023-06-10-shift-3', 'q30', 30, 30, 'If some words are coded from artificial language: like "Botlo Pono" means Drink water

''Maroh pono" means chew water

''Pono ajebo" means save water

Which code could mean "Save Drink"?', '[{"id":"A","text":"Botlo ajebo"},{"id":"B","text":"Botlo pono"},{"id":"C","text":"Pono ajebo"},{"id":"D","text":"Maroh Botlo"}]', 0, 'A', 'Botlo → Drink

Pono → Water

Maroh → Chew

Ajebo - Save

Therefore, code for ''Save Drink'' would be ''Botlo Ajebo''.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.468Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
