B', '[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"C"},{"id":"D","text":"D C D"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q35-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-1.jpg","page":4,"alt":"Figure for question 35"},{"id":"q35-figure-2","kind":"figure","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-2.jpg","page":4,"alt":"Figure for question 35"},{"id":"q35-figure-3","kind":"figure","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-3.jpg","page":4,"alt":"Figure for question 35"},{"id":"q35-figure-4","kind":"figure","path":"/local-papers/assets/general-test-2023-06-10-shift-3/q35-figure-4.jpg","page":4,"alt":"Figure for question 35"}]', '[3,4]', 'keyed', '[]', '2026-11-05T20:58:59.469Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3361, 'general-test-2023-06-10-shift-3', 'q36', 36, 36, 'At what time between 4 0'' clock and 5 0'' clock hour hand and minute hand will coincide?', '[{"id":"A","text":"4:18 $ \\frac{9}{11} $"},{"id":"B","text":"4:22 $ \\frac{9}{11} $"},{"id":"C","text":"4:21 $ \\frac{9}{11} $"},{"id":"D","text":"4:23 $ \\frac{9}{11} $"}]', 0, 'C', 'The hour hand of a clock covers 360^{\circ} in 12 hrs or 30^{\circ} in 1 hour or 0.5^{\circ} in 1 min.

At 4:00, the minute hand has covered 0^{\circ} and the hour hand has covered 120^{\circ}.

Let the time after which the hands coincide be x min.

So, the hour hand covers 120 + \frac{x}{2} up to that time and the minute hand covers 6x^{\circ} up to that time.

When they coincide, the angles should be the same. So, we can write 120 + \frac{x}{2} = 6x

$ \frac{12x-x}{2}=120 $

$ x=\frac{240}{11}=21\frac{9}{11} $

Therefore, they will coincide at 4:21.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.469Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3362, 'general-test-2023-06-10-shift-3', 'q37', 37, 37, 'A solid hemisphere of radius 24 cm is melted and identical cones each of base radius 8 cm and height 6 cm are formed. How many such cones are formed?', '[{"id":"A","text":"144"},{"id":"B","text":"96"},{"id":"C","text":"72"},{"id":"D","text":"24"}]', 0, 'C', 'ATQ, Volume of hemisphere = Volume of cone

$ \frac{2}{3} \times 24^3 = \frac{1}{3} \times 8^2 \times 6 $

Number of cones = $ \frac{\frac{2}{3}\pi r^3}{\frac{2}{3}\pi r^3} = \frac{\frac{2}{3} \times 24^3}{\frac{1}{3} \times 8^2 \times 6} = 72 $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.469Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3363, 'general-test-2023-06-10-shift-3', 'q38', 38, 38, 'Sourav completes a journey in 5½ hours. If he covers half of the distance at 5 km/h and the remaining distance at 6 km/h, then find the total distance covered by him.', '[{"id":"A","text":"30 km"},{"id":"B","text":"35 km"},{"id":"C","text":"33 km"},{"id":"D","text":"39 km"}]', 0, 'A', 'Let the distance travelled by man is 2d

$ \frac{d}{5}+\frac{d}{6}=5\frac{1}{2} $

$ \frac{11d}{30}=\frac{11}{2} $

d = 15

Then distance travelled by man = 2d = 30 km', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.470Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3364, 'general-test-2023-06-10-shift-3', 'q39', 39, 39, 'Who is the winner of UNESCO Peace Prize 2022?', '[{"id":"A","text":"Volodymyr Zelenskyy"},{"id":"B","text":"Tadashi Hattori"},{"id":"C","text":"Swati Piramal"},{"id":"D","text":"Angela Merkel"}]', 0, 'D', 'Former German chancellor Angela Merkel has been awarded the 2022 UNESCO Peace Prize for "her efforts to welcome refugees".', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.470Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3365, 'general-test-2023-06-10-shift-3', 'q40', 40, 40, 'If \cos6\theta=\sin3\theta, then the value of \theta is:', '[{"id":"A","text":"$ 9^{\\circ} $"},{"id":"B","text":"$ 12^{\\circ} $"},{"id":"C","text":"$ 10^{\\circ} $"},{"id":"D","text":"$ 6^{\\circ} $"}]', 0, 'C', 'putting $\theta=10^{\circ}$

$cos60^{\circ}=sin30^{\circ}$

$\frac{1}{2}=\frac{1}{2}$

Thus $\theta=10^{\circ}$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.470Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3366, 'general-test-2023-06-10-shift-3', 'q41', 41, 41, 'Simon Commission came to India in _.', '[{"id":"A","text":"1925"},{"id":"B","text":"1928"},{"id":"C","text":"1923"},{"id":"D","text":"1930"}]', 0, 'B', 'Simon Commission came formed in 1927 but came to India in 1927. But in official answer key 1927 is the correct answer.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.470Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3367, 'general-test-2023-06-10-shift-3', 'q42', 42, 42, 'In a school, ratio of number of boys to that of girls was 6:5. In the next year, number of boys increased by 20% and number of girls increased by 10% resulting in an increase of 119 students in the school. How many students were there in the school initially?', '[{"id":"A","text":"680"},{"id":"B","text":"750"},{"id":"C","text":"770"},{"id":"D","text":"780"}]', 0, 'C', 'Let the initial number of students be x

Then, Number of boys = $ \frac{6}{6+5}x = \frac{6x}{11} $

Similarly, Number of girls = $ \frac{5x}{11} $

20% increment in number of boys = $ \frac{6x}{11} + 20\% of \frac{6x}{11} $

10% increment in number of girls = $ \frac{5x}{11} + 10\% of \frac{5x}{11} $

ATQ. $ \frac{6x}{11} + 20\% of \frac{6x}{11} + \frac{5x}{11} + 10\% of \frac{5x}{11} = x + 119 $

$ \frac{6x}{11} + \frac{6x}{55} + \frac{5x}{11} + \frac{x}{22} = x + 119 $

127x - 110x = 119 $ \times $ 110

x = 770

Thus, number of students initially in the school is 770.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.471Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3368, 'general-test-2023-06-10-shift-3', 'q43', 43, 43, 'Find the missing term which can be filled at "?" place

1,3,7,22,67,?1077', '[{"id":"A","text":"269"},{"id":"B","text":"263"},{"id":"C","text":"362"},{"id":"D","text":"267"}]', 0, 'A', 'The sequence is

$ 1 \times 2 + 1 = 3 $

$ 3 \times 2 + 1 = 7 $

$ 7 \times 3 + 1 = 22 $

$ 22 \times 3 + 1 = 67 $

$ 67 \times 4 + 1 = 269 $

$ 269 \times 4 + 1 = 1077 $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.471Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3369, 'general-test-2023-06-10-shift-3', 'q44', 44, 44, 'In a certain code, ''lee ra de'' means ''Upanishads are it'', ''mo nil'' means ''you read'', ''nil pom ra'' means ''you like it'' and ''tok lee fo'' means ''They are immortal''. How will you write ''Upanishads you like'' in that code?', '[{"id":"A","text":"de nil pom"},{"id":"B","text":"de nil ra"},{"id":"C","text":"mo nil pom"},{"id":"D","text":"nil tok lee"}]', 0, 'A', 'lee → are

de → Upanishads

nil → you

ra → it

pom → like

So ''Upanishads you like'' will be written as ''de nil pom'' in that code.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.471Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3370, 'general-test-2023-06-10-shift-3', 'q46', 46, 45, 'White revolution refers to _.', '[{"id":"A","text":"Cotton textile Industry"},{"id":"B","text":"Marble Industry"},{"id":"C","text":"Cement Industry"},{"id":"D","text":"Dairying"}]', 0, 'D', 'The White Revolution in India, also known as Operation Flood, was a successful program implemented to increase milk production and make the country self-sufficient in milk and dairy products.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.471Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3371, 'general-test-2023-06-10-shift-3', 'q47', 47, 46, 'If today is Saturday, then day after 53 days will be:', '[{"id":"A","text":"Friday"},{"id":"B","text":"Monday"},{"id":"C","text":"Tuesday"},{"id":"D","text":"Wednesday"}]', 0, 'D', 'A week has 7 days "Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday".

53 / 7 = 7 (Remainder = 4)

So we can say that after multiples of 7 days, the day will repeat itself as Saturday. Hence after 49 days Saturday will occur again.

So, we calculate after the remainder (4), the answer is Wednesday.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.472Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3372, 'general-test-2023-06-10-shift-3', 'q48', 48, 47, 'A shopkeeper sold $ \frac{2}{3} $ of his stock of rice at a profit of 5% and the remaining stock at a loss of 2%. If his total profit was ₹1000, then the cost price of the whole stock of rice is:', '[{"id":"A","text":"₹24,800"},{"id":"B","text":"₹32,600"},{"id":"C","text":"₹37,500"},{"id":"D","text":"₹48,000"}]', 0, 'C', 'Let the cost price of the rice is Rs. X

$ \frac{2}{3}x \times \frac{5}{100} - \frac{1}{3}x \times \frac{2}{100} = 1000 $

$ 10x - 2x = 300000 $

x=37500

Thus, the cost price of the whole stock of rice is ₹37,500.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.472Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3373, 'general-test-2023-06-10-shift-3', 'q49', 49, 48, 'Which is the largest salt water inland lake of India, that provides sanctuary to lakhs of migratory birds during winter?', '[{"id":"A","text":"Pachpadra Lake"},{"id":"B","text":"Chilika Lake"},{"id":"C","text":"Pangong Lake"},{"id":"D","text":"Lomar Lake"}]', 0, 'B', 'The largest saltwater inland lake in India that provides sanctuary to a large number of migratory birds during winter is Chilika Lake.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.472Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
