INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3377, 'general-test-2023-06-10-shift-3', 'q53', 53, 52, 'The book titled "Exam Warriors" is written by:', '[{"id":"A","text":"L.K. Advani"},{"id":"B","text":"P. Chindambaram"},{"id":"C","text":"Jairam Ramesh"},{"id":"D","text":"Narendra Modi"}]', 0, 'D', 'The book titled "Exam Warriors" is written by Narendra Modi.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.473Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3378, 'general-test-2023-06-10-shift-3', 'q54', 54, 53, 'A and B can do a work in 10 days and 15 days respectively. They worked together for 5 days, then B left the work and A alone did the remaining work. The whole work got completed in:', '[{"id":"A","text":"$ 6\\frac{2}{3} $ days"},{"id":"B","text":"7 days"},{"id":"C","text":"$ 7\\frac{1}{2} $ days"},{"id":"D","text":"$ 6\\frac{1}{2} $ days"}]', 0, 'A', 'A can do a work in 10 days, thus A''s one day work = 1/10

B can do a work in 15 days, thus B''s one day work = 1/15

A and B''s one day work = $ \frac{1}{10} + \frac{1}{15} = \frac{1}{6} $

5 days'' work of A and B will be 5/6

Remaining work after B left = 1 - $ \frac{5}{6} $ = $ \frac{1}{6} $

A will finish remaining work in = $ \frac{1}{6} \times 10 = 1\frac{2}{3} $

Total number of days to complete the work is = $ 1\frac{2}{3} + 5 = 6\frac{2}{3} $ days', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.473Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3379, 'general-test-2023-06-10-shift-3', 'q55', 55, 54, 'Six persons A, B, C, D, E, and F are sitting in two rows with three persons in each row. People of both the rows are facing each other. E is not at the end of any row. D is second to the left of F. C is the neighbour of E and diagonally opposite to D. B is the neighbour of F. Who is in front of F?', '[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"C"},{"id":"D","text":"D"}]', 0, 'C', 'Clearly C is in front of F.

$ \begin{array}{c}

\text{Facing} \\

\text{South}

\end{array} $ $ \downarrow $ $ \begin{array}{c}

\text{F} \\

\text{C}

\end{array} $ $ \underline{B} $ $ \underline{D} $ $ \underline{A} $

$ \uparrow $ $ \begin{array}{c}

\text{Facing} \\

\text{North}

\end{array} $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.473Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3380, 'general-test-2023-06-10-shift-3', 'q56', 56, 55, 'Which is the only metal that is liquid at room temperature?', '[{"id":"A","text":"Bromine"},{"id":"B","text":"Mercury"},{"id":"C","text":"Tungsten"},{"id":"D","text":"Gallium"}]', 0, 'B', 'The only metal that is liquid at room temperature is Mercury (Hg).', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.473Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
