INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3493, 'physics-2023-05-25-shift-3', 'q16', 16, 16, 'Which phenomena proves the particle nature of photon?', '[{"id":"A","text":"Interference"},{"id":"B","text":"diffraction"},{"id":"C","text":"polarisation"},{"id":"D","text":"Photo electric effect"}]', 0, 'D', '(a) Interference is a phenomenon in which two waves of same frequency superpose to give resultant intensity different from sum of their separate intensity. So, it cannot exhibit particle''s nature of light.

(b) Diffraction is a phenomenon in which light bends at sharp ends of an obstacle or a hole. So, it also cannot exhibit particle''s nature of light.

(c) Polarisation of light is a property owing to which a light ray after emerging through a crystal (a special kind like tourmaline) have vibrations in a plane perpendicular to its direction of propagation. So, it also can not explain particle''s nature of light.

(d) Photoelectric effect states that light travels in the form of bundles or packets of energy, called photons. This effect is explained on the basis of quantum nature of light. So, it clearly explains the particles'' nature of light', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.494Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3494, 'physics-2023-05-25-shift-3', 'q17', 17, 17, 'Peak voltage of a modulating signal is 2 V. The carrier wave is represented by $ C(t) = 4\sin(8\pi t) $ V. The modulation index of modulated signal is:', '[{"id":"A","text":"0.5"},{"id":"B","text":"1.0"},{"id":"C","text":"4.0"},{"id":"D","text":"8.0"}]', 0, 'A', '$$ y(t)=[A_{c}+m(t)]c(t) $$

where,

$A_{C}$ is the amplitude of carrier wave.

The modulated waveform $y(t)$ as shown in fig.

Modulation index, $\mu=\frac{M}{A}=0.5$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.494Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3495, 'physics-2023-05-25-shift-3', 'q18', 18, 18, 'The waves used by artificial satellite for communication purposes are', '[{"id":"A","text":"Ground waves"},{"id":"B","text":"Microwaves"},{"id":"C","text":"F. M. radio waves"},{"id":"D","text":"A. M. radio waves"}]', 0, 'B', 'Microwaves are mostly used for satellite communication, as microwaves can pass straight through the atmosphere and connect antennas on earth to satellite in earth''s orbit.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.494Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3496, 'physics-2023-05-25-shift-3', 'q19', 19, 19, 'The time taken by light to travel normally through a glass plate of thickness 1 mm would be:

(Take refractive index of glass = 1.5)', '[{"id":"A","text":"$ 0.1 \\times 10^{-13} s $"},{"id":"B","text":"$ 12 \\times 10^{-5} s $"},{"id":"C","text":"$ 5 \\times 10^{-12} s $"},{"id":"D","text":"$ 1.5 \\times 10^{-5} s $"}]', 0, 'C', 'We know that

$$ v=c/\mu $$

$$ v=\frac{3\times10^{8}}{1.5}=2\times10^{8}m/s $$

$$ Time~=T=\frac{d}{v}=\frac{10^{-3}}{2\times10^{8}} $$

$$ T=0.5\times10^{-11}\mathrm{s e c} $$

$$ T=5\times10^{-12}\mathrm{s e c} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.494Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3497, 'physics-2023-05-25-shift-3', 'q20', 20, 20, 'A slab of material of dielectric constant k has the same area as the plates of a parallel plate capacitor, but has a thickness $\frac{3d}{4}$. Where d is the distance between plates of capacitor. The ratio of the capacitance with dielectric inside it to its capacitance without the dielectric is:', '[{"id":"A","text":"$\\frac{3k}{(k+4)}$"},{"id":"B","text":"$\\frac{4k}{(k+3)}$"},{"id":"C","text":"$\\frac{5k}{(k+2)}$"},{"id":"D","text":"$\\frac{k}{(k+3)}$"}]', 0, 'B', '$$ C=\frac{A\epsilon_{0}}{d} $$

Sol.

$$ C^{\prime}=\frac{A\epsilon_{0}}{d-t+\frac{t}{k}} $$

$$ \mathrm{P u t t}=\frac{3\mathrm{~d}}{4}; $$

$$ C^{\prime}=\frac{\dot{4}\mathrm{k}}{3+\mathrm{k}}\cdot\frac{\mathrm{A}\epsilon_{\mathrm{o}}}{\mathrm{d}} $$

$$ C^{\prime}=\frac{4k}{3+k}\cdot C $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.495Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3498, 'physics-2023-05-25-shift-3', 'q21', 21, 21, 'Monochromatic light of frequency $ 6 \times 10^{14} $ Hz is produced by a laser source. The energy of photon of light is:', '[{"id":"A","text":"$ 3.98 \\times 10^{-19} $ J"},{"id":"B","text":"$ 39.8 \\times 10^{-19} $ J"},{"id":"C","text":"$ 1.12 \\times 10^{-20} $ J"},{"id":"D","text":"$ 2.24 \\times 10^{-20} $ J"}]', 0, 'A', '$$ \begin{array}{l}E=h v\\ =6.63\times10^{-34}\times6.0\times10^{14}\\ =3.98\times10^{-19}J\end{array} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.495Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3499, 'physics-2023-05-25-shift-3', 'q22', 22, 22, 'A semiconductor device is connected in series circuit with a battery and resistance. A current is found to pass through the circuit. If the polarity of the battery is reversed, the current chops at almost zero. The device may be', '[{"id":"A","text":"A p-type semiconductor"},{"id":"B","text":"An Intrinsic semiconductor"},{"id":"C","text":"An n-type semiconductor"},{"id":"D","text":"a p-n Junction"}]', 0, 'D', 'A p-n junction is a device in which current flows through the junction when it is forward biased whereas when reverse biased, it conducts a very small current (almost zero) until the output voltage equals the breakdown voltage. Moreover, current through the intrinsic as well as extrinsic semiconductor does not depend on the polarity of the battery.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.495Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3500, 'physics-2023-05-25-shift-3', 'q23', 23, 23, 'Two identical thin metal plates are given charges q_{1} and q_{2} (q_{2} < q_{1}) respectively. If they are now brought close together to form a parallel plate capacitor with a capacitance ''C'' then the potential difference between the plates is:', '[{"id":"A","text":"$ \\frac{q_{1}+q_{2}}{2C} $"},{"id":"B","text":"$ \\frac{q_{1}}{2Cq_{2}} $"},{"id":"C","text":"$ \\frac{q_{1}-q_{2}}{2C} $"},{"id":"D","text":"$ \\frac{q_{2}}{C(q_{1}+q_{2})} $"}]', 0, 'C', 'Electric field between plates given by,

$$ E=\frac{q_{1}-q_{2}}{2A\varepsilon_{0}} $$

(Here, $ q_{1} > q_{2} $)

$$ \mathrm{V}=\mathrm{E d}=\frac{\mathrm{q}_{1}-\mathrm{q}_{2}}{2\mathrm{~A}\varepsilon_{0}}\mathrm{~d}=\frac{\mathrm{q}_{1}-\mathrm{q}_{2}}{2\mathrm{C}}\left(\because\mathrm{C}=\frac{\varepsilon_{0}\mathrm{~A}}{\mathrm{~d}}\right) $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.495Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3501, 'physics-2023-05-25-shift-3', 'q24', 24, 24, 'the shape of a wavefront when light emerging out of a convex lens when a parallel beam of light incident over it is,', '[{"id":"A","text":"Parabolic"},{"id":"B","text":"Plane"},{"id":"C","text":"Cylindrical"},{"id":"D","text":"Spherical"}]', 0, 'B', 'Corresponding to a beam of parallel rays of light the wavefronts, are planes parallel to one another.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.496Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3502, 'physics-2023-05-25-shift-3', 'q25', 25, 25, 'Arrange the following m Increasing number of quantum number when coming from excited energy state

A. Lyman Series

B. Balmer Series

C. Paschen Series

D Brackett Series

E. Pfund Series', '[{"id":"A","text":"E, D, C, B, A"},{"id":"B","text":"A, B, C, E, D"},{"id":"C","text":"A, B, C, D, E"},{"id":"D","text":"B, A, C, D, E"}]', 0, 'C', '5 $ 6 \rightarrow \infty $ Pfund series 2280 nm

6 $7 \rightarrow \infty$ Humphreys series 3283 nm', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.497Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3503, 'physics-2023-05-25-shift-3', 'q26', 26, 26, 'A short solenoid of radius a and $ n_1 $ number of turns per unit length and length $ L $ is kept coaxially inside a very long solenoid of radius $ b $ and $ n_2 $ number of turns per unit length. What is the mutual inductance of the system.', '[{"id":"A","text":"$ \\mu_0 \\pi b^2 n_1 n_2 L $"},{"id":"B","text":"$ \\mu_0 \\pi a^2 n_1 n_2 L^2 $"},{"id":"C","text":"$ \\mu_0 \\pi a^2 n_1 n_2 L $"},{"id":"D","text":"$ \\mu_0 \\pi b^2 n_1 n_2 L^2 $"}]', 0, 'C', 'Let L be the length of each solenoid $S_1$ and $S_2$ having radius a and b respectively.

$n_1$ and $n_2$ be the number of turns per unit length of $S_1$ and $S_2$.

And I be the current through solenoid $S_2$

Magnetic field in $S_2 = B_2 = \mu_0 n_2 I$

Magnetic flux linked with each turn of $S_1 = B_2 \times$ area of each turn = $B_1 \pi a^2$

Total magnetic flux linked with $S_1 = B_2 \pi a^2 n_1 L$

$\therefore \phi_1 = (\mu_0 n_2 I) \pi a^2 n_2 L = \mu_0 n_1 n_2 \pi a^2 I L$

But magnetic flux linked with $S_1$ is due to I

$\therefore \phi_1 \propto I$ or $\phi_1 = M I$

Where M is the mutual inductance of $S_2$ and $S_1$

$\therefore M I = \mu_0 n_1 n_2 \pi a^2 I L$

$\therefore M = \mu_0 n_1 n_2 \pi a^2 L$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.497Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3504, 'physics-2023-05-25-shift-3', 'q27', 27, 27, 'Which of the following statements are correct?

A. The saturation current is constant with collector plate potential for different frequencies of incident radiation.

B. The saturation current is different with collector plate potential for different frequencies of incident radiation.

C. The saturation current is different with collector plate potential for different intensity of incident radiation.

D. The saturation current is constant with collector plate potential for different intensity of incident radiation.

E. Below threshold frequency no photo electrons are emitted.', '[{"id":"A","text":"A, B, E Only"},{"id":"B","text":"A, B, C, D, E Only"},{"id":"C","text":"A, C, E Only"},{"id":"D","text":"C, D, E only"}]', 0, 'C', 'Since all the three-frequency curve have same saturation current, this must imply same intensity for all three as photoelectric current depends on intensity of radiation. Intensity equals $ I = nhv / AT $ (where A and T is constant), thus intensity depends on both number of photons(n) and frequency of radiation(v). Since intensity is constant, this should mean a inverse proportionality relation between number of photon and frequency, As frequency increases number of photon decreases to maintain same intensity. But as the number of photons decreases, number of photoelectrons decreases resulting in a decreases in photoelectric current. Thus concluding that different frequencies should not have same saturation current

A metal exhibits photoelectric effect that when a light of certain frequency, greater than the threshold frequency of metal surface, falls on the metal then the surface starts to emit electrons from its surface known as photo-electrons. If frequency of light is less than the threshold frequency, no emission of photo-electrons takes place.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.497Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3505, 'physics-2023-05-25-shift-3', 'q28', 28, 28, 'For insulators and semiconductors, the resistance decreases with increase in temperature because', '[{"id":"A","text":"number density decreases"},{"id":"B","text":"number density of charge carriers increases"},{"id":"C","text":"Resistivity does not depend upon the temperature"},{"id":"D","text":"Resistivity does not depend upon the number density of Charge carriers"}]', 0, 'B', 'In semiconductor, the density of charge carriers (electron holes) is very small, so its resistance is high. When temperature increases the charge carriers (density) increases which increases the conductivity. As temperature of semiconductor

increases, the speed of free electrons increases which decreases the relaxation time. As the density of charge carries is small so there is small effect on decrease of relaxation time.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.497Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3506, 'physics-2023-05-25-shift-3', 'q29', 29, 29, 'A long wire carrying current I is bent in the form of a circle as shown in the figure.

The $ \overrightarrow{B} $ at point O is:', '[{"id":"A","text":"$ \\frac{\\mu_0}{4\\pi} = \\frac{2\\mathrm{I}}{\\mathrm{r}} $ (1 - $ \\pi $) perpendicularly outward"},{"id":"B","text":"$ \\frac{\\mu_{0}}{4\\pi} = \\frac{2\\pi I}{r} $ perpendicularly inward"},{"id":"C","text":"$ \\frac{\\mu_{0}}{4\\pi} = \\frac{21}{r} (1 + \\pi) $ perpendicularly outward"},{"id":"D","text":"$ \\frac{\\mu_{0}}{4\\pi} = \\frac{21}{\\mathrm{r}} (1 + \\pi) $ perpendicularly inward"}]', 0, 'D', '$$ \frac{\mu_{0}l}{2\pi}(\pi+1) $$

Magnetic field at point O due to straight wire AB is

$$ B_{1}=\frac{\mu_{0}}{4\pi i}\frac{2\mathrm{I}}{r}=\frac{\mu_{0}l}{2\pi r} $$

Both these fields are normal to the plane of the loop and directed into the page. Therefore, net field at point O is

$$ B=B_{1}+B_{2}=\frac{\mu_{0}l}{2\pi r}+\frac{\mu_{0}l}{2r}=\frac{\mu_{0}l}{2\pi r}(1+\pi) $$', NULL, 'null', '[]', '[{"id":"q29-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-25-shift-3/q29-figure-1.jpg","page":4,"alt":"Figure for question 29"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.497Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3507, 'physics-2023-05-25-shift-3', 'q30', 30, 30, 'A bubble in glass slab ( $ \mu = 1.5 $) when viewed from one side appears at 5 cm and 2 cm from otherside, then the thickness of the glass slab is:', '[{"id":"A","text":"2.5 cm"},{"id":"B","text":"7.5 cm"},{"id":"C","text":"10.5 cm"},{"id":"D","text":"17.5 cm"}]', 0, 'C', 'Total apparent depth,

$$ y=y_{1}+y_{2}=5+2=7cm. $$

If x is real depth

= thickness of slab, then as

$$ \mu=\frac{\text{real depth}}{\text{apparent depth}}=\frac{x}{y} $$

$$ or,x=\mu y=1.5\times7=10.5cm. $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3508, 'physics-2023-05-25-shift-3', 'q31', 31, 31, 'Match List - I with List - II', '[{"id":"A","text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)"},{"id":"B","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"C","text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)"},{"id":"D","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q31-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-25-shift-3/q31-table-1.jpg","page":4,"alt":"Table for question 31"},{"id":"q31-table-2","kind":"table","path":"/local-papers/assets/physics-2023-05-25-shift-3/q31-table-2.jpg","page":4,"alt":"Table for question 31"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3509, 'physics-2023-05-25-shift-3', 'q32', 32, 32, 'I-V characteristics of solar cell is drawn in the fourth quadrant. The reason is', '[{"id":"A","text":"Solar cells does not draw current and supplies the same to the load."},{"id":"B","text":"Solar cell draws the current and does not supply."},{"id":"C","text":"Solar cell does not supply the current."},{"id":"D","text":"Solar cell only store the light energy."}]', 0, 'A', 'The solar cell does not need current for its operation; it gives current to the load. Also the EMF generated by the cells is positive As, the current is negative and the EMF generated is positive, that is why we have a graph in the fourth quadrant and the graph appears in the fourth quadrant. Without illumination, a solar cell has similar I-V characteristics like a large diode. When the light is incident on the cell, the I-V curve goes in the fourth quadrant since the cell begins to produce power. The P part of the P-N junction behaves as a positive electrode and the N side of the PN junction acts as a negative terminal of the electrode. Therefore, it can be said that the flow of current from the positive side when external source resistance is connected. Therefore, a solar cell does not withdraw current but it supplies to the load.', NULL, 'null', '[]', '[{"id":"q32-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-25-shift-3/q32-figure-1.jpg","page":4,"alt":"Figure for question 32"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3510, 'physics-2023-05-25-shift-3', 'q33', 33, 33, 'A parallel plate capacitor whose capacitance C is 13.0 pF is charged by a battery to a potential difference V = 13.0 V between its plates. What is the potential energy of the capacitor?', '[{"id":"A","text":"1.098 nJ"},{"id":"B","text":"2197 pF"},{"id":"C","text":"1.98 pJ"},{"id":"D","text":"2.197 nJ"}]', 0, 'A', 'Capacitance, C = 13pF

Potential difference, $ V = 13 \, V $

the initial energy stored in the capacitor Initial energy stored in the capacitor.

$$ \begin{array}{r l}{U_{i}}&{{}=(1/2)c v^{2}}\end{array} $$

$$ \begin{array}{r l}{U_{i}}&{{}=(1/2)\times13\times(13)^{2}p J}\end{array} $$

$$ U_{i} \quad =1098p J=1.098\mathrm{n J} $$

Sol.

$$ \begin{aligned}\frac{1}{d}\quad&=R^{2}\left(\frac{1}{n^{2}}-\frac{1}{m^{2}}\right)\\&=1.09\times10^{7}\times2^{2}\left(\frac{1}{2^{2}}-\frac{1}{3^{2}}\right)\\&=1.09\times10^{7}\times4\left(\frac{1}{4}-\frac{1}{9}\right)\\d\quad&=0.605\times10^{7}\\d\quad&=1.65\times10^{7}m\\&=165nm\end{aligned} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3511, 'physics-2023-05-25-shift-3', 'q35', 34, 34, 'An electric dipole of dipole moment $ 5 \times 10^{-6} $ Cm is placed in a uniform electric field of $ 10^{-2} $ N/C making an angle of $ 30^\circ $ with the direction of the field. The torque exerted by the electric field on the dipole is:', '[{"id":"A","text":"$ 1 \\times 10^{-8} $ Nm"},{"id":"B","text":"$ 1.5 \\times 10^{-8} $ Nm"},{"id":"C","text":"$ 2.5 \\times 10^{-8} $ Nm"},{"id":"D","text":"$ 5 \\times 10^{-8} $ Nm"}]', 0, 'C', 'Here, $ p = 5 \times 10^{-6} $ C.m, $ E = 10^{-2}N/C $, $ \theta = 30^{\circ} $
$ \tau = pE\sin\theta $
$ =(5\times10^{-6})10^{-2}\sin30^{\circ} $
$ =2.5\times10^{-8} $ N.m', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3512, 'physics-2023-05-25-shift-3', 'q36', 35, 35, 'Choose the wrong statement:', '[{"id":"A","text":". Potential difference across the terminals of the cell in a closed circuit is less than its emf."},{"id":"B","text":"Internal resistance of the cell decreases with decrease in temperature of electrolyte."},{"id":"C","text":"Terminal potential difference versus current graph for a cell is a straight line with a negative slope."},{"id":"D","text":"Terminal potential difference when cell is being charged V=E+Ir."}]', 0, 'B', 'In the presence of electrolyte, internal resistance, $ R_{1} $ is inversely proportional to temperature T. It is because, as we increase the temperature, more electrolyte dissociates and resistance decreases.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3513, 'physics-2023-05-25-shift-3', 'q37', 36, 36, 'A dielectric material placed in uniform electric field, which of the following option is $ \underline{\text{NOT CORRECT}} $:', '[{"id":"A","text":"The free movement of charges in a dielectric is not possible"},{"id":"B","text":"The free movement of charges in a dielectric is possible"},{"id":"C","text":"The external field induces dipole moment by stretching molecules of dielectrics"},{"id":"D","text":"The external field induces dipole moment by re-orienting molecules of dielectrics"}]', 0, 'B', 'Then dielectrics are placed in an electric field, practically no current flows in them because, unlike metals, they have no loosely bound, or free, electrons that may drift through the material. Instead, electric polarization occurs.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.498Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3514, 'physics-2023-05-25-shift-3', 'q38', 37, 37, 'A ray of light passes through four transparent media with refractive index $ \mu_1, \mu_2, \mu_3 $ and $ \mu_4 $ shown in figure. The surfaces of all media are parallel. If BC and DE are parallel, we must have', '[{"id":"A","text":"$ \\mu_1 = \\mu_4 $"},{"id":"B","text":"$ \\mu_2 = \\mu_3 $"},{"id":"C","text":"$ \\mu_2 = \\mu_4 $"},{"id":"D","text":"$ \\mu_1 = \\mu_2 $"}]', 0, 'C', 'Here, incident ray $BC$ is parallel to emergent ray $DE$

$\therefore \theta_{2} = \theta_{4}$

Since, incident ray $BC$ is parallel to emergent ray $DE$, so we can use

$\mu \sin \theta = \text{constant}$

So, for first and last media,

$\mu_{2} \sin \theta_{2} = \mu_{4} \sin \theta_{4}$

$\Rightarrow \mu_{2} = \mu_{4} \left( \because \theta_{2} = \theta_{4} \right)$', NULL, 'null', '[]', '[{"id":"q38-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-25-shift-3/q38-table-1.jpg","page":5,"alt":"Table for question 38"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.499Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3515, 'physics-2023-05-25-shift-3', 'q39', 38, 38, 'Four materials A, B, C and D have the magnetic susceptibility $ x_{mA}, x_{mB}, x_{mc} $ and $ x_{mD} $ respectively. which are related as $ x_{mD} < x_{mC} < x_{mB} < x_{mA} $. Which material can be magnetised with maximum ease?', '[{"id":"A","text":"B"},{"id":"B","text":"C"},{"id":"C","text":"A"},{"id":"D","text":"D"}]', 0, 'C', 'Materials that can be magnetized, which are also the ones that are strongly attracted to a magnet, are called ferromagnetic (or ferrimagnetic) substances. Magnetic susceptibility is very high and positive and depends on the applied field.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.499Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3516, 'physics-2023-05-25-shift-3', 'q40', 39, 39, 'Which of the following statements are correct?

A. The angle at minimum deviation of a prism is greater for violet light than that for red light.

B. The purpose of microscopes and telescopes is to increase the visual angle.

C. For the diffraction to take place the size of aperture or of the obstacle should be comparable to the wavelength of light.

D. The light scattered in the direction of the incident light is always plane polarised.

E. The source and its virtual image can behave as a coherent sources.', '[{"id":"A","text":"A, B, and C only"},{"id":"B","text":"A, B, C, D only"},{"id":"C","text":"A, B, C, E Only"},{"id":"D","text":"B, C, D, E Only"}]', 0, 'C', 'Linearly polarized light can be obtained by scattering. This is possible because when the light is scattered by the air molecules, the incident light and the scattered light are perpendicular to each other', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.499Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3517, 'physics-2023-05-25-shift-3', 'q41', 40, 40, 'Light of uniform intensity shines perpendicularly on a totally absorbing surface, fully illuminating the surface. If the area of the surface is decreased, what is the effect on radiation pressure?', '[{"id":"A","text":"Increases"},{"id":"B","text":"Decreases"},{"id":"C","text":"Remains the same"},{"id":"D","text":"Cannot be said"}]', 0, 'C', 'Light of uniform intensity shines perpendicularly on a totally absorbing surface, fully illuminating the surface. If the area of the surface is decreased, the radiation pressure stays.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.500Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3518, 'physics-2023-05-25-shift-3', 'q42', 41, 41, 'The intensity of a plane monochromatic wave is 1380 Wm⁻² What is the amplitude of electric field in this wave? (Take speed of light $ 3 \times 10^8 \, \text{ms}^{-1} $; $ \omega_0 = 8.85 \times 10^{-12} \, \text{C}^2 \, \text{N}^{-1} \, \text{m}^{-2} $)', '[{"id":"A","text":"102 N C⁻¹"},{"id":"B","text":"10.2 N C⁻¹"},{"id":"C","text":"1020 N C⁻¹"},{"id":"D","text":"10200 N C⁻¹"}]', 0, 'C', 'Intensity of wave $=\frac{1}{2}\epsilon_0E_0^2C$

$\epsilon_0=8.85\times10^{-12};E_0=?;C=3\times10^8,I=1380\mathrm{W/m^2}$

$1380=1/2\times8.85\times10^{-12}\times E_0^2\times3\times10^8$

$\Rightarrow E_0^2=\frac{2\times1380}{8.85\times3\times10^{-4}}=103.95\times10^4$

$\Rightarrow E_0=10.195\times10^2=1020\mathrm{N C}^{-1}$', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.500Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3519, 'physics-2023-05-25-shift-3', 'q43', 42, 42, 'In free space, all components of the complete electromagnetic spectrum have the same', '[{"id":"A","text":"energy"},{"id":"B","text":"velocity"},{"id":"C","text":"frequency"},{"id":"D","text":"intensity"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.500Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3520, 'physics-2023-05-25-shift-3', 'q44', 43, 43, 'The intensity of light due to (see figure) interference of two waves (1) and (2) which have path difference of $ \lambda $ is: (where $ I_{0} = \text{Intensity of each wave}) $', '[{"id":"A","text":"Zero"},{"id":"B","text":"$ I_{0} $"},{"id":"C","text":"$2I_{0}$"},{"id":"D","text":"$4I_{0}$"}]', 0, 'D', 'All components of the electromagnetic spectrum in vacuum have the same velocity

Sol. we know that.

we know that,

$ I = I_0 \cos^2 \frac{\phi}{2} $

If path difference = $ \lambda $

$ \Rightarrow \Delta \phi = \frac{2\pi}{\lambda} \times \Delta x $

$ \Rightarrow \Delta \phi = \frac{2\pi}{\lambda} \times \lambda = 2\pi $

Also, $ I = 4 I_0 \cos^2 \frac{\Delta \phi}{2} = 4 I_0 \cos^2 2\pi = 4 $', NULL, 'null', '[]', '[{"id":"q44-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-25-shift-3/q44-figure-1.jpg","page":6,"alt":"Figure for question 44"}]', '[5,6]', 'keyed', '[]', '2026-11-05T20:58:59.501Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3521, 'physics-2023-05-25-shift-3', 'q45', 44, 44, 'The induced e.m.f in a coil rotating in a uniform magnetic field will increases if

A. Total number of turns in the coil decreases

B. Magnetic field increases

C. Speed of rotation of coil decreases

D. Area of the coil increases', '[{"id":"A","text":"A, C and D only"},{"id":"B","text":"B and D only"},{"id":"C","text":"A, B and C Only"},{"id":"D","text":"A, B, C and D only"}]', 0, 'B', 'The magnitude of induced emf increases with the increase in the number of turns in closed coil. The induced emf in a coil change when the speed (acceleration) of the coil in a magnetic field is increased. This is because the induced emf is directly proportional to the rate of change of flux linkage.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.501Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3522, 'physics-2023-05-25-shift-3', 'q46', 45, 45, 'What is the ratio of wavelength in the given figure of energy levels of a molecule', '[{"id":"A","text":"5:1"},{"id":"B","text":"1:4"},{"id":"C","text":"2:3"},{"id":"D","text":"6:1"}]', 0, 'D', '$$ \begin{array}{l}E=\frac{hc}{\lambda}\\ \Rightarrow\lambda=\frac{hc}{E}\\ \Rightarrow\lambda\propto\frac{1}{E}\end{array} $$

Energy of photon of wavelength $\lambda_{2}\ \Delta E_{2}=-E-(-5E)=4E$

Energy of photon of wavelength $\lambda_{1}\Delta E_{1}=-E-(-\frac{5}{3}E)$

$=\frac{2}{3}E$

$\therefore\frac{\lambda_{1}}{\lambda_{2}}=\frac{\Delta E_{2}}{\Delta E_{1}}=\frac{(4E)}{\frac{2}{3}E}=\frac{4\times3E}{2E}$

$r=\frac{\lambda_{1}}{\lambda_{2}}=\frac{6}{1}$', NULL, 'null', '[]', '[{"id":"q46-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-25-shift-3/q46-figure-1.jpg","page":6,"alt":"Figure for question 46"}]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.501Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3523, 'physics-2023-05-25-shift-3', 'q47', 46, 46, 'A bulb and a capacitor are connected in series to an a.c. source. A dielectric slab is now introduced between the plates of the capacitor. The intensity of the bulb will be:', '[{"id":"A","text":"Zero"},{"id":"B","text":"Increases"},{"id":"C","text":"Decreases"},{"id":"D","text":"Remain same"}]', 0, 'B', 'As the dielectric slab is introduced between the plates of the capacitor, its capacitance will increase. Hence, the potential drop across the capacitor will decrease (V = Q/C). As a result, the potential drop across the bulb will increase (since both are connected in series). So, it brightness will increase.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.501Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3524, 'physics-2023-05-25-shift-3', 'q48', 47, 47, 'Match List - I with List - II', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)"},{"id":"C","text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)"},{"id":"D","text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q48-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-25-shift-3/q48-table-1.jpg","page":6,"alt":"Table for question 48"}]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.501Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3525, 'physics-2023-05-25-shift-3', 'q49', 48, 48, 'The magnitude of electric force exerted by a proton on an electron in a hydrogen atom is, (Given distance of separation between charges, 1Å)', '[{"id":"A","text":"$ 2.3 \\times 10^{-10} N $"},{"id":"B","text":"$ 2.3 \\times 10^{-8} N $"},{"id":"C","text":"$ 2.3 \\times 10^{-9} N $"},{"id":"D","text":"$ 2.3 \\times 10^{-7} N $"}]', 0, 'D', 'Charge on electron, $ q_1 = 1.6 \times 10^{-19} $ C

Charge on proton, $ q_2 = 1.6 \times 10^{-19} $ C

Distance between charges, $ r = 1\AA = 1 \times 10^{-10} $ m

The electrostatic force between charges is F = $ \frac{1}{4\pi\varepsilon_0} \frac{q_1 q_2}{r^2} $

$ =\frac{9 \times 10^9 \times (1.6 \times 10^{-19})^2}{(1 \times 10^{-10})^2} $

$ =\frac{9 \times 10^9 \times 2.56 \times 10^{-38}}{1 \times 10^{-21}} $

$ =2.304 \times 10^{-7} $ N', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.502Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3526, 'physics-2023-05-25-shift-3', 'q50', 49, 49, 'Displacement current $(i_{d})=\frac{\omega_{0}d\phi_{E}}{dt}$.

Where symbols have their usual meanings.

Which of the following options gives correct equation for displacement current?', '[{"id":"A","text":"$i_{d}=\\omega_{0}\\frac{d(BA)}{dt}$"},{"id":"B","text":"$i_{d}=A\\omega_{0}\\frac{dE}{dt}$"},{"id":"C","text":"$i_{d}=qA\\omega_{0}\\frac{dE}{dt}$"},{"id":"D","text":"$i_{d}=\\frac{A\\omega_{0}}{q}\\frac{dE}{dt}$"}]', 0, 'B', 'Displacement current $ (i_d) = \frac{\omega_0 d \phi_E}{dt} $

Where symbols have their usual meanings

$ i_d = A \omega_0 \frac{dE}{dt} $', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.502Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3527, 'physics-2023-05-30-shift-1', 'q01', 1, 1, 'Resolving power of a telescope can be increased by increasing:', '[{"id":"A","text":"Wavelength of light incident at telescope"},{"id":"B","text":"Diameter of eye piece"},{"id":"C","text":"Focal length of eyepiece"},{"id":"D","text":"Diameter of Objective lens"}]', 0, 'D', 'resolving power of telescope can be increased by increasing the diameter of objective lens of telescope', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.502Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3528, 'physics-2023-05-30-shift-1', 'q03', 3, 2, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"},{"id":"B","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"C","text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)"},{"id":"D","text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"}]', 0, 'B', '(A)-(IV), (B)-(III), (C)-(I), (D)-(II)', NULL, 'null', '[]', '[{"id":"q03-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q03-table-1.jpg","page":1,"alt":"Table for question 3"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3529, 'physics-2023-05-30-shift-1', 'q04', 4, 3, 'What is the mathematical expression for potential gradient?', '[{"id":"A","text":"$ \\frac{dv}{rdr} $"},{"id":"B","text":"$ -\\frac{dE}{dr} $"},{"id":"C","text":"$ -\\frac{dV}{dr} $"},{"id":"D","text":"$ -\\frac{dV}{dA} $"}]', 0, 'C', 'the mathematical expression for potential gradient is $ -\frac{dV}{dr} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3530, 'physics-2023-05-30-shift-1', 'q05', 5, 4, 'Two electrons are moving with different kinetic energies. If $ 1^{st} $ electron is moving with kinetic energy k and the $ 2^{nd} $ electron with kinetic energy 4k, the ratio of their de Broglie wavelengths will be respectively:', '[{"id":"A","text":"1:2"},{"id":"B","text":"1:4"},{"id":"C","text":"2:1"},{"id":"D","text":"4:1"}]', 0, 'C', 'Here we have, $E_{1}: E_{2} = 1: 4$

$\lambda_{1} = \frac{h}{\sqrt{2mE_{1}}}$

$\lambda_{2} = \frac{h}{\sqrt{2mE_{2}}}$

$\frac{\lambda_{1}}{\lambda_{2}} = \sqrt{\frac{E_{2}}{E_{1}}} = \sqrt{\frac{4}{1}} = \frac{2}{1}$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3531, 'physics-2023-05-30-shift-1', 'q06', 6, 5, 'The distance estimation for which ray optics is good approximation for an aperture of 3 mm and wavelength 300 nm would be:', '[{"id":"A","text":"40 m"},{"id":"B","text":"30 m"},{"id":"C","text":"20 m"},{"id":"D","text":"10 m"}]', 0, 'B', 'Here we have

Aperture (a) = 3 mm = 3 × 10⁻³ m

Wavelength (λ) = 300 nm = 300 × 10⁻⁹ m

Fresnel distance (Z) = a²/λ = (3 × 10⁻³)²/300 × 10⁻⁹ = 30 m

Thus 30m ray optics is good approximation. Hence

option 2 is correct.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3532, 'physics-2023-05-30-shift-1', 'q07', 7, 6, 'The current flowing through the two bulbs marked as 60 W, 240 V each when connected in series with 240 V source is:', '[{"id":"A","text":"0.125 A"},{"id":"B","text":"0.25 A"},{"id":"C","text":"4 A"},{"id":"D","text":"2 A"}]', 0, 'A', 'Current is same

$ I=\frac{V}{R_{1}+R_{2}} $

$ =\frac{240}{\frac{(240)^{2}}{P_{1}}+\frac{(240)^{2}}{P_{2}}} $

$ =\frac{1}{240}\times\frac{P_{1}P_{2}}{P_{1}+P_{2}} $

$ =\frac{60\times60}{120}\times\frac{1}{240} $

$ =0.125A $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3533, 'physics-2023-05-30-shift-1', 'q08', 8, 7, 'In equation $P = Ec^{-1}$, where $P$ is momentum, $E$ is energy and $c$ is the speed of light. In which of the following options, this equation is valid:', '[{"id":"A","text":"for an electron only"},{"id":"B","text":"for a photon but not for an electron"},{"id":"C","text":"for an electron as well as for a photon"},{"id":"D","text":"neither for an electron nor for a photon"}]', 0, 'B', 'The energy equation E=pc is valid only for the particle which has zero rest mass. So, it is valid for a photon but not for an electron.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.503Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3534, 'physics-2023-05-30-shift-1', 'q09', 9, 8, 'Let a rod AB of length l having resistance r is moving perpendicular to a magnetic field B with constant velocity v. If the ends of the rod is connected to a wire PQRS of negligible resistance, then current passing through the wire will be: (see fig.)', '[{"id":"A","text":"$ \\frac{Blv}{2r} $"},{"id":"B","text":"$ \\frac{Blv}{r} $"},{"id":"C","text":"$ \\frac{Blv}{4} $"},{"id":"D","text":"$ \\frac{3Blv}{4r} $"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q09-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-30-shift-1/q09-figure-1.jpg","page":1,"alt":"Figure for question 9"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3535, 'physics-2023-05-30-shift-1', 'q10', 10, 9, 'Let $ i_{E} $, $ i_{C} $ and $ i_{B} $ represent the emitter current, collector current and the base current respectively in a transistor. Choose the correct statement from the following.', '[{"id":"A","text":"$ i_{C} $ is slightly greater than $ i_{E} $"},{"id":"B","text":"$ i_{B} $ is much greater than $ i_{E} $"},{"id":"C","text":"$ i_{C} $ is equal to $ i_{B} $"},{"id":"D","text":"$ i_{E} $ is equal to the sum of $ i_{C} $ and $ i_{B} $"}]', 0, 'D', 'The highlighted parts could not be edited, as the meaning could not be understood. Also, please check the last line for logical accuracy. Only one option is given as correct, while the solution gives two correct options.

We know that in the transistor base is slightly doped, therefore when the majority carriers due to forward biasing of emitter base junction, feel the repulsive force from the battery and pass over to the base region. This gives the emitter current $ i_{E} $. As the base is thin and lightly doped, only few majority carriers of the emitter are neutralized at the base. This gives the base current. Hence, base current ( $ i_{B} $) is low.

The remaining majority carriers of the emitter pass to the collector and give collector current $ i_{C} $. Thus, we get the relation given below:

$$ i_{E}=i_{B}+i_{C} $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3536, 'physics-2023-05-30-shift-1', 'q12', 12, 10, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(III), (C)-(IV), (D)-(II)"},{"id":"B","text":"(A)-(II), (B)-(IV), (C)-(I), (D)-(III)"},{"id":"C","text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)"},{"id":"D","text":"(A)-(IV), (B)-(II), (C)-(I), (D)-(III)"}]', 0, 'B', '(A)-(II), (B)-(IV), (C)-(I), (D)-(III)', NULL, 'null', '[]', '[{"id":"q12-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q12-table-1.jpg","page":2,"alt":"Table for question 12"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3537, 'physics-2023-05-30-shift-1', 'q13', 13, 11, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"B","text":"(A)-(III), (B)-(I), (C)-(II), (D)-(IV)"},{"id":"C","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"D","text":"(A)-(II), (B)-(I), (C)-(IV), (D)-(III)"}]', 0, 'A', '(A)-(IV), (B)-(III), (C)-(I), (D)-(II)', NULL, 'null', '[]', '[{"id":"q13-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q13-table-1.jpg","page":2,"alt":"Table for question 13"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3538, 'physics-2023-05-30-shift-1', 'q14', 14, 12, 'What is the value of $ V_{0} $ if the silicon diode starts conducting at 0.7 V while the Germanium start conducting at 0.3 V?', '[{"id":"A","text":"11 V"},{"id":"B","text":"12 V"},{"id":"C","text":"11.7 V"},{"id":"D","text":"11.3 V"}]', 0, 'C', 'Consider the case when Ge and Si diodes are connected as shown in the given figure.

Equivalent voltage drops across the combination

Ge and Si diode = 0.3 V

⇒ Current $ i = \frac{12 - 0.3}{5k\Omega} = 2.34mA $

∴ Output voltage $ V_{0} = R_{i} = 5k\Omega \times 2.34mA = 11.7V $', NULL, 'null', '[]', '[{"id":"q14-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-30-shift-1/q14-figure-1.jpg","page":2,"alt":"Figure for question 14"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3539, 'physics-2023-05-30-shift-1', 'q15', 15, 13, 'A cube of side ''a'' has a charge Q at each of its vertices, what is the potential due to this charge array at the centre of the cube?', '[{"id":"A","text":"$ \\frac{2Q}{\\sqrt{3}\\pi\\epsilon_0a} $"},{"id":"B","text":"$ \\frac{4Q}{\\sqrt{3}\\pi\\epsilon_0a} $"},{"id":"C","text":"$ \\frac{Q}{2\\sqrt{3}\\pi\\epsilon_0a} $"},{"id":"D","text":"$ \\frac{8Q}{\\sqrt{3}\\pi\\epsilon_0a^2} $"}]', 0, 'B', 'Diagonal of the cube face, $ d = \sqrt{(b^2 + b^2)} = b\sqrt{2} $

Diagonal of cube $ l = \sqrt{(d^2 + b^2)} = b\sqrt{3} $

Distance between center of cube and vertices, $ r = \frac{1}{2} = \frac{b\sqrt{3}}{2} $

Potential, $ v = \frac{8q}{4\pi\epsilon_0r} = \frac{4q}{\sqrt{3}\pi\epsilon_0b} $ (8 due to presence of 8 charges at the vertices)', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.504Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3540, 'physics-2023-05-30-shift-1', 'q16', 16, 14, 'What will be the time by light to travel 2 cm thickness of glass of refractive index 1.5?', '[{"id":"A","text":"$ 2 \\times 10^{-10} s $"},{"id":"B","text":"$ 2.5 \\times 10^{-10} s $"},{"id":"C","text":"$ 2.25 \\times 10^{10} s $"},{"id":"D","text":"$ 10^{-10} s $"}]', 0, 'D', 'Given, refractive index of glass

We know,

$ \mu=\frac{\text{Speed of light in vacuum}}{\text{Speed of light in medium}}=\frac{c}{v} $

$ \Rightarrow v=\frac{c}{\mu_{g}} $

$ \Rightarrow v=\frac{3\times10^{8}}{1.5}=2\times10^{8}ms^{-1} $

Thickness of the slab, d = 2 cm = 0.02 m

Time taken by a ray of light to travel through the

glass slab is given as

$ t=\frac{d}{v}=\frac{0.02}{2\times10^{8}}=10^{-10} $ seconds', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3541, 'physics-2023-05-30-shift-1', 'q17', 17, 15, 'Choose the correct relation between drift velocity $ (v_{d}) $ and current density (J) from the following:', '[{"id":"A","text":"$ v_d = \\text{Jne} $"},{"id":"B","text":"$ v_d = \\frac{J}{ne} $"},{"id":"C","text":"$ v_d = \\frac{J}{neA} $"},{"id":"D","text":"$ v_d = \\frac{J}{ne^2A} $"}]', 0, 'B', 'Current flowing in a conductor is given by $ I = A_{nev} $

$ d $

Current density $ J = \frac{I}{A} $

$ J = nev_{d} $

$ v_{d} = \frac{J}{ne} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3542, 'physics-2023-05-30-shift-1', 'q18', 18, 16, 'A

B O

The logic circuit perform the logic function of:', '[{"id":"A","text":"AND"},{"id":"B","text":"NAND"},{"id":"C","text":"OR"},{"id":"D","text":"NOR"}]', 0, 'C', 'The logic circuit performs the logic function of OR gate.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3543, 'physics-2023-05-30-shift-1', 'q19', 19, 17, 'In Ampere-circuital law, the missing term is:

(a) $ i = \varepsilon_{O} \frac{dt}{d\phi_{E}} $

(b) $ i = \varepsilon_{O} \frac{d\phi_{E}}{dt} $

(c) $ i = \frac{1}{\varepsilon_{O}} \frac{dt}{d\phi_{E}} $

(d) $ i = \frac{1}{\varepsilon_{O}} \frac{d\phi_{E}}{dt} $

Q20 Which of the following causes electric conduction in a semiconductor?', '[{"id":"A","text":"Holes only"},{"id":"B","text":"Electrons only"},{"id":"C","text":"Both electrons and holes"},{"id":"D","text":"Neither holes nor electrons"}]', 0, 'B', 'Ampere-circuital law, the missing term is $ i = \varepsilon_{0} \frac{d\phi_{E}}{dt} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3544, 'physics-2023-05-30-shift-1', 'q21', 21, 18, 'Three circuits are shown below in which same alternating current is flowing. What will be the effect on currents in three cases respectively if frequency of alternating emf be increased?

(i)

(ii)

(iii)', '[{"id":"A","text":"Decrease; decrease; increase"},{"id":"B","text":"No effect; decrease; increase"},{"id":"C","text":"Increase; increase; decrease"},{"id":"D","text":"No effect; decrease; decrease"}]', 0, 'B', 'In circuit (i), there will be no effect on the current flowing. This is because, R is not affected by frequency.

In circuit (ii), current will decrease as inductive reactance $ X_{L} = \omega L = 2\pi v L $ will increase with increasing frequency.

In circuit (iii), current will increase as capacitive reactance $ X_{C} = \frac{1}{\omega C} = \frac{1}{2\pi v C} $ will decrease on increasing the frequency.', NULL, 'null', '[]', '[{"id":"q21-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-30-shift-1/q21-figure-1.jpg","page":3,"alt":"Figure for question 21"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3545, 'physics-2023-05-30-shift-1', 'q22', 22, 19, 'Four lenses of focal length $ \pm5 $ cm and $ \pm200 $ cm are available for making a telescope. To produce the largest magnification for making a telescope with the help of these lenses, the focal length of eye piece should be:', '[{"id":"A","text":"+200 cm"},{"id":"B","text":"5 cm"},{"id":"C","text":"200 cm"},{"id":"D","text":"+5 cm"}]', 0, 'D', 'Magnifying power of telescope $ M = f_0 / f_e $ to produce largest magnifications $ f_0 > f_e $ and $ f_0 $ and $ f_e $ both should be positive convex lens. Therefore $ f_e = +5 $ cm.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.505Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3546, 'physics-2023-05-30-shift-1', 'q23', 23, 20, 'In the circuit shown below, the potential difference between A and B is:', '[{"id":"A","text":"6 V"},{"id":"B","text":"3 V"},{"id":"C","text":"2 V"},{"id":"D","text":"1 V"}]', 0, 'C', 'Potential difference across AB will be equal to battery equivalent across CD.

$$ \begin{array}{r l}{V_{A B}=V_{C D}}&{{}=\frac{\frac{E_{1}}{r_{1}}+\frac{E_{2}}{r_{2}}+\frac{E_{3}}{r_{3}}}{\frac{1}{r_{1}}+\frac{1}{r_{2}}+\frac{1}{r_{3}}}}\\ &{{}=\frac{\frac{1}{1}+\frac{2}{1}+\frac{3}{1}}{\frac{1}{1}+\frac{1}{1}+\frac{1}{1}}}\\ &{{}=\frac{6}{3}}\\ {V_{A B}}&{{}=2~V}\end{array} $$', NULL, 'null', '[]', '[{"id":"q23-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-30-shift-1/q23-figure-1.jpg","page":3,"alt":"Figure for question 23"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3547, 'physics-2023-05-30-shift-1', 'q24', 24, 21, 'In a Young double slit experiment, if one of the slits is covered with a black paper then:', '[{"id":"A","text":"Fringe width of central maxima decreases"},{"id":"B","text":"Intensity of the central maxima increases"},{"id":"C","text":"Width of maxima decreases"},{"id":"D","text":"Diffraction pattern is observed on the screen"}]', 0, 'D', 'When one slit is closed completely instead of an interference pattern a diffraction pattern is observed. Central bright fringes and Other bright fringes will be observed.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3548, 'physics-2023-05-30-shift-1', 'q25', 25, 22, 'A 300 turns rectangular coil of length 20 cm and breadth 12 cm is carrying a current of 12 A, when placed in a magnetic field of 6 T. The plane of the coil is making an angle of $ 60^{\circ} $ with the magnetic field. What is the torque acting on the coil?', '[{"id":"A","text":"518.4 N m"},{"id":"B","text":"259.2 N m"},{"id":"C","text":"447.8 N m"},{"id":"D","text":"366.6 N m"}]', 0, 'B', 'Here, $n=300, l=20\ cm=0\cdot20\ m$, $b=12\ cm=0\cdot12\ m$ $B=6T, A=l\times b=0\cdot20\times0\cdot12=0\cdot024\ m^{2}$ $I=12A$.

Angle between $\overrightarrow{B}$ and normal on the plane of the coil $\theta=90^{\circ}-60^{\circ}=30^{\circ}$

Torque, $\tau = nIBA\sin\theta$

$=300\times12\times6\times0\cdot024\times\sin30^{\circ}=259.2Nm$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3549, 'physics-2023-05-30-shift-1', 'q26', 26, 23, 'In a hydrogen atom an electron makes a transition from $ n_{1} \to n_{2} $, where $ n_{1} $ and $ n_{2} $ are the principal quantum numbers of these two states. Assuming Bohr''s model to be valid, if the time period of electron in the initial state is eight times of that in the final state, the possible values of $ n_{1} $ and $ n_{2} $ are:', '[{"id":"A","text":"$ n_{1} = 8 $, $ n_{2} = 4 $"},{"id":"B","text":"$ n_{1} = 4 $, $ n_{2} = 8 $"},{"id":"C","text":"$ n_{1} = 8 $, $ n_{2} = 2 $"},{"id":"D","text":"$ n_{1} = 2 $, $ n_{2} = 8 $"}]', 0, 'A', 'Here, Z = 1. We can derive the expression for the time period of electron in $ n^{\text{th}} $ orbit as

$ T_{n} = \frac{1}{f_{n}} \propto n^{3} $

Hence

$ \frac{T_{1}}{T_{2}} = \frac{n_{1}^{3}}{n_{2}^{3}} $. As $ T_{1} = 8T_{2} $, therefore we get

$ 8 = \left(\frac{n_{1}}{n_{2}}\right)^{3} \Rightarrow n_{1} = 2n_{2} $

Thus, the possible values of $ n_{1} $ and $ n_{2} $ are $ n_{1} = 2 $, $ n_{2} = 1 $; $ n_{1} = 4 $, $ n_{2} = 2 $; $ n_{1} = 6 $, $ n_{2} = 3 $; $ n_{1} = 8 $, $ n_{2} = 4 $ and so on.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3550, 'physics-2023-05-30-shift-1', 'q27', 27, 24, 'A parallel plate capacitor with air between the plates has a capacitance of 6pF. What will be the capacitance if the distance between the plates is reduced to half and the space between them is filled with a substance of dielectric constant 5?', '[{"id":"A","text":"30pF"},{"id":"B","text":"60pF"},{"id":"C","text":"15pF"},{"id":"D","text":"120pF"}]', 0, 'B', '1. Let the initial distance between the plates be $d$.

Let $A$ be the area of each plate.

Capacitance of the parallel plate capacitor is given by:

$$C_{i} = \frac{A \epsilon_{0}}{d}$$

Capacitance after inserting dielectric

Let $k$ be the dielectric constant.

$$C_{f} = \frac{kA \in_{0}}{d''}$$

As the distance between plates is reduced to half,

new distance is $d = \frac{d}{2}$

$$\therefore C_{f} = \frac{2kA\epsilon_{0}}{d} = 2kC_{i} = 2 \times 5 \times 6pF = 6opF$$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.506Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3551, 'physics-2023-05-30-shift-1', 'q28', 28, 25, 'The wavelength of light from the spectral emission line of sodium is 662 nm. The kinetic energy at which an electron would have same de-Broglie wavelength would be: $ (h = 6.62 \times 10^{-34} J - s, m_e = 9 \times 10^{-31} kg) $', '[{"id":"A","text":"$ 5.5 \\times 10^{-25} $ J"},{"id":"B","text":"$5.5 \\times 10^{-24} J$"},{"id":"C","text":"$ 18 \\times 10^{-23} J $"},{"id":"D","text":"$ 4.5 \\times 10^{-22} J $"}]', 0, 'A', '$ h = 6.62 \times 10^{-34} J - s $

$ m_e = 9 \times 10^{-31} kg $

$ \lambda = 662 \times 10^{-9} m $

$ K = \frac{mv^2}{2} \ldots eq(1) $

$ m $ is the mass of the electron.

We have de Broglie wavelength as,

$ \lambda = \frac{h}{mv} \Rightarrow v = \frac{h}{m\lambda} \ldots eq(2) $

From (1) and (2), we get $ K = \frac{h^2}{2\lambda^2 m_e} = \frac{(6.62 \times 10^{-34})^2}{2 \times (662 \times 10^{-9})^2 \times 9 \times 10^{-31}} = 5.55 \times 10^{-25} J $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3552, 'physics-2023-05-30-shift-1', 'q29', 29, 26, 'A e.m.f. $ e_s = 50\sin 314t $ is applied across a pure capacitor of $ 637\mu F $. The instantaneous current I is:', '[{"id":"A","text":"$ 10\\cos 314tA $"},{"id":"B","text":"$ 50\\cos 314tA $"},{"id":"C","text":"$ 20\\cos 314tA $"},{"id":"D","text":"$ 20\\sin 314tA $"}]', 0, 'A', '$E=50\sin(314t)$

we have $\omega=314\Rightarrow2(\pi)f=100\pi\Rightarrow f=50\ Hz$

Capacitive reactance:

$(X_{c})=\frac{1}{\omega C}=\frac{1}{314\times637\times10^{-6}}=5\Omega$

since there is pure capacitor in the circuit, so

current leads emf by $(\phi)=(\pi)/2$

$i-i_{0}\sin(\omega t+\phi0=i_{0}\sin[314t+(\pi)/(2)]$

$=\frac{E_{0}}{X_{C}}\cos(314t)=\frac{50}{5}\cos(314t)=10\cos(314t)$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3553, 'physics-2023-05-30-shift-1', 'q30', 30, 27, 'An alpha-particle moves with a speed of $ (5 \times 10^5\,\text{fm})^-1 $. It enters a region where there is a magnetic field of magnitude 4T, directed at an angle of $ 45^\circ $ to the X-axis and lying in XY plane. The magnitude of magnetic force on alpha particle is:', '[{"id":"A","text":"$ 1.6 \\times 10^{-14}\\,N $"},{"id":"B","text":"$ 3.2 \\times 10^{-13}\\,N $"},{"id":"C","text":"$ 4.5 \\times 10^{-13}\\,N $"},{"id":"D","text":"$ 1.6 \\times 10^{-13}\\,N $"}]', 0, 'C', 'The speed of alpha-particle,

$ v = (5 \times 10^{5} \hat{l}) \, ms^{-1} $

Magnetic field, B = 4.0 Tesla

Angle $ \theta = 45^{\circ} $

Charge on proton, $ q = 2 \times 1.6 \times 10^{-19} C $

When the proton enters in magnitude field, it

experiences Lorentz force

$ F = q(v \times B) $

$ |F| = qvB\sin\theta $

$ F = 2 \times 1.6 \times 10^{-19} \times 5 \times 10^{6} \times 4 \times \sin 45^{\circ} $

$ = 4.52 \times 10^{-13} N $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3554, 'physics-2023-05-30-shift-1', 'q31', 31, 28, 'Calculate the Ratio of Range of Transmitting antenna of height 64 m to the receiving antenna of height 16 m:', '[{"id":"A","text":"4:1"},{"id":"B","text":"1:4"},{"id":"C","text":"2:1"},{"id":"D","text":"1:2"}]', 0, 'C', '$ H_{R} = 16 \, m $ and $ H_{T} = 64 \, m $

Ratio of covering Range= $ \frac{\sqrt{2RH_{T}}}{\sqrt{2RH_{R}}}=\frac{\sqrt{2RH_{T}}}{\sqrt{2R16}}=\frac{\sqrt{64}}{\sqrt{16}}=\frac{\sqrt{64}}{\sqrt{16}}=\frac{8}{4}=\frac{2}{1} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3555, 'physics-2023-05-30-shift-1', 'q32', 32, 29, 'The resistance of a potentiometer wire of length 4 m is 10Ω. A resistance box and 2 V accumulator are connected in series with it. What resistance should be introduced in the box to have a potential drop of 1μV/mm of the potentiometer wire?

(a) 799.9Ω

(b) 790Ω

(c) 9.995Ω

(d) 4990Ω

Q33 What is the unit of electric flux in terms of the base units of SI?', '[{"id":"A","text":"$ kg^{-1} \\, m^3 \\, s^{-3} \\, A^{-1} $"},{"id":"B","text":"$ kgm^3 \\, s^3 \\, A^{-1} $"},{"id":"C","text":"$ kgm^3 \\, s^{-3} \\, A^1 $"},{"id":"D","text":"$ kgm^3 \\, s^{-3} \\, A^{-1} $"}]', 0, 'D', '$R = 10\Omega, L = 4\ m, E = 2\ V,$

$K = 1\mu V/mm = 1 \times \frac{10^{-6}V}{10^{-3}m} = 10^{-3}V/m$

$K = \frac{V}{L} = \frac{ER}{(R+R_{B})L}$

where $R_{B}$ is the resistance in the box.

$\therefore 10^{-3} = \frac{2 \times 10}{(10 + R_{B})4}$

$\therefore 10 + R_{B} = \frac{5}{10^{-3}}$

$\therefore 10 + R_{B} = 5 \times 10^{3}$

$\therefore R_{B} = 5000 - 10$

$\therefore R_{B} = 4990\Omega$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3556, 'physics-2023-05-30-shift-1', 'q34', 34, 30, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"},{"id":"B","text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)"},{"id":"C","text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)"},{"id":"D","text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)"}]', 0, 'B', '(A)-(IV), (B)-(I), (C)-(III), (D)-(II)', NULL, 'null', '[]', '[{"id":"q34-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q34-table-1.jpg","page":4,"alt":"Table for question 34"},{"id":"q34-table-2","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q34-table-2.jpg","page":4,"alt":"Table for question 34"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3557, 'physics-2023-05-30-shift-1', 'q35', 35, 31, 'A capacitor charged from a 50 V d.c. supply is found to have charge of $ 10\mu C $. The capacitance of the capacitor would be:', '[{"id":"A","text":"$ 0.1\\mu F $"},{"id":"B","text":"$ 0.2\\mu F $"},{"id":"C","text":"$ 0.3\\mu F $"},{"id":"D","text":"$ 0.4\\mu F $"}]', 0, 'B', 'As $ C = \frac{q}{V} = \frac{10 \times 10^{-6}}{50} = 0.2\mu F $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3558, 'physics-2023-05-30-shift-1', 'q36', 36, 32, 'In terms of Bohr radius $ a_{0} $ the radius of $ 2^{nd} $ Bohr orbit of Hydrogen is:', '[{"id":"A","text":"$ 4a_{0} $"},{"id":"B","text":"$ 8a_{0} $"},{"id":"C","text":"$ \\sqrt{2}a_{0} $"},{"id":"D","text":"$ 2a_{0} $"}]', 0, 'A', 'As $ r \propto n^{2} $, therefore, radius of 2nd Bohr''s orbit = 4a_{0}.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3559, 'physics-2023-05-30-shift-1', 'q37', 37, 33, 'A point charge q moves from point A to point D along the path ABCD (as shown) in a uniform electric field E pointing parallel to negative direction of X-axis. The co-ordinates of A, B, C, D are $ (0,0,0) $, $ (a,b,0) $, $ (3a,0,0) $ and $ (2a,-b,0) $ respectively. The work done by the field in the above process is given by expression:', '[{"id":"A","text":"$ qEa $"},{"id":"B","text":"$ \\sqrt{2}qEa $"},{"id":"C","text":"qEa"},{"id":"D","text":"2aqE"}]', 0, 'D', '- 2aqE', NULL, 'null', '[]', '[{"id":"q37-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-05-30-shift-1/q37-figure-1.jpg","page":4,"alt":"Figure for question 37"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3560, 'physics-2023-05-30-shift-1', 'q38', 38, 34, 'A radioactive nucleus decays as given below:

$ \overset{A}{Z}P \to \overset{A}{Z+1}Q \to \overset{A-4}{Z-1}R^{*}\to \overset{A-4}{Z-1}R $

Which particles are emitted in the sequence?', '[{"id":"A","text":"$ \\alpha $, $ \\beta $, $ \\gamma $"},{"id":"B","text":"$ \\beta $, $ \\gamma $, $ \\alpha $"},{"id":"C","text":"$ \\gamma $, $ \\alpha $, $ \\beta $"},{"id":"D","text":"$ \\beta $, $ \\alpha $, $ \\gamma $"}]', 0, 'D', '$\alpha$-decay
$Z^{P^{A}}\stackrel{\alpha}{\longrightarrow}Z-2^{P^{A-4}}$
$\beta$-decay
$Z^{P^{A}}\stackrel{\beta}{\longrightarrow}Z+1^{P^{A}}$
$\gamma$-decay consists of electromagnetic radiation:
Now, the given decay series.
$Z^{P^{A}}\stackrel{\beta}{\rightarrow}Z+1^{Q^{A}}\stackrel{\alpha}{\rightarrow}Z-1^{R^{A-4}}\stackrel{\gamma}{\rightarrow}Z-1^{R^{A-4}}$
$\therefore$ The correct sequence.
$\beta, \alpha, \gamma$', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.507Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3561, 'physics-2023-05-30-shift-1', 'q39', 39, 35, 'An electron moves around the nucleus in a hydrogen atom of radius 0.05 nm with a velocity of $ 2 \times 10^{6} \, m s^{-1} $. The magnetic field produced at the center of nucleus is:', '[{"id":"A","text":"0.128"},{"id":"B","text":"6.4 T"},{"id":"C","text":"128 T"},{"id":"D","text":"12.8"}]', 0, 'D', '$ r = 0 \cdot 05\text{nm} = 5 \times 10^{-11}\text{ m} $
$ v = 2 \times 10^6\text{ m/s} $
$ I = \frac{e}{T} = \frac{e}{2\pi r/v} = \frac{ev}{2\pi r} $
$ = \frac{1 \cdot 6 \times 10^{-19} \times 2 \times 10^6}{2 \times 3 \cdot 14 \times 5 \times 10^{-11}} = 1.019 \times 10^{-4} $
$ B = \frac{\mu_0 I}{2r} = \frac{4\pi \times 10^{-7} \times 0.01019}{2 \times 5 \times 10^{-11}} = 12.79T $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3562, 'physics-2023-05-30-shift-1', 'q40', 40, 36, 'Match List - I with List - II.

Choose the correct answer from the options given below:

(a) (A)-(IV), (B)-(III), (C)-(I), (D)-(II)

(b) (A)-(IV), (B)-(III), (C)-(II), (D)-(I)

(c) (A)-(III), (B)-(IV), (C)-(I), (D)-(II)

(d) (A)-(II), (B)-(III), (C)-(I), (D)-(IV)

41. In an experiment, a student in the laboratory measures the terminal potential difference (V) of a cell (emf E and internal resistance r) as a function of current I flowing through it and plot a graph taking V on y-axis and I on x-axis. What is the slope of the graph between V and I?', '[{"id":"A","text":"$ r^{2} $"},{"id":"B","text":"$ -r^{2} $"},{"id":"C","text":"r"},{"id":"D","text":"r Compare it with standard equation of the line: $ y = mx + c $ $ \\Rightarrow y = c + mx $ Since graph of student is V vs I $ \\therefore $ V is y and I is x Since graph of student is $V$ vs $1$ : $V$ is $y$ and $I$ is $x$ Therefore, $(-r)$ is slope"}]', 0, 'A', NULL, NULL, 'null', '[]', '[{"id":"q40-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q40-table-1.jpg","page":5,"alt":"Table for question 40"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3563, 'physics-2023-05-30-shift-1', 'q42', 42, 37, 'A plane electromagnetic wave of frequency

30MHz travels in free space along the $x$-direction.

At a particular point in space and time $\vec{E} =$

6.3$\hat{j}$ $V/m$. The $\vec{B}$ at this point would be:', '[{"id":"A","text":"$2.1 \\times 10^{-8}\\hat{k}$ $T$"},{"id":"B","text":"$2.1 \\times 10^{-6}\\hat{j}$ $T$"},{"id":"C","text":"$1.6 \\times 10^{-8}\\hat{i}$ $T$"},{"id":"D","text":"$2.6 \\times 10^{-8}\\hat{j}$ $T$"}]', 0, 'A', 'frequency = 30MHz

Electric field $ \varepsilon = \frac{6v}{m}f $ (along + y axis)

Now we know that

$ c=\frac{\varepsilon_{0}}{B_{0}} $

c = speed of EM wave = $ 3 \times 10^{8} $ m/s

$ \varepsilon_{0} $ = peak value of electric field

$ B_{0} $ = peak value of magnetic field

$ c=\frac{\varepsilon}{B} $

B = magnetic field

$ 3 \times 10^{8}=\frac{6}{B} $

$ B=\frac{6}{3\times10^{8}}B=2.1\times10^{-8} $ Tesla

Now we have to find direction of magnetic field

We know that wave propagates in the direction

perpendicular to oscillating electric field and

magnetic field.

$ c=\vec{\varepsilon}\times\vec{B} $ (Only for direction)

c = along x axis

$ \varepsilon $ = along y axis

$$ B=2.1\times10^{-8}\hat{k}T $$', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3564, 'physics-2023-05-30-shift-1', 'q43', 43, 38, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)"},{"id":"C","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"D","text":"(A)-(III), (B)-(IV), (C)-(II), (D)-(I)"}]', 0, 'D', '(A)-(III), (B)-(IV), (C)-(II), (D)-(I)', NULL, 'null', '[]', '[{"id":"q43-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q43-table-1.jpg","page":5,"alt":"Table for question 43"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3565, 'physics-2023-05-30-shift-1', 'q44', 44, 39, 'Which of the following statements are correct?

(A) When light rays undergo two internal reflections inside a raindrop, a secondary rainbow is formed.

(B) The angle between the emergent ray and angle of prism is called the angle of deviation.

(C) Light undergoes successive total internal reflections as it moves through an optical fiber.

(D) A telescope provides angular magnification of distant objects.

(E) A simple magnifier is a diverging lens of small focal length.', '[{"id":"A","text":"(A), (B) and (E) only"},{"id":"B","text":"(A), (C) and (D) only"},{"id":"C","text":"(B), (C), (D) and (E) only"},{"id":"D","text":"(A), (B), (C) and (D) only"}]', 0, 'B', 'When the light rays undergo two internal reflections in a water drop, a secondary rainbow is formed. Observer can see a rainbow when his front is towards the Sun. Light is made to undergo total internal reflection successive times as the ray of light moves through the optical fiber. An astronomical telescope has an angular magnification of magnitude 5 for distant objects.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3566, 'physics-2023-05-30-shift-1', 'q45', 45, 40, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"},{"id":"C","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"},{"id":"D","text":"(A)-(II), (B)-(III), (C)-(I), (D)-(IV)"}]', 0, 'B', '(A)-(III), (B)-(II), (C)-(IV), (D)-(I)', NULL, 'null', '[]', '[{"id":"q45-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q45-table-1.jpg","page":5,"alt":"Table for question 45"}]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3567, 'physics-2023-05-30-shift-1', 'q46', 46, 41, 'Which of the following is not a significant characteristic of a pulse?', '[{"id":"A","text":"Pulse amplitude"},{"id":"B","text":"Pulse width"},{"id":"C","text":"Pulse position"},{"id":"D","text":"Pulse duration modulation"}]', 0, 'D', 'the significant characteristics of a pulse are pulse amplitude, pulse duration or pulse width, and pulse position (denoting the time of rise or fall of the pulse amplitude).', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3568, 'physics-2023-05-30-shift-1', 'q47', 47, 42, 'An object is placed before a convex lens and its real image is obtained. Now if half of the surface is covered with paper. The result will be:', '[{"id":"A","text":"No image will be formed"},{"id":"B","text":"Half image will be formed"},{"id":"C","text":"Image will be same as before"},{"id":"D","text":"Full image will be formed with less brightness"}]', 0, 'D', 'if half of the convex lens is covered with a black sheet of paper, the lens will produce a complete image of the object. However, the intensity of the image will be less and the image formed will be less bright as compared to the one formed by a complete convex lens', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3569, 'physics-2023-05-30-shift-1', 'q48', 48, 43, 'A car has a fresh storage battery of e.m.f. 15 V and internal resistance $ 4 \times 10^{-2} $ Ω. If the starter motor draws a current of 85 A, what is the terminal voltage of the battery when the starter is on?', '[{"id":"A","text":"3.4 V"},{"id":"B","text":"11.6 V"},{"id":"C","text":"12 V"},{"id":"D","text":"12.5 V"}]', 0, 'B', 'The relationship between the terminal voltage and emf is given as

$ V = \varepsilon - Ir $

$ V = 15 - (85 \times 0.04) $

$ V = 11.6V $', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3570, 'physics-2023-05-30-shift-1', 'q49', 49, 44, 'A bar magnet of magnetic moment 3J/T lies aligned with the directions of a uniform magnetic field of 0.2 T. The amount of work, required so as to align its magnetic moment opposite to the field direction is:', '[{"id":"A","text":"1.2 J"},{"id":"B","text":"0.6 J"},{"id":"C","text":"zero"},{"id":"D","text":"0.6 J"}]', 0, 'A', 'Magnetic moment, $ M = 3 J T^{-1} $

Magnetic field strength, $ B = 0.2 \, T $

Initial angle between the axis and the magnetic field, $ \theta_{1} = 0^{\circ} $

Final angle between the axis and the magnetic field, $ \theta_{2} = 180^{\circ} $

The work required to make the magnetic moment opposite to the direction of magnetic field is given as:

$$ \begin{array}{r l}{W}&{=-M B(c o s~\theta_{2}-c o s~\theta_{1})}\\ {}&{=-3\times0.2(c o s~180-c o s~0^{\circ})}\\ {}&{=-0.6(-1-1)}\\ {}&{=1.2J}\\ \end{array} $$', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.508Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3571, 'physics-2023-05-30-shift-1', 'q50', 50, 45, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(I), (B)-(IV), (C)-(III), (D)-(II)"},{"id":"B","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"C","text":"(A)-(III), (B)-(II), (C)-(IV), (D)-(I)"},{"id":"D","text":"(A)-(II), (B)-(III), (C)-(I), (D)-(IV)"}]', 0, 'B', '(A)-(IV), (B)-(III), (C)-(I), (D)-(II)', NULL, 'null', '[]', '[{"id":"q50-table-1","kind":"table","path":"/local-papers/assets/physics-2023-05-30-shift-1/q50-table-1.jpg","page":6,"alt":"Table for question 50"}]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3572, 'physics-2023-06-09-shift-3', 'q01', 1, 1, 'In an LCR circuit, which of the following expression has the dimension of frequency:', '[{"id":"A","text":"$\\sqrt{\\frac{L}{C}}$"},{"id":"B","text":"$\\frac{C}{R}$"},{"id":"C","text":"$\\frac{1}{\\sqrt{RC}}$"},{"id":"D","text":"$\\frac{1}{\\sqrt{LC}}$"}]', 0, 'D', 'For RC circuits, time constant is, $\tau = \mathrm{RC}$ has unit of time,

so, $\frac{1}{\mathrm{RC}}$ has a unit of frequency,

similar for LC oscillations, $\tau = \sqrt{LC}$

for $RL$ circuit, $\tau = \frac{L}{R}$

so,

$\frac{1}{\mathrm{RC}}$, $\frac{R}{\mathrm{L}}$ and $\frac{1}{\sqrt{\mathrm{LC}}}$ has units of frequency.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3573, 'physics-2023-06-09-shift-3', 'q02', 2, 2, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)"},{"id":"B","text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)"},{"id":"C","text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)"},{"id":"D","text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q02-table-1","kind":"table","path":"/local-papers/assets/physics-2023-06-09-shift-3/q02-table-1.jpg","page":1,"alt":"Table for question 2"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.509Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3574, 'physics-2023-06-09-shift-3', 'q03', 3, 3, 'What is the force between two small charged spheres having charges of $ 4 \times 10^{-7} $C and $ 6 \times 10^{-7} $C placed 60 cm apart in air?', '[{"id":"A","text":"$ 3 \\times 10^{-3} N $"},{"id":"B","text":"$ 4 \\times 10^{-3} N $"},{"id":"C","text":"$ 6 \\times 10^{-3} N $"},{"id":"D","text":"$ 9 \\times 10^{-3} N $"}]', 0, 'C', 'Charge on the first sphere, $ q_1 = 4 \times 10^{-7} $ C

Charge on the second sphere, $ q_2 = 6 \times 10^{-7} $ C

Distance between the spheres, r = 60 cm = 0.6 m

$$ \mathrm{F}=\frac{\mathrm{q}_{1}\mathrm{q}_{2}}{4\pi\varepsilon_{0}\mathrm{r}^{2}} $$

Were, $ \varepsilon_{0} $ = Permittivity of free space

$$ \frac{1}{4\pi\varepsilon_{0}}=9\times10^{9}\mathrm{N m^{2}C^{-2}} $$

$$ \mathrm{F}=\frac{9\times10^{9}\times4\times10^{-7}\times6\times10^{-7}}{(0.6)^{2}}=6\times10^{-3}\mathrm{N} $$

Hence, force between the two small charged spheres is $ 6 \times 10^{-3} $ N. The charges are of same nature. Hence, force between them will be repulsive.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3575, 'physics-2023-06-09-shift-3', 'q04', 4, 4, 'Which of the following scientists has not contributed significantly to photoelectric effect?', '[{"id":"A","text":"Wilhelm Hallwacks"},{"id":"B","text":"Philipp Lenard"},{"id":"C","text":"Albert Einstein"},{"id":"D","text":"C.J. Davission"}]', 0, 'D', 'C.J. Davission does not contributed significantly to photoelectric effect', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.509Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3576, 'physics-2023-06-09-shift-3', 'q05', 5, 5, 'Two spheres of silver of same radii, one solid and the other hollow are charged to the same potential, then:', '[{"id":"A","text":"solid sphere will have more charge"},{"id":"B","text":"hollow sphere will have more charge"},{"id":"C","text":"both spheres will have same charge"},{"id":"D","text":"solid sphere will have charge inside as well as on the surface"}]', 0, 'C', 'Both the spheres will hold the same amount of charge. It is because, the two spheres pass equal capacitance. The capacitance of a sphere depends only on its radius. It does not matter whether the sphere is hollow or solid.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3577, 'physics-2023-06-09-shift-3', 'q06', 6, 6, 'The resistivity of a potentiometer wire is $ 10^{-7} $ Ωm and its cross-section area is $ 10^{-6} $ m². When a current of 0.1 A follows through the wire, its potential gradient is:', '[{"id":"A","text":"$ 10^{-1} $ V/m"},{"id":"B","text":"$ 10^{-2} $ V/m"},{"id":"C","text":"$ 10^{-4} $ V/m"},{"id":"D","text":"10 V/m"}]', 0, 'B', 'Potential gradient of a wire equal to potential fall per unit length. Potential gradient = Potential fall per unit length = Current × Resistance per unit length = $ i = \frac{R}{l} $

But $ R = \frac{\rho l}{A} \Rightarrow \frac{R}{l} = \frac{\rho}{A} $

∴ Potential gradient = $ i \times \frac{\rho}{A} $

Here, $ \rho = 10^{-7} \, \Omega - m $, $ i = 0.1 \, A \times A = 10^{-6} \, m^2 $

Hence, potential gradient

$ = 0.1 \times \frac{10^{-7}}{10^{-6}} = \frac{0.1}{10} = 0.01 = 10^{-2} \, V/m $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3578, 'physics-2023-06-09-shift-3', 'q07', 7, 7, 'The two coherent monochromatic light beams of intensities I and 4I are superposed. The maximum and minimum possible intensities in the resulting beams are:', '[{"id":"A","text":"5 I and I"},{"id":"B","text":"9 I and I"},{"id":"C","text":"5 I and 3 I"},{"id":"D","text":"9 I and 3 I (d) 9 l and 3 l"}]', 0, 'B', 'The intensity of light waves depends on the amplitude of the wave in this manner.

$ I \propto A^{2} $

When two light waves converge, we cannot add the intensity of the light waves.

We need to find the amplitude of the waves and then calculate the resultant amplitude of the new superimposed wave.

Let''s assume the amplitude of the wave that has intensity L, is A.

As intensity depends on the square of the amplitude, we can write

$ I = kA^{2} $

Hence, for the other light wave amplitude can be given by.

$ 4I = k(2A)^{2} $

If the two light waves converge in-phase, the amplitudes can be added.

Hence, the resultant amplitude will be = (A + 2A) = 3A.

So, the intensity will be,

$ I'' = k(3A)^{2} = 9kA^{2} = 9I $

When the two light waves converge out-of-phase, the amplitude will be,

$ (2A - A) = A $

Hence, the intensity of the resultant light will be,

$ I^{n} = k(A)^{2} = kA^{2} = I $

So, the maximum intensity will be 9I and the minimum intensity will be I.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3579, 'physics-2023-06-09-shift-3', 'q08', 8, 8, 'The shortest wavelength present in the Lyman series of spectral lines is:

(Given Rydberg constant $ R = 1.097 \times 10^{7} $ m $ ^{-1} $)', '[{"id":"A","text":"$ 9.1 \\times 10^{-8} $ m"},{"id":"B","text":"$ 1.2 \\times 10^{-7} $ m"},{"id":"C","text":"$ 8.2 \\times 10^{7} $ m"},{"id":"D","text":"$ 9.1 \\times 10^{8} $ m"}]', 0, 'A', 'Rydberg''s formula is:

$ \frac{1}{\lambda} = R_{H}Z^{2}\left(\frac{1}{n_{1}^{2}} - \frac{1}{n_{2}^{2}}\right) $

For hydrogen, Z = 1 and for Lyman series, $ n_{1} = 1 $ and $ n_{2} = \infty $ (for shortest wavelength)

On substituting values, we get-

$$ \frac{1}{\lambda}=109678\times(1)^{2}\times\left[\frac{1}{(1)^{2}}-\frac{1}{(\infty)^{2}}\right] $$

$$ \frac{1}{\lambda}=109678cm^{-1} $$

$$ \begin{aligned}&or\lambda=\frac{1}{109678}cm^{-1}\\&=9.117\times10^{-6}cm\\&=911.7\times10^{-8}cm=9.1\times10^{-8}m\\ \end{aligned} $$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3580, 'physics-2023-06-09-shift-3', 'q09', 9, 9, 'Sodium has a work function of 2 eV. Calculate the maximum energy and speed of the emitted electrons, when sodium is illuminated by radiation of wavelength 150 nm:

(a) $ 7.5 \times 10^{-19} $ J and $ 3.2 \times 10^{3} $ m/s

(b) $ 13.2 \times 10^{-19} $ J and $ 1.5 \times 10^{6} $ m/s

(c) $ 7 \times 10^{-15} $ J and $ 1.2 \times 10^{4} $ m/s

(d) $ 3.5 \times 10^{-19} $ J and $ 2.4 \times 10^{6} $ m/s


The metre bridge wire is made of alloys such as nichrome because they have:', '[{"id":"A","text":"high temperature coefficient of resistance and high resistivity"},{"id":"B","text":"low temperature coefficient of resistance and low resistivity"},{"id":"C","text":"low temperature coefficient of resistance and high resistivity"},{"id":"D","text":"high temperature coefficient of resistance and low resistivity"}]', 0, 'B', 'Work Function $\left(\Phi\right)=2.0\,\mathrm{eV}$

Wavelength ($\lambda$) = 150 nm = $150\times10^{-19}$m

First, let''s calculate the maximum energy of the emitted electrons:

Energy of incident photons = ( Planck''s Constant $ ^{*} $ Speed of Light ) / Wavelength

$$ \begin{aligned}&\begin{aligned}\\ &=(6.62607015\times10^{-34}\times2.998\times10^{8}m/s)/(150\times10^{-1}\\&=8.82\times10^{-19}J\\ &\end{aligned}\\ \end{aligned} $$

Maximum Energy = Energy of incident photons - Work Function

$$ \mathrm{=8.82\times10^{-19}J-2.0eV^{*}(1.6\times10^{-19}J/eV)} $$

$$ =8.82\times10^{-19}J-3.2\times10^{-19}J $$

$$ =13.2\times10^{-19}J $$

Now, let''s calculate the maximum speed of the emitted electrons. We can use the formula:

Maximum Speed = sqrt(2 * Maximum Energy / Electron Mass)

$$ Electron~Mass=9.10938356\times10^{-31}kg $$

$$ \begin{aligned}&\text{Maximum Speed}=\sqrt{(2\times5.62\times10^{-19}/9.10938356\times10^{-31})}\\ &=1.5\times10^{6}m/s\\ \end{aligned} $$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3581, 'physics-2023-06-09-shift-3', 'q11', 11, 10, 'Match List - I with List - II.', '[{"id":"A","text":"(A)-(III), (B)-(IV), (C)-(I), (D)-(II)"},{"id":"B","text":"(A)-(III), (B)-(II), (C)-(I), (D)-(IV)"},{"id":"C","text":"(A)-(IV), (B)-(III), (C)-(II), (D)-(I)"},{"id":"D","text":"(A)-(III), (B)-(I), (C)-(II), (D)-(III)"}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q11-table-1","kind":"table","path":"/local-papers/assets/physics-2023-06-09-shift-3/q11-table-1.jpg","page":1,"alt":"Table for question 11"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3582, 'physics-2023-06-09-shift-3', 'q12', 12, 11, 'What will be the minimum length of antenna required to transmit a radio signal of frequency 10 MHz?', '[{"id":"A","text":"30 m"},{"id":"B","text":"15 m"},{"id":"C","text":"7.5 m"},{"id":"D","text":"60 m"}]', 0, 'C', 'Here, $ v = 10\text{MHz} = 10^7\text{ Hz} $

$$ \lambda=\frac{c}{v}=\frac{3\times10^{8}}{10^{7}}=30m $$

Minimum length of antenna = $ \frac{\lambda}{4} = \frac{30}{3} = 7.5 \, m $.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3583, 'physics-2023-06-09-shift-3', 'q13', 13, 12, 'The current flow in the circuit of two battery with internal resistance and two external resistance as shown in figure will be', '[{"id":"A","text":"1.5 A"},{"id":"B","text":"0.67 A"},{"id":"C","text":"0.9 A"},{"id":"D","text":"1.0 A"}]', 0, 'B', 'Since the batteries are connected in reverse polarities, the net potential applied to the circuit = 15 V - 5 V = 10 V

The net resistance in the circuit = r₁ + r₂ + r₃ + r₄ = 9Ω + 0.8Ω + 4Ω + 1.2Ω = 15Ω

$ ^{9} $m) Hence, the current in the circuit = $ \frac{10\ V}{15\Omega} $ = 0.66 A', NULL, 'null', '[]', '[{"id":"q13-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-06-09-shift-3/q13-figure-1.jpg","page":2,"alt":"Figure for question 13"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3584, 'physics-2023-06-09-shift-3', 'q14', 14, 13, 'A very long solenoid has 800 turns per unit length. A current of 1.6 A flows through it. Then the magnetic induction in the middle of the solenoid on its axis is approximately:', '[{"id":"A","text":"$ 16 \\times 10^{-4} $ T"},{"id":"B","text":"$ 8 \\times 10^{-4} $ T"},{"id":"C","text":"$ 32 \\times 10^{-4} $ T"},{"id":"D","text":"$ 4 \\times 10^{-4} $ T"}]', 0, 'A', 'The magnetic induction at the middle point of the solenoid on its axis is given as,

$$ \begin{aligned}&\mathrm{B}=\mu_{0}\mathrm{nI}\\ &=4\pi\times10^{-7}\times800\times1.6\\ &=16.084\times10^{-4}\mathrm{T}\\ \end{aligned} $$

Thus, the magnetic induction is $ 16.084 \times 10^{-4} $ T.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.510Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3585, 'physics-2023-06-09-shift-3', 'q15', 15, 14, 'The critical angle of a medium for a specific wavelength, if the medium has relative permittivity 3 and relative permeability $ \frac{4}{3} $ for this wavelength, will be:', '[{"id":"A","text":"$ 15^{\\circ} $"},{"id":"B","text":"$ 30^{\\circ} $"},{"id":"C","text":"$ 45^{\\circ} $"},{"id":"D","text":"$ 60^{\\circ} $"}]', 0, 'B', 'It is given that the

Relative permittivity of the medium, $ \epsilon_{r}=3 $

The relative permeability of the medium, $ \mu = \frac{4}{3} $

The refractive index of the medium

$$ \mu_{2}=\frac{c}{v} $$

Substituting the values of $ c = \frac{1}{\sqrt{v_0 \in 0}} $ and the $ v = \frac{1}{\sqrt{\mu \in r}} $ in the above formula,

critical angle of free space

$$ \mu_{2}=\frac{\frac{1}{\sqrt{v_{b}\in_{0}}}}{\frac{1}{\sqrt{\mu\in_{r}}}} $$

By simplifying the above equation, and also using the formula of The relative permittivity and The relative permeability of the medium in it, we get

$$ \mu_{2}=\sqrt{\mu_{r}\epsilon_{r}} $$

$$ \mu_{2}=\sqrt{3\times\frac{4}{3}} $$

$$ \mu_{2}=2 $$

Using the formula (4).

$$ \mu_{2}\sin\theta_{i}=\mu_{1}\sin\theta_{r} $$

The critical angle $ \theta_{r}=90^{\circ} $, so

$$ \mu_{2}\sin\theta_{i}=\mu_{1}\sin90^{\circ} $$

$$ \mu_{2}\sin\ \theta_{i}=2\times\frac{1}{2} $$

Substituting the value of the angles and the refractive index of the medium

$$ 2\mathrm{s i n}\theta_{i}=1 $$

$$ \theta_{i}=\frac{1}{2} $$

Hence the value of the critical angle of the medium is $ 30^{\circ} $.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3586, 'physics-2023-06-09-shift-3', 'q16', 16, 15, 'An insulating rod of length L carries charge q distributed uniformly on it. The rod is pivoted at one end and is rotated at a frequency f about a fixed perpendicular axis. Then the magnetic dipole moment of the system is:', '[{"id":"A","text":"$ \\pi qfL^{2} $"},{"id":"B","text":"$ \\frac{1}{3}\\pi qfL^{2} $"},{"id":"C","text":"qfL"},{"id":"D","text":"qfL^{2}"}]', 0, 'B', 'Consider a small element dl at a distance I from the pivot.

Charge on element = dq = $\frac{q}{l}$ dl

The rod sweeps a circle of radius I

Charge $dq$ rotating at frequency $f$ will give rise to

current $=di=dq\times f=\frac{df}{l}dl$

Magnetic moment of this element dl is

$$ d M=d i A=\frac{a_{f}}{l}d l(\pi|^{2}) $$

$$ M=\int\ d M=f\frac{q}{1}\pi\int_{0}^{1}\bigg|^{2}d l=f\frac{a}{1}\pi\frac{l^{3}}{3}=f\left(\frac{q}{1}\right)\pi\frac{13}{3} $$

$$ M=\frac{f q l^{2}\pi}{3} $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3587, 'physics-2023-06-09-shift-3', 'q17', 17, 16, 'The wave length of Red light in the visible region is about 760 nm the energy of photon in that case will be:', '[{"id":"A","text":"2.43 eV"},{"id":"B","text":"3.18 eV"},{"id":"C","text":"1.64 eV"},{"id":"D","text":"2.68 eV"}]', 0, 'C', '$$ \begin{aligned}E\quad&=\frac{hc}{\lambda}\\&=\frac{6.63\times10^{-34}\times3\times10^{8}}{760\times10^{-9}}\\&=2.61\times10^{-19}J\\ in ev\quad&\quad\frac{2.61\times10^{-19}}{1.6\times10^{-19}}\\&=\quad1.64eV\end{aligned} $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3588, 'physics-2023-06-09-shift-3', 'q18', 18, 17, 'A network of three capacitors each 9 µF connected in series and the fourth capacitor of 6 µF is supplied 400 V as shown in figure. The ratio of charge on the capacitor $ C_1 $ to the capacitor $ C_4 $ is:', '[{"id":"A","text":"1:3"},{"id":"B","text":"1:4"},{"id":"C","text":"4:1"},{"id":"D","text":"1:2"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3589, 'physics-2023-06-09-shift-3', 'q19', 19, 18, 'After how many half-lives a radioactive substance will decay to 6.25% of its original value:', '[{"id":"A","text":"One half life"},{"id":"B","text":"Two half lives"},{"id":"C","text":"Three half lives"},{"id":"D","text":"Four half lives"}]', 0, 'D', '$$ \mathrm{A}_{(\mathrm{g})}\rightarrow\mathrm{B}_{(\mathrm{g})}\mathrm{k}=2.3\times10^{-3}\mathrm{s}^{-1} $$

Here, unit of Rate constant (k) is $ \mathbf{s}^{-1} $. Therefore, it''s a first order reaction

Units of Rate constant in zero, first and second order reactions.

For a first order reaction, we can write

$$ \mathsf{N}=\frac{\mathsf{N}_{0}}{2^{\mathsf{n}}} $$

Were

$ N_{0} $ = Initial amount of substance

• $ \mathbf{N} = \text{Amount of substance after } \mathbf{n} \text{ half lives} $

• n = Number of half lives

$$ 6.25\%=\frac{100\%}{2^{n}} $$

$$ 2^{n}=\frac{100\%}{6.25\%} $$

$$ 2^{n}=16 $$

$$ 2^{n}=2^{4}=4 $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3590, 'physics-2023-06-09-shift-3', 'q20', 20, 19, 'A 20-watt, 50 V lamp is to be connected to AC mains of 250 V, 50 Hz. Calculate the value of series capacitor to run the lamp.', '[{"id":"A","text":"1.4 µF"},{"id":"B","text":"2.1 µF"},{"id":"C","text":"3.5 µF"},{"id":"D","text":"4.9 µF"}]', 0, 'D', 'Here, p = 20 watt, V = 50 volt

$ E_v = 260 \, V, C = ?, v = 50 \, Hz $

$ I = \frac{P}{V} = \frac{20}{50} = 0.4 \, A $

$ R = \frac{V}{I} = \frac{50}{0.4} = 125 \, ohm $

$ Z = \frac{E_v}{I_v} = \frac{E_v}{I} = \frac{250}{0.4} = 625 \, ohm $

$ X_C = \sqrt{Z^2 - R^2} = \sqrt{625^2 - 125^2} = 250\sqrt{6} $

As $ X_C = \frac{1}{\omega C} = \frac{1}{2\pi v C} = 250\sqrt{6} $

$ \therefore C = \frac{1}{2\pi v \times 250\sqrt{6}} $

$ = \frac{1}{2 \times 3.14 \times 50 \times 250\sqrt{6}} \text{farad} $

$ C = 0.052 \times 10^{-4} \, \text{F} = 5.2 \, \mu \text{F} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.511Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3591, 'physics-2023-06-09-shift-3', 'q21', 21, 20, 'Charge on a conducting metal sphere is present:', '[{"id":"A","text":"on the surface of the sphere"},{"id":"B","text":"inside the sphere"},{"id":"C","text":"outside the sphere"},{"id":"D","text":"both inside and outside the sphere"}]', 0, 'A', 'The charge on a conducting metal sphere is present on the surface of the sphere', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.512Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3592, 'physics-2023-06-09-shift-3', 'q22', 22, 21, 'An a.c. source of 200 V is connected through a diode ''D'' to a capacitor as shown in figure. Find the maximum potential difference across the capacitor:', '[{"id":"A","text":"100 V"},{"id":"B","text":"200 V"},{"id":"C","text":"283 V"},{"id":"D","text":"310 V"}]', 0, 'C', 'In half wave rectification, the diode will work as an open circuit for the negative half cycle. The positive half cycle will get reproduced as it is past the diode as it will work just as a closed circuit in case of a positive half cycle. Therefore, the output waveform is in the form of fluctuating dc and just consists of positive half cycles.

Now, as the current enters the capacitor with this waveform, it begins to charge till waveform reaches its peak. As the current starts to go down, the capacitor begins discharging and maintains the same peak potential difference until the next peak. Therefore, the potential difference that the capacitor has across it is simply the peak value of the input waveform i.e.,

$$ \begin{aligned}&V_{m}=V_{rms}\sqrt{2}\\ \end{aligned} $$', NULL, 'null', '[]', '[{"id":"q22-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-06-09-shift-3/q22-figure-1.jpg","page":2,"alt":"Figure for question 22"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.513Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3593, 'physics-2023-06-09-shift-3', 'q23', 23, 22, 'The electrical conductivity of a semiconductor increases when electromagnetic radiation of wavelength shorter than 2480 nm is incident on it. The band gap for the semiconductor is:', '[{"id":"A","text":"0.5 eV"},{"id":"B","text":"0.7 eV"},{"id":"C","text":"0.9 eV"},{"id":"D","text":"1.1 eV"}]', 0, 'A', 'Band gap, $ E_g = \frac{hc}{\lambda} = \frac{(6.63 \times 10^{-34})(3 \times 10^8)}{2480 \times 10^{-9} \times 1.6 \times 10^{-19}} $ eV = 0.5eV', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.513Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3594, 'physics-2023-06-09-shift-3', 'q24', 24, 23, 'Energy gap between valence band and conduction band of a semiconductor is approximately:

(a) zero

(b) 4 eV

(c) 1 eV

(d) 10 eV', '[{"id":"A","text":"(A)-(II), (B)-(I), (C)-(III), (D)-(IV)"},{"id":"B","text":"(A)-(IV), (B)-(I), (C)-(II), (D)-(III)"},{"id":"C","text":"(A)-(IV), (B)-(III), (C)-(I), (D)-(II)"},{"id":"D","text":"(A)-(I), (B)-(II), (C)-(III), (D)-(IV)"}]', 0, 'C', 'In the semiconductor, as the temperature increases the valence electron gain enough energy to jump from valence band to the conduction band. Thus, the band gap in semiconductor is approximately 1eV.', NULL, 'null', '[]', '[{"id":"q24-table-1","kind":"table","path":"/local-papers/assets/physics-2023-06-09-shift-3/q24-table-1.jpg","page":3,"alt":"Table for question 24"}]', '[2,3]', 'keyed', '[]', '2026-11-05T20:58:59.514Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3595, 'physics-2023-06-09-shift-3', 'q26', 26, 24, 'The given combination represents the following gate:', '[{"id":"A","text":"OR"},{"id":"B","text":"XOR"},{"id":"C","text":"NAND"},{"id":"D","text":"NOR"}]', 0, 'A', 'The given combination performs the function of an OR gate.

As per the combination.

$$ \begin{aligned}Y&=\overline{\overline{(A\cdot A)}}\cdot\overline{\overline{(B\cdot B)}}\\Y&=\overline{\overline{A\cdot\bar{B}}}\end{aligned} $$

By de-morgan''s law,

Y = A + B, which is the representation of OR gate.', NULL, 'null', '[]', '[{"id":"q26-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-06-09-shift-3/q26-figure-1.jpg","page":3,"alt":"Figure for question 26"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.514Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3596, 'physics-2023-06-09-shift-3', 'q27', 27, 25, 'Heavy water and _ is one of the substances used as moderator in reactors.', '[{"id":"A","text":"Sea water"},{"id":"B","text":"Titanium"},{"id":"C","text":"Graphite"},{"id":"D","text":"Cobalt"}]', 0, 'C', 'The substance used as moderator and coolant, in nuclear reactors is Heavy water. Heavy water: It is also known as deuterium oxide', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.514Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3597, 'physics-2023-06-09-shift-3', 'q28', 28, 26, 'Diameter of the objective lens of a telescope is 250 cm. For light of wavelength 600 nm, coming from a distant object, the limit of resolution of the telescope is close to:', '[{"id":"A","text":"$ 1.5 \\times 10^{-7} $ rad"},{"id":"B","text":"$ 2 \\times 10^{-7} $ rad"},{"id":"C","text":"$ 3 \\times 10^{-7} $ rad"},{"id":"D","text":"$ 4.5 \\times 10^{-7} $ rad"}]', 0, 'C', 'Limit of resolution $ =\frac{1.22\lambda}{d} $

$ =\frac{1.22 \times 600 \times 10^{-9}}{250 \times 10^{-2}} $

$ =2.9 \times 10^{-7} rad $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3598, 'physics-2023-06-09-shift-3', 'q29', 29, 27, 'A source emits sound of frequency 600 Hz inside water. The frequency heard in air (velocity of sound in water is 1500 m/s and velocity of sound in air is 300 m/s) will be:', '[{"id":"A","text":"300 Hz"},{"id":"B","text":"600 Hz"},{"id":"C","text":"900 Hz"},{"id":"D","text":"1200 Hz"}]', 0, 'B', 'Frequency of the a particular wave remains constant in all medium, but its velocity as well as wavelength vary with medium. Thus the source emits sound of frequency of 600 Hz inside water and in air also.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3599, 'physics-2023-06-09-shift-3', 'q30', 30, 28, 'An electron enters a crossed electrical and magnetic field region with a speed of 100 m s $ ^{-1} $ along + x-axis and passes undeviated. The strength of magnetic field is 5.0 T and it acts along + z-axis. Give the electrical field in vector notations indicating its magnitude as well as direction:', '[{"id":"A","text":"$ (500\\ V\\ m^{-1})j $"},{"id":"B","text":"$ -(500\\ V\\ m^{-1})\\hat{k} $"},{"id":"C","text":"$ (100\\ V\\ m^{-1})j $"},{"id":"D","text":"$ -(100\\ V\\ m^{-1})\\hat{k} $"}]', 0, 'A', 'The fact that the fields are uniform, with the feature that the charge moves in a straight line, implies the speed is constant (if it were not, then the magnetic force would vary while the electric force could not - causing it to deviate from straight-line motion). This is then the situation leading to $ v = \frac{E}{B} $, and we find

$$ |\overrightarrow{E}|=v|\overrightarrow{B}|=500V/m $$

Its direction (so that $ \vec{F} = q(\vec{E} + \vec{v} \times \vec{B}) $ vanishes) is downward, or $ -\hat{j} $, in the "page" coordinates.

In unit-vector notation, $ \vec{E} = -(500 \, \mathrm{V/m})\hat{j} $.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3600, 'physics-2023-06-09-shift-3', 'q31', 31, 29, 'An AC current is given by $ I = i_{1} \cos \omega t + i_{2} \sin \omega t $

The rms current is given by:', '[{"id":"A","text":"$ \\frac{1}{\\sqrt{2}} $ ( $ i_{1} + i_{2} $)"},{"id":"B","text":"$ \\frac{1}{\\sqrt{2}} $ ( $ i_{1} + i_{2} $)^{2}"},{"id":"C","text":"$ \\frac{1}{\\sqrt{2}} $ ( $ i_{1}^{2} + i_{2}^{2} $)^{\\frac{1}{2}}"},{"id":"D","text":"$ \\frac{1}{2} $ ( $ i_{1}^{2} + i_{2}^{2} $)^{\\frac{1}{2}}"}]', 0, 'C', '$$ \begin{aligned}iol.&\\&I=I_{1}\cos\omega t+I_{2}\sin\omega t\\&I=\sqrt{I_{1}^{2}+I_{2}^{2}+I_{1}I_{2}\cos90^{\circ}}\\&I=\sqrt{I_{1}^{2}+I_{2}^{2}}\\&I_{rms}=\frac{I}{\sqrt{2}}\\&I_{rms}=\frac{\sqrt{I_{1}^{2}+I_{2}^{2}}}{\sqrt{2}}\\&=\sqrt{\frac{I_{1}^{2}+I_{2}^{2}}{2}}\end{aligned} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3601, 'physics-2023-06-09-shift-3', 'q32', 32, 30, 'Frequencies in the UHF range normally propagate by means of:', '[{"id":"A","text":"Ground waves"},{"id":"B","text":"Sky waves"},{"id":"C","text":"Surface waves"},{"id":"D","text":"Space waves"}]', 0, 'D', 'Ultra-High Frequency (UHF) range normally propagate by means of Space waves', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3602, 'physics-2023-06-09-shift-3', 'q33', 33, 31, 'Which of the following is not an EM wave?', '[{"id":"A","text":"X-rays"},{"id":"B","text":"Gamma rays"},{"id":"C","text":"Microwaves"},{"id":"D","text":"Cathode rays"}]', 0, 'D', 'Cathode rays are not electromagnetic wave because they do not have electric and magnetic components perpendicular to each other', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.516Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3603, 'physics-2023-06-09-shift-3', 'q34', 34, 32, 'The least distance of distinct vision of a person is 50 cm. He wants to read a book placed at 25 cm. The focal length of the spectacles would be:', '[{"id":"A","text":"+25 cm"},{"id":"B","text":"25 cm"},{"id":"C","text":"+50 cm"},{"id":"D","text":"50 cm"}]', 0, 'C', 'For a normal person, the least distance of distinct vision is 25 cm. But in this problem, the least distance of distinct vision is 50 cm.

We have $ 1/f = 1/v - 1/u $

Here v = -50 cm

$ u = -25 \, cm $

$ 1/f = -1/50 - (-1/25) $

$ 1/f = 1/50 $

Focal length = 50 cm

Hence focal length should be +50 cm i.e. convex lens should be used.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.517Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3604, 'physics-2023-06-09-shift-3', 'q35', 35, 33, 'The current flowing through a wire as a function of time is given as: $ I = 3t^{2} + 2t + 5 $ The charge flowing through any cross-section of the wire in first 2 s is:', '[{"id":"A","text":"5 C"},{"id":"B","text":"17 C"},{"id":"C","text":"16 C"},{"id":"D","text":"22 C"}]', 0, 'D', 'Current through the wire We know that,

$$ \begin{aligned}I&=\frac{\mathrm{d}\boldsymbol{q}}{\mathrm{d}t}\\ \Rightarrow\mathrm{d}\boldsymbol{q}&=\mathrm{Id}t\ldots\ldots1(1)\end{aligned} $$

Integrating the equation (1) with proper limits Time interval: t = os to t = 2 s

$$ \begin{aligned}&\int\quad d q=\int_{0}^{2}I d t\\&I=3t^{2}+2t+5\\&\Rightarrow q=\int_{0}^{2}(3t^{2}+2t+5)d t=[t^{3}+t^{2}+5t]_{0}^{2}\\&\quad=(8+4+10)=22C\end{aligned} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3605, 'physics-2023-06-09-shift-3', 'q36', 36, 34, 'When a ray of light enters a glass slab from air:', '[{"id":"A","text":"its wavelength decreases"},{"id":"B","text":"its wavelength increases"},{"id":"C","text":"its frequency increases"},{"id":"D","text":"neither its wavelength nor its frequency changes"}]', 0, 'A', 'On entering a glass slab the velocity decreases. $v = v\lambda$

Frequency is inherent property of a wave and does not change. So the wavelength decreases which results in reduction in velocity on entering a glass slab from air.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3606, 'physics-2023-06-09-shift-3', 'q37', 37, 35, 'Light of two different frequencies whose photons have energies 1 eV and 2.5 eV respectively, illuminate a metal of work function 0.5 eV. The ratio of the maximum KE of the emitted electrons will be:', '[{"id":"A","text":"1:5"},{"id":"B","text":"1:4"},{"id":"C","text":"1:2"},{"id":"D","text":"1:1"}]', 0, 'B', 'For maximum speed of the photo electrons

$ \frac{1}{2}mv^{2}=E_{photon}-\phi $ where $ \phi=0.5eV $ is the work function of the metal.

Energy of photon $ E_{1}=1eV $

$ \therefore\frac{1}{2}mv_{1}^{2}=1-0.5 $

We get $ \frac{1}{2}mv_{1}^{2}=0.5eV $

Energy of photon $ E_{2}=2.5eV $

$ \therefore\frac{1}{2}mv_{2}^{2}=2.5-0.5 $

We get $ \frac{1}{2}mv_{2}^{2}=2eV $

Ratio of maximum speeds $ \frac{v_{1}^{2}}{v_{2}^{2}}=\frac{0.5}{2}=\frac{1}{4} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3607, 'physics-2023-06-09-shift-3', 'q38', 38, 36, 'The capacities of two capacitors are $C_{1}$ and $C_{2}$ and their respective potentials are $V_{1}$ and $V_{2}$. If they are connected with a wire, then the loss of energy is given by:', '[{"id":"A","text":"$\\frac{C_{1}C_{2}(V_{1}+V_{2})}{2(C_{1}+C_{2})}$"},{"id":"B","text":"$\\frac{C_{1}C_{2}(V_{1}-V_{2})}{2(C_{1}+C_{2})}$"},{"id":"C","text":"$\\frac{C_{1}C_{2}(V_{1}-V_{2})^{2}}{2(C_{1}+C_{2})}$"},{"id":"D","text":"$\\frac{(C_{1}+C_{2})(V_{1}-V_{2})}{C_{1}C_{2}}$"}]', 0, 'C', 'ol. Initial energy $(E_{i})=\frac{1}{2}C_{1}V_{1}^{2}+\frac{1}{2}C_{2}V_{2}^{2}$

Let V be the common potential after connection

By law of conservation of charge total initial charge

= total final charge

$q_{1}+q_{2}=q_{1}^{\prime}+q_{2}^{\prime}$

$C_{1}V_{1}+C_{2}V_{2}=C_{1}V+C_{2}V$

$V=\frac{C_{1}V_{1}+C_{2}V_{2}}{C_{1}+C_{2}}$

Final energy $(E_{f})=\frac{1}{2}(C_{1}+C_{2})V^{2}$

$=\frac{1}{2}(C_{1}+C_{2})\left[\frac{C_{1}V_{1}+C_{2}V_{3}^{2}}{C_{1}+C_{2}}\right]^{2}$

$\Rightarrow$ Energy loss $=E_{i}-E_{f}$

$=\frac{1}{2}C_{1}V_{1}^{2}+\frac{1}{2}C_{2}V_{2}^{2}-\frac{1}{2}(C_{1}+C_{2})\left[\frac{C_{1}V_{1}+C_{2}V_{2}^{2}}{C_{1}+C_{2}}\right]^{2}$

$=\frac{C_{1}C_{2}(V_{1}-V_{2})^{2}}{2(C_{1}+C_{2})}$

Thus, energy loss of capacitors is $ \frac{C_{1}C_{2}(V_{1}-V_{2})^{2}}{2(C_{1}+C_{2})} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3608, 'physics-2023-06-09-shift-3', 'q39', 39, 37, 'We can reduce eddy currents in the core of transformer by:', '[{"id":"A","text":"increasing the number of turns in the secondary coil"},{"id":"B","text":"taking laminated core"},{"id":"C","text":"making step down transformer"},{"id":"D","text":"using a weak AC at high potential"}]', 0, 'B', 'Eddy currents can be reduced by channelizing the current paths in a conductor. To do that, the core is formed by combining several insulated or laminated metal plates.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3609, 'physics-2023-06-09-shift-3', 'q40', 40, 38, 'A piece of copper and another of germanium are cooled from room temperature to 100 K. The resistance of:', '[{"id":"A","text":"copper increases and germanium decreases"},{"id":"B","text":"copper decreases and germanium increases"},{"id":"C","text":"each of them increases"},{"id":"D","text":"each of them decreases"}]', 0, 'B', 'the resistance of a conductor increases with increase in temperature whereas that of semiconductor decreases with increase in temperature. Copper is a very good conductor and germanium is a semiconductor. Thus, resistance of copper decreases but that of germanium increases when they are cooled from room temperature to 100 K', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.518Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3610, 'physics-2023-06-09-shift-3', 'q41', 41, 39, 'Three charges q, -q, q placed at the vertices of an equilateral triangle as shown in figure. What is the magnitude of force on charge placed at position 3 due to the presence of other two charges?', '[{"id":"A","text":"$ \\frac{1}{2\\pi\\varepsilon_{0}}\\frac{q^{2}}{l} $"},{"id":"B","text":"$ \\frac{\\sqrt{3}}{4\\pi\\varepsilon_{0}}\\frac{q^{2}}{l^{2}} $"},{"id":"C","text":"$ \\frac{\\sqrt{5}}{8\\pi\\varepsilon_{0}}\\frac{q}{\\sqrt{l}} $"},{"id":"D","text":"$ \\frac{1}{4\\pi\\varepsilon_{0}}\\frac{q^{2}}{\\sqrt{l}} $"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q41-figure-1","kind":"figure","path":"/local-papers/assets/physics-2023-06-09-shift-3/q41-figure-1.jpg","page":4,"alt":"Figure for question 41"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3611, 'physics-2023-06-09-shift-3', 'q42', 42, 40, 'Which of the following radiations will have maximum penetration power?', '[{"id":"A","text":"X-rays"},{"id":"B","text":"$ \\alpha $-rays"},{"id":"C","text":"$ \\beta $-rays"},{"id":"D","text":"$ \\gamma $-rays"}]', 0, 'D', 'Gamma rays have the shortest wavelengths of all electromagnetic radiation, has the greatest penetrating power.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3612, 'physics-2023-06-09-shift-3', 'q43', 43, 41, 'A hot wire voltmeter measures the voltage across the inductor, the capacitor and the resistor as 150 V, 100 V and 50 V across a series, LCR circuit. If resistance is 100 Ω, the current in the circuit is:', '[{"id":"A","text":"1.5 A"},{"id":"B","text":"1 A"},{"id":"C","text":"0.5 A"},{"id":"D","text":"0.7 A"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3613, 'physics-2023-06-09-shift-3', 'q44', 44, 42, 'Speed of Electromagnetic wave is Not the same:', '[{"id":"A","text":"in all media"},{"id":"B","text":"for all intensities in vacuum"},{"id":"C","text":"for all frequencies in vacuum"},{"id":"D","text":"for all wavelengths in vacuum"}]', 0, 'A', 'The speed of electromagnetic wave in a region is same for all intensities but different for different frequencies.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3614, 'physics-2023-06-09-shift-3', 'q45', 45, 43, 'What uniform magnetic field applied perpendicular to a beam of electrons moving at $ 1.3 \times 10^6 $ m/s, is required to make the electrons travels in a circular arc of radius 0.35 m?', '[{"id":"A","text":"$ 2.1 \\times 10^{-5} $ G"},{"id":"B","text":"$ 6 \\times 10^{-5} $ T"},{"id":"C","text":"$ 2.1 \\times 10^{-5} $ T"},{"id":"D","text":"$ 6 \\times 10^{-5} $ G"}]', 0, 'C', 'From $r = \frac{mv}{qB}$ we find

$B = \frac{m_e v}{er}$

$=\frac{(9.11 \times 10^{-31} \text{ kg})(1.30 \times 10^6 \text{ m/s})}{(1.60 \times 10^{-19} \text{C})(0.350 \text{ m})}$

$=2.11 \times 10^{-5} \text{ T}$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3615, 'physics-2023-06-09-shift-3', 'q46', 46, 44, 'In a double slit experiment, the distance between slits is increased 10 times whereas their distance from screen is halved, then what is the fringe width?', '[{"id":"A","text":"it remains same"},{"id":"B","text":"become $ \\frac{1}{10} $"},{"id":"C","text":"become $ \\frac{1}{20} $"},{"id":"D","text":"become $ \\frac{1}{90} $"}]', 0, 'C', 'Let $ \lambda $ be wavelength of monochromatic light, d the distance between coherent sources, and D the distance between screen and source, then fringe width is

$$ \beta=\frac{D\lambda}{d} $$

$$ \begin{aligned}Given,d_{1}=d,D_{1}&=D,d_{2}=1od,D_{2}=\frac{D}{2}\\&\therefore\beta_{2}=\frac{\frac{D_{2}}{2}\lambda}{1od}=\frac{D\lambda}{20d}\\&\Rightarrow\beta_{2}=\frac{W}{20}\end{aligned} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3616, 'physics-2023-06-09-shift-3', 'q47', 47, 45, 'A tiny spherical oil drop of mass 8 mg is kept suspended by applying a potential difference of 100 V between two metallic plates kept separated by a distance 1 cm. The number of electrons on the oil drop are: (Take $ g = 10 \, \text{ms}^{-2} $)', '[{"id":"A","text":"$ 5 \\times 10^{10} $"},{"id":"B","text":"$ 5 \\times 10^{8} $"},{"id":"C","text":"$ 5 \\times 10^{12} $"},{"id":"D","text":"$ 5 \\times 10^{13} $"}]', 0, 'A', '$$ V=100V $$

$$ \begin{array}{l}V=100\mathrm{~V}\\E=\frac{V}{d}=\frac{100}{1\times10^{-2}}=10000\\mg=qE\\q=\frac{mg}{E}\\\quad ne=q=\frac{mg}{E}\\\quad n=\frac{mg}{eE}\\\mathrm{n}=5\times10^{12}\end{array} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3617, 'physics-2023-06-09-shift-3', 'q48', 48, 46, 'A strong magnetic field is applied on a stationary electron:', '[{"id":"A","text":"The electron moves in the direction of the field"},{"id":"B","text":"The electron moves in an opposite direction"},{"id":"C","text":"The electron remains stationary"},{"id":"D","text":"The electron starts spinning"}]', 0, 'C', 'A strong magnetic field is applied on a stationary electron. Then the electron remains stationary because magnetic force act on moving charge.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3618, 'physics-2023-06-09-shift-3', 'q49', 49, 47, 'The focal length of the objective of a microscope if $ f_{o} $ and that of the eye piece if $ f_{e} $. The aperture of objective is $ d_{o} $ and that of eye piece is $ d_{e} $. Which of the following relation is correct?', '[{"id":"A","text":"$ f_{0} > f_{e}, d_{0} > d_{e} $"},{"id":"B","text":"$ f_{0} < f_{e}, d_{0} < d_{e} $"},{"id":"C","text":"$ f_{0} > f_{e}, d_{0} < d_{e} $"},{"id":"D","text":"$ f_{0} d_{e} $"}]', 0, 'B', '. The focal length of the objective of a microscope if $ f_{0} $ and that of the eye piece if $ f_{e} $. The aperture of objective is $ d_{o} $ and that of eye piece is $ d_{e} $. s the magnifying power of compound microscope is inversely proportional to the focal length of the objective lens. Hence, smaller is the focal length, higher is the magnifying power. Therefore, focal length of objective lens is less than the focal length of eyepiece lens.

$$ f_{o}<f_{e},d_{o}<d_{e} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3619, 'physics-2023-06-09-shift-3', 'q50', 50, 48, 'Time period of oscillation of a bar magnet in a uniform magnetic field is $T_{0}$. The magnet is cut into 3 equal parts transverse to its length. The new time period of oscillation of one part will be:', '[{"id":"A","text":"$T_{0}$"},{"id":"B","text":"$\\frac{T_{0}}{2}$"},{"id":"C","text":"$\\frac{T_{0}}{3}$"},{"id":"D","text":"$\\frac{T_{0}}{4}$"}]', 0, 'C', 'Initially the time period of magnet $T_0 = 2\pi \sqrt{\frac{1}{MB}}$ where I is the moment of inertia of the bar magnet M is the magnetic moment of the bar magnet When the magnet is cut in three equal parts, the magnetic moment of each bar becomes $\frac{M}{3} = M''$. Also the new moment of inertia becomes $I'' = \frac{1}{3^3} = \frac{1}{27}$ Hence, the new time period becomes $T'' = 2\pi \sqrt{\frac{I''}{M''B}} = \frac{T_0}{3}$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.519Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3620, 'biology-2022-08-18', 'q01', 1, 1, 'The protein formed by the encoded gene expression in a heterologous host is called:', '[{"id":"A","text":"Structural protein"},{"id":"B","text":"Recombinant protein"},{"id":"C","text":"Transposone"},{"id":"D","text":"Prohormone"}]', 0, 'B', 'Option (B) is the correct answer as any protein encoding gene is expressed in a heterologous host is called recombinant protein.

Option (A) is incorrect as structural proteins are the most abundant class of proteins in nature and form structural elements.

Option (C) is incorrect as transposons are repetitive DNA sequences that have the capacity to move from one location to another in genome.

Option (D) is incorrect as prohormones are the precursors of hormones', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3621, 'biology-2022-08-18', 'q02', 2, 2, 'A kind of population interaction in which one species benefits and the other is neither harmed nor benefited?', '[{"id":"A","text":"Commensalism"},{"id":"B","text":"Ammensalism"},{"id":"C","text":"Mutualism"},{"id":"D","text":"Parasitism"}]', 0, 'A', 'Commensalism is a type of population interaction where one species benefits and the other remains unaffected. It can also be denoted by (+, 0)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3622, 'biology-2022-08-18', 'q03', 3, 3, 'Fruit which develop only from the ovary are called-', '[{"id":"A","text":"False fruits"},{"id":"B","text":"Parthenocarpic fruits"},{"id":"C","text":"True fruits"},{"id":"D","text":"Apomictic fruits"}]', 0, 'C', 'True fruits are developed only from ovary while in false fruits, parts other than ovary also contributes.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.520Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3623, 'biology-2022-08-18', 'q04', 4, 4, 'Algal blooms do not cause-', '[{"id":"A","text":"Imbalance in ecosystem dynamics"},{"id":"B","text":"Deterioration of the water quality and fish mortality"},{"id":"C","text":"Reduction in BOD"},{"id":"D","text":"Increase in organic matters in water body"}]', 0, 'C', 'Algal blooms are formed by overproduction of algae in nutrient-rich or eutrophicated water-bodies. They can cause harmful effects on aquatic species by increasing organic matter and thus BOD of water body increases too.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3624, 'biology-2022-08-18', 'q05', 5, 5, 'Observe the given figure and name the step used in Recombinant DNA Technology', '[{"id":"A","text":"Selecting"},{"id":"B","text":"Scrolling"},{"id":"C","text":"Spiraling"},{"id":"D","text":"Spooling"}]', 0, 'D', 'Option (D) is the correct answer as the given figure represents the process of spooling which is a method of extraction of substance like DNA in the form of a spool over a glass rod.', NULL, 'null', '[]', '[{"id":"q05-figure-1","kind":"figure","path":"/local-papers/assets/biology-2022-08-18/q05-figure-1.jpg","page":1,"alt":"Figure for question 5"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3625, 'biology-2022-08-18', 'q06', 6, 6, 'Perisperm differs from endosperm is that it is:', '[{"id":"A","text":"Haploid having reserve food"},{"id":"B","text":"Polyploid having reserve food"},{"id":"C","text":"Triploid having no reserve food"},{"id":"D","text":"Diploid having no reserve food"}]', 0, 'D', 'Perisperm is remnant of nucellus and thus is diploid. Endosperm is triploid nutritious tissues. Both endosperm and perisperm store reserve food.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3626, 'biology-2022-08-18', 'q07', 7, 7, 'Identify and name the two parts in a flower which are most important units of sexual reproduction?', '[{"id":"A","text":"1 - Style, 3 - stamen"},{"id":"B","text":"4 - filament, 6 - thalamus"},{"id":"C","text":"3 - Anther, 7 - ovary"},{"id":"D","text":"2 - Stigma, 5 - sepals"}]', 0, 'C', 'In the question, most important units of sexual reproduction are asked which are Anther and ovary.

So correct option is (C).

Ovary', NULL, 'null', '[]', '[{"id":"q07-figure-1","kind":"figure","path":"/local-papers/assets/biology-2022-08-18/q07-figure-1.jpg","page":1,"alt":"Figure for question 7"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3627, 'biology-2022-08-18', 'q08', 8, 8, 'Density of population tells us about-', '[{"id":"A","text":"total number of individuals of a species"},{"id":"B","text":"total area occupied by a species"},{"id":"C","text":"number of individuals present per unit space in a given time"},{"id":"D","text":"population growth in a particular time span"}]', 0, 'C', 'Pollution density generally measured as number of individuals of species present in unit space in a given time.

Percent cover or biomass can also be used for measuring population density', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3628, 'biology-2022-08-18', 'q09', 9, 9, 'Select the hormones produced in women only during pregnancy

A. Estrogen

B. Human chronic gonadotroph

C. Progesterone

D. Human placental lactogen

E. Relaxin', '[{"id":"A","text":"B and D only"},{"id":"B","text":"B and E only"},{"id":"C","text":"A, B and C only"},{"id":"D","text":"B, D and E only"}]', 0, 'D', 'Option (D) is the correct answer as, hCG (human chorionic gonadotropin), hPL (human placental lactogen) and relaxin are produced in humans only during pregnancy.

Estrogen and progesterone are also secreted in a non-', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3629, 'biology-2022-08-18', 'q10', 10, 10, 'Which of the following is not an example of terrestrial ecosystem?', '[{"id":"A","text":"Wetland"},{"id":"B","text":"Grassland"},{"id":"C","text":"Forest"},{"id":"D","text":"Desert"}]', 0, 'A', 'Wetland is an aquatic ecosystem. Rest all are examples of terrestrial ecosystems.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3630, 'biology-2022-08-18', 'q11', 11, 11, 'Transfer of an ovum collected from a donor into fallopian tube is called $ \underline{\text{}} $ method.', '[{"id":"A","text":"ZIFT"},{"id":"B","text":"ICST"},{"id":"C","text":"GIFT"},{"id":"D","text":"IVF"}]', 0, 'C', 'Option (C) is the correct answer as:

GIFT is the method of transfer of ovum collected from a donor into the fallopian tube of another female who cannot produce one, but can provide suitable environment for fertilisation.

Option (A) is not the correct answer as ZIFT stands for the transfer of zygote (upto 8 blastomeres) into the fallopian tube.

Option (B) is not the correct answer as ICSI is the method of injecting the sperms directly into the ovum in-vitro.

Option (D) is not the answer as IVF stands for in-vitro fertilisation.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3631, 'biology-2022-08-18', 'q12', 12, 12, 'Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.

Assertion (A): Leydig cells synthesise and secrete male testicular hormones called androgens.

Reason (R): Androgens, stimulate the process of spermatogenesis.

In the light of the above statements, choose the most appropriate answer from the options given below:', '[{"id":"A","text":"Both A and R are correct and R is the correct explanation of A"},{"id":"B","text":"Both A and R are correct are R is NOT the correct explanation of A"},{"id":"C","text":"A is correct but R is not correct"},{"id":"D","text":"A is not correct but R is correct"}]', 0, 'A', 'Option (A) is the correct answer as at the age of puberty due to significant increase in the secretion of gonadotropin releasing hormone there is an increase in the secretion of gonadotropins i.e., LH and FSH. LH acts on the Leydig cells and stimulates synthesis and secretion of androgens.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3632, 'biology-2022-08-18', 'q13', 13, 13, 'The inactive protoxin gets converted into an active form due to the _', '[{"id":"A","text":"Alkaline pH of insect''s gut"},{"id":"B","text":"Temperature and acidic pH of gut"},{"id":"C","text":"Exposure to light"},{"id":"D","text":"Exposure to light and acidic pH of gut"}]', 0, 'A', 'Option (A) is the answer as the Bt toxin protein exist as inactive protoxins but once an insect ingests the inactive toxin, it is converted into an active form of toxin due to alkaline pH of the gut which solubilise the crystals.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.521Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3633, 'biology-2022-08-18', 'q14', 14, 14, 'Which of the following gets embedded in the endometrium during implantation?', '[{"id":"A","text":"Zygote"},{"id":"B","text":"Morula"},{"id":"C","text":"Blastocyst"},{"id":"D","text":"Embryo"}]', 0, 'C', 'Option (C) is the answer as the blastocyst gets embedded in the endometrium of the uterus.

Option (A) is not the answer as zygote is single-celled and it divides mitotically to develop into morula (8-16 celled).

Option (B) is not the answer as morula continues to divide and transforms into blastocyst.

Option (D) is not the answer as embryo with 8 blastomeres is called morula.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3634, 'biology-2022-08-18', 'q15', 15, 15, 'Introduction of which one of the following organism''s species did cause decline or extinction of indigenous species?', '[{"id":"A","text":"Eicchornia Crassipes"},{"id":"B","text":"Nile Perch"},{"id":"C","text":"Clarias gariepinus"},{"id":"D","text":"Steller''s Sea cow"}]', 0, 'D', 'The correct option given by NTA is option (D) but as per NCERT it should be option (B).

The Nile perch introduced into Lake Victoria led eventually to the extinction of ecologically unique assemblage of more than 200 species of cichlid fish in the lake.

Clarias gariepinus, African catfish pose threat to the indigenous catfish in our rivers.

Eicchornia cause environmental damage and pose threat to our native species.

Stellar''s sea cow got extinct due to overexploitation by humans.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3635, 'biology-2022-08-18', 'q16', 16, 16, 'Match List I with List II

A. Progestasert I. once a week pill

B. Saheli II. hormone releasing IUD

C. Lippe''s Loop III. Non-medicated IUD

D. Periodic IV. Natural method of birth abstinence control', '[{"id":"A","text":"A - II, B - III, C - I, D - IV"},{"id":"B","text":"A - I, B - II, C - IV, D - III"},{"id":"C","text":"A - II, B - I, C - III, D - IV"},{"id":"D","text":"A - II, B - IV, C - I, D - III"}]', 0, 'C', 'Option (C) is correct answer because

Progestasert is a hormone-releasing IUD.

Saheli is a ''once a week'' pill.

Lippe''s loop is a non-medicated IUD.

Periodic abstinence or rhythm method is a natural method of contraception in which couples abstain sexual intercourse from day 10 to 17 of a 28 days menstrual cycle.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3636, 'biology-2022-08-18', 'q17', 17, 17, 'The vital link that ensures continuity of species between organisms of one generation and the next generation is', '[{"id":"A","text":"Male gamete"},{"id":"B","text":"Female gamete"},{"id":"C","text":"Zygote"},{"id":"D","text":"Syngamy"}]', 0, 'C', 'The vital link that ensures continuity of species between organisms of one generation and the next generation is the zygote.

The process of fusion of gamete is called syngamy and it results in formation of diploid zygote.

Gametes are reproductive cells of a sexually reproducing organisms.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3637, 'biology-2022-08-18', 'q18', 18, 18, 'In case of COVID positive patients, presence of corona virus is suspected only when the pathogen has produced a disease symptom. But when the symptoms of the disease has not appeared, the corona virus in the body can be detected by-', '[{"id":"A","text":"Enzyme linked immuno-sorbent Assay (ELISA) only"},{"id":"B","text":"Recombinant DNA technology only"},{"id":"C","text":"Reverse transcriptase Polymerase Chain Reaction (RT-PCR)"},{"id":"D","text":"Widal Test"}]', 0, 'C', 'Option (C) is the correct answer because in K1-PCR, RNA of retrovirus is reverse transcripted with the help of enzyme reverse transcriptase. DNA formed is amplified with the help of PCR. So a minute quantity of corona virus can be detected with the help of RT-PCR. ELISA is based on antigen - antibody reaction. Widal test is a diagnostic test', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3638, 'biology-2022-08-18', 'q19', 19, 19, 'Bacillus thuringiensis is a biocontrol agent against', '[{"id":"A","text":"Nematode"},{"id":"B","text":"Fungal pathogen"},{"id":"C","text":"Insect pests"},{"id":"D","text":"Bacterial pathogen"}]', 0, 'C', 'Bacillus thuringiensis is a biocontrol agent against insect pests.

It is introduced in the field crop in order to control butterfly caterpillars (larva)', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3639, 'biology-2022-08-18', 'q20', 20, 20, 'Arrange the following events in the female reproductive cycle in their natural sequence.

A. Ovulation

B. Growth of corpus luteum

C. Sudden increase in level of LH

D. Secretion of FSH

E. Growth of ovarian follicle and oogenesis', '[{"id":"A","text":"E-D-A-B-C"},{"id":"B","text":"D-E-C-A-B"},{"id":"C","text":"E-C-A-D-B"},{"id":"D","text":"D-A-C-E-B"}]', 0, 'B', 'Option (B) is the correct answer because the correct sequence of the events in the female reproductive cycle is:

D - Secretion of FSH

E - FSH leads to the growth of ovarian follicles into a fully mature Graafian follicle

C - During the mid of menstrual cycle, there is sudden increase in the level of LH (LH surge)

A - LH surge leads to ovulation

B - It is followed by luteal phase in which the remaining parts of the Graafian follicle transform as the corpus luteum.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3640, 'biology-2022-08-18', 'q21', 21, 21, 'Which of the following methods are commonly used in DNA fingerprinting?', '[{"id":"A","text":"Genetic transformation"},{"id":"B","text":"PCR and RFLP"},{"id":"C","text":"Bioprospecting"},{"id":"D","text":"Molecular diagnosis"}]', 0, 'B', 'PCR and RFLP are used in DNA fingerprinting to increase the sensitivity of the technique. Bioprospecting is defined as exploring molecular, genetic and species level diversity for products of economic importance. Molecular diagnosis is referred to as detection of genomic variant.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.522Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3641, 'biology-2022-08-18', 'q22', 22, 22, 'Which layer of microsporangium is nutritive in function?

(a) Epidermis (b) Endothecium

(c) Middle Layers (d) Tapetum

3. Match List I with List II

A. Catalytic converter

B. Incinerators

C. Electrostatic precipitator

D. Sewage treatment plant

LIST I

I. Particulate matter

II. Organic waste

III. Hospital Waste

IV. Carbon monoxide and nitrogen oxides', '[{"id":"A","text":"A - III, B - II, C - IV, D - I"},{"id":"B","text":"A - IV, B - III, C - I, D - II"},{"id":"C","text":"A - II, B - III, C - I, D - IV"},{"id":"D","text":"A - I, B - II, C - IV, D - III"}]', 0, 'D', 'Tapetum is innermost wall layer of microsporangium and it provides nourishment to developing pollen grains, Outer three wall layers, epidermis, endothecium and middle layers perform the function of protection and help in dehiscence of anther to release pollen.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3642, 'biology-2022-08-18', 'q24', 24, 23, 'During gene therapy, which vector is used to introduce functional ADA cDNA into lymphocyte', '[{"id":"A","text":"Plasmid"},{"id":"B","text":"Bacteriophage"},{"id":"C","text":"pBR322"},{"id":"D","text":"Retrovirus"}]', 0, 'D', 'Option (D) is correct answer because disarmed retrovirus is used as a vector to introduce functional ADA cDNA into the lymphocytes, which are subsequently returned to the patient.

Plasmids are extra chromosomal double stranded circular DNA present in most of the bacteria. Bacteriophages are viruses which infect bacteria. pBR322 is a plasmid vector of E. coli.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3643, 'biology-2022-08-18', 'q25', 25, 24, 'The animals that feed on herbivores like insects, birds and mammals in terrestrial ecosystem, are called _(a) Saprotrophs

(b) Primary consumers

(c) Secondary carnivores

(d) Primary carnivores

(d) Primary canivores

26 Recombinant Proteins are expressed in', '[{"id":"A","text":"Cloning vector"},{"id":"B","text":"Heterology Host"},{"id":"C","text":"Homologous chromosomes"},{"id":"D","text":"Promotor"}]', 0, 'D', 'The animals that feed on herbivores are called primary carnivores. These are also called secondary consumers. Herbivores are primary consumers.

Secondary carnivores feed on primary carnivores.

Saprotrophs are decomposers. They act over the dead organic matter.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3644, 'biology-2022-08-18', 'q27', 27, 25, 'The chemical carcinogens present in tobacco smoke is the major cause of', '[{"id":"A","text":"AIDS"},{"id":"B","text":"Lung Cancer"},{"id":"C","text":"Allergy"},{"id":"D","text":"Pneumonia"}]', 0, 'B', 'Option (B) is the correct answer as the chemical carcinogens present in tobacco smoke have been identified as a major cause of lung cancer.

Option (A) is not the answer as AIDS is caused by HIV. It is a sexually transmitted disease.

Option (C) is not the answer as allergy is defined as the exaggerated response of the immune system towards certain antigens present in the environment.

Option (D) is not the answer pneumonia is a bacterial disease of respiratory tract.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.523Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3645, 'biology-2022-08-18', 'q28', 28, 26, 'Match the features that are required to facilitate cloning of alien DNA into a vector

List I List II

(Features to facilitate) (Cloning Vector)

A. Origin of replication I. Agrobacterium (ori)

B. Selectable Marker II. Recognition site

C. Cloning sites III. Helps in identifying non-transformants

D. Vectors for cloning IV. Sequence from genes in plants', '[{"id":"A","text":"A-IV, B-III, C-II, D-I"},{"id":"B","text":"A-I, B-II, C-III, D-IV"},{"id":"C","text":"A-II, B-III, C-IV, D-I"},{"id":"D","text":"A-III, B-I, C-II, D-IV"}]', 0, 'A', 'Option (A) is the correct answer because

Origin of the replication (ori) is the sequence from where the replication starts.

Selectable markers in vector help in identifying and eliminating non-transformants and selectively permitting the growth of the transformants.

Cloning sites are the recognition sites commonly used for restriction enzymes.

Agrobacterium tumefaciens is used as a cloning vector for plants. It is called as natural genetic engineer of plants.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3646, 'biology-2022-08-18', 'q29', 29, 27, 'Which of the following is effect of steroid in males?', '[{"id":"A","text":"Premature baldness"},{"id":"B","text":"Deepening of voice"},{"id":"C","text":"Excessive hair growth on face and body"},{"id":"D","text":"Enlargement of clitoris"}]', 0, 'A', 'Option (A) is the correct answer because the side effects of the use of anabolic steroids in males include premature baldness, increased aggressiveness, breast enlargement, etc.

The side-effects of the use of anabolic steroids in females include masculinisation, deepening of voice, excessive hair growth on face and body, enlargement of clitoris and abnormal menstrual cycles.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3647, 'biology-2022-08-18', 'q30', 30, 28, 'Which of the following cells produce antibodies?', '[{"id":"A","text":"Monocytes"},{"id":"B","text":"PMNL neutrophils"},{"id":"C","text":"T-lymphocytes"},{"id":"D","text":"B-lymphocytes"}]', 0, 'D', 'Option (D) is the correct answer because the B-lymphocytes produce an army of proteins in response to pathogens into our blood to fight with them. These proteins are called antibodies.

The T-cells themselves do not secrete antibodies but help B cells to produce them.

Neutrophils and monocytes are phagocytic cells included under cellular barriers of innate immunity.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3648, 'biology-2022-08-18', 'q31', 31, 29, 'Nutrient cycles are of two types:', '[{"id":"A","text":"Gaseous and solid"},{"id":"B","text":"Liquid and sedimentary"},{"id":"C","text":"Gaseous and sedimentary"},{"id":"D","text":"Aquatic and Gaseous"}]', 0, 'C', 'Nutrient cycles are of two types:

(i) Gaseous cycle - Biogeochemical is non-mineral. Exchange of nutrients occur in gaseous or vapour form. Reservoir pool is atmosphere or hydrosphere.

e.g. Nitrogen, Carbon, Oxygen and Hydrogen cycle.

(ii) Sedimentary cycle - Biogeochemical is mineral. Reservoir pool is earth''s crust or lithosphere. e.g. Sulphur and Phosphorus cycle.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.524Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3649, 'biology-2022-08-18', 'q32', 32, 30, 'Technology of biogas production in India was developed due to the efforts of

A. GEAC B. ICAR C. IARI D. IRRI E. KVIC', '[{"id":"A","text":"A and B only"},{"id":"B","text":"C and D only"},{"id":"C","text":"B and D only"},{"id":"D","text":"C and E only"}]', 0, 'D', 'The technology of biogas production was developed in India mainly due to the efforts of Indian Agricultural Research Institute (IARI) and Khadi and Village Industries Commission (KVIC).', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3650, 'biology-2022-08-18', 'q33', 33, 31, 'The bacterium responsible for breakdown of cellulose in a biogas plant is', '[{"id":"A","text":"Acetobacter aceti"},{"id":"B","text":"Lactobacillus"},{"id":"C","text":"Clostridium"},{"id":"D","text":"Methanobacterium"}]', 0, 'D', 'Certain bacteria, which grow anaerobically on cellulosic material, produce large amount of methane along with CO₂ and H₂. These bacteria are collectively called Methanogens, and one such common bacterium is Methanobacterium.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3651, 'biology-2022-08-18', 'q34', 34, 32, 'With reference to processing of hn RNA, which of the following statements is/are INCORRECT?

A. Introns are removed and exons are joined directly splicing.

B. Capping and Tailing occurs at 5'' end and 3'' end respectively.

C. Addition of 200-300 adenylated residues means capping.

D. Addition of guanosine triphosphate takes place at 5'' end.

E. Processing take place in the nucleus and converts hn RNA into functional RNA.

Choose the correct answer from the options given below

(a) B only (b) C only

(c) B and C only (d) B and D only

Match List I with List II.

List I List II

(Name of scientists) (Discovery)

A. Alec Jeffreys I. Lac Operon

B. Francois Jacob II. Deciphering of genetic and Jac-que Monod

C. Marshall Nirenberg III. Semiconservative replication of DNA

D. Meselson Stahl IV. DNA Fingerprint', '[{"id":"A","text":"A-IV, B-I, C-II, D-III"},{"id":"B","text":"A-I, B-III, C-IV, D-II"},{"id":"C","text":"A-II, B-III, C-I, D-IV"},{"id":"D","text":"A-IV, B-II, C-III, D-I"}]', 0, 'B', 'During processing of hn RNA,

(i) Splicing occurs which is removal of introns and joining of exons in a defined order.

(ii) Methyl guanosine triphosphate is added at 5'' end of hn RNA. This is called capping.

(iii) Tailing occurs by the addition of adenylate residues of about 200 - 300 at 3'' end of hn RNA.

(iv) The fully processed hn RNA is called mRNA and it is transported out of the nucleus for translation.

The technique of DNA fingerprinting was developed by Alec Jeffreys.

Jacob and Monod proposed the model of gene regulation, known as Operon model, in bacteria.

Nirenberg and Matthaei used a synthetic poly U RNA and deciphered the genetic code by translating this as polyphenylalanine.

• Meselson and Stahl proved the semi-conservative model of DNA replication in E. coli', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3652, 'biology-2022-08-18', 'q36', 36, 33, 'The pyramid of biomass in sea is generally inverted because:', '[{"id":"A","text":"Sunlight is filtered through sea water leading to less photosynthesis"},{"id":"B","text":"Of the high salt content of sea water"},{"id":"C","text":"The biomass of phytoplankton far exceeds that of fishes"},{"id":"D","text":"The biomass of fishes far exceeds that of phytoplankton"}]', 0, 'D', 'In sea ecosystem, pyramid of biomass is generally inverted, because the biomass of fishes far exceeds the biomass of producers (phytoplanktons) and primary consumers (zooplanktons), due to their large size and longer life span.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3653, 'biology-2022-08-18', 'q37', 37, 34, 'One of the following is NOT a characteristic/criteria of genetic materials, identify it:', '[{"id":"A","text":"Genetic material should be able to generate its replica"},{"id":"B","text":"Genetic material should be stable chemically and structurally"},{"id":"C","text":"It should not provide the scope for mutations"},{"id":"D","text":"It should be able to express itself in the form of Mendelian characters."}]', 0, 'C', 'A molecule that can act as genetic material must fulfil the following criteria:

(i) It should be chemically and structurally stable.

(ii) It should be able to generate its replica

(iii) It should provide scope for slow mutation that are required for evolution.

(iv) It should be able to express itself in the form of Mendelian characters.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.525Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3654, 'biology-2022-08-18', 'q38', 38, 35, 'Adenine pairs with Thymine through how many hydrogens bonds?', '[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"5"}]', 0, 'A', 'Adenine forms two hydrogen bonds with thymine from opposite strand in a DNA molecule.

Similarly, guanine is bonded with cytosine with three hydrogen bonds.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3655, 'biology-2022-08-18', 'q39', 39, 36, 'A pure breeding garden pea plant was crossed with a pure dwarf plant. The plant produced 400 seeds.

The seeds were sown to produce plants. The phenotype of the plants in next generation will be', '[{"id":"A","text":"All tall"},{"id":"B","text":"All dwarf"},{"id":"C","text":"300 tall and 100 dwarf plants"},{"id":"D","text":"All plants of intermediate height"}]', 0, 'A', 'Tallness and dwarfness in pea plants are dominant and recessive traits respectively. The cross can be represented as follows:', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3656, 'biology-2022-08-18', 'q40', 40, 37, 'If in a pond there were 150 carps found last year and through reproduction 450 new carps are added in the pond, what will be the birth rate here?', '[{"id":"A","text":"4 offsprings per carp per year"},{"id":"B","text":"3 offsprings per carp per year"},{"id":"C","text":"2 offsprings per carp per year"},{"id":"D","text":"1 offspring per carp per year"}]', 0, 'B', 'Given: -

Number of individuals last year (N) = 150

Number of individuals added in one year ( $ \Delta N $) = 450

Time period ( $ \Delta T $) = 1 year

$$ Birth rate=\frac{\Delta N}{N\Delta t}=\frac{450}{150\times1} $$

= 3 offsprings per carp per year', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3657, 'biology-2022-08-18', 'q41', 41, 38, 'When the life appear on the earth after its formation?', '[{"id":"A","text":"After 200 million years"},{"id":"B","text":"After 300 million years"},{"id":"C","text":"After 500 million years"},{"id":"D","text":"After 250 million years"}]', 0, 'C', 'Option (C) is the correct answer because life appeared 500 million years after the formation of earth, i.e., almost four billion years ago.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3658, 'biology-2022-08-18', 'q42', 42, 39, 'According to the early Greek thinkers, the unit of life which were transferred to different planets were-', '[{"id":"A","text":"Spores"},{"id":"B","text":"Water"},{"id":"C","text":"Oxygen"},{"id":"D","text":"Methane"}]', 0, 'A', 'Option (A) is the correct answer because according to the early Greek thinkers, the unit of life called spores were transformed to different planets including earth. It is still a favourite idea of some astronomers.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.526Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3659, 'biology-2022-08-18', 'q43', 43, 40, 'Louis Pasteur by careful experimentation demonstrated that life comes from', '[{"id":"A","text":"Killed yeast"},{"id":"B","text":"Rotting matter"},{"id":"C","text":"Other plants"},{"id":"D","text":"Pre-existing life"}]', 0, 'D', 'Option (D) is the correct answer because Louis Pasteur by careful experimentation demonstrated that life comes from pre-existing life.

Theory of spontaneous generation stated that living organisms arise from decaying and rotting matter. This was experimentally disproved by Louis Pasteur.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3660, 'biology-2022-08-18', 'q44', 44, 41, 'Oparin and Haldane proposed the theory that the first form of life could have come from-', '[{"id":"A","text":"Non-living organic molecules"},{"id":"B","text":"Inorganic molecules"},{"id":"C","text":"UV rays"},{"id":"D","text":"CO₂ and water ang terpanid sa ng bode belfoo - signa si stogys sa wawa sdi ion si (A) ninoQ al-2) sirom oni qolavb of yllaoimim asdivib si bus (boliso ot zouninoo slnon as towens sdi jon zi (B) ninoQ Jeyozald oni zmlonat bas shibib azimozald 8 tiw ocido sa towens sdi ton zi (C) ninoQ alunom bello si tud (C) notigo ai ATN yd nving noigo toqno sdf (*D) (B) notigo od bloride li TREK toq as bol anobiV sdi j oini boonboni dong sdi oT supim yllooqeloo to notonizs sdi or yllamovo ni deft biloro to asiceg 00 sadi snon to egaldmsas sdi o iamit soog deitio mothlA, mniqing nima mvin wo ni deftno zongigbit tassit soog bas syamab inomnoinvo sao nindod3 zeicoo avilam wo o yd noishioqzeovo ot sub toniz tog woo as a s''llol2 ammod sanood towans loonoo si (C) ninoQ (3) GUL gniassler-snommod a si hoaaogor Jliq ''jow a somo'' a si ilode2 GUL balsibom-non a si qool s''qqp.1 leunun a si bodism ndivgh to cononteda cibors touxes nida soqoo doifw ni noqpoomoo to bothom launozam xyb 3 a to 11 or 01 yeb mof emoo"}]', 0, 'A', 'Option (A) is the correct answer because Oparin and Haldane proposed that the first forms of life could have come from pre-existing non-living molecules (e.g. RNA, protein etc.) and that formation of life was preceded by chemical evolution.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3661, 'biology-2022-08-18', 'q45', 45, 42, 'The theory of Chemical evolution was studied and tested in laboratory by-', '[{"id":"A","text":"Charles Darwin"},{"id":"B","text":"S.L. Miller"},{"id":"C","text":"Louis Pasteur"},{"id":"D","text":"Haldane"}]', 0, 'B', 'Option (B) is the correct answer because based on the hypothesis proposed by Oparin and Haldane, S.L. Miller provided an experimental evidence of the chemical evolution in 1953 in a laboratory set-up. Louis Pasteur dismissed the theory of spontaneous generation once and for all.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3662, 'biology-2022-08-18', 'q46', 46, 43, 'The explant used in tissue culture must show _', '[{"id":"A","text":"Encystation"},{"id":"B","text":"Sporulation"},{"id":"C","text":"Dioecy"},{"id":"D","text":"Totipotency"}]', 0, 'D', 'The capacity to generate a whole plant from any cell/explant is called totipotency.

Therefore, the explant used in tissue culture must show totipotency.

Formation of cyst in unfavourable conditions by unicellular organisms is called encystation.

Sporulation is the production of spores by the organisms such as fungi.

Having male and female sex organs in different individuals is called dioecy.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3663, 'biology-2022-08-18', 'q47', 47, 44, 'Virus free plants of banana are developed by using', '[{"id":"A","text":"Protoplasts"},{"id":"B","text":"Meristem"},{"id":"C","text":"Cotyledon"},{"id":"D","text":"Leaf"}]', 0, 'B', 'Pathogen free clones of plants can be obtained through meristem culture because meristem is free of virus due to high concentration of auxins and rapid rate of cell division.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3664, 'biology-2022-08-18', 'q48', 48, 45, 'Pomato is developed by _ technique.', '[{"id":"A","text":"Micropropagation"},{"id":"B","text":"Mutation breeding"},{"id":"C","text":"Biofortification"},{"id":"D","text":"Somatic hybridization"}]', 0, 'D', 'Pomato was developed by somatic hybridization (protoplast fusion) of two different genera tomato and potato. It is intergeneric somatic hybrid. The method of producing thousands of plants through tissue culture is called micropropagation.

Biofortification is breeding of crops for higher level of nutrients.

Mutation breeding can make crops resistant against diseases.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.527Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3665, 'biology-2022-08-18', 'q49', 49, 46, 'In tissue culture, the nutrient medium usually contains _ as a carbon source.', '[{"id":"A","text":"Sucrose"},{"id":"B","text":"Maltose"},{"id":"C","text":"Carbon dioxide"},{"id":"D","text":"Calcium carbonate"}]', 0, 'A', 'In tissue culture, the nutrient medium usually contains sucrose as carbon source.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.528Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
