INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3686, 'biology-2022-08-20', 'q20', 20, 20, 'Identify the step involved in polymerase chain reaction from the given figure below.', '[{"id":"A","text":"Primer extension"},{"id":"B","text":"Denaturation"},{"id":"C","text":"Extension"},{"id":"D","text":"Annealing"}]', 0, 'D', 'This step is annealing allows the primers to connect to a specific spot on the single-stranded template DNA.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3687, 'biology-2022-08-20', 'q21', 21, 21, '''Rivet popper'' hypothesis was proposed by', '[{"id":"A","text":"Alexander Von Humboldt"},{"id":"B","text":"Paul Ehrlich"},{"id":"C","text":"Edward Wilson"},{"id":"D","text":"Robert May"}]', 0, 'B', 'The Rivet Popper Hypothesis was proposed by Paul Ehrlich. The hypothesis suggests the importance of species richness in the maintenance of the ecosystem.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3688, 'biology-2022-08-20', 'q22', 22, 22, 'Which of the following genes control corn borer disease?', '[{"id":"A","text":"amp $ ^{R} $"},{"id":"B","text":"cry I Ac"},{"id":"C","text":"cry / Ab"},{"id":"D","text":"cry II Ab"}]', 0, 'C', 'The proteins encoded by the genes cryIAc and cryIIAb control the cotton bollworms, that of cryIAb controls corn borer.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.535Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3689, 'biology-2022-08-20', 'q23', 23, 23, 'The rate of decomposition in a particular climatic condition is quicker, if detritus is rich in _ & _', '[{"id":"A","text":"Sugars, Phosphorus"},{"id":"B","text":"Lignin, Phosphorous"},{"id":"C","text":"Sugars, Nitrogen"},{"id":"D","text":"Lignin, Chitin"}]', 0, 'C', 'The rate of decomposition is controlled by chemical composition of detritus and climatic factors. In a particular climatic condition, decomposition rate is slower if detritus is rich in lignin and chitin, and quicker, if detritus is rich in nitrogen and water-soluble substances like sugars. Temperature and soil moisture are the most important climatic factors that regulate decomposition through their effects on the activities of soil microbes. Hence, option C is correct.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3690, 'biology-2022-08-20', 'q24', 24, 24, 'Which of the following is a natural method of birth control?', '[{"id":"A","text":"Condoms"},{"id":"B","text":"Lactational amenorrhea"},{"id":"C","text":"IUD"},{"id":"D","text":"Diaphragms"}]', 0, 'D', 'Lactational amenorrhoea is the method of natural contraception which is based on the fact that the ovulation and therefore the menstrual cycle do not occur during the period of intense lactation following parturition. Hence, option B is correct.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3691, 'biology-2022-08-20', 'q25', 25, 25, 'The Graafian follicle ruptures to release the ovum from the ovary by the process called', '[{"id":"A","text":"Ovulation"},{"id":"B","text":"Menstruation"},{"id":"C","text":"Implantation"},{"id":"D","text":"Copulation"}]', 0, 'A', 'Graafian follicles rupture to release the secondary oocyte and this process is called ovulation. The secondary oocyte completes meiosis II to form ovumi and a second polar body during fertilisation.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3692, 'biology-2022-08-20', 'q26', 26, 26, 'Match List-I with List-II', '[{"id":"A","text":"A-III, B-I, C-II, D-IV"},{"id":"B","text":"A-IV, B-III, C-I, D-II"},{"id":"C","text":"A-IV, B-I, C-III, D-II"},{"id":"D","text":"A-IV, B-II, C-III, D-I"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q26-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-20/q26-table-1.jpg","page":2,"alt":"Table for question 26"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.536Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3693, 'biology-2022-08-20', 'q27', 27, 27, 'Select the statement that are correct for GM plants with genetic modifications.

A. Made crops tolerant to abiotic stresses

B. Increased the reliance on chemical pesticides

C. Helped to reduce post-harvest losses

D. Decrease efficiency of mineral usage by plants

E. Enhanced nutritional value of food', '[{"id":"A","text":"C and E only"},{"id":"B","text":"B and C only"},{"id":"C","text":"A, C and E only"},{"id":"D","text":"C, D and E only"}]', 0, 'C', 'Genetic modification has:

(i) Made crops more tolerant to abiotic stress (cold, drought, salt, heat.)

(ii) Reduced reliance on chemical pesticides (pest-resistant crops).

(iii) Helped to reduce on post-harvest losses.

(iv) Increased efficiency of mineral usage by plants (this prevents early exhaustion of fertility of soil).

(v) Enhanced nutritional value of food, e.g., Vitamin ''A'' enriched rice.

In addition to these uses, GM has been used to create tailor-made plants to supply alternative resources to industries, in the form of starch, fuel, and pharmaceuticals.

28. (b, c) A parent with A blood group can have two possible genotypes, "IA IA" and "IA IO"; similarly parent with B blood group can have two possible genotypes, "IB IB" and "IB IO". Thus, they have three alleles, "IA", "IB" and "IO" which can make total six genotypes: IA IA, IA IO, IB IB, IB IO, IA IB and IOIO. Since, IA and IB alleles are dominant over IO allele; the genotypes IA IO and IB IO give A and B blood group respectively. Genotypes IA IA, IB IB, IO IO show A, B and O blood groups respectively. Due to codominance of "IA" and "IB" alleles, the genotype "IAIB" produce "AB" blood group respectively.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.536Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3694, 'biology-2022-08-20', 'q29', 28, 28, 'The embryo with 8 to 16 blastomeres is called _', '[{"id":"A","text":"Morula"},{"id":"B","text":"Blastula"},{"id":"C","text":"Zygote"},{"id":"D","text":"Foetus"}]', 0, 'A', 'Blastula is the hollow sphere of blastomeres, produced due to repeated cleavage. zygote is single celled structure formed due to fusion of male and female gametes. Foetus is the unborn offspring.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3695, 'biology-2022-08-20', 'q30', 29, 29, 'The species that invades a bare area is called _', '[{"id":"A","text":"Serial stage"},{"id":"B","text":"Allien species"},{"id":"C","text":"Endemic species"},{"id":"D","text":"Pioneer species"}]', 0, 'D', 'Pioneer species are the first species to populate a barren or devastated environment. E.g. a volcanic eruption burns an island clean of life, or causes a new island consisting of bare volcanic rock to emerge.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3696, 'biology-2022-08-20', 'q31', 30, 30, 'Mr. X wants to start Bee-keeping. Important points for successful bee-keeping are _.

A. Selection of suitable location for keeping beehives

B. Beehives can be kept in fruit orchards

C. Catching and hiving of swarms

D. Management of beehives during rainy season

E. Regular visit by veterinary doctor is mandatory', '[{"id":"A","text":"A, B, C and E"},{"id":"B","text":"A, B and C"},{"id":"C","text":"A, B, D and E"},{"id":"D","text":"A, C, D and E"}]', 0, 'B', 'Successful bee-keeping requirements are as follows:

(i) Knowledge of the nature and habits of bees,

(ii) Selection of suitable location for keeping the beehives

(iii) Catching and hiving of swarms

(iv) Management of beehives during different seasons, and

(v) Handling and collection of honey and of beeswax.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3697, 'biology-2022-08-20', 'q32', 31, 31, 'Given below are two statements; one is labelled as assertion A and other is labelled as Reason R

Assertion (A): In gel-electrophoresis, DNA fragments are separated.

Reason (R): DNA is negatively charged, so it moves towards the cathode under the influence of electric field.

In the light of the above sentences, choose the correct answer from the options given below', '[{"id":"A","text":"Both A and R are true and R is the correct explanation of A"},{"id":"B","text":"Both A and R are true and R is not the correct explanation of A"},{"id":"C","text":"A is true but R is false"},{"id":"D","text":"A is false but R is true"}]', 0, 'C', 'In this question, assertion is correct but reason is not correct. DNA is a negatively charged molecule, hence it moves towards the positive electrode (anode).

The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3698, 'biology-2022-08-20', 'q33', 32, 32, 'Identify the drug shown below in the diagram', '[{"id":"A","text":"Cocaine"},{"id":"B","text":"Heroin"},{"id":"C","text":"Cannabinoid"},{"id":"D","text":"Morphine"}]', 0, 'D', 'The given structure is of morphine.

Morphine belongs to a class of drugs known as opioid analgesics.', NULL, 'null', '[]', '[{"id":"q33-figure-1","kind":"figure","path":"/local-papers/assets/biology-2022-08-20/q33-figure-1.jpg","page":3,"alt":"Figure for question 33"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3699, 'biology-2022-08-20', 'q34', 33, 33, 'Which of the following does not show ecological diversity?', '[{"id":"A","text":"Coral reef"},{"id":"B","text":"Alpine meadows"},{"id":"C","text":"Wetlands"},{"id":"D","text":"Rauwolfia vomitoria"}]', 0, 'D', 'Coral reef, alpine meadows, deserts, wetlands, mangrove etc., are examples of ecological diversity whereas Rauwolfia vomitoria shows genetic diversity. Hence, option d is not correct.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3700, 'biology-2022-08-20', 'q35', 34, 34, 'Match List I with List II', '[{"id":"A","text":"A-1, B-III, C-IV, D-II"},{"id":"B","text":"A-II, B-III, C-IV, D-I"},{"id":"C","text":"A-II, B-IV, C-III, D-I"},{"id":"D","text":"A-III, B-II, C-IV, D-I"}]', 0, 'B', 'The correct matching will be:

Haemophilia is sex-linked recessive disorder.

Phenylketonuria is an autosomal recessive disorder.

Down''s syndrome is trisomy of chromosome number 21.

Turner''s syndrome is monosomy of X-chromosome.', NULL, 'null', '[]', '[{"id":"q35-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-20/q35-table-1.jpg","page":3,"alt":"Table for question 35"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3701, 'biology-2022-08-20', 'q36', 35, 35, 'The first restriction endonuclease isolated was', '[{"id":"A","text":"Eco RI"},{"id":"B","text":"pBR 322"},{"id":"C","text":"Hind II"},{"id":"D","text":"Bam HI"}]', 0, 'C', 'The first restriction nuclease characterized was isolated from Haemophilus influenzae bacteria and known as Hind II.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3702, 'biology-2022-08-20', 'q37', 36, 36, 'Which of the following are true, caused due to Inbreeding depression?

A. Reduces fertility and productivity

B. Helps in accumulation of inferior genes

C. Helps to evolve a hybrid in any animal

D. Increases productivity inbreed population

E. Retention of less desirable genes.', '[{"id":"A","text":"B and C only"},{"id":"B","text":"A and D only"},{"id":"C","text":"C and E only"},{"id":"D","text":"B and E only"}]', 0, 'B', 'The mating between the relatives in a small population is common and this may lower the population''s ability to persist and reproduce which is referred to as inbreeding depression. Inbreeding depression usually reduces fertility and productivity. Inbreeding helps in accumulation of superior genes and elimination of less desirable genes. Inbreeding depression does not play any role in development of hybrid.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3703, 'biology-2022-08-20', 'q39', 37, 37, 'Select the correct statements from the following

A. The presence of Thymine at the place of Uracil gives more stability to DNA

B. Both nucleic acids, i.e., DNA and RNA mutate

C. DNA is dependent on RNA for synthesis of proteins

D. RNA mutate at slower rate than DNA

E. DNA is better genetic material', '[{"id":"A","text":"A and D only"},{"id":"B","text":"A and B only"},{"id":"C","text":"A, B, C and D only"},{"id":"D","text":"A, B, C and E only"}]', 0, 'D', 'One incorrect statement is that RNA mutate at high rate than DNA because it is highly unstable. Rest other statements are correct.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.537Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3704, 'biology-2022-08-20', 'q40', 38, 38, 'Mr. X had purchased a fruit juice bottle from the market and is puzzled to see that is completely clear. It is due to', '[{"id":"A","text":"Lipase and Pectinase"},{"id":"B","text":"Amylase and Polymerase"},{"id":"C","text":"Pectinase and Protease"},{"id":"D","text":"Protease and Ligase"}]', 0, 'C', 'The enzymes pectinases and proteases help in clarifying fruit juices making them clearer as compared to those made at home. Lipases are used in detergent formulations and are helpful in removing oily stains from laundry. Amylase degrades starch.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3705, 'biology-2022-08-20', 'q41', 39, 39, 'Match List I with List II', '[{"id":"A","text":"A-1, B-III, C-II, D-IV"},{"id":"B","text":"A-I, B-III, C-IV, D-II"},{"id":"C","text":"A-II, B-I, C-III, D-IV"},{"id":"D","text":"A-II, B-III, C-I, D-IV"}]', 0, 'D', 'Pollination is the act of transferring pollen grains from the male anther of a flower to the female stigma. The goal of every living organism, including plants, is to create offspring for the next generation. Wind pollination is quite common in grasses. Marine seagrass Zostera is a water-pollinated plant.

Among the animals, insects, particularly bees are dominant biotic pollinating agents.

The tallest flower Amorphophallus is about 6 feet in height.', NULL, 'null', '[]', '[{"id":"q41-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-20/q41-table-1.jpg","page":4,"alt":"Table for question 41"}]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3706, 'biology-2022-08-20', 'q42', 40, 40, 'Yucca plant shows _', '[{"id":"A","text":"Flower with non-sticky pollen grains"},{"id":"B","text":"Water pollination"},{"id":"C","text":"Large feather stigma"},{"id":"D","text":"Moth is partner to complete life cycles"}]', 0, 'D', 'For more than 40 million years there has been a relationship between yucca plants and yucca moths. It''s a particularly important one because neither the yucca or the moth can survive without the other. The moth''s larvae depend on the seeds of the yucca plant for food, and the yucca plant can only be pollinated by the yucca moth.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3707, 'biology-2022-08-20', 'q43', 41, 41, '_ is aquatic plant showing insect pollination', '[{"id":"A","text":"Hydrilla"},{"id":"B","text":"Vallisneria"},{"id":"C","text":"Zostera"},{"id":"D","text":"Water hyacinth"}]', 0, 'D', 'In a majority of aquatic plants like water hyacinth and water lily, the flowers emerge above the water level and are pollinated by insects or wind as in most of the land plants.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3708, 'biology-2022-08-20', 'q44', 42, 42, 'Which of the following is NOT a feature of insect pollinated plant?', '[{"id":"A","text":"Light and non-sticky pollen grains"},{"id":"B","text":"Flowers are large and colourful"},{"id":"C","text":"Presence of nectar"},{"id":"D","text":"Flower with fragrance"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3709, 'biology-2022-08-20', 'q45', 43, 43, 'Grasses show pollination by', '[{"id":"A","text":"Water"},{"id":"B","text":"Insect"},{"id":"C","text":"Wind"},{"id":"D","text":"Animals PASSAGE Read the sentence and answer the questions. The process of replication requires a set of catalyst (enzymes). The main enzyme is referred to as DNA dependent DNA Polymerase. E.coli that has only $4.6 \\times 10^{6}$ bp (compare it with human whose diploid content is $6.6 \\times 10^{6}$ bp), completes the process of replication within 18 minutes, that means the average rate of polymerisation has to be approximately 2000 bp per second these polymerase also have catalase the reaction with high degree of accuracy. Deoxyribonucleoside Triphosphates serve dual purposes. In addition to DNA dependent DNA polymerases, many additional enzymes are required to complete the process of replication with high degree of accuracy. For long DNA molecules, since the two strands of DNA cannot be separated in its entire length (due to very high energy requirement), the replication occur with in a small opening of the DNA helix, referred to as replication fork. The DNA-dependent DNA polymerase catalyse polymerisation only in one direction, that $5^{\\prime}-3^{\\prime}$. This creates some additional complications at the replicating fork. Consequently, on one strand (the template with polarity $3^{\\prime}-5^{\\prime}$) the replication is continuous, which on the others (the template with polarity $5^{\\prime}-3^{\\prime}$), it is the discontinuous. The non-continuously synthesized fragments are later joined by the enzyme DNA ligase."}]', 0, 'C', 'Majority of insect pollinated flowers are large, colourful, fragrant and rich in nectar. So, option B, C and D are correct. Characteristics of wind pollinated flowers are: Well exposed stamens. Produce large number of pollens.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3710, 'biology-2022-08-20', 'q46', 44, 44, 'The DNA dependent-DNA polymerase catalyser is a DNA polymerase in one direction only that is _', '[{"id":"A","text":"5''-3'' of DNA"},{"id":"B","text":"3''-5'' of DNA"},{"id":"C","text":"5''-3'' of RNA"},{"id":"D","text":"3''-5'' of RNA"}]', 0, 'A', 'The DNA dependent DNA polymerase catalyse polymerisation only in one direction that is $5^{\prime}\rightarrow3^{\prime}$ of DNA.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3711, 'biology-2022-08-20', 'q47', 45, 45, 'In human beings DNA polymerase complete the process of replication in _', '[{"id":"A","text":"25 Minutes"},{"id":"B","text":"16 Minutes"},{"id":"C","text":"12 Minutes"},{"id":"D","text":"18 Minutes"}]', 0, 'D', 'The main enzyme of DNA replication is referred to as DNA dependent DNA polymerase which completes the process of replication within 18 minutes.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.538Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3712, 'biology-2022-08-20', 'q48', 46, 46, 'The number of nucleotides in E. coli is _', '[{"id":"A","text":"$ 1.2 \\times 10^{6} $ bp"},{"id":"B","text":"$ 2.3 \\times 10^{6} $ bp"},{"id":"C","text":"$ 4.6 \\times 10^{6} $ bp"},{"id":"D","text":"$ 6.6 \\times 10^{6} $ bp"}]', 0, 'C', 'The length of DNA is usually defined as number of nucleotides or base pairs present in it.

The number of nucleotide in $ E.coli $ is $ 4.6 \times 10^{6} $ bp.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.539Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3713, 'biology-2022-08-20', 'q49', 47, 47, 'In E. coli the main enzyme required to catalyze the polymerisation of deoxynucleotide is _', '[{"id":"A","text":"DNA-Dependent DNA Polymerase"},{"id":"B","text":"DNA-Dependent RNA Polymerase"},{"id":"C","text":"RNA-Dependent DNA Polymerase"},{"id":"D","text":"RNA-Dependent DNA Polymerase"}]', 0, 'A', 'The main enzyme for polymerisation of DNA is referred to as DNA dependent DNA polymerases, since it uses a DNA template to catalyse the polymerisation of deoxyribonucleotides.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.539Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3714, 'biology-2022-08-20', 'q50', 48, 48, 'Which of the following statements are correct?

A. DNA dependent DNA polymerase is a slow catalyst

B. Deoxyribonucleoside triphosphate provide energy for polymerisation

C. Replication fork is a small opening of the DNA helix

D. The replication is discontinuous on DNA template with polarity 3''-5''

E. The replication is continuous on DNA template with polarity 3''-5''', '[{"id":"A","text":"A and B only"},{"id":"B","text":"B and C only"},{"id":"C","text":"A and D only"},{"id":"D","text":"C and E only"}]', 0, 'B', 'Average rate of polymerisation of The enzyme DNA dependent DNA polymerase is approximately 2000 bp per second with high degree of accuracy. Hence it is a fast catalyst.

- Deoxyribonucleoside triphosphates provide energy for polymerisation because its two terminal phosphates are high energy phosphate same as in case of ATP.

Replication occurs with a small opening of the DNA helix, referred to as replication fork.

- The replication is continuous on the template strand with polarity 3''->5 while on the other strand replication is discontinuous with polarity 5''->3''

As per NTA option (B) is correct however as per NCERT, statements (B), (C) and (E) are correct but none of the option includes all three statements that are (B), (C) and (E).', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.539Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3715, 'biology-2022-08-23-shift-2', 'q01', 1, 1, 'Select the statements that are CORRECT regarding patterns of biodiversity.(A) Species diversity increases as we move away from the equator towards the poles(B) The tropical Amazon rain forest in South America has the greatest biodiversity on earth.(C) There is more solar energy available in the temperate region than tropics.(D) Tropical environments are less seasonal relatively more constant and predictable(E) A. Humboldt observed that within a region, species richness decreases with increasing explored area, up to a limit.Choose the correct answer from the options given below:', '[{"id":"A","text":"(A) and (E) only"},{"id":"B","text":"(B) and (C) only"},{"id":"C","text":"(B) and (D) only"},{"id":"D","text":"(C), (D) and (E) only"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.539Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
