INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3754, 'biology-2022-08-23-shift-2', 'q41', 41, 40, 'Read the following passage and answer the question :\nThe primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinary.
located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT). The primary lymphoid organ is .', '[{"id":"A","text":"Lymph nodes"},{"id":"B","text":"Bone marrow"},{"id":"C","text":"Tonsils"},{"id":"D","text":"Spleen"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.552Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3755, 'biology-2022-08-23-shift-2', 'q42', 42, 41, 'Read the following passage and answer the question : The primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen-sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is mainly lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean-shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT). Which of the following is not feature of spleen ?', '[{"id":"A","text":"It is large reservoir of erythrocyte."},{"id":"B","text":"It acts as filter of blood."},{"id":"C","text":"It shows reduction in size from birth to puberty"},{"id":"D","text":"It is a bean shaped organ containing lymphocyte and phagocyte"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.553Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3756, 'biology-2022-08-23-shift-2', 'q43', 43, 42, 'Read the following passage and answer the question :\nThe primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT).\nWhich of the following is NOT secondary lymphoid organ ?\n', '[{"id":"A","text":"Tonsils\\n"},{"id":"B","text":"Thymus\\n"},{"id":"C","text":"Appendix\\n"},{"id":"D","text":"Payer''s Patches"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.553Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3757, 'biology-2022-08-23-shift-2', 'q44', 44, 43, 'Read the following passage and answer the question :\nThe primary lymphoid organs are bone marrow and thymus, where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT).\nMucous associated lymphoid tissue (MALT) is NOT found in :\n', '[{"id":"A","text":"Urinogenital tract\\n"},{"id":"B","text":"Digestive tract\\n"},{"id":"C","text":"Tonsils\\n"},{"id":"D","text":"Respiratory tract"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.553Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3758, 'biology-2022-08-23-shift-2', 'q45', 45, 44, 'Read the following passage and answer the question :The primary lymphoid organs are bone marrow and thymus. Where immature lymphocytes differentiate into antigen sensitive lymphocytes. They migrate to secondary lymphoid organ like spleen, lymph nodes, tonsils, payer''s patches of small intestine and appendix. All blood cells including lymphocytes are produced in bone marrow which is main lymphoid organ. Spleen is large reservoir of erythrocytes. It is large bean shaped organ mainly containing lymphocyte and phagocyte. It acts as filter of blood by trapping blood borne micro organism. Lymph nodes are small solid structures located at different points along lymphatic system. Antigens trapped in lymph node are responsible for activation of lymphocytes present there and cause the immune response. There is lymphoid tissue located within. Lining of major tracts like respiratory, digestive and urinogenital tracts called mucous associated lymphoid tissue (MALT). Which of the following is incorrect statement. (A) All blood cells including lymphocytes are produced in bone marrow (B) Lymph nodes are small solid structures located at different points along lymphatic system (C) Payer''s patches of small intestine is primary lymphoid organ. (D) Antigen trapped in lymph node are responsible for activation of lymphocytes present in lymph node and causes immune response (D) (A) only (B) and (D) onlyChoose the correct answer from the options given below :', '[{"id":"A","text":"(C) only"},{"id":"B","text":"(B) only"},{"id":"C","text":"(A) only"},{"id":"D","text":"(D) only"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.553Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3759, 'biology-2022-08-23-shift-2', 'q46', 46, 45, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to
Fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel.\nThe separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors.\nAgarose is extracted from .\n', '[{"id":"A","text":"Bacteria\\n"},{"id":"B","text":"Marine animals\\n"},{"id":"C","text":"Sea weeds\\n"},{"id":"D","text":"Fungi"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.553Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3760, 'biology-2022-08-23-shift-2', 'q47', 47, 46, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel.\nThe separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors.\nWhat is elution ?\n', '[{"id":"A","text":"It is movement of negatively charged DNA fragments through agarose gel.\\n"},{"id":"B","text":"Extraction of DNA from the host\\n"},{"id":"C","text":"Extraction of DNA and treatment with restriction endonuclease\\n"},{"id":"D","text":"Cutting of separated DNA fragments from agarose gel and extraction of DNA fragment"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[21]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.554Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3761, 'biology-2022-08-23-shift-2', 'q48', 48, 47, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther from the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The DNA fragments formed by treatment with endonuclease are separated by .', '[{"id":"A","text":"PCR"},{"id":"B","text":"Gel Electrophoresis"},{"id":"C","text":"Cloning"},{"id":"D","text":"Restriction digestion"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[22]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.554Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3762, 'biology-2022-08-23-shift-2', 'q49', 49, 48, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther from the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA
can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The separated DNA fragments can be visualised after staining with _, followed by exposure to _.', '[{"id":"A","text":"$ \\beta $-galactosidase, UV radiation"},{"id":"B","text":"$ \\beta $-galactosidase, Gamma radiation"},{"id":"C","text":"Ethidium bromide, UV radiation"},{"id":"D","text":"Ethidium bromide, Gamma radiation"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[22]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.554Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3763, 'biology-2022-08-23-shift-2', 'q50', 50, 49, 'The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. Since DNA fragments are negatively charged molecules, they can be separated by forcing them to move towards the anode under an electric field through a medium/matrix. The commonly used matrix is agarose which is a natural polymer extracted from sea weeds. The DNA fragments separate according to their size through sieving effect provided by the agarose gel. Hence, the smaller fragments move farther in the agarose gel. The separated DNA fragments can be visualised only after staining the DNA with ethidium bromide followed by exposure to UV radiation. Bright orange coloured bands of DNA can be observed. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing recombinant DNA by joining them with cloning vectors. The fragments of DNA separate on agarose gel, based on the .', '[{"id":"A","text":"Size of fragments"},{"id":"B","text":"Charge of each fragment"},{"id":"C","text":"Colour of fragment"},{"id":"D","text":"Type of DNA"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[23]', 'keyed', '["verified-key"]', '2026-11-05T20:58:59.554Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3764, 'biology-2022-08-30', 'q02', 2, 1, 'Match List I with List II', '[{"id":"A","text":"A-I,B-IV,C-III,D-II"},{"id":"B","text":"A-II,B-I,C-IV,D-III"},{"id":"C","text":"A-III,B-IV,C-I,D-II"},{"id":"D","text":"A-IV,B-II,C-III,D-I"}]', 0, 'D', 'Option (D) is the correct answer because skin in our body is the main physical barrier which prevents entry of the micro-organisms. Natural killer cells are the cellular barriers of innate immunity. Tears from eyes comes under the category of physiological barriers. Virus infected cells secrete proteins called interferons which protect non-infected cells from further viral infection. It comes under cytokine barrier.', NULL, 'null', '[]', '[{"id":"q02-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q02-table-1.jpg","page":1,"alt":"Table for question 2"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.555Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3765, 'biology-2022-08-30', 'q03', 3, 2, 'A couple is unable to produce a child as the male partner has low sperm count. Infertility caused by this condition can be treated using', '[{"id":"A","text":"ZIFT"},{"id":"B","text":"AI"},{"id":"C","text":"GIFT"},{"id":"D","text":"IUT"}]', 0, 'B', 'Option (B) is the correct answer as infertility cases either due to inability of the male partner to inseminate the female or due to very low sperm count in the ejaculate, could be corrected by artificial insemination. After IVF, the zygote or early embryo (upto 8 blastomeres) could then be transferred into the fallopian tube i.e. ZIFT and embryo with more than 8 blastomeres is transferred into the uterus (IUT). Option (C) is not the answer as GIFT stands for Gamete Intra Fallopian Transfer.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.555Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3766, 'biology-2022-08-30', 'q04', 4, 3, 'Which of these are the carriers of male gametes in some seed plants?', '[{"id":"A","text":"Microspore mother cells"},{"id":"B","text":"Pollen Grains"},{"id":"C","text":"Anthers"},{"id":"D","text":"Megaspore mother cells"}]', 0, 'B', 'Pollen grains represent male gametophyte in seed plants. It carries the male gametes which can be transferred to the female gamete via pollination.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.555Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3767, 'biology-2022-08-30', 'q05', 5, 4, 'Match List I with List II', '[{"id":"A","text":"A-I, B-II, C-IV, D-III"},{"id":"B","text":"A-IV, B-III, C-I, D-II"},{"id":"C","text":"A-III, B-II, C-I, D-IV"},{"id":"D","text":"A-II, B-IV, C-I, D-III"}]', 0, 'B', 'Option (B) is the correct answer as the causative agents of malaria, pneumonia, typhoid and filariasis are Plasmodium (protozoa), Haemophilus (bacteria), Salmonella typhi (bacteria) and Wuchereria (nematode) respectively.', NULL, 'null', '[]', '[{"id":"q05-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q05-table-1.jpg","page":1,"alt":"Table for question 5"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3768, 'biology-2022-08-30', 'q06', 6, 5, 'Arrange the following steps in order for the technique of DNA finger printing.

A. Isolation of DNA.

B. Separation of DNA fragments by gel, electrophoresis.

C. Digestion of DNA by restriction endonucleases.

D. Blotting of separated DNA fragments to nylon membrane.

E. Hybridisation using VNTR probe followed by autoradiography.', '[{"id":"A","text":"A,C,B,D,E"},{"id":"B","text":"A,B,C,D,E"},{"id":"C","text":"A,B,D,C,E"},{"id":"D","text":"A,E,C,B,D"}]', 0, 'A', 'DNA fingerprinting involves following steps:

A. Isolation of DNA.

C. Digestion of DNA by restriction endonucleases.

B. Separation of DNA fragments by gel electrophoresis.

D. Blotting of separated DNA fragments to nylon membrane.

E. Hybridisation using VNTR probe followed by autoradiography.

So the correct order is A, C, B, D, E.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3769, 'biology-2022-08-30', 'q07', 7, 6, 'Long term use of alcohol specially causes-', '[{"id":"A","text":"Liver cirrhosis"},{"id":"B","text":"Arthritis"},{"id":"C","text":"Pulmonary system damage"},{"id":"D","text":"Premature baldness"}]', 0, 'A', 'Option (A) is the correct answer because the chronic use of drugs and alcohol damages nervous system and liver (alcoholic cirrhosis).

Option (B) is not the answer as, arthritis is defined as the inflammation of joints.

Option (C) is not the answer as pulmonary system damage is associated with smoking tobacco or other forms of air pollutants.

Option (D) is not the answer as premature baldness can occur due to deficiency of biotin or growth hormone deficiency.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3770, 'biology-2022-08-30', 'q08', 8, 7, 'Select the appropriate options with reference to post fertilisation changes in angiosperms.

A. Inner integument of ovule develops into tegmen.

B. Ovary wall forms pericarp

C. Ovule forms fruit

D. Zygote forms endosperm

E. Outer integument of ovule develops into Testa


Choose the correct answer from the options given below:

(a) B, E only (b) A, B, E only

(c) C, D, B only (d) A, C, B only

The part of the human sperm that helps in the fertilisation of the ovum is a cap-like structure called', '[{"id":"A","text":"Head"},{"id":"B","text":"Acrosome"},{"id":"C","text":"Middle piece"},{"id":"D","text":"Tail"}]', 0, 'B', 'Post fertilization events in angiosperms include-

• Formation of endosperm from primary endosperm cell.

• Formation of embryo from zygote

• Formation of seed from ovule

• During seed formation, integuments develops into seed coats. Outer integument forms testa (outer seed coat) while inner integument forms tegmen (inner seed coat).

- Formation of pericarp from ovary wall.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3771, 'biology-2022-08-30', 'q10', 10, 8, 'Rearrange the events of life cycle of a retrovirus.

A. New viral RNA produced by infected cell

B. Reverse transcription

C. New virus particles inject into other cells

D. Viral RNA introduced into the cell

E. Viral DNA incorporates into host genome', '[{"id":"A","text":"A, B, D, E, C"},{"id":"B","text":"B, E, D, A, C"},{"id":"C","text":"C, A, B, D, E"},{"id":"D","text":"D, B, E, A, C"}]', 0, 'D', 'Option (D) is correct answer because the steps for HIV in host is as follows:

D - Viral RNA is introduced into the cell.

B - Enzyme reverse transcriptase acts on viral RNA.

E - Viral DNA produced is incorporated into the host genome.

A - New viral RNA is produced by infected cell.

C - New virus particles inject into other cells.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3772, 'biology-2022-08-30', 'q11', 11, 9, 'Secondary treatment of sewage involves', '[{"id":"A","text":"Physical removal of large and small particles from sewage through filtration"},{"id":"B","text":"Anaerobic sludge digestion"},{"id":"C","text":"Sedimentation to remove smaller and larger particles"},{"id":"D","text":"Mechanical agitation coupled with addition of aerobic microbes"}]', 0, 'D', 'Sewage treatment consists of two stages

1. Primary treatment - Removes particles through filtration and sedimentation

2. Secondary treatment/ Biological treatment-Primary effluent is treated with aerobic microbes in an aerobic tank. During the process the medium is agitated continuously for proper mixing and aeration.

Once the organic content is degraded mostly, the effluent is allowed to sediment in settling tank where the sediment formed is called Activated sludge.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.556Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3773, 'biology-2022-08-30', 'q12', 12, 10, 'Given below two statements: one is labelled as assertion A and the other is labelled as Reason R

Assertion A: In F2 generation of a Mendelian cross, the traits seen in the progeny are identical to their parents.

Reason R: The progeny of the F2 generation in a Mendelian cross shows no blending of traits.

In the light of the above statements, chose the most appropriate answer from the options given below:', '[{"id":"A","text":"Both A and R are correct and R is the correct explanation of A"},{"id":"B","text":"Both A and R are correct but R is NOT the correct explanation of A"},{"id":"C","text":"A is correct but R is not correct"},{"id":"D","text":"A is not correct but R is correct"}]', 0, 'A', 'In monohybrid Mendelian cross, F1 generation shows phenotype of only one parent while F2 generation has progenies expressing phenotype of both parents.

This observation was possible because there is no blending of traits occur. This also led to the conclusion that traits are governed by discrete units.

Both A and R are correct and R is the correct explanation of A.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.557Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3774, 'biology-2022-08-30', 'q13', 13, 11, 'In flowering plants, the egg apparatus consists of:', '[{"id":"A","text":"Three antipodals and one egg cell"},{"id":"B","text":"Two synergids and one central cell"},{"id":"C","text":"Two synergids and one egg cell"},{"id":"D","text":"Three antipodals and two synergids"}]', 0, 'C', 'Embryo sac, the female gametophyte of angiosperm is 8-nucleated 7-celled. It includes-

1. Egg apparatus $ \rightarrow $ with one egg and two synergids

2. Central cell with 2 polar nuclei

3. Three antipodals', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.557Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3775, 'biology-2022-08-30', 'q14', 14, 12, 'Layers surrounding the ovum from outside to inside are

A. Zona pellucida

B. Vitelline membrane

C. Corona radiata', '[{"id":"A","text":"A, C, B"},{"id":"B","text":"C, B, A"},{"id":"C","text":"C, A, B"},{"id":"D","text":"A, B, C"}]', 0, 'C', 'Option (C) is the correct answer, because', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.557Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3776, 'biology-2022-08-30', 'q15', 15, 13, 'The term ribosome is applicable to the following molecule in bacteria', '[{"id":"A","text":"mRNA"},{"id":"B","text":"23S rRNA"},{"id":"C","text":"5S rRNA"},{"id":"D","text":"hn RNA"}]', 0, 'B', 'In prokaryotes, the larger subunit of ribosome consists of 23S and 5S rRNA. In eukaryotes, the larger subunit of ribosome has 28S, 5.8S and 5S rRNA. Hence term ribosome is applicable to 23S rRNA in bacteria. mRNA is synthesised by transcription in both prokaryotes and eukaryotes.

hnRNA is the precursor of mRNA in eukaryotes.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.557Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3777, 'biology-2022-08-30', 'q17', 17, 14, 'After an HIV infection, the body of the patient starts becoming immunodeficient mainly due to :', '[{"id":"A","text":"The damage caused to secondary lymphoid organs"},{"id":"B","text":"Rapid multiplication of the virus outside the host cells"},{"id":"C","text":"Progressive decline in the number of helper T-lymphocytes"},{"id":"D","text":"Infection by a number of pathogens"}]', 0, 'C', 'Option C is the correct answer as

T-helper cells stimulate B-cells to produce antibodies and induce killer-T-cells to destroy the non-self cells (foreign cells).

In HIV infection, due to decrease in the number of helper T-cells, the person starts suffering from opportunistic infections due to decrease in immunity.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.557Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3778, 'biology-2022-08-30', 'q18', 18, 15, 'Bioactive molecules like statins are produced by :', '[{"id":"A","text":"Trichoderma polysporum"},{"id":"B","text":"Monascus purpureus"},{"id":"C","text":"Acetobacter aceti"},{"id":"D","text":"Streptococcus"}]', 0, 'B', 'Bioactive molecules like statins are produced by the yeast Monascus purpureus.

Trichodermapolysporum produces an immunosuppressive agent cyclosporin A.

Acetobacter aceti produces acetic acid.

Streptococcus produces the clot buster enzyme streptokinase.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.558Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3779, 'biology-2022-08-30', 'q19', 19, 16, 'The haplodiploid sex-determination system where all the males of the population are haploid and females are diploid, is seen in', '[{"id":"A","text":"Drosophila"},{"id":"B","text":"Honey bees"},{"id":"C","text":"Birds"},{"id":"D","text":"Grasshoppers"}]', 0, 'B', 'The haplo-diploid sex determination system is seen in honey bees. In honeybee males have half the number of chromosomes than that of females.

In Drosophila and grasshopper, male heterogamety is seen.

In birds, female heterogamety is seen.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.558Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3780, 'biology-2022-08-30', 'q20', 20, 17, 'Match List I with List II', '[{"id":"A","text":"A-I, B-II, C-III, D-IV"},{"id":"B","text":"A-III, B-1, C-II, D-IV"},{"id":"C","text":"A-I, B-III, C-IV, D-II"},{"id":"D","text":"A-II, B-III, C-I, D-IV"}]', 0, 'D', 'Option (D) is the correct answer because

• Genetic drift is defined as sudden change in gene frequency by chance.

• In stabilising selection, more individuals acquire mean character value.

• Gene flow is the change in allele frequency due to immigration and emigration.

Saltation is the single step large mutation.', NULL, 'null', '[]', '[{"id":"q20-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q20-table-1.jpg","page":2,"alt":"Table for question 20"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.558Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3781, 'biology-2022-08-30', 'q21', 21, 18, 'Match List I with List II', '[{"id":"A","text":"A - II, B - III, C - IV, D - I"},{"id":"B","text":"A-I, B-II, C-III, D-IV"},{"id":"C","text":"A-III, B-I, C-IV, D-II"},{"id":"D","text":"A-IV, B-II, C-III, D-I"}]', 0, 'C', 'The crop bred by hybridisation and selection for particular disease resistance are as follows

Cowpea - Bacterial blight

Chilli - Tobacco mosaic virus

Brassica - White rust

Wheat - Leaf and stripe rust

Therefore, the correct answer is option C', NULL, 'null', '[]', '[{"id":"q21-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q21-table-1.jpg","page":2,"alt":"Table for question 21"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.558Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3782, 'biology-2022-08-30', 'q22', 22, 19, 'What happened when heat-killed S cells along with live R cells were injected into mice in Griffith''s experiment?', '[{"id":"A","text":"Mice died and showed live R cells in the blood"},{"id":"B","text":"Mice survived and showed live S cells in the blood"},{"id":"C","text":"Mice died and showed live S cells in the blood"},{"id":"D","text":"Mice survived and showed live R cells in the blood"}]', 0, 'C', 'When Griffith injected a mixture of heat-killed S cells and live R cells, the mice died. Moreover, he recovered living S-bacteria from the dead mice. He concluded that the R-strain bacteria had somehow been transformed by the heat-killed S-strain bacteria.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.558Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3783, 'biology-2022-08-30', 'q23', 23, 20, 'Autotrophic microbe for fixing atmospheric nitrogen:', '[{"id":"A","text":"Rhizobium"},{"id":"B","text":"Aspergillus"},{"id":"C","text":"Oscillatoria"},{"id":"D","text":"Trichoderma"}]', 0, 'C', 'Cyanobacteria are autotrophic microbes widely distributed in aquatic and terrestrial environment many of which can fix atmospheric nitrogen.

e.g. Anabaena, Nostoc, Oscillatoria

Trichoderma and Aspergillus are fungi

Rhizobium is heterotrophic bacteria, as symbiont, can fix atmospheric nitrogen.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3784, 'biology-2022-08-30', 'q24', 24, 21, 'In humans females at the time of birth, the stage of cell cycle of oocyte is', '[{"id":"A","text":"Prophase-I"},{"id":"B","text":"Prophase-II"},{"id":"C","text":"Meiosis-II"},{"id":"D","text":"Mitosis"}]', 0, 'A', 'Option (A) is the correct answer because oogonia start division during fetal life and enter into prophase-I of the meiotic division and get temporarily arrested at that stage called primary oocytes. So, at the time of birth, the stage of cell cycle of oocyte is prophase-I.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3785, 'biology-2022-08-30', 'q25', 25, 22, 'Calotropis, a weed growing in abandoned fields, produces one of the following biochemicals as a defense against grazers and browsers-', '[{"id":"A","text":"Nicotine"},{"id":"B","text":"Opium"},{"id":"C","text":"Cardiac glycosides"},{"id":"D","text":"Strychnine"}]', 0, 'C', 'Calotropis, a weed growing in abandoned field produces highly poisonous cardiac glycosides as a defense against grazers and browsers.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3786, 'biology-2022-08-30', 'q26', 26, 23, 'Calculate the birth rate if there were 60 sparrows in a garden last year and through reproduction 24 new sparrows are added this year', '[{"id":"A","text":"0.4 offsprings per sparrow per year"},{"id":"B","text":"0.2 offsprings per sparrow per year"},{"id":"C","text":"0.6 offsprings per sparrow per year"},{"id":"D","text":"0.1 offsprings per sparrow per year"}]', 0, 'A', 'Birth rate = $ \frac{\Delta N}{N\Delta t} = \frac{24}{60} = 0.4 $

If there were 60 sparrows in a garden last year and through reproduction 24 new sparrows are added this year, then birth rate is 0.4 offspring per sparrow per year.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3787, 'biology-2022-08-30', 'q27', 27, 24, 'Totipotency can be defined as', '[{"id":"A","text":"Capacity to generate whole plant from any cell/ex-plant"},{"id":"B","text":"Capacity to survive in unfavourable environment condition"},{"id":"C","text":"Ability to conduct water in 100 meter tall tree"},{"id":"D","text":"The duration of dormancy of seeds and other propagules in angiosperms"}]', 0, 'A', 'The capacity to generate whole plant from any cell/explant is called totipotency.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3788, 'biology-2022-08-30', 'q28', 28, 25, 'Match List I with List II', '[{"id":"A","text":"A-III, B-IV, C-I, D-II"},{"id":"B","text":"A-I, B-III, C-II, D-IV"},{"id":"C","text":"A-II, B-III, C-I, D-IV"},{"id":"D","text":"A-III, B-II, C-I, D-IV"}]', 0, 'A', '- Fig species can be pollinated only by its partner wasp species. So it shows mutual relationship.

• Koel and crow show brood parasitism in which parasitic bird lays its eggs in the nest of its host and let the host incubate them.

• Balanus dominates the intertidal areas and excludes the smaller barnacle Chathamalus from the zone so shows competition.

The egret and grazing cattle shows commensalism. The egrets always forage close to where the cattle are grazing.', NULL, 'null', '[]', '[{"id":"q28-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q28-table-1.jpg","page":3,"alt":"Table for question 28"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.559Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3789, 'biology-2022-08-30', 'q29', 29, 26, 'Match List I with List II', '[{"id":"A","text":"A-I, B-II, C-IV, D-III"},{"id":"B","text":"A-Ⅱ, B-Ⅰ, C-Ⅳ, D-Ⅲ"},{"id":"C","text":"A-II, B-IV, C-I, D-III"},{"id":"D","text":"A-I, B-IV, C-II, D-III"}]', 0, 'C', 'Option (C) is the correct answer because

• Sex determination is illegally done by amniocentesis so, there is ban on it in India.

- Withdrawal method of contraception is also known as coitus interrupts in which the male partner withdraws his penis from the vagina just before ejaculation.

Vault is a barrier method of contraception.

Syphilis is a venereal or sexually transmitted bacterial disease.', NULL, 'null', '[]', '[{"id":"q29-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q29-table-1.jpg","page":3,"alt":"Table for question 29"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3790, 'biology-2022-08-30', 'q30', 30, 27, 'Restriction endonucleases are used as molecular', '[{"id":"A","text":"molecular build up at nucleotides"},{"id":"B","text":"molecular cement to join DNA sites"},{"id":"C","text":"molecular knife cut DNA at specific site"},{"id":"D","text":"molecular degradation to break up the DNA to nucleotides"}]', 0, 'C', 'Option (C) is the correct answer because restriction endonucleases are commonly known as molecular scissors. Each restriction endonuclease inspects the length of a DNA sequence, finds its specific palindromic nucleotide sequence and cut each of the two strands of the double helix at this specific points in their sugar-phosphate backbone.

DNA ligase works as molecular glue to join up the DNA', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3791, 'biology-2022-08-30', 'q32', 32, 28, 'Match List I with List II', '[{"id":"A","text":"A-I, B-II, C-IV, D-III"},{"id":"B","text":"A-III, B-I, C-IV, D-II"},{"id":"C","text":"A-III, B-IV, C-II, D-I"},{"id":"D","text":"A-I, B-II, C-III, D-IV"}]', 0, 'B', 'The ''i'' gene codes for the repressor protein of the lac operon.

The ''z'' gene codes for beta galactosidase which is primarily responsible for hydrolysis of disaccharide.

The ''y'' gene codes for pemease which increases permeability of the cell to b-galactosidase.

''a'' gene encodes transacetylase.

So, A-III, B-I, C-IV, D-II.', NULL, 'null', '[]', '[{"id":"q32-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q32-table-1.jpg","page":3,"alt":"Table for question 32"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3792, 'biology-2022-08-30', 'q33', 33, 29, 'Cohen and Boyer created the first recombinant DNA using plasmid of', '[{"id":"A","text":"Escherichia coli"},{"id":"B","text":"Thermus aquaticus"},{"id":"C","text":"Salmonella typhimurium"},{"id":"D","text":"Bacillus thuringiensis"}]', 0, 'C', 'Option (C) is the correct answer because Stanley Cohen and Herbert Boyer created the first recombinant DNA using a native plasmid of Salmonella typhimurium. This recombinant DNA was then transferred into Escherichia coli.

Thermus aquaticus is a thermostable bacterium whose enzymes are used in PCR.

Bacillus thuringiensis is used to make Bt cotton (pest-resistant crop).', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3793, 'biology-2022-08-30', 'q34', 34, 30, 'Match List I with List II', '[{"id":"A","text":"A-II, B-III, C-I, D-IV"},{"id":"B","text":"A-I, B-IV, C-III, D-II"},{"id":"C","text":"A-IV, B-III, C-II, D-I"},{"id":"D","text":"A-III, B-IV, C-II, D-I"}]', 0, 'C', '- When exhaust passes through the catalytic converter, carbon monoxide and nitric oxide are changed to carbon dioxide and water.

• Electrostatic precipitator can remove over 99% particulate matter present in the exhaust from the thermal power plant.

• High noise level in an area is eliminated by using earmuffs

Solid wastes are trashed in a depression or trench considered as landfills.', NULL, 'null', '[]', '[{"id":"q34-table-1","kind":"table","path":"/local-papers/assets/biology-2022-08-30/q34-table-1.jpg","page":3,"alt":"Table for question 34"}]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3794, 'biology-2022-08-30', 'q35', 35, 31, 'Identify the correct statements

A. Oogenesis is initiated at puberty

B. Second meiotic division in secondary oocyte occurs in the ovary

C. Middle piece of sperm provides energy for movement

D. Fertilization of gametes occurs in the ampulla isthmic region of oviduct

E. Myometrium helps in muscular contractions of the uterus', '[{"id":"A","text":"A, D, E only"},{"id":"B","text":"A, B, D only"},{"id":"C","text":"B, C, D only"},{"id":"D","text":"C, D, E only"}]', 0, 'D', 'Option (D) is the correct answer because statements C, D and E are correct.

The middle piece of sperm possesses numerous mitochondria, which produce energy for the movement of tail.

Fertilisation can only occur if the ovum and sperms are transported simultaneously to the ampulla-isthmic region of oviduct.

The middle layer, myometrium exhibits strong uterine contractions during delivery of the baby.

Oogenesis is initiated during the embryonic development stage whereas spermatogenesis starts at the age of puberty.

2nd meiotic division in secondary oocyte is completed in fallopian tube after entry of sperm into the ovum.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3795, 'biology-2022-08-30', 'q36', 36, 32, 'How many gametes will be formed in the pea plant having genotype RrTT?', '[{"id":"A","text":"One"},{"id":"B","text":"Two"},{"id":"C","text":"Four"},{"id":"D","text":"Eight"}]', 0, 'B', 'In a pea plant having genotype $ RrT^{T} $, two types of gametes will be formed i.e. RT and rT.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.560Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3796, 'biology-2022-08-30', 'q37', 37, 33, 'The detritus food chain (DFC) begins with', '[{"id":"A","text":"Green plants"},{"id":"B","text":"Carnivore"},{"id":"C","text":"Dead Organic matter"},{"id":"D","text":"Herbivore"}]', 0, 'C', 'Detritus food chain begins with detritus or dead organic matter.

Grazing food chain begins with green plants.

Carnivores feed on consumers.

Herbivores feed on green plants.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3797, 'biology-2022-08-30', 'q38', 38, 34, 'How many cycles in a PCR will be required for amplifying the genetic material to about one billion times?', '[{"id":"A","text":"10 cycles"},{"id":"B","text":"15 cycles"},{"id":"C","text":"30 cycles"},{"id":"D","text":"35 cycles"}]', 0, 'C', 'Option (C) is the correct answer because if the process of replication of DNA is repeated many times, the segment of DNA can be amplified to approximately billion times, i.e., 1 billion copies are made at the end of 30 PCR cycles. It is possible to generate ''2n'' DNA molecules after ''n'' number of cycles.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3798, 'biology-2022-08-30', 'q39', 39, 35, 'Gene of which one of the following is present exclusively on the x-chromosome in human being', '[{"id":"A","text":"Thalassemia"},{"id":"B","text":"Phenylketonuria"},{"id":"C","text":"Red and green colour blindness"},{"id":"D","text":"Sickle cell anaemia"}]', 0, 'C', 'Red-green colour blindness is an X-linked recessive. Mendelian disorder. Gene for this character is present on X-chromosome in humans.

Thalassemia, phenylketonuria and sickle cell anaemia are autosomal recessive Mendelian disorders.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3799, 'biology-2022-08-30', 'q40', 40, 36, 'Biofortification refers to', '[{"id":"A","text":"Sources of proteins for animal and human nutrition"},{"id":"B","text":"Production of somatic hybrids"},{"id":"C","text":"Use of mutation breeding"},{"id":"D","text":"Breeding crops with higher levels of vitamins and minerals, or higher protein and healthier fat CASE STUDY Some strains of Bacillus thuringiensis produce protein that kill certain insects such as lepidopterans (tobacco budworm, armyworm), coleopterans (beetles) and dipterans (flies, mosquitoes). Bacillus thuringiensis forms protein crystals during a particular phase of their growth. These crystals contain a toxic insecticidal protein. The Bt toxin proteins exists as inactive protoxins but once an insect ingests the inactive toxin, it is converted into an active form due to alkaline pH of the gut which solubilise the crystals."}]', 0, 'D', 'Breeding of crops with higher levels of vitamins and minerals or higher protein and healthier fats is called biofortification.

SCP is one of the sources of proteins for animal and human nutrition.

Somatic hybrids are produced by somatic hybridization.

Mutation breeding is one of the methods for making crops disease resistant.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3800, 'biology-2022-08-30', 'q41', 41, 37, 'The Bt toxin acts on _ of insect pest', '[{"id":"A","text":"Hind gut"},{"id":"B","text":"Nervous system"},{"id":"C","text":"Reproductive system"},{"id":"D","text":"Midgut"}]', 0, 'D', 'Option (D) is the correct answer because the activated Bt toxins bind to the surface of midgut epithelial cells and create pores that cause cell swelling and lysis and eventually cause death of the insect.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3801, 'biology-2022-08-30', 'q42', 42, 38, 'Some strains of Bacillus thuringiensis produce proteins that kill certain insects such as', '[{"id":"A","text":"Grasshoppers and mosquitoes"},{"id":"B","text":"Lepidopterans, coleopterans and dipterans"},{"id":"C","text":"Coleopterans and nematodes"},{"id":"D","text":"Meloidegyne incognitia"}]', 0, 'B', 'Option (B) is the correct answer because some strains of Bacillus thuringiensis produce proteins that kill certain insects such as lepidopterans (tobacco budworm, armyworm), coleopterans (beetles) and dipterans (flies, mosquitoes).', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3802, 'biology-2022-08-30', 'q43', 43, 39, 'Thuringiensis forms protein crystals during a particular phase of their growth. These crystals contain a toxic.', '[{"id":"A","text":"Proteolytic enzymes"},{"id":"B","text":"Chitin"},{"id":"C","text":"Insecticidal protein"},{"id":"D","text":"Flavoprotein"}]', 0, 'C', 'Option (C) is the correct answer because Bacillus thuringiensis forms a toxic insecticidal protein during a particular phase of their growth. This protein kills the insects and leads to the development of pest-resistant crops.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3803, 'biology-2022-08-30', 'q44', 44, 40, 'Bt toxin exists as inactive protoxins, it is converted into an active form of toxin due to', '[{"id":"A","text":"Enzymes in insect''s gut"},{"id":"B","text":"Acidic pH of the insect''s gut"},{"id":"C","text":"Binding with collagen in insect''s gut"},{"id":"D","text":"Alkaline pH of the insect''s gut"}]', 0, 'D', 'Option (D) is the correct answer because the Bt toxin protein exists as inactive protoxins but once an insect ingests the inactive toxin, it is converted into an active form of toxin due to the alkaline pH of the gut which solubilises the crystals.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3804, 'biology-2022-08-30', 'q45', 45, 41, 'The proteins encoded by the genes cryIAc and cryIIAb control', '[{"id":"A","text":"Corn borers"},{"id":"B","text":"Cotton bollworms"},{"id":"C","text":"Mosquitoes"},{"id":"D","text":"Nematodes The biological wealth of our planet has been declining rapidly and the accusing finger is clearly pointing to human activities. The colonisation of tropical pacific islands by humans is said to have led to extinction of more than 2000 species of native birds. The IUCN red list documents the extinction of 784 species. Since the origin and diversification of life on earth, there were five episodes of mass extinction of species. Current species extinction rate as estimated to be 100-1000 times faster. There are four major causes called \"The Evil quartet\" Habitat loss, over exploitation, Alien species invasion and co-extinction. Conservation efforts are necessary to preserve biodiversity and protect endangered species and their habitats. PASSAGE"}]', 0, 'B', 'Option (B) is the correct answer because the proteins encoded by the genes cryIAc and cryIIAb control the cotton bollworms, that of cryIAb controls corn borer.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3805, 'biology-2022-08-30', 'q46', 46, 42, 'Tissue culture and cryopreservation are the techniques used', '[{"id":"A","text":"In in-situ conservation"},{"id":"B","text":"To control conservation of medicinal plants only"},{"id":"C","text":"In ex-situ conservation method"},{"id":"D","text":"Used in conventional breeding programmes"}]', 0, 'C', 'Ex-situ conservation method includes protective maintenance of threatened species in zoological parks and botanical gardens, in-vitro fertilization, tissue culture propagation and cryopreservation of gametes.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.561Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3806, 'biology-2022-08-30', 'q47', 47, 43, 'Mr. X wants to understand the ''Evil Quartet'' to know the reasons of Biodiversity loss. It is', '[{"id":"A","text":"Habitat loss and fragmentation only"},{"id":"B","text":"Over exploitation and Alien species invasions only"},{"id":"C","text":"Co-extinctions and Alien-species invasion"},{"id":"D","text":"Habitat loss, over exploitation, Alien species invasions and co-extinctions"}]', 0, 'D', 'There are four major causes of biodiversity losses called ''The Evil Quartet''. These are habitat loss and fragmentation, over exploitation, alien species invasions and co-extinctions.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.562Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3807, 'biology-2022-08-30', 'q48', 48, 44, 'Which one of the following is NOT the reason for decline in biodiversity?', '[{"id":"A","text":"Pollution"},{"id":"B","text":"Agriculture"},{"id":"C","text":"Sacred groves"},{"id":"D","text":"Fishing"}]', 0, 'C', 'There are accelerated rates of decline in biodiversity largely due to human activities. Agriculture results in habitat loss and pollution makes the environment unfit for survival of species. One of the example of over-exploitation can be fishing that can lead to decline in biodiversity.

In sacred groves wildlife is given total protection.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.563Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3808, 'biology-2022-08-30', 'q49', 49, 45, 'Select the one which is NOT an ex-situ conservation of biodiversity', '[{"id":"A","text":"Zoological parks"},{"id":"B","text":"Botanical gardens"},{"id":"C","text":"National parks"},{"id":"D","text":"Seed banks"}]', 0, 'C', 'National parks are in-situ conservation strategies for the protection of species. Zoological parks, botanical gardens and seed banks are ex-situ conservation strategies for the protection of species.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.563Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3809, 'biology-2022-08-30', 'q50', 50, 46, 'Identify the in-situ ways to conserve biodiversity from the following

A. Zoological parks

B. Eggs fertilised in-vitro

C. Sacred groves

D. Biosphere reserves', '[{"id":"A","text":"A, B only"},{"id":"B","text":"B, C only"},{"id":"C","text":"C, D only"},{"id":"D","text":"A, D only"}]', 0, 'C', 'Sacred groves and biosphere reserve are in-situ conservation strategies for protection of biodiversity. Zoological parks are ex-situ conservation strategies for biodiversity protection.

When the fertilization of egg is done outside the body, it is called in-vitro fertilization.

