INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3819, 'chemistry-2022-08-17', 'q11', 10, 10, 'Consider the case when a highly diluted solution of KI is added to AgNO_{3} solution. Arrange the following in the increasing order of ease of coagulation of the resulting sol.

A. BaSO_{4}

B. NaCl

C. Na_{3}PO_{4}

D. K_{4}[Fe(CN)_{6}]', '[{"id":"A","text":"A < C < B < D"},{"id":"B","text":"D < C < A < B"},{"id":"C","text":"A < B < C < D"},{"id":"D","text":"B < A < C < D"}]', 0, 'D', 'Since highly diluted KI is added into AgNO₃ solution, the resultant colloidal solution will be positive charged due to excess of Ag+.

This positively charged sol will be coagulated by anion of electrolyte.

Electrolyte having anion with higher negative charge will have more ease of coagulation.

Hence order will be

NaCl & BaSO₄ & Na₂PO₄ & K₄[Fe(CN)₆]', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.566Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3820, 'chemistry-2022-08-17', 'q12', 11, 11, 'Which of the following conditions can be used to change physical adsorption of a gas to chemical adsorption?', '[{"id":"A","text":"Decrease in temperature"},{"id":"B","text":"Increase in temperature"},{"id":"C","text":"Using catalyst"},{"id":"D","text":"Increasing surface area of adsorbent"}]', 0, 'B', 'On increasing the temperature, physical adsorption is converted to chemisorption as physisorption is an exothermic process.

