INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3843, 'chemistry-2022-08-17', 'q38', 34, 34, 'Which of the following monomeric pair is used to make polymer Nylon 6, 6?', '[{"id":"A","text":"Hexane-1, 6 dioic acid and Hexane-1, 6-diamine"},{"id":"B","text":"Ethane-1, 2-dioic acid and Benzene-1, 4-dicarboxylic Acid"},{"id":"C","text":"Urea and Methanal"},{"id":"D","text":"Phenol and Methanol"}]', 0, 'A', 'Nylon 6, 6 is formed by the condensation polymerisation of hexaethylene diamine with adipic acid under high pressure and at high temperature.

$$ \begin{align*}&\mathrm{nH_{2}N}-(\mathrm{CH_{2}})_{6}-\mathrm{NH_{2}}+\mathrm{nHOOC}-(\mathrm{CH_{2}})_{4}-\mathrm{COOH}\\&\quad\quad\quad\quad553\mathrm{K}\bigg|\bigg|_{{high~pressure}}\\&\quad\quad\quad(\mathrm{NH}-(\mathrm{CH_{2}})_{6}\mathrm{NH}-\mathrm{CO}-(\mathrm{CH_{2}})_{4}-\mathrm{CO})_{\pi}+\mathrm{nH_{2}O}\\&\quad\quad\quad\quad\mathrm{Nylon-6,6}\end{align*} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.570Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
