INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3848, 'chemistry-2022-08-17', 'q43', 39, 39, 'Adding a salt to water leads to increase in the boiling point of solution with respect to water because:', '[{"id":"A","text":"Vapour pressure of solution is increased"},{"id":"B","text":"Solubility of salt in water is increased"},{"id":"C","text":"Solubility of salt in water is decreased"},{"id":"D","text":"Vapour pressure of solution is decreased"}]', 0, 'D', 'On addition of salt to water, it will decrease the tendency to form vapour. Vapour pressure decreases as a result boiling point of solution increases.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.570Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
