INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3850, 'chemistry-2022-08-17', 'q45', 41, 41, 'Which of the following is a colligative property?', '[{"id":"A","text":"Vapour pressure"},{"id":"B","text":"Osmotic pressure"},{"id":"C","text":"Freezing point"},{"id":"D","text":"Boiling point Passage: Ethers are class of organic compounds that contain ether group - an oxygen atom connected to two alkyl groups or aryl groups. They have the general formula $ R-O-R'' $, where R and $ R'' $ represent the alkyl or aryl groups. Ether, like water have a tetrahedral geometry i.e., oxygen is $ sp^{3} $ hybridised. The C-O-C bond angle in ethers is slightly greater than the tetrahedral angle due to repulsive interactions between the two bulky groups when they are attached to oxygen."}]', 0, 'A', 'Osmotic pressure is a colligative property as it depends on the number of particles present in the solution.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.571Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
