INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3853, 'chemistry-2022-08-18', 'q01', 1, 1, 'Atoms of B forms fcc lattice and those of element A occupy alternate tetrahedral voids. The formula of the compound formed by elements A and B', '[{"id":"A","text":"$ AB_{2} $"},{"id":"B","text":"$ A_{2}B $"},{"id":"C","text":"AB"},{"id":"D","text":"$ A_{2}B_{3} $ (C) AB"}]', 0, 'C', 'Number of atom ''B'' forming Fcc lattice

$ =\frac{1}{8}\times8+\frac{1}{2}\times6=4 $

Number of atom ''A'' (Occupying alternate tetrahedral voids)

