INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3860, 'chemistry-2022-08-18', 'q09', 8, 8, 'Which of the following expression is correct for the rate of reaction given below:

$ 5\mathrm{Br}^{-}(aq) + \mathrm{BrO}_{3}^{-}(aq) + 6\mathrm{H}^{+} \rightarrow 3\mathrm{Br}_{2}(aq) + 3\mathrm{H}_{2}\mathrm{O}(l) $', '[{"id":"A","text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=5\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $"},{"id":"B","text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=\\frac{6}{5}\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $ $$ O B=\\frac{5}{1}O A $$"},{"id":"C","text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=\\frac{5}{6}\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $"},{"id":"D","text":"$ \\frac{\\Delta\\left[\\mathrm{Br}^{-}\\right]}{\\Delta t}=6\\frac{\\Delta\\left[\\mathrm{H}^{+}\\right]}{\\Delta t} $"}]', 0, 'C', 'Rate = $ \frac{-1}{5}\frac{\Delta[\mathrm{Br}^{-}]}{\Delta t} = \frac{-\Delta[\mathrm{BrO}_{3}^{-}]}{\Delta t} = \frac{-1}{6}\frac{\Delta[\mathrm{H}^{+}]}{\Delta t} $

$ \frac{1}{3}\frac{\Delta[\mathrm{Br}_{2}]}{\Delta t} = \frac{1}{3}\frac{\Delta[\mathrm{H}_{2}\mathrm{O}]}{\Delta t} $

$ \therefore \frac{\Delta[\mathrm{Br}^{-}]}{\Delta t} = \frac{5}{6}\frac{\Delta[\mathrm{H}^{+}]}{\Delta t} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.572Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
