INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3890, 'chemistry-2022-08-18', 'q45', 38, 38, 'Tranquilizers are the substances used for the treatments of', '[{"id":"A","text":"Cancer"},{"id":"B","text":"AIDS"},{"id":"C","text":"Mental diseases"},{"id":"D","text":"Physical disorder Passage Solubility of gases in liquids is greatly affected by pressure and temperature. Henry gave the quantitative relationship between pressure and solubility of gas in a solvent. According to Henry''s law, partial pressure of a gas above a liquid is directly proportional to its mole fraction in solution and is expressed as $P = K_{H}x$, where KH is Henry''s constant and x is mole fraction of gas. KH is a function of nature of gas. F M Raoult gave a quantitative relationship between partial pressures and mole fractions in the binary solution of volatile liquids. Raoult''s law states that for a binary solution of volatile liquids, the partial pressure of each component in the solution is directly proportional to its mole fraction. Thus for a solution of component 1 and 2, partial pressure of each component $ P_{1} = p_{1}^{0}x_{1} $, where $ p_{1}^{0} $ is the vapour pressure of pure component 1 at the same temperature. Similarly $ p_{2} = p_{2}^{0}x_{2} $"}]', 0, 'C', 'Tranquilizers are used for the treatments of mental diseases.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.575Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3891, 'chemistry-2022-08-18', 'q46', 39, 39, 'Solubility of Carbon dioxide in soda water increases with', '[{"id":"A","text":"Increase in pressure and temperature both"},{"id":"B","text":"Increase in pressure and decrease in temperature"},{"id":"C","text":"Decrease in pressure and increase in temperature"},{"id":"D","text":"Decrease in pressure and decrease in temperature"}]', 0, 'B', 'Solubility of CO $ _{2(g)} $ in water increases with increase in pressure and decrease in temperature.

