INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3892, 'chemistry-2022-08-18', 'q48', 40, 40, '$ K_{H} $ value for $ \mathrm{Ar(g)} $, $ \mathrm{CO(g)} $, $ \mathrm{HCHO(g)} $ and $ \mathrm{CH}_{4}(g) $ are 40.39, 1.67, $ 1.83 \times 10^{-5} $ and 0.413 respectively.

Identify the correct order of their increasing solubility in water', '[{"id":"A","text":"$ HCHO < CH_{4} < CO_{2} < Ar $"},{"id":"B","text":"$ HCHO < CO_{2} < CH_{4} < Ar $"},{"id":"C","text":"$ Ar < CO_{2} < CH_{4} < HCHO $"},{"id":"D","text":"$ Ar < CH_{4} < CO_{2} < HCHO $"}]', 0, 'C', 'Solubility of a gas in water varies inversely to its $ K_{H} $ value, so correct order of solubility is

$$ \mathrm{Ar}<\mathrm{CO}_{2}<\mathrm{CH}_{4}<\mathrm{HCHO} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.575Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3893, 'chemistry-2022-08-18', 'q49', 41, 41, 'If a solution exhibits positive deviation from Raoult''s Law then sign of $ \Delta_{\text{mix}} H $ and $ \Delta_{\text{mix}} V $ will be', '[{"id":"A","text":"$ \\Delta_{\\text{mix}} H = \\text{positive}; \\Delta_{\\text{mix}} V = \\text{positive} $"},{"id":"B","text":"$ \\Delta_{\\text{mix}} H = \\text{positive}; \\Delta_{\\text{mix}} V = \\text{negative} $"},{"id":"C","text":"$ \\Delta_{\\text{mix}} H = \\text{negative}; \\Delta_{\\text{mix}} V = \\text{positive} $"},{"id":"D","text":"$ \\Delta_{\\text{mix}} H = \\text{negative}; \\Delta_{\\text{mix}} V = \\text{negative} $"}]', 0, 'A', 'For a solution exhibiting positive deviation from Raoult''s law

$$ \Delta_{\mathrm{mix}}\mathrm{H}>0,\Delta_{\mathrm{mix}}\mathrm{V}>0 $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3894, 'chemistry-2022-08-18', 'q50', 42, 42, 'Henry''s law constant for O_{2} in water at 293 K is 46.82 bar. The mole fraction of oxygen in air is 0.21.

What mole fraction of oxygen is dissolved in 1 litre of water at 2.026 bar pressure and 293 K?', '[{"id":"A","text":"0.4254"},{"id":"B","text":"0.850"},{"id":"C","text":"0.018"},{"id":"D","text":"0.009"}]', 0, 'D', 'Partial pressure of $ O_{2} = 2.026 \times 0.21 $ = 0.425

Now, applying Henry''s law

$$ \mathbf{p}_{\mathrm{O}_{2}}=\mathrm{K}_{\mathrm{H}}\times\mathrm{X}_{\mathrm{O}_{2}} $$

$$ \therefore\quad X_{O_{2}}=\frac{p_{O_{2}}}{K_{H}}=\frac{0.425}{46.82}=0.009 $$

