INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3895, 'chemistry-2022-08-23', 'q01', 1, 1, 'Which of the following shows both Frenkel as well as Schottky defects?', '[{"id":"A","text":"AgBr"},{"id":"B","text":"NaCl"},{"id":"C","text":"KCl"},{"id":"D","text":"AgCl"}]', 0, 'A', 'AgBr shows both, Frenkel as well as Schottky defects.

(c) For hexagonal crystal system, $ a = b \neq c $ and $ \alpha = \beta = 90^{\circ}, \gamma = 120^{\circ} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3896, 'chemistry-2022-08-23', 'q03', 2, 2, 'Efficiency of packing in body centred cubic structures is found to be', '[{"id":"A","text":"33%"},{"id":"B","text":"74%"},{"id":"C","text":"52.4%"},{"id":"D","text":"68%"}]', 0, 'D', 'For body centred cubic structures, \sqrt{3}a = 4r

Packing efficiency

= $ \frac{\text{Volume occupied by two spheres in unit cell} \times 100}{\text{Volume of unit cell}} $

$ 2 \times \frac{4}{3} \pi r^{3} $

$ = \frac{a^{3}}{a^{3}} \times 100 = 68\% $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3897, 'chemistry-2022-08-23', 'q04', 3, 3, 'Observe the given graph and identify the correct statement for the solution.

$ x_1=1 $ Mole Fraction $ x_1=0 $

$ x_2=0 $ $ x_2 \longrightarrow x_2=1 $', '[{"id":"A","text":"Component 2 is more volatile than component 1"},{"id":"B","text":"Component 1 is more volatile than component 2"},{"id":"C","text":"Boiling point of component 1 is lower than that of component 2"},{"id":"D","text":"Volatility of a component depends upon its mole fraction"}]', 0, 'A', '$p_{1}^{0}$ and $p_{2}^{0}$ are the vapour pressures of pure component 1 and 2 respectively from the plot, $p_{2}^{0} > p_{1}^{0}$, that means component 2 is more volatile than component 1. So, boiling point of component 1 is greater than component 2.', NULL, 'null', '[]', '[{"id":"q04-figure-1","kind":"figure","path":"/local-papers/assets/chemistry-2022-08-23/q04-figure-1.jpg","page":1,"alt":"Figure for question 4"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3898, 'chemistry-2022-08-23', 'q05', 4, 4, '18 g of a non-volatile solution A is dissolved in 1 kg of water, the boiling point of water is raised to 373.51 K. Given $ K_{b} $ for water is 0.52 K kg mol $ ^{-1} $, boiling point for water is 373.15 K at 1.013 bar pressure.

The molecular weight of the solid A is', '[{"id":"A","text":"$ 58.0 \\, g \\, mol^{-1} $"},{"id":"B","text":"$ 26.0 \\, g \\, mol^{-1} $"},{"id":"C","text":"$ 55.0 \\, g \\, mol^{-1} $"},{"id":"D","text":"$ 110.0 \\, g \\, mol^{-1} $"}]', 0, 'B', '$ \Delta T_{b} = K_{b} \times m $ (where m is molality)

$ \Delta T_{b}=373.51-373.15=0.36K $

$ \therefore $ $ 0.36=0.52\times\frac{18}{M_{A}\times1}\Rightarrow M_{A}=26\ g\ mol^{-1} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3899, 'chemistry-2022-08-23', 'q06', 5, 5, 'Based on solute solvent interactions, arrange the following in the order of increasing solubility in n-octane.

A. Cyclohexane

B. KCl

C. $ \mathrm{CH_{3}OH} $

D. $ \mathrm{CH_{3}NH_{2}} $

E. $ \mathrm{CH_{3}CN} $', '[{"id":"A","text":"A < B < C < D < E"},{"id":"B","text":"B < C < E < D < A"},{"id":"C","text":"C < B < A < E < D"},{"id":"D","text":"B < C < D < E < A"}]', 0, 'D', 'According to like-dissolve-like theory, polar species are soluble with polar solvent and non-polar species are soluble with non-polar solvent. n-octane is non-polar in nature.

(A) Cyclohexane $ \rightarrow $ non-polar

(B) KCl $ \rightarrow $ highly polar

(C) CH_{3}OH $ \rightarrow $ polar

(D) CH_{3}NH_{2} $ \rightarrow $ polar

(E) CH_{3}CN $ \rightarrow $ less polar in nature.

So, correct order of solubility in n-octane is

B<C<D<E<A', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.576Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3900, 'chemistry-2022-08-23', 'q07', 6, 6, 'In a pseudo first order reaction, the rate constant', '[{"id":"A","text":"Is independent of the concentration of reactants"},{"id":"B","text":"Depends on concentration of reactants present in small quantity"},{"id":"C","text":"Depends on temperature"},{"id":"D","text":"Depends on concentration of reactants present in excess"}]', 0, 'D', 'In a pseudo first order reaction, rate constant depends on concentration of excess reagent.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.577Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3901, 'chemistry-2022-08-23', 'q08', 7, 7, 'When the temperature of a reaction is increased by $ 20^{\circ} $C, the rate of reaction increases by', '[{"id":"A","text":"3 times"},{"id":"B","text":"4 times"},{"id":"C","text":"2 times"},{"id":"D","text":"1.5 times"}]', 0, 'B', 'For a chemical reaction with rise in temperature by $ 10^{\circ} $C, the rate constant is nearly doubled. So, for $ 20^{\circ} $C rise in temperature, the rate constant increases by four times.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.577Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3902, 'chemistry-2022-08-23', 'q09', 8, 8, 'Observe the given graph. What will be the unit for the rate constant?', '[{"id":"A","text":"$ \\mathrm{mol L^{-1} s^{-1}} $"},{"id":"B","text":"$ \\mathrm{mol^{-1} L s^{-1}} $"},{"id":"C","text":"$ s^{-1} $"},{"id":"D","text":"$ \\mathrm{mol^{-2} L^{2} s^{-1}} $"}]', 0, 'C', 'For first order reaction

$$ \mathrm{k}=\frac{2.303}{\mathrm{t}}\log\frac{\left[\mathrm{R}\right]_{0}}{\left[\mathrm{R}\right]}\Longrightarrow\log\frac{\left[\mathrm{R}\right]_{0}}{\left[\mathrm{R}\right]}=\frac{\mathrm{k}}{2.303}\times\mathrm{t}. $$

\therefore \mathrm{Slope}=\frac{k}{2.303}, the given graph represents first order reaction.

Unit of rate constant = $ (\text{mol L}^{-1})^{1-1} $ s $ ^{-1} $ = s $ ^{-1} $.

(b) Let, rate = k[A]x [B]y

From data 1 in experiment,

$ 2 \times 10^{-3} = k[0.1]x [0.1]y $

...(i)

From data 2,

$ 4 \times 10^{-3} = k[0.2]x [0.2]y $

...(ii)

From data 3,

$ 2 \times 10^{-3} = k[0.1]x [0.2]y $

...(iii)

Dividing equation (i) and (iii)

$ \frac{2 \times 10^{-3}}{2 \times 10^{-3}} = \frac{k[0.1]x [0.1]y}{k[0.1]x [0.2]y} = \left(\frac{1}{2}\right)^y \Rightarrow y = 0 $

Put the value of y in equation (i) and (ii),

$ 2 \times 10^{-3} = k[0.1]x [0.1]0 $

...(iv)

$ 4 \times 10^{-3} = k[0.2]x [0.2]0 $

...(v)

Dividing equation (iv) and (v)

$ \frac{1}{2} = \left(\frac{0.1}{0.2}\right)^x \Rightarrow x = 1 $

So, overall order = x + y = 1 + 0 = 1', NULL, 'null', '[]', '[{"id":"q09-figure-1","kind":"figure","path":"/local-papers/assets/chemistry-2022-08-23/q09-figure-1.jpg","page":1,"alt":"Figure for question 9"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.577Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3903, 'chemistry-2022-08-23', 'q12', 9, 9, 'The colloids that cannot be easily coagulated are', '[{"id":"A","text":"Lyophobic colloids"},{"id":"B","text":"Lyophilic colloids"},{"id":"C","text":"Irreversible sols"},{"id":"D","text":"Associated colloids"}]', 0, 'B', 'Lyophilic colloids are quite stable and cannot be easily coagulated.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.577Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
