INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3932, 'chemistry-2022-08-23', 'q48', 38, 38, 'The emf of the cell Ag(s) | Ag⁺(1m) || Pb²⁺(1m) | Pb(s), is', '[{"id":"A","text":"0.67V"},{"id":"B","text":"1.06V"},{"id":"C","text":"0.93V"},{"id":"D","text":"0.93V"}]', 0, 'C', 'Anodic reaction: Ag $ \longrightarrow $ Ag $ ^{+} $ + e

Cathodic reaction: Pb $ ^{2+} $ + 2e $ \longrightarrow $ Pb.

Cell reaction: $ 2\mathrm{Ag} + \mathrm{Pb}^{2+} \longrightarrow \mathrm{Pb} + 2\mathrm{Ag}^{+} $

(s) (1m) (s) (1m)

$$ \begin{array}{rl}\therefore\quad\mathrm{E}_{\mathrm{cell}}=\mathrm{E}_{\mathrm{cell}}^{\circ}-\frac{\mathrm{RT}}{\mathrm{nF}}\ln\left[\frac{\mathrm{Ag}^{+}}{\mathrm{Pb}^{2+}}\right]^{2}\\=\mathrm{E}_{\mathrm{cell}}^{\circ}-\frac{2.303\mathrm{RT}}{2\mathrm{F}}2\log\left[\frac{\mathrm{Ag}^{+}}{\mathrm{Pb}^{2+}}\right]\\=\mathrm{E}_{\mathrm{cell}}^{\circ}-0.059\log\frac{1\mathrm{m}}{1\mathrm{m}}\\=\mathrm{E}_{\mathrm{cell}}^{\circ}\\=(-0.80-0.13)\mathrm{v}\quad=-0.93\mathrm{v}\end{array} $$', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.585Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3933, 'chemistry-2022-08-23', 'q49', 39, 39, 'When Pb is added to an aqueous solution of a mixture of $ Cu^{2+} $ and $ Mg^{2+} $ ions, it is', '[{"id":"A","text":"$ Cu^{2+} $ is reduced"},{"id":"B","text":"$ Mg^{2+} $ is reduced"},{"id":"C","text":"Cu is reduced"},{"id":"D","text":"$ Pb^{2+} $ is reduced"}]', 0, 'A', '$ E_{\text{red}}^{\circ} : Cu^{2+} > Pb^{2+} > Mg^{2+} $

$ Cu^{2+} $ will be reduced and $ Pb^{2+} $ will be oxidized, since the reduction potential of $ Cu^{2+} $ is more than $ Pb^{2+} $.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.585Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3934, 'chemistry-2022-08-23', 'q50', 40, 40, 'The combination of electrodes which will give maximum value of $E^{\circ}$ cell at 298 K is', '[{"id":"A","text":"Anode Cathode Ag Mg"},{"id":"B","text":"Anode Cathode Cu Fe"},{"id":"C","text":"Anode Cathode Mg Ag"},{"id":"D","text":"Anode Cathode Pb Mg $$ \\mathrm{form} \\cong \\mathrm{M} \\equiv \\frac{81}{1 \\times \\mathrm{A} \\mathrm{M}} \\times 52.0 = 85.0 $$ resonanz realog zweidst skl-svlosozib-sklf et gnibrozoA (b) zweicogz realog-non bns nvoloz zelog dfrw olduloz zs ni zelog-con ei omoo-n imvoloz zelog-non dfrw olduloz zuron (a) In筋柱上的筋柱侧向 $$ \\mathrm{t}=\\frac{k}{200\\mathrm{~S}}=\\frac{0\\left[R\\right]}{\\left[R\\right]}\\mathrm{gal}\\Leftarrow\\frac{0\\left[R\\right]}{\\left[R\\right]}\\mathrm{gal}\\frac{200\\mathrm{~S}}{1}=k $$"}]', 0, 'C', '$ E_{\text{cell}} = E_{\text{Mg/Mg}^{2+}} + E_{\text{Ag}^+/\text{Ag}} = 2.36 + 0.80 = 3.16 \, \text{V} $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:58:59.586Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3935, 'computer-science-2022', 'q01', 1, 1, 'Which of the following function(s) is/are SQL aggregate functions?

(A) Trim() (B) Max() (C) Count (D) Lower() (E) Avg()

Choose the correct answer from the options given below:

(a) (B) only (C) (B), (C) and (E) only (D) (B), (C), (D) and (E) only
2. Consider the given table and answer the question:

What will be the effect of following command?

Select Mname as "Name", Maddress as "residence" from Mother;', '[{"id":"A","text":"It will change the field headings temporarily Mname to Name and Maddress to residence."},{"id":"B","text":"It will give error message"},{"id":"C","text":"It will change all the Names, addresses to Name and residence"},{"id":"D","text":"It will change the field names Mname to name and Maddress to residence"}]', 0, 'C', 'Average function: It is used to perform calculations on multiple rows of a single column of a table. It is also used to summerise the data.

Sql aggregate function:

Count () → returns the no. of rows

Sum () → returns the sum

Avg () → returns the average value

Max () → returns the largest value

Min () → returns the smallest value

First () → returns the first value

Last () → returns the last value

In the given question Trim (), Lower (), are not aggregate function rest are aggregate function that is (B) Max. (c) Count (), (E) Avg ().

So option (c) B. C. E is our Answer.

So, option (c) B, C, E is our Answer.', NULL, 'null', '[]', '[{"id":"q01-table-1","kind":"table","path":"/local-papers/assets/computer-science-2022/q01-table-1.jpg","page":1,"alt":"Table for question 1"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.586Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3936, 'computer-science-2022', 'q03', 2, 2, 'To retrieve the given column from Mother table:

Name

Lata Sharma

Lovely Singh

Lavanya Mehra

The correct command is:', '[{"id":"A","text":"Select Mname from Mother Where Mname is ''Lata Sharma'', ''Lovely Singh'', ''Lavanya Mehra''."},{"id":"B","text":"Select Mname from Mother where Mname like ''%L'';"},{"id":"C","text":"Select Mname from Mother where Mname like ''L%'';"},{"id":"D","text":"Select Mname from Mother starting with L;"}]', 0, 'C', 'Select Mname from Mother whose Mname like ''L%''; is correct because. ''Like'' is logical operator is sql.

- Like is used in SELECT, UPDATE and DELETE statements only.

- It filter the record from columns based on pattern specified in sql query. This can be done by using two wild card operator with keyword "like"

(i) % (percent sign) → matches zero, one, or more than one character.

(ii) _ (underscore) → matches only single character. Select Column i, column ii, column X from table Name where column LIKE pattern

Option (i) and (iv) are invalid queries.

Option (ii) will give Mname having word end''s with ''L''

Only (iii) is correct it will give these names only which starts with letter ''L'' only.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.586Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3937, 'computer-science-2022', 'q04', 3, 3, 'Which of the following query will change the name - ''Lata Sharma'' to ''Elina''?', '[{"id":"A","text":"Update Mother where Mname = ''Lata Sharma'';"},{"id":"B","text":"Update Mother set Mname = ''Elina'' where Mname = ''Lata Sharma'';"},{"id":"C","text":"Alter table Mother set Mname = ''Elina'' where Mname = ''Lata Sharma'';"},{"id":"D","text":"Alter table Mname = ''Elina'' where Mname = ''Lata Sharma'';"}]', 0, 'B', 'Update syntax

Update table-name SET column = value - 1, column = value 2..... where condition:

So, option (b) is correct.

