INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3939, 'computer-science-2022', 'q06', 5, 5, 'Identify an application software which is required by a client to request any resource and to receive response of his request out of the following:', '[{"id":"A","text":"Google"},{"id":"B","text":"Web Browser"},{"id":"C","text":"Website"},{"id":"D","text":"Web Page"}]', 0, 'B', 'i. Google is search engine it is not any application software.

