INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3940, 'computer-science-2022', 'q07', 6, 6, 'What is the output of the code given below?

List = [1, 2, 3]

List[3]', '[{"id":"A","text":"NameError"},{"id":"B","text":"ValueError"},{"id":"C","text":"IndexError"},{"id":"D","text":"No Error, it will"}]', 0, 'C', 'Index Error

List = [1, 2, 3]

List [3]

If we have a list 1, 2, 3, 4, 5 in python then the index starts from (0) and goes to (length -1).

- The first element of the list is stored at 0th index second element stored at $ 1^{th} $ index and so on.

So, List [0] gives 1

List [i] gives 2

List [2] gives 3

[List [3] gives 4] But we have only [1, 2, 3] in the list.

So, it will give error which is indexing error name [#index Error.]', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.587Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
