- Radio wave have high wavelength and low frequency

Radio waves are used in RADAR, Satellite, air to air contact between planes etc.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.588Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3942, 'computer-science-2022', 'q09', 8, 8, 'Which of the following access mode is used to open binary file in read mode only?', '[{"id":"A","text":"wb"},{"id":"B","text":"a"},{"id":"C","text":"rb"},{"id":"D","text":"r"}]', 0, 'C', 'wb $ \rightarrow $ ''wb'' mode opens the file in binary formed for writing

