INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3949, 'computer-science-2022', 'q16', 15, 15, 'Tamisha has written SQL queries and used several functions that take numeric values as input and return a numeric value as result. Identify the category of function of SQL used for the above:', '[{"id":"A","text":"String"},{"id":"B","text":"Math"},{"id":"C","text":"Data and Time"},{"id":"D","text":"Integer"}]', 0, 'B', 'String and Integer is a data type not a function. So, eliminated. Because in the given statement Tamisha has written SQL queries and used several function that take numeric input and return numeric output. The only correct option is ''math'' function.

$\because$ Mathematical functions in SQL.

ABS(), Log10(), Power(), cos(), Sin(), Tan(), Log(), Radians(), Pi() etc.

