Timestamp - format: YYYY-MM-DD HH:MI:SS

Year - format: YYYY or YY', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.590Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
