INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3974, 'english-2022-08-06-shift-1', 'q01', 1, 1, 'Match List I with List II', '[{"id":"A","text":"A-IV, B-III, C-II, D-I"},{"id":"B","text":"A-III, B-II, C-I, D-IV"},{"id":"C","text":"A-I, B-III, C-II, D-IV"},{"id":"D","text":"A-II, B-I, C-IV, D-III"}]', 0, 'B', NULL, NULL, 'null', '[]', '[{"id":"q01-table-1","kind":"table","path":"/local-papers/assets/english-2022-08-06-shift-1/q01-table-1.jpg","page":1,"alt":"Table for question 1"}]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.594Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3975, 'english-2022-08-06-shift-1', 'q02', 2, 2, 'The two protagonists of the story are _ (Select the correct option)', '[{"id":"A","text":"Both innocent and naive"},{"id":"B","text":"One is intelligent and the other a fool"},{"id":"C","text":"Both cunning and selfish"},{"id":"D","text":"One of them is demanding and greedy, the other always generous, sensitive and supportive"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.595Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3976, 'english-2022-08-06-shift-1', 'q03', 3, 3, 'How were the tree and the little boy related to each other? (Select the correct option)', '[{"id":"A","text":"They were close contenders in their race to survive"},{"id":"B","text":"They were very close friends due to their very long association"},{"id":"C","text":"They were colleagues as they work together"},{"id":"D","text":"They were competitors in their need to fulfil their own needs."}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.595Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3977, 'english-2022-08-06-shift-1', 'q04', 4, 4, 'The story highlights a typical selfish human nature we are all familiar with. Identify it from the options given below:', '[{"id":"A","text":"Compassion and benevolence"},{"id":"B","text":"Conservation of forests"},{"id":"C","text":"Mindless greed to possess more and more wealth"},{"id":"D","text":"Heartless and foolish exploitation of nature"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.596Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3978, 'english-2022-08-06-shift-1', 'q05', 5, 5, '"The stump of the unselfish tree burnt in the fire, softly humming a tune." means: (Select the right options from the given options)', '[{"id":"A","text":"Every tree sings when it is burnt."},{"id":"B","text":"The selfless tree felt no pain even in its acute suffering while dying, caring for others."},{"id":"C","text":"The frail and wonderful tree fifed to forget its pain by humming"},{"id":"D","text":"The tree was a fool and was humming as it did not realize that it was dying."}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.596Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3979, 'english-2022-08-06-shift-1', 'q06', 6, 6, 'How would you define the relationship that the story illustrates? Select the correct answer from the following options.', '[{"id":"A","text":"It was a mutual symbiotic relationship."},{"id":"B","text":"It was a relationship based on deceit and treachery."},{"id":"C","text":"It was an one sided relationship where the tree loved, cared for and supported the boy till its end."},{"id":"D","text":"It was a disguised enmity. After reading the following passage, answer the questions which follow: I must say that beyond occasionally exposing me to laughter, my constitutional shyness has been of no great disadvantage to me. In fact, I can see that, on the contrary, it has been all to my advantage. My hesitancy in speech, which was once an annoyance, is now a pleasure. Its greatest pleasure has been that it has taught me the economy of words. I have naturally formed the habit of restraining my thoughts. And I can now give myself the certificate that a thoughtless word hardly ever escapes of my tongue or pen. I do not recollect ever having had to regret anything in my speech or writing. I have thus been spared many a mishap and waste of time. Experience has taught me that silence is part of the spiritual discipline of a votary of truth. Proneness to exaggerate, to suppress or modify the truth, wittingly or unwittingly, is a natural weakness of man and silence is necessary in order to surmount it. A man of few words will rarely be thoughtless in his speech; he will measure every word."}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.598Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3980, 'english-2022-08-06-shift-1', 'q07', 7, 7, 'The expression, "my constitutional shyness" in the given passage would mean _(Select the right answer from the options given below):', '[{"id":"A","text":"Shyness mentioned in Article 1 in the Indian Constitution"},{"id":"B","text":"Shyness prescribed as a mark of our democracy in the preamble of our Constitution."},{"id":"C","text":"The innate and natural shyness in the author"},{"id":"D","text":"A shyness that the author pretends to derive some evil advantages in life."}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.598Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3981, 'english-2022-08-06-shift-1', 'q08', 8, 8, 'The author as a matured individual believes that his shy nature brought him _ (Select the right answer from the options given below):', '[{"id":"A","text":"Great advantage in life"},{"id":"B","text":"Unmatched joy and enchantment in life"},{"id":"C","text":"Disadvantage while performing rituals"},{"id":"D","text":"Media coverage"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.598Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3982, 'english-2022-08-06-shift-1', 'q09', 9, 9, 'From the options given below, select the one which will appropriately answer the following question: The author due to his shy nature _', '[{"id":"A","text":"Would aggressively attack any and every crowd around him"},{"id":"B","text":"Worked hard to hide his stammer"},{"id":"C","text":"Naturally formed the habit of restraining his thoughts"},{"id":"D","text":"Became an ascetic."}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.599Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3983, 'english-2022-08-06-shift-1', 'q10', 10, 10, 'The author claims that _(Select the right answer from the options given below):', '[{"id":"A","text":"He has rarely even spoken a ''thoughtless word due to his shy nature"},{"id":"B","text":"He always speaks without thinking because he is shy"},{"id":"C","text":"As a shy individual, he has become prone to nightmares"},{"id":"D","text":"His shy nature helped him become a great cricket player."}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.599Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3984, 'english-2022-08-06-shift-1', 'q11', 11, 11, 'From the options given below, select the one which answer the following question: Experience has taught the author that', '[{"id":"A","text":"Silence is better than laughter to stay fit"},{"id":"B","text":"Silence is part of the spiritual discipline"},{"id":"C","text":"Silence is to be avoided at all costs"},{"id":"D","text":"Silence can never be attained by man"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.599Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3985, 'english-2022-08-06-shift-1', 'q12', 12, 12, 'Match List I with List II', '[{"id":"A","text":"A-IV, B-III, C-II, D-I"},{"id":"B","text":"A-II, B-I, C-IV, D-III"},{"id":"C","text":"A - III, B - IV, C - I, D - II"},{"id":"D","text":"A-I, B-II, C-III, D-IV After reading the passage, answer the questions that follow: Unhappiness and discontent spring not only from poverty. Man is a strange creature, fundamentally different from other animals. He has far horizons, invincible hopes, creative energies, spiritual powers. If they are left undeveloped and unsatisfied, he may have all the comforts which wealth can give, but will still feel that life is not worthwhile. The great humanist writers, Shaw and Wells, Arnold Bennett and Galsworthy, who are regarded as the prophets of the dawn, expose the foibles, inconsistencies and weaknesses of modern life, but they ignore the deeper currents and sometimes misrepresent them. At any rate, they give nothing in their place. In the void left by the removal of tradition, morality and religion, others are putting in vague sentiments of race and power. The modern mind is shaped by Rousseau''s Social Contract, Marx''s Capital, Darwin''s on the Origin of Species and Spengler''s The Decline of the West. The outward chaos and confusion of our life reflect the confusion of our hearts and minds. Constitutions, says Plato, \"are but the reflections in the outside world of the values which prevail in men''s minds.\" There must be a change in the ideals we cherish, in the values we adopt, before we can give social expression to them. We help to secure the future only to the extent to which we ourselves are changed. What is missing in our age is the soul: there is nothing wrong with the body. We suffer from sickness of spirit. We must discover our roots in the eternal and regain faith in the transcendent truth which will order life, discipline discordant elements, and bring unity and purpose into it. If not, when the floods come and the winds blow and beat upon our houses, it will fall."}]', 0, 'D', NULL, NULL, 'null', '[]', '[{"id":"q12-table-1","kind":"table","path":"/local-papers/assets/english-2022-08-06-shift-1/q12-table-1.jpg","page":2,"alt":"Table for question 12"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.600Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3986, 'english-2022-08-06-shift-1', 'q13', 13, 13, 'The author implies that if the eternal values and ideals are not regained, then _(Select the right option)', '[{"id":"A","text":"The world will be flooded"},{"id":"B","text":"The sky will fall"},{"id":"C","text":"The human civilization and society will be mined forever"},{"id":"D","text":"The earth Will get sucked into a black hole"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.600Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3987, 'english-2022-08-06-shift-1', 'q14', 14, 14, 'According to the author, the humanist writers have ignored _ (Select the correct option)', '[{"id":"A","text":"The spiritual aspect of life"},{"id":"B","text":"Religion and rituals"},{"id":"C","text":"Cultural progress"},{"id":"D","text":"Material welfare"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.600Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3988, 'english-2022-08-06-shift-1', 'q15', 15, 15, 'According to the author, how is man different from other animals? (Select the correct option)', '[{"id":"A","text":"Because of his unique power of speech"},{"id":"B","text":"In his hopes, creative-energies and spiritual powers"},{"id":"C","text":"In money and the material achievements of man"},{"id":"D","text":"In his physical prowess"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.600Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (3989, 'english-2022-08-06-shift-1', 'q16', 16, 16, 'According to the author, unhappiness and discontent spring from _ Select the right option.

(a) Poverty alone

(b) Ignorance

(c) Poverty along with the moral and spiritual degradation of man

