INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4129, 'english-2022-08-18', 'q12', 12, 10, 'Match list I with list II

List I

A. In 1878

B. In Colonial India

C. The Hindu

D. 900,000

List II

I. The Hindu was established as a weekly

II. The Hindu spoke of Indian Independence

III. Built a network of foreign bureaus while still spreading its national coverage.

IV. Daily circulation of The Hindu at the beginning of the 21st century', '[{"id":"A","text":"A-IV, B-III, C-I, D-II"},{"id":"B","text":"A-I, B-II, C-III, D-IV"},{"id":"C","text":"A-II, B-III, C-IV, D-I"},{"id":"D","text":"A-IV, B-III, C-II, D-, DIRECTIONS (Q. 13-18): Read carefully the following passage and then answer the questions given below: Karnad has gone significantly back to Indian tradition and culture to write his plays. He has recreated the rich and dynamic picture of Indian society, culture and its people. He often takes a theme, a historical event of Indian history and present it in a modernized way. Majority of his plays employ narratives of myths, history and folklore to evoke an ancient or pre-modern era in the image of present. He has also adopted the oral tale of the people and present it in myths and folk forms in his plays. Thus, he creates a synthesis between the ancient and the modern to serve his purpose of using the past to illuminate the present. Most of the playwrights in India have either written in such a traditional manner that it has lost relevance to their urban existence, or they have written in such an urbanized manner that it lost its relevance to the traditional part of personality. In this regard, Karnad comments \"we keep acerbating between the traditional and the modern, perhaps we would not hit upon a form which could balance both.\" He attempts to balance both in his plays. He does not take myths in their entirety, but he takes them only in parts that are useful to him and the rest he supplements with his imagination. Basically, he has given a new interpretation to the historical, oral and mythical tales."}]', 0, 'B', 'Here elimination method can save a lot of time.

Step 1: Let''s try to match fragment A with the fragments in list II. A matches with I.

Step 2: Let''s see which option/options has/have A matching with I. It''s only one b. Hence the answer is b.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.617Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
