INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4143, 'english-2022-08-18', 'q27', 27, 24, 'Re-arrange the given jumbled groups of words to make a meaningful sentence

A. The robbers when

B. They were in the lonely place

C. The police come upon

D. Dividing their booty', '[{"id":"A","text":"D, B, C, A"},{"id":"B","text":"B, C, A, D"},{"id":"C","text":"C, A, B, D"},{"id":"D","text":"D, C, B, A"}]', 0, 'C', 'Step 1: Let''s try to arrange the sentence according to the options. Option a is wrong because the nonfinite clause "dividing their booty" cannot meaningfully modify the pronoun "they". It will be a dangling modifier. Option b is wrong because to put the fragment C after fragment B we need a conjunction or a punctuation. Option d is wrong because it would erroneously mean the police were dividing the booty. The correct option is (c).

Sequence: The police came upon the robbers when they were in the lonely place dividing their booty.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.619Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4144, 'english-2022-08-18', 'q28', 28, 25, 'Rearrange the jumbled groups of words to make a meaningful sentence

A. On the tools you had been taught

B. The problem you face become more constructed

C. In management as you rise higher

D. And you can''t afford to fall back', '[{"id":"A","text":"B, A, C, D"},{"id":"B","text":"C, A, D, B"},{"id":"C","text":"C, B, D, A"},{"id":"D","text":"A, B, C, D"}]', 0, 'C', 'Step 1: Let''s try to arrange the sentences according to the options. Option a is wrong because putting fragment A after fragment B doesn''t create any meaning ("constructor" means something which is obsolete). Option b is wrong because if we put fragment A after C it would mean that the sentence is talking about rising higher on tools which is again not meaningful. Option d is wrong because it would mean that the hypothetical person, "you" has been taught problems on the tools which is again not meaningful. The correct answer is option (c). Correct sequence: In management as you rise higher the problem you face become more constructed and you can''t afford to fall back on the tools you had been thought.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:58:59.619Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
