INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4213, 'general-test-2022-08-06', 'q01', 1, 1, 'Given set is (2, 17, 31) is set of:

(A) Prime numbers (B) Whole numbers

(C) Odd numbers (D) Even numbers', '[{"id":"A","text":"(A) only"},{"id":"B","text":"(A) and (B) only"},{"id":"C","text":"(B) only"},{"id":"D","text":"(C) and (D) only"}]', 0, 'B', 'The given set (2, 17, 31) is both prime and whole numbers.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.627Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4214, 'general-test-2022-08-06', 'q02', 2, 2, 'Which of the following represents x, y = 64?', '[{"id":"A","text":"$ 8 : x = 8 : y $"},{"id":"B","text":"x : 8 = y : 8"},{"id":"C","text":"x : 16 = y : 4"},{"id":"D","text":"32 : x = y : 2"}]', 0, 'D', 'Solve using options:

32: x = y: 2

$ \Rightarrow \frac{32}{x} = \frac{y}{2} \Rightarrow 32 \times 2 = x \cdot y $

$ \Rightarrow x \cdot y = 64 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.627Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4215, 'general-test-2022-08-06', 'q03', 3, 3, 'Ratio $5^{8.14}:5^{5.14}$ is equal to:', '[{"id":"A","text":"1:5"},{"id":"B","text":"5:1"},{"id":"C","text":"25:1"},{"id":"D","text":"125:1"}]', 0, 'D', '$ 5^{8.14} : 5^{5.14} $

$ \Rightarrow \frac{5^{8.14}}{5^{5.14}} = \frac{5^{(8.14-5.14)}}{1} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.627Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4216, 'general-test-2022-08-06', 'q04', 4, 4, 'The LCM and HCF of two numbers are 35 and 15 respectively. The product of these numbers is _.', '[{"id":"A","text":"625"},{"id":"B","text":"525"},{"id":"C","text":"425"},{"id":"D","text":"325"}]', 0, 'B', 'Product of two number = HCF × LCM

= 15 × 35

= 525', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.627Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4217, 'general-test-2022-08-06', 'q05', 5, 5, 'The value of $3-3 \div 3$:', '[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"0"},{"id":"D","text":"1"}]', 0, 'A', '$ 3 - 3 \div 3 = 3 - \frac{3}{3} = 3 - 1 = 2 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4218, 'general-test-2022-08-06', 'q07', 6, 6, 'The sum of the ages of 5 children born at intervals of 3 years each is 50 years. What is the age of the youngest child?', '[{"id":"A","text":"4 years"},{"id":"B","text":"7 years"},{"id":"C","text":"9 years"},{"id":"D","text":"10 years"}]', 0, 'A', 'Let ages of 5 children are x, x + 3, x + 6, x + 9 and x + 12 years.

According to question

$ x + x + 3 + 6 + x + 12 = 50 $

$ \Rightarrow 5x = 50 - 30 $

$ \Rightarrow 5x = 20 $

$ \Rightarrow x = 4 $ years (age of youngest child)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4219, 'general-test-2022-08-06', 'q08', 7, 7, 'The average of 3 even consecutive integers is 12. What is their product?', '[{"id":"A","text":"1640"},{"id":"B","text":"1690"},{"id":"C","text":"1650"},{"id":"D","text":"1680"}]', 0, 'D', 'Let 3 even consecutive integers are x, x + 2, x + 4.

According to question,

$ \frac{x + x + 2 + x + 4}{3} = 12 $

$ \Rightarrow 3x + 6 = 36 $

$ \Rightarrow 3x = 36 - 6 = 30 $

$ \Rightarrow x = 10 $

Hence, their product = 10 × (10 + 2) × (10 + 4) = 1680', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4220, 'general-test-2022-08-06', 'q09', 8, 8, 'Find the average of following numbers.', '[{"id":"A","text":"18.25"},{"id":"B","text":"12.5"},{"id":"C","text":"19.1"},{"id":"D","text":"16.1"}]', 0, 'C', 'Required average = $ \frac{\text{Sum of all numbers}}{Total given numbers} $

$ \frac{191}{10} = 19.1 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4221, 'general-test-2022-08-06', 'q10', 9, 9, 'What percent decrease in salaries would exactly cancel the 20 percent increase?', '[{"id":"A","text":"$15\\frac{1}{3}\\%$"},{"id":"B","text":"$14\\frac{2}{3}\\%$"},{"id":"C","text":"$16\\frac{2}{3}\\%$"},{"id":"D","text":"$33\\frac{1}{3}\\%$"}]', 0, 'C', 'Let salary is 100.

$ \therefore \text{Increased salary} = \frac{100 \times 120}{100} = 120 $

120 - 100

$$ {\text{centage}}={\frac{120-100}{120}}\times100 $$

$$=\frac{20}{120}\times100$$

$$=16\frac{2}{3}\%$$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4222, 'general-test-2022-08-06', 'q11', 10, 10, 'If 20% of a number is 30, then the number is:', '[{"id":"A","text":"6"},{"id":"B","text":"150"},{"id":"C","text":"60"},{"id":"D","text":"15"}]', 0, 'B', 'Let number is x.

According to question,

$ \frac{x \times 20}{100} = 30 $

$ \Rightarrow x = 30 \times 5 = 150 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4223, 'general-test-2022-08-06', 'q12', 11, 11, 'An amount becomes its 3 times in 20 years. What is the rate of simple interest per annum?', '[{"id":"A","text":"15%"},{"id":"B","text":"10%"},{"id":"C","text":"6.67%"},{"id":"D","text":"6%"}]', 0, 'B', 'Let principal = a

$ \therefore $ Amount = 3a

S.I. = Amount - Principal

= 3a - a = 2a

$ \therefore $ S.I. = $ \left(\frac{P \times R \times T}{100}\right) $

2a = $ \left(\frac{a \times R \times 20}{100}\right) $

$ \Rightarrow $ Rate = $ \left(\frac{2a \times 100}{a \times 20}\right) $ % = 10% (Simple interest)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.628Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4224, 'general-test-2022-08-06', 'q13', 12, 12, 'What will be the simple interest earned on an amount of

22000 in 8 months at $8\frac{1}{4}\%$ per annum?', '[{"id":"A","text":"1013"},{"id":"B","text":"1012"},{"id":"C","text":"1210"},{"id":"D","text":"1215"}]', 0, 'C', 'Principal = ₹ 22000

Rate = 8\frac{1}{4} = \frac{33}{4}\%

Time = 8 month = \frac{8}{12} = \frac{2}{3} years

Hence, S.I = \frac{P \times R \times T}{100}

= \frac{22000 \times 33 \times 2}{4 \times 3 \times 100} = ₹ 1210', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.629Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4225, 'general-test-2022-08-06', 'q14', 13, 13, 'P, Q and R can complete a work in 12, 9 and 15 days respectively. Working together, they will complete the same work in:', '[{"id":"A","text":"$ 3\\frac{39}{47} $ days"},{"id":"B","text":"$ 5\\frac{15}{42} $ days"},{"id":"C","text":"$ 3\\frac{38}{47} $ days"},{"id":"D","text":"$ 5\\frac{39}{47} $ days"}]', 0, 'A', 'P''s one day work = $\frac{1}{12}$

Q''s one day work = $\frac{1}{9}$

R''s one day work = $\frac{1}{15}$

$\therefore (P+Q+R)''s$ one day work = $\frac{1}{12}+\frac{1}{9}+\frac{1}{15}$

$=\frac{15+20+12}{180}=\frac{47}{180}$

Hence, all together complete the same work in

$=\frac{180}{47}=3\frac{39}{47}$ days.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.630Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4226, 'general-test-2022-08-06', 'q15', 14, 14, 'If 36 farmers can do a piece of work in 24 hours, In how many hours will 18 farmers do it?', '[{"id":"A","text":"36 hours"},{"id":"B","text":"42 hours"},{"id":"C","text":"48 hours"},{"id":"D","text":"56 hours"}]', 0, 'C', 'According to question,

$ M_{1} \times H_{1} = M_{2} \times H_{2} $

$ \Rightarrow 36 \times 24 = 18 \times H_{2} $

$ \Rightarrow H_{2} = \frac{36 \times 24}{18} = 48 \text{ hours} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.630Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4227, 'general-test-2022-08-06', 'q16', 15, 15, 'A 400 m long train passes a railway platform in 20 seconds with speed 90 km/hr. What is the length of platform?', '[{"id":"A","text":"105 m"},{"id":"B","text":"102 m"},{"id":"C","text":"99 m"},{"id":"D","text":"100 m"}]', 0, 'D', 'Given, $ L_{1}=400\ m $

$ L_{2}= $ Length of platform = ?

T=20 sec

Train''s speed = 90 km/hr = $ 90 \times \frac{5}{18} = 25 $ m/s

According to question,

$ T=\frac{L_{1}+L_{2}}{S} $

$ \Rightarrow 20=\frac{400+L_{2}}{25} $

$ \Rightarrow 500=400+L_{2} $

$ \Rightarrow L_{2}=100m $ (Platform length)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.630Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4228, 'general-test-2022-08-06', 'q17', 16, 16, 'Consider a watch becomes fast by 10 minutes everyday. By what percent does it become fast?', '[{"id":"A","text":"$ \\frac{5}{12} $%"},{"id":"B","text":"$ \\frac{1}{6} $%"},{"id":"C","text":"$ \\frac{25}{36} $%"},{"id":"D","text":"2.5%"}]', 0, 'C', 'Total minute in one day = 24 $ \times $ 60 = 1440 min.

Watch gain = 10 min every day

Hence, watch becomes fast = $ \frac{10}{1440} $ $ \times $ 100

$ =\frac{100}{144}=\frac{25}{36}\% $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.630Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4229, 'general-test-2022-08-06', 'q18', 17, 17, 'Please read the following carefully and answer the questions:

The marks of 7 students in a unit test are given below:

9, 10, 7, 6, 9, 3, 5

The mode of the data is:', '[{"id":"A","text":"7"},{"id":"B","text":"9"},{"id":"C","text":"10"},{"id":"D","text":"6"}]', 0, 'B', 'Arrange data in sequence = 3, 5, 6, 7, 9, 9, 10

As only digit 9 repeat twice.

Hence, Mode = 9.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4230, 'general-test-2022-08-06', 'q19', 18, 18, 'Please read the following carefully and answer the questions:

The marks of 7 students in a unit test are given below:

9, 10, 7, 6, 9, 3, 5

Median of the data is:', '[{"id":"A","text":"6"},{"id":"B","text":"10"},{"id":"C","text":"9"},{"id":"D","text":"7"}]', 0, 'D', 'Arrange date in Ascending order

3, 5, 6, 7, 9, 9, 10

Number of observation = 7 (odd)

$ \therefore \frac{n+1}{2} = \frac{7+1}{2} = \frac{8}{2} = 4 $th observation

Hence, Median = 7', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4231, 'general-test-2022-08-06', 'q20', 19, 19, 'Please read the following carefully and answer the questions:

The marks of 7 students in a unit test are given below:

9,10,7,6,9,3,5

Mean of the data is :', '[{"id":"A","text":"9"},{"id":"B","text":"10"},{"id":"C","text":"7"},{"id":"D","text":"6"}]', 0, 'C', 'Given Data = 9, 10, 7, 6, 9, 3, 5

Hence, Mean = $ \frac{\text{Sum of all numbers}}{\text{Total numbers}} = \frac{49}{7} = 7 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4232, 'general-test-2022-08-06', 'q21', 20, 20, 'The value of x in the equation $2x-3=7-3x$', '[{"id":"A","text":"10"},{"id":"B","text":"2"},{"id":"C","text":"2"},{"id":"D","text":"5"}]', 0, 'B', '$ 2x - 3 = 7 - 3x $

$ \Rightarrow 2x + 3x = 7 + 3 $

$ \Rightarrow 5x = 10 $

$ \Rightarrow x = 2 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.631Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4233, 'general-test-2022-08-06', 'q22', 21, 21, 'If lengths of two diagonals of rectangle are $(2x-3)$ cm and $(x+2)$ cm, then the value of $x$ is:', '[{"id":"A","text":"1"},{"id":"B","text":"5"},{"id":"C","text":"$\\frac{5}{2}$"},{"id":"D","text":"$\\frac{5}{3}$"}]', 0, 'B', 'We know that length of diagonals of Rectangle are same.

$ \therefore 2x-3=x+2 $

$ \Rightarrow 2x-x=2+3 $

$ \Rightarrow x=5\ cm. $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4234, 'general-test-2022-08-06', 'q23', 22, 22, 'If a square has a diagonal of length $ 6\sqrt{2} $ cm, then the area of square is:', '[{"id":"A","text":"$ 48\\ cm^{2} $"},{"id":"B","text":"$ 72\\ cm^{2} $"},{"id":"C","text":"$ 16\\ cm^{2} $"},{"id":"D","text":"$ 36\\ cm^{2} $"}]', 0, 'D', 'As we know that,

Side of square = $ \frac{\text{Diagonal}}{\sqrt{2}} $ = $ \frac{6\sqrt{2}}{\sqrt{2}} $ = 6 cm

Hence, area of square = (side) $ ^2 $= (6) $ ^2 $ = 36 cm $ ^2 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4235, 'general-test-2022-08-06', 'q24', 23, 23, 'Please read the following carefully and answer the questions:

In the given figure ABCD is square and OE = 7 cm.

The perimeter of the figure is:', '[{"id":"A","text":"42 cm"},{"id":"B","text":"44 cm"},{"id":"C","text":"64 cm"},{"id":"D","text":"86 cm"}]', 0, 'C', 'Perimeter of semi-circle = $ \pi r = \frac{22}{7} \times 7 = 22 $ cm

Side of square (AD) = 7 + 7 = 14 cm.

Hence, perimeter of figure = 22 + DC + CB + BA = 22 + 14 + 14 + 14

=64 cm', NULL, 'null', '[]', '[{"id":"q24-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-08-06/q24-figure-1.jpg","page":2,"alt":"Figure for question 24"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4236, 'general-test-2022-08-06', 'q25', 24, 24, 'Please read the following carefully and answer the questions:

In the given figure ABCD is square and OE = 7 cm.

Length of diagonal of the square is :', '[{"id":"A","text":"$ 14\\sqrt{2} $ cm"},{"id":"B","text":"$ 7\\sqrt{2} $ cm"},{"id":"C","text":"14 cm"},{"id":"D","text":"7 cm"}]', 0, 'A', 'Side of square (AD) = 14 cm

Hence, length of diagonal = $ \sqrt{2} \times $ side

= $ 14\sqrt{2} $ cm', NULL, 'null', '[]', '[{"id":"q25-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-08-06/q25-figure-1.jpg","page":2,"alt":"Figure for question 25"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4237, 'general-test-2022-08-06', 'q26', 25, 25, 'Please read the following carefully and answer the questions: In the given ABCD is a square and OE = 7 cm

Area covered by the figure is:', '[{"id":"A","text":"350 cm²"},{"id":"B","text":"273 cm²"},{"id":"C","text":"372 cm²"},{"id":"D","text":"237 cm²"}]', 0, 'B', 'Side of square (AD) = 14 cm

$ \therefore $ Area of semicircle = $ \frac{1}{2}\pi r^{2} = \frac{1}{2} \times \frac{22}{7} \times 7 \times 7 = 77 \, cm^{2} $

And, area of square = (side) $ ^{2} $ = 14 $ ^{2} $ = 196 cm $ ^{2} $

Hence, area covered by figure = 77 + 196

= 273 cm $ ^{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.632Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4238, 'general-test-2022-08-06', 'q27', 26, 26, 'If two adjacent angles of a parallelogram are $(2x+30)^{\circ}$ and $(3x-15)^{\circ}$. Then the value of $x$ is:', '[{"id":"A","text":"36"},{"id":"B","text":"39"},{"id":"C","text":"33"},{"id":"D","text":"35 General Mental Ability & Logical and Analytical Reasoning"}]', 0, 'C', 'As we know that sum of two adjacent angle of parellogram is 180^{\circ}.

$ \therefore (2x+30)+(3x-15)=180^{\circ} $

$ \Rightarrow 5x+15=180^{\circ} $

$ \Rightarrow 5x=180-15=165^{\circ} $

$ \Rightarrow x=\frac{165}{5}=33^{\circ} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.633Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
