INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4286, 'general-test-2022-08-08-shift-1', 'q04', 4, 4, 'The Reserve Bank of India has authorized _ to collect direct taxes on behalf of the Central Board of Direct Taxes (CBDT).', '[{"id":"A","text":"Karur Vysya Bank (KVB)"},{"id":"B","text":"ICICI Bank"},{"id":"C","text":"HDFC Bank"},{"id":"D","text":"Axis Bank"}]', 0, 'A', 'Karur Vysya Bank is a Scheduled Commercial Bank in India. The Reserve Bank of India has authorised Karur Vysya Bank (KVB) to collect direct taxes on behalf of the Central Board of Direct Taxes (CBDT). After obtaining the approval, KVB has started the integration process with the CBDT to collect direct taxes. The integration would enable the bank to allow its customers to remit the direct taxes through any branch/net banking/mobile banking services.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
