INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4288, 'general-test-2022-08-08-shift-1', 'q06', 6, 6, 'Which among the following are the ranks of commissioned officers in army?

(A) General

(B) Commodore

(C) Colonel

(D) Captain

(E) Group Captain', '[{"id":"A","text":"(A), (C) and (D) only"},{"id":"B","text":"(B), (C) and (E) only"},{"id":"C","text":"(A), (B) and (D) only"},{"id":"D","text":"(C), (D) and (E) only"}]', 0, 'A', 'From the above, only General, Colonel, Captain are the ranks of commissioned officers in army. While Commodore and Group Capitan are the ranks of commissioned officers in Navy and Air - Force similarly. Captain ranks above the rank of Commander and lower than a Commodore. It is equivalent to colonel in the Indian Army and Group Captain in the Indian Aix Force.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4289, 'general-test-2022-08-08-shift-1', 'q07', 7, 7, 'Which among the following are the part of forebrain?

(A) Cerebrum

(B) Cerebellum

(C) Medulla oblongata

(D) Hypothalamus

(E) Diencephalon', '[{"id":"A","text":"(A), (D) and (E) only"},{"id":"B","text":"(A), (C) and (E) only"},{"id":"C","text":"(B), (C) and (D) only"},{"id":"D","text":"(A), (B) and (D) only"}]', 0, 'A', 'The lower part of brain stem forms the hindbrain which comprises of the medulla oblongata, pons, and cerebellum.

The cerebrum, diencephalon and hypothalamus are parts of the forebrain.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4290, 'general-test-2022-08-08-shift-1', 'q08', 8, 8, 'Which among the following enzymes is required to digest protein?', '[{"id":"A","text":"Disaccharides"},{"id":"B","text":"Trypsin"},{"id":"C","text":"Amylase"},{"id":"D","text":"Lipase"}]', 0, 'B', 'Protein digestive enzymes are pepsin and trypsin. They break down proteins into smaller peptides and amino acids. Pepsin is secreted by the gastric gland in the stomach whereas trypsin is secreted by Pancreas.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4291, 'general-test-2022-08-08-shift-1', 'q09', 9, 9, 'What is the name of the largest diamond in the world?', '[{"id":"A","text":"The Cullinan"},{"id":"B","text":"The Kohinoor"},{"id":"C","text":"The Sergio"},{"id":"D","text":"The Woyie River"}]', 0, 'A', 'The world''s biggest diamond called the "Star of Africa I," or "Cullinan," and at 530 carats, it is the

largest-cut fine-quality colorless diamond in the world. This breathtakingly beautiful stone is on display in the Tower of London as part of the Crown Jewels.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4292, 'general-test-2022-08-08-shift-1', 'q10', 10, 10, 'Which among the following countries have lion as their national emblem?

(A) Spain

(B) Belgium

(C) Norway

(D) France

(E) Netherlands', '[{"id":"A","text":"(A), (C) and (D) only"},{"id":"B","text":"(B), (C) and (E) only"},{"id":"C","text":"(A), (B) and (D) only"},{"id":"D","text":"(C), (D) and (E) only"}]', 0, 'B', 'Belgium, Norway and Netherlands have lion as their national emblem. The lion is the official national animal of Netherlands. The lion is widely regarded as a national symbol, the Netherlands. A heraldic lion can be seen on the Belgian coat of arms and can be seen as the country''s de facto national animal. A lion became the symbol of a Norwegian king at least as early as 1280. It still stands proudly on Norway''s Coat of Arms. Wild lions have likely never made their way to Norway, but European cave lions were once found as far north as Denmark.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.639Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4293, 'general-test-2022-08-08-shift-1', 'q11', 11, 11, 'First Field Marshal of India was:', '[{"id":"A","text":"General KM Cariappa"},{"id":"B","text":"General SHFJ Manekshaw"},{"id":"C","text":"General V P Malik"},{"id":"D","text":"General Bipin Rawat"}]', 0, 'B', 'War of 1971, and the first Indian Army officer to be promoted to the rank of field marshal.

Sol. Field Marshal equivalent to an admiral of the fleet in the Indian Navy and a, Marshal of the Indian Air Force in the Indian Air Force. General SHFJ Manekshaw was the first person who was promoted to the rank of Field Marshal. Field Marshal Sam Hormusji Framji Jamshedji Manekshaw is widely known as Sam Manekshaw and Sam Bahadur. He was the Chief of the Army Staff of the Indian Army during the Indo-Pakistani', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:58:59.640Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4294, 'general-test-2022-08-08-shift-1', 'q12', 12, 12, 'Which team has won the men''s cricket world cup the greatest number of times?', '[{"id":"A","text":"West Indies"},{"id":"B","text":"India"},{"id":"C","text":"England"},{"id":"D","text":"Australia"}]', 0, 'D', 'Australia is the most successful team in the ICC ODI World Cup, won the men''s cricket world cup number of times, i.e., 5 times and finished as the runner-up 2 times. The West Indies won the first two editions (1975 and 1979) and Australia won three in a row (1999, 2003 and 2007).', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.640Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4295, 'general-test-2022-08-08-shift-1', 'q13', 13, 13, 'Find the correct option

M × N : 13 × 14 ∵ F × R : ?', '[{"id":"A","text":"7 × 19"},{"id":"B","text":"5 × 17"},{"id":"C","text":"14 × 15"},{"id":"D","text":"6 × 18"}]', 0, 'D', 'As we know that the place value in alphabet series of M and N are 13 & 14 respectively.

So, here F and R will be replaced by their place value.

Hence. $ F \times R = 6 \times 18 $.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.640Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4296, 'general-test-2022-08-08-shift-1', 'q14', 14, 14, '_ transforms source code into the machine-readable code by converting into line by line.', '[{"id":"A","text":"Register"},{"id":"B","text":"Compiler"},{"id":"C","text":"Cache Memory"},{"id":"D","text":"Interpreter"}]', 0, 'B', 'A compiler is a software program that translates high-level programming language code into machine-readable code or binary code. It converts the entire source code into an executable file in one go, translating the code line by line and generating an output that can be directly executed by the computer''s hardware. This process is known as compilation. The compiled code is typically faster and more efficient than interpreted code, as the translation is done before the program is run.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.640Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4297, 'general-test-2022-08-08-shift-1', 'q15', 15, 15, 'Match the List-I with List II.', '[{"id":"A","text":"A-II, B-III, C-IV, D-I"},{"id":"B","text":"A-III, B-IV, C-I, D-II"},{"id":"C","text":"A-IV, B-II, C-I, D-III"},{"id":"D","text":"A-I, B-II, C-IV, D-III"}]', 0, 'A', NULL, NULL, 'null', '[]', '[{"id":"q15-table-1","kind":"table","path":"/local-papers/assets/general-test-2022-08-08-shift-1/q15-table-1.jpg","page":2,"alt":"Table for question 15"}]', '[2]', 'keyed', '[]', '2026-11-05T20:58:59.640Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
