INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4326, 'general-test-2022-08-08-shift-1', 'q48', 44, 44, 'Find the LCM of $ \frac{3}{5} $, $ \frac{4}{9} $ and $ \frac{5}{8} $ is', '[{"id":"A","text":"45"},{"id":"B","text":"55"},{"id":"C","text":"60"},{"id":"D","text":"65"}]', 0, 'C', '$$ \begin{array}{r l}{\mathrm{S o l.}}&{\mathrm{L C M~o f~f r a c t i o n}=\frac{\mathrm{L C M~o f~N u m e r a t o r}}{\mathrm{H C F~o f~D e n o m i n t o r}}}\\ &{=\frac{L C F\left(3,4,5\right)}{H C F\left(5,8,9\right)}=\frac{60}{1}}\\ &{=60}\end{array} $$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4327, 'general-test-2022-08-08-shift-1', 'q49', 45, 45, 'In a swimming pool measuring 80 m × 60 m, 120 men take a dip. If the average displacement of water by a man is 6 m³, then the rise in water level is -', '[{"id":"A","text":"0.25 m"},{"id":"B","text":"0.10 m"},{"id":"C","text":"0.15 m"},{"id":"D","text":"0.35 m"}]', 0, 'C', 'It is given that,

Length of swimming pool = 80m

Breadth of swimming pool - 60m

Let the depth of swimming pool = D m

Volume of water displaced = Displacement of water

by 120 men.

$ 80 \times 60 \times D = 120 \times 6 $

$ 4800 \times D = 720 $

D = 0.15 m', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:58:59.643Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4328, 'general-test-2022-08-08-shift-1', 'q50', 46, 46, 'The average age of group of 5 friends is 32 years. The youngest friend amongst them is 4 years old. What was the average age of the group at the time of birth of the youngest friend?', '[{"id":"A","text":"36 years"},{"id":"B","text":"35 years"},{"id":"C","text":"34 years"},{"id":"D","text":"33 years"}]', 0, 'B', 'Given that,

The average age of 5 fiend = 32 years

So, sum of their ages = $ 32 \times 5 = 160 $ years

The youngest friend is 4 years old, that means

youngest was born 4 years ago.

Now 4 years ago,

Sum = 160 - (4 $ \times $ 5) = 160 - 20 = 140 years

So, the average age of group at the time of the birth

of youngest one = 140/4 = 32 years

Hence, option B is correct answer.

