INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4334, 'general-test-2022-08-08-shift-1', 'q66', 52, 52, 'Match List I with List II', '[{"id":"A","text":"A-IV, B-II, C-III, D-I"},{"id":"B","text":"A-III, B-IV, C-II, D-I"},{"id":"C","text":"A-I, B-III, C-IV, D-II"},{"id":"D","text":"A-II, B-III, C-IV, D-I"}]', 0, 'D', 'From the given options, option D is perfect match of areas of given figures.', NULL, 'null', '[]', '[{"id":"q66-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-08-08-shift-1/q66-figure-1.jpg","page":6,"alt":"Figure for question 66"},{"id":"q66-table-2","kind":"table","path":"/local-papers/assets/general-test-2022-08-08-shift-1/q66-table-2.jpg","page":6,"alt":"Table for question 66"}]', '[5,6]', 'keyed', '[]', '2026-11-05T20:58:59.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4335, 'general-test-2022-08-08-shift-1', 'q67', 53, 53, 'The diameter of a circle whose area is numerically 110 more than its circumference is', '[{"id":"A","text":"5 units"},{"id":"B","text":"7 units"},{"id":"C","text":"14 units"},{"id":"D","text":"10 units"}]', 0, 'B', 'As we know that, area of circle = $\pi r^2$
And circumference = $2\pi r$
As per the question,
$\pi r^2 = 2\pi r + 110$
$\pi r^2 - 2\pi r = 110$
$\pi r(r - 2) = 110$
$r(r - 2) = 7 \times 5$
So, $r = 7$', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4336, 'general-test-2022-08-08-shift-1', 'q68', 54, 54, 'If $m-n=16$ and $m^{2}+n^{2}=400$, the value of mn is =', '[{"id":"A","text":"72"},{"id":"B","text":"25"},{"id":"C","text":"144"},{"id":"D","text":"192"}]', 0, 'A', 'As we know that,
$(m - n)^2 = m^2 + n^2 - 2mn$
$16^2 = 400 - 2mn$
$2mn = 400 - 256$
$2mn = 144$
$mn = 72$', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4337, 'general-test-2022-08-08-shift-1', 'q69', 55, 55, 'The value of ''y'' in the question 2x + 3y - 7 = 0

if x = -3/2', '[{"id":"A","text":"10"},{"id":"B","text":"10/3"},{"id":"C","text":"4/3"},{"id":"D","text":"13/3 Direction for question 70 to 72: From the graph given below, answer the following question."}]', 0, 'B', 'Given that,
$2x + 3y - 7 = 0$ if $x = -(3/2)$
$-2(3/2) + 3y - 7 = 0$
$-3 + 3y - 7 = 0$
$3y - 10 = 0$
$3y = 10$
$y = 10/3$
Hence, option b is correct option.', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4338, 'general-test-2022-08-08-shift-1', 'q70', 56, 56, 'The total number of people owing books more than ''40'' is', '[{"id":"A","text":"60"},{"id":"B","text":"31"},{"id":"C","text":"14"},{"id":"D","text":"30"}]', 0, 'B', 'The total number of people owing books more than $ 40 = 14 + 10 + 7 = 31 $', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.644Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
