INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4341, 'general-test-2022-08-08-shift-1', 'q73', 59, 59, '''AC'' is 23 cm in the adjoining figure. Consider the figure and answer the questions', '[{"id":"A","text":"133 cm²"},{"id":"B","text":"140 cm²"},{"id":"C","text":"70 cm²"},{"id":"D","text":"66.5 cm²"}]', 0, 'D', 'The area of DGFE (here, GF=h=7 cm)
