INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4342, 'general-test-2022-08-08-shift-1', 'q74', 60, 60, 'The area of $ \Delta DBC $ is DB is a straight line', '[{"id":"A","text":"$ 32.5 \\, cm^{2} $"},{"id":"B","text":"$ 65 \\, cm^{2} $"},{"id":"C","text":"$ 25 \\, cm^{2} $"},{"id":"D","text":"$ 15 \\, m^{2} $"}]', 0, 'A', 'Area of triangle
BDC = ½ × B × H
= 1/2 × 13 × 5 = 32.5 cm²', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:58:59.645Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4343, 'general-test-2022-08-08-shift-1', 'q75', 61, 61, 'The total area of figure is', '[{"id":"A","text":"184.5 cm²"},{"id":"B","text":"205 cm²"},{"id":"C","text":"175.5 cm²"},{"id":"D","text":"153 cm² SOLUTIONS"}]', 0, 'C', 'Area of figure = area ΔDBC + area ΔAGB + area
ΔEFA + Area of rec. DGFE
