INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4344, 'general-test-2022-08-18', 'q01', 1, 1, 'HCF of first five odd natural numbers is:', '[{"id":"A","text":"5"},{"id":"B","text":"3"},{"id":"C","text":"2"},{"id":"D","text":"1"}]', 0, 'D', 'First five odd natural numbers are 1, 3, 5, 7, 9. HCF is the highest common factor of these numbers.

Hence, HCF is 1.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.851Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4345, 'general-test-2022-08-18', 'q02', 2, 2, 'The value of $4-3\div3+5$', '[{"id":"A","text":"5"},{"id":"B","text":"0"},{"id":"C","text":"7"},{"id":"D","text":"8"}]', 0, 'D', '$ 4 - 3 \div 3 + 5 = 4 - 1 + 5 $

$ \Rightarrow $ 9 - 1 = 8', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.851Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4346, 'general-test-2022-08-18', 'q03', 3, 3, 'Common factor of $2a^{2}b$, $4ab^{2}$, $6ac^{2}$', '[{"id":"A","text":"2ab"},{"id":"B","text":"2a"},{"id":"C","text":"2abc"},{"id":"D","text":"2b"}]', 0, 'B', 'Factor of $2a^{2}b = 2 \times a \times a \times b$

Factor of $4ab^{2} = 2 \times 2 \times a \times b \times b$

Factor of $6ac^{2} = 2 \times 3 \times a \times c \times c$

Hence, common factor $=2 \times a = 2a$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.852Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4347, 'general-test-2022-08-18', 'q04', 4, 4, 'The average of 3 consecutive odd numbers is 65. What is the ratio of these numbers?', '[{"id":"A","text":"61:63:65"},{"id":"B","text":"59:61:63"},{"id":"C","text":"63:65:67"},{"id":"D","text":"65:67:69"}]', 0, 'C', 'Let three consecutive odd numbers are x, x+2, x+4. According to question,

$ \frac{x+x+2+x+4}{3}=65 $

$ \Rightarrow 3x+6=195 \Rightarrow 3x=195-6=189 $

$ \Rightarrow x=\frac{189}{3}=63 $

Hence, ratio of three numbers = 63 : 65 : 67

Hence, ratio of three numbers = 63 : 65 : 67', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.852Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4348, 'general-test-2022-08-18', 'q05', 5, 5, 'The sum of the ages of father and his son is 45 years. Five years ago, the product of their ages was 34. The age of father is:', '[{"id":"A","text":"40 years"},{"id":"B","text":"45 years"},{"id":"C","text":"39 years"},{"id":"D","text":"38 years"}]', 0, 'C', '''If the age of father is x years and age of son is y years.

According to question,

$ x + y = 45 $

$ \ldots (i) $

$ (x - 5)(y - 5) = 34 $

$ \Rightarrow $ xy - 5x - 5y + 25 = 34

$ \Rightarrow $ xy - 5(x + y) = 34 - 25 = 9

$ \Rightarrow $ xy = 9 + 5 $ \times $ 45 [From eqn. (i)]

$ \Rightarrow $ xy = 234

$ \ldots (ii) $

From eq $ ^{n} $ (i) and (ii)

$ \frac{234}{y} + y = 45 $

$ \Rightarrow $ y $ ^{2} $ - 45y + 234 = 0

$ \Rightarrow $ y $ ^{2} $ - 39y - 6y + 234 = 0

$ \Rightarrow $ y(y - 39) - 6(y - 39) = 0

$ \Rightarrow $ y = 39, 6 (very less age)

Hence, father''s age is 39 years.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.852Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4349, 'general-test-2022-08-18', 'q06', 6, 6, 'Sum of the ages of 4 children bom at the intervals of 4 years each is 52 years. What is the age of the eldest one?', '[{"id":"A","text":"7 years"},{"id":"B","text":"14 years"},{"id":"C","text":"19 years"},{"id":"D","text":"24 years"}]', 0, 'C', 'Let age of four children are x, x+4, x+8 and x+12 years. According to question,

x+x+4+x+8+x+12=52

$ \Rightarrow 4x=52-24=28 \Rightarrow x=\frac{28}{4}=7 $

Hence age of the eldest one = 7+12=19 years', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.852Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4350, 'general-test-2022-08-18', 'q07', 7, 7, 'What is the value of x. if x% of 142 + 30% of 280 = 368', '[{"id":"A","text":"150"},{"id":"B","text":"200"},{"id":"C","text":"175"},{"id":"D","text":"225"}]', 0, 'B', '$ \frac{x}{100} \times 142 + \frac{30}{100} \times 280 = 368 $

$ \Rightarrow 142x + 8400 = 368 \times 100 = 36800 $

$ \Rightarrow 142x = 36800 - 8400 = 28400 $

$ \Rightarrow x = \frac{28400}{142} = 200 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.852Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4351, 'general-test-2022-08-18', 'q08', 8, 8, 'If 0.03 is X% of 0.3, then the value of X is:

(a) 30

(b) 10

(c) 3

(d) 9

Simple interest of ₹ 9000 at 5% per annum for 6 months is:', '[{"id":"A","text":"₹ 235"},{"id":"B","text":"₹ 245"},{"id":"C","text":"₹ 205"},{"id":"D","text":"₹ 225"}]', 0, 'B', '$ \frac{x}{100} \times 0.3 = 0.03 $

$ \Rightarrow x = \frac{0.03}{0.3} \times 100 = \frac{3}{100} \times \frac{10}{3} \times 100 $

$ \Rightarrow x = 10\% $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.853Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4352, 'general-test-2022-08-18', 'q10', 9, 9, 'A can complete a work in 16 days. B can complete the same work in 8 days. If both of them come together, then in how many days can they complete the same work?', '[{"id":"A","text":"$ 2\\frac{1}{3} $ days"},{"id":"B","text":"$ 5\\frac{1}{3} $ days"},{"id":"C","text":"$ 7\\frac{1}{3} $ days"},{"id":"D","text":"$ 6\\frac{1}{3} $ days"}]', 0, 'B', 'A''s one day work = $ \frac{1}{16} $

B''s one day work = $ \frac{1}{8} $

$ \therefore $ (A + B)''s one day work = $ \frac{1}{16} + \frac{1}{8} = \frac{3}{16} $

Hence, A and B together complete the same work in $ \frac{16}{3} = 5\frac{1}{3} $ days', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.853Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4353, 'general-test-2022-08-18', 'q11', 10, 10, 'A train 420 m long passes a pole in 20 seconds. What is the speed of the train?', '[{"id":"A","text":"20 m/s"},{"id":"B","text":"22 m/s"},{"id":"C","text":"21 m/s"},{"id":"D","text":"24 m/s"}]', 0, 'C', 'Train''s speed = $ \frac{\text{Length of train}}{\text{Time taken to pass pole}} $ = $ \frac{420}{20} $ = 21 m/s', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.853Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4354, 'general-test-2022-08-18', 'q12', 11, 11, 'If 900 m long train crosses 700 in long platform in 1 minute, then speed of the train in kilometer per hour is:', '[{"id":"A","text":"$ \\frac{80}{3} $ km/h"},{"id":"B","text":"96 km/h"},{"id":"C","text":"15 km/h"},{"id":"D","text":"$ \\frac{35}{3} $ km/h"}]', 0, 'B', 'Total Length = 900 + 700 = 1600 m

Time = 1 min = 60 sec

Hence, speed of train = $ \frac{1600}{60} = \frac{160}{6} $ m/s

$ =\frac{160}{6} \times \frac{18}{5} = 32 \times 3 = 96 $ km/hr.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.853Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4355, 'general-test-2022-08-18', 'q13', 12, 12, 'If $ x^{2} + 9y^{2} - 6xy = 0 $, then x: y is equal to:', '[{"id":"A","text":"3:2"},{"id":"B","text":"1:3"},{"id":"C","text":"3:1"},{"id":"D","text":"2:3"}]', 0, 'C', '$ x^{2}+9y^{2}-6xy=0 $

$ \Rightarrow $ $ x^{2}+(3y)^{2}-2\times x\times3y=0 $

$ \Rightarrow $ $ (x-3y)^{2}=0 $ $ [\because a^{2}-2ab+b^{2}=(a-b)^{2}] $

$ \Rightarrow $ x-3y=0

$ \Rightarrow $ x=3y

$ \Rightarrow $ $ \frac{x}{y}=\frac{3}{1} $

Hence, x:y=3:1', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.853Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4356, 'general-test-2022-08-18', 'q14', 13, 13, 'In the formula "Work = Fs cos θ", if angle θ between force and displacement is more than 90°, the net work done will be:', '[{"id":"A","text":"Double"},{"id":"B","text":"Positive but not double"},{"id":"C","text":"Negative"},{"id":"D","text":"Zero"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4357, 'general-test-2022-08-18', 'q15', 14, 14, 'The factors of $4x^{2}-8x+3$ are', '[{"id":"A","text":"$(2x-3)(2x+1)$"},{"id":"B","text":"$(2x+3)(2x-1)$"},{"id":"C","text":"$(2x+3)(2x+1)$"},{"id":"D","text":"$(2x-3)(2x-1)$"}]', 0, 'D', '$ 4x^{2}-8x+3 $

=4x^{2}-6x-2x+3

=2x(2x-3)-1(2x-3)

=(2x-1)(2x-3)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4358, 'general-test-2022-08-18', 'q16', 15, 15, 'If the edge of a cube is 17 cm. then the volume is:', '[{"id":"A","text":"$ 4813 \\, cm^{3} $"},{"id":"B","text":"$ 4913 \\, cm^{3} $"},{"id":"C","text":"$ 4713 \\, cm^{3} $"},{"id":"D","text":"$ 5913 \\, cm^{3} $"}]', 0, 'B', 'Volume of the cube = (Edge)$^{3}$

= (17)$^{3}$ = 4913 cm$^3$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4359, 'general-test-2022-08-18', 'q17', 16, 16, 'If the base radius of a cone is 7 cm and height of it is 14 cm. then:

A. Slant height = $6\sqrt{5}$ cm

B. Slant height = $7\sqrt{5}$ cm

C. Volume = $718.67\mathrm{~cm}^{3}$

D. Volume = $708.66\mathrm{~cm}^{3}$

E. Ratio of height and slant height = 2:$\sqrt{5}$', '[{"id":"A","text":"A, C and D only"},{"id":"B","text":"B, C and E only"},{"id":"C","text":"B and C only"},{"id":"D","text":"A, C and E only"}]', 0, 'B', 'Cone''s radius (r) = 7 cm

Cone''s height (h) = 14 cm

$\therefore$ Slant height ($l$) = $\sqrt{(r)^2 + (h)^2} = \sqrt{(7)^2 + (14)^2}$

= $7\sqrt{5}$ cm.

And, volume of cone = $\frac{1}{3}\pi r^2 h = \frac{1}{3} \times \frac{22}{7} \times 7 \times 7 \times 14$

= $\frac{2156}{3} = 718.67$ cm$^3$

Ratio of height and slant height

= $\frac{h}{l} = \frac{14}{7\sqrt{5}} \Rightarrow 2 : \sqrt{5}$

Hence, only B, C and E are the correct answers.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4360, 'general-test-2022-08-18', 'q19', 17, 17, 'In the given figure AOB is a straight line. the value of x is:', '[{"id":"A","text":"60"},{"id":"B","text":"70"},{"id":"C","text":"50"},{"id":"D","text":"45"}]', 0, 'C', '$ (x+55)^{\circ}+(2x-25^{\circ})=180^{\circ} $ [SupplementaryAngle]

$ \Rightarrow $ $ 3x+30^{\circ}=180^{\circ} $

$ \Rightarrow $ $ 3x=180-30=150 \Rightarrow x=\frac{150}{3}=50 $', NULL, 'null', '[]', '[{"id":"q19-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-08-18/q19-figure-1.jpg","page":1,"alt":"Figure for question 19"}]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4361, 'general-test-2022-08-18', 'q21', 18, 18, 'Area of the triangular region FDE is:', '[{"id":"A","text":"$ 1000 \\, m^{2} $"},{"id":"B","text":"$ 1250 \\, m^{2} $"},{"id":"C","text":"$ 2400 \\, m^{2} $"},{"id":"D","text":"$ 1600 \\, m^{2} $"}]', 0, 'B', 'Area of triangular region FDE = $ \frac{1}{2} \times $ Base $ \times $ Height

$ =\frac{1}{2} \times 50 \times 50 = 1250 \, m^{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4362, 'general-test-2022-08-18', 'q22', 19, 19, 'Area of region ACDF is:', '[{"id":"A","text":"$ 3750 \\, m^{2} $"},{"id":"B","text":"$ 3500 \\, m^{2} $"},{"id":"C","text":"$ 3250 \\, m^{2} $"},{"id":"D","text":"$ 3000 \\, m^{2} $"}]', 0, 'A', 'In $ \Delta ABC $,

$ (AC)^{2} = (AB)^{2} + (BC)^{2} $ [By Pythagoras theorem]

$ \Rightarrow (AC)^{2} = (80)^{2} + (60)^{2} = 10000 $

$ \Rightarrow AC = \sqrt{10000} = 100 \, m $

$ \because $ Region ACDF is a trapezium shape region.

Hence, area of region ACDF = $ \frac{1}{2} \times [S_{1} + S_{2}] \times H $

$ =\frac{1}{2} \times [DF + AC] \times HG $

$ =\frac{1}{2} \times [50 + 100] \times 50 $

$ =3750 \, m^{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.854Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4363, 'general-test-2022-08-18', 'q23', 20, 20, 'Area of whole figure is:', '[{"id":"A","text":"7000 m $ ^{2} $"},{"id":"B","text":"7200 m $ ^{2} $"},{"id":"C","text":"7400 m $ ^{2} $"},{"id":"D","text":"7500 m $ ^{2} $"}]', 0, 'C', 'Area of whole figure = Area of \Delta FDE + Area of region A C D F + Area of \Delta A B C

= 1250 + 3750 + $ \frac{1}{2} $ × 80 × 60

= 5000 + 2400

= 7400 m²', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.855Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
