INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4416, 'general-test-2022-08-22', 'q09', 7, 7, 'If $ 2^{x-1} + 2^{x+1} = 1280 $, then find the value of x', '[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"8"},{"id":"D","text":"9"}]', 0, 'D', '$ \frac{2^{x}}{2} + 2^{x} \cdot 2 = 1280 $

