INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4417, 'general-test-2022-08-22', 'q10', 8, 8, 'If 50% of a number is equal to 1/5th of another number, what is the ratio of the number to the second number?', '[{"id":"A","text":"2:5"},{"id":"B","text":"9:6"},{"id":"C","text":"10:1"},{"id":"D","text":"3:7"}]', 0, 'A', 'Let the Ist No. = x

then IInd no = y

A.T.Q.

50% of $ x = \frac{1}{5} y $

$ \frac{1}{2}x = \frac{y}{5} $

$ \frac{x}{y} = \frac{2}{5} \rightarrow 2:5 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.863Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4418, 'general-test-2022-08-22', 'q11', 9, 9, 'The average of the four consecutive odd number is 16.

What is the difference between fourth and first?', '[{"id":"A","text":"4"},{"id":"B","text":"2"},{"id":"C","text":"5"},{"id":"D","text":"6"}]', 0, 'D', 'Let the four consecutive odd number.

$ 2x+1,2x+3,2x+5,2x+7 $

A.T.Q.

$ \frac{(2x+1)+(2x+3)+(2x+5)+(2x+7)}{4}=16 $

$ 8x+16=64 $

$ 8(x+2)=64 $

$ x+2=8 $

$ x=6 $

Ist odd no. = 2(6) + 1 = 13

4th odd no = 2(6) + 7 = 19

Diff. between fourth and 1st odd no. = 19 - 13 = 6', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.863Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4419, 'general-test-2022-08-22', 'q12', 10, 10, 'x% of x is the same as 20% of', '[{"id":"A","text":"$20x$"},{"id":"B","text":"$x/20$"},{"id":"C","text":"$x^{2}/20$"},{"id":"D","text":"$20x^{2}$"}]', 0, 'C', 'Let number = K.

$$ \frac{(X)}{100}\cdot(X)=\frac{20}{100}\cdot K $$

$$ K\Rightarrow=\frac{X^{2}}{20} $$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.864Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4420, 'general-test-2022-08-22', 'q13', 11, 11, 'Hari sells 6 eggs at Rs. 24. He buys 10 eggs at Rs. 30. What is his profit or loss%?', '[{"id":"A","text":"33.33%"},{"id":"B","text":"55.33%"},{"id":"C","text":"65.66%"},{"id":"D","text":"60.66%"}]', 0, 'A', 'Selling cost of 6 eggs = 24

Buying cost of 10 eggs = 30

$$ Profit\%=\frac{120-90}{90}\times100=33.33\% $$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.864Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4421, 'general-test-2022-08-22', 'q14', 12, 12, 'A shopkeeper bought candy at 10 for a rupee. How many for a rupee must he sells to gain 25%?', '[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}]', 0, 'D', 'Cost price of 10 candy = Rs. 1 gain = 25%

∴ Number of candy sell in Rs. 1

$ =10\times\frac{100}{(100+25)}=8 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.864Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4422, 'general-test-2022-08-22', 'q15', 13, 13, 'A sum becomes its double in 15 years. Find the annual rate of simple interest:', '[{"id":"A","text":"$ 6\\frac{1}{3}\\% \\text{ PA} $"},{"id":"B","text":"$ 6\\frac{2}{3}\\% \\text{ PA} $"},{"id":"C","text":"$ 7\\frac{2}{3}\\% \\text{ PA} $"},{"id":"D","text":"$ 7\\frac{1}{3}\\% \\text{ PA} $"}]', 0, 'B', 'Let the principal = Rs. P

Sum doubles i.e., = 2P

Simple interest = 2P - P = P

S.I. = $ \frac{P \times R \times T}{100} $

A.T.Q.

P = $ \frac{P \times R \times 15}{100} $

R = $ \frac{100}{15} = \frac{20}{3} = 6 \frac{2}{3}\% $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.865Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4423, 'general-test-2022-08-22', 'q16', 14, 14, 'Simple interest of Rs.20000 for 8 years at 6% PA is equal to the simple interest on Rs. 16000 at 3% PA for a fixed period. The time period is', '[{"id":"A","text":"20 yrs"},{"id":"B","text":"19 yrs"},{"id":"C","text":"21 yrs"},{"id":"D","text":"22 yrs"}]', 0, 'A', 'A.T.Q.

$ \frac{20000 \times 8 \times 6}{100} = \frac{16000 \times 3 \times T}{100} $

T = 20 yrs', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.865Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4424, 'general-test-2022-08-22', 'q17', 15, 15, 'P can lay railway track between two given stations in 15 days and Q can do the same job in 10 days. With help of R, they did the job in 4 days only. Then, R alone can do the job in:', '[{"id":"A","text":"10 days"},{"id":"B","text":"12 days"},{"id":"C","text":"8 days"},{"id":"D","text":"9 days"}]', 0, 'B', 'P''s one day word = $\frac{1}{15}$

Q''s one day work = $\frac{1}{10}$

Let R take x days to complete work.

P + Q + R one day word = $\frac{1}{4}$

R''s one day work = $\frac{1}{x}$

A. T.Q.

$\frac{1}{15} + \frac{1}{10} + \frac{1}{x} = \frac{1}{4}$

$\frac{1}{x} = \frac{1}{4} - \left[ \frac{1}{15} + \frac{1}{10} \right]$

$\frac{1}{x} = \frac{15 - (4 + 6)}{60} = \frac{5}{60}$

R can do job = $\frac{60}{2} = 12$ days', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.865Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4425, 'general-test-2022-08-22', 'q18', 16, 16, 'Mohan is on tour and he has Rs. 75 for his expenses. If he exceeds his tour by 4 days he must reduce daily expenses by Rs. 5. The number of days of Mohan''s tour programme is-', '[{"id":"A","text":"3 days"},{"id":"B","text":"4 days"},{"id":"C","text":"5 days"},{"id":"D","text":"6 days"}]', 0, 'D', 'Let Mohan has x days tour

Then, 1 day expanse = $ \frac{75}{x} $

A. T.Q.

If tour is extended i.e. $ (x+4) $

Then 1 day expanses = $ \frac{75}{x+4} $

Now,

$ \frac{75}{x}-\frac{75}{x+4}=5 $

$ 60=x^{2}+4x $

$ x^{2}+4x-60=0 $

$ x^{2}+10x-6x-60=0 $

$ x(x+10)-6(x+10)=0 $

$ (x+10)(x-6)=0 $

$ \boxed{x=6} $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4426, 'general-test-2022-08-22', 'q19', 17, 17, 'A can do piece of work in 20 days, which B can do in 16 days, B worked at it for 8 days. A can finish the remaining work is.....', '[{"id":"A","text":"8 days"},{"id":"B","text":"10 days"},{"id":"C","text":"6 days"},{"id":"D","text":"12 days"}]', 0, 'B', 'A $\xrightarrow{\quad}$ 20 $\xrightarrow{\quad}$ 4

B $\xrightarrow{\quad}$ 16 $\xrightarrow{\quad}$ 80

B''s 1 day work = 5

B''s 8 day work = $5 \times 8 = 40$

Reaming work finish by $A = \frac{(80 - 40)}{4} = 10$ days', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4427, 'general-test-2022-08-22', 'q20', 18, 18, 'The speed of a boat upstream is 12 km/hr and speed of the stream is 2 km/hr. How much time will take to travel 48 km downstream?', '[{"id":"A","text":"3.5 hours"},{"id":"B","text":"2.5 hours"},{"id":"C","text":"5.5 hours"},{"id":"D","text":"3 hours"}]', 0, 'D', 'Speed of the boat = u km/hr.

Here upstream speed = $(u - 2) = 12$

$\therefore u = 14$ km/hr.

$\therefore$ Downstream speed = $14 + 2 = 16$ km/hr.

Hence, time taken $= \frac{48}{16} = 3$ hr.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4428, 'general-test-2022-08-22', 'q21', 19, 19, 'Ramnaresh complete a journey in 10 hours. He travels first half of the journey at the rate of 20 km/hr and second half at the rate of 25 km/hr. Find the total journey in km.', '[{"id":"A","text":"111.11 km"},{"id":"B","text":"222.22 km"},{"id":"C","text":"333.33 km"},{"id":"D","text":"444.44 km"}]', 0, 'B', 'Average speed = $ \frac{2 \times S_{1} \times S_{2}}{S_{1} + S_{2}} $

$ =\frac{2 \times 20 \times 25}{(20 + 25)} $

$ =\frac{1000}{45} \text{km/hr} $.

Total travels time = 10 hrs.

$ \therefore \text{Distance} = \frac{1000}{45} \times 10 $

=222.22 km.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4429, 'general-test-2022-08-22', 'q22', 20, 20, 'Excluding stopage, the speed of a train is 120 kmph and including stopages it is 100 kmph. For how many minutes does the train stop per hour?', '[{"id":"A","text":"10min"},{"id":"B","text":"15min"},{"id":"C","text":"20min"},{"id":"D","text":"12min"}]', 0, 'A', 'without stoppage with stoppage

Speed 120 100

Time 5 6

Train takes 6 hrs with stoppage, whereas actual time taken is 5 hrs.

i.e. 1 hour is stopped in 6 hours.

A.T.Q:

6 hours = 60 min

1 hour = $ \frac{60}{6} = 10 $ min', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4430, 'general-test-2022-08-22', 'q23', 21, 21, 'A train passes two bridges of lengths 1 km and 500 m in 120 seconds and 80 second respectively. The length of the train is-', '[{"id":"A","text":"400m"},{"id":"B","text":"300m"},{"id":"C","text":"750m"},{"id":"D","text":"500m"}]', 0, 'D', 'Let the length of Train = $L_{T}$ and speed of Train = $S_{T}$

A. T.Q.

Train passes 1st bridge of 1000 m in 120 sec.

Then

$120 = \frac{1000 + L_{T}}{S}$

$S = \frac{1000 + L_{T}}{120}$

Train passes IInd bridge of 500 m is 80 sec.

Then,

$S = \frac{500 + L_{T}}{80}$

From (i) and (ii)

$\frac{1000 + L_{T}}{120} = \frac{500 + L_{T}}{80}$

$2000 + 2L_{T} = 1500 + 3L_{T}$

$L_{T} = 500$ m.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.866Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4431, 'general-test-2022-08-22', 'q24', 22, 22, 'The time taken by train 720 m long travelling at 28 km/hr in passing a boy walking 10 km/hr in same direction will be.', '[{"id":"A","text":"146 sec"},{"id":"B","text":"144 sec"},{"id":"C","text":"145 sec"},{"id":"D","text":"147 sec"}]', 0, 'B', 'Speed of train (in m/sec) = $ 28 \times \frac{5}{18} = \frac{70}{9} $ m/sec

Speed of boy (in m/sec) = $ 10 \times \frac{5}{18} = \frac{25}{9} $ m/sec

A. T.Q.

Relative speed of train :

$ t = \frac{720}{\left(\frac{70 - 25}{9}\right)} = \frac{9 \times 720}{45} $

= 144 sec.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4432, 'general-test-2022-08-22', 'q25', 23, 23, 'The minute arm of a clock is 20 cm long. The number of minutes taken by the tip of the arm to travel a length of 20 cm is nearly equal to.', '[{"id":"A","text":"4.77 min"},{"id":"B","text":"9.54 min"},{"id":"C","text":"19.18 min"},{"id":"D","text":"14.31 min"}]', 0, 'B', 'Total length convered by minute hand in 60 mint.

$ =2\pi\times20 $

∴ Time required to move 20 cm

$ =\frac{60}{2\pi\times20}\times20=9.54\ min. $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4433, 'general-test-2022-08-22', 'q26', 24, 24, 'If February 01, 2013 was Friday, what will be day on February 01, 2024?', '[{"id":"A","text":"Saturday"},{"id":"B","text":"Monday"},{"id":"C","text":"Tuesday"},{"id":"D","text":"Thursday"}]', 0, 'D', 'Number of odd days between 1st Feb 2024 to 1st Feb 2013 = 1 + 1 + 1 + 2 + 1 + 1 + 1 + 2 + 1 + 1 + 1 = 13 days

Hence, Feb 01, 2024 will be Thursday.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4434, 'general-test-2022-08-22', 'q27', 25, 25, 'How many times in a day, the hands of a clock are straight?', '[{"id":"A","text":"22"},{"id":"B","text":"24"},{"id":"C","text":"44"},{"id":"D","text":"46"}]', 0, 'C', 'In 24 hours, they are at $180^{\circ}$, 22 times and at $0^{\circ}$, 2 times

∴ total number of times = 44', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4435, 'general-test-2022-08-22', 'q28', 26, 26, 'Looking into the mirror the clock shows 9:30 as the time. The actual time is', '[{"id":"A","text":"3:30"},{"id":"B","text":"4:30"},{"id":"C","text":"2:30"},{"id":"D","text":"6:30"}]', 0, 'C', 'Actual time = (11:60) - (9:30) = 2:30

29. (*) Radius of circle = 22 cm.

$$ Area~of~circle=\pi r^{2}=\frac{22}{7}\times(22)^{2} $$

=1571.24 cm²

Circumference of circle = $ 2\pi r = 2 \times \frac{22}{7} \times 22 $

=138.78 cm.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4436, 'general-test-2022-08-22', 'q30', 27, 27, 'If the height of cylinder is halved and radius is doubled, then what will happen to the curved surface area?', '[{"id":"A","text":"Increase by 1"},{"id":"B","text":"double"},{"id":"C","text":"triple"},{"id":"D","text":"the same"}]', 0, 'D', 'Let the height of cylinder = h

Radius of cylinder = r

C.S. A of cylinder = 2πrh.

A.T.Q.

height of cylinder = $ \left(\frac{h}{2}\right) $

Radius of cylinder = 2r

C.S.A. of new cylinder = $ 2\pi(2r)\left(\frac{h}{2}\right) = 2\pi rh $

Comparing both C.S.A of cylinder, New C.S.A is sequence.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.867Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4437, 'general-test-2022-08-22', 'q31', 28, 28, 'The perimeter of a square is 40 cm. Find the area of given square.', '[{"id":"A","text":"40 cm"},{"id":"B","text":"40 cm $ ^{2} $"},{"id":"C","text":"100 cm"},{"id":"D","text":"100 cm $ ^{2} $"}]', 0, 'D', 'Perimeter of square = 40

4a = 40

a = 10 $ \therefore $ a = side}

Area of square = (a) $ ^{2} $

$ =(10)^{2} = 100 \, cm^{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.868Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4438, 'general-test-2022-08-22', 'q32', 29, 29, 'A man standing on the top of a tower standing on the sea shore, finds that a boat coming towards him takes 10 minutes for the angle to change from $45^{\circ}$ to $60^{\circ}$. Find the time taken by the boat to reach the shore from this position.', '[{"id":"A","text":"17.32 min"},{"id":"B","text":"8.66 min"},{"id":"C","text":"7.32 min"},{"id":"D","text":"13.66 min DIRECTIONS (Qs. 33-36): Study the given pie chart carefully to answer the following question from"}]', 0, 'D', 'In $\Delta ABD$

$\tan 45^{\circ} = \frac{AB}{BD}$

$$ \frac{1}{21} $$

In $ \Delta ABC $

$$\tan 60^{\circ} = \frac{AB}{BC}$$

$$\mathrm{BC} = \frac{AB}{\sqrt{3}}$$

$$\mathrm{CD} = \mathrm{BD} - \mathrm{BC}$$

$$= AB - \frac{AB}{\sqrt{3}}$$

$$\mathrm{CD} = AB \frac{(\sqrt{3} - 1)}{\sqrt{3}}$$

Dis. covered in 10 min = \frac{AB(\sqrt{3} - 1)}{\sqrt{3}}$$

time taken to cover dis. \(\frac{AB}{\sqrt{3}}$$

$$ \frac{100\times\sqrt{3}}{AB(\sqrt{3}-1)}\times\frac{AB}{\sqrt{3}} $$

$$=\frac{10\times\left(\sqrt{3}+1\right)}{3-1}\Rightarrow5(1.73+1)$$

=13.6min.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.868Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
