INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4472, 'general-test-2022-08-23-shift-1', 'q01', 1, 1, 'In which city Major Dhyan Chand Sports University is established?', '[{"id":"A","text":"New Delhi"},{"id":"B","text":"Amritsar"},{"id":"C","text":"Meerut"},{"id":"D","text":"Ahmedabad"}]', 0, 'C', 'Prime Minister Narendra Modi Has laid the foundation stone for Major Dhyan Chand Sports University in Meerut, Uttar Pradesh. This sports university is being established at an estimated cost of ₹700 crore at the Salawa and Kaili villages of the Sardhana town in Meerut. It will have the capacity of training 1,080 sportspersons, including 540 women and 540 men.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.873Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4473, 'general-test-2022-08-23-shift-1', 'q02', 2, 2, 'Match List-I with List-II.', '[{"id":"A","text":"(A)-(II), (B)-(III), (C)-(IV), (D)-(I)"},{"id":"B","text":"(A)-(IV), (B)-(I), (C)-(III), (D)-(II)"},{"id":"C","text":"(A)-(III), (B)-(I), (C)-(IV), (D)-(II)"},{"id":"D","text":"(A)-(I), (B)-(II), (C)-(IV), (D)-(III)"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q02-table-1","kind":"table","path":"/local-papers/assets/general-test-2022-08-23-shift-1/q02-table-1.jpg","page":1,"alt":"Table for question 2"}]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.873Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4474, 'general-test-2022-08-23-shift-1', 'q03', 3, 3, 'The rate at which banks part short-term excess liquidity with RBI, is called.', '[{"id":"A","text":"Repo Rate"},{"id":"B","text":"Reverse Repo Rate"},{"id":"C","text":"Bank Rate"},{"id":"D","text":"Cash Reserve Ratio"}]', 0, 'B', 'Reverse Repo Rate is the rate the central bank of a country apays its commercial banks to park their excess funds in the central bank. It is the rate at which banks earn inter-when they park surplus funds with the RBI. It helps to control inflation, and increases liquidity in the economy. The repo rate set by the RBI is always higher than the reverse repo.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.873Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4475, 'general-test-2022-08-23-shift-1', 'q04', 4, 4, 'Who has designed the National Flag of India?', '[{"id":"A","text":"Sarojini Naidu"},{"id":"B","text":"Subhash Chandra Bose"},{"id":"C","text":"Pingali Venkayya"},{"id":"D","text":"C. Rajagopalachari"}]', 0, 'C', 'Pingali Venkayya designed the National Flag of India. The design of the flag of India that was first presented in 1921 to Mahatma Gandhi, leader of the All-India Congress, was created by Pingali Venkayya. He was also as a lecturer author, geologist, Educationalist, agriculturist, and a polyglot.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.873Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4476, 'general-test-2022-08-23-shift-1', 'q05', 5, 5, 'Which among the following are considered as Vedangas?

(A) Kalp

(B) Ayurveda

(C) Vyakaran

(D) Manu Smriti

(E) Jyotish', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(B), (D) and (E) only"},{"id":"C","text":"(A), (C) and (E) only"},{"id":"D","text":"(A), (C) and (D) only"}]', 0, 'C', 'Vedangas, are six auxiliaries'' disciplines associated with the study understanding Of the Vedas. These are Shiksha, Chhandas, Vyakarana, Nirukta, Kalpa and Jyotisha. The Vedangas are the last treatises of the Vedic Literature.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.873Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
