INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4514, 'general-test-2022-08-23-shift-1', 'q46', 43, 43, 'Find the value of $ \frac{5^{2/3} \times \sqrt[3]{5^{7}}}{\sqrt[3]{5^{6}}} $', '[{"id":"A","text":"5"},{"id":"B","text":"1"},{"id":"C","text":"$ \\sqrt{5} $"},{"id":"D","text":"$ 3\\sqrt{5} $"}]', 0, 'A', '$ \frac{5^{2/3}\times\sqrt[3]{5^{7}}}{\sqrt[3]{5^{6}}}=\frac{5^{2/3}\times5^{7/3}}{5^{6/3}} $

$ =\frac{5^{9/3}}{5^{2}}=\frac{5^{3}}{5^{2}}=5 $

Hence, option A is correct option.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.878Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4515, 'general-test-2022-08-23-shift-1', 'q47', 44, 44, 'The angle of depression of a point situated at a distance 100 m from the base of a pole is $ 30^{\circ} $. The height of the pole is:', '[{"id":"A","text":"$ 100(\\sqrt{3} + 1)m $"},{"id":"B","text":"$ \\frac{100}{3}m $"},{"id":"C","text":"$ \\frac{100}{3}\\sqrt{3}m $"},{"id":"D","text":"$ 100\\sqrt{3}m $"}]', 0, 'C', 'In $ \Delta ABC $

$ \tan 30^{\circ} = \frac{h}{100} $

$$ \frac{1}{\sqrt{3}}=\frac{h}{100} $$

$$ h=\frac{100\times\sqrt{3}}{\sqrt{3}\times\sqrt{3}} $$

$$ h=\frac{100\sqrt{3}}{3}m $$

Hence, option C is correct option.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.878Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
