INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4518, 'general-test-2022-08-23-shift-1', 'q50', 47, 47, 'If $ \sqrt[3]{x} = 2y $. Then, the value of $ \frac{y^3}{x} $ is _', '[{"id":"A","text":"1"},{"id":"B","text":"2/5"},{"id":"C","text":"1/8"},{"id":"D","text":"8"}]', 0, 'C', 'Given that, $ \sqrt[3]{x} = 2y $

