INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4520, 'general-test-2022-08-23-shift-1', 'q52', 49, 49, 'The value of $ \sqrt{0.01} \times \sqrt[3]{0.027} - 0.3 $ is', '[{"id":"A","text":"0.1"},{"id":"B","text":"0.27"},{"id":"C","text":"0.027"},{"id":"D","text":"0.1"}]', 0, 'B', 'Given that,

