The logical order is Grass - Grasshopper - Frog - Snake - Eagle', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.884Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
