So, required ratio = 330 : 330 = 1:1', NULL, 'null', '[]', '[]', '[6]', 'keyed', '[]', '2026-11-05T20:59:06.886Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4543, 'general-test-2022-10-06-shift-1', 'q01', 1, 1, 'Actress and Model "Harnaaz Sandhu" was crowned as _ in Dec 2021.', '[{"id":"A","text":"Miss World 2021"},{"id":"B","text":"Miss India 2021"},{"id":"C","text":"Miss Universe 2021"},{"id":"D","text":"Miss Earth 2021"}]', 0, 'C', 'Actress and Model "Harnaaz Sandhu" was crowned as Miss Universe in Dec 2021.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.886Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4544, 'general-test-2022-10-06-shift-1', 'q02', 2, 2, 'If each side of a cube is reduced by 50% the surface area will be reduced by.', '[{"id":"A","text":"75%"},{"id":"B","text":"50%"},{"id":"C","text":"25%"},{"id":"D","text":"100%"}]', 0, 'C', 'Let the side of the cube $a$.

Surface area of the cube = $6a^{2}$

In second case, decrease in side = 50%

$\therefore$ Side = $\frac{100-50}{100} \times a = \frac{a}{2}$

$\therefore$ Total surface area = $6\left(\frac{a}{2}\right)^{2} = \frac{6a^{2}}{4}$

$\therefore$ Change of total surface area = $\frac{\frac{6a^{2}}{4}}{6a^{2}} \times 100 = 25\%$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.886Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4545, 'general-test-2022-10-06-shift-1', 'q03', 3, 3, 'If * is an operation such that a *b = 3a - 4b, find the value of 3 * 4', '[{"id":"A","text":"0"},{"id":"B","text":"7"},{"id":"C","text":"7"},{"id":"D","text":"1"}]', 0, 'B', 'If $ a * b = 3a - 4b $

$ \Rightarrow 3 \times 4 = 3(3) - 4(4) = 9 - 16 = -7 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.887Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4546, 'general-test-2022-10-06-shift-1', 'q04', 4, 4, 'In a certain language TRIANGLE is written as VTKCPING. How RECTANGLE will be written in this language?', '[{"id":"A","text":"TGEUCPING"},{"id":"B","text":"TGEVCPKNG"},{"id":"C","text":"TGEVCPING"},{"id":"D","text":"GTEVCPING"}]', 0, 'C', 'Each letter in the word is moved two steps forward to obtain the corresponding letter of the code.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.887Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4547, 'general-test-2022-10-06-shift-1', 'q05', 5, 5, 'The next figure is', '[{"id":"A","text":""},{"id":"B","text":""},{"id":"C","text":""},{"id":"D","text":""}]', 1, 'A', 'In each step, ''+'' moves one step in anti-clockwise direction and one diagonal is replaced by another in every step.', NULL, 'null', '[]', '[{"id":"q05-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q05-figure-1.jpg","page":1,"alt":"Figure for question 5"},{"id":"q05-options","kind":"options","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q05-options.jpg","page":1,"alt":"Printed answer choices for question 5"}]', '[1]', 'keyed', '["image-options"]', '2026-11-05T20:59:06.887Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4548, 'general-test-2022-10-06-shift-1', 'q06', 6, 6, 'Two numbers are in ratio of 7:10 and if the sum of the numbers is 119. Find the difference of the numbers.', '[{"id":"A","text":"7"},{"id":"B","text":"21"},{"id":"C","text":"17"},{"id":"D","text":"12"}]', 0, 'B', 'Let two numbers are x and y

Given: Two numbers are in ratio of 7:10

$ \Rightarrow x = 7k, y = 10k $

If the sum of the numbers is 119

$ \Rightarrow 7k + 10k = 119 $

= 17k = 119

= k = 7

So, two numbers are $ x = 7 \times 7 = 49 $, y = 10 $ \times $ 7 = 70

Hence, difference of the two numbers = y - x = 70 - 49 = 21', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.887Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4549, 'general-test-2022-10-06-shift-1', 'q07', 7, 7, 'Who is the first Chief of Defence Staff of the Indian Armed forces?', '[{"id":"A","text":"Field Marshal K. M. Cariappa"},{"id":"B","text":"General Manoj Mukund Narayan"},{"id":"C","text":"General Bipin Rawat"},{"id":"D","text":"General Manoj Pande"}]', 0, 'C', 'General Bipin Rawat was the first Chief of Defence Staff (CDS) of the Indian Armed Forces. He assumed office on January 1, 2020, and held the position until his unfortunate demise in a helicopter crash on December 8, 2021. The position of CDS was created in December 2019 to improve coordination and integration between the three branches of the Indian Armed Forces: the Army, Navy, and Air Force.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.887Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4550, 'general-test-2022-10-06-shift-1', 'q08', 8, 8, 'In the given figure ABCD is a rhombus, the value of x is.', '[{"id":"A","text":"$ 40^{\\circ} $"},{"id":"B","text":"$ 50^{\\circ} $"},{"id":"C","text":"$ 90^{\\circ} $"},{"id":"D","text":"$ 60^{\\circ} $"}]', 0, 'B', 'As we know that, CD ||AB, so alternate angles are equal

$\Rightarrow \angle CDB = \angle ABD = x$

Since, Diagonals of a rhombus are perpendicular to each other

In $\Delta AOB$

$\Rightarrow \angle OAB + \angle ABO + \angle BOA = 180^{\circ}$

$\Rightarrow \angle ABO = 180^{\circ} - 40^{\circ} - 90^{\circ}$

$\Rightarrow x = 180^{\circ} - 130^{\circ}$

$\Rightarrow x = 50^{\circ}$', NULL, 'null', '[]', '[{"id":"q08-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q08-figure-1.jpg","page":1,"alt":"Figure for question 8"}]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.888Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
