INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4555, 'general-test-2022-10-06-shift-1', 'q13', 13, 13, 'Match List I with List II', '[{"id":"A","text":"A-II, B-IV, C-III, D-I"},{"id":"B","text":"A-I, B-III, C-IV, D-II"},{"id":"C","text":"A-II, B-III, C-IV, D-I"},{"id":"D","text":"A-II, B-I, C-IV, D-III"}]', 0, 'C', 'A. $2x-4=2-x$

$\Rightarrow 3x=6$

$\Rightarrow x=2$

So, $A \to II$

B. $7-4x=0$

$\Rightarrow x=\frac{7}{4}$

So, $B \to III$

C. $\frac{x}{2}-3=0$

$\Rightarrow x=6$

So, $C \to IV$

D. $2x+3=x+6$

$\Rightarrow x=6-3$

$\Rightarrow x=3$

So, $D \to I$', NULL, 'null', '[]', '[{"id":"q13-table-1","kind":"table","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q13-table-1.jpg","page":2,"alt":"Table for question 13"}]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.888Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
