INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4564, 'general-test-2022-10-06-shift-1', 'q22', 22, 22, 'In the given figure $l \parallel m$ || $n$, the value of $x$ is', '[{"id":"A","text":"$ 80^{\\circ} $"},{"id":"B","text":"$ 70^{\\circ} $"},{"id":"C","text":"$ 60^{\\circ} $"},{"id":"D","text":"$ 50^{\\circ} $"}]', 0, 'D', 'Since, $l||m||n$

So, alternate angles are equal

$\angle1 = 120^{\circ}$

$\Rightarrow \angle1 + \angle2 = 180^{\circ}$

$=\angle2 = 180^{\circ} - 120^{\circ} = 60^{\circ}$

As we know that, sum of angles of triangle is $180^{\circ}$

$\Rightarrow \angle2 + 60^{\circ} + 70^{\circ} = 180^{\circ}$

$=\angle2 = 180^{\circ} - 130^{\circ}$

$=\angle2 = 50^{\circ}$', NULL, 'null', '[]', '[{"id":"q22-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q22-figure-1.jpg","page":2,"alt":"Figure for question 22"}]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.890Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4565, 'general-test-2022-10-06-shift-1', 'q23', 23, 23, 'On which date World Environment Day is celebrated?', '[{"id":"A","text":"21 June"},{"id":"B","text":"5 June"},{"id":"C","text":"21 July"},{"id":"D","text":"22 March"}]', 0, 'B', 'World Environment Day - 05 - June.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.890Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
