INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4575, 'general-test-2022-10-06-shift-1', 'q34', 34, 33, 'Which one of the following bills must be passed by each house of the India parliament separately by special majority?', '[{"id":"A","text":"Money Bill"},{"id":"B","text":"Finance Bill"},{"id":"C","text":"Ordinary Bill"},{"id":"D","text":"Constitutional Amendment Bill"}]', 0, 'D', '"Constitutional Amendment Bill" must be passed by each house of the Indian Parliament separately by special Majority.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4576, 'general-test-2022-10-06-shift-1', 'q35', 35, 34, 'The average of first 8 multiples of 8 is.', '[{"id":"A","text":"41"},{"id":"B","text":"45"},{"id":"C","text":"36"},{"id":"D","text":"31 (b) (c) (d)"}]', 0, 'C', 'First 8 multiples of 8 are 8, 16, 24, 32, 40, 48, 56, 64

So, average of first 8 multiples of 8 =

$ \frac{Sum\ of\ numbers}{total\ number}=\frac{8+16+24+32+40+48+56+64}{8}=36 $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4577, 'general-test-2022-10-06-shift-1', 'q37', 37, 35, 'At hill station, the boiling point of water will be _.', '[{"id":"A","text":"Same as at sea level"},{"id":"B","text":"More than that at sea level"},{"id":"C","text":"Less than that at sea level"},{"id":"D","text":"Equal to the melting point of Ice"}]', 0, 'C', 'At hill station, the boiling point of Water will be less than that at sea level.

Sol. A rectangular paper of width 8 cm is rolled along its width to form a cylinder.

Circumference of base = 22 cm

$\Rightarrow 2\pi r = 22$

$r = \frac{22}{2\pi}$

$r = \frac{22\times7}{2\times22} = \frac{7}{2}\text{cm}$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4578, 'general-test-2022-10-06-shift-1', 'q38', 38, 36, 'The radius of the cylinder is-', '[{"id":"A","text":"$ \\frac{2}{7} $ cm"},{"id":"B","text":"7 cm"},{"id":"C","text":"$ \\frac{7}{2} $ cm"},{"id":"D","text":"14 cm"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4579, 'general-test-2022-10-06-shift-1', 'q39', 39, 37, 'If the outer surface area of cylinder is pointed at the rate of $ \bar{x}\ 0.5/cm^{2} $, then the total cost of painting is', '[{"id":"A","text":"₹88"},{"id":"B","text":"₹176"},{"id":"C","text":"₹78"},{"id":"D","text":"₹186"}]', 0, 'A', 'Outer surface area of cylinder = $2\pi rh$

Height of cylinder = 8 cm

Radius of cylinder = $\frac{7}{2}$ cm

$\Rightarrow$ Outer surface area of cylinder = $2 \times \frac{22}{7} \times \frac{7}{2} \times 8 = 176 \, cm^{2}$

$\Rightarrow$ total cost = $0.5 \times 176 = 88$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4580, 'general-test-2022-10-06-shift-1', 'q40', 40, 38, 'The volume of cylinder is', '[{"id":"A","text":"98cm³"},{"id":"B","text":"49πcm³"},{"id":"C","text":"49cm³"},{"id":"D","text":"98πcm³"}]', 0, 'D', 'Volume of cylinder = $ \pi r^{2} h $

$ =\frac{7}{2}\times\frac{7}{2}\times8\pi=98\pi cm^{3} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.891Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
