INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4587, 'general-test-2022-10-06-shift-1', 'q47', 47, 45, 'Find the value of $ (25)^{3}+(-29)^{3}+(4)^{3} $', '[{"id":"A","text":"8700"},{"id":"B","text":"0"},{"id":"C","text":"8700"},{"id":"D","text":"2900"}]', 0, 'A', '$ \Rightarrow(25)^{3}+(-29)^{3}+4^{3}=-8700 $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.892Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4588, 'general-test-2022-10-06-shift-1', 'q48', 48, 46, 'If the area and sum of parallel side of a trapezium are 48 cm² and 48cm respectively. Then the distance between the parallel sides is', '[{"id":"A","text":"$ \\frac{1}{2} $ cm"},{"id":"B","text":"1 cm"},{"id":"C","text":"2 cm"},{"id":"D","text":"3 cm"}]', 0, 'C', 'The area of trapezium id given as 48\ cm^{2} with the sum of its parallel sides as 48\ cm. Let d be the distance between the parallel sides, then

$ \Rightarrow $ Area = $ \frac{1}{2} $(sum of the parallel sides) $ \times $ h

$ \Rightarrow 48 = \frac{1}{2} \times 48 \times d $

$ \Rightarrow d = 2 \, cm $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.892Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4589, 'general-test-2022-10-06-shift-1', 'q49', 49, 47, 'One TB (Tera Byte) approximately occupies or comprises which of the following data or space size', '[{"id":"A","text":"1000 KB"},{"id":"B","text":"1000 GB"},{"id":"C","text":"1024 KB"},{"id":"D","text":"1024 GB"}]', 0, 'D', 'One terabyte (TB) is approximately equal to 1024 gigabytes (GB). The storage capacity of digital devices is often measured in these units.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.892Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4590, 'general-test-2022-10-06-shift-1', 'q50', 50, 48, 'If 36 persons can finish 50% of work in 12 days. In how many days 72 person can finish the complete work?', '[{"id":"A","text":"6"},{"id":"B","text":"3"},{"id":"C","text":"9"},{"id":"D","text":"12"}]', 0, 'D', '36 persons can finish 50% of work in 12 days

36 persons can finish 100% of work in 24 days

We have to find 72 persons will take how many days

So, suppose $ x_{1}=36 $, $ y_{1}=24 $, $ x_{2}=72 $, $ y_{2}=? $

Applying inverse proportional formula to solve

As it is the relation between work and time. So, it will be an inverse proportion,

So, $ \frac{x_{2}}{x_{1}} = \frac{y_{1}}{y_{2}} $

$ \Rightarrow \frac{72}{36} = \frac{24}{y_{2}} $

$ = y_{2} = \frac{24 \times 36}{72} = 12 $ days', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4591, 'general-test-2022-10-06-shift-1', 'q51', 51, 49, 'Who is known as ''Nightingale of India''?', '[{"id":"A","text":"Vijaya Laxmi Pandit"},{"id":"B","text":"Indira Gandhi"},{"id":"C","text":"Sarojini Naidu"},{"id":"D","text":"Lata Mangeshkar"}]', 0, 'C', 'Sarojini Naidu was known as the Nightingale of India.', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
