INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4593, 'general-test-2022-10-06-shift-1', 'q53', 53, 51, 'A shopkeeper offers discount 50% + 50% on a shirt of M.R.P ₹800, find the selling price of the shirt.', '[{"id":"A","text":"₹700"},{"id":"B","text":"₹0"},{"id":"C","text":"₹400"},{"id":"D","text":"₹200"}]', 0, 'D', 'A shopkeeper offers discount 50% + 50% on a shirt of M.R.P ₹800

⇒ 50% on a shirt of M.R.P ₹800 = ₹ 400

⇒ A shopkeeper offer discount 50 % = ₹ 200

So, selling price of shirt is ₹ 200', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4594, 'general-test-2022-10-06-shift-1', 'q54', 54, 52, 'Pointing a man in a photograph, Karina Said, ''His mother is the only daughter of my mother,'' How is Karina related to the man of photograph.', '[{"id":"A","text":"Mother"},{"id":"B","text":"Sister"},{"id":"C","text":"Wife"},{"id":"D","text":"Daughter"}]', 0, 'A', 'Karina will be mother of man in the photograph.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4595, 'general-test-2022-10-06-shift-1', 'q55', 55, 53, 'If 180 meter long train crosses a pole in 9 seconds, find the speed of train in kilo meter/hour.', '[{"id":"A","text":"72 km/h"},{"id":"B","text":"36 km/h"},{"id":"C","text":"20 km/h"},{"id":"D","text":"90 km/h"}]', 0, 'A', 'Speed = $ \frac{Distance}{Time} = \frac{Length of train}{Time taken} = \frac{180}{9} $ m/sec = $ 20 \times \frac{18}{5} $ km/hr = 72 km/hr', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4596, 'general-test-2022-10-06-shift-1', 'q56', 56, 54, 'Match List I with List II', '[{"id":"A","text":"A-II, B-IV, C-I, D-III"},{"id":"B","text":"A-III, B-II, C-IV, D-I"},{"id":"C","text":"A-IV, B-I, C-II, D-III"},{"id":"D","text":"A-IV, B-I, C-III, D-II"}]', 0, 'C', NULL, NULL, 'null', '[]', '[{"id":"q56-table-1","kind":"table","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q56-table-1.jpg","page":5,"alt":"Table for question 56"}]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4597, 'general-test-2022-10-06-shift-1', 'q57', 57, 55, 'If the cost of 4 pens and 6 note books is 800, then find the cost of 6 pens and 9 note books.', '[{"id":"A","text":"₹ 900"},{"id":"B","text":"₹ 1200"},{"id":"C","text":"₹ 1000"},{"id":"D","text":"₹ 1100"}]', 0, 'B', 'Let the cost of 1 pen and 1 note book be $ \bar{x} $ x and $ \bar{y} $ respectively.

$ \Rightarrow 4x + 6y = 800 $

$ = 2x + 3y = 400 $

$ \Rightarrow 6x + 9y = 1200 $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4598, 'general-test-2022-10-06-shift-1', 'q58', 58, 56, 'The value of $ \frac{(2\cdot7)^{3}-(2\cdot2)^{3}}{(2\cdot7)^{2}+2\cdot7\times2\cdot2+(2\cdot2)^{2}} $ is', '[{"id":"A","text":"4.9"},{"id":"B","text":"0.5"},{"id":"C","text":"0.05"},{"id":"D","text":"0.49"}]', 0, 'B', '$ \Rightarrow\frac{(2\cdot7)^{3}-(2\cdot2)^{3}}{(2\cdot7)^{2}+2\cdot7\times2\cdot2+(2\cdot2)^{2}}= $

$ \frac{(2.7-2.2)\left((2.7)^{2}+2.7\times2.2+(2.2)^{2}\right)}{((2.7)^{2}+2.7\times2.2+(2.2)^{2})}=2.7-2.2=0.5 $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.893Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4599, 'general-test-2022-10-06-shift-1', 'q59', 59, 57, 'EVM Stands for _.', '[{"id":"A","text":"Electric Vending Machine"},{"id":"B","text":"Electronic Vending Machine"},{"id":"C","text":"Electronic Voting Machine"},{"id":"D","text":"Electric Voting Machine"}]', 0, 'C', 'EVM stands for Electronic Voting Machine.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4600, 'general-test-2022-10-06-shift-1', 'q60', 60, 58, 'If the volume of a cube is $ 27cm^3 $, then the diagonal of cube is', '[{"id":"A","text":"3 cm"},{"id":"B","text":"$ 3\\sqrt{3} $ cm"},{"id":"C","text":"$ \\sqrt{3} $ cm"},{"id":"D","text":"$ \\frac{1}{\\sqrt{3}} $ cm"}]', 0, 'B', 'Volume of cube = (side) $ ^{3} $

Diagonal of cube = $ \sqrt{3} \times $ side

$ \Rightarrow $ (side) $ ^{3} $ = 27

$ \Rightarrow $ side = 3 cm

$ \Rightarrow $ Diagonal of cube = $ 3\sqrt{3} $ cm', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4601, 'general-test-2022-10-06-shift-1', 'q61', 61, 59, 'An Atoll is _.', '[{"id":"A","text":"A lake in the Crates"},{"id":"B","text":"A Lagoon along the shores"},{"id":"C","text":"A lake in Glaciated mountains"},{"id":"D","text":"A ring-shaped island with a lagoon at the Centre"}]', 0, 'D', 'An Atoll is a ring-shaped Island with a lagoon at the centre.', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4602, 'general-test-2022-10-06-shift-1', 'q62', 62, 60, 'The area of $ \Delta $ ABF is.', '[{"id":"A","text":"180 m $ ^{2} $"},{"id":"B","text":"90 m $ ^{2} $"},{"id":"C","text":"125 m $ ^{2} $"},{"id":"D","text":"60 m $ ^{2} $"}]', 0, 'B', 'Given: AC = 25 m, AG = 12 m, BC = 7 m

$ \Rightarrow $ AG + GB + BC = AC

$ \Rightarrow $ 12 + GB + 7 = 25

$ \Rightarrow $ GB = 25 - 12 - 7

$ \Rightarrow $ GB = 25 - 19 = 6 m

$ \Rightarrow $ AB = AG + GB = 12 + 6 = 18 m

In $ \Delta $ ABF

$ \therefore $ Required area = $ \frac{1}{2} \times BF \times AB = \frac{1}{2} \times 10 \times 18 = 90 \, m^{2} $', NULL, 'null', '[]', '[{"id":"q62-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q62-figure-1.jpg","page":5,"alt":"Figure for question 62"}]', '[5]', 'keyed', '["shared-direction-image"]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4603, 'general-test-2022-10-06-shift-1', 'q63', 63, 61, 'The area of Trapezium DGCE is.', '[{"id":"A","text":"100 m $ ^{2} $"},{"id":"B","text":"260 m $ ^{2} $"},{"id":"C","text":"70 m $ ^{2} $"},{"id":"D","text":"130 m $ ^{2} $"}]', 0, 'D', 'In Trapezium DGCE

$ \Rightarrow $ Area of trapezium $ \frac{1}{2}(DG + EC) \times GC $

$ =\frac{1}{2}(5 + 15) \times (7 + 6) $

$ =\frac{1}{2} \times 20 \times 13 $

$ =130 \, m^{2} $', NULL, 'null', '[]', '[{"id":"q63-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q63-figure-1.jpg","page":5,"alt":"Figure for question 63"}]', '[5]', 'keyed', '["shared-direction-image"]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4604, 'general-test-2022-10-06-shift-1', 'q64', 64, 62, 'Area of $ \Delta $ AFC is.', '[{"id":"A","text":"$ 85 \\, m^2 $"},{"id":"B","text":"$ 75 \\, m^2 $"},{"id":"C","text":"$ 125 \\, m^2 $"},{"id":"D","text":"$ 250 \\, m^2 $"}]', 0, 'C', 'Area of $ \Delta AFC = \frac{1}{2} \times AC \times BF = \frac{1}{2} \times 25 \times 10 = 125 \, m^{2} $', NULL, 'null', '[]', '[{"id":"q64-figure-1","kind":"figure","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q64-figure-1.jpg","page":5,"alt":"Figure for question 64"}]', '[5]', 'keyed', '["shared-direction-image"]', '2026-11-05T20:59:06.894Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
