INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4606, 'general-test-2022-10-06-shift-1', 'q66', 66, 64, 'If 60% of 80 = x% of 96, then x is.', '[{"id":"A","text":"50"},{"id":"B","text":"40"},{"id":"C","text":"55"},{"id":"D","text":"45"}]', 0, 'A', 'If 60% of 80 = x% of 96

$ \Rightarrow \frac{60}{100} \times 80 = \frac{x}{100} \times 96 $

$ = 48 = \frac{96x}{100} $

$ = x = \frac{48 \times 100}{96} $

$ = x = 50 $', NULL, 'null', '[]', '[]', '[5]', 'keyed', '[]', '2026-11-05T20:59:06.895Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
