INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4611, 'general-test-2022-10-06-shift-1', 'q75', 75, 69, 'Match List I with List II', '[{"id":"A","text":"A-II, B-I, C-IV, D-III"},{"id":"B","text":"A-III, B-I, C-IV, D-II"},{"id":"C","text":"A-III, B-IV, C-I, D-II"},{"id":"D","text":"A-II, B-IV, C-I, D-III"}]', 0, 'B', 'Article - 368 → Constitutional Amendment

Article - 40 → Panchayati Raj

Article - 61 → Impeachment of President

Article - 352 → Emergency Provision', NULL, 'null', '[]', '[{"id":"q75-table-1","kind":"table","path":"/local-papers/assets/general-test-2022-10-06-shift-1/q75-table-1.jpg","page":7,"alt":"Table for question 75"}]', '[7]', 'keyed', '[]', '2026-11-05T20:59:06.898Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4612, 'geography-2022', 'q01', 1, 1, 'Griffith Taylor introduced which concept of human geography?', '[{"id":"A","text":"Environmental determinism"},{"id":"B","text":"New determinism"},{"id":"C","text":"Possibilism"},{"id":"D","text":"Dualism"}]', 0, 'B', 'The concept of Neo Determinism was introduced by Griffith Taylor which emphasises the middle path or madhyam marg between two ends of environmental determinism and possibilism.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4613, 'geography-2022', 'q02', 2, 2, 'Identify scholar, who voiced his concern about the growing scarcity of resources as compared to the human population?', '[{"id":"A","text":"Griffith Taylor"},{"id":"B","text":"Robert Malthus"},{"id":"C","text":"Ratzel"},{"id":"D","text":"Karl Marx"}]', 0, 'B', 'British economist Thomas Malthus coined the term overpopulation in the late 1700s. Malthus suggested that the world''s population was growing faster than the rate of food production, and as a result, mass starvation would occur.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4614, 'geography-2022', 'q03', 3, 3, 'Identify the push factors of migration from the following:

(A) Unemployment

(B) Political turmoil

(C) Peace and Stability

(D) Socio-economic backwardness

(E) Security of life and property

Choose the correct answer from the options given below.

(A)(B)(C) only (D),(E) on', '[{"id":"A","text":"(A), (B), (C) only"},{"id":"B","text":"(C), (D), (E) only"},{"id":"C","text":"(A), (C), (D) only"},{"id":"D","text":"(A), (B), (D) only"}]', 0, 'D', 'Push factors cause people to leave their residence or place of origin. These are Unemployment, Political turmoil and Socio-economic backwardness from among the given options.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4615, 'geography-2022', 'q04', 4, 4, 'Which one of the following approach was proposed by the International Labour Organisation?', '[{"id":"A","text":"Capability Approach"},{"id":"B","text":"Welfare Approach"},{"id":"C","text":"Basic Needs Approach"},{"id":"D","text":"Income Approach"}]', 0, 'C', 'Basic Needs approach is the answer.

The ILO report for the 1976 World Employment Conference defined basic needs in terms of food, clothing, housing, education, and public transportation. The ILO was founded in October 1919. It is headquartered in Geneva, Switzerland.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4616, 'geography-2022', 'q05', 5, 5, 'Continuity in the availability of opportunities is related to which concept of Human Development?', '[{"id":"A","text":"Sustainability"},{"id":"B","text":"Equity"},{"id":"C","text":"Productivity"},{"id":"D","text":"Empowerment"}]', 0, 'A', 'Sustainability means continuity in the availability of opportunities. To have sustainable human development, each generation must have the same opportunities. All environmental, financial and human resources must be used keeping in mind the future. Misuse of any of these resources will lead to fewer opportunities for future generations.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4617, 'geography-2022', 'q06', 6, 6, 'Which one of the following is not a significant aspect of human development?', '[{"id":"A","text":"Decent standard of living"},{"id":"B","text":"Living a long and healthier life"},{"id":"C","text":"Guaranteed human rights and personal self respect"},{"id":"D","text":"Leisure and recreation with luxurious mobility"}]', 0, 'D', 'A decent standard of living; living a long and healthier life; and guaranteed human rights and persona self-respect are significant aspects of human development.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.899Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4618, 'geography-2022', 'q07', 7, 7, 'Identify the main features of capability approach to Human Development.

(A) This is the oldest approach to Human Development.

(B) This approach was initially proposed by International Labour Organisation.

(C) This approach is associated with Prof Amartya Sen.

(D) Access to resources is the key to increasing human development.', '[{"id":"A","text":"(C) and (A) only"},{"id":"B","text":"(C) and (D) only"},{"id":"C","text":"(A) and (R) only"},{"id":"D","text":"(A) and (D) only Study the passage and answer questions numbered. Benda lives in the wilds of the Abujh Maad area of central India. His village consists of three huts deep in the wilds. Not even birds or stray dogs that usually crowd villages can be soom1to too rno:tuo2 (vi) seen in these areas. Wearing a small loin cloth and armed with his axe he slowly surveys the penda (forest) where his tribe practices a primitive form of agriculture called shifting cultivation. Benda and his friends burn small patches of forest to clear them for cultivation. The ash is used for making the soil fertile. Benda is happy that the mahua trees around him are in bloom. How lucky I am to be a part of this beautiful universe, he thinks as he looks up to see the Mahua, Palash and Sal trees that have sheltered him since childhood. Crossing the penda in a gliding motion, Benda makes his way to a stream. As he bends down to scoop up a palmful of water, he remembers to thank Loi-Lugi, the spirit of the forest for allowing him to quench his thirst. Moving on with his friends, Benda chews on succulent leaves and roots. The boys have been trying to collect Gajjhara and Kuchla, from the forest. These are special plants that Benda and his people use. He hopes the spirits of the forest will be kind and lead him to these herbs. These are needed to barter in the madhai or tribal fair coming up the next full moon. He closes his eyes and tries hard to recall what the elders had taught him about these herbs and the places they are found in. He wishes he had listened more carefully. Suddenly there is a rustling of leaves. Benda and his friends know it is the outsiders who have come searching for them in the wilds. In a single fluid motion Benda and his friends disappear behind the thick canopy of trees and become one with the spirit of the forest."}]', 0, 'B', 'The capability approach (also referred to as the capabilities approach) is a normative approach to human welfare that concentrates on the actual capability of persons to achieve lives they value rather than solely having a right or freedom to do so. It was conceived in the 1980s as an alternative approach to welfare economics. In this approach, Amartya Sen and Martha Nussbaum combine a range of ideas that were previously excluded from (or inadequately formulated in) traditional approaches to welfare economics. The core focus of the capability approach is improving access to the resources people use to live a fulfilling life.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4619, 'geography-2022', 'q08', 8, 8, 'To which one of the following ''Benda'' represents as given in the passage?', '[{"id":"A","text":"Tribe living in the area"},{"id":"B","text":"Cultivator"},{"id":"C","text":"Trader"},{"id":"D","text":"Hunter"}]', 0, 'A', 'From the passage it is clear that Benda is a cultivator.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4620, 'geography-2022', 'q09', 9, 9, 'To which one of the following ''Penda'' is referred in the text?', '[{"id":"A","text":"A tribe (vi)-(C)"},{"id":"B","text":"A hut"},{"id":"C","text":"Forest (vi)-(C)"},{"id":"D","text":"Succulent leaves"}]', 0, 'C', 'Penda refers to the forest.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4621, 'geography-2022', 'q10', 10, 10, 'Benda went to the forest for $ \underline{\text{for}} $.', '[{"id":"A","text":"For hunting"},{"id":"B","text":"For bringing wood"},{"id":"C","text":"For collecting herbs"},{"id":"D","text":"For cultivating land"}]', 0, 'C', 'Benda went to the forest for collecting herbs.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4622, 'geography-2022', 'q11', 11, 11, 'Which one of the following products were collected by Benda?', '[{"id":"A","text":"Loi-Lungi"},{"id":"B","text":"Gajjhara and Kuchla"},{"id":"C","text":"Mahua and Palash"},{"id":"D","text":"Sal and Neen"}]', 0, 'B', 'Benda and his friends had been trying to collect Gajjhara and Kuchla.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4623, 'geography-2022', 'q12', 12, 12, 'At which of the following places, Benda exchanges collected herbal parts?', '[{"id":"A","text":"Mathai tribal fair"},{"id":"B","text":"Madhai tribal fair"},{"id":"C","text":"Mithai tribal fair"},{"id":"D","text":"Midhai tribal fair"}]', 0, 'B', 'Benda exchanges collected herbal plants from Madhai tribal fair.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4624, 'geography-2022', 'q13', 13, 13, 'The Silicon valley near San Francisco and Silicon Forest near Seattle are example of which type of industry?', '[{"id":"A","text":"Iron and Steel"},{"id":"B","text":"Cotton Textile"},{"id":"C","text":"Information technology"},{"id":"D","text":"Chemical"}]', 0, 'C', 'Silicon Valley near San Francisco and Silicon Forest near Seattle are examples of Information Technology industries.

The term Silicon Valley refers to a region in the South San Francisco Bay Area. The name was first adopted in the early 1970s because of the region''s association with the silicon transistor, which is used in all modern microprocessors. The area is notable for the vast number of technology companies that are headquartered there.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.900Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4625, 'geography-2022', 'q14', 14, 14, 'Match List-I with List-II

(A) Mixed farming

(B) Dairy farming

(C) Mediterranean Agriculture

(D) Viticulture and North Africa

(i) Mediterranean Region

(ii) North-Western Europe

(iii) New Zealand and Tasmania

(iv) Southern cost of Europe

Choose the correct answer from the options given below:

(a) (A)-(i), (B)-(ii), (C)-(iv), (D)-(iii)

(b) (A)-(ii), (B)-(iv), (C)-(i), (D)-(iii)

