INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4684, 'hindi-2022-08-30-shift-2', 'q28', 28, 28, 'कितने से कितने कर्म की साधना में कौन-सा भाव निहित होता है ?', '[{"id":"A","text":"प्रसनता"},{"id":"B","text":"प्रफुल्लाति"},{"id":"C","text":"सुन्दरता"},{"id":"D","text":"तत्पर्मा"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[18]', 'keyed', '["column-key"]', '2026-11-05T20:59:06.907Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4685, 'hindi-2022-08-30-shift-2', 'q29', 29, 29, 'निम्नलिखित गवाहों को पढ़कर उसके आधार पर प्रश्न का उत्तर दीर्घकाल $ \downarrow $ उत्साद वास्तव में कर्म और फल की मिली--जुली अनुमौதி है जिसकी प्रेरणा से तत्पश्चात्तिकी होती है। यदि फल दूर ही पर विस्तृत पड़े, उसकी भावना के साथ ही उसका लेशमात्र भी कर्म या प्रयत्न के साथ लगाय न मालूम हो तो हमारे हाथ--पाँच कभी न उठे और उस फल के साथ हमारा संयोग ही न हो। इससे कर्म शुश्ला की पहली कड़ी पकड़ते ही फल
कर्म-रामायण के आधार की बेहरी हो गई। किसी व्यक्ति को नीचे बहुत दूर तक गई हुई सीबीएी दिखारें दी और यह मालूम हुआ कि नीचे उतरने पर सोने का डेर मिलेगा। यदि उसमें इतनी सजीवता है कि उक्त सूचना के साथ ही वह उस स्वर्ण-राशि के साथ एक प्रकार के मान्यिक संयोग का अनुभव करने लगा तथा उसका चित प्रफुल्ल और अंग संचेष्ट हो गए, उसे एक-एक सीबी एस्नमयी दिखारें देगी, एक-एक सीबी उत्तरने में उसे आनंद मिला जाएगा, एक-एक भण उसे सुख से बीतता हुआ जान पड़ेगा और वह प्रसनता के साथ स्वर्णराशि तक पहुंचेगा। इस प्रकार उसके प्रयत-काल को भी फल-प्राप्त होता के अंतर्गत ही समझना चाहिए। इसके विरुद्ध यदि उसका हृदय दुर्बल होगा और उसमें इच्छामात्र ही उत्पन्न होकर रह जायँगेगी, तो अभाव के बोध के कारण उसके चित न में यही होगा कि कैसे ड्रट से नीचे पहुंच जाएं उसे एक-एक सीबी उत्तरना बुरा मालूम होगा और आश्रय नहीं कि वह या तो हाथकर बैठ जाए या लाइखडारक मुँह के बैला गिरे गये।
"जब तक फल तक पहुंचने याला कर्म-पथ अच्छा न लगेगा तब तक केवल फल का अच्छा लगना कुछ नहीं?" इस वाक्यां में कर्म-पथ का क्या आश्रय है?', '[{"id":"A","text":"कर्म से मुवीत"},{"id":"B","text":"कर्म की प्रांति"},{"id":"C","text":"कर्म से आश्रित"},{"id":"D","text":"कर्म करने का सही मार्ग"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[18]', 'keyed', '["column-key"]', '2026-11-05T20:59:06.907Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
