INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4778, 'history-2022-08-21-shift-2', 'q34', 34, 32, 'How did Gandhiji broaden the basis of Nationalism : (A) New branches of Congress were set up in various parts of India (B) A series of ''Praja Mandals'' were established to promote nationalist creed in the princely states (C) Gandhiji encouraged communication of nationalist message in the mother tongue (D) Gandhiji was not able to gather support of Indian entrepreneurs and industrialists Choose the correct answer from the options given below :', '[{"id":"A","text":"(A), (D), (C) only"},{"id":"B","text":"(A), (B), (C) only"},{"id":"C","text":"(C) & (D) only"},{"id":"D","text":"(A) and (B) only"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[15]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.920Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4779, 'history-2022-08-21-shift-2', 'q36', 36, 33, 'Arrange the following movements in order to their occurrence.\n(A) Kheda Satyagraha\n(B) Bardoli Satyagraha\n(C) Rowlatt Satyagraha\n(D) Quit India Movement\n(E) Champaran Satyagraha\nChoose the correct answer from the options given below :\n', '[{"id":"A","text":"(A), (D), (C), (B), (E)\\n"},{"id":"B","text":"(E), (A), (C), (B), (D)\\n"},{"id":"C","text":"(E), (D), (C), (B), (A)\\n"},{"id":"D","text":"(B), (C), (D), (A), (E)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[16]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.920Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
