INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4781, 'history-2022-08-21-shift-2', 'q38', 38, 35, 'Mahatma Gandhi tried to obtain for the peasants security of tenure and freedom to cultivate the crops of their choice in which of the following movement :\n', '[{"id":"A","text":"Chauri Chaura\\n"},{"id":"B","text":"Ahmedabad Satyagraha\\n"},{"id":"C","text":"Kheda Satyagraha\\n"},{"id":"D","text":"Champaran Satyagraha"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.920Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
