INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4784, 'history-2022-08-21-shift-2', 'q41', 41, 38, 'Read the passage given below and answer. From the Fifth Report Referring to the condition of zamindars and the auction of lands, the Fifth Report stated: The revenue was not realised with punctuality, and lands to a considerable extent were periodically exposed to sale by auction. In the native year 1203, corresponding with 1796-97, the land advertised for sale comprehended a jumma or assessment of siccarupees 28,70,061, the extent of land actually sold bore a jumma or assessment of 14,18,756, and the amount of purchase money siccarupees 17,90,416. In 1204, corresponding with 1797-98, the land advertised was for siccarupees 26,66,191, the quantity sold was for siccarupees 22,74,076, and the purchase money siccarupees 21,47,580. Among the defaulters were some of the oldest families of the country. Such were the rajah of Nuddea, Rajeshaye, Bishenpore (all districts of Bengal), ... and others, the dismemberment of whose estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in their efforts to preserve undiminished the amount of public assessment. Name the British East India company official who introduced the Permanent Settlement?', '[{"id":"A","text":"Lord William Bentinck"},{"id":"B","text":"Lord Cornwallis"},{"id":"C","text":"Lord Hastings"},{"id":"D","text":"Lord Wellesley"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.920Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4785, 'history-2022-08-21-shift-2', 'q42', 42, 39, 'Read the passage given below and answer. From the Fifth Report Referring to the condition of zamindars and the auction of lands, the Fifth Report stated: The revenue estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in their efforts to preserve undiminished the amount of public assessment. Name the British East India company official who introduced the Permanent Settlement? (1) Lord William Bentinck (2) Lord Cornwallis (3) Lord Hastings (4) Lord Wellesley
The revenue was not realised with punctuality, and lands to a considerable extent were periodically exposed to sale by auction. In the native year 1203, corresponding with 1796-97, the land advertised for sale comprehended a jumma or assessment of siccarupees 28,70,061, the extent of land actually sold bore a jumma or assessment of 14,18,756, and the amount of purchase money siccarupees 17,90,416. In 1204, corresponding with 1797-98, the land advertised was for siccarupees 26,66,191, the quantity sold was for siccarupees 22,74,076, and the purchase money siccarupees 21,47,580. Among the defaulters were some of the oldest families of the country. Such were the rajah of Nuddea, Rajeshaye, Bishenpore (all districts of Bengal), ... and others, the dismemberment of whose estates at the end of each succeeding year, threatened them with poverty and ruin, and in some instance presented difficulties to the revenue officers, in the efforts to preserve undiminished the amount of public assessment. What were the officials trying to show through the figures? (A) Maladministration, corruption and misrule by East India Company (B) Drawbacks of the system of Permanent Settlement (C) Inefficiency in Revenue collection (D) Collapse of the traditional Zamindari power Choose the correct answer from the options given below:', '[{"id":"A","text":"(A) and (D) only"},{"id":"B","text":"(B) and (C) only"},{"id":"C","text":"(B) and (D) only"},{"id":"D","text":"(A) and (C) only"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[17]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.920Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
