INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4833, 'mathematics-2022-08-17', 'q45', 41, 41, 'If the cost price of a cheese pizza is ₹30, a veg pizza is ₹50 and a paneer pizza is ₹50, what is the profit of outlet A in a day?', '[{"id":"A","text":"₹6300"},{"id":"B","text":"₹3300"},{"id":"C","text":"₹2300"},{"id":"D","text":"₹18300 A rectangle of length ''x'' and breadth ''y'' is inscribed in a semi-circle of fixed radius ''r'' as shown in the figure given below. $$ \\textcircled{2}0^{\\prime}=\\frac{q_{1}}{q_{2}}=(\\alpha+\\bar{\\alpha})\\frac{q_{1}}{q_{2}}=-\\left(\\Sigma\\right)_{\\xi}=4\\xi+2 $$ $$ \\frac{q x}{q y}=\\frac{\\frac{q y}{q x}}{q x}\\quad\\therefore\\quad\\frac{q x}{q y}=\\frac{(q+2)}{-151-41+2}. $$ $$ \\partial=x\\partial x^{\\prime},x=x(x)\\cap D\\setminus\\mathcal{C}_{m} $$ $$ s < x \\Leftarrow 0 < 4 - x \\leq $$ $$ \\textcircled{H}:\\quad\\textcircled{a}G(x,u)=|u|^{2n}\\left(\\frac{1-x}{3x}\\right) $$ $$ \\frac{(x)(y)}{xy}\\cdot\\frac{1}{(x)(y)}=\\frac{(x)(y)}{xy} $$ $$ 20^{\\circ}=\\frac{95}{11}-\\frac{5}{11}-\\frac{25}{11}\\left(\\frac{1}{x-1}\\right) $$ $$ \\frac{1}{x-1}+\\frac{1}{x-1}=\\frac{\\zeta}{(x-1)\\times\\zeta}=\\left[\\frac{x\\zeta+\\zeta(x-1)}{\\zeta(x-1)}\\right]\\frac{x-1}{x\\zeta}= $$ Based on the above information answer the following question"}]', 0, 'C', 'Now, CP of 40 cheese + 30 veg + 20 paneer = 40 × 30 + 50 × 30 + 20 × 50 = 1200 + 1500 + 1000 = ₹3700

and SP of 40 cheese + 30 veg + 20 paneer = ₹6000

Now, profit of outlet A in a day = 6000 - 3700 = ₹2300', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.926Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4834, 'mathematics-2022-08-17', 'q46', 42, 42, 'Area A(θ), 0 < θ < $ \frac{\pi}{2} $ of the rectangle ABCD, is', '[{"id":"A","text":"$ r^{2}\\sin\\theta $"},{"id":"B","text":"$ r^{2}\\sin2\\theta $"},{"id":"C","text":"$ r^{2}\\cos2\\theta $"},{"id":"D","text":"$ r^{2}\\cos\\theta $"}]', 0, 'B', 'From given figure,

Area (ABCD) = x \times y

Area $ (ABCD) = 2r^{2} \cos \theta \sin \theta $

$ = r^{2} \sin 2\theta $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.926Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4835, 'mathematics-2022-08-17', 'q48', 43, 43, 'Dimensions x, y of the rectangle ABCD, when area is maximum are:', '[{"id":"A","text":"$ r\\frac{\\sqrt{3}}{2},\\frac{2r}{\\sqrt{3}} $"},{"id":"B","text":"$ r\\sqrt{2},\\frac{r}{\\sqrt{2}} $"},{"id":"C","text":"$ \\frac{r}{\\sqrt{2}},\\sqrt{2}r $"},{"id":"D","text":"$ r,\\frac{r}{\\sqrt{2}} $"}]', 0, 'B', 'For maximum,

Area of rectangular ABCD.

$ A'' = 0 \Rightarrow \theta = \frac{\pi}{4} $

$ \therefore x = 2r \cos \theta \quad y = r \sin \theta $

$ x = \frac{2r}{\sqrt{2}} \quad y = \frac{r}{\sqrt{2}} $

$ x = \sqrt{2} r \quad y = \frac{r}{\sqrt{2}} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.927Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4836, 'mathematics-2022-08-17', 'q49', 44, 44, 'Maximum area of the rectangle is: (a) $ 2r^{2} $ (b) $ 3r^{2} $ (c) $ r^{2} $ (d) $ 4r^{2} $', '[{"id":"A","text":"$ 2r^{2} $"},{"id":"B","text":"$ 3r^{2} $"},{"id":"C","text":"$ r^{2} $"},{"id":"D","text":"$ 4r^{2} $"}]', 0, 'C', 'For maximum,

Area = max $ (r^{2}\sin2\theta)=r^{2} $

$ \Rightarrow $ Maximum area =r^{2}', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.927Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4837, 'mathematics-2022-08-17', 'q50', 45, 45, 'Perimeter of rectangle when its area is maximum is:', '[{"id":"A","text":"$ \\frac{8\\sqrt{3}r}{3} $"},{"id":"B","text":"4r"},{"id":"C","text":"$ \\frac{7\\sqrt{3}r}{3} $"},{"id":"D","text":"$ 3\\sqrt{2}r $ $$ 0=\\mathbf{\\Pi}\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}-x\\xi\\right)\\mathbf{\\xi}(1+x)-\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}\\right)\\xi_{x\\xi}+\\left(\\frac{\\psi^{\\mathrm{S b}}}{\\xi_{\\mathrm{S b}}}\\right)\\xi_{x\\xi}, $$ $$ \\xi=(w)\\operatorname{arccot}\\xi,t=(w)\\operatorname{sinc}\\xi $$ $$ (b-x)(x)=m^{2}+(b-x)^{2}, $$ $$ 0=\\frac{v_{x}^{2}b}{x b}:w=\\frac{v_{b}^{2}}{x b} $$ $$ \\begin{aligned}&(1)x=1\\Longrightarrow1=x+\\xi=0\\\\&T(x+1+x-1)=1-\\psi x^{2}\\psi x=0\\\\&\\frac{1}{x^{2}+1}\\left(1-x-1\\right)\\frac{\\psi x}{x^{2}+1}=\\frac{1}{x^{2}+1}\\end{aligned} $$ $$ \\mathrm{d}\\Delta\\mathrm{T}_{\\mathrm{b}}\\left[\\mathrm{T}_{\\mathrm{d}}\\right]^{\\mathrm{T}_{\\mathrm{b}}}=\\mathrm{d}\\mathrm{b}\\frac{\\mathrm{T}_{\\mathrm{b}}}{\\mathrm{M}}\\prod_{\\mathrm{c}}^{\\mathrm{T}_{\\mathrm{b}}} $$ $$ \\left[\\frac{\\Sigma}{\\nabla I}\\right]=\\frac{1}{4}\\operatorname{c o s}\\left[\\frac{\\nabla I}{2}\\right]\\operatorname{c o s}\\left[\\frac{1}{4}\\right] $$"}]', 0, 'D', 'For maximum area,

$$x = \sqrt{2} r; \quad y = \frac{r}{\sqrt{2}} = \frac{1}{(R)^q} = \frac{(R)^q}{(R + 1)^q}$$

So, perimeter = 2 ($x + y$)

$$= 2 \left( r \sqrt{2} + \frac{r}{\sqrt{2}} \right) = \frac{(1 + 1)(1 + 1)}{(1 + 1)(1 + 1)} = \frac{(1 + 1)(1 + 1)}{(1 + 1)(1 + 1)} = 2 r$$', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.927Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4838, 'mathematics-2022-08-22', 'q01', 1, 1, 'If the matrices $ \begin{bmatrix} 1-x^2 & 2y \\ x+5 & 0 \end{bmatrix}=\begin{bmatrix}-3 & y-1 \\ 7 & 0 \end{bmatrix} $ then the value of x and y is equal to:', '[{"id":"A","text":"x=2, y=-1"},{"id":"B","text":"x=-2, y=-1"},{"id":"C","text":"x=2, y=-2"},{"id":"D","text":"x=2, y=-1"}]', 0, 'B', '(A) Let, $I = \int\limits_{0}^{\pi/2}\frac{\sin^{4}x}{\sin^{4}x+\cos^{4}x}dx$

$=\int\limits_{0}^{\pi/2}\frac{\sin^{4}\left(\frac{\pi}{2}-x\right)}{\sin^{4}\left(\frac{\pi}{2}-x\right)+\cos^{4}\left(\frac{\pi}{2}-x\right)}dx$

$\Rightarrow I=\int\limits_{0}^{\pi/2}\frac{\cos^{4}x}{\sin^{4}x+\cos^{4}x}dx$

Now,

$2I=\int\limits_{0}^{\pi/2}\frac{(\cos^{4}x+\sin^{4}x)}{\cos^{4}x+\sin^{4}x}dx=\int\limits_{0}^{\pi/2}dx=\frac{\pi}{2}$

$\Rightarrow I=\frac{\pi}{4}$

(B) $\operatorname{Let} f(x)=\sin^{5}x\cos^{4}x$

$f(-x)=-\sin^{5}x\cos^{4}x=-f(x)$

So, $\int\limits_{-1}^{\pi/2}\sin^{5}x\cos^{4}x=0$

(C) $\int\limits_{1}^{\sqrt{3}}\frac{dx}{1+x^{2}}=\left[\tan^{-1}x\right]_{1}^{\sqrt{3}}=\frac{\pi}{3}-\frac{\pi}{4}=\frac{\pi}{12}$

(D) $\int\limits_{2}^{3}x^{2}dx=\left[\frac{x^{3}}{3}\right]_{-2}^{3}=\frac{27}{3}-\frac{8}{3}=\frac{19}{3}$

$D>A>C>B$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.927Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4839, 'mathematics-2022-08-22', 'q02', 2, 2, 'Match List-I with List-II

List-I List-II

A. If $A'' = -A$, I. Symmetric

then matrix A is

B. If $A'' = A$, then II. $(A'')^{-1}$

matrix A is

C. $(A^{-1})'' =$ III. $B''A''$

D. $(AB)'' =$ IV. Skew-symmetric', '[{"id":"A","text":"A-IV, B-I, C-III, D-II"},{"id":"B","text":"A-IV, B-I, C-II, D-III"},{"id":"C","text":"A-I, B-IV, C-II, D-III"},{"id":"D","text":"A-I, B-IV, C-III, D-II (d) A-1, B-IV, C-III, D-II"}]', 0, 'B', '(A) If $ A'' = -A \Rightarrow A $ is skew symmetric

(B) If $ A'' = A \Rightarrow A $ is symmetric

(C) $ (A^{-1})'' = (A'')^{-1} $

(D) $ (AB)'' = B''A'' $ (Reversal law)', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.928Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4840, 'mathematics-2022-08-22', 'q03', 3, 3, 'For what value of k the following system of linear equations is:

$ kx + 3y + 3z = 5 $; x - 2y + z = -4

3x - y - 2z = 3

has no solution?', '[{"id":"A","text":"k=2"},{"id":"B","text":"k=6"},{"id":"C","text":"k=-3"},{"id":"D","text":"k=-6"}]', 0, 'D', 'Given,

$ kx + 3y + 3z = 5 $

$ x - 2y + z = -4 $

$ 3x - y - 2z = 3 $

For no solution, $ \begin{vmatrix} k & 3 & 3 \\ 1 & -2 & 1 \\ 3 & -1 & -2 \end{vmatrix} = 0 $

$ \Rightarrow k(4+1)-3(-2-3)+3(-1+6)=0 $

$ \Rightarrow 5k+15+15=0 \Rightarrow k=-6 $

and $ D_{1}=\begin{vmatrix} 5 & 3 & 3 \\ -4 & -2 & 1 \\ 3 & -1 & -2 \end{vmatrix} $

$ =5(4+1)-3(8-3)+3(4+6) $

$ =25-15+30 $

$ D_{1}=40\neq0 $

So k=-6 for no solution', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.928Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4841, 'mathematics-2022-08-22', 'q04', 4, 4, 'If $ \mathrm{e}^{\mathrm{y}}(\mathrm{x}+1)=1 $ and $ \frac{\mathrm{d}^{2}\mathrm{y}}{\mathrm{d}x^{2}}=\left(\frac{\mathrm{dy}}{\mathrm{dx}}\right)^{k} $ then the least positive integer $ k'' $ is equal to', '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]', 0, 'B', 'Given, $ e^{y}(x+1)=1 $

$ y+\ln(x+1)=\ln(1) \Rightarrow y=-\ln(x+1) $

Now, $ \frac{dy}{dx}=\frac{-1}{x+1} $

$ \frac{d^2y}{dx^2}=\frac{1}{(x+1)^2}=\left(\frac{1}{x+1}\right)^2 $

$ \Rightarrow \frac{d^2y}{dx^2}=\left(\frac{dy}{dx}\right)^2 $. So, k=2', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.928Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4842, 'mathematics-2022-08-22', 'q05', 5, 5, 'The tangent to the curve $ y = e^{2x} $ at the point $ (0, 1) $ meets x-axis at:', '[{"id":"A","text":"$ (0,1) $"},{"id":"B","text":"$ \\left(-\\frac{1}{2},0\\right) $"},{"id":"C","text":"$ (2,0) $"},{"id":"D","text":"$ (0,2) $"}]', 0, 'B', 'Given the curve $y = e^{2x}$

Now, $\frac{dy}{dx} = 2e^{2x}$

At $(0, 2)$, $\frac{dy}{dx} = 2 \times 1 = 2$

Since, equation of tangent line $y - 1 = 2(x - 0) \Rightarrow y = 2x + 1$

At $x$-axis, $2x + 1 = 0 \Rightarrow x = -\frac{1}{2}$

$\Rightarrow$ Required point $(-\frac{1}{2}, 0)$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.930Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4843, 'mathematics-2022-08-22', 'q06', 6, 6, 'The interval on which the function $f(x)=-2x^{3}-9x^{2}-12x+1$ is increasing, is:', '[{"id":"A","text":"$(-2,-1)$"},{"id":"B","text":"$(-1,\\infty)$"},{"id":"C","text":"$(-\\infty,-2)\\cup(-1,\\infty)$"},{"id":"D","text":"$(-\\infty,-2)$"}]', 0, 'A', 'Given, $f(x) = -2x^3 - 9x^2 - 12x + 1$

$f''(x) = -6x^2 - 18x - 12$

For increasing off, $f''(x) > 0$

$\Rightarrow -6x^2 - 18x - 12 > 0$

$\Rightarrow x^2 + 3x + 2 < 0$

$\Rightarrow (x + 2)(x + 1) < 0$

$\frac{x + 1 - x + 1}{-2 -1}$

So, $ x \in (-2, -1) $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.930Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4844, 'mathematics-2022-08-22', 'q07', 7, 7, 'If $ \int \frac{x}{\sqrt{x-1}} \, dx = f(x) $ and solution of this integral is

$ f(x) = A(x-1)^{3/2} + B\sqrt{x-1} + C $, then which of the

followings are true?

(A) $ A = \frac{3}{2} $, $ B = \frac{1}{2} $ (B) $ A = \frac{2}{3} $, $ B = 2 $

(C) $ A = \frac{2}{3} $, B = -2 (D) Iff(2) = 0, then $ C = -\frac{8}{3} $

(E) Iff(1) = 0, then C = 1', '[{"id":"A","text":"A, D only"},{"id":"B","text":"B, E only"},{"id":"C","text":"B, D only"},{"id":"D","text":"D, E only"}]', 0, 'C', 'Since, $\int\frac{x}{\sqrt{x-1}}dx = f(x)$

Let $x-1=t^{2} \Rightarrow dx=2tdt$

$\Rightarrow \int\frac{x}{\sqrt{x-1}}dx=\int\frac{t^{2}+1}{t}2t dt$

$=2\int(t^{2}+1)dt=2\left(\frac{t^{3}}{3}+t\right)+C$

$f(x)=\frac{2}{3}(x-1)^{3/2}+2\sqrt{x-1}+C$

So, $A=\frac{2}{3}$, $B=2$

If $f(2)=0 \Rightarrow \frac{2}{3}\cdot1+2\cdot1+C=0 \Rightarrow C=-\frac{8}{3}$

If $f(1)=0 \Rightarrow 0+0+C=0 \Rightarrow C=0$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.930Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4845, 'mathematics-2022-08-22', 'q08', 8, 8, '$ \int_{0}^{5}|x-5|dx= $', '[{"id":"A","text":"$ \\frac{25}{2} $"},{"id":"B","text":"25"},{"id":"C","text":"26"},{"id":"D","text":"$ \\frac{26}{2} $"}]', 0, 'A', '$\int_{0}^{5}\left|x-5\right|dx=-\int_{0}^{5}(x-5)dx$

$=\left(\frac{x^{2}}{2}-5x\right)_{5}^{0}=-\left(\frac{25}{2}-25\right)=\frac{25}{2}$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.931Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4846, 'mathematics-2022-08-22', 'q09', 9, 9, 'The area of the region bounded by the curve $ y=|x-1| $ and line x=0 and x=2 in first quadrant is', '[{"id":"A","text":"2"},{"id":"B","text":"0"},{"id":"C","text":"3"},{"id":"D","text":"1"}]', 0, 'D', 'Graph of the given curves

Required Area = $ \frac{1}{2} \times 1 \times 1 + \frac{1}{2} \times 1 \times 1 = \frac{1}{2} + \frac{1}{2} = 1 $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.931Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4847, 'mathematics-2022-08-22', 'q10', 10, 10, 'Match List-I with List-II.

List-I List-II

Differential equation Degree of

differential equation

$$ \left(\frac{\mathrm{d}^{2}\mathbf{y}}{\mathrm{d}\mathbf{x}^{2}}\right)^{2}+\left(\frac{\mathrm{d}\mathbf{y}}{\mathrm{d}\mathbf{x}}\right)^{2}=\left(\frac{\mathrm{d}\mathbf{y}}{\mathrm{d}\mathbf{x}}\right) $$

B. $ \left(1+\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{3}=\left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)^{3} $

C. $ \left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)+\left(\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{2}=0 $

D. $ \left(\frac{\mathrm{d}^{2}y}{\mathrm{d}x^{2}}\right)^{4}+2=\left(\frac{\mathrm{d}y}{\mathrm{d}x}\right)^{2} $

IV. 3', '[{"id":"A","text":"A-I, B-II, C-IV, D-III"},{"id":"B","text":"A-IV, B-III, C-I, D-II"},{"id":"C","text":"A-II, B-IV, C-I, D-III"},{"id":"D","text":"A-III, B-I, C-II, D-IV (d) A-III, B-I, C-II, D-IV"}]', 0, 'C', '(A) Degree = 2, (B) Degree = 3

(C) Degree = 1, (D) Degree = 4', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.931Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4848, 'mathematics-2022-08-22', 'q11', 11, 11, 'The differential equation representing family of curve $y=ae^{mx}+be^{mx}$ is', '[{"id":"A","text":"$y''''-(m+n)y''+mny=0$"},{"id":"B","text":"$y''''+(m+n)y''+mny=0$"},{"id":"C","text":"$y''''-(m+n)y''-mny=0$"},{"id":"D","text":"$y''-(m+n)y''+y=0$ (d) $ y''''-(m+n)y+y=0 $"}]', 0, 'A', 'Given, $y = ae^{mx} + be^{nx}$

Now, $y'' = ame^{mx} + bne^{nx}$

$y'''' = am^2e^{mx} + bn^2e^{nx}$

Since, $y'''' - my'' - ny''$

$= am^2e^{mx} + bn^2e^{nx} - am^2e^{mx} - bmne^{nx}$

$ = -mn(ae^{mx} + be^{nx})$

$\Rightarrow y'''' - (m + n)y'' + mny = 0$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.932Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4849, 'mathematics-2022-08-22', 'q12', 12, 12, 'Two dices are thrown simultaneously. If X denotes the number of sixes, then the expectation of X is', '[{"id":"A","text":"$ \\frac{1}{4} $"},{"id":"B","text":"$ \\frac{1}{3} $"},{"id":"C","text":"$ \\frac{1}{2} $"},{"id":"D","text":"$ \\frac{1}{8} $"}]', 0, 'B', 'Since, $E = \{(1, 6), (2, 6), (3, 6), (4, 6), (5, 6), (6, 6), (7, 6), (8, 6), (9, 6)\}$

Let $E_{1}=6$ coming at exact ones

$E_{2}=6$ coming on both dices

So, $P(E_{1})=\frac{10}{36}$, $P(E_{2})=\frac{1}{36}$

So, expectations $=1\times\frac{10}{36}+2\times\frac{1}{36}=\frac{1}{3}$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.933Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4850, 'mathematics-2022-08-22', 'q13', 13, 13, 'In a binomial distribution b(n, p), if n = 10 and q = 0.7, then its mean is', '[{"id":"A","text":"7"},{"id":"B","text":"5"},{"id":"C","text":"3"},{"id":"D","text":"1"}]', 0, 'C', 'Given, $n=10$

Since, $p+q=1 \Rightarrow p=1-0.7=0.3$

So. mean $10 \times 0.3 = 3$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.933Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4851, 'mathematics-2022-08-22', 'q15', 14, 14, 'The corner points of the feasible region, determined by the system of linear inequalities are $(0,0)(5,0)(3,4)$ and $(0,5)$. Let $z=2x+qy$ where $q>0$. For what value of $q$ the maximum value of $z$ occurs at both $(3,4)$ and $(0,5)$ is', '[{"id":"A","text":"$2 \\cdot"},{"id":"B","text":"$ 1"},{"id":"C","text":"$\\frac{2}{3}$"},{"id":"D","text":"$6$"}]', 0, 'D', 'Now, $ Z_{(0,0)}=0 $, $ Z_{(5,0)}=2.5=10 $

$ Z_{(3,4)}=6+4q $, $ Z_{(0,5)}=5q $

Since, $ Z_{(3,4)}=Z_{(0,5)} $

$ \Rightarrow 6+4a=5 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.934Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4852, 'mathematics-2022-08-22', 'q16', 15, 15, 'Let R be the relation in the set $\{1, 2, 3, 4\}$ and given by $R = \{(1,2),(2,2),(1,1),(1,3),(4,4),(3,3),(3,2)\}$.', '[{"id":"A","text":"R is reflexive and symmetric, but not transitive"},{"id":"B","text":"R is reflexive and transitive, but not symmetric"},{"id":"C","text":"R is symmetric and transitive, but not reflexive"},{"id":"D","text":"R is an equivalence relation"}]', 0, 'B', 'Given, $ R = \{(1, 2), (2, 2), (1, 1), (1, 3), (4, 4), (3, 3), (3, 2)\} $ and $ A = \{1, 2, 3, 4\} $

$ \forall x \in A, xRx \Rightarrow R $ is Reflexive Relation.

Since, $ 1R2 \nrightarrow 2R1 \Rightarrow R $ is not symmetric.

For any a, b, $ c \in A $, $ aRb $, $ bRc \Rightarrow aRc $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.934Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4853, 'mathematics-2022-08-22', 'q17', 16, 16, 'Which one of the following functions is one-one?

A. f: R → R such that f(x) = x²

B. f: R → R such that f(x) = 3x + 2

C. f: N → N such that f(x) = x²

D. f: R → R such that f(x) = [x], where [x] is greatest integer ≤ x', '[{"id":"A","text":"A and C only"},{"id":"B","text":"B and C only"},{"id":"C","text":"C and D only"},{"id":"D","text":"A, B and C only"}]', 0, 'B', 'Given, (A) $f(x)=x^{2}$, $f:R \to R$

For one-one, $f(x_{1})=f(x_{2})$ (Let)

$\Rightarrow x_{1}^{2}=x_{2}^{2} \Rightarrow x_{1}=\pm x_{2}$

$S_{o}f(x)=x^{2}$ is not one-one.

(B) $f(x)=3x+2$, $f:R \to R$

Let $f(x_{1})=f(x_{2})\Rightarrow 3x_{1}+2=3x_{2}+2$ $\Rightarrow x_{1}=x_{2}$

$\Rightarrow f(x)$ is one-one.

(C) $f:N \to N$, $f(x)=x^{2}$

Let $f(x_{1})=f(x_{2})\Rightarrow x_{1}^{2}=x_{2}^{2}\Rightarrow x_{1}=x_{2}$

$\Rightarrow f(x)$ is one-one.

(D) $f(x)=[x], f:R \to R$

Since $f(0.5)=[0.5]=0$, $f(0)=[0]=0$

$\Rightarrow f(x)$ is not one-one.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.934Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4854, 'mathematics-2022-08-22', 'q18', 17, 17, 'The value of $ \tan^{-1}\left[2\cos\left(2\sin^{-1}\frac{1}{2}\right)\right] $ is', '[{"id":"A","text":"$ \\pi $"},{"id":"B","text":"$ \\frac{\\pi}{2} $"},{"id":"C","text":"$ \\frac{\\pi}{3} $"},{"id":"D","text":"$ \\frac{\\pi}{4} $"}]', 0, 'D', 'Given,

$ \tan^{-1}\left[2\cos\left(2\cos^{-1}\left(\frac{1}{2}\right)\right)\right]=\tan^{-1}\left[2\cos\left(2\times\frac{\pi}{6}\right)\right] $

$ \tan^{-1}\left[2\cos\left(\frac{\pi}{3}\right)\right]=\tan^{-1}\left(2\times\frac{1}{2}\right) $

$ \tan^{-1}(1)=\frac{\pi}{4} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.935Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4855, 'mathematics-2022-08-22', 'q19', 18, 18, 'The value of $ \begin{vmatrix} x & \sin\theta & \cos\theta \\ -\sin\theta & -x & 1 \\ \cos\theta & 1 & x \end{vmatrix} $ is:', '[{"id":"A","text":"independent of \\theta"},{"id":"B","text":"dependent of \\theta"},{"id":"C","text":"equal to x^{3}"},{"id":"D","text":"depend on both \\theta and x"}]', 0, 'A', 'Given, $ \begin{vmatrix} x & \sin\theta & \cos\theta \\ -\sin\theta & -x & 1 \\ \cos\theta & 1 & x \end{vmatrix} $

$ = x (-x^2 - 1) - \sin\theta (-x \sin\theta - \cos\theta) + \cos\theta (x \cos\theta - \sin\theta) $

$ = -x^3 - x + x \sin^2\theta + \sin\theta \cos\theta + x \cos^2\theta - \sin\theta \cos\theta $

$ = -x^9 - x + x \cdot 1 = -x^3 $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.935Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4856, 'mathematics-2022-08-22', 'q20', 19, 19, 'One branch of $\sin^{-1}x$ other than the principal value branch corresponds to:', '[{"id":"A","text":"$\\left[\\pi, 2\\pi\\right]$"},{"id":"B","text":"$\\left[\\frac{\\pi}{2}, \\frac{3\\pi}{2}\\right]$"},{"id":"C","text":"$\\left[-\\frac{\\pi}{2}, \\frac{\\pi}{2}\\right] - \\{0\\}$"},{"id":"D","text":"$\\left[\\frac{3\\pi}{2}, \\frac{5\\pi}{2}\\right]$"}]', 0, 'D', '$ \sin^{-1} x \in \left[-\frac{\pi}{2}, \frac{\pi}{2}\right] $

$ \frac{-\pi}{2} \leq \sin^{-1} x \leq \frac{\pi}{2} $

So, other branch is

$ 2\pi - \frac{\pi}{2} \leq \sin^{-1} x \leq 2\pi + \frac{\pi}{2} $

$ \frac{3\pi}{2} \leq \sin^{-1} x \leq \frac{5\pi}{2} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.935Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4857, 'mathematics-2022-08-22', 'q21', 20, 20, 'If $A=\begin{bmatrix}2 & 3\\ 1 & 2\end{bmatrix}$ where $I$ is the identity matrix of order $2\times2$ and $O$ is $2\times2$ zero matrix, then choose one of the following correct option given below:', '[{"id":"A","text":"$A^{2}-4A+I=0$"},{"id":"B","text":"$A^{2}+4A+I=0$"},{"id":"C","text":"$A^{2}-4A-I=0$"},{"id":"D","text":"$A^{2}-4A+2I=0$"}]', 0, 'A', '$ A = \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} $

And, $ A^{2} = \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} = \begin{bmatrix} 7 & 12 \\ 4 & 7 \end{bmatrix} $

$ 4A = 4 \begin{bmatrix} 2 & 3 \\ 1 & 2 \end{bmatrix} = \begin{bmatrix} 8 & 12 \\ 4 & 8 \end{bmatrix} $

Now, $ A^{2} - 4A + I $

$ = \begin{bmatrix} 7 & 12 \\ 4 & 7 \end{bmatrix} - \begin{bmatrix} 8 & 12 \\ 4 & 8 \end{bmatrix} + \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix} = \begin{bmatrix} 0 & 0 \\ 0 & 0 \end{bmatrix} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.936Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4858, 'mathematics-2022-08-22', 'q22', 21, 21, 'The function $ f(x)=[x] $, where [x] denotes the greatest integer function, is continuous at', '[{"id":"A","text":"2"},{"id":"B","text":"0"},{"id":"C","text":"2"},{"id":"D","text":"2.5"}]', 0, 'D', '$ f(x) = [x] $

Since, the greatest integer function is discontinuous integers.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.936Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4859, 'mathematics-2022-08-22', 'q23', 22, 22, 'The points of discontinuity for the given function f:

$ R \rightarrow R $ defined as

$ f(x)=\left\{\begin{aligned}&2x-5&2<x<3\\ &2,&3\leq x<5\\ &5x,&5\leq x<7\end{aligned}\right. $

(A) 2 (B) 3 (C) 5 (D) 7', '[{"id":"A","text":"A and B only"},{"id":"B","text":"B and C only"},{"id":"C","text":"C and D only"},{"id":"D","text":"A and D only"}]', 0, 'B', '$ f: R \to R $ define as,

$ f(x) = \begin{cases} 2x - 5, & 2 < x < 3 \\ 2, & 3 \leq x < 5 \\ 5x, & 5 \leq x < 7 \end{cases} $

At $ x = 3 $, $ f(3^{-}) = 2 \times 3 - 5 = 1 $

$ f(3^{+}) = 2 $

Function discontinuous at $ x = 3 $

At $ x = 5 $,

$ f(5^{-}) = 2 $

$ f(5^{+}) = 5x = 5 \times 5 = 25 $

Function discontinuous at $ x = 5 $

So, 3, 5 is discontinuous points.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.936Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4860, 'mathematics-2022-08-22', 'q24', 23, 23, 'The function $ f(x) = |x - 1| + |x - 2| $ is not differentiable at (A) 1 (B) 2 (C) $ \frac{3}{2} $ (D) 0

(E) 4', '[{"id":"A","text":"A and B only"},{"id":"B","text":"A and C only"},{"id":"C","text":"C and D only"},{"id":"D","text":"D and E only"}]', 0, 'A', 'If $ f(x) = |x - a| $

then $ f(x) $ is not differentiable at x = a', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.936Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4861, 'mathematics-2022-08-22', 'q25', 24, 24, 'A window is in the form of a rectangle surmounted by an equilateral triangle. If the perimeter of the window is 10m. Find the side of triangle to admit maximum light. Write the steps to solve this problem in correct order.

A. Assume side of triangle as x and other side of rectangle as y

B. Write perimeter: $3x + 2y = 10$ and area (A) = $xy + \frac{\sqrt{3}}{4}x^{2}$

C. Put $\frac{\mathrm{d}A}{\mathrm{d}x}=0$ to get value of $x$

D. Write area (A) in terms of x and find $\frac{\mathrm{d}A}{\mathrm{d}x}$

E Check $\frac{\mathrm{d}^{2}A}{\mathrm{d}x^{2}}<0$ at value of x. Then x is required side of triangle

Choose the correct order from the option given below:

(a) A, B, D, C, E (b) B, A, C, D, E

(c) B, D, A, C, E (d) A, B, C, D, E

$$\int e^{2x}\sin x\,dx =$$', '[{"id":"A","text":"$\\frac{e^{2x}}{4}(2\\sin x - \\cos x) + C$"},{"id":"B","text":"$\\frac{e^{2x}}{5}(2\\cos x - \\sin x) + C$"},{"id":"C","text":"$\\frac{e^{2x}}{4}(2\\sin x + \\cos x) + C$"},{"id":"D","text":"$\\frac{e^{2x}}{5}(2\\sin x - \\cos x) + C$"}]', 0, 'A', '$A = \text{Assume the sides } x, y$

$B = \text{Write perimeter and area}$

$C = \text{Equate area to zero}$

$D = \text{Derivate the area}$

$E = \text{Check} \frac{d^{2}A}{dx^{2}} < 0$ at critical points.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.936Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4862, 'mathematics-2022-08-22', 'q27', 25, 25, 'Match List-I with List-II

List-I List-II

A. $ \int \frac{1}{\sqrt{a^{2}-x^{2}}} dx $

B. $ \int \frac{-1}{(a^{2}+x^{2})} dx $

C. $ \int \frac{1}{x \sqrt{x^{2}-a^{2}}} dx $

D. $ \int \frac{-1}{\sqrt{a^{2}-x^{2}}} dx $

I. $ \cos^{-1}\left(\frac{x}{a}\right)+C $

II. $ \frac{1}{a}\sec^{-1}\left(\frac{x}{a}\right)+C $

III. $ \frac{1}{a}\cot^{-1}\left(\frac{x}{a}\right)+C $

IV. $ \sin^{-1}\left(\frac{x}{a}\right)+C $', '[{"id":"A","text":"A-I, B-II, C-III, D-IV"},{"id":"B","text":"A-I, B-II, C-IV, D-III"},{"id":"C","text":"A-III, B-IV, C-II, D-I"},{"id":"D","text":"A-IV, B-III, C-II, D-I"}]', 0, 'D', 'By using formula of integration $ A \to \mathrm{IV}, B \to \mathrm{III}, C \to \mathrm{II}, D \to \mathrm{I} $ (d) is correct answer.

(c) Let $I = \int\limits_{0}^{\pi/2}\frac{dx}{1+\tan^{n}x}$, put $\tan x = \frac{\sin x}{\cos x}$

$I = \int\limits_{0}^{\pi/2}\frac{\cos^{n}x}{\sin^{n}x + \cos^{n}x}dx \quad \ldots\quad(i)$

By definite integral properly

$I = \int\limits_{0}^{\pi/2}\frac{\cos^{n}\left(\frac{\pi}{2} - x\right)}{\sin^{n}\left(\frac{\pi}{2} - x\right) + \cos^{n}\left(\frac{\pi}{2} - x\right)}$

$\Rightarrow I = \int\limits_{0}^{\pi/2}\frac{\sin^{n}x}{\cos^{n}x + \sin^{n}x}dx \quad \ldots\quad(ii)$

Add equations (i) and (ii),

$2I = \int\limits_{0}^{\pi/2}\frac{\cos^{n}x + \sin^{n}x}{\cos^{n}x + \sin^{n}x}dx = \int\limits_{0}^{\pi/2}1dx$

$$ 2I=\left[\begin{array}{c}x\end{array}\right]_{0}^{\pi/2}=\frac{\pi}{2}\quad\Rightarrow\quad I=\frac{\pi}{4} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.937Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4863, 'mathematics-2022-08-22', 'q29', 26, 26, 'Write the values of the following definite integration in increasing order

A. $ \int_{0}^{\frac{\pi}{2}}\sin^{5}x\,dx $

B. $ \int_{0}^{\frac{\pi}{2}}\log\left(\frac{4+3\sin x}{4+3\cos x}\right)dx $

C. $ \int_{\frac{\pi}{6}}^{\frac{\pi}{3}}\frac{1}{1+\sqrt{\tan x}}\,dx $

D. $ \int_{0}^{1}xe^{x}dx $', '[{"id":"A","text":"B<D<A<C"},{"id":"B","text":"D<B<C<A"},{"id":"C","text":"B<A<C<D"},{"id":"D","text":"B<C<A<D"}]', 0, 'D', '(A) Let

$$ I=\int\limits_{0}^{\pi/2}\sin^{5}x dx=\int\limits_{0}^{\pi/2}(1-\cos^{2}x)^{2}\sin x dx $$

$$ \Rightarrow I=-\int\limits_{1}^{0}\left(1-t^{2}\right)^{2}dt=\frac{1}{5}-\frac{2}{3}+1=\frac{8}{15} $$

$$ \begin{aligned}&(B)Let I=\int\limits_{0}^{\pi/2}\log\left(\frac{4+3\sin x}{4+3\cos x}\right)dx\\&=\int\limits_{0}^{\pi/2}\log\left(\frac{4+3\sin\left(\frac{\pi}{2}-x\right)}{4+3\cos\left(\frac{\pi}{2}-x\right)}\right)dx\\&\Rightarrow I=\int\limits_{0}^{\pi/2}\log\left(\frac{4+3\cos x}{4+3\sin x}\right)dx\\ \end{aligned} $$

$$ \begin{aligned}&2I=\int\limits_{0}^{\pi/2}\log\left(\frac{4+3\sin x}{4+3\cos x}\right)\left(\frac{4+3\cos x}{4+3\sin x}\right)d x\\ &\Rightarrow2I=0\Rightarrow I=0\\ \end{aligned} $$

$$ \begin{aligned}&(C)\text{Let}I=\int\limits_{\pi/6}^{\pi/3}\frac{1}{1+\sqrt{\tan x}}dx\\&\quad=\int\limits_{\pi/6}^{\pi/3}\frac{\sqrt{\cos x}}{\sqrt{\sin x}+\sqrt{\cos x}}dx\\&=\int\limits_{\pi/6}^{\pi/3}\frac{\sqrt{\cos\left(\frac{\pi}{6}+\frac{\pi}{3}-x\right)}}{\sqrt{\sin\left(\frac{\pi}{6}+\frac{\pi}{3}-x\right)}+\sqrt{\cos\left(\frac{\pi}{6}+\frac{\pi}{3}-x\right)}}dx\\&\Rightarrow I=\int\limits_{\pi/6}^{\pi/3}\frac{\sqrt{\sin x}}{\sqrt{\cos x}+\sqrt{\sin x}}dx\\&\quad\Rightarrow2I=\int\limits_{\pi/6}^{\pi/3}\frac{\left(\sqrt{\cos x}+\sqrt{\sin x}\right)}{\sqrt{\cos x}+\sqrt{\sin x}}dx=\frac{\pi}{3}-\frac{\pi}{6}\\&\quad\Rightarrow I=\frac{1}{2}\left[\frac{\pi}{3}-\frac{\pi}{6}\right]=\frac{\pi}{12}\end{aligned} $$

$$ \begin{aligned}&(D)\operatorname{Let}I=\int\limits_{0}^{1}x\,e^{x}\,dx\\ &\Rightarrow I=x e^{x}-\int\limits_{0}^{1}e^{x}\,dx\\ &\Rightarrow I=\begin{bmatrix}x e^{x}-e^{x}\end{bmatrix}=(\mathrm{e}^{1}-e^{1})-(0-1)=1\\ &\operatorname{So},D>A>C>B\\ \end{aligned} $$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.937Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4864, 'mathematics-2022-08-22', 'q30', 27, 27, '$ \int \frac{\sin(x + \alpha)}{\sin x} \, dx = $', '[{"id":"A","text":"$ x \\cos \\alpha + \\sin \\alpha \\log(\\sin x) + C $"},{"id":"B","text":"$ x \\cos \\alpha - \\sin \\alpha \\log(\\sin x) + C $"},{"id":"C","text":"$ x \\sin \\alpha + \\cos \\alpha \\log(\\sin x) + C $"},{"id":"D","text":"$ x \\sin \\alpha - \\cos \\alpha \\log(\\cos x) + C $"}]', 0, 'A', '$ \int \frac{\sin(x + \alpha)}{\sin x} dx = \int \left( \frac{\sin x \cos \alpha + \cos x \sin \alpha}{\sin x} \right) dx $

$ = \int \cos \alpha \, dx + \int \cot x \sin \alpha \, dx $

$ = x \cos \alpha + \sin \alpha \log (\sin x) + C $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.937Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4865, 'mathematics-2022-08-22', 'q33', 28, 28, 'The solution of differential equation $ xy \, dy = (x^2 + y^2) \, dx \, is $', '[{"id":"A","text":"$ y^2 = -x^2 \\log(Cx) $"},{"id":"B","text":"$ y = x^2 \\log x $"},{"id":"C","text":"$ y^2 = x \\log(Cx) $"},{"id":"D","text":"$ y^2 = 2x^2 \\log(Cx) $"}]', 0, 'D', '$ \frac{dy}{dx} = \frac{x^{2} + y^{2}}{xy} $

Let $ y = Vx \Rightarrow \frac{dy}{dx} = V + x \frac{dV}{dx} $

$$V + x\frac{dv}{dx} = \frac{x^{2} + V^{2}x^{2}}{Vx^{2}}$$

$$\Rightarrow V + x\frac{dV}{dx} = \frac{1 + V^{2}}{V} \Rightarrow x\frac{dV}{dx} = \frac{1}{V}$$

$$\Rightarrow VdV = \frac{dx}{x}$$

$$\Rightarrow \frac{V^{2}}{2} = \log x + \log c \Rightarrow \frac{y^{2}}{2x^{2}} = \log c$$

(a) (A) distance of (3, 4, 5) from (0, 4, 0) is

$ d=\sqrt{(3-0)^{2}+0+(5-0)^{2}}=\sqrt{34} $

(B) $ B \to III $

(C) Projection $ =\frac{\vec{a} \cdot \vec{b}}{|\vec{b}|}=\frac{2}{\sqrt{6}} $

(D) $ \cos\theta = \frac{\vec{a} \cdot \vec{b}}{|\vec{a}||\vec{b}|} = \frac{1}{3} \Rightarrow \theta = \cos^{-1}\left(\frac{1}{3}\right) $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.937Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4866, 'mathematics-2022-08-22', 'q35', 29, 29, 'The shortest distance of the point (3,-2,1) from the plane x+2y-2z+9=0 is', '[{"id":"A","text":"$ \\frac{1}{2} $"},{"id":"B","text":"12"},{"id":"C","text":"2"},{"id":"D","text":"2"}]', 0, 'C', 'Given the plane, $ x + 2y - 2z + 9 = 0 $

Now, required distance

$ =\frac{\left|3\cdot1+(-2)\cdot2+1\cdot(-2)+9\right|}{\sqrt{1^{2}+2^{2}+(-2)^{2}}} $

$ =\frac{\left|3-4-2+9\right|}{\sqrt{1+4+4}}=\frac{6}{3}=2 $ unit', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.937Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4867, 'mathematics-2022-08-22', 'q36', 30, 30, 'Arrange the distance between the following planes to the plane $ x + y - z + 2 = 0 $ in ascending order:

A. $ x + y - z + 5 = 0 $

B. $ 2x + 2y - 2z + 5 = 0 $

C. $ 3x + 3y - 3z + 9 = 0 $

D. $ \frac{1}{2}x + \frac{1}{2}y - \frac{1}{2}z + 1 = 0 $', '[{"id":"A","text":"A, B, C, D"},{"id":"B","text":"D, B, C, A"},{"id":"C","text":"B, A, D, C"},{"id":"D","text":"D, B, A, C"}]', 0, 'B', 'Given the plane $ x + y - z + 2 = 0 $

(A) The plane $ x + y - z + 5 = 0 $

So, required distance

$ =\frac{|5-2|}{\sqrt{1^{2}+1^{2}+1^{2}}}=\frac{3}{\sqrt{3}}=\sqrt{3} $ unit

(B) The plane $ x + y - z + \frac{5}{2} = 0 $

So, required distance

$$ = \frac{\left|\frac{5}{2} - 2\right|}{\sqrt{1+1+1}} = \frac{1}{2\sqrt{3}} = \frac{\sqrt{3}}{6} \text{ unit} $$

(C) The plane is $ x + y - z + 3 = 0 $

So, required distance

$$ = \frac{\left|3 - 2\right|}{\sqrt{1+1+1}} = \frac{1}{\sqrt{3}} = \frac{\sqrt{3}}{3} \text{ unit} $$

(D) The plane is $ x + y - z + 2 = 0 $

So, required distance

$$ = \frac{\left|2 - 2\right|}{\sqrt{1+1+1}} = 0 \text{ unit So } D, B, C, $$

37. (bonus), Let $ \frac{x-4}{2}=\frac{y}{3}=\frac{z+2}{4}=t $

$ \Rightarrow x=2t+4, y=3t, z=4t-2 $

Now, $ 2(2t+4)-2(3t)+4t-2=0 $

$\Rightarrow 4t+8-6t+4t-2=0$

$\Rightarrow 2t+6=0 \Rightarrow t=-3$

So, the point is $(-2,-9,-14)$.

Now, required distance

$=\sqrt{(-2)^{2}+(-9)^{2}+(-14)^{2}}$

$=\sqrt{4+81+196}=\sqrt{281}$ unit', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4868, 'mathematics-2022-08-22', 'q38', 31, 31, 'If A and B are independent events such that P(A) = $ \frac{1}{4} $ and P(B) = $ \frac{1}{2} $, then P(A'' / B'') is', '[{"id":"A","text":"$ \\frac{1}{4} $"},{"id":"B","text":"$ \\frac{3}{4} $"},{"id":"C","text":"$ \\frac{1}{2} $"},{"id":"D","text":"$ \\frac{1}{8} $"}]', 0, 'B', 'Given, $ P(A)=\frac{1}{4} $, $ P(B)=\frac{1}{2} $

Now,

$ P\left(\frac{A^{\prime}}{B^{\prime}}\right)=\frac{P(A^{\prime}\cap B^{\prime})}{P(B^{\prime})}=\frac{1-P(A\cup B)}{1-P(B)} $

$ = \frac{1 - (P(A) + P(B) - P(A \cap B))}{1 - \frac{1}{2}} $

$ = 2\left(1 - \frac{1}{4} - \frac{1}{2} + \frac{1}{4} \times \frac{1}{2}\right) = \frac{3}{4} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4869, 'mathematics-2022-08-22', 'q39', 32, 32, 'A random variable has the following probability distribution:

$ P(X=x) \quad k \quad \frac{1}{4} \quad 6k \quad 4k \quad k $

Which of the following statements are correct?

A. $ k = \frac{1}{10} $

B. $ P(X=3) = \frac{1}{4} $

C. $ P(X<2) = \frac{11}{16} $

D. $ P(1<X<4) = \frac{5}{8} $

E. $ P(X=4) = \frac{1}{8} $', '[{"id":"A","text":"A, B, E only"},{"id":"B","text":"B, C, D only"},{"id":"C","text":"B, D only"},{"id":"D","text":"D, E only"}]', 0, 'C', '(A) We know, P(x=0≤x≤4)=1

$ \Rightarrow k+\frac{1}{4}+6k+4k+k=1 \Rightarrow 12k=\frac{3}{4} $

$ \Rightarrow k=\frac{1}{16} $

(B) P(x=3)=4 $ \times\frac{1}{16}=\frac{1}{4} $

(C) P(x<2)=k+\frac{1}{4}=\frac{1}{16}+\frac{1}{4}=\frac{5}{16} $

(D) P(1<x<4)=6k+4k=10k= $ \frac{10}{16}=\frac{5}{8} $

(E) P(x=4)=k= $ \frac{1}{16} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4870, 'mathematics-2022-08-22', 'q40', 33, 33, 'In a linear programming problem, Maximize $ z = 3x + 9y $, the corner points are $ (0, 10) $, $ (5, 5) $, $ (15, 15) $ and $ (0, 20) $, z is maximum at

A. $ (0,10) $

B. $ (5,5) $

C. $ (15,15) $

D. $ (0,20) $', '[{"id":"A","text":"A and B only"},{"id":"B","text":"A and C only"},{"id":"C","text":"B and C only"},{"id":"D","text":"C and D only Passage Rahul went to a park with his younger brother and observed that park is circular and a pavement running around it. He asked the gardener about the radius of the park and found it to be 15m. And the pavement is 2m broad. Answer the following questions based on the above information."}]', 0, 'D', 'Given, $ z = 3x + 9y $

Now, $ Z_{(0,10)} = 0 + 9 \times 10 = 90 $

$ Z_{(5,5)} = 3.5 + 9.5 = 60 $

$ Z_{(15,15)} = 3.15 + 9.15 = 180 $

$ Z_{(0,20)} = 0 + 9.20 = 180 $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4871, 'mathematics-2022-08-22', 'q41', 34, 34, 'The area of the circular park, using integration, is given by

(a) $ \int_{0}^{15}\sqrt{225-x^{2}}dx $

(b) $ \int_{0}^{15}\sqrt{15-x^{2}}dx $

(c) $ \int_{0}^{15}\sqrt{225-x^{2}}dx $

(d) $ \int_{0}^{15}\sqrt{15-x^{2}}dx $

The integral $\sqrt{225-x^{2}}$ can be solved using $t$', '[{"id":"A","text":"$\\frac{x}{2}\\sqrt{x^{2}-a^{2}}-\\frac{a^{2}}{2}\\log\\left|x+\\sqrt{x^{2}-a^{2}}\\right|+C$"},{"id":"B","text":"$\\frac{x}{2}\\sqrt{x^{2}+a^{2}}+\\frac{a^{2}}{2}\\log\\left|x+\\sqrt{x^{2}+a^{2}}\\right|+C$"},{"id":"C","text":"$\\frac{x}{2}\\sqrt{a^{2}-x^{2}}+\\frac{a^{2}}{2}\\sin^{-1}\\frac{x}{a}+C$"},{"id":"D","text":"$\\frac{x}{2}\\sqrt{a^{2}-x^{2}}-\\frac{a^{2}}{2}\\sin^{-1}\\frac{x}{a}+C$"}]', 0, 'C', 'Equation of circle, $ x^{2} + y^{2} = (15)^{2} $

$ x = 15\sin\theta $, $ dx = 15\cos\theta\,d\theta $

$ A = 4\int\limits_{0}^{r}\sqrt{r^{2}-x^{2}}\,dx $ where $ r=15 $

$ A = 4\int\limits_{0}^{15}\sqrt{225-x^{2}}\,dx $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4872, 'mathematics-2022-08-22', 'q43', 35, 35, 'The area of the pavement running around the circular park, using integration, is given by', '[{"id":"A","text":"$4\\int_{0}^{17}\\sqrt{17-x^{2}}dx$"},{"id":"B","text":"$4\\int_{0}^{17}\\sqrt{289-x^{2}}dx$"},{"id":"C","text":"$$ \\left(4\\int\\limits_{0}^{17}\\sqrt{17-x^{2}}\\ d x\\right)-\\left(4\\int\\limits_{0}^{15}\\sqrt{15-x^{2}}\\ d x\\right) $$"},{"id":"D","text":"$ \\left(4\\int\\limits_{0}^{17}\\sqrt{289-x^{2}} \\mathrm{d}x\\right)-\\left(4\\int\\limits_{0}^{15}\\sqrt{225-x^{2}} \\mathrm{d}x\\right) $"}]', 0, 'D', 'Area of pavement = Total area - area of park

$ A = 4 \int_{0}^{17} \sqrt{289 - x^{2}} dx - 4 \int_{0}^{15} \sqrt{225 - x^{2}} dx $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.938Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4873, 'mathematics-2022-08-22', 'q44', 36, 36, 'The area of the circular pavement is', '[{"id":"A","text":"$ 289\\pi $ sq units"},{"id":"B","text":"$ 225\\pi $ sq units"},{"id":"C","text":"$ 514\\pi $ sq units"},{"id":"D","text":"$ 64\\pi $ sq units"}]', 0, 'D', '$ A = 4 \int_{0}^{17} \sqrt{289 - x^{2}} dx - 4 \int_{0}^{15} \sqrt{225 - x^{2}} dx $

