INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4876, 'mathematics-2022-08-22', 'q47', 39, 39, 'The vector $\overrightarrow{\mathrm{CD}}$ is', '[{"id":"A","text":"$2\\hat{i}+2\\hat{j}+3\\hat{k}$"},{"id":"B","text":"$\\hat{i}+2\\hat{j}+\\hat{k}$"},{"id":"C","text":"$\\hat{i}-\\hat{j}+\\hat{k}$"},{"id":"D","text":"$\\hat{i}-2\\hat{j}-\\hat{k}$"}]', 0, 'B', '$ \overrightarrow{C} = (3, 1, 0) $, $ \overrightarrow{D} = (4, 3, 1) $

