INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4877, 'mathematics-2022-08-22', 'q48', 40, 40, 'The area of $\triangle ABC$ is equal to', '[{"id":"A","text":"$\\frac{\\sqrt{13}}{2}$"},{"id":"B","text":"$\\frac{\\sqrt{5}}{2}$"},{"id":"C","text":"$\\frac{\\sqrt{7}}{2}$"},{"id":"D","text":"$\\frac{\\sqrt{11}}{2}$"}]', 0, 'D', '$ \overrightarrow{AB} = \overrightarrow{i} + \overrightarrow{j} $, $ \overrightarrow{BC} = \overrightarrow{i} - 2\overrightarrow{j} - \overrightarrow{k} $

Area = $ \frac{1}{2}\left|\overrightarrow{AB} \times \overrightarrow{BC}\right| $

$ = \frac{1}{2}\left|\begin{matrix} \overrightarrow{i} & \overrightarrow{j} & \overrightarrow{k} \\ 1 & 1 & 0 \\ 1 & -2 & -1 \end{matrix}\right| = \frac{\left|(-\overrightarrow{j} + \overrightarrow{i} - 3\overrightarrow{k})\right|}{2} = \frac{\sqrt{11}}{2} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.940Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
