INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4880, 'mathematics-2022-08-30', 'q01', 1, 1, 'Assume $P$, $Q$, $R$ and $S$ are matrices of order $2 \times m$, $k \times n$, $m \times 2$ and $2 \times 3$ respectively. The restrictions on $k$, $m$ and $n$, so that $PQ + RS$ is defined are', '[{"id":"A","text":"$m=3, n=2$"},{"id":"B","text":"$m=n, k$ is arbitrary"},{"id":"C","text":"$m=k$ $n$ is arbitrary"},{"id":"D","text":"$m=k=2, n=3$"}]', 0, 'D', 'Order of $P=2\times m$

Order of $Q=k\times n$

Order of $R=m\times2$

Order of $S=2\times3$

Now, for $PQ+RS$ to be defined.

$PQ$ and $RS$ is to be defined and $PQ$ and $RS$ should be of same order.

For $PQ$ to be defined $m=k$

$\Rightarrow$ Order of $PQ=2\times n$

For $RS$ to be defined $2=2$

$\Rightarrow$ Order of $RS=m\times3$

If order of $PQ$=Order of $RS$

$\Rightarrow$ $2\times n=m\times3$

$\Rightarrow$ $m=2,n=3,k=2$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.940Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4881, 'mathematics-2022-08-30', 'q02', 2, 2, 'The system of equations 3x + 4y = 5, 6x + 7y = -8 is written in matrix from as', '[{"id":"A","text":"$ \\begin{bmatrix} 3 & 4 \\\\ 6 & 7 \\end{bmatrix}[x \\quad y] = [5 - 8] $"},{"id":"B","text":"$ \\begin{bmatrix}3&6\\\\ 4&7\\end{bmatrix}\\begin{bmatrix}x\\\\ y\\end{bmatrix}=\\begin{bmatrix}5\\\\ -8\\end{bmatrix} $"},{"id":"C","text":"$ \\begin{bmatrix} x \\\\ y \\end{bmatrix} \\begin{bmatrix} 3 & 4 \\\\ 6 & 7 \\end{bmatrix} = \\begin{bmatrix} 5 \\\\ -8 \\end{bmatrix} $"},{"id":"D","text":"$ [x\\ y]\\begin{bmatrix}3\\ 6\\\\ 4\\ 7\\end{bmatrix}=[5\\ -8] $"}]', 0, 'D', 'Given the equations

