INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4882, 'mathematics-2022-08-30', 'q03', 3, 3, 'If $ 2\begin{bmatrix}a&d\\ b&c\end{bmatrix}+3\begin{bmatrix}1&-1\\ 0&2\end{bmatrix}=3\begin{bmatrix}3&5\\ 4&6\end{bmatrix} $, then the value of $ \left|a+b-c-d\right| $ is', '[{"id":"A","text":"3"},{"id":"B","text":"24"},{"id":"C","text":"6"},{"id":"D","text":"16"}]', 0, 'A', 'Sample space

S: {1, 2, 3}

Two numbers can be selected as (1, 2)(2, 3)(1, 3)

Now,

where $X$ denotes larger of two integers.', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4883, 'mathematics-2022-08-30', 'q04', 4, 4, 'Consider the function $f(x)=x^{\frac{1}{x}}$. Its', '[{"id":"A","text":"minimum value is $e^{\\frac{1}{e}}$"},{"id":"B","text":"maximum value is $e^{\\frac{1}{e}}$"},{"id":"C","text":"minimum value is $e^{e}$"},{"id":"D","text":"maximum value is $\\left(\\frac{1}{e}\\right)^{e}$"}]', 0, 'B', 'Given the function

$$

\begin{aligned}

f(x) &= x^{\frac{1}{x}} \Rightarrow \log f(x) = \frac{1}{x} \log x \\

\frac{f''(x)}{f(x)} &= \frac{1}{x^2} + (\log x) \left( -\frac{1}{x^2} \right) \\

f''(x) &= \frac{\frac{1}{x^x} [1 - \log x]}{x^2}, \text{ Now } f''(x) = 0 \\

\Rightarrow 1 - \log x &= 0 \Rightarrow \log x = 1 \\

\therefore x &= e \\

\text{Since } f''(e^-) > 0 \text{ and } f''(e^+) < 0 \\

\text{So, } f(x) \text{ has max. at } e. \\

\therefore f(x)_{\max} &= e^e

\end{aligned}

$$

$\therefore f(x)_{\max}=e^{e}$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4884, 'mathematics-2022-08-30', 'q05', 5, 5, 'The given function $f(x)=x^{5}-5x^{4}+5x^{3}-1$; has/have

(a) Local maxima at $x=1$

(b) Local maximum value is 0

(c) Local minimum at $x=3$

(d) Local minimum value is $-28$

(e) The point of inflexion is $x=1$

Choose the correct answer from the options given below

(a) (a), (b) only

(b) (a), (b), (c) only

(c)', '[{"id":"A","text":","},{"id":"B","text":","},{"id":"C","text":","},{"id":"D","text":"only (d) (a), (c), (e) only"}]', 0, 'C', 'Given, $f(x)=x^{5}-5x^{4}+5x^{3}-1$

$f''(x)=5x^{4}-20x^{3}+15x^{2}$

$=5x^{2}(x^{2}-4x+3)=0$

$=5x^{2}(x-3)(x-1)=0$

$x=0,3,1$

Now, $f''''(x)=20x^{3}-60x^{2}+30x$

$=10x(2x^{2}-6x+3)$

$f''''(x)=0 \Rightarrow x=0$

$f''''(1) 0 \Rightarrow x=3$

$f(3)=(3)^{5}-5(3)^{4}+5(3)^{3}-1=-28$

$f(1)=1-5+5-1=0$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4885, 'mathematics-2022-08-30', 'q06', 6, 6, 'Match List-I with List-II

(A) If $x = t^{2}$ and $y = t^{3}$

(B) then $\frac{d^{2}y}{dx^{2}}$ at $t=1$

(C) (D) (E) (F) (G) (H) (I)

List-I

List-II

(i) -2

(B) If $ f(x) = \sqrt{x} + 1 $, (ii) -1 the $ f''''(1) $

(C) The minimum value (iii) $ \frac{3}{4} $

$ \text{off}(x)=9x^{2}+12x+2 $ is

(D) The point of inflexion (iv) $ -\frac{1}{4} $ of the function $ f(x)=(x-2)^{4} $ $ (x+1)^{3} $ is

Choose the correct answer from the options given below

(a) (A)-(i), (B)-(iii), (C)-(ii), (D)-(iv)

(b) (A)-(ii), (B)-(iii), (C)-(i), (D)-(iv)

(c) (A)-(iii), (B)-(iv), (C)-(i), (D)-(ii)

(d) (A)-(iv), (B)-(i), (C)-(iii), (D)-(ii)

The area enclosed by the curve $ y^{2}=4ax $ and its latus rectum is', '[{"id":"A","text":"$ \\frac{8}{3}a^{2} $"},{"id":"B","text":"$ \\frac{4}{3}a^{2} $"},{"id":"C","text":"$ \\frac{1}{3}a^{2} $"},{"id":"D","text":"$ \\frac{1}{12}a^{2} $"}]', 0, 'D', '$f(a)=1$ and $f(a)=3$, which is not possible for any function', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4886, 'mathematics-2022-08-30', 'q08', 7, 7, '$ \int \frac{xe^{x}}{(x+1)^{2}} dx = $', '[{"id":"A","text":"$ \\frac{e^{x}}{x+1} + c $"},{"id":"B","text":"$ \\frac{e^{x}}{x-1} + c $"},{"id":"C","text":"$ \\frac{x}{x+1} + c $"},{"id":"D","text":"$ \\frac{x}{x-1} + c $"}]', 0, 'A', '$ \int \frac{xe^x}{(x+1)^2} dx = \int e^x \left[ \frac{x+1-1}{(x+1)^2} \right] dx $

$ \therefore \int e^x [f(x) + f''(x)] dx = e^x f(x) + C $

$ = \int e^x \left[ \frac{1}{x+1} - \frac{1}{(x+1)^2} \right] dx = \frac{e^x}{1+x} + C $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4887, 'mathematics-2022-08-30', 'q09', 8, 8, 'The solution of the differential equation

$ (x+1)\frac{dy}{dx}=1+y\text{ is} $', '[{"id":"A","text":"$ \\frac{1+y+y^{2}}{1+x^{2}}=C $"},{"id":"B","text":"$ \\log(x+1)-\\log\\left(y+\\frac{1}{2}\\right)=C $"},{"id":"C","text":"$ \\frac{x+1}{y+1}=C $"},{"id":"D","text":"$ \\log(1+y)-\\frac{\\sqrt{3}}{2}\\log(x+1)=C $"}]', 0, 'C', 'Given differential equation,

$$(x+1)\frac{dy}{dx}=1+y\Rightarrow\frac{dx}{1+x}=\frac{dy}{1+y}$$

$$\Rightarrow\ln(1+x)=\ln(1+y)+\ln C\Rightarrow\ln\left(\frac{1+x}{1+y}\right)=\ln C$$

$$\Rightarrow\frac{1+x}{1+y}=C$$', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4888, 'mathematics-2022-08-30', 'q11', 9, 9, 'Derivative of $ x^{3} + 1 $ with respect to $ x^{2} + 1 $ is', '[{"id":"A","text":"$ \\frac{2x}{3} $"},{"id":"B","text":"$ \\frac{x}{3} $"},{"id":"C","text":"$ \\frac{x}{2} $"},{"id":"D","text":"$ \\frac{3x}{2} $"}]', 0, 'D', 'Let $ f(x)=x^{3}+1 $

$ g(x)=x^{2}+1 $

$ \frac{f''(x)}{g''(x)}=\frac{3x^{2}}{2x}=\frac{3}{2}x $', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4889, 'mathematics-2022-08-30', 'q12', 10, 10, 'Solution of the differential equation $ (x + xy)dy - y(1-x^2)dx = 0 $ is', '[{"id":"A","text":"$ y = \\log \\frac{x}{y} - \\frac{x^2}{2} + C $"},{"id":"B","text":"$ y = \\log \\frac{x}{y} + \\frac{x^2}{2} + C $"},{"id":"C","text":"$ y = \\log xy - \\frac{x^2}{2} + C $"},{"id":"D","text":"$ \\frac{x^2}{2} + \\frac{x^2}{2} + C $"}]', 0, 'A', 'The given differential equation

$ (x + xy)dy - y(1 - x^2)dx = 0 $

$ x(1 + y)dy - y(1 - x^2)dx = 0 $

$ \int \frac{(1 + y)}{y} dy = \int \frac{(1 - x^2)}{x} dx $

$ \log y + y = \log x - \frac{x^2}{2} + C $

$ y = \log \frac{x}{y} - \frac{x^2}{2} + C $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4890, 'mathematics-2022-08-30', 'q15', 11, 11, 'In linear programming, the optimal function is attained at the points given by', '[{"id":"A","text":"intersection of the inequalities with the x-axis only"},{"id":"B","text":"intersection of the inequalities with the axes only"},{"id":"C","text":"corner points of the feasible region"},{"id":"D","text":"intersection of the inequalities with the y-axis only"}]', 0, 'C', 'The optimal values of the objective function is attained at the corner points of the feasible region.

(d) Since, $xRy, |x-y| \leq 1$

For reflexive $(a,a) \Rightarrow |a-a| = 0 \leq 1$.

$\therefore$ Relation is reflexive,

For symmetric $(a,b) \Rightarrow |a-b| \leq 1$.

$(b,a) \Rightarrow |b-a| \leq 1$.

$\therefore$ Relation is symmetric.

For transitive $(a,b) \Rightarrow |a-b| \leq 1$

$$ (b,c)\Rightarrow|b-c|\leq1 $$

$$ \nearrow\mid a-c\mid\le1 $$

∴ Only reflexive and symmetric and not transitive.

17. $ （d） $

A(1,2,1)

D is mid-point of line segment BC.

$$ D\equiv\left(\frac{4+2}{2},\frac{2+3}{2},\frac{3+1}{2}\right)\equiv\left(3,\frac{5}{2},2\right) $$

Equation of median through A.

$$ \left(\frac{x-1}{3-1}=\frac{y-2}{\frac{5}{2}-2}=\frac{2-1}{2-1}\right)\Rightarrow\frac{x-1}{2}=\frac{y-2}{\frac{1}{2}}=\frac{z-1}{1} $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.941Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4891, 'mathematics-2022-08-30', 'q18', 12, 12, 'A line makes the angle \theta with each of the x and z axes. If the angle \beta which it makes with y-axis is such that \sin^{2}\beta = 3\sin^{2}\theta, then the value of \cos^{2}\theta is', '[{"id":"A","text":"$ \\frac{2}{5} $"},{"id":"B","text":"$ \\frac{1}{5} $"},{"id":"C","text":"$ \\frac{3}{5} $"},{"id":"D","text":"$ \\frac{2}{5} $"}]', 0, 'C', 'We know that

$ \cos^{2}\theta + \cos^{2}\beta + \cos^{2}\theta = 1 $

or $ 2\cos^{2}\theta + 1 - 3\sin^{2}\theta = 1 $

or $ 2\cos^{2}\theta = 3\sin^{2}\theta $

or $ 2\cos^{2}\theta=3-3\cos^{2}\theta\Rightarrow\cos\theta=\frac{3}{5} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4892, 'mathematics-2022-08-30', 'q19', 13, 13, 'If $ x = 2 \sin \theta $ and $ y = 2 \cos \theta $, then the value of $ \frac{d^2 y}{dx^2} $ at $ \theta = 0 $ is', '[{"id":"A","text":"$ -\\frac{1}{2} $"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"1"}]', 0, 'A', 'Now, $ \frac{dy}{dx} = \frac{dy}{\frac{d\theta}{dx}} \Rightarrow \frac{dy}{dx} = \frac{-2\sin\theta}{2\cos\theta} = -\tan\theta $

$ \frac{d^2y}{dx^2} = \frac{d}{d\theta}\left(\frac{dy}{dx}\right) \cdot \frac{d\theta}{dx} \Rightarrow \frac{d^2y}{dx^2} = -\sec^2\theta \cdot \frac{d\theta}{dx} $

$ =\frac{-\sec^2\theta}{2\cos\theta} = -\frac{1}{2}\sec^3\theta $

$$ At\theta=0\Rightarrow\frac{d^{2}y}{dx^{2}}=-\frac{1}{2} $$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4893, 'mathematics-2022-08-30', 'q20', 14, 14, 'If $ x = e^{y + e^{y + \cdots}} $, x > 0, then $ \frac{dy}{dx} $ is equal to', '[{"id":"A","text":"$ \\frac{x}{1+x} $"},{"id":"B","text":"$ \\frac{1}{x} $"},{"id":"C","text":"$ \\frac{1-x}{x} $"},{"id":"D","text":"$ \\frac{1+x}{x} $"}]', 0, 'C', 'Since, $ x = e^{y+x} $

Differentiating w.r.t. x, we get

$ 1 = e^{x+y} \left( 1 + \frac{dy}{dx} \right) \Rightarrow \frac{1}{x} = 1 + \frac{dy}{dx} $

or $ \frac{dy}{dx} = \frac{1 - x}{x} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4894, 'mathematics-2022-08-30', 'q21', 15, 15, '$ \sin^{-1}(1-x)-2\sin^{-1}x=\frac{\pi}{2} $, then x is equal to', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"$ \\frac{1}{2} $"},{"id":"D","text":"2 Choose the most appropriate answer from the options given below: (a) (a) and (b) only (b) (a) and (c) only (c) (a) only (d) (c) only"}]', 0, 'C', 'Domain for $ \sin^{-1}(1-x) $ is [0,2] and domain for $ \sin^{-1}x $ is [-1,1].

So, Domain for x is [0,1].

$$ \left.\sin^{-1}(1-x)\right|_{\max}=\frac{\pi}{2};\left.\sin^{-1}(x)\right|_{\max}=0 $$

So, only possible condition is when x=0.', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4895, 'mathematics-2022-08-30', 'q22', 16, 16, 'The smaller of the areas enclosed by the circle $ x^{2}+y^{2}=4 $ and the line $ x+y=2 $ is', '[{"id":"A","text":"$ 2(\\pi-2) $"},{"id":"B","text":"$ \\pi-2 $"},{"id":"C","text":"$ 2\\pi-1 $"},{"id":"D","text":"$ 2\\pi+2 $"}]', 0, 'B', 'Graph of given curves

Area of smaller region

= $ \frac{1}{4}\times4\pi-\frac{1}{2}\cdot2.2=(\pi-2) $ sq. units', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4896, 'mathematics-2022-08-30', 'q23', 17, 17, 'If $ 0 < x < \pi $ and the matrix $ \begin{bmatrix} 4\sin x & -1 \\ -3 & \sin x \end{bmatrix} $ is

singular, then the values of x are:', '[{"id":"A","text":"$ \\frac{\\pi}{3}, \\frac{2\\pi}{3} $"},{"id":"B","text":"$ \\frac{\\pi}{6}, \\frac{5\\pi}{6} $"},{"id":"C","text":"$ \\frac{\\pi}{6}, \\frac{\\pi}{3} $"},{"id":"D","text":"$ \\frac{\\pi}{6}, \\frac{2\\pi}{3} $"}]', 0, 'A', 'Since, $ \begin{vmatrix} 4\sin x & -1 \\ -3 & \sin x \end{vmatrix} = 0 $

$ \Rightarrow 4\sin^{2}x - 3 = 0 \Rightarrow \sin^{2}x = \frac{3}{4} $

$ \Rightarrow \sin x = \pm \frac{\sqrt{3}}{2} \Rightarrow x = \frac{\pi}{3} $ or $ \frac{2\pi}{3} $', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4897, 'mathematics-2022-08-30', 'q24', 18, 18, '$ \int_{\frac{1}{3}}^{1}\frac{(x-x^{3})^{\frac{1}{3}}}{x^{4}}dx= $', '[{"id":"A","text":"3"},{"id":"B","text":"4"},{"id":"C","text":"6"},{"id":"D","text":"0"}]', 0, 'C', 'Let

$$I = \int_{1/3}^{1} \frac{x\left(\frac{1}{x^2}-1\right)^{1/3}}{x^4} dx = \int_{1/3}^{1} \frac{\left(\frac{1}{x^2}-1\right)^{1/3}}{x^3} dx$$

Let $\frac{1}{x^2} - 1 = t \Rightarrow \frac{-2}{x^3} dx = dt$

If $x = \frac{1}{3} \Rightarrow t = 8$

If $x = 1 \Rightarrow t = 0$

So, $I = \int_{8}^{0} \frac{-t^{1/3}}{2} dt = \frac{1}{2} \int_{0}^{8} t^{1/3} dt = \frac{1}{2} \cdot \frac{t^{4/3}}{4} \bigg|_{0}^{8}$

$\frac{3}{8} \left( \frac{4}{8^3} - 0^{\frac{4}{3}} \right) = \frac{3}{8} \cdot 8^{4/3} = 6$', NULL, 'null', '[]', '[]', '[2]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4898, 'mathematics-2022-08-30', 'q27', 19, 19, 'If the points $(2, -3)$, $(\lambda, -1)$ and $(0, 4)$ are collinear, then the value of $\lambda$ is', '[{"id":"A","text":"$\\frac{7}{10}$"},{"id":"B","text":"$\\frac{3}{10}$"},{"id":"C","text":"$\\frac{7}{3}$"},{"id":"D","text":"$\\frac{10}{7}$"}]', 0, 'D', 'For collinear points,

$ \begin{vmatrix} \lambda & -1 & 1 \\ 0 & 4 & 1 \\ 2 & -3 & 1 \end{vmatrix} = 0 \Rightarrow \lambda(7) + 1(-2) + 1(-8) = 0 $

$ \Rightarrow 7\lambda - 10 = 0 \Rightarrow \lambda = \frac{10}{7} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4899, 'mathematics-2022-08-30', 'q28', 20, 20, 'The value of $\sin\left[2\cot^{-1}\left(\frac{-5}{12}\right)\right]$ is:', '[{"id":"A","text":"$\\frac{120}{169}$"},{"id":"B","text":"$\\frac{-120}{169}$"},{"id":"C","text":"$\\frac{-60}{169}$"},{"id":"D","text":"$\\frac{60}{169}$"}]', 0, 'B', '$ \sin\left(2\pi-2\cot^{-1}\frac{5}{12}\right)=-\sin\left(2\cot^{-1}\frac{5}{15}\right) $

Since, $ \sin(2\pi-x)=-\sin x $

Let $ \cot^{-1}\frac{15}{12}=\theta \Rightarrow \cot\theta=\frac{5}{12} $

$ \Rightarrow \tan\theta=\frac{12}{5} $

$ \sin2\theta=\frac{2\tan\theta}{1+\tan^{3}\theta}=\frac{\frac{24}{5}}{1+\frac{144}{25}}=\frac{\frac{25}{5}}{\frac{169}{25}}=\frac{120}{169} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4900, 'mathematics-2022-08-30', 'q29', 21, 21, 'Let $y = m \sin rx + n \cos rx$. What is the value of $\frac{d^2 y}{dy^2}$?', '[{"id":"A","text":"$ry$"},{"id":"B","text":"$-ry$"},{"id":"C","text":"$ry^2 y$"},{"id":"D","text":"$-r^2 y$"}]', 0, 'D', 'Given, $ y = m \sin rx + r \cos rx $

$ \frac{dy}{dx} = m \cdot r (\cos rx) - nr (\sin rx) $

$ \Rightarrow \frac{d^2 y}{dx^2} = mr^2 [(-\sin rx) - nr^2 (\cos rx)] $

$ =-\frac{r^2 v $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4901, 'mathematics-2022-08-30', 'q30', 22, 22, 'The integrating factor of the differential equation \cos x\frac{dy}{dx}+y\sin x=1 is', '[{"id":"A","text":"$ \\sec x $"},{"id":"B","text":"$ \\cos x $"},{"id":"C","text":"$ \\sec x + \\tan x $"},{"id":"D","text":"$ \\tan x $"}]', 0, 'A', 'Given, the differential equation

$ \cos x \frac{dy}{dx} + y \sin x = 1 $

$ \frac{dy}{dx} + y \tan x = \sec x $

So, I.F. = $ e^{\int \tan x \, dx} = e^{\ln (\sec x)} = \sec x $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.942Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4902, 'mathematics-2022-08-30', 'q31', 23, 23, 'The order and degree of the differential equation $ \left[\left(\frac{d^{2}y}{dx^{2}}\right)-3\right]^{\frac{1}{3}}=2\left(\frac{dy}{dx}\right)^{\frac{1}{4}} $ are

(a) order=2, degree=2 (b) order=2, degree=4

(c) order=2, degree=8 (d) order=1, degree=1

$$ \int\sqrt{1-49x^{2}} $$', '[{"id":"A","text":"$ \\frac{x}{2}\\left(\\sqrt{1-49x^{2}}\\right)+\\frac{1}{98}\\sin^{-1}7x+C $"},{"id":"B","text":"$ \\frac{7x}{2}\\sqrt{1+49x^{2}}+\\frac{1}{49}\\sin^{-1}x+C $"},{"id":"C","text":"$ \\frac{x}{2}\\sqrt{1+\\frac{1}{7x^{2}}}-\\frac{1}{49}\\sin^{-1}7x+C $"},{"id":"D","text":"$ \\frac{x}{2}\\sqrt{1-49x^{2}}+\\frac{1}{14}\\sin^{-1}7x+C $"}]', 0, 'C', 'Since, $ \left[\left(\frac{d^{2}y}{dx^{2}}\right)^{2}-3\right]^{\frac{1}{3}}=2\left(\frac{dy}{dx}\right)^{\frac{1}{4}} $

$ \left(\left(\frac{d^{2}y}{dx^{2}}\right)^{2}-3\right)^{4}=2^{12}\left(\frac{dy}{dx}\right)^{3} $

So, Order=2, Degree=8', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4903, 'mathematics-2022-08-30', 'q33', 24, 24, 'The shortest distances of the point $(1,2,3)$ from $x$, $y$, $z$ axes respectively are', '[{"id":"A","text":"$1,2,3$"},{"id":"B","text":"$\\sqrt{5},\\sqrt{13},\\sqrt{10}$"},{"id":"C","text":"$\\sqrt{10},\\sqrt{13},\\sqrt{5}$"},{"id":"D","text":"$\\sqrt{13},\\sqrt{10},\\sqrt{5}$"}]', 0, 'D', 'Since, $ D_x = \sqrt{(1-1)^2 + (2-0)^2 + (3-0)^2} $

$ \Rightarrow D_x = \sqrt{2^2 + 3^2} = \sqrt{13} $

$ D_y = \sqrt{1^2 + 3^2} = \sqrt{10} $

$ D_z = \sqrt{1^2 + 2^2} = \sqrt{5} $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4904, 'mathematics-2022-08-30', 'q34', 25, 25, 'Distance between two planes $x+2y-z=5$ and $2x+4y-2z+2=0$ is', '[{"id":"A","text":"$\\sqrt{6}$ unit"},{"id":"B","text":"7 unit"},{"id":"C","text":"$\\frac{5}{\\sqrt{6}}$ unit"},{"id":"D","text":"$\\frac{4}{\\sqrt{6}}$ unit"}]', 0, 'A', 'Given the planes

$ P_{1}:2x+4y-2z=10 $

$ P_{2}:2x+4y-2z=-2 $

$ d=\frac{12}{\sqrt{2^{2}+4^{2}+2^{2}}}=\frac{12}{\sqrt{24}}=\sqrt{6} $ units', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4905, 'mathematics-2022-08-30', 'q35', 26, 26, 'If $\overrightarrow{a}=a_{1}\hat{i}+a_{2}\hat{j}+a_{3}\hat{k}$ and $\overrightarrow{b}=b_{1}\hat{i}+b_{2}\hat{j}+b_{3}\hat{k}$ are two non zero vectors inclined at an angle $\theta$, then identify the correct option out of the given options

(A) $\cos\theta=\frac{\overrightarrow{a}\cdot\overrightarrow{b}}{|\overrightarrow{a}|\cdot|\overrightarrow{b}|}$

(B) $\overrightarrow{a}$ and $\overrightarrow{b}$ are perpendicular, if $a_{1}b_{1}+a_{2}b_{2}+a_{3}b_{3}=0$

(C) $\overrightarrow{a}$ and $\overrightarrow{b}$ are perpendicular, $\frac{a_{1}}{b_{1}}=\frac{a_{2}}{b_{2}}\neq\frac{c_{1}}{c_{2}}$

(D) for $\theta=\pi,\overrightarrow{a}\times\overrightarrow{b}=0$

(E) $\cos\theta=\frac{|\overrightarrow{a}\times\overrightarrow{b}|}{|\overrightarrow{a}|\cdot|\overrightarrow{b}|}$', '[{"id":"A","text":"(A), (B) and (D) only"},{"id":"B","text":"(A), (B) and (E) only"},{"id":"C","text":"(B), (D) and (E) only"},{"id":"D","text":"(A) and (B) only"}]', 0, 'A', 'Given the vectors

$ \overrightarrow{a} = a_1\hat{i} + a_2\hat{j} + a_3\hat{k} $; $ \overrightarrow{b} = b_1\hat{i} + b_2\hat{j} + b_3\hat{k} $

If angle between $ \overrightarrow{a} $ and $ \overrightarrow{b} $ is $ \theta $

So, $ \cos\theta = \frac{\overrightarrow{a}\cdot\overrightarrow{b}}{|\overrightarrow{a}||\overrightarrow{b}|} $

and if $ \overrightarrow{a} $ is perpendicular to $ \overrightarrow{b} $ then

$ \overrightarrow{a}\cdot\overrightarrow{b} = 0 \Rightarrow a_1b_1 + a_2b_2 + a_3b_3 = 0 $

and if $ \theta = \pi $, then

$ \overrightarrow{a}\times\overrightarrow{b} = |\overrightarrow{a}||\overrightarrow{b}|\sin\theta\hat{n} = \overrightarrow{0} $

So, option (1) is correct.', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4906, 'mathematics-2022-08-30', 'q36', 27, 27, 'If $ \overline{p} = \hat{i} + \hat{j} - 2\hat{k} $ and $ \vec{q} = 2\hat{i} + \hat{j} - \hat{k} $, then the area of parallelogram having diagonals $ (\overline{p} + \overline{q}) $ and $ (\overline{p} - \overline{q}) $ is', '[{"id":"A","text":"$ 4\\sqrt{11} $ sq. unit"},{"id":"B","text":"$ \\sqrt{44} $ sq. unit"},{"id":"C","text":"$ \\sqrt{11} $ sq. unit"},{"id":"D","text":"$ 3\\sqrt{11} $ sq. unit"}]', 0, 'C', 'Given the vectors

$ p = \hat{i} + \hat{j} - 2\hat{k} $ and $ q = 2\hat{i} + 2\hat{j} - k $

Let $ \overrightarrow{d}_{1} = \overrightarrow{p} + \overrightarrow{q} = 3\hat{i} + 2\hat{j} - 3\hat{k} $

$ \overrightarrow{d}_{2} = \overrightarrow{p} - \overrightarrow{q} = \hat{i} - \hat{k} $

$ \therefore $ Area of parallelogram = $ \frac{1}{2} |\overrightarrow{d}_{1} \times \overrightarrow{d}_{2}| $

Now, $ \overrightarrow{d}_{1} \times \overrightarrow{d}_{2} = \begin{vmatrix} i & \hat{j} & \hat{k} \\ 3 & 2 & -3 \\ -1 & 0 & -1 \end{vmatrix} = -2\hat{i} + 6\hat{j} + 2\hat{k} $

$ \Rightarrow |d_{1} \times d_{2}| = \sqrt{(-2)^{2} + 6^{2} + 2^{2}} $

$ \therefore $ Area = $ \frac{1}{2}\sqrt{4 + 36 + 4} = \sqrt{11} $ sq. units', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4907, 'mathematics-2022-08-30', 'q37', 28, 28, 'If $ \overrightarrow{a}, \overrightarrow{b} $ and $ \overrightarrow{c} $ are three unit vectors such that $ \overrightarrow{a} + \overrightarrow{b} + \overrightarrow{c} = 0 $ then the value of $ \overrightarrow{a} \cdot \overrightarrow{b} + \overrightarrow{b} \cdot \overrightarrow{c} + \overrightarrow{c} \cdot \overrightarrow{a} $ is', '[{"id":"A","text":"3"},{"id":"B","text":"$ -\\frac{3}{2} $"},{"id":"C","text":"$ \\frac{3}{2} $"},{"id":"D","text":"$ -\\frac{1}{3} $"}]', 0, 'B', 'Given, $ \vec{a} + \vec{b} + \vec{c} = 0 $

Now, $ (\vec{a} + \vec{b} + \vec{c})(\vec{a} + \vec{b} + \vec{c}) = 0 $

$ \Rightarrow |\vec{a}| + |\vec{b}| + |\vec{c}| + 2(\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = 0 $

Since, $ \vec{a} = |\vec{b}| = |\vec{c}| = 1 $

$ \Rightarrow 2(\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = -3 $

$ \therefore (\vec{a} \cdot \vec{b} + \vec{b} \cdot \vec{c} + \vec{c} \cdot \vec{a}) = -\frac{3}{2} = (0, 0, 0) $', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4908, 'mathematics-2022-08-30', 'q38', 29, 29, 'The corner points of the feasible region for an $L.P.P.$ are $(0, 10), (5, 5), (15, 15)$ and $(0, 20)$. If the objective function is $z = px + qy; p, q > 0$, then the condition on $p$ and $q$ so that the maximum of zoccurs at $(15, 15)$ and $(0, 20)$ is', '[{"id":"A","text":"$p = q$"},{"id":"B","text":"$p = 2q$"},{"id":"C","text":"q = 3p"},{"id":"D","text":"q = 2p"}]', 0, 'C', 'Given, $z$ has max at (15, 15) and $(0, 20)$.

So, $z_{(15, 15)} = z_{(10, 20)} \Rightarrow 15p + 15q = 20q \Rightarrow q = 3p$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.943Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4909, 'mathematics-2022-08-30', 'q39', 30, 30, '$ \int x\sqrt{x+2} $ is equal to:

$$ \frac{ 贰 }{ 贰 } $$', '[{"id":"A","text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}-\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $"},{"id":"B","text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}+\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $"},{"id":"C","text":"$ \\frac{1}{5}(x+2)^{\\frac{5}{2}}+\\frac{2}{3}(x+2)^{\\frac{3}{2}}+C $"},{"id":"D","text":"$ \\frac{2}{5}(x+2)^{\\frac{5}{2}}+\\frac{4}{3}(x+2)^{\\frac{3}{2}}+C $"}]', 0, 'A', '$I = \int x \sqrt{x + 2} \, dx$

Let $x + 2 = t^2 \Rightarrow dx = 2t \, dt$

$\therefore I = \int (t^2 - 2) t \, (2t) \, dt$

$= \int (2t^4 - 4t^2) dt = \frac{2}{5}t^5 - \frac{4}{3}t^3 + C$

$= \frac{2}{5}(x + 2)^{\frac{5}{2}} - \frac{4}{3}(x + 2)^{\frac{3}{2}} + C$', NULL, 'null', '[]', '[]', '[3]', 'keyed', '[]', '2026-11-05T20:59:06.944Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4910, 'mathematics-2022-08-30', 'q40', 31, 31, 'Three urns contain 6 red, 4 black; 4 red, 6 black and 5 red, 5 black marbles respectively. One of the urns is selected at random and a marble is drawn from it. If the marble drawn is red, then the probability that it is drawn from the first urn is', '[{"id":"A","text":"$ \\frac{6}{10} $"},{"id":"B","text":"$ \\frac{4}{10} $"},{"id":"C","text":"$ \\frac{5}{10} $"},{"id":"D","text":"$ \\frac{2}{5} $"}]', 0, 'D', 'Let

6R 4R 5R

$ \frac{4B''}{U-1}\frac{6B''}{U-2}\frac{5B}{U-3} $

E: Drawn marble is red

$ E_1 $: Drawn marble from urn I

$ E_2 $: Drawn marble from urn II

$ E_3 $: Drawn marble from urn III

So, $ P(E_1) = P(E_2) = P(E_3) = \frac{1}{3} $

So, by conditional probability

$ P\left(\frac{E_1}{E}\right) = \frac{P(E \cap E_1)}{P(E)} $

$ P(E_1)P\left(\frac{E}{E_1}\right) $

$ P(E_1)P\left(\frac{E}{E_1}\right) + P(E_2)P\left(\frac{E}{E_2}\right) + P(E_3)\left(\frac{E}{E_3}\right) $

$ = \frac{\frac{6}{10}}{\frac{6}{10} + \frac{4}{10} + \frac{5}{10}} = \frac{6}{15} = \frac{2}{5} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.944Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4911, 'mathematics-2022-08-30', 'q41', 32, 32, 'Three persons A, B and C were given a task, whose probabilities of completion their task on time are $ \frac{1}{3}, \frac{1}{4} $, and $ \frac{1}{5} $ respectively. They were asked to complete the task on time independently. The probability that exactly one of them complete the task on time is', '[{"id":"A","text":"$ \\frac{2}{15} $"},{"id":"B","text":"$ \\frac{2}{5} $"},{"id":"C","text":"$ \\frac{3}{20} $"},{"id":"D","text":"$ \\frac{13}{20} $"}]', 0, 'D', 'Given, $ P(A)=\frac{1}{3}; P(B)=\frac{1}{4}; P(C)=\frac{1}{5} $

So, required probability

$ P=\frac{1}{3}\times\frac{3}{4}\times\frac{4}{5}+\frac{2}{3}\times\frac{1}{4}\times\frac{4}{5}+\frac{2}{3}\times\frac{3}{4}\times\frac{1}{5} $

$ =\frac{12+8+6}{60}=\frac{26}{60}=\frac{13}{30} $', NULL, 'null', '[]', '[]', '[4]', 'keyed', '[]', '2026-11-05T20:59:06.944Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
