INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4923, 'physics-2022-08-06', 'q05', 4, 4, 'Changing current through IV, cell and through $ 2\Omega $ resistor respectively is', '[{"id":"A","text":"2A, 1A"},{"id":"B","text":"1A, 2A"},{"id":"C","text":"2A, 2A"},{"id":"D","text":"1A, 1A"}]', 0, 'D', 'In loop (I), by KVL

