INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (4925, 'physics-2022-08-06', 'q09', 6, 6, 'The first particle accelerator of India (37" cyclotron) was established in the year 1953. Whose vision was behind this project?

(a) Dr. C.V. Raman

(b) Dr. Meghnad Saha

(c) Dr. Jagdish Chandra Bose

(d) Dr. Homi Jahangir Bhabha
10. Match List-I with List-II

