INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5081, 'cucet-2021-general-test', 'q40', 40, 37, 'The length of a metal wire is $ l_{1} $ when the tension is $ T_{1} $ and $ l_{2} $ when the tension is $ T_{2} $. The unstretched length of the wire is', '[{"id":"A","text":"$ \\frac{T_{2}l_{1}-T_{1}l_{2}}{T_{2}-T_{1}} $"},{"id":"B","text":"$ \\frac{T_{2}l_{1}+T_{1}l_{2}}{T_{2}-T_{1}} $"},{"id":"C","text":"$ \\frac{T_{2}l_{1}-T_{1}l_{2}}{T_{2}+T_{1}} $"},{"id":"D","text":"$ \\frac{T_{2}l_{1}+T_{1}l_{2}}{T_{2}+T_{1}} $"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[70]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.974Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5082, 'cucet-2021-general-test', 'q41', 41, 38, 'Two cylinders A and B of the same material have same length, their radii being in the ratio 1:2 respectively. The two are joined end to end as shown in the figure. One end of cylinder A is rigidly clamped while free end of cylinder B is twisted through an angle $ \theta $. The angle of twist of cylinder A is', '[{"id":"A","text":"$ \\frac{17}{16}\\theta $"},{"id":"B","text":"$ 16\\theta $"},{"id":"C","text":"$ 17\\theta $"},{"id":"D","text":"$ \\frac{16}{17}\\theta $"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[23]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.974Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5083, 'cucet-2021-general-test', 'q42', 42, 39, 'Soapy water drips from a capillary. When the drop breaks away, the diameter of its neck is D. The mass of the drop is m. The surface tension of soapy water is', '[{"id":"A","text":"$ \\frac{mgD}{\\pi} $"},{"id":"B","text":"$ \\frac{mg}{\\pi D} $"},{"id":"C","text":"$ \\frac{mg}{D} $"},{"id":"D","text":"$ \\frac{m}{\\pi gD} $"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[24]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.975Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5084, 'cucet-2021-general-test', 'q43', 43, 40, 'If the total energy of a particle executing SHM is E, then the potential energy V and the kinetic energy K of the particle in terms of E when its displacement is half of its amplitude will be', '[{"id":"A","text":"$ V = E/4 $ and $ K = 3E/4 $"},{"id":"B","text":"$ V = 3E/4 $ and $ K = E/4 $"},{"id":"C","text":"$ V = 3E/4 $ and $ K = 3E/4 $"},{"id":"D","text":"$ V = E/4 $ and $ K = E/4 $"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[70]', 'keyed', '["verified-key"]', '2026-11-05T20:59:06.975Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
