“Treacherous roads during snowfall.”', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:12.960Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5640, 'english-2026-05-26-shift-1', 'q12', 10, 10, 'Choose the meaning of "tumultuous."', '[{"id":"A","text":"Calm and peaceful"},{"id":"B","text":"Noisy and disorderly"},{"id":"C","text":"Short and clear"},{"id":"D","text":"Bright and colourful"}]', 0, 'B', 'Concept: Tumultuous refers to a situation full of noise, confusion, excitement, or disorder.

