Calm and peaceful', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:12.960Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5641, 'english-2026-05-26-shift-1', 'q13', 11, 11, 'What is the meaning of “benediction”?', '[{"id":"A","text":"Punishment"},{"id":"B","text":"Formal blessing"},{"id":"C","text":"Argument"},{"id":"D","text":"Complaint"}]', 0, 'B', 'Concept: “Benediction” refers to a blessing or expression of good wishes, especially in a religious or formal setting.

Step 1: Understand the word origin.

The word comes from Latin:

“bene” = well

and

“dictio” = speaking

