INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5642, 'english-2026-05-26-shift-1', 'q14', 12, 12, 'A “misanthrope” is a person who:', '[{"id":"A","text":"Loves nature deeply"},{"id":"B","text":"Dislikes humankind"},{"id":"C","text":"Enjoys travelling"},{"id":"D","text":"Speaks too much"}]', 0, 'B', 'Concept: A misanthrope is a person who dislikes or distrusts other people.

