Wail  $ \rightarrow $ Cry loudly

Vile  $ \rightarrow $ Extremely unpleasant', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:12.965Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5652, 'english-2026-05-26-shift-2', 'q10', 9, 9, 'Complete the sentence:

"The candidate was completely ___ by the deceptive questions asked by the interview board."', '[{"id":"A","text":"taken in"},{"id":"B","text":"brushed off"},{"id":"C","text":"ironed out"},{"id":"D","text":"lashed out"}]', 0, 'A', 'Step 1: Understand the sentence context.

