Bernier = France', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:13.038Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5933, 'history-2026-05-21-shift-1', 'q08', 4, 4, '“Mulk Abadi” referred to:', '[{"id":"A","text":"Military administration"},{"id":"B","text":"Revenue from forest regions"},{"id":"C","text":"Cultivated and inhabited land"},{"id":"D","text":"Tax on traders"}]', 0, 'C', 'Concept: The term “Mulk Abadi” was used in medieval Indian administration and land revenue records.

Step 1: Understanding the meaning of the term.

The word:

“Mulk”  $ \rightarrow $ territory or region

and

“Abadi”  $ \rightarrow $ inhabited or populated area

Together, the term referred to land that was:

• inhabited by people,

• cultivated regularly.

• productive for revenue purposes.

Step 2: Eliminating incorrect options.

• Military administration is unrelated to the term.

• Forest revenue refers to jungle resources.

• Tax on traders refers to commercial taxation.

#### Step 3: Selecting the correct answer.

Thus, “Mulk Abadi” referred to:

Cultivated and inhabited land

Hence, the correct option is:

<div style="text-align: center;"><img src="/local-papers/assets/history-2026-05-21-shift-1/q08-exp-1.jpg" alt="Figure 1 for question 8" /></div>


Quick Tip:

Abadi = Populated/Inhabited

This clue helps identify the meaning of the term quickly.', NULL, 'null', '[]', '[{"id":"q08-exp-1","kind":"explanation","path":"/local-papers/assets/history-2026-05-21-shift-1/q08-exp-1.jpg","page":1,"alt":"Figure 1 for question 8"}]', '[1]', 'keyed', '[]', '2026-11-05T20:59:13.038Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (5934, 'history-2026-05-21-shift-1', 'q09', 5, 5, 'Who is known as the “Father of Indian Archaeology”?', '[{"id":"A","text":"John Marshall"},{"id":"B","text":"Alexander Cunningham"},{"id":"C","text":"Rakhaldas Banerji"},{"id":"D","text":"Mortimer Wheeler"}]', 0, 'B', 'Concept: Archaeology is the scientific study of ancient remains, inscriptions, monuments, and artefacts to reconstruct history.

Step 1: Understanding Alexander Cunningham''s contribution.

Alexander Cunningham played a pioneering role in the development of archaeology in India. His major contributions include:

• Establishment of the Archaeological Survey of India (ASI)

• Survey and excavation of ancient sites

• Identification of Buddhist remains and monuments

• Systematic archaeological research in India

Because of these contributions, he is called:

Father of Indian Archaeology

Step 2: Eliminating incorrect options.

• John Marshall – Excavated Harappa and Mohenjo-daro.

• Rakhaldas Banerji – Discovered Mohenjo-daro.

• Mortimer Wheeler – Improved excavation techniques in India.

Step 3: Selecting the correct answer.

Therefore:

Alexander Cunningham

Hence, the correct option is:

<div style="text-align: center;"><img src="/local-papers/assets/history-2026-05-21-shift-1/q09-exp-1.jpg" alt="Figure 1 for question 9" /></div>


##### Quick Tip: Remember:

ASI Founder  $ \rightarrow $ Alexander Cunningham

Hence, he is known as the Father of Indian Archaeology.', NULL, 'null', '[]', '[{"id":"q09-exp-1","kind":"explanation","path":"/local-papers/assets/history-2026-05-21-shift-1/q09-exp-1.jpg","page":1,"alt":"Figure 1 for question 9"}]', '[1]', 'keyed', '[]', '2026-11-05T20:59:13.038Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
