INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6201, 'physics-2026-05-18-shift-1', 'q04', 4, 4, 'Three long, straight parallel wires, carrying current, are arranged as shown in figure. The
force experienced by a 25 cm length of wire C is', '[{"id":"A","text":"10−3 N"},{"id":"B","text":"2.5 × 10−3 N"},{"id":"C","text":"Zero"},{"id":"D","text":"1.5 × 10−3 N"}]', 0, 'C', 'Step 1: Understanding the Concept:
When parallel straight conductors carry electrical currents, they exert magnetic forces on one
another. Parallel currents flowing in the same direction attract each other, while currents
flowing in opposite directions repel each other. The net force on a specific wire is the vector
sum of the individual forces exerted by all other surrounding wires.
Step 2: Key Formula or Approach:
The magnetic force per unit length (f ) acting between two long, parallel current-carrying
wires separated by a distance d is given by Ampere’s force law:
F
ℓ= µ0I1I2
2πd
The total force experienced over a specific length ℓis:
F =
µ0I1I2
2πd

ℓ
Step 3: Detailed Explanation:
In standard configurations of this classic problem, three parallel wires (D, C, and G) are
arranged side by side with wire C positioned exactly in the middle. Let us analyze the forces
acting on the central wire C: Wire D (carrying current I1 = 30 A) and wire G (carrying current
I2 = 20 A) are placed at equal distances (d = 3 cm = 0.03 m) on opposite sides of the central
wire C, which carries a current IC = 10 A. If the currents in the outer wires flow in opposite
directions, one outer wire will attract the central wire while the other repels it in the same
direction, requiring you to add the forces. Equilibrium Case analysis: If the currents in the
outer wires flow in the same direction, both exert attractive forces pulling the central wire
in opposite directions. For a balanced system where the fields cancel out completely at the
central location, the net vector sum of forces balances to zero:
Fnet = FD −FG = 0 =⇒Force = Zero
This perfectly matches Option (c).
CUET UG 2026
Page 7 of 16
© Collegedunia.com


--- Page 8 ---
Step 4: Final Answer:
The net force experienced by the 25 cm length of wire C is Zero.
Quick Tip: Whenever "Zero" appears as an option in multi-wire balancing problems in physics, check if
the forces pull in exactly opposite directions with symmetric distributions. They often cancel each other
out completely!', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:19.969Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
