INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6203, 'physics-2026-05-18-shift-1', 'q06', 6, 6, 'The nucleus of helium atom contains two protons that are separated by a distance  $ 3.0 \times 10^{1} $ m. The magnitude of the electrostatic force that each proton exerts on the other is', '[{"id":"A","text":"20.6 N"},{"id":"B","text":"25.6 N"},{"id":"C","text":"15.6 N"},{"id":"D","text":"12.6 N"}]', 0, 'B', 'Step 1: Understanding the Concept:
The electrostatic interaction between two stationary point charges is governed by Coulomb’s
Law. Protons carry a known positive elementary charge, meaning they exert an equal and
