INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6206, 'physics-2026-05-18-shift-1', 'q09', 9, 9, 'Which of the following statements is not true about electric field lines?', '[{"id":"A","text":"Electric field lines start from positive charge and end at negative charge."},{"id":"B","text":"Two electric field lines can never cross each other."},{"id":"C","text":"Electrostatic field lines do not form any closed loops."},{"id":"D","text":"Electric field lines cannot be taken as continuous curve"}]', 0, 'D', 'Step 1: Understanding the Concept:
Electric field lines are imaginary geometric pathways used to visualize the direction and
strength of an electric field in space. The tangent drawn to a field line at any point indicates
the direction of the electric force vector acting on a positive test charge at that location. These
lines possess fundamental physical properties based on conservative electrostatic laws.
Step 2: Key Formula or Approach:
We evaluate each option against the standard properties of electrostatic field lines: Lines
emerge from positive sources and terminate on negative sinks. Field vectors have a single
unique direction at any given point in space. Electrostatic fields are conservative, meaning
the loop integral
H⃗
E ·⃗dℓ= 0. Field lines must form continuous curves in a charge-free space
because electric forces do not suddenly drop or break without a terminating charge.
Step 3: Detailed Explanation:
Option (a) is TRUE: Electric field lines naturally flow from high potential (positive charge) to
low potential (negative charge). Option (b) is TRUE: If two field lines crossed, the intersection
point would have two different tangents, implying two different directions for the electric field
at a single point, which is physically impossible. Option (c) is TRUE: Because the electrostatic
field is conservative, field lines cannot loop back onto themselves. They require a positive start
and a distinct negative finish. Option (d) is FALSE: Electric field lines are entirely continuous
curves that can only break or terminate at the surface of a charge. Therefore, stating they
"cannot be taken as continuous curves" is incorrect, making this the chosen answer.
Step 4: Final Answer:
The statement that is not true is: "Electric field lines cannot be taken as continuous curve".
CUET UG 2026
Page 14 of 16
© Collegedunia.com


--- Page 15 ---
Quick Tip: Remember: "Electric field lines are continuous, but they do NOT form closed loops." This is
a key distinction that separates them from magnetic field lines, which always form closed loops!', NULL, 'null', '[]', '[]', '[1]', 'keyed', '[]', '2026-11-05T20:59:19.971Z', NULL, NULL, 'ai_draft', 'unreviewed', NULL, NULL);
