<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Application</td><td style=''text-align: center; word-wrap: break-word;''>Allotment</td><td style=''text-align: center; word-wrap: break-word;''>First Call</td><td style=''text-align: center; word-wrap: break-word;''>Final Call</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>₹3</td><td style=''text-align: center; word-wrap: break-word;''>₹2</td><td style=''text-align: center; word-wrap: break-word;''>₹4</td><td style=''text-align: center; word-wrap: break-word;''>₹1</td></tr></table>

