<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Year</td><td style=''text-align: center; word-wrap: break-word;''>Profits (₹)</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2012-13</td><td style=''text-align: center; word-wrap: break-word;''>20,000</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2013-14</td><td style=''text-align: center; word-wrap: break-word;''>24,000</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2014-15</td><td style=''text-align: center; word-wrap: break-word;''>30,000</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2015-16</td><td style=''text-align: center; word-wrap: break-word;''>25,000</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2016-17</td><td style=''text-align: center; word-wrap: break-word;''>18,000</td></tr></table>

Calculate Goodwill on the basis of 3 years purchase of weighted average profits of last five years based on weights 1, 2, 3, 4 and 5 respectively.', '[{"id":"A","text":"₹68,200"},{"id":"B","text":"₹69,600"},{"id":"C","text":"₹64,800"},{"id":"D","text":"₹66,000"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["contains_table_data","missing_explanation"]', '2026-11-05T20:59:20.003Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6399, 'accountancy-2023-06-02-shift-1', 'q34', 35, 34, 'Consider the following facts about the categories of Share Capital

A. Nominal Capital is that part of Authorised Capital which is actually issued to the public

B. Issue Capital is a part of Registered Capital.

C. Subscribed Capital can be further categorised into fully paid-up and not fully paid up

D. Reserve Capital is a profit of capital nature

E. Called up Capital is that part of subscribed capital which company has asked the shareholders to pay

Choose the correct answer from the options given below:', '[{"id":"A","text":"A, B and D only"},{"id":"B","text":"B, C and E only"},{"id":"C","text":"C, D and E only"},{"id":"D","text":"A, B and C only"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.003Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6400, 'accountancy-2023-06-02-shift-1', 'q35', 36, 35, 'This formula would result in TRUE if C4 is less than 10 and D4 is less than 100.', '[{"id":"A","text":"= AND (C4 > 10, D4 > 10)"},{"id":"B","text":"= AND (C4 > 10, D4 > 100)"},{"id":"C","text":"= AND (C4 > 10, D4 = 100)"},{"id":"D","text":"= AND (C4 > 10, D4 < 100)"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.003Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
