INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6446, 'accountancy-2023-06-05-shift-1', 'q32', 40, 32, 'Himanshi and Nisha are partners in a firm sharing profit in the ratio of 3:2. There capital were ₹80,000 and ₹50,000 Respectively. They admitted Shikha on Jan 1, 2023 as a new partner for \frac15 share in future profit. If Shikha brought ₹60,000 as capital, the value of goodwill of the firm will be:', '[{"id":"A","text":"₹60,000"},{"id":"B","text":"₹1,10,000"},{"id":"C","text":"₹1,90,000"},{"id":"D","text":"₹3,00,000 Based on following Balance Sheet of Tarnav and Manav as at 31 ^st March 2022, answer question: (Q41-Q42) Balance Sheet as at 31 ^st March 2022 Liabilities ₹ Assets ₹ Sundry Creditors 30,000 Cash at Bank 13,000 Sanjay&#x27;s Loan 5,000 Stock in Trade 5,000 General Reserve 11,000 Debtors 20,000 Workman 12,000 Plant 30,000 Compensation Reserve Provision For Doubtful Debts 2,000 Goodwill 12,000 Capital: Tarnav 10,000 Manav 10,000 20,000 80,000 80,000 On that date the firm was dissolved on the following term: (i) Tarnav promised to pay Sanjay''s loan and took over stock in trade at ₹4,000. (ii) Creditors payable after one month, were paid immediately at 6% discount. (iii) Debtors of ₹1,000 proved bad, plant realised 130%. (iv) Expenses on Realisation were ₹1,500 borne and paid by Manav. (v) Manav took over an old computer completely written off from the book at ₹500"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.008Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
