INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6709, 'accountancy-2025-06-03-shift-2', 'q06', 10, 6, 'Dissolution of a partnership firm may be ordered by the court on the following grounds:

(A) when a partner becomes insane.

(B) when a partner becomes permanently incapable of performing his duties as partner.

(C) when a partner acts in good faith

(D) when it is regarded just and equitable by the court.

Choose the correct answer from the options given below:

1. (A) and (D) only

2. (A), (B) and (D) only

3. (D) only

4. (A), (B), (C) and (D)', '[{"id":"A","text":"(A) and (D) only"},{"id":"B","text":"(A), (B) and (D) only"},{"id":"C","text":"(D) only"},{"id":"D","text":"(A), (B), (C) and (D)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[11]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6710, 'accountancy-2025-06-03-shift-2', 'q07', 12, 7, 'At the time of admission of a new partner, under the fixed capital method, if the sacrificing partners withdraw their share of goodwill (fully or partly), the following journal entry will be passed:', '[{"id":"A","text":"Sacrificing Partners'' Capital A/c Dr. To Bank A/c"},{"id":"B","text":"Sacrificing Partners'' Current A/c Dr. To Bank A/c"},{"id":"C","text":"Gaining Partners'' Current A/c Dr"},{"id":"D","text":"Gaining Partners'' Capital A/c Dr. To Bank A/c"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[13]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6711, 'accountancy-2025-06-03-shift-2', 'q08', 13, 8, 'Rohan, Bharti and Leela are partners. On the retirement of Rohan, the goodwill already appears in the balance sheet at Rs. 24,000. The goodwill will be written-off:', '[{"id":"A","text":"By debiting all partners'' capital accounts in their old profit-sharing ratio"},{"id":"B","text":"By debiting remaining partners'' capital accounts in their new profit sharing ratio"},{"id":"C","text":"By debiting retiring partners'' capital accounts from his share of goodwill"},{"id":"D","text":"By debiting the retiring partners'' current account from his share of goodwill"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[14]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6712, 'accountancy-2025-06-03-shift-2', 'q09', 14, 9, 'Which statement is not false, in respect of the dissolution of a partnership firm :-

1. A partner took an un-recorded asset, it will be shown the credit side of realization account.

2. A partner takes an un-recorded asset, it will be shown the credit side of partners'' capital account

3. A partner took a recorded liability, it will be shown the credit side of realization account

4. A partner took an un-recorded liability, it will be shown the credit side of realization account.', '[{"id":"A","text":"A partner took an un-recorded asset, it will be shown the credit side of realization account"},{"id":"B","text":"A partner takes an un-recorded asset, it will be shown the credit side of partners'' capital account"},{"id":"C","text":"A partner took a recorded liability, it will be shown the credit side of realization account"},{"id":"D","text":"A partner took an un-recorded liability, it will be shown the credit side of realization account"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[15]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6713, 'accountancy-2025-06-03-shift-2', 'q10', 15, 10, 'Ranjan and Anjan were Partners in a firm sharing profits and losses in 3:2. they admitted Sanjan for 1/4 share of profit on 1 Jan 2024.

Goodwill of the firm will be valued at 3 years purchase of average profit of last 4 years which were

2024: Rs. 80,000

2023: Rs. 1,40,000,

2022: Rs. 2,000,000

2021: Rs. 1,60,000

The goodwill of the reconstituted firm will be', '[{"id":"A","text":"Rs. 1,45,000"},{"id":"B","text":"Rs. 4,33,000"},{"id":"C","text":"Rs. 4,35,000"},{"id":"D","text":"Rs. 1,35,000"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[16]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6714, 'accountancy-2025-06-03-shift-2', 'q11', 16, 11, 'Which statement among the following is NOT true about Goodwill?

1. Goodwill is the value of the reputation of a firm in respect of the profits expected in future, over and above the normal profits.

2. Goodwill is the capitalized value attached to the differential profit capacity of a business.

3. Goodwill can exist when the firm does not earn super profits, means any firm that earns normal profits or is incurring losses has goodwill

4. Goodwill is an intangible asset.', '[{"id":"A","text":"Goodwill is the value of the reputation of a firm in respect of the profits expected in future, over and above the normal profits"},{"id":"B","text":"Goodwill is the capitalized value attached to the differential profit capacity of a business"},{"id":"C","text":"Goodwill can exist when the firm does not earn super profits, means any firm that earns normal profits or is incurring losses has goodwill"},{"id":"D","text":"Goodwill is an intangible asset"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[17]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.051Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
