INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6723, 'accountancy-2025-06-03-shift-2', 'q20', 28, 20, 'Which of the following is not the feature of partnership -

1. There should be at least two persons coming together for a common goal.

2. Partnership is the result of an agreement between two or more persons to do business and share its profits only.

3. The business of a partnership concern may be carried on by all the partners or any of them acting for all.

4. The business profits and losses are shared by all the partners as per profit sharing ratio', '[{"id":"A","text":"There should be at least two persons coming together for a common goal"},{"id":"B","text":"Partnership is the result of an agreement between two or more persons to do business and share its profits only"},{"id":"C","text":"The business of a partnership concern may be carried on by all the partners or any of them acting for all"},{"id":"D","text":"The business profits and losses are shared by all the partners as per profit sharing ratio"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[28]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.053Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
