INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6768, 'business-studies-2022', 'q30', 41, 30, 'Identify which one is not a step in the process of setting up a Business?', '[{"id":"A","text":"Assessment of feasibility of the idea"},{"id":"B","text":"Reference and Background checks"},{"id":"C","text":"Project commissioning and launch"},{"id":"D","text":"Appraisal by funding agencies DIRECTIONS (Qs. 42-50): Read the case given below and attempt the following questions. Anukriti, a III year B.Com student is very fond of home cooked food as her mother keeps experimenting with new tastes and varieties every now and then. Although the family is well off and reputed in society, her mother feels lack of recognition and self-respect for herself. The mother daughter duo decided to go ahead with their own start up and cater to various occasions like birthday parties, office events, festivities, food for elderly and patients and so on. They assessed the number and type of human resources required and accordingly hired the calculated man-power for help from those introduced by their domestic help and some relatives. The ensured the quality standards for hygiene in kitchen, standardized the quality of vegetables, dry fruits and other raw materials to be purchased made sure that the orders are delivered in time. While Anukriti''s mother took care of all cooking in Kitchen, she personally observed the helpers at work. Being a commerce student, Anukriti decided to take care of finances herself. She prepared budgets in terms of quality, time, cost of material, calculated a point with no profit, no loss to ensure earning of target profits. As per the feedback received from customers, they improvised the dishes with lesser oil, spices, sugar. As both of them were very understanding and positive towards feedback, their business grew well. Gradually, they trained their staff in cooking packaging, inventory management. The employees are happy and satisfied as their basic remuneration and incentives are increased"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.062Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
