INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6849, 'business-studies-2023-06-11-shift-3', 'q34', 40, 34, 'Employees learn their jobs on the equipment they will be using, but the training is conducted away from the actual work place.

Name the training method, explained here.', '[{"id":"A","text":"Case study"},{"id":"B","text":"Programmed instructions"},{"id":"C","text":"Vestibule training"},{"id":"D","text":"Internship training ## Direction for the question 41 to 45: Read the following passage and answer question Directing refers to the process of instructing, guiding, counselling, motivating and leading people in the organisation to achieve its objectives. Directing is a managerial process which takes place throughout the life of the organisation irrespective of people occupying managerial positions. In the organisation every individual effort contributes to the organisational performance. Thus, it ensures that the individual work for organisational goals. One of the principles of Directing emphasises that directing techniques must help every individual in the organisation to contribute to his maximum potential for achievement of organisational objectives. In the organisation different techniques are used to motivate people such as pay, bonus, promotion, recognitions, praise, responsibility etc. and also different financial incentives are used. Under one of such incentive schemes employees are offered company shares at a predetermined price which is lower than market price"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.076Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6850, 'business-studies-2023-06-11-shift-3', 'q35', 41, 35, '"Directing takes place throughout the life of the organisation irrespective of people occupying managerial positions." Identify the feature of directing being reflected here.', '[{"id":"A","text":"Directing takes place at every level of management"},{"id":"B","text":"Directing initiates action"},{"id":"C","text":"Directing flows from top to bottom"},{"id":"D","text":"Directing is a continuous process"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.077Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
