INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (6853, 'business-studies-2023-06-11-shift-3', 'q38', 45, 38, 'Under which financial incentive schemes, employees are offered company''s shares at a predetermined price which is lower than market price?', '[{"id":"A","text":"Retirement benefit"},{"id":"B","text":"Co-partnership"},{"id":"C","text":"Profit sharing"},{"id":"D","text":"Bonus ## Direction for the question 46 to 50: Read the following passage and answer question Mr. Avinash has joined as a vice President of a manufacturing unit manufacturing garments. As a vice president, he was given the responsibility of increasing the production and efficiency of workers. He observed that managers relied on their personal judgement while attending to the problems they confronted. So, he recommended work study which will result in saving time, effort and increasing efficiency. He also noticed that management was not honouring their commitment. He surveyed the market too. His study of the survey showed that demand can be increased through diversification. He decided to diversify into footwear and handbags. He created divisions for garments, footwear and handbags and made the divisional managers responsible for performance. Each division is self-contained with respect to various functions like production, purchases, finance, marketing etc. Now he decided to fill the various positions created with the right person. For this, he analysed the number and type of workers needed. He got his organisation registered at naukri.com"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.077Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
