Recruitment is a:', '[{"id":"A","text":"Negative process"},{"id":"B","text":"Positive process"},{"id":"C","text":"Diversed process"},{"id":"D","text":"Additive process"}]', 0, 'B', NULL, 'business-studies-2025-05-30-shift-1-2025-05-30-1-passage004', 'null', '[]', '[]', '[61,62]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:20.106Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
