<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">List – I</td><td colspan="2">List – II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>A.</td><td style=''text-align: center; word-wrap: break-word;''>Bank Rate</td><td style=''text-align: center; word-wrap: break-word;''>I.</td><td style=''text-align: center; word-wrap: break-word;''>Securities are pledged in order to repurchase</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>B.</td><td style=''text-align: center; word-wrap: break-word;''>Marginal Standing Facility</td><td style=''text-align: center; word-wrap: break-word;''>II.</td><td style=''text-align: center; word-wrap: break-word;''>Minimum rate at which funds are provided for long term</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C.</td><td style=''text-align: center; word-wrap: break-word;''>Repo Rate</td><td style=''text-align: center; word-wrap: break-word;''>III.</td><td style=''text-align: center; word-wrap: break-word;''>Also known as Penal Interest Rate</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>D.</td><td style=''text-align: center; word-wrap: break-word;''>Reverse Repo Rate</td><td style=''text-align: center; word-wrap: break-word;''>IV.</td><td style=''text-align: center; word-wrap: break-word;''>Central Bank borrows funds from commercial banks</td></tr></table>

## Choose the correct answer from the options given below :', '[{"id":"A","text":"(A) - (I), (B) - (II), (C) - (III), (D) - (IV)"},{"id":"B","text":"(A) - (II), (B) - (III), (C) - (I), (D) - (IV)"},{"id":"C","text":"(A) - (I), (B) - (II), (C) - (IV), (D) - (III)"},{"id":"D","text":"(A) - (III), (B) - (IV), (C) - (I), (D) - (II)"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[5]', 'verified_against_ocr', '["contains_table_data","missing_explanation"]', '2026-11-05T20:59:25.001Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
