INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7233, 'legal-studies-2022', 'q03', 4, 3, 'A certain Mr. Zee was intercepted & arrested because of engagement in questionable activities. The secret service further provided intelligence that Mr Zee is a dangerous link for prepared terrorist attacks on the Rashtrapati Mahal and the markets close by. When Mr. Zee was not presented before the magistrate even after 36 hours of arrest as the investigation was still continuing, he decided to file a writ of hebeus corpus against the police authorities. Choose the most appropriate statement.', '[{"id":"A","text":"His petition will be maintainable as Rule of Law prevails over everyone"},{"id":"B","text":"His petition will be maintainable only if he is a citizen of India"},{"id":"C","text":"His petition will not be maintainable as he falls within the exceptions to article 22"},{"id":"D","text":"His petition will be maintainable after providing him an advocate Match the List I with List II List I List II A. Separation of Judiciary from executive B. Advisory Jurisdiction of Supreme Court C. The procedure for Joudges at High Court D. Appeal by Special Leave Choose the correct answer from the option given below: (a) A-I, B-II, C-III, D-IV (b) A-II, B-I, C-III, D-IV (c) A-I, B-III, C-II, D-IV (d) A-I, B-III, C-IV, D-II"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.056Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
