INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7255, 'legal-studies-2022', 'q25', 37, 25, 'Smit, an affluent jewellery designer was frequently abused by her husband she approached the District Legal Services Authority (DLSA) for filing a domestic violence case against her husband and requested for legal aid.', '[{"id":"A","text":"DLSA will refuse as Smit in affluent"},{"id":"B","text":"DLSA will have to provide legal aid as she is entitled to it under the Legal Services Authority Act"},{"id":"C","text":"DLSA will have to provide legal aid as she is entitled to it under the Advocate Act"},{"id":"D","text":"DLSA will refuse as domestic violence cases cannot be granted legal aid"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.064Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
