INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7257, 'legal-studies-2022', 'q27', 39, 27, 'Advocates are allowed to furnish a five piece information on their websites after the approval from Bar Council of India. Which amongst the following information is allowed to be put on Internet by an advocate?', '[{"id":"A","text":"Professional and Academic Qualification"},{"id":"B","text":"Areas of practice"},{"id":"C","text":"List of successful cases"},{"id":"D","text":"Photograph with name and details of enrollment with Bar (e) Contact details Choose the correct answer from the option given below: (a) (A), (B), (C) only (b) (B), (E), (D) only (c) (A), (B), (E) only (d) (C), (D), (E) only"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.065Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7258, 'legal-studies-2022', 'q28', 40, 28, 'Convention Relating to Status of Refugees, 1951 provides:', '[{"id":"A","text":"Legal safeguard to a refugee/person who is granted asylum/shelter in another country"},{"id":"B","text":"Economic support to refugees"},{"id":"C","text":"Protection of property right of refugees"},{"id":"D","text":"Interim benefits to refugees DIRECTIONS (Qs. 41-45): Read the passage and answer the question below: ## Case Study Sadhna a corporate lawyer is married to Ashish an IAS officer with the government of India. Both had a happy marriage for almost three years when Ashish started behaving poorly with Sadhna. His temper tantrums were becoming often. This was also a period when Sadhna was travelling outside the country for arbitration proceedings between her client M. Pharma (an Indian Company) and the opposite party Xylum Pharmaceuticals INC (incorporated in the United Kingdom having a subsidiary in India). The award for such an arbitration was to be enforced in India. Sadhna had wrapped up the arbitration and had come back to India, when she realised Ashish''s employment was terminated because of some bribery charges against him and also a sexual harassment complaint by one of his junior colleagues Ms. Pari Sahwney. While Ashish wanted to pursue his matter in the court of law, Sadhna wanted to file a divorce while their matter of divorce was still pending in the court of law, to fasten the matters Sadhna & Ashish filed their case at an alternative forum. Sadhna knew that the court will refund their court fee in case their dispute in resolved by this alternative forum. On the other hand, a case of bribery was also filed against Ashish by Mr. Khanna who had conducted this sting operation at Ashish''s office"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[5]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.065Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7259, 'legal-studies-2022', 'q29', 41, 29, 'Identify the type of arbitration that Sadhna who involved in, between M. Pharma & Xylum Pharmaceuticals:', '[{"id":"A","text":"Domestic Arbitration"},{"id":"B","text":"Foreign Arbitration"},{"id":"C","text":"Institutional Arbitration"},{"id":"D","text":"Ad-hoc Arbitration"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.065Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7260, 'legal-studies-2022', 'q30', 42, 30, 'There is an'' alternative forum'' where Sadhna & Ashish have field their divorce petition. Identify it:', '[{"id":"A","text":"Administrative tribunal"},{"id":"B","text":"Lokayukta"},{"id":"C","text":"Mediation"},{"id":"D","text":"Lok Adalat"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.066Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7261, 'legal-studies-2022', 'q31', 43, 31, 'After having identified the ''alternative forum for Sadhna and Ashish divorce petition, identify its functions.', '[{"id":"A","text":"No strict application of procedural laws"},{"id":"B","text":"Secrecy"},{"id":"C","text":"Flexible and informal technique"},{"id":"D","text":"Transparency (E) Efficiency Choose the correct answer from the option given below: (a) (B) and (E) only (b) (A), (D) and (E) only (c) (C) only (d) (C) and (D) only"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.066Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7262, 'legal-studies-2022', 'q32', 44, 32, 'The termination of services of Ashish by the Government of India can be handed by which forum:', '[{"id":"A","text":"Administrative Tribunal of India"},{"id":"B","text":"Central Administrative Tribunal of India"},{"id":"C","text":"Division Bench of the High court"},{"id":"D","text":"Original Jurisdiction under the Supreme Court"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.066Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7263, 'legal-studies-2022', 'q33', 45, 33, 'In which forum can Mr. Khanna bring the case of bribery against Ashish?', '[{"id":"A","text":"Lok Adalat"},{"id":"B","text":"Central Administrative Tribunal"},{"id":"C","text":"Central Vigilance Officer"},{"id":"D","text":"The Lokpal ### DIRECTIONS (Qs. 46-50): Read the passage and answer the question below: Legal Practice in India as in most other countries is a male dominated profession. In 1916, Calcutta high court and in 1922 Patna high court had held that women otherwise qualified were not entitled to enrol as a Vakil or pleader. In the Patna High Court case the petitioner secured BL Degree from Calcutta University and was refused to be enrolled as pleader. She challenged this in High Court of Patna. The Court ruled that legal practitioner Act referred to males only and no women had even been admitted to the roll of pleaders. The legal Practitioners (women) act XXIII of 1923 was enacted to expressly provide that no women would be reason only of her sex disqualified from being admitted or enrolled as legal practitioner or from practicing as such The Allahabad High Court took lead enrolling the first India Lady Vakil by a decision of English committee of court. Since then number of women entering into profession has increased but gender bias still pervades"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.066Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7264, 'legal-studies-2022', 'q34', 46, 34, 'The English Committee of the court who among the following decided on enrollment of first lady Vakil of Allahabad High Court considered of:', '[{"id":"A","text":"Sir Grim Wood"},{"id":"B","text":"Chief Justice Sir Grim Wood Meers"},{"id":"C","text":"Sir Arthur Whitefield"},{"id":"D","text":"CJI Fali Nariman"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[1]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.067Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
