Answer: B

According to the ‘two-nation theory’ advanced by the Muslim League, India consisted of not one but two people’, Hindus and Muslims. That is why it demanded Pakistan, a separate country for the Muslims.', '[{"id":"A","text":"Hindu Mahasabha"},{"id":"B","text":"Muslim League"},{"id":"C","text":"Pakistan Peoples ^* Party"},{"id":"D","text":"Indian National Congress"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[18]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.125Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7413, 'political-science-2025-06-27-shift-2', 'q14', 22, 14, 'Janata Party government declared its intention to follow ''genuine non-alignment.'' It meant that -

1. The pro-Soviet tilt in India''s foreign policy will be corrected.

2. The pro-Soviet tilt in the foreign policy will be continued.

3. Janata Party government will enter into bilateral treaties with both USA and USSR.

