INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7437, 'psychology-2024-07-19-shift-1', 'q09', 9, 9, 'Identify the behavioural component of the attitude displayed by Sanyogita towards the environment:', '[{"id":"A","text":"Sanyogita took the lead to organise a team of teachers and started going door to door in the nearby colonies"},{"id":"B","text":"She avidly read about methods used by developed countries"},{"id":"C","text":"She felt distressed when people were callous about their environment"},{"id":"D","text":"Sanyogita''s students and children joined her mission"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[10]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.142Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
