# "Sanyogita avidly read about methods used by other developed countries". Which component of attitude is being highlighted here?', '[{"id":"A","text":"Affective"},{"id":"B","text":"Behavioural"},{"id":"C","text":"Cognitive"},{"id":"D","text":"Valance"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[11,12]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.142Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7439, 'psychology-2024-07-19-shift-1', 'q11', 11, 11, 'Which one of the following is not a core/basic skill in the field of psychological services.', '[{"id":"A","text":"Leadership skills"},{"id":"B","text":"Communication skills"},{"id":"C","text":"Psychological testing skills"},{"id":"D","text":"Counselling skills"}]', 0, 'A', NULL, NULL, 'null', '[]', '[]', '[13]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.142Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7440, 'psychology-2024-07-19-shift-1', 'q12', 12, 12, 'While singing during school assembly you can see that some children are singing whereas some are only moving their legs or not singing at all. This phenomenon can be explained by _____.', '[{"id":"A","text":"Social Facilitation"},{"id":"B","text":"Social Loafing"},{"id":"C","text":"Social Inhibition"},{"id":"D","text":"Social Motivation"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[14]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.142Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7441, 'psychology-2024-07-19-shift-1', 'q13', 13, 13, 'George was in New York, when he saw the Twin Towers being destroyed by the terrorist airplanes. Now he has recurrent dreams, flashback and emotional numbing. These are characteristic of:-', '[{"id":"A","text":"Generalised Anxiety Disorder"},{"id":"B","text":"Post-Traumatic Stress Disorder"},{"id":"C","text":"Separation Anxiety Disorder"},{"id":"D","text":"Pre-Traumatic Stress Disorder"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[15]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.143Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7442, 'psychology-2024-07-19-shift-1', 'q14', 14, 14, 'Dhruv has been consuming alcohol for many years. Recently he has joined an alcohol rehabilitation center. During his group therapy session, Dhruv shared the amount of alcohol he could drink to feel ''high''. He started with a peg and to get the same effect now he has to take greater amount. Identify the reason for this change:', '[{"id":"A","text":"Withdrawal"},{"id":"B","text":"Tolerance"},{"id":"C","text":"Poor quality of alcohol"},{"id":"D","text":"Fixation"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[16]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.143Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7443, 'psychology-2024-07-19-shift-1', 'q15', 15, 15, 'The Clinical formulation of a client''s problem has the following advantages:

(A) Identification of areas to be targeted for treatment in psychotherapy

(B) Understanding the status of the client

(C) Understanding the problems

(D) To make money

(E) Choice of techniques for treatment

Choose the correct answer from the options given below:', '[{"id":"A","text":"(B), (C) & (E) only"},{"id":"B","text":"(C), (D) & (E) only"},{"id":"C","text":"(A), (B) & (C) only"},{"id":"D","text":"(A), (C) & (E) only"}]', 0, 'D', NULL, NULL, 'null', '[]', '[]', '[17]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.144Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7444, 'psychology-2024-07-19-shift-1', 'q16', 16, 16, 'Discussed below are elements of triarchic theory. Choose the correct options from the statements given below.

(A) The triarchic theory of intelligence was given by Howard Gardner

(B) According to this theory intelligence is the ability to adapt, to shape and select environment to accomplish ones goals.

(C)There are three basic types of intelligence: componential, contextual and experiential

(D)Componential intelligence may also be called street smartness or business sense

(E) Experiential or creative intelligence is involved in using past experiences creatively to solve novel problems

Choose the correct answer from the options given below:', '[{"id":"A","text":"(A), (C) and (D) only"},{"id":"B","text":"(B). (C) and (D) only"},{"id":"C","text":"(B), (C) and (E) only"},{"id":"D","text":"(A), (B) and (C) only"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[18,19]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.144Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7445, 'psychology-2024-07-19-shift-1', 'q17', 17, 17, 'When a large audience is asked to clap as loudly as possible, it was observed that the bigger the group size the more the increase in noise, but the amount of noise each participant made was reduced. This phenomenon is called:', '[{"id":"A","text":"Social facilitation"},{"id":"B","text":"Social Loafing"},{"id":"C","text":"Social rejection"},{"id":"D","text":"Social participation"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[20]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.144Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7446, 'psychology-2024-07-19-shift-1', 'q18', 18, 18, 'The concept of ''Balance'' in Attitude Change is explained below. Identify the correct options:

(A) Fritz Heider described this change in the form of P-O-X triangle, which explains relationship between the aspects.

(B) P is the person whose attitude is being studied. O is another person, X is the topic towards which attitude is studied.

(C) Attitude changes if there is a state of imbalance between P-O, O-X, P-X attitude.

(D) Imbalance is found when all three sides are positive.

(E) Balance is found when all three sides of the P-O-X triangle are negative.

Choose the correct answer from the options given below:', '[{"id":"A","text":"(A), (B) & (D) only"},{"id":"B","text":"(A), (B) & (C) only"},{"id":"C","text":"(A), (B) & (E) only"},{"id":"D","text":"(A), (D) & (E) only"}]', 0, 'B', NULL, NULL, 'null', '[]', '[]', '[21]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.144Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7447, 'psychology-2024-07-19-shift-1', 'q19', 19, 19, 'Find out the correct statements about alternative therapies:

(A) Yoga is an ancient Indian technique detailed in the Ashtanga Yoga of Patanjali''s Yoga Sutras.

(B) Alternative therapies are treatment possibilities to the conventional drug treatment or psychotherapy.

(C) Sudarshan Karma Yoga does not benefit individuals with anxiety and depression but helps substance abuse.

(D) There are many alternative therapies like cognitive behaviour therapy and rational emotive therapy.

(E) Vipasana meditation is also known as mindfulness based meditation.

Choose the correct answer from the options given below:', '[{"id":"A","text":"(A), (B) & (C) only"},{"id":"B","text":"(B), (C) & (D) only"},{"id":"C","text":"(A), (B) & (E) only"},{"id":"D","text":"(C), (D) & (E) only"}]', 0, 'C', NULL, NULL, 'null', '[]', '[]', '[22,23]', 'verified_against_ocr', '["missing_explanation"]', '2026-11-05T20:59:25.144Z', NULL, NULL, 'none', 'unreviewed', NULL, NULL);
INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7448, 'psychology-2024-07-19-shift-1', 'q20', 20, 20, 'Identify the neuro-developmental disorders:

(A) Autism Spectrum Disorder

(B) Intellectual Disability

