<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">List – I</td><td colspan="2">List – II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>A.</td><td style=''text-align: center; word-wrap: break-word;''>Logotherapy</td><td style=''text-align: center; word-wrap: break-word;''>I.</td><td style=''text-align: center; word-wrap: break-word;''>Freiderick Perls and Laura Perls</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>B.</td><td style=''text-align: center; word-wrap: break-word;''>Client Centred Therapy</td><td style=''text-align: center; word-wrap: break-word;''>II.</td><td style=''text-align: center; word-wrap: break-word;''>Victor Frankl</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C.</td><td style=''text-align: center; word-wrap: break-word;''>Gestalt Therapy</td><td style=''text-align: center; word-wrap: break-word;''>III.</td><td style=''text-align: center; word-wrap: break-word;''>Albert Ellis</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>D.</td><td style=''text-align: center; word-wrap: break-word;''>Rational Emotive Therapy</td><td style=''text-align: center; word-wrap: break-word;''>IV.</td><td style=''text-align: center; word-wrap: break-word;''>Carl Rogers</td></tr></table>

