INSERT OR REPLACE INTO practice_questions ("id", "paper_slug", "question_key", "source_question_no", "position", "stem", "options_json", "options_are_images", "correct_option", "explanation", "passage_key", "match_list_json", "arrangement_json", "assets_json", "source_pages_json", "review_status", "review_flags_json", "created_at", "updated_at", "deleted_at", "explanation_source", "explanation_status", "reviewed_by", "reviewed_at") VALUES (7461, 'psychology-2024-07-19-shift-1', 'q33', 33, 33, 'Arrange steps in the correct sequence followed in systematic desensitization technique:

(A) The therapist relaxes the clients and asks him to think about the least anxiety provoking situation.

