<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">List – I</td><td colspan="2">List – II</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>A.</td><td style=''text-align: center; word-wrap: break-word;''>Task-Oriented Strategy</td><td style=''text-align: center; word-wrap: break-word;''>I.</td><td style=''text-align: center; word-wrap: break-word;''>Dynamic situation specific reaction to stress</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>B.</td><td style=''text-align: center; word-wrap: break-word;''>Emotion-Oriented Strategy</td><td style=''text-align: center; word-wrap: break-word;''>II.</td><td style=''text-align: center; word-wrap: break-word;''>Maintaining a time schedule</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C.</td><td style=''text-align: center; word-wrap: break-word;''>Avoidance-Oriented Strategy</td><td style=''text-align: center; word-wrap: break-word;''>III.</td><td style=''text-align: center; word-wrap: break-word;''>Worry about what I am going to do</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>D.</td><td style=''text-align: center; word-wrap: break-word;''>Coping</td><td style=''text-align: center; word-wrap: break-word;''>IV.</td><td style=''text-align: center; word-wrap: break-word;''>Talent</td></tr></table>

